// ============================================================
// SmokeTest — JVM assertion suite for the South Park town app.
// NOT part of the APK (lives in tools/, compiled separately).
//
// v0.1.7 focus: IMAGE-MEASURED character specs. The core six
// (Kenny/Cartman/Craig/Stan/Kyle from their construction sheets,
// Garrison from his character model) are checked against the
// values produced by tools/measure_specs.py (PIL silhouette +
// center-column analysis; raw output in tools/measurements.json)
// — the constants below ARE those measured values. Also: the
// renderer geometry contract (FigureGeometry.derive), the three
// v0.1.6 playtest defects (per-character height/width dropped,
// hair/hat anchoring data, head ballooning), per-character
// proportion distinctness, and regression coverage of the
// v0.1.3-v0.1.6 systems (lorebook, cast, interiors, factions,
// generated NPCs, unmeasured fallback geometry).
//
// Run: see tools/run_smoke.sh
// ============================================================

package com.hunt3r.southparktown

import java.io.File
import kotlin.math.abs
import kotlin.math.roundToInt
import kotlin.random.Random

private var failures = 0
private var checks = 0

private fun check(cond: Boolean, msg: String) {
    checks++
    if (!cond) {
        failures++
        println("FAIL: $msg")
    }
}

private fun close(actual: Float, expected: Float, tol: Float, msg: String) {
    check(abs(actual - expected) <= tol,
        "$msg (expected $expected ±$tol, got $actual)")
}

private fun hexEq(actual: String, expected: String, msg: String) {
    check(actual.equals(expected, ignoreCase = true),
        "$msg (expected $expected, got $actual)")
}

/** Measured ground truth for one core character. */
private data class Truth(
    val skin: String, val top: String, val bottom: String,
    val hat: String?, val hatAccent: String?, val shoe: String?,
    val headShare: Float, val torsoShare: Float, val legShare: Float,
    val headAspect: Float, val headBodyWidth: Float, val heightRel: Float
)

fun main(args: Array<String>) {
    val root = if (args.isNotEmpty()) args[0] else "."
    println("== South Park town JVM smoke suite (v0.1.9f) ==")

    // ---------------- lorebook ----------------
    val loreJson = File(root, "assets/lorebook.json").readText()
    LoreBook.init(loreJson)
    check(LoreBook.loaded, "lorebook loaded")
    check(LoreBook.size == 3322, "lorebook has 3,322 entries (got ${LoreBook.size})")
    for ((game, lore) in LORE_CHAR_ALIASES) {
        check(LoreBook.entry(lore) != null, "lorebook covers cast member $game ($lore)")
    }
    check(LORE_CHAR_ALIASES.size == 98, "98 cast aliases (got ${LORE_CHAR_ALIASES.size})")
    for ((game, lore) in LORE_LOC_ALIASES) {
        check(LoreBook.entry(lore) != null, "lorebook covers location $game ($lore)")
    }
    check(LORE_LOC_ALIASES.size == 27, "27 location aliases (got ${LORE_LOC_ALIASES.size})")

    // ---------------- cast / world data ----------------
    check(CharacterSystem.CAST.size == 98, "CAST has 98 (got ${CharacterSystem.CAST.size})")
    check(CharacterSystem.CAST_KIDS.size == 42, "42 cast kids")
    check(CharacterSystem.CAST_ADULTS.size == 56, "56 cast adults")
    check(INTERIORS.size == 27, "27 interiors (got ${INTERIORS.size})")
    check(LOCATIONS.size == 27, "27 locations (got ${LOCATIONS.size})")
    check(WEATHER.size >= 8, "weather set present (${WEATHER.size})")
    check(FACTIONS.size == 8, "8 factions (got ${FACTIONS.size})")
    check(KidArt.SHEETS.size == 98, "98 character sheets (got ${KidArt.SHEETS.size})")
    check(KidArt.SHEETS.keys == CharacterSystem.CAST.keys,
        "sheet names == cast names")

    // ---------------- v0.1.7: measured ground truth, core six ----------------
    // Constants = tools/measurements.json (measure_specs.py output).
    val truth = mapOf(
        "Kenny" to Truth("#fedbb3", "#fc5c06", "#f95c07", null, null, null,
            0.607f, 0.267f, 0.126f, 1.155f, 1.089f, 1.040f),
        "Cartman" to Truth("#fedeb7", "#ca152c", "#5b2d24", "#52b9ba", "#ebda3a", "#170407",
            0.643f, 0.276f, 0.024f, 1.269f, 1.102f, 1.000f),
        "Craig" to Truth("#fedbb7", "#636aa2", "#322c36", "#636da6", "#fadb16", "#2b242a",
            0.647f, 0.230f, 0.065f, 0.900f, 1.073f, 0.994f),
        "Stan" to Truth("#fedcb6", "#9c5b55", "#636182", "#5668a6", "#c92344", "#252436",
            0.653f, 0.210f, 0.080f, 0.946f, 1.085f, 0.985f),
        "Kyle" to Truth("#fedcb6", "#f66118", "#43554b", "#239637", null, "#43524d",
            0.618f, 0.263f, 0.066f, 1.085f, 1.346f, 1.040f),
        "Garrison" to Truth("#fbdbb6", "#55c624", "#2d6543", null, null, "#2b232a",
            0.330f, 0.322f, 0.348f, 1.043f, 0.960f, 1.435f)
    )
    for ((name, t) in truth) {
        val spec = KidArt.SHEETS[name]
        check(spec != null, "$name has a sheet")
        spec!!
        hexEq(spec.skin, t.skin, "$name measured skin")
        hexEq(spec.top, t.top, "$name measured top")
        hexEq(spec.bottom, t.bottom, "$name measured bottom")
        if (t.hat != null) hexEq(spec.hatColor, t.hat, "$name measured hat")
        if (t.hatAccent != null) hexEq(spec.hatAccent, t.hatAccent, "$name measured hat accent")
        if (t.shoe != null) hexEq(spec.shoeColor, t.shoe, "$name measured shoe")
        val m = spec.measured
        check(m != null, "$name carries MeasuredProps")
        m!!
        close(m.headShare, t.headShare, 0.005f, "$name spec headShare == measured")
        close(m.torsoShare, t.torsoShare, 0.005f, "$name spec torsoShare == measured")
        close(m.legShare, t.legShare, 0.005f, "$name spec legShare == measured")
        close(m.headAspect, t.headAspect, 0.005f, "$name spec headAspect == measured")
        close(m.headBodyWidth, t.headBodyWidth, 0.005f, "$name spec headBodyWidth == measured")
        close(m.heightRel, t.heightRel, 0.005f, "$name spec heightRel == measured")

        // renderer contract: derive() must reproduce the measured
        // proportions (head-share may bend <=0.045 where the box
        // width clamp engages — Cartman's ultra-wide head)
        val d = FigureGeometry.derive(spec)
        close(d.headShare, t.headShare, 0.045f, "$name rendered headShare ~ measured")
        close(d.torsoShare, t.torsoShare, 0.03f, "$name rendered torsoShare ~ measured")
        close(d.legShare, t.legShare, 0.035f, "$name rendered legShare ~ measured")
        close(d.headAspect, t.headAspect, 0.03f, "$name rendered head aspect == measured")
        // face anchors INSIDE the head ellipse (defect 3: features
        // used to stay behind on fixed coords while the head grew)
        check(d.eyeL >= d.hx - d.hrx - 0.5f && d.eyeR <= d.hx + d.hrx + 0.5f,
            "$name eyes within head width")
        check(d.eyeT >= d.hy - d.hry - 0.5f && d.eyeB <= d.hy + d.hry + 0.5f,
            "$name eyes within head height")
        check(d.mouthY <= d.hy + d.hry + 0.5f, "$name mouth within head")
        // chin sits on the torso top (head anchored, no float/sink)
        close(d.hy + d.hry, d.plan.torsoTop + 2f, 0.6f, "$name chin anchored to torso")
    }
    // signature widths the measurements confirmed
    close(KidArt.SHEETS["Cartman"]!!.width, 1.3f, 0.001f, "Cartman width 1.3 (measured)")
    close(KidArt.SHEETS["Garrison"]!!.width, 0.92f, 0.001f, "Garrison slim width 0.92")

    // ---------------- per-character proportions for EVERYONE ----------------
    val tuples = mutableMapOf<List<Float>, String>()
    for ((name, spec) in KidArt.SHEETS) {
        if (name == "Towelie") {
            check(spec.measured == null, "Towelie measured == null (towel-block renderer)")
            continue
        }
        val m = spec.measured
        check(m != null, "$name carries its OWN MeasuredProps")
        m!!
        val key = listOf(m.headShare, m.torsoShare, m.legShare,
            m.headAspect, m.headBodyWidth, m.heightRel)
        check(!tuples.containsKey(key),
            "$name proportions distinct (clashes with ${tuples[key]})")
        tuples[key] = name
        // shares + the hat-cap allowance above the head ellipse = 1:
        // design-derived sets carry no cap (sum == 1); the measured
        // sheet kids sum to ~0.943 (their headShare is the head
        // CIRCLE, the cap is drawn by the hat layer)
        val sum = m.headShare + m.torsoShare + m.legShare
        check(sum in 0.93f..1.002f, "$name shares + hat cap ~ 1 (got $sum)")
        // every figure's limbs attached BY CONSTRUCTION at its own width
        val d = FigureGeometry.derive(spec)
        check(FigureGeometry.shoulderBite(d.plan) >= 2f,
            "$name shoulder bite >= 2 (got ${FigureGeometry.shoulderBite(d.plan)})")
        check(FigureGeometry.hipInside(d.plan), "$name hips inside torso")
        check(d.plan.legLen >= 4f, "$name legLen >= 4 (got ${d.plan.legLen})")
        check(d.hrx <= 48.5f, "$name head fits the unit box (hrx ${d.hrx})")
        // rendered total height = the spec's own heightRel
        close(KidArt.heightFor(name), m.heightRel, 0.001f,
            "$name heightFor == its measured heightRel")
    }
    // adults: legs at least the torso (Lucky's adult-sheet rule),
    // in SPEC shares and in RENDERED plan lengths
    for (name in CharacterSystem.CAST_ADULTS) {
        val spec = KidArt.SHEETS[name] ?: continue
        val m = spec.measured ?: continue
        check(m.legShare >= m.torsoShare - 0.001f,
            "$name adult legs >= torso in spec (${m.legShare} vs ${m.torsoShare})")
        val d = FigureGeometry.derive(spec)
        check(d.plan.legLen >= (d.plan.torsoBottom - d.plan.torsoTop) * 0.9f,
            "$name adult rendered legs ~>= torso")
    }
    // ordering: EVERY adult taller than EVERY kid (per-character
    // values, Michael the teen between them), Cartman widest kid
    val kidHeights = (CharacterSystem.CAST_KIDS - "Michael")
        .map { KidArt.heightFor(it) }
    val adultHeights = CharacterSystem.CAST_ADULTS.map { KidArt.heightFor(it) }
    check(kidHeights.max() < adultHeights.min(),
        "tallest kid (${kidHeights.max()}) < shortest adult (${adultHeights.min()})")
    val michaelH = KidArt.heightFor("Michael")
    check(michaelH > kidHeights.max() && michaelH < adultHeights.min(),
        "Michael (young teen) between kids and adults ($michaelH)")
    fun renderedWidth(name: String): Float {
        val spec = KidArt.SHEETS[name]!!
        return FigureGeometry.derive(spec).silhouetteW * spec.width
    }
    val cartmanW = renderedWidth("Cartman")
    for (k in CharacterSystem.CAST_KIDS - "Cartman") {
        check(cartmanW > renderedWidth(k), "Cartman wider than $k")
    }
    // no balloon heads: NO cast head renders wider than 1.35x its
    // height, and kid heads keep the sheet read (share >= 0.55)
    for ((name, spec) in KidArt.SHEETS) {
        val d = FigureGeometry.derive(spec)
        check(d.headAspect <= 1.36f, "$name head aspect sane (${d.headAspect})")
        if (name in CharacterSystem.CAST_KIDS) {
            check(d.headShare >= 0.55f, "$name kid head share >= 0.55 (${d.headShare})")
        }
    }
    // Mackey's giant head is proportion data now, not headScale
    check(KidArt.SHEETS["Mackey"]!!.headScale == 1f, "Mackey headScale retired to 1.0")
    check(KidArt.SHEETS["Mackey"]!!.measured!!.headShare >
        KidArt.SHEETS["Garrison"]!!.measured!!.headShare,
        "Mackey head share > Garrison head share")

    // ---------------- unmeasured fallback == v0.1.6 geometry EXACTLY ----------------
    val baseKid = FigureGeometry.derive(SheetSpec())
    check(baseKid.plan == FigureGeometry.KID, "unmeasured kid plan == base KID plan")
    close(baseKid.hry, 42.5f, 0.001f, "unmeasured kid head radius 42.5")
    close(baseKid.hy, 45.5f, 0.001f, "unmeasured kid head center 45.5")
    close(baseKid.eyeL, 28f, 0.001f, "unmeasured kid eyeL")
    close(baseKid.mouthY, 80f, 0.001f, "unmeasured kid mouthY")
    val baseAdult = FigureGeometry.derive(SheetSpec(tall = true))
    check(baseAdult.plan == FigureGeometry.ADULT, "unmeasured adult plan == base ADULT plan")
    close(baseAdult.hry, 34f, 0.001f, "unmeasured adult head radius 34")
    close(baseAdult.hy, 44f, 0.001f, "unmeasured adult head center 44")
    // headScale still works on the fallback path (avatar/NPCs), chin-anchored
    val bigHead = FigureGeometry.derive(SheetSpec(headScale = 1.3f))
    close(bigHead.hry, 55.25f, 0.01f, "fallback headScale scales radius")
    close(bigHead.hy + bigHead.hry, 88f, 0.01f, "fallback headScale keeps chin anchored")
    // base plans still satisfy the v0.1.6 attachment invariant
    check(FigureGeometry.limbsAttached(FigureGeometry.KID), "base KID limbs attached")
    check(FigureGeometry.limbsAttached(FigureGeometry.ADULT), "base ADULT limbs attached")
    // band ladder untouched (generated-NPC fallback)
    close(CharacterSystem.heightScale(AgeBand.KID), 1.0f, 0.001f, "band KID height 1.0")
    close(CharacterSystem.heightScale(AgeBand.ADULT), 1.38f, 0.001f, "band ADULT height 1.38")
    check(CharacterSystem.bandAdjust(SheetSpec(), AgeBand.ADULT).tall,
        "bandAdjust still maps generated specs to adult geometry")

    // ---------------- generated NPCs: seeded variety, no cast leakage ----------------
    val castLoreNames = LORE_CHAR_ALIASES.values.toSet()
    val sampleEntries = LoreBook.byCat("char")
        .filter { it.name !in castLoreNames }.take(3)
    var generated = 0
    for (e in sampleEntries) {
        val p = NpcGenerator.generate(e)
        generated++
        check(p.spec.measured == null, "generated ${p.loreName} uses band fallback (measured null)")
        check(p.spec.width in 0.94f..1.06f,
            "generated ${p.loreName} seeded width jitter (${p.spec.width})")
        check(p.spec.headScale in 0.95f..1.05f,
            "generated ${p.loreName} seeded headScale jitter (${p.spec.headScale})")
        check(p.spec.sig == null && p.spec.special == null,
            "generated ${p.loreName} carries no cast signature")
        val d = FigureGeometry.derive(
            CharacterSystem.bandAdjust(p.spec, p.band))
        check(FigureGeometry.shoulderBite(d.plan) >= 2f,
            "generated ${p.loreName} limbs attached after band adjust")
    }
    check(generated >= 2, "generated NPC samples produced ($generated)")

    // ================= v0.1.8 Phase 1: the 50 connected changes =================
    println("-- v0.1.8 phase 1: connected changes --")
    val eng8 = Engine()
    // calendar math (#25/#31 foundations)
    run {
        val s = eng8.newState()
        s.gameYear = 2026; s.gameMonth = 10
        s.gameDay = 1
        check(dayOfWeek(s) == 4, "2026-10-01 is a Thursday (dow 4)")
        s.gameDay = 3
        check(dayOfWeek(s) == 6, "2026-10-03 is a Saturday (dow 6)")
        s.gameDay = 4
        check(dayOfWeek(s) == 0, "2026-10-04 is a Sunday (dow 0)")
    }
    check(daysBetween("20261001", "20261008") == 7, "daysBetween a week")
    check(daysBetween("20260930", "20261002") == 2, "daysBetween across months")
    check(daysBetween("20261005", "20261005") == 0, "daysBetween same day")
    check(ordinalOfKey("20261002") > ordinalOfKey("20261001"), "ordinals increase")
    // forecast (#37): deterministic per state, varies across days
    run {
        val s = eng8.newState()
        s.todayKey = "20261001"; s.timeMin = 600; s.weatherId = "sunny"
        check(forecastWeather(s) == forecastWeather(s), "forecast is deterministic")
        check(forecastWeather(s) != "sunny", "forecast excludes current weather")
        val seen = WEATHER.keys.map { w ->
            s.weatherId = w; forecastWeather(s)
        }.toSet()
        check(seen.size >= 2, "forecast responds to current weather ($seen)")
    }
    // factions: mood model + association (#3/#4/#20)
    check(Factions.associationStart(0) == 0, "association: neutral standing starts at 0")
    check(Factions.associationStart(40) == 5, "association: +40 standing -> +5")
    check(Factions.associationStart(100) == 10, "association caps at +10")
    check(Factions.associationStart(-100) == -5, "association floors at -5")
    run {
        val fs = FactionState(50, 0, "even", moodScore = 5)
        check(Factions.moodIndex("boys_crew", fs, "sunny") in -2..2, "mood index clamps high")
        val fs2 = FactionState(50, 0, "even", moodScore = -5)
        check(Factions.moodIndex("goth_kids", fs2, "blizzard") in -2..2, "mood index clamps low")
        check(Factions.moodLabel(2) == "riding high", "mood label +2")
        check(Factions.moodLabel(-2) == "furious", "mood label -2")
        check(Factions.WEATHER_MOOD.keys.all { it in FACTION_BY_ID.keys },
            "weather mood table keys are real factions")
        check(Factions.WEATHER_MOOD.values.all { m -> m.keys.all { it in WEATHER.keys } },
            "weather mood table values key on real weather")
    }
    // living schedule transforms (#25/#26): weekend + summer move school
    run {
        val s = eng8.newState()
        val cartman = s.agents["Cartman"]!!
        s.todayKey = "20261001"; s.gameYear = 2026; s.gameMonth = 10; s.gameDay = 1
        val thu = eng8.effectiveAgendaBlock(s, cartman, 600)
        check(thu?.location == "Elementary", "Thursday 10am: Cartman in class (got ${thu?.location})")
        s.todayKey = "20261003"; s.gameDay = 3
        val sat = eng8.effectiveAgendaBlock(s, cartman, 600)
        check(sat?.location != "Elementary", "Saturday 10am: no school (got ${sat?.location})")
        s.todayKey = "20260715"; s.gameMonth = 7; s.gameDay = 15
        val sum = eng8.effectiveAgendaBlock(s, cartman, 600)
        check(sum?.location != "Elementary", "July: summer break, no school (got ${sum?.location})")
    }
    // shop hours (#29)
    run {
        val s = eng8.newState()
        s.todayKey = "20261001"; s.gameYear = 2026; s.gameMonth = 10; s.gameDay = 1
        check(eng8.shopClosedReason(s, "Elementary") == null,
            "school open while Garrison teaches (Thu 8am default)")
        // move Garrison home + late hour -> closed with a story
        val g = s.agents["Garrison"]!!
        g.location = "StanHouse"
        val late = eng8.shopClosedReason(s, "Elementary")
        check(late == null || late.contains("Closed"),
            "closed reason names the keeper's whereabouts")
        check(eng8.shopClosedReason(s, "Mall") == null, "keeperless places never lock")
        check(eng8.KEEPERS.values.all { it in s.agents.keys }, "all keepers are cast members")
    }
    // participation (#33): only cluster-loc actions count
    run {
        val s = eng8.newState()
        s.todayKey = "20261001"; s.timeMin = 600
        s.shenaniganId = "pirate_week"
        val def = SHENANIGAN_BY_ID["pirate_week"]!!
        val cluster = Shenanigans.stageOf(def, 600).clusterLoc
        if (cluster != null) {
            eng8.bumpParticipation(s, cluster)
            check(s.participation == 1, "participation bumps at the cluster loc")
            eng8.bumpParticipation(s, "Church")
            check(s.participation == 1, "no participation away from the action")
        } else {
            check(true, "pirate_week stage at 600 has no cluster (skipped)")
        }
    }
    // turf loot (#5): every flavored id is a real item
    for ((fid, ids) in TURF_LOOT) {
        check(fid in FACTION_BY_ID.keys, "turf loot faction $fid exists")
        for (id in ids) check(itemById(id) != null, "turf loot item $id exists")
    }
    // coverage (#39): every interior space has a searchable container
    for (locId in INTERIORS.keys) {
        check(containersAt(locId, true).isNotEmpty() || containersAt(locId, false).isNotEmpty(),
            "containers cover $locId")
    }
    // memory: likes + seen appearance round-trip (#12/#48)
    run {
        NpcMemoryStore.clear()
        NpcMemoryStore.recordGift("Test Kid", "Cheesy Poofs", true, 10, "20261001", 600, "Lucky")
        val after = NpcMemoryStore.get("Test Kid")!!
        check(after.likes.contains("Cheesy Poofs"), "loved gift lands in likes")
        after.seenAppearance = "hat=cap;skin=fair"
        val ser = NpcMemoryStore.serialize()
        NpcMemoryStore.clear()
        NpcMemoryStore.deserialize(ser)
        check(NpcMemoryStore.get("Test Kid")?.seenAppearance == "hat=cap;skin=fair",
            "seenAppearance survives save/load")
        check(NpcMemoryStore.get("Test Kid")?.likes?.contains("Cheesy Poofs") == true,
            "likes survive save/load")
        NpcMemoryStore.clear()
    }
    // weighted topics (#17): result always from the character's pool
    run {
        val s = eng8.newState()
        val t = eng8.weightedTopicFor(s, "Stan")
        check(t in (DAILY_TOPICS["Stan"] ?: emptyList()), "weighted topic comes from Stan's pool")
    }
    // visitor system: favorites, conversion, event crowd (#18/#19/#21)
    run {
        val someVisitor = VisitorSystem.eligible().firstOrNull {
            it.name !in VisitorSystem.residents().map { r -> r.loreName }.toSet()
        }
        check(someVisitor != null, "visitor pool has non-residents")
        if (someVisitor != null) {
            VisitorSystem.convertedProvider = { listOf(someVisitor.name) }
            val res = VisitorSystem.residents()
            val conv = res.firstOrNull { it.loreName == someVisitor.name }
            check(conv != null && conv.resident && conv.home != null,
                "converted visitor becomes a resident with a home")
            VisitorSystem.convertedProvider = { emptyList() }
        }
        val def = SHENANIGAN_BY_ID["pirate_week"]!!
        val crowd = VisitorSystem.eventCrowd("20261001", def, 1)
        check(crowd.size <= 2, "event crowd is at most 2 residents")
        check(crowd.all { it.persona.resident }, "event crowd members are residents")
        val favs = VisitorSystem.visitorsFor("20261001", 600)
        check(favs.isNotEmpty(), "visitors present in a day block")
        check(favs.none { v -> VisitorSystem.residents().any { it.loreName == v.persona.loreName } },
            "residents never double as visitors")
    }
    // creator unlocks (#42): options reference real collectibles
    for ((cat, pair) in CREATOR_OPTIONS) {
        for (opt in pair.second) {
            if (opt.unlockId != null) {
                check(COLLECTIBLES.any { it.id == opt.unlockId },
                    "creator option ${opt.id} unlock ${opt.unlockId} is a real collectible")
            }
        }
    }
    // clean-memory litter resistance (#40) is state-based: life map round-trips via GameState
    run {
        val s = eng8.newState()
        s.life["clean:MainStreet"] = 4
        check((s.life["clean:MainStreet"] ?: 0) == 4, "life map holds clean counts")
    }

    // ================= v0.1.8 Phase 2: the 100 living features =================
    println("-- v0.1.8 phase 2: living features --")
    run {
        val s = eng8.newState()
        // moon phases (#44)
        check((0..28).all { TownLife.moonPhase(it) in 0..7 }, "moon phase stays in 0..7")
        check((0..28).any { TownLife.moonPhase(it) == 4 }, "a full moon exists in the cycle")
        // gnome rotation (#91)
        val gnomes = (0..11).map { d -> s.absDay = d; TownLife.gnomeLocFor(s) }.toSet()
        check(gnomes.size >= 3, "gnome rotates yards ($gnomes)")
        check(gnomes.all { it in HOUSE_LOCS }, "gnome only haunts house yards")
        s.absDay = 5
        check(TownLife.gnomeLocFor(s) == TownLife.gnomeLocFor(s), "gnome is deterministic")
        // cat route (#5)
        val catSpots = (0..7).map { TownLife.catLocAt(it * 120) }.toSet()
        check(catSpots.size >= 4, "cat runs a real route ($catSpots)")
        check(TownLife.catLocAt(600) == TownLife.catLocAt(700), "cat stays put within a block")
        // alarm kid (#89)
        s.absDay = 2
        check(TownLife.alarmKidFor(s) == TownLife.alarmKidFor(s), "alarm kid deterministic")
        check(TownLife.alarmKidFor(s) in s.agents.keys, "alarm kid is a cast kid")
        // reputation tiers (#52)
        s.life["rep"] = 0
        check(TownLife.repTier(s) == "the new kid", "rep 0 = new kid")
        s.life["rep"] = 12
        check(TownLife.repTier(s) == "the helpful new kid", "rep 12 = helpful")
        s.life["rep"] = -12
        check(TownLife.repTier(s) == "that menace", "rep -12 = menace")
        TownLife.repAdd(s, 40)
        check(TownLife.rep(s) == 28, "repAdd accumulates")
        // lost & found (#64): deterministic, real owner + item
        val l1 = TownLife.lostToday(s)
        check(l1 != null && l1 == TownLife.lostToday(s), "lost item deterministic")
        check(l1!!.first in KID_HOUSE.keys, "lost owner is a cast member with a house")
        check(itemById(l1.second) != null, "lost item exists (${l1.second})")
        // birthdays (#55)
        s.todayKey = "20261019"
        check(birthdayOf(s) == "Stan", "Oct 19 is Stan's birthday")
        s.todayKey = "20261020"
        check(birthdayOf(s) == null, "Oct 20 is nobody's birthday")
        // peak faction accents (#59)
        check(TownLife.FACTION_ACCENTS.keys == FACTION_BY_ID.keys,
            "every faction has an accent color")
        val s2 = eng8.newState()
        s2.factionStates["goth_kids"]!!.influence = 80
        check(TownLife.peakFaction(s2) == "goth_kids", "peak faction detected at 80")
        check(TownLife.peakFaction(eng8.newState()) == null, "no peak faction at baseline")
        // night owls (#42): at 23:00 Michael is at his spot, not home
        val s3 = eng8.newState()
        s3.todayKey = "20261001"; s3.gameYear = 2026; s3.gameMonth = 10; s3.gameDay = 1
        val michael = s3.agents["Michael"]!!
        val nightBlock = eng8.effectiveAgendaBlock(s3, michael, 23 * 60)
        check(nightBlock?.location == "StarksPond",
            "23:00 Michael haunts the pond (got ${nightBlock?.location})")
        check(OWL_SPOTS.keys.all { it in s3.agents.keys }, "all owls are cast")
        // puddle lifecycle (#31/#32)
        val s4 = eng8.newState()
        s4.gameMonth = 1 // winter
        s4.weatherId = "rain"
        eng8.updatePuddlesDaily(s4)
        check(s4.puddles.isNotEmpty(), "rain leaves puddles (${s4.puddles.keys})")
        check(s4.frozenPuddles == s4.puddles.keys.toSet(), "winter cold freezes them over")
        val before = s4.puddles.values.max()
        s4.weatherId = "sunny"
        eng8.updatePuddlesDaily(s4)
        check(s4.puddles.values.all { it < before } || s4.puddles.isEmpty(),
            "a dry day shrinks the puddles")
        check(TownLife.puddleSizeAt(s4, "MainStreet") ==
            (s4.puddles["MainStreet"] ?: 0), "puddleSizeAt reads the map")
        // displayHoliday creep (#71): Halloween runs 10/25-10/31
        val s5 = eng8.newState()
        s5.gameYear = 2026; s5.gameMonth = 10; s5.gameDay = 23
        s5.todayKey = "20261023"
        check(currentHoliday("1023") == null, "no holiday on 10/23 itself")
        check(displayHoliday(s5)?.id == "halloween", "decorations creep in 2 days early")
        s5.gameDay = 24; s5.todayKey = "20261024"
        check(displayHoliday(s5)?.id == "halloween", "still creeping at 1 day early")
        s5.gameMonth = 11; s5.gameDay = 1; s5.todayKey = "20261101"
        check(displayHoliday(s5)?.id == "halloween", "decorations linger a day late")
        // fence feud lifecycle (#95) via onNewDay
        val s6 = eng8.newState()
        s6.gameYear = 2026; s6.gameMonth = 10; s6.gameDay = 1
        s6.absDay = 3
        eng8.onNewDay(s6) // absDay -> 4, a feud week
        check(s6.lifeText["feud"] != null, "feud erupts on schedule (${s6.lifeText["feud"]})")
        repeat(5) { eng8.onNewDay(s6) }
        check(s6.lifeText["feud"] == null, "feud burns out after five days")
        // aurora gating (#49): winter + clear + the rare night only
        val s7 = eng8.newState()
        s7.gameMonth = 1; s7.weatherId = "sunny"; s7.absDay = 5
        check(TownLife.auroraTonight(s7), "aurora on the seeded winter night")
        s7.absDay = 6
        check(!TownLife.auroraTonight(s7), "no aurora the night after")
        s7.absDay = 5; s7.gameMonth = 7
        check(!TownLife.auroraTonight(s7), "no aurora in summer")
        // lemonade is a real, giftable item (#75)
        check(itemById("lemonade") != null, "lemonade item exists")
    }

    // ================= v0.1.8 Phase 3: the 100 sprite changes =================
    println("-- v0.1.8 phase 3: sprite construction --")
    run {
        // #64 BIG MITTENS: hand radius nearly the sleeve's width
        check(FigureGeometry.KID.handRad == 6.5f,
            "kid hands are mittens (handRad ${FigureGeometry.KID.handRad})")
        check(FigureGeometry.ADULT.handRad == 7f,
            "adult hands are mittens (handRad ${FigureGeometry.ADULT.handRad})")
        check(FigureGeometry.KID.handRad > FigureGeometry.KID.armRad,
            "mitten wider than the sleeve is the sheet read")
        // #65 rest tilt in the sheet's 10-14 degree band
        check(SheetSpec().armTilt == 12f, "arm rest tilt is 12 degrees")
        // #100/#84 signature specs the sprite pass must never regress
        check(KidArt.SHEETS["Tolkien"]!!.skin == "#7a5230", "Tolkien skin spec")
        check(KidArt.SHEETS["Kenny"]!!.special == "kenny_parka", "Kenny parka renderer")
        check(KidArt.SHEETS["Garrison"]!!.beltHex == "#C0C0C0", "Garrison silver buckle")
        check(KidArt.SHEETS["Craig"]!!.hatId == "chullo", "Craig chullo")
        check(KidArt.SHEETS["Kyle"]!!.hatId == "ushanka", "Kyle ushanka")
        // every cast sheet still derives a sane plan after the pass
        for ((name, spec) in KidArt.SHEETS) {
            if (spec.special == "towel") continue
            val d = FigureGeometry.derive(spec)
            check(d.plan.handRad >= 6.5f, "$name derives mitten hands")
        }
    }

    // ---------------- v0.1.9a: the leftovers, finished ----------------
    println("== v0.1.9a: leftovers + scene parity ==")
    run {
        val eng9 = Engine()

        // #35 crowd density — the STRICT formula (per location, per hour)
        check(TownLife.densityCap(2, 3) == 0, "density: a 3 AM pair stays quiet")
        check(TownLife.densityCap(2, 12) == 2, "density: a midday pair can chat twice")
        check(TownLife.densityCap(12, 12) == 6, "density: a midday bazaar caps at 6")
        check(TownLife.densityCap(6, 3) == 1, "density: owls murmur once at 3 AM")
        check(TownLife.densityCap(3, 21) == 1, "density: evening trio gets one chat")
        check((0..23).all { hh -> TownLife.densityCap(4, hh) <= TownLife.densityCap(8, hh) },
            "density: monotone in occupancy at every hour")
        check(TownLife.densityWeight(12) > TownLife.densityWeight(3),
            "density: midday outweighs 3 AM")

        // #12 mail ritual — deterministic windows, both outcomes occur
        var letters = 0
        var bills = 0
        for (d in 0..40) for (n in listOf("Stan", "Kyle", "Cartman", "Kenny",
            "Butters", "Randy", "Sharon", "Tolkien")) {
            val s = TownLife.mailStart(n, d)
            check(s in 410..539, "mail: window lands 6:50-8:59")
            check(TownLife.mailStart(n, d) == s, "mail: deterministic")
            check(TownLife.mailPhaseAt(n, d, s) == 0f, "mail: phase opens at the window")
            check(TownLife.mailPhaseAt(n, d, s + 12) == null, "mail: phase closes after 12")
            if (TownLife.mailHasLetter(n, d)) letters++ else bills++
        }
        check(letters > 60 && bills > 60, "mail: letters AND bills both happen ($letters/$bills)")

        // #92 lunchbox — a real kid claims it, on departure, once a day
        val lunchKids = setOf("Stan", "Kyle", "Kenny", "Butters", "Craig",
            "Tweek", "Clyde", "Jimmy", "Wendy", "Bebe")
        for (d in 0..30) {
            val probe = eng9.newState(); probe.absDay = d
            check(TownLife.lunchboxKidFor(probe) in lunchKids,
                "lunchbox: retriever is a school kid")
        }
        val sL = eng9.newState(); sL.absDay = 0; sL.timeMin = 500
        val lk = TownLife.lunchboxKidFor(sL)
        val lAgent = sL.agents[lk]!!
        lAgent.location = "BusStop"; lAgent.destination = "BusStop"
        lAgent.waypoints.clear(); lAgent.asleep = false
        lAgent.coords = LOCATIONS["BusStop"]!!.let { it.gx to it.gy }
        eng9.tickLivingWorld(sL)
        check(sL.life["lunchboxDay"] == null, "lunchbox: waits while the kid waits")
        lAgent.location = "MainStreet"; lAgent.destination = "Elementary"
        lAgent.waypoints.clear(); lAgent.waypoints.add(50 to 52)
        lAgent.coords = 46 to 84
        eng9.tickLivingWorld(sL)
        check(sL.life["lunchboxDay"] == 0, "lunchbox: claimed on the kid's way out")

        // #33 snow cycle — buildup, shake window, reset
        for (n in listOf("Stan", "Kyle", "Kenny", "Butters")) {
            var sawShake = false
            var sawFull = false
            for (t in 0..1439 step 5) {
                val cov = TownLife.snowCover(n, t)
                check(cov in 0f..1f, "snow: cover stays 0..1")
                if (TownLife.snowShaking(n, t)) sawShake = true
                if (cov >= 0.99f) sawFull = true
            }
            check(sawShake, "snow: $n shakes off during the day")
            check(sawFull, "snow: $n builds to a full coat")
        }
        val tShake = (0..1439).first { TownLife.snowShaking("Stan", it) }
        check(TownLife.snowCover("Stan", tShake + 5) <= 0.26f,
            "snow: cover is a dusting right after a shake")

        // #62 chalk — aging, additions, fade
        val sC = eng9.newState(); sC.absDay = 100
        sC.lifeText["chalk:BusStop"] = "2:100"
        check(TownLife.chalkActive(sC, "BusStop"), "chalk: fresh chalk is active")
        check(TownLife.chalkShown(sC, "BusStop") == listOf(2), "chalk: day 0 shows yours alone")
        sC.absDay = 102
        check(TownLife.chalkShown(sC, "BusStop") == listOf(2, 3), "chalk: added to by day 2")
        sC.absDay = 104
        check(TownLife.chalkShownCount(sC, "BusStop") == 3, "chalk: three doodles by day 4")
        sC.absDay = 106
        check(!TownLife.chalkActive(sC, "BusStop"), "chalk: faded by day 6")
        check(TownLife.chalkShown(sC, "BusStop").isEmpty(), "chalk: nothing shown after fade")
        check(TownLife.CHALK_SPOTS.size == 4, "chalk: four slabs around town")

        // #93 mitten tree — hang, consume, refuse at the cap
        val sM = eng9.newState()
        sM.inventory["lost_mitten"] = 2
        check(itemById("lost_mitten") != null, "mitten: the item exists")
        check(TownLife.tryHangMitten(sM), "mitten: hangs while stocked")
        check((sM.inventory["lost_mitten"] ?: 0) == 1 && TownLife.mittensHung(sM) == 1,
            "mitten: consumed one, tree wears one")
        sM.life["mittensHung"] = TownLife.MAX_MITTENS
        sM.inventory["lost_mitten"] = 3
        check(!TownLife.tryHangMitten(sM), "mitten: a full tree refuses more")
        val sM2 = eng9.newState()
        check(!TownLife.tryHangMitten(sM2), "mitten: empty hands hang nothing")

        // #97 fan club — needs three Close Friends, no fewer
        val sF = eng9.newState()
        check(!TownLife.fanClubActive(sF), "fanclub: nobody, no club")
        sF.friendship["Stan"] = 60; sF.friendship["Kyle"] = 75
        check(!TownLife.fanClubActive(sF), "fanclub: two close friends is not a club")
        sF.friendship["Kenny"] = 90
        check(TownLife.fanClubActive(sF), "fanclub: three close friends form the club")

        // #98 sightings — deterministic, roughly half of nights
        var sightNights = 0
        for (d in 0..99) {
            val probe = eng9.newState(); probe.absDay = d
            val again = eng9.newState(); again.absDay = d
            check(TownLife.sightingTonight(probe) == TownLife.sightingTonight(again),
                "sighting: deterministic per night")
            if (TownLife.sightingTonight(probe)) sightNights++
        }
        check(sightNights in 30..80, "sightings: on roughly half of nights ($sightNights)")

        // #19 rain dash — relocation, pace, dispatcher respect, cleanup
        val sR = eng9.newState()
        sR.weatherId = "cloudy"
        val stanR = sR.agents["Stan"]!!
        stanR.location = "StarksPond"; stanR.destination = "StarksPond"
        stanR.waypoints.clear(); stanR.asleep = false
        stanR.coords = LOCATIONS["StarksPond"]!!.let { it.gx to it.gy }
        eng9.setWeather(sR, "rain")
        check(stanR.destination == "TweekBros",
            "rain dash: Stan reroutes to the pond's shelter (got ${stanR.destination})")
        check(sR.lifeText["dash:Stan"] == "TweekBros", "rain dash: the dash is marked")
        check(stanR.waypoints.isNotEmpty(), "rain dash: a route is computed")
        check(eng9.paceFor(sR, stanR) > 13.0,
            "rain dash: dash pace applies (${eng9.paceFor(sR, stanR)})")
        eng9.advanceTime(sR)
        if (sR.weatherId == "rain") {
            check(stanR.destination == "TweekBros",
                "rain dash: the block dispatcher leaves a dash alone")
        }
        eng9.setWeather(sR, "sunny")
        check(!sR.lifeText.containsKey("dash:Stan"), "rain dash: marks clear when rain ends")

        // #41 yawn window
        check(TownLife.yawnAt(1320, 1320), "yawn: pops at bedtime")
        check(!TownLife.yawnAt(1320, 1335), "yawn: gone nine minutes later")

        // ---- Scope B: scene parity registry vs. drawn source ----
        val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        check(LOC_ART_DETAILS.size == 27, "parity: registry covers all 27 locations")
        for ((locId, tokens) in LOC_ART_DETAILS) {
            check(LOCATIONS.containsKey(locId), "parity: $locId is a real location")
            check(tokens.size >= 2, "parity: $locId carries 2+ defining details")
            for (tok in tokens) {
                check(sceneSrc.contains("detail: $tok"), "parity: drawn — $locId/$tok")
            }
        }
        check(sceneSrc.contains("drawParityDetails"), "parity: the pass runs in drawScene")
        // corrected palettes (show-faithful fields)
        fun rgb(hex: String): Triple<Int, Int, Int> {
            val v = hex.removePrefix("#").toInt(16)
            return Triple(v shr 16 and 255, v shr 8 and 255, v and 255)
        }
        val (jr, jg, jb) = rgb(LOCATIONS["JimbosGuns"]!!.colorHex)
        check(jr > 140 && jg in 50..130 && jb < 90, "palette: Jimbo's walls are orange")
        val (rr, rg, rb) = rgb(LOCATIONS["Raisins"]!!.colorHex)
        check(rr > 180 && rg in 60..140 && rb < 110, "palette: Raisins wears orange-red")
        val (sr, sg, sb) = rgb(LOCATIONS["StanHouse"]!!.colorHex)
        check(sb > sr && sb > sg, "palette: the Marsh house reads blue")
        val (br, bg2, bb) = rgb(LOCATIONS["Bank"]!!.colorHex)
        check(bb >= br && bb >= bg2, "palette: the bank reads blue-gray stone")
    }

    // ================= v0.1.9b: chrome / game-UI parity =================
    // The restyle moved every layout decision into Chrome.kt —
    // these checks pin the v0.1.6 hard constraint (text never
    // overlaps) as arithmetic: fitting, stacking, bubble geometry.
    run {
        // -- fitText / ellipsize: the strip + bubble shrink semantics --
        val charW = { s: String -> s.length * 10f }
        check(Chrome.fitText("SHORT", 100f, measure = charW) == "SHORT",
            "chrome: text that fits is untouched")
        val fitted = Chrome.fitText("ABCDEFGHIJKLMNOP", 55f, measure = charW)
        check(fitted.length == 5 && charW(fitted) <= 55f,
            "chrome: fitText shrinks to the width (got '$fitted')")
        check(Chrome.fitText("ABCDEFGH", 1f, measure = charW).length == 4,
            "chrome: fitText never goes below minLen")
        val ell = Chrome.ellipsize("ABCDEFGHIJKLMNOP", 55f, measure = charW)
        check(ell.endsWith("…") && charW(ell) <= 55f,
            "chrome: ellipsize fits, ellipsis counted (got '$ell')")
        check(Chrome.ellipsize("OK", 55f, measure = charW) == "OK",
            "chrome: ellipsize leaves fitting text alone")

        // -- top chrome stacking (dp): ticker < top bar < chip --
        check(Chrome.TICKER_TOP_DP + Chrome.TICKER_MIN_H_DP <= Chrome.TOPBAR_TOP_DP,
            "chrome: ticker band clears the location bar")
        check(Chrome.TOPBAR_TOP_DP + Chrome.TOPBAR_MIN_H_DP <= Chrome.CHIP_TOP_DP,
            "chrome: location bar clears the quest chip")
        check(Chrome.CHIP_TOP_DP + Chrome.CHIP_MIN_H_DP <= Chrome.CHROME_FALLBACK_DP,
            "chrome: chip bottom stays inside GameView's fallback chrome height")

        // -- in-view overlays: the bubble always clears the strip --
        for (ct in listOf(0f, 118f, 200f)) {
            check(Chrome.bubbleTop(ct, true) >= Chrome.eventStripBottom(ct) + 10f,
                "chrome: bubble clears the event strip (chromeTop $ct)")
            check(Chrome.bubbleTop(ct, false) == ct + Chrome.BUBBLE_GAP_PLAIN_PX,
                "chrome: plain bubble offset (chromeTop $ct)")
            check(Chrome.eventStripBottom(ct) == ct + Chrome.EVENT_STRIP_H_PX,
                "chrome: strip bottom arithmetic (chromeTop $ct)")
        }
        for (n in 1..2) {
            check(Chrome.bubbleHeight(n) >= Chrome.bubbleContentBottom(n) + 20f,
                "chrome: bubble height fits $n line(s) with bottom room")
        }

        // -- name tags: the exact GameView fit, now in Chrome --
        val tagMeasure = { s: String, sz: Float -> s.length * sz * 0.55f }
        val (szFit, lbFit) = Chrome.nameTagFit("Stan Marsh", 200f, 15f, tagMeasure)
        check(szFit == 15f && lbFit == "Stan Marsh",
            "chrome: a fitting tag is unchanged")
        val (szLong, lbLong) = Chrome.nameTagFit(
            "Some Extremely Long Generated Name", 60f, 12.5f, tagMeasure)
        check(szLong == Chrome.TAG_MIN_SIZE,
            "chrome: long tag shrinks to the floor size (got $szLong)")
        check(lbLong.endsWith("…") &&
            tagMeasure(lbLong, szLong) <= 60f + tagMeasure("…", szLong),
            "chrome: long tag ellipsizes into its slot (got '$lbLong')")

        // -- the contrast pairs the chrome actually puts text on --
        check(Chrome.contrast(Chrome.INK, Chrome.PARCHMENT) >= 4.5f,
            "chrome: ink on parchment is readable")
        check(Chrome.contrast(Chrome.YELLOW, Chrome.CHARCOAL) >= 4.5f,
            "chrome: yellow on charcoal is readable")
        check(Chrome.contrast(Chrome.PARCHMENT, Chrome.CHARCOAL) >= 4.5f,
            "chrome: parchment on charcoal is readable")
        check(Chrome.contrast("#ffffff", Chrome.RED) >= 4.0f,
            "chrome: white on the red plaque is readable")

        // -- registry cross-check: the paper kit is really wired --
        // (mirrors the v0.1.9a scene-parity source cross-check, so
        // a surface can't silently fall back to stock chrome)
        val gameActSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(!gameActSrc.contains("AlertDialog.Builder"),
            "chrome: GameActivity dialogs all run on the paper kit")
        val settingsSrc = File(root,
            "src/com/hunt3r/southparktown/SettingsActivity.kt").readText()
        check(!settingsSrc.contains("AlertDialog.Builder"),
            "chrome: Settings dialogs all run on the paper kit")
        for (f in listOf("GameActivity", "JournalActivity", "InventoryActivity",
            "QuestActivity", "CollectionActivity", "LoreActivity",
            "SettingsActivity", "CreatorActivity", "DialogueSheet",
            "MainActivity")) {
            val src = File(root, "src/com/hunt3r/southparktown/$f.kt").readText()
            check(src.contains("UiKit") || src.contains("Chrome."),
                "chrome: $f is wired to the chrome kit")
        }
        val gameViewSrc = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        check(gameViewSrc.contains("Chrome.fitText") &&
            gameViewSrc.contains("Chrome.bubbleTop") &&
            gameViewSrc.contains("Chrome.nameTagFit"),
            "chrome: GameView overlays draw from the Chrome math")
    }

    // ================= v0.1.9c: episode framing =================
    // Title cards, act-break stings, credits wrap-ups and the
    // Journal shelf — driven through the real engine lifecycle.
    println("== v0.1.9c: episode framing ==")
    run {
        val engE = Engine()

        // -- def data: every story can be framed --
        for (def in SHENANIGANS) {
            check(def.causers.isNotEmpty(), "episode: ${def.id} credits its causers")
            check(def.episodeTitles.size == 2, "episode: ${def.id} has 2 alt titles")
            check(def.coldOpen.isNotEmpty(), "episode: ${def.id} has a cold open")
            check(def.coldOpen.all { it.speaker in AGENT_PROFILES },
                "episode: ${def.id} cold open is spoken by cast members")
            check(def.stages.size == 4, "episode: ${def.id} has 4 acts")
        }

        // -- rotating titles + treatments + act names --
        val chinpo = SHENANIGAN_BY_ID["chinpo_craze"]!!
        check(Episodes.titleFor(chinpo, 0, 100).first == chinpo.title,
            "episode: run 0 bills the def title")
        check(Episodes.titleFor(chinpo, 1, 100).first == chinpo.episodeTitles[0],
            "episode: run 1 rotates to alt title 1")
        check(Episodes.titleFor(chinpo, 2, 100).first == chinpo.episodeTitles[1],
            "episode: run 2 rotates to alt title 2")
        check(Episodes.titleFor(chinpo, 3, 100).first == chinpo.title,
            "episode: run 3 cycles back to the def title")
        check(Episodes.titleFor(chinpo, 0, 100).second in Episodes.TREATMENTS,
            "episode: treatment comes from the rotation")
        check(Episodes.actName(0) == "ACT I" && Episodes.actName(1) == "ACT II" &&
            Episodes.actName(2) == "ACT III" && Episodes.actName(3) == "ACT IV",
            "episode: act names I..IV")

        // -- a forced event airs as an episode --
        val sE = engE.newState()
        sE.gameDay = 20
        sE.timeMin = 1430
        // v0.15.0g staging: the cast no longer spawns
        // piled on the Bus Stop (CastHomes — everyone
        // starts at home), so this staging gathers the
        // town at the stop ON PURPOSE: the cold-open
        // beat under test is "you were standing with the
        // causers when it started", and the gathering is
        // what stages exactly that
        for ((_, aE) in sE.agents) {
            if (!aE.isPlayer) {
                aE.location = "BusStop"
                aE.destination = "BusStop"
                aE.waypoints.clear()
            }
        }
        engE.advanceTime(sE) // wraps past midnight -> Oct 21, forced roll
        check(sE.shenaniganId != null, "episode: the forced day rolled an event")
        val defE = SHENANIGAN_BY_ID[sE.shenaniganId]!!
        val epE = sE.episodes.singleOrNull { it.kind == "event" }
        check(epE != null, "episode: kickoff opened an episode record")
        if (epE != null) {
            check(!epE.titleShown, "episode: title card is pending at kickoff")
            check(epE.title.isNotEmpty() && epE.treatment in Episodes.TREATMENTS,
                "episode: generated title + treatment on the record")
            check(epE.causers.isNotEmpty(), "episode: causers credited on the record")
            check(epE.startInfluence.size == FACTIONS.size,
                "episode: faction snapshot taken at kickoff")
            check(epE.stageTitles.size == 4, "episode: four acts on the record")
            // cold open: the whole cast (causers included)
            // is standing with the player at the Bus Stop —
            // gathered there by the staging above (in the
            // shipped game they start at home; the beat
            // fires whenever the player truly is standing
            // with a causer at kickoff)
            check(epE.coldOpen, "episode: cold open fired with the causers present")
            check(sE.lastConversation == Episodes.coldOpenLines(defE),
                "episode: cold-open lines are the def's opening beat")

            // the title card fires ONCE — the UI flips this flag and
            // the queue has nothing left to re-fire
            epE.titleShown = true

            // act-break sting: queued once at the stage transition,
            // and it WAITS (deferred) until presented at a safe moment
            repeat(30) { engE.advanceTime(sE) } // -> ~07:35, into Act II
            check(Shenanigans.stageFor(sE.timeMin) == 1,
                "episode: reached Act II in the flow")
            check(epE.actPending == 1 && epE.actsShown.isEmpty(),
                "episode: Act II sting queued once, still deferred")
            repeat(10) { engE.advanceTime(sE) }
            check(epE.actPending == 1,
                "episode: the deferred sting is not re-queued or lost")
            // present it, as the Activity does at a safe moment
            for (i in 0..1) epE.actsShown.add(i)
            epE.actPending = -1

            // ride to the end with a known hand in it
            var guard = 0
            while (!epE.finished && guard++ < 220) {
                if (sE.shenaniganId != null &&
                    Shenanigans.stageFor(sE.timeMin) == 3) sE.participation = 7
                engE.advanceTime(sE)
            }
            check(epE.finished, "episode: the episode wrapped at rollover")
            check(epE.participation == 7,
                "episode: the recap kept your hand in it (got ${epE.participation})")
            check(epE.recap.any { it.contains("7/10") },
                "episode: recap prints the participation score")
            check(epE.recap.any { it.contains("🗿") },
                "episode: recap carries the mark the event left")
            check(epE.recap.any { it.contains("The acts:") },
                "episode: recap lists the four acts")
            check(!epE.wrapShown, "episode: credits wrap-up is pending presentation")
            check(epE.actPending == -1, "episode: no sting leaks past the wrap")

            // serialization round-trip (the Prefs shape)
            val back = Episodes.fromMap(epE.toMap())
            check(back != null && back.key == epE.key && back.finished &&
                back.titleShown && back.participation == 7 &&
                back.recap == epE.recap && back.actsShown == epE.actsShown,
                "episode: record survives the save round-trip")

            // later events accumulate more episodes on the shelf
            sE.gameMonth = 11
            sE.gameDay = 20
            sE.timeMin = 1430
            engE.advanceTime(sE)
            val evs = sE.episodes.filter { it.kind == "event" }
            check(evs.size >= 2, "episode: episodes accumulate (got ${evs.size})")
            check(evs.first().finished,
                "episode: the first episode sits finished on the shelf")
            check(evs[evs.size - 1].eventId != evs[evs.size - 2].eventId,
                "episode: lineage respected — no immediate rerun")
        }

        // -- mid-event old save: joined in progress, no re-trigger --
        val sM = engE.newState()
        sM.shenaniganId = "pirate_week"
        sM.shenaniganDay = sM.todayKey
        sM.lastStageSeen = 1
        check(sM.episodes.isEmpty(), "episode: old save has no records yet")
        Episodes.syncAiring(sM)
        val epM = sM.episodes.singleOrNull { it.kind == "event" }
        check(epM != null, "episode: sync synthesized the in-progress record")
        if (epM != null) {
            check(epM.titleShown,
                "episode: mid-event save does NOT re-fire the title card")
            check(epM.actPending == -1,
                "episode: no sting is back-queued for acts already played")
            check(epM.actsShown.containsAll(setOf(0, 1)),
                "episode: acts already played count as shown")
            // ...but the NEXT act still stings on its transition
            sM.timeMin = 800 // Act III territory
            engE.advanceTime(sM)
            check(epM.actPending == 2,
                "episode: the next act transition still queues its sting")
        }

        // -- holidays air as episodes through the same machinery --
        val sH = engE.newState()
        sH.gameDay = 24
        engE.onNewDay(sH) // Oct 25 — Halloween begins
        check(sH.holidayId == "halloween", "episode: Halloween is on")
        val epH = sH.episodes.singleOrNull { it.kind == "holiday" }
        check(epH != null && !epH.titleShown,
            "episode: the holiday opened an episode with its card pending")
        if (epH != null) {
            sH.questCounters["holidayTalks"] = 2 // you celebrated today
            repeat(7) { engE.onNewDay(sH) } // Oct 26 .. Nov 1
            check(sH.holidayId == null, "episode: Halloween ended on Nov 1")
            check(epH.finished, "episode: the holiday episode wrapped")
            check(epH.daysRun == 7,
                "episode: Halloween ran its full 7 days (got ${epH.daysRun})")
            check(epH.holidayTalks >= 2,
                "episode: holiday talks banked into the recap (got ${epH.holidayTalks})")
            check(epH.recap.any { it.contains("Halloween") },
                "episode: holiday recap names the holiday")
            check(!epH.wrapShown, "episode: holiday credits are pending too")
        }

        // -- wiring cross-checks: presentation is really hooked --
        val gameActSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gameActSrc.contains("Episodes.syncAiring") &&
            gameActSrc.contains("maybeShowEpisodeCards") &&
            gameActSrc.contains("showTitleCard") &&
            gameActSrc.contains("showActCard") &&
            gameActSrc.contains("showWrapCard"),
            "episode: GameActivity presents the queued cards")
        check(gameActSrc.contains("sheet.onDismissed"),
            "episode: dialogue close is a wired safe moment")
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(journalSrc.contains("📺 EPISODES") &&
            journalSrc.contains("showEpisodeDialog"),
            "episode: Journal carries the episode list + pages")
        val uiKitSrc = File(root,
            "src/com/hunt3r/southparktown/UiKit.kt").readText()
        check(uiKitSrc.contains("showEpisodeDialog"),
            "episode: the show card lives in the chrome kit")
    }

    // ================= v0.1.9d: creator depth =================
    run {
        // -- category set + per-category option counts
        // (v0.1.2-v0.1.9c: 7 categories / 54 options) --
        // v0.5.0b: the wardrobe adds 14 locked pieces to the
        // shelf (hat +5, top +5, bottom +2, accessory +2)
        val expectedCounts = linkedMapOf(
            "skin" to 8, "build" to 5, "hair_style" to 18, "hair_color" to 12,
            "hat" to 18, "top" to 21, "bottom" to 14, "shoes" to 6,
            "eyewear" to 5, "facial_hair" to 5, "gloves" to 6,
            "back_item" to 4, "accessory" to 6)
        check(CREATOR_ORDER == expectedCounts.keys.toList(),
            "creator: CREATOR_ORDER is the 13 deepened categories")
        var totalOpts = 0
        for ((cat, n) in expectedCounts) {
            val opts = CREATOR_OPTIONS[cat]?.second ?: emptyList()
            check(opts.size == n,
                "creator: $cat has $n options (got ${opts.size})")
            totalOpts += opts.size
            check(opts.map { it.id }.distinct().size == opts.size,
                "creator: $cat option ids unique")
            for (o in opts) {
                if (o.color != null) {
                    check(o.color!!.matches(Regex("#[0-9a-fA-F]{6}")),
                        "creator: $cat/${o.id} color is a hex (${o.color})")
                }
            }
        }
        check(totalOpts == 128, "creator: 128 total options (114 + the v0.5.0b wardrobe's 14) (got $totalOpts)")
        check(DEFAULT_APPEARANCE.keys == CREATOR_ORDER.toSet(),
            "creator: defaults cover every category")
        check(validateAppearance(DEFAULT_APPEARANCE) == DEFAULT_APPEARANCE,
            "creator: the blank New Kid default validates to itself")

        // -- old appearance strings still parse (additive contract) --
        val legacy = mapOf(
            "skin" to "tan", "hair_style" to "mop", "hair_color" to "red",
            "hat" to "cap", "top" to "jacket_red", "bottom" to "jeans",
            "accessory" to "freckles")
        val lv = validateAppearance(legacy)
        check(lv["build"] == "average" && lv["shoes"] == "shoes_black" &&
            lv["eyewear"] == "none" && lv["facial_hair"] == "none" &&
            lv["gloves"] == "none" && lv["back_item"] == "none",
            "creator: a 7-key legacy save gains the new defaults")
        check(lv["accessory"] == "freckles" && lv["hat"] == "cap",
            "creator: legacy choices survive validation")
        // legacy accessory migration into the new categories
        val migG = validateAppearance(legacy + ("accessory" to "glasses"))
        check(migG["eyewear"] == "glasses" && migG["accessory"] == "none",
            "creator: legacy glasses migrate to eyewear")
        val migS = validateAppearance(legacy + ("accessory" to "sunglasses"))
        check(migS["eyewear"] == "sunglasses" && migS["accessory"] == "none",
            "creator: legacy sunglasses migrate to eyewear")
        val migC = validateAppearance(legacy + ("accessory" to "chinstrap"))
        check(migC["facial_hair"] == "chinstrap" && migC["accessory"] == "none",
            "creator: legacy chinstrap migrates to facial hair")
        val migB = validateAppearance(legacy + ("accessory" to "backpack"))
        check(migB["back_item"] == "backpack" && migB["accessory"] == "none",
            "creator: legacy backpack migrates to back item")
        val migWin = validateAppearance(
            mapOf("accessory" to "glasses", "eyewear" to "star_shades"))
        check(migWin["eyewear"] == "star_shades",
            "creator: an explicit eyewear beats the legacy accessory")
        check(validateAppearance(mapOf("hat" to "bogus"))["hat"] == "none",
            "creator: unknown ids fall back to the default")

        // -- builds ride the measured-proportions path --
        check(CREATOR_BUILDS.keys ==
            setOf("average", "slight", "stocky", "tall", "petite"),
            "creator: five builds on the shelf")
        check(CREATOR_BUILDS["average"] == null,
            "creator: average = the classic unmeasured geometry")
        val buildTuples = mutableSetOf<List<Float>>()
        for ((id, props) in CREATOR_BUILDS) {
            if (props == null) continue
            val sum = props.headShare + props.torsoShare + props.legShare
            check(sum in 0.93f..1.01f,
                "creator: build $id shares ~ 1 (got $sum)")
            check(buildTuples.add(listOf(props.headShare, props.torsoShare,
                props.legShare, props.headAspect, props.headBodyWidth,
                props.heightRel)), "creator: build $id proportions distinct")
            val d = FigureGeometry.derive(SheetSpec(measured = props))
            check(FigureGeometry.limbsAttached(d.plan),
                "creator: build $id limbs attached at its extremes")
            check(FigureGeometry.shoulderBite(d.plan) >= 2f,
                "creator: build $id shoulder bite >= 2")
            check(FigureGeometry.hipInside(d.plan),
                "creator: build $id hips inside torso")
            check(d.hrx <= 48.5f, "creator: build $id head fits the box")
            check(d.headAspect <= 1.36f,
                "creator: build $id no balloon head")
        }
        check(FigureGeometry.derive(SheetSpec(
            measured = CREATOR_BUILDS["stocky"])).silhouetteW >
            FigureGeometry.derive(SheetSpec(
            measured = CREATOR_BUILDS["slight"])).silhouetteW,
            "creator: stocky renders wider than slight")
        check(CREATOR_BUILDS["tall"]!!.heightRel >
            CREATOR_BUILDS["petite"]!!.heightRel,
            "creator: tall is taller than petite")

        // -- avatarSpec: the pure appearance -> sheet mapping --
        val defSpec = avatarSpec(DEFAULT_APPEARANCE)
        check(defSpec.measured == null && defSpec.special == "underwear_top" &&
            defSpec.barefoot && defSpec.bottom == "#f0f0f0" &&
            defSpec.hairStyle == "bald",
            "creator: default avatar is the blank New Kid, exact")
        val jacket = avatarSpec(mapOf("top" to "jacket_red"))
        check(jacket.placket && jacket.buttons && jacket.pockets == 2 &&
            jacket.collarHex != null,
            "creator: a jacket wears placket + buttons + pockets + collar")
        val hoodie = avatarSpec(mapOf("top" to "hoodie_red"))
        check(hoodie.collarHex != null && !hoodie.placket && hoodie.pockets == 0,
            "creator: a hoodie wears its collar band only")
        val parka = avatarSpec(mapOf("top" to "parka_green"))
        check(parka.placket && parka.collarHex != null && !parka.buttons,
            "creator: a parka wears a zipper placket")
        val stockySpec = avatarSpec(mapOf("build" to "stocky"))
        check(stockySpec.measured == CREATOR_BUILDS["stocky"],
            "creator: build choice lands in the spec's MeasuredProps")
        check(FigureGeometry.limbsAttached(
            FigureGeometry.derive(stockySpec).plan),
            "creator: the stocky avatar's limbs attach")
        check(avatarSpec(mapOf("gloves" to "mittens_red")).handColor == "#c92344",
            "creator: mittens color the hands")
        check(avatarSpec(mapOf("gloves" to "none")).handColor == null,
            "creator: bare hands keep skin hands")
        check(avatarSpec(mapOf("eyewear" to "goggles")).eyewear == "goggles",
            "creator: goggles ride the eyewear slot")
        val gl = avatarSpec(mapOf("eyewear" to "glasses"))
        check(gl.glasses && gl.eyewear.isEmpty(),
            "creator: classic glasses ride the glasses flag")
        val fh1 = avatarSpec(mapOf("facial_hair" to "mustache"))
        check(fh1.mustache && !fh1.beard, "creator: mustache is mustache-only")
        val fh2 = avatarSpec(mapOf("facial_hair" to "goatee"))
        check(fh2.beard && fh2.beardStyle == "goatee",
            "creator: goatee is a styled beard")
        val fh3 = avatarSpec(mapOf("facial_hair" to "chinstrap"))
        check(fh3.beard && fh3.beardStyle == "chinstrap",
            "creator: chinstrap is a styled beard")
        check(avatarSpec(mapOf("back_item" to "cape")).backStyle == "cape",
            "creator: cape rides the back slot")
        check(avatarSpec(mapOf("back_item" to "backpack")).backpack,
            "creator: backpack still sets the backpack flag")
        check(avatarSpec(mapOf("bottom" to "jeans",
            "shoes" to "bare_feet")).barefoot,
            "creator: bare feet read barefoot under jeans")
        check(avatarSpec(mapOf("shoes" to "sneakers_red")).shoeColor == "#c0392b",
            "creator: shoe color reaches the spec")
        check(avatarSpec(mapOf("accessory" to "scarf")).scarfHex == "#c0392b",
            "creator: scarf reaches the spec")
        // every hair/hat the creator sells exists in the figure
        // system's draw language — a source cross-check. Since
        // v0.5.0f the hair/hat masses are HeadStack data in
        // CharacterSystem.kt (KidArt paints them), so the check
        // reads the figure system as a whole
        val kidArtSrc = File(root,
            "src/com/hunt3r/southparktown/KidArt.kt").readText() +
            File(root,
            "src/com/hunt3r/southparktown/CharacterSystem.kt").readText()
        for (o in CREATOR_OPTIONS["hair_style"]!!.second) {
            check(kidArtSrc.contains("\"${o.id}\""),
                "creator: hair style ${o.id} has a draw branch")
        }
        for (o in CREATOR_OPTIONS["hat"]!!.second) {
            if (o.id == "none") continue
            check(kidArtSrc.contains("\"${o.id}\""),
                "creator: hat ${o.id} has a draw branch")
        }

        // -- the dice: coherent, unlocked-only, deterministic --
        val r1 = randomAppearance(kotlin.random.Random(42))
        val r2 = randomAppearance(kotlin.random.Random(42))
        check(r1 == r2, "creator: the dice are deterministic per seed")
        var diceOk = true
        for (seed in 0 until 200) {
            val r = randomAppearance(kotlin.random.Random(seed))
            if (validateAppearance(r) != r) diceOk = false
            for (c in CREATOR_ORDER) {
                if (creatorOpt(c, r[c]!!).unlockId != null) diceOk = false
            }
            if (r["top"] == "underwear" && r["bottom"] == "underwear")
                diceOk = false
        }
        check(diceOk, "creator: 200 dice rolls all valid, unlocked, dressed")

        // -- presets round-trip --
        val slotsIn = listOf(
            mapOf("hat" to "cap", "build" to "stocky"),
            null,
            DEFAULT_APPEARANCE)
        val round = decodePresets(encodePresets(slotsIn))
        check(round.size == CREATOR_PRESET_SLOTS,
            "creator: presets decode to 3 slots")
        check(round[0] == validateAppearance(slotsIn[0]!!),
            "creator: preset 1 round-trips")
        check(round[1] == null, "creator: an empty preset stays empty")
        check(round[2] == validateAppearance(DEFAULT_APPEARANCE),
            "creator: preset 3 round-trips")
        check(decodePresets("not json") ==
            List<Map<String, String>?>(CREATOR_PRESET_SLOTS) { null },
            "creator: garbage preset data decodes to empty slots")
        check(decodePresets(null).size == CREATOR_PRESET_SLOTS,
            "creator: missing preset data decodes to 3 empty slots")

        // -- #48: every category has its own outfit comment --
        for (c in CREATOR_ORDER) {
            check(outfitCommentLine(c).isNotBlank(),
                "creator: outfit comment exists for $c")
        }
        check(outfitCommentLine("hat") ==
            "New hat? Bold choice. It works, weirdly.",
            "creator: the hat comment is unchanged from v0.1.8")
        check(outfitCommentLine("top") ==
            "New shirt. Trying to impress someone? Who? WHO?",
            "creator: the top comment is unchanged from v0.1.8")
        val lines = CREATOR_ORDER.map { outfitCommentLine(it) }.distinct()
        check(lines.size >= CREATOR_ORDER.size - 1,
            "creator: outfit comments are per-category (hair pair shares one)")
        check(describeAppearance(mapOf("eyewear" to "goggles"))
            .contains("goggles"),
            "creator: describeAppearance names new gear")
    }

    // ================= v0.1.9e: simulation depth =================
    println("== v0.1.9e: simulation depth ==")
    run {
        val engG = Engine()

        // ---- NPC goals: deterministic, personal derivation ----
        val castGoals = KID_ORDER.map { it to NpcGoals.goalFor(it, 0) }
        for ((name, g) in castGoals) {
            check(g.npcKey == name && g.cycle == 0,
                "goals: $name carries a cycle-0 goal")
            check(g.text.isNotBlank() && g.doneText.isNotBlank(),
                "goals: $name goal text is written")
            check(g.locId == null || g.locId in LOCATIONS,
                "goals: $name goal place is a real place")
            check(g.personName == null || g.personName in KID_ORDER,
                "goals: $name goal person is a cast member")
            check(g == NpcGoals.goalFor(name, 0),
                "goals: $name goal derivation is deterministic")
        }
        check(castGoals.map { it.second.text }.distinct().size >= 10,
            "goals: the cast's goals actually vary person to person")
        val allKinds = (0..7).flatMap { c -> KID_ORDER.map { NpcGoals.goalFor(it, c).kind } }.toSet()
        check(allKinds.size >= 5,
            "goals: the kind spread is wide (got $allKinds)")
        check(NpcGoals.cycleOf("20261001") == 0 && NpcGoals.cycleOf("20261002") == 0 &&
            NpcGoals.cycleOf("20261003") == 1 && NpcGoals.cycleOf("20261105") == 17,
            "goals: 2-day cycle math from day keys")
        val varyCount = KID_ORDER.count { n ->
            (0..5).map { NpcGoals.goalFor(n, it).text }.distinct().size > 1
        }
        check(varyCount >= 20,
            "goals: goals expire and renew across cycles ($varyCount/62 vary)")

        // ---- records: progress, completion, traces, expiry ----
        val sG = engG.newState()
        val placeKid = KID_ORDER.first {
            NpcGoals.goalFor(it, NpcGoals.cycleOf(sG.todayKey)).locId != null
        }
        val rec = NpcGoals.record(sG, placeKid)
        check(rec.cycle == NpcGoals.cycleOf(sG.todayKey),
            "goals: the live record matches today's cycle")
        var guard = 0
        while (!rec.done && guard++ < 60) NpcGoals.progressTick(sG, placeKid)
        check(rec.done, "goals: presence ticks complete a place goal")
        check(sG.agents[placeKid]!!.memories.any { it.startsWith("Goal done") },
            "goals: completion leaves a memory trace")
        check(sG.events.any { it.contains("✅") },
            "goals: completion reaches the ticker")
        check(NpcGoals.journalLine(sG, placeKid).startsWith("🎯 Wrapped up"),
            "goals: Journal shows the finished goal")
        // people goals: find a (kid, cycle) that has one, then
        // test contact inside that cycle
        var peoplePair: Pair<String, Int>? = null
        for (c in 0..5) for (n in KID_ORDER) {
            if (peoplePair == null && NpcGoals.goalFor(n, c).personName != null) {
                peoplePair = n to c
            }
        }
        check(peoplePair != null, "goals: people goals occur across cycles")
        if (peoplePair != null) {
            val (pk, pc) = peoplePair
            val sP = engG.newState()
            sP.todayKey = listOf("20261001", "20261003", "20261005",
                "20261007", "20261009", "20261011")[pc]
            val pg = NpcGoals.record(sP, pk)
            check(pg.personName != null, "goals: the people goal is live in its cycle")
            check(!NpcGoals.contactTick(sP, pk, "Nobody With This Name"),
                "goals: contact with the wrong person settles nothing")
            check(NpcGoals.contactTick(sP, pk, pg.personName!!) && pg.done,
                "goals: contact with the goal person settles the goal")
        }
        val sX = engG.newState()
        val stale = NpcGoals.record(sX, "Kyle")
        sX.todayKey = "20261009"
        val fresh = NpcGoals.record(sX, "Kyle")
        check(fresh.cycle == NpcGoals.cycleOf("20261009") && fresh !== stale &&
            !fresh.done && fresh.progress == 0,
            "goals: an expired goal is replaced by a fresh one, not stuck")
        // deviation: deterministic, real places, visibly bending
        val sD = engG.newState()
        val d1 = NpcGoals.deviationLoc(sD, "Cartman", "KidsPark", "10:00", setOf("KidsPark", "Mall"))
        val d2 = NpcGoals.deviationLoc(sD, "Cartman", "KidsPark", "10:00", setOf("KidsPark", "Mall"))
        check(d1 == d2, "goals: deviation agrees with itself")
        check(d1 == null || d1 in LOCATIONS, "goals: deviation target is a real place")
        var bends = 0
        for (n in KID_ORDER) for (bk in listOf("09:00", "12:00", "15:00", "18:00")) {
            if (NpcGoals.deviationLoc(sD, n, "Mall", bk, setOf("Mall", "KidsPark")) != null) bends++
        }
        check(bends >= 3, "goals: schedules visibly bend toward goals ($bends bends)")
        check(NpcGoals.journalLine(sD, "Stan").startsWith("🎯"),
            "goals: Journal line exists for an active goal")
        // generated folks carry goals too
        val someResident = VisitorSystem.residents().first()
        val gg = NpcGoals.goalFor(someResident.loreName, 0)
        check(gg.text.isNotBlank() && gg == NpcGoals.goalFor(someResident.loreName, 0),
            "goals: generated residents get deterministic goals")
        check(NpcGoals.mention(NpcGoals.goalFor("Stan", 1)).isNotBlank(),
            "goals: every goal has a spoken mention")

        // ---- conversation threads ----
        val mem1 = NpcMemory(meets = 1, topics = mutableListOf("money"))
        check(Threads.followUp(mem1, kotlin.random.Random(1)) == null,
            "threads: no follow-up on a first conversation")
        val mem3 = NpcMemory(meets = 3, topics = mutableListOf("school", "money"))
        val fu = Threads.followUp(mem3, kotlin.random.Random(2))
        check(fu != null && fu.contains("money"),
            "threads: the follow-up references the latest topic")
        check(Threads.callback(mem3, kotlin.random.Random(3)) != null,
            "threads: callbacks draw on stored topics")
        NpcMemoryStore.clear()
        NpcMemoryStore.getOrCreate("Thread Tester").apply {
            meets = 3; summary = "Met 3 times."
            topics.add("money"); topics.add("school")
        }
        val pb = NpcMemoryStore.promptBlock("Thread Tester", "Lucky")
        check(pb.contains("THREAD") && pb.contains("money"),
            "threads: the LLM prompt block carries thread context")
        NpcMemoryStore.clear()
        val sT = engG.newState()
        check(Threads.pairTopic(sT, "Stan", "Kyle") == null,
            "threads: pairs start threadless")
        Threads.recordPairTopic(sT, "Stan", "Kyle",
            "Anyway, the money thing at school was wild")
        val pt = Threads.pairTopic(sT, "Kyle", "Stan")
        check(pt == "money" || pt == "school",
            "threads: pair topic recorded from the dialogue's own words (got $pt)")
        check(Threads.pairJoke("Stan", "Kyle") == Threads.pairJoke("Kyle", "Stan"),
            "threads: the running joke belongs to the pair, either way round")
        var cbHits = 0
        repeat(40) { i ->
            if (Threads.pairCallback(sT, "Stan", "Kyle", 0,
                    kotlin.random.Random(i.toLong())) != null) cbHits++
        }
        check(cbHits > 0, "threads: pair callbacks fire on a stored topic")

        // ---- shenanigans: roster of 10, all fully framed ----
        check(SHENANIGANS.size == 10, "events: the roster grew to 10")
        for (id in listOf("coon_sightings", "memberberry_fever",
            "imagination_leak", "gold_fever")) {
            val def = SHENANIGAN_BY_ID[id]
            check(def != null, "events: $id exists")
            if (def != null) {
                check(def.stages.size == 4, "events: $id has the 4-stage arc")
                check(def.causers.isNotEmpty() && def.episodeTitles.size == 2 &&
                    def.coldOpen.isNotEmpty() &&
                    def.coldOpen.all { it.speaker in AGENT_PROFILES },
                    "events: $id carries complete episode framing")
                check(def.stages.all { st ->
                    (st.clusterLoc == null || st.clusterLoc in LOCATIONS) &&
                        (st.weatherLock == null || st.weatherLock in WEATHER) &&
                        st.factionEffects.all { it.factionId in FACTION_BY_ID } &&
                        st.banner.isNotBlank() && st.objective.isNotBlank()
                }, "events: $id stages reference real places, weather, factions")
            }
        }
        check(SHENANIGAN_BY_ID.getValue("coon_sightings").stages.any { it.weatherLock == "fog" } &&
            SHENANIGAN_BY_ID.getValue("memberberry_fever").stages.any { it.weatherLock == "sunny" } &&
            SHENANIGAN_BY_ID.getValue("imagination_leak").stages.any { it.weatherLock == "fog" },
            "events: the new stories use weather locks")
        check(EVENT_LINEAGE.keys.all { it in SHENANIGAN_BY_ID } &&
            EVENT_LINEAGE.values.all { m -> m.keys.all { k -> k in SHENANIGAN_BY_ID } },
            "events: the lineage web only references real events")
        check(EVENT_LINEAGE.keys.containsAll(setOf("coon_sightings", "memberberry_fever",
            "imagination_leak", "gold_fever")),
            "events: the new stories have lineage of their own")
        check(Shenanigans.applyTone("We ride at dawn.", "member", "Randy")
            .contains("'Member"),
            "events: the member tone wraps lines in nostalgia")
        val goldTones = (1..30).map {
            Shenanigans.applyTone("We ride at dawn.", "gold", "Stan")
        }
        check(goldTones.all { it.length > "We ride at dawn.".length } &&
            goldTones.any { it.contains("gold", ignoreCase = true) },
            "events: the gold tone appends fever talk")
        check(Shenanigans.applyTone("We ride at dawn.", "member", "Kenny") ==
            "We ride at dawn.",
            "events: Kenny stays exempt from tones, as ever")

        // ---- holiday traditions ----
        check(HOLIDAY_TRADITIONS.keys == HOLIDAYS.map { it.id }.toSet(),
            "traditions: every one of the 8 holidays has a tradition")
        for ((id, t) in HOLIDAY_TRADITIONS) {
            check(t.locId in LOCATIONS, "traditions: $id gathers somewhere real")
            check(t.beats.size >= 3 && t.dressing.isNotBlank() && t.activity.isNotBlank(),
                "traditions: $id has beats, dressing and an activity")
            check(t.hours.first in 0..23 && t.hours.last in 0..23 &&
                t.hours.first <= t.hours.last, "traditions: $id hours are sane")
            check(HOLIDAY_DRESSING[id]?.isNotEmpty() == true,
                "traditions: $id has drawn dressing elements")
        }
        val sceneSrcE = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        for ((id, els) in HOLIDAY_DRESSING) for (el in els) {
            check(sceneSrcE.contains(el),
                "traditions: SceneArt actually draws '$el' ($id)")
        }
        val sTrad = engG.newState()
        sTrad.holidayId = "halloween"; sTrad.timeMin = 18 * 60
        var tBends = 0
        for (n in KID_ORDER) {
            if (Traditions.bendLoc(sTrad, n, "KidsPark", "18:00",
                    setOf("KidsPark")) == "MainStreet") tBends++
        }
        check(tBends >= 3,
            "traditions: the town bends toward the gathering ($tBends bent)")
        val sPlain = engG.newState(); sPlain.timeMin = 18 * 60
        check(KID_ORDER.none {
            Traditions.bendLoc(sPlain, it, "KidsPark", "18:00", setOf("KidsPark")) != null
        }, "traditions: no tradition bend without a holiday")
        check(Traditions.dressingLine(sTrad, "MainStreet")?.startsWith("🎀") == true,
            "traditions: Look dressing shows at the gathering place")
        check(Traditions.dressingLine(sTrad, "Bank") == null,
            "traditions: no dressing away from the gathering")
        // wiring cross-checks: the surfaces are really hooked
        val journalSrcE = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(journalSrcE.contains("NpcGoals.journalLine"),
            "goals: the Journal WHO cards carry the Currently line")
        val prefsSrcE = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
        check(prefsSrcE.contains("\"npcGoals\""),
            "goals: goal records persist (additive save key)")
        val engineSrcE = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engineSrcE.contains("Threads.pairCallback") &&
            engineSrcE.contains("NpcGoals.deviationLoc") &&
            engineSrcE.contains("Traditions.bendLoc"),
            "sim: engine wires threads, goal deviation and tradition bends")
    }

    // ================= v0.1.9f: polish & performance =================
    // Robustness first: a damaged save must degrade, never crash
    // and never take the surviving data down with it. Then the
    // font-scale contract, then structural perf pins.
    run {
        // -- Json: corruption can never crash the loaders --
        // Pathological nesting must surface as IllegalArgumentException,
        // NOT StackOverflowError (an Error — the loaders' catch
        // (Exception) guards would miss it and the app would die).
        var deepThrew = false
        try {
            Json.parse("[".repeat(5000))
        } catch (e: IllegalArgumentException) {
            deepThrew = true
        }
        check(deepThrew, "json: pathological nesting is rejected, not crashed on")
        check(Json.parse("[".repeat(50) + "]".repeat(50)) is List<*>,
            "json: honest nesting still parses")
        for (bad in listOf("", "{", "{\"a\":", "[1,2", "\"unterminated",
            "tru", "{ bad }", "[[[[", "}}}}")) {
            val t = try { Json.parse(bad); null } catch (e: Throwable) { e }
            check(t == null || t is Exception,
                "json: corrupt input degrades safely: '${bad.take(12)}'")
        }
        val rt = Json.parse(Json.stringify(mapOf(
            "saveFormat" to SAVE_FORMAT_VERSION,
            "nested" to mapOf("a" to listOf(1L, 2L))))) as? Map<String, Any?>
        check(rt != null && inferSaveFormat(rt) == 3,
            "saves: the format stamp survives a round trip")

        // -- save-format inference across the eras --
        check(SAVE_FORMAT_VERSION == 3, "saves: this build writes format 3")
        check(inferSaveFormat(null) == 0, "saves: no doc = no save")
        check(inferSaveFormat(emptyMap()) == 1,
            "saves: a bare core doc reads as format 1")
        check(inferSaveFormat(mapOf("timeMin" to 480L)) == 1,
            "saves: a v0.1.0-era doc reads as format 1")
        check(inferSaveFormat(mapOf("playerInside" to false)) == 2,
            "saves: the v0.1.5 additive doc reads as format 2")
        check(inferSaveFormat(mapOf("playerInside" to false,
            "episodes" to emptyList<Any?>(), "npcGoals" to emptyList<Any?>())) == 2,
            "saves: later additive keys stay format 2")
        check(inferSaveFormat(mapOf("saveFormat" to 3L, "playerInside" to true)) == 3,
            "saves: a stamped doc reads its own stamp")
        check(inferSaveFormat(mapOf("saveFormat" to "junk", "playerInside" to true)) == 2,
            "saves: a garbage stamp falls back to the key test")

        // -- upgrade path: every era's shape through the REAL loader --
        fun eraDoc(extra: Map<String, Any?>): Map<String, Any?> = mapOf(
            "timeMin" to 600L, "gameYear" to 2026L, "gameMonth" to 10L,
            "gameDay" to 3L, "weatherId" to "sunny", "todayKey" to "20261003",
            "agents" to mapOf("Stan" to mapOf(
                "location" to "Elementary", "destination" to "Elementary",
                "coords" to listOf(50L, 50L), "isPlayer" to false,
                "agenda" to mapOf("08:00" to mapOf(
                    "location" to "Elementary", "activity" to "School.")))),
            "friendship" to mapOf("Stan" to 40L),
            "collected" to listOf("test_item")) + extra
        val v1 = decodeGameState(eraDoc(emptyMap()))
        check(v1.timeMin == 600 && v1.agents.containsKey("Stan"),
            "upgrade: a v0.1.0-era core doc loads")
        check(v1.friendship["Stan"] == 40 && "test_item" in v1.collected,
            "upgrade: friendship + collection ride along")
        check(v1.agents.size >= AGENT_PROFILES.size,
            "upgrade: the full cast merges into old saves")
        check(v1.shenaniganId == null && v1.episodes.isEmpty() && v1.npcGoals.isEmpty(),
            "upgrade: later systems default cleanly on old saves")
        val v2 = decodeGameState(eraDoc(mapOf(
            "playerInside" to true, "shenaniganId" to "coon_sightings")))
        check(v2.playerInside && v2.shenaniganId == "coon_sightings",
            "upgrade: a mid-event v0.1.5-era save keeps its event (no re-trigger data)")
        val v5 = decodeGameState(eraDoc(mapOf(
            "playerInside" to false,
            "episodes" to listOf(mapOf("key" to "ev1", "kind" to "event",
                "eventId" to "coon_sightings", "title" to "Test Episode")),
            "npcGoals" to listOf(mapOf("npcKey" to "Stan", "cycle" to 3L,
                "kind" to "ERRAND", "text" to "doing a thing",
                "doneText" to "did a thing")))))
        check(v5.episodes.size == 1 && v5.episodes[0].title == "Test Episode",
            "upgrade: v0.1.9c episode records load")
        check(v5.npcGoals["Stan"]?.cycle == 3,
            "upgrade: v0.1.9e goal records load")

        // -- corrupt VALUES degrade field by field --
        val corrupt = decodeGameState(mapOf(
            "timeMin" to 999999L, "gameMonth" to 99L, "gameDay" to -5L,
            "todayKey" to "20269901",
            "agents" to mapOf(
                "Stan" to mapOf(
                    "location" to "Atlantis", "destination" to "Nowhere",
                    "coords" to listOf(5000L, -40L),
                    "agenda" to mapOf("08:00" to mapOf(
                        "location" to "Atlantis", "activity" to "???"))),
                "NewKid" to mapOf("isPlayer" to true, "location" to "Atlantis")),
            "friendship" to "not-even-a-map",
            "episodes" to listOf("garbage", 42L),
            "npcGoals" to mapOf("wrong" to "shape")))
        check(corrupt.timeMin in 0..1439, "corrupt: timeMin clamps into the day")
        check(corrupt.gameMonth in 1..12 && corrupt.gameDay in 1..31,
            "corrupt: date fields clamp")
        check(corrupt.todayKey.length == 8 && corrupt.todayKey.all { it.isDigit() },
            "corrupt: an impossible todayKey is rebuilt from the date " +
            "(the engine slices it unguarded — a short key crashed tick 1)")
        val stanC = corrupt.agents["Stan"]
        check(stanC != null && stanC.location == "BusStop" &&
            stanC.destination == "BusStop",
            "corrupt: bogus places land at the Bus Stop")
        check(stanC != null && stanC.coords.first in 0..100 &&
            stanC.coords.second in 0..100, "corrupt: coords clamp to the grid")
        check(stanC?.agenda?.get("08:00")?.location == "BusStop",
            "corrupt: agenda places sanitize too")
        check(corrupt.agents.values.firstOrNull { it.isPlayer }?.location == "BusStop",
            "corrupt: a bogus PLAYER place can't black-screen the game")
        check(corrupt.episodes.isEmpty(),
            "corrupt: garbage episode entries are skipped, not fatal")
        check(ordinalOfKey("20269901") == 0 && ordinalOfKey("20261340") == 0,
            "corrupt: impossible date keys read as no-date")
        check(ordinalOfKey("20261013") > ordinalOfKey("20261001"),
            "dates: real keys still order correctly")
        check(NpcGoals.cycleOf("20269901") >= 0,
            "corrupt: the goal cycle survives an impossible day key")

        // -- salvage: a dead main doc loses nothing that survives --
        val rec = recoverGameState("{\"Stan\": 55}", "[\"a\", \"b\"]",
            "2026-10-12", "2026-10-01")
        check(rec.friendship["Stan"] == 55,
            "salvage: friendship survives a dead main doc")
        check(rec.collected.containsAll(listOf("a", "b")),
            "salvage: the collection survives")
        check(rec.lastPlayedDate == "2026-10-12" && rec.spawnDate == "2026-10-01",
            "salvage: the dates survive")
        check(rec.agents.size >= AGENT_PROFILES.size,
            "salvage: the town itself is whole")
        val recBad = recoverGameState("garbage{", "also]bad", "", "")
        check(recBad.friendship["Stan"] == 0 && recBad.collected.isEmpty(),
            "salvage: garbage backup keys degrade to defaults")
        val recNull = recoverGameState(null, null, "", "")
        check(recNull.agents.isNotEmpty(),
            "salvage: missing backup keys still yield a town")

        // -- day-0: a decoded empty save ticks without dying --
        val day0 = decodeGameState(emptyMap())
        val engF = Engine()
        repeat(40) { engF.advanceTime(day0) }
        check(day0.timeMin in 0..1439, "day-0: an empty save survives 40 ticks")

        // -- newest systems: garbage records default, never crash --
        check(Episodes.fromMap(emptyMap()) == null,
            "episodes: a record without a key is dropped")
        val epGarbage = Episodes.fromMap(mapOf("key" to "k1",
            "participation" to "lots", "causers" to "notalist",
            "actsShown" to listOf("x", 2L)))
        check(epGarbage != null && epGarbage.participation == 0 &&
            epGarbage.causers.isEmpty() && epGarbage.actsShown.contains(2) &&
            epGarbage.actsShown.size == 1,
            "episodes: garbage fields default, good ones survive")
        check(NpcGoal.fromMap(emptyMap()) == null,
            "goals: a record without an npc key is dropped")
        val goalGarbage = NpcGoal.fromMap(mapOf("npcKey" to "Stan",
            "cycle" to "soon", "needTicks" to "many"))
        check(goalGarbage != null && goalGarbage.cycle == 0 &&
            goalGarbage.needTicks == 4, "goals: garbage numbers default")
        check(decodePresets("not json").all { it == null },
            "creator: garbage presets read as empty slots")
        check(decodePresets("[1, 2]").all { it == null },
            "creator: non-map presets read as empty slots")
        check(decodePresets(null).size == CREATOR_PRESET_SLOTS,
            "creator: missing presets = the empty slots")
        check(validateAppearance(mapOf("skin" to "chartreuse"))["skin"] ==
            DEFAULT_APPEARANCE["skin"],
            "creator: an unknown option id falls back to the default")
        check(validateAppearance(null)["top"] == DEFAULT_APPEARANCE["top"],
            "creator: a missing appearance is the blank New Kid")

        // -- font scale: identity at 1.0, geometry only grows --
        check(Chrome.fontScaleOf(1.0f) == 1.0f, "a11y: scale 1.0 is itself")
        check(Chrome.fontScaleOf(0.5f) == Chrome.FONT_SCALE_MIN,
            "a11y: tiny scales clamp at the floor")
        check(Chrome.fontScaleOf(2.0f) == Chrome.FONT_SCALE_MAX,
            "a11y: huge scales clamp at the cap")
        check(Chrome.fontScaleOf(1.15f) == 1.15f, "a11y: in-range scales pass through")
        check(Chrome.eventStripHeight(1f) == Chrome.EVENT_STRIP_H_PX &&
            Chrome.eventStripTextDy(1f) == Chrome.EVENT_STRIP_TEXT_DY_PX &&
            Chrome.bubbleTop(118f, true, 1f) == Chrome.bubbleTop(118f, true) &&
            Chrome.bubbleHeight(2, 1f) == Chrome.bubbleHeight(2) &&
            Chrome.bubbleContentBottom(2, 1f) == Chrome.bubbleContentBottom(2),
            "a11y: at scale 1.0 every overlay number is the shipped one")
        for (fs in listOf(0.85f, 1.0f, 1.15f, 1.3f)) {
            check(Chrome.geoScale(fs) >= 1f, "a11y: geometry never shrinks (fs $fs)")
            check(Chrome.eventStripHeight(fs) >= Chrome.EVENT_STRIP_H_PX,
                "a11y: the strip never gets shorter (fs $fs)")
            for (ct in listOf(0f, 118f)) {
                check(Chrome.bubbleTop(ct, true, fs) >=
                    ct + Chrome.eventStripHeight(fs) + 10f - 0.01f,
                    "a11y: the bubble still clears the grown strip (fs $fs, top $ct)")
                check(Chrome.bubbleTop(ct, false, fs) == ct + Chrome.BUBBLE_GAP_PLAIN_PX,
                    "a11y: the plain bubble offset is scale-free (fs $fs)")
            }
            for (n in 1..2) {
                check(Chrome.bubbleContentBottom(n, fs) + 20f <=
                    Chrome.bubbleHeight(n, fs) + 0.01f,
                    "a11y: bubble content fits with room at fs $fs ($n lines)")
            }
        }
        // strip text at max scale: ascenders/descenders stay in the band
        check(Chrome.eventStripTextDy(Chrome.FONT_SCALE_MAX) -
            13f * Chrome.FONT_SCALE_MAX * 0.8f >= 0f,
            "a11y: strip text never clips the top at max scale")
        check(Chrome.eventStripTextDy(Chrome.FONT_SCALE_MAX) +
            13f * Chrome.FONT_SCALE_MAX * 0.25f <=
            Chrome.eventStripHeight(Chrome.FONT_SCALE_MAX),
            "a11y: strip text never clips the bottom at max scale")

        // -- contrast, re-verified for the pairs actually in use --
        check(Chrome.contrast("#e8e8e8", Chrome.CHARCOAL) >= 4.5f,
            "a11y: Settings body text on charcoal")
        check(Chrome.contrast(Chrome.INK, Chrome.PAPER_WHITE) >= 4.5f,
            "a11y: bubble text on paper white")
        check(Chrome.contrast("#ffffff", "#555555") >= 4.5f,
            "a11y: white on the unselected toggle grey")
        check(Chrome.contrast(Chrome.RED, Chrome.CHARCOAL) >= 3.0f,
            "a11y: red section titles (large bold text) on charcoal")

        // -- perf structure: the wins are real, not vibes --
        val paperSrc = File(root, "src/com/hunt3r/southparktown/Paper.kt").readText()
        check(paperSrc.contains("colorCache"),
            "perf: Paper caches parsed colors")
        check(Regex("Color\\.parseColor").findAll(paperSrc).count() == 1,
            "perf: exactly one parse site left — the cache's own")
        check(paperSrc.contains("fibreCache"),
            "perf: the grain fields are kept, not re-made per frame " +
                "(v0.16.0d: the fibre cache succeeds the retired " +
                "speckle grain paint, removed with its system)")
        val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
        check(gvSrc.contains("Chrome.fontScaleOf") &&
            gvSrc.contains("Chrome.eventStripHeight(fs)") &&
            gvSrc.contains("Chrome.bubbleHeight(show.size, fs)"),
            "a11y: GameView routes strip + bubble through the scaled geometry")
        val prefsSrcF = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
        check(prefsSrcF.contains("\"saveFormat\" to SAVE_FORMAT_VERSION"),
            "saves: the doc stamps its format")
        check(prefsSrcF.contains("fun decodeGameState") &&
            prefsSrcF.contains("fun recoverGameState"),
            "saves: loader + salvage are in place")
        val settingsSrcF = File(root,
            "src/com/hunt3r/southparktown/SettingsActivity.kt").readText()
        check(settingsSrcF.contains("storedSaveFormat()"),
            "saves: Settings shows the save format")
        val manifestSrc = File(root, "AndroidManifest.xml").readText()
        check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
            manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
            "release: the manifest itself carries 67 / 0.9.0a (no stale-manifest repeat)")
        check(File(root, "res/drawable/ic_launcher.png").length() > 0,
            "icon: a launcher icon ships")
        check(File(root, "tools/gen_icon.py").exists(),
            "icon: the icon is drawn by an in-repo generator")
    }

    // ================= v0.2.0a: scene parity pass #2 =================
    // Interiors depth & location identity: signature set-dressing
    // per room (registry cross-checked against InteriorArt, the
    // pass-#1 discipline), interior signage literals, and the
    // palette identity rules (distinctness + neighbor distance).
    println("== v0.2.0a: interiors depth & location identity ==")
    run {
        val interiorSrc = File(root,
            "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
        check(INTERIOR_ART_DETAILS.size == 27,
            "interior parity: registry covers all 27 interiors")
        for ((locId, tokens) in INTERIOR_ART_DETAILS) {
            check(INTERIORS.containsKey(locId),
                "interior parity: $locId is a real interior")
            check(tokens.size >= 3,
                "interior parity: $locId carries 3+ signature pieces")
            for (tok in tokens) {
                check(interiorSrc.contains("idetail: $tok"),
                    "interior parity: drawn — $locId/$tok")
            }
        }
        // a signature is not a template: no token serves two rooms
        val allToks = INTERIOR_ART_DETAILS.values.flatten()
        check(allToks.size == allToks.toSet().size,
            "interior parity: no dressing token is shared between interiors")
        // and no two rooms keep the same identity triple
        val triples = INTERIORS.values.map { Triple(it.wallHex, it.floorHex, it.props) }
        check(triples.size == triples.toSet().size,
            "interior parity: no two interiors share wall + floor + props")
        check(interiorSrc.contains("drawInteriorWallDetails") &&
            interiorSrc.contains("drawInteriorFloorDetails"),
            "interior parity: both dressing layers run in drawRoom")
        // signage: registered, attached to a real detail, and the
        // exact words are drawn in the art source
        for ((tok, text) in INTERIOR_SIGN_TEXTS) {
            check(allToks.contains(tok), "signage: $tok is a registered detail")
            check(interiorSrc.contains("\"$text\""),
                "signage: '$text' is lettered for $tok")
        }
        // palette identity: the record can't drift from the data
        // the renderers actually use
        fun rgbOf(hex: String): Triple<Int, Int, Int> {
            val v = hex.removePrefix("#").toInt(16)
            return Triple(v shr 16 and 255, v shr 8 and 255, v and 255)
        }
        fun dist(a: String, b: String): Double {
            val (r1, g1, b1) = rgbOf(a); val (r2, g2, b2) = rgbOf(b)
            return kotlin.math.sqrt(((r1 - r2) * (r1 - r2) +
                (g1 - g2) * (g1 - g2) + (b1 - b2) * (b1 - b2)).toDouble())
        }
        check(LOC_PALETTES.size == 27, "palette: a signature for all 27 locations")
        for ((id, pal) in LOC_PALETTES) {
            check(pal.fieldHex == LOCATIONS[id]?.colorHex,
                "palette: $id field matches its Location color")
            check(pal.wallHex == INTERIORS[id]?.wallHex,
                "palette: $id wall matches its InteriorDef")
            check(pal.floorHex == INTERIORS[id]?.floorHex,
                "palette: $id floor matches its InteriorDef")
        }
        check(LOC_PALETTES.values.map { it.accentHex }.toSet().size == 27,
            "palette: all 27 accents distinct")
        val pids = LOC_PALETTES.keys.toList()
        var minWall = Double.MAX_VALUE; var minFloor = Double.MAX_VALUE
        var minField = Double.MAX_VALUE
        for (i in pids.indices) for (j in i + 1 until pids.size) {
            val a = LOC_PALETTES[pids[i]]!!; val b = LOC_PALETTES[pids[j]]!!
            minWall = minOf(minWall, dist(a.wallHex, b.wallHex))
            minFloor = minOf(minFloor, dist(a.floorHex, b.floorHex))
            minField = minOf(minField, dist(a.fieldHex, b.fieldHex))
        }
        check(minWall >= 18.0,
            "palette: walls measurably distinct (min ${"%.1f".format(minWall)})")
        check(minFloor >= 16.0,
            "palette: floors measurably distinct (min ${"%.1f".format(minFloor)})")
        check(minField >= 14.0,
            "palette: fields measurably distinct (min ${"%.1f".format(minField)})")
        // neighbors on the map must not read as the same place:
        // combined field+wall+floor signature distance
        var minSig = Double.MAX_VALUE
        for ((a, ns) in EXITS) for (b in ns) {
            val pa = LOC_PALETTES[a] ?: continue
            val pb = LOC_PALETTES[b] ?: continue
            val sig = kotlin.math.sqrt(
                dist(pa.fieldHex, pb.fieldHex).let { it * it } +
                dist(pa.wallHex, pb.wallHex).let { it * it } +
                dist(pa.floorHex, pb.floorHex).let { it * it })
            if (sig < minSig) minSig = sig
        }
        check(minSig >= 60.0,
            "palette: map neighbors differ (min signature ${"%.1f".format(minSig)})")
    }

    // ================= v0.2.0b: audio pass =================
    // The game was silent; now everything is SYNTHESIZED in code
    // (SoundGen, pure) and played by SoundEngine. Pinned here:
    // deterministic + bounded buffers, the original town tune's
    // note data (it must stay the tune we composed, in the
    // pentatonic, resolving home), blip families (Kenny muffled,
    // by law), the ambience selection table, music presence,
    // the settings math, the WAV cache shape, the lifecycle
    // wiring, and the zero-audio-files rule over the source tree.
    println("== v0.2.0b: synthesized audio ==")
    run {
        fun peakOf(pcm: ShortArray): Int = pcm.maxOf { kotlin.math.abs(it.toInt()) }
        // every one-shot: deterministic, bounded, not silence
        for (id in SoundGen.SFX_IDS) {
            val a = SoundGen.renderSfx(id)
            val b = SoundGen.renderSfx(id)
            check(a.contentEquals(b), "audio: $id renders deterministically")
            check(a.isNotEmpty() &&
                a.size <= (SoundGen.MAX_SFX_SEC * SoundGen.SAMPLE_RATE).toInt(),
                "audio: $id is bounded (${a.size} samples)")
            check(peakOf(a) > 3000, "audio: $id is not silence (peak ${peakOf(a)})")
        }
        check(SoundGen.SFX_IDS.size == 21,
            "audio: the SFX kit is 21 strong (v0.2.0e added splash/coin/taco)")
        // seeded variants: different seed, different take
        check(!SoundGen.renderSnowStep(1).contentEquals(SoundGen.renderSnowStep(2)),
            "audio: snow step variants differ by seed")
        check(SoundGen.renderSnowStep(3).contentEquals(SoundGen.renderSnowStep(3)),
            "audio: snow step render is deterministic per seed")
        check(SoundGen.renderSnowStep(0).size in 2000..6000,
            "audio: a snow step is a step, not a song")
        // blips: one chirp per family, none silent
        for (fam in SoundGen.BlipFam.values()) {
            val blip = SoundGen.renderBlip(fam, 42L)
            check(blip.size in 1000..(0.2 * SoundGen.SAMPLE_RATE).toInt(),
                "audio: blip ${fam.name} is a short chirp (${blip.size})")
            check(peakOf(blip) > 3000, "audio: blip ${fam.name} is not silence")
            check(blip.contentEquals(SoundGen.renderBlip(fam, 42L)),
                "audio: blip ${fam.name} renders deterministically")
        }
        check(SoundGen.familyFor("Kenny") == SoundGen.BlipFam.MUFFLED,
            "audio: Kenny's blip family is MUFFLED (parka rules)")
        check(SoundGen.familyFor("Chef") == SoundGen.BlipFam.ADULT_DEEP,
            "audio: Chef is ADULT_DEEP")
        check(SoundGen.familyFor("Stan") == SoundGen.BlipFam.KID &&
            SoundGen.familyFor("Wendy") == SoundGen.BlipFam.KID_HIGH &&
            SoundGen.familyFor("Randy") == SoundGen.BlipFam.ADULT_M &&
            SoundGen.familyFor("Sharon") == SoundGen.BlipFam.ADULT_F,
            "audio: core cast pitch families")
        for (name in KID_ORDER) {
            check(SoundGen.BLIP_FAMILIES.containsKey(name),
                "audio: cast member $name has an explicit blip family")
        }
        check(SoundGen.familyFor("Some Generated Person") ==
            SoundGen.familyFor("Some Generated Person"),
            "audio: generated names resolve a stable family")
        // ---- the town tune: ORIGINAL note data, pinned ----
        check(TownMusic.MELODY.size == 30, "music: the melody is 30 notes")
        check(TownMusic.MELODY.first().midi == 69 &&
            TownMusic.MELODY.last().midi == 62,
            "music: melody opens on A4 and resolves home to D4")
        val penta = setOf(2, 4, 6, 9, 11) // D E F# A B pitch classes
        check(TownMusic.MELODY.all { (it.midi % 12) in penta },
            "music: every melody note is D-major pentatonic")
        check(TownMusic.MELODY.all {
            it.bar in 0 until TownMusic.BARS && it.beat >= 0.0 && it.beat < 4.0 },
            "music: melody notes sit inside the 8 bars")
        check(TownMusic.CHORD_BASS == listOf(38, 43, 38, 45, 47, 43, 38, 45),
            "music: progression is D G D A Bm G D A")
        check(TownMusic.CHORD_TONES.size == TownMusic.BARS &&
            TownMusic.CHORD_TONES.all { it.size == 4 },
            "music: four roll tones per bar")
        check(TownMusic.LOOP_SAMPLES == TownMusic.BARS * TownMusic.BEATS_PER_BAR *
            SoundGen.SAMPLE_RATE * 60 / TownMusic.BPM,
            "music: loop length matches bars x beats x tempo")
        val loop1 = TownMusic.renderLoop()
        val loop2 = TownMusic.renderLoop()
        check(loop1.contentEquals(loop2), "music: the loop renders deterministically")
        check(loop1.size == TownMusic.LOOP_SAMPLES,
            "music: the loop is exactly LOOP_SAMPLES long")
        check(peakOf(loop1) > 8000, "music: the loop is not silence")
        // ---- ambience: selection table + loop shape ----
        check(SoundGen.selectAmbience("rain", 600, false) == SoundGen.AmbBed.RAIN,
            "amb: rain outdoors = rain bed")
        check(SoundGen.selectAmbience("blizzard", 600, false) == SoundGen.AmbBed.WIND_STRONG,
            "amb: blizzard = strong wind")
        check(SoundGen.selectAmbience("heavy_snow", 600, false) == SoundGen.AmbBed.WIND_STRONG,
            "amb: heavy snow = strong wind")
        check(SoundGen.selectAmbience("wind", 600, false) == SoundGen.AmbBed.WIND_STRONG,
            "amb: wind weather = strong wind")
        check(SoundGen.selectAmbience("light_snow", 600, false) == SoundGen.AmbBed.WIND_LIGHT,
            "amb: light snow = light wind")
        check(SoundGen.selectAmbience("fog", 600, false) == SoundGen.AmbBed.WIND_LIGHT,
            "amb: fog = light wind")
        check(SoundGen.selectAmbience("sunny", 23 * 60, false) == SoundGen.AmbBed.CRICKETS,
            "amb: clear night = crickets")
        check(SoundGen.selectAmbience("cloudy", 2 * 60, false) == SoundGen.AmbBed.CRICKETS,
            "amb: cloudy small hours = crickets")
        check(SoundGen.selectAmbience("sunny", 12 * 60, false) == SoundGen.AmbBed.NONE,
            "amb: clear day = no bed (the tune carries it)")
        check(SoundGen.selectAmbience("rain", 600, true) == SoundGen.AmbBed.ROOM,
            "amb: indoors always wins")
        check(SoundGen.selectAmbience("sunny", 23 * 60, true) == SoundGen.AmbBed.ROOM,
            "amb: indoors beats crickets")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val buf = SoundGen.renderAmbience(bed)
            check(buf.size == SoundGen.AMB_LOOP_SAMPLES,
                "amb: $bed loop is exactly AMB_LOOP_SAMPLES")
            check(buf.contentEquals(SoundGen.renderAmbience(bed)),
                "amb: $bed renders deterministically")
            check(peakOf(buf) > 400, "amb: $bed is not silence")
        }
        check(SoundGen.renderAmbience(SoundGen.AmbBed.NONE).all { it == 0.toShort() },
            "amb: NONE is true silence")
        // ---- music presence by time/place ----
        close(musicPresence(false, 12 * 60), 1f, 0.001f, "music: full outdoors at noon")
        close(musicPresence(true, 12 * 60), 0.35f, 0.001f, "music: through the wall indoors")
        close(musicPresence(false, 23 * 60 + 30), 0f, 0.001f, "music: asleep late at night")
        close(musicPresence(false, 5 * 60), 0f, 0.001f, "music: still asleep before 6")
        close(musicPresence(false, 6 * 60), 1f, 0.001f, "music: awake at 6")
        // ---- settings math ----
        val adef = AudioSettings.DEFAULT
        check(adef.music == 60 && adef.sfx == 80 && adef.ambience == 60 && !adef.muted,
            "audio settings: defaults ON at modest volume (60/80/60)")
        close(adef.copy(muted = true).gain(AudioChannel.SFX), 0f, 0.0001f,
            "audio settings: mute zeroes a channel")
        close(adef.copy(muted = true).gain(AudioChannel.MUSIC), 0f, 0.0001f,
            "audio settings: mute zeroes the tune too")
        close(adef.withVolume(AudioChannel.MUSIC, 100).gain(AudioChannel.MUSIC),
            1f, 0.0001f, "audio settings: 100 = unity gain")
        close(adef.withVolume(AudioChannel.SFX, 0).gain(AudioChannel.SFX),
            0f, 0.0001f, "audio settings: 0 = silent channel")
        check(adef.withVolume(AudioChannel.MUSIC, 140).volumeOf(AudioChannel.MUSIC) == 100,
            "audio settings: volumes clamp to 100")
        check(adef.withVolume(AudioChannel.AMBIENCE, -5).volumeOf(AudioChannel.AMBIENCE) == 0,
            "audio settings: volumes clamp to 0")
        check(adef.gain(AudioChannel.SFX) > adef.gain(AudioChannel.MUSIC),
            "audio settings: default sfx sits above default music")
        // ---- WAV cache shape ----
        val tapPcm = SoundGen.renderSfx("ui_tap")
        val wav = SoundGen.wavBytes(tapPcm)
        check(wav.size == 44 + tapPcm.size * 2, "audio: WAV size = header + PCM")
        check(String(wav.copyOfRange(0, 4)) == "RIFF" &&
            String(wav.copyOfRange(8, 12)) == "WAVE",
            "audio: WAV magic is RIFF/WAVE")
        check(wav.contentEquals(SoundGen.wavBytes(tapPcm)),
            "audio: WAV encoding is deterministic")
        // ---- wiring + the zero-audio-files rule ----
        val genSrc = File(root, "src/com/hunt3r/southparktown/SoundGen.kt").readText()
        check(!genSrc.contains("import android"),
            "audio: SoundGen is pure (no android imports)")
        val engSrc = File(root, "src/com/hunt3r/southparktown/Sound.kt").readText()
        check(engSrc.contains("SoundPool") && engSrc.contains("AudioTrack"),
            "audio: the engine plays via SoundPool + AudioTrack")
        check(engSrc.contains("USAGE_MEDIA"),
            "audio: everything rides STREAM_MUSIC conventions")
        check(engSrc.contains("RINGER_MODE_SILENT"),
            "audio: silent ringer keeps the beds politely off")
        val gaSrcA = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gaSrcA.contains("SoundEngine.pauseLoops()"),
            "audio: GameActivity pauses the loops onPause")
        check(gaSrcA.contains("SoundEngine.startLoops()"),
            "audio: GameActivity starts the loops onResume")
        check(gaSrcA.contains("SoundEngine.updateWorld("),
            "audio: GameActivity feeds weather/time/indoors to the engine")
        check(gaSrcA.contains("SoundEngine.footsteps("),
            "audio: travel has footsteps")
        check(gaSrcA.contains("SoundEngine.snowball()"),
            "audio: snowballs whoosh, then splat")
        check(gaSrcA.contains("SoundEngine.titleSting()") &&
            gaSrcA.contains("SoundEngine.actSting()") &&
            gaSrcA.contains("SoundEngine.creditsMotif()"),
            "audio: episode cards sting, act-break, and roll credits")
        check(gaSrcA.contains("engine.onStageShift"),
            "audio: the engine's stage shifts cue the sound")
        val dsSrcA = File(root, "src/com/hunt3r/southparktown/DialogueSheet.kt").readText()
        check(dsSrcA.contains("SoundEngine.blip("),
            "audio: speech bubbles blip per speaker")
        val prefsSrcA = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
        check(prefsSrcA.contains("\"audio_music\"") && prefsSrcA.contains("\"audio_sfx\"") &&
            prefsSrcA.contains("\"audio_amb\"") && prefsSrcA.contains("\"audio_muted\""),
            "audio: settings persist under additive keys")
        val setSrcA = File(root, "src/com/hunt3r/southparktown/SettingsActivity.kt").readText()
        check(setSrcA.contains("SOUND") && setSrcA.contains("AudioChannel.MUSIC") &&
            setSrcA.contains("AudioChannel.SFX") &&
            setSrcA.contains("AudioChannel.AMBIENCE"),
            "audio: Settings carries the sound section, all three channels")
        val audioExts = setOf("mp3", "wav", "ogg", "oga", "m4a", "aac",
            "flac", "mid", "midi", "opus")
        val shippedFiles = listOf(File(root, "assets"), File(root, "res"))
            .flatMap { it.walkTopDown().toList() }.filter { it.isFile }
        check(shippedFiles.none { it.extension.lowercase() in audioExts },
            "audio: zero audio files in assets/ or res/ — all sound is synthesized")
        val allSrc = File(root, "src").walkTopDown()
            .filter { it.extension == "kt" }
            .joinToString("\n") { it.readText() }
        check(!allSrc.contains(".mp3") && !allSrc.contains(".ogg") &&
            !allSrc.contains("R.raw."),
            "audio: no bundled-audio references anywhere in src")
    }

    // ================= v0.2.0c: the selfie system =================
    println("== v0.2.0c: selfies, followers & photo feats ==")
    run {
        val engP = Engine()

        // ---- reactions across every relationship tier ----
        check(Photos.reactionFor("Stan", 100, "k") == Photos.GOOFY,
            "photos: a close friend goes GOOFY")
        check(Photos.reactionFor("Stan", 40, "k") == Photos.HAPPY,
            "photos: a friend poses HAPPY")
        check(Photos.reactionFor("Stan", 15, "k") == Photos.NEUTRAL,
            "photos: an acquaintance poses NEUTRAL")
        check(Photos.reactionFor("Stan", 5, "k") == Photos.NEUTRAL,
            "photos: a stranger poses NEUTRAL (stiffly)")
        val rivalCall = Photos.reactionFor("Cartman", -30, "seedA")
        check(rivalCall == Photos.REFUSE || rivalCall == Photos.PHOTOBOMB,
            "photos: a rival refuses or bombs — never poses sweetly")
        check(rivalCall == Photos.reactionFor("Cartman", -30, "seedA"),
            "photos: the rival call is deterministic")
        var bombSeed: String? = null
        for (i in 0 until 400) {
            if (Photos.reactionFor("Randy", -30, "s$i") == Photos.PHOTOBOMB) {
                bombSeed = "s$i"; break
            }
        }
        check(bombSeed != null, "photos: photobombs occur in rival seed space")
        if (bombSeed != null) {
            check(Photos.reactionFor("Randy", -30, bombSeed) == Photos.PHOTOBOMB,
                "photos: the bomb seed is stable across calls")
        }
        var refuseSeen = false
        for (i in 0 until 40) {
            if (Photos.reactionFor("Randy", -30, "r$i") == Photos.REFUSE) {
                refuseSeen = true; break
            }
        }
        check(refuseSeen, "photos: outright refusals occur too")

        // ---- goofy poses + the mood map ----
        val poseSet = (0 until 60).map { Photos.goofyPoseFor("Kyle", it.toLong()) }.toSet()
        check(poseSet.all { it in setOf("bunny", "tongue", "swap") } && poseSet.size >= 2,
            "photos: goofy poses are the known set and vary ($poseSet)")
        check(Photos.moodFor(Photos.GOOFY, "tongue") == "goofy",
            "photos: tongue pose wears the tongue-out face")
        check(Photos.moodFor(Photos.GOOFY, "bunny") == "happy" &&
            Photos.moodFor(Photos.HAPPY, "none") == "happy" &&
            Photos.moodFor(Photos.NEUTRAL, "none") == "idle" &&
            Photos.moodFor(Photos.PHOTOBOMB, "bomb") == "happy",
            "photos: reactions map to expression-system moods")

        // ---- follower math (prominence x affection) ----
        fun figOf(name: String, kind: String, reaction: String, points: Int) =
            PhotoFigure(name, kind, "happy", reaction = reaction, points = points)
        check(Photos.uniqueGain(figOf("Stan", "cast", Photos.GOOFY, 100)) == 24,
            "photos: cast close friend pays 12 x 2.0 = 24")
        check(Photos.uniqueGain(figOf("Stan", "cast", Photos.HAPPY, 40)) == 18,
            "photos: cast friend pays 12 x 1.5 = 18")
        check(Photos.uniqueGain(figOf("A", "resident", Photos.HAPPY, 40)) == 9,
            "photos: resident friend pays 6 x 1.5 = 9")
        check(Photos.uniqueGain(figOf("B", "visitor", Photos.NEUTRAL, 5)) == 3,
            "photos: visitor stranger pays 4 x 0.75 = 3")
        check(Photos.uniqueGain(figOf("C", "cast", Photos.PHOTOBOMB, -30)) == 6,
            "photos: a cast photobomb still pays half (12 x 0.5 = 6)")
        check(Photos.baseFor("cast") > Photos.baseFor("resident") &&
            Photos.baseFor("resident") > Photos.baseFor("visitor"),
            "photos: prominence ladder cast > residents > visitors")

        // ---- milestone edges ----
        check(Photos.crossedMilestone(9, 10) == 10,
            "photos: crossing 10 lands the badge")
        check(Photos.crossedMilestone(10, 10) == null,
            "photos: sitting on a milestone re-fires nothing")
        check(Photos.crossedMilestone(49, 60) == 50,
            "photos: crossing 50 lands 50")
        check(Photos.crossedMilestone(0, 300) == 250,
            "photos: a huge jump reports the highest crossed")
        check(Photos.crossedMilestone(0, 9) == null,
            "photos: no milestone under 10")
        check(Photos.badgeFor(300) == 250 && Photos.nextMilestone(300) == 500 &&
            Photos.badgeFor(3) == null,
            "photos: badge/next math")

        // ---- compose: determinism, player, refusal, record I/O ----
        val sR = engP.newState()
        sR.todayKey = "20261013"
        sR.friendship["Stan"] = 100
        sR.friendship["Kyle"] = 40
        val recR = Photos.compose(sR, listOf("Stan", "Kyle"), emptyList(),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        check(recR.figures.first().kind == "player",
            "photos: you are always in your own selfie")
        check(recR.figures.any { it.name == "Stan" && it.reaction == Photos.GOOFY },
            "photos: the close friend in frame is goofy")
        check(recR.figures.any { it.name == "Kyle" && it.reaction == Photos.HAPPY },
            "photos: the friend in frame is happy")
        check(recR.locId == "BusStop" && recR.dateLabel == "10/13",
            "photos: the record knows where and when")
        check(recR.caption.contains("Stan") && recR.caption.contains("Bus Stop"),
            "photos: the caption names names and places")
        check(Photos.compose(sR, listOf("Stan", "Kyle"), emptyList(),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE) == recR,
            "photos: compose is deterministic for the same town moment")
        val backR = PhotoRecord.fromMap(recR.toMap())
        check(backR != null && backR == recR,
            "photos: a record round-trips through its save map")
        val jsonRound = PhotoRecord.fromMap(
            (Json.parse(Json.stringify(recR.toMap())) as Map<String, Any?>))
        check(jsonRound == recR,
            "photos: a record survives the actual JSON save format")

        // ---- generated folks pose too, off their memory points ----
        val persona0 = VisitorSystem.residents().first()
        NpcMemoryStore.getOrCreate(persona0.loreName).points = 100
        val sGen = engP.newState()
        sGen.todayKey = "20261013"
        val recGen = Photos.compose(sGen, emptyList(), listOf(persona0),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        check(recGen.figures.any {
            it.name == persona0.loreName && it.kind == "resident" &&
                it.reaction == Photos.GOOFY
        }, "photos: a beloved generated resident goes goofy too")

        // ---- refusal: a snubbed shot is a solo shot ----
        val sSnub = engP.newState()
        sSnub.todayKey = "20261013"
        sSnub.friendship["Cartman"] = -30
        var snubRec: PhotoRecord? = null
        for (t in 480..1439 step 15) {
            sSnub.timeMin = t
            val r = Photos.compose(sSnub, listOf("Cartman"), emptyList(),
                PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            if (r.refused.isNotEmpty()) { snubRec = r; break }
        }
        check(snubRec != null, "photos: a refusing rival shows up in seed space")
        if (snubRec != null) {
            check(snubRec.npcs.isEmpty() && snubRec.caption.contains("said no. Rude."),
                "photos: total refusal = solo selfie + the snub in the caption")
            val resSnub = Photos.applyPhoto(sSnub, snubRec)
            check(resSnub.gained == 0 && !sSnub.photographed.containsKey("Cartman"),
                "photos: a refuser earns you nothing and is not 'photographed'")
        }

        // ---- photobomb: crashes the frame, still counts ----
        val sBomb = engP.newState()
        sBomb.todayKey = "20261013"
        sBomb.friendship["Randy"] = -30
        var bombRec: PhotoRecord? = null
        for (t in 480..1439 step 15) {
            sBomb.timeMin = t
            val r = Photos.compose(sBomb, listOf("Randy"), emptyList(),
                PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            if (r.npcs.any { it.reaction == Photos.PHOTOBOMB }) { bombRec = r; break }
        }
        check(bombRec != null, "photos: a bombing rival shows up in seed space")
        if (bombRec != null) {
            check(bombRec.caption.contains("photobombed it"),
                "photos: the caption tells on the bomber")
            val resBomb = Photos.applyPhoto(sBomb, bombRec)
            check(sBomb.photographed["Randy"] == 1 && resBomb.gained == 6,
                "photos: the bomber counts as photographed, at half pay")
            check("bombed" in resBomb.newFeats,
                "photos: getting bombed completes the bombed feat")
        }

        // ---- apply: followers, milestones, re-photo trickle ----
        val sA = engP.newState()
        sA.todayKey = "20261013"
        sA.friendship["Stan"] = 100
        val recA = Photos.compose(sA, listOf("Stan"), emptyList(),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        val resA = Photos.applyPhoto(sA, recA)
        check(resA.gained == 24 && sA.followers == 24 && recA.followersGained == 24,
            "photos: the first close-friend shot pays out in full")
        check(resA.milestone == 10,
            "photos: the 10-follower milestone fires on the way to 24")
        check(sA.photographed["Stan"] == 1 && sA.photos.size == 1,
            "photos: the tally and the album both record the shot")
        val resA2 = Photos.applyPhoto(sA, Photos.compose(sA, listOf("Stan"),
            emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE))
        check(resA2.gained == Photos.REPHOTO_GAIN && sA.followers == 25 &&
            resA2.milestone == 25,
            "photos: a re-photo trickles +1 — and lands exactly on the 25 badge")
        check(sA.agents[PLAYER_DEFAULT_NAME]!!.memories.any { it.contains("📸") },
            "photos: the shot leaves a memory trace")

        // ---- hat swaps pair up among goofy friends ----
        val sS = engP.newState()
        sS.todayKey = "20261013"
        for (n in listOf("Stan", "Kyle", "Kenny", "Butters")) sS.friendship[n] = 100
        var swapRec: PhotoRecord? = null
        for (t in 480..1439) {
            // step 1 on purpose: the pose draw is (hash + seed) mod 3
            // and the seed moves 131/min — coarser steps can land on
            // the same residue forever
            sS.timeMin = t
            val r = Photos.compose(sS, listOf("Stan", "Kyle", "Kenny", "Butters"),
                emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            if (r.figures.any { it.pose == "swap" }) { swapRec = r; break }
        }
        check(swapRec != null, "photos: hat swaps occur for close-friend crowds")
        if (swapRec != null) {
            val swappers = swapRec.figures.filter { it.pose == "swap" }
            check(swappers.size % 2 == 0 && swappers.all { s ->
                swappers.any { it.name == s.swapWith && it.swapWith == s.name }
            }, "photos: swaps are mutual pairs, never one-way")
            check(swappers.all { it.reaction == Photos.GOOFY },
                "photos: only goofy friends swap hats")
            check(swapRec.figures.filter { it.pose == "tongue" }
                .all { it.mood == "goofy" } &&
                swapRec.figures.filter { it.pose == "bunny" }
                    .all { it.mood == "happy" },
                "photos: stored moods match stored poses")
        }

        // ---- album cap: newest survive, oldest fade ----
        val sC = engP.newState()
        sC.todayKey = "20261013"
        val capIds = mutableListOf<String>()
        repeat(Photos.ALBUM_CAP + 5) {
            val r = Photos.compose(sC, emptyList(), emptyList(),
                PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            Photos.applyPhoto(sC, r)
            capIds.add(r.id)
        }
        check(sC.photos.size == Photos.ALBUM_CAP,
            "photos: the album caps at ${Photos.ALBUM_CAP}")
        check(sC.photos.first().id == capIds[5] && sC.photos.last().id == capIds.last(),
            "photos: the cap fades the OLDEST photos first")
        check((sC.life["selfies"] ?: 0) == Photos.ALBUM_CAP + 5,
            "photos: the lifetime counter outlives the cap")

        // ---- goal tie-in: a PHOTO goal completes on shutter ----
        var holder: String? = null
        var holderCycle = -1
        for (c in 0..5) for (n in KID_ORDER) {
            if (holder == null && NpcGoals.goalFor(n, c).kind == "PHOTO") {
                holder = n; holderCycle = c
            }
        }
        check(holder != null, "photos: PHOTO goals occur in the goal deck")
        if (holder != null) {
            val sPh = engP.newState()
            sPh.todayKey = listOf("20261001", "20261003", "20261005",
                "20261007", "20261009", "20261011")[holderCycle]
            val gPh = NpcGoals.record(sPh, holder)
            check(gPh.kind == "PHOTO" && !gPh.done,
                "photos: the PHOTO goal is live in its cycle")
            check(NpcGoals.mention(gPh).isNotBlank(),
                "photos: a PHOTO goal has a spoken mention")
            val otherName = KID_ORDER.first {
                it != holder && NpcGoals.goalFor(it, holderCycle).kind != "PHOTO"
            }
            check(!NpcGoals.photoTick(sPh, otherName),
                "photos: a shutter does nothing for non-photo goals")
            check(!gPh.done, "photos: someone else's shutter settles nothing")
            sPh.friendship[holder] = 50   // pose happily for the shot
            val recPh = Photos.compose(sPh, listOf(holder), emptyList(),
                PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            val resPh = Photos.applyPhoto(sPh, recPh)
            check(holder in resPh.goalsDone && gPh.done,
                "photos: being photographed completes the PHOTO goal")
        }

        // ---- participation: once per event, at the cluster ----
        var evState: GameState? = null
        var evCluster: String? = null
        for (def in SHENANIGANS) {
            if (evState != null) break
            for (t in 0..1439 step 15) {
                val cl = Shenanigans.stageOf(def, t).clusterLoc
                if (cl != null) {
                    val s = engP.newState()
                    s.todayKey = "20261013"
                    s.shenaniganId = def.id
                    s.shenaniganDay = s.todayKey
                    s.timeMin = t
                    evState = s; evCluster = cl
                    break
                }
            }
        }
        check(evState != null && evCluster != null,
            "photos: a clustered event stage exists to shoot at")
        if (evState != null && evCluster != null) {
            check(Photos.noteSelfieParticipation(evState, evCluster),
                "photos: the first selfie at the cluster counts")
            check(evState.participation == 1,
                "photos: participation moved by exactly one")
            check(!Photos.noteSelfieParticipation(evState, evCluster),
                "photos: the second selfie in the same event does NOT recount")
            check(evState.participation == 1,
                "photos: participation stays at one")
            val sOff = engP.newState()
            sOff.todayKey = "20261013"
            sOff.shenaniganId = evState.shenaniganId
            sOff.shenaniganDay = sOff.todayKey
            sOff.timeMin = evState.timeMin
            val offLoc = LOCATIONS.keys.first { it != evCluster }
            check(!Photos.noteSelfieParticipation(sOff, offLoc) &&
                sOff.participation == 0,
                "photos: a selfie away from the cluster scores nothing")
            val sCalm = engP.newState()
            check(!Photos.noteSelfieParticipation(sCalm, evCluster),
                "photos: no event, no participation")
        }

        // ---- feats: squad/pair/full-house/holiday/night ----
        val sF = engP.newState()
        sF.todayKey = "20261013"
        for (n in Photos.SQUAD) sF.friendship[n] = 100
        val recSquad = Photos.compose(sF, Photos.SQUAD, emptyList(),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        check(recSquad.caption.contains("say 'cheese'"),
            "photos: a goofy crowd earns the cheese line")
        val resF = Photos.applyPhoto(sF, recSquad)
        check("squad_shot" in resF.newFeats && "pair_shot" in resF.newFeats,
            "photos: the squad shot completes squad + pair feats")
        check("squad_shot" in sF.photoFeats,
            "photos: completed feats persist on the state")
        val resF2 = Photos.applyPhoto(sF, Photos.compose(sF, Photos.SQUAD,
            emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE))
        check(resF2.newFeats.isEmpty(), "photos: feats never re-complete")
        val crowdNames = KID_ORDER.take(7)
        val sH = engP.newState()
        sH.todayKey = "20261013"
        for (n in crowdNames) sH.friendship[n] = 50
        val recCrowd = Photos.compose(sH, crowdNames, emptyList(),
            PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        check(Photos.featMet(sH, recCrowd, "full_house"),
            "photos: 7 townsfolk in frame is a full house")
        check(!Photos.featMet(sH, recSquad, "full_house"),
            "photos: 4 is not a full house")
        check(Photos.featMet(sH, recCrowd.copy(timeMin = 22 * 60), "night_owl") &&
            !Photos.featMet(sH, recCrowd.copy(timeMin = 12 * 60), "night_owl"),
            "photos: night owl reads the clock on the record")
        sH.holidayId = HOLIDAYS.first().id
        check(Photos.featMet(sH, recCrowd, "holiday_shot"),
            "photos: a shot during a holiday is a holiday shot")
        check(Photos.PHOTO_FEATS.size == 13 &&
            Photos.PHOTO_FEATS.map { it.id }.distinct().size == 13,
            "photos: thirteen feats, unique ids (6 classic + 4 group, v0.4.0c; " +
                "+ 3 commission, v0.6.0a)")

        // ---- save/load through the real decoder ----
        val docP = mapOf<String, Any?>(
            "photos" to listOf(recR.toMap()),
            "followers" to 42L,
            "photographed" to mapOf("Stan" to 3L),
            "photoFeats" to listOf("bombed"))
        val sLoaded = decodeGameState(docP)
        check(sLoaded.photos.size == 1 && sLoaded.photos[0] == recR,
            "photos: the album loads back intact")
        check(sLoaded.followers == 42 && sLoaded.photographed["Stan"] == 3 &&
            "bombed" in sLoaded.photoFeats,
            "photos: follower state loads back")
        val sEra = decodeGameState(emptyMap())
        check(sEra.photos.isEmpty() && sEra.followers == 0 &&
            sEra.photographed.isEmpty() && sEra.photoFeats.isEmpty(),
            "photos: old saves (no photo keys) load as a fresh album")

        // ---- wiring + the no-files rule ----
        val photosSrc = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
        check(!photosSrc.contains("import android"),
            "photos: Photos logic is pure Kotlin")
        val gaSrcP = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gaSrcP.contains("📸 Selfie") && gaSrcP.contains("onSelfie"),
            "photos: the Selfie button rides the bottom bar")
        check(gaSrcP.contains("Photos.compose") && gaSrcP.contains("Photos.applyPhoto"),
            "photos: GameActivity shoots through Photos")
        check(gaSrcP.contains("SoundEngine.shutter()"),
            "photos: the shutter sounds on the shot")
        check(gaSrcP.contains("generatedHere()"),
            "photos: selfie presence = the renderer's presence")
        val jSrcP = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(jSrcP.contains("📸 ALBUM") && jSrcP.contains("PhotoView"),
            "photos: the Journal carries the album")
        val colSrcP = File(root, "src/com/hunt3r/southparktown/CollectionActivity.kt").readText()
        check(colSrcP.contains("PHOTO FEATS") && colSrcP.contains("Photos.PHOTO_FEATS"),
            "photos: feats live on the Collection screen")
        val kidSrcP = File(root, "src/com/hunt3r/southparktown/KidArt.kt").readText()
        check(kidSrcP.contains("\"goofy\""),
            "photos: the tongue-out selfie face lives in the expression system")
        val pvSrcP = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
        check(pvSrcP.contains("PaperDoll.drawDoll") && pvSrcP.contains("avatarSpec"),
            "photos: the album re-renders with the game's own figure pipeline " +
                "(v0.16.0d: routed through the PaperDoll stills path — " +
                "the same renderer under doll rules)")
        val prefsSrcP = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
        check(prefsSrcP.contains("\"photos\" to state.photos.map") &&
            prefsSrcP.contains("\"followers\" to state.followers"),
            "photos: the album persists under additive keys")
        val imgExts = setOf("png", "jpg", "jpeg", "gif", "webp")
        val imgFiles = listOf(File(root, "assets"), File(root, "res"))
            .flatMap { it.walkTopDown().toList() }
            .filter { it.isFile && it.extension.lowercase() in imgExts }
        check(imgFiles.all { it.name == "ic_launcher.png" || it.name == "title_logo.png" },
            "photos: no image files added beyond the launcher icon and " +
                "the approved title art (v0.15.0e supersedes this pin: " +
                "the title logo ships as a bundled asset)")
    }

    // ================= v0.2.0d: writing depth pass #2 =================
    println("== v0.2.0d: voice banks, pair scripts, speech rules, topics, threads, ambient pools ==")
    run {
        val castNames = CharacterSystem.CAST.keys

        // ---- voice banks: every cast member doubled (4 -> 9) ----
        check(LINE_BANKS.keys == castNames,
            "writing: LINE_BANKS covers exactly the 62 cast")
        for (n in castNames) {
            val bank = LINE_BANKS[n] ?: emptyList()
            check(bank.size >= 8, "writing: $n's line bank doubled (got ${bank.size}, floor 8)")
            check(bank.size == 9, "writing: $n's line bank is exactly 9 (4 base + 5 new)")
            check(bank.distinct().size == bank.size,
                "writing: no duplicate lines inside $n's bank")
            check(bank.all { it.isNotBlank() }, "writing: $n's bank has no blanks")
        }
        check(LINE_BANKS.values.sumOf { it.size } == 882,
            "writing: 882 collision lines town-wide (98 x 9)")
        check((LINE_BANKS["Kenny"] ?: emptyList()).all { it.startsWith("(muffled)") },
            "writing: every Kenny bank line stays muffled")

        // ---- pair scripts: pinned coverage, >= 2 each ----
        val expectedPairs: Set<Set<String>> = setOf(
            setOf("Cartman", "Kyle"), setOf("Cartman", "Butters"),
            setOf("Stan", "Kyle"), setOf("Cartman", "Stan"),
            setOf("Kyle", "Butters"), setOf("Stan", "Butters"),
            setOf("Stan", "Wendy"), setOf("Craig", "Tweek"),
            setOf("Wendy", "Bebe"), setOf("Jimmy", "Timmy"),
            setOf("Randy", "Sharon"), setOf("Gerald", "Sheila"),
            setOf("Stan", "Randy"), setOf("Kyle", "Sheila"),
            setOf("Butters", "Stephen"), setOf("Cartman", "Kenny"),
            setOf("Stan", "Kenny"), setOf("Kyle", "Kenny"),
            setOf("Cartman", "Wendy"), setOf("Garrison", "Mackey"),
            setOf("Randy", "Towelie"), setOf("Jesus", "Father Maxi"),
            setOf("Craig", "Clyde"), setOf("Michael", "Pete"),
            setOf("Randy", "Gerald"), setOf("Jimbo", "Stuart"),
            setOf("Tolkien", "Craig"), setOf("Stuart", "Carol"),
            // v0.3.0b wave 2: the new bonds get scripts too
            setOf("Mr. Tweek", "Mrs. Tweek"), setOf("Mr. Tweek", "Tweek"),
            setOf("Mrs. Tweek", "Tweek"), setOf("Jimbo", "Ned"),
            setOf("Heidi", "Cartman"), setOf("McDaniels", "Barbrady"),
            setOf("Nichole", "Tolkien"),
            // v0.7.0a wave 3: the new bonds get scripts too
            setOf("Karen", "Kenny"), setOf("Karen", "Carol"),
            setOf("Scott", "Butters"), setOf("Firkle", "Michael"),
            setOf("Bradley", "Henrietta"), setOf("Annie", "Wendy"),
            setOf("Skeeter", "Stuart"), setOf("Victoria", "Garrison"),
            setOf("Marvin", "Randy"), setOf("Mr. Tucker", "Craig"),
            setOf("Steve", "Tolkien"),
            // v0.8.0a wave 4: the new bonds get scripts too
            setOf("Ike", "Kyle"), setOf("Ike", "Sheila"),
            setOf("Kevin McCormick", "Kenny"), setOf("Kevin McCormick", "Karen"),
            setOf("Shelley", "Stan"), setOf("Shelley", "Randy"),
            setOf("Laura", "Mr. Tucker"), setOf("Laura", "Craig"),
            setOf("Mephesto", "Chef"), setOf("Yates", "Barbrady"),
            setOf("Adler", "Garrison"), setOf("Lu Kim", "Mr. Tweek"),
            // v0.9.0a wave 5: the new bonds get scripts too
            setOf("Roger", "Clyde"), setOf("Ryan", "Jimmy"),
            setOf("Sarah", "Jimmy"), setOf("Ryan", "Sarah"),
            setOf("Alexis", "Wendy"), setOf("Mr. Testaburger", "Wendy"),
            setOf("Alexis", "Mr. Testaburger"), setOf("Nathan", "Jimmy"),
            setOf("Nathan", "Timmy"), setOf("Sophie", "Scott"),
            setOf("Sophie", "Wendy"), setOf("Big Gay Al", "Chef"),
            setOf("Roger", "Stephen"),
            // wave 6 (v0.11.0d): the audit's forty-one pairs
            setOf("Pip", "Butters"), setOf("Pip", "Dougie"),
            setOf("Dougie", "Butters"), setOf("Jason", "Craig"),
            setOf("Terrance Mephesto", "Mephesto"),
            setOf("Terrance Mephesto", "Stan"),
            setOf("Terrance Mephesto", "Nathan"),
            setOf("Jenny", "Wendy"), setOf("Jenny", "Bebe"),
            setOf("Flora", "Ike"), setOf("Filmore", "Ike"),
            setOf("Quaid", "Filmore"), setOf("Mimsy", "Nathan"),
            setOf("Mimsy", "Jimmy"), setOf("Tricia", "Craig"),
            setOf("Tricia", "Laura"), setOf("Mr. Slave", "Big Gay Al"),
            setOf("Mr. Slave", "Garrison"), setOf("Linda Black", "Steve"),
            setOf("Linda Black", "Tolkien"), setOf("Harriet", "Henrietta"),
            setOf("Harriet", "Mr. Biggle"), setOf("Mr. Biggle", "Bradley"),
            setOf("Mr. Turner", "Heidi"), setOf("Nancy", "Heidi"),
            setOf("Mr. Stevens", "Bebe"), setOf("Mrs. Stevens", "Bebe"),
            setOf("Mr. Stoley", "Kevin"), setOf("Mrs. Stoley", "Kevin"),
            setOf("Mr. Stoley", "Mrs. Stoley"), setOf("Clark", "Scott"),
            setOf("Maggie", "Yates"), setOf("Mitch", "Yates"),
            setOf("Mitch", "Barbrady"), setOf("Bob Johnson", "McDaniels"),
            setOf("Pusslicker", "Jimmy"), setOf("Dr. Doctor", "Randy"),
            setOf("Choksondik", "Garrison"), setOf("Choksondik", "Stan"),
            setOf("Strong Woman", "Victoria"),
            setOf("Strong Woman", "Mackey"))
        check(PAIR_SCRIPTS.keys == expectedPairs,
            "writing: pair-script coverage is exactly the pinned 112 pairs")
        for ((pair, scripts) in PAIR_SCRIPTS) {
            check(scripts.size >= 2,
                "writing: $pair has >= 2 scripts (got ${scripts.size})")
            for (script in scripts) {
                check(script.size >= 2, "writing: a $pair script has at least 2 beats")
                check(script.all { (who, line) -> who in pair && line.isNotBlank() },
                    "writing: $pair script lines are spoken by the pair, non-blank")
            }
        }
        check(PAIR_SCRIPTS.values.sumOf { it.size } == 226,
            "writing: 226 pair scripts total (10 base + 47 wave-1 + 14 wave-2 + 22 wave-3 + 25 wave-4 + 26 wave-5 + 82 wave-6)")
        // every scripted pair is also a relations pair or core-group kin
        check(expectedPairs.all { relationNote(it.first(), it.last()) != null ||
            setOf("Stan", "Kyle", "Cartman", "Kenny", "Butters").containsAll(it) },
            "writing: scripted pairs are lore relations or core-group")

        // ---- speech rules: the full cast, compact + distinct ----
        check(SPEECH_RULES.keys == castNames,
            "writing: SPEECH_RULES covers exactly the 70 cast")
        for ((n, rule) in SPEECH_RULES) {
            check(rule.length in 80..420,
                "writing: $n's speech rule is compact (${rule.length} chars)")
            check(rule.contains("Tics:") && rule.contains("Never") && rule.contains("Deflects"),
                "writing: $n's speech rule carries tics / never / deflects")
        }
        check(SPEECH_RULES.values.distinct().size == 98,
            "writing: every speech rule is distinct")

        // ---- speech rules ride BOTH prompt builders ----
        val engD = Engine(20240)
        val sD = engD.newState()
        val stan = sD.agents["Stan"]!!
        val kyle = sD.agents["Kyle"]!!
        val cartman = sD.agents["Cartman"]!!
        val colPrompt = engD.buildCollisionPrompt(stan, kyle, "Main Street",
            "10:00 AM", "Snowy.", "", sD)
        check(colPrompt.contains("VOICE — Stan:") && colPrompt.contains("VOICE — Kyle:"),
            "writing: the collision prompt carries both speakers' voice cards")
        check(colPrompt.contains(SPEECH_RULES["Stan"]!!.take(40)),
            "writing: the collision prompt embeds Stan's actual rule text")
        val playPrompt = engD.buildPlayerPrompt(sD, listOf(cartman, stan),
            "hi guys", "Main Street", "10:00 AM", "Snowy.")
        check(playPrompt.contains("VOICE — Cartman:") && playPrompt.contains("VOICE — Stan:"),
            "writing: the player prompt carries a voice card per present cast member")
        val engSrcD = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engSrcD.contains("speechRulesBlock(listOf(a1.name, a2.name))") &&
            engSrcD.contains("speechRulesBlock(present.map { it.name })"),
            "writing: both prompt builders splice speechRulesBlock (source)")

        // ---- daily topics grew: core 28, everyone else 18 ----
        check(DAILY_TOPICS.keys == castNames,
            "writing: DAILY_TOPICS covers exactly the 62 cast")
        for (n in listOf("Cartman", "Stan", "Kyle", "Kenny", "Butters")) {
            val t = DAILY_TOPICS[n] ?: emptyList()
            check(t.size == 28, "writing: core kid $n has 28 daily topics (got ${t.size})")
        }
        for (n in castNames) {
            val t = DAILY_TOPICS[n] ?: emptyList()
            check(t.size >= 18, "writing: $n has >= 18 daily topics (got ${t.size})")
            check(t.distinct().size == t.size,
                "writing: no duplicate topics inside $n's pool")
        }
        check(DAILY_TOPICS.values.sumOf { it.size } == 1814,
            "writing: 1814 daily topics town-wide (5x28 + 93x18)")

        // ---- freshness ring: no back-to-back repeats ----
        val engF = Engine(777)
        val stanBank = LINE_BANKS["Stan"]!!
        val picks = (1..14).map { engF.freshLine("Stan", stanBank, kotlin.random.Random(it * 31L)) }
        check(picks.all { it in stanBank }, "writing: freshLine only returns bank lines")
        for (i in 3 until picks.size) {
            check(picks[i] !in picks.subList(i - 3, i),
                "writing: pick $i doesn't repeat any of the previous 3 lines")
        }
        check(engF.freshLine("Nobody", emptyList()) == "...",
            "writing: an empty bank degrades to an ellipsis")
        check(engF.freshLine("Tiny", listOf("a", "b")) in listOf("a", "b"),
            "writing: a tiny bank still returns a member")
        check(engSrcD.contains("heardRing") && engSrcD.contains("fun freshLine"),
            "writing: the freshness ring lives in Engine (in-memory only)")

        // ---- threads: new topic classes classify + follow up ----
        check(NpcMemoryStore.topicOf("my puppy chewed the squeaky toy") == "pets & critters",
            "writing: puppy talk classifies as pets & critters")
        check(NpcMemoryStore.topicOf("the wifi died and the router is laughing at me") == "tech & gadgets",
            "writing: wifi talk classifies as tech & gadgets")
        check(NpcMemoryStore.topicOf("my sweetheart sent me a note") == "crushes & drama",
            "writing: sweetheart talk classifies as crushes & drama")
        check(NpcMemoryStore.topicOf("my teacher assigned homework") == "school",
            "writing: the original classes keep priority over the new ones")
        val allTags = listOf("school", "food", "money", "weather", "music", "games",
            "family", "gross stuff", "secrets", "aliens & weird stuff",
            "crushes & drama", "pets & critters", "tech & gadgets")
        for (tag in allTags) {
            val mem = NpcMemory(meets = 2, topics = mutableListOf(tag))
            val fu = Threads.followUp(mem, kotlin.random.Random(42))
            check(fu != null && fu.contains(tag),
                "writing: a follow-up exists for the '$tag' thread class")
        }
        val cbMem = NpcMemory(meets = 3, topics = mutableListOf("food", "money"))
        check(Threads.callback(cbMem, kotlin.random.Random(7)) != null,
            "writing: callbacks still fire on stored topics")
        check(Threads.PAIR_JOKES.size >= 12,
            "writing: the pair-joke bank grew to ${Threads.PAIR_JOKES.size}")

        // ---- generated NPC ambient pools separate by kind ----
        val farmerPool = NpcGenerator.ambientPoolFor("farmer", listOf("cheerful"), false)
        val singerPool = NpcGenerator.ambientPoolFor("singer", listOf("grumpy"), false)
        check(farmerPool.size >= 5 && singerPool.size >= 5,
            "writing: role+trait ambient pools are meaty (${farmerPool.size}/${singerPool.size})")
        check(farmerPool.intersect(singerPool.toSet()).isEmpty(),
            "writing: a farmer and a singer share ZERO ambient lines")
        val gothPool = NpcGenerator.ambientPoolFor(null, emptyList(), true)
        check(gothPool.any { "goth" in it.lowercase() },
            "writing: the goth set actually talks goth")
        check(NpcGenerator.ambientPoolFor(null, emptyList(), false).isNotEmpty(),
            "writing: a kind-less NPC still gets the neutral pool")
        check(NpcGenerator.ambientPoolFor("police officer", emptyList(), false) ==
            NpcGenerator.ambientPoolFor("officer", emptyList(), false),
            "writing: role aliases resolve to the same pool")
        // end-to-end through real persona generation
        val farmerPersona = NpcGenerator.generate(LoreEntry("Test Farmer", "characters",
            "Test Farmer is a cheerful farmer who grows corn outside town. He is kind " +
            "to his animals and talks to the rows like coworkers every single morning.",
            listOf("farmer")))
        val gothPersona = NpcGenerator.generate(LoreEntry("Test Goth", "characters",
            "Test Goth is a singer and a devoted goth who performs sad songs at the " +
            "cafe. She is quiet and honest about absolutely everything in her life.",
            listOf("goth", "singer")))
        check(farmerPersona.role == "farmer" && farmerPersona.ambientLines.isNotEmpty(),
            "writing: the generated farmer carries an ambient pool")
        check(gothPersona.ambientLines.any { "goth" in it.lowercase() },
            "writing: the generated goth sounds like a goth")
        check(farmerPersona.ambientLines.intersect(gothPersona.ambientLines.toSet()).isEmpty(),
            "writing: generated farmer vs generated goth — disjoint ambient voices")
        val gaSrcD = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gaSrcD.contains("persona.ambientLines"),
            "writing: visitor replies draw from the ambient pool (source)")
        val genSrcD = File(root, "src/com/hunt3r/southparktown/NpcGen.kt").readText()
        check(genSrcD.contains("fun ambientPoolFor") && genSrcD.contains("ROLE_AMBIENT"),
            "writing: ambient templates live in NpcGen (source)")
    }

    // ================= v0.2.0e: minigames =================
    // Three games on one scaffold: pure seeded sessions
    // (Minigames.kt), rewards settled once through the
    // inventory/friendship systems, records in the Journal.
    println("== v0.2.0e: minigames ==")
    run {
        val engE = Engine()

        // ---------- 🎣 fishing: the bite math ----------
        check(biteFactor("sunny", 6) < biteFactor("sunny", 12),
            "fishing: dawn out-bites midday")
        check(biteFactor("sunny", 18) < biteFactor("sunny", 12),
            "fishing: dusk out-bites midday")
        check(biteFactor("blizzard", 6) > biteFactor("heavy_snow", 6) &&
            biteFactor("heavy_snow", 6) > biteFactor("light_snow", 6),
            "fishing: the worse the snow, the longer the wait")
        check(biteFactor("rain", 12) < biteFactor("sunny", 12),
            "fishing: rain helps (every grandpa was right)")
        check(biteWindowMs("blizzard") < biteWindowMs("heavy_snow") &&
            biteWindowMs("heavy_snow") < biteWindowMs("sunny"),
            "fishing: storm windows are tighter")
        check(FISH_TABLE.sumOf { it.weight } == 100,
            "fishing: the catch table sums to 100")
        check(FISH_TABLE.count { it.joke } == 1 &&
            fishById("old_boot")!!.joke,
            "fishing: exactly one joke catch, and it is the boot")
        check(FISH_TABLE.count { it.rare } == 3,
            "fishing: three rares (rainbow, golden, three-eyed)")
        check(FISH_TABLE.all { itemById(it.itemId) != null },
            "fishing: every catch lands as a real item")

        // ---------- fishing: the session machine ----------
        val fa = FishingSession(42L, "sunny", 6)
        val fb = FishingSession(42L, "sunny", 6)
        check(fa.biteAtMs == fb.biteAtMs && fa.biteAtMs >= 800L,
            "fishing: same seed, same bite time (floored at 800ms)")
        val scaredS = FishingSession(7L, "sunny", 6)
        scaredS.tap(100L)
        check(scaredS.outcome == FishingSession.Outcome.SCARED &&
            scaredS.phase == FishingSession.Phase.OVER,
            "fishing: an early tap scares the fish and ends the cast")
        val waitS = FishingSession(7L, "sunny", 6)
        waitS.tick(waitS.biteAtMs - 1)
        check(waitS.phase == FishingSession.Phase.WAITING,
            "fishing: still waiting one ms before the bite")
        waitS.tick(waitS.biteAtMs)
        check(waitS.phase == FishingSession.Phase.BITE,
            "fishing: the bite lands exactly at biteAtMs")
        val hookS = FishingSession(7L, "sunny", 6)
        hookS.tap(hookS.biteAtMs)
        check(hookS.outcome == FishingSession.Outcome.CAUGHT &&
            hookS.species != null &&
            hookS.sizeCm in hookS.species!!.minCm..hookS.species!!.maxCm,
            "fishing: a tap at the dip hooks a sized fish")
        val hookS2 = FishingSession(7L, "sunny", 6)
        hookS2.tap(hookS2.biteAtMs)
        check(hookS2.species == hookS.species && hookS2.sizeCm == hookS.sizeCm,
            "fishing: same seed, same fish, same size")
        val edgeS = FishingSession(9L, "heavy_snow", 20)
        edgeS.tap(edgeS.biteEndMs)
        check(edgeS.outcome == FishingSession.Outcome.CAUGHT,
            "fishing: the window's last millisecond still hooks")
        val lateS = FishingSession(9L, "heavy_snow", 20)
        lateS.tick(lateS.biteEndMs + 1)
        check(lateS.outcome == FishingSession.Outcome.ESCAPED,
            "fishing: one ms past the window, it's gone")
        val slowS = FishingSession(9L, "heavy_snow", 20)
        slowS.tap(slowS.biteEndMs + 1)
        check(slowS.outcome == FishingSession.Outcome.ESCAPED,
            "fishing: a late tap finds only regret")

        // ---------- fishing: settle once, log, feats ----------
        val fishState = engE.newState()
        noteCast(fishState)
        check(fishState.fishCasts == 1, "fishing: casts are counted")
        val catchS = FishingSession(11L, "sunny", 6)
        catchS.tap(catchS.biteAtMs)
        val cr = applyCatch(fishState, catchS)
        check(cr != null && "first_cast" in cr.feats &&
            "first_cast" in fishState.gameFeats,
            "fishing: the first catch completes First Cast")
        check(fishState.fishLog[catchS.species!!.id]?.count == 1 &&
            fishState.fishLog[catchS.species!!.id]?.biggestCm == catchS.sizeCm &&
            (fishState.inventory[catchS.species!!.itemId] ?: 0) == 1,
            "fishing: the catch is logged AND in the pack")
        check(applyCatch(fishState, catchS) == null,
            "fishing: a catch settles exactly once")
        check(catchFeats(fishState, "golden_carp") == listOf("golden") &&
            catchFeats(fishState, "three_eyed_fish") == listOf("three_eyed"),
            "fishing: rare catches map to their feats")
        val carpItem = itemById("fish_carp")!!
        val (carpPts, carpLoved) = giftValue(carpItem, "Jimbo", emptyList())
        check(carpLoved && carpPts == carpItem.giftPoints * 2,
            "fishing: Jimbo loves the golden carp (gift value doubles)")
        val coinItem = itemById("capsule_coin")
        check(coinItem != null && coinItem.tier == "gift",
            "games: the capsule coin is an inventory item, not a currency")

        // ---------- ❄️ showdown: zones, dodges, windows ----------
        check(Showdown.zoneOf(0.44f) == "perfect" && Showdown.zoneOf(0.56f) == "perfect" &&
            Showdown.zoneOf(0.50f) == "perfect", "showdown: the perfect band, edges in")
        check(Showdown.zoneOf(0.43f) == "good" && Showdown.zoneOf(0.30f) == "good" &&
            Showdown.zoneOf(0.70f) == "good", "showdown: the good band")
        check(Showdown.zoneOf(0.29f) == "ok" && Showdown.zoneOf(0.15f) == "ok" &&
            Showdown.zoneOf(0.85f) == "ok", "showdown: the ok band")
        check(Showdown.zoneOf(0.14f) == "wild" && Showdown.zoneOf(0f) == "wild" &&
            Showdown.zoneOf(1f) == "wild", "showdown: edge releases are wild")
        check(Showdown.zonePower("perfect") > Showdown.zonePower("good") &&
            Showdown.zonePower("good") > Showdown.zonePower("ok") &&
            Showdown.zonePower("ok") > Showdown.zonePower("wild"),
            "showdown: zone power descends perfect → wild")
        check(Showdown.dodgeFor("Butters") < Showdown.dodgeFor("Cartman") &&
            Showdown.dodgeFor("Cartman") < Showdown.dodgeFor("Tweek"),
            "showdown: Butters is a barn, Tweek is a ghost")
        check(Showdown.dodgeWindowMs(1, "Stan") > Showdown.dodgeWindowMs(3, "Stan"),
            "showdown: dodge windows shrink as rounds wear on")
        check(Showdown.dodgeWindowMs(1, "Tweek") < Showdown.dodgeWindowMs(1, "Butters"),
            "showdown: quick kids throw harder to dodge")
        check((1..6).all { Showdown.dodgeWindowMs(it, "Craig") in 380L..700L },
            "showdown: windows stay inside their clamps")

        // dodge edges against a live duel
        val wStart = Showdown.dodgeWindowStart(1, "Stan")
        val dd1 = ShowdownDuel(5L, "Stan")
        check(dd1.resolveDodge(wStart),
            "showdown: a tap at the window's first ms dodges (inclusive)")
        check(dd1.youHits == 0, "showdown: a dodge costs nothing")
        val dd2 = ShowdownDuel(5L, "Stan")
        check(!dd2.resolveDodge(wStart - 1) && dd2.youHits == 1,
            "showdown: one ms early is a flinch — and a hit taken")
        val dd3 = ShowdownDuel(5L, "Stan")
        check(dd3.resolveDodge(Showdown.FLIGHT_MS),
            "showdown: a tap at the flight's last ms still dodges")
        val dd4 = ShowdownDuel(5L, "Stan")
        check(!dd4.resolveDodge(null) && dd4.youHits == 1,
            "showdown: standing there is not a dodge")

        // a scripted duel replays identically and ends at 3
        fun scriptDuel(seed: Long, opp: String): ShowdownDuel {
            val d = ShowdownDuel(seed, opp)
            var guard = 0
            while (!d.over && guard++ < 300) {
                d.resolveThrow(0.5f)
                if (!d.over) {
                    val st = Showdown.dodgeWindowStart(d.round, opp)
                    d.resolveDodge((st + Showdown.FLIGHT_MS) / 2)
                }
            }
            return d
        }
        val duelA = scriptDuel(99L, "Stan")
        val duelB = scriptDuel(99L, "Stan")
        check(duelA.over && duelB.over,
            "showdown: scripted duels terminate")
        check(duelA.youHits == duelB.youHits && duelA.oppHits == duelB.oppHits,
            "showdown: same seed + same script = same duel")
        check(if (duelA.youWon) duelA.oppHits == Showdown.HITS_TO_WIN
            else duelA.youHits == Showdown.HITS_TO_WIN,
            "showdown: the duel ends the moment somebody reaches 3")

        // feats: find a scripted shutout vs Cartman, verify both feats
        var shutoutDuel: ShowdownDuel? = null
        for (sd in 0L..600L) {
            val d = scriptDuel(sd, "Cartman")
            if (d.youWon && d.youHits == 0) { shutoutDuel = d; break }
        }
        check(shutoutDuel != null,
            "showdown: optimal script play CAN shut Cartman out")
        val featState = engE.newState()
        check(showdownFeats(featState, shutoutDuel ?: scriptDuel(0L, "Stan"))
            .containsAll(listOf("shutout", "sore_loser")),
            "showdown: a 3–0 over Cartman completes both duel feats")

        // settle: record, coins, friendship, once-only
        val duelState = engE.newState()
        val finDuel = scriptDuel(99L, "Stan")
        val coinsBefore = Minigames.capsuleCoins(duelState)
        val friendBefore = duelState.friendship["Stan"] ?: 0
        val sr = applyShowdownResult(duelState, finDuel)
        check(sr != null, "showdown: a finished duel settles")
        check(Minigames.capsuleCoins(duelState) - coinsBefore ==
            if (finDuel.youWon) 5 else 1,
            "showdown: winners take 5 coins, losers take 1 for showing up")
        check((duelState.showdown["Stan"]?.wins ?: 0) +
            (duelState.showdown["Stan"]?.losses ?: 0) == 1,
            "showdown: the W/L record files the duel")
        check((duelState.friendship["Stan"] ?: 0) - friendBefore ==
            if (finDuel.youWon) 3 else 1,
            "showdown: friendship swings through the town's own pipe")
        check(applyShowdownResult(duelState, finDuel) == null,
            "showdown: a duel pays out exactly once")
        check(applyShowdownResult(duelState, ShowdownDuel(1L, "Stan")) == null,
            "showdown: an unfinished duel pays nothing")
        // Cartman's swing runs backwards, win or lose
        val cmState = engE.newState()
        cmState.friendship["Cartman"] = 50
        val cmDuel = scriptDuel(7L, "Cartman")
        applyShowdownResult(cmState, cmDuel)
        check((cmState.friendship["Cartman"] ?: 0) == 48,
            "showdown: Cartman friendship drops either way (−2, sore everything)")
        // the lines: Kenny muffled, Cartman litigious
        check(showdownLine("Kenny", true, "Lucky").contains("Mmph") &&
            showdownLine("Kenny", false, "Lucky").contains("MMPH"),
            "showdown: Kenny's lines come through the parka")
        check(showdownLine("Cartman", true, "Lucky").contains("cheated"),
            "showdown: beat Cartman and he accuses you of cheating")
        check(showdownLine("Cartman", false, "Lucky").contains("Lucky"),
            "showdown: lose to Cartman and he gloats BY NAME")

        // ---------- 🌮 taco catch: schedule, scoring, tiers ----------
        val tc1 = TacoCatchSession(3L)
        val tc2 = TacoCatchSession(3L)
        check(tc1.spawns == tc2.spawns,
            "taco: same seed, same rain of food")
        check(tc1.spawns.zipWithNext().all { (a, b) -> b.atMs > a.atMs } &&
            tc1.spawns.all { it.atMs in 0 until TacoCatchSession.DURATION_MS &&
                it.x01 in 0f..1f && it.fallMs in 1200L..3200L },
            "taco: spawns sorted, inside the minute, on the field")
        check(tc1.spawns.size in 55..130,
            "taco: a full minute of falling food (${tc1.spawns.size} items)")
        check(tc1.spawns.any { it.kind == "taco" } &&
            tc1.spawns.any { s -> tc1.isHazard(s.kind) },
            "taco: the menu includes food AND consequences")
        check(tc1.pointsFor("taco") == 10 && tc1.pointsFor("burrito") == 15 &&
            tc1.pointsFor("berry") == -15 && tc1.pointsFor("tv") == -25,
            "taco: the points table")
        val tcScore = TacoCatchSession(4L)
        check(tcScore.onCatch("taco", 1000L) == 10 && tcScore.score == 10,
            "taco: a caught taco pays 10")
        check(tcScore.onCatch("tv", 2000L) == -10 && tcScore.score == 0,
            "taco: a TV costs 25 but the score floors at zero")
        check(tcScore.stunnedAt(2949L) && !tcScore.stunnedAt(2951L) &&
            tcScore.hazardsHit == 1,
            "taco: a TV stuns the tray for ~950ms")
        val missedBefore = tcScore.missed
        tcScore.onGround("taco")
        check(tcScore.missed == missedBefore + 1, "taco: dropped food is a miss")
        tcScore.onGround("tv")
        check(tcScore.missed == missedBefore + 1,
            "taco: a TV hitting the floor is called dodging")
        check(TacoCatch.coinsForScore(600) == 12 && TacoCatch.coinsForScore(599) == 9 &&
            TacoCatch.coinsForScore(450) == 9 && TacoCatch.coinsForScore(449) == 6 &&
            TacoCatch.coinsForScore(300) == 6 && TacoCatch.coinsForScore(180) == 4 &&
            TacoCatch.coinsForScore(80) == 2 && TacoCatch.coinsForScore(79) == 1 &&
            TacoCatch.coinsForScore(1) == 1 && TacoCatch.coinsForScore(0) == 0,
            "taco: every coin tier edge")
        val tacoState = engE.newState()
        val bigRun = TacoCatchSession(8L)
        repeat(50) { bigRun.onCatch("burrito", 1000L + it * 100L) }
        val tr = applyTacoResult(tacoState, bigRun)
        check(tr != null && tr.score == 750 && tr.coins == 12 && tr.newHigh &&
            tacoState.tacoHigh == 750 && tacoState.tacoPlays == 1 &&
            Minigames.capsuleCoins(tacoState) == 12,
            "taco: a 750 run pays top tier, files the high score, counts the play")
        check(applyTacoResult(tacoState, bigRun) == null,
            "taco: a run pays out exactly once")
        val titanState = engE.newState()
        check(tacoFeats(titanState, 500) == listOf("taco_500") &&
            tacoFeats(titanState, 499).isEmpty() &&
            "taco_500" in tacoState.gameFeats,
            "taco: Taco Titan completes at exactly 500")

        // ---------- availability gating ----------
        val gate = engE.newState()
        val gMe = gate.agents[PLAYER_DEFAULT_NAME]!!
        val gStan = gate.agents["Stan"]!!
        gStan.waypoints.clear(); gStan.asleep = false
        gMe.location = "StarksPond"; gate.playerInside = false
        check(Minigames.fishingAvailable(gate), "gating: the pond fishes from the dock")
        gate.playerInside = true
        check(!Minigames.fishingAvailable(gate), "gating: not from inside the hut")
        gate.playerInside = false; gMe.location = "MainStreet"
        check(!Minigames.fishingAvailable(gate), "gating: Main Street has no pond")
        gMe.location = "KidsPark"; gStan.location = "KidsPark"
        gate.weatherId = "sunny"
        check(!Minigames.showdownAvailable(gate),
            "gating: no showdown without snow (the charm is the rule)")
        gate.weatherId = "light_snow"
        check(Minigames.showdownAvailable(gate) &&
            Minigames.showdownOpponents(gate).contains("Stan"),
            "gating: snow + a present kid = a duel")
        gStan.location = "MainStreet"
        check(!Minigames.showdownAvailable(gate),
            "gating: the kid has to actually be standing with you")
        gMe.location = "FreemansTacos"; gate.playerInside = true
        check(Minigames.tacoAvailable(gate), "gating: the cabinet is inside Freeman's")
        gate.playerInside = false
        check(!Minigames.tacoAvailable(gate), "gating: not from the sidewalk")

        // ---------- feats registry + coin helper ----------
        check(Minigames.GAME_FEATS.map { it.id }.distinct().size ==
            Minigames.GAME_FEATS.size && Minigames.GAME_FEATS.size == 7,
            "games: seven feats, unique ids (six through v0.6.0g, " +
                "v0.7.0d's bee champion)")
        val featS = engE.newState()
        check(Minigames.awardFeat(featS, "golden") && !Minigames.awardFeat(featS, "golden") &&
            featS.gameFeats.size == 1, "games: feats complete once")
        check(!Minigames.awardFeat(featS, "not_a_feat"),
            "games: unknown feats don't complete")
        val coinS = engE.newState()
        check(Minigames.awardCoins(coinS, 3) == 3 && Minigames.capsuleCoins(coinS) == 3 &&
            (coinS.inventory["capsule_coin"] ?: 0) == 3,
            "games: coins stack in the inventory as an item")

        // ---------- persistence: additive keys round-trip ----------
        val docG = mapOf<String, Any?>(
            "fishLog" to mapOf("golden_carp" to mapOf("count" to 2L, "biggest" to 51L)),
            "fishCasts" to 17L,
            "showdown" to mapOf("Kenny" to mapOf("wins" to 1L, "losses" to 2L)),
            "tacoHigh" to 321L, "tacoPlays" to 4L,
            "gameFeats" to listOf("golden"))
        val loadedG = decodeGameState(docG)
        check(loadedG.fishLog["golden_carp"] == FishRecord(2, 51) &&
            loadedG.fishCasts == 17,
            "games: the fishing log survives the save round-trip")
        check(loadedG.showdown["Kenny"] == ShowdownRecord(1, 2) &&
            loadedG.tacoHigh == 321 && loadedG.tacoPlays == 4 &&
            "golden" in loadedG.gameFeats,
            "games: showdown record, taco scores and feats survive")
        val eraG = decodeGameState(emptyMap())
        check(eraG.fishLog.isEmpty() && eraG.fishCasts == 0 &&
            eraG.showdown.isEmpty() && eraG.tacoHigh == 0 &&
            eraG.tacoPlays == 0 && eraG.gameFeats.isEmpty(),
            "games: old saves load with an empty games page")

        // ---------- wiring (source cross-checks) ----------
        val mgSrc = File(root, "src/com/hunt3r/southparktown/Minigames.kt").readText()
        check(!mgSrc.contains("import android"), "games: Minigames logic is pure Kotlin")
        val gaSrcE = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gaSrcE.contains("startFishing()") && gaSrcE.contains("startShowdown") &&
            gaSrcE.contains("startTacoCatch()"),
            "games: all three launchers wired in GameActivity")
        check(gaSrcE.contains("\"snowfort\" -> snowfortDialog()") &&
            gaSrcE.contains("\"arcade\" -> arcadeDialog()"),
            "games: the fort and the cabinet answer scene taps")
        val gvSrcE = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
        check(gvSrcE.contains("\"snowfort\"") && gvSrcE.contains("\"arcade\"") &&
            gvSrcE.contains("drawArcadeCabinet"),
            "games: the fort and cabinet are drawn in the world")
        val mvSrcE = File(root, "src/com/hunt3r/southparktown/MinigameViews.kt").readText()
        check(mvSrcE.contains("class FishingView") &&
            mvSrcE.contains("class ShowdownView") &&
            mvSrcE.contains("class TacoCatchView"),
            "games: three views, one per game")
        val jSrcE = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(jSrcE.contains("🎮 GAMES"),
            "games: the Journal keeps the 🎮 GAMES page")
        val prefsSrcE = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
        check(prefsSrcE.contains("\"fishLog\" to") && prefsSrcE.contains("\"tacoHigh\" to") &&
            prefsSrcE.contains("\"gameFeats\" to"),
            "games: the new records persist through Prefs")
        val sndSrcE = File(root, "src/com/hunt3r/southparktown/Sound.kt").readText()
        check(sndSrcE.contains("v020g_r1") && sndSrcE.contains("fun fishBite()") &&
            sndSrcE.contains("fun coinDing()") && sndSrcE.contains("fun tacoPop()"),
            "games: the new synth sounds are wired (cache stamp bumped)")
    }

    sectionMainMystery(root)

    sectionV020g(root)
    sectionV030a(root)
    sectionV030b(root)
    sectionV030c(root)
    sectionV030d(root)
    sectionV030e(root)
    sectionV030f(root)
    sectionV030g(root)
    sectionV040a(root)
