/** v0.2.0g section, extracted from main(): the suite's main
 *  hit the JVM 64 KB method limit at ~5,800 checks, so new
 *  sections live in their own functions from here on. */
private fun sectionV020g(root: String) {
// ================= v0.2.0g: polish & performance pass #2 =================
// Queue #2's final item. The long-session robustness audit
// (every save-state growth path capped or proven bounded,
// exercised through the REAL save path via encodeGameState),
// the audio peak budget, minigame feel centralization +
// first-entry how-tos, the newest screens' fit/contrast QA,
// a simulated 60-day fast-forward, and the flagged-gap
// fixes (SoundPool listener readiness, weather-shift bed
// refresh, pair-script freshness ring, lamp-key prune).
println("== v0.2.0g: robustness audit, peak budget, feel, fit QA, 60-day sim ==")
run {
    // ---------- the audio peak budget ----------
    val pb = SoundGen.PeakBudget
    println("peak budget: music ${pb.musicPeakOut()} + bed ${pb.ambiencePeakOut()} + " +
        "sfx ${pb.sfxPeakOut()} + blip ${pb.blipPeakOut()} -> named ${pb.namedStack()}, " +
        "double-sfx ${pb.doubleSfxStack()}")
    check(pb.namedStack() <= 1.0f,
        "budget: blip + sting + bed + tune peaks sum under full scale (got ${pb.namedStack()})")
    check(pb.doubleSfxStack() <= 1.0f,
        "budget: two one-shots over bed + tune stay under full scale (got ${pb.doubleSfxStack()})")
    check(pb.musicPeakOut() in 0.15f..0.26f,
        "budget: the tune keeps a real allocation (got ${pb.musicPeakOut()})")
    check(pb.ambiencePeakOut() in 0.08f..0.17f,
        "budget: the loudest bed keeps a real allocation (got ${pb.ambiencePeakOut()})")
    for (id in SoundGen.SFX_IDS) {
        check(pb.peakOf(SoundGen.renderSfx(id)) <= pb.SFX_CEILING + 0.001f,
            "budget: $id renders under the SFX ceiling")
    }
    for (fam in SoundGen.BlipFam.values()) {
        check(pb.peakOf(SoundGen.renderBlip(fam, 1234L + fam.ordinal)) <=
            pb.BLIP_CEILING + 0.001f,
            "budget: blip ${fam.name} renders under the blip ceiling")
    }
    for (s in listOf(0L, 1L, 2L, 3L)) {
        check(pb.peakOf(SoundGen.renderSnowStep(s)) <= pb.SFX_CEILING + 0.001f,
            "budget: snow step $s renders under the SFX ceiling")
    }
    close(pb.peakOf(SoundGen.renderSfx("door_close")), 0.3951f, 0.01f,
        "budget: a quiet render passes the limiter untouched")
    val soundSrc = File(root, "src/com/hunt3r/southparktown/Sound.kt").readText()
    check(soundSrc.contains("setOnLoadCompleteListener") && !soundSrc.contains("Thread.sleep"),
        "audio: pool readiness is earned via OnLoadCompleteListener — no settle sleep")
    check(soundSrc.contains("PeakBudget.MUSIC_CHAIN") && soundSrc.contains("PeakBudget.AMB_CHAIN"),
        "audio: the player reads the budget's own chain constants")
    check(soundSrc.contains("\"v020g_r1\""),
        "audio: the render stamp moved with the new renders")

    // ---------- flagged gap: beds follow a weather flip at once ----------
    val engW = Engine(5)
    val sW = engW.newState()
    var shifts = 0
    engW.onWeatherShift = { shifts++ }
    val w0 = sW.weatherId
    val w1 = if (w0 == "rain") "sunny" else "rain"
    engW.setWeather(sW, w1)
    check(shifts == 1, "weather: a real flip fires the shift hook")
    engW.setWeather(sW, w1)
    check(shifts == 1, "weather: re-setting the same sky does not fire")
    engW.setWeather(sW, w0)
    check(shifts == 2, "weather: flipping back fires again")
    val gaSrcG = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrcG.contains("engine.onWeatherShift"),
        "weather: GameActivity wires the hook to the beds")

    // ---------- flagged gap: pair scripts join the freshness ring ----------
    val engR = Engine(31)
    val pairRK = setOf("Stan", "Kyle")
    val rndR = kotlin.random.Random(7)
    var lastIdx = -1
    repeat(12) {
        val idx = engR.freshScriptIndex(pairRK, 3, rndR)
        check(idx in 0 until 3, "pair ring: the index stays in range")
        check(idx != lastIdx, "pair ring: never the same script twice in a row")
        lastIdx = idx
    }
    check(engR.freshScriptIndex(pairRK, 1, rndR) == 0,
        "pair ring: a lone script is index 0")
    val sR2 = engR.newState()
    var prevChat: List<String>? = null
    repeat(6) {
        val chat = engR.mockDialogue(sR2.agents["Stan"]!!, sR2.agents["Kyle"]!!,
            "Main Street", sR2).map { "${it.speaker}:${it.text}" }
        check(chat != prevChat, "pair ring: back-to-back scripted chats differ")
        prevChat = chat
    }

    // ---------- audit fix: yesterday's lamp key is pruned ----------
    val engL = Engine(9)
    val sL2 = engL.newState()
    sL2.lifeText["lampFixed:${sL2.absDay}"] = "MainStreet"
    sL2.lifeText["lampFixed:${sL2.absDay - 3}"] = "KidsPark"
    sL2.lifeText["zzCustom"] = "keep"
    engL.onNewDay(sL2)
    check(sL2.lifeText.keys.none { it.startsWith("lampFixed:") },
        "audit: lampFixed keys do not survive a rollover")
    check(sL2.lifeText["zzCustom"] == "keep",
        "audit: the prune is surgical — other lifeText survives")

    // ---------- minigame feel: centralized, values unchanged ----------
    check(Feel.BITE_WINDOW_MS == 950L && Feel.BITE_WINDOW_HEAVY_SNOW_MS == 820L &&
        Feel.BITE_WINDOW_BLIZZARD_MS == 700L,
        "feel: bite windows live in Feel at the shipped values")
    check(biteWindowMs("blizzard") == Feel.BITE_WINDOW_BLIZZARD_MS &&
        biteWindowMs("heavy_snow") == Feel.BITE_WINDOW_HEAVY_SNOW_MS &&
        biteWindowMs("sunny") == Feel.BITE_WINDOW_MS, "feel: biteWindowMs reads Feel")
    check(Showdown.zoneOf(Feel.ZONE_PERFECT_LO) == "perfect" &&
        Showdown.zoneOf(Feel.ZONE_GOOD_HI) == "good" &&
        Showdown.zoneOf(Feel.ZONE_OK_LO) == "ok" &&
        Showdown.zoneOf(0.01f) == "wild", "feel: zone edges are Feel's")
    check(Showdown.dodgeWindowMs(1, "Tweek") in Feel.DODGE_MIN_MS..Feel.DODGE_MAX_MS &&
        Showdown.dodgeWindowMs(9, "Butters") == Feel.DODGE_MIN_MS,
        "feel: dodge windows clamp to Feel's band")
    val tacoSess = TacoCatchSession(42)
    check(tacoSess.spawns.isNotEmpty() && tacoSess.spawns.first().atMs == Feel.SPAWN_FIRST_MS,
        "feel: the cabinet's first drop is Feel's")
    check(tacoSess.spawns.all { it.fallMs >= 1300L },
        "feel: no item falls faster than floor x jitter")
    check(TacoCatch.coinsForScore(600) == Feel.COIN_TIERS.first().second &&
        TacoCatch.coinsForScore(0) == 0, "feel: the payout walks Feel's tier table")
    val gamesSrc = File(root, "src/com/hunt3r/southparktown/Minigames.kt").readText()
    check(gamesSrc.contains("object Feel"), "feel: Minigames.kt centralizes tuning in Feel")

    // ---------- first-entry how-tos ----------
    val sH = Engine(3).newState()
    check(Minigames.firstEntryHowTo(sH, "fishing") == Minigames.HOW_TO["fishing"],
        "howto: the first fishing entry shows its line")
    check(Minigames.firstEntryHowTo(sH, "fishing") == null,
        "howto: the second fishing entry is quiet")
    check(Minigames.firstEntryHowTo(sH, "showdown") != null &&
        Minigames.firstEntryHowTo(sH, "taco") != null,
        "howto: each game gets its own first entry")
    check(Minigames.firstEntryHowTo(sH, "pinball") == null,
        "howto: unknown games stay quiet")
    check(Minigames.HOW_TO.values.all { "\n" !in it && it.length in 40..160 },
        "howto: every line is one line, subtitle-sized")
    check(gaSrcG.contains("firstEntryHowTo"), "howto: the three entry points wire the lines")

    // ---------- save-state caps, through the REAL save path ----------
    val engC = Engine(17)
    val sC2 = engC.newState()
    repeat(100) { sC2.events.add("event $it") }
    repeat(100) { townLogLine(sC2, "log $it") }
    val stanC = sC2.agents["Stan"]!!
    repeat(25) { stanC.memories.add("memory $it") }
    val docC = encodeGameState(sC2)
    check((docC["events"] as List<*>).size == 40,
        "caps: the save doc carries at most 40 events")
    check(sC2.townLog.size == 30 && (docC["townLog"] as List<*>).size == 30,
        "caps: the town log holds at 30 in memory and in the doc")
    val agentsDoc = docC["agents"] as Map<*, *>
    val stanDoc = agentsDoc["Stan"] as Map<*, *>
    check((stanDoc["memories"] as List<*>).size == 10,
        "caps: agent memories save at 10 deep")
    // episodes: the add path trims the shelf at 30
    val sE2 = engC.newState()
    val def0 = SHENANIGANS.first()
    repeat(35) { i ->
        sE2.todayKey = "2026%02d%02d".format(1 + i / 28, 1 + i % 28)
        val ep = Episodes.beginEvent(sE2, def0)
        ep.finished = true
    }
    check(sE2.episodes.size == 30,
        "caps: the episode shelf trims to 30 (got ${sE2.episodes.size})")
    // photos: the add path trims the album at its cap
    val sP2 = engC.newState()
    engC.createPlayer(sP2, "Snapper", DEFAULT_APPEARANCE)
    repeat(100) { i ->
        Photos.applyPhoto(sP2, PhotoRecord(
            id = "cap$i", dayKey = "20260101", dateLabel = "1/1", timeMin = 600,
            locId = "MainStreet", inside = false, weatherId = "sunny",
            appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Snapper", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy")),
            caption = "cap test $i", followersGained = 1, seed = i.toLong()))
    }
    check(sP2.photos.size == Photos.ALBUM_CAP,
        "caps: the album trims to its cap (got ${sP2.photos.size})")
    // conversions: the gate caps NEW move-ins; existing saves keep everyone
    check(VisitorSystem.MAX_CONVERTED == 24, "caps: the move-in cap is 24")
    check(gaSrcG.contains("VisitorSystem.MAX_CONVERTED"),
        "caps: the conversion site reads the cap")
    val sV2 = engC.newState()
    repeat(30) { sV2.convertedResidents.add("Long Ago Converted Resident $it") }
    val backV = decodeGameState(encodeGameState(sV2))
    check(backV.convertedResidents.size == 30,
        "caps: a save already past the cap keeps every resident (no load trim)")

    // ---------- npc_memory: the entry-count cap ----------
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        NpcMemoryStore.clear()
        for (n in CharacterSystem.CAST.keys) {
            val m = NpcMemoryStore.getOrCreate(n)
            m.meets = 3; m.lastMetDay = "20260101"
        }
        for (i in 0 until 450) {
            val m = NpcMemoryStore.getOrCreate("Generated Person %03d".format(i))
            m.meets = 1
            m.lastMetDay = "2027%02d%02d".format(1 + i / 28, 1 + i % 28)
        }
        val memDoc = NpcMemoryStore.serialize()
        check(memDoc.size == NpcMemoryStore.MAX_ENTRIES,
            "memory cap: the serialized doc stops at ${NpcMemoryStore.MAX_ENTRIES} (got ${memDoc.size})")
        check(CharacterSystem.CAST.keys.all { it in memDoc },
            "memory cap: every cast member survives")
        check("Generated Person 449" in memDoc,
            "memory cap: the freshest generated NPC survives")
        check("Generated Person 000" !in memDoc,
            "memory cap: the stalest generated NPC prunes first")
        val memJson = Json.stringify(memDoc)
        println("npc_memory at cap: ${memJson.length} chars serialized")
        check(memJson.length < 256 * 1024,
            "memory cap: a capped memory doc stays lean (got ${memJson.length})")
    } finally {
        NpcMemoryStore.clear()
        NpcMemoryStore.deserialize(memSnapshot)
    }

    // ---------- newest-screen fit QA (Mystery / Games / Album / finale) ----------
    // These screens are wrapping TextViews on cardstock — the
    // invariants that guard them are the contrast pairs they
    // actually use, and that their longest real lines pass
    // through the Chrome fit machinery intact-or-ellipsized
    // (never overflowing, never collapsing) at font scales
    // 1.0 and 1.3, in the suite's 10px-per-char model.
    check(Chrome.contrast(Chrome.INK, Chrome.PARCHMENT) >= 4.5f,
        "fitQA: board/games/album ink on cardstock")
    check(Chrome.contrast(Chrome.INK_SOFT, Chrome.PARCHMENT) >= 4.5f,
        "fitQA: soft-ink body text on cardstock")
    check(Chrome.contrast("#ffffff", Chrome.RED) >= 4.5f,
        "fitQA: white on the finale plaque red")
    check(Chrome.contrast(Chrome.RED, Chrome.CHARCOAL) >= 3.0f,
        "fitQA: red section titles on charcoal (large bold)")
    val innerW = 420f
    val engQ = Engine(11)
    val sQ = engQ.newState()
    sQ.arcStarted = true; sQ.arcChapter = 5
    for (c in Mystery.CLUES) sQ.mysteryClues.add(c.id)
    val boardLines = Mystery.boardLines(sQ)
    check(boardLines.first() == "🔍 ${Mystery.ARC_TITLE}", "fitQA: the board's title line")
    val albumHeader0 = "👥 0 followers" +
        (Photos.badgeFor(0)?.let { " · 🏅 $it club" } ?: "") +
        (Photos.nextMilestone(0)?.let { " · next badge at $it" } ?: "")
    val albumHeaderFat = "👥 123456 followers" +
        (Photos.badgeFor(123456)?.let { " · 🏅 $it club" } ?: "") +
        (Photos.nextMilestone(123456)?.let { " · next badge at $it" } ?: "")
    val gamesLines = Minigames.GAME_FEATS.map {
        "✅ ${it.name} — ${it.desc}"
    } + listOf("🪙 Capsule Coins ×9999",
        "🏆 GAME FEATS — ${Minigames.GAME_FEATS.size}/${Minigames.GAME_FEATS.size}")
    val finaleItems = listOf(
        "📢 Present the truth — you know what that light is " +
            "(${Mystery.clueCount(sQ)}/${Mystery.CLUES.size} clues)",
        "🤫 Say nothing — let the town have its aliens")
    val allScreenLines = boardLines + gamesLines + finaleItems +
        listOf(albumHeader0, albumHeaderFat, "🔍 The Light Over The Pond")
    for (fs in listOf(1.0f, 1.3f)) {
        val mFs = { s: String -> s.length * 10f * fs }
        for (line in allScreenLines) {
            val e = Chrome.ellipsize(line, innerW, measure = mFs)
            check(mFs(e) <= innerW + 0.01f,
                "fitQA: a newest-screen line fits at fs $fs")
            check(e.length >= 4, "fitQA: a newest-screen line never collapses at fs $fs")
        }
    }
    val m10 = { s: String -> s.length * 10f }
    check(Chrome.ellipsize(boardLines.first(), innerW, measure = m10) == boardLines.first(),
        "fitQA: the board title fits one line at fs 1.0")
    check(Chrome.ellipsize(albumHeader0, innerW, measure = m10) == albumHeader0,
        "fitQA: the album header fits one line at fs 1.0")
    check(Chrome.ellipsize("🔍 The Light Over The Pond", innerW, measure = m10) ==
        "🔍 The Light Over The Pond", "fitQA: the finale title fits its plaque at fs 1.0")

    // ---------- the heavy veteran: serialized size of a saturated save ----------
    val engV = Engine(99)
    val vet = engV.newState()
    engV.createPlayer(vet, "Veteran", DEFAULT_APPEARANCE)
    vet.gameYear = 2027; vet.gameMonth = 6; vet.gameDay = 15
    vet.todayKey = "20270615"; vet.lastPlayedDate = "20270615"; vet.absDay = 400
    for (n in CharacterSystem.CAST.keys) vet.friendship[n] = 100
    for ((_, a) in vet.agents) repeat(25) {
        a.memories.add("A whole day in South Park, Colorado — the whole town " +
            "was involved and absolutely nobody learned a thing.")
    }
    repeat(40) { vet.events.add("📌 A day where everything happened at once, again ($it)") }
    repeat(30) { townLogLine(vet, "🎪 Town history entry $it — a full sentence about the day.") }
    for (sp in FISH_TABLE) vet.fishLog[sp.id] = FishRecord(999, sp.maxCm)
    for (kid in CharacterSystem.CAST_KIDS) vet.showdown[kid] = ShowdownRecord(400, 400)
    vet.fishCasts = 9000; vet.tacoHigh = 640; vet.tacoPlays = 900; vet.followers = 250000
    for (item in ITEMS) vet.inventory[item.id] = 99
    vet.inventory[Minigames.COIN_ITEM] = 9999
    for (c in Mystery.CLUES) vet.mysteryClues.add(c.id)
    for (f in Minigames.GAME_FEATS) vet.gameFeats.add(f.id)
    for (f in Photos.PHOTO_FEATS) vet.photoFeats.add(f.id)
    repeat(24) { vet.convertedResidents.add("Converted Resident With A Long Lore Name $it") }
    repeat(300) { vet.photographed["Photographed Townsfolk With A Name $it"] = 7 }
    for (loc in LOCATIONS.keys) {
        vet.locVisits[loc] = 999
        vet.lifeText["mark:$loc"] = "Stan"
        vet.lifeText["chalk:$loc"] = "a very elaborate chalk mural"
        vet.lifeText["prank:$loc"] = "whoopee cushion, deluxe"
        vet.life["clean:$loc"] = 9
    }
    for (n in CharacterSystem.CAST.keys) {
        vet.npcGoals[n] = NpcGoal.fromMap(mapOf("npcKey" to n))!!
    }
    repeat(30) { i ->
        vet.episodes.add(EpisodeRecord(
            key = "event$i@20260101", kind = "event", eventId = "event$i",
            eventTitle = "The Big Event $i", title = "The One Where Everything Happens $i",
            treatment = "A very special episode, presented without commercial interruption.",
            causers = listOf("Stan", "Kyle", "Cartman", "Kenny"),
            dayKey = "20260101", dateLabel = "1/1",
            stageTitles = listOf("Cold Open", "Act One", "Act Two", "The Wrap"),
            stageNotes = listOf("It starts.", "It escalates.", "It peaks.", "It lands."),
            finished = true, participation = 10))
    }
    repeat(60) { i ->
        vet.photos.add(PhotoRecord(
            id = "vet$i", dayKey = "20270615", dateLabel = "6/15", timeMin = 700,
            locId = "MainStreet", inside = false, weatherId = "sunny",
            appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Veteran", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy"), PhotoFigure("Kyle", "cast", "goofy")),
            caption = "Best day ever in South Park with the whole gang, again ($i)",
            followersGained = 25, seed = i.toLong()))
    }
    val vetJson = Json.stringify(encodeGameState(vet))
    println("veteran game_state: ${vetJson.length} chars serialized")
    check(vetJson.length < 512 * 1024,
        "veteran: a saturated save stays under half a megabyte (got ${vetJson.length})")
    @Suppress("UNCHECKED_CAST")
    val vetBack = decodeGameState(Json.parse(vetJson) as Map<String, Any?>)
    check(vetBack.episodes.size == 30 && vetBack.photos.size == 60 &&
        vetBack.convertedResidents.size == 24,
        "veteran: the saturated save round-trips at its caps")
    check((vetBack.agents["Stan"]?.memories?.size ?: 0) <= 10,
        "veteran: round-tripped memories respect the save trim")

    // ---------- the 60-day fast-forward ----------
    val engSim = Engine(20260)
    val sim = engSim.newState()
    engSim.createPlayer(sim, "Veteran", DEFAULT_APPEARANCE)
    val startAbs = sim.absDay
    var simError: String? = null
    try {
        repeat(60) { day ->
            repeat(96) { engSim.advanceTime(sim) }
            if (day % 7 == 3) {
                Photos.applyPhoto(sim, PhotoRecord(
                    id = "sim$day", dayKey = sim.todayKey, dateLabel = "?",
                    timeMin = 720, locId = "MainStreet", inside = false,
                    weatherId = sim.weatherId, appearance = DEFAULT_APPEARANCE,
                    figures = listOf(PhotoFigure("Veteran", "player", "happy"),
                        PhotoFigure("Stan", "cast", "happy")),
                    caption = "day $day in the park", followersGained = 3,
                    seed = day.toLong()))
            }
        }
    } catch (e: Exception) {
        simError = "${e.javaClass.simpleName}: ${e.message}"
    }
    check(simError == null,
        "sim: 60 days fast-forwarded without an exception (got $simError)")
    check(sim.absDay == startAbs + 60,
        "sim: the calendar advanced exactly 60 days (got ${sim.absDay - startAbs})")
    check(sim.events.size <= 40 && sim.townLog.size <= 30,
        "sim: ticker + town log stayed capped")
    check(sim.episodes.size <= 30, "sim: episodes stayed capped (got ${sim.episodes.size})")
    check(sim.photos.size <= Photos.ALBUM_CAP,
        "sim: the album stayed capped (got ${sim.photos.size})")
    check(sim.npcGoals.isNotEmpty(), "sim: goal cycles churned (records live at day 60)")
    check(sim.arcStarted, "sim: the season mystery began")
    check(sim.arcRetired, "sim: the season mystery retired itself inside 60 days")
    println("sim: absDay $startAbs->${sim.absDay}, episodes ${sim.episodes.size}, " +
        "photos ${sim.photos.size}, goals ${sim.npcGoals.size}, " +
        "arc chapter ${sim.arcChapter} retired=${sim.arcRetired} branch=${sim.arcBranch}")
}
}

/** v0.3.0a section, extracted from main() like v0.2.0g's:
 *  new sections live in their own functions (64 KB limit). */
private fun sectionV030a(root: String) {
// ================= v0.3.0a: scene parity pass #3 =================
// Exteriors & light — opens the 0.3.0 series. The LIGHT layer
// registry + LOC_LIGHT identity, the seasonal dressing
// registry, weather wear as measured palette transforms on
// LOC_PALETTES data, and the one shared light state
// (SceneLight) that SceneArt, InteriorArt and PhotoView read.
println("== v0.3.0a: exteriors & light — light layer, seasons, weather wear ==")
run {
    val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    fun rgb(hex: String): Triple<Int, Int, Int> {
        val v = hex.removePrefix("#").toInt(16)
        return Triple(v shr 16 and 255, v shr 8 and 255, v and 255)
    }

    // ---------- bands & light level: one table for everyone ----------
    check(SceneLight.bandOf(420) == "day", "light: 7:00 is day")
    check(SceneLight.bandOf(1079) == "day", "light: 17:59 still day")
    check(SceneLight.bandOf(1080) == "dusk", "light: 18:00 is dusk")
    check(SceneLight.bandOf(1259) == "dusk", "light: 20:59 still dusk")
    check(SceneLight.bandOf(1260) == "night", "light: 21:00 is night")
    check(SceneLight.bandOf(0) == "night", "light: midnight is night")
    check(SceneLight.bandOf(419) == "night", "light: 6:59 still night")
    close(SceneLight.lightLevel(720), 0f, 0.001f, "light: noon level 0 (off)")
    close(SceneLight.lightLevel(1140), 0.65f, 0.001f, "light: 19:00 dusk level 0.65")
    close(SceneLight.lightLevel(1380), 1f, 0.001f, "light: 23:00 full night")
    check(!SceneLight.lightsOn(720) && SceneLight.lightsOn(1140) && SceneLight.lightsOn(60),
        "light: lightsOn follows the level")
    check(SceneLight.glowAlpha(200, 720) == 0 && SceneLight.glowAlpha(200, 1140) == 130 &&
        SceneLight.glowAlpha(200, 1380) == 200, "light: glow alpha scales by level")
    check(sceneSrc.contains("SceneLight.bandOf"),
        "light: SceneArt delegates its band table to SceneLight")
    for (m in listOf(0, 419, 420, 720, 1079, 1080, 1259, 1260, 1439)) {
        check(SceneArt.timeOfDay(m) == SceneLight.bandOf(m),
            "light: timeOfDay agrees with bandOf at $m")
    }
    val photoSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
    check(photoSrc.contains("SceneLight.bandOf") && photoSrc.contains("SceneLight.wearHex"),
        "light: the selfie backdrop shares the light state + wear")
    val interiorSrc = File(root, "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
    check(interiorSrc.contains("SceneLight.lampsOf"),
        "light: interiors read the exterior lamp state")

    // ---------- weather wear: measured, pinned, reversible ----------
    for ((id, pal) in LOC_PALETTES) {
        for (hex in listOf(pal.fieldHex, pal.wallHex, pal.floorHex, pal.accentHex)) {
            check(SceneLight.applyWear(hex, SceneLight.NO_WEAR) == hex,
                "wear: NO_WEAR identity $id $hex")
            check(SceneLight.wearHex(hex, "sunny") == hex,
                "wear: sunny leaves $id $hex byte-exact")
        }
    }
    for ((id, loc) in LOCATIONS) {
        check(SceneLight.wearHex(loc.colorHex, "sunny") == loc.colorHex,
            "wear: facade identity $id")
    }
    check(SceneLight.wearFor("not_a_weather") == SceneLight.NO_WEAR,
        "wear: unknown weather = no wear")
    hexEq(SceneLight.wearHex("#8a8578", "rain"), "#767269",
        "wear: rain darkens a step")
    hexEq(SceneLight.wearHex("#5aa85a", "fog"), "#78a378",
        "wear: fog mutes the green")
    hexEq(SceneLight.wearHex("#3e6b8a", "blizzard"), "#8ba2b2",
        "wear: blizzard whites out the blue")
    hexEq(SceneLight.wearHex("#ffffff", "rain"), "#dbdbdb",
        "wear: rain grays the snow")
    hexEq(SceneLight.wearHex("#c0392b", "heavy_snow"), "#c9665c",
        "wear: heavy snow frosts the red")
    for ((id, pal) in LOC_PALETTES) {
        val (r0, g0, b0) = rgb(pal.fieldHex)
        val (r1, g1, b1) = rgb(SceneLight.wearHex(pal.fieldHex, "rain"))
        check(r1 + g1 + b1 <= r0 + g0 + b0, "wear: rain never brightens $id")
        val (r2, g2, b2) = rgb(SceneLight.wearHex(pal.fieldHex, "blizzard"))
        check(minOf(r2, g2, b2) >= minOf(r0, g0, b0),
            "wear: blizzard lifts the darkest channel of $id")
        val (r3, g3, b3) = rgb(SceneLight.wearHex(pal.fieldHex, "fog"))
        check(maxOf(r3, g3, b3) - minOf(r3, g3, b3) <= maxOf(r0, g0, b0) - minOf(r0, g0, b0),
            "wear: fog never saturates $id")
        check(SceneLight.wearHex(pal.fieldHex, "rain") ==
            SceneLight.wearHex(pal.fieldHex, "rain"),
            "wear: the transform is pure for $id")
    }
    check(sceneSrc.contains("SceneLight.wearHex"),
        "wear: the scene routes its colors through the transforms")

    // ---------- LOC_LIGHT: a light identity per place ----------
    check(LOC_LIGHT.size == 27, "light: LOC_LIGHT covers all 27 locations")
    for ((id, ll) in LOC_LIGHT) {
        check(LOCATIONS.containsKey(id), "light: $id is a real location")
        val (r, g, b) = rgb(ll.warmthHex)
        check(maxOf(r, g, b) >= 235, "light: $id warmth is a lit color (${ll.warmthHex})")
        check(maxOf(r, g, b) - minOf(r, g, b) >= 20,
            "light: $id warmth is tinted, not gray (${ll.warmthHex})")
        check(ll.lamps in 0..2, "light: $id lamp count sane (${ll.lamps})")
        check(SceneLight.warmthOf(id) == ll.warmthHex, "light: warmthOf $id")
        check(SceneLight.lampsOf(id) == ll.lamps, "light: lampsOf $id")
    }
    check(LOC_LIGHT.values.map { it.warmthHex }.distinct().size == 27,
        "light: 27 distinct warmths — no two places burn the same")
    for (id in listOf("SkeetersBar", "Bijou", "CityWok", "FreemansTacos", "Mall",
            "Raisins", "TweekBros", "Church")) {
        check(SceneLight.signGlowOf(id) != null, "light: $id's sign glows at night")
    }
    for (id in listOf("BusStop", "MainStreet", "Mall", "KidsPark", "TolkienHouse",
            "PostOffice", "CityHall", "Elementary")) {
        check(SceneLight.lampsOf(id) >= 1, "light: $id has a street/yard lamp")
    }
    check(SceneLight.warmthOf("Nowhere") == "#f2c230",
        "light: an unknown place falls back to town amber")
    check(sceneSrc.contains("SceneLight.warmthOf"),
        "light: facade windows burn in the location's warmth")

    // ---------- the LIGHT layer registry vs. drawn source ----------
    check(LOC_LIGHT_DETAILS.size == 27, "light: layer registry covers all 27")
    val lightToks = LOC_LIGHT_DETAILS.values.flatten()
    check(lightToks.size == 56, "light: 56 light tokens (got ${lightToks.size})")
    check(lightToks.distinct().size == lightToks.size,
        "light: every token belongs to exactly one location")
    for ((locId, tokens) in LOC_LIGHT_DETAILS) {
        check(LOCATIONS.containsKey(locId), "light: $locId is a real location")
        check(tokens.size >= 2, "light: $locId carries 2+ light pieces")
        for (tok in tokens) {
            check(sceneSrc.contains("light: $tok"), "light: drawn — $locId/$tok")
        }
    }
    check(sceneSrc.contains("drawLightLayer"), "light: the layer runs in drawScene")
    check(sceneSrc.contains("SceneLight.lightLevel(timeMin) > 0f"),
        "light: the layer is gated to dusk/night hours")

    // ---------- the SEASONAL registry vs. drawn source ----------
    check(LOC_SEASON_DETAILS.size == 27, "season: registry covers all 27")
    val seasonToks = LOC_SEASON_DETAILS.values.flatten()
    check(seasonToks.size == 108, "season: 108 seasonal tokens (got ${seasonToks.size})")
    check(seasonToks.distinct().size == seasonToks.size,
        "season: every token belongs to exactly one location")
    for ((locId, tokens) in LOC_SEASON_DETAILS) {
        check(LOCATIONS.containsKey(locId), "season: $locId is a real location")
        check(tokens.size == 4, "season: $locId dresses all four seasons")
        for (tok in tokens) {
            check(sceneSrc.contains("season: $tok"), "season: drawn — $locId/$tok")
        }
        for (s in Season.values()) {
            val active = SceneLight.seasonTokensFor(locId, s)
            check(active.size == 1,
                "season: $locId has exactly one ${SceneLight.seasonPrefix(s)} piece")
            check(active[0] in tokens, "season: the gate returns registry tokens for $locId")
        }
    }
    check(SceneLight.seasonTokensFor("StanHouse", Season.WINTER) ==
        listOf("winter-garage-icicles"), "season: the winter gate is exact")
    check(SceneLight.seasonTokensFor("StanHouse", Season.SPRING) ==
        listOf("spring-cleanout-boxes"), "season: the spring gate is exact")
    check(sceneSrc.contains("drawSeasonDetails"), "season: the layer runs in drawScene")

    // ---------- registry totals grow past passes #1 + #2 ----------
    // v0.4.0a: pass #4 adds the 27 silhouettes to the count.
    val total = LOC_ART_DETAILS.values.sumOf { it.size } +
        INTERIOR_ART_DETAILS.values.sumOf { it.size } + lightToks.size + seasonToks.size +
        LOC_SILHOUETTES.size
    check(total == 336, "registries: 63 + 82 + 56 + 108 + 27 silhouettes = 336 pinned tokens (got $total)")
}
}

private fun sectionV030b(root: String) {
// ================= v0.3.0b: cast expansion wave 2 =================
// Twelve new named townsfolk join the 32 (cast 32 -> 44): Heidi,
// Nichole, Red, Kevin, Francis, DogPoo (Elementary kids) and
// McDaniels, Barbrady, Crabtree, Mr. Tweek, Mrs. Tweek, Ned
// (adults). This section pins the wave's own contract; the
// moved 32 -> 44 pins live in the sections that own them.
println("== v0.3.0b: cast expansion wave 2 — twelve new townsfolk ==")
run {
    val wave2 = listOf("Heidi", "Nichole", "Red", "Kevin", "Francis", "DogPoo",
        "McDaniels", "Barbrady", "Crabtree", "Mr. Tweek", "Mrs. Tweek", "Ned")
    val wave2Kids = wave2.take(6)
    val wave2Adults = wave2.drop(6)

    // ---------- the roster arithmetic: 44 everywhere ----------
    check(WAVE2_ORDER == wave2, "wave2: the wave roster is exactly the twelve")
    check(KID_ORDER.size == 98 && KID_ORDER.distinct().size == 98,
        "wave4: KID_ORDER carries 98 distinct names")
    check(AGENT_PROFILES.size == 98, "wave4: 98 agent profiles")
    check(KID_HOUSE.size == 98, "wave4: 98 homes")
    check(CharacterSystem.CAST_KIDS.size + CharacterSystem.CAST_ADULTS.size == 98 &&
        (CharacterSystem.CAST_KIDS intersect CharacterSystem.CAST_ADULTS).isEmpty(),
        "wave4: 42 kids + 56 adults, disjoint")
    check(wave2Kids.all { it in CharacterSystem.CAST_KIDS } &&
        wave2Adults.all { it in CharacterSystem.CAST_ADULTS },
        "wave2: the twelve sit in the right age sets")
    check(CharacterSystem.CAST.keys == AGENT_PROFILES.keys,
        "wave2: CAST and AGENT_PROFILES describe the same 44")

    // ---------- every registry knows every newcomer ----------
    for (n in wave2) {
        check(n in AGENT_PROFILES, "wave2: $n has a profile")
        check(n in KidArt.SHEETS, "wave2: $n has a sheet spec")
        check(n in KID_HOUSE, "wave2: $n has a home")
        check(n in LINE_BANKS && n in DAILY_TOPICS && n in SPEECH_RULES,
            "wave2: $n has bank, topics and a speech rule")
        check(n in FRIEND_GREETINGS && n in RESPONSE_BANKS && n in SLEEPY_LINES,
            "wave2: $n greets, responds and sleep-talks")
        check(SoundGen.BLIP_FAMILIES.containsKey(n), "wave2: $n has a blip family")
        check(LORE_CHAR_ALIASES.containsKey(n) &&
            LoreBook.charLore(n) != null, "wave2: $n resolves to lorebook prose")
        check(FACTION_OF_CAST.containsKey(n), "wave2: $n belongs to a faction")
    }
    // the generated-visitor pool must never double-cast them
    val loreNames = wave2.map { LORE_CHAR_ALIASES[it]!! }.toSet()
    check(VisitorSystem.eligible().none { it.name in loreNames },
        "wave2: the visitor pool excludes the new cast")

    // ---------- homes & workplaces: existing locations only ----------
    check(KID_HOUSE["McDaniels"] == "CityHall", "wave2: the Mayor homes to City Hall")
    check(KID_HOUSE["Barbrady"] == "MainStreet", "wave2: Barbrady homes to his patrol")
    check(KID_HOUSE["Crabtree"] == "BusStop", "wave2: Crabtree homes to the bus stop")
    check(KID_HOUSE["Mr. Tweek"] == "TweekBros" && KID_HOUSE["Mrs. Tweek"] == "TweekBros",
        "wave2: the Tweeks home to the coffeehouse")
    check(KID_HOUSE["Ned"] == "JimbosGuns", "wave2: Ned homes to the gun shop")
    for (n in wave2Kids) {
        check(KID_HOUSE[n] == "Elementary", "wave2: $n uses the Elementary home convention")
    }

    // ---------- schedules: seven blocks, real places ----------
    for (n in wave2) {
        val p = AGENT_PROFILES[n]!!
        check(p.agenda.keys == setOf("08:00", "09:00", "12:00", "15:00", "16:30", "18:00", "21:00"),
            "wave2: $n keeps the town's seven-block day")
        check(p.agenda.values.all { it.location in LOCATIONS },
            "wave2: every stop on $n's day is a real location")
        check(p.description.length > 200, "wave2: $n's persona is written deep")
    }
    check(AGENT_PROFILES["Crabtree"]!!.agenda.values.count { it.location == "BusStop" } >= 4,
        "wave2: Crabtree's day belongs to the bus")
    check(AGENT_PROFILES["Barbrady"]!!.agenda.values.count { it.location == "MainStreet" } >= 3,
        "wave2: Barbrady patrols Main Street")
    check(AGENT_PROFILES["McDaniels"]!!.agenda.values.count { it.location == "CityHall" } >= 4,
        "wave2: the Mayor's day belongs to City Hall")

    // ---------- factions: exactly one each, canon-flavored ----------
    check(FACTION_OF_CAST.size == 98, "wave4: every cast member holds exactly one faction")
    check(FACTION_OF_CAST["Heidi"] == "girls_circle" &&
        FACTION_OF_CAST["Nichole"] == "girls_circle" &&
        FACTION_OF_CAST["Red"] == "girls_circle", "wave2: the new girls join the circle")
    check(FACTION_OF_CAST["Kevin"] == "craigs_gang", "wave2: Kevin runs with Craig's gang")
    check(FACTION_OF_CAST["Francis"] == "boys_crew" &&
        FACTION_OF_CAST["DogPoo"] == "boys_crew", "wave2: Francis & DogPoo trail the boys")
    check(FACTION_OF_CAST["Crabtree"] == "school_staff", "wave2: Crabtree is school staff")
    check(FACTION_OF_CAST["Ned"] == "tegridy_crew" &&
        FACTION_OF_CAST["Mr. Tweek"] == "tegridy_crew" &&
        FACTION_OF_CAST["Mrs. Tweek"] == "tegridy_crew",
        "wave2: local business claims Ned and the Tweeks")
    check(FACTION_OF_CAST["McDaniels"] == "parents" &&
        FACTION_OF_CAST["Barbrady"] == "parents", "wave2: City Hall sits with the grown-ups")

    // ---------- specs: measured-system invariants for the twelve ----------
    for (n in wave2) {
        val spec = KidArt.SHEETS[n]!!
        val m = spec.measured
        check(m != null, "wave2: $n carries MeasuredProps")
        m!!
        close(m.headShare + m.torsoShare + m.legShare, 1.0f, 0.011f,
            "wave2: $n's shares sum to a whole figure")
        val d = FigureGeometry.derive(spec)
        close(d.headShare, m.headShare, 0.045f, "wave2: $n rendered headShare ~ spec")
        close(d.torsoShare, m.torsoShare, 0.03f, "wave2: $n rendered torsoShare ~ spec")
        close(d.legShare, m.legShare, 0.035f, "wave2: $n rendered legShare ~ spec")
        close(d.headAspect, m.headAspect, 0.03f, "wave2: $n rendered head aspect == spec")
        check(d.eyeL >= d.hx - d.hrx - 0.5f && d.eyeR <= d.hx + d.hrx + 0.5f,
            "wave2: $n's eyes sit inside the head ellipse")
        check(d.mouthY <= d.hy + d.hry + 0.5f, "wave2: $n's mouth sits inside the head")
        close(d.hy + d.hry, d.plan.torsoTop + 2f, 0.6f, "wave2: $n's chin anchors to the torso")
        if (n in wave2Kids) {
            check(m.headShare in 0.60f..0.66f, "wave2: kid $n keeps the big-head band")
            check(!spec.tall, "wave2: kid $n is not on adult proportions")
        } else {
            check(spec.tall, "wave2: adult $n is on adult proportions")
            check(m.legShare >= m.torsoShare, "wave2: adult $n keeps legs >= torso")
            check(m.headShare in 0.33f..0.37f, "wave2: adult $n keeps the adult head band")
        }
    }
    // the twelve are twelve distinct silhouettes, not one reskinned
    val shapes = wave2.map {
        val m = KidArt.SHEETS[it]!!.measured!!
        listOf(m.headShare, m.heightRel, KidArt.SHEETS[it]!!.width)
    }
    check(shapes.distinct().size == 12, "wave2: no two newcomers share a silhouette")

    // ---------- signature spot-pins: recognizable without a label ----------
    check(KidArt.SHEETS["Heidi"]!!.hairStyle == "long" &&
        KidArt.SHEETS["Heidi"]!!.top == "#d46a8a", "wave2: Heidi = long auburn hair, pink jacket")
    check(KidArt.SHEETS["Red"]!!.hairColor == "#b83a1e",
        "wave2: Red's hair is the name")
    check(KidArt.SHEETS["Nichole"]!!.skin == "#7a5230" &&
        KidArt.SHEETS["Nichole"]!!.hairStyle == "curls",
        "wave2: Nichole = dark skin, black curl mane")
    check(KidArt.SHEETS["Francis"]!!.width == 1.18f, "wave2: Francis is the wide one")
    check(KidArt.SHEETS["DogPoo"]!!.freckles, "wave2: DogPoo's grime is drawn")
    check(KidArt.SHEETS["Barbrady"]!!.sunglasses && KidArt.SHEETS["Barbrady"]!!.hatId == "cap",
        "wave2: Barbrady = uniform cap and shades")
    check(KidArt.SHEETS["Crabtree"]!!.hairStyle == "curls" &&
        KidArt.SHEETS["Crabtree"]!!.face == "deadpan",
        "wave2: Crabtree = mane and scowl")
    check(KidArt.SHEETS["McDaniels"]!!.hairStyle == "bob" &&
        KidArt.SHEETS["McDaniels"]!!.lipstick, "wave2: McDaniels = bob and suit polish")
    check(KidArt.SHEETS["Mrs. Tweek"]!!.hairStyle == "bun", "wave2: Mrs. Tweek wears the bun")
    check(KidArt.SHEETS["Mr. Tweek"]!!.sig?.contains("coffee") == true,
        "wave2: Mr. Tweek carries the coffee sig, like his son")
    check(KidArt.SHEETS["Ned"]!!.sig?.contains("vest") == true &&
        KidArt.SHEETS["Ned"]!!.glasses, "wave2: Ned = vest and glasses, like Jimbo's counter")

    // ---------- Ned's voice: the box speaks in every line ----------
    check((LINE_BANKS["Ned"] ?: emptyList()).all { "voice box" in it || it == "Mmm." },
        "wave2: every Ned collision line comes through the voice box")

    // ---------- showdown: the new kids are real opponents ----------
    for (n in wave2Kids) {
        val dv = Showdown.dodgeFor(n)
        check(dv in 0.05..0.45, "wave2: $n has a sane dodge stat")
    }
    check(Showdown.dodgeFor("Francis") < Showdown.dodgeFor("Red"),
        "wave2: Francis is easier to hit than Red (barn physics)")

    // ---------- relations: the scripted pairs are real bonds ----------
    for (pair in WAVE2_PAIR_SCRIPTS.keys) {
        check(relationNote(pair.first(), pair.last()) != null,
            "wave2: $pair carries a relations note")
    }
    check(relationNote("Heidi", "Cartman")?.contains("ex") == true,
        "wave2: Heidi & Cartman are history, tastefully")

    // ---------- a fresh town spawns all 54 (old saves just gain them) ----------
    val engW = Engine(303)
    val sW = engW.newState()
    check(wave2.all { it in sW.agents }, "wave2: a new state seats all twelve newcomers")
    check(sW.agents.size >= 98, "wave4: the roster spawns at 98+")

    // ---------- fan sheets: params carry all 54 ----------
    val paramsFile = File(root, "../goals/south-park-interactive-town/files/sheets/tools/params.json")
    check(paramsFile.exists(), "wave2: the sheet params live where the pipeline keeps them")
    if (paramsFile.exists()) {
        val params = paramsFile.readText()
        check(KID_ORDER.all { params.contains("\"name\": \"$it\"") },
            "wave4: sheet params contain every one of the 98")
        check(params.split("\"name\":").size - 1 == 98,
            "wave4: sheet params hold exactly 98 characters")
    }
}
}

/** v0.3.0c section, extracted like the others (64 KB rule):
 *  relationship storylines — five multi-day arcs on the town's
 *  existing machinery, plus the wave-2 causer rebalance. */
private fun sectionV030c(root: String) {
// ================= v0.3.0c: relationship storylines =================
println("== v0.3.0c: relationship storylines — five arcs ==")
run {
    val engS = Engine(404)

    // ---------- the defs: five arcs, valid stage graphs ----------
    check(StoryArcs.ARCS.size == 5, "arcs: exactly five storylines")
    check(StoryArcs.ARCS.map { it.id }.distinct().size == 5, "arcs: ids distinct")
    check(StoryArcs.ARCS.map { it.minAbsDay } ==
        listOf(2, 6, 10, 14, 18), "arcs: the season is paced (gates 2/6/10/14/18)")
    for (def in StoryArcs.ARCS) {
        check(def.stages.size in 3..4, "arcs: ${def.id} runs 3-4 stages (got ${def.stages.size})")
        check(def.title.isNotBlank() && def.blurb.isNotBlank(),
            "arcs: ${def.id} is titled and blurbed")
        check(def.parties.all { it in AGENT_PROFILES } &&
            def.supporting.all { it in AGENT_PROFILES } &&
            def.core.all { it in AGENT_PROFILES },
            "arcs: ${def.id} names only real cast")
        check(def.core.containsAll(def.parties),
            "arcs: ${def.id}'s core covers its parties")
        check(def.core.all { it in def.parties + def.supporting } &&
            (def.parties + def.supporting).distinct().size ==
                (def.parties + def.supporting).size,
            "arcs: ${def.id}'s core is drawn from its cast, nobody cast twice")
        for ((i, st) in def.stages.withIndex()) {
            check(st.title.isNotBlank() && st.banner.isNotBlank() &&
                st.journalNote.isNotBlank() && st.objective.isNotBlank(),
                "arcs: ${def.id} stage $i is fully written")
            check(st.locId == null || st.locId in LOCATIONS,
                "arcs: ${def.id} stage $i lives somewhere real")
            check(st.lines.isNotEmpty() && st.lines.all { it.speaker in AGENT_PROFILES },
                "arcs: ${def.id} stage $i has a witnessable beat")
            check(st.talkLines.keys.containsAll(def.core),
                "arcs: ${def.id} stage $i gives every core person a talk beat")
            check(st.talkLines.keys.all { it in def.parties + def.supporting },
                "arcs: ${def.id} stage $i talks only for its cast")
        }
        // two endings, both fully landed, both sticking differently
        check(def.warm.id != def.solo.id, "arcs: ${def.id} has two distinct endings")
        for (oc in listOf(def.warm, def.solo)) {
            check(oc.title.isNotBlank() && oc.text.isNotBlank() &&
                oc.relationNote.isNotBlank(),
                "arcs: ${def.id}/${oc.id} lands with title, text, note")
            check(oc.callbacks.size >= 2,
                "arcs: ${def.id}/${oc.id} leaves >= 2 ambient callbacks")
            check(oc.callbacks.all { it.speaker in def.parties + def.supporting },
                "arcs: ${def.id}/${oc.id} callbacks speak in its own cast's voices")
            check(oc.bondDelta > 0, "arcs: ${def.id}/${oc.id} moves the bond up")
        }
        check(def.warm.bondDelta > def.solo.bondDelta,
            "arcs: ${def.id} rewards showing up (warm bond > solo bond)")
        check(def.warm.relationNote != def.solo.relationNote,
            "arcs: ${def.id}'s two endings leave different notes")
    }
    // the arcs are the brief's five, in order
    check(StoryArcs.ARCS.map { it.id } == listOf(
        "stan_wendy_note", "craig_tweek_pressure", "heidi_herself",
        "randy_sharon_line", "jimbo_ned_hunt"),
        "arcs: the five are the five, in season order")

    // ---------- Heidi: a solo arc, and Cartman stays history ----------
    val heidi = StoryArcs.ARC_BY_ID.getValue("heidi_herself")
    check(heidi.parties == listOf("Heidi"),
        "arcs: Heidi's arc is hers alone at the top of the bill")
    check("Cartman" !in heidi.parties + heidi.supporting + heidi.core,
        "arcs: Cartman is NOT cast in Heidi's arc — no re-pairing")
    check(heidi.supporting == listOf("Nichole", "Red", "Bebe"),
        "arcs: Heidi's circle is Nichole, Red and Bebe")
    check(relationNote("Heidi", "Cartman")?.contains("ex") == true,
        "arcs: the Heidi-Cartman note still reads as history")

    // ---------- Ned: the voice box speaks every line he's given ----------
    val nedArc = StoryArcs.ARC_BY_ID.getValue("jimbo_ned_hunt")
    val nedLines = mutableListOf<String>()
    for (st in nedArc.stages) {
        st.lines.filter { it.speaker == "Ned" }.forEach { nedLines.add(it.text) }
        st.talkLines["Ned"]?.let { nedLines.add(it) }
    }
    for (oc in listOf(nedArc.warm, nedArc.solo)) {
        oc.callbacks.filter { it.speaker == "Ned" }.forEach { nedLines.add(it.text) }
    }
    check(nedLines.size >= 10, "arcs: Ned has a real part (${nedLines.size} lines)")
    check(nedLines.all { "voice box" in it },
        "arcs: EVERY Ned line in the arc comes through the voice box")

    // ---------- a day in the life: open, beat, nudge, turn ----------
    val sA = engS.newState()
    check(StoryArcs.pageLines(sA).size > 5 && !StoryArcs.pageVisible(sA),
        "arcs: no page before the first story opens")
    sA.absDay = 1
    StoryArcs.dailyTick(sA)
    check(!StoryArcs.pageVisible(sA), "arcs: day 1 is still too early (gate 2)")
    sA.absDay = 2
    StoryArcs.dailyTick(sA)
    val defA = StoryArcs.activeDef(sA)
    check(defA?.id == "stan_wendy_note", "arcs: the note opens first")
    val recA = StoryArcs.activeRecord(sA)!!
    check(recA.stage == 0 && StoryArcs.pageVisible(sA),
        "arcs: the page exists once a story is on")
    // the talk beat plays once per person per stage
    val beat = StoryArcs.talkLine(sA, "Stan")
    check(beat != null && beat.speaker == "Stan",
        "arcs: talking to Stan surfaces his stage beat")
    check(StoryArcs.talkLine(sA, "Stan") == null,
        "arcs: the beat does not repeat within the stage")
    check(StoryArcs.talkLine(sA, "Cartman") == null,
        "arcs: bystanders have no beat in someone else's story")
    // a partial nudge is not a helped stage
    StoryArcs.noteInteraction(sA, "Stan", "talk")
    check(recA.stage !in recA.helpedStages, "arcs: one of two nudges is not a help yet")
    // the other core person via a different interaction kind counts too
    StoryArcs.noteInteraction(sA, "Wendy", "selfie")
    check(recA.stage in recA.helpedStages,
        "arcs: talk + selfie across the core = a helped stage")
    val helpedSize = recA.helpedStages.size
    StoryArcs.noteInteraction(sA, "Wendy", "gift")
    check(recA.helpedStages.size == helpedSize,
        "arcs: help credit lands exactly once per stage")
    // helped stage turns at the NEXT midnight (1 day), not instantly
    StoryArcs.dailyTick(sA)
    check(recA.stage == 0, "arcs: a helped stage still lives its day")
    sA.absDay = 3
    StoryArcs.dailyTick(sA)
    check(recA.stage == 1 && recA.stageNudges.isEmpty() &&
        recA.stageTalkShown.isEmpty(),
        "arcs: the helped stage turned over, fresh nudges for the new beat")
    check(StoryArcs.talkLine(sA, "Stan") != null,
        "arcs: the new stage has its own beat for Stan")

    // ---------- left alone, every arc still resolves (solo) ----------
    fun runArcAlone(state: GameState, wantId: String): StoryArcState {
        var guard = 0
        while (true) {
            val rec = state.storyArcs[wantId]
            if (rec?.done == true) return rec
            state.absDay++
            StoryArcs.dailyTick(state)
            if (++guard > 40) error("arc $wantId never resolved unattended")
        }
    }
    val sSolo = engS.newState()
    sSolo.absDay = 2
    StoryArcs.dailyTick(sSolo)
    val soloRec = runArcAlone(sSolo, "stan_wendy_note")
    val soloDays = soloRec.finishedAbsDay - soloRec.startedAbsDay
    check(soloDays == 8, "arcs: unattended, 4 stages x 2 days = 8 days (got $soloDays)")
    check(soloRec.outcomeId == "stan_wendy_solo",
        "arcs: an unwitnessed arc lands its solo ending")
    check((sSolo.npcBonds["Stan|Wendy"] ?: 0) == 1,
        "arcs: the solo ending still moves the bond (+1)")
    check(sSolo.lifeText["arcNote:Stan|Wendy"]?.contains("themselves") == true,
        "arcs: the solo ending writes its permanent relation note")
    check(StoryArcs.relationNoteFor(sSolo, "Wendy", "Stan") ==
        sSolo.lifeText["arcNote:Stan|Wendy"],
        "arcs: the Journal's note lookup reads the arc override (either way round)")
    check(sSolo.agents["Stan"]!!.memories.any { it.contains("The Note in the Locker") },
        "arcs: the ending sticks in the pair's memories")
    // the callbacks are live, in the pair's own voices
    var cbHits = 0
    repeat(30) { i ->
        val cb = StoryArcs.ambientCallback(sSolo, "Stan", "Wendy",
            kotlin.random.Random(i.toLong()))
        if (cb != null && cb.speaker in setOf("Stan", "Wendy")) cbHits++
    }
    check(cbHits == 30, "arcs: a finished pair's callbacks always answer (got $cbHits)")
    check(StoryArcs.ambientCallback(sSolo, "Stan", "Kyle",
        kotlin.random.Random(1)) == null,
        "arcs: non-pairs get no callbacks from someone else's ending")
    // journal: done arc shows its outcome in one line
    val soloPage = StoryArcs.pageLines(sSolo)
    check(soloPage.any { it.contains("Together") && it.contains("eventually") },
        "arcs: the Journal prints the solo outcome line")

    // ---------- fully nudged, every arc lands warm — and faster ----------
    fun runArcHelped(state: GameState, wantId: String): StoryArcState {
        var guard = 0
        while (true) {
            val def = StoryArcs.ARC_BY_ID.getValue(wantId)
            val rec = state.storyArcs[wantId]
            if (rec?.done == true) return rec
            if (StoryArcs.activeDef(state)?.id == wantId && rec != null) {
                for (n in def.core) StoryArcs.noteInteraction(state, n, "talk")
            }
            state.absDay++
            StoryArcs.dailyTick(state)
            if (++guard > 40) error("arc $wantId never resolved when helped")
        }
    }
    val sWarm = engS.newState()
    sWarm.absDay = 2
    StoryArcs.dailyTick(sWarm)
    val swStanPts = sWarm.friendship["Stan"] ?: 0
    val warmRec = runArcHelped(sWarm, "stan_wendy_note")
    check(warmRec.finishedAbsDay - warmRec.startedAbsDay == 4,
        "arcs: fully nudged, 4 stages x 1 day = 4 days (twice as fast)")
    check(warmRec.outcomeId == "stan_wendy_warm",
        "arcs: a witnessed arc lands its warm ending")
    check((sWarm.npcBonds["Stan|Wendy"] ?: 0) == 3,
        "arcs: the warm ending moves the bond +3")
    check((sWarm.friendship["Stan"] ?: 0) == swStanPts + 3 &&
        (sWarm.friendship["Wendy"] ?: 0) == 3,
        "arcs: the warm ending thanks the player in friendship (+3 each)")
    check(StoryArcs.pageLines(sWarm).any { it.contains("note is in his pocket") },
        "arcs: the Journal prints the warm outcome line")

    // ---------- a strong pre-existing bond can carry an ending ----------
    val sBond = engS.newState()
    sBond.absDay = 2
    StoryArcs.dailyTick(sBond)
    sBond.npcBonds["Stan|Wendy"] = 7
    val bondRec = runArcAlone(sBond, "stan_wendy_note")
    check(bondRec.outcomeId == "stan_wendy_warm",
        "arcs: a pair already close (bond 7) lands warm even unwitnessed")
    check((sBond.npcBonds["Stan|Wendy"] ?: 0) == 10,
        "arcs: the bond clamps at the town's ceiling (7 + 3 = 10)")

    // ---------- the whole season: five arcs, sequential, all resolve ----------
    val sSeason = engS.newState()
    var seasonGuard = 0
    while (!StoryArcs.allDone(sSeason) && seasonGuard < 200) {
        sSeason.absDay++
        StoryArcs.dailyTick(sSeason)
        seasonGuard++
        check(StoryArcs.ARCS.count {
            val r = sSeason.storyArcs[it.id]; r != null && !r.done } <= 1,
            "arcs: never more than one story on stage")
    }
    check(StoryArcs.allDone(sSeason),
        "arcs: all five resolve unattended inside 200 days (took $seasonGuard)")
    check(sSeason.storyArcs.size == 5,
        "arcs: the season leaves exactly five records (bounded state)")
    check(StoryArcs.ARCS.all { def ->
        sSeason.storyArcs[def.id]!!.outcomeId == def.solo.id },
        "arcs: a fully unattended season lands five solo endings")
    check(StoryArcs.ARCS.all { def ->
        def.primaryPairs.all { pair ->
            sSeason.lifeText["arcNote:${Threads.pairKey(pair.first(), pair.last())}"] != null } },
        "arcs: every ending wrote its permanent relation note")
    check(StoryArcs.pageLines(sSeason).count { it.startsWith("✓") } == 5,
        "arcs: the Journal shows five finished stories")

    // ---------- persistence: mid-arc saves & era saves ----------
    val sMid = engS.newState()
    sMid.absDay = 2
    StoryArcs.dailyTick(sMid)
    StoryArcs.noteInteraction(sMid, "Stan", "talk")
    StoryArcs.noteInteraction(sMid, "Wendy", "talk")
    val docMid = encodeGameState(sMid)
    val sBack = decodeGameState(docMid)
    val recBack = sBack.storyArcs["stan_wendy_note"]
    check(recBack != null && recBack.stage == 0 &&
        recBack.helpedStages == setOf(0) && !recBack.done,
        "arcs: a mid-arc save round-trips stage + help credit")
    check(StoryArcs.activeDef(sBack)?.id == "stan_wendy_note",
        "arcs: the restored save resumes its story on stage")
    val sEra = decodeGameState(emptyMap())
    check(sEra.storyArcs.isEmpty(),
        "arcs: an era save (no storyArcs key) starts the stories fresh")
    val docBogus = mapOf<String, Any?>("storyArcs" to listOf(
        mapOf<String, Any?>("arcId" to "not_a_real_arc", "stage" to 2L)))
    check(decodeGameState(docBogus).storyArcs.isEmpty(),
        "arcs: invented arc ids are dropped at load, never trusted")

    // ---------- wave-2 causers: the rebalance pins ----------
    check(SHENANIGANS.size == 10, "arcs: the random pool is still the ten defs")
    val wave2 = listOf("Heidi", "Nichole", "Red", "Kevin", "Francis", "DogPoo",
        "McDaniels", "Barbrady", "Crabtree", "Mr. Tweek", "Mrs. Tweek", "Ned")
    for (n in wave2) {
        check(SHENANIGANS.any { n in it.causers },
            "causers: $n is eligible in at least one event def")
    }
    fun causersOf(id: String) = SHENANIGAN_BY_ID.getValue(id).causers
    check("McDaniels" in causersOf("upside_down_day") &&
        "Crabtree" in causersOf("upside_down_day"),
        "causers: the Mayor declares Upside-Down Day; Crabtree strands it")
    check("Barbrady" in causersOf("mole_panic") &&
        "Barbrady" in causersOf("coon_sightings"),
        "causers: Barbrady investigates the moles AND the Coon")
    check("Ned" in causersOf("tegridy_takeover"),
        "causers: Ned rides with the Tegridy takeover")
    check("Heidi" in causersOf("silent_challenge") &&
        "Nichole" in causersOf("pirate_week") &&
        "Red" in causersOf("chinpo_craze") && "Kevin" in causersOf("chinpo_craze"),
        "causers: the wave-2 kids land in the school beats")
    check(SHENANIGANS.all { it.causers.all { c -> c in AGENT_PROFILES } },
        "causers: every credited causer is real cast")
    check(!Mystery.ARC_CHAPTERS.any { ch ->
        wave2.any { it in ch.causers && it !in
            listOf("Jimbo", "Kenny", "Wendy", "Cartman", "Randy", "Kyle", "Tweek",
                "Towelie", "Stephen", "Butters", "Stan") } },
        "causers: the mystery chapters' credits are untouched")

    // ---------- wiring ----------
    val storiesSrc = File(root, "src/com/hunt3r/southparktown/Stories.kt").readText()
    val engineSrcS = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val journalSrcS = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val gameActSrcS = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val photosSrcS = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
    val prefsSrcS = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    check(!storiesSrc.contains("import android"),
        "arcs: Stories.kt stays pure Kotlin (JVM-testable)")
    check(engineSrcS.contains("StoryArcs.dailyTick") &&
        engineSrcS.contains("StoryArcs.noteInteraction") &&
        engineSrcS.contains("StoryArcs.ambientCallback"),
        "arcs: the engine ticks arcs at midnight, hears talk/gift nudges, tells callbacks")
    check(File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
            .contains("StoryArcs.talkLine") &&
        gameActSrcS.contains("TalkGate.owedLines"),
        "arcs: GameActivity plays the talk beats (via TalkGate)")
    check(photosSrcS.contains("StoryArcs.noteInteraction"),
        "arcs: selfies nudge storylines")
    check(journalSrcS.contains("📖 STORY ARCS") &&
        journalSrcS.contains("StoryArcs.pageLines") &&
        journalSrcS.contains("StoryArcs.relationNoteFor"),
        "arcs: the Journal renders the ARCS page + the permanent notes")
    check(prefsSrcS.contains("\"storyArcs\" to"),
        "arcs: the save doc carries the arcs additively")
    check(!storiesSrc.contains("arc_ch") && !storiesSrc.contains("Mystery."),
        "arcs: the storylines never touch the mystery's machinery")
}
}

/** v0.3.0d section: YOUR HOUSE — the 27th location. The place
 *  itself in every registry, the graph, the privacy invariant
 *  (nobody is ever inside but you), the doorstep, the bed's
 *  equivalence with the natural midnight path, the derived
 *  decor/shelf/mail, and the no-new-save-keys proof. */
private fun sectionV030d(root: String) {
// ================= v0.3.0d: your house =================
    run {
        val mine = LOCATIONS[YOUR_HOUSE]
        check(mine != null && mine!!.kind == "house" && mine.name == "Your House",
            "house: the 27th location is Your House, a house")
        check(mine?.gx == 77 && mine?.gy == 80,
            "house: east end of the residential row, past Kyle's")
        check(INTERIORS[YOUR_HOUSE]?.theme == "home",
            "house: its interior is a home")
        check(LOC_PALETTES[YOUR_HOUSE] != null &&
            LOC_ART_DETAILS[YOUR_HOUSE]?.size == 3 &&
            INTERIOR_ART_DETAILS[YOUR_HOUSE]?.size == 3 &&
            LOC_LIGHT[YOUR_HOUSE]?.warmthHex == "#ffd2a1" &&
            LOC_LIGHT_DETAILS[YOUR_HOUSE]?.size == 2 &&
            LOC_SEASON_DETAILS[YOUR_HOUSE]?.size == 4 &&
            LORE_LOC_ALIASES[YOUR_HOUSE] == "The New Kid's Residence",
            "house: palette, parity, interior, light, season and lore " +
                "registries all carry the address")
        // the graph: in through Kyle's street, back out the same way
        check("YourHouse" in (EXITS["KyleHouse"] ?: emptyList()) &&
            EXITS[YOUR_HOUSE] == listOf("KyleHouse"),
            "house: Kyle's street is the way in and the way out")
        val seen = mutableSetOf("BusStop")
        val queue = ArrayDeque<String>(); queue.add("BusStop")
        while (queue.isNotEmpty()) {
            val cur = queue.removeFirst()
            for (nxt in EXITS[cur] ?: emptyList()) {
                if (seen.add(nxt)) queue.add(nxt)
            }
        }
        check(seen.size == 27 && YOUR_HOUSE in seen,
            "house: every one of the 27 locations still walks from the Bus Stop")
        val sceneSrc = File(root,
            "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        check(sceneSrc.contains("\"THE NEW KID\"") &&
            sceneSrc.contains("\"WELCOME-ISH\""),
            "house: the mailbox is lettered for its owner, the mat is honest")

        // ---------- THE PRIVACY INVARIANT ----------
        check(!CharacterSystem.npcInside(YOUR_HOUSE),
            "privacy: npcInside(YourHouse) is false by construction")
        check(CharacterSystem.npcInside("KennysHouse") &&
            !CharacterSystem.npcInside("MainStreet"),
            "privacy: the special case touches nothing else")
        val eng = Engine(7)
        val st = eng.newState()
        val meA = eng.player(st)
        meA.location = YOUR_HOUSE; meA.destination = YOUR_HOUSE
        val stan = st.agents["Stan"]!!
        stan.location = YOUR_HOUSE; stan.destination = YOUR_HOUSE
        stan.waypoints.clear(); stan.asleep = false
        st.playerInside = false
        check(eng.presentWithPlayer(st).any { it.name == "Stan" },
            "privacy: a friend at YourHouse stands on your DOORSTEP — talkable")
        st.playerInside = true
        check(eng.presentWithPlayer(st).isEmpty(),
            "privacy: step inside and the room is yours alone")
        // no system aims an NPC at your interior or address:
        // cast goals, generated visitors and residents alike
        var goalAimed = false
        for (key in AGENT_PROFILES.keys) for (cycle in 0..5) {
            if (NpcGoals.goalFor(key, cycle).locId == YOUR_HOUSE) goalAimed = true
        }
        check(!goalAimed, "privacy: no cast goal ever targets your house")
        var genAimed = false
        for (key in listOf("20261001", "20261005", "20261009", "20261013",
            "20261102", "20261225")) {
            for (t in listOf(480, 720, 1080, 1260, 60)) {
                if (VisitorSystem.visitorsFor(key, t).any { it.locId == YOUR_HOUSE })
                    genAimed = true
                if (VisitorSystem.residentsNow(t, 1, t < 420 || t >= 1260, 3, key)
                        .any { it.locId == YOUR_HOUSE }) genAimed = true
            }
        }
        check(!genAimed, "privacy: no visitor or resident is ever placed at your house")
        // a full lived day with every friend beelining for your
        // most-visited place still leaves the interior empty
        val eng2 = Engine(11)
        val day = eng2.newState()
        day.locVisits[YOUR_HOUSE] = 50
        for ((n, _) in day.friendship) day.friendship[n] = 100
        val me2 = eng2.player(day)
        me2.location = YOUR_HOUSE; me2.destination = YOUR_HOUSE
        day.playerInside = true
        repeat(96) { eng2.inGameTick(day) }
        check(eng2.presentWithPlayer(day).isEmpty(),
            "privacy: a whole day of best friends, and your room stayed yours")

        // ---------- THE BED ----------
        val eA = Engine(42); val a = eA.newState(); a.timeMin = 21 * 60
        val eB = Engine(42); val b = eB.newState(); b.timeMin = 21 * 60
        val ticks = eA.sleepUntilMorning(a)
        repeat(ticks) { eB.inGameTick(b) }
        check(ticks == 40 && a.timeMin == House.WAKE_MIN && b.timeMin == House.WAKE_MIN,
            "bed: 9 PM sleeps 40 ticks to 7 AM (got $ticks)")
        check(a.absDay == 1 && b.absDay == 1 && a.todayKey == b.todayKey &&
            a.gameYear == b.gameYear && a.gameMonth == b.gameMonth &&
            a.gameDay == b.gameDay,
            "bed: the slept night lands on the SAME morning as the lived night")
        check(a.dailyGain.isEmpty() && a.questCounters.isEmpty() &&
            a.agents.values.none { it.asleep },
            "bed: the rollover cleared the same daily books as midnight")
        check(a.friendship == b.friendship,
            "bed: overnight friendship upkeep matches the natural path exactly")
        val eC = Engine(42); val cc = eC.newState(); cc.timeMin = 3 * 60
        val tC = eC.sleepUntilMorning(cc)
        check(tC == 16 && cc.absDay == 0 && cc.timeMin == House.WAKE_MIN,
            "bed: 3 AM just walks to morning, no phantom day")
        val eD = Engine(42); val dd = eD.newState(); dd.timeMin = House.WAKE_MIN
        check(eD.sleepUntilMorning(dd) == 0 && dd.absDay == 0,
            "bed: already morning is a no-op")
        val eE = Engine(42); val ee = eE.newState(); ee.timeMin = 6 * 60 + 40
        eE.sleepUntilMorning(ee)
        check(ee.timeMin == House.WAKE_MIN && ee.absDay == 0,
            "bed: 6:40 AM snaps to 7:00 with no rollover")

        // ---------- DECOR (pure derivation, no save keys) ----------
        val dv = Engine(3).newState()
        check(House.decorFor(dv).isEmpty() && House.decorTokensFor(dv).isEmpty(),
            "decor: a fresh house is honestly bare")
        dv.episodes.add(EpisodeRecord("e@x", "event", "bus_stop_blizzard",
            "t", "t", "t", emptyList(), "x", "1/1", finished = true))
        check(House.decorFor(dv) == setOf("episode_keepsake"),
            "decor: a finished episode hangs its poster")
        dv.photoFeats.add(Photos.PHOTO_FEATS[0].id)
        dv.gameFeats.add(Minigames.GAME_FEATS[0].id)
        check(House.decorFor(dv) == setOf("episode_keepsake", "photo_strip",
            "game_trophy"), "decor: photo and game feats dress the room")
        check(House.decorTokensFor(dv) == setOf("episode-poster",
            "photo-strip", "game-trophy"), "decor: ids map to art tokens")
        for ((branch, want) in listOf("truth" to "mystery_truth",
            "silent" to "mystery_silent", "town" to "mystery_town")) {
            val mv = Engine(3).newState()
            mv.arcRetired = true; mv.arcBranch = branch
            val got = House.decorFor(mv)
            check(got == setOf(want),
                "decor: the $branch ending leaves exactly its own mark ($got)")
        }
        val interiorSrc = File(root,
            "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
        check(House.DECOR.size == 17 &&
            House.DECOR.all { interiorSrc.contains("decor: ${it.token}") } &&
            House.DECOR.map { it.token }.toSet().size == 17,
            "decor: all sixteen earned pieces are drawn, token for token " +
                "(eight through v0.4.0d, the four season-finale pieces of v0.5.0h, " +
                "v0.7.0b's town map, v0.7.0d's bee trophy, v0.8.0d's " +
                "yearbook shelf, and v0.9.0c's ribbon display)")
        check(!File(root, "src/com/hunt3r/southparktown/House.kt")
            .readText().contains("import android"),
            "decor: House.kt is pure Kotlin (suite-testable)")

        // ---------- SHELF + MAIL + REPORT ----------
        val sv = Engine(3).newState()
        check(House.shelfSlots(sv).size == House.SHELF_SLOTS &&
            House.shelfSlots(sv).all { it == null },
            "shelf: twelve honest empty slots on day one")
        sv.collected.add(COLLECTIBLES[0].id); sv.collected.add(COLLECTIBLES[2].id)
        val slots = House.shelfSlots(sv)
        check(slots[0] == COLLECTIBLES[0].icon && slots[1] == null &&
            slots[2] == COLLECTIBLES[2].icon,
            "shelf: found trophies stand in collection order, gaps stay gaps")
        sv.photoFeats.addAll(Photos.PHOTO_FEATS.map { it.id })
        sv.gameFeats.addAll(Minigames.GAME_FEATS.map { it.id })
        check(House.featCups(sv) == House.MAX_CUPS &&
            House.featOverflow(sv) == Photos.PHOTO_FEATS.size +
                Minigames.GAME_FEATS.size - House.MAX_CUPS,
            "shelf: feat cups cap at six and the rest become a proud number")
        val mv2 = Engine(3).newState()
        mv2.friendship["Kyle"] = 50
        var notes = 0; var junk = 0; var empty = 0
        for (d in 0..39) {
            mv2.absDay = d
            val m1 = House.mailLine(mv2); val m2 = House.mailLine(mv2)
            check(m1 == m2, "mail: day $d's mail is deterministic")
            when {
                m1 == null -> empty++
                m1.contains("Junk mail") -> junk++
                else -> notes++
            }
        }
        check(notes > 0 && junk > 0 && empty > 0,
            "mail: friends write, junk arrives, and some days the box is empty " +
                "($notes/$junk/$empty)")
        check(House.newEvents(listOf("a", "b"), listOf("a", "b", "c")) ==
            listOf("c"), "report: overnight events diff cleanly")
        val big = (1..40).map { "e$it" }
        check(House.newEvents(big, big.drop(10) + listOf("n1", "n2")) ==
            listOf("n1", "n2"), "report: the diff survives the 40-cap front trim")
        check(House.newEvents(big, big).isEmpty(), "report: no news is no lines")
        val repState = Engine(3).newState()
        val arcId = StoryArcs.ARCS[0].id
        repState.storyArcs[arcId] = StoryArcState(arcId, stage = 3, done = true,
            outcomeId = StoryArcs.ARCS[0].warm.id)
        val rep = House.morningReport(repState,
            listOf("🚶 Stan took off toward Kyle's House.", "🌅 dup"),
            mapOf(arcId to (1 to false)), 0, false, "📬 test mail")
        check(rep.first().startsWith("🌅") &&
            rep.any { it.contains("Stan took off") } &&
            rep.none { it.contains("🌅 dup") } &&
            rep.any { it.contains("warm ending") } &&
            rep.any { it.contains("test mail") },
            "report: date, overnight events (minus the rollover's own line), " +
                "arc endings and mail all make the morning page")
        val repState2 = Engine(3).newState(); repState2.arcChapter = 2
        check(House.morningReport(repState2, emptyList(), emptyMap(), 0,
            false, null).any { it.contains("chapter 2 of 5") },
            "report: a mystery chapter that aired overnight is noted, spoiler-free")
        repState2.arcRetired = true
        check(House.morningReport(repState2, emptyList(), emptyMap(), 0,
            false, null).any { it.contains("case is closed") },
            "report: the case closing overnight is noted, spoiler-free")

        // ---------- SAVES: the house derives, nothing is stored ----------
        val doc = encodeGameState(sv)
        check(doc.keys.none { it.contains("house", ignoreCase = true) },
            "save: v0.3.0d writes NO house keys — the room is derived, not stored")
        val svBack = decodeGameState(doc)
        check(House.decorFor(svBack) == House.decorFor(sv) &&
            House.shelfSlots(svBack) == House.shelfSlots(sv),
            "save: the derived house survives the round trip intact")
        val hv = Engine(5).newState()
        val hp = hv.agents.values.first { it.isPlayer }
        hp.location = YOUR_HOUSE; hp.destination = YOUR_HOUSE
        hv.playerInside = true
        val hBack = decodeGameState(encodeGameState(hv))
        val hpBack = hBack.agents.values.first { it.isPlayer }
        check(hpBack.location == YOUR_HOUSE && hBack.playerInside,
            "save: going home, and being in it, save like anywhere else")

        // ---------- WIRING ----------
        val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
        val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        val engSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(gvSrc.contains("drawHouseFixtures") &&
            gvSrc.contains("Hit(\"fixture\"") && gvSrc.contains("\"fixture\""),
            "wiring: the four fixtures draw and route taps")
        check(gaSrc.contains("\"fixture\" ->") && gaSrc.contains("sleepUntilMorning") &&
            gaSrc.contains("House.morningReport") && gaSrc.contains("House.knockLine") &&
            gaSrc.contains("putExtra(\"section\", \"album\")"),
            "wiring: bed, shelf, album and mirror all answer their taps")
        check(File(root, "src/com/hunt3r/southparktown/JournalActivity.kt")
            .readText().contains("getStringExtra(\"section\")"),
            "wiring: the Journal can open on the album shelf")
        check(engSrc.contains("fun sleepUntilMorning") &&
            engSrc.contains("it.id != YOUR_HOUSE"),
            "wiring: the bed sleeps via the natural tick; the rain dash skips your porch")
    }
}

/** v0.3.0e section: SKY PARITY — the sky as data (SkyState):
 *  the moon's one formula, the three specials at their pinned
 *  frequencies over a simulated year, the rollover record and
 *  the morning-after buzz, the wish at the pond, the fishing
 *  hook, the ambience hush, and photos that remember their sky. */
private fun sectionV030e(root: String) {
    println("== v0.3.0e: sky parity — SkyState, specials, the wish ==")
    run {
        // canonical alignment for the simulated year: absDay a
        // is calendar day-of-year a+1 (a leap-free year).
        fun monthOfDoy(doy: Int): Int {
            var m = 1; var rest = doy
            val lens = intArrayOf(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
            while (rest > lens[m - 1]) { rest -= lens[m - 1]; m++ }
            return m
        }
        fun seasonOfAbs(a: Int): Season = seasonFor(monthOfDoy(a + 1))
        fun seasonOfAbsShifted(a: Int, k: Int): Season =
            seasonFor(monthOfDoy(((a + k) % 365) + 1))

        // ---------- THE MOON: one formula, no drift ----------
        check((0..58).all { SkyState.moonPhase(it) == TownLife.moonPhase(it) },
            "sky: SkyState owns the moon — TownLife's #44 formula, delegated, identical")
        check((-90..400).all { SkyState.moonPhase(it) in 0..7 },
            "sky: the phase stays in 0..7 for any ordinal")
        check(SkyState.moonPhase(0) == 0 && SkyState.moonPhase(17) == 4,
            "sky: absDay 0 is a new moon, absDay 17 is full (the 29-day cycle)")
        check(SkyState.MOONLIGHT.size == 8 &&
            SkyState.moonlight(17) == 1.0f &&
            SkyState.moonlight(0) < SkyState.moonlight(9) &&
            SkyState.moonlight(9) < SkyState.moonlight(17),
            "sky: moonlight climbs new < quarter < full, and full is 1.0")
        check(SkyState.moonName(17) == "full moon" &&
            SkyState.MOON_NAMES.size == 8,
            "sky: every phase has a name")

        // ---------- PURITY ----------
        val nowA = SkyState.now(200, 23 * 60, "sunny", Season.WINTER)
        val nowB = SkyState.now(200, 23 * 60, "sunny", Season.WINTER)
        check(nowA == nowB && nowA.phase == SkyState.moonPhase(200),
            "sky: same inputs, same sky — SkyState is a pure function")

        // ---------- AURORA: rare, winter, clear ----------
        var winterDays = 0; var auroraEligible = 0
        for (a in 0..363) {
            if (seasonOfAbs(a) == Season.WINTER) {
                winterDays++
                if (SkyState.auroraDate(a)) auroraEligible++
            }
        }
        check(winterDays in 88..92,
            "sky: the simulated winter runs ~90 days (got $winterDays)")
        check(auroraEligible == 7,
            "sky: exactly 7 aurora-eligible nights in a canonical winter (got $auroraEligible)")
        check((0..273 step 7).all { k ->
            (k until k + 90).count { SkyState.auroraDate(it) } in 5..7
        }, "sky: any 90-day window holds 5-7 eligible nights — rare, not mythical")
        check(SkyState.auroraTonight(5, "sunny", Season.WINTER) &&
            !SkyState.auroraTonight(6, "sunny", Season.WINTER) &&
            !SkyState.auroraTonight(5, "cloudy", Season.WINTER) &&
            !SkyState.auroraTonight(5, "sunny", Season.SUMMER),
            "sky: aurora needs an eligible date, winter, and a CLEAR sky")
        val sAur = Engine(3).newState()
        sAur.gameMonth = 1; sAur.weatherId = "sunny"; sAur.absDay = 5
        check(TownLife.auroraTonight(sAur),
            "sky: TownLife's #49 aurora reads SkyState now (the legacy pin holds)")
        check(SkyState.auroraIntensity(23) == 1.0f &&
            SkyState.auroraIntensity(12) == 0f &&
            SkyState.auroraIntensity(21) < SkyState.auroraIntensity(23) &&
            SkyState.auroraIntensity(6) < SkyState.auroraIntensity(0),
            "sky: the aurora burns brightest in the long dark middle of the night")
        check(SkyState.now(5, 12 * 60, "sunny", Season.WINTER).special == SkyState.NONE &&
            SkyState.now(5, 23 * 60, "sunny", Season.WINTER).special == SkyState.AURORA &&
            SkyState.now(5, 23 * 60, "sunny", Season.WINTER).auroraIntensity > 0f,
            "sky: an aurora date shows nothing at noon and curtains at 23:00")

        // ---------- METEORS: 9 fixed nights a year ----------
        val metCounts = mutableMapOf<Season, Int>()
        for (a in 0..363) {
            val s = seasonOfAbs(a)
            if (SkyState.meteorDate(a, s)) metCounts[s] = (metCounts[s] ?: 0) + 1
        }
        check(metCounts[Season.SPRING] == 2 && metCounts[Season.SUMMER] == 3 &&
            metCounts[Season.FALL] == 2 && metCounts[Season.WINTER] == 2 &&
            metCounts.values.sum() == 9,
            "sky: exactly 9 meteor nights a year — 2/3/2/2 by season (got $metCounts)")
        check(listOf(40, 100, 200, 300).all { k ->
            (0..363).count { a ->
                SkyState.meteorDate(a, seasonOfAbsShifted(a, k))
            } in 8..10
        }, "sky: shifted years still get their handful of shower nights")
        check(SkyState.meteorNow(194, 22 * 60, "sunny", Season.SUMMER) &&
            !SkyState.meteorNow(194, 22 * 60, "cloudy", Season.SUMMER) &&
            !SkyState.meteorNow(194, 12 * 60, "sunny", Season.SUMMER) &&
            !SkyState.meteorNow(200, 22 * 60, "sunny", Season.SUMMER),
            "sky: meteors need their date, a clear sky, and the night band")

        // ---------- HARVEST MOON: one autumn full moon ----------
        val harvestNights = (0..363).filter {
            SkyState.isHarvestMoon(it, seasonOfAbs(it))
        }
        check(harvestNights.size == 4 &&
            harvestNights.maxOrNull()!! - harvestNights.minOrNull()!! == 3 &&
            harvestNights.all { SkyState.moonPhase(it) == 4 },
            "sky: exactly one harvest block per autumn — 4 full nights in a row (got $harvestNights)")
        check(listOf(40, 300).all { k ->
            (0..363).count { a ->
                SkyState.isHarvestMoon(a, seasonOfAbsShifted(a, k))
            } in 3..6
        }, "sky: shifted autumns still get exactly one harvest moon (3-6 nights)")
        val hDay = harvestNights.first()
        check(SkyState.specialAt(hDay, 19 * 60, "cloudy", Season.FALL) == SkyState.HARVEST &&
            SkyState.specialAt(hDay, 12 * 60, "cloudy", Season.FALL) == SkyState.NONE,
            "sky: the harvest moon is up from dusk, never at noon")
        check(!SkyState.isHarvestMoon(hDay, Season.WINTER),
            "sky: the same full moon in winter is just a full moon")

        // ---------- specials never show through weather ----------
        check(SkyState.specialAt(5, 23 * 60, "blizzard", Season.WINTER) == SkyState.NONE &&
            SkyState.dateSpecial(194, "cloudy", Season.SUMMER) == SkyState.NONE &&
            SkyState.dateSpecial(194, "sunny", Season.SUMMER) == SkyState.METEOR &&
            SkyState.dateSpecial(5, "sunny", Season.WINTER) == SkyState.AURORA,
            "sky: a special nobody could see is a special that didn't happen")

        // ---------- THE RECORD: rollover -> buzz -> report ----------
        val eSky = Engine(7)
        val sMet = eSky.newState()
        sMet.gameYear = 2026; sMet.gameMonth = 7; sMet.gameDay = 15
        sMet.absDay = 194; sMet.weatherId = "sunny"; sMet.todayKey = "20260715"
        eSky.onNewDay(sMet)
        check(sMet.absDay == 195 && sMet.lifeText[SkyState.LAST_SKY_KEY] == "meteor" &&
            sMet.life[SkyState.LAST_SKY_DAY_KEY] == 195 &&
            SkyState.buzzKind(sMet) == "meteor",
            "sky: the rollover records a clear meteor night against the new day")
        check(House.morningReport(sMet, emptyList(), emptyMap(), 0, false, null)
            .any { it.contains("While you slept") && it.contains("meteors") },
            "sky: the morning report mourns the sky you slept through")
        val sCloud = eSky.newState()
        sCloud.gameYear = 2026; sCloud.gameMonth = 7; sCloud.gameDay = 15
        sCloud.absDay = 194; sCloud.weatherId = "cloudy"; sCloud.todayKey = "20260715"
        eSky.onNewDay(sCloud)
        check(sCloud.lifeText[SkyState.LAST_SKY_KEY] == null &&
            SkyState.buzzKind(sCloud) == null,
            "sky: a clouded-out shower leaves no record and no buzz")
        val sPlain = eSky.newState()
        sPlain.gameYear = 2026; sPlain.gameMonth = 7; sPlain.gameDay = 20
        sPlain.absDay = 200; sPlain.weatherId = "sunny"; sPlain.todayKey = "20260720"
        eSky.onNewDay(sPlain)
        check(sPlain.lifeText[SkyState.LAST_SKY_KEY] == null &&
            !House.morningReport(sPlain, emptyList(), emptyMap(), 0, false, null)
                .any { it.contains("While you slept") },
            "sky: a plain night records nothing and the report stays quiet")

        // ---------- THE BUZZ: topics debate the sky ----------
        val eBuzz = Engine(11)
        val sBuzz = eBuzz.newState()
        sBuzz.absDay = 195; sBuzz.weatherId = "sunny"
        sBuzz.lifeText[SkyState.LAST_SKY_KEY] = "meteor"
        sBuzz.life[SkyState.LAST_SKY_DAY_KEY] = 195
        val skyPool = SkyTopics.topicsFor("Stan", "meteor").toSet()
        val draws = (1..24).map { eBuzz.weightedTopicFor(sBuzz, "Stan") }
        check(draws.all { it in skyPool },
            "sky: the morning after, Stan's topics ARE the meteor debate")
        check(skyPool.size == 3 &&
            SkyTopics.topicsFor("Kyle", "aurora").any { it.contains("DIAGRAM") } &&
            SkyTopics.topicsFor("Tweek", "meteor").size == 4,
            "sky: the buzz mixes the generic debate with each kid's own position")
        val allSkyWriting = (SKY_WITNESS_LINES.values.flatten() +
            SkyTopics.GENERIC.values.flatten() +
            SkyTopics.BY_KID.values.flatMap { it.values.flatten() })
        check(allSkyWriting.none {
            val l = it.lowercase()
            "clue" in l || "chaos" in l || "sleepwalk" in l || "case" in l
        }, "sky: the sky writing NEVER touches the pond case — different subject, full stop")
        check((SKY_WITNESS_LINES[SkyState.AURORA] ?: emptyList()).none {
            "pond" in it.lowercase()
        } && SKY_WITNESS_LINES.values.all { it.size >= 3 },
            "sky: aurora witnesses talk sky, not water — and every kind has 3+ witnesses")

        // ---------- LOOK: the sky gets its line ----------
        val eLook = Engine(5)
        val sLook = eLook.newState()
        sLook.gameMonth = 1; sLook.absDay = 5; sLook.weatherId = "sunny"
        sLook.timeMin = 23 * 60; sLook.playerInside = false
        check(eLook.playerLook(sLook, Season.WINTER).contains("🌌"),
            "sky: Look names the aurora on its night")
        sLook.timeMin = 12 * 60
        check(!eLook.playerLook(sLook, Season.WINTER).contains("🌌"),
            "sky: Look stays quiet about the sky at noon")

        // ---------- 🌠 THE WISH ----------
        val eWish = Engine(13)
        val sWish = eWish.newState()
        sWish.gameMonth = 7; sWish.absDay = 194; sWish.weatherId = "sunny"
        sWish.timeMin = 22 * 60; sWish.playerInside = false
        sWish.agents.values.forEach { if (!it.isPlayer) it.location = "MainStreet" }
        val wPlayer = sWish.agents.values.first { it.isPlayer }
        wPlayer.location = "StarksPond"; wPlayer.destination = "StarksPond"
        val wish1 = eWish.pondWish(sWish)
        check(wish1 != null && wish1.contains("Wish #1") && wishCount(sWish) == 1,
            "wish: a meteor night at the pond takes your first wish")
        val wishAgain = eWish.pondWish(sWish)
        check(wishAgain != null && wishAgain.contains("already wished") &&
            wishCount(sWish) == 1,
            "wish: one per night — the pond enforces it politely")
        sWish.absDay = 195 // the next shower night (residue 13)
        val wish2 = eWish.pondWish(sWish)
        check(wish2 != null && wish2.contains("Wish #2") && wishCount(sWish) == 2,
            "wish: a new night, a new wish — the tally is forever")
        val sWishStan = eWish.newState()
        sWishStan.gameMonth = 7; sWishStan.absDay = 194
        sWishStan.weatherId = "sunny"; sWishStan.timeMin = 22 * 60
        sWishStan.agents.values.forEach { if (!it.isPlayer) it.location = "MainStreet" }
        val swp = sWishStan.agents.values.first { it.isPlayer }
        swp.location = "StarksPond"; swp.destination = "StarksPond"
        sWishStan.agents["Stan"]?.let {
            it.location = "StarksPond"; it.destination = "StarksPond"
        }
        check(eWish.pondWish(sWishStan)?.contains("Stan") == true,
            "wish: whoever's at the pond wishes too — out loud, usually")
        fun wishGate(mut: (GameState) -> Unit): Boolean {
            val g = eWish.newState()
            g.gameMonth = 7; g.absDay = 194; g.weatherId = "sunny"
            g.timeMin = 22 * 60; g.playerInside = false
            val p = g.agents.values.first { it.isPlayer }
            p.location = "StarksPond"; p.destination = "StarksPond"
            mut(g)
            return eWish.pondWish(g) == null
        }
        check(wishGate { it.timeMin = 12 * 60 }, "wish: no wishes at noon")
        check(wishGate { it.weatherId = "cloudy" }, "wish: no wishes through cloud")
        check(wishGate { it.playerInside = true }, "wish: no wishes from inside the hut")
        check(wishGate { it.absDay = 200 }, "wish: no wishes on a plain night")
        check(wishGate {
            val p = it.agents.values.first { a -> a.isPlayer }
            p.location = "MainStreet"; p.destination = "MainStreet"
        }, "wish: no wishes away from the pond")

        // ---------- 🎣 THE FISHING HOOK ----------
        check(Feel.METEOR_RARE_MULT == 1.5,
            "sky: the meteor rare-fish bend lives in Feel, at 1.5x")
        fun catchCounts(meteor: Boolean): Map<String, Int> {
            val counts = mutableMapOf<String, Int>()
            for (seed in 1L..600L) {
                val sess = FishingSession(seed, "sunny", 23, meteorNight = meteor)
                sess.tap(sess.biteAtMs)
                val sp = sess.species?.id ?: "none"
                counts[sp] = (counts[sp] ?: 0) + 1
            }
            return counts
        }
        val plainCounts = catchCounts(false)
        val meteorCounts = catchCounts(true)
        val plainRare = plainCounts.filterKeys {
            fishById(it)?.rare == true }.values.sum()
        val meteorRare = meteorCounts.filterKeys {
            fishById(it)?.rare == true }.values.sum()
        check(meteorRare > plainRare,
            "sky: meteor nights land more rare fish ($meteorRare vs $plainRare of 600)")
        check((meteorCounts["three_eyed_fish"] ?: 0) >
            (plainCounts["three_eyed_fish"] ?: 0),
            "sky: the three-eyed fish especially likes meteor nights " +
                "(${meteorCounts["three_eyed_fish"]} vs ${plainCounts["three_eyed_fish"]})")
        check((plainCounts["three_eyed_fish"] ?: 0) in 8..48,
            "sky: the plain table keeps the three-eyed fish rare (got ${plainCounts["three_eyed_fish"]})")
        var legacySame = true
        for (seed in 1L..50L) {
            val a = FishingSession(seed, "light_snow", 12)
            val b = FishingSession(seed, "light_snow", 12, meteorNight = false)
            a.tap(a.biteAtMs); b.tap(b.biteAtMs)
            if (a.species != b.species || a.sizeCm != b.sizeCm) legacySame = false
        }
        check(legacySame,
            "sky: a plain night's fishing replays the legacy table exactly")

        // ---------- 🎧 THE HUSH ----------
        check(SoundGen.selectAmbience("sunny", 23 * 60, false) ==
            SoundGen.AmbBed.CRICKETS,
            "sky: a plain clear night still gets its crickets")
        check(SoundGen.selectAmbience("sunny", 23 * 60, false, aweNight = true) ==
            SoundGen.AmbBed.WIND_LIGHT,
            "sky: on an aurora night the crickets stand down for the hush")
        check(SoundGen.selectAmbience("rain", 23 * 60, false, aweNight = true) ==
            SoundGen.AmbBed.RAIN &&
            SoundGen.selectAmbience("sunny", 23 * 60, true, aweNight = true) ==
            SoundGen.AmbBed.ROOM &&
            SoundGen.selectAmbience("sunny", 12 * 60, false, aweNight = true) ==
            SoundGen.AmbBed.NONE,
            "sky: weather and indoors still outrank the hush; daytime has none")

        // ---------- 📸 PHOTOS REMEMBER THEIR SKY ----------
        val recSky = PhotoRecord(
            id = "psky", dayKey = "20260105", dateLabel = "1/5",
            timeMin = 23 * 60, locId = "StarksPond", inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = emptyList(), absDay = 5)
        val backSky = PhotoRecord.fromMap(recSky.toMap())
        check(backSky != null && backSky.absDay == 5 && backSky == recSky,
            "sky: a photo record keeps its capture day through the save map")
        val legacyMap = recSky.toMap().toMutableMap().apply { remove("absDay") }
        check(PhotoRecord.fromMap(legacyMap)?.absDay == -1,
            "sky: a pre-0.3.0e record loads with no sky day (plain-moon fallback)")
        check(SkyState.now(recSky.absDay, recSky.timeMin, recSky.weatherId,
            seasonFor(1)).special == SkyState.AURORA,
            "sky: the record's own inputs reproduce its aurora — selfie and scene agree")
        val sPhoto = Engine(3).newState()
        sPhoto.photos.add(recSky)
        val sPhotoBack = decodeGameState(encodeGameState(sPhoto))
        check(sPhotoBack.photos.firstOrNull()?.absDay == 5,
            "sky: the capture day survives the real save round-trip")

        // ---------- WIRING ----------
        val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        val photoSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
        val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        val journalSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        val soundSrc = File(root, "src/com/hunt3r/southparktown/SoundGen.kt").readText()
        check(sceneSrc.contains("SkyState.AURORA") &&
            sceneSrc.contains("SkyState.METEOR") &&
            sceneSrc.contains("TownInfo.moonlight"),
            "sky: the scene draws washes, streaks, and moonlight from SkyState")
        check(photoSrc.contains("SkyState.now") && photoSrc.contains("rec.absDay"),
            "sky: the selfie backdrop reads the same SkyState from the record")
        check(gaSrc.contains("engine.pondWish") && gaSrc.contains("SkyState.meteorNow") &&
            gaSrc.contains("SkyState.auroraNow") && gaSrc.contains("SkyState.now("),
            "sky: GameActivity bridges SkyState to the pond, the rod, the hush and TownInfo")
        check(journalSrc.contains("wishCount"),
            "sky: the Journal's GAMES page keeps the wish tally")
        check(soundSrc.contains("aweNight"),
            "sky: the bed picker takes the aurora as a flavor input")
    }
}

/** v0.3.0f section, extracted from main() like the others. */
private fun sectionV030f(root: String) {
// ================= v0.3.0f: mystery arc #2, "The Locked Booth" =================
// Queue #3 item 6. The second case REUSES the pond case's
// discipline — beats on the episode machinery, clues gathered
// three ways, a gated finale, permanent marks, retirement —
// with a different skeleton: one marathon night, three
// interview days, an accusation. It queues a week behind the
// pond case's retirement and never overlaps it.
    println("== v0.3.0f: mystery arc #2 ? the locked booth ==")
    val eng2 = Engine()
    fun baseInf2(id: String) = FACTIONS.first { it.id == id }.baseInfluence

    // ---------- def integrity ----------
    check(Mystery2.BEATS.size == 2, "booth: two beats (the night, the accusation)")
    check(Mystery2.BEATS.map { it.id }.distinct().size == 2,
        "booth: beat ids are unique")
    check(Mystery2.BEATS[0].id == Mystery2.MARATHON_ID &&
        Mystery2.BEATS[1].id == Mystery2.ACCUSATION_ID,
        "booth: the marathon airs first, the accusation second")
    val regularIds2 = SHENANIGANS.map { it.id }.toSet()
    for (def in Mystery2.BEATS) {
        check(def.stages.size == 4 && def.causers.isNotEmpty() &&
            def.episodeTitles.size == 2 && def.coldOpen.isNotEmpty() &&
            def.theme.header.isNotBlank(),
            "booth: ${def.id} carries the full episode kit " +
                "(4 stages, causers, 2 titles, cold open)")
        check(def.id !in regularIds2 && SHENANIGAN_BY_ID[def.id] == def,
            "booth: ${def.id} is not in the random pool but resolves by id")
        check(def.stages[2].clusterLoc == "Bijou",
            "booth: ${def.id}'s climax is at the Bijou (where its mark lands)")
        check(def.id !in Mystery.ARC_CHAPTERS.map { it.id },
            "booth: ${def.id} is its own case, not a pond chapter")
    }
    check(SHENANIGANS.size == 10, "booth: the random pool is still the ten")

    // ---------- the clue registry ----------
    check(Mystery2.CLUES2.size == 10, "booth: ten clues on the board")
    check(Mystery2.CLUES2.map { it.id }.distinct().size == 10 &&
        Mystery2.CLUES2.all { it.id in Mystery2.CLUE2_IDS },
        "booth: clue ids are unique")
    check(Mystery2.CLUES2.count { it.kind == Mystery.ClueKind.WITNESS } == 5 &&
        Mystery2.CLUES2.count { it.kind == Mystery.ClueKind.LOOK } == 3 &&
        Mystery2.CLUES2.count { it.kind == Mystery.ClueKind.PARTICIPATION } == 2,
        "booth: clues split 5 witnesses / 3 looks / 2 participations")
    for (clue in Mystery2.CLUES2) {
        check(clue.detail.isNotBlank(), "booth: ${clue.id} carries its flavor")
        when (clue.kind) {
            Mystery.ClueKind.WITNESS -> check(
                (clue.npc != null && clue.npc in AGENT_PROFILES || clue.byUsher) &&
                    !clue.spoken.isNullOrBlank(),
                "booth: ${clue.id}'s witness is a real cast member (or the usher) who speaks")
            Mystery.ClueKind.LOOK -> check(
                clue.locId != null && clue.locId in LOCATIONS &&
                    !clue.foundText.isNullOrBlank(),
                "booth: ${clue.id} is hidden at a real location")
            Mystery.ClueKind.PARTICIPATION -> check(
                clue.beatDefId == Mystery2.MARATHON_ID,
                "booth: ${clue.id} is earned on the marathon night")
        }
    }
    check(Mystery2.ALIBI_IDS.size == 3 &&
        Mystery2.ALIBI_IDS.all { id ->
            Mystery2.CLUE2_BY_ID[id]?.npc == "Mackey"
        },
        "booth: the alibi is three tellings from one teller")
    check(Mystery2.ACCUSE_MIN_CLUES in 1 until Mystery2.CLUES2.size,
        "booth: the accusation gate sits inside the clue count")
    check(Mystery2.SUSPECT_KEYS.size == 4 &&
        Mystery2.CULPRIT_KEY in Mystery2.SUSPECT_KEYS,
        "booth: four names can be said; the true one is among them")

    // ---------- the usher pick (pure) ----------
    val usherPool = listOf(
        "Marv Albertson" to "A quiet man who has lived in South Park for years.",
        "Big Celebrity" to "A famous actor, celebrity and movie star adored worldwide.",
        "Onename" to "A quiet soul who lives in South Park and keeps to himself.",
        "Dana Whitfield" to "Works the late shift. Lives in South Park. Likes bowling.",
        "Kid Student" to "A student at South Park Elementary who loves recess.")
    check(Mystery2.pickUsherName(usherPool, 40) ==
        Mystery2.pickUsherName(usherPool, 40),
        "booth: the usher pick is deterministic for a given marathon day")
    var screenedOk = true
    for (d in 0..60) {
        val pick = Mystery2.pickUsherName(usherPool, d)
        if (pick != "Marv Albertson" && pick != "Dana Whitfield") screenedOk = false
    }
    check(screenedOk,
        "booth: the screen keeps celebrities, single names and schoolkids off the usher shift")
    check(Mystery2.pickUsherName(emptyList(), 3) == null,
        "booth: an empty pool seats no usher")
    check(Mystery2.pickUsherName(listOf("Onename" to "Lives in South Park."), 3) == null,
        "booth: a fully screened-out pool seats no usher")

    // ---------- scheduling: the case queues behind the pond ----------
    val sGate2 = eng2.newState()
    check(Mystery2.dueBeat(sGate2) == null && sGate2.arc2DueAbsDay == -1,
        "booth: while the pond case is open, this one does not even schedule")
    sGate2.arcRetired = true
    check(Mystery2.dueBeat(sGate2) == null &&
        sGate2.arc2DueAbsDay == sGate2.absDay + Mystery2.OPEN_DELAY_DAYS,
        "booth: the first ask after the pond retires books the marathon a week out")
    sGate2.absDay = sGate2.arc2DueAbsDay - 1
    check(Mystery2.dueBeat(sGate2) == null, "booth: the marathon is never early")
    sGate2.absDay = sGate2.arc2DueAbsDay
    check(Mystery2.dueBeat(sGate2)?.id == Mystery2.MARATHON_ID,
        "booth: the marathon is due on its day")
    sGate2.holidayId = "halloween"
    check(Mystery2.dueBeat(sGate2) == null,
        "booth: a due marathon defers for a holiday episode")
    sGate2.holidayId = null
    check(Mystery2.dueBeat(sGate2)?.id == Mystery2.MARATHON_ID,
        "booth: ...and is due again the moment the holiday clears")
    Mystery2.noteBeatStarted(sGate2, Mystery2.BEATS[0])
    check(sGate2.arc2Started && sGate2.arc2MarathonDay == sGate2.absDay &&
        sGate2.arc2AccuseDueAbsDay == sGate2.absDay + Mystery2.ACCUSATION_GAP_DAYS,
        "booth: the marathon books the second screening four days out")
    sGate2.absDay += Mystery2.ACCUSATION_GAP_DAYS - 1
    check(Mystery2.dueBeat(sGate2) == null, "booth: the accusation is never early")
    sGate2.absDay += 1
    check(Mystery2.dueBeat(sGate2)?.id == Mystery2.ACCUSATION_ID,
        "booth: the accusation lands on its due day")
    Mystery2.noteBeatStarted(sGate2, Mystery2.BEATS[1])
    check(sGate2.arc2AccusationAired && Mystery2.dueBeat(sGate2) == null,
        "booth: once the accusation has aired, nothing more is due")
    check(!Mystery2.boardVisible2(eng2.newState()),
        "booth: no board before the case exists")

    // ---------- interviews: the alibi will not sit still ----------
    val sTalk = eng2.newState()
    sTalk.arcRetired = true; sTalk.arc2Started = true
    sTalk.arc2MarathonDay = 10; sTalk.absDay = 10
    check(Mystery2.witnessLine2(sTalk, "Mackey") == null &&
        Mystery2.witnessLine2(sTalk, "Butters") == null,
        "booth: there are no interviews on the marathon day itself")
    sTalk.absDay = 11
    val says1 = Mystery2.witnessLine2(sTalk, "Mackey")
    check(says1 != null && says1.speaker == "Mackey" &&
        sTalk.mystery2Clues == setOf("alibi_lobby"),
        "booth: interview day 1 hears the alibi's first telling")
    check(Mystery2.witnessLine2(sTalk, "Mackey") == null,
        "booth: the alibi retells once a day, never twice")
    check(sTalk.events.any { it.contains("CLUE 1/10") },
        "booth: a found clue hits the ticker")
    val shad = Mystery2.witnessLine2(sTalk, "Butters")
    check(shad != null && "tall_shadow" in sTalk.mystery2Clues,
        "booth: Butters saw the tall shadow")
    check(Mystery2.witnessLine2(sTalk, "Butters") == null,
        "booth: a witness tells it exactly once")
    val cluesBeforeFlavor = Mystery2.clueCount2(sTalk)
    check(Mystery2.suspectFlavorLine(sTalk, "Clyde")?.speaker == "Clyde" &&
        Mystery2.clueCount2(sTalk) == cluesBeforeFlavor &&
        Mystery2.suspectFlavorLine(sTalk, "Clyde") == null,
        "booth: Clyde's non-alibi is flavor — once, and it grants nothing")
    check(Mystery2.suspectFlavorLine(sTalk, "Craig")?.speaker == "Craig",
        "booth: Craig's alibi is a shrug and Tweek")
    sTalk.arc2Usher = "Dana Whitfield"
    val ush = Mystery2.witnessLine2(sTalk, "Dana Whitfield")
    check(ush != null && ush.speaker == "Dana Whitfield" &&
        "usher_timeline" in sTalk.mystery2Clues,
        "booth: the usher's honest timeline contradicts the lobby story")
    check(Mystery2.witnessLine2(sTalk, "Randy") == null,
        "booth: Randy is nobody's witness in this case")
    sTalk.absDay = 12
    check(Mystery2.witnessLine2(sTalk, "Mackey") != null &&
        "alibi_near" in sTalk.mystery2Clues &&
        "alibi_adjacent" !in sTalk.mystery2Clues,
        "booth: day 2 — the lobby becomes 'near the lobby' (the drift, in order)")
    sTalk.absDay = 13
    check(Mystery2.witnessLine2(sTalk, "Mackey") != null &&
        "alibi_adjacent" in sTalk.mystery2Clues,
        "booth: day 3 — 'lobby-adjacent'. The story has left the lobby.")
    sTalk.absDay = 14
    check(Mystery2.witnessLine2(sTalk, "Mackey") == null,
        "booth: three tellings is all the alibi has")

    // ---------- clues: look ----------
    val sLook = eng2.newState()
    sLook.arcRetired = true
    check(Mystery2.lookClueText2(sLook, "Bijou") == null,
        "booth: no evidence before the marathon airs")
    sLook.arc2Started = true; sLook.arc2MarathonDay = 5; sLook.absDay = 6
    check(Mystery2.lookClueText2(sLook, "Bijou") != null &&
        "key_log" in sLook.mystery2Clues,
        "booth: the Bijou's first Look gives up the key log")
    check(Mystery2.lookClueText2(sLook, "Bijou") != null &&
        "thumbprint" in sLook.mystery2Clues,
        "booth: the second Look finds the thumbprint in the butter")
    check(Mystery2.lookClueText2(sLook, "Bijou") == null,
        "booth: the Bijou holds exactly two pieces of evidence")
    check(Mystery2.lookClueText2(sLook, "Elementary") != null &&
        "confiscation_form" in sLook.mystery2Clues,
        "booth: the school's tray holds a half-filled slip")
    check(Mystery2.lookClueText2(sLook, "Bank") == null,
        "booth: the Bank holds no evidence")

    // ---------- clues: participation ----------
    val sPart2 = eng2.newState()
    sPart2.arcRetired = true; sPart2.arc2Started = true
    sPart2.arc2MarathonDay = sPart2.absDay
    sPart2.shenaniganId = Mystery2.MARATHON_ID; sPart2.shenaniganDay = sPart2.todayKey
    sPart2.timeMin = 60   // stage 0; the marathon gathers at the Bijou
    eng2.player(sPart2).location = "Bijou"
    eng2.bumpParticipation(sPart2, "Bijou")
    check(sPart2.participation == 1 && "booth_program" in sPart2.mystery2Clues,
        "booth: showing up early earns the marathon program (and its scene list)")
    sPart2.timeMin = 13 * 60   // the climax: the booth stands open and empty
    eng2.bumpParticipation(sPart2, "Bijou")
    check("booth_search" in sPart2.mystery2Clues,
        "booth: helping search the booth at the climax turns up the tidy truth")
    eng2.bumpParticipation(sPart2, "Bijou")
    check(sPart2.mystery2Clues.count {
        it == "booth_program" || it == "booth_search" } == 2,
        "booth: the marathon grants its two discoveries once each")
    val sFar2 = eng2.newState()
    sFar2.arc2Started = true; sFar2.shenaniganId = Mystery2.MARATHON_ID
    sFar2.timeMin = 60
    eng2.player(sFar2).location = "Mall"
    eng2.bumpParticipation(sFar2, "Mall")
    check(sFar2.participation == 0 && sFar2.mystery2Clues.isEmpty(),
        "booth: no discoveries away from the marathon's turf")

    // ---------- the accusation gate ----------
    fun accuseState(clues: Int): GameState {
        val s = eng2.newState()
        s.arcRetired = true; s.arc2Started = true
        s.arc2MarathonDay = 10; s.absDay = 14
        s.shenaniganId = Mystery2.ACCUSATION_ID
        s.shenaniganDay = s.todayKey
        for (c in Mystery2.CLUES2.take(clues)) s.mystery2Clues.add(c.id)
        return s
    }
    val accDef = Mystery2.BEAT_BY_ID[Mystery2.ACCUSATION_ID]!!
    check(!Mystery2.accusationDue(accuseState(5).apply { timeMin = 13 * 60 }),
        "booth: five clues is NOT enough to say a name (below the gate)")
    val sGate3 = accuseState(6); sGate3.timeMin = 13 * 60
    check(Mystery2.accusationDue(sGate3),
        "booth: six clues opens the floor (the boundary)")
    check(!Mystery2.accusationDue(accuseState(9).apply { timeMin = 600 }),
        "booth: the moment waits for the climax, not the morning")
    check(!Mystery2.accusationDue(accuseState(9).apply {
        timeMin = 13 * 60; shenaniganId = Mystery2.MARATHON_ID }),
        "booth: the moment belongs to the second screening alone")
    check(!Mystery2.accuse(sGate3, "butters"),
        "booth: only the four suspects can be named")
    check(Mystery2.accuse(sGate3, "clyde") && sGate3.arc2Accused == "clyde",
        "booth: a name can be said at the gate")
    check(!Mystery2.accusationDue(sGate3) && !Mystery2.accuse(sGate3, "craig"),
        "booth: a said name closes the floor")
    val sDecline = accuseState(7); sDecline.timeMin = 13 * 60
    check(Mystery2.declineAccusation(sDecline) && sDecline.arc2Declined &&
        !Mystery2.accusationDue(sDecline) && !Mystery2.accuse(sDecline, "clyde"),
        "booth: keeping your seat is a real choice, and it closes the floor too")

    // ---------- the wrap: three landings ----------
    fun wrappedCase(clues: Int, accused: String): GameState {
        val s = accuseState(clues)
        s.arc2Accused = accused
        Episodes.beginEvent(s, accDef)
        s.lastEventWeek = 39
        s.timeMin = 1430
        eng2.advanceTime(s)
        return s
    }
    val freshFriend = eng2.newState().friendship["Stan"] ?: 0
    val sSolved = wrappedCase(8, Mystery2.CULPRIT_KEY)
    check(sSolved.arc2Retired && sSolved.arc2Branch == "solved",
        "booth: naming right retires the case SOLVED")
    val epSolved = sSolved.episodes.lastOrNull { it.eventId == Mystery2.ACCUSATION_ID }
    check(epSolved != null && epSolved.finished &&
        epSolved.recap.any { it.contains("CONFESSION") },
        "booth: the solved ending's credits carry the confession")
    check(sSolved.lifeText["mark:Bijou"]?.contains("plaque") == true,
        "booth: the solved case leaves its plaque at the Bijou")
    check(sSolved.factionStates.getValue("school_staff").influence ==
        baseInf2("school_staff") + 3 &&
        sSolved.factionStates.getValue("boys_crew").influence ==
        baseInf2("boys_crew") + 2,
        "booth: the solved ripples (Staff +3, Crew +2)")
    check((sSolved.friendship["Stan"] ?: 0) == freshFriend + 2,
        "booth: the filmmakers warm to the kid who got their movie back")
    check(Mystery2.statusStamp2(sSolved).contains("SOLVED"),
        "booth: the board stamps SOLVED")

    val sWrongBase = accuseState(8)
    sWrongBase.arc2Accused = "clyde"
    sWrongBase.friendship["Clyde"] = 40
    Episodes.beginEvent(sWrongBase, accDef)
    sWrongBase.lastEventWeek = 39
    sWrongBase.timeMin = 1430
    eng2.advanceTime(sWrongBase)
    val sWrong = sWrongBase
    check(sWrong.arc2Branch == "wrong" && sWrong.arc2Retired,
        "booth: naming wrong still retires the case — cold, with a name in it")
    check((sWrong.friendship["Clyde"] ?: 0) == 40 - Mystery2.WRONG_ACCUSE_SCAR,
        "booth: the wrongly-named carries the scar (-${Mystery2.WRONG_ACCUSE_SCAR})")
    check(sWrong.episodes.last { it.eventId == Mystery2.ACCUSATION_ID }
        .recap.any { it.contains("THE NAME THAT STUCK") },
        "booth: the wrong ending's credits record the name, not a verdict")
    check(sWrong.lifeText["mark:Bijou"]?.contains("KEYS SIGNED IN & OUT") == true,
        "booth: the wrong case leaves the new booth rules as its mark")
    check(Mystery2.grudgeCallback(sWrong, "Clyde", "Stan")?.speaker == "Clyde" &&
        Mystery2.grudgeCallback(sWrong, "Mackey", "Stan") == null &&
        Mystery2.grudgeCallback(sSolved, "Clyde", "Stan") == null,
        "booth: the grudge lives only in the wrongly-named, only in the wrong ending")
    check(Mystery2.statusStamp2(sWrong).contains("a name was named"),
        "booth: the wrong board stamps the naming, not the truth of it")

    val sColdBase = accuseState(2)
    sColdBase.friendship["Clyde"] = 40
    Episodes.beginEvent(sColdBase, accDef)
    sColdBase.lastEventWeek = 39
    sColdBase.timeMin = 1430
    eng2.advanceTime(sColdBase)
    check(sColdBase.arc2Branch == "cold" &&
        sColdBase.lifeText["mark:Bijou"]?.contains("REEL MISSING") == true &&
        (sColdBase.friendship["Clyde"] ?: 0) == 40,
        "booth: no name, no clues to speak of — the case goes cold and scars nobody")
    val sRigged = wrappedCase(2, Mystery2.CULPRIT_KEY)
    check(sRigged.arc2Branch == "cold",
        "booth: even the RIGHT name, said without the case behind it, falls apart")

    // ---------- the reel turns up ----------
    check(!Mystery2.noteReelFound(sWrong),
        "booth: the lost-and-found beat is not instant")
    sWrong.absDay += Mystery2.REEL_FOUND_DELAY_DAYS - 1
    check(!Mystery2.noteReelFound(sWrong),
        "booth: six days is not a week")
    sWrong.absDay += 1
    check(Mystery2.noteReelFound(sWrong) && sWrong.arc2ReelFound &&
        sWrong.events.any { it.contains("lost-and-found") },
        "booth: a week after a cold close, the reel quietly turns up")
    check(!Mystery2.noteReelFound(sWrong),
        "booth: the reel turns up exactly once")
    check(Mystery2.boardLines2(sWrong).any { it.contains("Final note") },
        "booth: the board's final note lets a careful reader suspect forever")
    val sSolvedLater = wrappedCase(9, Mystery2.CULPRIT_KEY)
    sSolvedLater.absDay += 30
    check(!Mystery2.noteReelFound(sSolvedLater),
        "booth: a solved case's reel is already home — no lost-and-found beat")

    // ---------- the board ----------
    val sBoard = eng2.newState()
    sBoard.arcRetired = true; sBoard.arc2Started = true
    sBoard.arc2MarathonDay = 10; sBoard.absDay = 12; sBoard.arc2Usher = "Dana Whitfield"
    val board = Mystery2.boardLines2(sBoard)
    check(board.first().contains("The Locked Booth") &&
        board.any { it.contains("🧩 CLUES — 0/10") } &&
        board.any { it.contains("Dana Whitfield") } &&
        board.any { it.contains("Mr. Mackey") } &&
        board.any { it.contains("smart money") },
        "booth: the board shows the case, its empty clue count, its four suspects")
    Mystery2.grantClue2(sBoard, "key_log")
    check(Mystery2.boardLines2(sBoard).any { it.contains("🧩 CLUES — 1/10") },
        "booth: the board counts what you carry")

    // ---------- engine: a full two-arc lifetime ----------
    val sLife = eng2.newState()
    var sawMarathon = false
    var sawAccusation = false
    var overlapViolation = false
    var pondRetiredDay = -1
    var marathonDaySeen = -1
    var guardL = 0
    while (guardL++ < 220 && !(sLife.arcRetired && sLife.arc2Retired)) {
        eng2.onNewDay(sLife)
        if (sLife.shenaniganId == Mystery2.MARATHON_ID) sawMarathon = true
        if (sLife.shenaniganId == Mystery2.ACCUSATION_ID) sawAccusation = true
        if (sLife.arc2Started && !sLife.arcRetired) overlapViolation = true
        if (sLife.arcRetired && pondRetiredDay < 0) pondRetiredDay = sLife.absDay
        if (sLife.arc2Started && marathonDaySeen < 0) marathonDaySeen = sLife.absDay
    }
    check(sLife.arcRetired && sLife.arc2Retired,
        "booth: a full two-arc lifetime plays out (pond, then booth) in ${guardL} days")
    check(sawMarathon && sawAccusation,
        "booth: both beats aired inside the lifetime")
    check(!overlapViolation,
        "booth: the second case never opens while the first is live")
    check(marathonDaySeen - pondRetiredDay in
        Mystery2.OPEN_DELAY_DAYS..(Mystery2.OPEN_DELAY_DAYS + 9),
        "booth: the marathon follows the pond's retirement by about a week " +
            "(got ${marathonDaySeen - pondRetiredDay})")
    check(sLife.arc2Branch == "cold",
        "booth: an unattended booth case goes cold on its own")

    // ---------- persistence: mid-case saves & era saves ----------
    val docMid2 = mapOf<String, Any?>(
        "arc" to mapOf<String, Any?>("chapter" to 5L, "due" to 38L,
            "started" to true, "retired" to true,
            "branch" to "town", "choice" to ""),
        "arc2" to mapOf<String, Any?>("due" to 50L, "started" to true,
            "marathonDay" to 46L, "accuseDue" to 50L,
            "accusationAired" to false, "retired" to false,
            "branch" to "", "accused" to "", "usher" to "Dana Whitfield",
            "alibiDay" to 48L, "retiredDay" to -1L, "reelFound" to false,
            "declined" to false, "flavor" to listOf("Clyde")),
        "mystery2Clues" to listOf("key_log", "bogus_clue"))
    val sMid2 = decodeGameState(docMid2)
    check(sMid2.arc2Started && sMid2.arc2MarathonDay == 46 &&
        sMid2.arc2AccuseDueAbsDay == 50 && sMid2.arc2Usher == "Dana Whitfield" &&
        sMid2.arc2AlibiDay == 48 && "Clyde" in sMid2.arc2FlavorSeen,
        "booth: a mid-case save restores the case's clocks and its usher")
    check(sMid2.mystery2Clues == setOf("key_log"),
        "booth: known clues restore; invented ids are dropped")
    sMid2.absDay = 50
    check(Mystery2.dueBeat(sMid2)?.id == Mystery2.ACCUSATION_ID,
        "booth: a restored mid-case save airs its accusation on time")
    val docTampered = mapOf<String, Any?>("arc2" to mapOf<String, Any?>(
        "branch" to "banana", "accused" to "butters"))
    val sTampered = decodeGameState(docTampered)
    check(sTampered.arc2Branch == "" && sTampered.arc2Accused == "",
        "booth: invented branch/suspect values are neutralized on load")
    val sEra2 = decodeGameState(emptyMap())
    check(!sEra2.arc2Started && sEra2.arc2DueAbsDay == -1 &&
        sEra2.mystery2Clues.isEmpty() && !Mystery2.boardVisible2(sEra2),
        "booth: an era save (no arc2 keys) has no second case yet")
    val sRound = wrappedCase(7, "craig")
    val sBack2 = decodeGameState(encodeGameState(sRound))
    check(sBack2.arc2Retired && sBack2.arc2Branch == "wrong" &&
        sBack2.arc2Accused == "craig" &&
        sBack2.mystery2Clues == sRound.mystery2Clues,
        "booth: a closed case round-trips through the real save path")

    // ---------- spoiler hygiene: the changelog keeps the secret ----------
    val readme2 = File(root, "docs/CHANGELOG.md").readText()
    val fSection = readme2.substringAfter("### v0.3.0f")
        .substringBefore("### v0.3.0e")
    check(fSection.contains("The Locked Booth"),
        "booth: the v0.3.0f changelog section exists")
    for (tell in listOf("confiscat", "lobby-adjacent", "for your own good",
        "took the reel", "stole the reel", "mackey took", "mackey stole")) {
        check(!fSection.contains(tell, ignoreCase = true),
            "booth: the changelog never prints the case's tell ('$tell')")
    }

    // ---------- wiring ----------
    val mystery2Src = File(root, "src/com/hunt3r/southparktown/Mystery2.kt").readText()
    val gameActivitySrc2 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc2 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val engineSrc2 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val prefsSrc2 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc2 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    check(!mystery2Src.contains("import android"),
        "booth: Mystery2.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc2.contains("Mystery2.dueBeat") &&
        engineSrc2.contains("Mystery2.resolveAccusation") &&
        engineSrc2.contains("Mystery2.noteParticipation2") &&
        engineSrc2.contains("Mystery2.grudgeCallback") &&
        engineSrc2.contains("Mystery2.noteReelFound"),
        "booth: the engine airs the beats, resolves the accusation, feeds " +
            "participation, grudges and the lost-and-found")
    check(File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
            .contains("Mystery2.witnessLine2") &&
        gameActivitySrc2.contains("Mystery2.lookClueText2") &&
        gameActivitySrc2.contains("Mystery2.accuse") &&
        gameActivitySrc2.contains("Mystery2.declineAccusation") &&
        gameActivitySrc2.contains("maybeShowAccusation") &&
        gameActivitySrc2.contains("Mystery2.usherHere"),
        "booth: GameActivity wires interviews, looks, the accusation and the usher")
    check(journalSrc2.contains("Mystery2.boardLines2"),
        "booth: the Journal renders the second case's board")
    check(prefsSrc2.contains("\"arc2\" to mapOf") &&
        prefsSrc2.contains("\"mystery2Clues\" to"),
        "booth: the save doc carries the second case additively")
    check(shenanigansSrc2.contains("Mystery2.BEATS"),
        "booth: the beat defs join SHENANIGAN_BY_ID only")
}

/** v0.3.0g section, extracted from main() like the others:
 *  polish & performance pass #3 — the Queue #3 audit. */
private fun sectionV030g(root: String) {
// ================= v0.3.0g: polish & performance pass #3 =================
// Queue #3's final item. No new features: the unified lifetime
// soak (the whole modern stack, 400 days), the veteran save
// re-measured against today's registries, the morning report
// audited for duplicates/throws/spoilers (one real defect
// found + fixed: story beats were reported twice), the newest
// screens' fit QA, the cadence constants, and the audio peak
// budget re-measured at a distance.
println("== v0.3.0g: lifetime soak, veteran II, report audit, cadence, budget ==")
run {
    // ---------- cadence: the timing numbers are named constants ----------
    check(StoryArcs.STAGE_DAYS_NUDGED == 1 && StoryArcs.STAGE_DAYS_SOLO == 2 &&
        StoryArcs.WARM_HELPED_NUM == 1 && StoryArcs.WARM_HELPED_DEN == 2 &&
        StoryArcs.WARM_BOND_THRESHOLD == 6,
        "cadence: story timing lives in named constants at the shipped values")
    val storiesSrcG = File(root, "src/com/hunt3r/southparktown/Stories.kt").readText()
    check(storiesSrcG.split("STAGE_DAYS_NUDGED").size - 1 >= 2 &&
        storiesSrcG.split("STAGE_DAYS_SOLO").size - 1 >= 2 &&
        storiesSrcG.split("WARM_BOND_THRESHOLD").size - 1 >= 2 &&
        storiesSrcG.split("WARM_HELPED_DEN").size - 1 >= 2,
        "cadence: stageDays/warmEarned read the constants, not literals")
    val defCad = StoryArcs.ARCS[0]
    check(StoryArcs.stageDays(StoryArcState(defCad.id, stage = 0,
            helpedStages = mutableSetOf(0))) == StoryArcs.STAGE_DAYS_NUDGED,
        "cadence: a nudged stage turns over tomorrow")
    check(StoryArcs.stageDays(StoryArcState(defCad.id, stage = 0)) ==
        StoryArcs.STAGE_DAYS_SOLO,
        "cadence: a left-alone stage lives two days")
    val sWarmG = Engine(41).newState()
    val recHalf = StoryArcState(defCad.id, stage = defCad.stages.size - 1,
        helpedStages = (0 until (defCad.stages.size + 1) / 2).toMutableSet())
    check(StoryArcs.warmEarned(sWarmG, defCad, recHalf),
        "cadence: nudging half the stages earns the warm ending")
    val recNone = StoryArcState(defCad.id, stage = defCad.stages.size - 1)
    check(!StoryArcs.warmEarned(sWarmG, defCad, recNone),
        "cadence: no help and no bond lands the solo ending")
    sWarmG.npcBonds[Threads.pairKey("Stan", "Wendy")] =
        StoryArcs.WARM_BOND_THRESHOLD
    check(StoryArcs.warmEarned(sWarmG, defCad, recNone),
        "cadence: a bond at the threshold earns the warm ending on its own")
    sWarmG.npcBonds[Threads.pairKey("Stan", "Wendy")] =
        StoryArcs.WARM_BOND_THRESHOLD - 1
    check(!StoryArcs.warmEarned(sWarmG, defCad, recNone),
        "cadence: a bond one under the threshold does not")
    check(Mystery.CHAPTER_GAP_DAYS == 7 &&
        Mystery.FIRST_CHAPTER_MIN_ABSDAY == 3 && Mystery.TRUTH_MIN_CLUES == 7,
        "cadence: the pond case's +7 bookings and 7-clue gate at shipped values")
    check(Mystery2.OPEN_DELAY_DAYS == 7 && Mystery2.ACCUSATION_GAP_DAYS == 4 &&
        Mystery2.ACCUSE_MIN_CLUES == 6 && Mystery2.REEL_FOUND_DELAY_DAYS == 7,
        "cadence: the booth case's +7/+4 bookings, 6-clue gate, week-late reel")

    // ---------- audio: the peak budget, re-measured at a distance ----------
    val pbG = SoundGen.PeakBudget
    println("budget distance: named ${pbG.namedStack()} " +
        "(headroom ${1f - pbG.namedStack()}), double-sfx ${pbG.doubleSfxStack()} " +
        "(headroom ${1f - pbG.doubleSfxStack()}), beds max ${pbG.ambiencePeakOut()}")
    check(pbG.namedStack() <= 1.0f && pbG.doubleSfxStack() <= 1.0f,
        "budget: both designed stacks still sum under full scale")
    check(1f - pbG.namedStack() > 0.0f && 1f - pbG.doubleSfxStack() > 0.0f,
        "budget: real headroom remains in both stacks")
    for (bed in SoundGen.AmbBed.values()) {
        if (bed == SoundGen.AmbBed.NONE) continue
        val out = AudioSettings.DEFAULT.gain(AudioChannel.AMBIENCE) *
            pbG.AMB_CHAIN * pbG.peakOf(SoundGen.renderAmbience(bed))
        check(out <= pbG.ambiencePeakOut() + 0.0001f,
            "budget: bed $bed sits inside the ambience allocation")
    }
    check(SoundGen.selectAmbience("sunny", 23 * 60, inside = false,
            aweNight = true) == SoundGen.AmbBed.WIND_LIGHT,
        "budget: an aurora night stands the crickets down for the hush")
    check(SoundGen.selectAmbience("sunny", 23 * 60, inside = false,
            aweNight = false) == SoundGen.AmbBed.CRICKETS,
        "budget: a plain clear night keeps its crickets")
    val hushOut = AudioSettings.DEFAULT.gain(AudioChannel.AMBIENCE) *
        pbG.AMB_CHAIN * pbG.peakOf(SoundGen.renderAmbience(SoundGen.AmbBed.WIND_LIGHT))
    check(hushOut <= pbG.ambiencePeakOut() + 0.0001f,
        "budget: the aurora hush bed spends no more than the allocation")

    // ---------- the morning report, audited ----------
    // The defect this section pins shut: the rollover appends
    // story beats to the events feed (NEW STORY / banners /
    // STORY'S END) AND the report's arc section summarizes the
    // same beats — a slept-through transition was printed
    // twice. v0.3.0g: the arc section owns the transitions;
    // the ticker versions are filtered, and the report is
    // distinct() by construction.
    val engRep = Engine(43)
    val defRep = StoryArcs.ARCS[0]
    // (a) a resolution overnight
    val sRes = engRep.newState(); sRes.absDay = 40
    val recRes = StoryArcState(defRep.id, stage = defRep.stages.size - 1,
        stageStartAbsDay = 39, startedAbsDay = 30,
        helpedStages = (0 until defRep.stages.size).toMutableSet())
    sRes.storyArcs[defRep.id] = recRes
    val evRes = sRes.events.toList()
    val arcsRes = mapOf(defRep.id to (recRes.stage to false))
    StoryArcs.dailyTick(sRes)
    check(recRes.done, "report audit: the set-up arc really resolved at the tick")
    val repRes = House.morningReport(sRes, House.newEvents(evRes, sRes.events),
        arcsRes, 0, false, null)
    check(repRes.none { it.contains("STORY'S END") },
        "report: the ticker's STORY'S END line is not repeated on the morning page")
    check(repRes.count { it.contains("resolved overnight") } == 1,
        "report: an overnight resolution is reported exactly once")
    check(repRes.size == repRes.distinct().size,
        "report: no duplicated lines on a resolution night")
    // (b) a stage turning overnight
    val sAdv = engRep.newState(); sAdv.absDay = 40
    val recAdv = StoryArcState(defRep.id, stage = 0,
        stageStartAbsDay = 38, startedAbsDay = 38)
    sAdv.storyArcs[defRep.id] = recAdv
    val evAdv = sAdv.events.toList()
    StoryArcs.dailyTick(sAdv)
    check(recAdv.stage == 1 && !recAdv.done,
        "report audit: the set-up stage really turned at the tick")
    val repAdv = House.morningReport(sAdv, House.newEvents(evAdv, sAdv.events),
        mapOf(defRep.id to (0 to false)), 0, false, null)
    check(repAdv.count { it.contains("turned a page overnight") } == 1,
        "report: an overnight page-turn is reported exactly once")
    check(repAdv.none { it == "· ${defRep.stages[1].banner}" },
        "report: the stage banner is not repeated on the morning page")
    check(repAdv.size == repAdv.distinct().size,
        "report: no duplicated lines on a page-turn night")
    // (c) an arc opening overnight
    val sOpen = engRep.newState(); sOpen.absDay = 10
    val evOpen = sOpen.events.toList()
    StoryArcs.dailyTick(sOpen)
    check(sOpen.storyArcs.containsKey(defRep.id),
        "report audit: the first arc really opened at the tick")
    val repOpen = House.morningReport(sOpen,
        House.newEvents(evOpen, sOpen.events), emptyMap(), 0, false, null)
    check(repOpen.count { it.contains("A new story opened") } == 1,
        "report: an overnight opening is reported exactly once")
    check(repOpen.none { it.contains("NEW STORY:") },
        "report: the ticker's NEW STORY line is not repeated on the morning page")
    check(repOpen.size == repOpen.distinct().size,
        "report: no duplicated lines on an opening night")
    // (d) the lost-and-found beat — and a feed that doubles it
    val reelLine = "🎞️ Bijou lost-and-found, cleaned out today: at the bottom, " +
        "one film reel. Unlabeled. Slightly dusty. The clerk logged it, shelved " +
        "it, and thought no more about it."
    val sReel = engRep.newState()
    val repReel = House.morningReport(sReel, listOf(reelLine, reelLine),
        emptyMap(), 0, false, null)
    check(repReel.count { it.contains("lost-and-found") } == 1,
        "report: even a duplicated feed line prints once (distinct by construction)")
    // (e) edge: the case closed BEFORE last night — not news
    val sRet = engRep.newState()
    sRet.arcRetired = true; sRet.arcChapter = 5; sRet.arcBranch = "town"
    val repRet = House.morningReport(sRet, emptyList(), emptyMap(), 5, true, null)
    check(repRet.none { it.contains("pond case") },
        "report: a case closed before last night is not re-reported")
    // (f) edge: finale lands AND a special sky AND chapters were
    // pending, all in one slept night — one line each, no more
    val sBig = engRep.newState(); sBig.absDay = 60
    sBig.arcRetired = true; sBig.arcChapter = 5; sBig.arcBranch = "town"
    sBig.life[SkyState.LAST_SKY_DAY_KEY] = 60
    sBig.lifeText[SkyState.LAST_SKY_KEY] = SkyState.AURORA
    val repBig = House.morningReport(sBig, emptyList(), emptyMap(), 3, false, null)
    check(repBig.count { it.contains("pond case is closed") } == 1,
        "report: the overnight close is reported exactly once")
    check(repBig.none { it.contains("chapter") },
        "report: a closed case does not also print a chapter line")
    check(repBig.count { it.contains("While you slept") } == 1,
        "report: the slept-through aurora gets its line the same morning")
    check(repBig.size == repBig.distinct().size,
        "report: no duplicated lines on a finale + sky night")
    // (g) spoiler hygiene: the pond truth stays out of the report
    val sTruth = engRep.newState()
    sTruth.arcRetired = true; sTruth.arcBranch = "truth"; sTruth.arcChapter = 5
    val repTruth = House.morningReport(sTruth, emptyList(), emptyMap(), 5, false, null)
    check(repTruth.any { it.contains("case is closed") },
        "report: the truth branch's close is reported")
    for (tell in listOf("Professor Chaos", "foil", "Butters",
        "bike helmet", "Fortress of Doom")) {
        check(repTruth.none { it.contains(tell) },
            "report: the closed-case line never tells ('$tell')")
    }
    // (h) spoiler hygiene: every booth-case landing stays
    // premise-only on the morning page, lost-and-found included
    for (branch in listOf("solved", "wrong", "cold")) {
        val sB = engRep.newState()
        sB.arcRetired = true; sB.arc2Retired = true
        sB.arc2Branch = branch; sB.arc2ReelFound = true
        val repB = House.morningReport(sB, listOf(reelLine),
            emptyMap(), 5, true, null)
        for (tell in listOf("confiscat", "lobby-adjacent",
            "for your own good", "took the reel", "stole the reel", "Mackey")) {
            check(repB.none { it.contains(tell, ignoreCase = true) },
                "report: booth-case mornings stay premise-only ('$tell', $branch)")
        }
        check(repB.count { it.contains("lost-and-found") } == 1,
            "report: the lost-and-found beat reaches the morning page ($branch)")
    }
    // (i) edge: a loader-clamped arc record cannot throw
    val sCorrupt = engRep.newState()
    sCorrupt.storyArcs[defRep.id] = StoryArcState(defRep.id,
        stage = defRep.stages.size, done = false, outcomeId = "")
    var corruptError: String? = null
    var repCorrupt: List<String> = emptyList()
    try {
        repCorrupt = House.morningReport(sCorrupt, emptyList(),
            mapOf(defRep.id to (defRep.stages.size to false)), 0, false, null)
    } catch (e: Exception) { corruptError = "${e.javaClass.simpleName}: ${e.message}" }
    check(corruptError == null && repCorrupt.isNotEmpty(),
        "report: a clamped arc record cannot throw the report (got $corruptError)")
    check(StoryArcs.pageLines(sCorrupt).isNotEmpty(),
        "report: the arcs page also survives the clamped record")
    val houseSrcG = File(root, "src/com/hunt3r/southparktown/House.kt").readText()
    check(houseSrcG.contains("storyOwned") && houseSrcG.contains("lines.distinct()"),
        "report: the dedupe is structural in House.kt, not a caller habit")

    // ---------- newest-screen fit QA (story arcs / house / both boards / accusation) ----------
    // Same discipline as v0.2.0g: the contrast pairs these
    // screens actually use, and their longest real lines
    // through the Chrome fit machinery at font scales 1.0/1.3.
    check(Chrome.contrast(Chrome.INK, Chrome.PARCHMENT) >= 4.5f,
        "fitQA: arcs page / boards / report ink on cardstock")
    check(Chrome.contrast(Chrome.INK_SOFT, Chrome.PARCHMENT) >= 4.5f,
        "fitQA: soft-ink body text on cardstock")
    check(Chrome.contrast("#ffffff", Chrome.RED) >= 4.5f,
        "fitQA: white on the accusation plaque red")
    check(Chrome.contrast(Chrome.RED, Chrome.CHARCOAL) >= 3.0f,
        "fitQA: red titles on charcoal (large bold)")
    val sPageG = engRep.newState()
    for (def in StoryArcs.ARCS) {
        sPageG.storyArcs[def.id] = StoryArcState(def.id,
            stage = def.stages.size, done = true, outcomeId = def.warm.id,
            finishedAbsDay = 100)
    }
    val arcsDoneLines = StoryArcs.pageLines(sPageG)
    val sPageMid = engRep.newState()
    val defMid = StoryArcs.ARCS[2]
    sPageMid.storyArcs[defMid.id] = StoryArcState(defMid.id, stage = 1,
        helpedStages = mutableSetOf(1))
    val arcsMidLines = StoryArcs.pageLines(sPageMid)
    val sBoardG = engRep.newState()
    sBoardG.arcStarted = true; sBoardG.arcChapter = 5
    for (c in Mystery.CLUES) sBoardG.mysteryClues.add(c.id)
    sBoardG.arcRetired = true; sBoardG.arcBranch = "town"
    val pondBoard = Mystery.boardLines(sBoardG)
    val sBoard2G = engRep.newState()
    sBoard2G.arcRetired = true; sBoard2G.arc2Started = true
    sBoard2G.arc2Retired = true; sBoard2G.arc2Branch = "cold"
    sBoard2G.arc2ReelFound = true
    sBoard2G.arc2Usher = "Alexandria Featherstonehaugh"
    for (c in Mystery2.CLUES2) sBoard2G.mystery2Clues.add(c.id)
    val boothBoard = Mystery2.boardLines2(sBoard2G)
    val sFit = engRep.newState(); sFit.absDay = 60
    sFit.arcRetired = true; sFit.arcChapter = 5; sFit.arcBranch = "town"
    sFit.life[SkyState.LAST_SKY_DAY_KEY] = 60
    sFit.lifeText[SkyState.LAST_SKY_KEY] = SkyState.METEOR
    sFit.storyArcs[defRep.id] = StoryArcState(defRep.id, stage = 2)
    val repMax = House.morningReport(sFit,
        listOf(reelLine) + (1..6).map {
            "📌 Overnight ticker item number $it with a reasonably long tail of text" },
        mapOf(defRep.id to (0 to false)), 3, false,
        "📬 Junk mail: one City Wok coupon (expired), a timeshare " +
            "flyer for Fairplay, and a very official envelope " +
            "containing absolutely nothing.")
    val accuseItems = listOf(
        "🎞️ Accuse Mr. Mackey — the chaperone (his story keeps moving)",
        "🍿 Accuse Clyde — near the booth; he wanted the ending",
        "😐 Accuse Craig — the deadpan non-alibi",
        "🎟️ Accuse ${Mystery2.suspectLabel(sBoard2G, "usher")} — the usher, the obvious suspect",
        "🤐 Say no name — let the case go cold")
    val shelfLine = "Collectibles: 0 of ${House.SHELF_SLOTS} shelf slots " +
        "filled — still out there: " +
        COLLECTIBLES.take(House.SHELF_SLOTS).joinToString(", ") { it.name } + "."
    val allNewLines = arcsDoneLines + arcsMidLines + pondBoard + boothBoard +
        repMax + accuseItems + listOf(shelfLine,
            "🛏️ Your bed", "😴 Sleep until morning (7:00 AM)",
            "📖 Just sit on the edge a minute")
    val innerWG = 420f
    for (fs in listOf(1.0f, 1.3f)) {
        val mFs = { s: String -> s.length * 10f * fs }
        for (line in allNewLines) {
            val e = Chrome.ellipsize(line, innerWG, measure = mFs)
            check(mFs(e) <= innerWG + 0.01f,
                "fitQA: a Queue #3 screen line fits at fs $fs")
            check(e.length >= 4,
                "fitQA: a Queue #3 screen line never collapses at fs $fs")
        }
    }
    val m10G = { s: String -> s.length * 10f }
    // (the intact-at-1.0 picks are the screens' genuinely
    // one-line chrome — the arcs/report/board BODY headers
    // wrap by design and are covered by the loop above)
    check(Chrome.ellipsize("📖 STORY ARCS", innerWG, measure = m10G) ==
        "📖 STORY ARCS", "fitQA: the arcs section title fits one line at fs 1.0")
    check(Chrome.ellipsize(boothBoard.first(), innerWG, measure = m10G) ==
        boothBoard.first(), "fitQA: the booth board title fits one line at fs 1.0")
    check(Chrome.ellipsize("🔍 The Locked Booth", innerWG, measure = m10G) ==
        "🔍 The Locked Booth", "fitQA: the accusation title fits its plaque at fs 1.0")

    // ---------- the veteran, re-measured (v0.2.0g's save, today's town) ----------
    val engVG = Engine(97)
    val vetG = engVG.newState()
    engVG.createPlayer(vetG, "Veteran", DEFAULT_APPEARANCE)
    vetG.gameYear = 2027; vetG.gameMonth = 6; vetG.gameDay = 15
    vetG.todayKey = "20270615"; vetG.lastPlayedDate = "20270615"; vetG.absDay = 400
    for (n in CharacterSystem.CAST.keys) vetG.friendship[n] = 100
    for ((_, a) in vetG.agents) repeat(25) {
        a.memories.add("A whole day in South Park, Colorado — the whole town " +
            "was involved and absolutely nobody learned a thing.")
    }
    repeat(40) { vetG.events.add("📌 A day where everything happened at once, again ($it)") }
    repeat(30) { townLogLine(vetG, "🎪 Town history entry $it — a full sentence about the day.") }
    for (sp in FISH_TABLE) vetG.fishLog[sp.id] = FishRecord(999, sp.maxCm)
    for (kid in CharacterSystem.CAST_KIDS) vetG.showdown[kid] = ShowdownRecord(400, 400)
    vetG.fishCasts = 9000; vetG.tacoHigh = 640; vetG.tacoPlays = 900
    vetG.followers = 250000
    for (item in ITEMS) vetG.inventory[item.id] = 99
    vetG.inventory[Minigames.COIN_ITEM] = 9999
    for (c in Mystery.CLUES) vetG.mysteryClues.add(c.id)
    vetG.arcStarted = true; vetG.arcChapter = 5
    vetG.arcRetired = true; vetG.arcBranch = "truth"
    for (c in Mystery2.CLUES2) vetG.mystery2Clues.add(c.id)
    vetG.arc2Started = true; vetG.arc2MarathonDay = 380
    vetG.arc2AccusationAired = true; vetG.arc2Retired = true
    vetG.arc2Branch = "wrong"; vetG.arc2Accused = "craig"
    vetG.arc2Usher = "Alexandria Featherstonehaugh"
    vetG.arc2RetiredDay = 390; vetG.arc2ReelFound = true
    vetG.arc2FlavorSeen.addAll(listOf("Clyde", "Craig"))
    for (def in StoryArcs.ARCS) {
        vetG.storyArcs[def.id] = StoryArcState(def.id, stage = def.stages.size,
            stageStartAbsDay = 390, startedAbsDay = 370, finishedAbsDay = 395,
            done = true, outcomeId = def.warm.id,
            helpedStages = (0 until def.stages.size).toMutableSet(),
            stageNudges = def.core.toMutableSet(),
            stageTalkShown = (def.parties + def.supporting).toMutableSet())
    }
    vetG.life["wishes"] = 500
    vetG.life[SkyState.LAST_SKY_DAY_KEY] = 400
    vetG.lifeText[SkyState.LAST_SKY_KEY] = SkyState.AURORA
    for (f in Minigames.GAME_FEATS) vetG.gameFeats.add(f.id)
    for (f in Photos.PHOTO_FEATS) vetG.photoFeats.add(f.id)
    repeat(24) { vetG.convertedResidents.add("Converted Resident With A Long Lore Name $it") }
    repeat(300) { vetG.photographed["Photographed Townsfolk With A Name $it"] = 7 }
    for (loc in LOCATIONS.keys) {
        vetG.locVisits[loc] = 999
        vetG.lifeText["mark:$loc"] = "Stan"
        vetG.lifeText["chalk:$loc"] = "a very elaborate chalk mural"
        vetG.lifeText["prank:$loc"] = "whoopee cushion, deluxe"
        vetG.life["clean:$loc"] = 9
    }
    for (n in CharacterSystem.CAST.keys) {
        vetG.npcGoals[n] = NpcGoal.fromMap(mapOf("npcKey" to n))!!
    }
    repeat(30) { i ->
        vetG.episodes.add(EpisodeRecord(
            key = "event$i@20260101", kind = "event", eventId = "event$i",
            eventTitle = "The Big Event $i", title = "The One Where Everything Happens $i",
            treatment = "A very special episode, presented without commercial interruption.",
            causers = listOf("Stan", "Kyle", "Cartman", "Kenny"),
            dayKey = "20260101", dateLabel = "1/1",
            stageTitles = listOf("Cold Open", "Act One", "Act Two", "The Wrap"),
            stageNotes = listOf("It starts.", "It escalates.", "It peaks.", "It lands."),
            finished = true, participation = 10))
    }
    repeat(60) { i ->
        vetG.photos.add(PhotoRecord(
            id = "vet$i", dayKey = "20270615", dateLabel = "6/15", timeMin = 700,
            locId = "MainStreet", inside = false, weatherId = "sunny",
            appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Veteran", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy"), PhotoFigure("Kyle", "cast", "goofy")),
            caption = "Best day ever in South Park with the whole gang, again ($i)",
            followersGained = 25, seed = i.toLong(), absDay = 340 + i))
    }
    val vetJsonG = Json.stringify(encodeGameState(vetG))
    println("veteran II game_state: ${vetJsonG.length} chars serialized")
    check(vetJsonG.length < 512 * 1024,
        "veteran: the modern saturated save stays under half a megabyte (got ${vetJsonG.length})")
    check(vetJsonG.length > 175413,
        "veteran: today's registries really are in there (beats v0.2.0g's 175,413)")
    @Suppress("UNCHECKED_CAST")
    val vetBackG = decodeGameState(Json.parse(vetJsonG) as Map<String, Any?>)
    check(vetBackG.episodes.size == 30 && vetBackG.photos.size == 60 &&
        vetBackG.convertedResidents.size == 24,
        "veteran: the capped collections round-trip at their caps")
    check((vetBackG.agents["Stan"]?.memories?.size ?: 0) <= 10,
        "veteran: round-tripped memories respect the save trim")
    check(vetBackG.storyArcs.size == StoryArcs.ARCS.size &&
        vetBackG.storyArcs.values.all { it.done && it.outcomeId.isNotEmpty() },
        "veteran: all five story endings survive the round trip")
    check(vetBackG.mysteryClues.size == Mystery.CLUES.size &&
        vetBackG.mystery2Clues == Mystery2.CLUES2.map { it.id }.toSet(),
        "veteran: both cases' full clue sets survive the round trip")
    check(vetBackG.photos.all { it.absDay >= 0 } && vetBackG.life["wishes"] == 500,
        "veteran: photo capture days and the wish count survive")
    check(House.decorFor(vetBackG).containsAll(setOf(
            "episode_keepsake", "photo_strip", "game_trophy", "mystery_truth")),
        "veteran: the derived house reads the saturated save correctly")

    // ---------- the ticker cap, at every add site ----------
    // The soak below caught the feed at 42: the 40-cap was
    // re-implemented per add site, and the sites that forgot
    // (both mystery cases' clue grants, the finale choice,
    // faction shifts, the lost-and-found, goal obituaries,
    // five GameActivity beats, one story banner) let a busy
    // rollover bulge past it. The save doc was always capped
    // at encode — this pins the IN-MEMORY invariant instead.
    val engCap = Engine(53)
    fun primedEvents(): GameState {
        val s = engCap.newState()
        s.events.clear()
        repeat(40) { s.events.add("📌 filler $it") }
        return s
    }
    val sCap1 = primedEvents()
    check(Mystery.grantClue(sCap1, Mystery.CLUES[0].id) &&
        sCap1.events.size <= 40,
        "cap: a pond clue grant holds the feed at 40 (got ${sCap1.events.size})")
    val sCap2 = primedEvents()
    check(Mystery2.grantClue2(sCap2, Mystery2.CLUES2[0].id) &&
        sCap2.events.size <= 40,
        "cap: a booth clue grant holds the feed at 40 (got ${sCap2.events.size})")
    val sCap3 = primedEvents()
    sCap3.arcRetired = true; sCap3.arc2Retired = true
    sCap3.arc2Branch = "cold"; sCap3.arc2RetiredDay = 10; sCap3.absDay = 20
    check(Mystery2.noteReelFound(sCap3) && sCap3.events.size <= 40,
        "cap: the lost-and-found beat holds the feed at 40 (got ${sCap3.events.size})")
    val sCap4 = primedEvents(); sCap4.absDay = 10
    StoryArcs.dailyTick(sCap4)
    check(sCap4.storyArcs.isNotEmpty() && sCap4.events.size <= 40,
        "cap: a story opening (two ticker lines) holds the feed at 40 " +
            "(got ${sCap4.events.size})")
    val sCap5 = primedEvents(); sCap5.absDay = 10
    sCap5.npcGoals["Stan"] = NpcGoal("Stan", 0, "ERRAND",
        "Fetch the thing", "Fetched the thing")
    sCap5.npcGoals["Kyle"] = NpcGoal("Kyle", 0, "ERRAND",
        "Fetch the other thing", "Fetched the other thing")
    NpcGoals.dailyRollover(sCap5)
    check(sCap5.events.size <= 40,
        "cap: goal obituaries hold the feed at 40 (got ${sCap5.events.size})")
    val fatDoc = decodeGameState(mapOf<String, Any?>(
        "events" to (1..60).map { "e$it" }))
    check(fatDoc.events.size == 40,
        "cap: even a hand-inflated save doc loads at 40 (got ${fatDoc.events.size})")

    // ---------- THE LIFETIME: the whole modern stack, 400 days ----------
    // The unified soak: one fresh town, driven through the
    // real daily stack (onNewDay: calendar, goals, stories,
    // all three mystery cases via the event slot, the sky
    // record, the lost-and-found) once per calendar day for a full
    // sky year and change — with a photo a week, like a
    // player lives. (Tick-level churn has its own tradition
    // in the v0.2.0g 60-day sim; this soak is the daily
    // stack, whole.) Ends only when every long system has
    // resolved and nothing is stuck.
    val engLife = Engine(777)
    val lifeS = engLife.newState()
    engLife.createPlayer(lifeS, "Lifer", DEFAULT_APPEARANCE)
    val lifeStart = lifeS.absDay
    var lifeError: String? = null
    var maxEvents = 0; var maxLog = 0; var maxEpisodes = 0
    var maxPhotos = 0; var maxLifeText = 0
    var maxUnprotectedPhotos = 0
    var maxErrands = 0
    var buzzMornings = 0
    val buzzKinds = mutableSetOf<String>()
    var skySpecials = 0
    var cycleAt100 = -1
    // v0.4.0g: the soak grows Queue #4's surfaces — errands
    // from all three sources, group photos in the weekly
    // habit, holiday beats played inside the lived year,
    // and barks decided by Barks.decide itself on a daily
    // entry cadence (cooldowns a local map, as GameActivity
    // keeps them: in memory only).
    val errandBySource = mutableMapOf<String, Int>()
    val compositionsSeen = mutableSetOf<String>()
    val barkCooldowns = mutableMapOf<String, Int>()
    val barkFires = mutableListOf<Pair<String, Int>>()
    val barkFireTimes = mutableListOf<Int>()
    val barkRnd = kotlin.random.Random(4242)
    val castNames = CharacterSystem.CAST.keys.toList()
    // v0.5.0i: Queue #5's surfaces join the lived year —
    // walking trips and bus rides on a cadence, the wardrobe
    // syncing off lived feats and seasons, a Pocket Pals
    // collection pursued at the machine and the trade table,
    // faction chains pushed through their standing gates,
    // the four season finales played (or pointedly not),
    // phone texts arriving under their caps all year, and
    // a weekly crowd gathered into clusters at the lifer's
    // corner. Tallies here; assertions in the end-state.
    val q5Rnd = kotlin.random.Random(777001)
    val locKeys = LOCATIONS.keys.toList()
    var wardrobeGrants = 0
    var palTrades = 0
    var palLastCopyViolations = 0
    var factionLands = 0
    val phoneTextIds = mutableSetOf<String>()
    var maxPhoneTexts = 0; var maxUnread = 0; var maxNotes = 0
    var crowdDays = 0; var crowdClustered = 0
    var prevErrandsDone = 0
    // v0.6.0g: Queue #6 tallies in the same lived year.
    var q6Paydays = 0
    var q6EarnedSeen = 0
    var q6FarmQuit = false
    var q6PaperQuit = false
    var q6StreakMax = 0
    var q6VotesCast = 0
    var q6StandingMax = 0
    var maxCommPlate = 0
    var maxCommState = 0
    val q6PrintIds = mutableSetOf<String>()
    // v0.7.0g: Queue #7's surfaces join the year — the
    // 62-cast town, town secrets under their real gates,
    // movie nights, school days, climaxes PLAYED at mixed
    // tiers, and the wave-3 newcomers met as townsfolk.
    // (The fifth case's due-observation rides the arc block
    // below with its four elders; its retirement is pinned
    // in the Queue #6 end-state and again in Queue #7's.)
    val q7Newcomers = listOf("Karen", "Scott", "Firkle",
        "Annie", "Bradley", "Skeeter", "Victoria", "Marvin",
        "Mr. Tucker", "Steve")
    val q7NewcomersMet = mutableSetOf<String>()
    var q7SecretsTried = 0
    var q7MoviesAttended = 0
    val q7MovieTiers = mutableSetOf<String>()
    var q7HeadlineNights = 0
    var q7LessonsSat = 0
    var q7RecessPlayed = 0
    var q7BeesIn = 0
    var q7ClimaxesPlayed = 0
    var maxMovieHist = 0
    var maxLessonHist = 0
    var maxBeeHist = 0
    var maxRecessHist = 0
    // v0.8.0g: Queue #8's surfaces join the same lived year —
    // the wave-4 newcomers met as townsfolk, capstones
    // driven through the town's real income (and the
    // below-gate hint heard on the way), emergencies priced
    // off the lifer's own corner and answered, declined or
    // let slip, a yearbook volume at the June turn with the
    // lifer's stars judged beside the unstarred, a rival
    // crowned and contested through the real funnels, and
    // the sixth case opening behind the fifth.
    val q8Newcomers = listOf("Ike", "Kevin McCormick", "Shelley",
        "Laura", "Mephesto", "Yates", "Adler", "Lu Kim")
    val q8NewcomersMet = mutableSetOf<String>()
    var q8CapHints = 0
    var q8EmergDays = 0
    var q8EmergAccepted = 0
    var q8EmergRescued = 0
    var q8EmergExpired = 0
    var q8EmergDeclined = 0
    var q8DeferenceDays = 0
    var q8EmergDeadlineOk = true
    // accepted emergencies the driver deliberately did
    // NOT settle itself (let slip, or a judge that didn't
    // land) — watched by id until the plate clears them,
    // so their fate (the town's funnels landed them after
    // all, or the rollover's expiry took them) is counted
    // from the module's own counter, never assumed
    val q8Watch = linkedMapOf<String, Int>()
    var q8TownCompleted = 0
    var q8EmergFailed = 0
    var q8OfferNullLive = 0
    var q8OfferNullStops = 0
    var q8OfferNullLate = 0
    var q8OfferNullOther = 0
    val q8StarredIds = mutableSetOf<String>()
    var q8RivalRevealed = false
    var q8RivalOffers = 0
    var q8RivalDeclines = 0
    var q8PranksAnswered = 0
    var q8Arc6Overlap = false
    var q8JobHired = false
    // land an armed faction beat through its verb's own
    // judge (sectionV050d's landBeat is local to that
    // section; this is the same dispatch, kept local here)
    fun landArmedQ5(s: GameState, b: FactionBeat): Boolean = when (b.verb) {
        "TALK" -> FactionMissions.judgeTalk(s, b.targetNpc!!)
            .any { it.beat == b }
        "GIVE" -> {
            s.inventory[b.itemId!!] = (s.inventory[b.itemId] ?: 0) + 1
            FactionMissions.onGive(s, b.targetNpc!!, b.itemId!!)
                .any { it.beat == b }
        }
        "LOOK" -> {
            s.timeMin = if (b.minMin > 0) b.minMin else 720
            FactionMissions.lookText(s, b.locId!!) != null
        }
        "PHOTO" -> FactionMissions.onPhoto(s, PhotoRecord(
            id = "life-fm-photo", dayKey = s.todayKey, dateLabel = "?",
            timeMin = 720, locId = b.locId!!, inside = false,
            weatherId = s.weatherId, appearance = DEFAULT_APPEARANCE,
            figures = emptyList())).any { it.beat == b }
        "CATCH" -> FactionMissions.onCatch(s, b.fishId ?: "pond_smelt")
            .any { it.beat == b }
        "SHOWDOWN" -> FactionMissions.onShowdown(s, true,
            b.targetNpc ?: "Stan").any { it.beat == b }
        "TACO" -> FactionMissions.onTaco(s, b.tacoMin!!)
            .any { it.beat == b }
        else -> false
    }
    /** Run one accepted errand through its own judge, the
     *  way a player would (fetch from the pack, deliver by
     *  talking, find by looking, fix by tapping, photo by
     *  shutter, play by settling a game). True when the
     *  town's done-count moved. */
    fun runThroughJudge(e: Errand, dayIdx: Int): Boolean {
        val before = lifeS.errandsDoneCount
        when (e.type) {
            "FETCH" -> {
                lifeS.inventory[e.itemId!!] =
                    (lifeS.inventory[e.itemId] ?: 0) + 1
                Errands.handInFetch(lifeS, e.asker, e.itemId!!)
            }
            "DELIVER" -> Errands.deliverTo(lifeS, e.targetName!!)
            "FIND" -> Errands.recoverFind(lifeS, e.targetLoc!!)
            "FIX" -> Errands.onFixTap(lifeS, e.fixKind!!,
                e.targetLoc ?: Errands.flickerLoc(lifeS.absDay))
            "PHOTO" -> Errands.onPhoto(lifeS, PhotoRecord(
                id = "lifeE$dayIdx", dayKey = lifeS.todayKey,
                dateLabel = "?", timeMin = 720,
                locId = e.targetLoc ?: "MainStreet",
                inside = false, weatherId = lifeS.weatherId,
                appearance = DEFAULT_APPEARANCE,
                figures = listOf(
                    PhotoFigure("Lifer", "player", "happy"),
                    PhotoFigure(e.targetName ?: "Stan", "cast", "happy")),
                seed = dayIdx.toLong(), absDay = lifeS.absDay))
            else -> when {
                e.playKind?.startsWith("fish:") == true ->
                    Errands.onPlayCatch(lifeS,
                        e.playKind.removePrefix("fish:"))
                e.playKind == "showdown" ->
                    Errands.onPlayShowdown(lifeS, true)
                else -> Errands.onPlayTaco(lifeS, 999)
            }
        }
        return lifeS.errandsDoneCount > before
    }
    // v0.6.0b: a completed chain head reveals its next link
    // onto the plate — the lifer runs revealed links through
    // the same judges, the way a player would, so chains
    // live (and close) inside the year instead of clogging
    // the plate the cadence feeds from.
    fun drainRevealed(dayIdx: Int) {
        var guard = 0
        while (guard++ < 6) {
            val link = Errands.active(lifeS)
                .firstOrNull { it.chainLink > 1 } ?: return
            if (!runThroughJudge(link, dayIdx)) return
        }
    }
    // v0.8.0g: land an armed capstone beat through its own
    // verb's judge, the way the town's funnels run — a TALK
    // at its place in its window, a photo through the real
    // shutter (the screening beat only while the house is
    // live), a catch through a real cast, a duel through
    // the real ShowdownDuel. VOTE beats cast the ballot and
    // let the week's count land them; JOB beats ride the
    // day loop's own job handling. True when the beat's
    // bit stands set afterwards.
    fun landCapstoneQ8(s: GameState, b: CapstoneBeat): Boolean {
        fun landed() = Capstones.mask(s, b.factionId) and
            (1 shl (b.beat - 1)) != 0
        when (b.verb) {
            "TALK" -> {
                if (b.locId != null)
                    s.agents[b.targetNpc!!]?.location = b.locId
                s.timeMin = when {
                    b.beat == 3 -> 16 * 60
                    b.minMin > 0 -> b.minMin + 30
                    else -> 10 * 60
                }
                Capstones.judgeTalk(s, b.targetNpc!!)
            }
            "GIVE" -> {
                s.inventory[b.itemId!!] =
                    (s.inventory[b.itemId!!] ?: 0) + 1
                Capstones.onGive(s, b.targetNpc!!, b.itemId!!)
            }
            "LOOK" -> {
                if (b.minMin > 0) s.timeMin = b.minMin + 30
                Capstones.lookText(s, b.locId!!)
            }
            "PHOTO" -> {
                if (b.needsScreening &&
                    !Capstones.screeningLive(s)) return false
                Photos.applyPhoto(s, PhotoRecord(
                    id = "life-cap-${s.absDay}-${b.factionId}",
                    dayKey = s.todayKey, dateLabel = "?",
                    timeMin = s.timeMin, locId = b.locId!!,
                    inside = CharacterSystem.npcInside(b.locId!!),
                    weatherId = s.weatherId,
                    appearance = DEFAULT_APPEARANCE,
                    figures = listOf(
                        PhotoFigure("Lifer", "player", "happy"),
                        PhotoFigure("Cartman", "cast", "happy")),
                    seed = s.absDay.toLong(), absDay = s.absDay))
            }
            "CATCH" -> {
                noteCast(s)
                val fs = FishingSession(
                    s.absDay * 31L + 7, s.weatherId, 10)
                fs.tap(fs.biteAtMs + 1)
                applyCatch(s, fs)
            }
            "SHOWDOWN" -> {
                val d = ShowdownDuel(
                    s.absDay * 17L + b.factionId.length,
                    b.targetNpc ?: "Stan")
                var guard = 0
                while (!d.over && guard++ < 300) {
                    d.resolveThrow(0.5f)
                    if (!d.over) d.resolveDodge(300L)
                }
                applyShowdownResult(s, d)
            }
            "TACO" -> Capstones.onTaco(s, b.tacoMin ?: 0)
            "VOTE" -> {
                val q = Votes.currentQuestion(s)
                Votes.castVote(s, q.options.first().id)
            }
            else -> {}
        }
        return landed()
    }
    try {
        repeat(400) { dayIdx ->
            // the ending night's sky, judged exactly as the
            // rollover judges it (ending day, its weather, its season)
            val endedDay = lifeS.absDay
            val endedWeather = lifeS.weatherId
            val endedSeason = seasonFor(lifeS.gameMonth)
            engLife.onNewDay(lifeS)
            if (SkyState.dateSpecial(endedDay, endedWeather, endedSeason) !=
                SkyState.NONE) skySpecials++
            SkyState.buzzKind(lifeS)?.let { buzzMornings++; buzzKinds += it }
            // v0.4.0g: holiday beats live in the year too —
            // in their windows the lifer plays the two
            // Talk/Look-judged beats through their own
            // judges, as the v0.4.0d calendar soak does.
            when (lifeS.holidayId) {
                "christmas" -> {
                    HolidayBeats.judgeTalk(lifeS, "Cartman")
                    HolidayBeats.judgeTalk(lifeS, "Kenny")
                    HolidayBeats.judgeTalk(lifeS, "Butters")
                    HolidayBeats.judgeTalk(lifeS, "Liane")
                }
                "stpatricks" -> {
                    for (loc in listOf("Elementary", "Church", "KidsPark",
                        "TweekBros", "SkeetersBar"))
                        HolidayBeats.lookText(lifeS, loc)
                }
            }
            if (dayIdx % 7 == 3) {
                // v0.4.0g: every fourth weekly photo is a
                // GROUP shot, composed from whoever the
                // rotation gathers at the lifer's corner —
                // the frame, the chemistry and the payouts
                // all run through composeGroup/applyPhoto.
                if (dayIdx % 28 == 3) {
                    val groupSets = listOf(
                        listOf("Stan", "Kyle", "Cartman", "Kenny"),
                        listOf("Craig", "Tweek", "Clyde"),
                        listOf("Stan", "Wendy", "Butters"),
                        listOf("Heidi", "Nichole", "Bebe"),
                        listOf("Stan", "Kyle"))
                    val set = groupSets[(dayIdx / 28) % groupSets.size]
                    val meA = lifeS.agents.values.firstOrNull { it.isPlayer }
                    for (n in set) lifeS.agents[n]?.let {
                        it.location = meA?.location ?: "MainStreet"
                    }
                    val grec = Photos.composeGroup(lifeS, set, emptyList(),
                        "Lifer", DEFAULT_APPEARANCE)
                    Photos.applyPhoto(lifeS, grec)
                    compositionsSeen += grec.composition
                } else {
                    Photos.applyPhoto(lifeS, PhotoRecord(
                        id = "life$dayIdx", dayKey = lifeS.todayKey, dateLabel = "?",
                        timeMin = 720, locId = "MainStreet", inside = false,
                        weatherId = lifeS.weatherId, appearance = DEFAULT_APPEARANCE,
                        figures = listOf(PhotoFigure("Lifer", "player", "happy"),
                            PhotoFigure("Stan", "cast", "happy")),
                        caption = "day $dayIdx in the park", followersGained = 3,
                        seed = dayIdx.toLong(), absDay = lifeS.absDay))
                }
            }
            // v0.8.0g: every third week the lifer stars the
            // week's photo from the Album, the way a player
            // curates — the yearbook will judge starred and
            // unstarred side by side at the June turn, and
            // the album cap must keep every star it is given.
            if (dayIdx % 21 == 3) {
                lifeS.photos.lastOrNull { it.id == "life$dayIdx" }
                    ?.let {
                        it.starred = true
                        q8StarredIds += it.id
                    }
            }
            // v0.4.0b: errands live in the year too — every
            // tenth day the lifer takes the board's first open
            // posting and runs it through its own judge, the
            // way a player would (fetch from the pack, deliver
            // by talking, find by looking, fix by tapping,
            // photo by shutter, play by settling a game).
            // v0.4.0g: direct asks (offset 2) and shopkeeper
            // asks (offset 7) join the same cadence, each
            // accepted and run through the same judges.
            if (dayIdx % 10 == 5) {
                val pick = Errands.boardOpen(lifeS).firstOrNull()
                if (pick != null && Errands.accept(lifeS, pick) &&
                    runThroughJudge(pick, dayIdx))
                    errandBySource[pick.source] =
                        (errandBySource[pick.source] ?: 0) + 1
            }
            if (dayIdx % 10 == 2) {
                val ask = KID_ORDER.firstNotNullOfOrNull {
                    Errands.askFor(lifeS, it)
                }
                if (ask != null && Errands.accept(lifeS, ask) &&
                    runThroughJudge(ask, dayIdx))
                    errandBySource[ask.source] =
                        (errandBySource[ask.source] ?: 0) + 1
            }
            if (dayIdx % 10 == 7) {
                val shop = Errands.SHOP_ASKERS.entries
                    .firstNotNullOfOrNull { (loc, npc) ->
                        Errands.shopAskFor(lifeS, npc, loc)
                    }
                if (shop != null && Errands.accept(lifeS, shop) &&
                    runThroughJudge(shop, dayIdx))
                    errandBySource[shop.source] =
                        (errandBySource[shop.source] ?: 0) + 1
            }
            // v0.7.0g: the wave-3 newcomers ask too — the
            // rotation walks all ten across the year, each
            // accepted and judged like anyone else's ask.
            if (dayIdx % 10 == 4) {
                val ncAsker = q7Newcomers[(dayIdx / 10) %
                    q7Newcomers.size]
                val ask = Errands.askFor(lifeS, ncAsker)
                if (ask != null && Errands.accept(lifeS, ask) &&
                    runThroughJudge(ask, dayIdx)) {
                    errandBySource[ask.source] =
                        (errandBySource[ask.source] ?: 0) + 1
                    q7NewcomersMet += ncAsker
                }
            }
            // v0.6.0b: whatever the cadence revealed, run it
            drainRevealed(dayIdx)
            // v0.4.0g: barks on a daily cadence, decided by
            // Barks.decide itself — three entries at waking
            // hours (the room rotates through the cast), one
            // lingering arrival, and one late-night entry
            // inside quiet hours that must stay silent.
            val rot = dayIdx % castNames.size
            val room = listOf(castNames[rot],
                castNames[(rot + 7) % castNames.size],
                castNames[(rot + 19) % castNames.size])
            fun barkAttempt(timeMin: Int, entered: Boolean,
                            present: List<String>, newcomers: Set<String>) {
                val nowAbs = lifeS.absDay * 1440 + timeMin
                val pickB = Barks.decide(true, timeMin, entered,
                    present.map { it to (lifeS.friendship[it] ?: 0) },
                    newcomers, barkCooldowns, nowAbs,
                    barkRnd.nextDouble(), barkRnd.nextDouble())
                if (pickB != null) {
                    barkCooldowns[pickB] = nowAbs
                    barkFires.add(pickB to nowAbs)
                    barkFireTimes.add(timeMin)
                }
            }
            barkAttempt(600, true, room, emptySet())
            barkAttempt(780, true, room, emptySet())
            barkAttempt(795, false, room + castNames[(rot + 23) % castNames.size],
                setOf(castNames[(rot + 23) % castNames.size]))
            barkAttempt(1170, true, room, emptySet())
            barkAttempt(1395, true, room, emptySet())
            // ---------- v0.5.0i: Queue #5 lives in the year ----------
            // Walking: every sixth day the lifer strolls to a
            // rotating corner of town, leg by leg through the
            // real judges (advance = false — the soak is the
            // daily stack; tick-level churn has its own
            // sections, and a walking tick could roll the date
            // under the soak's own onNewDay). The feat-pass
            // hook is mirrored weekly, as GameActivity calls
            // it on load; if the year is deep and the pass
            // still hasn't come, the lifer buys it at the Mall
            // kiosk like anyone else. Rides follow on their
            // own cadence once the pass is in the wallet.
            if (dayIdx % 6 == 1) {
                val dest = locKeys[(dayIdx / 6) % locKeys.size]
                var legGuard = 0
                while (engLife.player(lifeS).location != dest &&
                    legGuard++ < 20) {
                    Walk.walkTo(lifeS, dest, q5Rnd, advance = false)
                }
            }
            if (dayIdx % 10 == 9) Walk.ensureFeatPass(lifeS)
            if (dayIdx == 120 && !lifeS.busPass) {
                engLife.player(lifeS).location = "Mall"
                if (Minigames.capsuleCoins(lifeS) < Walk.BUS_PASS_PRICE)
                    lifeS.inventory[Minigames.COIN_ITEM] = Walk.BUS_PASS_PRICE
                Walk.buyPass(lifeS)
            }
            if (lifeS.busPass && dayIdx % 15 == 8) {
                val dest = locKeys[(dayIdx / 15 + 5) % locKeys.size]
                if (dest != engLife.player(lifeS).location)
                    Walk.ride(lifeS, dest, advance = false)
            }
            // The wardrobe syncs off the lived year — feats
            // crossed, seasons turned, cases retired — the
            // same call GameActivity makes on refresh.
            wardrobeGrants += Wardrobe.syncUnlocks(lifeS).size
            // Pocket Pals: a pull every fifth day (the driver
            // tops the machine fund up to the pull price when
            // the lived economy runs dry — the economy itself
            // is proven in v0.5.0c's section; here the binder
            // is what has to grow inside a lived year), and a
            // trade most weeks, with the last-copy rule watched
            // on every single one.
            if (dayIdx % 5 == 2) {
                if (Minigames.capsuleCoins(lifeS) < PocketPals.MACHINE_COST)
                    lifeS.inventory[Minigames.COIN_ITEM] =
                        PocketPals.MACHINE_COST
                PocketPals.pull(lifeS, q5Rnd)
            }
            if (dayIdx % 7 == 5) {
                val npc = castNames[(dayIdx / 7) % castNames.size]
                if (PocketPals.tradeOffer(lifeS, npc) != null) {
                    val singles = PocketPals.CARDS
                        .filter { PocketPals.count(lifeS, it) == 1 }
                        .map { it.id }.toSet()
                    if (PocketPals.executeTrade(lifeS, npc) != null) {
                        palTrades++
                        if (singles.any { PocketPals.count(lifeS,
                                PocketPals.cardById(it)!!) == 0 })
                            palLastCopyViolations++
                    }
                }
            }
            // Faction chains: one chain a day on rotation —
            // land its armed beat through the verb's own
            // judge, or take the front-person's next offer
            // and land that. Standing gates are the town's
            // problem: beat pays and road pitches (the walks
            // above) are the organic income.
            if (dayIdx % 8 == 4) {
                val chain = FactionMissions.CHAINS[
                    (dayIdx / 8) % FactionMissions.CHAINS.size]
                val armed = FactionMissions.activeBeat(lifeS, chain.factionId)
                if (armed != null) {
                    if (landArmedQ5(lifeS, armed)) factionLands++
                } else {
                    val offer = castNames.firstNotNullOfOrNull { n ->
                        FactionMissions.offerFor(lifeS, n)
                            ?.takeIf { it.factionId == chain.factionId }
                    }
                    if (offer != null && FactionMissions.accept(lifeS, offer) &&
                        landArmedQ5(lifeS, offer)) factionLands++
                }
            }
            // Season finales, as the year turns them up:
            // autumn played and called, winter ignored
            // outright, spring played and left to the town,
            // summer played and called the other way — the
            // same script the v0.5.0h year drive runs alone;
            // here it runs with the whole town in the way.
            Finales.activeWindow(lifeS)?.let { w ->
                if (w.def.id != "winter") {
                    val idx = Finales.currentStepIndex(lifeS, w.def,
                        w.instanceYear, w.dayIndex)
                    if (idx != null) {
                        val step = w.def.steps[idx]
                        when (step.verb) {
                            "TALK" -> {
                                if (step.loc != null)
                                    lifeS.agents[step.who]?.location = step.loc
                                Finales.judgeTalk(lifeS, step.who!!)
                            }
                            "LOOK" -> Finales.lookText(lifeS, step.loc!!)
                            "PHOTO" -> Finales.onPhoto(lifeS, PhotoRecord(
                                id = "life-fin-${w.def.id}-${w.instanceYear}",
                                dayKey = lifeS.todayKey, dateLabel = "?",
                                timeMin = 720, locId = step.loc!!,
                                inside = false, weatherId = lifeS.weatherId,
                                appearance = DEFAULT_APPEARANCE,
                                figures = emptyList(),
                                seed = dayIdx.toLong(), absDay = lifeS.absDay))
                        }
                    }
                    if (Finales.choiceDue(lifeS)) when (w.def.id) {
                        "autumn" -> Finales.choose(lifeS, w.def.choices[0].key)
                        "summer" -> Finales.choose(lifeS, w.def.choices[1].key)
                        // spring: played, but the call is the town's
                    }
                }
            }
            // The phone: the day's facts are noted the way
            // GameActivity's hooks note them (a photo day, a
            // finished errand), the inbox is read dry every
            // Sunday, and the caps are watched daily.
            if (dayIdx % 7 == 3)
                Phone.notePhoto(lifeS, "Stan", "MainStreet")
            if (lifeS.errandsDoneCount > prevErrandsDone) {
                Phone.noteErrand(lifeS,
                    castNames[lifeS.errandsDoneCount % castNames.size])
                prevErrandsDone = lifeS.errandsDoneCount
            }
            if (dayIdx % 7 == 6)
                for (t in Phone.threads(lifeS))
                    Phone.markThreadRead(lifeS, t.name)
            phoneTextIds += lifeS.phoneTexts.map { it.id }
            maxPhoneTexts = maxOf(maxPhoneTexts, lifeS.phoneTexts.size)
            maxUnread = maxOf(maxUnread, Phone.unreadCount(lifeS))
            maxNotes = maxOf(maxNotes, lifeS.phoneNotes.size)
            // A crowd, weekly: a dozen townsfolk gathered at
            // the lifer's corner, laid out by Crowds off the
            // same chemistry snapshot GameView builds.
            if (dayIdx % 7 == 6) {
                val here = engLife.player(lifeS).location
                val gathered = (0 until 12)
                    .map { castNames[(dayIdx + it * 3) % castNames.size] }
                    .distinct()
                for (n in gathered) lifeS.agents[n]?.location = here
                val presentG = gathered.toSet()
                val bondG = mutableMapOf<Set<String>, Int>()
                val rivalsG = mutableSetOf<Set<String>>()
                for (a in gathered) for (b in gathered) {
                    if (a >= b) continue
                    val key = setOf(a, b)
                    lifeS.npcBonds[engLife.bondKey(a, b)]?.let { bondG[key] = it }
                    if (relationNote(a, b) == "arch-rivals") rivalsG.add(key)
                }
                val layoutG = Crowds.layout(gathered, Crowds.Chem(
                    bond = bondG,
                    scriptPairs = PAIR_SCRIPTS.keys
                        .filter { p -> p.all { it in presentG } }.toSet(),
                    rivalPairs = rivalsG,
                    factionOf = gathered.mapNotNull { n ->
                        FACTION_OF_CAST[n]?.let { n to it } }.toMap()))
                if (layoutG != null && layoutG.placed.size == gathered.size) {
                    crowdDays++
                    if (layoutG.placed.any { it.clusterId >= 0 })
                        crowdClustered++
                }
            }
            // ---------- v0.6.0g: Queue #6 lives in the year ----------
            // Town jobs: paydays are counted where the rollover
            // actually pays them. The lifer applies at the farm
            // on the first shift morning that offers, works
            // every shift through the real judges, and gives
            // notice after a season; then a paper route the
            // same way, quit clean too.
            val earnedNow = Jobs.lifetimeEarned(lifeS)
            if (earnedNow > q6EarnedSeen) {
                q6Paydays++
                q6EarnedSeen = earnedNow
            }
            val farmDef = Jobs.defById("farm")!!
            val paperDef = Jobs.defById("paper")!!
            fun workShiftQ6(def: JobDef) {
                lifeS.timeMin = 8 * 60 + 30
                if (!Jobs.clockedIn(lifeS))
                    Jobs.judgeTalk(lifeS, Jobs.bossFor(lifeS, def),
                        Jobs.workplaceFor(lifeS, def))
                for (t in Jobs.tasksFor(lifeS, def)) when (t.kind) {
                    "LOOK" -> Jobs.lookText(lifeS, t.target)
                    "TALK" -> Jobs.judgeTalk(lifeS, t.target,
                        Jobs.workplaceFor(lifeS, def))
                }
                Jobs.judgeTalk(lifeS, Jobs.bossFor(lifeS, def),
                    Jobs.workplaceFor(lifeS, def))
                q6StreakMax = maxOf(q6StreakMax, Jobs.streak(lifeS))
            }
            if (Jobs.currentJob(lifeS) == null && !q6FarmQuit &&
                dayIdx >= 5 && Jobs.isShiftDay(lifeS.absDay, farmDef)) {
                lifeS.timeMin = 8 * 60 + 30
                Jobs.judgeTalk(lifeS, "Randy", "TegridyFarms")
            }
            if (Jobs.currentJob(lifeS) == null && q6FarmQuit && !q6PaperQuit &&
                dayIdx >= 160 && Jobs.isShiftDay(lifeS.absDay, paperDef)) {
                lifeS.timeMin = 8 * 60 + 30
                Jobs.judgeTalk(lifeS, "McDaniels", "CityHall")
            }
            Jobs.currentJob(lifeS)?.let { job ->
                val quitDay = (job.id == "farm" && dayIdx >= 150) ||
                    (job.id == "paper" && dayIdx >= 230)
                if (quitDay && Jobs.isShiftDay(lifeS.absDay, job) &&
                    !Jobs.clockedIn(lifeS) && !Jobs.shiftDoneToday(lifeS)) {
                    lifeS.timeMin = 10 * 60
                    Jobs.judgeTalk(lifeS, Jobs.bossFor(lifeS, job),
                        Jobs.workplaceFor(lifeS, job))
                    if (job.id == "farm") q6FarmQuit = true else q6PaperQuit = true
                } else if (Jobs.isShiftDay(lifeS.absDay, job) &&
                    !Jobs.shiftDoneToday(lifeS)) {
                    workShiftQ6(job)
                }
            }
            // Family evenings: host when a try finds an eligible
            // household (the evening then runs the hosted
            // beats); otherwise sit at the anchored invite
            // through its three beats, deferrals respected.
            if (dayIdx % 21 == 20 && Dinners.hostingTonight(lifeS) == null)
                Dinners.hostOptions(lifeS).firstOrNull { it.eligible }?.let {
                    Dinners.scheduleHosting(lifeS, it.def.id) }
            val hostingQ6 = Dinners.hostingTonight(lifeS)
            val inviteQ6 = Dinners.todaysInvite(lifeS)
            if (hostingQ6 != null) {
                lifeS.timeMin = 18 * 60
                Dinners.judgeTalk(lifeS, hostingQ6.host)
                if ((lifeS.inventory["snack_cake"] ?: 0) < 1)
                    lifeS.inventory["snack_cake"] = 1
                Dinners.lookText(lifeS, "YourHouse")
                hostingQ6.members.firstOrNull { it != hostingQ6.host }
                    ?.let { Dinners.judgeTalk(lifeS, it) }
            } else if (inviteQ6 != null && !Dinners.beatsDeferred(lifeS)) {
                lifeS.timeMin = 18 * 60
                Dinners.judgeTalk(lifeS, inviteQ6.host)
                inviteQ6.members.firstOrNull { it != inviteQ6.host }
                    ?.let { Dinners.judgeTalk(lifeS, it) }
                Dinners.lookText(lifeS, inviteQ6.house)
            }
            // Town votes: a ballot most weeks, through the
            // same castVote the fixture judges; standings are
            // observed, never forced.
            if (dayIdx % 7 == 2) {
                val q = Votes.currentQuestion(lifeS)
                Votes.castVote(lifeS, q.options[(dayIdx / 7) % q.options.size].id)
                q6VotesCast++
            }
            q6StandingMax = maxOf(q6StandingMax,
                Votes.QUESTIONS.count { Votes.standingOption(lifeS, it) != null })
            // Photo commissions: the board is taken weekly and
            // every held ask is shot through Photos.applyPhoto
            // — the same shutter that settles everything else.
            // Shooting pauses once the print run is long, so
            // the album's promise (a commissioned print is
            // never shed while anything else can go) is what
            // the end-state gets to check.
            if (dayIdx % 7 == 4) {
                if (lifeS.commissionsDone < 45) {
                    for (c in Commissions.boardOpen(lifeS)) {
                        if (Commissions.activeCount(lifeS) >=
                            Commissions.MAX_PLATE) break
                        Commissions.accept(lifeS, c)
                    }
                }
                for (c in Commissions.active(lifeS)) {
                    val figs = c.subjects.map {
                        PhotoFigure(it, "cast", "happy") } +
                        PhotoFigure("Lifer", "player", "happy")
                    Photos.applyPhoto(lifeS, PhotoRecord(
                        id = "life-comm-$dayIdx-${c.id}",
                        dayKey = lifeS.todayKey, dateLabel = "?",
                        timeMin = 720, locId = c.locId,
                        inside = CharacterSystem.npcInside(c.locId),
                        weatherId = lifeS.weatherId,
                        appearance = DEFAULT_APPEARANCE, figures = figs,
                        caption = "on commission", followersGained = 0,
                        seed = dayIdx.toLong() * 31 + c.id.hashCode(),
                        absDay = lifeS.absDay,
                        composition = if (c.condKind == "comp")
                            c.condValue else ""))
                }
                for (p in lifeS.photos) if (p.isCommissioned)
                    q6PrintIds += p.id
            }
            // ---------- v0.7.0g: Queue #7 lives in the year ----------
            // Town secrets: once a day the lifer stands where
            // each unfound secret lives, in the posture its
            // trigger wants, and tries the real trigger. The
            // GATE decides — a secret whose window is shut
            // today stays scenery, exactly as it does for a
            // player. Placement and the clock are restored
            // after; a discovery, once made, persists.
            run {
                val me = engLife.player(lifeS)
                val savedLoc = me.location
                val savedInside = lifeS.playerInside
                val savedTime = lifeS.timeMin
                for (secret in Secrets.SECRETS) {
                    if (Secrets.isFound(lifeS, secret)) continue
                    when (secret.trigger) {
                        Secrets.TRIGGER_LOOK -> {
                            val loc = secret.locId ?: continue
                            me.location = loc; me.destination = loc
                            me.waypoints.clear()
                            when (secret.gate) {
                                Secrets.GATE_DAY_IN -> {
                                    lifeS.playerInside = true
                                    lifeS.timeMin = 600
                                }
                                Secrets.GATE_DUSK_IN -> {
                                    lifeS.playerInside = true
                                    lifeS.timeMin = 1140
                                }
                                Secrets.GATE_NIGHT_IN -> {
                                    lifeS.playerInside = true
                                    lifeS.timeMin = 1320
                                }
                                Secrets.GATE_ALWAYS_IN -> {
                                    lifeS.playerInside = true
                                    lifeS.timeMin = 600
                                }
                                Secrets.GATE_AURORA_OUT -> {
                                    lifeS.playerInside = false
                                    lifeS.timeMin = 1320
                                }
                                Secrets.GATE_SNOW_OUT,
                                Secrets.GATE_RAIN_OUT,
                                Secrets.GATE_SPRING_OUT -> {
                                    lifeS.playerInside = false
                                    lifeS.timeMin = 600
                                }
                                else -> {
                                    lifeS.playerInside =
                                        CharacterSystem.npcInside(loc)
                                    lifeS.timeMin = 600
                                }
                            }
                            if (Secrets.gateOpen(lifeS, secret)) {
                                q7SecretsTried++
                                Secrets.lookText(lifeS, loc)
                            }
                        }
                        Secrets.TRIGGER_BENCH -> {
                            me.location = secret.locId!!
                            me.destination = secret.locId!!
                            me.waypoints.clear()
                            lifeS.playerInside = false
                            lifeS.timeMin = 600
                            if (Secrets.gateOpen(lifeS, secret)) {
                                q7SecretsTried++
                                Secrets.propTap(lifeS,
                                    Secrets.TRIGGER_BENCH)
                            }
                        }
                        Secrets.TRIGGER_GNOME -> {
                            val gl = TownLife.gnomeLocFor(lifeS)
                            me.location = gl; me.destination = gl
                            me.waypoints.clear()
                            lifeS.playerInside = false
                            lifeS.timeMin = 1320
                            if (Secrets.gateOpen(lifeS, secret)) {
                                q7SecretsTried++
                                Secrets.propTap(lifeS,
                                    Secrets.TRIGGER_GNOME)
                            }
                        }
                    }
                }
                me.location = savedLoc; me.destination = savedLoc
                me.waypoints.clear()
                lifeS.playerInside = savedInside
                lifeS.timeMin = savedTime
            }
            // School days: on a school day the town isn't
            // holding its breath for, the lifer sits the
            // morning lesson with the kids actually gathered
            // and referees the midday recess. The bee waits
            // below — an afternoon the climax takes is an
            // afternoon the bee goes unentered, and it
            // settles walked-away at midnight, as it should.
            if (School.isSchoolDay(lifeS.absDay) &&
                School.quietReason(lifeS) == null) {
                val me = engLife.player(lifeS)
                for (kid in CharacterSystem.CAST_KIDS) {
                    lifeS.agents[kid]?.let {
                        it.location = "Elementary"
                        it.destination = "Elementary"
                        it.waypoints.clear(); it.asleep = false
                    }
                }
                me.location = "Elementary"
                me.destination = "Elementary"
                me.waypoints.clear()
                lifeS.playerInside = true
                lifeS.timeMin = 10 * 60
                if (School.lessonStatus(lifeS).kind ==
                    School.LS_AVAILABLE &&
                    School.startLesson(lifeS)) {
                    val choice = listOf("right", "funny", "pass")[
                        dayIdx % 3]
                    var guard = 0
                    while (guard++ < 12) {
                        val beat = School.lessonBeat(lifeS) ?: break
                        if (beat.kind == "prompt") {
                            if (!School.answerLesson(lifeS, choice))
                                break
                        } else School.advanceLesson(lifeS)
                    }
                    if (School.recordFor(lifeS, lifeS.absDay) != null)
                        q7LessonsSat++
                }
                lifeS.timeMin = 12 * 60 + 5
                val rst = School.recessStatus(lifeS)
                if (rst.kind == School.RS_AVAILABLE &&
                    rst.beat != null && rst.a != null &&
                    rst.b != null) {
                    if (School.playRecess(lifeS,
                            rst.beat.options.first().id,
                            rst.a, rst.b) != null)
                        q7RecessPlayed++
                }
            }
            // Climaxes PLAYED: when the day's event stands at
            // its peak the lifer plays the chain — heroically
            // one day in three, fumbled the next, and one day
            // in three never shows at all (that event wraps
            // legacy, its beats untouched).
            var q7ClimaxTookAfternoon = false
            run {
                lifeS.timeMin = 13 * 60
                if (Climaxes.isLive(lifeS) && dayIdx % 3 != 0) {
                    val heroic = dayIdx % 3 == 1
                    var guard = 0
                    var done = false
                    loop@ while (guard++ < 60) {
                        val beat = Climaxes.sessionBeat(lifeS)
                            ?: break
                        when (beat.kind) {
                            "intro" -> Climaxes.begin(lifeS)
                            "result" -> Climaxes.advance(lifeS)
                            "done" -> { done = true; break@loop }
                            "choice" -> {
                                val cb = Climaxes.currentBeat(lifeS)
                                    ?: break@loop
                                val pick = if (heroic)
                                    cb.options.indices.maxByOrNull {
                                        cb.options[it].score }!!
                                else
                                    cb.options.indices.minByOrNull {
                                        cb.options[it].score }!!
                                Climaxes.choose(lifeS, pick)
                            }
                            "stand" -> {
                                val esc = Climaxes
                                    .currentEscalation(lifeS)
                                    ?: break@loop
                                val pick = if (heroic) esc.holdIndex
                                else esc.options.indices.first {
                                    it != esc.holdIndex }
                                Climaxes.standChoose(lifeS, pick)
                            }
                            "task" -> {
                                val cb = Climaxes.currentBeat(lifeS)
                                    ?: break@loop
                                if (heroic) {
                                    when (cb.kind) {
                                        Climaxes.KIND_PHOTO ->
                                            Climaxes.notePhoto(lifeS,
                                                Climaxes.climaxLoc(
                                                    SHENANIGAN_BY_ID[
                                                        lifeS.shenaniganId!!]!!)!!)
                                        Climaxes.KIND_FIND ->
                                            Climaxes.lookText(lifeS,
                                                cb.findLoc)
                                    }
                                    if (Climaxes.taskAction(lifeS, 0)
                                        != null) break@loop
                                } else Climaxes.taskAction(lifeS, 1)
                            }
                            else -> break@loop
                        }
                    }
                    if (done) {
                        q7ClimaxesPlayed++
                        q7ClimaxTookAfternoon = true
                    }
                }
            }
            // The Friday bee, on Fridays the climax didn't
            // take: spelled perfectly one bee, missed from
            // the first letter the next — some won, some lost.
            if (School.isBeeDay(lifeS.absDay) &&
                !q7ClimaxTookAfternoon &&
                School.quietReason(lifeS) == null) {
                val me = engLife.player(lifeS)
                me.location = "Elementary"
                me.destination = "Elementary"
                me.waypoints.clear()
                lifeS.playerInside = true
                lifeS.timeMin = 13 * 60 + 30
                if (School.beeStatus(lifeS) == School.BS_OPEN &&
                    School.enterBee(lifeS)) {
                    q7BeesIn++
                    val perfect = q7BeesIn % 2 == 1
                    var guard = 0
                    while (guard++ < 400) {
                        val beat = School.beeBeat(lifeS) ?: break
                        when (beat.kind) {
                            "letter" -> {
                                val word = School.currentWord(lifeS)
                                val idx = School.spellingProgress(lifeS)
                                    .split(" ").count { it != "_" }
                                val want = if (perfect) word[idx]
                                else School.letterOptions(lifeS)
                                    .first { it != word[idx] }
                                School.pickLetter(lifeS, want)
                            }
                            "done" -> {
                                School.advanceBee(lifeS); break
                            }
                            else -> School.advanceBee(lifeS)
                        }
                    }
                }
            }
            // Movie nights: on a screening night the Bijou
            // isn't dark for, the lifer takes a seat — a
            // perfect house one attended night in three, a
            // warm one the next, a whiffed one the third.
            // The audience the module derives is watched for
            // wave-3 faces, and Saturday's feature is the
            // vote's headline whenever the town has spoken.
            if (MovieNights.isScreeningDay(lifeS.absDay) &&
                !MovieNights.isDarkTonight(lifeS)) {
                val f = MovieNights.featureForDay(lifeS, lifeS.absDay)
                q7NewcomersMet += (MovieNights.attendance(lifeS) +
                    f.stars).filter { it in q7Newcomers }
                val me = engLife.player(lifeS)
                me.location = "Bijou"; me.destination = "Bijou"
                me.waypoints.clear()
                lifeS.playerInside = true
                lifeS.timeMin = MovieNights.DOORS_FROM + 15
                if (MovieNights.seat(lifeS)) {
                    val style = q7MoviesAttended % 3
                    var guard = 0
                    while (guard++ < 40) {
                        val beat = MovieNights.sessionBeat(lifeS)
                            ?: break
                        if (beat.kind == "prompt") {
                            val card = MovieNights.featureFor(lifeS)
                                .cards[beat.cardIndex]
                            val reaction = when (style) {
                                0 -> MovieNights.rightFor(card.beat)
                                1 -> if (beat.cardIndex == 1)
                                    MovieNights.closeFor(card.beat)
                                else MovieNights.rightFor(card.beat)
                                else -> listOf("laugh", "gasp",
                                    "applaud").first {
                                    it != MovieNights
                                        .rightFor(card.beat) &&
                                    it != MovieNights
                                        .closeFor(card.beat) &&
                                    it != "heckle" }
                            }
                            MovieNights.react(lifeS, reaction)
                        } else MovieNights.advance(lifeS)
                    }
                    val rec = MovieNights.recordFor(lifeS, lifeS.absDay)
                    if (rec != null) {
                        q7MoviesAttended++
                        q7MovieTiers += rec.tier
                        if (f.headline) q7HeadlineNights++
                    }
                }
            }
            // ---------- v0.8.0g: Queue #8 lives in the year ----------
            if (lifeS.arc6Started && !lifeS.arc5Retired)
                q8Arc6Overlap = true
            // Wave-4 newcomers ask on the wave-3 cadence —
            // accepted and judged like anyone else's ask —
            // and the Bijou's audiences carry their faces.
            if (dayIdx % 10 == 6) {
                val ncAsker = q8Newcomers[(dayIdx / 10) %
                    q8Newcomers.size]
                val ask = Errands.askFor(lifeS, ncAsker)
                if (ask != null && Errands.accept(lifeS, ask) &&
                    runThroughJudge(ask, dayIdx)) {
                    errandBySource[ask.source] =
                        (errandBySource[ask.source] ?: 0) + 1
                    q8NewcomersMet += ncAsker
                }
            }
            if (MovieNights.isScreeningDay(lifeS.absDay) &&
                !MovieNights.isDarkTonight(lifeS)) {
                val f = MovieNights.featureForDay(lifeS, lifeS.absDay)
                q8NewcomersMet += (MovieNights.attendance(lifeS) +
                    f.stars).filter { it in q8Newcomers }
            }
            // The below-gate hint, heard the way TalkGate's
            // owed lines speak it: a finished chain's senior,
            // once a day, while Beloved is still out of reach.
            for (chain in Capstones.CHAINS)
                if (Capstones.hintLine(lifeS, chain.seniorNpc) != null)
                    q8CapHints++
            // Capstones: one faction a day — take the offer
            // it fronts, land the armed beat through its own
            // judge. The Beloved gate is the town's income
            // (chains, tier crossings, road pitches), never
            // a fabrication; a faction the year can't afford
            // simply never asks, and its hint above is what
            // the lifer hears instead.
            run {
                val fid = Capstones.CHAINS[dayIdx %
                    Capstones.CHAINS.size].factionId
                var active = Capstones.activeBeat(lifeS, fid)
                if (active == null) {
                    val offer = castNames.firstNotNullOfOrNull { n ->
                        Capstones.offerFor(lifeS, n)
                            ?.takeIf { it.factionId == fid }
                    }
                    if (offer != null &&
                        Capstones.accept(lifeS, offer))
                        active = offer
                }
                if (active != null && active.verb == "JOB") {
                    // the parents' second beat lands on a real
                    // clock-out. If the lifer is between the
                    // soak's own two seasons, hire honestly —
                    // late enough that notice can still be
                    // given before the year ends.
                    var job = Jobs.currentJob(lifeS)
                    if (job == null && q6FarmQuit && q6PaperQuit &&
                        dayIdx in 240..360) {
                        val def = Jobs.JOBS.firstOrNull {
                            Jobs.isShiftDay(lifeS.absDay, it) }
                        if (def != null) {
                            lifeS.timeMin = 8 * 60 + 30
                            Jobs.judgeTalk(lifeS,
                                Jobs.bossFor(lifeS, def),
                                Jobs.workplaceFor(lifeS, def))
                            job = Jobs.currentJob(lifeS)
                            if (job != null) q8JobHired = true
                        }
                    }
                    if (job != null &&
                        Jobs.isShiftDay(lifeS.absDay, job) &&
                        !Jobs.shiftDoneToday(lifeS))
                        workShiftQ6(job)
                } else if (active != null) {
                    landCapstoneQ8(lifeS, active)
                }
                // a capstone job, once its beat has landed,
                // is given notice the way the soak's own
                // seasons ended — the boss, mid-morning,
                // not clocked in — until the card is clear.
                if (q8JobHired &&
                    Capstones.mask(lifeS, "parents") and 0b010 != 0) {
                    val cur = Jobs.currentJob(lifeS)
                    if (cur == null) {
                        q8JobHired = false
                    } else if (Jobs.isShiftDay(lifeS.absDay, cur) &&
                        !Jobs.clockedIn(lifeS) &&
                        !Jobs.shiftDoneToday(lifeS)) {
                        lifeS.timeMin = 10 * 60
                        Jobs.judgeTalk(lifeS,
                            Jobs.bossFor(lifeS, cur),
                            Jobs.workplaceFor(lifeS, cur))
                        if (Jobs.currentJob(lifeS) == null)
                            q8JobHired = false
                    }
                }
            }
            // Emergencies: when the day carries one, price
            // its offer off the lifer's own corner and check
            // the deadline against the Walk matrix on the
            // spot. The lifer answers most, turns one in
            // nine down flat, and lets one in nine slip past
            // its clock — the rollover's own expiry settles
            // those, and the count is taken as they leave
            // the plate.
            run {
                // the morning tick: an emergency's clock is
                // settled on the game's ticks, not at the
                // day roll — the one tick lived play always
                // gets, run here so yesterday's plate is
                // honestly yesterday's before today is read
                Emergencies.checkExpiry(lifeS)
                // resolve the watched: an accepted emergency
                // the driver left on the plate has settled
                // when it leaves the plate — by the rescue
                // counter if the town's own funnels landed
                // it after all, by expiry if they didn't
                val settled = q8Watch.keys.filter { id ->
                    lifeS.errands.none { it.id == id } }
                for (id in settled) {
                    val seen = q8Watch.remove(id)!!
                    if (Emergencies.rescuesDone(lifeS) > seen)
                        q8TownCompleted++
                    else q8EmergExpired++
                }
                val sc = Emergencies.todaysScenario(lifeS)
                if (sc != null) {
                    q8EmergDays++
                    lifeS.timeMin = 9 * 60
                    val owned = Emergencies.momentOwned(lifeS)
                    if (owned) q8DeferenceDays++
                    val me = engLife.player(lifeS)
                    val offer = Emergencies.pendingOffer(
                        lifeS, sc.asker, me.location)
                    if (offer == null && !owned) {
                        // why no offer, probed from the
                        // module's own gates — the audit
                        // wants the lived year's real shape
                        when {
                            Emergencies.liveEmergency(lifeS) != null ->
                                q8OfferNullLive++
                            Emergencies.stopsFor(lifeS, sc) == null ->
                                q8OfferNullStops++
                            lifeS.timeMin +
                                Emergencies.routeMinutes(lifeS,
                                    me.location,
                                    Emergencies.stopsFor(lifeS, sc)
                                        ?: emptyList()) +
                                Emergencies.allowance(
                                    Emergencies.stopsFor(lifeS, sc)
                                        ?.size ?: 0) >
                                Barks.QUIET_START ->
                                q8OfferNullLate++
                            else -> q8OfferNullOther++
                        }
                    }
                    if (offer != null) {
                        val expect = lifeS.timeMin +
                            Emergencies.routeMinutes(
                                lifeS, me.location, offer.stops) +
                            Emergencies.allowance(offer.stops.size)
                        if (expect != offer.deadlineMin)
                            q8EmergDeadlineOk = false
                        Emergencies.markOffered(lifeS, sc.asker)
                        // a slip is only honest on a quiet
                        // eve: if tomorrow runs an ask
                        // cadence, its judges could land
                        // the plate's errand themselves and
                        // the expiry would never be the
                        // rollover's own verdict
                        val quietEve = (dayIdx + 1) % 10 != 5 &&
                            (dayIdx + 1) % 10 != 6 &&
                            (dayIdx + 1) % 11 != 4
                        when {
                            dayIdx % 9 == 4 -> {
                                Emergencies.decline(lifeS)
                                q8EmergDeclined++
                            }
                            else -> {
                                val placed = Emergencies.accept(
                                    lifeS, offer)
                                if (placed != null) {
                                    q8EmergAccepted++
                                    // the rescue counter as it
                                    // stands BEFORE any judge
                                    // runs — the watched are
                                    // judged against this
                                    val seenBefore = Emergencies
                                        .rescuesDone(lifeS)
                                    if (dayIdx % 9 == 7 && quietEve) {
                                        q8Watch[placed.id] = seenBefore
                                    } else if (runThroughJudge(
                                            placed, dayIdx) &&
                                        lifeS.errands.firstOrNull {
                                            it.id == placed.id }
                                            ?.done == true) {
                                        // the judge gets the
                                        // credit only when the
                                        // emergency itself is
                                        // the one marked done —
                                        // a verb can land a twin
                                        // errand instead, and
                                        // then the rescue is
                                        // still owed
                                        q8EmergRescued++
                                    } else {
                                        q8EmergFailed++
                                        q8Watch[placed.id] = seenBefore
                                    }
                                }
                            }
                        }
                    }
                }
            }
            // The rival: the crown met when it falls due
            // (and the lifer, friendly-leaning, lets them
            // have the slice), pranks found by Looking and
            // answered mostly with mercy, challenges taken
            // three times in four and declined the fourth —
            // free, as promised. Every contest settles
            // through the funnel the game itself uses.
            run {
                val rival = Rival.rivalOf(lifeS)
                if (Rival.prankActive(lifeS) &&
                    !Rival.prankFound(lifeS))
                    Rival.prankLoc(lifeS)?.let {
                        Rival.lookText(lifeS, it) }
                lifeS.timeMin = 10 * 60
                val hit = Rival.talkStepFor(lifeS, rival)
                if (hit != null) when (hit.kind) {
                    "reveal" -> {
                        Rival.playReveal(lifeS, 2)
                        q8RivalRevealed = true
                    }
                    "lock" -> Rival.playLock(lifeS)
                    "prank" -> {
                        Rival.answerPrank(lifeS,
                            Rival.contestsPlayed(lifeS) % 4 == 0)
                        q8PranksAnswered++
                    }
                    "offer" -> {
                        q8RivalOffers++
                        if (q8RivalOffers % 4 == 0) {
                            Rival.decline(lifeS)
                            q8RivalDeclines++
                        } else when (hit.offerKind) {
                            Rival.K_SHOWDOWN -> {
                                Rival.accept(lifeS, hit.offerKind)
                                val d = ShowdownDuel(
                                    lifeS.absDay * 13L + 5, rival)
                                var guard = 0
                                while (!d.over && guard++ < 300) {
                                    d.resolveThrow(0.5f)
                                    if (!d.over) d.resolveDodge(300L)
                                }
                                applyShowdownResult(lifeS, d)
                            }
                            Rival.K_FISHING -> {
                                Rival.accept(lifeS, hit.offerKind)
                                noteCast(lifeS)
                                val fs = FishingSession(
                                    lifeS.absDay * 29L + 3,
                                    lifeS.weatherId, 10)
                                fs.tap(fs.biteAtMs + 1)
                                applyCatch(lifeS, fs)
                            }
                            Rival.K_RACE -> {
                                val acc = Rival.accept(
                                    lifeS, hit.offerKind)
                                val target = acc.raceTarget
                                if (target != null) {
                                    var guard = 0
                                    while (engLife.player(lifeS)
                                            .location != target &&
                                        guard++ < 24) {
                                        Walk.walkTo(lifeS, target,
                                            q5Rnd, advance = true)
                                    }
                                    Rival.raceArrival(lifeS, target)
                                }
                            }
                            else -> Rival.accept(lifeS, hit.offerKind)
                            // FOLLOWERS arms here and judges
                            // itself at the rollovers and the
                            // milestone funnel.
                        }
                    }
                    else -> {}
                }
            }
            maxMovieHist = maxOf(maxMovieHist,
                MovieNights.history(lifeS).size)
            maxLessonHist = maxOf(maxLessonHist,
                School.lessonHistory(lifeS).size)
            maxBeeHist = maxOf(maxBeeHist,
                School.beeHistory(lifeS).size)
            maxRecessHist = maxOf(maxRecessHist,
                School.recessHistory(lifeS).size)
            maxCommPlate = maxOf(maxCommPlate, Commissions.activeCount(lifeS))
            maxCommState = maxOf(maxCommState, lifeS.commissions.size)
            maxEvents = maxOf(maxEvents, lifeS.events.size)
            maxLog = maxOf(maxLog, lifeS.townLog.size)
            maxEpisodes = maxOf(maxEpisodes, lifeS.episodes.size)
            maxPhotos = maxOf(maxPhotos, lifeS.photos.size)
            // v0.9.0a: the album cap is SOFT by design (v0.6.0a:
            // commissioned prints never fade; v0.8.0d: starred
            // keepers neither) — with 70 cast the year's
            // commissions alone carried the shelf to 61. The
            // hard invariant is the UNPROTECTED count.
            maxUnprotectedPhotos = maxOf(maxUnprotectedPhotos,
                lifeS.photos.count { !it.isCommissioned && !it.starred })
            maxLifeText = maxOf(maxLifeText, lifeS.lifeText.size)
            maxErrands = maxOf(maxErrands, lifeS.errands.size)
            if (dayIdx == 99) {
                cycleAt100 = lifeS.npcGoals.values.maxOfOrNull { it.cycle } ?: -1
            }
            // (driven by onNewDay alone: exactly one calendar
            // day per iteration — the v0.3.0f lifetime pattern)
        }
    } catch (e: Exception) {
        lifeError = "${e.javaClass.simpleName}: ${e.message}"
    }
    println("lifetime: pond branch=${lifeS.arcBranch}, booth branch=${lifeS.arc2Branch}, " +
        "buried branch=${lifeS.arc3Branch}, " +
        "stories done=${lifeS.storyArcs.values.count { it.done }}/${StoryArcs.ARCS.size}, " +
        "sky specials=$skySpecials, buzz mornings=$buzzMornings $buzzKinds, " +
        "maxima: events=$maxEvents log=$maxLog episodes=$maxEpisodes " +
        "photos=$maxPhotos lifeText=$maxLifeText")
    check(lifeError == null,
        "lifetime: 400 days of the full stack without an exception (got $lifeError)")
    check(lifeS.absDay == lifeStart + 400,
        "lifetime: the calendar advanced exactly 400 days (got ${lifeS.absDay - lifeStart})")
    check(lifeS.arcRetired && lifeS.arcBranch.isNotEmpty(),
        "lifetime: the pond case retired inside the year (branch ${lifeS.arcBranch})")
    check(lifeS.arc2Retired && lifeS.arc2Branch == "cold",
        "lifetime: the booth case opened, played and went cold unattended")
    check(lifeS.arc2ReelFound,
        "lifetime: the lost-and-found beat fired inside the year")
    // v0.4.0f: the third case lives in the same year — it
    // queues ten days behind the booth case, digs its four
    // chapters, and an unattended town lets the county take
    // the box. No favor, no pending decision left dangling.
    check(lifeS.arc3Retired && lifeS.arc3Branch == "county",
        "lifetime: the buried case opened, dug and went to the county unattended")
    check(!lifeS.arc3Favor && !lifeS.arc3SharonPending,
        "lifetime: no favor stands and no decision dangles at day 400")
    check(StoryArcs.allDone(lifeS) &&
        lifeS.storyArcs.values.all { it.outcomeId.isNotEmpty() },
        "lifetime: all five story arcs resolved — none stuck")
    check(StoryArcs.activeDef(lifeS) == null && Mystery.dueChapter(lifeS) == null &&
        Mystery2.dueBeat(lifeS) == null && Mystery3.dueChapter3(lifeS) == null,
        "lifetime: nothing is still demanding the mystery slot at day 400")
    val lifeDecor = House.decorFor(lifeS)
    check("episode_keepsake" in lifeDecor,
        "lifetime: the house derived its episode poster from the lived year")
    check(listOf("mystery_truth", "mystery_silent", "mystery_town")
            .count { it in lifeDecor } == 1,
        "lifetime: exactly one mystery decor piece, branch-appropriate")
    check(maxEvents <= 40 && maxLog <= 30 && maxEpisodes <= 30 &&
        maxUnprotectedPhotos <= Photos.ALBUM_CAP,
        "lifetime: the capped collections never broke their caps " +
            "(the album's cap binds its unprotected shelf — prints " +
            "and starred keepers hold past it by design)")
    check(maxLifeText <= 330,
        "lifetime: lifeText stayed bounded across the year (max $maxLifeText; " +
            "the bound stood at 200 through the 70-cast town and moves " +
            "with the census — wave 6's 98 measured 211 at this seed, " +
            "the ninth case's year measured 221, and the scale & " +
            "space build's year (v0.15.0g — the town re-anchored at " +
            "home, so its meetings fall differently; no new lifeText " +
            "keys) measured 235; v0.16.0c moves the bound to 310 for " +
            "ONE disclosed reason: Travel's trip:<name> records — one " +
            "transient key per agent en route, shed on arrival, so " +
            "the year's peak (school-run simultaneity) measured 298; " +
            "v0.16.0d moves the bound to 330 for a MEASUREMENT reason, " +
            "disclosed in full: this rendering build adds NO lifeText " +
            "keys, but the year's micro-trajectory is sensitive to " +
            "compiled-artifact hash ordering — the unmodified " +
            "v0.16.0c tree measured 298 in its own build environment " +
            "and 307 re-measured in this one, and class overlays of " +
            "untouched sources swing the isolated soak's peak across " +
            "293–318; this tree measures 316, so the bound tracks the " +
            "measured peak with the same ~4% headroom as 298 -> 310)")
    check(lifeS.errandsDoneCount >= 20,
        "lifetime: errands ran all year — a board posting every ten days, " +
            "judged and done (got ${lifeS.errandsDoneCount})")
    check(maxErrands <= Errands.STATE_CAP &&
        lifeS.errandsRecent.size <= Errands.STATE_RECENT_CAP,
        "lifetime: the errand plate and its history never broke their caps " +
            "(max plate $maxErrands, recent ${lifeS.errandsRecent.size})")
    check(lifeS.errands.none { it.done },
        "lifetime: rollovers pruned every finished errand off the plate")
    check(lifeS.npcGoals.isNotEmpty() &&
        (lifeS.npcGoals.values.maxOfOrNull { it.cycle } ?: 0) > cycleAt100,
        "lifetime: goal cycles kept turning over (cycle $cycleAt100 -> " +
            "${lifeS.npcGoals.values.maxOfOrNull { it.cycle }})")
    check(skySpecials >= 1 && buzzMornings >= 1,
        "lifetime: the sky did its specials and the town woke up talking " +
            "($skySpecials specials, $buzzMornings buzz mornings)")
    val lifeJson = Json.stringify(encodeGameState(lifeS))
    println("lifetime save at day 400: ${lifeJson.length} chars serialized")
    check(lifeJson.length < 512 * 1024,
        "lifetime: a lived 400-day save stays under half a megabyte (got ${lifeJson.length})")
    @Suppress("UNCHECKED_CAST")
    val lifeBack = decodeGameState(Json.parse(lifeJson) as Map<String, Any?>)
    check(lifeBack.arcRetired && lifeBack.arc2Retired && lifeBack.arc3Retired &&
        StoryArcs.allDone(lifeBack),
        "lifetime: the lived year round-trips with every arc closed")
    check(lifeBack.errandsDoneCount == lifeS.errandsDoneCount &&
        lifeBack.errandsRecent.size == lifeS.errandsRecent.size,
        "lifetime: the lived year's errand tally round-trips")

    // ---------- v0.4.0g: Queue #4's surfaces, end-state ----------
    println("lifetime Q4: errands by source=$errandBySource, " +
        "group compositions=$compositionsSeen, " +
        "group shots=${lifeS.life["groupShots"]}, barks=${barkFires.size}")
    check((errandBySource[Errands.ASK] ?: 0) >= 3 &&
        (errandBySource[Errands.SHOP] ?: 0) >= 3,
        "lifetime: direct asks and shopkeeper asks were accepted and " +
            "completed through their judges all year (got $errandBySource)")
    check(HolidayBeats.yearsDone(lifeS, "christmas") >= 1 &&
        HolidayBeats.yearsDone(lifeS, "stpatricks") >= 1,
        "lifetime: two holiday beats completed inside the lived year " +
            "(christmas ${HolidayBeats.yearsDone(lifeS, "christmas")}, " +
            "stpatricks ${HolidayBeats.yearsDone(lifeS, "stpatricks")})")
    check(lifeS.life.keys.count { it.startsWith("hb:") } <= 2 * HOLIDAYS.size &&
        lifeS.life.keys.count { it.startsWith("hbYears:") } <= HOLIDAYS.size,
        "lifetime: beat keys stayed capped across the year")
    check((lifeS.life["groupShots"] ?: 0) >= 5 &&
        "squad" in compositionsSeen && "lineup" in compositionsSeen,
        "lifetime: group photos joined the weekly habit — posed frames " +
            "in more than one composition (shots " +
            "${lifeS.life["groupShots"]}, saw $compositionsSeen)")
    check(barkFires.size >= 600,
        "lifetime: barks fired all year under the real decision " +
            "(got ${barkFires.size})")
    check(barkFireTimes.none { Barks.inQuietHours(it) },
        "lifetime: no bark ever broke quiet hours, all year")
    check(barkFires.groupBy { it.first }.values.all { fires ->
            fires.map { it.second }.sorted().zipWithNext()
                .all { (a, b) -> b - a >= Barks.COOLDOWN_MINUTES }
        },
        "lifetime: no NPC ever barked inside their cooldown, all year")
    check((errandBySource[Errands.BOARD] ?: 0) >= 20,
        "lifetime: the board cadence alone ran all year (got $errandBySource)")

    // ---------- v0.5.0i: Queue #5's surfaces, end-state ----------
    val q5Beats = FactionMissions.CHAINS.sumOf {
        FactionMissions.beatsDone(lifeS, it.factionId) }
    val q5Marks = Finales.DEFS.map { it.id to Finales.markOf(lifeS, it) }
    println("lifetime Q5: trips=${lifeS.walkTrips}, legs=${lifeS.walkLegs}, " +
        "shortcuts=${lifeS.walkShortcuts.size}, rides=${lifeS.life["walkRides"]}, " +
        "pass=${lifeS.busPass}, wardrobe grants=$wardrobeGrants " +
        "(owned ${Wardrobe.ownedCount(lifeS)}/${Wardrobe.PIECES.size}), " +
        "pals pulls=${PocketPals.pulls(lifeS)}, owned=" +
        "${PocketPals.ownedCount(lifeS)}/${PocketPals.CARDS.size}, " +
        "trades=$palTrades, faction lands=$factionLands, beats=$q5Beats, " +
        "chains done=${FactionMissions.chainsDone(lifeS)}, " +
        "finale marks=${q5Marks.count { it.second != null }}/4, " +
        "phone texts seen=${phoneTextIds.size} (max stored $maxPhoneTexts, " +
        "max unread $maxUnread, max notes $maxNotes), " +
        "crowd days=$crowdDays (clustered $crowdClustered)")
    check(lifeS.walkTrips >= 15 && lifeS.walkLegs >= lifeS.walkTrips,
        "lifetime: the lifer walked all year — trips and legs on the " +
            "real graph (trips ${lifeS.walkTrips}, legs ${lifeS.walkLegs})")
    check(lifeS.walkShortcuts.isNotEmpty() &&
        lifeS.walkShortcuts.size <= Walk.SHORTCUT_CAP,
        "lifetime: shortcuts were learned on the road and stayed " +
            "capped (${lifeS.walkShortcuts.size})")
    check(lifeS.busPass && (lifeS.life["walkRides"] ?: 0) >= 3,
        "lifetime: the bus pass arrived inside the year and the bus " +
            "got ridden (rides ${lifeS.life["walkRides"]})")
    check(wardrobeGrants >= 3 && Wardrobe.ownedCount(lifeS) >= 3,
        "lifetime: the wardrobe unlocked off the lived year — feats, " +
            "seasons and specials firing (grants $wardrobeGrants, " +
            "owned ${Wardrobe.ownedCount(lifeS)})")
    check(PocketPals.pulls(lifeS) >= 30 &&
        PocketPals.ownedCount(lifeS) >= 6,
        "lifetime: the binder grew inside the year — pulls " +
            "${PocketPals.pulls(lifeS)}, owned " +
            "${PocketPals.ownedCount(lifeS)}/${PocketPals.CARDS.size}")
    check(palTrades >= 1 && palLastCopyViolations == 0,
        "lifetime: trades happened and no last copy was ever lost " +
            "(trades $palTrades, violations $palLastCopyViolations)")
    check(factionLands >= 5 && q5Beats >= 5,
        "lifetime: faction chains progressed through their gates " +
            "inside the year (lands $factionLands, beats $q5Beats, " +
            "chains done ${FactionMissions.chainsDone(lifeS)})")
    check(q5Marks.all { it.second != null },
        "lifetime: all four season finales left standing marks " +
            "(got ${q5Marks.filter { it.second != null }.map { it.first }})")
    val autumnMark = Finales.markOf(lifeS, Finales.defById("autumn")!!)
    val winterMark = Finales.markOf(lifeS, Finales.defById("winter")!!)
    val springMark = Finales.markOf(lifeS, Finales.defById("spring")!!)
    val summerMark = Finales.markOf(lifeS, Finales.defById("summer")!!)
    check(autumnMark?.byYou == true &&
        Finales.playedCount(lifeS, Finales.defById("autumn")!!) >= 1,
        "lifetime: autumn was played and called by the lifer")
    check(winterMark?.byYou == false &&
        Finales.playedCount(lifeS, Finales.defById("winter")!!) == 0,
        "lifetime: winter was ignored outright — the town wrapped " +
            "it alone and the mark says so")
    check(springMark?.byYou == false &&
        Finales.playedCount(lifeS, Finales.defById("spring")!!) >= 1,
        "lifetime: spring was played but left to the town's call")
    check(summerMark?.byYou == true &&
        Finales.playedCount(lifeS, Finales.defById("summer")!!) >= 1,
        "lifetime: summer was played and called by the lifer")
    check(Finales.DEFS.all { Finales.runs(lifeS, it) == 1 },
        "lifetime: every finale ran exactly once inside the year")
    check(phoneTextIds.size >= 12,
        "lifetime: the town texted all year (saw ${phoneTextIds.size} " +
            "distinct texts)")
    check(maxPhoneTexts <= Phone.MAX_TEXTS &&
        maxUnread <= Phone.MAX_UNREAD && maxNotes <= Phone.MAX_NOTES,
        "lifetime: the phone's caps held all year (stored " +
            "$maxPhoneTexts/${Phone.MAX_TEXTS}, unread " +
            "$maxUnread/${Phone.MAX_UNREAD}, notes $maxNotes/${Phone.MAX_NOTES})")
    check(crowdDays >= 40 && crowdClustered >= 20,
        "lifetime: weekly crowds gathered and clustered all year " +
            "(days $crowdDays, clustered $crowdClustered)")

    // ---------- v0.6.0g: Queue #6's surfaces, end-state ----------
    val q6PrintsKept = lifeS.photos.count { it.isCommissioned }
    val q6HouseholdsSat = Dinners.HOUSEHOLDS.count {
        Dinners.attendedCount(lifeS, it) > 0 }
    println("lifetime Q6: commissions done=${lifeS.commissionsDone} " +
        "(prints kept $q6PrintsKept of ${q6PrintIds.size} seen, " +
        "plate max $maxCommPlate, state max $maxCommState), " +
        "chains done=${lifeS.life["chainsDone"] ?: 0}, " +
        "dinners attended=${Dinners.totalAttended(lifeS)} across " +
        "$q6HouseholdsSat households, hosted=${Dinners.totalHosted(lifeS)}, " +
        "wages=${Jobs.lifetimeEarned(lifeS)} over $q6Paydays paydays " +
        "(farm shifts ${Jobs.totalShifts(lifeS, Jobs.defById("farm")!!)}, " +
        "paper shifts ${Jobs.totalShifts(lifeS, Jobs.defById("paper")!!)}, " +
        "streak max $q6StreakMax), votes cast=$q6VotesCast, " +
        "standings max=$q6StandingMax, " +
        "arc4 retired=${lifeS.arc4Retired} branch=${lifeS.arc4Branch}")
    check(lifeS.commissionsDone >= 20 && q6PrintIds.isNotEmpty() &&
        q6PrintsKept == q6PrintIds.size,
        "lifetime: commissions were accepted and shot all year and " +
            "every commissioned print is still in the album — the " +
            "cap sheds anything else first (done " +
            "${lifeS.commissionsDone}, prints $q6PrintsKept/" +
            "${q6PrintIds.size})")
    check(maxCommPlate <= Commissions.MAX_PLATE &&
        maxCommState <= Commissions.STATE_CAP &&
        lifeS.commissionRecent.size <= Commissions.RECENT_CAP,
        "lifetime: the commission plate, list and recent record " +
            "never broke their caps (plate $maxCommPlate, state " +
            "$maxCommState, recent ${lifeS.commissionRecent.size})")
    check((lifeS.life["chainsDone"] ?: 0) >= 3 &&
        lifeS.errands.filter { it.chainLen > 0 }.all {
            it.chainLink in 1..it.chainLen &&
                it.chainRest.size == it.chainLen - it.chainLink },
        "lifetime: chained favors ran to closure inside the year " +
            "and no live link is malformed (chains done " +
            "${lifeS.life["chainsDone"] ?: 0})")
    check(lifeS.arc4Retired &&
        lifeS.arc4Branch in Mystery4.BRANCH_KEYS &&
        Mystery4.fixTokensByLoc(lifeS).isNotEmpty() &&
        Mystery4.dueChapter4(lifeS) == null,
        "lifetime: the fourth case opened behind the third, played " +
            "its chapters in the same year and retired — a " +
            "four-case lifetime (branch ${lifeS.arc4Branch}, its " +
            "standing traces still on the town)")
    check(lifeS.arc5Retired &&
        lifeS.arc5Branch in Mystery5.BRANCH_KEYS &&
        Mystery5.dueChapter5(lifeS) == null,
        "lifetime: the fifth case opened behind the fourth and " +
            "retired unattended inside the same year — a five-case " +
            "lifetime (branch ${lifeS.arc5Branch})")
    check(Dinners.totalAttended(lifeS) >= 15 && q6HouseholdsSat >= 3,
        "lifetime: family evenings were sat across the town all " +
            "year (attended ${Dinners.totalAttended(lifeS)}, " +
            "households $q6HouseholdsSat)")
    check(Dinners.totalHosted(lifeS) >= 1,
        "lifetime: the lifer's own table hosted at least one " +
            "family evening inside the year (hosted " +
            "${Dinners.totalHosted(lifeS)})")
    check(Jobs.lifetimeEarned(lifeS) > 0 && q6Paydays >= 12 &&
        q6StreakMax >= Jobs.STEADY_STREAK,
        "lifetime: wages landed on real paydays all year and the " +
            "streak reached the Steady tier (earned " +
            "${Jobs.lifetimeEarned(lifeS)}, paydays $q6Paydays, " +
            "streak $q6StreakMax)")
    check(Jobs.totalShifts(lifeS, Jobs.defById("farm")!!) >= 20 &&
        Jobs.totalShifts(lifeS, Jobs.defById("paper")!!) >= 10 &&
        Jobs.currentJob(lifeS) == null && q6FarmQuit && q6PaperQuit,
        "lifetime: a farm season and a paper season were both " +
            "worked and both quit clean — nobody's employed at " +
            "day 400 (farm " +
            "${Jobs.totalShifts(lifeS, Jobs.defById("farm")!!)}, " +
            "paper ${Jobs.totalShifts(lifeS, Jobs.defById("paper")!!)})")
    check(q6VotesCast >= 45 &&
        Votes.history(lifeS).size == Votes.HISTORY_CAP &&
        q6StandingMax >= 1,
        "lifetime: the ballot box was fed most weeks, counts " +
            "landed all year and outcomes stood on the town " +
            "(cast $q6VotesCast, history " +
            "${Votes.history(lifeS).size}/${Votes.HISTORY_CAP}, " +
            "standings max $q6StandingMax)")

    // ---------- v0.7.0g: Queue #7's surfaces, end-state ----------
    val q7ClimaxTally = mutableMapOf<String, Int>()
    for (ep in lifeS.episodes) {
        if (ep.kind != "event" || !ep.finished) continue
        val t = Episodes.climaxTierOf(ep)
        if (t.isNotEmpty()) q7ClimaxTally[t] =
            (q7ClimaxTally[t] ?: 0) + 1
    }
    val q7BarkNewcomers = barkFires.map { it.first }
        .filter { it in q7Newcomers }.distinct()
    println("lifetime Q7: secrets found=" +
        "${Secrets.foundCount(lifeS)}/12 (open-gate attempts " +
        "$q7SecretsTried): " +
        "${Secrets.foundSecrets(lifeS).map { it.id }}, " +
        "movies attended=$q7MoviesAttended " +
        "tiers=$q7MovieTiers headline nights=$q7HeadlineNights " +
        "(history max $maxMovieHist), lessons=$q7LessonsSat " +
        "recess=$q7RecessPlayed bees in=" +
        "${School.beeEntered(lifeS)} won=${School.beeWon(lifeS)} " +
        "(history max $maxLessonHist/$maxBeeHist/$maxRecessHist), " +
        "climaxes played=$q7ClimaxesPlayed tiers=$q7ClimaxTally, " +
        "newcomers met=${q7NewcomersMet.size} " +
        "(barked ${q7BarkNewcomers.size})")
    check(Secrets.foundCount(lifeS) >= 9,
        "lifetime: a year's honest looking found most of the " +
            "town's secrets — every one through its own gate, " +
            "in its own window (found " +
            "${Secrets.foundCount(lifeS)}/12: " +
            "${Secrets.foundSecrets(lifeS).map { it.id }})")
    check(Secrets.foundCount(lifeS) <= Secrets.SECRET_COUNT &&
        Secrets.SECRETS.all {
            !Secrets.isFound(lifeS, it) ||
                Secrets.discoveryOf(lifeS, it) != null },
        "lifetime: the found-set never outgrew the registry, " +
            "and every find carries its record")
    check(q7MoviesAttended >= 25 &&
        MovieNights.attendedCount(lifeS) == q7MoviesAttended &&
        MovieNights.TIER_LEGENDARY in q7MovieTiers &&
        MovieNights.TIER_DEAD in q7MovieTiers,
        "lifetime: movie nights ran all year at every buzz — " +
            "perfect houses and dead ones both (attended " +
            "$q7MoviesAttended, tiers $q7MovieTiers)")
    check(q7HeadlineNights >= 1,
        "lifetime: the vote's pick headlined at least one " +
            "lived Saturday (got $q7HeadlineNights)")
    check(maxMovieHist <= MovieNights.HISTORY_CAP &&
        MovieNights.history(lifeS).size == MovieNights.HISTORY_CAP,
        "lifetime: the movie history rode at its cap, never " +
            "past it (max $maxMovieHist)")
    check(q7LessonsSat >= 40 &&
        School.lessonsSat(lifeS) == q7LessonsSat,
        "lifetime: lessons were sat all year through the real " +
            "session (sat $q7LessonsSat)")
    check(q7RecessPlayed >= 20,
        "lifetime: recesses were refereed all year (got " +
            "$q7RecessPlayed)")
    check(School.beeEntered(lifeS) >= 8 &&
        School.beeWon(lifeS) >= 1 &&
        School.beeEntered(lifeS) - School.beeWon(lifeS) >= 1,
        "lifetime: Friday bees were entered all year — some " +
            "won, some lost (in ${School.beeEntered(lifeS)}, " +
            "won ${School.beeWon(lifeS)})")
    check(maxLessonHist <= School.HISTORY_CAP &&
        maxBeeHist <= School.BEE_HISTORY_CAP &&
        maxRecessHist <= School.RECESS_HISTORY_CAP,
        "lifetime: the school histories never broke their " +
            "caps (lessons $maxLessonHist, bees $maxBeeHist, " +
            "recess $maxRecessHist)")
    check(q7ClimaxesPlayed >= 20 &&
        (q7ClimaxTally[Climaxes.TIER_HEROIC] ?: 0) >= 1 &&
        (q7ClimaxTally[Climaxes.TIER_FUMBLED] ?: 0) >= 1 &&
        ((q7ClimaxTally[Climaxes.TIER_ABSENT] ?: 0) +
            (q7ClimaxTally["legacy"] ?: 0)) >= 1,
        "lifetime: climaxes were PLAYED at mixed tiers all " +
            "year — heroic and fumbled both — and the events " +
            "the lifer skipped still read absent/legacy " +
            "(played $q7ClimaxesPlayed, tiers $q7ClimaxTally)")
    check(q7NewcomersMet.size >= 5 &&
        q7BarkNewcomers.isNotEmpty(),
        "lifetime: the wave-3 newcomers lived in the town — " +
            "asked, attended, starred, barked (met " +
            "${q7NewcomersMet.size}: $q7NewcomersMet; barked " +
            "${q7BarkNewcomers.size})")
    check(lifeS.arcRetired && lifeS.arc2Retired &&
        lifeS.arc3Retired && lifeS.arc4Retired &&
        lifeS.arc5Retired,
        "lifetime: a FIVE-case lifetime — every case opened " +
            "behind the last and retired inside the one long " +
            "save, none overlapping")

    // ---------- v0.8.0g: Queue #8's surfaces, end-state ----------
    val q8CapDone = Capstones.CHAINS.count {
        Capstones.capstoneDone(lifeS, it.factionId) }
    val q8Volumes = Yearbook.volumes(lifeS)
    val q8RivalKinds = Rival.contestLog(lifeS)
        .map { it.kind }.toSet()
    val q8StarredKept = q8StarredIds.count { id ->
        lifeS.photos.any { it.id == id } }
    println("lifetime Q8: newcomers met=${q8NewcomersMet.size} " +
        "$q8NewcomersMet, capstones done=$q8CapDone " +
        "(hints heard $q8CapHints), emergency days=$q8EmergDays " +
        "(accepted $q8EmergAccepted, rescued $q8EmergRescued, " +
        "town-landed $q8TownCompleted, expired $q8EmergExpired, " +
        "declined $q8EmergDeclined, deference mornings " +
        "$q8DeferenceDays, no-offer days: live-plate " +
        "$q8OfferNullLive, no-route $q8OfferNullStops, " +
        "too-late $q8OfferNullLate, other $q8OfferNullOther, " +
        "judges that didn't land $q8EmergFailed), yearbook " +
        "volumes=${q8Volumes.size} (photos judged " +
        "${q8Volumes.sumOf { it.photoCount }}), stars kept " +
        "$q8StarredKept/${q8StarredIds.size}, rival=" +
        "${Rival.rivalOf(lifeS)} contests=" +
        "${Rival.contestsPlayed(lifeS)} kinds=$q8RivalKinds " +
        "standing=${Rival.standingOf(lifeS)} " +
        "locked=${Rival.locked(lifeS)} " +
        "pranks answered=$q8PranksAnswered, arc6 " +
        "started=${lifeS.arc6Started} " +
        "retired=${lifeS.arc6Retired} branch=${lifeS.arc6Branch}")
    check(q8NewcomersMet.size >= 5,
        "lifetime: the wave-4 newcomers lived in the town — " +
            "asked, attended, starred (met " +
            "${q8NewcomersMet.size}: $q8NewcomersMet)")
    check(q8CapDone >= 1,
        "lifetime: at least one capstone was driven to its " +
            "ceremony inside the year, on income the town " +
            "actually paid (done $q8CapDone of " +
            "${Capstones.CHAINS.size})")
    check(q8CapHints >= 1,
        "lifetime: a finished chain's senior spoke the " +
            "below-gate hint inside the year — Beloved was " +
            "a road, not a switch (heard $q8CapHints)")
    check(q8EmergDays in 100..220,
        "lifetime: emergency days inside the year's band — " +
            "the 0.40 dial over 400 lived days (got $q8EmergDays)")
    check(q8EmergRescued >= 5 && q8EmergDeclined >= 1,
        "lifetime: emergencies were answered through the " +
            "errand verbs and turned down flat, both inside " +
            "the year (rescued $q8EmergRescued, declined " +
            "$q8EmergDeclined)")
    check(q8EmergExpired >= 1,
        "lifetime: at least one accepted emergency slipped " +
            "past its clock and the rollover settled it — " +
            "failure stayed free (expired $q8EmergExpired)")
    check(q8EmergDeadlineOk,
        "lifetime: every offered deadline in the lived year " +
            "recomputed exactly — now + the Walk route's true " +
            "minutes + the allowance, at the lifer's own corner")
    check(Emergencies.rescuesDone(lifeS) ==
        q8EmergRescued + q8TownCompleted,
        "lifetime: the rescue counter agrees with the lived " +
            "count, to the rescue — every settlement is " +
            "accounted: landed by the driver's own judges, " +
            "or by the town's funnels off a plate the driver " +
            "left loaded (counter " +
            "${Emergencies.rescuesDone(lifeS)}, driver " +
            "$q8EmergRescued, town $q8TownCompleted)")
    check(q8Volumes.size == 1 && !q8Volumes[0].pamphlet &&
        q8Volumes[0].photoCount >= 30,
        "lifetime: exactly one yearbook volume published at " +
            "the June turn inside the year — a full book off " +
            "a lived album, not a pamphlet (volumes " +
            "${q8Volumes.size}, photos " +
            "${q8Volumes.firstOrNull()?.photoCount})")
    check(q8Volumes.isNotEmpty() &&
        q8Volumes[0].entries.isNotEmpty() &&
        q8Volumes[0].entries.all { e ->
            e.record == null ||
                Yearbook.categoryById(e.categoryId)?.let { cat ->
                    Yearbook.scoreOf(cat, e.record!!) == e.score
                } == true },
        "lifetime: every published winner's printed score " +
            "recomputes from its own stored record — fields " +
            "plus the star, nothing else")
    check(q8Volumes.isNotEmpty() &&
        q8Volumes[0].entries.any { it.record?.starred == true } &&
        q8Volumes[0].entries.any { it.record?.starred == false },
        "lifetime: the June book crowned starred and " +
            "unstarred photos side by side — the star is a " +
            "bonus, not a coronation")
    check(q8StarredIds.isNotEmpty() &&
        q8StarredKept == q8StarredIds.size,
        "lifetime: the album cap kept every star the lifer " +
            "ever set (kept $q8StarredKept/${q8StarredIds.size})")
    check(q8RivalRevealed &&
        Rival.contestsPlayed(lifeS) >= Rival.LOCK_AT &&
        Rival.locked(lifeS),
        "lifetime: the rival was crowned in a played moment, " +
            "contested past the lock, and the standing stands " +
            "recorded (contests ${Rival.contestsPlayed(lifeS)}, " +
            "standing ${Rival.standingOf(lifeS)})")
    check(q8RivalKinds.size >= 3 &&
        Rival.contestLog(lifeS).size <= Rival.LOG_CAP,
        "lifetime: the contests spread across kinds and the " +
            "ledger kept its cap (kinds $q8RivalKinds, log " +
            "${Rival.contestLog(lifeS).size}/${Rival.LOG_CAP})")
    check(Rival.locked(lifeS) &&
        lifeS.lifeText["rivalStanding"] == Rival.standingOf(lifeS) &&
        Rival.pageLines(lifeS).any {
            it.contains("Standing: " +
                Rival.standingLabel(Rival.standingOf(lifeS))) },
        "lifetime: the locked standing is recorded once, " +
            "read back whole, and spoken on the Journal page " +
            "in its own label — escalations " +
            "${Rival.escalations(lifeS)}, mercies " +
            "${Rival.mercies(lifeS)}")
    check(!q8Arc6Overlap,
        "lifetime: the sixth case never opened over the " +
            "fifth — not one morning of the lived year")
    check(lifeS.arc6Started && lifeS.arc5Retired,
        "lifetime: the sixth case opened behind the fifth " +
            "inside the one long save — a six-case lifetime " +
            "begun in the same year (retired " +
            "${lifeS.arc6Retired}, branch ${lifeS.arc6Branch})")
    // The memory store is process-global — one save on a
    // device, many worlds in this suite. The lifer's season
    // of work wrote the work topic into it; later sections
    // are entitled to a store holding only what their own
    // worlds wrote, so the year hands it back clean.
    // v0.7.0g: the same courtesy for Queue #7's topics — a
    // year of played climaxes plants retellings on every
    // causer in town, and v0.7.0e's absent-event pins are
    // entitled to a store that never heard of them.
    val q7Topics = setOf(Jobs.TOPIC, Secrets.TOPIC,
        MovieNights.TOPIC, School.TOPIC, Climaxes.TOPIC_HEROIC,
        Climaxes.TOPIC_HANDLED, Climaxes.TOPIC_FUMBLED)
    // v0.8.0g: the same courtesy for Queue #8's topics — a
    // year of capstones, rescues, yearbook arguments and
    // rivalry planted its threads on half the town, and
    // the sections after this one are entitled to a store
    // holding only what their own worlds wrote.
    val q8Topics = setOf(Capstones.TOPIC_PENDING,
        Capstones.TOPIC_DONE, Rival.TOPIC,
        Emergencies.RESCUE_TOPIC, Yearbook.TOPIC_WIN,
        Yearbook.TOPIC_SNUB)
    for ((_, mem) in NpcMemoryStore.all())
        mem.topics.removeAll { it in q7Topics || it in q8Topics }
}
}

private fun sectionV040a(root: String) {
// ================= v0.4.0a: scene parity pass #4 =================
// Horizons & sight-lines — opens the 0.4.0 series. Passes #1-#3
// made every place agree with itself; this one makes the town
// agree with itself: Horizon.kt derives each exterior's
// skyline from the map (the EXITS graph + gx/gy) as a pure
// function — graph neighbors on their true bearings, shrunk
// by their true distances, cut by the weather's sight range,
// plus the water tower and the rim's mountain ridge — and
// SceneArt + PhotoView render the same list, so a photo's
// skyline is the scene's skyline.
println("== v0.4.0a: horizons & sight-lines — the skyline is the map ==")
run {
    val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    val photoSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
    val horizonSrc = File(root, "src/com/hunt3r/southparktown/Horizon.kt").readText()

    // ---------- the registry: one silhouette per place ----------
    check(LOC_SILHOUETTES.size == 27, "horizon: the registry covers all 27 locations")
    check(LOC_SILHOUETTES.keys == LOCATIONS.keys,
        "horizon: registry keys are exactly the locations")
    val silToks = LOC_SILHOUETTES.values.toList()
    check(silToks.distinct().size == 27, "horizon: 27 distinct silhouette tokens")
    for ((id, tok) in LOC_SILHOUETTES) {
        check(sceneSrc.contains("silhouette: $tok"), "horizon: drawn — $id/$tok")
    }
    check(sceneSrc.contains("silhouette: ${Horizon.WATER_TOWER_TOKEN}"),
        "horizon: the water tower is drawn")
    check(sceneSrc.contains("silhouette: ${Horizon.RIDGE_TOKEN}"),
        "horizon: the mountain ridge is drawn")
    // a silhouette is its own drawing — no token is borrowed
    // from the close-up registries of passes #1-#3
    val otherToks = (LOC_ART_DETAILS.values.flatten() +
        LOC_LIGHT_DETAILS.values.flatten() + LOC_SEASON_DETAILS.values.flatten() +
        INTERIOR_ART_DETAILS.values.flatten()).toSet()
    for (tok in silToks) {
        check(tok !in otherToks, "horizon: $tok belongs to the silhouette registry only")
    }

    // ---------- tiers, heights, sight ----------
    check(Horizon.tierFor(0f) == Horizon.TIER_NEAR &&
        Horizon.tierFor(Horizon.NEAR_MAX) == Horizon.TIER_NEAR,
        "horizon: the near tier reaches NEAR_MAX")
    check(Horizon.tierFor(Horizon.NEAR_MAX + 0.1f) == Horizon.TIER_MID &&
        Horizon.tierFor(Horizon.MID_MAX) == Horizon.TIER_MID,
        "horizon: the mid tier spans to MID_MAX")
    check(Horizon.tierFor(Horizon.MID_MAX + 0.1f) == Horizon.TIER_FAR,
        "horizon: past MID_MAX is far")
    check(Horizon.heightFrac(Horizon.TIER_NEAR) > Horizon.heightFrac(Horizon.TIER_MID) &&
        Horizon.heightFrac(Horizon.TIER_MID) > Horizon.heightFrac(Horizon.TIER_FAR),
        "horizon: nearer silhouettes stand taller")
    check(Horizon.sightRange("fog") == Horizon.NEAR_MAX,
        "horizon: fog ends sight at the near tier")
    check(Horizon.sightRange("blizzard") == 30f, "horizon: blizzard sight is 30 units")
    check(Horizon.sightRange("heavy_snow") == Horizon.MID_MAX,
        "horizon: heavy snow sight reaches the mid tier")
    check(Horizon.sightRange("sunny") == Float.MAX_VALUE &&
        Horizon.sightRange("rain") == Float.MAX_VALUE &&
        Horizon.sightRange("wind") == Float.MAX_VALUE,
        "horizon: rain and clear skies keep the whole town in view")

    // ---------- the rim is the map's edge, by rule ----------
    val rim = LOCATIONS.values.filter { Horizon.isRim(it) }.map { it.id }.toSet()
    check(rim == setOf("KennysHouse", "TegridyFarms", "StarksPond", "Elementary",
        "TolkienHouse", "SoDoSoPa", "BusStop"),
        "horizon: the rim set is the map edge (got $rim)")

    // ---------- the graph is mutual (the reciprocity premise) ----------
    for ((a, exits) in EXITS) {
        for (b in exits) {
            check(a in (EXITS[b] ?: emptyList()), "horizon: the graph is mutual ($a <-> $b)")
        }
    }

    // ---------- every exterior on a clear day: the graph, exactly ----------
    for ((id, loc) in LOCATIONS) {
        val ps = Horizon.placementsFor(id, "sunny")
        val seen = ps.mapNotNull { it.targetId }.toSet()
        check(seen == (EXITS[id] ?: emptyList()).toSet(),
            "horizon: $id sees exactly its graph neighbors — no more, no fewer (got $seen)")
        check(seen.isNotEmpty(), "horizon: $id sees at least one true neighbor")
        check(id !in seen, "horizon: $id never sees itself")
        for (p in ps) {
            check(p.xFrac in 0f..1f, "horizon: $id's ${p.token} stands in frame")
            val tId = p.targetId ?: continue
            check(p.token == LOC_SILHOUETTES[tId],
                "horizon: $id sees $tId wearing $tId's own silhouette")
            val t = LOCATIONS[tId]!!
            val d = Horizon.distFor(t.gx - loc.gx, t.gy - loc.gy)
            close(p.dist, d, 0.01f, "horizon: $id -> $tId distance is the map's")
            check(p.tier == Horizon.tierFor(d),
                "horizon: $id -> $tId tier matches its distance")
            val dx = t.gx - loc.gx
            if (dx > 0) check(p.xFrac > 0.5f,
                "horizon: $tId is EAST of $id and stands on the right")
            if (dx < 0) check(p.xFrac < 0.5f,
                "horizon: $tId is WEST of $id and stands on the left")
        }
        val dists = ps.filter { !it.backdrop }.map { it.dist }
        check(dists == dists.sortedDescending(),
            "horizon: $id's skyline paints far to near")
        val ridge = ps.firstOrNull { it.backdrop }
        if (id in rim) {
            check(ridge != null && ridge.token == Horizon.RIDGE_TOKEN && ps.first() == ridge,
                "horizon: rim spot $id opens on its ridge")
        } else {
            check(ridge == null, "horizon: $id is not on the rim — no ridge")
        }
        // the tower: a clear day puts it in EVERY view in town
        val tower = ps.firstOrNull { it.token == Horizon.WATER_TOWER_TOKEN }
        check(tower != null && tower.targetId == null,
            "horizon: the water tower stands over $id on a clear day")
        if (tower != null) {
            val td = Horizon.distFor(Horizon.WATER_TOWER_GX - loc.gx,
                Horizon.WATER_TOWER_GY - loc.gy)
            close(tower.dist, td, 0.01f, "horizon: $id's tower distance is the map's")
            check(td <= Horizon.LANDMARK_MAX && tower.tier == Horizon.tierFor(td),
                "horizon: $id's tower is in landmark range, tiered by distance")
        }
        // purity: same inputs, same skyline; the band moves nothing
        check(Horizon.placementsFor(id, "sunny") == ps,
            "horizon: $id's skyline is a pure function")
        check(Horizon.sightLines(id, "day", "sunny") == ps &&
            Horizon.sightLines(id, "dusk", "sunny") == ps &&
            Horizon.sightLines(id, "night", "sunny") == ps,
            "horizon: $id's geography ignores the light band")
    }
    check(Horizon.placementsFor("Nowhere", "sunny").isEmpty(),
        "horizon: an unknown place has no skyline")
    check(!horizonSrc.contains("Prefs") && !horizonSrc.contains("Random"),
        "horizon: the derivation stores nothing and rolls nothing")

    // ---------- reciprocity: the map reads the same both ways ----------
    for ((a, exits) in EXITS) {
        for (b in exits) {
            val ab = Horizon.placementsFor(a, "sunny").firstOrNull { it.targetId == b }
            val ba = Horizon.placementsFor(b, "sunny").firstOrNull { it.targetId == a }
            check(ab != null && ba != null, "horizon: $a and $b see each other")
            if (ab != null && ba != null) {
                close(ab.dist, ba.dist, 0.01f, "horizon: $a<->$b distance agrees both ways")
                val wrapped = ((ba.xFrac - ab.xFrac) % 1f + 1f) % 1f
                close(wrapped, 0.5f, 0.01f,
                    "horizon: $b stands half a panorama from where $a stands in $b's view")
                val dx = LOCATIONS[b]!!.gx - LOCATIONS[a]!!.gx
                if (dx != 0) {
                    check((ab.xFrac > 0.5f) == (ba.xFrac < 0.5f),
                        "horizon: $a and $b mirror each other's sides")
                }
            }
        }
    }

    // ---------- signature sight-lines, pinned ----------
    run {
        fun from(id: String, weather: String = "sunny") =
            Horizon.placementsFor(id, weather)
        fun sees(id: String, target: String, weather: String = "sunny") =
            from(id, weather).firstOrNull { it.targetId == target }
        // the pond's treeline over the park's shoulder, right side
        val pond = sees("KidsPark", "StarksPond")
        check(pond != null && pond.token == "pond-treeline" &&
            pond.tier == Horizon.TIER_MID && pond.xFrac in 0.6f..0.8f,
            "horizon: the pond tree line stands right of the park, mid-distance")
        // the residential row reads in quarters: same street, dy = 0
        close(sees("StanHouse", "KyleHouse")!!.xFrac, 0.75f, 0.001f,
            "horizon: Kyle's is due east of Stan's — right quarter")
        close(sees("StanHouse", "CartmanHouse")!!.xFrac, 0.25f, 0.001f,
            "horizon: Cartman's is due west of Stan's — left quarter")
        close(sees("Church", "CityHall")!!.xFrac, 0.75f, 0.001f,
            "horizon: City Hall is due east of the church")
        // downtown's one FAR neighbor: the farm, small on the skyline
        val farm = sees("MainStreet", "TegridyFarms")
        check(farm != null && farm.tier == Horizon.TIER_FAR,
            "horizon: Tegridy is Main Street's lone far silhouette")
        check(from("MainStreet").count { it.targetId != null && it.tier == Horizon.TIER_FAR } == 1,
            "horizon: exactly one far neighbor stands over Main Street")
        // the bus stop hangs at the panorama's seam from Cartman's
        val stop = sees("CartmanHouse", "BusStop")
        check(stop != null && stop.xFrac > 0.85f,
            "horizon: due south wraps to the seam (the bus stop from Cartman's)")
        // the tower rides near center-north over Main Street
        val towerMs = from("MainStreet").first { it.token == Horizon.WATER_TOWER_TOKEN }
        check(towerMs.xFrac in 0.45f..0.58f && towerMs.tier == Horizon.TIER_MID,
            "horizon: the tower stands north over Main Street, mid-distance")
    }

    // ---------- weather cuts the sight-lines ----------
    run {
        fun seenIds(id: String, weather: String) =
            Horizon.placementsFor(id, weather).mapNotNull { it.targetId }.toSet()
        // fog: Main Street keeps its block and loses the rest of town
        check(seenIds("MainStreet", "fog") == setOf("TweekBros", "JimbosGuns",
            "CityWok", "SkeetersBar", "TomsRhino", "Bank", "PostOffice", "CityHall"),
            "horizon: fog leaves Main Street its near neighbors only")
        check(Horizon.placementsFor("MainStreet", "fog")
            .all { it.backdrop || it.tier == Horizon.TIER_NEAR },
            "horizon: nothing mid or far survives the fog")
        check("ButtersHouse" in seenIds("KennysHouse", "fog"),
            "horizon: even in fog, Kenny's still sees Butters' — his one neighbor")
        check(Horizon.placementsFor("MainStreet", "fog")
            .none { it.token == Horizon.WATER_TOWER_TOKEN },
            "horizon: fog swallows the tower from Main Street")
        check(Horizon.placementsFor("KidsPark", "fog")
            .any { it.token == Horizon.WATER_TOWER_TOKEN },
            "horizon: the park sits close enough to keep the tower in fog")
        // heavy snow: only the far drops
        val hs = seenIds("MainStreet", "heavy_snow")
        check("TegridyFarms" !in hs && "Elementary" in hs && "Bijou" in hs,
            "horizon: heavy snow drops the far farm, keeps the mid town")
        // a blizzard cuts into the mid tier too
        val bz = seenIds("MainStreet", "blizzard")
        check("Bijou" !in bz && "KidsPark" !in bz && "BusStop" !in bz &&
            "Church" in bz && "FreemansTacos" in bz,
            "horizon: the blizzard cuts Main Street's sight at 30 units")
        // rain cuts nothing — it only darkens (the wear's job)
        check(seenIds("MainStreet", "rain") == seenIds("MainStreet", "sunny"),
            "horizon: rain shortens nothing")
    }

    // ---------- band colors & weather wear ----------
    hexEq(Horizon.colorFor("day"), "#8fa9c8", "horizon: day silhouettes are pale blue-grey")
    hexEq(Horizon.colorFor("dusk"), "#57486b", "horizon: dusk silhouettes are cutouts")
    hexEq(Horizon.colorFor("night"), "#131b30", "horizon: night silhouettes are near-black")
    for (band in listOf("day", "dusk", "night")) {
        check(SceneLight.wearHex(Horizon.colorFor(band), "sunny") == Horizon.colorFor(band),
            "horizon: a clear day leaves the $band skyline byte-exact")
    }
    fun spread(hex: String): Int {
        val v = hex.removePrefix("#").toInt(16)
        val ch = listOf(v shr 16 and 255, v shr 8 and 255, v and 255)
        return ch.max() - ch.min()
    }
    fun floorOf(hex: String): Int {
        val v = hex.removePrefix("#").toInt(16)
        return minOf(v shr 16 and 255, v shr 8 and 255, v and 255)
    }
    check(spread(SceneLight.wearHex(Horizon.colorFor("day"), "fog")) <
        spread(Horizon.colorFor("day")),
        "horizon: fog grays the skyline like everything else")
    check(floorOf(SceneLight.wearHex(Horizon.colorFor("night"), "blizzard")) >
        floorOf(Horizon.colorFor("night")),
        "horizon: a blizzard whites the night skyline out")
    check(sceneSrc.contains("SceneLight.wearHex(Horizon.colorFor(band), weatherId)"),
        "horizon: the renderer runs the band color through the wear")

    // ---------- both surfaces render the derivation ----------
    check(sceneSrc.contains("Horizon.placementsFor"),
        "horizon: the scene derives its skyline from Horizon")
    check(sceneSrc.contains("drawHorizon(c, 0f, h * 0.618f"),
        "horizon: the scene draws the layer on the horizon line, behind the field")
    check(photoSrc.contains("SceneArt.drawHorizon"),
        "horizon: the selfie backdrop draws the same horizon")
    check(photoSrc.contains("rec.weatherId") && photoSrc.contains("SceneLight.bandOf"),
        "horizon: the photo derives from its record's own weather and hour")
}
}

private fun sectionV040b(root: String) {
// ================= v0.4.0b: errands =================
// Queue #4 item 2. Small work for townsfolk, from three
// sources (the City Hall board, goal-driven direct asks,
// shopkeeper trade asks), in six types, each judged by a
// verb the game already had — Give, Talk, Look, the
// lamp/bench taps, the selfie, the minigame settles. The
// board is a pure function of the day; accepted errands are
// the only state, and they are capped like everything else.
println("== v0.4.0b: errands — small work for townsfolk ==")
run {
    val eng = Engine(404)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Helper", DEFAULT_APPEARANCE)
        return s
    }
    fun plateErrand(s: GameState, e: Errand): Errand {
        check(Errands.accept(s, e), "errands: accept ${e.type} (${e.id})")
        return Errands.active(s).first { it.id == e.id }
    }
    fun validErrand(e: Errand, tag: String) {
        check(e.asker in KID_ORDER, "$tag: asker ${e.asker} is cast")
        check(e.text.isNotBlank(), "$tag: the ask has words")
        when (e.type) {
            "FETCH" -> check(e.itemId in Errands.FETCH_POOL,
                "$tag: fetch target ${e.itemId} is in the obtainable pool")
            "DELIVER" -> check(e.targetName in KID_ORDER && e.targetName != e.asker,
                "$tag: deliver target ${e.targetName} is somebody else, in town")
            "FIND" -> check(e.itemId in Errands.FIND_POOL &&
                e.targetLoc in LOCATIONS,
                "$tag: the lost ${e.itemId} is lost somewhere real (${e.targetLoc})")
            "FIX" -> check(e.fixKind in setOf("lamp", "bench") &&
                (e.fixKind != "bench" || e.targetLoc in LOCATIONS),
                "$tag: the fix spot exists")
            "PHOTO" -> check((e.targetName in KID_ORDER) != (e.targetLoc in LOCATIONS),
                "$tag: a photo errand names a person XOR a place")
            "PLAY" -> check(e.playKind == "showdown" ||
                (e.playKind?.startsWith("fish:") == true &&
                    fishById(e.playKind.removePrefix("fish:")) != null) ||
                (e.playKind?.startsWith("taco:") == true &&
                    (e.playKind.removePrefix("taco:").toIntOrNull() ?: 0) > 0),
                "$tag: the play target ${e.playKind} parses")
            else -> check(false, "$tag: unknown type ${e.type}")
        }
    }

    // ---------- the dials ----------
    check(Errands.MAX_ACTIVE == 6, "errands: the plate holds 6")
    check(Errands.BOARD_MIN == 2, "errands: the board posts at least 2")
    check(Errands.ASK_CHANCE in 0.05..0.95 && Errands.SHOP_ASK_CHANCE in 0.05..0.95 &&
        Errands.SHOP_ASK_CHANCE > Errands.ASK_CHANCE,
        "errands: ask odds are named constants, shopkeepers bolder " +
            "(${Errands.ASK_CHANCE} / ${Errands.SHOP_ASK_CHANCE})")
    check(Errands.TYPES.toSet() == Errands.FRIENDSHIP.keys &&
        Errands.TYPES.toSet() == Errands.COINS.keys,
        "errands: every type has a friendship row and a coin row")
    check(Errands.FRIENDSHIP.values.all { it in 1..10 } &&
        Errands.COINS.getValue("PLAY") == 0 &&
        Errands.TYPES.count { (Errands.COINS[it] ?: 0) > 0 } == 5,
        "errands: coins for most types — PLAY pays through the game itself")
    check(Errands.ERRAND_FEATS.map { it.at } == listOf(10, 50, 150),
        "errands: the feat chain is 10 / 50 / 150")
    check(Errands.titleFor(0) == null && Errands.titleFor(9) == null &&
        Errands.titleFor(10) == "Neighborly" &&
        Errands.titleFor(149) == "Town Fixture" &&
        Errands.titleFor(150) == "Indispensable" &&
        Errands.titleFor(900) == "Indispensable",
        "errands: the helpful titles land on their counts")

    // ---------- the obtainable universe (a proof, not a hope) ----------
    for (item in ITEMS) {
        check(Errands.sourceOf(item.id) != null,
            "obtainable: ${item.id} enters the world (${Errands.sourceOf(item.id)})")
    }
    check(FISH_TABLE.all { Errands.sourceOf(it.itemId) == "pond" },
        "obtainable: everything on the catch table comes from the pond")
    check(Errands.sourceOf("lemonade") == "stand" &&
        Errands.sourceOf("capsule_coin") == "games" &&
        Errands.sourceOf("definitely_not_an_item") == null,
        "obtainable: the stand, the games, and nothing for non-items")
    check(COLLECTIBLES.all { Errands.sourceOf(it.id) == "spawn" },
        "obtainable: collectibles arrive on the daily spawns")
    check(Errands.FETCH_POOL.isNotEmpty() &&
        Errands.FETCH_POOL.all { Errands.sourceOf(it) in
            setOf("container", "spawn", "pond", "stand") },
        "obtainable: every fetch target is producible in any season")
    check(Minigames.COIN_ITEM !in Errands.FETCH_POOL &&
        "lost_mitten" !in Errands.FETCH_POOL,
        "obtainable: no fetching the reward currency or winter-only litter")
    check(Errands.FIND_POOL.all { itemById(it) != null } &&
        Errands.FIND_LOCS.all { it in LOCATIONS } &&
        Errands.PHOTO_LOCS.all { it in LOCATIONS } &&
        Errands.PLAY_FISH.all { fishById(it) != null },
        "obtainable: find/photo/play pools name only real things")

    // ---------- the board: same day, same postings ----------
    val sb1 = freshState(); val sb2 = freshState()
    val board1 = Errands.boardFor(sb1)
    check(board1 == Errands.boardFor(sb2),
        "board: a pure function of the day — two towns agree")
    check(board1.size in 2..3, "board: 2–3 postings (got ${board1.size})")
    check(board1.map { it.asker }.distinct().size == board1.size,
        "board: no asker posts twice in a day")
    check(board1.all { it.source == Errands.BOARD && it.acceptedDay == -1 },
        "board: postings are listings, not yet errands")
    for (e in board1) validErrand(e, "board")
    val engDays = Engine(405)
    val sdBoard = engDays.newState()
    engDays.createPlayer(sdBoard, "Days", DEFAULT_APPEARANCE)
    var boardDays = 0
    repeat(30) {
        engDays.onNewDay(sdBoard)
        val b = Errands.boardFor(sdBoard)
        check(b.size in 2..3, "board: day ${it + 2} posts ${b.size}")
        for (e in b) validErrand(e, "board day ${it + 2}")
        boardDays++
    }
    check(boardDays == 30, "board: a month of boards generated clean")
    // taking (or running) a posting clears it from the open board
    val sTake = freshState()
    val posting = Errands.boardOpen(sTake).first()
    check(Errands.accept(sTake, posting), "board: a posting can be taken")
    check(Errands.boardOpen(sTake).none { it.id == posting.id },
        "board: a taken posting leaves the cork")
    val sRun = freshState()
    val runPosting = Errands.boardOpen(sRun).first()
    Errands.accept(sRun, runPosting)
    val ranComp = when (runPosting.type) {
        "FETCH" -> {
            sRun.inventory[runPosting.itemId!!] =
                (sRun.inventory[runPosting.itemId] ?: 0) + 1
            Errands.handInFetch(sRun, runPosting.asker, runPosting.itemId!!)
        }
        "DELIVER" -> Errands.deliverTo(sRun, runPosting.targetName!!)
        "FIND" -> Errands.recoverFind(sRun, runPosting.targetLoc!!)
        "FIX" -> Errands.onFixTap(sRun, runPosting.fixKind!!,
            runPosting.targetLoc ?: Errands.flickerLoc(sRun.absDay))
        "PHOTO" -> Errands.onPhoto(sRun, PhotoRecord(
            id = "bt", dayKey = sRun.todayKey, dateLabel = "?", timeMin = 720,
            locId = runPosting.targetLoc ?: "MainStreet", inside = false,
            weatherId = sRun.weatherId, appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Helper", "player", "happy"),
                PhotoFigure(runPosting.targetName ?: "Stan", "cast", "happy")),
            seed = 1L, absDay = sRun.absDay)).firstOrNull()
        else -> when {
            runPosting.playKind?.startsWith("fish:") == true ->
                Errands.onPlayCatch(sRun,
                    runPosting.playKind.removePrefix("fish:")).firstOrNull()
            runPosting.playKind == "showdown" ->
                Errands.onPlayShowdown(sRun, true).firstOrNull()
            else -> Errands.onPlayTaco(sRun, 999).firstOrNull()
        }
    }
    check(ranComp != null, "board: a posting of type ${runPosting.type} runs")
    check(Errands.boardOpen(sRun).none { it.id == runPosting.id },
        "board: a posting run today stays off the cork")

    // ---------- direct asks: goal-gated, once a day ----------
    val engAsk = Engine(406)
    val sAsk = engAsk.newState()
    engAsk.createPlayer(sAsk, "Asked", DEFAULT_APPEARANCE)
    var offers = 0
    repeat(14) { d ->
        if (d > 0) engAsk.onNewDay(sAsk)
        for (npc in KID_ORDER) {
            val a1 = Errands.askFor(sAsk, npc)
            check(a1 == Errands.askFor(sAsk, npc),
                "ask: deterministic for $npc on day ${d + 1}")
            if (a1 != null) {
                offers++
                check(a1.source == Errands.ASK && a1.asker == npc,
                    "ask: the offer is $npc's own")
                validErrand(a1, "ask $npc")
            }
        }
    }
    check(offers >= 20,
        "ask: a fortnight of town offers real favors (got $offers)")
    check(Errands.askFor(sAsk, "Not A Person") == null,
        "ask: strangers from the lorebook pool don't ask — cast only")
    // offered once: marking ends it for the day; rollover lapses it
    val engMark = Engine(407)
    val sMark = engMark.newState()
    engMark.createPlayer(sMark, "Marked", DEFAULT_APPEARANCE)
    var offerNpc: String? = null
    var guardDays = 0
    while (offerNpc == null && guardDays < 10) {
        offerNpc = KID_ORDER.firstOrNull { Errands.askFor(sMark, it) != null }
        if (offerNpc == null) { engMark.onNewDay(sMark); guardDays++ }
    }
    check(offerNpc != null, "ask: somebody offers within ten days")
    if (offerNpc != null) {
        check(Errands.askFor(sMark, offerNpc) != null,
            "ask: the offer stands until it is marked")
        Errands.markAsked(sMark, offerNpc)
        check(Errands.askFor(sMark, offerNpc) == null,
            "ask: once offered, never twice in a day")
        engMark.onNewDay(sMark)
        check(sMark.errandAsked[offerNpc] == null,
            "ask: yesterday's offers lapse at rollover")
    }
    // an asker with an errand already out doesn't stack another
    val sStack = freshState()
    plateErrand(sStack, Errand("stk", Errands.ASK, "Stan", "FETCH",
        "t", "h", itemId = "snack_cake", dayKey = sStack.todayKey))
    check(Errands.askFor(sStack, "Stan") == null &&
        Errands.shopAskFor(sStack, "Stan", "TweekBros") == null,
        "ask: one open errand per asker, from any source")

    // ---------- shop asks: the counter, the keeper ----------
    check(Errands.SHOP_ASKERS == mapOf("TweekBros" to "Tweek",
        "JimbosGuns" to "Jimbo", "FreemansTacos" to "Chef",
        "Bank" to "Gerald"),
        "shop: the four counters and their keeps")
    val sShop0 = freshState()
    check(Errands.shopAskFor(sShop0, "Tweek", "MainStreet") == null,
        "shop: no trade ask away from the shop")
    check(Errands.shopAskFor(sShop0, "Stan", "TweekBros") == null,
        "shop: only the keeper asks at their counter")
    val engShop = Engine(408)
    val sShop = engShop.newState()
    engShop.createPlayer(sShop, "Shopper", DEFAULT_APPEARANCE)
    var shopOffers = 0
    repeat(21) { d ->
        if (d > 0) engShop.onNewDay(sShop)
        for ((loc, keeper) in Errands.SHOP_ASKERS) {
            val a = Errands.shopAskFor(sShop, keeper, loc)
            if (a != null) {
                shopOffers++
                check(a.source == Errands.SHOP && a.asker == keeper,
                    "shop: the $loc ask is $keeper's")
                validErrand(a, "shop $keeper")
            }
        }
    }
    check(shopOffers >= 4,
        "shop: three weeks of counters produce trade asks (got $shopOffers)")

    // ---------- the plate: cap, duplicates, abandon ----------
    val sCap = freshState()
    fun mkErrand(i: Int) = Errand("cap$i", Errands.BOARD, "Stan", "FETCH",
        "t", "h", itemId = "snack_cake", dayKey = sCap.todayKey)
    repeat(Errands.MAX_ACTIVE) { i ->
        check(Errands.accept(sCap, mkErrand(i)), "plate: accept ${i + 1}")
    }
    check(!Errands.accept(sCap, mkErrand(99)),
        "plate: the ${Errands.MAX_ACTIVE + 1}th errand is refused")
    check(!Errands.accept(sCap, mkErrand(0)),
        "plate: the same posting can't be taken twice")
    val sigh = Errands.abandon(sCap, "cap3")
    check(sigh != null && sigh.isNotBlank(),
        "plate: abandoning returns the asker's disappointment")
    check(Errands.activeCount(sCap) == Errands.MAX_ACTIVE - 1 &&
        Errands.accept(sCap, mkErrand(7)),
        "plate: a dropped errand frees its slot")
    check(Errands.abandon(sCap, "no-such-errand") == null,
        "plate: abandoning a phantom is a no-op")
    check(sCap.errandsDoneCount == 0,
        "plate: none of this counted as running an errand")
}
}

private fun sectionV040bJudges(root: String) {
// ================= v0.4.0b (2/2): the judges =================
// Every type settles through the REAL verb path the game
// uses — the Give handler's judge, the Talk gate's judge,
// Look's judge, the fixture taps, Photos.applyPhoto, and the
// three Minigames settle functions with fabricated sessions.
println("== v0.4.0b (2/2): errand judges through the real verbs ==")
run {
    val eng = Engine(409)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Runner", DEFAULT_APPEARANCE)
        return s
    }
    fun plateErrand(s: GameState, e: Errand): Errand {
        check(Errands.accept(s, e), "judges: accept ${e.type} (${e.id})")
        return Errands.active(s).first { it.id == e.id }
    }

    // ---------- FETCH, judged by the Give rail ----------
    val sf = freshState()
    plateErrand(sf, Errand("f1", Errands.ASK, "Carol", "FETCH", "t", "h",
        itemId = "snack_cake", dayKey = sf.todayKey))
    check(Errands.handInFetch(sf, "Carol", "snack_cake") == null,
        "fetch: an empty pack hands in nothing")
    sf.inventory["snack_cake"] = 2
    val carolBefore = sf.friendship["Carol"] ?: 0
    val coinsBefore = Minigames.capsuleCoins(sf)
    val fComp = Errands.handInFetch(sf, "Carol", "snack_cake")
    check(fComp != null && fComp.errand.id == "f1",
        "fetch: the hand-in settles the errand")
    check((sf.inventory["snack_cake"] ?: 0) == 1,
        "fetch: exactly one pack copy is consumed")
    check((sf.friendship["Carol"] ?: 0) ==
        carolBefore + Errands.FRIENDSHIP.getValue("FETCH"),
        "fetch: the friendship lands on the engine's scale")
    check(Minigames.capsuleCoins(sf) ==
        coinsBefore + Errands.COINS.getValue("FETCH"),
        "fetch: the capsule coins land in the pack")
    check(sf.errandsDoneCount == 1 && Errands.activeCount(sf) == 0 &&
        sf.errandsRecent.lastOrNull()?.id == "f1",
        "fetch: the count, the plate and the history all move")
    check(sf.lifeText["errandThanks:Carol"] != null,
        "fetch: the thank-you waits for Carol's next conversation")
    check(sf.life["errandBeatDay"] == sf.absDay &&
        sf.lifeText["errandBeat"] != null,
        "fetch: the morning beat is recorded against today")
    check(Errands.handInFetch(sf, "Carol", "snack_cake") == null,
        "fetch: an errand settles exactly once")
    // the wrong person / wrong item never settles it
    val sf2 = freshState()
    plateErrand(sf2, Errand("f2", Errands.ASK, "Carol", "FETCH", "t", "h",
        itemId = "snack_cake", dayKey = sf2.todayKey))
    sf2.inventory["snack_cake"] = 1; sf2.inventory["flower"] = 1
    check(Errands.handInFetch(sf2, "Stan", "snack_cake") == null &&
        Errands.handInFetch(sf2, "Carol", "flower") == null &&
        Errands.activeCount(sf2) == 1,
        "fetch: wrong person or wrong item settles nothing")

    // ---------- DELIVER, judged by the Talk gate ----------
    val sDel = freshState()
    plateErrand(sDel, Errand("d1", Errands.ASK, "Stan", "DELIVER", "t", "h",
        targetName = "Kyle", dayKey = sDel.todayKey))
    check(Errands.deliverTo(sDel, "Kenny") == null &&
        Errands.activeCount(sDel) == 1,
        "deliver: talking to anybody else settles nothing")
    check(Errands.deliverTo(sDel, "Kyle") != null &&
        sDel.errandsDoneCount == 1,
        "deliver: the recipient's conversation settles it")

    // ---------- FIND, judged by Look ----------
    val sFind = freshState()
    plateErrand(sFind, Errand("fd1", Errands.BOARD, "Butters", "FIND",
        "t", "h", itemId = "velcro_wallet", targetLoc = "KidsPark",
        dayKey = sFind.todayKey))
    check(Errands.recoverFind(sFind, "Mall") == null,
        "find: looking anywhere else finds nothing")
    check(Errands.recoverFind(sFind, "KidsPark") != null &&
        sFind.errandsDoneCount == 1,
        "find: a careful look at the right place recovers it")

    // ---------- FIX, judged by the fixture taps ----------
    val sFix = freshState()
    plateErrand(sFix, Errand("x1", Errands.BOARD, "Ned", "FIX", "t", "h",
        fixKind = "lamp", dayKey = sFix.todayKey))
    plateErrand(sFix, Errand("x2", Errands.BOARD, "Red", "FIX", "t", "h",
        fixKind = "bench", targetLoc = "KidsPark", dayKey = sFix.todayKey))
    check(Errands.onFixTap(sFix, "bench", "BusStop") == null,
        "fix: the wrong bench stays wobbly")
    check(Errands.onFixTap(sFix, "lamp", "Anywhere")?.errand?.id == "x1",
        "fix: the lamp errand settles wherever the flicker is tonight")
    check(Errands.onFixTap(sFix, "bench", "KidsPark")?.errand?.id == "x2",
        "fix: the right bench settles its errand")
    check((0..80).all { Errands.flickerLoc(it) in LOCATIONS },
        "fix: the flicker formula only ever names real streets")

    // ---------- PHOTO, judged by Photos.applyPhoto ----------
    val sPh = freshState()
    plateErrand(sPh, Errand("p1", Errands.ASK, "Wendy", "PHOTO", "t", "h",
        targetName = "Bebe", dayKey = sPh.todayKey))
    plateErrand(sPh, Errand("p2", Errands.ASK, "Randy", "PHOTO", "t", "h",
        targetLoc = "StarksPond", dayKey = sPh.todayKey))
    fun photoRec(id: String, loc: String, vararg cast: String) = PhotoRecord(
        id = id, dayKey = sPh.todayKey, dateLabel = "?", timeMin = 720,
        locId = loc, inside = false, weatherId = sPh.weatherId,
        appearance = DEFAULT_APPEARANCE,
        figures = listOf(PhotoFigure("Runner", "player", "happy")) +
            cast.map { PhotoFigure(it, "cast", "happy") },
        seed = 7L, absDay = sPh.absDay)
    Photos.applyPhoto(sPh, photoRec("t1", "Mall", "Stan"))
    check(sPh.errandsDoneCount == 0,
        "photo: the wrong face in the wrong place settles nothing")
    Photos.applyPhoto(sPh, photoRec("t2", "StarksPond", "Bebe"))
    check(sPh.errandsDoneCount == 2,
        "photo: one shutter settles the person AND the place errand " +
            "(got ${sPh.errandsDoneCount})")

    // ---------- PLAY, judged by the Minigames settles ----------
    val sPl = freshState()
    plateErrand(sPl, Errand("g1", Errands.ASK, "Jimbo", "PLAY", "t", "h",
        playKind = "fish:speckled_trout", dayKey = sPl.todayKey))
    plateErrand(sPl, Errand("g2", Errands.ASK, "Cartman", "PLAY", "t", "h",
        playKind = "showdown", dayKey = sPl.todayKey))
    plateErrand(sPl, Errand("g3", Errands.SHOP, "Chef", "PLAY", "t", "h",
        playKind = "taco:180", dayKey = sPl.todayKey))
    fun catchOf(speciesId: String): FishingSession {
        // species rolls from the seed at the tap (the session's
        // fields are private-set by design) — scan seeds until
        // the pond gives up the named fish, like the suite does
        var seed = 100L
        while (seed < 100_000L) {
            val sess = FishingSession(seed, "sunny", 6)
            sess.tap(sess.biteAtMs)
            if (sess.outcome == FishingSession.Outcome.CAUGHT &&
                sess.species?.id == speciesId) return sess
            seed++
        }
        error("no seed in range catches $speciesId")
    }
    applyCatch(sPl, catchOf("old_boot"))
    check(sPl.errandsDoneCount == 0, "play: a boot is not a trout")
    applyCatch(sPl, catchOf("speckled_trout"))
    check(sPl.errandsDoneCount == 1 &&
        Errands.active(sPl).none { it.id == "g1" },
        "play: the named catch settles through applyCatch")
    // duels are scripted through the real throw/dodge verbs
    // (the result fields have private setters by design)
    val loss = ShowdownDuel(12L, "Kyle")
    var lossGuard = 0
    while (!loss.over && lossGuard++ < 300) {
        loss.resolveThrow(0.0f) // harmless zone
        if (!loss.over) loss.resolveDodge(null) // stand there, take it
    }
    check(loss.over && !loss.youWon, "play: the scripted loss really lost")
    applyShowdownResult(sPl, loss)
    check(sPl.errandsDoneCount == 1, "play: losing the bet settles nothing")
    val win = ShowdownDuel(13L, "Kyle")
    var winGuard = 0
    while (!win.over && winGuard++ < 500) {
        win.resolveThrow(0.5f) // dead center of the bar
        if (!win.over) {
            val st = Showdown.dodgeWindowStart(win.round, "Kyle")
            win.resolveDodge((st + Showdown.FLIGHT_MS) / 2)
        }
    }
    check(win.over && win.youWon, "play: the scripted win really won")
    applyShowdownResult(sPl, win)
    check(sPl.errandsDoneCount == 2, "play: the win settles the bet")
    val lowTaco = TacoCatchSession(14L)
    repeat(10) { lowTaco.onCatch("taco", 1000L) } // 100 points
    applyTacoResult(sPl, lowTaco)
    check(sPl.errandsDoneCount == 2, "play: 100 < 180 settles nothing")
    val bigTaco = TacoCatchSession(15L)
    repeat(18) { bigTaco.onCatch("taco", 1000L) } // 180 points
    applyTacoResult(sPl, bigTaco)
    check(sPl.errandsDoneCount == 3, "play: hitting the target settles the dare")
    check(Errands.COINS.getValue("PLAY") == 0,
        "play: errands pay no coins on top of the game's own purse")

    // ---------- rewards: the thank-you item rule ----------
    // idHash % 4 == 0 grants one gift-tier item; anything else
    // doesn't. String.hashCode is specified, so the rule is
    // pinned by construction, not by luck.
    fun idWithRemainder(r: Int): String {
        var i = 0
        while (true) {
            val cand = "hash$i"
            val h = cand.hashCode() and 0x7fffffff
            // v0.5.0c: the item probe must also dodge the Pocket
            // Pals card branch of the thank-you gate (1 in
            // ERRAND_CARD_EVERY thank-yous is a card instead) —
            // this helper pins the ITEM side of the rule.
            if (h % 4 == r && h % 3 != 1 &&
                (r != 0 || (h / 4) % PocketPals.ERRAND_CARD_EVERY != 0)) return cand
            i++
        }
    }
    val sGift = freshState()
    val giftId = idWithRemainder(0)
    plateErrand(sGift, Errand(giftId, Errands.ASK, "Sharon", "DELIVER",
        "t", "h", targetName = "Stan", dayKey = sGift.todayKey))
    val packBefore = sGift.inventory.values.sum()
    val gComp = Errands.deliverTo(sGift, "Stan")
    check(gComp?.reward?.thankItem != null &&
        (gComp.reward.thankItem?.tier == "gift") &&
        sGift.inventory.values.sum() == packBefore +
            Errands.COINS.getValue("DELIVER") + 1,
        "rewards: a hash-lucky errand pays a gift-tier thank-you item " +
            "(pack delta = the errand's coins + the one gift)")
    val sPlain = freshState()
    val plainId = idWithRemainder(2)
    plateErrand(sPlain, Errand(plainId, Errands.ASK, "Sharon", "DELIVER",
        "t", "h", targetName = "Stan", dayKey = sPlain.todayKey))
    val pComp = Errands.deliverTo(sPlain, "Stan")
    check(pComp?.reward?.thankItem == null,
        "rewards: most errands pay friendship and coins, not things")

    // ---------- feats cross on the count ----------
    val sFeat = freshState()
    sFeat.errandsDoneCount = 9
    plateErrand(sFeat, Errand("z1", Errands.ASK, "Stan", "FIX", "t", "h",
        fixKind = "bench", targetLoc = "KidsPark", dayKey = sFeat.todayKey))
    val zComp = Errands.onFixTap(sFeat, "bench", "KidsPark")
    check(zComp?.reward?.newFeats == listOf("errand_10"),
        "feats: the tenth errand crosses Neighborly (got ${zComp?.reward?.newFeats})")
    check(Errands.titleFor(sFeat.errandsDoneCount) == "Neighborly" &&
        sFeat.townLog.any { it.contains("Neighborly") },
        "feats: the title lands and the town log keeps it")

    // ---------- expiry: board yes, accepted no ----------
    val engExp = Engine(410)
    val sExp = engExp.newState()
    engExp.createPlayer(sExp, "Patient", DEFAULT_APPEARANCE)
    val dayOneBoard = Errands.boardFor(sExp).map { it.id }
    val kept = Errands.boardOpen(sExp).first()
    Errands.accept(sExp, kept)
    val doneOne = Errands.boardOpen(sExp).firstOrNull()
    if (doneOne != null) {
        Errands.accept(sExp, doneOne)
        when (doneOne.type) {
            "DELIVER" -> Errands.deliverTo(sExp, doneOne.targetName!!)
            "FIND" -> Errands.recoverFind(sExp, doneOne.targetLoc!!)
            "FIX" -> Errands.onFixTap(sExp, doneOne.fixKind!!,
                doneOne.targetLoc ?: Errands.flickerLoc(sExp.absDay))
            else -> { /* other types persist done until rollover too */ }
        }
    }
    engExp.onNewDay(sExp)
    check(Errands.boardFor(sExp).map { it.id }.none { it in dayOneBoard },
        "expiry: yesterday's unaccepted postings are gone with the day")
    check(Errands.active(sExp).any { it.id == kept.id },
        "expiry: an accepted errand survives the night")
    check(sExp.errands.none { it.done },
        "expiry: finished errands leave the plate at rollover")
    check(sExp.errandsDoneCount >= (if (doneOne != null &&
        doneOne.type in setOf("DELIVER", "FIND", "FIX")) 1 else 0),
        "expiry: the lifetime count keeps what the plate dropped")

    // ---------- saves: round-trip, old saves, caps ----------
    val sSave = freshState()
    plateErrand(sSave, Errand("r1", Errands.BOARD, "Kyle", "FIND", "t", "h",
        itemId = "comic_book", targetLoc = "Mall", dayKey = sSave.todayKey))
    sSave.errandsDoneCount = 27
    sSave.errandsRecent.add(ErrandDoneNote("old1", "20261001", "✔ something"))
    sSave.errandAsked["Stan"] = sSave.absDay
    val doc = encodeGameState(sSave)
    check(doc.containsKey("errands") && doc.containsKey("errandsRecent") &&
        doc.containsKey("errandAsked") && doc.containsKey("errandsDone"),
        "saves: the errand keys ride the doc additively")
    val back = decodeGameState(doc)
    check(back.errands.size == 1 && back.errands[0].id == "r1" &&
        back.errands[0].itemId == "comic_book" &&
        back.errands[0].targetLoc == "Mall" &&
        back.errandsDoneCount == 27 && back.errandsRecent.size == 1 &&
        back.errandAsked["Stan"] == sSave.absDay,
        "saves: plate, count, history and asked-marks all round-trip")
    val oldBack = decodeGameState(mapOf("timeMin" to 480))
    check(oldBack.errands.isEmpty() && oldBack.errandsDoneCount == 0 &&
        oldBack.errandsRecent.isEmpty(),
        "saves: a pre-errands save loads with an empty plate")
    val fat = decodeGameState(mapOf(
        "errands" to (1..40).map {
            mapOf("id" to "x$it", "asker" to "Stan", "type" to "FETCH",
                "text" to "t")
        },
        "errandsRecent" to (1..20).map {
            mapOf("id" to "y$it", "day" to "20261001", "line" to "l$it")
        }))
    check(fat.errands.size <= Errands.STATE_CAP &&
        fat.errandsRecent.size <= Errands.STATE_RECENT_CAP,
        "saves: an inflated doc decodes inside the caps " +
            "(${fat.errands.size}/${fat.errandsRecent.size})")
    val mixed = decodeGameState(mapOf("errands" to listOf(
        mapOf("id" to "ok1", "asker" to "Stan", "type" to "FETCH", "text" to "t"),
        mapOf("asker" to "Stan", "type" to "FETCH", "text" to "t"),
        mapOf("id" to "bad", "asker" to "Stan", "type" to "DANCE", "text" to "t"))))
    check(mixed.errands.map { it.id } == listOf("ok1"),
        "saves: bad errand entries drop one by one, never the list")

    // ---------- the morning beat & the journal page ----------
    val engBeat = Engine(411)
    val sBeat = engBeat.newState()
    engBeat.createPlayer(sBeat, "Beater", DEFAULT_APPEARANCE)
    plateErrand(sBeat, Errand("m1", Errands.ASK, "Sharon", "DELIVER",
        "t", "h", targetName = "Stan", dayKey = sBeat.todayKey))
    Errands.deliverTo(sBeat, "Stan")
    engBeat.onNewDay(sBeat)
    val report = House.morningReport(sBeat, emptyList(), emptyMap(),
        0, false, null)
    check(report.any { it.startsWith("📋") },
        "beat: yesterday's errand makes the morning report (got $report)")

    val sJ = freshState()
    val lines0 = Errands.pageLines(sJ)
    check(lines0.first().contains("0 run for this town") &&
        lines0.any { it.contains("ON THE BOARD") },
        "journal: an empty day still reads as a page")
    plateErrand(sJ, Errand("j1", Errands.ASK, "Wendy", "DELIVER", "t", "h",
        targetName = "Stan", dayKey = sJ.todayKey))
    val lines1 = Errands.pageLines(sJ)
    check(lines1.any { it.contains("ON YOUR PLATE (1/${Errands.MAX_ACTIVE})") } &&
        lines1.any { it.contains("Deliver") && it.contains("Stan") },
        "journal: the plate lists objectives with their people")

    // ---------- the wiring is real, not aspirational ----------
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    val phSrc = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
    val mgSrc = File(root, "src/com/hunt3r/southparktown/Minigames.kt").readText()
    val pfSrc = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val enSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val joSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val coSrc = File(root, "src/com/hunt3r/southparktown/CollectionActivity.kt").readText()
    check(gaSrc.contains("\"errandboard\"") && gvSrc.contains("drawErrandBoard"),
        "wiring: City Hall draws the board and the tap routes to its dialog")
    check(gaSrc.contains("Errands.handInFetch") &&
        gaSrc.contains("TalkGate.gateFor") &&
        gaSrc.contains("Errands.recoverFind") &&
        gaSrc.contains("Errands.onFixTap"),
        "wiring: Give, Talk, Look and the fixture taps all judge errands")
    val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(tgSrc.contains("Errands.pendingAsk") &&
        tgSrc.contains("HolidayBeats.talkStepFor"),
        "wiring: the Talk gate's pure decision reads the ask and the beat step")
    check(phSrc.contains("Errands.onPhoto") &&
        mgSrc.contains("Errands.onPlayCatch") &&
        mgSrc.contains("Errands.onPlayShowdown") &&
        mgSrc.contains("Errands.onPlayTaco"),
        "wiring: the shutter and all three game settles judge errands")
    check(pfSrc.contains("\"errands\" to state.errands") &&
        enSrc.contains("Errands.dailyRollover"),
        "wiring: saves carry the plate and rollover turns it")
    check(joSrc.contains("Errands.pageLines") &&
        coSrc.contains("ERRAND_FEATS"),
        "wiring: the Journal page and the Collection feats render the system")
}
}

private fun sectionV040c(root: String) {
// ================= v0.4.0c: group photos =================
// Queue #4 item 3. The selfie grows up: with 2+ townsfolk
// present the camera offers a posed GROUP frame alongside
// the classic pile-in. Group records carry a composition
// and a figure list in FRAME ORDER, arranged from the
// town's own pair ledgers — chemistry adjacent, rivals
// gapped, the strongest rivalry back-to-back. Payouts run
// at the group rate plus a debut-pair chemistry bonus, and
// every existing judge (errands, goals, participation,
// feats) reads group records exactly as it reads selfies.
println("== v0.4.0c: group photos — posed frames, chemistry, crashers ==")
run {
    val eng = Engine()
    fun freshState(): GameState {
        val s = eng.newState()
        s.todayKey = "20261013"
        return s
    }

    // ---------- the dials + the feat registry ----------
    check(Photos.GROUP_MAX_NPCS == 3,
        "group: a posed frame holds 3 (the core four excepted)")
    check(Photos.GROUP_RATE == 0.6f, "group: the group rate is 0.6")
    check(Photos.CHEMISTRY_PAIR_BONUS == 10 && Photos.CHEMISTRY_PAIRS_CAPPED == 2,
        "group: +10 per debut recognized pair, at most 2 pairs paid")
    check(Photos.GROUP_SHOTS_FEAT == 25, "group: SAY CHEESE wants 25 group shots")
    check(Photos.COMP_LINEUP == "lineup" && Photos.COMP_SQUAD == "squad" &&
        Photos.COMP_STACKED == "stacked",
        "group: the three compositions are lineup / squad / stacked")
    for (id in listOf("first_crowd", "gangs_all_here", "full_house_group",
            "say_cheese"))
        check(Photos.featById(id) != null, "group: feat $id is registered")

    // ---------- chemistry: one read of the pair ledgers ----------
    val sC = freshState()
    check(Photos.isRecognizedPair("Craig", "Tweek") &&
        Photos.isRecognizedPair("Stan", "Wendy") &&
        Photos.isRecognizedPair("Jimbo", "Ned"),
        "group: the registry knows its couples (PAIR_SCRIPTS is the source)")
    check(!Photos.isRecognizedPair("Kyle", "Wendy"),
        "group: not every duo is a recognized pair")
    check(Photos.recognizedPairsIn(listOf("Craig", "Tweek", "Chef")) ==
        listOf("Craig" to "Tweek"),
        "group: recognizedPairsIn finds the pair in the crowd, in stable order")
    check(Photos.bondBetween(sC, "Craig", "Tweek") == 0,
        "group: an unmoved bond reads 0")
    sC.npcBonds[Threads.pairKey("Craig", "Tweek")] = 3
    check(Photos.bondBetween(sC, "Tweek", "Craig") == 3,
        "group: bonds read through the sorted pair key, either order")
    check(Photos.chemistryBetween(sC, "Craig", "Tweek") ==
        3 + Photos.RECOGNIZED_CHEMISTRY,
        "group: chemistry = bond + recognition")
    check(Photos.isRivalPair(sC, "Cartman", "Kyle"),
        "group: canon arch-rivals are rivals with no bond at all")
    check(!Photos.isRivalPair(sC, "Stan", "Kyle"),
        "group: best friends are not rivals")
    sC.npcBonds[Threads.pairKey("Stan", "Cartman")] = -5
    check(Photos.isRivalPair(sC, "Stan", "Cartman"),
        "group: a bond at the storm line (<= -3) makes rivals")
    sC.npcBonds[Threads.pairKey("Stan", "Cartman")] = -2
    check(!Photos.isRivalPair(sC, "Stan", "Cartman"),
        "group: a grudge short of the line is just a grudge")

    // ---------- selection: affection picks the frame ----------
    val sSel = freshState()
    sSel.friendship["Stan"] = 100; sSel.friendship["Kyle"] = 90
    sSel.friendship["Wendy"] = 80; sSel.friendship["Bebe"] = 70
    sSel.friendship["Clyde"] = 60
    val recSel = Photos.composeGroup(sSel,
        listOf("Stan", "Kyle", "Wendy", "Bebe", "Clyde"), emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recSel.isGroup, "group: a group record knows what it is")
    check(recSel.npcs.map { it.name }.toSet() == setOf("Stan", "Kyle", "Wendy"),
        "group: the frame takes the top 3 by affection (got ${recSel.npcs.map { it.name }})")
    check(recSel.figures.count { it.kind == "player" } == 1,
        "group: exactly one of you in your own group photo")
    check(recSel.composition == Photos.COMP_SQUAD,
        "group: three kids, cool chemistry = squad (got ${recSel.composition})")
    check(recSel.caption.contains("gang") && recSel.caption.contains("Bus Stop"),
        "group: the caption names the gang and the place (${recSel.caption})")
    check(Photos.composeGroup(sSel,
        listOf("Stan", "Kyle", "Wendy", "Bebe", "Clyde"), emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE) == recSel,
        "group: composeGroup is deterministic for the same town moment")

    // a duo lines up
    val sTwo = freshState()
    sTwo.friendship["Stan"] = 100; sTwo.friendship["Kyle"] = 100
    val recTwo = Photos.composeGroup(sTwo, listOf("Stan", "Kyle"), emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recTwo.composition == Photos.COMP_LINEUP && recTwo.npcs.size == 2,
        "group: a duo lines up")

    // kids running hot on chemistry pile; adults never do
    val sHot = freshState()
    sHot.friendship["Craig"] = 100; sHot.friendship["Tweek"] = 100
    sHot.friendship["Clyde"] = 90
    sHot.npcBonds[Threads.pairKey("Craig", "Tweek")] = 6
    val recHot = Photos.composeGroup(sHot, listOf("Craig", "Tweek", "Clyde"),
        emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recHot.composition == Photos.COMP_STACKED,
        "group: kids + high chemistry = the pile (got ${recHot.composition})")
    val hotNames = recHot.figures.map { it.name }
    check(abs(hotNames.indexOf("Craig") - hotNames.indexOf("Tweek")) == 1,
        "group: the hot pair stands adjacent IN the record ($hotNames)")
    val sAd = freshState()
    sAd.friendship["Randy"] = 100; sAd.friendship["Sharon"] = 100
    sAd.friendship["Gerald"] = 90
    sAd.npcBonds[Threads.pairKey("Randy", "Sharon")] = 8
    val recAd = Photos.composeGroup(sAd, listOf("Randy", "Sharon", "Gerald"),
        emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recAd.composition == Photos.COMP_SQUAD,
        "group: chemistry can't make adults pile — squad, however warm")

    // ---------- frame order: adjacency, gaps, your slot ----------
    val sOrd = freshState()
    sOrd.npcBonds[Threads.pairKey("Craig", "Tweek")] = 6
    val (ordNames, ordSlot) = Photos.frameOrder(
        sOrd, listOf("Clyde", "Craig", "Tweek"), null)
    val framed = ordNames.toMutableList().also { it.add(ordSlot, "YOU") }
    check(abs(framed.indexOf("Craig") - framed.indexOf("Tweek")) == 1,
        "group: you never stand between a high-chemistry pair ($framed)")
    val sGap = freshState()
    val (gapOrder, _) = Photos.frameOrder(
        sGap, listOf("Kyle", "Cartman", "Stan"), null)
    check(abs(gapOrder.indexOf("Kyle") - gapOrder.indexOf("Cartman")) > 1,
        "group: with no bit to play, rivals simply keep a gap ($gapOrder)")

    // ---------- the back-to-back bit + the other pair's gap ----------
    val sBb = freshState()
    sBb.friendship["Stan"] = 100; sBb.friendship["Kyle"] = 100
    sBb.friendship["Cartman"] = 100
    sBb.npcBonds[Threads.pairKey("Stan", "Kyle")] = -5
    val recBb = Photos.composeGroup(sBb, listOf("Stan", "Kyle", "Cartman"),
        emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    val bbFigs = recBb.figures.filter { it.pose == "backToBack" }
    check(bbFigs.map { it.name }.toSet() == setOf("Stan", "Kyle"),
        "group: the strongest rivalry gets the back-to-back bit " +
            "(got ${bbFigs.map { it.name }})")
    check(bbFigs.all { it.mood == "hurt" },
        "group: back-to-back wears the arms-crossed face")
    val namesBb = recBb.figures.map { it.name }
    check(abs(namesBb.indexOf("Stan") - namesBb.indexOf("Kyle")) == 1,
        "group: the back-to-back pair stands together ($namesBb)")
    check(abs(namesBb.indexOf("Cartman") - namesBb.indexOf("Kyle")) > 1,
        "group: the OTHER rival pair keeps its gap ($namesBb)")
    check(recBb.caption.contains("NOT posing together"),
        "group: the caption tells on the back-to-back pair")

    // ---------- the core-four exception ----------
    val sCore = freshState()
    for (n in Photos.SQUAD) sCore.friendship[n] = 100
    sCore.friendship["Wendy"] = 100
    val recCore = Photos.composeGroup(sCore, Photos.SQUAD + "Wendy",
        emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recCore.npcs.map { it.name }.toSet() == Photos.SQUAD.toSet(),
        "group: the core-four exception takes exactly the four (Wendy waits)")
    check(recCore.composition == Photos.COMP_LINEUP,
        "group: the gang lines up")
    check(recCore.caption.startsWith("The whole gang at"),
        "group: the caption knows the whole gang (${recCore.caption})")
    check(Photos.featMet(sCore, recCore, "gangs_all_here"),
        "group: the gang feat reads the record")
    val resCore = Photos.applyPhoto(sCore, recCore)
    check("gangs_all_here" in resCore.newFeats &&
        "first_crowd" in resCore.newFeats,
        "group: the gang shot completes the gang + first-crowd feats")
    val sCore2 = freshState()
    for (n in Photos.SQUAD) sCore2.friendship[n] = 100
    val recSolo4 = Photos.compose(sCore2, Photos.SQUAD, emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(!recSolo4.isGroup &&
        !Photos.featMet(sCore2, recSolo4, "gangs_all_here") &&
        Photos.featMet(sCore2, recSolo4, "squad_shot"),
        "group: a pile-in selfie is not a group frame, however famous the crowd")

    // ---------- refusals stay refusals ----------
    val sRef = freshState()
    sRef.friendship["Stan"] = 100
    sRef.friendship["Cartman"] = -30
    var recRef: PhotoRecord? = null
    for (t in 480..1439 step 15) {
        sRef.timeMin = t
        val r = Photos.composeGroup(sRef, listOf("Stan", "Cartman"),
            emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        if (r.refused.isNotEmpty()) { recRef = r; break }
    }
    check(recRef != null, "group: a refusing rival shows up in seed space")
    if (recRef != null) {
        check(recRef.npcs.map { it.name } == listOf("Stan") &&
            recRef.caption.contains("said no. Rude."),
            "group: a refuser is out of the frame and into the caption")
    }

    // ---------- the crasher: uninvited, unseated, still famous ----------
    val sCr = freshState()
    sCr.friendship["Stan"] = 100; sCr.friendship["Kyle"] = 100
    sCr.friendship["Wendy"] = 100
    sCr.friendship["Randy"] = -30
    var recCr: PhotoRecord? = null
    for (t in 480..1439 step 15) {
        sCr.timeMin = t
        val r = Photos.composeGroup(sCr, listOf("Stan", "Kyle", "Wendy", "Randy"),
            emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
        if (r.npcs.any { it.reaction == Photos.PHOTOBOMB }) { recCr = r; break }
    }
    check(recCr != null, "group: a crashing rival shows up in seed space")
    if (recCr != null) {
        check(recCr.npcs.count { it.reaction != Photos.PHOTOBOMB } == 3,
            "group: the crasher is NOT one of the three seats")
        check(recCr.figures.size == 5 && recCr.figures.last().name == "Randy",
            "group: 3 posed + you + the crasher leaning in last = 5 figures")
        check(recCr.caption.contains("crashed it"),
            "group: the caption tells on the crasher")
        check(Photos.featMet(sCr, recCr, "full_house_group"),
            "group: 5 figures incl. a crasher is the group full house")
        // payout, audited figure by figure off the record itself
        val perFigure = recCr.npcs.sumOf {
            (Photos.uniqueGain(it) * Photos.GROUP_RATE).roundToInt()
        }
        val debutPairs = Photos.recognizedPairsIn(recCr.npcs.map { it.name }).size
        val expectBonus = Photos.CHEMISTRY_PAIR_BONUS *
            minOf(Photos.CHEMISTRY_PAIRS_CAPPED, debutPairs)
        val resCr = Photos.applyPhoto(sCr, recCr)
        check(resCr.gained == perFigure + expectBonus &&
            resCr.chemistryBonus == expectBonus,
            "group: a crashed frame pays group rate per figure + the debut " +
                "bonus (got ${resCr.gained}, expected ${perFigure + expectBonus})")
        check("full_house_group" in resCr.newFeats && "bombed" in resCr.newFeats,
            "group: the crashed frame completes full-house + bombed")
        check(sCr.photographed["Randy"] == 1,
            "group: the crasher counts as photographed, as bombs always have")
    }

    // ---------- payout: the duo, priced exactly ----------
    val sPay = freshState()
    sPay.friendship["Stan"] = 100; sPay.friendship["Kyle"] = 100
    val recPay = Photos.composeGroup(sPay, listOf("Stan", "Kyle"), emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    val resPay = Photos.applyPhoto(sPay, recPay)
    check(resPay.chemistryBonus == Photos.CHEMISTRY_PAIR_BONUS,
        "group: a debut recognized pair pays the chemistry bonus")
    check(resPay.gained ==
        2 * (24 * Photos.GROUP_RATE).roundToInt() + Photos.CHEMISTRY_PAIR_BONUS,
        "group: duo payout = 2 group-rated close friends + bonus " +
            "(got ${resPay.gained})")
    val resPay2 = Photos.applyPhoto(sPay, Photos.composeGroup(sPay,
        listOf("Stan", "Kyle"), emptyList(), PLAYER_DEFAULT_NAME,
        DEFAULT_APPEARANCE))
    check(resPay2.gained == 2 * Photos.REPHOTO_GAIN &&
        resPay2.chemistryBonus == 0,
        "group: a re-shot pair trickles +1s — the bonus is a debut prize")
    check((sPay.life["groupShots"] ?: 0) == 2 &&
        (sPay.life["selfies"] ?: 0) == 2,
        "group: group shots tick the group counter AND the selfie counter")

    // ---------- feats: first crowd, say cheese ----------
    val sFc = freshState()
    sFc.friendship["Stan"] = 50; sFc.friendship["Kyle"] = 50
    val resFc = Photos.applyPhoto(sFc, Photos.composeGroup(sFc,
        listOf("Stan", "Kyle"), emptyList(), PLAYER_DEFAULT_NAME,
        DEFAULT_APPEARANCE))
    check("first_crowd" in resFc.newFeats,
        "group: the first group shot lands FIRST CROWD")
    val sFc2 = freshState()
    sFc2.friendship["Stan"] = 50; sFc2.friendship["Kyle"] = 50
    val resFc2 = Photos.applyPhoto(sFc2, Photos.compose(sFc2,
        listOf("Stan", "Kyle"), emptyList(), PLAYER_DEFAULT_NAME,
        DEFAULT_APPEARANCE))
    check("first_crowd" !in resFc2.newFeats &&
        (sFc2.life["groupShots"] ?: 0) == 0,
        "group: a crowded SELFIE is not a group shot")
    val sChz = freshState()
    sChz.friendship["Stan"] = 100; sChz.friendship["Kyle"] = 100
    sChz.life["groupShots"] = Photos.GROUP_SHOTS_FEAT - 1
    val resChz = Photos.applyPhoto(sChz, Photos.composeGroup(sChz,
        listOf("Stan", "Kyle"), emptyList(), PLAYER_DEFAULT_NAME,
        DEFAULT_APPEARANCE))
    check("say_cheese" in resChz.newFeats &&
        (sChz.life["groupShots"] ?: 0) == Photos.GROUP_SHOTS_FEAT,
        "group: the 25th group shot lands SAY CHEESE")

    // ---------- generated folks pose in frames too ----------
    val personaA = VisitorSystem.residents().first()
    val personaB = VisitorSystem.residents().drop(1).first()
    NpcMemoryStore.getOrCreate(personaA.loreName).points = 100
    NpcMemoryStore.getOrCreate(personaB.loreName).points = 90
    val sGenG = freshState()
    val recGenG = Photos.composeGroup(sGenG, emptyList(),
        listOf(personaA, personaB), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recGenG.isGroup && recGenG.npcs.map { it.name }.toSet() ==
        setOf(personaA.loreName, personaB.loreName),
        "group: generated residents pose in group frames too")

    // ---------- the judges read group records as-is ----------
    // PHOTO errands: the named person / the named place,
    // settled by applyPhoto off the group record's figures.
    val sEr = freshState()
    eng.createPlayer(sEr, "Runner", DEFAULT_APPEARANCE)
    check(Errands.accept(sEr, Errand("g1", Errands.ASK, "Wendy", "PHOTO",
        "t", "h", targetName = "Kyle", dayKey = sEr.todayKey)),
        "group errand: accept the person errand")
    check(Errands.accept(sEr, Errand("g2", Errands.ASK, "Randy", "PHOTO",
        "t", "h", targetLoc = "BusStop", dayKey = sEr.todayKey)),
        "group errand: accept the place errand")
    sEr.friendship["Stan"] = 50; sEr.friendship["Kyle"] = 50
    Photos.applyPhoto(sEr, Photos.composeGroup(sEr, listOf("Stan", "Kyle"),
        emptyList(), "Runner", DEFAULT_APPEARANCE))
    check(sEr.errandsDoneCount == 2,
        "group: one group shutter settles the person AND the place errand " +
            "(got ${sEr.errandsDoneCount})")

    // participation: a group shot at the cluster counts once
    var evState: GameState? = null
    var evCluster: String? = null
    for (def in SHENANIGANS) {
        if (evState != null) break
        for (t in 0..1439 step 15) {
            val cl = Shenanigans.stageOf(def, t).clusterLoc
            if (cl != null) {
                val s = eng.newState()
                s.todayKey = "20261013"
                s.shenaniganId = def.id
                s.shenaniganDay = s.todayKey
                s.timeMin = t
                evState = s; evCluster = cl
                break
            }
        }
    }
    check(evState != null && evCluster != null,
        "group: a clustered event stage exists to shoot at")
    if (evState != null && evCluster != null) {
        val sEv = evState
        sEv.friendship["Stan"] = 50; sEv.friendship["Kyle"] = 50
        val gRec = Photos.composeGroup(sEv, listOf("Stan", "Kyle"),
            emptyList(), PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
            .copy(locId = evCluster)
        val rEv1 = Photos.applyPhoto(sEv, gRec)
        check(rEv1.participationCounted && sEv.participation == 1,
            "group: a group shot at the cluster counts as participation")
        val rEv2 = Photos.applyPhoto(sEv, Photos.composeGroup(sEv,
            listOf("Stan", "Kyle"), emptyList(), PLAYER_DEFAULT_NAME,
            DEFAULT_APPEARANCE).copy(locId = evCluster))
        check(!rEv2.participationCounted && sEv.participation == 1,
            "group: the second group shot in the same event does NOT recount")
    }

    // ---------- legacy records render and load as before ----------
    val sLeg = freshState()
    sLeg.friendship["Stan"] = 100
    val recLeg = Photos.compose(sLeg, listOf("Stan"), emptyList(),
        PLAYER_DEFAULT_NAME, DEFAULT_APPEARANCE)
    check(recLeg.composition == "" && !recLeg.isGroup,
        "group: the classic compose path writes no composition")
    val backLeg = PhotoRecord.fromMap(recLeg.toMap() - "composition")
    check(backLeg != null && backLeg == recLeg && !backLeg.isGroup,
        "group: a pre-v0.4.0c record map loads as the same classic selfie")
    check(PhotoRecord.fromMap(recBb.toMap()) == recBb,
        "group: a back-to-back record round-trips through its save map")
    val jsonGroup = PhotoRecord.fromMap(
        (Json.parse(Json.stringify(recHot.toMap())) as Map<String, Any?>))
    check(jsonGroup == recHot && jsonGroup?.isGroup == true,
        "group: a group record survives the actual JSON save format")
    val sLoadedG = decodeGameState(
        mapOf<String, Any?>("photos" to listOf(recHot.toMap())))
    check(sLoadedG.photos.size == 1 && sLoadedG.photos[0] == recHot,
        "group: the album loads group records back intact")

    // ---------- wiring ----------
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("Photos.composeGroup") && gaSrc.contains("Group shot"),
        "group wiring: the camera offers the group frame when 2+ are present")
    check(gaSrc.contains("chemistryBonus"),
        "group wiring: the chemistry bonus is announced on the polaroid")
    val pvSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
    check(pvSrc.contains("drawGroupFigures") && pvSrc.contains("GroupGeom.layout") &&
        pvSrc.contains("backToBack"),
        "group wiring: PhotoView lays out compositions + the back-to-back flip")
    val phSrcC = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
    check(phSrcC.contains("COMP_SQUAD") && phSrcC.contains("COMP_STACKED") &&
        phSrcC.contains("object GroupGeom"),
        "group wiring: the pure layout owns the three compositions")
    val photosSrc = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
    check(photosSrc.contains("fun composeGroup") &&
        photosSrc.contains("\"composition\" to"),
        "group wiring: the composition persists in the record map")
}
}

private fun sectionV040d(root: String) {
// ================= v0.4.0d: holiday signature beats =================
// Every holiday gains ONE bespoke playable beat, playable only
// inside its window, judged through the REAL verb rails (the
// Talk gate, Look, the gift rail, Photos.applyPhoto,
// Minigames' catch settle), leaving a permanent mark in capped
// per-(holiday, year) keys — missable without punishment,
// completed forever, back again next year.
println("== v0.4.0d: holiday beats — eight windows, eight small stories ==")
run {
    val eng = Engine(411)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Runner", DEFAULT_APPEARANCE)
        return s
    }
    /** A state inside a holiday window, as the rollover leaves it. */
    fun holidayState(year: Int, month: Int, day: Int, hid: String,
                     timeMin: Int = 720): GameState {
        val s = freshState()
        s.gameYear = year; s.gameMonth = month; s.gameDay = day
        s.todayKey = "%04d%02d%02d".format(year, month, day)
        s.holidayId = hid
        s.timeMin = timeMin
        return s
    }
    fun setLoc(s: GameState, name: String, loc: String) {
        s.agents[name]?.location = loc
    }
    fun playerTo(s: GameState, loc: String) {
        s.agents.values.firstOrNull { it.isPlayer }?.location = loc
    }
    fun photoAt(s: GameState, loc: String) = PhotoRecord(
        id = "hb-${s.absDay}-$loc", dayKey = s.todayKey, dateLabel = "?",
        timeMin = s.timeMin, locId = loc, inside = false,
        weatherId = s.weatherId, appearance = DEFAULT_APPEARANCE,
        figures = listOf(PhotoFigure("Runner", "player", "happy")),
        seed = 3L, absDay = s.absDay)

    // ---------- the registry: one beat per holiday, real people/places/things ----------
    check(HolidayBeats.BEATS.size == HOLIDAYS.size &&
        HolidayBeats.BEATS.map { it.holidayId }.toSet() ==
            HOLIDAYS.map { it.id }.toSet(),
        "beats: exactly one beat per registered holiday (8)")
    val castNames = CharacterSystem.CAST.keys
    val itemIds = ITEMS.map { it.id }.toSet()
    for (b in HolidayBeats.BEATS) {
        check(b.steps.size in 2..8, "beats: ${b.holidayId} has 2–8 steps")
        check(b.title.isNotEmpty() && b.intro.isNotEmpty() &&
            b.hint.isNotEmpty() && b.doneLine.isNotEmpty(),
            "beats: ${b.holidayId} is fully written (title/intro/hint/mark)")
        check(b.ambient.isNotEmpty() || b.ambientGeneric.isNotEmpty(),
            "beats: ${b.holidayId} is referenced in window conversation")
        check(b.rewardCoins in 0..3, "beats: ${b.holidayId} coins at errand scale")
        check(b.rewardFriends.values.all { it in 1..6 },
            "beats: ${b.holidayId} friendship at errand scale, per person")
        check(b.rewardItem == null || b.rewardItem in itemIds,
            "beats: ${b.holidayId} reward item exists")
        for (s in b.steps) {
            check(s.who == null || s.who in castNames,
                "beats: ${b.holidayId} step names a cast member (${s.who})")
            check(s.loc == null || s.loc in LOCATIONS,
                "beats: ${b.holidayId} step names a real place (${s.loc})")
            check(s.houseLoc == null || s.houseLoc in LOCATIONS,
                "beats: ${b.holidayId} house stop names a real house")
            check(s.item == null || s.item in itemIds,
                "beats: ${b.holidayId} step item exists")
            check(s.line.isNotEmpty() && s.short.isNotEmpty(),
                "beats: ${b.holidayId} step is written, long and short")
        }
    }
    check(HolidayBeats.BEATS.flatMap { b -> b.steps.map { it.verb } }.toSet()
        .containsAll(setOf("TALK", "LOOK", "PHOTO", "CATCH", "HOUSE")),
        "beats: the step verbs cover Talk/Look/Photo/Catch/House across the " +
            "year (Give rides the HOUSE rail — exercised below)")
    check(HolidayBeats.CANDY_ITEMS.all { it in itemIds },
        "beats: the good-candy set is real items")

    // ---------- window gating: no holiday, no beat ----------
    val plain = freshState()
    check(HolidayBeats.activeBeat(plain) == null &&
        HolidayBeats.judgeTalk(plain, "Cartman") == null &&
        HolidayBeats.lookText(plain, "MainStreet") == null &&
        HolidayBeats.onCatch(plain) == null &&
        HolidayBeats.onGive(plain, "Kenny", "snack_cake") == null &&
        HolidayBeats.morningNote(plain) == null &&
        HolidayBeats.ambientLine(plain, "Stan") == null,
        "beats: an ordinary day judges nothing, notes nothing, says nothing")
    val wrongDay = holidayState(2026, 12, 30, "christmas")
    check(HolidayBeats.activeBeat(wrongDay) != null,
        "beats: the window is the holidayId's, as the engine maintains it")

    // ---------- instance years (the wrap is the whole game) ----------
    val nye = HOLIDAYS.first { it.id == "newyear" }
    check(HolidayBeats.instanceYear(
        holidayState(2026, 12, 31, "newyear"), nye) == 2026,
        "beats: Dec 31 2026 is the 2026 New Year instance")
    check(HolidayBeats.instanceYear(
        holidayState(2027, 1, 1, "newyear"), nye) == 2026,
        "beats: Jan 1 2027 still belongs to the instance that began Dec 31 2026")
    check(HolidayBeats.instanceYear(
        holidayState(2027, 1, 2, "newyear"), nye) == 2026,
        "beats: even Jan 2 (the wrap-up morning) reads the 2026 instance")

    // ---------- HALLOWEEN: the full route (Look / Talk / Give rails) ----------
    val hw = holidayState(2026, 10, 28, "halloween", 18 * 60)
    val hwBeat = HolidayBeats.beatFor("halloween")!!
    check(HolidayBeats.lookText(hw, "YourHouse") == null,
        "halloween: your own porch waits for the route (last-step rule)")
    val porch = HolidayBeats.lookText(hw, "KyleHouse")
    check(porch != null && porch.contains("toothbrushes") &&
        HolidayBeats.stepsDone(hw, hwBeat) == 1,
        "halloween: the Broflovski porch answers (toothbrushes, audited)")
    check(HolidayBeats.lookText(hw, "KyleHouse") == null,
        "halloween: a porch answers exactly once")
    val stanHit = HolidayBeats.judgeTalk(hw, "Stan")
    check(stanHit != null && stanHit.text.contains("floral") &&
        HolidayBeats.stepsDone(hw, hwBeat) == 2,
        "halloween: catching the resident in costume is the same stop")
    check(HolidayBeats.onGive(hw, "Butters", "tin_can") == null,
        "halloween: junk is not the good candy")
    check(HolidayBeats.onGive(hw, "Butters", "cheesy_poof") != null &&
        HolidayBeats.stepsDone(hw, hwBeat) == 3,
        "halloween: the good candy, delivered, is a stop")
    check(HolidayBeats.onGive(hw, "Kenny", "snack_cake") != null &&
        HolidayBeats.stepsDone(hw, hwBeat) == 4,
        "halloween: Kenny's house, provided for")
    HolidayBeats.lookText(hw, "CartmanHouse")
    check(HolidayBeats.stepsDone(hw, hwBeat) == 5,
        "halloween: five houses down")
    val hwDone = HolidayBeats.lookText(hw, "YourHouse")
    check(hwDone != null && hwDone.contains("BEAT COMPLETE") &&
        HolidayBeats.isDone(hw, hwBeat) &&
        HolidayBeats.yearsDone(hw, "halloween") == 1 &&
        HolidayBeats.doneTotal(hw) == 1,
        "halloween: the route completes and the mark is permanent")
    check((hw.inventory["snack_cake"] ?: 0) >= 1 &&
        Minigames.capsuleCoins(hw) == 2,
        "halloween: the haul lands (the good candy + 2 coins)")
    check(HolidayBeats.lookText(hw, "StanHouse") == null &&
        HolidayBeats.judgeTalk(hw, "Kyle") == null &&
        HolidayBeats.activeBeat(hw) == null,
        "halloween: a played beat stays played, all window long")
    check("holiday_garland" in House.decorFor(hw) &&
        "full_calendar" !in House.decorFor(hw),
        "halloween: the first beat ever hangs the garland, not the calendar")
    check(HolidayBeats.pageLines(hw).any {
        it.contains("Ran the full trick-or-treat route") },
        "halloween: the Journal mark reads back")

    // persistence: a mid-route save round-trips through the real save path
    val hwMid = holidayState(2026, 10, 29, "halloween", 18 * 60)
    HolidayBeats.lookText(hwMid, "StanHouse")
    HolidayBeats.judgeTalk(hwMid, "Kenny")
    val hwBack = decodeGameState(encodeGameState(hwMid))
    check(HolidayBeats.stepsDone(hwBack, hwBeat) == 2 &&
        !HolidayBeats.isDone(hwBack, hwBeat),
        "halloween: the step mask survives the real save path")
    // next year: the same window, a fresh mask, the count grows
    val hw27 = holidayState(2027, 10, 30, "halloween", 18 * 60)
    hw27.life["hbYears:halloween"] = 1; hw27.life["hbTotal"] = 1
    check(HolidayBeats.activeBeat(hw27) != null &&
        HolidayBeats.stepsDone(hw27, hwBeat) == 0,
        "halloween: skipped or played, the route returns next year untouched")
    check(HolidayBeats.pageLines(hw27).any {
        it.contains("▶") && it.contains("The Full Route") },
        "halloween: next year's page shows the live beat again")

    // ---------- CHRISTMAS: the relay, in order ----------
    val xm = holidayState(2026, 12, 22, "christmas")
    check(HolidayBeats.judgeTalk(xm, "Kenny") == null,
        "christmas: the relay refuses to start mid-chain")
    HolidayBeats.judgeTalk(xm, "Cartman")
    check(HolidayBeats.judgeTalk(xm, "Butters") == null,
        "christmas: Butters waits for Kenny's parcel, not Cartman's")
    val kennyBefore = xm.friendship["Kenny"] ?: 0
    HolidayBeats.judgeTalk(xm, "Kenny")
    HolidayBeats.judgeTalk(xm, "Butters")
    val xmDone = HolidayBeats.judgeTalk(xm, "Liane")
    check(xmDone != null && xmDone.completedNow &&
        HolidayBeats.isDone(xm, HolidayBeats.beatFor("christmas")!!),
        "christmas: the relay closes at Liane's")
    check((xm.friendship["Kenny"] ?: 0) == kennyBefore + 4 &&
        (xm.inventory["snack_cake"] ?: 0) >= 1,
        "christmas: the mule is paid (friendship + the cookie tin)")

    // ---------- NEW YEAR: the countdown is a time, not a vibe ----------
    val ny = holidayState(2026, 12, 31, "newyear", 19 * 60)
    playerTo(ny, "MainStreet"); setLoc(ny, "Stan", "MainStreet")
    check(HolidayBeats.judgeTalk(ny, "Stan") == null,
        "newyear: the crowd hasn't gathered before 8 PM")
    ny.timeMin = 21 * 60
    val crowd = HolidayBeats.judgeTalk(ny, "Stan")
    check(crowd != null && crowd.text.contains("crowd"),
        "newyear: talking to anyone in the Main Street crowd joins it")
    ny.timeMin = 23 * 60 + 15
    check(HolidayBeats.lookText(ny, "MainStreet") == null,
        "newyear: 11:15 is not the countdown yet")
    ny.timeMin = 23 * 60 + 45
    val strike = HolidayBeats.lookText(ny, "MainStreet")
    check(strike != null && strike.contains("HAPPY NEW YEAR") &&
        HolidayBeats.isDone(ny, HolidayBeats.beatFor("newyear")!!) &&
        Minigames.capsuleCoins(ny) == 3,
        "newyear: the last Look of the year fires the cannons (early)")
    val jan1 = holidayState(2027, 1, 1, "newyear", 21 * 60)
    playerTo(jan1, "MainStreet"); setLoc(jan1, "Stan", "MainStreet")
    check(HolidayBeats.judgeTalk(jan1, "Stan") == null &&
        HolidayBeats.lookText(jan1, "MainStreet") == null,
        "newyear: on Jan 1 the moment has passed — next year, no hard feelings")

    // ---------- VALENTINE'S: cupid's route + the arc-aware line ----------
    val vd = holidayState(2027, 2, 14, "valentine")
    check(HolidayBeats.judgeTalk(vd, "Stan") == null,
        "valentine: no card, no delivery — Wendy starts the route")
    HolidayBeats.judgeTalk(vd, "Wendy")
    val stanPlain = HolidayBeats.judgeTalk(vd, "Stan")
    check(stanPlain != null && stanPlain.text.contains("twelve things"),
        "valentine: Stan's stomach confirms receipt (the classic tell)")
    for (n in listOf("Bebe", "Clyde", "Craig", "Tweek", "Butters"))
        HolidayBeats.judgeTalk(vd, n)
    val vdDone = HolidayBeats.judgeTalk(vd, "Kenny")
    check(vdDone != null && vdDone.completedNow &&
        (vd.inventory["flower"] ?: 0) >= 1 &&
        (vd.friendship["Tweek"] ?: 0) >= 3,
        "valentine: the route completes — a flower and a vibrating Tweek")
    val vdWarm = holidayState(2027, 2, 14, "valentine")
    vdWarm.storyArcs["stan_wendy_note"] = StoryArcState(
        arcId = "stan_wendy_note", done = true, outcomeId = "stan_wendy_warm")
    HolidayBeats.judgeTalk(vdWarm, "Wendy")
    val stanWarm = HolidayBeats.judgeTalk(vdWarm, "Stan")
    check(stanWarm != null && stanWarm.text.contains("She knows"),
        "valentine: with the note saga resolved warm, Stan's line knows it too")

    // ---------- 4TH OF JULY: pond, Randy, darkness ----------
    val j4 = holidayState(2027, 7, 4, "july4", 10 * 60)
    check(HolidayBeats.judgeTalk(j4, "Randy") == null,
        "july4: Randy deputizes only a fed rehearsal (catch first)")
    check(HolidayBeats.onCatch(j4) != null,
        "july4: any honest fish on the Fourth is the picnic")
    check(HolidayBeats.onCatch(j4) == null,
        "july4: one picnic is enough")
    HolidayBeats.judgeTalk(j4, "Randy")
    check(HolidayBeats.lookText(j4, "KidsPark") == null,
        "july4: the Big One waits for dark (7 PM)")
    j4.timeMin = 19 * 60 + 30
    val bigOne = HolidayBeats.lookText(j4, "KidsPark")
    check(bigOne != null && bigOne.contains("car alarms") &&
        HolidayBeats.isDone(j4, HolidayBeats.beatFor("july4")!!),
        "july4: flashlight held, destiny lit, alarms applauding")

    // ---------- COW DAYS: the vigil ----------
    val cd = holidayState(2027, 7, 18, "cowdays")
    check(HolidayBeats.judgeTalk(cd, "Jimbo") == null,
        "cowdays: orders come after the cow has weighed you")
    check(HolidayBeats.lookText(cd, "MainStreet") != null,
        "cowdays: the blink lands")
    HolidayBeats.judgeTalk(cd, "Jimbo")
    check(HolidayBeats.onPhoto(cd, photoAt(cd, "KidsPark")).isEmpty(),
        "cowdays: a portrait anywhere else is just a photo")
    check(HolidayBeats.onPhoto(cd, photoAt(cd, "MainStreet")).size == 1,
        "cowdays: the official portrait is taken on Main Street")
    val cdDone = HolidayBeats.judgeTalk(cd, "Ned")
    check(cdDone != null && cdDone.completedNow &&
        HolidayBeats.isDone(cd, HolidayBeats.beatFor("cowdays")!!),
        "cowdays: Ned's ceremonial moo closes the vigil")

    // ---------- ST. PATRICK'S: the hunt, finisher last ----------
    val sp = holidayState(2027, 3, 17, "stpatricks")
    check(HolidayBeats.lookText(sp, "SkeetersBar") == null,
        "stpatricks: the pot waits for the other four")
    for (loc in listOf("KidsPark", "Elementary", "TweekBros", "Church")) {
        val found = HolidayBeats.lookText(sp, loc)
        check(found != null && found.contains("OF 5"),
            "stpatricks: a shamrock at $loc")
    }
    check(HolidayBeats.lookText(sp, "KidsPark") == null,
        "stpatricks: a found shamrock stays found")
    val pot = HolidayBeats.lookText(sp, "SkeetersBar")
    check(pot != null && pot.contains("LEPRECHAUN") &&
        HolidayBeats.isDone(sp, HolidayBeats.beatFor("stpatricks")!!) &&
        Minigames.capsuleCoins(sp) == 3,
        "stpatricks: the pot pays three chocolate coins, spent loud")

    // ---------- BLACK FRIDAY: the line feast ----------
    val bf = holidayState(2026, 11, 27, "blackfriday", 8 * 60)
    setLoc(bf, "Butters", "KidsPark")
    check(HolidayBeats.judgeTalk(bf, "Butters") == null,
        "blackfriday: Butters off the line is just Butters (the Mall is the beat)")
    setLoc(bf, "Butters", "Mall")
    check(HolidayBeats.judgeTalk(bf, "Butters") != null,
        "blackfriday: the casserole emergency opens the beat")
    HolidayBeats.judgeTalk(bf, "Linda")
    check(HolidayBeats.judgeTalk(bf, "Butters") != null,
        "blackfriday: the casserole arrives at the line")
    val bfDone = HolidayBeats.onPhoto(bf, photoAt(bf, "Mall"))
    check(bfDone.size == 1 && bfDone[0].completedNow &&
        (bf.inventory["hot_chocolate"] ?: 0) >= 1 &&
        HolidayBeats.isDone(bf, HolidayBeats.beatFor("blackfriday")!!),
        "blackfriday: the fridge-door photo completes the feast")

    // ---------- the morning note: once per holiday, first morning only ----------
    val oct25 = holidayState(2026, 10, 25, "halloween", 7 * 60)
    val note = HolidayBeats.morningNote(oct25)
    check(note != null && note.contains("The Full Route"),
        "morning: the window's first morning names the beat")
    check(House.morningReport(oct25, emptyList(), emptyMap(), 0, false, null)
        .any { it.contains("The Full Route") },
        "morning: the bed report carries the note")
    check(HolidayBeats.morningNote(
        holidayState(2026, 10, 26, "halloween", 7 * 60)) == null,
        "morning: the second morning is silent (no nagging)")
    check(HolidayBeats.morningNote(
        holidayState(2026, 12, 31, "newyear", 7 * 60)) != null &&
        HolidayBeats.morningNote(
            holidayState(2027, 1, 1, "newyear", 7 * 60)) == null,
        "morning: New Year is noted on the 31st, not the 1st")
    oct25.life["hb:halloween:2026:done"] = 1
    check(HolidayBeats.morningNote(oct25) == null,
        "morning: a played beat needs no introduction")

    // ---------- ambient: referenced in conversation, once a day ----------
    val amb = holidayState(2026, 12, 21, "christmas")
    val cartmanAmb = HolidayBeats.ambientLine(amb, "Cartman")
    check(cartmanAmb != null && cartmanAmb.text.contains("WRAPPED"),
        "ambient: a participant with a waiting step says his piece")
    check(HolidayBeats.ambientLine(amb, "Cartman") == null,
        "ambient: once per person per day")
    check(HolidayBeats.ambientLine(amb, "Stan") != null &&
        HolidayBeats.ambientLine(amb, "Kyle") == null,
        "ambient: one generic beat reference a day, town-wide")
    HolidayBeats.judgeTalk(amb, "Cartman")
    amb.absDay += 1
    check(HolidayBeats.ambientLine(amb, "Cartman") == null,
        "ambient: once the step lands, the grumble retires")

    // ---------- the full calendar decor ----------
    val cal = freshState()
    for (h in HOLIDAYS.drop(1)) cal.life["hbYears:${h.id}"] = 1
    cal.life["hbYears:halloween"] = 0
    cal.life["hbTotal"] = 7
    check("full_calendar" !in House.decorFor(cal) &&
        "holiday_garland" in House.decorFor(cal),
        "decor: seven of eight holidays still leaves a bare calendar spot")
    cal.life["hbYears:halloween"] = 1
    check("full_calendar" in House.decorFor(cal) &&
        HolidayBeats.distinctDone(cal) == 8,
        "decor: all eight beats across the years ring the calendar")

    // ---------- the Journal page on a fresh save ----------
    val page = HolidayBeats.pageLines(freshState())
    check(page.size == 1 + HOLIDAYS.size &&
        HOLIDAYS.all { h -> page.any { it.contains(h.name) } } &&
        page.any { it.contains("its beat") },
        "journal: the HOLIDAYS page lists every holiday and its beat")

    // ---------- the calendar soak: 400 days, holidays firing ----------
    // Drive the real rollover through a full year and change:
    // every holiday must open and wrap through the episode
    // machine; two beats get played through the real calendar
    // (Christmas chain, Shamrock hunt) by their own judges;
    // and nobody's keys grow teeth.
    val engS = Engine(417)
    val soak = engS.newState()
    engS.createPlayer(soak, "Soaker", DEFAULT_APPEARANCE)
    val seenHolidays = mutableSetOf<String>()
    var soakError: String? = null
    try {
        repeat(400) {
            engS.onNewDay(soak)
            soak.holidayId?.let { seenHolidays += it }
            when (soak.holidayId) {
                "christmas" -> {
                    HolidayBeats.judgeTalk(soak, "Cartman")
                    HolidayBeats.judgeTalk(soak, "Kenny")
                    HolidayBeats.judgeTalk(soak, "Butters")
                    HolidayBeats.judgeTalk(soak, "Liane")
                }
                "stpatricks" -> {
                    for (loc in listOf("Elementary", "Church", "KidsPark",
                        "TweekBros", "SkeetersBar"))
                        HolidayBeats.lookText(soak, loc)
                }
            }
            // every live beat gets poked by the wrong verb too —
            // the judges must stay shut outside their steps
            HolidayBeats.onCatch(soak)
            HolidayBeats.onPhoto(soak, photoAt(soak, "BusStop"))
        }
    } catch (e: Exception) {
        soakError = "${e.javaClass.simpleName}: ${e.message}"
    }
    check(soakError == null, "soak: 400 days of rollovers with holidays " +
        "firing and beats judged, no exception (got $soakError)")
    check(seenHolidays == HOLIDAYS.map { it.id }.toSet(),
        "soak: all eight holidays opened inside 400 days (got $seenHolidays)")
    check(soak.episodes.any { it.kind == "holiday" && it.finished },
        "soak: holiday episodes wrapped through the machine")
    check(HolidayBeats.yearsDone(soak, "christmas") == 1 &&
        HolidayBeats.yearsDone(soak, "stpatricks") == 1,
        "soak: the two played beats completed through the real calendar")
    check(soak.life.keys.count { it.startsWith("hb:") } <= 2 * 8 &&
        soak.life.keys.count { it.startsWith("hbYears:") } <= 8,
        "soak: beat keys stay capped — one mask + one flag per played " +
            "instance, one counter per holiday (got " +
            "${soak.life.keys.count { it.startsWith("hb") }})")
    check(Episodes.airingHoliday(soak) == null,
        "soak: no holiday episode is left hanging at day 400")

    // ---------- wiring ----------
    val hbSrc = File(root, "src/com/hunt3r/southparktown/HolidayBeats.kt").readText()
    check(!hbSrc.contains("import android"),
        "wiring: HolidayBeats.kt stays pure Kotlin (JVM-testable)")
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("TalkGate.gateFor") &&
        gaSrc.contains("HolidayBeats.judgeTalk"),
        "wiring: the Talk gate judges beat steps")
    check(gaSrc.contains("HolidayBeats.lookText"),
        "wiring: Look judges beat steps")
    check(gaSrc.contains("HolidayBeats.onGive"),
        "wiring: the gift rail judges the good candy")
    check(File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
            .contains("HolidayBeats.ambientLine") &&
        gaSrc.contains("TalkGate.owedLines"),
        "wiring: conversations reference the beat in its window (via TalkGate)")
    check(gaSrc.contains("HolidayBeats.doneTotal"),
        "wiring: the polaroid announces a beat settled by the shutter")
    val phSrc = File(root, "src/com/hunt3r/southparktown/Photos.kt").readText()
    check(phSrc.contains("HolidayBeats.onPhoto"),
        "wiring: applyPhoto settles beat portrait steps")
    val mgSrc = File(root, "src/com/hunt3r/southparktown/Minigames.kt").readText()
    check(mgSrc.contains("HolidayBeats.onCatch"),
        "wiring: a catch settles the Fourth's picnic")
    val jSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jSrc.contains("🎉 HOLIDAYS") && jSrc.contains("HolidayBeats.pageLines"),
        "wiring: the Journal renders the HOLIDAYS page")
    val hSrc = File(root, "src/com/hunt3r/southparktown/House.kt").readText()
    check(hSrc.contains("HolidayBeats.morningNote") &&
        hSrc.contains("holiday_garland") && hSrc.contains("full_calendar"),
        "wiring: the morning report notes the beat; the house derives its marks")
    val epSrc = File(root, "src/com/hunt3r/southparktown/Episodes.kt").readText()
    check(epSrc.contains("HolidayBeats.isDone"),
        "wiring: a holiday's credits name its played beat")
}
}
private fun sectionV040e(root: String) {
// ================= v0.4.0e: voice & barks =================
// The voice pass: every cast member gains a rhythm signature
// (Barks.PATTERNS) rendered on their own blip voice, greeting
// barks fire under pure pinned rules (presence weighting,
// caps, cooldowns, quiet hours, indoor/evening shaping) with
// a paper hello bubble whose geometry is pinned, and dialogue
// blips bend with the line's mood — while every pre-existing
// render stays byte-identical (the NEUTRAL fingerprint below),
// so the SoundPool cache and the v020g render stamp stand.
println("== v0.4.0e: barks, mood blips, the peak budget re-proven ==")
run {
    fun peakOf(pcm: ShortArray): Int = pcm.maxOf { kotlin.math.abs(it.toInt()) }
    fun zcrPerSec(pcm: ShortArray): Double {
        var zc = 0; var prev = 0
        for (v in pcm) { val iv = v.toInt()
            if ((prev < 0 && iv >= 0) || (prev > 0 && iv <= 0)) zc++
            if (iv != 0) prev = iv }
        return zc * SoundGen.SAMPLE_RATE.toDouble() / pcm.size
    }
    fun roughPerPeak(pcm: ShortArray): Double {
        var rough = 0L; var prev = 0
        for (v in pcm) { val iv = v.toInt(); rough += kotlin.math.abs(iv - prev); prev = iv }
        return (rough.toDouble() / pcm.size) / maxOf(1, peakOf(pcm))
    }
    /** Mean |sample| / peak: a lowpassed voice squashes the
     *  body and keeps the spikes (low crest); a squared-off
     *  electronic voice holds its level (high crest). */
    fun crest(pcm: ShortArray): Double {
        val p = maxOf(1, peakOf(pcm)).toDouble()
        return pcm.sumOf { kotlin.math.abs(it.toInt()) }.toDouble() / pcm.size / p
    }
    /** Fraction of samples dwelling above 85% of peak. */
    fun dwell85(pcm: ShortArray): Double {
        val p = maxOf(1, peakOf(pcm)).toDouble()
        return pcm.count { kotlin.math.abs(it.toInt()) > 0.85 * p }.toDouble() / pcm.size
    }
    val pb = SoundGen.PeakBudget

    // ---------- the table: 70 patterns, each recognizably its owner ----------
    check(Barks.PATTERNS.size == 98,
        "barks: 98 patterns (got ${Barks.PATTERNS.size})")
    check(Barks.PATTERNS.keys == CharacterSystem.CAST.keys,
        "barks: the table covers exactly the cast")
    check(Barks.PATTERNS.values.map { it.hello }.toSet().size == 98,
        "barks: every hello is its own line (no shared greetings)")
    check(Barks.PATTERNS.values.map { Barks.signature(it) }.toSet().size == 98,
        "barks: every rhythm signature is unique")
    val shapedKeys = Barks.PATTERNS.values.map { pat ->
        "${pat.notes.size}:${pat.notes.first().semi}:${pat.notes.last().semi}"
    }.toSet()
    check(shapedKeys.size >= 33,
        "barks: coarse (count, first, last) shapes mostly differ — the " +
            "handful that share one are split by middle notes, lengths, " +
            "gaps (and Ned by his voice box) in the full signature " +
            "(got ${shapedKeys.size})")
    for ((name, pat) in Barks.PATTERNS) {
        check(pat.notes.size in 2..6, "barks: $name has 2..6 notes")
        check(pat.notes.all { it.semi in -7..12 && it.len in 0.4f..2.0f },
            "barks: $name's notes sit in the sane band")
        check(pat.gap in 0.1f..0.6f, "barks: $name's gap is a breath, not a pause")
        check(pat.hello.isNotBlank() && pat.hello.length <= 40 &&
            !pat.hello.contains("{newkid}"),
            "barks: $name's hello is one short original line")
        check(Barks.totalBeats(pat) in 2.0f..7.0f,
            "barks: $name's pattern is a greeting, not a song")
        check(SoundGen.BLIP_FAMILIES.containsKey(name),
            "barks: $name has the blip voice the pattern rides on")
    }
    // the shapes the table claims, pinned by name
    val craig = Barks.PATTERNS["Craig"]!!
    check(craig.notes.size == 2 && craig.notes.all { it.semi == 0 },
        "barks: Craig is a flat two-note (of course he is)")
    check(Barks.PATTERNS["Kenny"]!!.notes.size >= 5,
        "barks: Kenny is a rapid patter (5+ short notes)")
    check(SoundGen.familyFor("Kenny") == SoundGen.BlipFam.MUFFLED,
        "barks: Kenny's patter rides the MUFFLED family (parka rules)")
    check(Barks.PATTERNS["Cartman"]!!.notes.first().len >= 1.6f,
        "barks: Cartman's first note drags — drawn-out and imperious")
    val butters = Barks.PATTERNS["Butters"]!!
    check(butters.notes.last().semi > butters.notes.first().semi,
        "barks: Butters ends higher than he started (the up-lilt)")
    check(Barks.PATTERNS["Ned"]!!.electronic &&
        Barks.PATTERNS.values.count { it.electronic } == 1,
        "barks: Ned's voice box is the table's only electronic voice")
    check(Barks.PATTERNS.values.count { it.notes.size >= 3 } >= 30,
        "barks: most of the town gets a real rhythm (3+ notes)")

    // ---------- the renders: deterministic, bounded, in-voice ----------
    for (name in Barks.PATTERNS.keys) {
        val a = SoundGen.renderBark(name)
        val b = SoundGen.renderBark(name)
        check(a.contentEquals(b), "barks: $name's bark renders deterministically")
        check(a.isNotEmpty() && peakOf(a) > 3000,
            "barks: $name's bark is not silence")
        check(pb.peakOf(a) <= pb.BARK_CEILING + 0.002f,
            "barks: $name's bark renders under the bark ceiling")
        val sec = a.size.toDouble() / SoundGen.SAMPLE_RATE
        check(sec in 0.18..1.2, "barks: $name's bark is greeting-length (${(sec * 100).toInt() / 100.0}s)")
    }
    check(Barks.PATTERNS.keys.minByOrNull {
            SoundGen.renderBark(it).size } == "Tweek",
        "barks: Tweek's staccato is the shortest bark in town")
    check(SoundGen.renderBark("Some Generated Person").isEmpty(),
        "barks: names outside the table render silence (callers gate)")
    println("barks zcr: kenny ${zcrPerSec(SoundGen.renderBark("Kenny"))}, " +
        "stan ${zcrPerSec(SoundGen.renderBark("Stan"))}, " +
        "ned ${zcrPerSec(SoundGen.renderBark("Ned"))}")
    check(zcrPerSec(SoundGen.renderBark("Kenny")) <
        zcrPerSec(SoundGen.renderBark("Stan")),
        "barks: the parka eats Kenny's consonants (lower crossing rate)")
    // the two special voices, told apart in the waveform:
    // Kenny's lowpass squashes his bark's body while the
    // spikes survive (the table's lowest crest), and Ned's
    // buzz-modulated box never dwells at the top the way a
    // plain voice does — neither matches a flesh voice.
    val kennyBark = SoundGen.renderBark("Kenny")
    val nedBark = SoundGen.renderBark("Ned")
    check(crest(kennyBark) < 0.36 && crest(kennyBark) < crest(nedBark) * 0.85 &&
        crest(kennyBark) < crest(SoundGen.renderBark("Stan")),
        "barks: the parka's crest is unmistakably the squashed one")
    check(dwell85(nedBark) < 0.6 * minOf(dwell85(SoundGen.renderBark("Stan")),
            dwell85(SoundGen.renderBark("Craig")),
            dwell85(SoundGen.renderBark("Jesus"))),
        "barks: the voice box's buzz keeps it off the top — no plain voice dwells like it")

    // ---------- mood blips: the contour bends, NEUTRAL never moved ----------
    // The legacy fingerprint, measured on the pre-v0.4.0e
    // renders (pool seed): if NEUTRAL ever drifts, every
    // phone's cache lies — so these numbers are law now.
    val legacyLen = mapOf(
        SoundGen.BlipFam.PLAYER to 1984, SoundGen.BlipFam.KID to 1984,
        SoundGen.BlipFam.KID_HIGH to 1874, SoundGen.BlipFam.ADULT_M to 2646,
        SoundGen.BlipFam.ADULT_DEEP to 2866, SoundGen.BlipFam.ADULT_F to 2425,
        SoundGen.BlipFam.MUFFLED to 2425)
    val legacyPeak = mapOf(
        SoundGen.BlipFam.PLAYER to 10627, SoundGen.BlipFam.KID to 10627,
        SoundGen.BlipFam.KID_HIGH to 10627, SoundGen.BlipFam.ADULT_M to 10627,
        SoundGen.BlipFam.ADULT_DEEP to 10627, SoundGen.BlipFam.ADULT_F to 10627,
        SoundGen.BlipFam.MUFFLED to 15728)
    for (fam in SoundGen.BlipFam.values()) {
        val seed = 1234L + fam.ordinal
        val neutral = SoundGen.renderBlip(fam, seed)
        check(neutral.size == legacyLen[fam] && peakOf(neutral) == legacyPeak[fam],
            "mood: ${fam.name}'s NEUTRAL blip is byte-fingerprinted to the legacy render")
        check(neutral.contentEquals(SoundGen.renderBlip(fam, seed, SoundGen.BlipMood.NEUTRAL)),
            "mood: the 2-arg blip IS the NEUTRAL render for ${fam.name}")
        for (mood in SoundGen.BlipMood.values()) {
            val r = SoundGen.renderBlip(fam, seed, mood)
            check(r.contentEquals(SoundGen.renderBlip(fam, seed, mood)),
                "mood: ${fam.name}/${mood.name} renders deterministically")
            check(pb.peakOf(r) <= pb.BLIP_CEILING + 0.002f,
                "mood: ${fam.name}/${mood.name} renders under the blip ceiling")
            check(r.isNotEmpty() && peakOf(r) > 3000,
                "mood: ${fam.name}/${mood.name} is not silence")
        }
    }
    val kid = SoundGen.BlipFam.KID
    val kSeed = 1234L + kid.ordinal
    val lenN = SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.NEUTRAL).size
    val lenE = SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.EXCITED).size
    val lenS = SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.SAD).size
    val lenA = SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.ANGRY).size
    check(lenS > lenN && lenN > lenA && lenA > lenE,
        "mood: sad drags longest, excited is the shortest chirp")
    check(zcrPerSec(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.EXCITED)) >
        zcrPerSec(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.NEUTRAL)) &&
        zcrPerSec(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.NEUTRAL)) >
        zcrPerSec(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.SAD)),
        "mood: pitch orders excited > neutral > sad in the waveform")
    check(roughPerPeak(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.ANGRY)) >
        roughPerPeak(SoundGen.renderBlip(kid, kSeed, SoundGen.BlipMood.NEUTRAL)),
        "mood: angry is sharper — a harder clip, measurably rougher edge")

    // ---------- moodOfLine: the line's own data drives the contour ----------
    check(SoundGen.moodOfLine("Cartman", "DAMMIT, that was my last one!") ==
        SoundGen.BlipMood.ANGRY, "mood: caps-shouting reads angry")
    check(SoundGen.moodOfLine("Timmy", "TIMMY!") == SoundGen.BlipMood.EXCITED,
        "mood: Timmy's caps are just Timmy — the shout rule skips him")
    check(SoundGen.moodOfLine("Butters", "Oh… okay. Sorry, fellas.") ==
        SoundGen.BlipMood.SAD, "mood: ellipses and sorry drag the blip down")
    check(SoundGen.moodOfLine("Kyle", "I miss you!!") == SoundGen.BlipMood.SAD,
        "mood: sad beats excited when a line does both")
    check(SoundGen.moodOfLine("Stan", "Dude, we actually won!") ==
        SoundGen.BlipMood.EXCITED, "mood: a plain exclamation lifts")
    check(SoundGen.moodOfLine("Wendy", "That is so awesome.") ==
        SoundGen.BlipMood.EXCITED, "mood: the lift words work without punctuation")
    check(SoundGen.moodOfLine("Craig", "The pond is frozen. Again.") ==
        SoundGen.BlipMood.NEUTRAL, "mood: flat facts stay neutral")

    // ---------- the budget, re-proven with the bark in the stack ----------
    println("budget v0.4.0e: bark out ${pb.barkPeakOut()}, mood blip out " +
        "${pb.moodBlipPeakOut()}, bark stack ${pb.barkStack()}")
    check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f,
        "budget: the loudest bark costs no more than the loudest blip")
    check(pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
        "budget: no mood contour out-peaks the neutral blip")
    check(pb.barkStack() <= 1.0f,
        "budget: bark + sting + bed + tune stays under full scale")

    // ---------- trigger rules: caps, cooldowns, quiet hours, shaping ----------
    check(Barks.inQuietHours(22 * 60 + 30) && Barks.inQuietHours(23 * 60) &&
        Barks.inQuietHours(6 * 60 + 29),
        "barks: quiet hours cover the small hours")
    check(!Barks.inQuietHours(6 * 60 + 30) && !Barks.inQuietHours(12 * 60) &&
        !Barks.inQuietHours(22 * 60 + 29),
        "barks: the day (and the edge of evening) stays barkable")
    check(Barks.gateOpen(true, 12 * 60) && !Barks.gateOpen(false, 12 * 60) &&
        !Barks.gateOpen(true, 23 * 60),
        "barks: the gate is the toggle AND the clock")
    close(Barks.volumeScale(false, 12 * 60), 1f, 0.001f,
        "barks: full voice outdoors at midday")
    close(Barks.volumeScale(true, 12 * 60), Barks.INDOOR_SCALE, 0.001f,
        "barks: indoors is softer")
    close(Barks.volumeScale(false, 20 * 60), Barks.EVENING_SCALE, 0.001f,
        "barks: the evening winds down")
    close(Barks.volumeScale(true, 20 * 60),
        Barks.INDOOR_SCALE * Barks.EVENING_SCALE, 0.001f,
        "barks: indoor-evening stacks both softenings")
    close(Barks.volumeScale(false, 18 * 60 + 59), 1f, 0.001f,
        "barks: no wind-down before its hour")
    check(Barks.INDOOR_SCALE in 0.5f..0.9f && Barks.EVENING_SCALE in 0.4f..0.8f,
        "barks: the shapings soften, never mute")
    check(Barks.cooledDown(null, 500) &&
        !Barks.cooledDown(500, 500 + Barks.COOLDOWN_MINUTES - 1) &&
        Barks.cooledDown(500, 500 + Barks.COOLDOWN_MINUTES),
        "barks: the per-NPC cooldown is exactly its constant")
    check(Barks.COOLDOWN_MINUTES in 5..60 && Barks.ARRIVAL_CHANCE in 0.05..0.5 &&
        Barks.BUBBLE_MS in 1500L..3000L,
        "barks: caps sit in the polite band (cooldown, arrival chance, bubble life)")

    // ---------- presence weighting: your people hail you ----------
    close(Barks.weightOf(0), 1f, 0.001f, "barks: a stranger still weighs 1")
    close(Barks.weightOf(-50), 1f, 0.001f, "barks: a rival's weight floors at 1")
    close(Barks.weightOf(100), 6f, 0.001f, "barks: a best friend weighs 6")
    check(Barks.pickBarker(emptyList(), 0.5) == null,
        "barks: nobody present, nobody picked")
    check(Barks.pickBarker(listOf("Craig" to 0), 0.99) == "Craig",
        "barks: a lone candidate always barks")
    val duo = listOf("Stranger" to 0, "Bestie" to 100)
    check(Barks.pickBarker(duo, 0.5) == "Bestie",
        "barks: the roll walks heaviest-first — mid-roll lands on the friend")
    check(Barks.pickBarker(duo, 0.99) == "Stranger",
        "barks: the far tail of the roll still reaches the stranger")
    check(Barks.pickBarker(duo, 0.0) == "Bestie" &&
        Barks.pickBarker(duo, 0.5) == Barks.pickBarker(duo, 0.5),
        "barks: the pick is a pure function of the roll")

    // ---------- bubble geometry: paper over the head, never in the chrome ----------
    val r1 = Barks.bubbleRect(500f, 900f, 200f, 1080f, 340f)
    close(r1.top, 900f - Barks.BUBBLE_GAP - Barks.BUBBLE_H, 0.01f,
        "bubble: hangs a gap above the head")
    close(r1.height, Barks.BUBBLE_H, 0.01f, "bubble: one line tall")
    check(r1.left >= Barks.BUBBLE_EDGE && r1.right <= 1080f - Barks.BUBBLE_EDGE &&
        r1.top >= 340f + Barks.BUBBLE_CHROME_GAP && r1.bottom <= 900f,
        "bubble: inside the view, below the chrome, above the head")
    val r2 = Barks.bubbleRect(500f, 380f, 200f, 1080f, 340f)
    close(r2.top, 340f + Barks.BUBBLE_CHROME_GAP, 0.01f,
        "bubble: a high-standing figure's bubble pins under the chrome")
    val r3 = Barks.bubbleRect(20f, 900f, 200f, 1080f, 340f)
    close(r3.left, Barks.BUBBLE_EDGE, 0.01f,
        "bubble: the left edge clamps")
    val r4 = Barks.bubbleRect(500f, 900f, 4000f, 1080f, 340f)
    check(r4.width <= 1080f - 2 * Barks.BUBBLE_EDGE && r4.left >= Barks.BUBBLE_EDGE,
        "bubble: an over-wide hello still fits the view")
    val r5 = Barks.bubbleRect(500f, 900f, 200f, 1080f, 340f, fontScale = 1.3f)
    close(r5.height, Barks.BUBBLE_H * 1.3f, 0.01f,
        "bubble: the height follows the system font scale")

    // ---------- wiring ----------
    val soundSrc = File(root, "src/com/hunt3r/southparktown/Sound.kt").readText()
    check(soundSrc.contains("renderBark") && soundSrc.contains("BARK_GAIN_SCALE") &&
        soundSrc.contains("bark_\$name"),
        "wiring: the pool caches a bark per cast member and plays it at the budget scale")
    check(soundSrc.contains("renderBlip(fam, 1234L + fam.ordinal, mood)"),
        "wiring: the pool caches the mood-contoured blips")
    check(soundSrc.contains("\"v020g_r1\""),
        "wiring: the render stamp stands — every pre-existing render is byte-identical")
    val dlgSrc = File(root, "src/com/hunt3r/southparktown/DialogueSheet.kt").readText()
    check(dlgSrc.contains("moodOfLine"),
        "wiring: dialogue blips are mood-driven at the bubble")
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("maybeBark") && gaSrc.contains("Barks.decide") &&
        gaSrc.contains("showBark"),
        "wiring: entries and arrivals route through the Barks gates")
    val barksSrc = File(root, "src/com/hunt3r/southparktown/Barks.kt").readText()
    check(barksSrc.contains("fun decide") && barksSrc.contains("gateOpen") &&
        barksSrc.contains("pickBarker") && barksSrc.contains("cooledDown"),
        "wiring: the pure decision composes the gate, the pick and the cooldown")
    val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("showBark") && gvSrc.contains("Barks.bubbleRect"),
        "wiring: the scene draws the hello bubble from the pinned geometry")
    val setSrc = File(root, "src/com/hunt3r/southparktown/SettingsActivity.kt").readText()
    check(setSrc.contains("Greeting barks") && setSrc.contains("setBarksEnabled"),
        "wiring: Settings carries the barks toggle")
    val prefsSrc = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    check(prefsSrc.contains("\"audio_barks\"") && prefsSrc.contains("barksEnabled"),
        "wiring: the toggle persists under its one additive key")
}
}

/** v0.4.0f section, extracted from main() like the others:
 *  mystery arc #3 — the excavation. */
private fun sectionV040f(root: String) {
// ================= v0.4.0f: mystery arc #3, "What's Buried" =================
// Queue #4 item 6. The third case keeps the discipline of the
// first two — chapters on the episode machinery, clues three
// ways plus paper, a gated dialogue-safe finale, permanent
// marks, retirement — with a different skeleton again: an
// OBJECT-driven excavation. Four weekly dig sites, a map that
// changes while the arc runs, and a finale that is not an
// accusation but a disposition: what happens to the box.
    println("== v0.4.0f: mystery arc #3 ? what's buried ==")
    val eng3 = Engine(4040)
    fun baseInf3(id: String) = FACTIONS.first { it.id == id }.baseInfluence

    // ---------- def integrity ----------
    check(Mystery3.CHAPTERS3.size == 4, "buried: four chapters (one per site)")
    check(Mystery3.CHAPTERS3.map { it.id }.distinct().size == 4,
        "buried: chapter ids are unique")
    check(Mystery3.CHAPTERS3[3].id == Mystery3.FINALE3_ID,
        "buried: the last chapter is the finale (the last pit)")
    val regularIds3 = SHENANIGANS.map { it.id }.toSet()
    for (def in Mystery3.CHAPTERS3) {
        check(def.stages.size == 4 && def.causers.isNotEmpty() &&
            def.episodeTitles.size == 2 && def.coldOpen.isNotEmpty() &&
            def.theme.header.isNotBlank(),
            "buried: ${def.id} carries the full episode kit " +
                "(4 stages, causers, 2 titles, cold open)")
        check(def.id !in regularIds3 && SHENANIGAN_BY_ID[def.id] == def,
            "buried: ${def.id} is not in the random pool but resolves by id")
        check(def.id !in Mystery.ARC_CHAPTERS.map { it.id } &&
            def.id !in Mystery2.BEATS.map { it.id },
            "buried: ${def.id} is its own case, not an earlier one")
    }
    check(SHENANIGANS.size == 10, "buried: the random pool is still the ten")
    check(Mystery3.CHAPTERS3.map { it.stages[2].clusterLoc } ==
        listOf("TegridyFarms", "StarksPond", "Elementary", "TegridyFarms"),
        "buried: the climaxes dig at the farm, the pond bank, the oak lot, the farm again")

    // ---------- the clue registry ----------
    check(Mystery3.CLUES3.size == 12, "buried: twelve clues on the board")
    check(Mystery3.CLUES3.map { it.id }.distinct().size == 12 &&
        Mystery3.CLUES3.all { it.id in Mystery3.CLUE3_IDS },
        "buried: clue ids are unique")
    check(Mystery3.CLUES3.count { it.kind == Mystery3.Kind3.LOOK } == 6 &&
        Mystery3.CLUES3.count { it.kind == Mystery3.Kind3.WITNESS } == 3 &&
        Mystery3.CLUES3.count { it.kind == Mystery3.Kind3.PARTICIPATION } == 2 &&
        Mystery3.CLUES3.count { it.kind == Mystery3.Kind3.PAPER } == 1,
        "buried: clues split 6 finds / 3 witnesses / 2 participations / 1 paper")
    for (clue in Mystery3.CLUES3) {
        check(clue.detail.isNotBlank(), "buried: ${clue.id} carries its flavor")
        check(clue.minChapter in 0..3,
            "buried: ${clue.id} opens inside the four chapters")
        when (clue.kind) {
            Mystery3.Kind3.WITNESS -> check(
                clue.npc != null && clue.npc in AGENT_PROFILES &&
                    !clue.spoken.isNullOrBlank(),
                "buried: ${clue.id}'s witness is a real cast member who speaks")
            Mystery3.Kind3.LOOK, Mystery3.Kind3.PAPER -> check(
                clue.locId != null && clue.locId in LOCATIONS &&
                    !clue.foundText.isNullOrBlank(),
                "buried: ${clue.id} is hidden at a real location")
            Mystery3.Kind3.PARTICIPATION -> check(
                clue.chapterDefId != null &&
                    clue.chapterDefId in Mystery3.CHAPTER3_BY_ID,
                "buried: ${clue.id} is earned at a real dig chapter")
        }
    }
    check(Mystery3.DISPOSITION_MIN_CLUES in 1 until Mystery3.CLUES3.size,
        "buried: the disposition gate sits inside the clue count")
    check(Mystery3.CHOICE_KEYS.size == 3 &&
        Mystery3.BRANCH_KEYS == Mystery3.CHOICE_KEYS + Mystery3.DEFAULT_BRANCH,
        "buried: three dispositions can be chosen; the fourth is the default")

    // ---------- the dig sites & their tokens ----------
    check(Mystery3.DIG_SITES.size == 4, "buried: four dig sites")
    check(Mystery3.DIG_SITES.map { it.chapter } == listOf(0, 1, 2, 3),
        "buried: one site opens per chapter, in order")
    check(Mystery3.DIG_SITES.all { it.locId in LOCATIONS },
        "buried: every site sits at a real location")
    val siteToks = Mystery3.DIG_SITES.flatMap { it.tokens }
    check(siteToks.distinct().size == siteToks.size &&
        Mystery3.DIG_TOKENS == siteToks.toSet() + Mystery3.MARKER_TOKEN,
        "buried: site tokens are unique; the registry is sites + the marker stone")
    val sceneSrc3 = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    for (tok in Mystery3.DIG_TOKENS) {
        check(sceneSrc3.contains("dig: $tok"),
            "buried: the dig layer draws $tok")
    }
    // which tokens are live, state by state
    val sDig = eng3.newState()
    check(Mystery3.digTokensByLoc(sDig).isEmpty(),
        "buried: no dressing before the case exists")
    sDig.arc2Retired = true; sDig.arc3Started = true; sDig.arc3Chapter = 1
    check(Mystery3.digTokensByLoc(sDig) ==
        mapOf("TegridyFarms" to Mystery3.DIG_SITES[0].tokens),
        "buried: chapter 1 dresses the field site only")
    sDig.arc3Chapter = 2
    check(Mystery3.digTokensByLoc(sDig)["StarksPond"] ==
        Mystery3.DIG_SITES[1].tokens,
        "buried: chapter 2 opens the pond bank")
    sDig.arc3Chapter = 3
    check(Mystery3.digTokensByLoc(sDig)["Elementary"] ==
        Mystery3.DIG_SITES[2].tokens,
        "buried: chapter 3 opens the oak lot")
    sDig.arc3Chapter = 4
    check(Mystery3.digTokensByLoc(sDig)["TegridyFarms"] ==
        Mystery3.DIG_SITES[0].tokens + Mystery3.DIG_SITES[3].tokens,
        "buried: chapter 4 digs the deep corner beside the first field")
    sDig.arc3Retired = true; sDig.arc3Branch = "county"
    check(Mystery3.digTokensByLoc(sDig).isEmpty(),
        "buried: after a county close the sites grass over, nothing kept")
    sDig.arc3Branch = "publish"
    check(Mystery3.digTokensByLoc(sDig) ==
        mapOf(Mystery3.MARKER_LOC to listOf(Mystery3.MARKER_TOKEN)),
        "buried: after a public close only the marker stone stands")

    // ---------- scheduling: the case queues behind BOTH ----------
    val sGate = eng3.newState()
    check(Mystery3.dueChapter3(sGate) == null && sGate.arc3DueAbsDay == -1,
        "buried: while the pond case is open, this one does not even schedule")
    sGate.arcRetired = true
    check(Mystery3.dueChapter3(sGate) == null && sGate.arc3DueAbsDay == -1,
        "buried: while the booth case is open, this one still waits")
    sGate.arc2Retired = true; sGate.arc2RetiredDay = 100; sGate.absDay = 100
    check(Mystery3.dueChapter3(sGate) == null &&
        sGate.arc3DueAbsDay == 100 + Mystery3.OPEN_DELAY_DAYS,
        "buried: the first ask after the booth retires books chapter 1 ten days out")
    sGate.absDay = sGate.arc3DueAbsDay - 1
    check(Mystery3.dueChapter3(sGate) == null, "buried: chapter 1 is never early")
    sGate.absDay = sGate.arc3DueAbsDay
    check(Mystery3.dueChapter3(sGate)?.id == Mystery3.CHAPTERS3[0].id,
        "buried: chapter 1 is due on its day")
    sGate.holidayId = "halloween"
    check(Mystery3.dueChapter3(sGate) == null,
        "buried: a due chapter defers for a holiday episode")
    sGate.holidayId = null
    check(Mystery3.dueChapter3(sGate)?.id == Mystery3.CHAPTERS3[0].id,
        "buried: ...and is due again the moment the holiday clears")
    Mystery3.noteChapterStarted3(sGate, Mystery3.CHAPTERS3[0])
    check(sGate.arc3Started && sGate.arc3Chapter == 1 &&
        sGate.arc3DueAbsDay == sGate.absDay + Mystery3.CHAPTER_GAP_DAYS,
        "buried: a chapter books the next one a week out")
    for (i in 1..3) {
        sGate.absDay = sGate.arc3DueAbsDay
        check(Mystery3.dueChapter3(sGate)?.id == Mystery3.CHAPTERS3[i].id,
            "buried: chapter ${i + 1} follows in order")
        Mystery3.noteChapterStarted3(sGate, Mystery3.CHAPTERS3[i])
    }
    check(Mystery3.dueChapter3(sGate) == null,
        "buried: once the last chapter has aired, nothing more is due")
    check(!Mystery3.boardVisible3(eng3.newState()),
        "buried: no board before the case exists")

    // ---------- clues: witnesses ----------
    val sWit = eng3.newState()
    sWit.arcRetired = true; sWit.arc2Retired = true
    sWit.arc3Started = true; sWit.arc3Chapter = 1
    check(Mystery3.witnessLine3(sWit, "Stuart") == null &&
        Mystery3.witnessLine3(sWit, "Jimbo") == null &&
        Mystery3.witnessLine3(sWit, "Sharon") == null,
        "buried: the old-timers have nothing to remember before the layers open")
    sWit.arc3Chapter = 2
    val stu = Mystery3.witnessLine3(sWit, "Stuart")
    check(stu != null && stu.speaker == "Stuart" &&
        "oldtimer_memory" in sWit.mystery3Clues,
        "buried: Stuart remembers the commune")
    check(Mystery3.witnessLine3(sWit, "Stuart") == null,
        "buried: a witness tells it exactly once")
    check(Mystery3.witnessLine3(sWit, "Jimbo")?.speaker == "Jimbo" &&
        "night_cart" in sWit.mystery3Clues,
        "buried: Jimbo tells the night-cart story (and calls it what it is)")
    check(sWit.events.any { it.contains("CLUE 2/12") },
        "buried: a found clue hits the ticker")
    check(Mystery3.witnessLine3(sWit, "Sharon") == null,
        "buried: Sharon's suspicion waits for the oak lot chapter")
    check(Mystery3.witnessLine3(sWit, "Randy") == null,
        "buried: Randy is nobody's witness in his own case")
    sWit.arc3Chapter = 3
    check(Mystery3.witnessLine3(sWit, "Sharon")?.speaker == "Sharon" &&
        "sharon_suspicion" in sWit.mystery3Clues,
        "buried: at the oak lot, Sharon says the quiet part")

    // ---------- clues: look & paper ----------
    val sLook3 = eng3.newState()
    sLook3.arcRetired = true; sLook3.arc2Retired = true
    check(Mystery3.lookClueText3(sLook3, "TegridyFarms") == null,
        "buried: no finds before the first trench opens")
    sLook3.arc3Started = true; sLook3.arc3Chapter = 1
    check(Mystery3.lookClueText3(sLook3, "TegridyFarms") != null &&
        "bead_strand" in sLook3.mystery3Clues,
        "buried: the farm's first Look turns up the bead strand")
    check(Mystery3.lookClueText3(sLook3, "TegridyFarms") == null,
        "buried: the farm holds nothing more until the deep corner opens")
    check(Mystery3.lookClueText3(sLook3, "CityHall") == null,
        "buried: the purchase file means nothing before the layers chapter")
    sLook3.arc3Chapter = 2
    check(Mystery3.lookClueText3(sLook3, "StarksPond") != null &&
        "waterbed_key" in sLook3.mystery3Clues,
        "buried: the bank's first Look finds the waterbed key")
    check(Mystery3.lookClueText3(sLook3, "StarksPond") != null &&
        "commune_newsletter" in sLook3.mystery3Clues,
        "buried: the bank's second Look reads the newsletter")
    check(Mystery3.lookClueText3(sLook3, "StarksPond") == null,
        "buried: the bank holds exactly two finds")
    check(Mystery3.lookClueText3(sLook3, "CityHall") != null &&
        "purchase_gap" in sLook3.mystery3Clues,
        "buried: the paper clue is a gap in the purchase file")
    sLook3.arc3Chapter = 3
    check(Mystery3.lookClueText3(sLook3, "Elementary") != null &&
        "photo_strip" in sLook3.mystery3Clues,
        "buried: the oak lot's first Look finds the photo strip")
    check(Mystery3.lookClueText3(sLook3, "Elementary") != null &&
        "seed_jar" in sLook3.mystery3Clues,
        "buried: the oak lot's second Look finds the seed jar")
    check(Mystery3.lookClueText3(sLook3, "Elementary") == null,
        "buried: the oak lot holds exactly two finds")
    sLook3.arc3Chapter = 4
    check(Mystery3.lookClueText3(sLook3, "TegridyFarms") != null &&
        "strongbox" in sLook3.mystery3Clues,
        "buried: at the last pit, the farm gives up the strongbox")
    check(Mystery3.lookClueText3(sLook3, "Bank") == null,
        "buried: the Bank holds no finds")

    // ---------- clues: participation ----------
    val sPart3 = eng3.newState()
    sPart3.arcRetired = true; sPart3.arc2Retired = true
    sPart3.arc3Started = true; sPart3.arc3Chapter = 1
    sPart3.shenaniganId = Mystery3.CHAPTERS3[0].id
    sPart3.shenaniganDay = sPart3.todayKey
    sPart3.timeMin = 60
    eng3.player(sPart3).location = "TegridyFarms"
    eng3.bumpParticipation(sPart3, "TegridyFarms")
    check(sPart3.participation == 1 && "dig_shift" in sPart3.mystery3Clues,
        "buried: working a sift shift at the first pit earns its find")
    val sPicnic = eng3.newState()
    sPicnic.arcRetired = true; sPicnic.arc2Retired = true
    sPicnic.arc3Started = true; sPicnic.arc3Chapter = 3
    sPicnic.shenaniganId = Mystery3.CHAPTERS3[2].id
    sPicnic.shenaniganDay = sPicnic.todayKey
    sPicnic.timeMin = 60
    eng3.player(sPicnic).location = "Elementary"
    eng3.bumpParticipation(sPicnic, "Elementary")
    check("fence_picnic" in sPicnic.mystery3Clues,
        "buried: eating at the fence line earns the picnic's find")
    val sFar3 = eng3.newState()
    sFar3.arc3Started = true; sFar3.arc3Chapter = 1
    sFar3.shenaniganId = Mystery3.CHAPTERS3[0].id; sFar3.timeMin = 60
    eng3.player(sFar3).location = "Mall"
    eng3.bumpParticipation(sFar3, "Mall")
    check(sFar3.participation == 0 && sFar3.mystery3Clues.isEmpty(),
        "buried: no finds away from a dig's turf")

    // ---------- the disposition gate ----------
    fun dispState(clues: Int): GameState {
        val s = eng3.newState()
        s.arcRetired = true; s.arc2Retired = true
        s.arc3Started = true; s.arc3Chapter = 4
        s.shenaniganId = Mystery3.FINALE3_ID
        s.shenaniganDay = s.todayKey
        for (c in Mystery3.CLUES3.take(clues)) s.mystery3Clues.add(c.id)
        return s
    }
    val finDef3 = Mystery3.CHAPTER3_BY_ID[Mystery3.FINALE3_ID]!!
    check(!Mystery3.dispositionDue(dispState(7).apply { timeMin = 13 * 60 }),
        "buried: seven clues is NOT enough to decide the box (below the gate)")
    val sDisp = dispState(8); sDisp.timeMin = 13 * 60
    check(Mystery3.dispositionDue(sDisp),
        "buried: eight clues opens the disposition (the boundary)")
    check(!Mystery3.dispositionDue(dispState(10).apply { timeMin = 600 }),
        "buried: the moment waits for the climax, not the morning")
    check(!Mystery3.dispositionDue(dispState(10).apply {
        timeMin = 13 * 60; shenaniganId = Mystery3.CHAPTERS3[0].id }),
        "buried: the moment belongs to the last pit alone")
    check(!Mystery3.chooseDisposition(sDisp, "keep"),
        "buried: only the three dispositions can be locked")
    check(Mystery3.chooseDisposition(sDisp, "bury") && sDisp.arc3Choice == "bury",
        "buried: a disposition can be locked at the gate")
    check(!Mystery3.dispositionDue(sDisp) &&
        !Mystery3.chooseDisposition(sDisp, "publish"),
        "buried: a locked disposition closes the moment")

    // ---------- the wrap: four landings ----------
    fun wrappedChapter3(clues: Int, choice: String): GameState {
        val s = dispState(clues)
        s.arc3Choice = choice
        Episodes.beginEvent(s, finDef3)
        s.lastEventWeek = 39
        s.timeMin = 1430
        eng3.advanceTime(s)
        return s
    }
    val sPubBase = dispState(10)
    sPubBase.arc3Choice = "publish"
    sPubBase.friendship["Randy"] = 20; sPubBase.friendship["Sharon"] = 20
    Episodes.beginEvent(sPubBase, finDef3)
    sPubBase.lastEventWeek = 39
    sPubBase.timeMin = 1430
    eng3.advanceTime(sPubBase)
    val sPub = sPubBase
    check(sPub.arc3Retired && sPub.arc3Branch == "publish",
        "buried: publishing retires the case in public")
    val epPub = sPub.episodes.lastOrNull { it.eventId == Mystery3.FINALE3_ID }
    check(epPub != null && epPub.finished &&
        epPub.recap.any { it.contains("THE VOTE") },
        "buried: the public ending's credits carry the meeting")
    check(sPub.lifeText["mark:TegridyFarms"]?.contains("EVERYBODY'S") == true,
        "buried: the public case leaves the stone by the gate")
    check(sPub.factionStates.getValue("tegridy_crew").influence ==
        baseInf3("tegridy_crew") - 4 &&
        sPub.factionStates.getValue("parents").influence ==
        baseInf3("parents") + 3,
        "buried: the public ripples (Tegridy -4 humbled, Parents +3)")
    check((sPub.friendship["Sharon"] ?: 0) == 22 &&
        (sPub.friendship["Randy"] ?: 0) == 18,
        "buried: the meeting warms Sharon to you (+2) and costs Randy a little (-2)")
    check(!sPub.arc3Favor && Mystery3.favorLine3(sPub, "Randy") == null,
        "buried: no favor stands in the public ending")
    check(Mystery3.statusStamp3(sPub).contains("SETTLED IN PUBLIC"),
        "buried: the board stamps the public close")

    val sBury = wrappedChapter3(8, "bury")
    check(sBury.arc3Retired && sBury.arc3Branch == "bury" && sBury.arc3Favor,
        "buried: burying it again retires the case — and opens the debt")
    check(sBury.episodes.last { it.eventId == Mystery3.FINALE3_ID }
        .recap.any { it.contains("THE FAVOR") },
        "buried: the quiet ending's credits name the favor")
    check(sBury.lifeText["mark:TegridyFarms"]?.contains("grass came back") == true,
        "buried: the quiet case's mark is the too-fast grass")
    check(Mystery3.favorLine3(sBury, "Randy")?.speaker == "Randy" &&
        Mystery3.favorLine3(sBury, "Sharon") == null &&
        Mystery3.favorLine3(sPub, "Randy") == null,
        "buried: the favor line lives in Randy's talks, in that ending only")
    val favA = Mystery3.favorLine3(sBury, "Randy")!!.text
    sBury.absDay += 1
    check(Mystery3.favorLine3(sBury, "Randy")!!.text != favA,
        "buried: the favor rotates by the day (a standing line, not a stuck one)")
    check(Mystery3.digTokensByLoc(sBury).isEmpty(),
        "buried: the quiet ending keeps no stone — nothing shows, by design")
    check(Mystery3.boardLines3(sBury).any { it.contains("Randy owes you one") },
        "buried: the board records the debt")

    val sShar = wrappedChapter3(9, "sharon")
    check(sShar.arc3Retired && sShar.arc3Branch == "sharon" &&
        sShar.arc3SharonPending && sShar.arc3SharonText.isEmpty(),
        "buried: Sharon's ending closes the case with the decision still out")
    check(Mystery3.digTokensByLoc(sShar).isEmpty(),
        "buried: her stone isn't up yet — the decision hasn't landed")
    check(!Mystery3.noteSharonDecision(sShar),
        "buried: her decision is not instant")
    sShar.absDay += Mystery3.SHARON_DECISION_DELAY_DAYS
    check(Mystery3.noteSharonDecision(sShar) && !sShar.arc3SharonPending &&
        sShar.arc3SharonText.isNotEmpty(),
        "buried: a day later, her decision lands")
    check(sShar.lifeText["mark:TegridyFarms"]?.contains("FIRST FARMERS") == true &&
        Mystery3.digTokensByLoc(sShar) ==
            mapOf(Mystery3.MARKER_LOC to listOf(Mystery3.MARKER_TOKEN)),
        "buried: her landing sets the stone and rewrites the mark")
    check(sShar.events.any { it.contains("SHARON'S DECISION") } &&
        Mystery3.boardLines3(sShar).any { it.contains("SHARON'S DECISION") },
        "buried: the decision reaches the ticker and the board")
    check(!Mystery3.noteSharonDecision(sShar),
        "buried: her decision lands exactly once")

    // her call, colored by the Marshes' own storyline (v0.3.0c)
    fun sharonFlavor(outcomeId: String?): String {
        val s = eng3.newState()
        if (outcomeId != null) {
            s.storyArcs[Mystery3.MARSH_ARC_ID] = StoryArcState(
                arcId = Mystery3.MARSH_ARC_ID, done = true, outcomeId = outcomeId)
        }
        return Mystery3.sharonDecisionText(s)
    }
    check(sharonFlavor(Mystery3.MARSH_ARC_WARM).contains("the man I keep"),
        "buried: a warm Marsh ending — she decides WITH him, and says why")
    check(sharonFlavor("randy_sharon_solo").contains("very helpful"),
        "buried: a solo Marsh ending — she decides alone, and he finds out")
    check(sharonFlavor(null).contains("defusing"),
        "buried: no Marsh ending yet — she decides like a woman defusing something")
    check(sharonFlavor(Mystery3.MARSH_ARC_WARM) != sharonFlavor("randy_sharon_solo") &&
        sharonFlavor("randy_sharon_solo") != sharonFlavor(null),
        "buried: the three flavors of her call are three different texts")

    val sCounty = wrappedChapter3(3, "")
    check(sCounty.arc3Retired && sCounty.arc3Branch == "county",
        "buried: no disposition, few clues — the county decides by default")
    check(sCounty.episodes.last { it.eventId == Mystery3.FINALE3_ID }
        .recap.any { it.contains("THE CATALOGUE") },
        "buried: the county ending's credits carry the catalogue")
    check(!sCounty.arc3Favor && !sCounty.arc3SharonPending,
        "buried: the county ending leaves no debt and no decision")
    val sRigged3 = wrappedChapter3(5, "publish")
    check(sRigged3.arc3Branch == "county",
        "buried: even the RIGHT call, locked without the case behind it, falls to the county")
    check(Mystery3.ambientCallback3(sPub, kotlin.random.Random(4)) != null &&
        Mystery3.ambientCallback3(sCounty, kotlin.random.Random(4)) != null &&
        Mystery3.ambientCallback3(eng3.newState(), kotlin.random.Random(4)) == null,
        "buried: every closed ending stays in the town's mouth; an open case doesn't")

    // ---------- the board ----------
    val sBoard3 = eng3.newState()
    sBoard3.arcRetired = true; sBoard3.arc2Retired = true
    sBoard3.arc3Started = true; sBoard3.arc3Chapter = 2; sBoard3.absDay = 30
    val board3 = Mystery3.boardLines3(sBoard3)
    check(board3.first().contains("What's Buried") &&
        board3.any { it.contains("🧩 CLUES — 0/12") } &&
        board3.any { it.contains("THE SITES") } &&
        board3.any { it.contains("The pond's far bank") } &&
        board3.any { it.contains("A commune, the old-timers say") },
        "buried: the board shows the case, its sites, its empty count, its theory")
    Mystery3.grantClue3(sBoard3, "bead_strand")
    check(Mystery3.boardLines3(sBoard3).any { it.contains("🧩 CLUES — 1/12") },
        "buried: the board counts what you've dug up")

    // ---------- engine: a full THREE-case lifetime ----------
    val sLife3 = eng3.newState()
    var sawChapters = mutableSetOf<String>()
    var slotViolation = false
    var arc2RetiredDaySeen = -1
    var arc3OpenedDay = -1
    var guard3 = 0
    while (guard3++ < 400 &&
        !(sLife3.arcRetired && sLife3.arc2Retired && sLife3.arc3Retired)) {
        eng3.onNewDay(sLife3)
        sLife3.shenaniganId?.let { if (Mystery3.isChapter3(it)) sawChapters += it }
        if ((sLife3.arc2Started && !sLife3.arcRetired) ||
            (sLife3.arc3Started && !sLife3.arc2Retired)) slotViolation = true
        if (sLife3.arc2Retired && arc2RetiredDaySeen < 0)
            arc2RetiredDaySeen = sLife3.arc2RetiredDay
        if (sLife3.arc3Started && arc3OpenedDay < 0) arc3OpenedDay = sLife3.absDay
    }
    check(sLife3.arcRetired && sLife3.arc2Retired && sLife3.arc3Retired,
        "buried: a full three-case lifetime plays out in sequence in $guard3 days")
    check(sawChapters.size == 4,
        "buried: all four chapters aired inside the lifetime")
    check(!slotViolation,
        "buried: no case ever opens while an earlier one is live (one slot, three cases)")
    check(arc3OpenedDay - arc2RetiredDaySeen in
        Mystery3.OPEN_DELAY_DAYS..(Mystery3.OPEN_DELAY_DAYS + 14),
        "buried: the dig opens about ten days after the booth case retires " +
            "(got ${arc3OpenedDay - arc2RetiredDaySeen})")
    check(sLife3.arc3Branch == "county",
        "buried: an unattended buried case goes to the county on its own")

    // ---------- persistence: mid-case saves & era saves ----------
    val docMid3 = mapOf<String, Any?>(
        "arc" to mapOf<String, Any?>("chapter" to 5L, "due" to 38L,
            "started" to true, "retired" to true,
            "branch" to "town", "choice" to ""),
        "arc2" to mapOf<String, Any?>("due" to 50L, "started" to true,
            "marathonDay" to 46L, "accuseDue" to 50L,
            "accusationAired" to true, "retired" to true,
            "branch" to "cold", "accused" to "", "usher" to "",
            "alibiDay" to -1L, "retiredDay" to 60L, "reelFound" to true,
            "declined" to true, "flavor" to emptyList<String>()),
        "arc3" to mapOf<String, Any?>("chapter" to 2L, "due" to 84L,
            "started" to true, "retired" to false,
            "branch" to "", "choice" to "",
            "retiredDay" to -1L, "favor" to false,
            "sharonPending" to false, "sharonDay" to -1L,
            "sharonText" to ""),
        "mystery3Clues" to listOf("bead_strand", "dig_hole_to_china"))
    val sMid3 = decodeGameState(docMid3)
    check(sMid3.arc3Started && sMid3.arc3Chapter == 2 &&
        sMid3.arc3DueAbsDay == 84 && sMid3.arc2RetiredDay == 60,
        "buried: a mid-case save restores the dig's clocks")
    check(sMid3.mystery3Clues == setOf("bead_strand"),
        "buried: known finds restore; invented ids are dropped")
    sMid3.absDay = 84
    check(Mystery3.dueChapter3(sMid3)?.id == Mystery3.CHAPTERS3[2].id,
        "buried: a restored mid-case save airs its next chapter on time")
    val docTampered3 = mapOf<String, Any?>("arc3" to mapOf<String, Any?>(
        "branch" to "banana", "choice" to "keep", "chapter" to 99L))
    val sTampered3 = decodeGameState(docTampered3)
    check(sTampered3.arc3Branch == "" && sTampered3.arc3Choice == "" &&
        sTampered3.arc3Chapter == Mystery3.CHAPTERS3.size,
        "buried: invented branch/disposition values are neutralized, chapters clamp")
    val sEra3 = decodeGameState(emptyMap())
    check(!sEra3.arc3Started && sEra3.arc3DueAbsDay == -1 &&
        sEra3.mystery3Clues.isEmpty() && !Mystery3.boardVisible3(sEra3),
        "buried: an era save (no arc3 keys) has no third case yet")
    val sBack3 = decodeGameState(encodeGameState(sBury))
    check(sBack3.arc3Retired && sBack3.arc3Branch == "bury" && sBack3.arc3Favor &&
        sBack3.mystery3Clues == sBury.mystery3Clues,
        "buried: a closed case (and its standing favor) round-trips the real save path")

    // ---------- spoiler hygiene: the changelog keeps the secret ----------
    val readme3 = File(root, "docs/CHANGELOG.md").readText()
    val f3Section = readme3.substringAfter("### v0.4.0f")
        .substringBefore("### v0.4.0e")
    check(f3Section.contains("What's Buried"),
        "buried: the v0.4.0f changelog section exists")
    for (tell in listOf("deed", "communal", "dissolv", "community trust",
        "owes you", "redact", "lease", "charter")) {
        check(!f3Section.contains(tell, ignoreCase = true),
            "buried: the changelog never prints the case's tell ('$tell')")
    }

    // ---------- wiring ----------
    val mystery3Src = File(root, "src/com/hunt3r/southparktown/Mystery3.kt").readText()
    val gameActivitySrc3 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc3 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val engineSrc3 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val prefsSrc3 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc3 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    val townLifeSrc3 = File(root, "src/com/hunt3r/southparktown/TownLife.kt").readText()
    check(!mystery3Src.contains("import android"),
        "buried: Mystery3.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc3.contains("Mystery3.dueChapter3") &&
        engineSrc3.contains("Mystery3.resolveDisposition") &&
        engineSrc3.contains("Mystery3.noteParticipation3") &&
        engineSrc3.contains("Mystery3.noteSharonDecision") &&
        engineSrc3.contains("Mystery3.ambientCallback3"),
        "buried: the engine airs the chapters, resolves the disposition, " +
            "feeds participation, lands Sharon's call, keeps the callbacks")
    val talkGateSrc3 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(talkGateSrc3.contains("Mystery3.witnessLine3") &&
        talkGateSrc3.contains("Mystery3.favorLine3") &&
        gameActivitySrc3.contains("Mystery3.lookClueText3") &&
        gameActivitySrc3.contains("Mystery3.chooseDisposition") &&
        gameActivitySrc3.contains("maybeShowDisposition") &&
        gameActivitySrc3.contains("Mystery3.digTokensByLoc"),
        "buried: GameActivity wires witnesses, looks, the disposition, " +
            "the favor line and the dig-token bridge")
    check(journalSrc3.contains("Mystery3.boardLines3"),
        "buried: the Journal renders the third case's board")
    check(prefsSrc3.contains("\"arc3\" to mapOf") &&
        prefsSrc3.contains("\"mystery3Clues\" to"),
        "buried: the save doc carries the third case additively")
    check(shenanigansSrc3.contains("Mystery3.CHAPTERS3"),
        "buried: the chapter defs join SHENANIGAN_BY_ID only")
    check(townLifeSrc3.contains("var digTokens"),
        "buried: TownInfo carries the live dig tokens into the renderers")
    check(sceneSrc3.contains("drawDigDetails") &&
        sceneSrc3.contains("TownInfo.digTokens"),
        "buried: SceneArt draws the dig layer from the bridged tokens")
}

/** v0.4.0g section: polish & performance pass #4 — Queue #4's
 *  audit. No new features: the lifetime soak grows Queue #4's
 *  surfaces (in sectionV030g), the veteran is re-measured
 *  against the full modern state, the newest screens and the
 *  group-photo geometry get measured fit QA, the Talk rail's
 *  stacked order is pinned under fabricated contention, and
 *  the peak budget is re-verified at a third distance. */
private fun sectionV040g(root: String) {
println("== v0.4.0g: polish #4 — rail order, bark caps, photo geometry, veteran III ==")
run {
    val engR = Engine(31)
    fun railState(year: Int, day: Int): GameState {
        val s = engR.newState()
        engR.createPlayer(s, "Rail", DEFAULT_APPEARANCE)
        s.gameYear = year; s.gameMonth = 12; s.gameDay = day
        s.todayKey = "%04d%02d%02d".format(year, 12, day)
        s.holidayId = "christmas"
        s.timeMin = 720
        return s
    }

    // ---------- the rail, under fabricated contention ----------
    // Kenny, armed with EVERYTHING at once: an accepted
    // DELIVER errand addressed to him, the Christmas relay's
    // current step (a Talk with Kenny), a fresh direct ask
    // the seeded probe is willing to make, the pond case's
    // witness telling (chapter aired, clue ungranted) — and
    // a bark on cooldown, which is garnish and must not move
    // any of it. The gate peels the stack one rail at a time.
    var railS: GameState? = null
    var year = 2026
    while (railS == null && year <= 2060) {
        for (day in 20..26) {
            val s = railState(year, day)
            val g = NpcGoals.record(s, "Kenny")
            s.npcGoals["Kenny"] = g.copy(kind = "ERRAND")
            if (Errands.askFor(s, "Kenny") != null) { railS = s; break }
        }
        year++
    }
    check(railS != null,
        "rail: a December day exists where Kenny's ask probe passes")
    val rs = railS!!
    // arm the beat: Cartman's step lands, Kenny's is current
    check(HolidayBeats.judgeTalk(rs, "Cartman") != null &&
        HolidayBeats.talkStepFor(rs, "Kenny") != null,
        "rail: the relay's current step waits on Kenny")
    // arm the witness: the pond case is two chapters in
    rs.arcStarted = true; rs.arcChapter = 2
    check(Mystery.clueAvailable(rs,
            Mystery.CLUES.first { it.id == "kenny_sighting" }) &&
        "kenny_sighting" !in rs.mysteryClues,
        "rail: Kenny's witness telling is live (chapter aired, ungranted)")
    // arm the delivery: Stan's parcel, addressed to Kenny
    val railDelivery = Errand("rail-deliver", Errands.BOARD, "Stan",
        "DELIVER", "Take this to Kenny.", "He's around.",
        targetName = "Kenny", dayKey = rs.todayKey)
    check(Errands.accept(rs, railDelivery),
        "rail: the delivery sits on the plate")
    // a bark cooling down changes nothing (and TalkGate
    // structurally cannot see bark state at all)
    val barkCd = mapOf("Kenny" to (rs.absDay * 1440 + rs.timeMin - 5))
    check(!Barks.cooledDown(barkCd["Kenny"], rs.absDay * 1440 + rs.timeMin),
        "rail: Kenny's bark is mid-cooldown during the contention")
    val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(!tgSrc.contains("Barks."),
        "rail: TalkGate never calls the bark engine — garnish is not a rail")
    check(HolidayBeats.talkStepFor(rs, "Kenny") != null &&
        Errands.askFor(rs, "Kenny") != null,
        "rail: beat step and ask are BOTH armed under the delivery")
    val gate1 = TalkGate.gateFor(rs, "Kenny", "MainStreet")
    check(gate1.rail == TalkGate.Rail.DELIVER &&
        gate1.delivery?.id == "rail-deliver",
        "rail: a delivery settles first — it masks the beat step (got ${gate1.rail})")
    check(Errands.deliverTo(rs, "Kenny") != null,
        "rail: the delivery settles through its judge")
    val gate2 = TalkGate.gateFor(rs, "Kenny", "MainStreet")
    check(gate2.rail == TalkGate.Rail.HOLIDAY_BEAT,
        "rail: with the parcel gone, the today-only beat step is next (got ${gate2.rail})")
    check(HolidayBeats.judgeTalk(rs, "Kenny") != null &&
        HolidayBeats.talkStepFor(rs, "Kenny") == null,
        "rail: the beat step lands through its judge")
    val gate3 = TalkGate.gateFor(rs, "Kenny", "MainStreet")
    check(gate3.rail == TalkGate.Rail.ERRAND_ASK && gate3.ask != null &&
        gate3.ask!!.asker == "Kenny",
        "rail: with the beat played, the fresh ask surfaces (got ${gate3.rail})")
    Errands.markAsked(rs, "Kenny")
    val gate4 = TalkGate.gateFor(rs, "Kenny", "MainStreet")
    check(gate4.rail == TalkGate.Rail.DIALOGUE,
        "rail: with the ask offered, the Talk is an ordinary conversation")
    val owed = TalkGate.owedLines(rs, "Kenny")
    check(owed.isNotEmpty() && owed[0].speaker == "Kenny" &&
        "kenny_sighting" in rs.mysteryClues,
        "rail: inside the conversation, the witness telling plays first " +
            "and grants its clue (got ${owed.size} owed lines)")
    check(TalkGate.owedLines(rs, "Kenny").none {
            it.text == owed[0].text },
        "rail: the telling is spent — it never plays twice")

    // ---------- owed lines: witness before story ----------
    // Wendy holds the pond case's chapter-2 witness telling
    // AND the first arc's current-stage beat at once; the
    // stack plays the case before the heart.
    val sW = engR.newState()
    engR.createPlayer(sW, "Rail", DEFAULT_APPEARANCE)
    sW.absDay = 2
    StoryArcs.dailyTick(sW)
    val swDef = StoryArcs.activeDef(sW)
    check(swDef?.id == "stan_wendy_note",
        "rail: the note arc is the active story (got ${swDef?.id})")
    sW.arcStarted = true; sW.arcChapter = 3
    val wendyLines = TalkGate.owedLines(sW, "Wendy")
    val wendyStageLine = swDef!!.stages[0].talkLines["Wendy"]
    check(wendyLines.size >= 2 &&
        "wendy_pattern" in sW.mysteryClues &&
        wendyLines[1].text == wendyStageLine,
        "rail: Wendy's witness telling plays ahead of her arc beat " +
            "(got ${wendyLines.size} lines)")
    // the thank-you rides last of the owed stack
    sW.lifeText["errandThanks:Wendy"] = "You are a lifesaver. Truly."
    val owedW = TalkGate.owedLines(sW, "Wendy")
    check(owedW.isNotEmpty() &&
        owedW.last().text == "You are a lifesaver. Truly." &&
        "errandThanks:Wendy" !in sW.lifeText,
        "rail: an errand thank-you plays once, at the stack's tail")

    // ---------- Barks.decide: the shipped decision, unit-pinned ----------
    val room2 = listOf("Kenny" to 50, "Craig" to 0)
    check(Barks.decide(false, 720, true, room2, emptySet(), emptyMap(), 5000, 0.0, 0.0) == null,
        "decide: the Settings toggle closes the gate")
    check(Barks.decide(true, 23 * 60, true, room2, emptySet(), emptyMap(), 5000, 0.0, 0.0) == null,
        "decide: quiet hours close the gate")
    check(Barks.decide(true, 720, false, room2, emptySet(), emptyMap(), 5000, 0.0, 0.0) == null,
        "decide: lingering with no arrival offers nobody")
    check(Barks.decide(true, 720, false, room2, setOf("Craig"), emptyMap(), 5000, 0.99, 0.0) == null,
        "decide: a failed arrival roll offers nobody")
    check(Barks.decide(true, 720, false, room2, setOf("Craig"), emptyMap(), 5000, 0.10, 0.0) == "Craig",
        "decide: a passed arrival roll offers the newcomer, not the room")
    check(Barks.decide(true, 720, true, listOf("Kenny" to 50),
            emptySet(), mapOf("Kenny" to 4995), 5000, 0.0, 0.5) == null,
        "decide: the cooldown vetoes the pick — no re-roll to a second choice")
    check(Barks.decide(true, 720, true, listOf("Kenny" to 50),
            emptySet(), mapOf("Kenny" to 4980), 5000, 0.0, 0.5) == "Kenny",
        "decide: exactly at the cooldown's edge, the voice is back")

    // ---------- the blast: cap math under a dense entry stream ----------
    // Everyone present, a re-entry every five game-minutes
    // for three straight days: the cooldown and the quiet
    // hours are the only brakes, and both must hold exactly.
    val blastRnd = kotlin.random.Random(99)
    val blastCd = mutableMapOf<String, Int>()
    val blastFires = mutableListOf<Pair<String, Int>>()
    val everyone = CharacterSystem.CAST.keys.map { it to 30 }
    var blastAttempts = 0
    for (absMin in 0 until 3 * 1440 step 5) {
        blastAttempts++
        val pick = Barks.decide(true, absMin % 1440, true, everyone,
            emptySet(), blastCd, absMin,
            blastRnd.nextDouble(), blastRnd.nextDouble())
        if (pick != null) {
            blastCd[pick] = absMin
            blastFires.add(pick to absMin)
        }
    }
    val openAttempts = (0 until 3 * 1440 step 5)
        .count { !Barks.inQuietHours(it % 1440) }
    println("blast: ${blastFires.size} barks from $blastAttempts entries " +
        "($openAttempts outside quiet hours)")
    check(blastFires.size in 300..openAttempts,
        "blast: fires stay under the open-entry count — no runaway (got ${blastFires.size})")
    check(blastFires.none { Barks.inQuietHours(it.second % 1440) },
        "blast: quiet hours are absolute, even mid-stream")
    check(blastFires.groupBy { it.first }.values.all { fires ->
            fires.map { it.second }.sorted().zipWithNext()
                .all { (a, b) -> b - a >= Barks.COOLDOWN_MINUTES }
        },
        "blast: no NPC barked inside their cooldown, three dense days")
    check(blastFires.groupBy { it.first }.values
            .all { it.size <= (3 * 960) / Barks.COOLDOWN_MINUTES + 1 },
        "blast: per-NPC counts respect the cooldown's arithmetic cap")
    check(blastFires.map { it.first }.toSet().size >= 30,
        "blast: the weighted pick still roams the room (got " +
            "${blastFires.map { it.first }.toSet().size} distinct barkers)")
}
run {
    // ---------- group-photo geometry, measured ----------
    // The v0.4.0c layouts were paper-tuned inside PhotoView;
    // they live in Photos.GroupGeom now, and this is the
    // measuring. Every reachable frame (duos, trios, the
    // core four, adult trios, back-to-back pairs in both
    // rows) x every aspect the album and the viewer can
    // produce — the polaroid's photo rect runs from tall
    // (0.5) to the album card's wide (2.4) and beyond.
    val G = Photos.GroupGeom
    fun figOf(name: String, backToBack: Boolean = false): Photos.GroupGeom.Fig =
        Photos.GroupGeom.Fig(KidArt.heightFor(name),
            Photos.halfWidthFrac(KidArt.SHEETS[name]!!), backToBack)
    val playerFig = Photos.GroupGeom.Fig(1f,
        Photos.halfWidthFrac(avatarSpec(DEFAULT_APPEARANCE)))
    val aspects = listOf(0.5f, 0.75f, 1.0f, 1.5f, 2.0f, 2.4f, 3.0f)
    data class Frame(val comp: String, val figs: List<Photos.GroupGeom.Fig>, val label: String)
    val frames = listOf(
        Frame(Photos.COMP_LINEUP,
            listOf(figOf("Cartman"), playerFig), "duo, widest kid first"),
        Frame(Photos.COMP_LINEUP,
            listOf(playerFig, figOf("Cartman")), "duo, player first"),
        Frame(Photos.COMP_LINEUP,
            listOf(figOf("Stan"), playerFig, figOf("Kyle")), "trio lineup"),
        Frame(Photos.COMP_LINEUP,
            listOf(figOf("Stan"), figOf("Kyle"), playerFig,
                figOf("Cartman"), figOf("Kenny")), "the core four + you"),
        Frame(Photos.COMP_SQUAD,
            listOf(figOf("Craig", true), figOf("Tweek", true),
                playerFig, figOf("Clyde")), "squad, rivals in back"),
        Frame(Photos.COMP_SQUAD,
            listOf(figOf("Stan"), playerFig,
                figOf("Cartman", true), figOf("Kyle", true)),
            "squad, rivals up front"),
        Frame(Photos.COMP_SQUAD,
            listOf(figOf("Randy"), figOf("Sharon"),
                playerFig, figOf("Gerald")), "squad, adult trio"),
        Frame(Photos.COMP_STACKED,
            listOf(figOf("Craig"), figOf("Tweek"), playerFig,
                figOf("Clyde")), "stacked, the pile"),
        Frame(Photos.COMP_STACKED,
            listOf(playerFig, figOf("Clyde"),
                figOf("Cartman", true), figOf("Kyle", true)),
            "stacked, rivals in the back row"))
    val measuredFrames = frames
    var worstHeadTop = Float.MAX_VALUE
    var worstFeet = 0f
    for (f in measuredFrames) {
        for (a in aspects) {
            val placed = G.layout(f.comp, f.figs, a)
            check(placed.size == f.figs.size &&
                placed.map { it.index }.toSet() == f.figs.indices.toSet(),
                "geom: ${f.label} @ $a places every figure exactly once")
            for (p in placed) {
                val fig = f.figs[p.index]
                val effH = p.h * fig.scale
                val headTop = p.feet - effH * G.INK_OVERHEAD
                if (headTop < worstHeadTop) worstHeadTop = headTop
                if (p.feet > worstFeet) worstFeet = p.feet
                check(headTop >= G.HEAD_MARGIN - 0.0015f,
                    "geom: ${f.label} @ $a — head ${p.index} stays inside " +
                        "the frame (top $headTop)")
                check(p.feet <= G.GROUND + 0.0001f,
                    "geom: ${f.label} @ $a — feet ${p.index} never sink " +
                        "toward the chin stamp (feet ${p.feet})")
                check(p.cx in 0f..1f,
                    "geom: ${f.label} @ $a — center ${p.index} in frame")
            }
            // draw order: the back row paints first
            if (f.comp != Photos.COMP_LINEUP && f.figs.size >= 4) {
                val backIdx = if (f.comp == Photos.COMP_SQUAD)
                    setOf(0, 1) else setOf(2, 3)
                check(placed.take(2).map { it.index }.toSet() == backIdx,
                    "geom: ${f.label} @ $a — the back row draws first")
                val back = placed.filter { it.index in backIdx }
                val front = placed.filter { it.index !in backIdx }
                check(back.all { it.feet < front.maxOf { p2 -> p2.feet } },
                    "geom: ${f.label} @ $a — the back row stands higher")
            }
        }
    }
    println("geom: worst head top across frames x aspects = $worstHeadTop, " +
        "lowest feet = $worstFeet (ground ${G.GROUND})")
    check(worstHeadTop >= 0f,
        "geom: no head crosses the frame's top edge anywhere")
    // STACKED's back row, named on its own (the audit's
    // headline): at the album's wide aspect the paper cap
    // alone put back-row heads at the frame's edge — the
    // headroom cap is what keeps them in.
    val stackedBack = G.layout(Photos.COMP_STACKED,
        listOf(figOf("Craig"), figOf("Tweek"), playerFig, figOf("Clyde")), 2.4f)
        .filter { it.index >= 2 }
    check(stackedBack.all { it.feet == G.GROUND - G.STACKED_LIFT },
        "geom: the pile's back row stands on its lift")
    check(stackedBack.all {
            it.feet - it.h * G.INK_OVERHEAD >= G.HEAD_MARGIN - 0.0015f },
        "geom: STACKED back-row heads are inside the frame at album aspect")
    val stackedNoCap = minOf(G.STACKED_BACK_MAX_H,
        (1f - 2 * G.STACKED_INSET) / 2 * G.SLOT_H_FACTOR * 2.4f)
    check(G.GROUND - G.STACKED_LIFT - stackedNoCap * 1.05f < 0f,
        "geom: (control) the pre-audit caps alone WOULD clip at 2.4 — " +
            "the headroom cap is load-bearing")
    // SQUAD's inset, named on its own: the back row's span
    // is a strict inset of the front row's, and its feet
    // ride the lift, clear of the ground line the front
    // row stands on — nothing in the back row reaches
    // down toward the chin.
    val squad = G.layout(Photos.COMP_SQUAD,
        listOf(figOf("Randy"), figOf("Sharon"), playerFig, figOf("Gerald")), 1.0f)
    val squadBack = squad.filter { it.index < 2 }
    val squadFront = squad.filter { it.index >= 2 }
    check(squadBack.all { it.cx in G.SQUAD_INSET..(1f - G.SQUAD_INSET) } &&
        squadFront.all { it.cx in G.EDGE..(1f - G.EDGE) } &&
        squadBack.minOf { it.cx } > squadFront.minOf { it.cx } &&
        squadBack.maxOf { it.cx } < squadFront.maxOf { it.cx },
        "geom: SQUAD's back row is a strict inset of the front row")
    check(squadBack.all { it.feet == G.GROUND - G.SQUAD_LIFT } &&
        squadFront.all { it.feet == G.GROUND },
        "geom: SQUAD's rows stand on their own lines (lift / ground)")
    // back-to-back mirrors, named on their own: mirroring
    // is around the figure's own center, so the posed
    // layout is the unposed layout, point for point — a
    // mirror can never throw a figure out of its slot.
    for (comp in listOf(Photos.COMP_SQUAD, Photos.COMP_STACKED)) {
        val posed = listOf(figOf("Stan"), playerFig,
            figOf("Cartman", true), figOf("Kyle", true))
        val plain = listOf(figOf("Stan"), playerFig,
            figOf("Cartman"), figOf("Kyle"))
        for (a in aspects) {
            val lp = G.layout(comp, posed, a)
            val lu = G.layout(comp, plain, a)
            check(lp.size == lu.size && lp.indices.all { i ->
                    lp[i].index == lu[i].index && lp[i].cx == lu[i].cx &&
                    lp[i].feet == lu[i].feet && lp[i].h == lu[i].h },
                "geom: $comp @ $a — the back-to-back pose moves nobody")
            val flipped = lp.filter { it.flipped }
            check(flipped.size == 1 && flipped[0].index == 2,
                "geom: $comp @ $a — exactly the pair's first half mirrors")
            val p = flipped[0]
            val fig = posed[p.index]
            val halfWx = fig.halfWFrac * p.h * fig.scale / a
            check(p.cx - halfWx >= -0.03f && p.cx + halfWx <= 1.03f,
                "geom: $comp @ $a — the mirrored figure's ink stays at " +
                    "the frame (box ${p.cx - halfWx}..${p.cx + halfWx})")
        }
    }
    // the extent data itself: nobody's ink is wider than
    // the geometry the invariants assume
    val worstHalf = CharacterSystem.CAST.keys
        .maxOf { Photos.halfWidthFrac(KidArt.SHEETS[it]!!) }
    println("geom: widest ink half-width fraction = $worstHalf")
    check(worstHalf in 0.25f..0.55f,
        "geom: cast ink half-widths sit in the audited band (got $worstHalf)")
    check(G.layout(Photos.COMP_LINEUP, emptyList(), 1.0f).isEmpty() &&
        G.layout("bogus", listOf(playerFig), 1.0f).size == 1,
        "geom: empty frames lay out empty; unknown compositions line up")
    // wiring: PhotoView paints GroupGeom's placements and
    // nothing else for group records
    val pvSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
    check(pvSrc.contains("Photos.GroupGeom.layout") &&
        pvSrc.contains("Photos.halfWidthFrac"),
        "geom wiring: PhotoView draws the measured layout")
}
