/** The v0.2.0f season-mystery block, extracted from main()
 *  in v0.4.0g: main had reached the JVM 64KB method limit. */
private fun sectionMainMystery(root: String) {
// ================= v0.2.0f: the season mystery =================
// "The Lights Over Stark's Pond" — five chapters on a weekly
// cadence through the Shenanigans/Episodes machinery, a
// twelve-clue case gathered three ways, a finale whose branch
// is gated on the clues, and a retirement that never re-runs.
run {
    val engM = Engine()
    fun baseInf(id: String) = FACTIONS.first { it.id == id }.baseInfluence

    // ---------- def integrity ----------
    check(Mystery.ARC_CHAPTERS.size == 5, "mystery: five chapters")
    check(Mystery.ARC_CHAPTERS.map { it.id }.distinct().size == 5,
        "mystery: chapter ids are unique")
    check(Mystery.ARC_CHAPTERS.last().id == Mystery.FINALE_ID,
        "mystery: chapter 5 IS the finale")
    val regularIds = SHENANIGANS.map { it.id }.toSet()
    for (def in Mystery.ARC_CHAPTERS) {
        check(def.stages.size == 4 && def.causers.isNotEmpty() &&
            def.episodeTitles.size == 2 && def.coldOpen.isNotEmpty() &&
            def.theme.header.isNotBlank(),
            "mystery: ${def.id} carries the full episode kit " +
                "(4 stages, causers, 2 titles, cold open)")
        check(def.id !in regularIds && SHENANIGAN_BY_ID[def.id] == def,
            "mystery: ${def.id} is not in the random pool but resolves by id")
        check(def.stages.all { it.clusterLoc == null || it.clusterLoc in LOCATIONS },
            "mystery: ${def.id}'s clusters are real places")
    }
    check(SHENANIGANS.size == 10, "mystery: the random pool is still the ten")
    val finDef = SHENANIGAN_BY_ID[Mystery.FINALE_ID]!!
    check(finDef.stages[2].clusterLoc == "StarksPond",
        "mystery: the finale's climax is at the pond (where its mark lands)")
    check(Episodes.titleFor(finDef, 0, 0).first == finDef.title,
        "mystery: chapters title like any episode")

    // ---------- the clue registry ----------
    check(Mystery.CLUES.size == 12, "mystery: twelve clues on the board")
    check(Mystery.CLUES.map { it.id }.distinct().size == 12 &&
        Mystery.CLUES.all { it.id in Mystery.CLUE_IDS },
        "mystery: clue ids are unique")
    check(Mystery.CLUES.count { it.kind == Mystery.ClueKind.WITNESS } == 5 &&
        Mystery.CLUES.count { it.kind == Mystery.ClueKind.LOOK } == 5 &&
        Mystery.CLUES.count { it.kind == Mystery.ClueKind.PARTICIPATION } == 2,
        "mystery: clues split 5 witnesses / 5 looks / 2 participations")
    for (clue in Mystery.CLUES) {
        check(clue.minChapter in 0..3 && clue.detail.isNotBlank(),
            "mystery: ${clue.id} is staged across the arc with flavor")
        when (clue.kind) {
            Mystery.ClueKind.WITNESS -> check(
                clue.npc != null && clue.npc in AGENT_PROFILES &&
                    !clue.spoken.isNullOrBlank(),
                "mystery: ${clue.id}'s witness is a real cast member who speaks")
            Mystery.ClueKind.LOOK -> check(
                clue.locId != null && clue.locId in LOCATIONS &&
                    !clue.foundText.isNullOrBlank(),
                "mystery: ${clue.id} is hidden at a real location")
            Mystery.ClueKind.PARTICIPATION -> check(
                clue.chapterDefId != null && clue.chapterDefId in
                    Mystery.ARC_CHAPTERS.map { it.id },
                "mystery: ${clue.id} is earned inside a real chapter")
        }
    }
    check(Mystery.TRUTH_MIN_CLUES in 1 until Mystery.CLUES.size,
        "mystery: the truth gate sits inside the clue count")

    // ---------- scheduling: due-day math ----------
    val sSched = engM.newState()
    check(Mystery.dueChapter(sSched) == null && sSched.arcDueAbsDay == 3,
        "mystery: day 0 schedules chapter 1 for day 3, it does not fire")
    check(Mystery.dueChapter(sSched) == null,
        "mystery: the schedule is stable until the day comes")
    sSched.absDay = 3
    check(Mystery.dueChapter(sSched)?.id == "arc_ch1_lights",
        "mystery: chapter 1 is due on its day")
    sSched.holidayId = "halloween"
    check(Mystery.dueChapter(sSched) == null,
        "mystery: a due chapter defers for a holiday episode")
    sSched.holidayId = null
    check(Mystery.dueChapter(sSched)?.id == "arc_ch1_lights",
        "mystery: ...and is due again the moment the holiday clears")
    Mystery.noteChapterStarted(sSched, Mystery.ARC_CHAPTERS[0])
    check(sSched.arcStarted && sSched.arcChapter == 1 && sSched.arcDueAbsDay == 10,
        "mystery: starting chapter 1 books chapter 2 exactly a week out")
    sSched.absDay = 9
    check(Mystery.dueChapter(sSched) == null, "mystery: chapter 2 is never early")
    sSched.absDay = 10
    check(Mystery.dueChapter(sSched)?.id == "arc_ch2_vanishing",
        "mystery: chapter 2 lands on its due day")
    val sAired = engM.newState(); sAired.arcChapter = 5; sAired.absDay = 99
    check(Mystery.dueChapter(sAired) == null,
        "mystery: once every chapter has aired, nothing is due")
    check(!Mystery.boardVisible(engM.newState()),
        "mystery: no board before the case exists")

    // ---------- engine: the chapter takes the slot ----------
    val sArc = engM.newState()
    var guardA = 0
    while (!sArc.arcStarted && guardA++ < 10) engM.onNewDay(sArc)
    check(sArc.arcStarted && sArc.shenaniganId == "arc_ch1_lights",
        "mystery: chapter 1 opens on its own and holds the event slot")
    check(sArc.episodes.any { it.kind == "event" &&
        it.eventId == "arc_ch1_lights" && !it.finished },
        "mystery: chapter 1 opened an episode record like any event")
    check(sArc.arcChapter == 1 && sArc.arcDueAbsDay == sArc.absDay + 7,
        "mystery: chapter 2 is booked a week past chapter 1's air day")
    check(sArc.events.any { it.contains("NEW CASE OPENS") },
        "mystery: the town ticker announces the case")
    check(Mystery.boardVisible(sArc) &&
        Mystery.boardLines(sArc).any { it.contains("Chapter 1") },
        "mystery: the clue board exists from chapter 1")
    check(Mystery.currentTheory(sArc).contains("begun a pamphlet"),
        "mystery: the town's first theory is the pamphlet's")

    // ---------- engine: holidays outrank chapters ----------
    val sHol = engM.newState()
    sHol.absDay = 20; sHol.gameDay = 24   // next midnight: Oct 25, Halloween
    engM.onNewDay(sHol)
    check(sHol.holidayId == "halloween" && !sHol.arcStarted &&
        sHol.shenaniganId != "arc_ch1_lights",
        "mystery: chapter 1 does not crash Halloween's opening")
    var guardH = 0
    while (sHol.holidayId != null && guardH++ < 10) engM.onNewDay(sHol)
    check(sHol.arcStarted &&
        sHol.episodes.any { it.eventId == "arc_ch1_lights" },
        "mystery: chapter 1 airs the day the holiday clears")

    // ---------- clues: witnesses ----------
    val sClue = engM.newState()
    check(Mystery.witnessLine(sClue, "Jimbo") == null,
        "mystery: witnesses stay quiet before the case opens")
    sClue.arcChapter = 1
    val jimboSays = Mystery.witnessLine(sClue, "Jimbo")
    check(jimboSays != null && jimboSays.speaker == "Jimbo" &&
        "lights_shopping" in sClue.mysteryClues,
        "mystery: Jimbo testifies once chapter 1 has begun")
    check(Mystery.witnessLine(sClue, "Jimbo") == null,
        "mystery: a witness tells it exactly once")
    check(sClue.events.any { it.contains("CLUE 1/12") },
        "mystery: a found clue hits the ticker")
    check(Mystery.witnessLine(sClue, "Kenny") == null,
        "mystery: Kenny's sighting belongs to chapter 2")
    sClue.arcChapter = 2
    check(Mystery.witnessLine(sClue, "Kenny")?.speaker == "Kenny",
        "mystery: Kenny talks once chapter 2 begins")
    check(Mystery.witnessLine(sClue, "Randy") == null,
        "mystery: Randy is nobody's witness")

    // ---------- clues: look ----------
    check(Mystery.lookClueText(sClue, "StarksPond") != null &&
        "foil_square" in sClue.mysteryClues,
        "mystery: the pond dock gives up its foil")
    check(Mystery.lookClueText(sClue, "StarksPond") == null,
        "mystery: physical evidence is found once")
    check(Mystery.lookClueText(sClue, "ButtersHouse") == null,
        "mystery: the driveway clue waits for chapter 4")
    check(Mystery.lookClueText(sClue, "Bank") == null,
        "mystery: the Bank holds no evidence")

    // ---------- clues: participation ----------
    val sPart = engM.newState()
    sPart.arcChapter = 1; sPart.arcStarted = true
    sPart.shenaniganId = "arc_ch1_lights"; sPart.shenaniganDay = sPart.todayKey
    sPart.timeMin = 60   // stage 0; chapter 1 gathers at the pond
    engM.player(sPart).location = "StarksPond"
    engM.bumpParticipation(sPart, "StarksPond")
    check(sPart.participation == 1 && "boot_prints" in sPart.mysteryClues,
        "mystery: helping at the pond turns up the boot prints")
    engM.bumpParticipation(sPart, "StarksPond")
    check(sPart.participation == 2 &&
        sPart.mysteryClues.count { it == "boot_prints" } == 1,
        "mystery: the prints get noted once, participation keeps counting")
    val sFar = engM.newState()
    sFar.arcChapter = 1; sFar.shenaniganId = "arc_ch1_lights"; sFar.timeMin = 60
    engM.player(sFar).location = "Mall"
    engM.bumpParticipation(sFar, "Mall")
    check(sFar.participation == 0 && sFar.mysteryClues.isEmpty(),
        "mystery: no clue away from the chapter's turf")

    // ---------- the finale gate ----------
    fun finaleState(clues: Int, choice: String = ""): GameState {
        val s = engM.newState()
        s.arcStarted = true
        s.arcChapter = Mystery.ARC_CHAPTERS.size
        s.shenaniganId = Mystery.FINALE_ID
        s.shenaniganDay = s.todayKey
        s.arcChoice = choice
        for (c in Mystery.CLUES.take(clues)) s.mysteryClues.add(c.id)
        return s
    }
    val sGate = finaleState(7); sGate.timeMin = 13 * 60
    check(!Mystery.finaleChoiceDue(finaleState(6).apply { timeMin = 13 * 60 }),
        "mystery: six clues is NOT enough to know (below the gate)")
    check(Mystery.finaleChoiceDue(sGate),
        "mystery: seven clues opens the choice (the boundary)")
    check(!Mystery.finaleChoiceDue(finaleState(9).apply { timeMin = 600 }),
        "mystery: the choice waits for the climax, not the morning")
    check(!Mystery.finaleChoiceDue(finaleState(9).apply {
        timeMin = 13 * 60; shenaniganId = "arc_ch4_photograph" }),
        "mystery: the choice belongs to the finale alone")
    check(Mystery.chooseFinale(sGate, true) && sGate.arcChoice == "truth",
        "mystery: the truth can be chosen at the gate")
    check(!Mystery.finaleChoiceDue(sGate),
        "mystery: a locked choice closes the table")
    check(!Mystery.chooseFinale(finaleState(3), true),
        "mystery: you cannot choose what you do not know")

    // ---------- the wrap: three endings ----------
    // Drive the midnight wrap the way the game does. The next
    // day's roll is pinned quiet (lastEventWeek = Oct 2's week
    // index 39; gameDay 2 can't force) so influence reads are
    // purely the branch ripples.
    fun wrappedFinale(clues: Int, choice: String): GameState {
        val s = finaleState(clues, choice)
        Episodes.beginEvent(s, finDef)
        s.lastEventWeek = 39
        s.timeMin = 1430
        engM.advanceTime(s)
        return s
    }
    val sTruth = wrappedFinale(9, "truth")
    check(sTruth.arcRetired && sTruth.arcBranch == "truth",
        "mystery: presenting the truth retires the case SOLVED")
    val epTruth = sTruth.episodes.lastOrNull { it.eventId == Mystery.FINALE_ID }
    check(epTruth != null && epTruth.finished &&
        epTruth.recap.any { it.contains("Professor Chaos") },
        "mystery: the truth ending's credits name Professor Chaos")
    check(sTruth.lifeText["mark:ButtersHouse"]?.contains("Fortress") == true,
        "mystery: the truth leaves the dismantled fort as its mark")
    check(sTruth.lifeText["mark:StarksPond"] != null,
        "mystery: the generic climax mark lands alongside it")
    check(sTruth.factionStates.getValue("boys_crew").influence == baseInf("boys_crew") + 4 &&
        sTruth.factionStates.getValue("church_faithful").influence == baseInf("church_faithful") - 4 &&
        sTruth.factionStates.getValue("parents").influence == baseInf("parents") + 3,
        "mystery: the truth ripples (Crew +4, Faithful -4, Parents +3)")
    val baseRel = engM.newState()
        .factionRelations[Factions.relationKey("boys_crew", "girls_circle")] ?: 0
    check(sTruth.factionRelations[Factions.relationKey("boys_crew", "girls_circle")] ==
        baseRel + 1,
        "mystery: Wendy's list earns the Crew a notch with the girls")
    check(sTruth.shenaniganId == null,
        "mystery: the event slot is empty the morning after the finale")
    check(Mystery.statusStamp(sTruth).contains("SOLVED"),
        "mystery: the board stamps SOLVED")

    val sSilent = wrappedFinale(8, "silent")
    check(sSilent.arcBranch == "silent" &&
        sSilent.lifeText["mark:CityHall"]?.contains("sorry") == true,
        "mystery: silence leaves the framed ban with its penciled apology")
    check(sSilent.episodes.last { it.eventId == Mystery.FINALE_ID }
        .recap.any { it.contains("THE SECRET") },
        "mystery: the silent credits admit what you did")
    check(Mystery.statusStamp(sSilent).contains("CLOSED"),
        "mystery: the silent board stamps CLOSED, not SOLVED")

    val sTown = wrappedFinale(3, "")
    check(sTown.arcBranch == "town" &&
        sTown.lifeText["mark:CityHall"]?.contains("POND ALIEN BAN") == true,
        "mystery: few clues -> the town writes its own (alien) ending")
    check(sTown.episodes.last { it.eventId == Mystery.FINALE_ID }
        .recap.any { it.contains("THE OFFICIAL STORY") },
        "mystery: the town ending's credits go with the official story")
    check(sTown.factionStates.getValue("church_faithful").influence ==
        baseInf("church_faithful") + 6,
        "mystery: the alien ending rallies the Faithful (+6)")
    check(Mystery.statusStamp(sTown).contains("official town history"),
        "mystery: the town board is a matter of record now")

    // a tampered truth choice without the clues degrades honestly
    val sRigged = wrappedFinale(2, "truth")
    check(sRigged.arcBranch == "town",
        "mystery: a truth claim without the clues falls apart at the wrap")

    // ---------- retirement: the arc never runs again ----------
    check(Mystery.dueChapter(sTruth) == null,
        "mystery: retired means never due")
    sTruth.absDay += 400
    check(Mystery.dueChapter(sTruth) == null,
        "mystery: still retired a year of game days later")
    check(Mystery.boardLines(sTruth).any { it.startsWith("🧩 CLUES") },
        "mystery: the closed board still shows its work")
    check(Mystery.ambientCallback(sTruth, kotlin.random.Random(1)) != null &&
        Mystery.ambientCallback(sTown, kotlin.random.Random(1)) != null,
        "mystery: the closed case lives on in ambient talk (both banks)")
    check(Mystery.ambientCallback(engM.newState(), kotlin.random.Random(1)) == null,
        "mystery: no callbacks before there is an ending to call back to")
    check(Mystery.witnessLine(sTruth, "Wendy") == null &&
        Mystery.lookClueText(sTruth, "Mall") == null,
        "mystery: a retired case stops handing out clues")

    // ---------- persistence: mid-arc saves & era saves ----------
    val docMid = mapOf<String, Any?>(
        "arc" to mapOf<String, Any?>("chapter" to 3L, "due" to 40L,
            "started" to true, "retired" to false,
            "branch" to "", "choice" to ""),
        "mysteryClues" to listOf("foil_square", "straw_trail", "bogus_id"))
    val sMid = decodeGameState(docMid)
    check(sMid.arcChapter == 3 && sMid.arcDueAbsDay == 40 && sMid.arcStarted &&
        !sMid.arcRetired,
        "mystery: a mid-arc save restores chapter, due day and flags")
    check(sMid.mysteryClues == setOf("foil_square", "straw_trail"),
        "mystery: known clues restore; invented ids are dropped")
    sMid.absDay = 40
    check(Mystery.dueChapter(sMid)?.id == "arc_ch4_photograph",
        "mystery: a restored mid-arc save airs its next chapter on time")
    val sEra = decodeGameState(emptyMap())
    check(sEra.arcChapter == 0 && sEra.arcDueAbsDay == -1 && !sEra.arcStarted &&
        !sEra.arcRetired && sEra.mysteryClues.isEmpty(),
        "mystery: an era save (no arc keys) starts the case fresh")
    val docClamp = mapOf<String, Any?>("arc" to mapOf<String, Any?>(
        "chapter" to 99L))
    check(decodeGameState(docClamp).arcChapter == Mystery.ARC_CHAPTERS.size,
        "mystery: a corrupt chapter count clamps to the arc's length")

    // ---------- wiring ----------
    val mysterySrc = File(root, "src/com/hunt3r/southparktown/Mystery.kt").readText()
    val gameActivitySrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val engineSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val prefsSrc = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    check(!mysterySrc.contains("import android"),
        "mystery: Mystery.kt stays pure Kotlin (JVM-testable)")
    val talkGateSrcM = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(talkGateSrcM.contains("Mystery.witnessLine") &&
        gameActivitySrc.contains("Mystery.lookClueText") &&
        gameActivitySrc.contains("Mystery.chooseFinale") &&
        gameActivitySrc.contains("maybeShowFinaleChoice") &&
        gameActivitySrc.contains("TalkGate.owedLines"),
        "mystery: GameActivity wires witnesses (via TalkGate), looks and the finale choice")
    check(journalSrc.contains("🔍 MYSTERY") &&
        journalSrc.contains("Mystery.boardLines"),
        "mystery: the Journal renders the clue board")
    check(engineSrc.contains("Mystery.dueChapter") &&
        engineSrc.contains("Mystery.resolveFinale") &&
        engineSrc.contains("Mystery.noteParticipation") &&
        engineSrc.contains("Mystery.ambientCallback"),
        "mystery: the engine airs chapters, resolves the finale, " +
            "feeds participation clues and ambient callbacks")
    check(prefsSrc.contains("\"mysteryClues\" to") &&
        prefsSrc.contains("\"arc\" to mapOf"),
        "mystery: the save doc carries the arc additively")
    check(shenanigansSrc.contains("Mystery.ARC_CHAPTERS"),
        "mystery: the chapter defs join SHENANIGAN_BY_ID only")
}
}
private fun sectionV050a(root: String) {
// ================= v0.5.0a: the Walk =================
// Queue #5 item 1 (opens the 0.5.0 series). Travel stops
// teleporting: destinations route leg by leg over the EXITS
// graph, each leg lands you IN the intermediate place for
// real, minutes are charged by true gx/gy distance and
// banked into the town's 15-minute ticks, first traversals
// teach shortcuts, pass-through stops may fire one road
// beat per trip, and the bus pass (Mall kiosk / Town
// Fixture perk) sells the old teleport back — priced, since
// v0.15.0c, at the route's minutes at bus speed
// (BusNetwork's derivation over this same graph). All
// rules are pure (Walk); this section drives them end
// to end.
println("== v0.5.0a: the Walk — the town becomes a place you cross ==")
// section-level helpers (the blocks below share them)
val eng = Engine(505)
fun freshState(): GameState {
    val s = eng.newState()
    eng.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
    return s
}
fun place(s: GameState, loc: String) {
    eng.player(s).location = loc
    s.walkDest = ""
}
/** Walk leg by leg until the player stands at [target]. */
fun walkAll(s: GameState, target: String, rnd: Random,
            advance: Boolean = true): List<LegOutcome> {
    val outs = mutableListOf<LegOutcome>()
    var guard = 0
    while (eng.player(s).location != target && guard++ < 16) {
        val o = Walk.walkTo(s, target, rnd, advance)
        outs += o
        if (!o.moved) break
    }
    return outs
}
run {
    // ---------- the dials ----------
    check(Walk.MINUTES_PER_UNIT == 0.6, "walk: 0.6 minutes per map unit")
    check(Walk.TICK_MINUTES == 15, "walk: the town clock ticks in 15s")
    check(Walk.SHORTCUT_SAVE_MINUTES == Walk.TICK_MINUTES,
        "walk: a learned cut-through saves a full tick on its leg")
    check(Walk.BUS_PASS_PRICE == 25, "walk: the pass costs 25 capsule coins")
    check(Walk.WALK_FEATS.map { it.at } == listOf(10, 50, 10) &&
        Walk.WALK_FEATS.map { it.kind } == listOf("trips", "trips", "shortcuts"),
        "walk: the feat chain is 10 trips / 50 trips / 10 shortcuts")
    check(Walk.SHORTCUT_CAP == EXITS.values.sumOf { it.size },
        "walk: the shortcut cap is exactly the directed edge count")

    // ---------- the graph: symmetric, connected, routable ----------
    for ((a, outs) in EXITS) for (b in outs)
        check(a in EXITS[b].orEmpty(), "walk graph: the edge $a->$b runs both ways")
    // an independent BFS distance, to cross-check Walk.route
    fun bfsDist(from: String, to: String): Int {
        if (from == to) return 0
        val dist = mutableMapOf(from to 0)
        val q = mutableListOf(from); var h = 0
        while (h < q.size) {
            val cur = q[h++]
            for (n in EXITS[cur].orEmpty()) if (n !in dist) {
                dist[n] = dist.getValue(cur) + 1
                if (n == to) return dist.getValue(n)
                q += n
            }
        }
        return -1
    }
    for (a in LOCATIONS.keys) for (b in LOCATIONS.keys) {
        val r = Walk.route(a, b)
        if (a == b) {
            check(r == listOf(a), "walk route: $a to itself is a stay")
            continue
        }
        check(r.isNotEmpty() && r.first() == a && r.last() == b,
            "walk route: $a->$b exists and ends where it should")
        check(r.size - 1 == bfsDist(a, b),
            "walk route: $a->$b is shortest (${r.size - 1} legs)")
        check(r.zipWithNext().all { (x, y) -> y in EXITS[x].orEmpty() },
            "walk route: $a->$b walks only real edges")
        check(Walk.route(a, b) == r,
            "walk route: $a->$b is deterministic — same trip, same streets")
    }
    check(Walk.route("KennysHouse", "StarksPond") == listOf(
        "KennysHouse", "ButtersHouse", "CartmanHouse", "BusStop",
        "MainStreet", "KidsPark", "StarksPond"),
        "walk route: the golden cross-town route, learned by heart")
    check(Walk.route("MainStreet", "YourHouse") == listOf(
        "MainStreet", "BusStop", "CartmanHouse", "StanHouse",
        "KyleHouse", "YourHouse"),
        "walk route: downtown to your door, the residential way")
    check(Walk.route("YourHouse", "TegridyFarms") == listOf(
        "YourHouse", "KyleHouse", "StanHouse", "CartmanHouse",
        "BusStop", "MainStreet", "TegridyFarms"),
        "walk route: your house to the farm crosses the whole town")

    // ---------- time math ----------
    check(Walk.legMinutesRaw("KennysHouse", "ButtersHouse") == 10,
        "walk time: 17 units of tracks = 10 min")
    check(Walk.legMinutesRaw("CartmanHouse", "StanHouse") == 8,
        "walk time: a 13-unit block = 8 min")
    check(Walk.legMinutesRaw("MainStreet", "TegridyFarms") == 33,
        "walk time: the longest edge in town = 33 min")
    check(Walk.legMinutesRaw("BusStop", "MainStreet") == 23,
        "walk time: the bus stop to downtown = 23 min")
    run {
        val s = freshState()
        check(Walk.routeMinutes(s, "KennysHouse", "StarksPond") == 87,
            "walk time: the whole cross-town walk is 87 honest minutes")
        // banking: two 8-minute hops ≈ one tick between them
        check(Walk.applyMinutes(s, 8) == 0 && s.walkCarryMin == 8,
            "walk time: 8 minutes bank, no tick yet")
        val before = s.timeMin
        check(Walk.applyMinutes(s, 8) == 1 && s.walkCarryMin == 1 &&
            s.timeMin == (before + 15) % 1440,
            "walk time: the second hop tips the bank into one tick")
        check(Walk.applyMinutes(s, 30, advance = false) == 0 &&
            s.walkCarryMin == 1,
            "walk time: real-time sync mode banks nothing, ticks nothing")
        // shortcuts shave a tick, floored at MIN_LEG_MINUTES
        s.walkShortcuts += Walk.legKey("KennysHouse", "ButtersHouse")
        check(Walk.legMinutes(s, "KennysHouse", "ButtersHouse") ==
            Walk.MIN_LEG_MINUTES,
            "walk time: a taught block costs the floor, not zero")
        s.walkShortcuts += Walk.legKey("BusStop", "MainStreet")
        check(Walk.legMinutes(s, "BusStop", "MainStreet") == 8,
            "walk time: a taught long leg costs 23 - 15 = 8")
        check(Walk.routeMinutes(s, "KennysHouse", "StarksPond") == 64,
            "walk time: two taught legs pull the crossing to 64")
        check(Walk.rideCostMinutes("KennysHouse", "StarksPond") == 35,
            "bus time: a ride costs the ROUTE at bus speed — " +
                "Kennys→Starks walks 87 raw minutes, the bus " +
                "takes ceil(87 × 2/5) = 35 (v0.15.0c: " +
                "BusNetwork's derivation replaces the flat " +
                "one-leg price this pin used to state)")
    }

    // ---------- a trip, walked end to end ----------
    run {
        val s = freshState()
        place(s, "KennysHouse")
        val outs = walkAll(s, "StarksPond", Random(42))
        check(outs.size == 6, "walk trip: six legs cross the town (got ${outs.size})")
        check(outs.map { it.to } == listOf("ButtersHouse", "CartmanHouse",
            "BusStop", "MainStreet", "KidsPark", "StarksPond"),
            "walk trip: every leg lands in the next real place")
        check(outs.dropLast(1).all { it.passThrough && !it.arrived },
            "walk trip: intermediate stops are pass-throughs, not arrivals")
        check(outs.last().arrived && !outs.last().passThrough,
            "walk trip: the last leg arrives")
        check(s.walkTrips == 1 && s.walkLegs == 6 && s.walkDest.isEmpty(),
            "walk trip: the counters and the cleared plan agree")
        check(outs.sumOf { it.minutes } == 87,
            "walk trip: the legs charge the route's minutes")
        // the first leg taught its cut-through — and ONLY the
        // first: one beat slot per trip, discovery spends it
        check(outs.first().shortcutFound &&
            s.walkShortcuts == setOf("KennysHouse>ButtersHouse"),
            "walk trip: the first traversal teaches exactly one shortcut")
        check(outs.drop(1).all { !it.shortcutFound },
            "walk trip: no second discovery hides in the same trip")
        // walk home: the reverse first leg teaches its own
        val back = walkAll(s, "KennysHouse", Random(43))
        check(back.size == 6 && s.walkTrips == 2,
            "walk trip: the way home is a trip too")
        check("StarksPond>KidsPark" in s.walkShortcuts &&
            s.walkShortcuts.size == 2,
            "walk trip: shortcuts are directional — home teaches its own")
        check(Walk.legMinutes(s, "KennysHouse", "ButtersHouse") ==
            Walk.MIN_LEG_MINUTES,
            "walk trip: the taught leg is cheaper forever after")
    }

    // ---------- pass-through stops are REAL stops ----------
    run {
        val s2 = freshState()
        place(s2, "KennysHouse")
        s2.timeMin = 10 * 60
        // Stan waits at Main Street, mid-route; a DELIVER
        // errand for him is accepted before the walk
        s2.agents.getValue("Stan").location = "MainStreet"
        s2.agents.getValue("Stan").asleep = false
        val e = Errand(id = "walk_test_deliver", source = "ASK",
            asker = "Kyle", type = "DELIVER",
            text = "Take this to Stan. Don't shake it.",
            hint = "Stan's around.", targetName = "Stan",
            dayKey = s2.todayKey)
        check(Errands.accept(s2, e), "walk stop: the errand takes")
        var legs = 0
        while (eng.player(s2).location != "MainStreet" && legs++ < 8)
            Walk.walkTo(s2, "StarksPond", Random(7), advance = false)
        check(eng.player(s2).location == "MainStreet" &&
            Walk.activeDest(s2) == "StarksPond",
            "walk stop: mid-trip, you are AT Main Street with the pond still the plan")
        check(eng.presentWithPlayer(s2).any { it.name == "Stan" },
            "walk stop: Stan is present at the pass-through, for real")
        val rec = Photos.compose(s2, listOf("Stan"), emptyList(),
            "Walker", DEFAULT_APPEARANCE)
        check(rec.figures.any { it.name == "Stan" },
            "walk stop: a photo at the pass-through frames who's there")
        val done = Errands.deliverTo(s2, "Stan")
        check(done != null && s2.errandsDoneCount == 1,
            "walk stop: a DELIVER errand settles at the pass-through stop")
        // and the trip still completes afterwards
        val rest = walkAll(s2, "StarksPond", Random(8), advance = false)
        check(rest.isNotEmpty() && s2.walkTrips == 1,
            "walk stop: business done, the trip walks on and completes")
    }

    // ---------- road beats: the slot, the gates, the record ----------
    run {
        // a fresh town is not case-critical; a fabricated
        // finale on the table makes it so — and silences the road
        val s = freshState()
        check(!Walk.caseCritical(s), "beats: a fresh town is not case-critical")
        s.shenaniganId = Mystery.FINALE_ID
        s.timeMin = 13 * 60 // stage >= 2
        s.mysteryClues.addAll(Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES)
            .map { it.id })
        check(Walk.caseCritical(s) && Mystery.finaleChoiceDue(s),
            "beats: the pond finale on the table is case-critical")
        place(s, "KennysHouse")
        val quiet = Walk.walkTo(s, "ButtersHouse", Random(1), advance = false)
        check(quiet.moved && quiet.beat == null && !quiet.shortcutFound &&
            s.walkShortcuts.isEmpty(),
            "beats: case-critical ground teaches nothing and says nothing")
        s.arcChoice = "truth" // the moment passes
        check(!Walk.caseCritical(s), "beats: the moment passes, the road reopens")
        val open = Walk.walkTo(s, "KennysHouse", Random(1), advance = false)
        check(open.shortcutFound &&
            "ButtersHouse>KennysHouse" in s.walkShortcuts,
            "beats: the same street teaches its shortcut once the case lets it")
    }
    run {
        // presence-gated, cooldown-shaped pool behavior: Stan
        // and Kyle hold Kids Park; every pool beat except the
        // argument is pre-cooled, so the argument is the only
        // candidate at that stop — day fires it, night can't
        val s = freshState()
        place(s, "KennysHouse")
        s.agents.getValue("Stan").location = "KidsPark"
        s.agents.getValue("Kyle").location = "KidsPark"
        s.agents.getValue("Stan").asleep = false
        s.agents.getValue("Kyle").asleep = false
        // teach every leg up to and including the park, so
        // discoveries can't spend the trip's one beat early
        for (k in listOf("KennysHouse>ButtersHouse", "ButtersHouse>CartmanHouse",
            "CartmanHouse>BusStop", "BusStop>MainStreet", "MainStreet>KidsPark",
            "KidsPark>StarksPond"))
            s.walkShortcuts += k
        for (id in listOf("dropped", "pitch", "wave", "directions",
            "busker", "gnome_road"))
            s.life["rb:$id"] = s.absDay
        s.timeMin = 10 * 60
        var arguments = 0
        repeat(30) { i ->
            place(s, "KennysHouse")
            val outs = walkAll(s, "StarksPond", Random(1000 + i), advance = false)
            for (o in outs) if (o.beat?.id == "argument") {
                arguments++
                check(s.lastConversation.size == 2 &&
                    s.lastConversation.map { it.speaker }.distinct().size == 2 &&
                    s.lastConversation.all { it.speaker in s.agents },
                    "beats: the overheard argument is a real pair, mid-spat")
            }
        }
        check(arguments >= 1,
            "beats: across 30 day trips the argument fires at the park (got $arguments)")
        check((s.life["roadBeatDay"] ?: -1) == s.absDay &&
            (s.lifeText["roadBeat"] ?: "").isNotEmpty(),
            "beats: the road keeps its morning record")
        // the morning report reads yesterday's road back
        s.absDay += 1
        val report = House.morningReport(s, emptyList(), emptyMap(), 0, false, null)
        check(report.any { it.startsWith("🚶 On the road yesterday") },
            "beats: the morning report mentions yesterday's road beat")
        // night: the noisy argument is gated out entirely —
        // and with everything else freshly cooled (the day
        // turned over above), the road is silent
        for (id in listOf("dropped", "pitch", "wave", "directions",
            "busker", "gnome_road"))
            s.life["rb:$id"] = s.absDay
        s.timeMin = 23 * 60 + 30
        var nightBeats = 0
        repeat(10) { i ->
            place(s, "KennysHouse")
            val outs = walkAll(s, "StarksPond", Random(2000 + i), advance = false)
            nightBeats += outs.count { it.beat != null }
        }
        check(nightBeats == 0,
            "beats: quiet hours silence the noisy road (got $nightBeats)")
        // the pool table itself: cooldowns are days, the
        // noisy set is the loud third of the pool
        check(Walk.POOL.size == 8 && Walk.POOL.all { it.cooldownDays in 1..7 } &&
            Walk.POOL.count { it.noisy } == 3,
            "beats: eight beats, day-scale cooldowns, three of them loud")
    }

    // ---------- feats: crossings announce themselves ----------
    run {
        val s = freshState()
        place(s, "KennysHouse")
        s.walkTrips = 9
        Walk.walkTo(s, "ButtersHouse", Random(3), advance = false)
        check(s.walkTrips == 10 && s.life["walkFeat:walk_10"] == 1 &&
            s.events.any { it.contains("First Steps") },
            "walk feats: the tenth trip lands First Steps out loud")
        val s2 = freshState()
        place(s2, "KennysHouse")
        // nine shortcuts known; the next new leg is the tenth
        for (k in listOf("ButtersHouse>CartmanHouse", "CartmanHouse>BusStop",
            "BusStop>MainStreet", "MainStreet>KidsPark", "KidsPark>StarksPond",
            "StarksPond>KidsPark", "KidsPark>MainStreet", "MainStreet>BusStop",
            "BusStop>CartmanHouse"))
            s2.walkShortcuts += k
        Walk.walkTo(s2, "ButtersHouse", Random(3), advance = false)
        check(s2.walkShortcuts.size == 10 &&
            s2.life["walkFeat:walk_shortcuts_10"] == 1,
            "walk feats: the tenth shortcut lands Local")
        check(Walk.featEarned(s, Walk.featById("walk_10")!!) &&
            !Walk.featEarned(s, Walk.featById("walk_50")!!),
            "walk feats: earned reads the counters, not the claims")
    }

    // ---------- the bus pass ----------
    run {
        val s = freshState()
        place(s, "KennysHouse")
        val passItem = itemById("bus_pass")
        check(passItem != null && passItem.tier == "key",
            "bus: the pass is a KEY item — no loot or gift pool can deal it")
        check(Errands.sourceOf("bus_pass") == "kiosk" &&
            "bus_pass" !in Errands.FETCH_POOL && "bus_pass" !in Errands.FIND_POOL,
            "bus: the kiosk is its only source; no errand can ask for it")
        check(Walk.buyPass(s) == "poor" && !s.busPass,
            "bus: an empty wallet gets the kiosk's blink, not a pass")
        Minigames.awardCoins(s, 30)
        check(Walk.buyPass(s) == "bought" && s.busPass &&
            Minigames.capsuleCoins(s) == 30 - Walk.BUS_PASS_PRICE &&
            (s.inventory["bus_pass"] ?: 0) == 1,
            "bus: 25 coins at the kiosk, pass in the wallet, card in the pack")
        check(Walk.buyPass(s) == "owned", "bus: the kiosk won't sell you two")
        // riding: no pass is a refusal; with the pass it's
        // one leg's minutes and a cleared walk plan
        val s2 = freshState()
        place(s2, "KennysHouse")
        check(Walk.ride(s2, "StarksPond", advance = false).let {
            !it.ok && it.reason == "nopass"
        }, "bus: no pass, no ride")
        s2.busPass = true
        s2.walkDest = "Mall" // a walk in progress, abandoned for the bus
        val ride = Walk.ride(s2, "StarksPond", advance = false)
        check(ride.ok && ride.minutes == 35 &&
            eng.player(s2).location == "StarksPond" &&
            s2.walkDest.isEmpty() && s2.walkTrips == 0 &&
            (s2.life["walkRides"] ?: 0) == 1,
            "bus: the ride lands you there for the route at " +
                "bus speed — 35 on the 87-minute walk — trips " +
                "uncounted (v0.15.0c: BusNetwork's derivation " +
                "retires the flat first-leg price this pin " +
                "used to state)")
        val ride2 = Walk.ride(s2, "KennysHouse", advance = true)
        check(ride2.ok && ride2.minutes == 35 && s2.walkCarryMin == 5,
            "bus: ride minutes bank through the same carry as " +
                "walking — the same 87 raw minutes home, the " +
                "same 35 at bus speed (two ticks and 5 banked)")
        // Town Fixture: the perk, claimed at the kiosk or
        // retroactively on load — never bought twice over
        val s3 = freshState()
        s3.errandsDoneCount = 50
        check(Walk.townFixture(s3) && Walk.buyPass(s3) == "granted" &&
            s3.busPass && Minigames.capsuleCoins(s3) == 0,
            "bus: Town Fixture claims the pass free, coins untouched")
        val s4 = freshState()
        s4.errandsDoneCount = 75
        check(Walk.ensureFeatPass(s4) && s4.busPass &&
            !Walk.ensureFeatPass(s4),
            "bus: an old save's perk lands retroactively, exactly once")
        val s5 = freshState()
        s5.errandsDoneCount = 49
        check(!Walk.townFixture(s5) && !Walk.ensureFeatPass(s5),
            "bus: 49 errands is not the perk — the line is the line")
    }

    // ---------- saves: additive, capped, honest ----------
    run {
        val s = freshState()
        s.walkDest = "StarksPond"; s.walkCarryMin = 7
        s.walkTrips = 12; s.walkLegs = 40; s.busPass = true
        s.walkShortcuts += "KennysHouse>ButtersHouse"
        s.walkShortcuts += "BusStop>MainStreet"
        val back = decodeGameState(encodeGameState(s))
        check(back.walkDest == "StarksPond" && back.walkCarryMin == 7 &&
            back.walkTrips == 12 && back.walkLegs == 40 && back.busPass &&
            back.walkShortcuts == s.walkShortcuts,
            "walk saves: the whole record round-trips")
        // a hand-inflated doc is clamped back to the real town
        val doc = encodeGameState(s).toMutableMap()
        doc["walk"] = mapOf(
            "dest" to "Nowhere", "carry" to 99, "trips" to -5,
            "legs" to 12, "busPass" to true,
            "shortcuts" to listOf("KennysHouse>ButtersHouse",
                "KennysHouse>MainStreet", // not an edge
                "Nowhere>MainStreet",     // not a place
                "BusStop>MainStreet", "BusStop>MainStreet"))
        val clamped = decodeGameState(doc)
        check(clamped.walkDest.isEmpty() && clamped.walkCarryMin == 14 &&
            clamped.walkTrips == 0 && clamped.walkLegs == 12 &&
            clamped.walkShortcuts == setOf(
                "KennysHouse>ButtersHouse", "BusStop>MainStreet"),
            "walk saves: decode keeps only real streets, at real values")
        // a pre-walk save loads as a town nobody has crossed
        val old = encodeGameState(s).toMutableMap()
        old.remove("walk")
        val legacy = decodeGameState(old)
        check(legacy.walkDest.isEmpty() && legacy.walkTrips == 0 &&
            legacy.walkLegs == 0 && legacy.walkShortcuts.isEmpty() &&
            !legacy.busPass,
            "walk saves: old saves load unwalked and passless")
    }

    // ---------- the soak: a year of crossings ----------
    run {
        val eng2 = Engine(777)
        val s = eng2.newState()
        eng2.createPlayer(s, "Soaker", DEFAULT_APPEARANCE)
        var trips = 0
        repeat(200) { day ->
            eng2.onNewDay(s)
            val target = if (day % 2 == 0) "StarksPond" else "KennysHouse"
            var guard = 0
            while (eng2.player(s).location != target && guard++ < 16) {
                val o = Walk.walkTo(s, target, Random(9000 + day), advance = true)
                if (!o.moved) break
                if (o.arrived) trips++
            }
        }
        check(trips >= 190, "walk soak: a year of days, a trip a day (got $trips)")
        check(s.walkTrips >= 190 && s.walkLegs >= s.walkTrips * 5,
            "walk soak: the lifetime counters keep the year's shape")
        check(s.walkShortcuts.size in 1..Walk.SHORTCUT_CAP,
            "walk soak: shortcuts stay capped at the edge count (${s.walkShortcuts.size})")
        check(s.walkCarryMin in 0 until Walk.TICK_MINUTES,
            "walk soak: the minute bank never overflows its tick")
        check(s.walkDest.isEmpty(),
            "walk soak: no trip is left dangling at year's end")
        val rt = decodeGameState(encodeGameState(s))
        check(rt.walkTrips == s.walkTrips &&
            rt.walkShortcuts == s.walkShortcuts,
            "walk soak: the year's record survives its own save")
    }

    // ---------- wiring (source pins, the suite's habit) ----------
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("Walk.walkTo") && gaSrc.contains("openGoSomewhere") &&
        gaSrc.contains("Walk.ride") && gaSrc.contains("\"buskiosk\" -> busKioskDialog()") &&
        gaSrc.contains("Walk.ensureFeatPass"),
        "walk wiring: exits walk, the picker picks, the kiosk answers, the perk lands")
    val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("drawTransitKiosk") && gvSrc.contains("Walk.nextStop"),
        "walk wiring: the kiosk glows in the Mall and signposts know the next stop")
    val jSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jSrc.contains("🗺 WALKS") && jSrc.contains("Walk.pageLines"),
        "walk wiring: the Journal keeps the 🗺 WALKS page")
    val cSrc = File(root, "src/com/hunt3r/southparktown/CollectionActivity.kt").readText()
    check(cSrc.contains("🗺 WALK FEATS") && cSrc.contains("Walk.WALK_FEATS"),
        "walk wiring: the Collection keeps the walk feats")
    val hSrc = File(root, "src/com/hunt3r/southparktown/House.kt").readText()
    check(hSrc.contains("roadBeatDay"),
        "walk wiring: the morning report reads the road record")
    check(Walk.pageLines(freshState()).first().startsWith("🗺 WALKS"),
        "walk wiring: the page opens with its headline")
}
}
private fun sectionV050b(root: String) {
// ================= v0.5.0b: outfits & unlockables =================
// Queue #5 item 2. Fourteen creator pieces join the shelf —
// hats, tops, bottoms, accessories — every one LOCKED at
// first with a named source and a player-facing hint, all of
// them ordinary creator options (no parallel appearance
// system) whose unlock rails live in the pure Wardrobe
// registry: 4 bought with Capsule Coins at two real counters,
// 4 granted by feats (one per feat family, retroactively on
// load), 3 seasonal (two holiday signature beats + the winter
// season itself), 3 special (a case retirement, the Town
// Fixture title, a collection milestone). The creator greys
// the locked, the dice never rolls them, presets hold owned
// sets only, the house mirror quick-swaps presets, and the
// outfit-comment rail speaks piece-specific lines.
println("== v0.5.0b: outfits & unlockables — a wardrobe the town can see ==")
val eng = Engine(5050)
fun freshState(): GameState {
    val s = eng.newState()
    eng.createPlayer(s, "Dresser", DEFAULT_APPEARANCE)
    return s
}
run {
    // ---------- the registry: complete, real, well-formed ----------
    check(Wardrobe.PIECES.size == 14, "wardrobe: exactly 14 pieces")
    check(Wardrobe.PIECE_IDS.size == 14, "wardrobe: piece ids unique")
    check(Wardrobe.PIECES.map { it.kind }.count { it == Wardrobe.KIND_COIN } == 4 &&
        Wardrobe.PIECES.map { it.kind }.count { it == Wardrobe.KIND_FEAT } == 4 &&
        Wardrobe.PIECES.map { it.kind }.count { it == Wardrobe.KIND_SEASONAL } == 3 &&
        Wardrobe.PIECES.map { it.kind }.count { it == Wardrobe.KIND_SPECIAL } == 3,
        "wardrobe: 4 coin / 4 feat / 3 seasonal / 3 special")
    val cats = Wardrobe.PIECES.map { it.category }.toSet()
    check(cats == setOf("hat", "top", "bottom", "accessory"),
        "wardrobe: pieces spread across hats / tops / bottoms / accessories")
    for (p in Wardrobe.PIECES) {
        check(p.category in CREATOR_ORDER, "wardrobe: ${p.id} category is a creator category")
        val opts = CREATOR_OPTIONS[p.category]?.second ?: emptyList()
        check(opts.any { it.id == p.id },
            "wardrobe: ${p.id} is a real option in the ${p.category} list (same shelf, no parallel system)")
        check(creatorOpt(p.category, p.id).name == p.name,
            "wardrobe: ${p.id} registry name matches the creator option name")
        check(p.hint.isNotBlank() && p.sourceLabel.isNotBlank(),
            "wardrobe: ${p.id} has a named source and a player-facing hint")
        check(p.noticeLine.isNotBlank(), "wardrobe: ${p.id} has a notice line for the outfit rail")
        check((p.noticeNpc == null) == (p.noticeNpcLine == null),
            "wardrobe: ${p.id} named callout and its line come as a pair")
        if (p.noticeNpc != null)
            check(p.noticeNpc in AGENT_PROFILES,
                "wardrobe: ${p.id} callout NPC ${p.noticeNpc} is a real cast member")
    }
    // creator total: 114 + 14
    val total = CREATOR_OPTIONS.values.sumOf { it.second.size }
    check(total == 128, "wardrobe: the creator shelf is 114 + 14 = 128 options (got $total)")

    // ---------- coin pieces: real counters, sane prices ----------
    val coin = Wardrobe.PIECES.filter { it.kind == Wardrobe.KIND_COIN }
    check(coin.all { it.price > 0 && it.shopLoc in LOCATIONS },
        "wardrobe: every coin piece has a price and a real shop location")
    check(coin.map { it.shopLoc }.toSet() == setOf("Mall", "JimbosGuns"),
        "wardrobe: coin pieces sell at the Mall plus one other shop (Jimbo's Guns)")
    check(coin.count { it.shopLoc == "Mall" } == 2 &&
        coin.count { it.shopLoc == "JimbosGuns" } == 2,
        "wardrobe: two pieces per counter")
    check(coin.map { it.price } == listOf(12, 18, 15, 10),
        "wardrobe: prices are 12 / 18 at the Mall, 15 / 10 at Jimbo's")
    check(Wardrobe.coinTotal() == 55, "wardrobe: the coin shelf is a 55-coin sink")
    check(coin.all { Wardrobe.piecesAt(it.shopLoc!!).contains(it) },
        "wardrobe: piecesAt returns each coin piece at its own counter")

    // ---------- feat pieces: one per family, feats are real ----------
    val feats = Wardrobe.PIECES.filter { it.kind == Wardrobe.KIND_FEAT }
    check(feats.map { it.featFamily }.toSet() == setOf("errand", "photo", "game", "walk"),
        "wardrobe: one feat piece per family (errand / photo / game / walk)")
    for (p in feats) {
        val real = when (p.featFamily) {
            "errand" -> Errands.featById(p.featId!!) != null
            "photo" -> Photos.featById(p.featId!!) != null
            "game" -> Minigames.featById(p.featId!!) != null
            "walk" -> Walk.featById(p.featId!!) != null
            else -> false
        }
        check(real, "wardrobe: ${p.id} feat ${p.featFamily}/${p.featId} exists in its family table")
    }

    // ---------- seasonal/special: triggers name real systems ----------
    for (p in Wardrobe.PIECES.filter {
        it.kind == Wardrobe.KIND_SEASONAL || it.kind == Wardrobe.KIND_SPECIAL }) {
        if (p.holidayId != null) {
            check(HOLIDAYS.any { it.id == p.holidayId } &&
                HolidayBeats.beatFor(p.holidayId) != null,
                "wardrobe: ${p.id} holiday ${p.holidayId} has a real signature beat")
        } else {
            check(p.trigger in setOf(Wardrobe.TRIGGER_WINTER, Wardrobe.TRIGGER_MYSTERY,
                Wardrobe.TRIGGER_FIXTURE, Wardrobe.TRIGGER_COLLECTION),
                "wardrobe: ${p.id} trigger is a named trigger (${p.trigger})")
        }
    }
    val winter = Wardrobe.pieceById("deep_winter_parka")!!
    check(winter.trigger == Wardrobe.TRIGGER_WINTER && winter.holidayId == null,
        "wardrobe: the parka's trigger is the season itself, named in data")
    check(Wardrobe.COLLECTION_MILESTONE == 15 && COLLECTIBLES.size == 25,
        "wardrobe: the collection milestone is 15 of the 25 collectibles")

    // ---------- locked at first; sync grants nothing to a fresh town ----------
    run {
        val s = freshState() // Oct 1, 2026 — fall, no feats, no finds
        check(s.unlockedWardrobe.isEmpty(), "wardrobe: a fresh town owns nothing")
        check(Wardrobe.PIECES.all { Wardrobe.isLocked(s, it.category, it.id) },
            "wardrobe: every piece reads locked on a fresh save")
        check(Wardrobe.syncUnlocks(s).isEmpty() && s.unlockedWardrobe.isEmpty(),
            "wardrobe: the retroactive sync grants a fresh town nothing")
        check(Wardrobe.ownedCount(s) == 0, "wardrobe: owned count starts at 0/14")
    }

    // ---------- feat retro-grants: one fabricated crossing per family ----------
    run {
        val s = freshState(); s.errandsDoneCount = 10
        val g = Wardrobe.syncUnlocks(s)
        check(g.map { it.id } == listOf("neighbor_scarf"),
            "wardrobe retro: 10 errands grants exactly the Neighborly Scarf (got ${g.map { it.id }})")
        check(s.unlockedWardrobe == setOf("neighbor_scarf"),
            "wardrobe retro: the scarf is in the unlocked set")
        check(s.events.any { it.contains("Neighborly Scarf") },
            "wardrobe retro: the grant posts a ticker line")
        check(s.townLog.any { it.contains("Neighborly Scarf") },
            "wardrobe retro: the grant writes a town-log line")
        check(Wardrobe.syncUnlocks(s).isEmpty(),
            "wardrobe retro: a second sync grants nothing (idempotent)")
    }
    run {
        val s = freshState(); s.photoFeats += "squad_shot"
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("squad_hoodie"),
            "wardrobe retro: the squad photo feat grants the Squad Hoodie")
    }
    run {
        val s = freshState(); s.gameFeats += "taco_500"
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("taco_hat"),
            "wardrobe retro: the Taco Titan feat grants the Taco Hat")
    }
    run {
        val s = freshState(); s.walkTrips = 10
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("road_jeans"),
            "wardrobe retro: 10 walked trips grants the Road-Worn Jeans")
    }
    run {
        // just under a threshold grants nothing
        val s = freshState(); s.errandsDoneCount = 9; s.walkTrips = 9
        check(Wardrobe.syncUnlocks(s).isEmpty(),
            "wardrobe retro: one short of a feat is one short — nothing granted")
    }

    // ---------- seasonal + special retro-grants ----------
    run {
        val s = freshState(); s.life["hbYears:halloween"] = 1
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("pumpkin_sweater"),
            "wardrobe seasonal: a played Full Route grants the Pumpkin Sweater")
    }
    run {
        val s = freshState(); s.life["hbYears:christmas"] = 1
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("santa_hat"),
            "wardrobe seasonal: a played Secret Santa Relay grants the Santa Hat")
    }
    run {
        val s = freshState(); s.gameMonth = 1 // January — winter
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("deep_winter_parka"),
            "wardrobe seasonal: a winter date grants the Deep Winter Parka (the season itself)")
        val s2 = freshState(); s2.gameMonth = 7 // July — summer
        check(Wardrobe.syncUnlocks(s2).isEmpty(),
            "wardrobe seasonal: a summer date grants no parka")
    }
    run {
        val s = freshState(); s.arc2Retired = true
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("sleuth_cap"),
            "wardrobe special: retiring the booth case grants the Sleuth's Cap")
        val s3 = freshState(); s3.arcRetired = true
        check(Wardrobe.syncUnlocks(s3).map { it.id } == listOf("sleuth_cap"),
            "wardrobe special: retiring the pond case grants it too — ANY case")
    }
    run {
        val s = freshState(); s.errandsDoneCount = 50
        val g = Wardrobe.syncUnlocks(s).map { it.id }
        check("fixture_vest" in g && "neighbor_scarf" in g,
            "wardrobe special: 50 errands grants the Town Fixture Vest (and the 10-errand scarf under it)")
    }
    run {
        val s = freshState()
        s.collected += COLLECTIBLES.take(15).map { it.id }
        check(Wardrobe.syncUnlocks(s).map { it.id } == listOf("collector_scarf"),
            "wardrobe special: 15 collectibles grants the Completionist Scarf")
        val s2 = freshState(); s2.collected += COLLECTIBLES.take(14).map { it.id }
        check(Wardrobe.syncUnlocks(s2).isEmpty(),
            "wardrobe special: 14 collectibles is not the milestone")
    }

    // ---------- the coin rail ----------
    run {
        val s = freshState()
        val cap = Wardrobe.pieceById("mall_rat_cap")!!
        check(Wardrobe.buy(s, cap.id, "Mall") == "poor",
            "wardrobe coin: no coins, no cap — insufficient funds rail")
        check(!Wardrobe.owned(s, cap) && Minigames.capsuleCoins(s) == 0,
            "wardrobe coin: a failed purchase changes nothing")
        Minigames.awardCoins(s, 11)
        check(Wardrobe.buy(s, cap.id, "Mall") == "poor" &&
            Minigames.capsuleCoins(s) == 11,
            "wardrobe coin: 11 of 12 is still poor, balance untouched")
        Minigames.awardCoins(s, 1)
        check(Wardrobe.buy(s, cap.id, "JimbosGuns") == "notsold",
            "wardrobe coin: the Mall cap is not sold at Jimbo's counter")
        check(Wardrobe.buy(s, cap.id, "Mall") == "bought",
            "wardrobe coin: 12 coins at the Mall buys the cap")
        check(Wardrobe.owned(s, cap) && Minigames.capsuleCoins(s) == 0,
            "wardrobe coin: the cap is owned and the till took exactly 12")
        check(Wardrobe.buy(s, cap.id, "Mall") == "owned",
            "wardrobe coin: buying an owned piece answers owned, charges nothing")
        check(Wardrobe.buy(s, "road_jeans", "Mall") == "notsold",
            "wardrobe coin: a feat piece is not for sale anywhere")
        check(Wardrobe.buy(s, "no_such_piece", "Mall") == "notsold",
            "wardrobe coin: an unknown piece is not sold")
        check(s.events.any { it.contains("Mall Rat Cap") },
            "wardrobe coin: the purchase posts its ticker line")
    }
    run {
        // the whole shelf, bought end to end: 55 coins, exact change math
        val s = freshState()
        Minigames.awardCoins(s, 55)
        for (p in Wardrobe.PIECES.filter { it.kind == Wardrobe.KIND_COIN })
            check(Wardrobe.buy(s, p.id, p.shopLoc!!) == "bought",
                "wardrobe coin: ${p.id} buys at ${p.shopLoc}")
        check(Minigames.capsuleCoins(s) == 0 && Wardrobe.ownedCount(s) == 4,
            "wardrobe coin: 55 coins buys out both counters exactly")
    }

    // ---------- creator discipline: dice, sanitize, presets ----------
    run {
        var diceClean = true
        for (seed in 0 until 300) {
            val r = randomAppearance(Random(seed))
            for (c in CREATOR_ORDER)
                if (r[c] in Wardrobe.PIECE_IDS) diceClean = false
        }
        check(diceClean, "wardrobe dice: 300 rolls never deal a wardrobe piece")
        // a look built of locked pieces cannot survive sanitize
        val greedy = DEFAULT_APPEARANCE + mapOf(
            "hat" to "santa_hat", "top" to "varsity_jacket",
            "accessory" to "neighbor_scarf")
        val cleaned = Wardrobe.sanitizeAppearance(greedy, emptySet(), emptySet())
        check(cleaned["hat"] == DEFAULT_APPEARANCE["hat"] &&
            cleaned["top"] == DEFAULT_APPEARANCE["top"] &&
            cleaned["accessory"] == DEFAULT_APPEARANCE["accessory"],
            "wardrobe sanitize: locked pieces fall back to the blank defaults")
        check(!Wardrobe.presetOk(greedy, emptySet(), emptySet()),
            "wardrobe presets: a set referencing unowned pieces is not a legal preset")
        // …but the same look passes untouched once owned (monotonic)
        val owned = setOf("santa_hat", "varsity_jacket", "neighbor_scarf")
        check(Wardrobe.sanitizeAppearance(greedy, emptySet(), owned) ==
            validateAppearance(greedy),
            "wardrobe sanitize: an owned set passes through byte-identical")
        check(Wardrobe.presetOk(greedy, emptySet(), owned),
            "wardrobe presets: an owned set is a legal preset")
        // unlocking-while-worn is impossible by construction:
        // a piece must be in the unlocked set before sanitize
        // lets it into any wearable look (shown above), and the
        // creator pick path is guarded by isLocked (source pin
        // in the wiring block below)
        check(Wardrobe.isLocked(emptySet(), "hat", "santa_hat") &&
            !Wardrobe.isLocked(setOf("santa_hat"), "hat", "santa_hat") &&
            !Wardrobe.isLocked(emptySet(), "hat", "cowboy"),
            "wardrobe locks: wardrobe pieces lock until owned; ordinary options never lock here")
    }

    // ---------- save round-trip: one key, decode-filtered ----------
    run {
        val s = freshState()
        s.unlockedWardrobe += setOf("santa_hat", "taco_hat")
        val doc = encodeGameState(s)
        check(doc["wardrobe"] != null, "wardrobe save: the doc carries the wardrobe key")
        val back = decodeGameState(doc)
        check(back.unlockedWardrobe == setOf("santa_hat", "taco_hat"),
            "wardrobe save: unlocked pieces round-trip")
        val inflated = encodeGameState(s).toMutableMap()
        inflated["wardrobe"] = listOf("santa_hat", "infinity_gauntlet", "santa_hat")
        val clamped = decodeGameState(inflated)
        check(clamped.unlockedWardrobe == setOf("santa_hat"),
            "wardrobe save: decode filters invented pieces and dedupes")
        val era = decodeGameState(emptyMap())
        check(era.unlockedWardrobe.isEmpty(),
            "wardrobe save: a pre-wardrobe save loads with a locked wardrobe")
    }

    // ---------- the worn-piece rendering path ----------
    run {
        // every piece, worn through the REAL appearance ->
        // avatarSpec mapping, changes the spec in its own slot
        val base = avatarSpec(DEFAULT_APPEARANCE)
        for (p in Wardrobe.PIECES) {
            val look = DEFAULT_APPEARANCE + (p.category to p.id)
            val spec = avatarSpec(look)
            val ok = when (p.category) {
                "hat" -> spec.hatId == p.id &&
                    spec.hatColor == creatorOpt("hat", p.id).color
                "top" -> spec.top == creatorOpt("top", p.id).color &&
                    spec.top != base.top
                "bottom" -> spec.bottom == creatorOpt("bottom", p.id).color &&
                    spec.bottom != base.bottom
                "accessory" -> spec.scarfHex == creatorOpt("accessory", p.id).color
                else -> false
            }
            check(ok, "wardrobe render: wearing ${p.id} reaches avatarSpec in the ${p.category} slot")
        }
        // construction tokens ride along for the tops
        check(avatarSpec(mapOf("top" to "varsity_jacket")).let {
            it.placket && it.buttons && it.pockets == 2 },
            "wardrobe render: the Varsity Jacket wears the jacket construction")
        check(avatarSpec(mapOf("top" to "fixture_vest")).let {
            it.placket && it.buttons && it.pockets == 0 },
            "wardrobe render: the Fixture Vest wears the vest construction")
        check(avatarSpec(mapOf("top" to "deep_winter_parka")).placket,
            "wardrobe render: the Deep Winter Parka wears the parka zipper")
        check(avatarSpec(mapOf("top" to "squad_hoodie")).collarHex != null,
            "wardrobe render: the Squad Hoodie wears its collar band")
    }

    // ---------- the town notices: the outfit rail, piece-aware ----------
    run {
        val oldLook = DEFAULT_APPEARANCE
        val cowboy = DEFAULT_APPEARANCE + ("hat" to "rhinestone_cowboy")
        check(Wardrobe.noticeLine(cowboy, oldLook, "Jimbo") ==
            Wardrobe.pieceById("rhinestone_cowboy")!!.noticeNpcLine,
            "wardrobe notice: Jimbo gets his own line about the cowboy hat")
        check(Wardrobe.noticeLine(cowboy, oldLook, "Kyle") ==
            Wardrobe.pieceById("rhinestone_cowboy")!!.noticeLine,
            "wardrobe notice: anyone else gets the piece's generic line")
        val plain = DEFAULT_APPEARANCE + ("hat" to "cowboy")
        check(Wardrobe.noticeLine(plain, oldLook, "Jimbo") == null,
            "wardrobe notice: an ordinary hat change stays on the category rail (null)")
        check(Wardrobe.noticeLine(oldLook, oldLook, "Jimbo") == null,
            "wardrobe notice: no change, no line")
        for (p in Wardrobe.PIECES) {
            val look = DEFAULT_APPEARANCE + (p.category to p.id)
            check(Wardrobe.noticeLine(look, oldLook, "Stan") != null,
                "wardrobe notice: wearing ${p.id} produces a line")
            if (p.noticeNpc != null)
                check(Wardrobe.noticeLine(look, oldLook, p.noticeNpc) == p.noticeNpcLine,
                    "wardrobe notice: ${p.noticeNpc} has the named callout for ${p.id}")
        }
        val named = Wardrobe.PIECES.filter { it.noticeNpc != null }
        check(named.size >= 4,
            "wardrobe notice: at least four pieces carry named cast callouts (got ${named.size})")
    }

    // ---------- the Collection surface ----------
    run {
        val s = freshState()
        val lines = Wardrobe.collectionLines(s)
        check(lines.first().contains("0/14"),
            "wardrobe collection: the header counts 0/14 on a fresh town")
        check(lines.count { it.startsWith("👤") } == 14,
            "wardrobe collection: all 14 locked pieces show as silhouettes")
        check(lines.filter { it.startsWith("👤") }.all { l ->
            Wardrobe.PIECES.any { l.contains(it.hint) } },
            "wardrobe collection: every silhouette carries its piece's hint")
        Wardrobe.syncUnlocks(s.apply { gameMonth = 12 })
        val lines2 = Wardrobe.collectionLines(s)
        check(lines2.first().contains("1/14") &&
            lines2.any { it.startsWith("✅") && it.contains("Deep Winter Parka") },
            "wardrobe collection: an owned piece is named with its source")
    }

    // ---------- wiring (source cross-checks) ----------
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("Wardrobe.syncUnlocks(state)"),
        "wardrobe wiring: GameActivity syncs unlocks (load + refresh)")
    check(gaSrc.contains("mirrorDialog()") && gaSrc.contains("wearPreset"),
        "wardrobe wiring: the mirror opens the wardrobe surface with one-tap preset swaps")
    check(gaSrc.contains("\"clothesrack\"") && gaSrc.contains("wardrobeShopDialog"),
        "wardrobe wiring: the counters answer fixture taps with the shop dialog")
    check(gaSrc.contains("Wardrobe.noticeLine"),
        "wardrobe wiring: the outfit-comment rail asks Wardrobe for piece lines")
    val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("drawWardrobeRack") && gvSrc.contains("drawGunRack"),
        "wardrobe wiring: both counters are drawn in the world")
    val crSrc = File(root, "src/com/hunt3r/southparktown/CreatorActivity.kt").readText()
    check(crSrc.contains("Wardrobe.pieceFor") && crSrc.contains("piece.hint"),
        "wardrobe wiring: the creator greys locked pieces and prints their hints")
    check(crSrc.contains("Wardrobe.sanitizeAppearance"),
        "wardrobe wiring: the creator sanitizes looks and presets to owned pieces")
    val colSrc = File(root, "src/com/hunt3r/southparktown/CollectionActivity.kt").readText()
    check(colSrc.contains("👕 WARDROBE") && colSrc.contains("Wardrobe.collectionLines"),
        "wardrobe wiring: the Collection carries the 👕 WARDROBE section")
    val wSrc = File(root, "src/com/hunt3r/southparktown/Wardrobe.kt").readText()
    check(!wSrc.contains("import android"),
        "wardrobe wiring: Wardrobe logic is pure Kotlin")
    val prefsSrc = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    check(prefsSrc.contains("\"wardrobe\" to") && prefsSrc.contains("Wardrobe.PIECE_IDS"),
        "wardrobe wiring: the save persists the wardrobe key, decode-filtered to the registry")
}
}

private fun sectionV050c(root: String) {
// ================= v0.5.0c: Pocket Pals =================
// Queue #5 item 3. A 24-card set of ORIGINAL parody creatures
// (14 common / 7 uncommon / 3 rare, four schools), every name
// and design invented here and guarded against a franchise
// denylist. The faucet: the capsule machine inside the Mall
// (2 capsule coins a pull, weighted rarities, dupes counted),
// errand thank-yous that sometimes land as a card, and two
// Look-find exclusives that never ride the drum. The sink:
// weekly seeded kid stashes, obsession-school valuation,
// one-for-one trades with a capped friendship swing, and
// last-copy protection. Feats derive from ownership; the
// binder lives in one additive decode-capped save key.
println("== v0.5.0c: Pocket Pals — the binder economy ==")
val eng = Engine(50503)
fun freshState(): GameState {
    val s = eng.newState()
    eng.createPlayer(s, "Collector", DEFAULT_APPEARANCE)
    return s
}
run {
    // ---------- the set: complete, original, well-formed ----------
    check(PocketPals.CARDS.size == 24, "pals: exactly 24 cards")
    check(PocketPals.CARD_IDS.size == 24, "pals: card ids unique")
    check(PocketPals.CARDS.map { it.name }.toSet().size == 24, "pals: card names unique")
    check(PocketPals.CARDS.count { it.rarity == PocketPals.COMMON } == 14 &&
        PocketPals.CARDS.count { it.rarity == PocketPals.UNCOMMON } == 7 &&
        PocketPals.CARDS.count { it.rarity == PocketPals.RARE } == 3,
        "pals: the rarity split is 14 common / 7 uncommon / 3 rare")
    for (school in PocketPals.SCHOOLS) {
        check(PocketPals.CARDS.count { it.school == school } == 6,
            "pals: six $school cards")
    }
    val bodies = setOf("ROUND", "TALL", "WIDE", "BLOB", "SQUARE", "STAR")
    val earsOk = setOf("NONE", "POINTS", "FLOPPY", "ANTENNA", "HORNS", "FIN", "TUFT")
    val eyesOk = setOf("DOTS", "HAPPY", "SLEEPY", "STAR", "WINK", "ROUND")
    val extraOk = setOf("NONE", "STRIPES", "STAR_MARK", "BELT", "CAP", "TAIL", "WINGS")
    val hexRe = Regex("#[0-9a-fA-F]{6}")
    for (card in PocketPals.CARDS) {
        check(card.school in PocketPals.SCHOOLS, "pals: ${card.id} school is one of the four")
        check(card.flavor.isNotBlank() && card.flavor.length <= 140,
            "pals: ${card.id} has a one-line flavor")
        check(card.body in bodies && card.ears in earsOk && card.eyes in eyesOk &&
            card.extra in extraOk,
            "pals: ${card.id} drawing spec uses only the renderer's shapes")
        check(hexRe.matches(card.bodyColor) && hexRe.matches(card.bellyColor) &&
            hexRe.matches(card.accentColor),
            "pals: ${card.id} palette is three hex colors")
    }
    // the same data draws the same card forever: specs are distinct
    val specs = PocketPals.CARDS.map {
        listOf(it.body, it.bodyColor, it.bellyColor, it.accentColor,
            it.ears, it.eyes, it.extra).joinToString("|")
    }
    check(specs.toSet().size == 24, "pals: every card's drawing spec is unique")
    // originality guard: no franchise terms, no borrowed names
    val borrowed = (CharacterSystem.CAST.keys + COLLECTIBLES.map { it.name } +
        ITEMS.map { it.name }).map { it.lowercase() }.toSet()
    for (card in PocketPals.CARDS) {
        val text = (card.name + " " + card.flavor).lowercase()
        for (term in PocketPals.DENYLIST)
            check(!text.contains(term), "pals: ${card.id} is clean of '$term'")
        check(card.name.lowercase() !in borrowed,
            "pals: ${card.id} name '${card.name}' is borrowed from nobody in town")
    }
    // the chase rare: machine stock, Spark, named like it matters
    check(PocketPals.CHASE.id == "aurorath" && PocketPals.CHASE.rarity == PocketPals.RARE &&
        PocketPals.CHASE.source == PocketPals.SOURCE_MACHINE &&
        PocketPals.CHASE.name.contains(","),
        "pals: the chase rare is Aurorath, the Storm That Stayed — machine stock")
    // pools: 22 ride the drum, 2 hide, never both
    check(PocketPals.MACHINE_POOL.size == 22, "pals: 22 cards ride the drum")
    check(PocketPals.LOOK_CARDS.size == 2, "pals: exactly 2 Look exclusives")
    check(PocketPals.MACHINE_POOL.none { it in PocketPals.LOOK_CARDS } &&
        (PocketPals.MACHINE_POOL + PocketPals.LOOK_CARDS).toSet() ==
            PocketPals.CARDS.toSet(),
        "pals: machine pool and Look exclusives partition the set")
    for (card in PocketPals.LOOK_CARDS) {
        check(card.lookLoc in LOCATIONS && !card.lookSpot.isNullOrBlank(),
            "pals: ${card.id} hides at a named spot (${card.lookSpot})")
    }
    check(PocketPals.MACHINE_POOL.sumOf { PocketPals.weightOf(it) } ==
        14 * PocketPals.WEIGHT_COMMON + 6 * PocketPals.WEIGHT_UNCOMMON +
            2 * PocketPals.WEIGHT_RARE,
        "pals: the drum's weights sum to the printed table")
    check(PocketPals.MACHINE_COST == 2 && PocketPals.MACHINE_LOC == "Mall",
        "pals: a pull is 2 capsule coins at the machine inside the Mall")
}
run {
    // ---------- the machine: poor, priced, counted, dupes ----------
    val s = freshState()
    val r0 = PocketPals.pull(s, Random(1))
    check(r0.status == "poor" && r0.card == null && PocketPals.pulls(s) == 0 &&
        PocketPals.totalCards(s) == 0,
        "pals machine: no coins, no pull, no counter tick")
    Minigames.awardCoins(s, 2)
    val r1 = PocketPals.pull(s, Random(1))
    check(r1.status == "ok" && r1.card != null && r1.card in PocketPals.MACHINE_POOL,
        "pals machine: 2 coins buys exactly one machine card")
    check(Minigames.capsuleCoins(s) == 0 &&
        (Minigames.COIN_ITEM !in s.inventory),
        "pals machine: the last 2 coins leave the pack empty")
    check(PocketPals.pulls(s) == 1 && PocketPals.totalCards(s) == 1,
        "pals machine: the pull and the card both count")
    // dupes allowed and counted: 300 seeded pulls, pigeonhole says repeat
    val s2 = freshState()
    Minigames.awardCoins(s2, 100000)
    val rnd = Random(42)
    repeat(300) { PocketPals.pull(s2, rnd) }
    check(PocketPals.pulls(s2) == 300 && PocketPals.totalCards(s2) == 300,
        "pals machine: 300 pulls = 300 cards in the binder (dupes counted)")
    check(PocketPals.CARDS.any { PocketPals.count(s2, it) >= 2 },
        "pals machine: dupes happen and stack")
    check(Minigames.capsuleCoins(s2) == 100000 - 600,
        "pals machine: the faucet charges exactly 2 a pull")
    // determinism: same seed, same drum
    val seqA = (1..50).map { PocketPals.roll(Random(7)).id }
    val seqB = (1..50).map { PocketPals.roll(Random(7)).id }
    // (fresh Random(7) each draw restarts the stream — compare streams properly)
    val ra = Random(7); val sa = (1..50).map { PocketPals.roll(ra).id }
    val rb = Random(7); val sb = (1..50).map { PocketPals.roll(rb).id }
    check(sa == sb && seqA.size == 50, "pals machine: a seeded drum repeats exactly")
    // distribution over the seeded drum + the exclusives NEVER roll
    val dist = Random(20261013)
    val n = 163400
    val byRarity = mutableMapOf<String, Int>()
    val byId = mutableMapOf<String, Int>()
    repeat(n) {
        val card = PocketPals.roll(dist)
        byRarity[card.rarity] = (byRarity[card.rarity] ?: 0) + 1
        byId[card.id] = (byId[card.id] ?: 0) + 1
    }
    val cShare = (byRarity[PocketPals.COMMON] ?: 0).toDouble() / n
    val uShare = (byRarity[PocketPals.UNCOMMON] ?: 0).toDouble() / n
    val rShare = (byRarity[PocketPals.RARE] ?: 0).toDouble() / n
    check(cShare in 0.845..0.870, "pals machine: commons land ~85.7% (got $cShare)")
    check(uShare in 0.122..0.143, "pals machine: uncommons land ~13.2% (got $uShare)")
    check(rShare in 0.008..0.014, "pals machine: rares land ~1.1% (got $rShare)")
    check(PocketPals.LOOK_CARDS.all { (byId[it.id] ?: 0) == 0 },
        "pals machine: the Look exclusives NEVER roll, in $n pulls")
    check(PocketPals.MACHINE_POOL.all { (byId[it.id] ?: 0) > 0 },
        "pals machine: every drum card comes up in $n pulls")
    check((byId[PocketPals.CHASE.id] ?: 0) > 0,
        "pals machine: the chase rare is pullable (rare, not mythical)")
}
run {
    // ---------- the Look exclusives ----------
    val s = freshState()
    check(PocketPals.lookText(s, "Mall") == null &&
        PocketPals.lookText(s, "KidsPark") == null,
        "pals look: other places give up nothing")
    val t1 = PocketPals.lookText(s, "StarksPond")
    check(t1 != null && t1.contains("Pondmother") &&
        PocketPals.count(s, PocketPals.cardById("pondmother")!!) == 1,
        "pals look: a careful Look under the dock finds the Pondmother")
    check(PocketPals.lookText(s, "StarksPond") == null,
        "pals look: the spot gives up its card exactly once")
    val t2 = PocketPals.lookText(s, "Elementary")
    check(t2 != null && PocketPals.count(s, PocketPals.cardById("pollenator")!!) == 1,
        "pals look: the playground garden holds the Pollenator")
    for (loc in LOCATIONS.keys - setOf("StarksPond", "Elementary"))
        check(PocketPals.lookText(s, loc) == null,
            "pals look: $loc hides no card")
    check(PocketPals.hintFor(PocketPals.cardById("pondmother")!!)
        .contains("under the dock at Stark's Pond"),
        "pals look: the album hint names the spot")
    check(PocketPals.hintFor(PocketPals.CHASE).contains("capsule machine"),
        "pals look: machine cards hint at the machine")
}
run {
    // ---------- errand thank-yous: sometimes a card ----------
    for (h in 0..20000)
        check(PocketPals.errandCard(h) in PocketPals.MACHINE_POOL,
            "pals errand: hash $h deals machine stock only")
    // find fabricated errand ids on both sides of the gate
    fun probeId(wantCard: Boolean): String {
        for (i in 0..100000) {
            val id = "palprobe$i"
            val h = id.hashCode() and 0x7fffffff
            if (h % 4 == 0 && ((h / 4) % PocketPals.ERRAND_CARD_EVERY == 0) == wantCard)
                return id
        }
        error("no probe id")
    }
    val sCard = freshState()
    val eCard = Errand(id = probeId(true), source = "BOARD", asker = "Stan",
        type = "FETCH", text = "probe", hint = "probe")
    sCard.errands += eCard
    val doneCard = Errands.complete(sCard, eCard)
    check(doneCard?.reward?.thankCard != null && doneCard.reward.thankItem == null,
        "pals errand: 1 in ${PocketPals.ERRAND_CARD_EVERY} thank-yous is a card, not an item")
    check(PocketPals.count(sCard, doneCard!!.reward.thankCard!!) == 1,
        "pals errand: the thank-you card lands in the binder")
    val sItem = freshState()
    val eItem = Errand(id = probeId(false), source = "BOARD", asker = "Stan",
        type = "FETCH", text = "probe", hint = "probe")
    sItem.errands += eItem
    val doneItem = Errands.complete(sItem, eItem)
    check(doneItem?.reward?.thankCard == null && doneItem?.reward?.thankItem != null,
        "pals errand: the other thank-yous stay items")
    // the pinned rate, counted over fabricated ids
    var thanks = 0; var cards = 0
    for (i in 0..20000) {
        val h = "rateprobe$i".hashCode() and 0x7fffffff
        if (h % 4 == 0) { thanks++; if ((h / 4) % PocketPals.ERRAND_CARD_EVERY == 0) cards++ }
    }
    check(thanks > 3000 && cards.toDouble() / thanks in 0.16..0.24,
        "pals errand: the card share of thank-yous is ~1/${PocketPals.ERRAND_CARD_EVERY} (got ${cards}/${thanks})")
}
run {
    // ---------- kids' stashes & valuation quirks ----------
    for (npc in AGENT_PROFILES.keys) {
        check(PocketPals.obsessionOf(npc) in PocketPals.SCHOOLS,
            "pals trade: $npc obsesses over a real school")
        check(PocketPals.obsessionOf(npc) == PocketPals.obsessionOf(npc),
            "pals trade: $npc's obsession is deterministic")
    }
    check(AGENT_PROFILES.keys.map { PocketPals.obsessionOf(it) }.toSet() ==
        PocketPals.SCHOOLS.toSet(),
        "pals trade: all four schools have an obsessive somewhere in the cast")
    for (week in 0..5) {
        val stash = PocketPals.stashFor("Cartman", week)
        check(stash.size == PocketPals.STASH_SIZE &&
            stash.toSet().size == PocketPals.STASH_SIZE,
            "pals trade: a weekly stash is ${PocketPals.STASH_SIZE} distinct cards (week $week)")
        check(stash == PocketPals.stashFor("Cartman", week),
            "pals trade: the same week shows the same stash (week $week)")
    }
    check((0..11).map { PocketPals.stashFor("Kyle", it) }.toSet().size > 6,
        "pals trade: stashes actually rotate week to week")
    check(PocketPals.valueOf(PocketPals.CHASE) == 9 &&
        PocketPals.valueOf(PocketPals.cardById("zippit")!!) == 1 &&
        PocketPals.valueOf(PocketPals.cardById("teslon")!!) == 3,
        "pals trade: values run 1 / 3 / 9 by rarity")
    val sparkFan = AGENT_PROFILES.keys.first { PocketPals.obsessionOf(it) == "Spark" }
    check(PocketPals.valueTo(sparkFan, PocketPals.CHASE) == 18 &&
        PocketPals.valueTo(sparkFan, PocketPals.cardById("pondmother")!!) == 9,
        "pals trade: the obsession school is worth double TO its fan")
}
run {
    // ---------- a trade, end to end ----------
    val s = freshState()
    val npc = "Stan"
    val stash = PocketPals.stashFor(npc, PocketPals.weekOf(s))
    // binder: dupes of everything except the stash cards (which Stan holds)
    for (card in PocketPals.CARDS) if (card !in stash)
        s.pocketPals[card.id] = 2
    val offer = PocketPals.tradeOffer(s, npc)
    check(offer != null, "pals trade: a stocked binder and a fresh stash make a trade")
    offer!!
    check(offer.get in stash && PocketPals.count(s, offer.get) == 0,
        "pals trade: they offer a stash card you lack")
    check(PocketPals.count(s, offer.give) >= 2,
        "pals trade: you offer a dupe, never your last copy")
    check(offer.give.school == PocketPals.obsessionOf(npc) || offer.give !in stash,
        "pals trade: they covet it — their school, or one their stash lacks")
    check(offer.delta in -PocketPals.TRADE_SWING_CAP..PocketPals.TRADE_SWING_CAP,
        "pals trade: the friendship swing is capped at ±${PocketPals.TRADE_SWING_CAP}")
    check(PocketPals.tradeOffer(s, "Nobody Real") == null,
        "pals trade: non-cast names never trade")
    val friendBefore = s.friendship[npc] ?: 0
    val done = PocketPals.executeTrade(s, npc)
    check(done == offer, "pals trade: the settled trade is the offered trade")
    check(PocketPals.count(s, offer.give) == 1 && PocketPals.count(s, offer.get) == 1,
        "pals trade: one-for-one — a dupe leaves, a new card lands")
    check((s.friendship[npc] ?: 0) ==
        (friendBefore + offer.delta).coerceIn(-50, 100),
        "pals trade: friendship moves by exactly the value gap")
    check(PocketPals.tradedThisWeek(s, npc) && PocketPals.tradeOffer(s, npc) == null,
        "pals trade: one trade per kid per week")
    s.absDay += 7
    check(!PocketPals.tradedThisWeek(s, npc),
        "pals trade: next week the binder opens again")
    check(PocketPals.declineLine(npc, s) == PocketPals.declineLine(npc, s) &&
        PocketPals.declineLine(npc, s).contains(npc),
        "pals trade: declining is free, funny, and deterministic")
}
run {
    // ---------- last-copy protection, both directions of bad luck ----------
    val s = freshState()
    for (card in PocketPals.CARDS) s.pocketPals[card.id] = 1
    for (npc in AGENT_PROFILES.keys) for (week in listOf(0, 3, 9)) {
        s.absDay = week * 7
        check(PocketPals.tradeOffer(s, npc) == null,
            "pals protection: a binder of single copies trades with nobody ($npc, week $week)")
    }
    // the only dupe is a card this kid already stashes and doesn't obsess over
    val s2 = freshState()
    var guarded = false
    for (npc in AGENT_PROFILES.keys) {
        val stash = PocketPals.stashFor(npc, 0)
        val dead = stash.firstOrNull {
            it.school != PocketPals.obsessionOf(npc) } ?: continue
        val missing = stash.firstOrNull { it != dead } ?: continue
        s2.pocketPals.clear()
        for (card in PocketPals.CARDS) s2.pocketPals[card.id] = 1
        s2.pocketPals[dead.id] = 2
        s2.pocketPals.remove(missing.id)
        check(PocketPals.tradeOffer(s2, npc) == null,
            "pals protection: a dupe they neither covet nor lack makes no trade ($npc)")
        guarded = true
        break
    }
    check(guarded, "pals protection: the uncoveted-dupe case was exercised")
    // the swing cap under maximum provocation, both signs
    var sawCapPos = false; var sawCapNeg = false
    for (npc in AGENT_PROFILES.keys) for (week in 0..30) {
        val st = freshState(); st.absDay = week * 7
        val stash = PocketPals.stashFor(npc, week)
        // you hold only a dupe of their obsession's rare; they stash commons
        for (card in PocketPals.CARDS) st.pocketPals.remove(card.id)
        val theirRare = PocketPals.RARES.firstOrNull {
            it.school == PocketPals.obsessionOf(npc) && it !in stash }
        val stashCommon = stash.firstOrNull { it.rarity == PocketPals.COMMON }
        if (theirRare != null && stashCommon != null) {
            for (card in PocketPals.CARDS)
                if (card != theirRare) st.pocketPals[card.id] = 1
            st.pocketPals[theirRare.id] = 2
            st.pocketPals.remove(stashCommon.id)
            val o = PocketPals.tradeOffer(st, npc)
            if (o != null && o.give == theirRare && o.get == stashCommon) {
                check(o.delta == PocketPals.TRADE_SWING_CAP,
                    "pals trade: a dream-card for a common still swings only +${PocketPals.TRADE_SWING_CAP}")
                sawCapPos = true
            }
        }
        // mirror: your only dupe is a common; their stash holds your missing rare
        val st2 = freshState(); st2.absDay = week * 7
        val stash2 = PocketPals.stashFor(npc, week)
        val stashRare = stash2.firstOrNull { it.rarity == PocketPals.RARE }
        val dupeCommon = PocketPals.CARDS.firstOrNull {
            it.rarity == PocketPals.COMMON && it !in stash2 }
        if (stashRare != null && dupeCommon != null) {
            for (card in PocketPals.CARDS) st2.pocketPals[card.id] = 1
            st2.pocketPals[dupeCommon.id] = 2
            st2.pocketPals.remove(stashRare.id)
            val o2 = PocketPals.tradeOffer(st2, npc)
            if (o2 != null && o2.get == stashRare) {
                check(o2.delta >= -PocketPals.TRADE_SWING_CAP,
                    "pals trade: even landing a rare costs at most -${PocketPals.TRADE_SWING_CAP}")
                if (o2.delta == -PocketPals.TRADE_SWING_CAP) sawCapNeg = true
            }
        }
    }
    check(sawCapPos, "pals trade: the +cap case was exercised")
    check(sawCapNeg, "pals trade: the -cap case was exercised")
}
run {
    // ---------- feats: derived, crossing exactly once ----------
    val s = freshState()
    check(PocketPals.PAL_FEATS.size == 2 &&
        PocketPals.PAL_FEATS.none { PocketPals.featEarned(s, it) },
