    PocketPals.grantCard(s, PocketPals.cardById("pondmother")!!, "test")
    PocketPals.grantCard(s, PocketPals.CHASE, "test")
    check(PocketPals.PAL_FEATS.none { PocketPals.featEarned(s, it) },
        "pals feats: two of three rares is not the crown")
    val crossed = PocketPals.grantCard(s, PocketPals.cardById("tanglewood")!!, "test")
    check(crossed == listOf("pal_rare_trio") &&
        PocketPals.featEarned(s, PocketPals.featById("pal_rare_trio")!!),
        "pals feats: the third rare crosses TRIPLE CROWN")
    check(s.events.any { it.contains("TRIPLE CROWN") },
        "pals feats: the crossing posts its ticker line")
    var fullCross: List<String> = emptyList()
    for (card in PocketPals.CARDS) {
        val c = PocketPals.grantCard(s, card, "test")
        if (c.isNotEmpty()) fullCross = c
    }
    check(fullCross == listOf("pal_full_set") &&
        PocketPals.featEarned(s, PocketPals.featById("pal_full_set")!!),
        "pals feats: the 24th distinct card crosses FULL SET!")
    check(PocketPals.grantCard(s, PocketPals.CHASE, "test").isEmpty(),
        "pals feats: a crossing is announced exactly once")
    // the count cap holds even at the grant rail
    val sCap = freshState()
    repeat(PocketPals.COUNT_CAP + 25) { PocketPals.grantCard(sCap, PocketPals.CHASE, "test") }
    check(PocketPals.count(sCap, PocketPals.CHASE) == PocketPals.COUNT_CAP,
        "pals feats: per-card counts cap at ${PocketPals.COUNT_CAP}")
}
run {
    // ---------- the album surface ----------
    val s = freshState()
    val lines = PocketPals.collectionLines(s)
    check(lines.first().contains("0/24") && lines.first().contains("0 machine pulls"),
        "pals album: the header counts an empty binder")
    check(lines.count { it.startsWith("⬜") } == 2,
        "pals album: both feats show unearned on a fresh town")
    for (card in PocketPals.CARDS)
        check(PocketPals.hintFor(card).isNotBlank(),
            "pals album: ${card.id} carries a hint for its silhouette")
}
run {
    // ---------- saves: one key, filtered, capped, additive ----------
    val s = freshState()
    s.pocketPals["aurorath"] = 3; s.pocketPals["zippit"] = 12
    s.life[PocketPals.PULLS_KEY] = 41
    val doc = encodeGameState(s)
    check(doc["pocketPals"] != null, "pals save: the binder rides its own key")
    val back = decodeGameState(Json.parse(Json.stringify(doc)) as Map<String, Any?>)
    check(back.pocketPals == mapOf("aurorath" to 3, "zippit" to 12),
        "pals save: counts round-trip exactly")
    check(PocketPals.pulls(back) == 41,
        "pals save: the pulls counter rides the life map")
    val inflated = decodeGameState(mapOf("pocketPals" to mapOf(
        "aurorath" to 5000L, "zippit" to -4L, "bogus_card" to 7L,
        "teslon" to "lots")))
    check(inflated.pocketPals == mapOf("aurorath" to PocketPals.COUNT_CAP),
        "pals save: decode caps per-card counts and drops invented cards")
    val old = decodeGameState(emptyMap())
    check(old.pocketPals.isEmpty() && PocketPals.pulls(old) == 0,
        "pals save: a v0.5.0b save loads with an empty binder")
}
run {
    // ---------- the lifetime: a seeded collector finishes ----------
    // Machine + Look + the whole town's weekly trading, driven
    // week by week. Asserts the faucet and the sink TOGETHER
    // can complete the set — and that no trade ever touches a
    // last copy on the way.
    val s = freshState()
    val rnd = Random(50503)
    PocketPals.lookText(s, "StarksPond")
    PocketPals.lookText(s, "Elementary")
    check(PocketPals.ownedCount(s) == 2, "pals lifetime: the Look pair opens the binder")
    var awarded = 0; var tradesDone = 0; var weeks = 0
    while (PocketPals.ownedCount(s) < 24 && weeks < 520) {
        s.absDay = weeks * 7 + 1
        Minigames.awardCoins(s, 60); awarded += 60
        while (Minigames.capsuleCoins(s) >= PocketPals.MACHINE_COST)
            PocketPals.pull(s, rnd)
        for (npc in AGENT_PROFILES.keys) {
            val offer = PocketPals.tradeOffer(s, npc) ?: continue
            check(PocketPals.count(s, offer.give) >= 2,
                "pals lifetime: no trade ever offers a last copy (week $weeks, $npc)")
            if (PocketPals.executeTrade(s, npc) != null) tradesDone++
        }
        weeks++
    }
    check(PocketPals.ownedCount(s) == 24,
        "pals lifetime: the seeded collector COMPLETES the set " +
            "(weeks=$weeks, pulls=${PocketPals.pulls(s)}, trades=$tradesDone)")
    check(tradesDone > 0, "pals lifetime: trades carried part of the set home")
    check(PocketPals.PAL_FEATS.all { PocketPals.featEarned(s, it) },
        "pals lifetime: both feats stand earned at the full set")
    check(Minigames.capsuleCoins(s) ==
        awarded - PocketPals.MACHINE_COST * PocketPals.pulls(s),
        "pals lifetime: every coin is accounted for — 2 a pull, nothing else spends")
    check(PocketPals.CARDS.all { PocketPals.count(s, it) >= 1 },
        "pals lifetime: the full set means every slot, not just the count")
}
run {
