private fun sectionV050d(root: String) {
// ================= v0.5.0d: Faction Missions =================
// Queue #5 item 4. Every faction runs one escalating 3-beat
// chain (errand -> scheme -> set piece), offered by a faction
// member through the Talk gate's new FACTION_MISSION rail and
// judged ENTIRELY by existing verbs (Talk/Give/Look/Photo/
// Catch/Showdown/Taco — the errand & holiday-beat rails).
// Beat 1 is open at any standing; beats 2/3 gate at the
// standingLabel thresholds (Liked 10 / Respected 30). Beat 3
// leaves a permanent derived mark (a SceneArt dressing token)
// plus a carried title, and costs RIVAL_COST with a named
// rival — RIVAL_OF is a perfect pairing, so no faction can
// ever lose more than RIVAL_COST to the whole system, and the
// lifetime soak below runs ALL EIGHT chains in one save.
// State: zero new save keys — two `life` entries per faction.
println("== v0.5.0d: Faction Missions — eight chains ==")
val eng = Engine(50504)
fun freshState(): GameState {
    val s = eng.newState()
    eng.createPlayer(s, "Envoy", DEFAULT_APPEARANCE)
    return s
}
fun chain(fid: String) = FactionMissions.CHAINS.first { it.factionId == fid }
fun beat(fid: String, n: Int) = chain(fid).beats[n - 1]
fun setStanding(s: GameState, fid: String, v: Int) {
    s.factionStates[fid]!!.playerStanding = v
}
/** Fast-forward the town's repeatable standing sources (the
 *  road pitch's +2 is the unit — Walk.firePoolBeat performs
 *  literally this clamped +2) until [target] is met. */
fun boostStanding(s: GameState, fid: String, target: Int) {
    var guard = 0
    while (FactionMissions.standingOf(s, fid) < target && guard++ < 500) {
        val fs = s.factionStates[fid]!!
        fs.playerStanding = (fs.playerStanding + 2).coerceIn(-50, 100)
    }
}
fun photoAt(locId: String) = PhotoRecord(
    id = "fm-photo", dayKey = "20261001", dateLabel = "10/1",
    timeMin = 720, locId = locId, inside = false,
    weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
    figures = emptyList())
/** Land an ARMED beat through its verb's real judge. */
fun landBeat(s: GameState, b: FactionBeat): Boolean = when (b.verb) {
    "TALK" -> FactionMissions.judgeTalk(s, b.targetNpc!!).any { it.beat == b }
    "GIVE" -> {
        s.inventory[b.itemId!!] = (s.inventory[b.itemId] ?: 0) + 1
        FactionMissions.onGive(s, b.targetNpc!!, b.itemId!!).any { it.beat == b }
    }
    "LOOK" -> {
        s.timeMin = if (b.minMin > 0) b.minMin else 720
        FactionMissions.lookText(s, b.locId!!) != null
    }
    "PHOTO" -> FactionMissions.onPhoto(s, photoAt(b.locId!!)).any { it.beat == b }
    "CATCH" -> FactionMissions.onCatch(s, b.fishId ?: "pond_smelt").any { it.beat == b }
    "SHOWDOWN" -> FactionMissions.onShowdown(s, true, b.targetNpc ?: "Stan")
        .any { it.beat == b }
    "TACO" -> FactionMissions.onTaco(s, b.tacoMin!!).any { it.beat == b }
    else -> false
}
run {
    // ---------- the chains: complete, ordered, real ----------
    check(FactionMissions.CHAINS.size == 8, "missions: exactly 8 chains")
    check(FactionMissions.CHAINS.map { it.factionId } == FACTIONS.map { it.id },
        "missions: one chain per faction, in faction order")
    check(FactionMissions.CHAINS.sumOf { it.beats.size } == 24,
        "missions: 8 chains x 3 beats = 24 beats")
    val allBeats = FactionMissions.CHAINS.flatMap { it.beats }
    check(allBeats.map { "${it.factionId}:${it.beat}" }.toSet().size == 24,
        "missions: every (faction, beat) pair is unique")
    for (ch in FactionMissions.CHAINS) {
        val f = FACTION_BY_ID[ch.factionId]!!
        check(ch.beats.map { it.beat } == listOf(1, 2, 3),
            "missions: ${ch.factionId} beats are numbered 1, 2, 3 in order")
        check(ch.markLoc in LOCATIONS && ch.markToken.isNotBlank() &&
            ch.markLabel.isNotBlank() && ch.playerTitle.isNotBlank() &&
            ch.title.isNotBlank(),
            "missions: ${ch.factionId} carries a named mark and title")
        for (b in ch.beats) {
            check(b.factionId == ch.factionId && b.verb in FactionMissions.VERBS,
                "missions: ${b.factionId} beat ${b.beat} is judged by a real verb (${b.verb})")
            check(b.offerNpc in f.members,
                "missions: ${b.factionId} beat ${b.beat} is offered by a faction member (${b.offerNpc})")
            check(b.offerNpc in KID_ORDER && b.title.isNotBlank() &&
                b.offerText.isNotBlank() && b.line.isNotBlank() &&
                b.short.isNotBlank() && b.hint.isNotBlank(),
                "missions: ${b.factionId} beat ${b.beat} is fully written")
            when (b.verb) {
                "TALK" -> check(b.targetNpc != null && b.targetNpc in KID_ORDER && b.targetNpc != b.offerNpc,
                    "missions: ${b.factionId} beat ${b.beat} TALKs to a real, different person")
                "GIVE" -> check(b.targetNpc != null && b.targetNpc in KID_ORDER &&
                    b.itemId != null && b.itemId in Errands.FETCH_POOL.toSet() &&
                    Errands.sourceOf(b.itemId!!) != null,
                    "missions: ${b.factionId} beat ${b.beat} GIVE item is real and obtainable (${b.itemId})")
                "LOOK", "PHOTO" -> check(b.locId != null && b.locId in LOCATIONS,
                    "missions: ${b.factionId} beat ${b.beat} ${b.verb} names a real place")
                "CATCH" -> check(b.fishId == null || fishById(b.fishId!!) != null,
                    "missions: ${b.factionId} beat ${b.beat} CATCH names a real species")
                "SHOWDOWN" -> check(b.targetNpc == null || b.targetNpc!! in KID_ORDER,
                    "missions: ${b.factionId} beat ${b.beat} SHOWDOWN opponent is real")
                "TACO" -> check(b.tacoMin in Errands.TACO_TARGETS,
                    "missions: ${b.factionId} beat ${b.beat} TACO target is a posted target")
            }
            check(b.minMin in 0 until b.maxMin && b.maxMin <= 1440,
                "missions: ${b.factionId} beat ${b.beat} time window is sane")
        }
    }
    // every verb in the registry is exercised by the chains
    check(allBeats.map { it.verb }.toSet() == FactionMissions.VERBS.toSet(),
        "missions: all seven existing verbs judge at least one beat")
    // marks: unique tokens, one per chain
    check(FactionMissions.MARK_TOKENS.size == 8 &&
        FactionMissions.CHAINS.map { it.markToken }.toSet().size == 8,
        "missions: eight distinct mark tokens")
    check(FactionMissions.CHAINS.map { it.playerTitle }.toSet().size == 8,
        "missions: eight distinct titles")
    // gates: named, monotonic, and the standingLabel thresholds
    check(FactionMissions.BEAT1_MIN_STANDING == -50 &&
        FactionMissions.BEAT2_MIN_STANDING == 10 &&
        FactionMissions.BEAT3_MIN_STANDING == 30,
        "missions: the gates are -50 / 10 / 30 (any / Liked / Respected)")
    check((1..3).map { FactionMissions.gateForBeat(it) } ==
        listOf(FactionMissions.BEAT1_MIN_STANDING,
            FactionMissions.BEAT2_MIN_STANDING, FactionMissions.BEAT3_MIN_STANDING) &&
        FactionMissions.BEAT1_MIN_STANDING < FactionMissions.BEAT2_MIN_STANDING &&
        FactionMissions.BEAT2_MIN_STANDING < FactionMissions.BEAT3_MIN_STANDING,
        "missions: gates are monotonic in the beat number")
    check(Factions.standingLabel(FactionMissions.BEAT2_MIN_STANDING) == "Liked" &&
        Factions.standingLabel(FactionMissions.BEAT3_MIN_STANDING) == "Respected",
        "missions: the gates ARE the standing labels' own thresholds")
    // rival pairing: an involution over all eight factions
    check(FactionMissions.RIVAL_OF.keys == FACTIONS.map { it.id }.toSet() &&
        FactionMissions.RIVAL_OF.values.toSet() == FACTIONS.map { it.id }.toSet(),
        "missions: every faction has exactly one rival and is exactly one's rival")
    for ((a, b) in FactionMissions.RIVAL_OF)
        check(FactionMissions.RIVAL_OF[b] == a && a != b,
            "missions: the rivalry $a <-> $b is mutual and never with itself")
    // beat 3's offer text telegraphs its rival cost, by name
    for (ch in FactionMissions.CHAINS) {
        val rivalName = FACTION_BY_ID[FactionMissions.RIVAL_OF[ch.factionId]]!!.name
        val shortName = rivalName.removePrefix("The ").substringBefore("'").substringBefore(" ")
        check(ch.beats[2].offerText.contains(shortName, ignoreCase = true),
            "missions: ${ch.factionId} beat 3 telegraphs its rival ($rivalName) in the offer")
    }
}
run {
    // ---------- offers: gates, arming, the silencing rule ----------
    val s = freshState()
    check(FactionMissions.offerFor(s, "Cartman") == beat("boys_crew", 1),
        "missions offer: beat 1 is offered at any standing, even 0")
    setStanding(s, "boys_crew", -50)
    check(FactionMissions.offerFor(s, "Cartman") == beat("boys_crew", 1),
        "missions offer: beat 1 is offered even at the standing floor")
    setStanding(s, "boys_crew", 0)
    check(FactionMissions.offerFor(s, "Kenny") == null,
        "missions offer: a member who doesn't front the beat offers nothing")
    check(!FactionMissions.accept(s, beat("boys_crew", 2)),
        "missions offer: beat 2 cannot be armed out of order")
    check(FactionMissions.accept(s, beat("boys_crew", 1)) &&
        FactionMissions.activeBeat(s, "boys_crew") == beat("boys_crew", 1),
        "missions offer: accepting the offer arms the beat")
    check(FactionMissions.offerFor(s, "Cartman") == null &&
        FactionMissions.offerFor(s, "Kyle") == null,
        "missions offer: while a beat is taken on, the faction offers nothing new")
    check(landBeat(s, beat("boys_crew", 1)),
        "missions offer: the armed GIVE beat lands through the gift rail")
    check(FactionMissions.activeBeat(s, "boys_crew") == null &&
        FactionMissions.beatsDone(s, "boys_crew") == 1,
        "missions offer: a landed beat disarms and records")
    // beat 2's gate: short standing = no offer, gate met = offer
    setStanding(s, "boys_crew", FactionMissions.BEAT2_MIN_STANDING - 1)
    check(FactionMissions.offerFor(s, "Kyle") == null,
        "missions offer: one point short of Liked, beat 2 waits")
    setStanding(s, "boys_crew", FactionMissions.BEAT2_MIN_STANDING)
    check(FactionMissions.offerFor(s, "Kyle") == beat("boys_crew", 2),
        "missions offer: at Liked, beat 2 is offered")
    // the silencing rule: a due finale mutes OFFERS, not work
    val sf = freshState()
    check(FactionMissions.accept(sf, beat("girls_circle", 1)),
        "missions silence: the girls' first beat arms in peacetime")
    sf.shenaniganId = Mystery.FINALE_ID
    sf.timeMin = 20 * 60
    for (c in Mystery.CLUES) sf.mysteryClues.add(c.id)
    check(Mystery.finaleChoiceDue(sf),
        "missions silence: the fabricated finale is genuinely due")
    check(Walk.caseCritical(sf) && FactionMissions.offerFor(sf, "Cartman") == null,
        "missions silence: while the finale is due, mission offers wait")
    check(TalkGate.gateFor(sf, "Cartman", "MainStreet").rail != TalkGate.Rail.FACTION_MISSION,
        "missions silence: the Talk gate agrees — no faction rail under a finale")
    check(FactionMissions.judgeTalk(sf, "Bebe").any { it.beat == beat("girls_circle", 1) },
        "missions silence: a beat already taken on still lands under a finale")
    sf.arcChoice = "truth"
    check(!Walk.caseCritical(sf) && FactionMissions.offerFor(sf, "Cartman") != null,
        "missions silence: once the choice is locked, offers speak again")
}
run {
    // ---------- the Talk gate: the new order, pinned ----------
    val s = freshState()
    // a fresh offer outranks a fresh errand ask from the same person
    val gOffer = TalkGate.gateFor(s, "Wendy", "Elementary")
    check(gOffer.rail == TalkGate.Rail.FACTION_MISSION &&
        gOffer.missionOffer == beat("girls_circle", 1) && gOffer.missionTalk == null,
        "missions gate: a faction offer rides the new rail (got ${gOffer.rail})")
    // an armed TALK beat for this person rides it as missionTalk
    check(FactionMissions.accept(s, beat("girls_circle", 1)), "missions gate: arm the girls' beat 1")
    val gTalk = TalkGate.gateFor(s, "Bebe", "Elementary")
    check(gTalk.rail == TalkGate.Rail.FACTION_MISSION &&
        gTalk.missionTalk == beat("girls_circle", 1) && gTalk.missionOffer == null,
        "missions gate: an armed TALK beat rides as the talk payload")
    check(FactionMissions.judgeTalk(s, "Bebe").size == 1,
        "missions gate: the talk judge lands it")
    // a delivery still masks faction business (Kyle fronts beat 2
    // of the Crew; Stan's parcel for Kyle settles first)
    val s2 = freshState()
    boostStanding(s2, "boys_crew", FactionMissions.BEAT2_MIN_STANDING)
    check(FactionMissions.accept(s2, beat("boys_crew", 1)) && landBeat(s2, beat("boys_crew", 1)),
        "missions gate: crew beat 1 lands (setup)")
    val parcel = Errand("fm-parcel", Errands.BOARD, "Stan", "DELIVER",
        "Take this to Kyle.", "He's around.", targetName = "Kyle", dayKey = s2.todayKey)
    check(Errands.accept(s2, parcel), "missions gate: the parcel sits on the plate (setup)")
    check(TalkGate.gateFor(s2, "Kyle", "MainStreet").rail == TalkGate.Rail.DELIVER,
        "missions gate: a delivery still settles before faction business")
    check(Errands.deliverTo(s2, "Kyle") != null, "missions gate: the parcel settles (setup)")
    val gAfter = TalkGate.gateFor(s2, "Kyle", "MainStreet")
    check(gAfter.rail == TalkGate.Rail.FACTION_MISSION &&
        gAfter.missionOffer == beat("boys_crew", 2),
        "missions gate: with the parcel gone, the faction offer surfaces")
    // and a today-only holiday step still outranks the chain:
    // Christmas, Cartman's relay step vs Cartman's beat-1 offer
    val s3 = freshState()
    s3.gameMonth = 12; s3.gameDay = 25; s3.todayKey = "20261225"; s3.holidayId = "christmas"
    s3.timeMin = 720
    check(HolidayBeats.talkStepFor(s3, "Cartman") != null,
        "missions gate: the relay step waits on Cartman (setup)")
    check(TalkGate.gateFor(s3, "Cartman", "MainStreet").rail == TalkGate.Rail.HOLIDAY_BEAT,
        "missions gate: the today-only holiday beat outranks the standing chain")
    // TalkGate's source keeps the pinned order legible.
    // The search is scoped to gateFor's own body: the file's
    // header essay legitimately names these APIs while
    // documenting them, and an unscoped indexOf measured the
    // essay instead of the order the function tries.
    val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val tgBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
    val iDeliver = tgBody.indexOf("Rail.DELIVER, delivery")
    val iHoliday = tgBody.indexOf("Rail.HOLIDAY_BEAT")
    val iFaction = tgBody.indexOf("Rail.FACTION_MISSION, missionTalk")
    val iAsk = tgBody.indexOf("Errands.pendingAsk")
    check(iDeliver in 0 until iHoliday && iHoliday < iFaction && iFaction < iAsk,
        "missions gate: gateFor tries DELIVER, HOLIDAY_BEAT, FACTION_MISSION, ERRAND_ASK in that order")
    check(!tgSrc.contains("Barks."), "missions gate: the bark rule survives — garnish is not a rail")
}
run {
