run {
    // ---------- standing math: capped, floored, never locking ----------
    val s = freshState()
    setStanding(s, "boys_crew", 0); setStanding(s, "girls_circle", 0)
    FactionMissions.applyCompletionStanding(s, beat("boys_crew", 1))
    check(FactionMissions.standingOf(s, "boys_crew") == FactionMissions.BEAT_STANDING[0] &&
        FactionMissions.standingOf(s, "girls_circle") == 0,
        "missions math: early beats pay their own faction and touch no rival")
    FactionMissions.applyCompletionStanding(s, beat("boys_crew", 3))
    check(FactionMissions.standingOf(s, "boys_crew") ==
        FactionMissions.BEAT_STANDING[0] + FactionMissions.BEAT_STANDING[2] &&
        FactionMissions.standingOf(s, "girls_circle") == -FactionMissions.RIVAL_COST,
        "missions math: beat 3 pays its faction and costs its rival exactly RIVAL_COST")
    // the floor holds under maximum provocation
    setStanding(s, "girls_circle", -50)
    FactionMissions.applyCompletionStanding(s, beat("boys_crew", 3))
    check(FactionMissions.standingOf(s, "girls_circle") == -50,
        "missions math: rival cost can never push standing below the -50 floor")
    setStanding(s, "boys_crew", 100)
    FactionMissions.applyCompletionStanding(s, beat("boys_crew", 3))
    check(FactionMissions.standingOf(s, "boys_crew") == 100,
        "missions math: rewards can never push standing above the 100 ceiling")
    // the lifetime bound: run every chain's standing math in
    // every order — no faction ever nets below -RIVAL_COST
    // from missions, and every chain's own beats alone carry
    // a player from that worst dip back past beat 2's gate
    // with the town's ordinary +2 pitches (three of them).
    for (fid in FACTIONS.map { it.id }) {
        val worst = -FactionMissions.RIVAL_COST // the pairing's whole cost, paid up front
        val afterB1 = worst + FactionMissions.BEAT_STANDING[0]
        check(afterB1 + 3 * 2 >= FactionMissions.BEAT2_MIN_STANDING,
            "missions math: $fid — worst dip + beat 1 + three road pitches clears beat 2's gate")
        val afterB2 = afterB1 + 3 * 2 + FactionMissions.BEAT_STANDING[1]
        check(afterB2 + 7 * 2 >= FactionMissions.BEAT3_MIN_STANDING,
            "missions math: $fid — the same arithmetic clears beat 3's gate without grinding")
    }
    check(FactionMissions.RIVAL_COST in 1..5 &&
        FactionMissions.BEAT_STANDING.all { it in 1..15 } &&
        FactionMissions.BEAT_COINS.all { it in 0..5 },
        "missions math: the dials stay small — cost ${FactionMissions.RIVAL_COST}, " +
            "standing ${FactionMissions.BEAT_STANDING}, coins ${FactionMissions.BEAT_COINS}")
    // standing is earnable through the town's real pipes, too:
    // befriending a member across a tier moves their faction
    val s2 = freshState()
    val before = FactionMissions.standingOf(s2, "boys_crew")
    eng.relAdjust(s2, "Butters", 60)
    check(FactionMissions.standingOf(s2, "boys_crew") > before,
        "missions math: friendship tier crossings still move faction standing (the grind exists)")
}
run {
    // ---------- marks & titles: derived, exact, permanent ----------
    val s = freshState()
    check(FactionMissions.markTokensByLoc(s).isEmpty() &&
        FactionMissions.titlesEarned(s).isEmpty(),
        "missions marks: a fresh town has no marks and no titles")
    boostStanding(s, "boys_crew", FactionMissions.BEAT3_MIN_STANDING)
    for (n in 1..2) {
        check(FactionMissions.accept(s, beat("boys_crew", n)) && landBeat(s, beat("boys_crew", n)),
            "missions marks: crew beat $n lands (setup)")
        check(FactionMissions.markTokensByLoc(s).isEmpty(),
            "missions marks: no mark stands before beat 3 (after beat $n)")
    }
    check(FactionMissions.accept(s, beat("boys_crew", 3)), "missions marks: the set piece arms")
    val hit = FactionMissions.onPhoto(s, photoAt("StarksPond")).firstOrNull()
    check(hit != null && hit.chainCompletedNow && hit.completionText != null &&
        hit.completionText!!.contains(chain("boys_crew").playerTitle),
        "missions marks: beat 3 completes the chain and names the title")
    check(FactionMissions.markTokensByLoc(s) == mapOf("StarksPond" to listOf("crew-flag")),
        "missions marks: exactly the crew flag stands, at the pond")
    check(FactionMissions.titlesEarned(s).any { it.contains(chain("boys_crew").playerTitle) },
        "missions marks: the title is carried after the chain")
    check(s.townLog.any { it.contains(chain("boys_crew").playerTitle) },
        "missions marks: the town log keeps the title too")
    // permanence: days pass, saves round-trip, the mark stands
    s.absDay += 30
    val doc = encodeGameState(s)
    val back = decodeGameState(Json.parse(Json.stringify(doc)) as Map<String, Any?>)
    check(FactionMissions.chainDone(back, "boys_crew") &&
        FactionMissions.markTokensByLoc(back) == FactionMissions.markTokensByLoc(s) &&
        FactionMissions.titlesEarned(back) == FactionMissions.titlesEarned(s),
        "missions marks: the mark and title survive a save round-trip a month later")
    // zero new save keys: the doc's key set gains NOTHING —
    // progress rides the pre-existing `life` map alone
    val freshDoc = encodeGameState(freshState())
    check(doc.keys == freshDoc.keys,
        "missions marks: the save doc carries no new keys (progress is in `life`)")
    check((doc["life"] as Map<*, *>).keys.any { it.toString().startsWith("fmMask:") },
        "missions marks: the chain mask rides the existing life map")
    val old = decodeGameState(emptyMap())
    check(FactionMissions.CHAINS.all { !FactionMissions.chainDone(old, it.factionId) } &&
        FactionMissions.markTokensByLoc(old).isEmpty(),
        "missions marks: a v0.5.0c save loads with every chain untouched")
    // the Journal page reads the whole arc of a chain
    val lines = FactionMissions.pageLines(s)
    check(lines.first().contains("1 of 8 chains"),
        "missions marks: the Journal header counts finished chains")
    check(lines.any { it.contains("The Great Pond Claim") && it.contains("DONE") },
        "missions marks: the finished chain reads DONE with its mark")
    check(lines.any { it.contains("The Conformist Census") && it.contains("Henrietta") },
        "missions marks: an untouched chain names its first offerer")
    // every mark token is drawn by the SceneArt mark layer
    val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    for (tok in FactionMissions.MARK_TOKENS)
        check(sceneSrc.contains("// fmark: $tok"),
            "missions marks: $tok is drawn by the mark layer")
    check(sceneSrc.contains("drawFactionMarkDetails") &&
        sceneSrc.contains("TownInfo.factionMarkTokens"),
        "missions marks: the mark layer runs in drawScene off TownInfo")
}
run {
    // ---------- the lifetime: all eight chains, one save ----------
    // Each chain in faction order: offer -> accept -> land,
    // topping standing up with the town's own +2 road pitches
    // between beats, exactly as a player between errands
    // would. Rival costs land as they land; nothing locks.
    val s = freshState()
    val coins0 = Minigames.capsuleCoins(s)
    for (ch in FactionMissions.CHAINS) {
        for (n in 1..3) {
            val b = ch.beats[n - 1]
            boostStanding(s, ch.factionId, FactionMissions.gateForBeat(n))
            check(FactionMissions.offerFor(s, b.offerNpc) == b,
                "missions lifetime: ${ch.factionId} beat $n is offered by ${b.offerNpc}")
            check(TalkGate.gateFor(s, b.offerNpc, "MainStreet").rail ==
                TalkGate.Rail.FACTION_MISSION,
                "missions lifetime: ${ch.factionId} beat $n rides the Talk gate")
            check(FactionMissions.accept(s, b),
                "missions lifetime: ${ch.factionId} beat $n is taken on")
            check(landBeat(s, b),
                "missions lifetime: ${ch.factionId} beat $n lands via ${b.verb}")
        }
        check(FactionMissions.chainDone(s, ch.factionId),
            "missions lifetime: ${ch.factionId}'s chain is complete")
    }
    check(FactionMissions.chainsDone(s) == 8,
        "missions lifetime: ALL EIGHT chains complete in one save")
    check(FactionMissions.markTokensByLoc(s).values.flatten().toSet() ==
        FactionMissions.MARK_TOKENS,
        "missions lifetime: all eight marks stand")
    check(FactionMissions.markTokensByLoc(s).keys ==
        FactionMissions.CHAINS.map { it.markLoc }.toSet(),
        "missions lifetime: the marks stand at their named locations")
    check(FactionMissions.titlesEarned(s).size == 8,
        "missions lifetime: all eight titles are carried")
    check(Minigames.capsuleCoins(s) - coins0 ==
        FactionMissions.CHAINS.size * FactionMissions.BEAT_COINS.sum(),
        "missions lifetime: every coin is accounted for — the beats paid their table")
    for (f in FACTIONS)
        check(FactionMissions.standingOf(s, f.id) >= -FactionMissions.RIVAL_COST,
            "missions lifetime: ${f.id}'s standing never fell past the one rival cost")
    // and the whole lifetime still fits the save budget
    val doc = encodeGameState(s)
    val json = Json.stringify(doc)
    check(json.length < 512 * 1024,
        "missions lifetime: the eight-chain save stays inside the 512K budget (${json.length} chars)")
    val back = decodeGameState(Json.parse(json) as Map<String, Any?>)
    check(FactionMissions.chainsDone(back) == 8 &&
        FactionMissions.markTokensByLoc(back) == FactionMissions.markTokensByLoc(s),
        "missions lifetime: the finished lifetime round-trips whole")
}
run {
    // ---------- wiring (source cross-checks) ----------
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("TalkGate.Rail.FACTION_MISSION") &&
