/** v0.5.0e section, extracted from main() like the others:
 *  new sections live in their own functions (64 KB rule). */
private fun sectionV050e(root: String) {
// ================= v0.5.0e: The Phone =================
// Queue #5 item 5. A hub (Phone.APPS) over the surfaces that
// already exist — Journal, its album + games sections, the
// Go Somewhere picker (routed back through GameActivity), and
// Settings — plus Messages: ambient texts generated by
// Phone.dailyRollover from noted facts (the event systems'
// hooks) and derived triggers (story beats, mystery motion,
// birthdays, holidays, weather, paced hellos). The contract
// under test: generation is deterministic per fact (a
// save/reload can NEVER reroll a text), senders follow the
// trigger's rules, every store cap holds forever, quick
// replies pay +1 under a daily cap and plant a "texting"
// topic thread, Kenny's texts are muffled but recoverable,
// and no template can leak a case/arc solution.
println("== v0.5.0e: The Phone — a hub, and Messages ==")
val engP = Engine(50505)
fun freshPhone(): GameState {
    val s = engP.newState()
    engP.createPlayer(s, "Texter", DEFAULT_APPEARANCE)
    return s
}
fun textsOf(s: GameState, trigger: String): List<PhoneText> =
    s.phoneTexts.filter { it.trigger == trigger }
run {
    // ---------- the hub registry ----------
    check(Phone.APPS.map { it.id } == listOf(
        "journal", "album", "map", "messages", "settings", "games",
        "play"),
        "phone: exactly seven tiles, in hub order (the " +
            "🎭 Play tile joined at v0.16.0e pass 2 — the " +
            "costume system's door)")
    check(Phone.appById("journal")?.target == "JournalActivity" &&
        Phone.appById("album")?.target == "JournalActivity#album" &&
        Phone.appById("games")?.target == "JournalActivity#games",
        "phone: Journal tiles target the real Journal and its sections")
    check(Phone.appById("map")?.target == "GameActivity:GoSomewhere" &&
        Phone.appById("messages")?.target == "PhoneActivity:messages" &&
        Phone.appById("settings")?.target == "SettingsActivity" &&
        Phone.appById("play")?.target == "FictionActivity",
        "phone: map/messages/settings/play tiles name their real routes")
    check(Phone.APPS.all { it.label.isNotBlank() },
        "phone: every tile is labeled")

    // ---------- hub routes resolve (source cross-checks) ----
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    check(File(srcDir, "JournalActivity.kt").exists() &&
        File(srcDir, "SettingsActivity.kt").exists() &&
        File(srcDir, "PhoneActivity.kt").exists(),
        "phone: every tile's activity exists on disk")
    val jSrc = File(srcDir, "JournalActivity.kt").readText()
    check(jSrc.contains("🎮 GAMES") && jSrc.contains("section == \"games\"") &&
        jSrc.contains("gamesAnchor"),
        "phone: the Journal resolves the #games route (anchor + extra)")
    check(jSrc.contains("section == \"album\""),
        "phone: the Journal still resolves the #album route")
    val paSrc = File(srcDir, "PhoneActivity.kt").readText()
    check(paSrc.contains("JournalActivity::class.java") &&
        paSrc.contains("SettingsActivity::class.java"),
        "phone: the hub launches the real Journal and Settings")
    check(paSrc.contains("putExtra(\"section\", \"album\")") &&
        paSrc.contains("putExtra(\"section\", \"games\")"),
        "phone: album/games tiles carry their section extras")
    check(paSrc.contains("setResult(RESULT_OK") &&
        paSrc.contains("putExtra(\"phone_route\", \"map\")"),
        "phone: the map tile hands its route back as a result")
