    run {
        // enviable pulls note; commons never do (dedupe-aware)
        val s = freshPhone()
        s.inventory[Minigames.COIN_ITEM] = 500
        val rnd = kotlin.random.Random(7)
        val notedNames = mutableSetOf<String>()
        var pulls = 0
        while (pulls < 200 && notedNames.size < 2) {
            val before = s.phoneNotes.count { it.contains("|${Phone.PULL}|") }
            val res = PocketPals.pull(s, rnd)
            pulls++
            check(res.status == "ok" && res.card != null,
                "phone: the machine deals while the purse holds")
            val card = res.card!!
            val after = s.phoneNotes.count { it.contains("|${Phone.PULL}|") }
            if (card.rarity != PocketPals.COMMON) {
                check(after == before + 1 &&
                    s.phoneNotes.any { it.contains("|${Phone.PULL}|${card.name}|") },
                    "phone: an enviable pull (${card.name}) notes itself")
                notedNames.add(card.name)
            } else {
                check(after == before,
                    "phone: a common pull (${card.name}) is beneath notice")
            }
        }
        check(notedNames.size >= 2,
            "phone: the machine dealt at least two enviable cards in $pulls pulls")
    }

    // ---------- determinism: same facts, same words ----------
    run {
        fun seeded(): GameState {
            val s = freshPhone()
            s.absDay = 10
            s.weatherId = "cloudy"
            s.friendship["Stan"] = 50
            s.friendship["Kyle"] = 50
            Phone.noteFeat(s, "📸 The Whole Squad")
            Phone.noteErrand(s, "Wendy")
            Phone.notePhoto(s, "Kyle", "StarksPond")
            s.absDay = 11
            return s
        }
        val a = seeded(); Phone.dailyRollover(a)
        val b = seeded(); Phone.dailyRollover(b)
        check(a.phoneTexts.isNotEmpty(), "phone: the seeded morning delivers")
        check(a.phoneTexts == b.phoneTexts,
            "phone: identical facts write identical texts")
        // a save/reload between the fact and the morning
        // cannot reroll the words
        val c0 = seeded()
        c0.absDay = 10
        val c = decodeGameState(encodeGameState(c0))
        c.absDay = 11
        Phone.dailyRollover(c)
        check(c.phoneTexts == a.phoneTexts,
            "phone: a save/reload cannot reroll a text")
    }

