    // ---------- hellos: paced, gated, deterministic ----------
    run {
        val s = freshPhone()
        s.weatherId = "cloudy"
        s.friendship["Butters"] = 90
        s.friendship["Stan"] = 90
        s.friendship["Kyle"] = 90
        val helloDays = mutableListOf<Pair<Int, String>>()
        var seen = 0
        for (day in 1..30) {
            s.absDay = day
            Phone.dailyRollover(s)
            val now = textsOf(s, Phone.HELLO)
            while (seen < now.size) {
                helloDays.add(day to now[seen].sender); seen++
            }
        }
        check(helloDays.isNotEmpty(),
            "phone: close friends do say hi within a month of mornings")
        check(helloDays.zipWithNext().all { (a, b) -> b.first - a.first >=
            Phone.HELLO_EVERY_DAYS },
            "phone: hellos pace themselves (${Phone.HELLO_EVERY_DAYS} days apart at least)")
        val bySender = helloDays.groupBy { it.second }
        check(bySender.values.all { days ->
            days.map { it.first }.zipWithNext()
                .all { (a, b) -> b - a >= Phone.HELLO_SENDER_GAP_DAYS } },
            "phone: the same friend waits ${Phone.HELLO_SENDER_GAP_DAYS} days between hellos")
        check(helloDays.all { it.second in setOf("Butters", "Stan", "Kyle") },
            "phone: only real friends hello — strangers stay silent")
        // acquaintances don't qualify
        val s2 = freshPhone()
        s2.weatherId = "cloudy"
        s2.friendship["Butters"] = Phone.HELLO_MIN_FRIENDSHIP - 1
        for (day in 1..30) {
            s2.absDay = day
            Phone.dailyRollover(s2)
        }
        check(textsOf(s2, Phone.HELLO).isEmpty(),
            "phone: below the friend tier, no unprompted hellos")
    }

    // ---------- Kenny: muffled, never erased ----------
    run {
        fun wordsOf(t: String): List<String> =
            t.lowercase().split(Regex("[^a-z0-9']+")).filter { it.isNotBlank() }
        val banks = listOf(Phone.FEAT_LINES, Phone.PHOTO_LINES_WITH,
            Phone.PHOTO_LINES_SOLO, Phone.ERRAND_LINES, Phone.PULL_LINES,
            Phone.STORY_LINES, Phone.STORY_DONE_LINES, Phone.MYSTERY_LINES,
            Phone.WEATHER_LINES, Phone.WEATHER_NICE_LINES,
            Phone.HOLIDAY_TODAY_LINES, Phone.HOLIDAY_SOON_LINES,
            Phone.BIRTHDAY_LINES, Phone.HELLO_LINES) +
            Phone.ACK_LINES.values.toList()
        var totalWords = 0
        var recovered = 0
        for (bank in banks) for (tpl in bank) {
            val filled = tpl.replace("{you}", "Texter").replace("{x}", "Aurorath")
            val out = Phone.kennyfy(filled)
            check(out.startsWith("mmph. "),
                "phone: Kenny's texts wear the muffle")
            check(out == out.lowercase(),
                "phone: Kenny types in muffled lowercase")
            val outWords = wordsOf(out).toSet()
            for (w in wordsOf(filled)) {
                totalWords++
                val mapped = Phone.KENNY_SUBS.firstOrNull { it.first == w }?.second ?: w
                if (mapped in outWords || w in outWords) recovered++
            }
        }
        check(totalWords > 400,
            "phone: the readability audit covers the whole bank ($totalWords words)")
        check(recovered.toDouble() / totalWords >= 0.97,
            "phone: Kenny's words survive the muffle " +
                "($recovered/$totalWords recoverable)")
        // and in generation, Kenny's own texts arrive muffled
        val s = freshPhone()
        s.absDay = 3
        Phone.noteErrand(s, "Kenny")
        s.absDay = 4
        Phone.dailyRollover(s)
        val kt = s.phoneTexts.single()
        check(kt.sender == "Kenny" && kt.text.startsWith("mmph. "),
            "phone: a text from Kenny is Kenny-typed")
    }

    // ---------- spoiler hygiene over banks + a lived year ---
    run {
        val deny = listOf("sleepwalk", "foil", "confiscat", "cameo",
            "strongbox", "communal", "dissolv", "redact", "owes you",
            "professor chaos", "alibi", "charter", "lease")
        val corpus = mutableListOf<String>()
        val banks = listOf(Phone.FEAT_LINES, Phone.PHOTO_LINES_WITH,
            Phone.PHOTO_LINES_SOLO, Phone.ERRAND_LINES, Phone.PULL_LINES,
            Phone.STORY_LINES, Phone.STORY_DONE_LINES, Phone.MYSTERY_LINES,
            Phone.WEATHER_LINES, Phone.WEATHER_NICE_LINES,
            Phone.HOLIDAY_TODAY_LINES, Phone.HOLIDAY_SOON_LINES,
            Phone.BIRTHDAY_LINES, Phone.HELLO_LINES) +
            Phone.ACK_LINES.values.toList()
        for (bank in banks) corpus.addAll(bank)
        // a lived year of mornings, every trigger family fed
        val s = freshPhone()
        s.weatherId = "cloudy"
        for (day in 1..365) {
            s.absDay = day
            Phone.noteFeat(s, "Feat of Day $day")
            if (day % 3 == 0) Phone.noteErrand(s, KID_ORDER[day % KID_ORDER.size])
            if (day % 5 == 0) Phone.notePhoto(s, KID_ORDER[(day * 3) % KID_ORDER.size],
                "StarksPond")
            if (day % 7 == 0) Phone.notePull(s, "Aurorath, the Storm That Stayed")
            if (day % 25 == 0) s.arcChapter = (s.arcChapter + 1).coerceAtMost(5)
            Phone.dailyRollover(s)
            check(s.phoneTexts.size <= Phone.MAX_TEXTS,
                "phone soak: the inbox never passes ${Phone.MAX_TEXTS} (day $day)")
            check(Phone.unreadCount(s) <= Phone.MAX_UNREAD,
                "phone soak: unread never passes ${Phone.MAX_UNREAD} (day $day)")
            check(s.phoneTexts.groupBy { it.thread }.values.all {
                it.size <= Phone.MAX_PER_THREAD },
                "phone soak: no thread passes ${Phone.MAX_PER_THREAD} (day $day)")
            check(s.phoneNotes.size <= Phone.MAX_NOTES,
                "phone soak: pending facts never pass ${Phone.MAX_NOTES} (day $day)")
            if (day % 7 == 0) for (t in s.phoneTexts) t.read = true
        }
        check((s.phoneMeta["seq"] ?: 0) > 150,
            "phone soak: the town kept texting all year " +
                "(${(s.phoneMeta["seq"] ?: 0)} texts delivered)")
        corpus.addAll(s.phoneTexts.map { it.text })
        for (line in corpus) {
            val low = line.lowercase()
            for (bad in deny) {
                check(bad !in low,
                    "phone hygiene: no template or text leaks \"$bad\"")
            }
        }
    }

