        stan.asleep = false
        s.npcGoals["Cartman"] = NpcGoal(
            npcKey = "Cartman", cycle = 0, kind = "SCHEME",
            text = "Currently: scheming", doneText = "Schemed.")
        check(Phone.statusLine(s, "Cartman").contains("probably scheming"),
            "phone: a live scheme flavors the status")
    }

    // ---------- caps: per-thread and whole-store ----------
    run {
        val s = freshPhone()
        for (i in 1..30) {
            s.phoneTexts.add(PhoneText(
                id = "t$i", thread = "Butters", sender = "Butters",
                trigger = Phone.HELLO, absDay = i, dayKey = "20261001",
                text = "text $i", read = i <= 15))
        }
        Phone.enforceCaps(s)
        val kept = Phone.threadTexts(s, "Butters")
        check(kept.size == Phone.MAX_PER_THREAD,
            "phone: a thread trims to ${Phone.MAX_PER_THREAD}")
        check(kept.first().id == "t11" && kept.last().id == "t30",
            "phone: trimming sheds the oldest read first, keeps the news")
        val s2 = freshPhone()
        val names = listOf("Stan", "Kyle", "Kenny", "Butters", "Wendy", "Craig", "Clyde", "Cartman", "Jimmy", "Tolkien", "Timmy", "Red")
        for (n in names) for (i in 1..19) {
            s2.phoneTexts.add(PhoneText(
                id = "$n-$i", thread = n, sender = n,
                trigger = Phone.HELLO, absDay = i, dayKey = "20261001",
                text = "text $i from $n", read = true))
        }
        Phone.enforceCaps(s2)
        check(s2.phoneTexts.size == Phone.MAX_TEXTS,
            "phone: the whole inbox trims to ${Phone.MAX_TEXTS}")
    }

    // ---------- saves: round-trip + hostile docs ----------
    run {
        val s = freshPhone()
        s.absDay = 3
        Phone.noteErrand(s, "Wendy")
        Phone.notePull(s, "Aurorath, the Storm That Stayed")
        s.absDay = 4
        Phone.dailyRollover(s)
        Phone.noteFeat(s, "Tomorrow's Feat")
        val back = decodeGameState(encodeGameState(s))
        check(back.phoneTexts == s.phoneTexts,
            "phone: texts round-trip the save whole")
        check(back.phoneNotes == s.phoneNotes,
            "phone: pending facts round-trip the save whole")
        check(back.phoneMeta == s.phoneMeta,
            "phone: the bookkeeping round-trips the save whole")
        // a hostile doc: 300 texts, bogus people, bogus kinds
        val doc = encodeGameState(freshPhone()).toMutableMap()
        val fake = (1..300).map { i ->
            mapOf<String, Any?>(
                "id" to "fake$i",
                "thread" to KID_ORDER[i % KID_ORDER.size],
                "sender" to KID_ORDER[i % KID_ORDER.size],
                "trigger" to "hello", "absDay" to 3, "day" to "20261004",
                "text" to "inflated text $i", "read" to (i % 2 == 0),
                "emoji" to "")
        } + listOf(
            mapOf<String, Any?>("id" to "ghost", "thread" to "Ghost",
                "sender" to "Ghost", "trigger" to "hello", "absDay" to 3,
                "day" to "20261004", "text" to "boo", "read" to false,
                "emoji" to ""),
            mapOf<String, Any?>("id" to "bogus", "thread" to "Stan",
                "sender" to "Stan", "trigger" to "bogus", "absDay" to 3,
                "day" to "20261004", "text" to "???", "read" to false,
                "emoji" to ""))
        doc["phone"] = mapOf(
            "texts" to fake,
            "notes" to listOf("1|bogus|x|", "2|feat|Real Feat|", "x|feat|F|"),
            "meta" to mapOf("seq" to 999999999))
        val clean = decodeGameState(doc)
        check(clean.phoneTexts.size <= Phone.MAX_TEXTS,
            "phone: an inflated inbox decodes under the cap")
        check(clean.phoneTexts.groupBy { it.thread }.values.all {
            it.size <= Phone.MAX_PER_THREAD },
            "phone: inflated threads decode under their cap")
        check(clean.phoneTexts.none { it.thread == "Ghost" ||
            it.trigger == "bogus" },
            "phone: unknown people and triggers are dropped on decode")
        check(clean.phoneNotes == listOf("2|feat|Real Feat|"),
            "phone: only well-formed facts survive decode")
        check(clean.phoneMeta["seq"] == 1_000_000,
            "phone: bookkeeping clamps on decode")
        // an old save (no phone key at all) loads silent
        val oldDoc = encodeGameState(freshPhone()).toMutableMap()
        oldDoc.remove("phone")
        val old = decodeGameState(oldDoc)
        check(old.phoneTexts.isEmpty() && old.phoneNotes.isEmpty(),
            "phone: yesterday's saves wake up to a silent phone")
    }

    // ---------- README ----------
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.5.0e"),
        "phone: the v0.5.0e changelog section exists")
}
}

/** v0.5.0f section: the figure pass — hair, hats & the seamless
 *  merge, a direct playtest correction from Lucky ("the hair is
 *  broken — make sure it covers the head correctly and works
 *  with the hats" + "make the independent shapes of the people
 *  seamlessly merged"). The renderer now paints HeadStack ink
 *  layers — pure shapes in CharacterSystem.kt — so this section
 *  rasterizes THOSE shapes with their own point tests and pins:
 *  (a) scanline solidity dome-to-torso, (b) hair-region samples
 *  against each sheet's hair region, (c) hat crowns with the
 *  under-brim hair rules, (d) seam bands at chin, hairline,
 *  brim and shoulder. */
private fun sectionV050f(root: String) {
// ================= v0.5.0f: hair, hats & the seamless merge =================
println("== v0.5.0f: hair, hats & the seamless merge ==")

    // ---- the model exists and the renderer paints it ----
    val kidSrc = File(root, "src/com/hunt3r/southparktown/KidArt.kt").readText()
    val charSrc = File(root, "src/com/hunt3r/southparktown/CharacterSystem.kt").readText()
    check(charSrc.contains("object HeadStack"),
        "figure: the head stack is pure data (HeadStack)")
    check(kidSrc.contains("HeadStack.layers(spec)") &&
        kidSrc.contains("InkKind.BEHIND_HAIR") &&
        kidSrc.contains("InkKind.HEAD") &&
        kidSrc.contains("InkKind.HAIR") && kidSrc.contains("InkKind.HAT"),
        "figure: KidArt paints the stack (behind/head/hair/hat)")
    check(!kidSrc.contains("private fun drawHair(") &&
        !kidSrc.contains("private fun drawHat(") &&
        !kidSrc.contains("private fun drawBehindHair("),
        "figure: the old pasted-on hair/hat draw paths are gone")
    check(HeadStack.HAIR_PAD > 0f && HeadStack.HAT_PAD > HeadStack.HAIR_PAD,
        "figure: hair rides proud of the head, hats prouder still")
    check(kidSrc.split("drawHead(c, spec, g").size - 1 == 2,
        "figure: both figure builders (all poses) route through the one merged head")

    // ---- raster helpers: the shapes' own point tests ----
    fun torsoPoly(spec: SheetSpec): PolyInk {
        val p = FigureGeometry.derive(spec).plan
        return PolyInk(listOf(
            FPt(50f - p.torsoHalfTop, p.torsoTop), FPt(50f, p.torsoTop - 2f),
            FPt(50f + p.torsoHalfTop, p.torsoTop),
            FPt(50f + p.torsoHalfBot, p.torsoBottom - 2f),
            FPt(50f - p.torsoHalfBot, p.torsoBottom - 2f)))
    }
    fun hatPalette(spec: SheetSpec): Set<String> = setOf(
        spec.hatColor, spec.hatAccent, darkerHex(spec.hatColor),
        "#f4f4f4", "#f0f0f0")

    // (a) scanline solidity: center + near-center scanlines run
    // from first ink to the torso's bottom with NO background
    // gap — head, hair, hat and torso read as one silhouette.
    // (Side scanlines assert solidity across the head's own
    // span; the jaw-to-shoulder notch is outline, not a gap.)
    fun scanlines(name: String, spec: SheetSpec) {
        val d = FigureGeometry.derive(spec)
        val torso = torsoPoly(spec)
        fun inked(x: Float, y: Float): Boolean =
            HeadStack.colorAt(spec, x, y) != null || torso.contains(x, y)
        for (fx in listOf(-0.2f, 0f, 0.2f)) {
            val x = d.hx + fx * d.hrx
            var started = false
            var gap = 0f
            var maxGap = 0f
            var y = d.hy - d.hry - 30f
            while (y <= d.plan.torsoBottom - 2f) {
                if (inked(x, y)) {
                    started = true; gap = 0f
                } else if (started) {
                    gap += 1.5f; if (gap > maxGap) maxGap = gap
                }
                y += 1.5f
            }
            check(started && maxGap <= 0.1f,
                "figure: $name scanline $fx is one merged silhouette (gap $maxGap)")
        }
        // side scanlines cover the head's own span (dome line
        // to chin line at that x): perched accessories above
        // the dome line are separate masses by design, but
        // INSIDE the head's span every sample must be inked
        for (fx in listOf(-0.75f, -0.45f, 0.45f, 0.75f)) {
            val x = d.hx + fx * d.hrx
            val root = Math.sqrt(1.0 - fx * fx.toDouble()).toFloat()
            val headTop = d.hy - d.hry * root
            val headBot = d.hy + d.hry * root
            var gappy = false
            var y = headTop + 0.5f
            while (y <= headBot) {
                if (HeadStack.colorAt(spec, x, y) == null) gappy = true
                y += 1.5f
            }
            check(!gappy,
                "figure: $name head-span scanline $fx has no sliver gaps")
        }
    }

    // (d) chin seam band: head bottom and torso top overlap —
    // the band between them is inked at every sample
    fun chinBand(name: String, spec: SheetSpec) {
        val d = FigureGeometry.derive(spec)
        val torso = torsoPoly(spec)
        val chinY = d.hy + d.hry
        for (fx in listOf(-0.3f, 0f, 0.3f)) {
            var ok = true
            var y = chinY - 3f
            while (y <= d.plan.torsoTop + 3f) {
                val x = d.hx + fx * d.hrx
                if (HeadStack.colorAt(spec, x, y) == null &&
                    !torso.contains(x, y)) ok = false
                y += 1f
            }
            check(ok, "figure: $name chin seam band at $fx is fully inked")
        }
    }

    // (d) shoulder seam: the sleeve's ROOT — just inside its
    // inner edge, a little below the anchor, in the arm's rest
    // tilt frame — is buried in the torso mass. The arms draw
    // BEFORE the torso, so the coat's edge cuts across the
    // sleeve: the root overlapping the torso is what makes
    // the junction one silhouette instead of a pinned-on arm
    fun shoulderTuck(name: String, spec: SheetSpec) {
        val d = FigureGeometry.derive(spec)
        val p = d.plan
        val torso = torsoPoly(spec)
        for (sd in listOf(-1f, 1f)) {
            val th = Math.toRadians((if (sd < 0) spec.armTilt else -spec.armTilt).toDouble())
            val cos = Math.cos(th).toFloat()
            val sin = Math.sin(th).toFloat()
            val ax = 50f + sd * p.shoulderX
            val ay = p.shoulderY
            val lx = -sd * p.armRad * 0.9f
            val ly = 2f
            val wx = ax + lx * cos - ly * sin
            val wy = ay + lx * sin + ly * cos
            check(torso.contains(wx, wy),
                "figure: $name sleeve root (side $sd) is buried in the torso")
        }
    }

    // (b) the dome arc, sampled just inside the head ellipse.
    // The CROWN arc (240-300) sits above every style's hairline
    // on every head: hair where the sheet wears hair, skin
    // where the sheet is bare (bald, Garrison's fringe). At
    // the TEMPLES the test samples decisively instead: one
    // point just above the style's own hairline at that x
    // (must be hair — the containment the old renderer
    // broke), one below it (must be the sheet's forehead,
    // except where frames/bands/the swoop's low side fall).
    // A hat may cover hair, never uncover it — hatted specs
    // are compared against their own hatless stack.
    fun arcChecks(name: String, spec: SheetSpec) {
        val d = FigureGeometry.derive(spec)
        val noHat = spec.copy(hatId = "none")
        val f = d.eyeT - 6f
        fun arcPt(deg: Float): Pair<Float, Float> {
            val a = Math.toRadians(deg.toDouble())
            return (d.hx + 0.97f * d.hrx * Math.cos(a).toFloat()) to
                (d.hy + 0.97f * d.hry * Math.sin(a).toFloat())
        }
        for (deg in listOf(240f, 255f, 270f, 285f, 300f)) {
            val (px, py) = arcPt(deg)
            val base = HeadStack.colorAt(noHat, px, py)
            val actual = HeadStack.colorAt(spec, px, py)
            check(actual != null, "figure: $name crown arc $deg is inked")
            if (spec.hatId == "none") {
                when {
                    spec.hairStyle == "bald" || spec.hairStyle == "fringe" ->
                        check(actual == spec.skin,
                            "figure: $name crown arc $deg reads skin (bare dome)")
                    spec.hairStyle == "curtains" && deg == 270f ->
                        check(actual == spec.skin || actual == spec.hairColor,
                            "figure: $name curtains part at the crown reads skin or hair")
                    else ->
                        check(actual == spec.hairColor,
                            "figure: $name crown arc $deg is hair-colored (got $actual)")
                }
            } else {
                check(actual != spec.skin || base == spec.skin,
                    "figure: $name crown arc $deg: the hat never bares the dome")
                check(actual == base || actual in hatPalette(spec),
                    "figure: $name crown arc $deg: only hair or hat above the head (got $actual)")
            }
        }
        if (spec.hatId != "none") {
            for (deg in listOf(195f, 210f, 330f, 345f)) {
                val (px, py) = arcPt(deg)
                val base = HeadStack.colorAt(noHat, px, py)
                val actual = HeadStack.colorAt(spec, px, py)
                check(actual != null, "figure: $name temple arc $deg is inked")
                check(actual != spec.skin || base == spec.skin,
                    "figure: $name temple arc $deg: the hat never bares the head")
                check(actual == base || actual in hatPalette(spec),
                    "figure: $name temple arc $deg: only hair or hat (got $actual)")
            }
            return
        }
        // no hat: temple points placed decisively — one deep in
        // the hair region (just above the style's own hairline
        // at that x), one below the hairline where the sheet
        // shows forehead. The hairline at the temple is the
        // sheet data each style was drawn from
        val deepDy = when (spec.hairStyle) {
            "ponytail", "bun", "pigtails", "braid", "beehive" -> 2f
            "curls" -> -1f
            "mop" -> -4f
            "messy" -> if (d.hry > 34f) -8f else -5f
            "shaggy" -> -4f
            "sidepart" -> -1f
            "spiky" -> 0f
            "bowl" -> 1f
            "swirl" -> -8f
            "swoop" -> -4f
            "curtains" -> -9f
            "fringeflick" -> -1f
            "afro" -> -2f
            else -> -6f
        }
        for (sd in listOf(-1f, 1f)) {
            val tx = d.hx + sd * d.hrx * 0.70f
            when (spec.hairStyle) {
                "bald" -> check(HeadStack.colorAt(spec, tx, f - 6f) == spec.skin,
                    "figure: $name bald temple (side $sd) is skin")
                "fringe" -> check(HeadStack.colorAt(spec,
                    d.hx + sd * d.hrx * 0.84f, d.hy) == spec.hairColor,
                    "figure: $name fringe band hugs the temple (side $sd)")
                "bob" -> check(HeadStack.colorAt(spec,
                    d.hx + sd * (d.hrx - 3f), d.hy + 2f) == spec.hairColor,
                    "figure: $name bob frame covers the temple (side $sd)")
                "buzz" -> check(HeadStack.colorAt(spec,
                    d.hx + sd * d.hrx * 0.60f,
                    (d.hy - d.hry) + d.hry * 0.40f - 6f) == spec.hairColor,
                    "figure: $name buzz crop covers its dome (side $sd)")
                "flattop" -> check(HeadStack.colorAt(spec,
                    d.hx + sd * d.hrx * 0.60f, f - 6f) == spec.hairColor,
                    "figure: $name flattop covers its dome (side $sd)")
                else -> check(HeadStack.colorAt(spec, tx, f + deepDy) ==
                    spec.hairColor,
                    "figure: $name hair covers the temple (side $sd)")
            }
            // below the hairline the sheet shows forehead —
            // except the frames (pinned by their own checks),
            // curtains' fall, the swoop's low side, and
            // Garrison's bands, which reach the jaw
            val below = HeadStack.colorAt(spec, tx, f + 8f)
            when {
                spec.hairStyle in listOf("bob", "long", "curtains",
                    "fringeflick") -> Unit
                spec.hairStyle == "fringe" ->
                    check(below == spec.hairColor,
                        "figure: $name fringe band reaches toward the jaw (side $sd)")
                spec.hairStyle == "swoop" && sd > 0 ->
                    check(below == spec.hairColor,
                        "figure: $name swoop's low side falls long")
                else ->
                    check(below == spec.skin,
                        "figure: $name below-hairline temple (side $sd) is skin (got $below)")
            }
        }
    }

    // (c) hat crowns + the signature under-brim rules
    fun hatChecks(name: String, spec: SheetSpec) {
        if (spec.hatId == "none" || spec.hatId.isEmpty()) return
        val d = FigureGeometry.derive(spec)
        val top = d.hy - d.hry
        val pal = hatPalette(spec)
        if (HeadStack.hatCoversHair(spec.hatId)) {
            check(HeadStack.colorAt(spec, d.hx, top - 1f) in pal,
                "figure: $name crown reads hat")
            val brimY = HeadStack.brimBottomCenter(spec.hatId, d) - 1f
            val bc = HeadStack.colorAt(spec, d.hx, brimY)
            check(bc in pal || bc == spec.hairColor,
                "figure: $name brim band is hat or the hair under it (got $bc)")
        }
        when (spec.hatId) {
            "beret", "yarmulke", "cowboy", "wizard", "crown",
            "chefhat", "taco_hat" ->
                check(HeadStack.colorAt(spec, d.hx, top - 1f) in pal,
                    "figure: $name perch crown reads hat")
            "earmuffs" ->
                check(HeadStack.colorAt(spec,
                    d.hx + d.hrx + 0.5f, d.hy + 2f) == spec.hatColor,
                    "figure: $name muff disc reads hat")
        }
        if (spec.hatId == "ushanka" || spec.hatId == "chullo") {
            check(HeadStack.colorAt(spec, d.hx + d.hrx + 1f, d.eyeT + 6f) ==
                spec.hatColor &&
                HeadStack.colorAt(spec, d.hx - d.hrx - 1f, d.eyeT + 6f) ==
                spec.hatColor,
                "figure: $name ear flaps cover the temples (no skin gap)")
        }
        if (spec.hatId in setOf("beanie", "pomhat", "cap", "mr_hat_cap",
                "mall_rat_cap", "trucker", "bandana", "santa_hat",
                "sleuth_cap") && spec.hairStyle != "bald") {
            val yT = HeadStack.brimBottomCenter(spec.hatId, d)
            check(HeadStack.colorAt(spec, d.hx + d.hrx * 0.92f, yT + 4.5f) ==
                spec.hairColor,
                "figure: $name keeps a temple tuft under the brim")
        }
    }

    // ---- every cast spec ----
    for ((name, spec) in KidArt.SHEETS) {
        if (spec.special == "towel") continue
        scanlines(name, spec)
        chinBand(name, spec)
        shoulderTuck(name, spec)
        if (spec.special == "kenny_parka") {
            val d = FigureGeometry.derive(spec)
            check(HeadStack.colorAt(spec, d.hx, d.hy - d.hry - 1f) == spec.top,
                "figure: Kenny's hood crowns the head in parka color")
            check(HeadStack.colorAt(spec, d.hx, d.eyeB + 2f) == "#460905",
                "figure: Kenny's face ring is the dark parka ring")
            continue
        }
        arcChecks(name, spec)
        hatChecks(name, spec)
    }

    // Wendy's beret + long hair: the locks frame the face OVER
    // the head's rim and fall behind the shoulders
    run {
        val w = KidArt.SHEETS["Wendy"]!!
        val d = FigureGeometry.derive(w)
        check(HeadStack.colorAt(w, d.hx - d.hrx * 0.86f,
            d.hy + d.hry * 0.3f) == w.hairColor,
            "figure: Wendy's front lock frames the face")
        val behind = HeadStack.layers(w).filter { it.kind == InkKind.BEHIND_HAIR }
        check(behind.any { it.shape.contains(d.hx - d.hrx - 0.5f,
            d.plan.torsoTop + 10f) },
            "figure: Wendy's hair falls behind her shoulders")
    }
    // long hair's dome: a real cap, not bare skin between locks
    // (sampled hatless — Wendy's beret owns her crown when worn)
    for (nm in listOf("Wendy", "Heidi", "Red", "Jesus")) {
        val sp = KidArt.SHEETS[nm]!!.copy(hatId = "none")
        val d = FigureGeometry.derive(sp)
        check(HeadStack.colorAt(sp, d.hx, d.hy - d.hry + 4f) == sp.hairColor,
            "figure: $nm long hair caps the dome")
    }
    // Pete's dyed tips hang below his fringe
    run {
        val sp = KidArt.SHEETS["Pete"]!!
        val d = FigureGeometry.derive(sp)
        check(HeadStack.colorAt(sp, d.hx - d.hrx + 44f,
            d.eyeT - 6f + 8f) == "#b03040",
            "figure: Pete's fringe tips are dyed")
    }
    // Sheila's hive sits on a cap — no skin gap at its base
    run {
        val sp = KidArt.SHEETS["Sheila"]!!
        val d = FigureGeometry.derive(sp)
        check(HeadStack.colorAt(sp, d.hx + d.hrx * 0.45f,
            d.hy - d.hry + 3f) == sp.hairColor,
            "figure: Sheila's beehive base is hair, not skin")
    }
    // Kyle's afro under the ushanka: the halo stays, the front
    // cap yields to the hat, temples belong to the flaps
    run {
        val sp = KidArt.SHEETS["Kyle"]!!
        val d = FigureGeometry.derive(sp)
        check(HeadStack.colorAt(sp, d.hx, d.hy - d.hry - 10f) == sp.hairColor,
            "figure: Kyle's afro halo rings the ushanka")
    }

    // ---- the under-brim fringe strip, where the sheet's
    // hairline dips below the brim ----
    run {
        val base = KidArt.SHEETS["Kyle"]!!.copy(
            hairColor = "#7a4a21", hatColor = "#31572c", hatAccent = "#e0a51f")
        val swoopCap = base.copy(hairStyle = "swoop", hatId = "cap")
        val sd = FigureGeometry.derive(swoopCap)
        check(HeadStack.colorAt(swoopCap, sd.hx + sd.hrx * 0.65f,
            HeadStack.brimBottomCenter("cap", sd) + 1.5f) == "#7a4a21",
            "figure: the swoop's low side keeps its fringe under a cap")
        val curtCap = base.copy(hairStyle = "curtains", hatId = "cap")
        val cd = FigureGeometry.derive(curtCap)
        check(HeadStack.colorAt(curtCap, cd.hx,
            HeadStack.brimBottomCenter("cap", cd) + 1f) == "#7a4a21",
            "figure: curtains keep a fringe strip under a cap")
        // spikes are part of the cap mass: a dome hat swallows them
        val spikeCap = base.copy(hairStyle = "spiky", hatId = "cap")
        val kd = FigureGeometry.derive(spikeCap)
        check(HeadStack.colorAt(spikeCap, kd.hx, kd.hy - kd.hry - 10f) != "#7a4a21",
            "figure: spikes never poke through a dome hat")
        // the Lorde wig option (a creator HAT) renders as a wig:
        // a bob frame in the hat color, the wearer's hair hidden
        val wig = avatarSpec(mapOf("hat" to "lorde_wig_opt"))
        val wd = FigureGeometry.derive(wig)
        check(HeadStack.colorAt(wig, wd.hx, wd.hy - wd.hry + 3f) == wig.hatColor,
            "figure: the Lorde wig crowns in its own color")
        check(HeadStack.layers(wig).none {
            it.kind == InkKind.HAIR && it.color == wig.hairColor },
            "figure: the wig replaces the wearer's hair")
    }

    // ---- creator hair x hat matrix on three bodies: the
    // unmeasured creator kid, a measured cast kid, a measured
    // cast adult — solidity + crown rules for every combo ----
    val hairOpts = CREATOR_OPTIONS["hair_style"]!!.second.map { it.id }
    val hatOpts = CREATOR_OPTIONS["hat"]!!.second.map { it.id }
    check(hairOpts.size >= 18 && hatOpts.size >= 18,
        "figure: the creator matrix covers the full option lists")
    val matrixBases = listOf(
        "creator" to avatarSpec(emptyMap()).copy(
            hairColor = "#7a4a21", hatColor = "#31572c", hatAccent = "#e0a51f"),
        "kid" to KidArt.SHEETS["Kyle"]!!.copy(
            hairColor = "#7a4a21", hatColor = "#31572c", hatAccent = "#e0a51f"),
        "adult" to KidArt.SHEETS["Randy"]!!.copy(
            hairColor = "#7a4a21", hatColor = "#31572c", hatAccent = "#e0a51f"))
    for ((baseName, base) in matrixBases) {
        for (hs in hairOpts) {
            for (ht in hatOpts) {
                val spec = base.copy(hairStyle = hs, hatId = ht)
                val nm = "$baseName/$hs/$ht"
                scanlines(nm, spec)
                val d = FigureGeometry.derive(spec)
                val top = d.hy - d.hry
                // the crown sample sits 1 unit above the head
                // for hat masses (their pads reach it), and just
                // under the crown line for bare heads and the
                // open perch hats — adult hairlines ride high
                // (messy's center bumps nearly reach the crown),
                // so the bare sample hugs the arc; the flattop's
                // flat sits 1 unit lower and keeps its own
                val crownHat = HeadStack.colorAt(spec, d.hx, top - 1f)
                val crownBare = HeadStack.colorAt(spec, d.hx,
                    top + if (hs == "flattop") 2f else 0.5f)
                when {
                    ht == "lorde_wig_opt" ->
                        check(crownHat == spec.hatColor,
                            "figure: $nm wig crowns in wig color")
                    HeadStack.hatCoversHair(ht) ->
                        check(crownHat in hatPalette(spec),
                            "figure: $nm covered crown reads hat")
                    hs == "curtains" && ht in listOf("none", "earmuffs", "headband") ->
                        check(crownBare == spec.skin || crownBare == spec.hairColor,
                            "figure: $nm the part reads skin or hair")
                    ht == "none" ->
                        check(crownBare == if (hs == "bald") spec.skin else spec.hairColor,
                            "figure: $nm bare crown")
                    ht == "earmuffs" ->
                        check(crownBare == if (hs == "bald") spec.skin else spec.hairColor,
                            "figure: $nm hair shows between the muffs")
                    ht == "headband" -> {
                        // (on a short adult head the band itself
                        // crosses the crown sample — hat color is
                        // an honest read there too)
                        check((crownBare ==
                            if (hs == "bald") spec.skin else spec.hairColor) ||
                            crownBare == spec.hatColor,
                            "figure: $nm hair crowns over the headband")
                        check(HeadStack.colorAt(spec, d.hx, d.eyeT - 9f) == spec.hatColor,
                            "figure: $nm the band itself reads hat")
                    }
                    else ->
                        check(crownHat in hatPalette(spec),
                            "figure: $nm perch crown reads hat")
                }
                if (hs == "bald" && HeadStack.hatCoversHair(ht)) {
                    val f = d.eyeT - 6f
                    check(HeadStack.colorAt(spec, d.hx, (top + f) / 2f) in
                        hatPalette(spec),
                        "figure: $nm dome hat owns the bald dome")
                }
            }
        }
    }

    // ---------- README ----------
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.5.0f"),
        "figure: the v0.5.0f changelog section exists")
}

private fun sectionV050g(root: String) {
// ================= v0.5.0g: scene depth — bands, foreground, crowd clusters =================
println("== v0.5.0g: scene depth pass ==")

    val sceneSrc = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    val interiorSrc = File(root, "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
    val gameSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    val photoSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()

    // ---- the layer stacks: bands as data ----
    fun bandOrder(layers: List<Depth.Layer>, label: String) {
        check(layers.zipWithNext().all { (a, b) -> a.band.ordinal <= b.band.ordinal },
            "depth: $label bands never decrease in draw order")
        check(layers.count { it.id == "figures" } == 1 &&
            layers.first { it.id == "figures" }.band == Band.MIDGROUND,
            "depth: $label has exactly one figures layer, and it is midground")
        check(layers.map { it.id }.distinct().size == layers.size,
            "depth: $label layer ids are unique")
        check(layers.first().band == Band.BACKGROUND &&
            layers.last().band == Band.FOREGROUND,
            "depth: $label opens on the background and closes on the foreground")
    }
    bandOrder(Depth.EXTERIOR_LAYERS, "exterior stack")
    bandOrder(Depth.INTERIOR_LAYERS, "interior stack")
    check(Depth.bandOfLayer("facade", false) == Band.BACKGROUND &&
        Depth.bandOfLayer("horizon", false) == Band.BACKGROUND,
        "depth: the location's own building and the neighbors share ONE background")
    check(Depth.bandOfLayer("props", true) == Band.BACKGROUND &&
        Depth.bandOfLayer("fixtures", true) == Band.MIDGROUND &&
        Depth.bandOfLayer("foreground", true) == Band.FOREGROUND,
        "depth: interior wall dressing is background, fixtures midground, near furniture foreground")
    check(Depth.EXTERIOR_LAYERS.first { it.id == "weather-particles" }.band ==
        Band.FOREGROUND,
        "depth: weather falls in the foreground, in front of the crowd")

    // ---- draw-order source pins: the renderers really do
    // paint in the registry's order, layer marker by marker ----
    fun chain(src: String, anchor: String, markers: List<String>, label: String) {
        var pos = src.indexOf(anchor)
        check(pos >= 0, "depth: $label anchor present ($anchor)")
        if (pos < 0) return
        for (m in markers) {
            val idx = src.indexOf(m, pos + 1)
            check(idx > pos, "depth: $label draw order — '$m' paints after the layer before it")
            if (idx < 0) return
            pos = idx
        }
    }
    chain(sceneSrc, "fun drawScene",
        Depth.EXTERIOR_LAYERS.takeWhile { it.id != "critters" }.map { it.marker },
        "SceneArt stack")
    chain(gameSrc, "override fun onDraw",
        Depth.EXTERIOR_LAYERS.dropWhile { it.id != "critters" }.map { it.marker },
        "GameView exterior stack")
    chain(interiorSrc, "fun drawRoom",
        Depth.INTERIOR_LAYERS.takeWhile { it.id != "home-props" }.map { it.marker },
        "InteriorArt stack")
    chain(gameSrc, "override fun onDraw",
        listOf("InteriorArt.drawRoom(", "drawHomeLifeProps(", "drawLivingInterior(",
            "drawArcadeCabinet(", "drawFigures(", "InteriorArt.drawForegroundLayer("),
        "GameView interior stack")
    chain(photoSrc, "override fun onDraw",
        listOf("drawBackdrop(", "drawFigures(", "drawForeground("),
        "PhotoView stack")
    check(photoSrc.contains("SceneArt.drawHorizon("),
        "depth: photos share the scene's Horizon background construction")
    check(photoSrc.contains("SceneArt.drawForegroundStrip(") &&
        photoSrc.contains("InteriorArt.drawForegroundStrip("),
        "depth: photos extend the same foreground painters, not a fork")

    // ---- the foreground registries ----
    check(LOC_FOREGROUND.keys == LOCATIONS.keys.toSet(),
        "depth: every location carries a foreground token")
    check(LOC_FOREGROUND.values.distinct().size == LOC_FOREGROUND.size,
        "depth: foreground tokens are unique per location")
    check(Depth.FOREGROUND_KINDS.keys == LOCATIONS.keys.toSet(),
        "depth: every location carries a foreground kind")
    check(LOC_FOREGROUND.values.all { sceneSrc.contains("// foreground: $it") },
        "depth: every foreground token is marked at the SceneArt painter")
    val themesUsed = INTERIORS.values.map { it.theme }.toSet()
    check(INTERIOR_FOREGROUND.keys == themesUsed,
        "depth: interior foreground covers exactly the themes in use")
    check(INTERIOR_FOREGROUND.values.distinct().size == INTERIOR_FOREGROUND.size,
        "depth: interior foreground tokens are unique per theme")
    check(Depth.INTERIOR_FOREGROUND_KINDS.keys == themesUsed,
        "depth: every theme carries an interior foreground kind")
    check(INTERIOR_FOREGROUND.values.all { interiorSrc.contains("// iforeground: $it") },
        "depth: every interior foreground token is marked at the InteriorArt painter")
    check(sceneSrc.contains("fun drawForegroundLayer(") &&
        sceneSrc.contains("fun drawForegroundStrip("),
        "depth: SceneArt owns the exterior foreground painters")
    check(interiorSrc.contains("fun drawForegroundLayer(") &&
        interiorSrc.contains("fun drawForegroundStrip("),
        "depth: InteriorArt owns the interior foreground painters")

    // ---- no token left bandless; no token double-claimed ----
    fun bandIs(tokens: Collection<String>, band: Band, label: String) {
        check(tokens.isNotEmpty() && tokens.all { Depth.tokenBand(it) == band },
            "depth: every $label token is banded $band")
    }
    bandIs(LOC_SILHOUETTES.values, Band.BACKGROUND, "silhouette")
    bandIs(LOC_ART_DETAILS.values.flatten(), Band.BACKGROUND, "parity")
    bandIs(LOC_SEASON_DETAILS.values.flatten(), Band.BACKGROUND, "season")
    bandIs(LOC_LIGHT_DETAILS.values.flatten(), Band.MIDGROUND, "light")
    bandIs(Mystery3.DIG_TOKENS, Band.BACKGROUND, "dig")
    bandIs(Mystery4.FIX_TOKENS, Band.BACKGROUND, "fix")
    bandIs(FactionMissions.MARK_TOKENS, Band.BACKGROUND, "faction-mark")
    bandIs(INTERIOR_ART_DETAILS.values.flatten(), Band.BACKGROUND, "interior-detail")
    bandIs(INTERIORS.values.flatMap { it.props }.toSet(), Band.BACKGROUND, "interior-prop")
    bandIs(LOC_FOREGROUND.values, Band.FOREGROUND, "foreground")
    bandIs(INTERIOR_FOREGROUND.values, Band.FOREGROUND, "interior-foreground")
    val registrySets = listOf(
        LOC_SILHOUETTES.values.toSet(),
        LOC_ART_DETAILS.values.flatten().toSet(),
        LOC_SEASON_DETAILS.values.flatten().toSet(),
        LOC_LIGHT_DETAILS.values.flatten().toSet(),
        Mystery3.DIG_TOKENS.toSet(),
        Mystery4.FIX_TOKENS.toSet(),
        FactionMissions.MARK_TOKENS.toSet(),
        Capstones.MARK_TOKENS.toSet(),
        INTERIOR_ART_DETAILS.values.flatten().toSet(),
        INTERIORS.values.flatMap { it.props }.toSet(),
        LOC_FOREGROUND.values.toSet(),
        INTERIOR_FOREGROUND.values.toSet(),
        Fair.FAIR_TOKENS.toSet())
    check(registrySets.sumOf { it.size } == Depth.TOKEN_BANDS.size,
        "depth: no token is claimed by two registries (the band map lost none)")

    // ---- the occlusion budget: geometry, not taste ----
    check(Depth.FG_TOP_OUT > Depth.FRONT_FEET_OUT &&
        Depth.FG_TOP_OUT < Depth.FRONT_FEET_OUT + 0.045f,
        "depth: the outdoor strip starts just below the front row's feet")
    check(Depth.FG_TOP_IN > Depth.FRONT_FEET_IN &&
        Depth.FG_TOP_IN < Depth.FRONT_FEET_IN + 0.045f,
        "depth: the indoor strip starts just below the front row's feet")
    check(Depth.FG_TOP_OUT - Depth.worstChin(Depth.FRONT_FEET_OUT) >= 0.15f,
        "depth: the outdoor strip clears the worst possible chin by >= 0.15 of the scene")
    check(Depth.FG_TOP_IN - Depth.worstChin(Depth.FRONT_FEET_IN) >= 0.15f,
        "depth: the indoor strip clears the worst possible chin by >= 0.15 of the scene")
    val measured = KidArt.SHEETS.values.mapNotNull { it.measured }
    check(measured.isNotEmpty() &&
        measured.maxOf { it.heightRel } <= Depth.FIG_SCALE_MAX,
        "depth: FIG_SCALE_MAX covers the tallest measured sheet in the cast")
    check(measured.minOf { it.headShare } >= Depth.HEAD_SHARE_MIN,
        "depth: HEAD_SHARE_MIN floors the smallest measured head share in the cast")
    check(gameSrc.contains("h * 0.205f") && Depth.FH_BASE_MAX == 0.205f,
        "depth: FH_BASE_MAX is the figure layout's real height cap")

    // ---- crowds: the pure layout, pinned hard ----
    check(Crowds.CLUSTER_MIN_TOTAL == 7,
        "crowd: the clustering threshold is named — 7 or more present")
    check(Crowds.rowsFor(5) == 1 && Crowds.rowsFor(10) == 2 &&
        Crowds.rowsFor(16) == 3 && Crowds.rowsFor(17) == 4,
        "crowd: row counts match the classic layout's")
    val emptyChem = Crowds.Chem()
    check(Crowds.layout((1..6).map { "N$it" }, emptyChem) == null,
        "crowd: under the threshold there is no crowd layout (classic spread runs)")
    val ab = setOf("A", "B")
    check(Crowds.affinity("A", "B", Crowds.Chem(scriptPairs = setOf(ab))) ==
        Crowds.SCRIPT_AFFINITY,
        "crowd: a pair script is the strongest pull")
    check(Crowds.affinity("A", "B", Crowds.Chem(rivalPairs = setOf(ab))) < 0,
        "crowd: arch-rivals block each other")
    check(Crowds.affinity("A", "B", Crowds.Chem(rivalPairs = setOf(ab),
        scriptPairs = setOf(ab))) > 0,
        "crowd: a scripted double act outranks the grudge")
    check(Crowds.affinity("A", "B", Crowds.Chem(bond = mapOf(ab to 10))) == 30,
        "crowd: bonds pull at 3x")
    check(Crowds.affinity("A", "B", Crowds.Chem(
        factionOf = mapOf("A" to "crew", "B" to "crew"))) == Crowds.FACTION_AFFINITY,
        "crowd: same faction pulls a little")

    // the invariant harness: every fabricated crowd must keep
    // everyone placed once, clusters legal, centers separated,
    // members consecutive, mirrors facing inward
    fun assertLayout(names: List<String>, chem: Crowds.Chem, label: String) {
        val l1 = Crowds.layout(names, chem)
        val l2 = Crowds.layout(names, chem)
        check(l1 != null && l1 == l2, "crowd: $label — layout exists and is deterministic")
        if (l1 == null) return
        check(l1.placed.map { it.name }.sorted() == names.sorted(),
            "crowd: $label — everyone placed exactly once")
        check(l1.rows <= Crowds.rowsFor(names.size),
            "crowd: $label — rows never exceed the classic layout's count")
        val groups = l1.placed.filter { it.clusterId >= 0 }.groupBy { it.clusterId }
        check(groups.values.all { it.size in 2..Crowds.CLUSTER_MAX },
            "crowd: $label — cluster sizes are 2..${Crowds.CLUSTER_MAX}")
        check(groups.values.all { g -> g.map { it.frontness }.distinct().size == 1 },
            "crowd: $label — a cluster never splits across rows")
        var sepOk = true
        var contigOk = true
        for ((_, row) in l1.placed.groupBy { it.frontness }) {
            val byX = row.sortedBy { it.xFrac }
            for (i in 1 until byX.size) {
                if (byX[i].xFrac - byX[i - 1].xFrac < Crowds.MIN_SEP - 0.0001f) sepOk = false
            }
            for ((_, members) in byX.filter { it.clusterId >= 0 }
                .groupBy { it.clusterId }) {
                val idxs = members.map { byX.indexOf(it) }
                if (idxs.max() - idxs.min() != members.size - 1) contigOk = false
            }
        }
        check(sepOk, "crowd: $label — centers never closer than MIN_SEP in a row")
        check(contigOk, "crowd: $label — cluster members stand consecutive in their row")
        check(l1.placed.all { it.xFrac >= 0.03f - 0.0001f &&
            it.xFrac <= 0.97f + 0.0001f },
            "crowd: $label — everyone stands inside the classic margins")
        var mirrorOk = true
        for ((_, members) in groups) {
            val byX = members.sortedBy { it.xFrac }
            byX.forEachIndexed { rank, m ->
                if (m.mirror != (rank * 2 > byX.size - 1)) mirrorOk = false
            }
        }
        check(mirrorOk && l1.placed.filter { it.clusterId < 0 }.all { !it.mirror },
            "crowd: $label — right-of-center members turn inward, loners never mirror")
    }
    for (total in 7..24) {
        val names = (1..total).map { "Kid%02d".format(it) }
        assertLayout(names, emptyChem, "empty-$total")
        val bonds = mutableMapOf<Set<String>, Int>()
        for (i in names.indices) for (j in i + 1 until names.size) {
            val v = (i * 7 + j * 13) % 23 - 4
            if (v > 0) bonds[setOf(names[i], names[j])] = v
        }
        assertLayout(names, Crowds.Chem(bond = bonds), "bonds-$total")
    }
    // the cast chemistry matrix: EVERY pair-script pair,
    // dropped into a crowd of strangers, finds each other
    for (pair in PAIR_SCRIPTS.keys) {
        if (pair.size != 2) continue
        val a = pair.first(); val b = pair.last()
        val names = listOf(a, b) + (1..6).map { "Filler$it" }
        val lay = Crowds.layout(names,
            Crowds.Chem(scriptPairs = setOf(pair)))
        val pa = lay?.placed?.first { it.name == a }
        val pb = lay?.placed?.first { it.name == b }
        check(pa != null && pb != null && pa.clusterId >= 0 &&
            pa.clusterId == pb.clusterId,
            "crowd: script pair $a + $b clusters together in a stranger crowd")
    }
    // rivals, however friendly the room, never share a huddle —
    // unless the script says the rivalry IS the act
    run {
        val names = listOf("A", "B") + (1..6).map { "F$it" }
        val bonds = mutableMapOf<Set<String>, Int>()
        for (i in names.indices) for (j in i + 1 until names.size) {
            bonds[setOf(names[i], names[j])] = 20
        }
        val layR = Crowds.layout(names, Crowds.Chem(bond = bonds,
            rivalPairs = setOf(ab)))
        val ra = layR?.placed?.first { it.name == "A" }
        val rb = layR?.placed?.first { it.name == "B" }
        check(ra != null && rb != null &&
            (ra.clusterId < 0 || ra.clusterId != rb.clusterId),
            "crowd: arch-rivals never share a cluster, however friendly the room")
        val layS = Crowds.layout(names, Crowds.Chem(bond = bonds,
            rivalPairs = setOf(ab), scriptPairs = setOf(ab)))
        val sa = layS?.placed?.first { it.name == "A" }
        val sb = layS?.placed?.first { it.name == "B" }
        check(sa != null && sb != null && sa.clusterId >= 0 &&
            sa.clusterId == sb.clusterId,
            "crowd: a scripted rival pair still clusters (the grudge is the act)")
        val layB = Crowds.layout(listOf("A", "B") + (1..5).map { "F$it" },
            Crowds.Chem(bond = mapOf(ab to 15)))
        val ba = layB?.placed?.first { it.name == "A" }
        val bb = layB?.placed?.first { it.name == "B" }
        check(ba != null && bb != null && ba.clusterId >= 0 &&
            ba.clusterId == bb.clusterId,
            "crowd: a high-bond pair clusters")
    }
    // the whole cast at once, real chemistry
    run {
        val castNames = KidArt.SHEETS.keys.toList()
        val rivals = mutableSetOf<Set<String>>()
        for (a in castNames) for (b in castNames) {
            if (a < b && relationNote(a, b) == "arch-rivals") rivals.add(setOf(a, b))
        }
        assertLayout(castNames, Crowds.Chem(
            scriptPairs = PAIR_SCRIPTS.keys.toSet(),
            rivalPairs = rivals, factionOf = FACTION_OF_CAST), "full-cast")
    }
    check(gameSrc.contains("Crowds.layout(") &&
        gameSrc.contains("Crowds.CLUSTER_MIN_TOTAL"),
        "crowd: GameView routes crowds at the named threshold through Crowds")
    check(gameSrc.contains("PaperTap.resolve(items"),
        "crowd: figure taps resolve to the nearest center " +
            "(clusters stay tappable) — v0.15.0c re-pin: the " +
            "rule lives in PaperTap now and GameView routes " +
            "every tap through it")

    // ---------- README ----------
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.5.0g"),
        "depth: the v0.5.0g changelog section exists")
}

private fun sectionV050h(root: String) {
// ================= v0.5.0h: season finales =================
// Every season ends with a set-piece: a 7-day finale week
// (the season's last 7 days by the game's own boundaries)
// with an ensemble gathering, four judged beats, a closing
// call on the last day, and a standing mark that lasts until
// the same season next year. Pure module (Finales.kt) on the
// life/lifeText maps; the Engine opens/wraps it in the
// rollover, the daily roll pre-empts to it, and its call
// defers while any case climax is on the table.
println("== v0.5.0h: season finales ==")

    val eng = Engine(50508)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Finalist", DEFAULT_APPEARANCE)
        return s
    }
    fun dated(s: GameState, key: String) {
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun win(key: String): Finales.FinaleWindow? {
        val s = freshState(); dated(s, key); return Finales.windowAt(s)
    }

    // ---------- the registry: one finale per season, whole ----------
    check(Finales.DEFS.size == 4, "finales: exactly four finales ship")
    check(Finales.DEFS.map { it.season }.toSet() == Season.values().toSet(),
        "finales: one per season — spring, summer, fall, winter")
    check(Finales.DEFS.map { it.id }.distinct().size == 4,
        "finales: ids are distinct")
    check(Finales.DEFS.map { it.decorId }.distinct().size == 4,
        "finales: each season's decor piece is its own")
    val decorById = House.DECOR.associateBy { it.id }
    val interiorSrc = File(root,
        "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
    for (def in Finales.DEFS) {
        val tag = "finales[${def.id}]"
        check(def.host in def.ensemble, "$tag: the host is in their own ensemble")
        check(def.ensemble.all { it in KID_ORDER } && def.ensemble.size >= 6,
            "$tag: the ensemble is real cast, six or more (${def.ensemble})")
        check(def.loc in LOCATIONS, "$tag: the gathering place exists (${def.loc})")
        check(def.steps.size == 4, "$tag: four judged beats pace the week")
        check(def.steps.all { it.verb in setOf("TALK", "LOOK", "PHOTO") },
            "$tag: every beat is judged by a verb the player already has")
        check(def.steps.all { it.dayFrom in 0..6 && it.dayTo in it.dayFrom..6 },
            "$tag: every beat's day range lives inside the 7-day window")
        check(def.steps.first().dayFrom == 0 && def.steps.first().verb == "TALK" &&
            def.steps.first().who == def.host && def.steps.first().loc == def.loc,
            "$tag: the week opens with the host, at the place, on day one")
        check(def.steps.count { it.verb == "PHOTO" } <= 1,
            "$tag: at most one photo beat per finale")
        for (step in def.steps) {
            if (step.verb == "TALK") check(step.who in def.ensemble,
                "$tag: talk beat '${step.title}' belongs to the ensemble (${step.who})")
            if (step.verb != "TALK") check(step.loc == def.loc,
                "$tag: beat '${step.title}' happens at the finale's place")
            check(step.line.isNotBlank() && step.short.isNotBlank() &&
                step.title.isNotBlank(),
                "$tag: beat '${step.title}' has a title, a line and a ticker")
        }
        check(def.choices.size == 2 &&
            def.choices.map { it.key }.distinct().size == 2,
            "$tag: the closing call is a real choice — two distinct sides")
        check(def.townChoice in def.choices.indices,
            "$tag: the town's fallback call exists")
        check(def.choices.all { it.markText.isNotBlank() && it.outcome.isNotBlank() &&
            it.winner.isNotBlank() && it.label.isNotBlank() && it.pickLine.isNotBlank() },
            "$tag: both calls carry an outcome, a mark and a credited winner")
        check(def.townOutcome.isNotBlank() && def.absentOutcome.isNotBlank() &&
            def.intro.isNotBlank() && def.hint.isNotBlank() &&
            def.closingCall.isNotBlank() && def.gatherActivity.isNotBlank(),
            "$tag: town and absent endings are written, and so are the notices")
        check(def.ambient.keys.all { it in def.ensemble },
            "$tag: ambient lines belong to the ensemble")
        check(decorById[def.decorId] != null,
            "$tag: the decor piece '${def.decorId}' is registered in House.DECOR")
        check(interiorSrc.contains("decor: ${decorById[def.decorId]?.token}"),
            "$tag: the decor token '${decorById[def.decorId]?.token}' is drawn in the room")
    }

    // ---------- the window math: the season's last 7 days ----------
    check(win("20270524") == null && win("20270601") == null,
        "finales: spring's window is bounded — May 24 and Jun 1 are ordinary days")
    check(win("20270525")?.let { it.def.id == "spring" && it.dayIndex == 0 &&
        it.instanceYear == 2027 } == true,
        "finales: spring opens May 25 (day 1 of 7)")
    check(win("20270531")?.dayIndex == 6,
        "finales: spring's last day is May 31 (day 7 of 7)")
    check(win("20270825")?.let { it.def.id == "summer" && it.dayIndex == 0 } == true &&
        win("20270831")?.dayIndex == 6 && win("20270901") == null,
        "finales: summer's window is Aug 25–31")
    check(win("20261123") == null &&
        win("20261124")?.let { it.def.id == "autumn" && it.dayIndex == 0 &&
            it.instanceYear == 2026 } == true &&
        win("20261130")?.dayIndex == 6 && win("20261201") == null,
        "finales: fall's window is Nov 24–30, endpoints included")
    check(win("20270221") == null &&
        win("20270222")?.let { it.def.id == "winter" && it.dayIndex == 0 &&
            it.instanceYear == 2027 } == true &&
        win("20270228")?.dayIndex == 6 && win("20270301") == null,
        "finales: winter's window is Feb 22–28 in a common year, and its " +
            "instance year is the February's, not the December's")
    check(win("20280223")?.let { it.def.id == "winter" && it.dayIndex == 0 &&
        it.instanceYear == 2028 } == true &&
        win("20280229")?.dayIndex == 6 && win("20280301") == null,
        "finales: in a leap year winter's window slides to Feb 23–29")
    check(win("20261231") == null && win("20270115") == null &&
        win("20261225") == null && win("20261001") == null,
        "finales: deep winter and the year turn are NOT a finale window — " +
            "the season's last week is February's, by the game's own boundaries")
    check(Finales.seasonEndMonthDay(Season.WINTER, 2028) == (2 to 29) &&
        Finales.seasonEndMonthDay(Season.WINTER, 2027) == (2 to 28) &&
        Finales.seasonEndMonthDay(Season.FALL, 2026) == (11 to 30),
        "finales: season ends — Feb 29 leap / Feb 28 common / Nov 30")

    // ---------- state reads are capped against the registry ----------
    run {
        val s = freshState(); dated(s, "20270531")
        val spring = Finales.defById("spring")!!
        s.life["fin:spring:2027:start"] = 5
        s.life["fin:spring:2027:mask"] = 0xFFFF
        check(Finales.stepsDone(s, spring, 2027) == 4,
            "finales: an inflated mask is capped to the beats that exist")
        s.life["fin:spring:2027:choice"] = 99
        check(Finales.choiceIndex(s, spring, 2027) == -1 && Finales.choiceDue(s),
            "finales: an inflated choice reads as no choice at all — it " +
                "can't fake a locked call, and the real one is still due")
        s.life["finRuns:spring"] = 5000
        check(Finales.runs(s, spring) == 999,
            "finales: lifetime counters are capped too")
    }

    // ---------- the call: due only on the last day, only for a player ----------
    run {
        val s = freshState(); dated(s, "20270531")
        val spring = Finales.defById("spring")!!
        s.life["fin:spring:2027:start"] = 5
        check(!Finales.choiceDue(s),
            "finales: the call is NOT due for a player who caught nothing — " +
                "the town will handle it")
        s.life["fin:spring:2027:mask"] = 1
        check(Finales.choiceDue(s) && Finales.choiceDef(s) == spring,
            "finales: one caught beat earns the call on the last day")
        check(!Finales.choose(s, "not-a-choice"),
            "finales: an unknown call is refused")
        check(Finales.choose(s, "butters") &&
            Finales.choiceIndex(s, spring, 2027) == 1,
            "finales: the call locks in")
        check(!Finales.choiceDue(s) && !Finales.choose(s, "sharon"),
            "finales: a locked call can't be re-called")
        val early = freshState(); dated(early, "20270530")
        early.life["fin:spring:2027:start"] = 5
        early.life["fin:spring:2027:mask"] = 1
        check(!Finales.choiceDue(early),
            "finales: day 6 of 7 is too early — the call waits for the last day")
    }

    // ---------- the wraps: three branches, three endings ----------
    run {
        val spring = Finales.defById("spring")!!
        // the player's call
        val s = freshState(); dated(s, "20270601")
        s.life["fin:spring:2027:start"] = 5
        s.life["fin:spring:2027:mask"] = 0b1111
        s.life["fin:spring:2027:choice"] = 2
        Finales.dailyRollover(s)
        val mark = Finales.markOf(s, spring)
        check(Finales.isWrapped(s, spring, 2027) &&
            mark?.winner == "Butters" && mark.byYou && mark.year == 2027 &&
            mark.text == spring.choices[1].markText,
            "finales: the player's call leaves THEIR mark, credited to them")
        check(Finales.playedCount(s, spring) == 1 && Finales.runs(s, spring) == 1,
            "finales: a played finale counts as played, and as run")
        check((s.friendship["Sharon"] ?: 0) == 3 &&
            (s.friendship["Butters"] ?: 0) == 4 &&
            (s.friendship["Randy"] ?: 0) == 2 &&
            (s.friendship["Cartman"] ?: 0) == 0,
            "finales: the wrap pays the host +3, the ensemble +2, and the " +
                "winner +2 more — nobody outside the ensemble is paid")
        check("finale_garden" in House.decorFor(s),
            "finales: a played spring earns the Garden Verdict Ribbon")
        // the town's call (played, never called)
        val t = freshState(); dated(t, "20270601")
        t.life["fin:spring:2027:start"] = 5
        t.life["fin:spring:2027:mask"] = 0b0011
        Finales.dailyRollover(t)
        val tMark = Finales.markOf(t, spring)
        check(tMark?.winner == "Sharon" && !tMark.byYou &&
            Finales.playedCount(t, spring) == 1,
            "finales: played but uncalled — the town makes its call, " +
                "and the week still counts as played")
        check((t.friendship["Sharon"] ?: 0) == 5,
            "finales: the town's winner still gets the winner's +2 (host +3, winner +2)")
        // the absent ending (never showed)
        val a = freshState(); dated(a, "20270601")
        a.life["fin:spring:2027:start"] = 5
        Finales.dailyRollover(a)
        check(Finales.isWrapped(a, spring, 2027) &&
            Finales.playedCount(a, spring) == 0 && Finales.runs(a, spring) == 1 &&
            (a.friendship["Sharon"] ?: 0) == 0 &&
            Finales.markOf(a, spring)?.byYou == false &&
            "finale_garden" !in House.decorFor(a),
            "finales: an ignored finale wraps WITHOUT the player — the town " +
                "marks the 'you weren't there' outcome, no friendship, no decor")
        check(a.events.any { it.contains(spring.absentOutcome.take(40)) } ||
            a.townLog.any { it.contains("Garden Verdict") },
            "finales: even the absent ending is on the record")
        // never even opened (the blocked-all-week case): quiet wrap
        val u = freshState(); dated(u, "20270601")
        Finales.dailyRollover(u)
        check(Finales.isWrapped(u, spring, 2027) && Finales.runs(u, spring) == 1 &&
            u.episodes.none { it.kind == "finale" && it.eventId == "spring" },
            "finales: an unopened week still wraps and marks — quietly, " +
                "with no episode for a week that never aired")
    }

    // ---------- deferral: a case climax owns the morning ----------
    run {
        val s = freshState(); dated(s, "20270525")
        s.timeMin = 800 // afternoon: a case's climax stage
        s.shenaniganId = Mystery.FINALE_ID
        s.mysteryClues.addAll(Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES).map { it.id })
        check(Mystery.finaleChoiceDue(s) && Finales.climaxPending(s),
            "finales: (fabrication) the case's climax is genuinely due")
        Finales.dailyRollover(s)
        val spring = Finales.defById("spring")!!
        check(!Finales.isOpened(s, spring, 2027) && Finales.activeWindow(s) == null &&
            s.episodes.none { it.kind == "finale" },
            "finales: the finale does NOT open while a case climax is on " +
                "the table — two player-facing climaxes never stack")
        s.shenaniganId = null
        check(!Finales.climaxPending(s), "finales: the table is clear")
        dated(s, "20270526")
        Finales.dailyRollover(s)
        check(Finales.isOpened(s, spring, 2027) && Finales.activeWindow(s) != null,
            "finales: the next clear morning, the finale opens — deferred, " +
                "not cancelled, and its beats' ranges have the slack for it")
    }

    // ---------- pre-emption: the daily roll stands down in-window ----------
    run {
        val engF = Engine(777)
        val inWin = engF.newState()
        engF.createPlayer(inWin, "Window", DEFAULT_APPEARANCE)
        dated(inWin, "20261123"); inWin.eventsThisMonth = 0
        check(Finales.suppressesDailyRoll(inWin) == false,
            "finales: Nov 23 is outside the window — no suppression")
        engF.onNewDay(inWin) // → Nov 24, the autumn window's first day
        check(inWin.todayKey == "20261124" && Finales.suppressesDailyRoll(inWin),
            "finales: Nov 24 IS the window (calendar truth, opened or not)")
        check(inWin.shenaniganId == null,
            "finales: the forced daily roll (a dry month, day ≥ 20) is " +
                "pre-empted in the window — the finale IS the week's episode")
        check(Finales.isOpened(inWin, Finales.defById("autumn")!!, 2026),
            "finales: and the finale itself opened through the real rollover")
        val outWin = engF.newState()
        engF.createPlayer(outWin, "Control", DEFAULT_APPEARANCE)
        dated(outWin, "20261119"); outWin.eventsThisMonth = 0
        engF.onNewDay(outWin) // → Nov 20, same forced setup, no window
        check(outWin.shenaniganId != null,
            "finales: (control) the same forced setup fires a daily episode " +
                "outside the window — the suppression is the window's doing")
    }

    // ---------- the gathering: ensemble presence by override ----------
    run {
        val s = freshState(); dated(s, "20270525")
        val spring = Finales.defById("spring")!!
        s.life["fin:spring:2027:start"] = 5
        val noon = 12 * 60
        check(Finales.gatheringBlock(s, "Sharon", noon)?.location == "KidsPark" &&
            Finales.gatheringBlock(s, "Butters", noon)?.location == "KidsPark",
            "finales: on the opening day the ensemble is AT the garden plot")
        check(Finales.gatheringBlock(s, "Cartman", noon) == null,
            "finales: the gathering is the ENSEMBLE — Cartman is not summoned")
        check(Finales.gatheringBlock(s, "Sharon", 400) == null &&
            Finales.gatheringBlock(s, "Sharon", 19 * 60) == null,
            "finales: the gathering keeps gathering hours (9:00–18:00)")
        dated(s, "20270527")
        check(Finales.gatheringBlock(s, "Sharon", noon) == null,
            "finales: mid-week, the ensemble goes back to their lives — no override")
        dated(s, "20270531")
        check(Finales.gatheringBlock(s, "Sharon", noon)?.location == "KidsPark",
            "finales: the closing day gathers them again")
        val block = Engine(1).effectiveAgendaBlock(s, s.agents["Sharon"]!!, noon)
        check(block?.location == "KidsPark" && block.activity == spring.gatherActivity,
            "finales: the Engine's agenda lookup really applies the override")
    }

    // ---------- the Talk gate: FINALE below the holiday beat, above the chains ----------
    run {
        val talkSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        val gateBody = talkSrc.substring(talkSrc.indexOf("fun gateFor"))
        val iDel = gateBody.indexOf("Rail.DELIVER")
        val iHb = gateBody.indexOf("Rail.HOLIDAY_BEAT")
        val iFin = gateBody.indexOf("Rail.FINALE")
        val iFm = gateBody.indexOf("Rail.FACTION_MISSION")
        val iAsk = gateBody.indexOf("Errands.pendingAsk")
        check(0 <= iDel && iDel < iHb && iHb < iFin && iFin < iFm && iFm < iAsk,
            "finales: gate order inside gateFor is DELIVER → HOLIDAY_BEAT → " +
                "FINALE → FACTION_MISSION → ERRAND_ASK")
        val s = freshState(); dated(s, "20270525")
        s.life["fin:spring:2027:start"] = 5
        s.agents["Sharon"]!!.location = "KidsPark"
        check(TalkGate.gateFor(s, "Sharon", "KidsPark").rail == TalkGate.Rail.FINALE,
            "finales: the host with a live beat gates to FINALE")
        val hit = Finales.judgeTalk(s, "Sharon")
        check(hit != null && hit.stepIndex == 0 &&
            Finales.stepsDone(s, Finales.defById("spring")!!, 2027) == 1,
            "finales: the conversation lands the opening beat")
        check(Finales.talkStepFor(s, "Sharon") == null &&
            TalkGate.gateFor(s, "Sharon", "KidsPark").rail != TalkGate.Rail.FINALE,
            "finales: with the beat landed, the finale no longer claims her gate")
        // a pending delivery still outranks the finale
        val s2 = freshState(); dated(s2, "20270525")
        s2.life["fin:spring:2027:start"] = 5
        s2.agents["Sharon"]!!.location = "KidsPark"
        val errand = Errand(id = "fin-test-deliver", source = "ASK",
            asker = "Kyle", type = "DELIVER",
            text = "Take this to Sharon, would you?",
            hint = "Sharon's expecting it.", targetName = "Sharon",
            dayKey = s2.todayKey)
        check(Errands.accept(s2, errand), "finales: (fabrication) delivery plated")
        check(TalkGate.gateFor(s2, "Sharon", "KidsPark").rail == TalkGate.Rail.DELIVER,
            "finales: a bag in hand still beats the finale — DELIVER outranks it")
        // ambient: the ensemble talks about the week, once a day each
        val line = Finales.ambientLine(s2, "Sharon")
        check(line != null && line.speaker == "Sharon",
            "finales: the host references the finale in conversation")
        check(Finales.ambientLine(s2, "Sharon") == null,
            "finales: once a day — the reference doesn't nag")
        check(Finales.ambientLine(s2, "Cartman") == null,
            "finales: non-ensemble members have no finale lines")
    }

    // ---------- notices: the morning report announces open + close ----------
    run {
        val s = freshState(); dated(s, "20270525")
        s.absDay = 236
        s.life["fin:spring:2027:start"] = 237 // opened this morning
        val note = Finales.morningNote(s)
        check(note != null && note.contains("finale week opens") &&
            note.contains("Great Garden Verdict"),
            "finales: the opening morning is announced")
        check(House.morningReport(s, emptyList(), emptyMap(), 0, false, null)
            .any { it.contains("finale week opens") },
            "finales: the announcement rides the bed's real morning report")
        dated(s, "20270531"); s.absDay = 242
        val closeNote = Finales.morningNote(s)
        check(closeNote != null && closeNote.contains("last day") &&
            closeNote.contains("handed down"),
            "finales: the closing morning carries the summons")
        dated(s, "20270527"); s.absDay = 238
        check(Finales.morningNote(s) == null,
            "finales: mid-week mornings are quiet — two notices per finale")
    }

    // ---------- marks persist; next year opens with a callback ----------
    run {
        val spring = Finales.defById("spring")!!
        val s = freshState(); dated(s, "20270601")
        s.life["fin:spring:2027:start"] = 5
        s.life["fin:spring:2027:mask"] = 0b1111
        s.life["fin:spring:2027:choice"] = 2 // Butters, by your call
        Finales.dailyRollover(s)
        check(Finales.markOf(s, spring)?.winner == "Butters",
            "finales: (setup) 2027's mark credits Butters")
        dated(s, "20280525")
        Finales.dailyRollover(s)
        check(Finales.isOpened(s, spring, 2028),
            "finales: the finale returns next year")
        check(s.events.any { it.contains("SERGEANT SPROUT") },
            "finales: the opening acknowledges the standing mark — " +
                "last year's winner gets their callback")
        check(Finales.markOf(s, spring)?.year == 2027,
            "finales: the old mark stands until THIS year's week wraps")
        dated(s, "20280601")
        Finales.dailyRollover(s)
        val newMark = Finales.markOf(s, spring)
        check(newMark?.year == 2028 && newMark.winner == "Sharon" && !newMark.byYou,
            "finales: the ignored return wraps absent, and the town's new " +
                "mark replaces the old one")
        check(Finales.runs(s, spring) == 2 && Finales.playedCount(s, spring) == 1,
            "finales: two years run, one of them played")
    }

    // ---------- saves: the whole machine round-trips ----------
    run {
        val s = freshState(); dated(s, "20270827")
        val summer = Finales.defById("summer")!!
        s.life["fin:summer:2027:start"] = 9
        s.life["fin:summer:2027:mask"] = 0b0101
        s.lifeText["finMark:spring"] = "a fabricated mark"
        s.life["finMarkYear:spring"] = 2027
        s.lifeText["finMarkBy:spring"] = "you"
        s.lifeText["finMarkWinner:spring"] = "Butters"
        val back = decodeGameState(encodeGameState(s))
        check(Finales.mask(back, summer, 2027) == 0b0101 &&
            Finales.isOpened(back, summer, 2027),
            "finales: live instance state survives the save round-trip")
        check(Finales.markOf(back, Finales.defById("spring")!!) ==
            Finales.markOf(s, Finales.defById("spring")!!),
            "finales: standing marks survive the save round-trip, whole")
    }

    // ---------- the Journal page ----------
    run {
        val s = freshState()
        val lines = Finales.pageLines(s)
        check(lines.first().contains("SEASON FINALES") &&
            Finales.DEFS.all { d -> lines.any { it.contains(d.title) } },
            "finales: the Journal page names all four finales before any are played")
        val t = freshState(); dated(t, "20270601")
        t.life["fin:spring:2027:start"] = 5
        t.life["fin:spring:2027:mask"] = 1
        t.life["fin:spring:2027:choice"] = 2
        Finales.dailyRollover(t)
        val marked = Finales.pageLines(t)
        check(marked.any { it.contains("SERGEANT SPROUT") && it.contains("your call") },
            "finales: the page keeps the standing mark, its year and its author")
    }

    // ---------- the full year, lived through the real rollover ----------
    // Oct 2026 → Sep 2027, one onNewDay at a time: autumn played
    // and called, winter ignored outright, spring played but left
    // to the town, summer played and called the other way.
    run {
        val yearEng = Engine(20270)
        val ys = yearEng.newState()
        yearEng.createPlayer(ys, "Yearling", DEFAULT_APPEARANCE)
        fun playDay() {
            val w = Finales.activeWindow(ys) ?: return
            val idx = Finales.currentStepIndex(ys, w.def, w.instanceYear,
                w.dayIndex) ?: return
            val step = w.def.steps[idx]
            when (step.verb) {
                "TALK" -> {
                    if (step.loc != null) {
                        ys.agents[step.who]?.location = step.loc
                    }
                    check(Finales.judgeTalk(ys, step.who!!) != null,
                        "year: ${w.def.id} beat '${step.title}' lands " +
                            "(day ${w.dayIndex + 1} of the window)")
                }
                "LOOK" -> check(Finales.lookText(ys, step.loc!!) != null,
                    "year: ${w.def.id} beat '${step.title}' lands to a Look")
                "PHOTO" -> {
                    Finales.onPhoto(ys, PhotoRecord(
                        id = "yr-${w.def.id}-${w.instanceYear}",
                        dayKey = ys.todayKey, dateLabel = "",
                        timeMin = 600, locId = step.loc!!, inside = false,
                        weatherId = "sunny", appearance = emptyMap(),
                        figures = emptyList()))
                    check(Finales.mask(ys, w.def, w.instanceYear) and
                        (1 shl idx) != 0,
                        "year: ${w.def.id} beat '${step.title}' lands to a photo")
                }
            }
        }
        // the episode list is a rolling 30 — capture each
        // finale's credits as they land, before they scroll off.
        val seenEps = mutableMapOf<String, EpisodeRecord>()
        var guard = 0
        while (guard++ < 400 && ys.todayKey != "20270902") {
            yearEng.onNewDay(ys)
            ys.episodes.filter { it.kind == "finale" && it.finished }
                .forEach { seenEps[it.eventId] = it }
            val w = Finales.windowAt(ys) ?: continue
            if (w.def.id == "winter") continue // the ignored finale
            playDay()
            if (Finales.choiceDue(ys)) {
                when (w.def.id) {
                    "autumn" -> check(Finales.choose(ys, "truescale"),
                        "year: the autumn call is yours, and you weigh it true")
                    "summer" -> check(Finales.choose(ys, "kenny"),
                        "year: the summer call is yours, and the homework boat wins")
                    // spring: played, but the call is left to the town
                }
            }
        }
        check(ys.todayKey == "20270902",
            "year: the drive really crossed all four windows ($guard days)")
        val autumn = Finales.defById("autumn")!!
        val winter = Finales.defById("winter")!!
        val spring = Finales.defById("spring")!!
        val summer = Finales.defById("summer")!!
        for (def in Finales.DEFS) {
            check(Finales.runs(ys, def) == 1,
                "year: ${def.id} ran exactly once in the year")
        }
        val aMark = Finales.markOf(ys, autumn)
        check(aMark?.winner == "a tie" && aMark.byYou && aMark.year == 2026 &&
            aMark.text.contains("SHARED CROWN"),
            "year: autumn — your true-scale call stands as a shared crown")
        val wMark = Finales.markOf(ys, winter)
        check(Finales.playedCount(ys, winter) == 0 && wMark != null && !wMark.byYou,
            "year: winter — ignored, wrapped without you, marked by the town")
        check("finale_lantern" !in House.decorFor(ys),
            "year: winter — no decor for a finale you never touched")
        val sMark = Finales.markOf(ys, spring)
        check(Finales.playedCount(ys, spring) == 1 && sMark?.winner == "Sharon" &&
            !sMark.byYou,
            "year: spring — played every beat, left the call, the town crowned Sharon")
        val uMark = Finales.markOf(ys, summer)
        check(uMark?.winner == "Kenny" && uMark.byYou &&
            uMark.text.contains("KENNY'S BOAT"),
            "year: summer — your call, Kenny's plate on the dock post")
        check(setOf("finale_garden", "finale_regatta", "finale_harvest")
            .all { it in House.decorFor(ys) },
            "year: three seasons of decor hang in the house — the played ones")
        check(seenEps.size == 4,
            "year: all four finales aired and wrapped as episodes")
        val winterEp = seenEps["winter"]
        check(winterEp?.participation == 0 &&
            winterEp?.outcome == winter.absentOutcome,
            "year: the winter episode's credits record an empty chair")
        val autumnEp = seenEps["autumn"]
        check(autumnEp?.participation == 4 &&
            autumnEp?.outcome == autumn.choices[0].outcome &&
            autumnEp?.markText == autumn.choices[0].markText,
            "year: the autumn episode caught all four beats and your call")
        val recap = Episodes.page(autumnEp!!, -1).body
        check(recap.any { it.contains("SHARED CROWN") } &&
            recap.any { it.contains("Your hand in it: 4 of 4") },
            "year: the wrapped episode's page tells the week's story")
        val page = Finales.pageLines(ys)
        check(page.any { it.contains("KENNY'S BOAT") } &&
            page.any { it.contains("4 finales played") },
            "year: the Journal page carries the year's marks")
        // and the whole lived year survives a save round-trip
        val back = decodeGameState(encodeGameState(ys))
        check(Finales.DEFS.all { Finales.markOf(back, it) == Finales.markOf(ys, it) } &&
            Finales.DEFS.all { Finales.runs(back, it) == 1 },
            "year: the year's marks and counts survive the save round-trip")
    }

    // ---------- wiring pins: the hooks are really in the machine ----------
    run {
        val engineSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engineSrc.indexOf("Phone.dailyRollover(state)") >= 0 &&
            engineSrc.indexOf("Finales.dailyRollover(state)") >
            engineSrc.indexOf("Phone.dailyRollover(state)"),
            "finales: the rollover hook runs in onNewDay, after the phone's")
        check(engineSrc.contains("!Finales.suppressesDailyRoll(state)"),
            "finales: the daily roll checks the window before it fires")
        check(engineSrc.contains("Finales.gatheringBlock(state, a.name, timeMin)"),
            "finales: the agenda lookup asks for the gathering override")
        val gameSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gameSrc.contains("Finales.judgeTalk(state, kidName)") &&
            gameSrc.contains("TalkGate.Rail.FINALE"),
            "finales: the Talk flow judges finale beats off the gate")
        check(gameSrc.contains("Finales.lookText(state, me.location)"),
            "finales: the Look flow consults the finale's inspection beats")
        check(gameSrc.contains("maybeShowFinaleVerdict") &&
            gameSrc.contains("Finales.climaxPending(state)") &&
            gameSrc.contains("Finales.choose(state, choice.key)"),
            "finales: the verdict presenter exists, defers to case " +
                "climaxes, and locks the call through Finales.choose")
        val photoSrc = File(root,
            "src/com/hunt3r/southparktown/Photos.kt").readText()
        check(photoSrc.contains("Finales.onPhoto(state, rec)"),
            "finales: the photo pipeline consults the finale's portrait beat")
        val houseSrc = File(root,
            "src/com/hunt3r/southparktown/House.kt").readText()
        check(houseSrc.contains("Finales.morningNote(state)") &&
            houseSrc.contains("Finales.playedCount(state, def)"),
            "finales: the morning report and the decor derivation both " +
                "read Finales")
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(journalSrc.contains("❄ SEASON FINALES") &&
            journalSrc.contains("Finales.pageLines(state)"),
            "finales: the Journal carries the ❄ SEASON FINALES page")
        val talkSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        check(talkSrc.contains("Finales.ambientLine(state, npcName)"),
            "finales: owed conversation includes the ensemble's week talk")
        val readme = File(root, "docs/CHANGELOG.md").readText()
        check(readme.contains("### v0.5.0h"),
            "finales: the v0.5.0h changelog section exists")
    }
}


private fun sectionV070a(root: String) {
// ================= v0.7.0a: cast expansion wave 3 =================
// Ten new named townsfolk join the 44 (cast 44 -> 54): Karen,
// Scott, Firkle, Annie, Bradley (Elementary kids) and Skeeter,
// Victoria, Marvin, Mr. Tucker, Steve (adults). Karen and
// Skeeter were already NAMED inside the old cast's writing —
// Carol's and Stuart's banks talked about Karen for a year,
// and Skeeter's bar stood ownerless; Steve seats the Black
// household at Dinners (his house had a table with one member);
// Mr. Tucker gives Craig the parent every other core kid had.
// This section pins the wave's own contract; the moved
// 44 -> 54 pins live in the sections that own them.
println("== v0.7.0a: cast expansion wave 3 — ten new townsfolk (Queue #7 opens) ==")
run {
    val wave3 = listOf("Karen", "Scott", "Firkle", "Annie", "Bradley",
        "Skeeter", "Victoria", "Marvin", "Mr. Tucker", "Steve")
    val wave3Kids = wave3.take(5)
    val wave3Adults = wave3.drop(5)

    // ---------- the roster arithmetic: 54 everywhere ----------
    check(WAVE3_ORDER == wave3, "wave3: the wave roster is exactly the ten")
    check(KID_ORDER.size == 98 && KID_ORDER.distinct().size == 98,
        "wave4: KID_ORDER carries 98 distinct names")
    check(AGENT_PROFILES.size == 98, "wave4: 98 agent profiles")
    check(KID_HOUSE.size == 98, "wave4: 98 homes")
    check(CharacterSystem.CAST_KIDS.size + CharacterSystem.CAST_ADULTS.size == 98 &&
        (CharacterSystem.CAST_KIDS intersect CharacterSystem.CAST_ADULTS).isEmpty(),
        "wave4: 42 kids + 56 adults, disjoint")
    check(wave3Kids.all { it in CharacterSystem.CAST_KIDS } &&
        wave3Adults.all { it in CharacterSystem.CAST_ADULTS },
        "wave3: the ten sit in the right age sets")
    check(CharacterSystem.CAST.keys == AGENT_PROFILES.keys,
        "wave4: CAST and AGENT_PROFILES describe the same 70")

    // ---------- every registry knows every newcomer ----------
    for (n in wave3) {
        check(n in AGENT_PROFILES, "wave3: $n has a profile")
        check(n in KidArt.SHEETS, "wave3: $n has a sheet spec")
        check(n in KID_HOUSE, "wave3: $n has a home")
        check(n in LINE_BANKS && n in DAILY_TOPICS && n in SPEECH_RULES,
            "wave3: $n has bank, topics and a speech rule")
        check(n in FRIEND_GREETINGS && n in RESPONSE_BANKS && n in SLEEPY_LINES,
            "wave3: $n greets, responds and sleep-talks")
        check(SoundGen.BLIP_FAMILIES.containsKey(n), "wave3: $n has a blip family")
        check(LORE_CHAR_ALIASES.containsKey(n) &&
            LoreBook.charLore(n) != null, "wave3: $n resolves to lorebook prose")
        check(FACTION_OF_CAST.containsKey(n), "wave3: $n belongs to a faction")
    }
    // the generated-visitor pool must never double-cast them
    val loreNames = wave3.map { LORE_CHAR_ALIASES[it]!! }.toSet()
    check(VisitorSystem.eligible().none { it.name in loreNames },
        "wave3: the visitor pool excludes the new cast")

    // ---------- homes & workplaces: existing locations only ----------
    check(KID_HOUSE["Karen"] == "KennysHouse", "wave3: Karen homes to the McCormicks")
    check(KID_HOUSE["Skeeter"] == "SkeetersBar", "wave3: Skeeter homes to his own bar")
    check(KID_HOUSE["Victoria"] == "Elementary", "wave3: the Principal homes to the school")
    check(KID_HOUSE["Marvin"] == "StanHouse", "wave3: Grandpa homes to the Marsh couch")
    check(KID_HOUSE["Mr. Tucker"] == "MainStreet", "wave3: Mr. Tucker homes to his patrol")
    check(KID_HOUSE["Steve"] == "TolkienHouse", "wave3: Steve homes to the big house")
    for (n in listOf("Scott", "Firkle", "Annie", "Bradley")) {
        check(KID_HOUSE[n] == "Elementary", "wave3: $n uses the Elementary home convention")
    }

    // ---------- schedules: seven blocks, real places ----------
    for (n in wave3) {
        val p = AGENT_PROFILES[n]!!
        check(p.agenda.keys == setOf("08:00", "09:00", "12:00", "15:00", "16:30", "18:00", "21:00"),
            "wave3: $n keeps the town's seven-block day")
        check(p.agenda.values.all { it.location in LOCATIONS },
            "wave3: every stop on $n's day is a real location")
        check(p.description.length > 200, "wave3: $n's persona is written deep")
    }
    check(AGENT_PROFILES["Skeeter"]!!.agenda.values.count { it.location == "SkeetersBar" } >= 4,
        "wave3: Skeeter's day belongs to the bar")
    check(AGENT_PROFILES["Victoria"]!!.agenda.values.count { it.location == "Elementary" } >= 4,
        "wave3: the Principal's day belongs to the school")
    check(AGENT_PROFILES["Steve"]!!.agenda.values.count { it.location == "TolkienHouse" } >= 3,
        "wave3: Steve's day belongs to the big house")
    check(AGENT_PROFILES["Karen"]!!.agenda.values.count { it.location == "KennysHouse" } >= 3,
        "wave3: Karen's day belongs to the McCormick house")

    // ---------- factions: exactly one each, canon-flavored ----------
    check(FACTION_OF_CAST.size == 98, "wave4: every cast member holds exactly one faction")
    check(FACTION_OF_CAST["Karen"] == "boys_crew" &&
        FACTION_OF_CAST["Bradley"] == "boys_crew",
        "wave3: the crew's little sister and its quiet hero trail the boys")
    check(FACTION_OF_CAST["Firkle"] == "goth_kids", "wave3: the fourth goth joins the goths")
    check(FACTION_OF_CAST["Annie"] == "girls_circle", "wave3: Annie joins the circle")
    check(FACTION_OF_CAST["Scott"] == "craigs_gang", "wave3: Scott runs with Craig's gang")
    check(FACTION_OF_CAST["Victoria"] == "school_staff", "wave3: the Principal heads school staff")
    check(FACTION_OF_CAST["Skeeter"] == "parents" &&
        FACTION_OF_CAST["Marvin"] == "parents" &&
        FACTION_OF_CAST["Mr. Tucker"] == "parents" &&
        FACTION_OF_CAST["Steve"] == "parents",
        "wave3: the bar, the couch, the fence, and the library sit with the grown-ups")

    // ---------- specs: measured-system invariants for the ten ----------
    for (n in wave3) {
        val spec = KidArt.SHEETS[n]!!
        val m = spec.measured
        check(m != null, "wave3: $n carries MeasuredProps")
        m!!
        close(m.headShare + m.torsoShare + m.legShare, 1.0f, 0.011f,
            "wave3: $n's shares sum to a whole figure")
        val d = FigureGeometry.derive(spec)
        close(d.headShare, m.headShare, 0.045f, "wave3: $n rendered headShare ~ spec")
        close(d.torsoShare, m.torsoShare, 0.03f, "wave3: $n rendered torsoShare ~ spec")
        close(d.legShare, m.legShare, 0.035f, "wave3: $n rendered legShare ~ spec")
        close(d.headAspect, m.headAspect, 0.03f, "wave3: $n rendered head aspect == spec")
        check(d.eyeL >= d.hx - d.hrx - 0.5f && d.eyeR <= d.hx + d.hrx + 0.5f,
            "wave3: $n's eyes sit inside the head ellipse")
        check(d.mouthY <= d.hy + d.hry + 0.5f, "wave3: $n's mouth sits inside the head")
        close(d.hy + d.hry, d.plan.torsoTop + 2f, 0.6f, "wave3: $n's chin anchors to the torso")
        if (n in wave3Kids) {
            check(m.headShare in 0.60f..0.66f, "wave3: kid $n keeps the big-head band")
            check(!spec.tall, "wave3: kid $n is not on adult proportions")
        } else {
            check(spec.tall, "wave3: adult $n is on adult proportions")
            check(m.legShare >= m.torsoShare, "wave3: adult $n keeps legs >= torso")
            check(m.headShare in 0.33f..0.37f, "wave3: adult $n keeps the adult head band")
        }
    }
    // the ten are ten distinct silhouettes, not one reskinned
    val shapes = wave3.map {
        val m = KidArt.SHEETS[it]!!.measured!!
        listOf(m.headShare, m.heightRel, KidArt.SHEETS[it]!!.width)
    }
    check(shapes.distinct().size == 10, "wave3: no two newcomers share a silhouette")

    // ---------- signature spot-pins: recognizable without a label ----------
    check(KidArt.SHEETS["Karen"]!!.hairStyle == "long" &&
        KidArt.SHEETS["Karen"]!!.top == "#b84a78", "wave3: Karen = long brown hair, magenta coat")
    check(KidArt.SHEETS["Karen"]!!.measured!!.heightRel <
        wave3Kids.filter { it != "Karen" }
            .minOf { KidArt.SHEETS[it]!!.measured!!.heightRel } &&
        KidArt.SHEETS["Karen"]!!.measured!!.heightRel <
            KidArt.SHEETS["Kenny"]!!.measured!!.heightRel,
        "wave3: Karen is the smallest of the new kids — shorter than her big brother")
    check(KidArt.SHEETS["Scott"]!!.freckles, "wave3: Scott's freckles are drawn")
    check(KidArt.SHEETS["Firkle"]!!.hairStyle == "fringeflick",
        "wave3: Firkle wears the goth bangs in training")
    check(KidArt.SHEETS["Annie"]!!.hairColor == "#e3b93c" &&
        KidArt.SHEETS["Annie"]!!.face == "lashes", "wave3: Annie = blond and bright")
    check(KidArt.SHEETS["Bradley"]!!.hairStyle == "mop",
        "wave3: Bradley's mop is the camouflage")
    check(KidArt.SHEETS["Skeeter"]!!.beard &&
        KidArt.SHEETS["Skeeter"]!!.hairColor == "#b85a28",
        "wave3: Skeeter = red hair, red beard")
    check(KidArt.SHEETS["Victoria"]!!.glasses &&
        KidArt.SHEETS["Victoria"]!!.hairStyle == "bun",
        "wave3: Victoria = bun and glasses over the clipboard")
    check(KidArt.SHEETS["Marvin"]!!.wrinkles, "wave3: Marvin's years are drawn")
    check(KidArt.SHEETS["Marvin"]!!.measured!!.heightRel <
        wave3Adults.filter { it != "Marvin" }
            .minOf { KidArt.SHEETS[it]!!.measured!!.heightRel },
        "wave3: Marvin is the shortest of the new adults (stooped by right)")
    check(KidArt.SHEETS["Mr. Tucker"]!!.hairStyle == "sidepart",
        "wave3: Mr. Tucker's sidepart is Craig's, thirty years on")
    check(KidArt.SHEETS["Steve"]!!.tie && KidArt.SHEETS["Steve"]!!.skin == "#5a3a22",
        "wave3: Steve = the suit and the tie")

    // ---------- showdown: the new kids are real opponents ----------
    for (n in wave3Kids) {
        val dv = Showdown.dodgeFor(n)
        check(dv in 0.05..0.45, "wave3: $n has a sane dodge stat")
    }
    check(Showdown.dodgeFor("Firkle") > Showdown.dodgeFor("Karen"),
        "wave3: Firkle is the hardest of the new kids to hit (smallest target)")

    // ---------- relations: the scripted pairs are real bonds ----------
    for (pair in WAVE3_PAIR_SCRIPTS.keys) {
        check(relationNote(pair.first(), pair.last()) != null,
            "wave3: $pair carries a relations note")
    }
    check(relationNote("Karen", "Kenny")?.contains("guardian angel") == true,
        "wave3: Karen & Kenny are the angel arrangement")
    check(relationNote("Bradley", "Henrietta")?.contains("sister") == true,
        "wave3: Bradley is Henrietta's little brother")

    // ---------- dinners: the Black table gains its second generation ----------
    val black = Dinners.HOUSEHOLDS.first { it.id == "black" }
    check(black.members == listOf("Tolkien", "Steve", "Linda Black"),
        "wave3: the Black household seats father and son now " +
            "(mother seated by wave 6, v0.11.0d — the house was always hers too)")
    check(Dinners.householdOf("Steve") == black,
        "wave3: Steve resolves to his own household's table")
    check(KID_HOUSE["Steve"] == black.house,
        "wave3: Steve actually lives at his dinner house")

    // ---------- a fresh town spawns all 54 (old saves just gain them) ----------
    val engW = Engine(707)
    val sW = engW.newState()
    check(wave3.all { it in sW.agents }, "wave3: a new state seats all ten newcomers")
    check(sW.agents.size >= 98, "wave4: the roster spawns at 98+")
}
}

// ================= v0.7.0b: town secrets =================
private fun sectionV070b(root: String) {
    println("== v0.7.0b: town secrets — a dozen quiet things ==")
    val eng = Engine(7002)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        // A still town to measure against: the whole cast
        // parked at Raisins, nowhere near any secret.
        fun fresh(): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "Seeker", DEFAULT_APPEARANCE)
            s.agents.values.forEach {
                if (!it.isPlayer) {
                    it.location = "Raisins"; it.destination = "Raisins"
                    it.waypoints.clear()
                }
            }
            return s
        }
        fun place(s: GameState, locId: String, inside: Boolean,
                  timeMin: Int, weather: String? = null,
                  month: Int? = null, absDay: Int? = null) {
            val me = s.agents.values.first { it.isPlayer }
            me.location = locId; me.destination = locId
            me.waypoints.clear()
            s.playerInside = inside
            s.timeMin = timeMin
            weather?.let { s.weatherId = it }
            month?.let { s.gameMonth = it }
            absDay?.let { s.absDay = it }
        }
        fun sec(id: String) = Secrets.secretById(id)!!
        // The moment a secret's gate stands open (and, with
        // open=false, the same moment with the gate shut).
        fun configure(s: GameState, secret: Secrets.Secret, open: Boolean) {
            when (secret.gate) {
                Secrets.GATE_ALWAYS_OUT ->
                    place(s, secret.locId!!, inside = !open, timeMin = 600)
                Secrets.GATE_ALWAYS_IN ->
                    place(s, secret.locId!!, inside = open, timeMin = 600)
                Secrets.GATE_DAY_IN ->
                    place(s, secret.locId!!, inside = true,
                        timeMin = if (open) 600 else 1320)
                Secrets.GATE_DUSK_IN ->
                    place(s, secret.locId!!, inside = true,
                        timeMin = if (open) 1140 else 600)
                Secrets.GATE_NIGHT_IN ->
                    place(s, secret.locId!!, inside = true,
                        timeMin = if (open) 1320 else 600)
                Secrets.GATE_AURORA_OUT ->
                    place(s, secret.locId!!, inside = false, timeMin = 1320,
                        weather = "sunny", month = 1,
                        absDay = if (open) 5 else 6)
                Secrets.GATE_SNOW_OUT ->
                    place(s, secret.locId!!, inside = false, timeMin = 600,
                        weather = if (open) "heavy_snow" else "sunny")
                Secrets.GATE_RAIN_OUT ->
                    place(s, secret.locId!!, inside = false, timeMin = 600,
                        weather = if (open) "rain" else "cloudy")
                Secrets.GATE_SPRING_OUT ->
                    place(s, secret.locId!!, inside = false, timeMin = 600,
                        month = if (open) 4 else 10)
                else -> throw IllegalStateException(
                    "configure() does not cover gate ${secret.gate}")
            }
        }

        // ---------- the registry ----------
        val secs = Secrets.SECRETS
        check(secs.size == Secrets.SECRET_COUNT && secs.size == 12,
            "secrets: the registry holds twelve (has ${secs.size})")
        check(secs.map { it.id }.distinct().size == secs.size,
            "secrets: ids are unique")
        val triggers = setOf(Secrets.TRIGGER_LOOK, Secrets.TRIGGER_BENCH,
            Secrets.TRIGGER_GNOME)
        val gates = setOf(Secrets.GATE_ALWAYS_OUT, Secrets.GATE_ALWAYS_IN,
            Secrets.GATE_DAY_IN, Secrets.GATE_DUSK_IN, Secrets.GATE_NIGHT_IN,
            Secrets.GATE_AURORA_OUT, Secrets.GATE_SNOW_OUT,
            Secrets.GATE_RAIN_OUT, Secrets.GATE_SPRING_OUT,
            Secrets.GATE_VOTE_ANY, Secrets.GATE_ALWAYS, Secrets.GATE_NIGHT)
        for (secret in secs) {
            check(secret.title.isNotBlank() && secret.riddle.isNotBlank() &&
                secret.reveal.isNotBlank() && secret.blurb.isNotBlank(),
                "secrets: ${secret.id} is fully written")
            check(secret.trigger in triggers,
                "secrets: ${secret.id} rides a real trigger (${secret.trigger})")
            check(secret.gate in gates,
                "secrets: ${secret.id} names a real gate (${secret.gate})")
            if (secret.trigger == Secrets.TRIGGER_GNOME) {
                check(secret.locId == null,
                    "secrets: the gnome secret travels (no home location)")
            } else {
                check(secret.locId in LOCATIONS,
                    "secrets: ${secret.id} lives at a real place (${secret.locId})")
            }
            check(secret.coins >= 0,
                "secrets: ${secret.id} never charges the finder")
            if (secret.collectibleId != null) {
                check(collectibleById(secret.collectibleId) != null,
                    "secrets: ${secret.id} grants a real collectible")
            }
        }
        check(secs.map { it.trigger to it.gate }.distinct().size == secs.size,
            "secrets: no two secrets share a (trigger, gate) shape")
        check(secs.count { it.trigger == Secrets.TRIGGER_LOOK } >= 9 &&
            secs.any { it.trigger == Secrets.TRIGGER_BENCH } &&
            secs.any { it.trigger == Secrets.TRIGGER_GNOME },
            "secrets: Looks carry the set, with a bench tap and a gnome tap for shape")
        check(secs.mapNotNull { it.locId }.distinct().size >= 10,
            "secrets: the set spreads over at least ten places")

        // ---------- riddle hygiene: the ONLY hint names nothing ----------
        // A riddle may gesture at the subject; it may never
        // name its own location, trigger or gate.
        val forbidden: Map<String, List<String>> = mapOf(
            "dock_carving" to listOf("pond", "dock", "stark", "look"),
            "second_plow" to listOf("aurora", "tegridy", "night", "look"),
            "confessional_marks" to listOf("church", "confessional", "look"),
            "seat_k9" to listOf("bijou", "theater", "theatre", "dusk", "look"),
            "ones_still_waiting" to listOf("bench", "bus", "sit", "tap"),
            "traveling_tag" to listOf("gnome", "night", "tap", "hat"),
            "the_class_that_never_met" to listOf("elementary", "school",
                "indoor", "look"),
            "the_third_box" to listOf("vote", "ballot", "city hall",
                "count", "glass"),
            "the_warm_ring" to listOf("snow", "park", "melt", "look"),
            "admission_one_button" to listOf("rain", "main street",
                "poster", "look"),
            "still_gaining" to listOf("spring", "stan", "marsh", "garage",
                "pencil", "look"),
            "put_it_back" to listOf("house", "night", "dark", "bed",
                "floorboard"))
        for (secret in secs) {
            val low = secret.riddle.lowercase()
            for (bad in forbidden[secret.id] ?: emptyList()) {
                check(bad !in low,
                    "secrets: ${secret.id}'s riddle never says \"$bad\"")
            }
            for ((_, loc) in LOCATIONS) {
                check(loc.name.lowercase() !in low,
                    "secrets: ${secret.id}'s riddle names no location " +
                        "(${loc.name})")
            }
        }
        // the fresh Journal page, whole: riddles and a count,
        // nothing else leaks (no place, no title, no how)
        run {
            val page = Secrets.pageLines(fresh()).joinToString("\n")
            val low = page.lowercase()
            for ((_, loc) in LOCATIONS) {
                check(loc.name.lowercase() !in low,
                    "secrets page: a fresh page names no location (${loc.name})")
            }
            for (secret in secs) {
                check(secret.title.lowercase() !in low,
                    "secrets page: a fresh page carries no found name " +
                        "(${secret.title})")
            }
            for (bad in listOf("bench", "gnome", "aurora", "snow", "rain",
                "spring", "dusk", "vote", "ballot")) {
                check(bad !in low,
                    "secrets page: a fresh page never says \"$bad\"")
            }
            check(page.contains("0 of 12 found"),
                "secrets page: a fresh page counts honestly")
        }

        // ---------- 🔴 spoiler hygiene over every player-facing word ----
        run {
            val deny = listOf("sleepwalk", "foil", "confiscat", "cameo",
                "strongbox", "communal", "dissolv", "redact", "owes you",
                "professor chaos", "alibi", "charter", "lease", "gardener")
            val corpus = mutableListOf<String>()
            for (secret in secs) {
                corpus += secret.title; corpus += secret.riddle
                corpus += secret.reveal; corpus += secret.blurb
            }
            corpus += Secrets.pageLines(fresh())
            val all = fresh()
            for (secret in secs) Secrets.discover(all, secret)
            corpus += Secrets.pageLines(all)
            Secrets.morningNote(all.copy(absDay = all.absDay + 1))
                ?.let { corpus += it }
            for (line in corpus) {
                val low = line.lowercase()
                for (bad in deny) {
                    check(bad !in low,
                        "secrets hygiene: no secret surface leaks \"$bad\"")
                }
            }
        }

        // ---------- gates: shut is silent, open is certain ----------
        for (secret in secs) {
            if (secret.trigger != Secrets.TRIGGER_LOOK) continue
            if (secret.gate == Secrets.GATE_VOTE_ANY) continue
            val sClosed = fresh()
            configure(sClosed, secret, open = false)
            check(Secrets.lookText(sClosed, secret.locId!!) == null &&
                !Secrets.isFound(sClosed, secret),
                "secrets: ${secret.id} stays scenery with its gate shut")
            val sOpen = fresh()
            configure(sOpen, secret, open = true)
            val coinsBefore = Minigames.capsuleCoins(sOpen)
            val text = Secrets.lookText(sOpen, secret.locId!!)
            check(text != null && Secrets.isFound(sOpen, secret),
                "secrets: ${secret.id} fires the moment its gate stands open")
            check(text!!.contains("🔎 Secret 1 of 12"),
                "secrets: ${secret.id} reports its own count")
            check(Secrets.lookText(sOpen, secret.locId!!) == null,
                "secrets: ${secret.id} fires exactly once")
            if (secret.collectibleId == null && secret.coins > 0) {
                check(Minigames.capsuleCoins(sOpen) ==
                    coinsBefore + secret.coins,
                    "secrets: ${secret.id} settles its ${secret.coins} coins once")
            }
            // a Look at the WRONG place never fires it
            val sWrong = fresh()
            configure(sWrong, secret, open = true)
            val other = LOCATIONS.keys.first {
                it != secret.locId && it != "Raisins"
            }
            check(Secrets.lookText(sWrong, other) == null &&
                !Secrets.isFound(sWrong, secret),
                "secrets: ${secret.id} does not fire from $other")
        }

        // ---------- the bench tap (BusStop) ----------
        run {
            val secret = sec("ones_still_waiting")
            val s = fresh()
            place(s, "BusStop", inside = false, timeMin = 600)
            val before = Minigames.capsuleCoins(s)
            val text = Secrets.propTap(s, "bench")
            check(text != null && Secrets.isFound(s, secret),
                "secrets: the bus-stop bench gives up its plate")
            check(Minigames.capsuleCoins(s) == before + 2,
                "secrets: the bench's two quarters settle once")
            check(Secrets.propTap(s, "bench") == null,
                "secrets: the bench keeps no second secret")
            val sPark = fresh()
            place(sPark, "KidsPark", inside = false, timeMin = 600)
            check(Secrets.propTap(sPark, "bench") == null &&
                !Secrets.isFound(sPark, secret),
                "secrets: the park bench is just a bench")
            val sLookOnly = fresh()
            place(sLookOnly, "BusStop", inside = false, timeMin = 600)
            check(Secrets.lookText(sLookOnly, "BusStop") == null &&
                !Secrets.isFound(sLookOnly, secret),
                "secrets: the bench secret wants the tap, not a Look")
        }

        // ---------- the gnome tap (traveling, night only) ----------
        run {
            val secret = sec("traveling_tag")
            val s = fresh()
            val gloc = TownLife.gnomeLocFor(s)
            place(s, gloc, inside = false, timeMin = 1320, absDay = s.absDay)
            check(TownLife.gnomeLocFor(s) == gloc,
                "secrets: the gnome stands where the day put it ($gloc)")
            val text = Secrets.propTap(s, "gnome")
            check(text != null && Secrets.isFound(s, secret),
                "secrets: the gnome tips its hat at night")
            check("gnome_underpants" in s.collected,
                "secrets: the gnome's keepsake joins the collection")
            check(Secrets.propTap(s, "gnome") == null,
                "secrets: the gnome gives its secret once")
            // daylight: just a gnome
            val sDay = fresh()
            place(sDay, TownLife.gnomeLocFor(sDay), inside = false,
                timeMin = 600)
            check(Secrets.propTap(sDay, "gnome") == null &&
                !Secrets.isFound(sDay, secret),
                "secrets: by day the gnome is only standing there, menacingly")
            // wrong yard: no gnome, no secret
            val sAway = fresh()
            val away = HOUSE_LOCS.first { it != TownLife.gnomeLocFor(sAway) }
            place(sAway, away, inside = false, timeMin = 1320)
            check(Secrets.propTap(sAway, "gnome") == null &&
                !Secrets.isFound(sAway, secret),
                "secrets: no gnome in this yard tonight")
            // already owns the underpants: the find settles in change
            val sOwned = fresh()
            sOwned.collected.add("gnome_underpants")
            place(sOwned, TownLife.gnomeLocFor(sOwned), inside = false,
                timeMin = 1320)
            val coinsBefore = Minigames.capsuleCoins(sOwned)
            val ownedText = Secrets.propTap(sOwned, "gnome")
            check(ownedText != null && ownedText.contains("already own") &&
                Minigames.capsuleCoins(sOwned) == coinsBefore + 3,
                "secrets: a dupe keepsake settles as 3 coins, once")
        }

        // ---------- the vote gate: the count must stand ----------
        run {
            val secret = sec("the_third_box")
            val s = fresh()
            place(s, "CityHall", inside = true, timeMin = 600)
            check(Secrets.lookText(s, "CityHall") == null &&
                !Secrets.isFound(s, secret),
                "secrets: with nothing standing, the count room is just a room")
            val sV = fresh()
            while (sV.absDay < 7) eng.onNewDay(sV)
            check(Votes.QUESTIONS.any {
                Votes.standingOption(sV, it) != null },
                "secrets: the week's count leaves something standing")
            place(sV, "CityHall", inside = true, timeMin = 600)
            val text = Secrets.lookText(sV, "CityHall")
            check(text != null && Secrets.isFound(sV, secret),
                "secrets: the first ballot shows itself once the town has voted")
        }

        // ---------- witnesses: the moment is shared, and remembered ----
        run {
            NpcMemoryStore.clear()
            val s = fresh()
            val stan = s.agents["Stan"]!!
            stan.location = "StarksPond"; stan.destination = "StarksPond"
            stan.waypoints.clear(); stan.asleep = false
            place(s, "StarksPond", inside = false, timeMin = 600)
            val text = Secrets.lookText(s, "StarksPond")
            check(text != null && text.contains("Stan"),
                "secrets: whoever stands here reacts in the moment")
            check(NpcMemoryStore.get("Stan")?.topics
                ?.contains(Secrets.TOPIC) == true,
                "secrets: the witness carries the town-secret thread")
            val mem = NpcMemoryStore.getOrCreate("Stan")
            mem.meets = 3
            val rendered = setOf(
                "That town secret you turned up — you ever tell anyone " +
                    "else? Asking as its co-keeper, apparently.",
                "Update on the town secret front: I checked again. " +
                    "Still there. Still weird. Still ours.",
                "I keep thinking about that town secret. The town's got " +
                    "layers, and you peeled one.")
            val seen = (1..80).mapNotNull {
                Threads.followUp(mem, kotlin.random.Random(it * 31))
            }.toSet()
            check(seen.isNotEmpty() && seen.all { it in rendered },
                "secrets: the thread's follow-ups are the secret bank's own")
            NpcMemoryStore.clear()
            // alone at the pond, the moment is yours only
            val sAlone = fresh()
            place(sAlone, "StarksPond", inside = false, timeMin = 600)
            val aloneText = Secrets.lookText(sAlone, "StarksPond")
            check(aloneText != null && !aloneText.contains("stares at it") &&
                !aloneText.contains("whistles, low"),
                "secrets: no witness, no reaction — the find stands alone")
        }

        // ---------- the feat, the map, the morning after ----------
        run {
            val s = fresh()
            for ((i, secret) in secs.withIndex()) {
                Secrets.discover(s, secret)
                if (i + 1 < Secrets.FEAT_THRESHOLD) {
                    check(s.events.none { it.contains("Town Sleuth") },
                        "secrets: no feat before the threshold (${i + 1})")
                }
                if (i + 1 == Secrets.FEAT_THRESHOLD) {
                    check(s.events.count {
                        it.contains(Secrets.FEAT_NAME) } == 1,
                        "secrets: the feat lands exactly at six")
                    check(Secrets.featDone(s),
                        "secrets: the feat reads done at six")
                }
            }
            check(s.events.count { it.contains(Secrets.FEAT_NAME) } == 1,
                "secrets: the feat never re-fires on the way to twelve")
            check(Secrets.foundCount(s) == 12,
                "secrets: twelve discoveries count twelve")
            check("secret_map" in House.decorFor(s) &&
                "secret-map" in House.decorTokensFor(s),
                "secrets: the full set hangs the map in your house")
            val note = Secrets.morningNote(
                s.copy(absDay = s.absDay + 1))
            val last = secs.last()
            check(note != null && note.contains(last.title),
                "secrets: the morning names yesterday's find — and only it")
            check(Secrets.morningNote(s) == null,
                "secrets: same-day is not the morning after")
            check(Secrets.morningNote(
                s.copy(absDay = s.absDay + 2)) == null,
                "secrets: the note does not nag two mornings later")
            val report = House.morningReport(
                s.copy(absDay = s.absDay + 1),
                emptyList(), emptyMap(), 0, false, null)
            check(report.any { it.contains("🔎") && it.contains(last.title) },
                "secrets: the bed's report carries the discovery line")
            // the finished page: found names are history now,
            // and the riddle shelf stands empty
            val page = Secrets.pageLines(s).joinToString("\n")
            check(page.contains("12 of 12 found") &&
                page.contains("Nothing left out there"),
                "secrets: the finished page says so")
            for (secret in secs) {
                check(page.contains(secret.title),
                    "secrets: the finished page writes up ${secret.id}")
                check(!page.contains(secret.riddle),
                    "secrets: a found secret's riddle retires (${secret.id})")
            }
        }

        // ---------- hostile records mint nothing ----------
        run {
            val s = fresh()
            s.lifeText["secret:dock_carving"] = "garbage"
            check(!Secrets.isFound(s, sec("dock_carving")),
                "secrets: a malformed record is no find")
            s.lifeText["secret:dock_carving"] = "12|Nowhere"
            check(!Secrets.isFound(s, sec("dock_carving")),
                "secrets: a find in no place is no find")
            s.lifeText["secret:dock_carving"] = "-5|StarksPond"
            check(!Secrets.isFound(s, sec("dock_carving")),
                "secrets: a find before time is no find")
            s.lifeText["secret:not_a_secret"] = "12|StarksPond"
            check(Secrets.foundCount(s) == 0,
                "secrets: ids outside the registry count for nothing")
            s.lifeText["secret:dock_carving"] = "12|StarksPond"
            check(Secrets.isFound(s, sec("dock_carving")) &&
                Secrets.foundCount(s) == 1,
                "secrets: an honest record reads back whole")
        }

        // ---------- the save round-trip ----------
        run {
            val s = fresh()
            place(s, "StarksPond", inside = false, timeMin = 600)
            Secrets.lookText(s, "StarksPond")
            place(s, "BusStop", inside = false, timeMin = 600)
            Secrets.propTap(s, "bench")
            val back = decodeGameState(encodeGameState(s))
            check(Secrets.foundCount(back) == 2 &&
                Secrets.isFound(back, sec("dock_carving")) &&
                Secrets.isFound(back, sec("ones_still_waiting")),
                "secrets: finds survive the save round-trip")
            check(Secrets.discoveryOf(back, sec("dock_carving"))?.second ==
                "StarksPond",
                "secrets: the record keeps its where")
            // a v0.7.0a save: no secret keys at all
            val sOld = fresh()
            check(Secrets.foundCount(sOld) == 0 &&
                Secrets.pageLines(sOld).first().contains("0 of 12"),
                "secrets: an old save wakes to a town full of them")
        }

        // ---------- the year of looking: a soak over every gate ----------
        run {
            val s = fresh()
            var discoveries = 0
            for (day in 1..400) {
                eng.onNewDay(s)
                for (secret in secs) {
                    val was = Secrets.foundCount(s)
                    // configure() stages another day's sky for
                    // the gated secrets; the soak's own clock
                    // is restored after every attempt.
                    val dayNow = s.absDay
                    when (secret.trigger) {
                        Secrets.TRIGGER_LOOK -> {
                            if (secret.gate == Secrets.GATE_VOTE_ANY) {
                                place(s, secret.locId!!, inside = true,
                                    timeMin = 600)
                            } else {
                                configure(s, secret, open = true)
                            }
                            if (Secrets.lookText(s, secret.locId!!) != null) {
                                discoveries++
                            }
                        }
                        Secrets.TRIGGER_BENCH -> {
                            place(s, secret.locId!!, inside = false,
                                timeMin = 600)
                            if (Secrets.propTap(s, "bench") != null) {
                                discoveries++
                            }
                        }
                        Secrets.TRIGGER_GNOME -> {
                            place(s, TownLife.gnomeLocFor(s),
                                inside = false, timeMin = 1320)
                            if (Secrets.propTap(s, "gnome") != null) {
                                discoveries++
                            }
                        }
                    }
                    s.absDay = dayNow
                    check(Secrets.foundCount(s) in was..(was + 1),
                        "secrets soak: the count climbs by at most the " +
                            "one find on offer")
                    check(Secrets.foundCount(s) <= Secrets.SECRET_COUNT,
                        "secrets soak: the count never passes twelve")
                }
                check(s.events.size <= 40,
                    "secrets soak: the events feed keeps its cap (day $day)")
            }
            check(discoveries == Secrets.SECRET_COUNT,
                "secrets soak: a year of right-place-right-time finds " +
                    "all twelve (got $discoveries)")
            check(Secrets.foundCount(s) == Secrets.SECRET_COUNT,
                "secrets soak: the year ends with the whole set")
        }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

/** v0.5.0i: polish & performance pass #5 — Queue #5's audit.
 *  The lifetime soak (sectionV030g) now lives Queue #5's
 *  surfaces too; this section carries the rest of the closing
 *  audit: the veteran save at IV, the newest screens' fit QA,
 *  the TalkGate's complete rail order under fabricated total
 *  contention, the finale verdict's climax deferral, the
 *  figure/depth seam audit, the peak budget at a fourth
 *  distance, and the tuning ledger's completeness. No new
 *  features — measure, pin, tighten. */
private fun sectionV050i(root: String) {
// ================= v0.5.0i: polish pass #5 =================
println("== v0.5.0i: polish pass #5 ==")
run {
    // ---------- the veteran, re-measured (IV) ----------
    // Veteran III's saturated save rebuilt line for line,
    // then Queue #5's state laid over it at ITS caps: a
    // walk ledger with every street's shortcut learned, the
    // full wardrobe owned, a binder at the per-card cap,
    // all eight faction chains masked complete, a phone
    // store sitting exactly on its caps, and four season
    // finales' worth of standing marks and instance state.
    // The growth question is the same as ever: does the
    // honest worst case still fit, and does it round-trip?
    val engV4 = Engine(114)
    val vet = engV4.newState()
    engV4.createPlayer(vet, "Veteran", DEFAULT_APPEARANCE)
    vet.gameYear = 2028; vet.gameMonth = 6; vet.gameDay = 15
    vet.todayKey = "20280615"; vet.lastPlayedDate = "20280615"; vet.absDay = 700
    for (n in CharacterSystem.CAST.keys) vet.friendship[n] = 100
    for ((_, a) in vet.agents) repeat(25) {
        a.memories.add("A whole day in South Park, Colorado — the whole town " +
            "was involved and absolutely nobody learned a thing.")
    }
    repeat(40) { vet.events.add("📌 A day where everything happened at once, again ($it)") }
    repeat(30) { townLogLine(vet, "🎪 Town history entry $it — a full sentence about the day.") }
    for (sp in FISH_TABLE) vet.fishLog[sp.id] = FishRecord(999, sp.maxCm)
    for (kid in CharacterSystem.CAST_KIDS) vet.showdown[kid] = ShowdownRecord(400, 400)
    vet.fishCasts = 9000; vet.tacoHigh = 640; vet.tacoPlays = 900
    vet.followers = 250000
    for (item in ITEMS) vet.inventory[item.id] = 99
    vet.inventory[Minigames.COIN_ITEM] = 9999
    for (c in Mystery.CLUES) vet.mysteryClues.add(c.id)
    vet.arcStarted = true; vet.arcChapter = 5
    vet.arcRetired = true; vet.arcBranch = "truth"
    for (c in Mystery2.CLUES2) vet.mystery2Clues.add(c.id)
    vet.arc2Started = true; vet.arc2MarathonDay = 380
    vet.arc2AccusationAired = true; vet.arc2Retired = true
    vet.arc2Branch = "wrong"; vet.arc2Accused = "craig"
    vet.arc2Usher = "Alexandria Featherstonehaugh"
    vet.arc2RetiredDay = 390; vet.arc2ReelFound = true
    vet.arc2FlavorSeen.addAll(listOf("Clyde", "Craig"))
    for (c in Mystery3.CLUES3) vet.mystery3Clues.add(c.id)
    vet.arc3Started = true; vet.arc3Chapter = 4
    vet.arc3Retired = true; vet.arc3Branch = "sharon"
    vet.arc3Choice = "sharon"; vet.arc3RetiredDay = 690
    vet.arc3SharonText = "Sharon's decision, in full: the box goes home " +
        "to the valley it came from, and the town never digs there again."
    for (def in StoryArcs.ARCS) {
        vet.storyArcs[def.id] = StoryArcState(def.id, stage = def.stages.size,
            stageStartAbsDay = 390, startedAbsDay = 370, finishedAbsDay = 395,
            done = true, outcomeId = def.warm.id,
            helpedStages = (0 until def.stages.size).toMutableSet(),
            stageNudges = def.core.toMutableSet(),
            stageTalkShown = (def.parties + def.supporting).toMutableSet())
    }
    val vetTypes = listOf("FETCH", "DELIVER", "FIND", "FIX", "PHOTO", "PLAY")
    repeat(Errands.STATE_CAP) { i ->
        vet.errands.add(Errand("vet-e$i",
            listOf(Errands.BOARD, Errands.ASK, Errands.SHOP)[i % 3],
            CharacterSystem.CAST.keys.elementAt(i % 54),
            vetTypes[i % vetTypes.size],
            "The longest-running favor in town, part $i.",
            "It's around.", itemId = ITEMS[i % ITEMS.size].id,
            targetName = "Alexandria Featherstonehaugh",
            dayKey = "20280615", acceptedDay = 699, done = i % 2 == 0))
    }
    repeat(Errands.STATE_RECENT_CAP) { i ->
        vet.errandsRecent.add(ErrandDoneNote("vet-d$i", "20280614",
            "Ran the big one for the whole town and lived to tell it ($i)"))
    }
    for (n in CharacterSystem.CAST.keys) vet.errandAsked[n] = 700
    vet.errandsDoneCount = 1500
    for (h in HOLIDAYS) {
        val full = (1 shl HolidayBeats.beatFor(h.id)!!.steps.size) - 1
        for (y in listOf(2027, 2028)) {
            vet.life["hb:${h.id}:$y:mask"] = full
            vet.life["hb:${h.id}:$y:done"] = 1
        }
        vet.life["hbYears:${h.id}"] = 2
    }
    vet.life["hbTotal"] = 16
    vet.life["wishes"] = 500
    vet.life["selfies"] = 900
    vet.life["groupShots"] = 400
    vet.life[SkyState.LAST_SKY_DAY_KEY] = 700
    vet.lifeText[SkyState.LAST_SKY_KEY] = SkyState.AURORA
    for (f in Minigames.GAME_FEATS) vet.gameFeats.add(f.id)
    for (f in Photos.PHOTO_FEATS) vet.photoFeats.add(f.id)
    repeat(24) { vet.convertedResidents.add("Converted Resident With A Long Lore Name $it") }
    repeat(300) { vet.photographed["Photographed Townsfolk With A Name $it"] = 7 }
    for (loc in LOCATIONS.keys) {
        vet.locVisits[loc] = 999
        vet.lifeText["mark:$loc"] = "Stan"
        vet.lifeText["chalk:$loc"] = "a very elaborate chalk mural"
        vet.lifeText["prank:$loc"] = "whoopee cushion, deluxe"
        vet.life["clean:$loc"] = 9
    }
    for (n in CharacterSystem.CAST.keys) {
        vet.npcGoals[n] = NpcGoal.fromMap(mapOf("npcKey" to n))!!
    }
    repeat(30) { i ->
        vet.episodes.add(EpisodeRecord(
            key = "event$i@20260101", kind = "event", eventId = "event$i",
            eventTitle = "The Big Event $i", title = "The One Where Everything Happens $i",
            treatment = "A very special episode, presented without commercial interruption.",
            causers = listOf("Stan", "Kyle", "Cartman", "Kenny"),
            dayKey = "20260101", dateLabel = "1/1",
            stageTitles = listOf("Cold Open", "Act One", "Act Two", "The Wrap"),
            stageNotes = listOf("It starts.", "It escalates.", "It peaks.", "It lands."),
            finished = true, participation = 10))
    }
    repeat(60) { i ->
        if (i < 24) {
            vet.photos.add(PhotoRecord(
                id = "vetg$i", dayKey = "20280615", dateLabel = "6/15",
                timeMin = 700, locId = "MainStreet", inside = false,
                weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
                figures = listOf(
                    PhotoFigure("Veteran", "player", "happy"),
                    PhotoFigure("Craig", "cast", "hurt", "backToBack",
                        reaction = "goofy", points = 40),
                    PhotoFigure("Tweek", "cast", "hurt", "backToBack",
                        reaction = "goofy", points = 42),
                    PhotoFigure("Stan", "cast", "happy", "none",
                        reaction = "happy", points = 55),
                    PhotoFigure("Cartman", "cast", "happy", "bomb",
                        reaction = "bomb", points = 12)),
                caption = "The whole gang, posed and crashed, again ($i)",
                followersGained = 40, seed = 1000L + i, absDay = 640 + i,
                composition = listOf(Photos.COMP_LINEUP, Photos.COMP_SQUAD,
                    Photos.COMP_STACKED)[i % 3]))
        } else {
            vet.photos.add(PhotoRecord(
                id = "vet$i", dayKey = "20280615", dateLabel = "6/15",
                timeMin = 700, locId = "MainStreet", inside = false,
                weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
                figures = listOf(PhotoFigure("Veteran", "player", "happy"),
                    PhotoFigure("Stan", "cast", "happy"),
                    PhotoFigure("Kyle", "cast", "goofy")),
                caption = "Best day ever in South Park with the whole gang, again ($i)",
                followersGained = 25, seed = i.toLong(), absDay = 640 + i))
        }
    }
    // ---- Queue #5's state, at its caps ----
    // the walk ledger: every directed street learned, the
    // pass in the wallet, counters deep into four figures
    vet.busPass = true
    vet.walkTrips = 900; vet.walkLegs = 4000; vet.walkCarryMin = 14
    for ((from, exits) in EXITS) for (to in exits)
        vet.walkShortcuts.add("$from>$to")
    vet.life["walkRides"] = 300
    // the wardrobe: all fourteen pieces owned
    for (p in Wardrobe.PIECES) vet.unlockedWardrobe.add(p.id)
    // the binder: every card at the per-card cap; the pull
    // counter deep; two Look exclusives included (they count)
    for (card in PocketPals.CARDS) vet.pocketPals[card.id] = PocketPals.COUNT_CAP
    vet.life["palPulls"] = 5000
    // faction chains: all eight masked complete
    for (ch in FactionMissions.CHAINS) {
        vet.life["fmMask:${ch.factionId}"] = 0b111
        vet.life["fmActive:${ch.factionId}"] = 0
    }
    // the phone store, exactly on its caps: seven threads of
    // twenty (140 texts at the 280-char ceiling), notes at
    // 24, the meta ledger warm. The threads are KID threads
    // — the store is a kid network by design, and decode
    // drops anything else (PhoneText.fromMap) — so the seven
    // longest kid names carry it.
    // v0.9.0a: eight full threads — the veteran's inbox
    // saturates exactly at the wave-5 cap (8 x 20 = 160)
    // v0.11.0d: eleven full threads at the wave-6 cap (11 x 20 = 220)
    val threadNames = KID_ORDER.sortedByDescending { it.length }.take(11)
    var seq = 0
    for (tName in threadNames) repeat(Phone.MAX_PER_THREAD) { k ->
        seq++
        vet.phoneTexts.add(PhoneText(
            id = "vet-t$seq", thread = tName,
            sender = if (k % 7 == 3) "you" else tName,
            trigger = Phone.HELLO, absDay = 699, dayKey = "20280615",
            text = "A maximally long town text about absolutely everything " +
                "that happened today, in complete detail, with opinions ($seq)".padEnd(280, '·'),
            read = k % 3 != 0))
    }
    for (kind in listOf(Phone.FEAT, Phone.PHOTO, Phone.ERRAND, Phone.PULL))
        repeat(6) { vet.phoneNotes.add("699|$kind|Stan|") }
    vet.phoneMeta["seq"] = seq
    vet.phoneMeta["lastRoll"] = 699
    vet.phoneMeta["replies"] = 3
    // four finales, each with a standing mark and a fully
    // played instance year on the books
    for (def in Finales.DEFS) {
        vet.lifeText["finMark:${def.id}"] = def.choices[0].markText
        vet.life["finMarkYear:${def.id}"] = 2028
        vet.lifeText["finMarkBy:${def.id}"] = "you"
        vet.lifeText["finMarkWinner:${def.id}"] = def.choices[0].winner
        vet.life["fin:${def.id}:2028:mask"] =
            (1 shl def.steps.size) - 1
        vet.life["fin:${def.id}:2028:choice"] = 0
        vet.life["fin:${def.id}:2028:done"] = 1
        vet.life["finRuns:${def.id}"] = 2
        vet.life["finPlayed:${def.id}"] = 2
    }
    val vetJson = Json.stringify(encodeGameState(vet))
    println("veteran IV game_state: ${vetJson.length} chars serialized")
    check(vetJson.length < 512 * 1024,
        "veteran IV: the saturated save (Queue #5 included) stays " +
            "under the 512K ceiling (got ${vetJson.length})")
    check(vetJson.length > 224997,
        "veteran IV: today's full state outgrows veteran III's " +
            "224,997 (got ${vetJson.length})")
    @Suppress("UNCHECKED_CAST")
    val vetBack = decodeGameState(Json.parse(vetJson) as Map<String, Any?>)
    check(vetBack.busPass && vetBack.walkTrips == 900 &&
        vetBack.walkLegs == 4000 && vetBack.walkCarryMin == 14 &&
        vetBack.walkShortcuts.size == Walk.SHORTCUT_CAP &&
        (vetBack.life["walkRides"] ?: 0) == 300,
        "veteran IV: the walk ledger round-trips at its cap " +
            "(${vetBack.walkShortcuts.size}/${Walk.SHORTCUT_CAP} shortcuts)")
    check(Wardrobe.ownedCount(vetBack) == Wardrobe.PIECES.size &&
        vetBack.unlockedWardrobe.toSet() == Wardrobe.PIECE_IDS,
        "veteran IV: the full wardrobe round-trips")
    check(PocketPals.ownedCount(vetBack) == PocketPals.CARDS.size &&
        PocketPals.totalCards(vetBack) ==
            PocketPals.CARDS.size * PocketPals.COUNT_CAP &&
        PocketPals.pulls(vetBack) == 5000,
        "veteran IV: the binder round-trips at the per-card cap " +
            "(${PocketPals.totalCards(vetBack)} cards)")
    check(FactionMissions.chainsDone(vetBack) == FactionMissions.CHAINS.size &&
        FactionMissions.CHAINS.all {
            FactionMissions.beatsDone(vetBack, it.factionId) == 3 },
        "veteran IV: all eight chains round-trip complete")
    check(vetBack.phoneTexts.size == Phone.MAX_TEXTS &&
        Phone.threads(vetBack).size == threadNames.size &&
        Phone.threads(vetBack).all { it.count == Phone.MAX_PER_THREAD } &&
        vetBack.phoneNotes.size == Phone.MAX_NOTES,
        "veteran IV: the phone store round-trips exactly on its caps " +
            "(texts ${vetBack.phoneTexts.size}, notes ${vetBack.phoneNotes.size})")
    check(Finales.DEFS.all { def ->
            val m = Finales.markOf(vetBack, def)
            m != null && m.byYou && m.year == 2028 &&
                m.text == def.choices[0].markText &&
                Finales.runs(vetBack, def) == 2 &&
                Finales.playedCount(vetBack, def) == 2 },
        "veteran IV: four standing finale marks round-trip with " +
            "their years, winners and run counts")
    check(vetBack.errands.size == Errands.STATE_CAP &&
        vetBack.photos.size == 60 && StoryArcs.allDone(vetBack),
        "veteran IV: the veteran III body still round-trips whole")
}
run {
    // ---------- fit QA: Queue #5's newest screens ----------
    // The v0.3.0g/v0.4.0g discipline on the surfaces Queue
    // #5 added: the Phone's home and Messages list at their
    // maximum, the SEASON FINALES page with four standing
    // marks, the Pocket Pals binder, and the WALKS page with
    // a veteran's numbers — the longest real lines each
    // screen can produce, at font scales 1.0 and 1.3.
    val engQ = Engine(65)
    val qLines = mutableListOf<String>()
    // the phone at maximum: a capped store — every cast
    // member a thread, every last text at the char ceiling
    val sPh = engQ.newState()
    engQ.createPlayer(sPh, "Fitter", DEFAULT_APPEARANCE)
    sPh.inventory[Minigames.COIN_ITEM] = 9999
    var qSeq = 0
    for (name in CharacterSystem.CAST.keys) repeat(2) { k ->
        qSeq++
        sPh.phoneTexts.add(PhoneText(
            id = "fq-t$qSeq", thread = name,
            sender = if (k == 0) name else "you",
            trigger = Phone.HELLO, absDay = 100 + k, dayKey = "20261001",
            text = "The longest text this thread will ever carry, with " +
                "the whole day in it and a postscript ($qSeq)".padEnd(280, '·'),
            read = false))
    }
    Phone.enforceCaps(sPh)
    val hub = Phone.hubStatus(sPh)
    // the status strip, composed exactly as PhoneActivity does
    qLines += "🕐 ${hub.time} · ${hub.weatherIcon} ${hub.weatherLabel} · " +
        "🪙 ${hub.coins}"
    qLines += if (hub.unread > 0) "💬 ${hub.unread} unread text" +
        (if (hub.unread == 1) "" else "s") + " — the town has opinions"
        else "💬 all caught up — for now"
    for (app in Phone.APPS)
        qLines += if (app.id == "messages" && hub.unread > 0)
            "${app.label} (${hub.unread})" else app.label
    // the Messages list: every thread's name, last text, and
    // status line — with every goal flavor the status line
    // can wear, on the town's longest location names
    val goalKinds = listOf("SCHEME", "GRUDGE", "CRAVING", "MEETUP",
        "PROJECT", "ERRAND", "FACTION", "WORK")
    val castList = CharacterSystem.CAST.keys.toList()
    for ((i, name) in castList.withIndex()) {
        sPh.npcGoals[name] = NpcGoal.fromMap(mapOf(
            "npcKey" to name, "kind" to goalKinds[i % goalKinds.size]))!!
        val a = sPh.agents[name]!!
        a.asleep = false
        a.location = LOCATIONS.keys.maxByOrNull { LOCATIONS[it]!!.name.length }!!
    }
    for (t in Phone.threads(sPh)) {
        qLines += t.name
        qLines += t.last.text
        qLines += Phone.statusLine(sPh, t.name)
    }
    for (name in castList) qLines += Phone.statusLine(sPh, name)
    // asleep is the other status the list can show
    sPh.agents[castList[0]]!!.asleep = true
    qLines += Phone.statusLine(sPh, castList[0])
    check(Phone.threads(sPh).size == castList.size,
        "fitQA: the Messages list really is at maximum — a thread " +
            "per cast member (got ${Phone.threads(sPh).size})")
    // the SEASON FINALES page with four standing marks
    val sFin = engQ.newState()
    engQ.createPlayer(sFin, "Fitter", DEFAULT_APPEARANCE)
    for (def in Finales.DEFS) {
        sFin.lifeText["finMark:${def.id}"] = def.choices[1].markText
        sFin.life["finMarkYear:${def.id}"] = 2028
        sFin.lifeText["finMarkBy:${def.id}"] = "town"
        sFin.lifeText["finMarkWinner:${def.id}"] = def.choices[1].winner
        sFin.life["finRuns:${def.id}"] = 3
        sFin.life["finPlayed:${def.id}"] = 2
    }
    val finLines = Finales.pageLines(sFin)
    check(finLines.count { it.startsWith("✓") } == 4,
        "fitQA: the finales page shows all four standing marks")
    qLines += finLines
    // the binder at full: header, feats, and every card cell
    // composed exactly as CollectionActivity composes it
    val sPal = engQ.newState()
    engQ.createPlayer(sPal, "Fitter", DEFAULT_APPEARANCE)
    for (card in PocketPals.CARDS) sPal.pocketPals[card.id] = PocketPals.COUNT_CAP
    sPal.life[PocketPals.PULLS_KEY] = 5000
    qLines += PocketPals.collectionLines(sPal)
    for (card in PocketPals.CARDS) {
        qLines += card.name
        qLines += "${PocketPals.schoolIcon(card.school)} ${card.school} · " +
            (when (card.rarity) {
                PocketPals.RARE -> "★ RARE"
                PocketPals.UNCOMMON -> "◆ uncommon"
                else -> "common"
            }) + " · ×${PocketPals.COUNT_CAP}"
        qLines += card.flavor
        qLines += PocketPals.hintFor(card)
    }
    // the WALKS page with a veteran's numbers
    val sWk = engQ.newState()
    engQ.createPlayer(sWk, "Fitter", DEFAULT_APPEARANCE)
    sWk.busPass = true
    sWk.walkTrips = 900; sWk.walkLegs = 4000
    for ((from, exits) in EXITS) for (to in exits)
        sWk.walkShortcuts.add("$from>$to")
    sWk.life["walkRides"] = 300
    val walkLines = Walk.pageLines(sWk)
    qLines += walkLines
    val innerW = 420f
    for (fs in listOf(1.0f, 1.3f)) {
        val mFs = { s: String -> s.length * 10f * fs }
        for (line in qLines) {
            if (line.isEmpty()) continue
            val e = Chrome.ellipsize(line, innerW, measure = mFs)
            check(mFs(e) <= innerW + 0.01f,
                "fitQA: a Queue #5 screen line fits at fs $fs")
            check(e.length >= 4 || e == line,
                "fitQA: a Queue #5 screen line never collapses at fs $fs " +
                    "(a genuinely tiny line — a thread named Ned, or " +
                    "Red — passes through whole instead)")
        }
    }
    val m10 = { s: String -> s.length * 10f }
    // the genuine one-liners stay whole at 1.0: thread names
    // in the Messages list, card names in the binder, and
    // the phone's tile labels (the pages' own first lines
    // are stat lines — they wrap by design and are covered
    // by the fit checks above, not this one)
    val longNameQ = castList.maxByOrNull { it.length }!!
    check(Chrome.ellipsize(longNameQ, innerW, measure = m10) == longNameQ,
        "fitQA: the longest thread name fits one line at fs 1.0")
    check(PocketPals.CARDS.all {
            Chrome.ellipsize(it.name, innerW, measure = m10) == it.name },
        "fitQA: every Pocket Pal card name fits one line at fs 1.0")
    check(Phone.APPS.all {
            Chrome.ellipsize(it.label, innerW, measure = m10) == it.label },
        "fitQA: every phone tile label fits one line at fs 1.0")
    check(finLines.first().contains("SEASON FINALES") &&
        walkLines.first().contains("WALKS"),
        "fitQA: both Journal pages carry their titles")
}
run {
    // ---------- total contention: the rail order, final form ----------
    // Five rails now, and the audit arms ALL of them on one
    // man at once. Jimbo is the only townsfolk who can hold
    // the whole stack: he HOSTS the summer finale (its first
    // beat is his), the Cow Days vigil's second step is his,
    // the Tegridy chain opens with his offer, he keeps a
    // counter (so the shop ask can be his), and a delivery
    // can be addressed to anyone. The calendar never stacks
    // a regatta week on Cow Days, so the stack is armed
    // field by field — the gate's ORDER is what's on trial,
    // not the calendar's manners.
    fun contentionJimbo(year: Int): GameState {
        val e = Engine(5150)
        val s = e.newState()
        e.createPlayer(s, "Contender", DEFAULT_APPEARANCE)
        s.gameYear = year; s.gameMonth = 8; s.gameDay = 25
        s.todayKey = "%04d0825".format(year); s.lastPlayedDate = s.todayKey
        s.absDay = 300; s.timeMin = 600
        // the regatta opens on its first morning
        Finales.dailyRollover(s)
        // Jimbo stands at the pond for his own finale beat
        s.agents["Jimbo"]!!.location = "StarksPond"
        s.agents["Jimbo"]!!.destination = "StarksPond"
        // Cow Days, armed by hand: the cow is met (step 0),
        // and the vigil's next step waits on Jimbo
        s.holidayId = "cowdays"
        HolidayBeats.lookText(s, "MainStreet")
        // a finished errand left its thank-you in his pocket
        s.lifeText["errandThanks:Jimbo"] =
            "You did right by the festival, new kid. The house remembers."
        // and a delivery addressed to him sits on the plate
        Errands.accept(s, Errand("rail-deliver-jimbo", Errands.BOARD,
            "Ned", "DELIVER", "Take this to Jimbo.", "He's around.",
            targetName = "Jimbo", dayKey = s.todayKey))
        return s
    }
    var jimboS: GameState? = null
    for (y in 2027..2060) {
        val cand = contentionJimbo(y)
        if (Errands.pendingAsk(cand, "Jimbo", "JimbosGuns") != null) {
            jimboS = cand; break
        }
    }
    check(jimboS != null,
        "contention: an August exists where Jimbo's shop-ask probe " +
            "passes under the full stack")
    val cs = jimboS!!
    check(Finales.talkStepFor(cs, "Jimbo") != null &&
        HolidayBeats.talkStepFor(cs, "Jimbo") != null &&
        FactionMissions.offerFor(cs, "Jimbo")?.factionId == "tegridy_crew" &&
        Errands.pendingAsk(cs, "Jimbo", "JimbosGuns") != null &&
        !Walk.caseCritical(cs),
        "contention: finale beat, vigil step, chain offer and shop " +
            "ask are ALL armed on Jimbo under the delivery")
    // a bark on cooldown rides along — and changes nothing,
    // as ever: garnish is not a rail
    val barkCdJ = mapOf("Jimbo" to (cs.absDay * 1440 + cs.timeMin - 5))
    check(!Barks.cooledDown(barkCdJ["Jimbo"], cs.absDay * 1440 + cs.timeMin),
        "contention: Jimbo's bark is mid-cooldown during the stack")
    // the owed stack, read ONCE at full contention (reading
    // plays the lines): the vigil's ambient and the
    // regatta's ambient are both owed, and the thank-you
    // rides last of the three
    val owed0 = TalkGate.owedLines(cs, "Jimbo")
    val holAmbJ = HolidayBeats.beatFor("cowdays")!!.ambient["Jimbo"]
    val finAmbJ = Finales.defById("summer")!!.ambient["Jimbo"]
    val holIdx = owed0.indexOfFirst { it.text == holAmbJ }
    val finIdx = owed0.indexOfFirst { it.text == finAmbJ }
    val thxIdx = owed0.indexOfFirst { it.text.startsWith("You did right") }
    check(holIdx >= 0 && finIdx > holIdx && thxIdx > finIdx,
        "contention: the owed stack orders holiday ambient, then " +
            "finale ambient, then the errand thank-you (got " +
            "${owed0.map { it.text.take(18) }})")
    // peel, rail by rail, each through its own judge
    val g1 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g1.rail == TalkGate.Rail.DELIVER &&
        g1.delivery?.id == "rail-deliver-jimbo",
        "contention: a delivery settles first (got ${g1.rail})")
    check(Errands.deliverTo(cs, "Jimbo") != null,
        "contention: the delivery settles through its judge")
    val g2 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g2.rail == TalkGate.Rail.HOLIDAY_BEAT,
        "contention: the vigil's step is next (got ${g2.rail})")
    check(HolidayBeats.judgeTalk(cs, "Jimbo") != null &&
        HolidayBeats.talkStepFor(cs, "Jimbo") == null,
        "contention: the vigil step lands through its judge")
    val g3 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g3.rail == TalkGate.Rail.FINALE,
        "contention: the finale beat outranks the standing chain " +
            "(got ${g3.rail})")
    check(Finales.judgeTalk(cs, "Jimbo") != null &&
        Finales.talkStepFor(cs, "Jimbo") == null,
        "contention: the finale beat lands through its judge")
    val g4 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g4.rail == TalkGate.Rail.FACTION_MISSION,
        "contention: the chain's offer surfaces next (got ${g4.rail})")
    val offerJ = FactionMissions.offerFor(cs, "Jimbo")!!
    check(FactionMissions.accept(cs, offerJ) &&
        FactionMissions.onCatch(cs, "pond_smelt")
            .any { it.beat == offerJ } &&
        FactionMissions.activeBeat(cs, "tegridy_crew") == null,
        "contention: the Tegridy chain's first beat (a catch at " +
            "the pond) lands through its judge")
    val g5 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g5.rail == TalkGate.Rail.ERRAND_ASK && g5.ask?.asker == "Jimbo",
        "contention: with the chain quiet, the shop ask surfaces " +
            "(got ${g5.rail})")
    Errands.markAsked(cs, "Jimbo")
    val g6 = TalkGate.gateFor(cs, "Jimbo", "JimbosGuns")
    check(g6.rail == TalkGate.Rail.DIALOGUE,
        "contention: with every rail settled, the Talk is an " +
            "ordinary conversation (got ${g6.rail})")
    // and the order is pinned at the source, scoped to
    // gateFor's body (the file's header essay names the
    // rails too — v0.5.0d's lesson)
    val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val tgBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
    val railPins = listOf("Rail.DELIVER", "Rail.HOLIDAY_BEAT",
        "Rail.FINALE", "Rail.FACTION_MISSION", "Rail.ERRAND_ASK",
        "Rail.DIALOGUE")
    var lastPos = -1
    var orderOk = true
    for (pin in railPins) {
        val idx = tgBody.indexOf(pin)
        if (idx <= lastPos) { orderOk = false; break }
        lastPos = idx
    }
    check(orderOk,
        "contention: gateFor's body checks the rails in the final " +
            "order — DELIVER, HOLIDAY_BEAT, FINALE, FACTION_MISSION, " +
            "ERRAND_ASK, DIALOGUE")

    // ---------- the finale verdict defers to a case climax ----------
    // The v0.5.0h section pinned the presenter's half in
    // GameActivity's source; this pins the data half on a
    // live state: spring's last day, the call due, a case
    // climax on the table — the courtesy condition holds —
    // and the moment the case settles, the SAME call is
    // still there to make.
    val engD = Engine(88)
    val ds = engD.newState()
    engD.createPlayer(ds, "Deferrer", DEFAULT_APPEARANCE)
    ds.gameYear = 2027; ds.gameMonth = 5; ds.gameDay = 25
    ds.todayKey = "20270525"; ds.lastPlayedDate = ds.todayKey
    ds.absDay = 234; ds.timeMin = 600
    Finales.dailyRollover(ds)   // the Garden Verdict opens
    ds.gameDay = 28; ds.todayKey = "20270528"; ds.absDay = 237
    check(Finales.lookText(ds, "KidsPark") != null,
        "deferral: the judging Look lands mid-window")
    check(Finales.judgeTalk(ds, "Butters") != null,
        "deferral: a spring beat lands mid-window (participation)")
    ds.gameDay = 31; ds.todayKey = "20270531"; ds.absDay = 240
    ds.timeMin = 600
    val springDef = Finales.defById("spring")!!
    check(Finales.choiceDue(ds) && !Finales.climaxPending(ds),
        "deferral: on the last day the call is due and nothing " +
            "defers it yet")
    // the pond case reaches its own finale the same evening
    ds.arcStarted = true; ds.arcChapter = 5
    for (c in Mystery.CLUES) ds.mysteryClues.add(c.id)
    ds.shenaniganId = Mystery.FINALE_ID
    ds.timeMin = (0..1439 step 15).first { Shenanigans.stageFor(it) >= 2 }
    check(Mystery.finaleChoiceDue(ds) && Finales.climaxPending(ds) &&
        Finales.choiceDue(ds),
        "deferral: with the case's climax on the table, the " +
            "finale's call is due AND deferred — the exact " +
            "condition the presenter waits on")
    ds.arcChoice = "truth"   // the case's call is made
    check(!Finales.climaxPending(ds) && Finales.choiceDue(ds),
        "deferral: the case settled, the finale's call is still " +
            "there — deferral postponed it, never ate it")
    Finales.choose(ds, springDef.choices[0].key)
    check(Finales.choiceIndex(ds, springDef, 2027) == 0 &&
        !Finales.choiceDue(ds),
        "deferral: and the call still lands when it's made")
}
run {
    // ---------- the seam audit: HeadStack x Crowds x Depth ----------
    // The figure pass and the depth pass shipped back-to-back
    // and were audited separately (v0.5.0f's raster, v0.5.0g's
    // bands). This is the seam between them: crowds placed by
    // Crowds, drawn through the merged HeadStack, standing in
    // Depth's bands — checked where they meet.
    val castNames = CharacterSystem.CAST.keys.toList()
    // the town's real chemistry, the snapshot GameView builds
    val rivalPairs = mutableSetOf<Set<String>>()
    for (a in castNames) for (b in castNames)
        if (a < b && relationNote(a, b) == "arch-rivals")
            rivalPairs.add(setOf(a, b))
    val fullChem = Crowds.Chem(
        scriptPairs = PAIR_SCRIPTS.keys.filter { it.size == 2 }.toSet(),
        rivalPairs = rivalPairs,
        factionOf = FACTION_OF_CAST)
    // (1) the crowd matrix at full size: every headcount the
    // town can gather, every row, both scene kinds — the
    // worst chin of every row stays above the frieze, and
    // the MIN_SEP floor survives crowds past two dozen (the
    // v0.5.0g harness stopped at 24; a finale-day Main Street
    // doesn't)
    for (total in 7..44) {
        val names = castNames.take(total)
        val lay = Crowds.layout(names, fullChem)
        check(lay != null && lay.placed.size == total,
            "seam: a crowd of $total lays out whole")
        if (lay == null) continue
        for (inside in listOf(false, true)) {
            val feet0 = if (inside) Depth.FRONT_FEET_IN
                else Depth.FRONT_FEET_OUT
            val fgTop = if (inside) Depth.FG_TOP_IN else Depth.FG_TOP_OUT
            var chinOk = true
            for (p in lay.placed) {
                val feet = feet0 - p.frontness * Depth.FH_BASE_MAX * 0.54f
                if (Depth.worstChin(feet) >= fgTop) chinOk = false
            }
            check(chinOk,
                "seam: crowd of $total ${if (inside) "indoors" else "outdoors"} — " +
                    "no clustered row pushes a face into the frieze")
        }
        var sepOk = true
        for ((_, row) in lay.placed.groupBy { it.frontness }) {
            val byX = row.sortedBy { it.xFrac }
            for (i in 1 until byX.size)
                if (byX[i].xFrac - byX[i - 1].xFrac <
                    Crowds.MIN_SEP - 0.0001f) sepOk = false
        }
        check(sepOk,
            "seam: crowd of $total — the MIN_SEP floor holds at full size")
    }
    // (2) worn combos: every cast member's hair under every
    // hat the creator can put on a head (theirs, the
    // wardrobe's, anyone's). Under a COVERING hat the dome
    // band reads hat — the wearer's own hair never pokes
    // through it; under any hat at all, the crown is never
    // a hole. This is Lucky's "hair is broken — make sure
    // it covers the head correctly and works with the hats"
    // swept across species: cast hair x the whole hat shelf.
    val hatOpts = CREATOR_OPTIONS["hat"]!!.second
    val hatColorOf = hatOpts.associate { it.id to it.color }
    val hatIds = (hatOpts.map { it.id } +
        KidArt.SHEETS.values.map { it.hatId })
        .distinct().filter { it != "none" }
    fun hatPalette(spec: SheetSpec): Set<String> = setOf(
        spec.hatColor, spec.hatAccent, darkerHex(spec.hatColor),
        "#f4f4f4", "#f0f0f0")
    // the one exemption, pinned as the design it is: the
    // towel is a full-body special form — HeadStack.build
    // returns no stack for it at all, under any hat, and
    // KidArt draws the towel itself. It is not a broken
    // crown; there is no crown.
    val towelSpec = KidArt.SHEETS["Towelie"]!!
    check(hatIds.all {
            HeadStack.layers(towelSpec.copy(hatId = it)).isEmpty() },
        "seam: the towel carries no head stack under any hat, " +
            "by construction")
    var wornCombos = 0
    for ((nm, base) in KidArt.SHEETS) {
        if (base.special == "towel") continue
        for (hat in hatIds) {
            val worn = base.copy(hatId = hat,
                hatColor = hatColorOf[hat] ?: base.hatColor)
            val d = FigureGeometry.derive(worn)
            val top = d.hy - d.hry
            val palette = hatPalette(worn)
            wornCombos++
            if (HeadStack.hatCoversHair(hat) &&
                worn.hairColor !in palette) {
                var domeOk = true
                for (fx in listOf(-0.3f, 0f, 0.3f)) {
                    for (dy in listOf(-1f, 0.5f, 2f)) {
                        if (HeadStack.colorAt(worn,
                                d.hx + d.hrx * fx, top + dy) ==
                            worn.hairColor) domeOk = false
                    }
                }
                check(domeOk,
                    "seam: $nm under a $hat — no hair pokes through " +
                        "the covering dome")
            }
            check(HeadStack.colorAt(worn, d.hx, top - 1f) != null ||
                HeadStack.colorAt(worn, d.hx, top + 0.5f) != null,
                "seam: $nm wearing a $hat — the crown is never a hole")
        }
    }
    println("seam: $wornCombos worn combos audited " +
        "(${KidArt.SHEETS.size} heads x ${hatIds.size} hats)")
    // (3) the placement/stack split itself: Crowds sees
    // names, HeadStack sees specs — neither can reach into
    // the other, which is why a mirrored cluster member's
    // stack is byte-identical to an unmirrored one's
    val stackA = HeadStack.layers(KidArt.SHEETS["Kenny"]!!)
    val stackB = HeadStack.layers(KidArt.SHEETS["Kenny"]!!)
    check(stackA == stackB && stackA.isNotEmpty(),
        "seam: a figure's stack is a pure function of its spec — " +
            "placement (mirror included) cannot reach it")
    // (4) PhotoView at the album's aspect: merged figures in
    // group frames over the foreground strip — heads clear
    // of the frame top (the v0.4.0g discipline) AND every
    // chin clear of the strip the photo paints last (top
    // 0.945 of the photo), for every composition and group
    // size the album can hold
    val G = Photos.GroupGeom
    val albumAspects = listOf(2.3f, 2.35f, 2.4f)
    val groupNames = listOf("Stan", "Kyle", "Cartman", "Kenny", "Butters")
    for (comp in listOf(Photos.COMP_LINEUP, Photos.COMP_SQUAD,
        Photos.COMP_STACKED)) {
        for (n in 3..5) {
            val figs = groupNames.take(n).map { nm ->
                Photos.GroupGeom.Fig(KidArt.heightFor(nm),
                    Photos.halfWidthFrac(KidArt.SHEETS[nm]!!))
            }
            for (a in albumAspects) {
                val placed = G.layout(comp, figs, a)
                check(placed.size == n,
                    "seam: $comp x$n @ $a — the frame lays out whole")
                for (p in placed) {
                    val figH = p.h * figs[p.index].scale
                    check(p.feet - figH * G.INK_OVERHEAD >=
                        G.HEAD_MARGIN - 0.0001f,
                        "seam: $comp x$n @ $a — merged crowns keep " +
                            "their headroom at the album aspect")
                    check(p.feet - figH * (1f - Depth.HEAD_SHARE_MIN) <
                        0.945f,
                        "seam: $comp x$n @ $a — no chin dips into the " +
                            "photo's foreground strip")
                }
            }
        }
    }
    // the photo really does paint figures first and the
    // strip after (the strip-over-feet tuck is by design)
    val photoSrc = File(root, "src/com/hunt3r/southparktown/PhotoView.kt").readText()
    check(photoSrc.indexOf("drawFigures(") in 0 until
        photoSrc.indexOf("drawForeground("),
        "seam: PhotoView paints figures, then the foreground strip " +
            "over their feet — the tuck is the design, not a bug")
}
run {
    // ---------- the peak budget, fourth distance ----------
    // The same pins as v0.4.0e/g, on today's render set —
    // Queue #5 added no new audio family, and the budget
    // must be able to prove it.
    val pb = SoundGen.PeakBudget
    println("budget v0.5.0i: named ${pb.namedStack()}, " +
        "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
        "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
        "amb ${pb.ambiencePeakOut()}")
    check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
        "budget: the named stack has not drifted since v0.4.0e " +
            "(got ${pb.namedStack()})")
    check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
        "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
    check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
        "budget: the bark stack has not drifted (got ${pb.barkStack()})")
    check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
        pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
        "budget: neither barks nor mood contours out-peak the plain blip")
    for (bed in SoundGen.AmbBed.values()) {
        if (bed == SoundGen.AmbBed.NONE) continue
        val post = AudioSettings.DEFAULT.gain(
            AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
            pb.peakOf(SoundGen.renderAmbience(bed))
        check(post <= pb.ambiencePeakOut() + 0.002f,
            "budget: bed $bed stays inside the ambience allocation")
    }
}
run {
    // ---------- the tuning ledger, swept for Queue #5 ----------
    // Every paper-tuned Queue #5 constant, named in the
    // README ledger with its home — so playtest feedback
    // ("the bus feels cheap", "the binder's stingy") maps
    // to exactly one line. If a dial ships, its name lands
    // here in the same build; this pin is how the next
    // polish pass notices one that didn't.
    val readme = File(root, "docs/TUNING.md").readText()
    val changelog = File(root, "docs/CHANGELOG.md").readText()
    val ledgerDials = listOf(
        // the Walk (v0.5.0a)
        "MINUTES_PER_UNIT", "SHORTCUT_SAVE_MINUTES", "MIN_LEG_MINUTES",
        "BEAT_CHANCE", "BUS_PASS_PRICE",
        // the Wardrobe (v0.5.0b)
        "COLLECTION_MILESTONE",
        // Pocket Pals (v0.5.0c)
        "MACHINE_COST", "COUNT_CAP", "TRADE_SWING_CAP", "STASH_SIZE",
        "ERRAND_CARD_EVERY",
        // faction missions (v0.5.0d)
        "RIVAL_COST", "BEAT_FRIENDSHIP",
        // the Phone (v0.5.0e)
        "MAX_TEXTS", "MAX_PER_THREAD", "MAX_UNREAD", "MAX_NEW_PER_DAY",
        "MAX_NOTES", "HELLO_MIN_FRIENDSHIP", "REPLY_DAILY_CAP",
        // the figure merge (v0.5.0f)
        "HAIR_PAD", "HAT_PAD",
        // scene depth + crowds (v0.5.0g)
        "FG_TOP_OUT", "FG_TOP_IN", "CLUSTER_MIN_TOTAL", "CLUSTER_MAX",
        "TIGHT", "BETWEEN", "MIN_SEP",
        // season finales (v0.5.0h)
        "WINDOW_DAYS", "GATHER_FROM")
    for (dial in ledgerDials) {
        check(readme.contains(dial),
            "ledger: the README tuning ledger names $dial")
    }
    check(readme.contains("## Tuning ledger"),
        "ledger: the ledger section itself stands")

    // ---------- README ----------
    check(changelog.contains("### v0.5.0i"),
        "polish5: the v0.5.0i changelog section exists")
}
}

/** v0.6.0a: photo commissions (Queue #6 item 1) — the weekly
 *  board as a pure function of the week, schedule-proven
 *  reachability over a year of calendars, the judge's truth
 *  table over fabricated records, the plate lifecycle, prints
 *  that never fade, and the save round-trip. */
private fun sectionV060a(root: String) {
// ================= v0.6.0a: photo commissions =================
println("== v0.6.0a: photo commissions ==")

    val engC = Engine()
    val epochC = ordinalOfKey("20261001")

    /** A fresh town pinned to an absolute day, calendar and
     *  key in agreement (the anchor Commissions reads). */
    fun stateAt(day: Int): GameState {
        val s = engC.newState()
        s.absDay = day
        s.todayKey = keyFromOrdinal(epochC + day)
        s.gameYear = s.todayKey.substring(0, 4).toInt()
        s.gameMonth = s.todayKey.substring(4, 6).toInt()
        s.gameDay = s.todayKey.substring(6, 8).toInt()
        return s
    }

    // ---------- keyFromOrdinal: the inverse calendar ----------
    for (k in listOf("20261001", "20260228", "20280229", "20280301",
            "20261231", "20270101", "20000229", "19000301", "20240229")) {
        check(keyFromOrdinal(ordinalOfKey(k)) == k,
            "commissions: keyFromOrdinal round-trips $k")
    }
    run {
        var ord = ordinalOfKey("20250101")
        var allOk = true
        repeat(1500) {
            if (ordinalOfKey(keyFromOrdinal(ord)) != ord) allOk = false
            ord++
        }
        check(allOk, "commissions: 1,500 consecutive ordinals round-trip")
    }

    // ---------- independent co-presence (minute grid) ----------
    // Re-derived from AGENT_PROFILES by a different method
    // than Commissions' interval spans: the block in effect
    // at each sampled minute, sleep excluded.
    fun locAtMinute(name: String, minute: Int): String? {
        val p = AGENT_PROFILES[name] ?: return null
        val blocks = p.agenda.entries.sortedBy { timeStrToMinutes(it.key) }
        var cur = blocks.last().value
        for (e in blocks) if (timeStrToMinutes(e.key) <= minute) cur = e.value
        if (cur.activity == SLEEP_ACTIVITY) return null
        return cur.location
    }
    fun coPresent(names: List<String>, locId: String): Boolean {
        var m = 0
        while (m < 1440) {
            if (names.all { locAtMinute(it, m) == locId }) return true
            m += 5
        }
        return false
    }

    // ---------- a year of weekly boards ----------
    // Driven day by day through the REAL rollover, so the
    // no-repeat memory folds exactly as it does in play.
    val sYear = engC.newState()
    var totalPostings = 0
    var condPostings = 0
    val shapesSeen = mutableSetOf<Int>()
    val condKindsSeen = mutableSetOf<String>()
    val locsSeen = mutableSetOf<String>()
    val textsSeen = mutableSetOf<String>()
    for (week in 0 until 52) {
        for (d in 0 until Commissions.WEEK_DAYS) {
            val day = week * Commissions.WEEK_DAYS + d
            sYear.absDay = day
            sYear.todayKey = keyFromOrdinal(epochC + day)
            sYear.gameYear = sYear.todayKey.substring(0, 4).toInt()
            sYear.gameMonth = sYear.todayKey.substring(4, 6).toInt()
            sYear.gameDay = sYear.todayKey.substring(6, 8).toInt()
            Commissions.dailyRollover(sYear)
            if (d > 0) break   // the week's board is read on its first day
        }
        val posts = Commissions.postingsFor(sYear)
        check(posts == Commissions.postingsFor(sYear),
            "commissions: week $week's board is deterministic (same state, same asks)")
        check(posts.size == Commissions.POSTINGS,
            "commissions: week $week posts ${Commissions.POSTINGS} asks (got ${posts.size})")
        check(posts.map { it.asker }.distinct().size == posts.size,
            "commissions: week $week's askers are distinct")
        val weekStartAbs = week * Commissions.WEEK_DAYS
        val spanSeason = run {
            val first = seasonFor(sYear.todayKey.substring(4, 6).toInt())
            var constant: Season? = first
            for (dd in 1 until 14) {
                val k = keyFromOrdinal(epochC + weekStartAbs + dd)
                if (seasonFor(k.substring(4, 6).toInt()) != first) {
                    constant = null; break
                }
            }
            constant
        }
        val weekSeason = seasonFor(
            keyFromOrdinal(epochC + weekStartAbs).substring(4, 6).toInt())
        for (p in posts) {
            totalPostings++
            shapesSeen += p.subjects.size
            locsSeen += p.locId
            textsSeen += p.text
            check(p.asker in KID_ORDER && p.subjects.size in 1..3 &&
                p.subjects.distinct().size == p.subjects.size &&
                p.subjects.all { it in KID_ORDER } && p.locId in LOCATIONS,
                "commissions: week $week ask ${p.id} is well-formed")
            check(p.signature != sYear.commissionLast[p.asker],
                "commissions: week $week asker ${p.asker} does not repeat " +
                    "their last ask (${p.id})")
            check(coPresent(p.subjects, p.locId),
                "commissions: week $week ask ${p.id} is reachable — " +
                    "${p.subjects} are together at ${p.locId} on their rounds")
            val basePay = when (p.subjects.size) {
                1 -> Commissions.PAY_ONE
                2 -> Commissions.PAY_PAIR
                else -> Commissions.PAY_GROUP
            }
            check(p.pay == basePay +
                (if (p.condKind.isNotEmpty()) Commissions.COND_BONUS else 0),
                "commissions: week $week ask ${p.id} pays by its shape")
            check(p.text.length > 20 && !p.text.contains("{who}") &&
                !p.text.contains("{place}") && !p.text.contains("{cond}"),
                "commissions: week $week ask ${p.id} text is filled and finished")
            if (p.condKind.isNotEmpty()) {
                condPostings++
                condKindsSeen += p.condKind
                when (p.condKind) {
                    "comp" -> check(p.condValue in Commissions.compApplies(p.subjects),
                        "commissions: week $week ask ${p.id} composition is " +
                            "the one compositionFor guarantees for its set")
                    "season" -> check(spanSeason != null &&
                        p.condValue == spanSeason.name,
                        "commissions: week $week ask ${p.id} season fills its " +
                            "whole live window")
                    "weather" -> check(Commissions.weatherApplies(p.condValue, weekSeason),
                        "commissions: week $week ask ${p.id} weather is one " +
                            "the season can produce")
                    else -> check(false,
                        "commissions: week $week ask ${p.id} has a known condition kind")
                }
            }
        }
    }
    check(totalPostings == 52 * Commissions.POSTINGS,
        "commissions: the year posted every week ($totalPostings)")
    check(shapesSeen == setOf(1, 2, 3),
        "commissions: the year saw solo, pair and group asks ($shapesSeen)")
    check(condPostings > totalPostings / 4 && condKindsSeen.size >= 2,
        "commissions: conditions are common and varied ($condPostings, $condKindsSeen)")
    check(locsSeen.size >= 10 && textsSeen.size > 100,
        "commissions: the year's asks roam (${locsSeen.size} places, " +
            "${textsSeen.size} distinct texts)")

    // ---------- the judge's truth table ----------
    val locIn = LOCATIONS.keys.first { CharacterSystem.npcInside(it) }
    val locOut = LOCATIONS.keys.first { !CharacterSystem.npcInside(it) }
    fun figC(name: String) = PhotoFigure(name, "cast", "happy",
        reaction = "happy", points = 10)
    fun recC(subjects: List<String>, locId: String, inside: Boolean,
             composition: String = "", dayKey: String = "20270115",
             weatherId: String = "sunny"): PhotoRecord = PhotoRecord(
        id = "tc", dayKey = dayKey, dateLabel = "1/15", timeMin = 600,
        locId = locId, inside = inside, weatherId = weatherId,
        appearance = emptyMap(),
        figures = listOf(PhotoFigure("You", "player", "happy",
            reaction = "player")) + subjects.map { figC(it) },
        absDay = 100, composition = composition)
    fun commC(subjects: List<String>, locId: String, kind: String = "",
              value: String = "") = Commission("ct", "Stan", subjects,
        locId, kind, value, "the ask", 3, 0)
    val jA = "Kyle"; val jB = "Wendy"; val jX = "Cartman"
    // subjects dimension
    check(Commissions.judge(commC(listOf(jA), locOut),
        recC(listOf(jA), locOut, false)) == Commissions.Verdict.MATCH,
        "commissions: solo ask, right person/place = MATCH")
    check(Commissions.judge(commC(listOf(jA), locOut),
        recC(listOf(jX), locOut, false)) == Commissions.Verdict.MISS,
        "commissions: wrong person = MISS (not a near miss)")
    check(Commissions.judge(commC(listOf(jA), locOut),
        recC(listOf(jA, jB), locOut, false)) == Commissions.Verdict.MATCH,
        "commissions: extra people in frame never spoil an ask")
    // place dimension (subjects right)
    check(Commissions.judge(commC(listOf(jA), locOut),
        recC(listOf(jA), locIn, true)) == Commissions.Verdict.NEAR,
        "commissions: right person, wrong place = NEAR")
    check(Commissions.judge(commC(listOf(jA), locIn),
        recC(listOf(jA), locIn, false)) == Commissions.Verdict.NEAR,
        "commissions: right building, wrong side of its door = NEAR")
    check(Commissions.judge(commC(listOf(jA), locIn),
        recC(listOf(jA), locIn, true)) == Commissions.Verdict.MATCH,
        "commissions: an interior ask lands indoors")
    // composition dimension
    check(Commissions.judge(commC(listOf(jA, jB), locOut, "comp", "lineup"),
        recC(listOf(jA, jB), locOut, false, "lineup")) == Commissions.Verdict.MATCH,
        "commissions: lineup ask + lineup frame = MATCH")
    check(Commissions.judge(commC(listOf(jA, jB), locOut, "comp", "lineup"),
        recC(listOf(jA, jB), locOut, false, "squad")) == Commissions.Verdict.NEAR,
        "commissions: lineup ask + squad frame = NEAR")
    check(Commissions.judge(commC(listOf(jA, jB), locOut, "comp", "lineup"),
        recC(listOf(jA, jB), locOut, false, "")) == Commissions.Verdict.NEAR,
        "commissions: lineup ask + pile-in selfie = NEAR (no composition)")
    check(Commissions.judge(commC(listOf(jA, jB), locOut, "comp", "group"),
        recC(listOf(jA, jB), locOut, false, "stacked")) == Commissions.Verdict.MATCH,
        "commissions: 'any group frame' takes any composition")
    // season dimension (record dayKey: Jan = WINTER, Jul = SUMMER)
    check(Commissions.judge(commC(listOf(jA), locOut, "season", "WINTER"),
        recC(listOf(jA), locOut, false, dayKey = "20270115")) ==
        Commissions.Verdict.MATCH,
        "commissions: winter ask + January shot = MATCH")
    check(Commissions.judge(commC(listOf(jA), locOut, "season", "WINTER"),
        recC(listOf(jA), locOut, false, dayKey = "20270715")) ==
        Commissions.Verdict.NEAR,
        "commissions: winter ask + July shot = NEAR (the record's own stamp judges)")
    // weather dimension
    for ((fam, good, bad) in listOf(
            Triple("snow", "heavy_snow", "sunny"),
            Triple("sun", "sunny", "light_snow"),
            Triple("rain", "rain", "cloudy"))) {
        check(Commissions.judge(commC(listOf(jA), locOut, "weather", fam),
            recC(listOf(jA), locOut, false, weatherId = good)) ==
            Commissions.Verdict.MATCH,
            "commissions: weather '$fam' matches $good")
        check(Commissions.judge(commC(listOf(jA), locOut, "weather", fam),
            recC(listOf(jA), locOut, false, weatherId = bad)) ==
            Commissions.Verdict.NEAR,
            "commissions: weather '$fam' misses $bad")
    }
    // every weather family is producible in every season
    for (season in Season.values()) for (fam in Commissions.WEATHER_FAMILIES.keys)
        check(Commissions.weatherApplies(fam, season),
            "commissions: weather family $fam is season-legal in $season")

    // ---------- the plate lifecycle ----------
    val sL = stateAt(10)
    val board = Commissions.boardOpen(sL)
    check(board.isNotEmpty(), "commissions: the cork has asks")
    val first = board[0]
    check(Commissions.accept(sL, first), "commissions: accept lands")
    check(!Commissions.accept(sL, first),
        "commissions: the same ask can't be taken twice")
    check(first.acceptedDay == -1,
        "commissions: accepting copies — the posting itself stays pristine")
    val heldFirst = Commissions.active(sL).first { it.id == first.id }
    check(heldFirst.acceptedDay == sL.absDay &&
        heldFirst.expiresDay == sL.absDay + Commissions.EXPIRY_DAYS - 1,
        "commissions: an accepted ask lives EXPIRY_DAYS from today")
    check(Commissions.boardOpen(sL).none { it.id == first.id },
        "commissions: a taken ask leaves the cork")
    for (c in Commissions.boardOpen(sL)) {
        if (Commissions.activeCount(sL) >= Commissions.MAX_PLATE) break
        Commissions.accept(sL, c)
    }
    check(Commissions.activeCount(sL) == Commissions.MAX_PLATE,
        "commissions: the plate fills to MAX_PLATE")
    val extra = Commissions.boardOpen(sL).firstOrNull()
    check(extra == null || !Commissions.accept(sL, extra),
        "commissions: a full plate refuses one more")
    val sigh = Commissions.abandon(sL, heldFirst.id)
    check(sigh != null && Commissions.activeCount(sL) == Commissions.MAX_PLATE - 1,
        "commissions: letting go sighs and frees the plate")
    check(Commissions.abandon(sL, "c999:nope") == null,
        "commissions: letting go of nothing is nothing")
    // expiry: free, silent on friendship, final at the boundary
    val sE = stateAt(20)
    val ec = Commissions.boardOpen(sE)[0]
    Commissions.accept(sE, ec)
    val eHeld = Commissions.active(sE).first()
    val frBefore = sE.friendship[ec.asker] ?: 0
    sE.absDay = eHeld.expiresDay
    sE.todayKey = keyFromOrdinal(epochC + sE.absDay)
    Commissions.dailyRollover(sE)
    check(Commissions.active(sE).any { it.id == ec.id },
        "commissions: an ask is still live ON its expiry day")
    sE.absDay = eHeld.expiresDay + 1
    sE.todayKey = keyFromOrdinal(epochC + sE.absDay)
    Commissions.dailyRollover(sE)
    check(Commissions.active(sE).none { it.id == ec.id } &&
        sE.commissions.none { it.id == ec.id },
        "commissions: the morning after expiry, the ask has lapsed")
    check((sE.friendship[ec.asker] ?: 0) == frBefore && sE.commissionsDone == 0,
        "commissions: expiry costs nothing — no friendship hit, no record of failure")

    // ---------- completion through the real shutter ----------
    fun matchingRec(c: Commission, dayKey: String = "20270115"): PhotoRecord {
        val composition = when {
            c.condKind != "comp" -> ""
            c.condValue == "group" -> Photos.COMP_LINEUP
            else -> c.condValue
        }
        val weather = when {
            c.condKind != "weather" -> "sunny"
            c.condValue == "snow" -> "light_snow"
            c.condValue == "sun" -> "sunny"
            else -> "rain"
        }
        val key = if (c.condKind == "season") when (c.condValue) {
            "WINTER" -> "20270115"
            "SPRING" -> "20270415"
            "SUMMER" -> "20270715"
            else -> "20271015"
        } else dayKey
        return recC(c.subjects, c.locId,
            CharacterSystem.npcInside(c.locId), composition, key, weather)
    }
    val sP = stateAt(30)
    val pc = Commissions.boardOpen(sP)[0]
    check(Commissions.accept(sP, pc), "commissions: the completion test takes its ask")
    val coinsBefore = Minigames.capsuleCoins(sP)
    val frAskerBefore = sP.friendship[pc.asker] ?: 0
    val pRec = matchingRec(pc)
    Photos.applyPhoto(sP, pRec)
    check(sP.commissionsDone == 1,
        "commissions: a matching shutter lands the print")
    check(Minigames.capsuleCoins(sP) == coinsBefore + pc.pay,
        "commissions: the pay lands in capsule coins")
    check((sP.friendship[pc.asker] ?: 0) == frAskerBefore + Commissions.FRIENDSHIP,
        "commissions: the asker's friendship lands")
    check(pRec.isCommissioned && pRec.commissionAsker == pc.asker &&
        pRec.commissionText == pc.text,
        "commissions: the record wears its stamp (asker + the ask itself)")
    check("first_print" in sP.photoFeats,
        "commissions: the first-print feat lands on the same shutter")
    check(Commissions.lastNote(sP)?.line?.contains(pc.asker) == true &&
        sP.commissionRecent.size == 1,
        "commissions: the wall remembers the print")
    check(sP.phoneNotes.any { it.contains("|${Phone.COMMISSION}|") },
        "commissions: the asker will text about it in the morning")
    check(Commissions.boardOpen(sP).none { it.id == pc.id },
        "commissions: a landed ask leaves the cork for the week")
    Commissions.dailyRollover(sP)
    check(sP.commissions.none { it.id == pc.id },
        "commissions: a landed ask leaves the plate at rollover")

    // one photo, two asks: both pay, the first owns the stamp
    val s2 = stateAt(40)
    val shared = Commission("cx:1", "Stan", listOf(jA), locOut, "", "",
        "Stan's ask", 2, 0)
    val shared2 = Commission("cx:2", "Kyle", listOf(jA), locOut, "", "",
        "Kyle's ask", 3, 0)
    Commissions.accept(s2, shared); Commissions.accept(s2, shared2)
    val s2Rec = recC(listOf(jA), locOut, false)
    Photos.applyPhoto(s2, s2Rec)
    check(s2.commissionsDone == 2 && s2Rec.commissionAsker == "Stan",
        "commissions: one photo can satisfy two asks; the first owns the stamp")

    // ---------- near miss: honest words, once ----------
    val sN = stateAt(50)
    val nc = Commission("cn:1", "Wendy", listOf(jA), locOut, "", "",
        "Wendy's ask", 2, 0)
    Commissions.accept(sN, nc)
    Photos.applyPhoto(sN, recC(listOf(jA), locIn, true))   // right person, wrong place
    check(sN.commissionsDone == 0,
        "commissions: a near miss lands nothing")
    check(sN.lifeText["commNear:Wendy"] != null,
        "commissions: a near miss arms the asker's 'close, but…'")
    val talk1 = Commissions.talkLines(sN, "Wendy")
    check(talk1.any { it.text.contains("Close, but") } ||
        talk1.any { it.text.contains("adjacent") } ||
        talk1.any { it.text.contains("going for") },
        "commissions: the near-miss line plays in talk")
    val talk2 = Commissions.talkLines(sN, "Wendy")
    check(talk2.none { it.text.contains("Close, but") } &&
        sN.lifeText["commNear:Wendy"] == null,
        "commissions: the near-miss line plays exactly once")
    check(talk1.any { it.text.contains(Commissions.objective(nc)) },
        "commissions: a held ask reminds you what it is, in talk")
    check(talk2.isEmpty(),
        "commissions: the reminder is once a day, not a nag")

    // ---------- feats at their thresholds ----------
    val sF = stateAt(60)
    sF.commissionsDone = 9
    val fc = Commissions.boardOpen(sF)[0]
    Commissions.accept(sF, fc)
    Photos.applyPhoto(sF, matchingRec(fc))
    check(sF.commissionsDone == 10 && "print_10" in sF.photoFeats,
        "commissions: the tenth print earns Town Photographer")
    sF.commissionsDone = 25
    check(Photos.featMet(sF, matchingRec(fc), "print_25"),
        "commissions: 25 prints satisfy the fridge-door feat")

    // ---------- prints never fade ----------
    val sA = stateAt(70)
    repeat(Photos.ALBUM_CAP) { i ->
        Photos.applyPhoto(sA, recC(listOf(jA), locOut, false)
            .copy(id = "bulk$i", timeMin = 480 + i))
    }
    check(sA.photos.size == Photos.ALBUM_CAP,
        "commissions: the album fills to its cap as before")
    val ac = Commission("ca:1", "Stan", listOf(jA), locOut, "", "",
        "the forever shot", 2, 0)
    Commissions.accept(sA, ac)
    val printRec = recC(listOf(jA), locOut, false).copy(id = "theprint")
    Photos.applyPhoto(sA, printRec)
    check(printRec.isCommissioned && sA.photos.any { it.id == "theprint" },
        "commissions: the print files into a full album (an ordinary photo faded)")
    repeat(12) { i ->
        Photos.applyPhoto(sA, recC(listOf(jA), locOut, false)
            .copy(id = "after$i", timeMin = 500 + i))
    }
    check(sA.photos.any { it.id == "theprint" } &&
        sA.photos.size == Photos.ALBUM_CAP,
        "commissions: a dozen photos later, the print is still on the shelf")

    // ---------- save round-trip + decode discipline ----------
    val sS = stateAt(80)
    val sc = Commissions.boardOpen(sS)[0]
    Commissions.accept(sS, sc)
    sS.commissionsDone = 7
    sS.commissionLast["Stan"] = "Stan|Kyle|BusStop|:"
    sS.commissionRecent.add(CommissionNote("cz:0", sS.todayKey,
        "✔ an older print"))
    val stamped = recC(listOf(jA), locOut, false).copy(id = "savedprint")
    stamped.commissionAsker = "Stan"; stamped.commissionText = "the saved ask"
    sS.photos.add(stamped)
    val sBack = decodeGameState(encodeGameState(sS))
    val backHeld = sBack.commissions.firstOrNull { it.id == sc.id }
    check(backHeld != null && backHeld.asker == sc.asker &&
        backHeld.subjects == sc.subjects && backHeld.locId == sc.locId &&
        backHeld.condKind == sc.condKind && backHeld.pay == sc.pay &&
        backHeld.acceptedDay == sS.absDay &&
        backHeld.expiresDay == sS.absDay + Commissions.EXPIRY_DAYS - 1,
        "commissions: the plate round-trips through the real save path")
    check(sBack.commissionsDone == 7 && sBack.commissionLast["Stan"] != null &&
        sBack.commissionRecent.any { it.id == "cz:0" },
        "commissions: count, memory and wall round-trip")
    val backPrint = sBack.photos.firstOrNull { it.id == "savedprint" }
    check(backPrint != null && backPrint.isCommissioned &&
        backPrint.commissionAsker == "Stan" &&
        backPrint.commissionText == "the saved ask",
        "commissions: the print's stamp round-trips")
    // a pre-commissions save (no key at all) loads empty
    val sOld = decodeGameState(mapOf("timeMin" to 480))
    check(sOld.commissions.isEmpty() && sOld.commissionsDone == 0,
        "commissions: a v0.5.0i-era save loads with an empty plate")
    // hostile docs: caps + registry filtering
    val hostile = (0 until Commissions.STATE_CAP + 5).map { i ->
        Commission("h$i", "Stan", listOf("Kyle"), "BusStop", "", "",
            "x", 1, 0).toMap()
    }
    val bad = listOf(
        Commission("bad1", "Stan", listOf("Kyle"), "BusStop", "", "", "x", 1, 0)
            .toMap() + ("asker" to "Nobody"),
        Commission("bad2", "Stan", listOf("Kyle"), "BusStop", "", "", "x", 1, 0)
            .toMap() + ("subjects" to listOf("Ghost")),
        Commission("bad3", "Stan", listOf("Kyle"), "BusStop", "", "", "x", 1, 0)
            .toMap() + ("locId" to "Nowhere"))
    val sHostile = decodeGameState(mapOf("commissions" to mapOf(
        "plate" to (hostile + bad), "done" to 3)))
    check(sHostile.commissions.size == Commissions.STATE_CAP,
        "commissions: a hand-inflated plate decodes to the cap " +
            "(got ${sHostile.commissions.size})")
    check(sHostile.commissions.none { it.id.startsWith("bad") },
        "commissions: records naming nobody/nowhere are dropped at decode")

    // ---------- the page + the wiring ----------
    val page = Commissions.pageLines(sP)
    check(page.first().contains("COMMISSIONS") && page.size > 3,
        "commissions: the page assembles (plate, cork, wall)")
    check(Phone.COMMISSION in Phone.NOTE_KINDS &&
        Phone.COMMISSION in Phone.TRIGGERS,
        "commissions: the phone carries the commission note kind")
    val photosSrc = File(root,
        "src/com/hunt3r/southparktown/Photos.kt").readText()
    check(photosSrc.contains("Commissions.onPhoto(state, rec)"),
        "commissions: applyPhoto judges commissions on the shutter")
    val journalSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(journalSrc.contains("Commissions.pageLines(state)") &&
        journalSrc.contains("rec.isCommissioned"),
        "commissions: the Journal hosts the page and the album wears the stamp")
    val gameSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gameSrc.contains("Commissions.talkLines(state, npcName)"),
        "commissions: the Talk sheet carries the asker's words")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.6.0a"),
        "commissions: the v0.6.0a changelog section exists")
}

private fun sectionV060b(root: String) {
// ================= v0.6.0b: errands #2 — favor chains =================
// Queue #6 item 2. Some generated asks are the head of a
// chain of 2–3 links: completing a link reveals the next —
// a favor for the link's beneficiary, or their relation —
// and the final link closes back on the origin asker with
// a bonus. The chain is the unit: one plate slot, one
// Journal thread, one drop. Generation is stamped, never
// re-rolled: the plan is a pure function of the ask, so
// boards stay deterministic and hand-built errands (every
// older section's fabrications) never chain.
println("== v0.6.0b: favor chains ==")
run {
    val eng = Engine(407)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Chain", DEFAULT_APPEARANCE)
        return s
    }
    // run one live errand through its own judge, the way a
    // player (and the lifetime soak) would
    fun runErrand(s: GameState, e: Errand): ErrandCompletion? = when (e.type) {
        "FETCH" -> {
            s.inventory[e.itemId!!] = (s.inventory[e.itemId] ?: 0) + 1
            Errands.handInFetch(s, e.asker, e.itemId!!)
        }
        "DELIVER" -> Errands.deliverTo(s, e.targetName!!)
        "FIND" -> Errands.recoverFind(s, e.targetLoc!!)
        "FIX" -> Errands.onFixTap(s, e.fixKind!!,
            e.targetLoc ?: Errands.flickerLoc(s.absDay))
        "PHOTO" -> Errands.onPhoto(s, PhotoRecord(
            id = "cb${e.id.hashCode()}", dayKey = s.todayKey,
            dateLabel = "?", timeMin = 720,
            locId = e.targetLoc ?: "MainStreet", inside = false,
            weatherId = s.weatherId, appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Chain", "player", "happy"),
                PhotoFigure(e.targetName ?: "Stan", "cast", "happy")),
            seed = 3L, absDay = s.absDay)).firstOrNull()
        else -> when {
            e.playKind?.startsWith("fish:") == true ->
                Errands.onPlayCatch(s,
                    e.playKind.removePrefix("fish:")).firstOrNull()
            e.playKind == "showdown" ->
                Errands.onPlayShowdown(s, true).firstOrNull()
            else -> Errands.onPlayTaco(s, 999).firstOrNull()
        }
    }
    fun coins(s: GameState): Int = Minigames.capsuleCoins(s)
    fun errandNotes(s: GameState): Int =
        s.phoneNotes.count { it.contains("|errand|") }

    // ---------- the dials ----------
    check(Errands.CHAIN_CHANCE_BOARD in 0.1..0.5 &&
        Errands.CHAIN_CHANCE_ASK in 0.1..0.5 &&
        Errands.CHAIN_CHANCE_SHOP > 0.0 &&
        Errands.CHAIN_CHANCE_SHOP < Errands.CHAIN_CHANCE_BOARD,
        "chains: the rates are named dials — board/ask modest, " +
            "shop rare (${Errands.CHAIN_CHANCE_BOARD} / " +
            "${Errands.CHAIN_CHANCE_ASK} / ${Errands.CHAIN_CHANCE_SHOP})")
    check(Errands.CHAIN_MAX_LINKS == 3 &&
        Errands.CHAIN_BONUS_COINS_PER_LINK > 0 &&
        Errands.CHAIN_BONUS_FRIENDSHIP_PER_LINK > 0,
        "chains: at most 3 links, and the closing bonus is real")
    check(Errands.CHAIN_FEATS.map { it.at } == listOf(1, 10) &&
        Errands.ERRAND_FEATS.map { it.at } == listOf(10, 50, 150),
        "chains: chain feats land at 1 / 10 chains; the errand " +
            "feats are untouched")
    check(Errands.CHAIN_TOPIC == "favor chain",
        "chains: the planted topic is the town's own phrase")

    // ---------- generation: stamped, deterministic, minority ----------
    val engB = Engine(408)
    val sB = engB.newState()
    engB.createPlayer(sB, "Board", DEFAULT_APPEARANCE)
    var postings = 0; var singles = 0; var len2 = 0; var len3 = 0
    repeat(60) { d ->
        if (d > 0) engB.onNewDay(sB)
        for (e in Errands.boardFor(sB)) {
            postings++
            check(e.chainLink == 0 && e.chainRest.isEmpty() &&
                e.chainFrom == null,
                "chains: a posting is an untaken head or a single")
            when (e.chainLen) {
                0 -> singles++
                2 -> len2++
                3 -> len3++
                else -> check(false,
                    "chains: a stamped length is 0, 2 or 3")
            }
        }
    }
    val heads = len2 + len3
    check(heads >= 3 && heads < singles,
        "chains: heads are a minority of the board " +
            "($heads of $postings postings)")
    check(len2 > 0 && len3 > 0,
        "chains: both lengths occur ($len2 twos, $len3 threes)")
    // the board (stamps included) is the same pure function
    // of the day it always was
    val twin1 = freshState(); val twin2 = freshState()
    check(Errands.boardFor(twin1) == Errands.boardFor(twin2),
        "chains: twin states derive identical boards, stamps and all")
    // direct asks and shop asks carry the stamp too — scan a
    // month of mornings for both
    val engA = Engine(409)
    val sA = engA.newState()
    engA.createPlayer(sA, "Asked", DEFAULT_APPEARANCE)
    var askHeads = 0; var shopHeads = 0; var shopOffers = 0
    repeat(30) { d ->
        if (d > 0) engA.onNewDay(sA)
        for (npc in KID_ORDER) {
            val a = Errands.askFor(sA, npc) ?: continue
            if (a.chainLen >= 2) askHeads++
        }
        for ((loc, npc) in Errands.SHOP_ASKERS) {
            val sh = Errands.shopAskFor(sA, npc, loc) ?: continue
            shopOffers++
            if (sh.chainLen >= 2) shopHeads++
        }
    }
    check(askHeads >= 1,
        "chains: direct asks chain too ($askHeads in a month)")
    check(shopHeads >= 1 && shopHeads < maxOf(shopOffers / 2, 1),
        "chains: shop asks chain, rarely ($shopHeads of $shopOffers offers)")

    // ---------- find one head of each length ----------
    fun headOfLength(len: Int): Pair<GameState, Errand> {
        val e2 = Engine(410L + len)
        val s = e2.newState()
        e2.createPlayer(s, "Seeker$len", DEFAULT_APPEARANCE)
        repeat(150) { d ->
            if (d > 0) e2.onNewDay(s)
            Errands.boardOpen(s).firstOrNull { it.chainLen == len }
                ?.let { return s to it }
        }
        throw IllegalStateException("no len-$len head in 150 days")
    }

    // ---------- the walk: completability, accounting, pay ----------
    fun walkChain(len: Int) {
        val (s, head) = headOfLength(len)
        val origin = head.asker
        check(Errands.chainTeaser(head) != null,
            "chains: a head on offer carries the teaser (len $len)")
        val coinsBefore = coins(s)
        val frBefore = s.friendship[origin] ?: 0
        val notesBefore = errandNotes(s)
        check(Errands.accept(s, head), "chains: the head takes (len $len)")
        val placed = Errands.active(s).first { it.id == head.id }
        check(placed.chainLink == 1 && placed.chainFrom == origin &&
            placed.chainId == "c:" + head.id &&
            placed.chainRest.size == len - 1,
            "chains: taking a head grows its tail behind it (len $len)")
        // the tail was composed whole: every link names a
        // real person and validates against the world
        for (link in placed.chainRest) {
            check(link.asker in KID_ORDER && link.chainFrom == origin &&
                link.chainLen == len,
                "chains: link ${link.chainLink} of $len is composed " +
                    "for ${link.asker}, under $origin")
            check(Errands.linkStillValid(link),
                "chains: link ${link.chainLink} of $len is completable " +
                    "as composed (${link.type})")
        }
        if (len == 3) {
            check(placed.chainRest.last().asker == origin,
                "chains: a 3-chain's final link returns to its asker")
            check(placed.chainRest.first().asker != origin,
                "chains: a 3-chain's middle link walks away first")
        }
        var expectedCoins = coinsBefore
        var landed = 0
        var guard = 0
        while (guard++ < 6) {
            val liveLinks = Errands.active(s)
                .filter { it.chainId == placed.chainId }
            check(liveLinks.size == 1,
                "chains: exactly one live link holds the plate slot")
            val link = liveLinks.first()
            check(link.chainLink == landed + 1,
                "chains: links land in order (${link.chainLink})")
            check(link.chainPrior.size == landed,
                "chains: the thread remembers $landed landed links")
            expectedCoins += Errands.COINS[link.type] ?: 0
            val c = runErrand(s, link)
            check(c != null, "chains: link ${link.chainLink} of $len " +
                "runs through its judge (${link.type})")
            c!!
            landed++
            if (landed < len) {
                check(c.reward.chainNext != null &&
                    !c.reward.chainFinished,
                    "chains: a mid link reveals, never closes")
                check(c.reward.chainRevealLine != null &&
                    c.reward.chainRevealLine.contains(
                        c.reward.chainNext!!.asker),
                    "chains: the reveal names the next pair of hands")
                check(errandNotes(s) == notesBefore,
                    "chains: no morning text mid-chain — the asker " +
                        "texts at the end")
                check(Errands.chainsDone(s) == 0,
                    "chains: an open chain is not a finished one")
            } else {
                check(c.reward.chainFinished && c.reward.chainNext == null,
                    "chains: the final link closes the chain")
                check(c.reward.chainBonusCoins ==
                    Errands.CHAIN_BONUS_COINS_PER_LINK * len &&
                    c.reward.chainBonusFriendship ==
                    Errands.CHAIN_BONUS_FRIENDSHIP_PER_LINK * len,
                    "chains: the closing bonus scales with the chain")
                break
            }
        }
        check(landed == len, "chains: a len-$len chain lands $len links")
        check(Errands.active(s).none { it.chainId == placed.chainId },
            "chains: a closed chain leaves the plate")
        check(s.errandsDoneCount == len,
            "chains: every link counts toward the errand feats")
        check(Errands.chainsDone(s) == 1,
            "chains: and the chain itself counts, once")
        expectedCoins += Errands.CHAIN_BONUS_COINS_PER_LINK * len
        check(coins(s) == expectedCoins,
            "chains: the pay is link rates + the closing bonus " +
                "(${coins(s)} vs $expectedCoins)")
        check((s.friendship[origin] ?: 0) - frBefore >=
            Errands.CHAIN_BONUS_FRIENDSHIP_PER_LINK * len,
            "chains: the origin asker's friendship carries the bonus")
        check(errandNotes(s) == notesBefore + 1 &&
            s.phoneNotes.any { it.contains("|errand|$origin") },
            "chains: exactly one morning text, from the origin asker")
        check(NpcMemoryStore.get(origin)?.topics
            ?.contains(Errands.CHAIN_TOPIC) == true,
            "chains: the origin carries the favor-chain topic")
        check(s.lifeText["chainBeat"]?.contains(origin) == true,
            "chains: the morning beat is written for $origin")
        // determinism: the same head, taken again in a twin
        // world, grows the identical tail
        val (sT, headT) = headOfLength(len)
        check(Errands.accept(sT, headT), "chains: twin head takes")
        val placedT = Errands.active(sT).first { it.id == headT.id }
        check(placedT.chainRest == placed.chainRest,
            "chains: the same posting grows the same chain, anywhere")
    }
    walkChain(2)
    walkChain(3)

    // ---------- substitution: the world moved, the chain didn't strand ----------
    val sSub = freshState()
    val badLink = Errand(id = "c:sub:2", source = Errands.BOARD,
        asker = "Kyle", type = "FETCH", text = "t", hint = "h",
        itemId = "not_a_real_item", dayKey = sSub.todayKey,
        chainId = "c:sub", chainLink = 2, chainLen = 2,
        chainFrom = "Stan")
    check(!Errands.linkStillValid(badLink),
        "chains: a link naming nothing real fails validation")
    sSub.errands.add(Errand(id = "sub", source = Errands.BOARD,
        asker = "Stan", type = "DELIVER", text = "t", hint = "h",
        targetName = "Kyle", dayKey = sSub.todayKey,
        chainId = "c:sub", chainLink = 1, chainLen = 2,
        chainFrom = "Stan", chainRest = listOf(badLink)))
    val cSub = Errands.deliverTo(sSub, "Kyle")
    check(cSub?.reward?.chainNext != null,
        "chains: a stale link is substituted, never stranded")
    val placedSub = cSub!!.reward.chainNext!!
    check(placedSub.type == "FETCH" && placedSub.asker == "Kyle" &&
        placedSub.itemId in Errands.FETCH_POOL,
        "chains: the substitute is equivalent — same type, same " +
            "person, an item the world can produce")
    check(placedSub.chainLink == 2 && placedSub.chainFrom == "Stan" &&
        placedSub.id == badLink.id,
        "chains: the substitute keeps its place, name and chain")
    val cSub2 = runErrand(sSub, placedSub)
    check(cSub2?.reward?.chainFinished == true &&
        Errands.chainsDone(sSub) == 1,
        "chains: a substituted chain still closes")

    // ---------- mid-chain saves ----------
    val (sMid, headMid) = headOfLength(3)
    check(Errands.accept(sMid, headMid), "chains: mid-chain head takes")
    val midFirst = Errands.active(sMid).first { it.chainId != null }
    check(runErrand(sMid, midFirst) != null,
        "chains: the first link lands before the save")
    val midBack = decodeGameState(encodeGameState(sMid))
    val midLive = Errands.active(midBack)
        .firstOrNull { it.chainId != null }
    check(midLive != null && midLive.chainLink == 2 &&
        midLive.chainPrior.size == 1 &&
        midLive.chainRest.size == 1 &&
        midLive.chainFrom == headMid.asker,
        "chains: a mid-chain save round-trips — live link, thread " +
            "and tail intact")
    check(Errands.chainsDone(midBack) == 0,
        "chains: the saved chain is still open")
    var midGuard = 0
    while (midGuard++ < 4) {
        val l = Errands.active(midBack)
            .firstOrNull { it.chainId != null } ?: break
        if (runErrand(midBack, l) == null) break
    }
    check(Errands.chainsDone(midBack) == 1,
        "chains: a loaded chain still closes")
    // a pre-chain save (no chain keys at all) decodes as singles
    val plainMap = Errand(id = "old", source = Errands.BOARD,
        asker = "Stan", type = "FETCH", text = "t", hint = "h",
        itemId = "flower", dayKey = "20000101").toMap()
    check(!plainMap.containsKey("chainLen"),
        "chains: singles serialize exactly as they always have")
    val plainBack = Errand.fromMap(plainMap)
    check(plainBack != null && plainBack.chainLen == 0 &&
        plainBack.chainRest.isEmpty(),
        "chains: an old record decodes as the single it is")

    // ---------- hostile decode ----------
    val hostile = plainMap.toMutableMap()
    hostile["chainLen"] = 99; hostile["chainLink"] = 7
    hostile["chainFrom"] = "Stan"; hostile["chainId"] = "c:evil"
    hostile["chainRest"] = listOf(hostile)
    val decHostile = Errand.fromMap(hostile)
    check(decHostile != null && decHostile.chainLen == 0 &&
        decHostile.chainRest.isEmpty(),
        "chains: an inflated, self-nesting chain doc decodes as " +
            "a single")
    val tailLink = Errand(id = "c:cap:2", source = Errands.BOARD,
        asker = "Kyle", type = "FETCH", text = "t", hint = "h",
        itemId = "flower", dayKey = "d", chainId = "c:cap",
        chainLink = 2, chainLen = 2, chainFrom = "Stan")
    val capDoc = plainMap.toMutableMap()
    capDoc["chainLen"] = 2; capDoc["chainLink"] = 1
    capDoc["chainFrom"] = "Stan"; capDoc["chainId"] = "c:cap"
    capDoc["chainRest"] = listOf(tailLink.toMap(), tailLink.toMap(),
        tailLink.toMap())
    val decCap = Errand.fromMap(capDoc)
    check(decCap != null && decCap.chainRest.size == 1 &&
        decCap.chainRest.first().chainRest.isEmpty(),
        "chains: the stored tail is capped at the links left, " +
            "and tails carry no tails")

    // ---------- drop semantics ----------
    val (sDrop, headDrop) = headOfLength(2)
    check(Errands.accept(sDrop, headDrop), "chains: drop-test head takes")
    val dropFirst = Errands.active(sDrop).first { it.chainId != null }
    check(runErrand(sDrop, dropFirst) != null,
        "chains: drop-test first link lands")
    val dropLive = Errands.active(sDrop).first { it.chainId != null }
    check(Errands.displayAsker(dropLive) == headDrop.asker,
        "chains: a chain answers to its origin asker")
    val sigh = Errands.abandon(sDrop, dropLive.id)
    check(sigh != null && Errands.active(sDrop).isEmpty() &&
        Errands.chainsDone(sDrop) == 0,
        "chains: dropping the live link drops the whole chain, " +
            "with the sigh and no credit")

    // ---------- gossip: the town watches ----------
    fun gossipState(): GameState {
        val s = freshState()
        s.errands.add(Errand(id = "g link", source = Errands.BOARD,
            asker = "Kyle", type = "FETCH", text = "t", hint = "h",
            itemId = "flower", dayKey = s.todayKey,
            chainId = "c:gossip", chainLink = 2, chainLen = 3,
            chainFrom = "Stan"))
        s.timeMin = 12 * 60
        return s
    }
    val friend = relationsOf("Stan")
        .first { it in KID_ORDER && it != "Kyle" && it != "Stan" }
    val stranger = KID_ORDER.first { it != "Stan" && it != "Kyle" &&
        it !in relationsOf("Stan") }
    val sG = gossipState()
    check(Errands.chainGossipLine(sG, "Stan") == null &&
        Errands.chainGossipLine(sG, "Kyle") == null,
        "gossip: the involved don't gossip about their own chain")
    check(Errands.chainGossipLine(sG, stranger) == null,
        "gossip: no relation to the asker, no opinion")
    val gLine = Errands.chainGossipLine(sG, friend)
    check(gLine != null && gLine.speaker == friend &&
        gLine.text.contains("Stan"),
        "gossip: a friend of the origin names the chain")
    check(Errands.chainGossipLine(sG, friend) == null,
        "gossip: once per chain per day, then the town moves on")
    val sG2 = gossipState()
    check(TalkGate.owedLines(sG2, friend)
        .any { it.text.contains("CHAIN") || it.text.contains("chain") },
        "gossip: the owed-lines rail carries the town's piece")
    val sG3 = gossipState()
    sG3.timeMin = 23 * 60
    check(Errands.chainGossipLine(sG3, friend) == null,
        "gossip: quiet hours are quiet")

    // ---------- the follow-up bank answers the topic ----------
    val mem = NpcMemoryStore.getOrCreate("ChainWatcher")
    mem.meets = 5
    mem.topics.clear()
    mem.topics.add(Errands.CHAIN_TOPIC)
    val fu = Threads.followUp(mem, kotlin.random.Random(3))
    check(fu != null && (fu.contains("last link") ||
        fu.contains("middle part") || fu.contains("era")),
        "threads: the favor-chain follow-up bank answers the " +
            "planted topic")

    // ---------- the Journal thread ----------
    val (sPage, headPage) = headOfLength(3)
    val boardLine = Errands.pageLines(sPage)
        .firstOrNull { it.contains("posted it") &&
            it.contains(headPage.asker) }
    check(boardLine != null && boardLine.contains("🧵"),
        "chains: today's board marks a posting that tangles")
    check(Errands.accept(sPage, headPage), "chains: page head takes")
    val pageFirst = Errands.active(sPage).first { it.chainId != null }
    check(runErrand(sPage, pageFirst) != null,
        "chains: page chain's first link lands")
    val page = Errands.pageLines(sPage)
    check(page.any { it.contains("🧵 CHAIN for ${headPage.asker}") },
        "chains: the Journal shows the chain as its own thread")
    check(page.any { it.contains("✓") && it.contains("▶") &&
        it.contains("🏁 ${headPage.asker}") },
        "chains: the thread reads landed → live → home")

    // ---------- the morning beat ----------
    val sBeat = freshState()
    sBeat.life["chainBeatDay"] = sBeat.absDay - 1 // yesterday
    sBeat.lifeText["chainBeat"] =
        "the favor chain for Stan pulled its next thread — " +
            "link 1 of 3 landed; next: bring a flower to Kyle"
    check(House.morningReport(sBeat, emptyList(), emptyMap(), 0,
        false, null).any { it.contains("🧵") && it.contains("favor chain") },
        "chains: the morning report carries yesterday's chain beat")

    // ---------- singles are singles ----------
    val sSingle = freshState()
    val single = Errand(id = "plain1", source = Errands.ASK,
        asker = "Wendy", type = "FETCH", text = "t", hint = "h",
        itemId = "flower", dayKey = sSingle.todayKey)
    check(Errands.accept(sSingle, single), "chains: a single takes")
    val cSingle = runErrand(sSingle,
        Errands.active(sSingle).first())
    check(cSingle != null && cSingle.reward.chainNext == null &&
        !cSingle.reward.chainFinished &&
        Errands.chainsDone(sSingle) == 0 &&
        Errands.active(sSingle).isEmpty(),
        "chains: a single completes as a single — no reveal, " +
            "no bonus, nothing left behind")
    check(errandNotes(sSingle) == 1,
        "chains: a single's morning text still fires, as ever")

    // ---------- the wiring ----------
    val gameSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gameSrc.contains("Errands.chainTeaser(theAsk)") &&
        gameSrc.contains("Errands.chainDialogText(r)") &&
        gameSrc.contains("Errands.chainToastSuffix("),
        "chains: the offer, delivery and judge surfaces speak chain")
    val talkSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(talkSrc.contains("Errands.chainGossipLine(state, npcName)"),
        "chains: gossip rides the owed-lines rail")
    val journalSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(journalSrc.contains("Errands.displayAsker(e)"),
        "chains: the Journal names the origin asker on a drop")
    val collSrc = File(root,
        "src/com/hunt3r/southparktown/CollectionActivity.kt").readText()
    check(collSrc.contains("Errands.CHAIN_FEATS"),
        "chains: the Collection shows the chain feats")
    val threadsSrc = File(root,
        "src/com/hunt3r/southparktown/Threads.kt").readText()
    check(threadsSrc.contains("\"favor chain\" to listOf("),
        "chains: Threads carries the favor-chain follow-up bank")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.6.0b"),
        "chains: the v0.6.0b changelog section exists")
}
}

private fun sectionV060c(root: String) {
// ================= v0.6.0c: mystery arc #4, "The Night Gardener" =================
// Queue #6 item 3. The fourth case keeps the discipline of
// the first three — chapters on the episode machinery, fair
// clues, a gated dialogue-safe finale, permanent marks,
// retirement — with a fourth skeleton: the investigation
// follows FIXES, not a crime. Somebody is quietly repairing
// the town at night; the finale is a vigil, and the choice
// is about gratitude, not guilt. The secret itself is never
// printed in this section beyond what the spoiler scan needs
// to hunt for.
    println("== v0.6.0c: mystery arc #4 — the night gardener ==")
    val eng4 = Engine(6060)
    fun baseInf4(id: String) = FACTIONS.first { it.id == id }.baseInfluence
    val secretName = Mystery4.CULPRIT

    // ---------- def integrity ----------
    check(Mystery4.CHAPTERS4.size == 4, "gardener: four chapters (one per fix)")
    check(Mystery4.CHAPTERS4.map { it.id }.distinct().size == 4,
        "gardener: chapter ids are unique")
    check(Mystery4.CHAPTERS4[3].id == Mystery4.FINALE4_ID,
        "gardener: the last chapter is the finale (the vigil)")
    val regularIds4 = SHENANIGANS.map { it.id }.toSet()
    for (def in Mystery4.CHAPTERS4) {
        check(def.stages.size == 4 && def.causers.isNotEmpty() &&
            def.episodeTitles.size == 2 && def.coldOpen.isNotEmpty() &&
            def.theme.header.isNotBlank(),
            "gardener: ${def.id} carries the full episode kit " +
                "(4 stages, causers, 2 titles, cold open)")
        check(def.id !in regularIds4 && SHENANIGAN_BY_ID[def.id] == def,
            "gardener: ${def.id} is not in the random pool but resolves by id")
        check(def.id !in Mystery.ARC_CHAPTERS.map { it.id } &&
            def.id !in Mystery2.BEATS.map { it.id } &&
            def.id !in Mystery3.CHAPTERS3.map { it.id },
            "gardener: ${def.id} is its own case, not an earlier one")
    }
    check(SHENANIGANS.size == 10, "gardener: the random pool is still the ten")
    check(Mystery4.CHAPTERS4.map { it.stages[2].clusterLoc } ==
        listOf("KidsPark", "MainStreet", "CityHall", "Elementary"),
        "gardener: the climaxes gather at the park, the fountain, the hall, the schoolyard")

    // ---------- the clue registry ----------
    check(Mystery4.CLUES4.size == 12, "gardener: twelve clues on the board")
    check(Mystery4.CLUES4.map { it.id }.distinct().size == 12 &&
        Mystery4.CLUES4.all { it.id in Mystery4.CLUE4_IDS },
        "gardener: clue ids are unique")
    check(Mystery4.CLUES4.count { it.kind == Mystery4.Kind4.PATTERN } == 2 &&
        Mystery4.CLUES4.count { it.kind == Mystery4.Kind4.MATERIAL } == 2 &&
        Mystery4.CLUES4.count { it.kind == Mystery4.Kind4.CRAFT } == 2 &&
        Mystery4.CLUES4.count { it.kind == Mystery4.Kind4.WITNESS } == 4 &&
        Mystery4.CLUES4.count { it.kind == Mystery4.Kind4.PARTICIPATION } == 2,
        "gardener: clues split 2 pattern / 2 material / 2 craft / 4 witnesses / 2 participations")
    for (clue in Mystery4.CLUES4) {
        check(clue.detail.isNotBlank(), "gardener: ${clue.id} carries its flavor")
        check(clue.minChapter in 0..3,
            "gardener: ${clue.id} opens inside the four chapters")
        // delivery channel is what matters, not the kind: a
        // clue reaches the player by a witness's mouth, a
        // Look at its place, or a shift worked on its turf —
        // and the spine is a PATTERN carried by a witness.
        when {
            clue.spoken != null -> check(
                clue.npc != null && clue.npc in AGENT_PROFILES,
                "gardener: ${clue.id}'s witness is a real cast member who speaks")
            clue.chapterDefId != null -> check(
                clue.chapterDefId in Mystery4.CHAPTER4_BY_ID,
                "gardener: ${clue.id} is earned at a real gardener chapter")
            else -> check(
                clue.locId != null && clue.locId in LOCATIONS &&
                    !clue.foundText.isNullOrBlank(),
                "gardener: ${clue.id} is hidden at a real location")
        }
        // FAIRNESS + SPOILER, in one pin: no clue — title,
        // detail, telling or find — ever names the fixer.
        // The case is assembled, never announced.
        val surfaces = listOf(clue.title, clue.detail,
            clue.spoken ?: "", clue.foundText ?: "")
        check(surfaces.none { it.contains(secretName) },
            "gardener: ${clue.id} never names the fixer (fair + sealed)")
    }
    check(Mystery4.VIGIL_MIN_CLUES in 1 until Mystery4.CLUES4.size,
        "gardener: the vigil gate sits inside the clue count")
    check(Mystery4.CHOICE_KEYS.size == 3 &&
        Mystery4.BRANCH_KEYS == Mystery4.CHOICE_KEYS + Mystery4.DEFAULT_BRANCH,
        "gardener: three calls can be made at the vigil; the fourth is the default")

    // ---------- the tell's spine, pinned as data ----------
    // The deduction must be mechanically real: one complaint
    // in the posted record (Look, City Hall), one complaint
    // that was never written down (the minutes-keeper's own
    // telling) — so the fixer was in the room. The room, the
    // garden, the size, the soil: four witnesses, four legs.
    val spine = Mystery4.CLUE4_BY_ID.getValue("unminuted_complaint")
    check(spine.kind == Mystery4.Kind4.PATTERN && spine.npc == "Gerald" &&
        spine.detail.contains("never") && spine.minChapter == 2,
        "gardener: the spine is the un-minuted complaint, told by the minutes-keeper")
    val minuted = Mystery4.CLUE4_BY_ID.getValue("complaint_match")
    check(minuted.kind == Mystery4.Kind4.PATTERN && minuted.locId == "CityHall" &&
        minuted.minChapter == 0,
        "gardener: the minuted complaint is on the public record from chapter 1")
    check(Mystery4.CLUES4.mapNotNull { it.npc }.toSet() ==
        setOf("McDaniels", "Barbrady", "Gerald", "Garrison", "Ned"),
        "gardener: the room, the keeper, the teacher and the night all testify")
    check(secretName in KID_ORDER && secretName != "Ned" &&
        Mystery4.CLUES4.none { it.npc == secretName },
        "gardener: the fixer is a real cast kid who is nobody's witness")
    check(Mystery4.CLUE4_BY_ID.getValue("herring_nail").kind == Mystery4.Kind4.CRAFT &&
        Mystery4.CLUE4_BY_ID.getValue("herring_nail").locId == "StarksPond",
        "gardener: the herring clears himself by his own nail, at the gate")

    // ---------- the fix sites & their tokens ----------
    check(Mystery4.FIX_SITES.size == 5, "gardener: five fix sites")
    check(Mystery4.FIX_SITES.map { it.chapter } == listOf(0, 1, 1, 2, 3),
        "gardener: the fixes land bench / fountain+gate / planters / the watched rope")
    check(Mystery4.FIX_SITES.all { it.locId in LOCATIONS },
        "gardener: every fix sits at a real location")
    val siteToks4 = Mystery4.FIX_SITES.flatMap { it.tokens }
    check(siteToks4.distinct().size == siteToks4.size &&
        Mystery4.FIX_TOKENS == siteToks4.toSet() + Mystery4.PORCH_TOKEN +
            Mystery4.EXTRA_FIXES.map { it.token }.toSet(),
        "gardener: fix tokens are unique; the registry is sites + porch + the endings' tails")
    val sceneSrc4 = File(root, "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    for (tok in Mystery4.FIX_TOKENS) {
        check(sceneSrc4.contains("fix: $tok"),
            "gardener: the fix layer draws $tok")
        check(Depth.tokenBand(tok) == Band.BACKGROUND,
            "gardener: $tok is banded with the scene's own dressing")
    }
    // which fixes stand, state by state — a fix, once made,
    // is made FOREVER (the dig sites grassed over; these don't)
    val sFix = eng4.newState()
    check(Mystery4.fixTokensByLoc(sFix).isEmpty() &&
        Mystery4.fixLookText(sFix, "KidsPark") == null,
        "gardener: no repairs before the case exists")
    sFix.arcRetired = true; sFix.arc2Retired = true; sFix.arc3Retired = true
    sFix.arc4Started = true; sFix.arc4Chapter = 1
    check(Mystery4.fixTokensByLoc(sFix) ==
        mapOf("KidsPark" to listOf("gard-bench")),
        "gardener: chapter 1 leaves the bench standing")
    check(Mystery4.fixLookText(sFix, "KidsPark")?.contains("rock-solid") == true,
        "gardener: the bench reads mended in the Look text")
    sFix.arc4Chapter = 2
    check(Mystery4.fixTokensByLoc(sFix)["MainStreet"] == listOf("gard-fountain") &&
        Mystery4.fixTokensByLoc(sFix)["StarksPond"] == listOf("gard-gate"),
        "gardener: chapter 2 connects the fountain and the older gate")
    sFix.arc4Chapter = 3
    check(Mystery4.fixTokensByLoc(sFix)["CityHall"] == listOf("gard-planters"),
        "gardener: chapter 3 leaves the planters blooming")
    sFix.arc4Chapter = 4
    check(Mystery4.fixTokensByLoc(sFix)["Elementary"] == null &&
        Mystery4.fixLookText(sFix, "Elementary")?.contains("frayed") == true,
        "gardener: in the vigil week the rope still hangs frayed — and watched")
    sFix.arc4Retired = true; sFix.arc4Branch = "cold"; sFix.arc4RetiredDay = sFix.absDay
    check(Mystery4.fixTokensByLoc(sFix)["Elementary"] == null &&
        (Mystery4.fixTokensByLoc(sFix)["KidsPark"] == listOf("gard-bench")),
        "gardener: a cold close keeps the old fixes and never makes the rope")
    sFix.arc4Branch = "guard"
    check(Mystery4.fixTokensByLoc(sFix)["Elementary"] == listOf("gard-rope"),
        "gardener: a kept vigil leaves the rope sound")
    // the endings' tails, on their own clocks
    check(Mystery4.extraFixesStanding(sFix).isEmpty(),
        "gardener: the kept secret's fixes haven't started on day one")
    sFix.absDay = sFix.arc4RetiredDay + 30
    check(Mystery4.extraFixesStanding(sFix).map { it.token } == listOf("gard-sign"),
        "gardener: a month on, the bus sign stands straight")
    sFix.absDay = sFix.arc4RetiredDay + 105
    check(Mystery4.extraFixesStanding(sFix).map { it.token } ==
        listOf("gard-sign", "gard-swing", "gard-railing"),
        "gardener: the guarded town keeps being quietly repaired")
    check(Mystery4.fixLookText(sFix, "BusStop")?.contains("bus-stop sign") == true,
        "gardener: the sign reads fixed in the Look text too")
    val sJoinFx = eng4.newState()
    sJoinFx.arc4Retired = true; sJoinFx.arc4Branch = "join"
    sJoinFx.arc4RetiredDay = 50; sJoinFx.absDay = 50 + 20
    check(Mystery4.extraFixesStanding(sJoinFx).isEmpty(),
        "gardener: the joined fixes wait their turn too")
    sJoinFx.absDay = 50 + 21
    check(Mystery4.extraFixesStanding(sJoinFx).map { it.token } ==
        listOf("gard-joined-bench"),
        "gardener: three weeks on, the first two-hands fix stands")

    // ---------- scheduling: the case queues behind ALL THREE ----------
    val sGate4 = eng4.newState()
    check(Mystery4.dueChapter4(sGate4) == null && sGate4.arc4DueAbsDay == -1,
        "gardener: while the pond case is open, this one does not even schedule")
    sGate4.arcRetired = true; sGate4.arc2Retired = true
    check(Mystery4.dueChapter4(sGate4) == null && sGate4.arc4DueAbsDay == -1,
        "gardener: while the buried case is open, this one still waits")
    sGate4.arc3Retired = true; sGate4.arc3RetiredDay = 100; sGate4.absDay = 100
    check(Mystery4.dueChapter4(sGate4) == null &&
        sGate4.arc4DueAbsDay == 100 + Mystery4.OPEN_DELAY_DAYS,
        "gardener: the first ask after the dig retires books chapter 1 ten days out")
    sGate4.absDay = sGate4.arc4DueAbsDay - 1
    check(Mystery4.dueChapter4(sGate4) == null, "gardener: chapter 1 is never early")
    sGate4.absDay = sGate4.arc4DueAbsDay
    check(Mystery4.dueChapter4(sGate4)?.id == Mystery4.CHAPTERS4[0].id,
        "gardener: chapter 1 is due on its day")
    sGate4.holidayId = "halloween"
    check(Mystery4.dueChapter4(sGate4) == null,
        "gardener: a due chapter defers for a holiday episode")
    sGate4.holidayId = null
    check(Mystery4.dueChapter4(sGate4)?.id == Mystery4.CHAPTERS4[0].id,
        "gardener: ...and is due again the moment the holiday clears")
    Mystery4.noteChapterStarted4(sGate4, Mystery4.CHAPTERS4[0])
    check(sGate4.arc4Started && sGate4.arc4Chapter == 1 &&
        sGate4.arc4DueAbsDay == sGate4.absDay + Mystery4.CHAPTER_GAP_DAYS,
        "gardener: a chapter books the next one a week out")
    for (i in 1..3) {
        sGate4.absDay = sGate4.arc4DueAbsDay
        check(Mystery4.dueChapter4(sGate4)?.id == Mystery4.CHAPTERS4[i].id,
            "gardener: chapter ${i + 1} follows in order")
        Mystery4.noteChapterStarted4(sGate4, Mystery4.CHAPTERS4[i])
    }
    check(Mystery4.dueChapter4(sGate4) == null,
        "gardener: once the vigil has aired, nothing more is due")
    check(!Mystery4.boardVisible4(eng4.newState()),
        "gardener: no board before the case exists")

    // ---------- clues: witnesses ----------
    val sWit4 = eng4.newState()
    sWit4.arcRetired = true; sWit4.arc2Retired = true; sWit4.arc3Retired = true
    sWit4.arc4Started = true; sWit4.arc4Chapter = 1
    check(Mystery4.witnessLine4(sWit4, "Gerald") == null &&
        Mystery4.witnessLine4(sWit4, "Barbrady") == null &&
        Mystery4.witnessLine4(sWit4, "Garrison") == null &&
        Mystery4.witnessLine4(sWit4, "Ned") == null,
        "gardener: the room's witnesses have nothing to add before their chapters")
    val mayor = Mystery4.witnessLine4(sWit4, "McDaniels")
    check(mayor != null && mayor.speaker == "McDaniels" &&
        "meeting_room" in sWit4.mystery4Clues,
        "gardener: the mayor describes the room — and its back row")
    check(Mystery4.witnessLine4(sWit4, "McDaniels") == null,
        "gardener: a witness tells it exactly once")
    sWit4.arc4Chapter = 2
    check(Mystery4.witnessLine4(sWit4, "Barbrady")?.speaker == "Barbrady" &&
        "almost_seen" in sWit4.mystery4Clues,
        "gardener: the patrolman nearly saw them (and jiggled the bench)")
    check(sWit4.events.any { it.contains("CLUE 2/12") },
        "gardener: a found clue hits the ticker")
    check(Mystery4.witnessLine4(sWit4, "Gerald") == null,
        "gardener: the minutes-keeper waits for the planters")
    sWit4.arc4Chapter = 3
    check(Mystery4.witnessLine4(sWit4, "Gerald")?.speaker == "Gerald" &&
        "unminuted_complaint" in sWit4.mystery4Clues,
        "gardener: at the planters, the keeper says the quiet part")
    check(Mystery4.witnessLine4(sWit4, "Garrison")?.speaker == "Garrison" &&
        "garden_keeper" in sWit4.mystery4Clues,
        "gardener: the teacher knows his marigolds")
    check(Mystery4.witnessLine4(sWit4, "Ned")?.speaker == "Ned" &&
        "night_crossing" in sWit4.mystery4Clues,
        "gardener: the other night-walker saw the crossing")
    check(Mystery4.witnessLine4(sWit4, "Randy") == null &&
        Mystery4.witnessLine4(sWit4, secretName) == null,
        "gardener: neither the farmer nor the fixer is a witness")

    // ---------- clues: look & record ----------
    val sLook4 = eng4.newState()
    sLook4.arcRetired = true; sLook4.arc2Retired = true; sLook4.arc3Retired = true
    check(Mystery4.lookClueText4(sLook4, "KidsPark") == null,
        "gardener: no finds before the first fix")
    sLook4.arc4Started = true; sLook4.arc4Chapter = 1
    check(Mystery4.lookClueText4(sLook4, "KidsPark") != null &&
        "twine_signature" in sLook4.mystery4Clues,
        "gardener: the bench's first Look finds the twine bow")
    check(Mystery4.lookClueText4(sLook4, "KidsPark") == null,
        "gardener: the bench holds nothing more")
    check(Mystery4.lookClueText4(sLook4, "CityHall") != null &&
        "complaint_match" in sLook4.mystery4Clues,
        "gardener: the posted minutes match the bench, word for word")
    check(Mystery4.lookClueText4(sLook4, "CityHall") == null,
        "gardener: the hall holds nothing more until the planters bloom")
    sLook4.arc4Chapter = 2
    check(Mystery4.lookClueText4(sLook4, "MainStreet") != null &&
        "fountain_washer" in sLook4.mystery4Clues,
        "gardener: the fountain's washer is the town's own")
    check(Mystery4.lookClueText4(sLook4, "StarksPond") != null &&
        "herring_nail" in sLook4.mystery4Clues,
        "gardener: the gate shows two hands — one careful, one not")
    sLook4.arc4Chapter = 3
    check(Mystery4.lookClueText4(sLook4, "CityHall") != null &&
        "seed_trace" in sLook4.mystery4Clues,
        "gardener: the planters trace to a garden the town knows")
    check(Mystery4.lookClueText4(sLook4, "CityHall") == null,
        "gardener: the hall holds exactly its two finds")
    check(Mystery4.lookClueText4(sLook4, "Bank") == null,
        "gardener: the Bank holds no finds")

    // ---------- clues: participation ----------
    val sPart4 = eng4.newState()
    sPart4.arcRetired = true; sPart4.arc2Retired = true; sPart4.arc3Retired = true
    sPart4.arc4Started = true; sPart4.arc4Chapter = 1
    sPart4.shenaniganId = Mystery4.CHAPTERS4[0].id
    sPart4.shenaniganDay = sPart4.todayKey
    sPart4.timeMin = 60
    eng4.player(sPart4).location = "KidsPark"
    eng4.bumpParticipation(sPart4, "KidsPark")
    check(sPart4.participation == 1 && "steady_hands" in sPart4.mystery4Clues,
        "gardener: holding the bench earns the small thumbprint")
    val sSoil = eng4.newState()
    sSoil.arcRetired = true; sSoil.arc2Retired = true; sSoil.arc3Retired = true
    sSoil.arc4Started = true; sSoil.arc4Chapter = 3
    sSoil.shenaniganId = Mystery4.CHAPTERS4[2].id
    sSoil.shenaniganDay = sSoil.todayKey
    sSoil.timeMin = 60
    eng4.player(sSoil).location = "CityHall"
    eng4.bumpParticipation(sSoil, "CityHall")
    check("soil_trail" in sSoil.mystery4Clues,
        "gardener: stacking the meeting chairs earns the soil trail")
    val sFar4 = eng4.newState()
    sFar4.arc4Started = true; sFar4.arc4Chapter = 1
    sFar4.shenaniganId = Mystery4.CHAPTERS4[0].id
    sFar4.shenaniganDay = sFar4.todayKey; sFar4.timeMin = 60
    eng4.player(sFar4).location = "Mall"
    eng4.bumpParticipation(sFar4, "Mall")
    check(sFar4.mystery4Clues.isEmpty(),
        "gardener: no finds away from a chapter's turf")

    // ---------- the vigil gate ----------
    fun vigilState(clues: Int): GameState {
        val s = eng4.newState()
        s.arcRetired = true; s.arc2Retired = true; s.arc3Retired = true
        s.arc4Started = true; s.arc4Chapter = 4
        s.shenaniganId = Mystery4.FINALE4_ID
        s.shenaniganDay = s.todayKey
        for (c in Mystery4.CLUES4.take(clues)) s.mystery4Clues.add(c.id)
        return s
    }
    val finDef4 = Mystery4.CHAPTER4_BY_ID[Mystery4.FINALE4_ID]!!
    check(!Mystery4.vigilDue(vigilState(7).apply { timeMin = 19 * 60 }),
        "gardener: seven clues is NOT enough to keep the vigil (below the gate)")
    check(!Mystery4.vigilDue(vigilState(8).apply { timeMin = 13 * 60 }),
        "gardener: eight clues at noon is still not a vigil — it is a dark-hours beat")
    check(!Mystery4.vigilDue(vigilState(8).apply { timeMin = 16 * 60 + 59 }),
        "gardener: the vigil waits for dusk, not the afternoon")
    val sVigil = vigilState(8); sVigil.timeMin = 17 * 60
    check(Mystery4.vigilDue(sVigil),
        "gardener: eight clues at dusk opens the vigil (the boundary)")
    check(Finales.climaxPending(sVigil),
        "gardener: a due vigil holds the season finales' calls, like every climax")
    check(!Mystery4.vigilDue(vigilState(10).apply {
        timeMin = 19 * 60; shenaniganId = Mystery4.CHAPTERS4[0].id }),
        "gardener: the vigil belongs to the last chapter alone")
    check(!Mystery4.chooseVigil(sVigil, "tell"),
        "gardener: only the three calls can be made at the vigil")
    check(Mystery4.chooseVigil(sVigil, "guard") && sVigil.arc4Choice == "guard",
        "gardener: a call can be locked at the vigil")
    check(!Mystery4.vigilDue(sVigil) &&
        !Mystery4.chooseVigil(sVigil, "name"),
        "gardener: a locked call closes the vigil")

    // ---------- the wrap: four landings ----------
    fun wrappedVigil(clues: Int, choice: String): GameState {
        val s = vigilState(clues)
        s.arc4Choice = choice
        Episodes.beginEvent(s, finDef4)
        s.lastEventWeek = 39
        s.timeMin = 1430
        eng4.advanceTime(s)
        return s
    }
    // NAME: the ceremony, the stop, and one last private fix
    val sNameBase = vigilState(10)
    sNameBase.arc4Choice = "name"
    sNameBase.friendship["McDaniels"] = 20
    Episodes.beginEvent(sNameBase, finDef4)
    sNameBase.lastEventWeek = 39
    sNameBase.timeMin = 1430
    eng4.advanceTime(sNameBase)
    val sName = sNameBase
    check(sName.arc4Retired && sName.arc4Branch == "name",
        "gardener: naming retires the case in the open")
    val epName = sName.episodes.lastOrNull { it.eventId == Mystery4.FINALE4_ID }
    check(epName != null && epName.finished &&
        epName.recap.any { it.contains("THE NAME") && it.contains(secretName) },
        "gardener: the naming's credits carry the reveal — in the credits, nowhere earlier")
    check(sName.episodes.last { it.eventId == Mystery4.FINALE4_ID }
        .outcome.contains(secretName) == false,
        "gardener: even the outcome line keeps the name for the credits")
    check(sName.factionStates.getValue("parents").influence ==
        baseInf4("parents") + 2 &&
        sName.factionStates.getValue("school_staff").influence ==
        baseInf4("school_staff") + 1,
        "gardener: the naming's ripples (Parents +2 gratitude, Staff +1 proud-sorry)")
    check((sName.friendship["McDaniels"] ?: 0) == 22,
        "gardener: the mayor warms to the one who gave her the name (+2)")
    check(sName.arc4LastFixPending && !sName.arc4LastFixLanded &&
        Mystery4.fixTokensByLoc(sName)[Mystery4.PORCH_LOC] == null,
        "gardener: the last fix is promised, not yet landed")
    check(!Mystery4.noteLastFix(sName),
        "gardener: the last fix is not instant")
    sName.absDay += Mystery4.LAST_FIX_DELAY_DAYS
    check(Mystery4.noteLastFix(sName) && sName.arc4LastFixLanded &&
        !sName.arc4LastFixPending,
        "gardener: a morning later, the last fix lands at your porch")
    check(Mystery4.fixTokensByLoc(sName)[Mystery4.PORCH_LOC] ==
        listOf(Mystery4.PORCH_TOKEN) &&
        Mystery4.fixLookText(sName, Mystery4.PORCH_LOC)?.contains("marigold") == true,
        "gardener: the porch keeps the mended step and the marigold")
    check(!Mystery4.noteLastFix(sName),
        "gardener: the last fix lands exactly once")
    check(sName.lifeText["mark:CityHall"]?.contains("NIGHT GARDENER") == true &&
        Mystery4.statusStamp4(sName).contains("NAMED"),
        "gardener: the plaque goes up and the board stamps the naming")
    check(Mystery4.gardenerNodLine4(sName, secretName)?.speaker == secretName &&
        Mystery4.gardenerNodLine4(sName, "Stan") == null,
        "gardener: in the named town, the fixer has his almost-nothing to say — to you only")

    // GUARD: the secret kept, the town kept
    val sGuard = wrappedVigil(8, "guard")
    check(sGuard.arc4Retired && sGuard.arc4Branch == "guard",
        "gardener: guarding retires the case — and nothing else changes")
    check(sGuard.episodes.last { it.eventId == Mystery4.FINALE4_ID }
        .recap.any { it.contains("THE SECRET") && it.contains(secretName) },
        "gardener: the guarded ending's credits hold the name — for the player's eyes")
    check(sGuard.lifeText["mark:Elementary"]?.contains("Somebody won't") == true,
        "gardener: the guarded case's mark is the sound rope and the silence")
    check(Mystery4.gardenerNodLine4(sGuard, secretName) != null &&
        Mystery4.fixTokensByLoc(sGuard)["Elementary"] == listOf("gard-rope"),
        "gardener: the nod exists, and the rope stands, in the kept town")
    val nodA = Mystery4.gardenerNodLine4(sGuard, secretName)!!.text
    sGuard.absDay += 1
    check(Mystery4.gardenerNodLine4(sGuard, secretName)!!.text != nodA,
        "gardener: the nod rotates by the day (a standing line, not a stuck one)")
    check(Mystery4.boardLines4(sGuard).any { it.contains("never say the sentence") },
        "gardener: the board records the keeper's vow")

    // JOIN: two gardeners
    val sJoinBase = vigilState(9)
    sJoinBase.arc4Choice = "join"
    sJoinBase.friendship[secretName] = 10
    Episodes.beginEvent(sJoinBase, finDef4)
    sJoinBase.lastEventWeek = 39
    sJoinBase.timeMin = 1430
    eng4.advanceTime(sJoinBase)
    val sJoin = sJoinBase
    check(sJoin.arc4Retired && sJoin.arc4Branch == "join",
        "gardener: joining retires the case into a tradition")
    check(sJoin.episodes.last { it.eventId == Mystery4.FINALE4_ID }
        .recap.any { it.contains("TWO GARDENERS") },
        "gardener: the joined ending's credits name the tradition")
    check((sJoin.friendship[secretName] ?: 0) == 13,
        "gardener: the fixer warms to a second pair of hands (+3)")
    check(sJoin.lifeText["mark:Elementary"]?.contains("blue ribbon") == true &&
        sJoin.factionStates.getValue("boys_crew").influence ==
            baseInf4("boys_crew") + 2,
        "gardener: two signatures on the rope; the Crew investigates the ghosts (+2)")
    check(Mystery4.statusStamp4(sJoin).contains("TWO GARDENERS"),
        "gardener: the board stamps the two gardeners")

    // COLD: the vigil never kept
    val sCold = wrappedVigil(3, "")
    check(sCold.arc4Retired && sCold.arc4Branch == "cold",
        "gardener: no vigil, few clues — the case closes cold on its own")
    val epCold = sCold.episodes.last { it.eventId == Mystery4.FINALE4_ID }
    check(epCold.recap.any { it.contains("THE QUIET WINTER") } &&
        epCold.recap.none { it.contains(secretName) } &&
        !epCold.outcome.contains(secretName),
        "gardener: the cold ending NEVER learns the name — the file closes sealed")
    check(sCold.lifeText["mark:Elementary"]?.contains("stands bare") == true &&
        Mystery4.fixTokensByLoc(sCold)["Elementary"] == null &&
        Mystery4.gardenerNodLine4(sCold, secretName) == null,
        "gardener: the cold town keeps a bare flagpole and no nod")
    val sRigged4 = wrappedVigil(5, "name")
    check(sRigged4.arc4Branch == "cold",
        "gardener: even the RIGHT call, locked without the case behind it, falls cold")
    check(Mystery4.ambientCallback4(sGuard, kotlin.random.Random(4)) != null &&
        Mystery4.ambientCallback4(sCold, kotlin.random.Random(4)) != null &&
        Mystery4.ambientCallback4(eng4.newState(), kotlin.random.Random(4)) == null,
        "gardener: every closed ending stays in the town's mouth; an open case doesn't")

    // ---------- the board ----------
    val sBoard4 = eng4.newState()
    sBoard4.arcRetired = true; sBoard4.arc2Retired = true; sBoard4.arc3Retired = true
    sBoard4.arc4Started = true; sBoard4.arc4Chapter = 2; sBoard4.absDay = 30
    val board4 = Mystery4.boardLines4(sBoard4)
    check(board4.first().contains("The Night Gardener") &&
        board4.any { it.contains("🧩 CLUES — 0/12") } &&
        board4.any { it.contains("THE FIXES") } &&
        board4.any { it.contains("The park bench — FIXED") } &&
        board4.any { it.contains("Somebody is LISTENING") },
        "gardener: the board shows the case, its fixes, its empty count, its theory")
    Mystery4.grantClue4(sBoard4, "twine_signature")
    check(Mystery4.boardLines4(sBoard4).any { it.contains("🧩 CLUES — 1/12") },
        "gardener: the board counts what you've noticed")
    // all four boards coexist on the one Journal page
    val sAll4 = eng4.newState()
    sAll4.arcRetired = true; sAll4.arc2Retired = true; sAll4.arc3Retired = true
    sAll4.arc4Started = true; sAll4.arc4Chapter = 1
    check(Mystery.boardVisible(sAll4) && Mystery2.boardVisible2(sAll4) &&
        Mystery3.boardVisible3(sAll4) && Mystery4.boardVisible4(sAll4) &&
        Mystery4.boardLines4(sAll4).isNotEmpty(),
        "gardener: four cases share the Journal board — town history, all of it")

    // ---------- spoiler hygiene: nothing pre-reveal names the fixer ----------
    val preReveal = StringBuilder()
    for (def in Mystery4.CHAPTERS4) {
        preReveal.append(def.cause).append(def.blurb)
        for (st in def.stages) {
            preReveal.append(st.title).append(st.banner)
                .append(st.journalNote).append(st.objective)
        }
        for (l in def.coldOpen) preReveal.append(l.text)
    }
    for (clue in Mystery4.CLUES4) {
        preReveal.append(clue.title).append(clue.detail)
            .append(clue.spoken ?: "").append(clue.foundText ?: "")
    }
    for (ch in 1..4) {
        val sPre = eng4.newState()
        sPre.arcRetired = true; sPre.arc2Retired = true; sPre.arc3Retired = true
        sPre.arc4Started = true; sPre.arc4Chapter = ch
        for (line in Mystery4.boardLines4(sPre)) preReveal.append(line)
        preReveal.append(Mystery4.statusStamp4(sPre))
            .append(Mystery4.currentTheory4(sPre))
    }
    check(!preReveal.toString().contains(secretName),
        "gardener: NO pre-reveal surface — chapters, clues, board, theory — names the fixer")
    check(!preReveal.toString().contains("back-row chair") &&
        preReveal.toString().contains("back row"),
        "gardener: the board may point at the room, never at the chair")

    // ---------- engine: a full FOUR-case lifetime ----------
    val sLife4 = eng4.newState()
    var sawChapters4 = mutableSetOf<String>()
    var slotViolation4 = false
    var arc3RetiredDaySeen = -1
    var arc4OpenedDay = -1
    var guard4 = 0
    while (guard4++ < 600 &&
        !(sLife4.arcRetired && sLife4.arc2Retired &&
            sLife4.arc3Retired && sLife4.arc4Retired)) {
        eng4.onNewDay(sLife4)
        sLife4.shenaniganId?.let { if (Mystery4.isChapter4(it)) sawChapters4 += it }
        if ((sLife4.arc2Started && !sLife4.arcRetired) ||
            (sLife4.arc3Started && !sLife4.arc2Retired) ||
            (sLife4.arc4Started && !sLife4.arc3Retired)) slotViolation4 = true
        if (sLife4.arc3Retired && arc3RetiredDaySeen < 0)
            arc3RetiredDaySeen = sLife4.arc3RetiredDay
        if (sLife4.arc4Started && arc4OpenedDay < 0) arc4OpenedDay = sLife4.absDay
    }
    check(sLife4.arcRetired && sLife4.arc2Retired &&
        sLife4.arc3Retired && sLife4.arc4Retired,
        "gardener: a full four-case lifetime plays out in sequence in $guard4 days")
    check(sawChapters4.size == 4,
        "gardener: all four chapters aired inside the lifetime")
    check(!slotViolation4,
        "gardener: no case ever opens while an earlier one is live (one slot, four cases)")
    check(arc4OpenedDay - arc3RetiredDaySeen in
        Mystery4.OPEN_DELAY_DAYS..(Mystery4.OPEN_DELAY_DAYS + 14),
        "gardener: the garden opens about ten days after the dig retires " +
            "(got ${arc4OpenedDay - arc3RetiredDaySeen})")
    check(sLife4.arc4Branch == "cold",
        "gardener: an unattended gardener case closes cold on its own")
    check(Mystery4.fixTokensByLoc(sLife4)["KidsPark"] == listOf("gard-bench"),
        "gardener: after everything, the bench is STILL fixed — the case improved the town")

    // ---------- persistence: mid-case saves & era saves ----------
    val docMid4 = mapOf<String, Any?>(
        "arc3" to mapOf<String, Any?>("chapter" to 4L, "due" to 90L,
            "started" to true, "retired" to true,
            "branch" to "county", "choice" to "",
            "retiredDay" to 88L, "favor" to false,
            "sharonPending" to false, "sharonDay" to -1L,
            "sharonText" to ""),
        "arc4" to mapOf<String, Any?>("chapter" to 2L, "due" to 120L,
            "started" to true, "retired" to false,
            "branch" to "", "choice" to "",
            "retiredDay" to -1L, "lastFixPending" to false,
            "lastFixDay" to -1L, "lastFixLanded" to false),
        "mystery4Clues" to listOf("twine_signature", "gardener_is_the_mayor"))
    val sMid4 = decodeGameState(docMid4)
    check(sMid4.arc4Started && sMid4.arc4Chapter == 2 &&
        sMid4.arc4DueAbsDay == 120 && sMid4.arc3RetiredDay == 88,
        "gardener: a mid-case save restores the garden's clocks")
    check(sMid4.mystery4Clues == setOf("twine_signature"),
        "gardener: known finds restore; invented ids are dropped")
    sMid4.absDay = 120
    check(Mystery4.dueChapter4(sMid4)?.id == Mystery4.CHAPTERS4[2].id,
        "gardener: a restored mid-case save airs its next chapter on time")
    val docTampered4 = mapOf<String, Any?>("arc4" to mapOf<String, Any?>(
        "branch" to "banana", "choice" to "tell", "chapter" to 99L))
    val sTampered4 = decodeGameState(docTampered4)
    check(sTampered4.arc4Branch == "" && sTampered4.arc4Choice == "" &&
        sTampered4.arc4Chapter == Mystery4.CHAPTERS4.size,
        "gardener: invented branch/call values are neutralized, chapters clamp")
    val sEra4 = decodeGameState(emptyMap())
    check(!sEra4.arc4Started && sEra4.arc4DueAbsDay == -1 &&
        sEra4.mystery4Clues.isEmpty() && !Mystery4.boardVisible4(sEra4),
        "gardener: an era save (no arc4 keys) has no fourth case yet")
    val sBack4 = decodeGameState(encodeGameState(sGuard))
    check(sBack4.arc4Retired && sBack4.arc4Branch == "guard" &&
        sBack4.arc4RetiredDay == sGuard.arc4RetiredDay &&
        sBack4.mystery4Clues == sGuard.mystery4Clues,
        "gardener: a closed case (and its kept secret) round-trips the real save path")

    // ---------- spoiler hygiene: the changelog keeps the secret ----------
    val readme4 = File(root, "docs/CHANGELOG.md").readText()
    val cSection = readme4.substringAfter("### v0.6.0c")
        .substringBefore("### v0.6.0b")
    check(cSection.contains("The Night Gardener"),
        "gardener: the v0.6.0c changelog section exists")
    for (tell in listOf(secretName, "Petuski", "back row", "school garden",
        "never written", "thumbprint", "potting soil", "minute book")) {
        check(!cSection.contains(tell, ignoreCase = true),
            "gardener: the changelog never prints the case's tell ('$tell')")
    }

    // ---------- wiring ----------
    val mystery4Src = File(root, "src/com/hunt3r/southparktown/Mystery4.kt").readText()
    val gameActivitySrc4 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc4 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val engineSrc4 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val prefsSrc4 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc4 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    val townLifeSrc4 = File(root, "src/com/hunt3r/southparktown/TownLife.kt").readText()
    val talkGateSrc4 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val finalesSrc4 = File(root, "src/com/hunt3r/southparktown/Finales.kt").readText()
    check(!mystery4Src.contains("import android"),
        "gardener: Mystery4.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc4.contains("Mystery4.dueChapter4") &&
        engineSrc4.contains("Mystery4.resolveVigil") &&
        engineSrc4.contains("Mystery4.noteParticipation4") &&
        engineSrc4.contains("Mystery4.noteLastFix") &&
        engineSrc4.contains("Mystery4.ambientCallback4"),
        "gardener: the engine airs the chapters, resolves the vigil, " +
            "feeds participation, lands the last fix, keeps the callbacks")
    check(talkGateSrc4.contains("Mystery4.witnessLine4") &&
        talkGateSrc4.contains("Mystery4.gardenerNodLine4") &&
        gameActivitySrc4.contains("Mystery4.lookClueText4") &&
        gameActivitySrc4.contains("Mystery4.fixLookText") &&
        gameActivitySrc4.contains("Mystery4.chooseVigil") &&
        gameActivitySrc4.contains("maybeShowVigil") &&
        gameActivitySrc4.contains("Mystery4.fixTokensByLoc"),
        "gardener: GameActivity wires witnesses, looks, the vigil, " +
            "the nod line and the fix-token bridge")
    check(journalSrc4.contains("Mystery4.boardLines4"),
        "gardener: the Journal renders the fourth case's board")
    check(prefsSrc4.contains("\"arc4\" to mapOf") &&
        prefsSrc4.contains("\"mystery4Clues\" to"),
        "gardener: the save doc carries the fourth case additively")
    check(shenanigansSrc4.contains("Mystery4.CHAPTERS4"),
        "gardener: the chapter defs join SHENANIGAN_BY_ID only")
    check(townLifeSrc4.contains("var fixTokens") &&
        sceneSrc4.contains("drawFixDetails") &&
        sceneSrc4.contains("TownInfo.fixTokens"),
        "gardener: SceneArt draws the fix layer from the bridged tokens")
    check(finalesSrc4.contains("Mystery4.vigilDue"),
        "gardener: the season finales defer to the vigil, like every climax")
    check(!gameActivitySrc4.contains(secretName) &&
        !journalSrc4.contains(secretName),
        "gardener: the UI sources never print the fixer's name")
}

private fun sectionV060d(root: String) {
// ================= v0.6.0d: family evenings =================
// Queue #6 item 4. The town's households have eaten dinner
// behind their own doors since v0.1 — the 18:00 agenda
// blocks were always a meal. Now there's a chair for the
// new kid: a rotating invitation (three evenings a week, a
// pure function of the calendar), three judged beats at
// their table, the mirror at yours once the house and the
// friendship qualify, and wraps that pay at midnight.
// Dinners defer to everything bigger — finales, holiday
// beats, case chapters — and the suite pins the deference.
    println("== v0.6.0d: family evenings ==")
    val eng = Engine(6004)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun dated(s: GameState, key: String) {
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    /** A fresh state standing on [absDay] at [timeMin], with
     *  the day's dinner record anchored the way the real
     *  rollover anchors it. */
    fun onDay(absDay: Int, timeMin: Int): GameState {
        val s = freshState()
        s.absDay = absDay
        s.timeMin = timeMin
        Dinners.dailyRollover(s)
        return s
    }
    /** The first dinner day whose natural rotation pick
     *  (before collisions) is [def]. */
    fun dayFor(def: HouseholdDef): Int {
        var d = 1
        while (true) {
            if (Dinners.isDinnerDay(d) &&
                Dinners.HOUSEHOLDS[Dinners.dinnerDaysBefore(d) %
                    Dinners.HOUSEHOLDS.size] == def) return d
            d++
        }
    }
    val marsh = Dinners.defById("marsh")!!
    val brof = Dinners.defById("broflovski")!!
    val black = Dinners.defById("black")!!
    val eve = 18 * 60   // squarely inside the dinner window

    // ---------- registry integrity ----------
    check(Dinners.HOUSEHOLDS.size == 7,
        "dinners: seven households hold a table (got ${Dinners.HOUSEHOLDS.size})")
    check(Dinners.HOUSEHOLDS.map { it.id }.distinct().size == 7 &&
        Dinners.HOUSEHOLDS.map { it.house }.distinct().size == 7,
        "dinners: household ids and houses are unique")
    for (def in Dinners.HOUSEHOLDS) {
        check(def.house in LOCATIONS && def.host in def.members &&
            def.members.all { it in KID_ORDER },
            "dinners: ${def.id}'s house is a place, its host sits at its table, " +
                "and every member is cast")
        check(def.members.all { KID_HOUSE[it] == def.house },
            "dinners: ${def.id}'s whole family actually lives at ${def.house}")
        check(listOf(def.dish, def.ritual, def.welcome, def.moment,
            def.momentShort, def.hand, def.arrive, def.guestLine)
            .all { it.isNotBlank() },
            "dinners: ${def.id} carries its full dinner kit (dish, ritual, " +
                "welcome, moment, hand, arrival, table line)")
        check(Dinners.householdOf(def.host) == def,
            "dinners: ${def.id}'s host resolves back to the household")
    }
    check(Dinners.defById("tucker") == null &&
        Dinners.defById("testaburger") == null,
        "dinners: Tucker and Testaburger have no house in town to eat in — " +
            "honestly absent from the rotation, not faked")
    for (item in Dinners.PANTRY_ITEMS) {
        check(itemById(item) != null && Errands.sourceOf(item) != null,
            "dinners: the pantry item $item is real and the town can produce it")
    }
    for (item in Dinners.THANK_GIFTS) {
        check(itemById(item) != null,
            "dinners: the thank-you gift $item is a real item")
    }
    check(Dinners.INVITED_TITLES.size == Dinners.STEP_COUNT &&
        Dinners.HOSTED_TITLES.size == Dinners.STEP_COUNT,
        "dinners: three beats a side, titled")

    // ---------- the dials ----------
    check(Dinners.DINNER_FROM == 1050 && Dinners.DINNER_TO == 1230 &&
        Dinners.DINNER_TO < 22 * 60,
        "dinners: the window is 5:30–8:30 PM and ends before the town's " +
            "late night — attendance respects bedtime by construction")
    check(Dinners.windowLabel() == "05:30 PM–08:30 PM",
        "dinners: the window as the town says it")
    check(Dinners.HOST_MIN_DECOR == 4 &&
        House.DECOR.size >= Dinners.HOST_MIN_DECOR,
        "dinners: hosting asks ${Dinners.HOST_MIN_DECOR} of the " +
            "${House.DECOR.size} decor pieces")
    check(Dinners.HOST_MIN_TIER == Relationships.FRIEND &&
        Relationships.tierOf(30) == Relationships.FRIEND &&
        Relationships.tierOf(29) == Relationships.ACQUAINTANCE,
        "dinners: hosting asks the FRIEND tier, and the tier line is 30")

    // ---------- rotation determinism ----------
    check((0..13).count { Dinners.isDinnerDay(it) } == 6 &&
        Dinners.isDinnerDay(1) && Dinners.isDinnerDay(3) &&
        Dinners.isDinnerDay(5) && !Dinners.isDinnerDay(0) &&
        !Dinners.isDinnerDay(2) && !Dinners.isDinnerDay(6),
        "dinners: three evenings a week (absDay % 7 in {1, 3, 5})")
    check(Dinners.dinnerDaysBefore(0) == 0 && Dinners.dinnerDaysBefore(1) == 0 &&
        Dinners.dinnerDaysBefore(3) == 1 && Dinners.dinnerDaysBefore(5) == 2 &&
        Dinners.dinnerDaysBefore(6) == 3 && Dinners.dinnerDaysBefore(8) == 3 &&
        Dinners.dinnerDaysBefore(15) == 6,
        "dinners: the rotation's odometer counts dinner evenings only")
    run {
        // determinism: the same day derives the same invite,
        // on any state, twice — the invite is a function,
        // not a roll
        val a = freshState(); a.absDay = 5
        val b = freshState(); b.absDay = 5
        check(Dinners.inviteFor(a) != null &&
            Dinners.inviteFor(a) == Dinners.inviteFor(b),
            "dinners: same day, same invitation, every state")
        val off = freshState(); off.absDay = 2
        check(Dinners.inviteFor(off) == null &&
            Dinners.todaysInvite(off) == null,
            "dinners: no invitation on an off evening")
        // coverage: 49 collision-free days seat every
        // household at least once (the rotation walks the
        // registry in order)
        val seen = mutableSetOf<String>()
        for (d in 1..49) {
            val s = freshState(); s.absDay = d
            Dinners.inviteFor(s)?.let { seen += it.id }
        }
        check(seen == Dinners.HOUSEHOLDS.map { it.id }.toSet(),
            "dinners: over seven weeks every household hosts (saw $seen)")
        // the natural order is the registry's order
        check(Dinners.inviteFor(freshState().apply { absDay = 1 }) == marsh &&
            Dinners.inviteFor(freshState().apply { absDay = 3 }) == brof,
            "dinners: the rotation opens with the Marshes, then the Broflovskis")
    }

    // ---------- collision deferrals ----------
    run {
        // (a) a season finale's gathering day: the ensemble
        // is spoken for; mid-window days and the finale's
        // own place obey their own scoped rules
        val s = onDay(dayFor(marsh), eve)
        var gatherKey: String? = null
        var midKey: String? = null
        for (d in 20..31) {
            val key = "202705%02d".format(d)
            val t = freshState(); dated(t, key)
            val w = Finales.windowAt(t) ?: continue
            if (w.def.id == "spring" && w.dayIndex == 0) gatherKey = key
            if (w.def.id == "spring" && w.dayIndex == 2) midKey = key
        }
        check(gatherKey != null && midKey != null,
            "dinners: (fabrication) the spring finale has a gathering day " +
                "and a mid-window day to test against")
        if (gatherKey != null && midKey != null) {
            dated(s, gatherKey)
            check(Dinners.collides(s, marsh) && Dinners.collides(s, brof),
                "dinners: on the finale's gathering day, ensemble households " +
                    "defer (Marsh and Broflovski are both in the spring cast)")
            check(Dinners.inviteFor(s) != marsh,
                "dinners: the colliding household never gets the invitation")
            dated(s, midKey)
            check(!Dinners.collides(s, marsh),
                "dinners: mid-window, away from the finale's place, the " +
                    "Marsh table is its own again")
        }
    }
    run {
        // (b) a holiday beat at the family's table
        val s = onDay(dayFor(marsh), eve)
        s.holidayId = "halloween"
        val beat = HolidayBeats.activeBeat(s)
        check(beat != null,
            "dinners: (fabrication) the Halloween beat is live")
        if (beat != null) {
            val touched = Dinners.HOUSEHOLDS.filter { def ->
                beat.steps.any { it.loc == def.house ||
                    it.houseLoc == def.house ||
                    (it.who != null && it.who in def.members) } }
            val untouched = Dinners.HOUSEHOLDS.filter { it !in touched }
            check(touched.isNotEmpty() && untouched.isNotEmpty(),
                "dinners: (fabrication) Halloween touches some tables and " +
                    "not others (touched: ${touched.map { it.id }})")
            for (def in touched) check(Dinners.collides(s, def),
                "dinners: ${def.id} defers to the holiday beat at its table")
            for (def in untouched) check(!Dinners.collides(s, def),
                "dinners: ${def.id}'s evening is untouched by the beat")
        }
    }
    run {
        // (c) a case chapter whose cast IS the family
        val chapter = Mystery3.CHAPTERS3.first {
            it.causers.containsAll(listOf("Randy", "Sharon", "Stan")) }
        val s = onDay(dayFor(marsh), eve)
        s.shenaniganId = chapter.id
        check(Dinners.collides(s, marsh) && !Dinners.collides(s, black),
            "dinners: the buried case's chapter owns the Marsh evening — " +
                "its cast is the family; the Black table is clear")
        check(Dinners.inviteFor(s) != marsh,
            "dinners: the invitation moves on when a chapter claims the house")
        // an ordinary shenanigan with a Marsh causer is NOT
        // a case — the street keeps its claim modest
        val plain = SHENANIGANS.firstOrNull {
            it.id !in Dinners.CASE_DEF_IDS && "Randy" in it.causers }
        if (plain != null) {
            val s2 = onDay(dayFor(marsh), eve)
            s2.shenaniganId = plain.id
            check(!Dinners.collides(s2, marsh),
                "dinners: a random shenanigan (${plain.id}) doesn't cancel dinner")
        }
    }
    run {
        // (d) a case climax on the table: the INVITE stands
        // (it was breakfast's news) but the beats wait
        val s = onDay(dayFor(marsh), eve)
        check(Dinners.todaysInvite(s) == marsh &&
            Dinners.talkStepFor(s, marsh.host) != null,
            "dinners: (fabrication) the Marsh dinner is live before the climax")
        s.shenaniganId = Mystery.FINALE_ID
        s.mysteryClues.addAll(Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES)
            .map { it.id })
        check(Finales.climaxPending(s),
            "dinners: (fabrication) the pond case's climax is genuinely due")
        check(Dinners.talkStepFor(s, marsh.host) == null &&
            Dinners.judgeTalk(s, marsh.host) == null &&
            Dinners.lookText(s, marsh.house) == null,
            "dinners: while the climax is due, dinner beats politely wait")
        check(Dinners.todaysInvite(s) == marsh,
            "dinners: the invitation itself never un-happens mid-day")
        s.shenaniganId = null
        check(Dinners.talkStepFor(s, marsh.host) != null,
            "dinners: the table clears, the dinner resumes")
    }

    // ---------- the invited dinner: full lifecycle ----------
    run {
        val s = onDay(dayFor(marsh), eve)
        check(Dinners.todaysInvite(s) == marsh,
            "dinners: on the Marsh day, the Marshes hold the invitation")
        val note = Dinners.morningNote(s)
        check(note != null && note.contains("the Marshes") &&
            note.contains(marsh.dish) && note.contains("Marsh Residence"),
            "dinners: the morning line names the family, the dish, the house")
        // the family is AT the table during the window —
        // the schedule override, at module and engine level
        check(Dinners.gatheringBlock(s, "Stan", eve)?.location == marsh.house &&
            Dinners.gatheringBlock(s, "Sharon", eve)?.location == marsh.house &&
            Dinners.gatheringBlock(s, "Stan", 900) == null &&
            Dinners.gatheringBlock(s, "Kyle", eve) == null,
            "dinners: the household gathers at home in the window, and " +
                "only in the window, and only its own")
        check(eng.effectiveAgendaBlock(s, s.agents["Stan"]!!, eve)
            ?.location == marsh.house,
            "dinners: the engine's agenda agrees — Stan is home for dinner")
        // the gate routes the host's Talk to the dinner rail
        check(TalkGate.gateFor(s, marsh.host, marsh.house).rail ==
            TalkGate.Rail.DINNER,
            "dinners: Talk with the host takes the DINNER rail in the window")
        // beat 0: the welcome (host)
        val h0 = Dinners.judgeTalk(s, marsh.host)
        check(h0 != null && h0.stepIndex == 0 && h0.text == marsh.welcome &&
            !h0.allLanded && Dinners.invitedStepsDone(s) == 1,
            "dinners: beat 0 lands on the host — the welcome")
        // beat 1: table talk (any member) — the moment lands
        // and sticks in the family's own record
        val h1 = Dinners.judgeTalk(s, "Stan")
        check(h1 != null && h1.stepIndex == 1 && h1.text == marsh.moment &&
            Dinners.momentOf(s, marsh) == marsh.momentShort,
            "dinners: beat 1 is table talk with any of the family, and " +
                "the household moment sticks")
        // beat 2: lend a hand (a Look in the room)
        val handText = Dinners.lookText(s, marsh.house)
        check(handText == marsh.hand && Dinners.invitedStepsDone(s) == 3,
            "dinners: beat 2 is a Look around their house — lend a hand")
        check(Dinners.judgeTalk(s, marsh.host) == null &&
            Dinners.lookText(s, marsh.house) == null,
            "dinners: a landed dinner has no beats left to give")
        // the wrap: full evening pays across the household
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(Dinners.attendedCount(s, marsh) == 1 &&
            s.lifeText["dinOutcome:marsh"] == "full" &&
            Dinners.nightLine(s, marsh) != null &&
            Dinners.lastDinnerDay(s, marsh) == dayFor(marsh),
            "dinners: the full evening wraps — attended, recorded, lined")
        check((s.friendship["Sharon"] ?: 0) - (f0["Sharon"] ?: 0) == 3 &&
            (s.friendship["Randy"] ?: 0) - (f0["Randy"] ?: 0) == 2 &&
            (s.friendship["Stan"] ?: 0) - (f0["Stan"] ?: 0) == 2,
            "dinners: a full evening pays the host +3 and the family +2")
        check(s.agents["Stan"]!!.memories.any { it.startsWith("🍽") } &&
            (NpcMemoryStore.get("Stan")?.topics?.contains(Dinners.TOPIC) == true),
            "dinners: the night sticks — an agent memory and a thread topic")
        check(Dinners.wrapFor(s, dayFor(marsh)) == (marsh to "attended"),
            "dinners: the wrap record is there for the phone's thanks text")
        // a second rollover pays nothing twice
        val f1 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(s.friendship == f1 && Dinners.attendedCount(s, marsh) == 1,
            "dinners: the wrap never double-pays")
    }

    // ---------- early leave & no-show ----------
    run {
        val s = onDay(dayFor(marsh), eve)
        Dinners.judgeTalk(s, marsh.host)   // the welcome, then life calls
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(s.lifeText["dinOutcome:marsh"] == "early" &&
            Dinners.attendedCount(s, marsh) == 1 &&
            (s.friendship["Sharon"] ?: 0) - (f0["Sharon"] ?: 0) == 2 &&
            (s.friendship["Stan"] ?: 0) - (f0["Stan"] ?: 0) == 1,
            "dinners: leaving early is a shorter, still-warm night " +
                "(host +2, family +1, attended all the same)")
    }
    run {
        val s = onDay(dayFor(marsh), eve)
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(Dinners.attendedCount(s, marsh) == 0 &&
            s.lifeText["dinOutcome:marsh"] == null &&
            s.friendship == f0 && Dinners.wrapFor(s, dayFor(marsh)) == null,
            "dinners: a no-show is just an evening the town had without " +
                "you — no record, no penalty, no hard feelings")
    }

    // ---------- window discipline ----------
    run {
        val early = onDay(dayFor(marsh), Dinners.DINNER_FROM - 15)
        val late = onDay(dayFor(marsh), Dinners.DINNER_TO)
        val lastTick = onDay(dayFor(marsh), Dinners.DINNER_TO - 15)
        check(Dinners.talkStepFor(early, marsh.host) == null &&
            Dinners.lookText(early, marsh.house) == null,
            "dinners: no beats before the window opens")
        check(Dinners.talkStepFor(late, marsh.host) == null &&
            Dinners.judgeTalk(late, marsh.host) == null,
            "dinners: no beats once the window closes")
        check(Dinners.talkStepFor(lastTick, marsh.host) != null,
            "dinners: the window's last tick still counts")
        val wrongRoom = onDay(dayFor(marsh), eve)
        check(Dinners.lookText(wrongRoom, "Elementary") == null &&
            Dinners.lookText(wrongRoom, brof.house) == null,
            "dinners: lend-a-hand only lands in the host's own house")
    }

    // ---------- the rail order (source pin, the TalkGate way) ----------
    run {
        val gateSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        val body = gateSrc.substringAfter("fun gateFor")
        check(body.indexOf("HolidayBeats.talkStepFor") <
            body.indexOf("Finales.talkStepFor") &&
            body.indexOf("Finales.talkStepFor") <
            body.indexOf("Dinners.talkStepFor") &&
            body.indexOf("Dinners.talkStepFor") <
            body.indexOf("FactionMissions.talkBeatFor"),
            "dinners: the gate peels HOLIDAY < FINALE < DINNER < FACTION — " +
                "a delivery still beats the dinner, the dinner still " +
                "defers to the finale")
        val engineSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engineSrc.indexOf("Dinners.gatheringBlock") <
            engineSrc.indexOf("Finales.gatheringBlock"),
            "dinners: the dinner gathering yields to the finale gathering " +
                "in the engine's own order")
        check(engineSrc.indexOf("Dinners.dailyRollover(state)") <
            engineSrc.indexOf("Phone.dailyRollover(state)"),
            "dinners: wraps land before the phone harvests them")
    }

    // ---------- hosting: qualification math ----------
    fun richHouse(s: GameState) {
        // four honest decor pieces through the real
        // derivation: a finished episode, a photo feat, a
        // game feat, a case ending's mark
        s.episodes.add(EpisodeRecord("e@x", "event", "bus_stop_blizzard",
            "t", "t", "t", emptyList(), "x", "1/1", finished = true))
        s.photoFeats.add(Photos.PHOTO_FEATS[0].id)
        s.gameFeats.add(Minigames.GAME_FEATS[0].id)
        s.arcRetired = true; s.arcBranch = "truth"
    }
    run {
        // (the Marshes are free tonight — it's a Broflovski
        // invitation day; the invite-day rule gets its own
        // fabrication at the end of this block)
        val s = onDay(dayFor(brof), eve)
        check(!Dinners.hostEligible(s, marsh.id) &&
            Dinners.hostOptions(s).first { it.def == marsh }
                .reason.contains("decor"),
            "hosting: a bare house can't host — the reason names the decor")
        richHouse(s)
        check(House.decorFor(s).size >= Dinners.HOST_MIN_DECOR &&
            !Dinners.hostEligible(s, marsh.id) &&
            Dinners.hostOptions(s).first { it.def == marsh }
                .reason.contains("Friend"),
            "hosting: decor alone isn't enough — the host must count " +
                "you a friend first")
        s.friendship[marsh.host] = 29
        check(!Dinners.hostEligible(s, marsh.id),
            "hosting: 29 points is ACQUAINTANCE — the gate reads the tier live")
        s.friendship[marsh.host] = 30
        check(Dinners.hostEligible(s, marsh.id),
            "hosting: at FRIEND (30) the table opens")
        check(!Dinners.scheduleHosting(s, "tucker"),
            "hosting: an unknown household can't be scheduled")
        // tonight's OWN invitation blocks hosting that
        // household — you're expected at theirs
        val invDay = onDay(dayFor(brof), eve)
        richHouse(invDay)
        invDay.friendship[brof.host] = 40
        invDay.friendship[marsh.host] = 40
        check(Dinners.todaysInvite(invDay) == brof &&
            !Dinners.hostEligible(invDay, brof.id) &&
            Dinners.hostEligible(invDay, marsh.id),
            "hosting: the household that invited YOU tonight can't be " +
                "hosted by you tonight — turns are turns")
    }

    // ---------- hosting: the evening itself ----------
    run {
        val s = onDay(dayFor(brof), eve)   // not a Marsh night
        richHouse(s)
        s.friendship[marsh.host] = 50
        check(Dinners.scheduleHosting(s, marsh.id),
            "hosting: an eligible household takes the invitation")
        check(Dinners.hostingTonight(s) == marsh,
            "hosting: the Marshes are tonight's guests")
        check(Dinners.gatheringBlock(s, "Stan", eve)?.location == YOUR_HOUSE &&
            Dinners.gatheringBlock(s, "Stan", 900) == null &&
            Dinners.gatheringBlock(s, "Kyle", eve) == null,
            "hosting: the guests gather at YOUR house, in the window only")
        check(eng.effectiveAgendaBlock(s, s.agents["Randy"]!!, eve)
            ?.location == YOUR_HOUSE,
            "hosting: the engine's agenda brings Randy to your door")
        // beat 0: the welcome in (Talk the guest host)
        val h0 = Dinners.judgeTalk(s, marsh.host)
        check(h0 != null && h0.hosted && h0.stepIndex == 0 &&
            h0.text == marsh.arrive,
            "hosting: beat 0 lands on the guest host — the welcome in")
        // beat 1: the spread (Look at yours) — the pantry
        // is served and consumed
        s.inventory["snack_cake"] = 1
        val serve = Dinners.lookText(s, YOUR_HOUSE)
        check(serve != null &&
            serve.contains(itemById("snack_cake")!!.name) &&
            (s.inventory["snack_cake"] ?: 0) == 0 &&
            Dinners.hostedStepsDone(s) == 2,
            "hosting: the spread serves what's stocked, and the pantry " +
                "is honestly lighter for it")
        // beat 2: over the table — guests remark on the
        // house's REAL contents
        val facts = Dinners.conversationFacts(s)
        check(facts.isNotEmpty(),
            "hosting: a lived-in house gives the table something true " +
                "to say")
        val h2 = Dinners.judgeTalk(s, "Stan")
        check(h2 != null && h2.stepIndex == 2 && h2.allLanded &&
            facts.any { h2.text.contains(it) },
            "hosting: beat 2 is the guests on your actual house — " +
                "every remark traceable to a true fact")
        // the wrap: well-hosted pays best
        val f0 = s.friendship.toMap()
        val dinnerDay = s.absDay
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(s.lifeText["hostOutcome:marsh"] == "well" &&
            Dinners.hostedCount(s, marsh) == 1 &&
            Dinners.hostNightLine(s, marsh) != null &&
            (s.friendship["Sharon"] ?: 0) - (f0["Sharon"] ?: 0) == 4 &&
            (s.friendship["Stan"] ?: 0) - (f0["Stan"] ?: 0) == 3,
            "hosting: a well-hosted night wraps 'well' — guest host +4, " +
                "family +3, the mark on the page")
        check(Dinners.wrapFor(s, dinnerDay) == (marsh to "hosted"),
            "hosting: the wrap record feeds the guests' thanks text")
        check(Dinners.hostCooldownLeft(s, marsh) in 1..Dinners.HOST_COOLDOWN_DAYS,
            "hosting: the same table rests — cooldown is running")
    }

    // ---------- hosting: honest judging ----------
    run {
        // the facts are ONLY facts: a bare house has none
        val bare = freshState()
        check(Dinners.conversationFacts(bare).isEmpty(),
            "hosting: a bare house gives the table nothing to say — " +
                "the guest lines can't invent a life you haven't lived")
        richHouse(bare)
        val facts1 = Dinners.conversationFacts(bare)
        val piece = House.DECOR.first { it.id in House.decorFor(bare) }
        check(facts1.any { it.contains(piece.name, ignoreCase = true) },
            "hosting: the decor fact names a piece that's really up")
        bare.collected.addAll(COLLECTIBLES.take(8).map { it.id })
        check(Dinners.conversationFacts(bare)
            .any { it.contains("shelf", ignoreCase = true) },
            "hosting: eight treasures on the shelf earn the shelf line")
        bare.photos.add(PhotoRecord("p1", "x", "1/1", 600, "MainStreet",
            false, "clear", emptyMap(), emptyList(),
            commissionAsker = "Stan"))
        check(Dinners.conversationFacts(bare)
            .any { it.contains("commissioned", ignoreCase = true) },
            "hosting: a commissioned print in the album earns its line — " +
                "and only a real one does")
        // a thin night: eligible house, empty pantry,
        // every beat landed — still judged 'fine'
        val s = onDay(dayFor(brof), eve)
        richHouse(s)
        s.friendship[marsh.host] = 40
        Dinners.scheduleHosting(s, marsh.id)
        Dinners.judgeTalk(s, marsh.host)
        val serve = Dinners.lookText(s, YOUR_HOUSE)
        check(serve != null && serve.contains("cupboard"),
            "hosting: an empty pantry still lands the beat — with the " +
                "honest bare-cupboard line")
        Dinners.judgeTalk(s, "Stan")
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(s.lifeText["hostOutcome:marsh"] == "fine" &&
            (s.friendship["Sharon"] ?: 0) - (f0["Sharon"] ?: 0) == 2 &&
            (s.friendship["Stan"] ?: 0) - (f0["Stan"] ?: 0) == 2,
            "hosting: a thin night is a fine night (+2/+2), not a failed one")
    }

    // ---------- hosting: stood up, cooldown, cancel ----------
    run {
        val s = onDay(dayFor(brof), eve)
        richHouse(s)
        s.friendship[marsh.host] = 40
        s.friendship[brof.host] = 40
        Dinners.scheduleHosting(s, marsh.id)
        check(!Dinners.scheduleHosting(s, brof.id),
            "hosting: one set of guests a night — the table seats one family")
        check(Dinners.cancelHosting(s) &&
            Dinners.hostingTonight(s) == null,
            "hosting: plans can be called off before they start")
        check(Dinners.scheduleHosting(s, marsh.id),
            "hosting: a called-off night costs nothing — rebook freely")
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)   // nobody came; you weren't there either
        check(Dinners.hostedCount(s, marsh) == 0 &&
            s.friendship == f0 &&
            Dinners.hostNightLine(s, marsh) != null &&
            Dinners.hostCooldownLeft(s, marsh) > 0 &&
            Dinners.wrapFor(s, dayFor(brof)) == null,
            "hosting: a stood-up table spends the cooldown and nothing " +
                "else — no mark, no pay, no thanks text")
        check(!Dinners.hostEligible(s, marsh.id) &&
            Dinners.hostEligible(s, brof.id),
            "hosting: the cooldown is per-household — another family " +
                "can still be asked")
        // cancel is refused once the evening has started
        val s2 = onDay(dayFor(brof), eve)
        richHouse(s2)
        s2.friendship[marsh.host] = 40
        Dinners.scheduleHosting(s2, marsh.id)
        Dinners.judgeTalk(s2, marsh.host)
        check(!Dinners.cancelHosting(s2),
            "hosting: once the guests are in, there's no calling it off")
    }

    // ---------- hosting supersedes the invitation ----------
    run {
        val s = onDay(dayFor(marsh), eve)   // the Marshes invited YOU
        richHouse(s)
        s.friendship[brof.host] = 40
        check(Dinners.todaysInvite(s) == marsh &&
            Dinners.scheduleHosting(s, brof.id),
            "hosting: (fabrication) invited by one house, hosting another")
        check(Dinners.talkStepFor(s, marsh.host) == null &&
            Dinners.judgeTalk(s, marsh.host) == null &&
            Dinners.talkStepFor(s, brof.host) != null,
            "hosting: your guests own your evening — the invitation " +
                "across town waits, and lapses")
        val f0 = s.friendship.toMap()
        s.absDay += 1
        Dinners.dailyRollover(s)
        check(Dinners.attendedCount(s, marsh) == 0 &&
            s.friendship == f0,
            "hosting: the lapsed invitation wraps silently — the " +
                "supersede pays nobody and records nothing")
    }

    // ---------- the thank-you odds ----------
    run {
        fun giftHash(def: HouseholdDef, day: Int) =
            ((def.id.hashCode() and 0x3fffffff) + day)
        var itemCase: Pair<HouseholdDef, Int>? = null
        var cardCase: Pair<HouseholdDef, Int>? = null
        var missCase: Pair<HouseholdDef, Int>? = null
        for (day in 1..600) {
            for (def in Dinners.HOUSEHOLDS) {
                // the day's own invitation must not be this
                // household (you can't host who's hosting you)
                if (Dinners.inviteFor(freshState().apply { absDay = day }) ==
                    def) continue
                val h = giftHash(def, day)
                if (h % Dinners.THANK_EVERY != 0) {
                    if (missCase == null) missCase = def to day
                } else if ((h / Dinners.THANK_EVERY) %
                    PocketPals.ERRAND_CARD_EVERY == 0) {
                    if (cardCase == null) cardCase = def to day
                } else if (itemCase == null) itemCase = def to day
            }
            if (itemCase != null && cardCase != null && missCase != null) break
        }
        check(itemCase != null && cardCase != null && missCase != null,
            "hosting: (fabrication) the thank-you odds produce all three " +
                "outcomes inside 600 days")
        // a well-hosted evening, staged identically each
        // time; only the (household, day) seed differs
        fun stagedWellHosted(def: HouseholdDef, day: Int): GameState {
            val s = onDay(day, eve)
            richHouse(s)
            s.friendship[def.host] = 50
            s.collected.addAll(COLLECTIBLES.take(8).map { it.id })
            check(Dinners.scheduleHosting(s, def.id),
                "hosting: (fabrication) ${def.id} can be hosted on day $day")
            Dinners.judgeTalk(s, def.host)
            s.inventory["snack_cake"] = 1
            Dinners.lookText(s, YOUR_HOUSE)
            val anyGuest = def.members.firstOrNull { it != def.host } ?: def.host
            Dinners.judgeTalk(s, anyGuest)
            return s
        }
        if (itemCase != null) {
            val (def, day) = itemCase!!
            val s = stagedWellHosted(def, day)
            val h = giftHash(def, day)
            val gid = Dinners.THANK_GIFTS[
                (h / Dinners.THANK_EVERY) % Dinners.THANK_GIFTS.size]
            val before = s.inventory[gid] ?: 0
            s.absDay = day + 1
            Dinners.dailyRollover(s)
            check(s.lifeText["hostOutcome:${def.id}"] == "well" &&
                (s.inventory[gid] ?: 0) == before + 1,
                "hosting: at the rail's odds, ${def.id} leaves a " +
                    "${itemById(gid)?.name} on the table")
        }
        if (cardCase != null) {
            val (def, day) = cardCase!!
            val s = stagedWellHosted(def, day)
            val before = s.pocketPals.size
            s.absDay = day + 1
            Dinners.dailyRollover(s)
            check(s.lifeText["hostOutcome:${def.id}"] == "well" &&
                s.pocketPals.size == before + 1,
                "hosting: one thank-you in ${PocketPals.ERRAND_CARD_EVERY} " +
                    "is a Pocket Pal — the errands' own rail, reused")
        }
        if (missCase != null) {
            val (def, day) = missCase!!
            val s = stagedWellHosted(def, day)
            val giftsBefore = Dinners.THANK_GIFTS.sumOf { s.inventory[it] ?: 0 }
            val palsBefore = s.pocketPals.size
            s.absDay = day + 1
            Dinners.dailyRollover(s)
            check(s.lifeText["hostOutcome:${def.id}"] == "well" &&
                Dinners.THANK_GIFTS.sumOf { s.inventory[it] ?: 0 } ==
                    giftsBefore && s.pocketPals.size == palsBefore,
                "hosting: most well-hosted nights leave only the memory — " +
                    "the odds are the odds")
        }
    }

    // ---------- the phone: invite & thanks ----------
    run {
        check(Phone.DINNER in Phone.TRIGGERS &&
            Phone.DINNER_THANKS in Phone.TRIGGERS,
            "phone: dinner and dinner-thanks are registered triggers")
        val s = freshState()
        s.timeMin = 23 * 60
        eng.sleepUntilMorning(s)   // -> day 1: the Marsh dinner day
        check(s.absDay == 1 && Dinners.todaysInvite(s) == marsh,
            "phone: (fabrication) day 1 dawns on the Marsh invitation")
        val invite = s.phoneTexts.firstOrNull {
            it.trigger == Phone.DINNER && it.sender == marsh.host }
        check(invite != null && invite.text.contains("meatloaf"),
            "phone: the host texts the invitation herself, dish and all")
        // attend in full, sleep, and be thanked
        s.timeMin = eve
        Dinners.judgeTalk(s, marsh.host)
        Dinners.judgeTalk(s, "Stan")
        Dinners.lookText(s, marsh.house)
        s.timeMin = 23 * 60
        eng.sleepUntilMorning(s)   // -> day 2
        val thanks = s.phoneTexts.firstOrNull {
            it.trigger == Phone.DINNER_THANKS && it.sender == marsh.host }
        check(thanks != null,
            "phone: the morning after a full dinner, the host says thanks")
    }

    // ---------- the Journal page ----------
    run {
        val s = onDay(dayFor(marsh), eve)
        val before = Dinners.pageLines(s)
        check(before.first().startsWith("🍽 FAMILY EVENINGS") &&
            before.any { it.contains("Tonight") && it.contains("the Marshes") } &&
            before.count { it.contains("not yet") } == Dinners.HOUSEHOLDS.size,
            "page: tonight's table leads, and every household starts unvisited")
        Dinners.judgeTalk(s, marsh.host)
        Dinners.judgeTalk(s, "Stan")
        Dinners.lookText(s, marsh.house)
        s.absDay += 1
        Dinners.dailyRollover(s)
        val after = Dinners.pageLines(s)
        check(after.any { it.contains("the Marshes") &&
            it.contains("dined at theirs ×1") } &&
            after.count { it.contains("not yet") } ==
                Dinners.HOUSEHOLDS.size - 1 &&
            after.any { it.contains("the moment:") },
            "page: an attended dinner moves the Marshes off the " +
                "still-to-visit list, moment and all")
    }

    // ---------- save round-trip & hostile saves ----------
    run {
        val s = onDay(dayFor(marsh), eve)
        Dinners.judgeTalk(s, marsh.host)
        Dinners.judgeTalk(s, "Stan")
        Dinners.lookText(s, marsh.house)
        s.absDay += 1
        Dinners.dailyRollover(s)
        val back = decodeGameState(encodeGameState(s))
        check(Dinners.attendedCount(back, marsh) == 1 &&
            Dinners.nightLine(back, marsh) == Dinners.nightLine(s, marsh) &&
            Dinners.momentOf(back, marsh) == marsh.momentShort &&
            Dinners.lastDinnerDay(back, marsh) == dayFor(marsh),
            "saves: the dinner records ride the real save path whole")
        // a hostile doc: unknown households and a fat mask
        // are clamped or ignored, never honored
        val evil = onDay(dayFor(marsh), eve)
        evil.life["dinAttended:tucker"] = 50
        evil.life["dinMask"] = 999
        evil.life["dinDay"] = evil.absDay
        check(Dinners.totalAttended(evil) == 0 &&
            Dinners.invitedStepsDone(evil) <= Dinners.STEP_COUNT &&
            Dinners.pageLines(evil).none { it.contains("Tucker") },
            "saves: dinner derivations read through the registry — a " +
                "planted household stays invisible, a fat mask clamps")
    }

    // ---------- the long way round: 60 days of dinners ----------
    run {
        val s = freshState()
        var inviteDays = 0
        var guard = 0
        while (s.absDay < 60 && guard++ < 90) {
            if (Dinners.isDinnerDay(s.absDay) &&
                Dinners.todaysInvite(s) != null) inviteDays++
            check(Dinners.invitedStepsDone(s) == 0 &&
                Dinners.hostedStepsDone(s) == 0,
                "drive: every morning starts with clean masks (day ${s.absDay})")
            s.timeMin = 23 * 60
            eng.sleepUntilMorning(s)
        }
        check(s.absDay >= 60 && inviteDays >= 10,
            "drive: 60 days roll by — $inviteDays dinner invitations " +
                "landed, every wrap resolved, no exceptions")
        check(Dinners.totalAttended(s) == 0 && Dinners.totalHosted(s) == 0,
            "drive: a player who never sits down has an empty page — " +
                "the town ate without them, kindly")
    }

    // ---------- wiring ----------
    run {
        val dinnersSrc = File(root,
            "src/com/hunt3r/southparktown/Dinners.kt").readText()
        val gameSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        val viewSrc = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        val houseSrc = File(root,
            "src/com/hunt3r/southparktown/House.kt").readText()
        check(!dinnersSrc.contains("import android"),
            "dinners: Dinners.kt stays pure Kotlin (JVM-testable)")
        check(gameSrc.contains("Rail.DINNER") &&
            gameSrc.contains("Dinners.judgeTalk") &&
            gameSrc.contains("Dinners.lookText") &&
            gameSrc.contains("hostDinnerDialog()"),
            "dinners: the Talk rail, the Look append, and the table " +
                "dialog are all wired in the game")
        check(viewSrc.contains("Hit(\"fixture\", \"table\"") &&
            gameSrc.contains("\"table\" -> hostDinnerDialog()"),
            "dinners: the dining table is drawn at your house and its " +
                "tap opens the hosting dialog")
        check(journalSrc.contains("Dinners.pageLines") &&
            journalSrc.contains("FAMILY EVENINGS"),
            "dinners: the Journal carries the 🍽 page")
        check(houseSrc.contains("Dinners.morningNote"),
            "dinners: the morning report carries the invitation")
    }
}

private fun sectionV060e(root: String) {
// ================= v0.6.0e: town jobs =================
// Queue #6 item 5. Errands are favors; a job is a standing
// commitment — a boss, a weekly schedule, shifts played
// live (clock in, land the card, clock out), a streak that
// pays, a kind miss ladder (reminder, warning, let go at
// three), and excuses when the town's set-pieces outrank
// work. State rides life/lifeText; the suite pins the
// calendar against the real one, the lifecycle through the
// real gate and verbs, and the pay math to the coin.
    println("== v0.6.0e: town jobs ==")
    val eng = Engine(6005)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun dated(s: GameState, key: String) {
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    val baseOrd = ordinalOfKey("20261001")   // day 0: Thu Oct 1, 2026
    fun keyOf(absDay: Int) = keyFromOrdinal(baseOrd + absDay)
    /** A fresh state standing on [absDay] at [timeMin],
     *  calendar-consistent (absDay and todayKey agree). */
    fun onDay(absDay: Int, timeMin: Int): GameState {
        val s = freshState()
        s.absDay = absDay
        s.timeMin = timeMin
        dated(s, keyOf(absDay))
        return s
    }
    val paper = Jobs.defById("paper")!!
    val farm = Jobs.defById("farm")!!
    val shop = Jobs.defById("shop")!!

    // ---------- the calendar, pinned against the real one ----------
    check(Jobs.weekdayOf(0) == 4 && Jobs.WEEKDAY_NAMES[4] == "Thursday",
        "jobs: day 0 is a Thursday — the anchor is Oct 1, 2026")
    var calOk = true
    for (d in 0..364) {
        val real = java.time.LocalDate.of(2026, 10, 1)
            .plusDays(d.toLong()).dayOfWeek.value % 7
        if (Jobs.weekdayOf(d) != real) { calOk = false; break }
    }
    check(calOk, "jobs: weekdayOf matches the real calendar for a full year")
    check(Jobs.weekIndex(0) == 0 && Jobs.weekIndex(6) == 0 &&
        Jobs.weekIndex(7) == 1 && Jobs.weekIndex(13) == 1 &&
        Jobs.weekIndex(14) == 2,
        "jobs: game weeks start on day 0 (Thursday) — payday's rhythm")

    // ---------- registry integrity ----------
    check(Jobs.JOBS.size == 3 &&
        Jobs.JOBS.map { it.id }.distinct().size == 3,
        "jobs: three jobs on the registry (got ${Jobs.JOBS.size})")
    for (def in Jobs.JOBS) {
        check(def.boss in KID_ORDER && def.workplace in LOCATIONS &&
            def.factionId in FACTIONS.map { it.id },
            "jobs: ${def.id}'s boss is cast, its workplace is a place, " +
                "its faction exists")
        check(def.days.isNotEmpty() && def.inFrom < def.inTo &&
            def.inTo <= def.shiftEnd && def.basePay > 0 && def.perTask > 0,
            "jobs: ${def.id} has real days, a real window, honest wages")
        check(listOf(def.blurb, def.applyText, def.refuseText,
            def.clockInText, def.clockOutText, def.quitText)
            .all { it.isNotBlank() },
            "jobs: ${def.id} carries its full script (apply, refuse, " +
                "clock in/out, notice)")
    }
    check(Jobs.SHOPS.size == 3, "jobs: the shop rota has three counters")
    for (sh in Jobs.SHOPS) {
        check(sh.locId in LOCATIONS &&
            Errands.SHOP_ASKERS[sh.locId] == sh.keeper,
            "jobs: ${sh.locId}'s rota keeper is its real keeper " +
                "(${sh.keeper})")
    }
    check(eng.KEEPERS["TweekBros"] == "Tweek" &&
        eng.KEEPERS["JimbosGuns"] == "Jimbo",
        "jobs: the rota agrees with the Engine's own keeper map")
    for ((loc, house, resident) in Jobs.ROUTE_HOUSES) {
        check(loc in LOCATIONS && resident in KID_ORDER &&
            KID_HOUSE[resident] == loc,
            "jobs: the route's $house is a real house and $resident " +
                "lives there")
    }
    check(Jobs.CUSTOMERS.keys == Jobs.SHOPS.map { it.locId }.toSet() &&
        Jobs.CUSTOMERS.values.flatten().all { it in KID_ORDER },
        "jobs: every rota counter has its regulars, and every regular " +
            "is cast")

    // ---------- the dials ----------
    check(Jobs.HIRE_STANDING_FLOOR == -10 && Jobs.MISS_LIMIT == 3 &&
        Jobs.STEADY_STREAK == 5 && Jobs.TRUSTED_STREAK == 12 &&
        Jobs.STEADY_BONUS == 1 && Jobs.TRUSTED_BONUS == 2 &&
        Jobs.ROUTE_SIZE == 4,
        "jobs: the dials as ledgered (floor -10, miss limit 3, steady " +
            "5/+1, trusted 12/+2, route 4)")
    check(Factions.standingLabel(-10) == "Suspect" &&
        Factions.standingLabel(-9) == "Unknown",
        "jobs: the hire floor is Factions' own Suspect line — standing " +
            "must be strictly better than -10")
    check(Jobs.tierBonus(0) == 0 && Jobs.tierBonus(4) == 0 &&
        Jobs.tierBonus(5) == 1 && Jobs.tierBonus(11) == 1 &&
        Jobs.tierBonus(12) == 2 &&
        Jobs.tierName(0) == "New hand" &&
        Jobs.tierName(5) == "Steady hand" &&
        Jobs.tierName(12) == "Trusted hand",
        "jobs: the streak tiers pay what the ledger says")

    // ---------- schedule & rota determinism over a year ----------
    run {
        var ok = true
        for (w in 0..51) {
            val days = (w * 7)..(w * 7 + 6)
            if (days.count { Jobs.isShiftDay(it, paper) } != 5 ||
                days.count { Jobs.isShiftDay(it, farm) } != 3 ||
                days.count { Jobs.isShiftDay(it, shop) } != 3) ok = false
        }
        check(ok, "jobs: every week of the year holds 5 paper days, " +
            "3 farm days, 3 shop days")
        check(Jobs.isShiftDay(0, paper) && Jobs.isShiftDay(0, farm) &&
            !Jobs.isShiftDay(0, shop) && !Jobs.isShiftDay(2, paper) &&
            Jobs.isShiftDay(2, farm) && Jobs.isShiftDay(1, shop),
            "jobs: day 0 (Thu) is paper+farm, day 1 (Fri) adds shop, " +
                "day 2 (Sat) is farm only")
        check(Jobs.shopFor(0).locId == "TweekBros" &&
            Jobs.shopFor(7).locId == "JimbosGuns" &&
            Jobs.shopFor(14).locId == "FreemansTacos" &&
            Jobs.shopFor(21).locId == "TweekBros",
            "jobs: the rota turns Tweek Bros → Jimbo's → Freeman's → back")
        var det = true
        for (d in 0..364) {
            if (Jobs.shopFor(d) != Jobs.shopFor(d + 21)) det = false
            if (Jobs.routeFor(d) != Jobs.routeFor(d + 6)) det = false
            val r = Jobs.routeFor(d)
            if (r.size != Jobs.ROUTE_SIZE ||
                r.distinct().size != Jobs.ROUTE_SIZE) det = false
        }
        check(det, "jobs: rota (3-week) and route (6-day) are pure " +
            "functions of the calendar, all year")
        val t1 = onDay(37, 540); val t2 = onDay(37, 540)
        check(Jobs.tasksFor(t1, paper) == Jobs.tasksFor(t2, paper) &&
            Jobs.tasksFor(t1, shop) == Jobs.tasksFor(t2, shop) &&
            Jobs.tasksFor(t1, farm).size == 3,
            "jobs: the same day deals the same card, on any state")
    }

    // ---------- the bosses are at work (natural agendas) ----------
    run {
        val s = onDay(1, 540)
        check(eng.effectiveAgendaBlock(s, s.agents["McDaniels"]!!, 540)
            ?.location == "CityHall",
            "jobs: McDaniels keeps City Hall hours on a Friday morning")
        check(eng.effectiveAgendaBlock(s, s.agents["Randy"]!!, 540)
            ?.location == "TegridyFarms",
            "jobs: Randy is on the farm on a Friday morning")
        check(eng.effectiveAgendaBlock(s, s.agents["Tweek"]!!, 930)
            ?.location == "TweekBros",
            "jobs: Tweek is behind his counter mid-afternoon")
        check(eng.effectiveAgendaBlock(s, s.agents["Jimbo"]!!, 1020)
            ?.location == "JimbosGuns",
            "jobs: Jimbo is back at the shop by five")
        val un = onDay(15, 930)
        check(Jobs.gatheringBlock(un, "Chef", 930) == null,
            "jobs: nobody pulls Chef to Freeman's while you're " +
                "unemployed — the gathering is the job's, not the town's")
    }

    // ---------- the paper route: full lifecycle through the gate ----------
    run {
        val s = onDay(1, 510)   // Friday, 8:30 AM
        val g0 = TalkGate.gateFor(s, "McDaniels", "CityHall")
        check(g0.rail == TalkGate.Rail.WORK &&
            g0.jobStep?.kind == "APPLY" && g0.jobStep?.refused == false,
            "jobs: Talk with McDaniels at her counter takes the WORK " +
                "rail — an application")
        val hired = Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(hired?.text == paper.applyText &&
            Jobs.currentJob(s) == paper && Jobs.sinceDay(s) == 1,
            "jobs: the application hires — the route is yours")
        check(Jobs.pageLines(s).any {
            it.contains("clock in with McDaniels") },
            "jobs: the Journal's WORK page points at today's clock-in")
        val g1 = TalkGate.gateFor(s, "McDaniels", "CityHall")
        check(g1.jobStep?.kind == "CLOCK_IN",
            "jobs: the next Talk is the clock-in")
        val inHit = Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(inHit?.kind == "CLOCK_IN" && Jobs.clockedIn(s) &&
            Jobs.tasksFor(s, paper).size == 4,
            "jobs: clocked in — the card holds the route's four houses")
        // the route, walked by Look at each house (the Walk's verbs)
        val route = Jobs.routeFor(1)
        check(route.map { it.second } == listOf("the Broflovski house",
            "the Cartman house", "the McCormick house",
            "the Stotch house"),
            "jobs: Friday's route is Broflovski, Cartman, McCormick, " +
                "Stotch (got ${route.map { it.second }})")
        for ((loc, _, _) in route) {
            val txt = Jobs.lookText(s, loc)
            check(txt != null && txt.startsWith("💼"),
                "jobs: the paper lands at $loc by Look")
        }
        check(Jobs.allTasksDone(s, paper) && Jobs.lookText(s, "CityHall") == null,
            "jobs: the card is full — no task fires twice, none fires " +
                "off-route")
        val g2 = TalkGate.gateFor(s, "McDaniels", "CityHall")
        check(g2.jobStep?.kind == "CLOCK_OUT",
            "jobs: with the card full, Talk with the boss is clock-out")
        val out = Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(out?.kind == "CLOCK_OUT" && Jobs.weekPay(s) == 6 &&
            Jobs.shiftsAtJob(s) == 1 && Jobs.streak(s) == 1 &&
            Jobs.shiftDoneToday(s),
            "jobs: exact pay — base 2 + 4 papers × 1 + no tier bonus " +
                "at streak 1 = 6 🪙 on the tab (got ${Jobs.weekPay(s)})")
        check(Jobs.pageLines(s).any {
            it.contains("Record here: 1 shift(s) done, streak 1") },
            "jobs: the WORK page keeps the record the shift earned")
    }

    // ---------- the standing refusal ----------
    run {
        val s = onDay(1, 540)
        s.factionStates["parents"]!!.playerStanding = -30
        check(!Jobs.standingOk(s, paper),
            "jobs: (fabrication) at standing -30 the parents' circle " +
                "is hostile")
        val hit = Jobs.talkStepFor(s, "McDaniels", "CityHall")
        check(hit?.kind == "APPLY" && hit?.refused == true,
            "jobs: the application is still offered — as a refusal")
        val judged = Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(judged?.text == paper.refuseText &&
            Jobs.currentJob(s) == null &&
            s.life["jobRefused:paper"] == 1,
            "jobs: the refusal is spoken once, stamped for the day, " +
                "and hires nobody")
        check(Jobs.talkStepFor(s, "McDaniels", "CityHall") == null,
            "jobs: no re-offer the same day — the door stays shut " +
                "until tomorrow")
        s.factionStates["parents"]!!.playerStanding = -10
        check(!Jobs.standingOk(s, paper),
            "jobs: standing exactly -10 (Suspect) still refuses")
        s.factionStates["parents"]!!.playerStanding = -9
        check(Jobs.standingOk(s, paper),
            "jobs: standing -9 (Unknown) hires — the floor is strict")
    }

    // ---------- one job at a time ----------
    run {
        val s = onDay(1, 540)
        Jobs.judgeTalk(s, "McDaniels", "CityHall")   // hired: paper
        val farmDoor = Jobs.talkStepFor(s, "Randy", "TegridyFarms")
        s.timeMin = 930   // shop hours — the pool's door, tested fairly
        val shopDoor = Jobs.talkStepFor(s, "Tweek", "TweekBros")
        check(Jobs.currentJob(s) == paper && farmDoor == null &&
            shopDoor == null,
            "jobs: holding the route, no other counter offers you " +
                "an application — one job at a time")
    }

    // ---------- quit: the record clears, the tab keeps ----------
    run {
        val s = onDay(1, 510)
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        for ((loc, _, _) in Jobs.routeFor(1)) Jobs.lookText(s, loc)
        Jobs.judgeTalk(s, "McDaniels", "CityHall")   // clock out, +6
        check(Jobs.weekPay(s) == 6, "jobs: (setup) the tab holds 6 🪙")
        s.absDay = 2; dated(s, keyOf(2)); s.timeMin = 540   // Saturday
        val hit = Jobs.talkStepFor(s, "McDaniels", "CityHall")
        check(hit?.kind == "QUIT",
            "jobs: on a rest day in work hours, Talk with the boss " +
                "offers the notice")
        val judged = Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(judged?.text == paper.quitText &&
            Jobs.currentJob(s) == null && Jobs.weekPay(s) == 6 &&
            Jobs.totalShifts(s, paper) == 1,
            "jobs: notice given — job cleared, the week's tab and " +
                "the lifetime record kept")
    }

    // ---------- the miss ladder: reminder, warning, let go ----------
    run {
        val s = onDay(0, 540)   // Thursday — hired on a farm day
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        check(Jobs.currentJob(s) == farm && Jobs.sinceDay(s) == 0,
            "jobs: (setup) hired onto the farm crew")
        s.life["jobStreak"] = 3   // a record the first miss must zero
        s.absDay = 3; dated(s, keyOf(3)); Jobs.dailyRollover(s)
        check(Jobs.missStreak(s) == 1 && Jobs.streak(s) == 0 &&
            Jobs.currentJob(s) == farm &&
            s.events.any { it.contains("reminder") },
            "jobs: Saturday's no-show settles Sunday morning as a " +
                "reminder — and the streak resets")
        s.absDay = 6; dated(s, keyOf(6)); Jobs.dailyRollover(s)
        check(Jobs.missStreak(s) == 2 &&
            s.events.any { it.contains("second word") },
            "jobs: Tuesday missed too — the boss's second word is a " +
                "warning")
        check(Jobs.pageLines(s).any {
            it.contains("missed shift(s) in a row") },
            "jobs: the WORK page shows the warning on the record")
        s.absDay = 8; dated(s, keyOf(8)); Jobs.dailyRollover(s)
        check(Jobs.currentJob(s) == null && s.life["jobFired:farm"] == 1 &&
            s.events.any { it.contains("lets you go") },
            "jobs: Thursday missed — three in a row and Randy lets " +
                "you go; the firing is on the record")
    }

    // ---------- excuses: the set-pieces outrank work ----------
    run {
        // (a) a case climax due: the missed shift is covered
        val s = onDay(0, 540)
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        s.absDay = 3; dated(s, keyOf(3)); s.timeMin = 13 * 60
        s.shenaniganId = Mystery.FINALE_ID
        s.mysteryClues.addAll(Mystery.CLUES
            .take(Mystery.TRUTH_MIN_CLUES).map { it.id })
        check(Finales.climaxPending(s),
            "jobs: (fabrication) the pond case's climax is genuinely due")
        Jobs.dailyRollover(s)
        check(Jobs.missStreak(s) == 0 && Jobs.currentJob(s) == farm &&
            s.events.any { it.contains("covered your") },
            "jobs: a shift missed to a case climax is excused before " +
                "it counts")
    }
    run {
        // (b) a finale week live yesterday: covered too
        var ended = -1
        for (d in 1..400) {
            if (!Jobs.isShiftDay(d, farm)) continue
            val probe = freshState(); dated(probe, keyOf(d))
            if (Finales.windowAt(probe) != null) { ended = d; break }
        }
        check(ended > 0,
            "jobs: (fabrication) a farm day inside a finale window " +
                "exists to test against (day $ended)")
        if (ended > 0) {
            val s = onDay(0, 540)
            Jobs.judgeTalk(s, "Randy", "TegridyFarms")
            s.absDay = ended + 1; dated(s, keyOf(ended + 1))
            Jobs.dailyRollover(s)
            check(Jobs.missStreak(s) == 0 &&
                Jobs.currentJob(s) == farm &&
                s.events.any { it.contains("covered your") },
                "jobs: a shift missed inside a finale week is excused")
        }
    }
    run {
        // (c) a family table you sat at excuses an EVENING
        // shift — and only an evening shift
        val s = onDay(0, 930)
        Jobs.judgeTalk(s, "Tweek", "TweekBros")   // hired: shop pool
        check(Jobs.currentJob(s) == shop, "jobs: (setup) in the pool")
        s.life["dinWrapDay:marsh"] = 1   // Friday night, at their table
        s.absDay = 2; dated(s, keyOf(2)); Jobs.dailyRollover(s)
        check(Jobs.missStreak(s) == 0 &&
            s.events.any { it.contains("covered your") },
            "jobs: Friday's shop shift, missed for a family table " +
                "you actually sat at, is excused")
        val s2 = onDay(0, 930)
        Jobs.judgeTalk(s2, "Tweek", "TweekBros")
        s2.absDay = 2; dated(s2, keyOf(2)); Jobs.dailyRollover(s2)
        check(Jobs.missStreak(s2) == 1,
            "jobs: the same Friday with no table sat at counts as " +
                "a miss — the excuse is earned, not ambient")
        val s3 = onDay(0, 540)
        Jobs.judgeTalk(s3, "McDaniels", "CityHall")   // hired: paper
        s3.life["dinWrapDay:marsh"] = 1
        s3.absDay = 2; dated(s3, keyOf(2)); Jobs.dailyRollover(s3)
        check(Jobs.missStreak(s3) == 1,
            "jobs: a dinner never excuses a MORNING route — the " +
                "windows have to overlap")
    }

    // ---------- a partial shift: showed up, ran out of day ----------
    run {
        val s = onDay(0, 540)
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        s.absDay = 2; dated(s, keyOf(2)); s.timeMin = 510   // Saturday
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")   // clock in
        check(Jobs.clockedIn(s), "jobs: (setup) clocked in Saturday")
        Jobs.lookText(s, "TegridyFarms")   // tend the rows, only
        s.absDay = 3; dated(s, keyOf(3)); Jobs.dailyRollover(s)
        check(Jobs.weekPay(s) == 2 && Jobs.streak(s) == 0 &&
            Jobs.missStreak(s) == 0 && Jobs.shiftDay(s) == -1 &&
            s.events.any { it.contains("ran out of day") },
            "jobs: the partial shift pays its one task (1 × 2 🪙) " +
                "into the tab, holds the streak, counts no miss, " +
                "and clears the record (got tab ${Jobs.weekPay(s)})")
    }

    // ---------- payday: the week's tab, counted out ----------
    run {
        val s = onDay(4, 510)   // Monday of week 0
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        for ((loc, _, _) in Jobs.routeFor(4)) Jobs.lookText(s, loc)
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        check(Jobs.weekPay(s) == 6 &&
            Minigames.capsuleCoins(s) == 0,
            "jobs: (setup) wages accrue on the tab — no coins yet")
        s.absDay = 7; dated(s, keyOf(7)); Jobs.dailyRollover(s)
        check(Minigames.capsuleCoins(s) == 6 &&
            Jobs.lifetimeEarned(s) == 6 && Jobs.weekPay(s) == 0 &&
            Jobs.paydayLine(s)?.contains("Payday") == true,
            "jobs: Thursday morning of the new week, payday lands — " +
                "6 🪙 counted out, the tab cleared, the line kept")
    }

    // ---------- tier pay: steady hands earn ----------
    run {
        val a = onDay(1, 510)
        Jobs.judgeTalk(a, "McDaniels", "CityHall")
        a.life["jobStreak"] = 4
        Jobs.judgeTalk(a, "McDaniels", "CityHall")
        for ((loc, _, _) in Jobs.routeFor(1)) Jobs.lookText(a, loc)
        Jobs.judgeTalk(a, "McDaniels", "CityHall")
        check(Jobs.streak(a) == 5 && Jobs.weekPay(a) == 7,
            "jobs: the shift that makes five in a row pays the " +
                "Steady bonus — 2 + 4 + 1 = 7 (got ${Jobs.weekPay(a)})")
        val b = onDay(4, 510)
        Jobs.judgeTalk(b, "McDaniels", "CityHall")
        b.life["jobStreak"] = 11
        Jobs.judgeTalk(b, "McDaniels", "CityHall")
        for ((loc, _, _) in Jobs.routeFor(4)) Jobs.lookText(b, loc)
        Jobs.judgeTalk(b, "McDaniels", "CityHall")
        check(Jobs.streak(b) == 12 && Jobs.weekPay(b) == 8 &&
            Jobs.tierName(Jobs.streak(b)) == "Trusted hand",
            "jobs: the shift that makes twelve pays the Trusted " +
                "bonus — 2 + 4 + 2 = 8 (got ${Jobs.weekPay(b)})")
    }

    // ---------- the shop rota: two weeks, two counters ----------
    run {
        val s = onDay(1, 930)   // Friday, week 0: Tweek Bros
        check(Jobs.talkStepFor(s, "Kyle", "TweekBros") == null &&
            (NpcMemoryStore.get("Kyle")?.topics
                ?.contains(Jobs.TOPIC) ?: false) == false,
            "jobs: (setup) no work thread on the regular before " +
                "any shift")
        Jobs.judgeTalk(s, "Tweek", "TweekBros")   // apply at the counter
        check(Jobs.currentJob(s) == shop &&
            Jobs.bossFor(s, shop) == "Tweek" &&
            Jobs.workplaceFor(s, shop) == "TweekBros",
            "jobs: hired into the pool at Tweek's counter — week 0 " +
                "is his")
        Jobs.judgeTalk(s, "Tweek", "TweekBros")   // clock in
        check(Jobs.clockedIn(s) && Jobs.customerFor(s, shop) == "Kyle",
            "jobs: clocked in; Friday's regular at Tweek Bros is Kyle")
        Jobs.lookText(s, "TweekBros")            // stock the shelves
        val serve = Jobs.judgeTalk(s, "Kyle", "TweekBros")
        check(serve?.kind == "TASK" &&
            Jobs.lookText(s, "TweekBros") != null,   // count the till
            "jobs: the serve beat lands by Talk, the till by Look")
        Jobs.judgeTalk(s, "Tweek", "TweekBros")   // clock out
        check(Jobs.weekPay(s) == 9 && Jobs.streak(s) == 1,
            "jobs: a full shop shift pays base 3 + 3 tasks × 2 = 9 🪙 " +
                "(got ${Jobs.weekPay(s)})")
        check(NpcMemoryStore.get("Kyle")?.topics
            ?.contains(Jobs.TOPIC) == true,
            "jobs: the served regular remembers the service — a " +
                "work thread")
        // week 2: Freeman's — Chef is pulled to his own counter
        s.absDay = 15; dated(s, keyOf(15)); s.timeMin = 930
        check(Jobs.bossFor(s, shop) == "Chef" &&
            Jobs.workplaceFor(s, shop) == "FreemansTacos",
            "jobs: week 2's counter is Freeman's, and Chef is the boss")
        check(eng.effectiveAgendaBlock(s, s.agents["Chef"]!!, 930)
            ?.location == "FreemansTacos",
            "jobs: the engine puts Chef at Freeman's for your shift — " +
                "his own agenda never takes him there")
        Jobs.judgeTalk(s, "Chef", "FreemansTacos")   // clock in
        check(Jobs.clockedIn(s) && Jobs.customerFor(s, shop) == "Butters" &&
            Jobs.gatheringBlock(s, "Butters", 930)?.location ==
                "FreemansTacos",
            "jobs: clocked in at Freeman's; the regular (Butters) is " +
                "gathered to the counter")
        Jobs.lookText(s, "FreemansTacos")
        Jobs.judgeTalk(s, "Butters", "FreemansTacos")
        Jobs.lookText(s, "FreemansTacos")
        Jobs.judgeTalk(s, "Chef", "FreemansTacos")
        check(Jobs.weekPay(s) == 18 && Jobs.shiftsAtJob(s) == 2,
            "jobs: the Freeman's shift pays the same honest 9 — the " +
                "tab holds both weeks (got ${Jobs.weekPay(s)})")
    }

    // ---------- reputation: the boss remembers the work ----------
    run {
        val s = onDay(0, 540)
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        check((NpcMemoryStore.get("Randy")?.topics
            ?.contains(Jobs.TOPIC) ?: false) == false &&
            (NpcMemoryStore.get("Sharon")?.topics
                ?.contains(Jobs.TOPIC) ?: false) == false &&
            s.agents["Randy"]!!.memories.none { it.contains("Farmhand") },
            "jobs: before any shift, no work thread anywhere — " +
                "reputation reads only true state")
        s.absDay = 2; dated(s, keyOf(2)); s.timeMin = 510   // Saturday
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")   // clock in
        Jobs.lookText(s, "TegridyFarms")             // tend the rows
        Jobs.lookText(s, "TegridyFarms")             // mend the fence
        val insp = Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        check(insp?.kind == "TASK",
            "jobs: Randy's inspection is a task beat, not a clock-out")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")   // clock out
        check(Jobs.weekPay(s) == 9,
            "jobs: a full farm shift pays base 3 + 3 tasks × 2 = 9 🪙")
        check(NpcMemoryStore.get("Randy")?.topics
            ?.contains(Jobs.TOPIC) == true &&
            NpcMemoryStore.get("Sharon")?.topics
                ?.contains(Jobs.TOPIC) == true &&
            s.agents["Randy"]!!.memories.any { it.contains("Farmhand") } &&
            s.agents["Sharon"]!!.memories.any { it.contains("book") },
            "jobs: the shift sticks — a work thread on the boss, " +
                "one on Sharon (she keeps the book), and memories " +
                "to match")
    }

    // ---------- mid-shift save round-trip ----------
    run {
        val s = onDay(1, 510)
        Jobs.judgeTalk(s, "McDaniels", "CityHall")
        Jobs.judgeTalk(s, "McDaniels", "CityHall")   // clock in
        Jobs.lookText(s, "KyleHouse")
        Jobs.lookText(s, "CartmanHouse")
        check(Jobs.tasksDone(s, paper) == 2,
            "jobs: (setup) two papers down, mid-shift")
        val back = decodeGameState(encodeGameState(s))
        check(Jobs.currentJob(back) == paper && Jobs.clockedIn(back) &&
            Jobs.tasksDone(back, paper) == 2,
            "jobs: the mid-shift save loads back on the clock, card " +
                "half-landed")
        Jobs.lookText(back, "KennysHouse")
        Jobs.lookText(back, "ButtersHouse")
        Jobs.judgeTalk(back, "McDaniels", "CityHall")
        check(Jobs.weekPay(back) == 6 && Jobs.shiftsAtJob(back) == 1,
            "jobs: the loaded shift finishes and pays in full")
    }

    // ---------- hostile saves read as unemployed / clamped ----------
    run {
        val docH = encodeGameState(freshState()).toMutableMap()
        docH["lifeText"] = mapOf("jobId" to "bogus")
        val sH = decodeGameState(docH)
        check(Jobs.currentJob(sH) == null &&
            Jobs.pageLines(sH).first().contains("no job right now"),
            "jobs: a bogus job id in the save reads as unemployed — " +
                "never a phantom job")
        val docM = encodeGameState(freshState()).toMutableMap()
        docM["lifeText"] = mapOf("jobId" to "paper")
        docM["life"] = mapOf("jobShiftDay" to 0L, "jobClocked" to 1L,
            "jobMask" to 65535L)
        val sM = decodeGameState(docM)
        check(Jobs.clockedIn(sM) && Jobs.taskMask(sM, paper) == 15 &&
            Jobs.tasksDone(sM, paper) == 4,
            "jobs: an inflated task mask is clamped to the card — " +
                "four tasks, not sixty-five thousand")
        val page = Jobs.pageLines(freshState())
        check(Jobs.JOBS.all { j -> page.any { it.contains(j.title) } } &&
            page.any { it.contains("McDaniels") },
            "jobs: the unemployed WORK page lists all three doors " +
                "and who to ask")
    }

    // ---------- wiring pins (source order, the suite's way) ----------
    run {
        val gateSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        val body = gateSrc.substringAfter("fun gateFor")
        check(body.indexOf("Dinners.talkStepFor") <
            body.indexOf("Jobs.talkStepFor") &&
            body.indexOf("Jobs.talkStepFor") <
            body.indexOf("FactionMissions.talkBeatFor"),
            "jobs: the gate peels DINNER < WORK < FACTION_MISSION — " +
                "dinner still beats work, work still beats the " +
                "faction ask")
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engSrc.indexOf("Dinners.gatheringBlock") <
            engSrc.indexOf("Jobs.gatheringBlock") &&
            engSrc.indexOf("Jobs.gatheringBlock") <
            engSrc.indexOf("Finales.gatheringBlock"),
            "jobs: the work gathering sits between dinner's and the " +
                "finale's — set-pieces still win the person")
        check(engSrc.indexOf("Dinners.dailyRollover(state)") <
            engSrc.indexOf("Jobs.dailyRollover(state)") &&
            engSrc.indexOf("Jobs.dailyRollover(state)") <
            engSrc.indexOf("Phone.dailyRollover(state)"),
            "jobs: the settlement runs after Dinners (its wraps are " +
                "the dinner excuse's evidence) and before the phone")
        val threadsSrc = File(root,
            "src/com/hunt3r/southparktown/Threads.kt").readText()
        check(threadsSrc.contains("\"work\" to listOf("),
            "jobs: Threads carries a work follow-up bank — the " +
                "thread a shift plants has somewhere to go")
    }
}

// ================= v0.6.0f: town votes =================
// Queue #6 item 6. One small civic question a week at City
// Hall; authored cast ballots (champion + faction + obsession
// leans over the persona data), the player's ballot weighted
// by the Fixture rule, a count at the week's turn, and a
// standing outcome the town lives with — its trace on Look
// at the place it belongs to. State rides life/lifeText.
private fun sectionV060f(root: String) {
    println("== v0.6.0f: town votes ==")
    val eng = Engine(6006)
    fun freshState(): GameState {
        val s = eng.newState()
        eng.createPlayer(s, "Voter", DEFAULT_APPEARANCE)
        return s
    }
    fun dated(s: GameState, key: String) {
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    val baseOrd = ordinalOfKey("20261001")
    fun keyOf(absDay: Int) = keyFromOrdinal(baseOrd + absDay)
    fun onDay(absDay: Int): GameState {
        val s = freshState()
        s.absDay = absDay
        s.timeMin = 600
        dated(s, keyOf(absDay))
        return s
    }
    fun expectedWinner(q: Votes.VoteQuestion, week: Int,
                       extra: Pair<String, Int>?): String {
        val t = Votes.castTally(q, week).toMutableMap()
        if (extra != null) t[extra.first] = (t[extra.first] ?: 0) + extra.second
        var win = q.options[0]; var wv = t[win.id] ?: 0
        for (o in q.options.drop(1)) {
            val v = t[o.id] ?: 0
            if (v > wv) { win = o; wv = v }
        }
        return win.id
    }

    // ---------- the bank ----------
    val qs = Votes.QUESTIONS
    check(qs.size >= 10,
        "votes: the bank holds at least ten questions (has ${qs.size})")
    check(qs.map { it.id }.distinct().size == qs.size,
        "votes: question ids are unique")
    val factionIds = FACTIONS.map { it.id }.toSet()
    for (q in qs) {
        check(q.options.size in 2..3, "votes: ${q.id} offers 2-3 options")
        check(q.options.map { it.id }.distinct().size == q.options.size,
            "votes: ${q.id} option ids are unique")
        check(q.locId in LOCATIONS,
            "votes: ${q.id} leaves its trace at a real place (${q.locId})")
        check(q.title.isNotBlank() && q.ask.isNotBlank(),
            "votes: ${q.id} is fully written")
        for (o in q.options) {
            check(o.champion in KID_ORDER,
                "votes: ${q.id}/${o.id} champion ${o.champion} is cast")
            check(o.factions.all { it in factionIds },
                "votes: ${q.id}/${o.id} flatters real factions")
            check(o.school == null || o.school in PocketPals.SCHOOLS,
                "votes: ${q.id}/${o.id} smells like a real school")
            check(o.label.isNotBlank() && o.trace.isNotBlank() &&
                o.epitaph.isNotBlank(),
                "votes: ${q.id}/${o.id} carries a label, a trace and an epitaph")
        }
    }

    // ---------- the rotation ----------
    val seq = (0 until 156).map { Votes.questionForWeek(it).id }
    check(seq == (0 until 156).map { Votes.questionForWeek(it).id },
        "votes: the rotation is a pure function of the week")
    var windowOk = true
    for (i in seq.indices) for (d in 1 until Votes.NO_REPEAT_WEEKS) {
        if (i + d < seq.size && seq[i] == seq[i + d]) windowOk = false
    }
    check(windowOk,
        "votes: no question repeats within ${Votes.NO_REPEAT_WEEKS} weeks over three years")
    check(seq.toSet() == qs.map { it.id }.toSet(),
        "votes: every question comes up over three years")
    for (q in qs) check(seq.count { it == q.id } >= 6,
        "votes: ${q.id} is not starved by the rotation")

    // ---------- authored ballots ----------
    for (q in qs) for (o in q.options) for (w in listOf(0, 7, 33)) {
        check(Votes.ballotOf(o.champion, q, w) == o.id,
            "votes: ${o.champion} votes their own line in ${q.id} (week $w)")
    }
    val lights = Votes.questionById("winter_lights")!!
    check(Votes.ballotOf("Cartman", lights, 3) == "rainbow",
        "votes: Cartman votes Cartman-ishly (every color, twice)")
    val bijou = Votes.questionById("bijou_matinee")!!
    check(Votes.ballotOf("Chef", bijou, 3) == "pancakes",
        "votes: Chef carries the pancake movie")
    val tallyA = Votes.castTally(bijou, 11)
    check(tallyA == Votes.castTally(bijou, 11),
        "votes: the same week tallies the same way twice")
    check(tallyA.values.sum() == KID_ORDER.size,
        "votes: every cast member votes exactly once")
    check(tallyA.keys == bijou.options.map { it.id }.toSet(),
        "votes: the tally covers the whole paper")

    // ---------- the Fixture rule ----------
    val sw = freshState()
    check(Votes.playerWeight(sw) == 1, "votes: a new kid's ballot counts once")
    sw.errandsDoneCount = 49
    check(Votes.playerWeight(sw) == 1, "votes: Neighborly still counts once")
    sw.errandsDoneCount = 50
    check(Votes.playerWeight(sw) == 2, "votes: Town Fixture counts double")
    sw.errandsDoneCount = 149
    check(Votes.playerWeight(sw) == 2, "votes: double holds until Indispensable")
    sw.errandsDoneCount = 150
    check(Votes.playerWeight(sw) == 3, "votes: Indispensable counts triple")

    // ---------- the lifecycle: vote, change, count ----------
    val s = onDay(3)
    val q0 = Votes.currentQuestion(s)
    check(q0 == Votes.questionForWeek(0), "votes: day 3 asks week 0's question")
    check(Votes.playerVote(s) == null, "votes: no ballot on record yet")
    check(!Votes.castVote(s, "not_on_the_paper"),
        "votes: an option that isn't offered is refused")
    check(Votes.castVote(s, q0.options[1].id), "votes: a ballot goes in")
    check(Votes.playerVote(s) == q0.options[1].id, "votes: the ballot reads back")
    check(Votes.castVote(s, q0.options[0].id),
        "votes: the ballot can change before the count")
    check(Votes.playerVote(s) == q0.options[0].id, "votes: the change is the record")
    Votes.retractVote(s)
    check(Votes.playerVote(s) == null, "votes: a ballot can be taken back")
    val myPick = q0.options.last().id
    check(Votes.castVote(s, myPick), "votes: the final ballot goes in")
    val wantWin = expectedWinner(q0, 0, myPick to 1)
    while (s.absDay < 7) eng.onNewDay(s)
    check(Jobs.weekIndex(s.absDay) == 1, "votes: the week has turned")
    val res = Votes.lastResult(s)
    check(res != null && res.week == 0 && res.questionId == q0.id &&
        res.countedDay == 7,
        "votes: week 0 was counted on Thursday's rollover")
    check(res!!.optionId == wantWin,
        "votes: the count matches the paper (cast + player weight)")
    check(res.playerVoted && res.playerWon == (res.optionId == myPick),
        "votes: the record knows whether your pick carried it")
    check(res.totalVotes == KID_ORDER.size + 1,
        "votes: the total counts the town plus your weighted ballot")
    check(Votes.history(s).size == 1, "votes: the count joins the Journal's memory")
    check(Votes.standingOption(s, q0)?.id == res.optionId, "votes: the winner stands")
    check(Votes.lookText(s, q0.locId) == res.option()?.trace,
        "votes: the winner's trace is on Look at its place")
    check(s.events.any { it.contains("THE COUNT IS IN") },
        "votes: the town hears the count")
    check(Votes.playerVote(s) == null, "votes: last week's ballot is shed at the turn")
    val note = Votes.morningNote(s)
    check(note != null && note.contains(res.winnerLabel()),
        "votes: the morning report carries the fresh count")
    check(Votes.freshResult(s) != null,
        "votes: the count is fresh for the phone on its morning")
    check(Phone.VOTE in Phone.TRIGGERS, "votes: the phone knows the vote trigger")
    check(s.phoneTexts.any { it.sender == "McDaniels" &&
        it.trigger == Phone.VOTE && it.text.contains(res.winnerLabel().take(12)) },
        "votes: City Hall texts the result on the count's morning")

    // ---------- the town decides without you ----------
    val s2 = onDay(10)
    val q1 = Votes.currentQuestion(s2)
    check(q1 == Votes.questionForWeek(1), "votes: day 10 asks week 1's question")
    while (s2.absDay < 14) eng.onNewDay(s2)
    val res2 = Votes.lastResult(s2)
    check(res2 != null && res2.week == 1 && !res2.playerVoted && !res2.playerWon,
        "votes: an unvoted week still counts, and says so")
    check(res2!!.optionId == expectedWinner(q1, 1, null),
        "votes: without you, the cast's paper decides it")
    check(res2.totalVotes == KID_ORDER.size,
        "votes: and the total is the town alone")

    // ---------- standings: expiry and replacement ----------
    val dock = Votes.questionById("dock_name")!!
    val s3 = onDay(7)
    s3.lifeText["voteStand:${dock.id}"] = dock.options[0].id
    s3.life["voteStandDay:${dock.id}"] = 7
    check(Votes.standingOption(s3, dock) == dock.options[0],
        "votes: a fresh standing reads")
    check(Votes.lookText(s3, dock.locId) == dock.options[0].trace,
        "votes: and its trace shows")
    s3.absDay = 7 + Votes.OUTCOME_WEEKS * 7 - 1
    check(Votes.standingOption(s3, dock) != null,
        "votes: a standing lives its full span")
    s3.absDay = 7 + Votes.OUTCOME_WEEKS * 7
    check(Votes.standingOption(s3, dock) == null,
        "votes: and lapses when the span runs out")
    check(Votes.lookText(s3, dock.locId) == null, "votes: the trace goes with it")
    val rw = (0..40).first { Votes.questionForWeek(it).id == dock.id }
    val s3b = onDay(rw * 7 + 2)
    s3b.lifeText["voteStand:${dock.id}"] = dock.options[0].id
    s3b.life["voteStandDay:${dock.id}"] = s3b.absDay
    Votes.countWeek(s3b, rw)
    val resB = Votes.lastResult(s3b)
    check(resB != null && Votes.standingOption(s3b, dock)?.id == resB.optionId,
        "votes: a recount replaces the standing, whatever won before")

    // ---------- every option of every question has a trace ----------
    for (q in qs) for (o in q.options) {
        val st = onDay(20)
        st.lifeText["voteStand:${q.id}"] = o.id
        st.life["voteStandDay:${q.id}"] = 20
        check(Votes.standingOption(st, q) == o, "votes: ${q.id}/${o.id} can stand")
        check(Votes.lookText(st, q.locId) == o.trace,
            "votes: ${q.id}/${o.id} leaves its trace at ${q.locId}")
    }

    // ---------- multi-week jumps count every finished week ----------
    val s4 = onDay(0)
    s4.absDay = 22
    Votes.dailyRollover(s4)
    check(Votes.lastResult(s4)?.week == 2,
        "votes: a long sleep counts weeks 0-2, latest on top")
    check(Votes.history(s4).size == 3, "votes: and remembers all three counts")

    // ---------- the Journal page ----------
    val page = Votes.pageLines(s)
    check(page.first().contains("TOWN VOTES"), "votes: the page has its masthead")
    check(page.any { it.contains("PAST COUNTS") }, "votes: the page keeps past counts")
    check(page.any { it.contains("STANDING IN TOWN") },
        "votes: the page lists what's standing")
    check(page.any { it.contains("graciously") },
        "votes: the runner-up's epitaph is on the page")
    val freshPage = Votes.pageLines(freshState())
    check(freshPage.any { it.contains("haven't voted") },
        "votes: a fresh page invites a ballot")

    // ---------- morning-note discipline ----------
    val s5 = onDay(6)
    check(Votes.morningNote(s5)?.contains("Last day to vote") == true,
        "votes: the week's last morning nudges an uncast ballot")
    Votes.castVote(s5, Votes.currentQuestion(s5).options[0].id)
    check(Votes.morningNote(s5) == null, "votes: and goes quiet once you've voted")
    check(Votes.morningNote(onDay(3)) == null, "votes: mid-week mornings say nothing")

    // ---------- save round-trips and hostile docs ----------
    val s6 = onDay(3)
    val q6 = Votes.currentQuestion(s6)
    Votes.castVote(s6, q6.options[0].id)
    val back = decodeGameState(encodeGameState(s6))
    check(Votes.playerVote(back) == q6.options[0].id,
        "votes: a ballot survives the save")
    val back2 = decodeGameState(encodeGameState(s))
    check(Votes.lastResult(back2) == res, "votes: the last count survives the save")
    check(Votes.history(back2) == Votes.history(s),
        "votes: the history survives the save")
    check(Votes.standingOption(back2, q0)?.id == res.optionId,
        "votes: the standing survives the save")
    val hostile = freshState()
    hostile.absDay = 3
    hostile.life["voteWeek"] = 0
    hostile.lifeText["voteChoice"] = "write_in_ghost"
    check(Votes.playerVote(hostile) == null,
        "votes: a ballot for an option that isn't offered reads as none")
    hostile.lifeText["voteLastResult"] = "not|a|real|record"
    check(Votes.lastResult(hostile) == null,
        "votes: a malformed count record reads as none")
    hostile.lifeText["voteStand:${dock.id}"] = dock.options[0].id
    hostile.life["voteStandDay:${dock.id}"] = 9999
    check(Votes.standingOption(hostile, dock) == null,
        "votes: a standing dated in the future does not stand")

    // ---------- chassis pins: the wiring is really wired ----------
    val engineSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val ji = engineSrc.indexOf("Jobs.dailyRollover(state)")
    val vi = engineSrc.indexOf("Votes.dailyRollover(state)")
    val pi = engineSrc.indexOf("Phone.dailyRollover(state)")
    check(ji >= 0 && vi > ji && pi > vi,
        "votes: the count settles after Jobs and before the phone harvest")
    val houseSrc = File(root, "src/com/hunt3r/southparktown/House.kt").readText()
    check(houseSrc.indexOf("Finales.morningNote") in 0 until
        houseSrc.indexOf("Votes.morningNote"),
        "votes: the morning note rides below the finales")
    val gvSrc = File(root, "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("drawBallotBox") && gvSrc.contains("\"ballotbox\""),
        "votes: the ballot box is drawn in City Hall with its tap")
    val gaSrc = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("ballotDialog()") && gaSrc.contains("Votes.lookText"),
        "votes: the box opens the ballot and Look carries the traces")
    val jSrc = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jSrc.contains("Votes.pageLines"), "votes: the Journal renders the votes page")
    val phSrc = File(root, "src/com/hunt3r/southparktown/Phone.kt").readText()
    check(phSrc.contains("Votes.freshResult"),
        "votes: the phone harvest reads the fresh count")
    val thSrc = File(root, "src/com/hunt3r/southparktown/Threads.kt").readText()
    check(thSrc.contains("\"vote\" to listOf"),
        "votes: the champions keep the thread in talks")
    val readme = File(root, "docs/TUNING.md").readText()
    for (dial in listOf("NO_REPEAT_WEEKS", "OUTCOME_WEEKS", "HISTORY_CAP",
        "CHAMPION_LEAN", "FACTION_LEAN", "SCHOOL_LEAN")) {
        check(readme.contains(dial), "votes: the tuning ledger names $dial")
    }
}

// =====================================================================
// SECTION v0.6.0g — polish & performance pass #6: the Queue #6 audit.
// The train's own discipline, sixth time: measure everything
// the queue added, pin the seams it left between systems, and
// change production code only where a measurement says a real
// defect lives. Queue #6 gave the town weekly photo
// commissions, chained favors, a fourth case, family evenings,
// town jobs and town votes; the audit re-runs the lifetime
// with all six living in it (the soak extension rides in
// sectionV030g, where the unified 400 years... days live),
// re-measures the saturated save as VETERAN V, fits the five
// newest Journal pages, proves the Talk rail's final order
// under the fullest contention the cast data allows, walks
// the five cross-system seams, re-checks the audio peak
// budget at a fifth distance, and sweeps the tuning ledger
// for every Queue #6 dial. No new features; the case this
// queue opened stays sealed here exactly as in the README —
// structure only, never the secret.
// =====================================================================
private fun sectionV060g(root: String) {
    println("== v0.6.0g: polish pass #6 — the Queue #6 audit ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.6.0g"),
        "v0.6.0g: the README carries this build's changelog entry")

    run {
        // ---------- veteran save V ----------
        // The veteran IV body, carried whole, with Queue #6's
        // state laid over it at its own caps: a commission
        // list at the state cap with the plate full, prints
        // stamped into the album, a live chain link mid-tail,
        // the fourth case's typed state closed, dinner counts
        // for every household, a job record with a warm tab,
        // and a vote history counted full through the module's
        // own rollover. Does the honest worst case still fit,
        // and does it round-trip?
        val engV5 = Engine(115)
        val vet = engV5.newState()
        engV5.createPlayer(vet, "Veteran", DEFAULT_APPEARANCE)
        vet.gameYear = 2028; vet.gameMonth = 6; vet.gameDay = 15
        vet.todayKey = "20280615"; vet.lastPlayedDate = "20280615"; vet.absDay = 700
        for (n in CharacterSystem.CAST.keys) vet.friendship[n] = 100
        for ((_, a) in vet.agents) repeat(25) {
            a.memories.add("A whole day in South Park, Colorado — the whole town " +
                "was involved and absolutely nobody learned a thing.")
        }
        repeat(40) { vet.events.add("📌 A day where everything happened at once, again ($it)") }
        repeat(30) { townLogLine(vet, "🎪 Town history entry $it — a full sentence about the day.") }
        for (sp in FISH_TABLE) vet.fishLog[sp.id] = FishRecord(999, sp.maxCm)
        for (kid in CharacterSystem.CAST_KIDS) vet.showdown[kid] = ShowdownRecord(400, 400)
        vet.fishCasts = 9000; vet.tacoHigh = 640; vet.tacoPlays = 900
        vet.followers = 250000
        for (item in ITEMS) vet.inventory[item.id] = 99
        vet.inventory[Minigames.COIN_ITEM] = 9999
        for (c in Mystery.CLUES) vet.mysteryClues.add(c.id)
        vet.arcStarted = true; vet.arcChapter = 5
        vet.arcRetired = true; vet.arcBranch = "truth"
        for (c in Mystery2.CLUES2) vet.mystery2Clues.add(c.id)
        vet.arc2Started = true; vet.arc2MarathonDay = 380
        vet.arc2AccusationAired = true; vet.arc2Retired = true
        vet.arc2Branch = "wrong"; vet.arc2Accused = "craig"
        vet.arc2Usher = "Alexandria Featherstonehaugh"
        vet.arc2RetiredDay = 390; vet.arc2ReelFound = true
        vet.arc2FlavorSeen.addAll(listOf("Clyde", "Craig"))
        for (c in Mystery3.CLUES3) vet.mystery3Clues.add(c.id)
        vet.arc3Started = true; vet.arc3Chapter = 4
        vet.arc3Retired = true; vet.arc3Branch = "sharon"
        vet.arc3Choice = "sharon"; vet.arc3RetiredDay = 690
        vet.arc3SharonText = "Sharon's decision, in full: the box goes home " +
            "to the valley it came from, and the town never digs there again."
        for (def in StoryArcs.ARCS) {
            vet.storyArcs[def.id] = StoryArcState(def.id, stage = def.stages.size,
                stageStartAbsDay = 390, startedAbsDay = 370, finishedAbsDay = 395,
                done = true, outcomeId = def.warm.id,
                helpedStages = (0 until def.stages.size).toMutableSet(),
                stageNudges = def.core.toMutableSet(),
                stageTalkShown = (def.parties + def.supporting).toMutableSet())
        }
        val vetTypes = listOf("FETCH", "DELIVER", "FIND", "FIX", "PHOTO", "PLAY")
        repeat(Errands.STATE_CAP) { i ->
            vet.errands.add(Errand("vet-e$i",
                listOf(Errands.BOARD, Errands.ASK, Errands.SHOP)[i % 3],
                CharacterSystem.CAST.keys.elementAt(i % 54),
                vetTypes[i % vetTypes.size],
                "The longest-running favor in town, part $i.",
                "It's around.", itemId = ITEMS[i % ITEMS.size].id,
                targetName = "Alexandria Featherstonehaugh",
                dayKey = "20280615", acceptedDay = 699, done = i % 2 == 0))
        }
        // one plate slot is a live chain link, mid-tail
        vet.errands[1] = Errand("vet-chain", Errands.BOARD, "Stan", "DELIVER",
            "A favor inside a favor inside a favor, still going.",
            "It's around.", targetName = "Kyle",
            dayKey = "20280615", acceptedDay = 699,
            chainId = "c:vet", chainLink = 2, chainLen = 3,
            chainFrom = "Stan", chainPrior = listOf("Picked up the thing"),
            chainRest = listOf(Errand("vet-chain:3", Errands.BOARD, "Kyle",
