        vet.life["chainsDone"] = 250
        repeat(Errands.STATE_RECENT_CAP) { i ->
            vet.errandsRecent.add(ErrandDoneNote("vet-d$i", "20280614",
                "Ran the big one for the whole town and lived to tell it ($i)"))
        }
        for (n in CharacterSystem.CAST.keys) vet.errandAsked[n] = 700
        vet.errandsDoneCount = 1500
        for (h in HOLIDAYS) {
            val full = (1 shl HolidayBeats.beatFor(h.id)!!.steps.size) - 1
            for (y in listOf(2027, 2028)) {
                vet.life["hb:${h.id}:$y:mask"] = full
                vet.life["hb:${h.id}:$y:done"] = 1
            }
            vet.life["hbYears:${h.id}"] = 2
        }
        vet.life["hbTotal"] = 16
        vet.life["wishes"] = 500
        vet.life["selfies"] = 900
        vet.life["groupShots"] = 400
        vet.life[SkyState.LAST_SKY_DAY_KEY] = 700
        vet.lifeText[SkyState.LAST_SKY_KEY] = SkyState.AURORA
        for (f in Minigames.GAME_FEATS) vet.gameFeats.add(f.id)
        for (f in Photos.PHOTO_FEATS) vet.photoFeats.add(f.id)
        repeat(24) { vet.convertedResidents.add("Converted Resident With A Long Lore Name $it") }
        repeat(300) { vet.photographed["Photographed Townsfolk With A Name $it"] = 7 }
        for (loc in LOCATIONS.keys) {
            vet.locVisits[loc] = 999
            vet.lifeText["mark:$loc"] = "Stan"
            vet.lifeText["chalk:$loc"] = "a very elaborate chalk mural"
            vet.lifeText["prank:$loc"] = "whoopee cushion, deluxe"
            vet.life["clean:$loc"] = 9
        }
        for (n in CharacterSystem.CAST.keys) {
            vet.npcGoals[n] = NpcGoal.fromMap(mapOf("npcKey" to n))!!
        }
        repeat(30) { i ->
            vet.episodes.add(EpisodeRecord(
                key = "event$i@20260101", kind = "event", eventId = "event$i",
                eventTitle = "The Big Event $i", title = "The One Where Everything Happens $i",
                treatment = "A very special episode, presented without commercial interruption.",
                causers = listOf("Stan", "Kyle", "Cartman", "Kenny"),
                dayKey = "20260101", dateLabel = "1/1",
                stageTitles = listOf("Cold Open", "Act One", "Act Two", "The Wrap"),
                stageNotes = listOf("It starts.", "It escalates.", "It peaks.", "It lands."),
                finished = true, participation = 10))
        }
        repeat(60) { i ->
            if (i < 24) {
                vet.photos.add(PhotoRecord(
                    id = "vetg$i", dayKey = "20280615", dateLabel = "6/15",
                    timeMin = 700, locId = "MainStreet", inside = false,
                    weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
                    figures = listOf(
                        PhotoFigure("Veteran", "player", "happy"),
                        PhotoFigure("Craig", "cast", "hurt", "backToBack",
                            reaction = "goofy", points = 40),
                        PhotoFigure("Tweek", "cast", "hurt", "backToBack",
                            reaction = "goofy", points = 42),
                        PhotoFigure("Stan", "cast", "happy", "none",
                            reaction = "happy", points = 55),
                        PhotoFigure("Cartman", "cast", "happy", "bomb",
                            reaction = "bomb", points = 12)),
                    caption = "The whole gang, posed and crashed, again ($i)",
                    followersGained = 40, seed = 1000L + i, absDay = 640 + i,
                    composition = listOf(Photos.COMP_LINEUP, Photos.COMP_SQUAD,
                        Photos.COMP_STACKED)[i % 3]))
            } else {
                vet.photos.add(PhotoRecord(
                    id = "vet$i", dayKey = "20280615", dateLabel = "6/15",
                    timeMin = 700, locId = "MainStreet", inside = false,
                    weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
                    figures = listOf(PhotoFigure("Veteran", "player", "happy"),
                        PhotoFigure("Stan", "cast", "happy"),
                        PhotoFigure("Kyle", "cast", "goofy")),
                    caption = "Best day ever in South Park with the whole gang, again ($i)",
                    followersGained = 25, seed = i.toLong(), absDay = 640 + i))
            }
        }
        // the walk ledger, the wardrobe, the binder, the
        // faction chains and the phone, at their caps
        vet.busPass = true
        vet.walkTrips = 900; vet.walkLegs = 4000; vet.walkCarryMin = 14
        for ((from, exits) in EXITS) for (to in exits)
            vet.walkShortcuts.add("$from>$to")
        vet.life["walkRides"] = 300
        for (p in Wardrobe.PIECES) vet.unlockedWardrobe.add(p.id)
        for (card in PocketPals.CARDS) vet.pocketPals[card.id] = PocketPals.COUNT_CAP
        vet.life["palPulls"] = 5000
        for (ch in FactionMissions.CHAINS) {
            vet.life["fmMask:${ch.factionId}"] = 0b111
            vet.life["fmActive:${ch.factionId}"] = 0
        }
        val threadNames = KID_ORDER.sortedByDescending { it.length }.take(6)
        var seq = 0
        for (tName in threadNames) repeat(Phone.MAX_PER_THREAD) { k ->
            seq++
            vet.phoneTexts.add(PhoneText(
                id = "vet-t$seq", thread = tName,
                sender = if (k % 7 == 3) "you" else tName,
                trigger = Phone.HELLO, absDay = 699, dayKey = "20280615",
                text = "A maximally long town text about absolutely everything " +
                    "that happened today, in complete detail, with opinions ($seq)".padEnd(280, '·'),
                read = k % 3 != 0))
        }
        for (kind in listOf(Phone.FEAT, Phone.PHOTO, Phone.ERRAND, Phone.PULL))
            repeat(6) { vet.phoneNotes.add("699|$kind|Stan|") }
        vet.phoneMeta["seq"] = seq
        vet.phoneMeta["lastRoll"] = 699
        vet.phoneMeta["replies"] = 3
        for (def in Finales.DEFS) {
            vet.lifeText["finMark:${def.id}"] = def.choices[0].markText
            vet.life["finMarkYear:${def.id}"] = 2028
            vet.lifeText["finMarkBy:${def.id}"] = "you"
            vet.lifeText["finMarkWinner:${def.id}"] = def.choices[0].winner
            vet.life["fin:${def.id}:2028:mask"] =
                (1 shl def.steps.size) - 1
            vet.life["fin:${def.id}:2028:choice"] = 0
            vet.life["fin:${def.id}:2028:done"] = 1
            vet.life["finRuns:${def.id}"] = 2
            vet.life["finPlayed:${def.id}"] = 2
        }
        // ---- Queue #6's state, at its caps ----
        // the fourth case, closed, its full clue set held
        for (c in Mystery4.CLUES4) vet.mystery4Clues.add(c.id)
        vet.arc4Started = true; vet.arc4Chapter = 4
        vet.arc4Retired = true; vet.arc4Branch = "guard"
        vet.arc4RetiredDay = 695; vet.arc4DueAbsDay = -1
        vet.arc4LastFixLanded = true
        // commissions: the state list at its cap, the plate
        // full, the recent record full, the counter deep
        val castListV = CharacterSystem.CAST.keys.toList()
        repeat(Commissions.STATE_CAP) { i ->
            vet.commissions.add(Commission(
                id = "c290:$i", asker = castListV[i % 54],
                subjects = listOf(castListV[(i + 5) % 54]),
                locId = "MainStreet", condKind = "", condValue = "",
                text = "The longest-standing commission in town, part $i.",
                pay = 5, week = 290, acceptedDay = 699,
                expiresDay = 706, done = i >= Commissions.MAX_PLATE))
        }
        vet.commissionsDone = 500
        repeat(Commissions.RECENT_CAP) { i ->
            vet.commissionRecent.add(CommissionNote("c28$i:0", "20280614",
                "✔ The longest print run in town — a print for a friend ($i)"))
        }
        // every sixth album photo is a commissioned print
        vet.photos.forEachIndexed { i, p ->
            if (i % 6 == 0) {
                p.commissionAsker = "Stan"
                p.commissionText = "The longest-standing commission in town."
            }
        }
        // family evenings: every household sat and hosted, deep
        for (h in Dinners.HOUSEHOLDS) {
            vet.life["dinAttended:${h.id}"] = 60
            vet.life["dinHosted:${h.id}"] = 25
        }
        // town votes: ten real counts through the module's own
        // rollover — the history pins at its cap and the
        // standings stand at theirs
        repeat(10) {
            val q = Votes.currentQuestion(vet)
            Votes.castVote(vet, q.options[it % q.options.size].id)
            vet.absDay += 7
            Votes.dailyRollover(vet)
        }
        // the job record: a shop tenure, a warm tab, totals
        vet.lifeText["jobId"] = "shop"
        vet.life["jobSince"] = 100
        vet.life["jobShifts"] = 300
        vet.life["jobStreak"] = 12
        vet.life["jobMissStreak"] = 0
        vet.life["jobWeekPay"] = 250
        vet.life["jobEarned"] = 99999
        vet.lifeText["jobPaydayLine"] =
            "💼 Payday: a long season of shifts, settled in full."
        vet.life["jobTotal:farm"] = 200
        vet.life["jobTotal:paper"] = 200
        vet.life["jobTotal:shop"] = 200
        vet.life["jobShiftDay"] = vet.absDay
        vet.life["jobClocked"] = 0
        vet.life["jobShiftDone"] = 1
        vet.life["jobMask"] = 7
        vet.life["jobSettledDay"] = vet.absDay - 1
        val vetJson = Json.stringify(encodeGameState(vet))
        println("veteran V game_state: ${vetJson.length} chars serialized")
        check(vetJson.length < 512 * 1024,
            "veteran V: the saturated save (Queue #6 included) stays " +
                "under the 512K ceiling (got ${vetJson.length})")
        check(vetJson.length > 286_249,
            "veteran V: today's full state outgrows veteran IV's " +
                "286,249 — the growth is the queue's own records, " +
                "each one capped (got ${vetJson.length})")
        @Suppress("UNCHECKED_CAST")
        val vetBack = decodeGameState(Json.parse(vetJson) as Map<String, Any?>)
        check(vetBack.errands.size == Errands.STATE_CAP &&
            vetBack.photos.size == 60 && StoryArcs.allDone(vetBack) &&
            vetBack.busPass && vetBack.walkTrips == 900,
            "veteran V: the veteran IV body still round-trips whole")
        check(vetBack.commissions.size == Commissions.STATE_CAP &&
            Commissions.activeCount(vetBack) == Commissions.MAX_PLATE &&
            vetBack.commissionsDone == 500 &&
            vetBack.commissionRecent.size == Commissions.RECENT_CAP &&
            vetBack.photos.count { it.isCommissioned } == 10,
            "veteran V: the commission list, plate, recent record " +
                "and stamped prints round-trip at their caps " +
                "(list ${vetBack.commissions.size}, prints " +
                "${vetBack.photos.count { it.isCommissioned }})")
        check(Errands.chainsDone(vetBack) == 250 &&
            vetBack.errands.first { it.id == "vet-chain" }.chainRest.size == 1 &&
            vetBack.errands.first { it.id == "vet-chain" }.chainLink == 2,
            "veteran V: the chain ledger and a live mid-tail link " +
                "round-trip whole")
        check(vetBack.arc4Retired && vetBack.arc4Branch == "guard" &&
            vetBack.mystery4Clues.size == Mystery4.CLUES4.size &&
            vetBack.arc4Chapter == 4,
            "veteran V: the fourth case's typed state round-trips " +
                "closed, its clue set complete")
        check(Dinners.totalAttended(vetBack) == 7 * 60 &&
            Dinners.totalHosted(vetBack) == 7 * 25,
            "veteran V: seven households of dinner counts " +
                "round-trip (attended ${Dinners.totalAttended(vetBack)}, " +
                "hosted ${Dinners.totalHosted(vetBack)})")
        check(Jobs.currentJob(vetBack)?.id == "shop" &&
            Jobs.lifetimeEarned(vetBack) == 99999 &&
            Jobs.totalShifts(vetBack, Jobs.defById("farm")!!) == 200 &&
            Jobs.streak(vetBack) == Jobs.TRUSTED_STREAK,
            "veteran V: the job record round-trips — tenure, " +
                "lifetime wages, per-job totals, the Trusted streak")
        check(Votes.history(vetBack).size == Votes.HISTORY_CAP &&
            Votes.QUESTIONS.count {
                Votes.standingOption(vetBack, it) != null } >= 6,
            "veteran V: the vote history round-trips at its cap " +
                "with standings standing (history " +
                "${Votes.history(vetBack).size})")

        // ---------- fit QA: Queue #6's newest screens ----------
        // The same discipline on the five pages the queue
        // added, composed off this same saturated state — the
        // fullest each page can ever be.
        val q6Lines = mutableListOf<String>()
        q6Lines += Commissions.pageLines(vetBack)
        q6Lines += Errands.pageLines(vetBack)
        q6Lines += Dinners.pageLines(vetBack)
        q6Lines += Jobs.pageLines(vetBack)
        q6Lines += Votes.pageLines(vetBack)
        check(Commissions.pageLines(vetBack).first().contains("COMMISSIONS") &&
            Dinners.pageLines(vetBack).first().contains("FAMILY EVENINGS") &&
            Jobs.pageLines(vetBack).first().contains("WORK") &&
            Votes.pageLines(vetBack).first().contains("TOWN VOTES"),
            "fitQA: the Queue #6 Journal pages carry their titles")
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { s: String -> s.length * 10f * fs }
            for (line in q6Lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a Queue #6 screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a Queue #6 screen line never collapses at fs $fs")
            }
        }
    }

    run {
        // ---------- the rail order, final form ----------
        // Queue #6 added DINNER and WORK to the Talk gate, and
        // the order is now the whole ladder. First the source
        // pin, scoped to gateFor's own body: the order the
        // judges are TRIED is the order a stacked conversation
        // peels in.
        val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        val railOrder = listOf("Rail.DELIVER", "Rail.HOLIDAY_BEAT",
            "Rail.FINALE", "Rail.CLIMAX", "Rail.DINNER", "Rail.WORK",
            "Rail.FACTION_MISSION", "Rail.ERRAND_ASK", "Rail.DIALOGUE")
        val railIdx = railOrder.map { gateBody.indexOf(it) }
        check(railIdx.all { it >= 0 } &&
            railIdx.zipWithNext().all { (a, b) -> a < b },
            "rail order: gateFor tries DELIVER, HOLIDAY_BEAT, " +
                "FINALE, CLIMAX (v0.7.0e, extended in place), " +
                "DINNER, WORK, FACTION_MISSION, ERRAND_ASK " +
                "and DIALOGUE in exactly that order")

        // Then the fullest live stack the cast data allows.
        // Jimbo's five-rail stack (sectionV050i) still stands
        // unchanged; Queue #6's two new rails can't join it —
        // no dinner household is his and the gun counter's
        // evening shift is the one thing his finale week never
        // overlaps. RANDY is the man who can hold the new
        // ladder whole: a delivery can be addressed to him,
        // the Fourth's rehearsal deputizes him, spring's
        // confession step is his, the Marsh table seats him,
        // the farm's inspection is a Talk with the boss
        // himself, the parents' chain ends by reporting to
        // him, and his goals give him days with something to
        // ask. The calendar never stacks them — the spring
        // finale wants late May, the Fourth wants July, dinner
        // wants a rotation Tuesday — so, like Jimbo's, the
        // stack is fabricated honestly: every rail armed
        // through its own module's state, every peel through
        // its own judge.
        val eng = Engine(606_007)
        var stack: GameState? = null
        var stackYear = -1
        outer@ for (y in 2027..2060) {
            for (ad in 999..1400 step 7) {   // ad % 7 == 5: a Tuesday
                val cand = eng.newState()
                eng.createPlayer(cand, "Stack", DEFAULT_APPEARANCE)
                cand.absDay = ad
                cand.gameYear = y; cand.gameMonth = 5; cand.gameDay = 28
                cand.todayKey = "%04d0528".format(y)
                Dinners.dailyRollover(cand)
                if (Dinners.todaysInvite(cand)?.id != "marsh") continue
                if (Errands.askFor(cand, "Randy") == null) continue
                stack = cand; stackYear = y
                break@outer
            }
        }
        check(stack != null,
            "contention: a spring Tuesday exists where the Marsh " +
                "table is set and Randy has something to ask")
        val s = stack!!
        // the farm, in the morning: hired, clocked in, the
        // rows and the fence done — the inspection (the boss
        // Talk task) still standing when the day runs long.
        s.timeMin = 8 * 60 + 30
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        Jobs.lookText(s, "TegridyFarms")
        Jobs.lookText(s, "TegridyFarms")
        check(Jobs.currentJob(s)?.id == "farm" && Jobs.clockedIn(s) &&
            Jobs.talkStepFor(s, "Randy", "TegridyFarms")?.kind == "TASK",
            "contention: the farm inspection stands armed on Randy")
        // the parents' chain, walked to its final beat — the
        // report delivered to Randy in person
        s.factionStates["parents"]!!.playerStanding = 50
        FactionMissions.offerFor(s, "Sharon")?.let {
            FactionMissions.accept(s, it) }
        FactionMissions.lookText(s, "MainStreet")
        val parentsChain = FactionMissions.CHAINS
            .first { it.factionId == "parents" }
        FactionMissions.offerFor(s, parentsChain.beats[1].offerNpc)?.let {
            FactionMissions.accept(s, it) }
        s.inventory["hot_chocolate"] = 1
        FactionMissions.onGive(s, "Barbrady", "hot_chocolate")
        FactionMissions.offerFor(s, "McDaniels")?.let {
            FactionMissions.accept(s, it) }
        check(FactionMissions.talkBeatFor(s, "Randy") != null,
            "contention: the Watch report stands armed on Randy")
        // spring, walked to the confession step (the garden
        // step aged out by day three; the Look between is real)
        val springDef = Finales.defById("spring")!!
        Finales.dailyRollover(s)
        Finales.lookText(s, springDef.steps[1].loc!!)
        s.agents[springDef.steps[2].who]!!.location =
            springDef.steps[2].loc ?: "KidsPark"
        Finales.judgeTalk(s, springDef.steps[2].who!!)
        s.agents["Randy"]!!.location = springDef.steps[3].loc ?: "KidsPark"
        check(Finales.talkStepFor(s, "Randy") != null,
            "contention: the spring confession stands armed on Randy")
        // the Fourth's rehearsal: the pond already provided
        s.holidayId = "july4"
        s.life["hb:july4:$stackYear:mask"] = 1
        check(HolidayBeats.talkStepFor(s, "Randy") != null,
            "contention: the rehearsal deputizing stands armed on Randy")
        // a delivery in hand, addressed to him
        s.errands.add(Errand(id = "stack-deliver", source = Errands.BOARD,
            asker = "Ned", type = "DELIVER", text = "t", hint = "h",
            targetName = "Randy", itemId = "fishing_lure",
            dayKey = s.todayKey, acceptedDay = s.absDay))
        s.inventory["fishing_lure"] =
            (s.inventory["fishing_lure"] ?: 0) + 1
        check(Errands.active(s).any {
            it.type == "DELIVER" && it.targetName == "Randy" },
            "contention: a delivery stands addressed to Randy")
        // the evening: the Marsh welcome lands, and the table
        // talk that follows is his
        s.timeMin = 17 * 60 + 45
        Dinners.judgeTalk(s, "Sharon")
        check(Dinners.talkStepFor(s, "Randy") != null,
            "contention: the Marsh table talk stands armed on Randy")
        check(Errands.askFor(s, "Randy") != null,
            "contention: Randy's ask survived the arming")
        // TOTAL CONTENTION — every rail he can hold, one man,
        // one tap. The peel runs the final order end to end.
        var g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DELIVER,
            "contention: a delivery outranks everything (got ${g.rail})")
        Errands.deliverTo(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.HOLIDAY_BEAT,
            "contention: the holiday beat is next (got ${g.rail})")
        HolidayBeats.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.FINALE,
            "contention: the finale is next (got ${g.rail})")
        Finales.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DINNER,
            "contention: the dinner beat is next (got ${g.rail})")
        Dinners.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.WORK &&
            g.jobStep?.kind == "TASK",
            "contention: the inspection is next (got ${g.rail})")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.WORK &&
            g.jobStep?.kind == "CLOCK_OUT",
            "contention: a finished shift still holds the work " +
                "rail — the clock-out is owed (got ${g.rail})")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.FACTION_MISSION,
            "contention: the faction beat is next (got ${g.rail})")
        FactionMissions.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.ERRAND_ASK,
            "contention: the direct ask is next (got ${g.rail})")
        Errands.markAsked(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DIALOGUE,
            "contention: and at the bottom of the whole ladder, " +
                "a conversation (got ${g.rail})")
    }

    run {
        // ---------- the Queue #6 seams ----------
        val engS = Engine(606_101)
        val shopDef = Jobs.defById("shop")!!
        val paperDef = Jobs.defById("paper")!!

        // ---- dinners × jobs: the excuse is asymmetric ----
        // A sat family evening excuses an EVENING shift that
        // ran across it — the shop counters close at six and
        // half six — and never a morning paper route: the
        // papers were due before the table was set. Pinned at
        // the decision function and at the rollover it feeds.
        var seamDay = -1
        var seamState: GameState? = null
        // Fridays: the one weekday that is both a dinner
        // evening and a shop shift day — the overlap the
        // asymmetry lives in (and clear of the autumn finale)
        for (ad in listOf(36, 43, 50, 57)) {   // November Fridays
            val cand = engS.newState()
            engS.createPlayer(cand, "Seam", DEFAULT_APPEARANCE)
            cand.absDay = ad
            cand.gameYear = 2026; cand.gameMonth = 11
            cand.gameDay = 6 + (ad - 36)
            cand.todayKey = "202611%02d".format(cand.gameDay)
            Dinners.dailyRollover(cand)
            if (Dinners.todaysInvite(cand) != null) {
                seamDay = ad; seamState = cand; break
            }
        }
        check(seamState != null,
            "seam: a November Friday carries a family evening")
        val sD = seamState!!
        // hired the day BEFORE the dinner: a job taken the
        // same morning is never missable (the rollover spares
        // the hire day), so the excuse — not the calendar —
        // is what has to save this shift
        sD.absDay = seamDay - 1
        sD.gameDay -= 1
        sD.todayKey = "202611%02d".format(sD.gameDay)
        val shopWin = Jobs.windowFor(sD, shopDef)
        sD.timeMin = shopWin.first + 30
        Jobs.judgeTalk(sD, Jobs.bossFor(sD, shopDef),
            Jobs.workplaceFor(sD, shopDef))
        check(Jobs.currentJob(sD)?.id == "shop",
            "seam: the lifer holds the shop job on dinner day")
        sD.absDay = seamDay
        sD.gameDay += 1
        sD.todayKey = "202611%02d".format(sD.gameDay)
        val inv = Dinners.todaysInvite(sD)!!
        sD.timeMin = 18 * 60
        Dinners.judgeTalk(sD, inv.host)
        inv.members.firstOrNull { it != inv.host }
            ?.let { Dinners.judgeTalk(sD, it) }
        Dinners.lookText(sD, inv.house)
        // the morning after, in Engine's own rollover order
        sD.absDay += 1; sD.gameDay += 1
        sD.todayKey = "202611%02d".format(sD.gameDay)
        Dinners.dailyRollover(sD)
        Jobs.dailyRollover(sD)
        check(Dinners.eveningSpent(sD, seamDay),
            "seam: the evening was spent, and the wrap remembers")
        check(Jobs.excusedYesterday(sD, shopDef, seamDay),
            "seam: a sat evening excuses the shop shift it covered")
        check(!Jobs.excusedYesterday(sD, paperDef, seamDay),
            "seam: the same evening never excuses a morning route")
        check((sD.life["jobMissStreak"] ?: 0) == 0,
            "seam: the rollover charged no miss for the excused shift")
        // the control: same job, hired the same Thursday,
        // same Friday skipped — but no dinner sat
        val sC0 = engS.newState()
        engS.createPlayer(sC0, "Seam", DEFAULT_APPEARANCE)
        sC0.absDay = seamDay - 1
        sC0.gameYear = 2026; sC0.gameMonth = 11
        sC0.gameDay = 5 + (seamDay - 36)
        sC0.todayKey = "202611%02d".format(sC0.gameDay)
        val shopWin0 = Jobs.windowFor(sC0, shopDef)
        sC0.timeMin = shopWin0.first + 30
        Jobs.judgeTalk(sC0, Jobs.bossFor(sC0, shopDef),
            Jobs.workplaceFor(sC0, shopDef))
        sC0.absDay += 2; sC0.gameDay += 2
        sC0.todayKey = "202611%02d".format(sC0.gameDay)
        Dinners.dailyRollover(sC0)
        Jobs.dailyRollover(sC0)
        check(!Jobs.excusedYesterday(sC0, shopDef, seamDay) &&
            (sC0.life["jobMissStreak"] ?: 0) == 1,
            "seam: without the dinner, the same skipped shift " +
                "counts — the excuse is the evening, not the day")

        // ---- votes × finales: the morning report's order ----
        // The count lands in the report BELOW the finale's
        // lines — source first, then live, on the one spring
        // morning where both have something to say (the
        // finale's last day is a Thursday the vote week turns).
        val houseSrc = File(root, "src/com/hunt3r/southparktown/House.kt")
            .readText()
        val reportBody = houseSrc.substring(
            houseSrc.indexOf("fun morningReport"))
        check(reportBody.indexOf("Finales.morningNote") >= 0 &&
            reportBody.indexOf("Votes.morningNote") >
                reportBody.indexOf("Finales.morningNote"),
            "seam: the morning report appends the finale's note " +
                "before the votes note — the count never jumps " +
                "the finale's announcement")
        val sR = engS.newState()
        engS.createPlayer(sR, "Reporter", DEFAULT_APPEARANCE)
        sR.absDay = 239
        sR.gameYear = 2027; sR.gameMonth = 5; sR.gameDay = 28
        sR.todayKey = "20270528"
        Finales.dailyRollover(sR)
        Finales.lookText(sR, Finales.defById("spring")!!.steps[1].loc!!)
        sR.absDay = 240; sR.gameDay = 29; sR.todayKey = "20270529"
        val qR = Votes.currentQuestion(sR)
        Votes.castVote(sR, qR.options[0].id)
        sR.absDay = 242; sR.gameDay = 31; sR.todayKey = "20270531"
        Votes.dailyRollover(sR)
        val finNote = Finales.morningNote(sR)
        val voteNote = Votes.morningNote(sR)
        check(finNote != null && voteNote != null,
            "seam: on the finale's last morning both the finale " +
                "and the count have a line (finale ${finNote != null}, " +
                "votes ${voteNote != null})")
        val report = House.morningReport(sR, emptyList(), emptyMap(),
            0, false, null)
        check(report.indexOf(finNote) >= 0 &&
            report.indexOf(voteNote) > report.indexOf(finNote),
            "seam: the lived report prints the finale's closing " +
                "call above the count — order kept in practice")

        // ---- commissions × chained PHOTO errands ----
        // One shutter, two judges: a frame that lands a held
        // commission must also settle a held PHOTO errand —
        // here a chain's first link — and both books must show
        // it, the print stamped, the next link revealed.
        val sC = engS.newState()
        engS.createPlayer(sC, "Shooter", DEFAULT_APPEARANCE)
        var askC: Commission? = null
        for (w in 0..30) {
            sC.absDay = w * 7
            askC = Commissions.boardOpen(sC)
                .firstOrNull { it.condKind.isEmpty() }
            if (askC != null) break
        }
        check(askC != null,
            "seam: some week's board carries a plain commission")
        val c0 = askC!!
        check(Commissions.accept(sC, c0),
            "seam: the commission takes onto the plate")
        val subjC = c0.subjects.first()
        val link2 = Errand(id = "seam:2", source = Errands.ASK,
            asker = c0.asker, type = "PHOTO", text = "t2", hint = "h",
            targetName = subjC, targetLoc = c0.locId,
            dayKey = sC.todayKey, chainId = "c:seam", chainLink = 2,
            chainLen = 2, chainFrom = c0.asker)
        sC.errands.add(Errand(id = "seam:1", source = Errands.ASK,
            asker = c0.asker, type = "PHOTO", text = "t", hint = "h",
            targetName = subjC, targetLoc = c0.locId,
            dayKey = sC.todayKey, acceptedDay = sC.absDay,
            chainId = "c:seam", chainLink = 1, chainLen = 2,
            chainFrom = c0.asker, chainRest = listOf(link2)))
        val recC = PhotoRecord(
            id = "seam-photo", dayKey = sC.todayKey, dateLabel = "?",
            timeMin = 720, locId = c0.locId,
            inside = CharacterSystem.npcInside(c0.locId),
            weatherId = sC.weatherId, appearance = DEFAULT_APPEARANCE,
            figures = c0.subjects.map { PhotoFigure(it, "cast", "happy") } +
                PhotoFigure("Shooter", "player", "happy"),
            caption = "one shutter, two judges", followersGained = 0,
            seed = 42L, absDay = sC.absDay)
        Photos.applyPhoto(sC, recC)
        check(sC.commissionsDone == 1 && recC.isCommissioned &&
            recC.commissionAsker == c0.asker,
            "seam: the shutter landed the commission and the " +
                "print wears its stamp (done ${sC.commissionsDone})")
        check(sC.errandsDoneCount == 1 &&
            sC.errands.any { it.id == "seam:2" && it.chainLink == 2 },
            "seam: the same shutter settled the chain's first " +
                "link and the second stands revealed (done " +
                "${sC.errandsDoneCount})")

        // ---- the fourth case's dressing × the depth bands ----
        // The fixes the case leaves standing are dressing like
        // any other: background band, claimed exactly once in
        // the whole registry — the enumeration the finisher
        // completed, re-run as this pass's audit.
        check(Mystery4.FIX_TOKENS.isNotEmpty() &&
            Mystery4.FIX_TOKENS.all {
                Depth.tokenBand(it) == Band.BACKGROUND },
            "seam: every overnight-fix token stands in the " +
                "background band — dressing, never a prop in " +
                "front of the cast")
        val registrySets = listOf(
            LOC_SILHOUETTES.values.toSet(),
            LOC_ART_DETAILS.values.flatten().toSet(),
            LOC_SEASON_DETAILS.values.flatten().toSet(),
            LOC_LIGHT_DETAILS.values.flatten().toSet(),
            Mystery3.DIG_TOKENS.toSet(),
            Mystery4.FIX_TOKENS.toSet(),
            FactionMissions.MARK_TOKENS.toSet(),
            Capstones.MARK_TOKENS.toSet(),
            INTERIOR_ART_DETAILS.values.flatten().toSet(),
            INTERIORS.values.flatMap { it.props }.toSet(),
            LOC_FOREGROUND.values.toSet(),
            INTERIOR_FOREGROUND.values.toSet(),
            Fair.FAIR_TOKENS.toSet())
        check(registrySets.sumOf { it.size } == Depth.TOKEN_BANDS.size,
            "seam: the registry enumeration still balances — " +
                "no token double-claimed, none bandless")

        // ---- jobs × the Walk: route deliveries ride Look ----
        // A paper morning leaves the walk ledger exactly as it
        // found it — no carry minutes invented, no trips
        // booked — and every house on the route is a real stop
        // on the town's walking graph.
        val sW = engS.newState()
        engS.createPlayer(sW, "Walker", DEFAULT_APPEARANCE)
        sW.absDay = 4
        sW.gameYear = 2026; sW.gameMonth = 10; sW.gameDay = 5
        sW.todayKey = "20261005"
        sW.walkTrips = 3; sW.walkLegs = 9; sW.walkCarryMin = 14
        sW.walkShortcuts.add("CityHall>MainStreet")
        sW.timeMin = 8 * 60 + 30
        Jobs.judgeTalk(sW, "McDaniels", "CityHall")
        Jobs.judgeTalk(sW, "McDaniels", "CityHall")
        for (t in Jobs.tasksFor(sW, paperDef)) Jobs.lookText(sW, t.target)
        check(Jobs.tasksDone(sW, paperDef) == Jobs.ROUTE_SIZE,
            "seam: the whole route delivered through Look " +
                "(${Jobs.tasksDone(sW, paperDef)}/${Jobs.ROUTE_SIZE})")
        check(sW.walkTrips == 3 && sW.walkLegs == 9 &&
            sW.walkCarryMin == 14 &&
            sW.walkShortcuts == setOf("CityHall>MainStreet"),
            "seam: the walk ledger is untouched by the route — " +
                "deliveries are work, not walking")
        val reachW = mutableSetOf("CityHall")
        val queueW = mutableListOf("CityHall")
        while (queueW.isNotEmpty()) {
            val cur = queueW.removeAt(0)
            for (nxt in EXITS[cur].orEmpty())
                if (reachW.add(nxt)) queueW.add(nxt)
        }
        val routeLocs = Jobs.routeFor(sW.absDay).map { it.first }
        check(routeLocs.size == Jobs.ROUTE_SIZE &&
            routeLocs.all { it in reachW && it in LOCATIONS },
            "seam: every route house stands on the walking " +
                "graph, reachable from the hall ($routeLocs)")
    }

    run {
        // ---------- the peak budget, fifth distance ----------
        // The same pins as v0.4.0e, on today's render set. And
        // the family census: Queue #6 shipped six systems and
        // not one sound — the registries are exactly the sizes
        // the last pass counted, which is what "no new audio
        // family" looks like when it's proven instead of said.
        val pb = SoundGen.PeakBudget
        println("budget v0.6.0g: named ${pb.namedStack()}, " +
            "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
            "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
            "amb ${pb.ambiencePeakOut()}")
        check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
            "budget: the named stack has not drifted since v0.4.0e " +
                "(got ${pb.namedStack()})")
        check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
            "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
        check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
            "budget: the bark stack has not drifted (got ${pb.barkStack()})")
        check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
            pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
            "budget: neither barks nor mood contours out-peak the plain blip")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val post = AudioSettings.DEFAULT.gain(
                AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
                pb.peakOf(SoundGen.renderAmbience(bed))
            check(post <= pb.ambiencePeakOut() + 0.002f,
                "budget: bed $bed stays inside the ambience allocation")
        }
        check(SoundGen.SFX_IDS.size == 21 &&
            SoundGen.BlipFam.values().size == 7 &&
            SoundGen.BlipMood.values().size == 4 &&
            SoundGen.AmbBed.values().size == 6,
            "budget: the audio census is unchanged — 21 named " +
                "effects, 7 blip families, 4 moods, 6 ambience " +
                "beds. Queue #6 added no audio family (got " +
                "${SoundGen.SFX_IDS.size}/${SoundGen.BlipFam.values().size}/" +
                "${SoundGen.BlipMood.values().size}/${SoundGen.AmbBed.values().size})")
    }

    run {
        // ---------- the tuning ledger, swept for Queue #6 ----------
        // Every paper-tuned Queue #6 constant, named in the
        // ledger section itself — scoped to the section, so a
        // dial that only ever made a changelog doesn't count.
        val tuning = File(root, "docs/TUNING.md").readText()
        val ledgerStart = tuning.indexOf("## Tuning ledger")
        val ledgerEnd = tuning.length
        check(ledgerStart >= 0 && ledgerEnd > ledgerStart,
            "ledger: the ledger section stands ahead of the changelog")
        val ledger = tuning.substring(ledgerStart, ledgerEnd)
        val q6Dials = listOf(
            // commissions (v0.6.0a)
            "WEEK_DAYS", "POSTINGS", "MAX_PLATE", "EXPIRY_DAYS",
            "PAY_ONE", "PAY_PAIR", "PAY_GROUP", "COND_BONUS",
            // chained favors (v0.6.0b)
            "CHAIN_CHANCE_BOARD", "CHAIN_CHANCE_ASK", "CHAIN_CHANCE_SHOP",
            "CHAIN_MAX_LINKS", "CHAIN_BONUS_COINS_PER_LINK",
            "CHAIN_BONUS_FRIENDSHIP_PER_LINK",
            // the fourth case (v0.6.0c) — windows and counts
            // only; the case itself stays sealed
            "OPEN_DELAY_DAYS", "CHAPTER_GAP_DAYS", "VIGIL_MIN_CLUES",
            "VIGIL_FROM_MIN", "LAST_FIX_DELAY_DAYS",
            // family evenings (v0.6.0d)
            "DINNER_FROM", "DINNER_TO", "DINNER_WEEKDAYS",
            "HOST_MIN_DECOR", "HOST_MIN_TIER", "HOST_COOLDOWN_DAYS",
            "WELL_SCORE", "THANK_EVERY",
            // town jobs (v0.6.0e)
            "HIRE_STANDING_FLOOR", "MISS_LIMIT", "STEADY_STREAK",
            "STEADY_BONUS", "TRUSTED_STREAK", "TRUSTED_BONUS",
            "ROUTE_SIZE",
            // town votes (v0.6.0f)
            "NO_REPEAT_WEEKS", "OUTCOME_WEEKS", "HISTORY_CAP",
            "CHAMPION_LEAN", "FACTION_LEAN", "SCHOOL_LEAN")
        for (dial in q6Dials) {
            check(ledger.contains(dial),
                "ledger: the tuning ledger names $dial")
        }
    }
}

// ================= v0.7.0c: Bijou movie nights =================
private fun sectionV070c(root: String) {
    println("== v0.7.0c: Bijou movie nights — Friday premieres, Saturday headlines ==")
    val eng = Engine(7003)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        fun fresh(): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "Moviegoer", DEFAULT_APPEARANCE)
            return s
        }
        // Put a state on an absolute day, with the calendar
        // fields that follow from it (day 0 = Thu 2026-10-01).
        fun setDay(s: GameState, day: Int) {
            s.absDay = day
            val key = keyFromOrdinal(ordinalOfKey("20261001") + day)
            s.todayKey = key
            s.gameYear = key.substring(0, 4).toInt()
            s.gameMonth = key.substring(4, 6).toInt()
            s.gameDay = key.substring(6, 8).toInt()
        }
        // Day-of-slot -> the screening day carrying it
        // (slots alternate Fri, Sat from day 1).
        fun dayOfSlot(slot: Int): Int =
            (slot / 2) * 7 + (if (slot % 2 == 0) 1 else 2)

        // ---------- dials & cadence ----------
        check(MovieNights.SCREENING_WEEKDAYS == setOf(5, 6),
            "movies: the cadence is Friday + Saturday (Jobs.weekdayOf)")
        check(MovieNights.DOORS_FROM == 19 * 60 &&
            MovieNights.LAST_SEATING == 20 * 60 &&
            MovieNights.FEATURE_END == 21 * 60 + 30 &&
            MovieNights.GATHER_TO == MovieNights.FEATURE_END,
            "movies: doors 19:00, last seating 20:00, out by 21:30")
        check(MovieNights.FEATURE_END < 22 * 60,
            "movies: the feature ends before the 22:00 sleep march (quiet hours by construction)")
        check(MovieNights.HOUSE_CAP in 8..16,
            "movies: the house cap is a crowd the layout renders cleanly")
        var screenDays = 0
        for (d in 0 until 364) if (MovieNights.isScreeningDay(d)) screenDays++
        check(screenDays == 104,
            "movies: 104 screening days in a 364-day year, got $screenDays")
        check(MovieNights.slotOf(1) == 0 && MovieNights.slotOf(2) == 1 &&
            MovieNights.slotOf(8) == 2 && MovieNights.slotOf(9) == 3,
            "movies: slots index the screening days in order")
        check(MovieNights.nextScreeningDay(0) == 1 &&
            MovieNights.nextScreeningDay(1) == 2 &&
            MovieNights.nextScreeningDay(2) == 8,
            "movies: the next screening is never more than a week out")

        // ---------- the feature rotation ----------
        val feats = (0 until 120).map { MovieNights.generatedFeature(it) }
        for ((i, f) in feats.withIndex()) {
            check(f.stars.size in 2..4 && f.stars.all { it in KID_ORDER },
                "movies: slot $i stars 2-4 of the cast")
            check(f.cards.size == 5 &&
                f.cards.count { it.beat == MovieNights.BEAT_DUD } == 1,
                "movies: slot $i has five cards and exactly one immortal flop")
            check(f.title.isNotBlank() &&
                f.cards.all { it.text.isNotBlank() && "{" !in it.text },
                "movies: slot $i — every card filled, no placeholders left")
            check(f.cards[0].text.contains(f.stars[0]),
                "movies: slot $i opens on its star")
            check(MovieNights.generatedFeature(i) == f,
                "movies: slot $i is a pure function of the slot")
            for (j in maxOf(0, i - MovieNights.NO_REPEAT_SLOTS) until i) {
                check(feats[j].identity() != f.identity(),
                    "movies: no identity repeats within ${MovieNights.NO_REPEAT_SLOTS} slots ($j vs $i)")
            }
            // spoiler hygiene: the banks tell no case's secret.
            // The terms are content words, not cast names — a
            // feature may star anyone in town; what it may
            // never do is say how any case comes out.
            val allText = (f.title + f.cards.joinToString(" ") { it.text })
                .lowercase()
            check("sleepwalk" !in allText && "strongbox" !in allText &&
                "deed" !in allText && "reel" !in allText,
                "movies: slot $i carries no case's secret")
            // the title is the one piece of a feature that can
            // travel (a phone text carries it): it must stay
            // clear of the phone banks' own denylist too
            val titleLow = f.title.lowercase()
            check(listOf("sleepwalk", "foil", "confiscat", "cameo",
                "strongbox", "communal", "dissolv", "redact",
                "owes you", "professor chaos", "alibi", "charter",
                "lease").none { it in titleLow },
                "movies: slot $i's title is phone-safe")
        }

        // ---------- reaction scoring: the truth table ----------
        val table = mapOf(
            MovieNights.BEAT_COMEDY to mapOf("laugh" to 2, "applaud" to 1,
                "gasp" to 0, "heckle" to -1),
            MovieNights.BEAT_SCARE to mapOf("gasp" to 2, "laugh" to 1,
                "applaud" to 0, "heckle" to -1),
            MovieNights.BEAT_HEART to mapOf("applaud" to 2, "gasp" to 1,
                "laugh" to 0, "heckle" to -1),
            MovieNights.BEAT_SPECTACLE to mapOf("gasp" to 2, "applaud" to 1,
                "laugh" to 0, "heckle" to -1),
            MovieNights.BEAT_DUD to mapOf("heckle" to 2, "laugh" to 1,
                "gasp" to 0, "applaud" to 0))
        for ((beat, wants) in table) {
            for ((rid, want) in wants) {
                check(MovieNights.scoreFor(beat, rid) == want,
                    "movies: score $beat/$rid == $want")
            }
        }
        check(MovieNights.tierFor(-3) == MovieNights.TIER_DEAD &&
            MovieNights.tierFor(1) == MovieNights.TIER_DEAD &&
            MovieNights.tierFor(2) == MovieNights.TIER_POLITE &&
            MovieNights.tierFor(3) == MovieNights.TIER_POLITE &&
            MovieNights.tierFor(4) == MovieNights.TIER_BUZZING &&
            MovieNights.tierFor(5) == MovieNights.TIER_BUZZING &&
            MovieNights.tierFor(6) == MovieNights.TIER_LEGENDARY,
            "movies: buzz tiers break at 2 / 4 / 6")
        check(MovieNights.starPay(MovieNights.TIER_DEAD) == 0 &&
            MovieNights.starPay(MovieNights.TIER_POLITE) == 1 &&
            MovieNights.starPay(MovieNights.TIER_BUZZING) == 2 &&
            MovieNights.starPay(MovieNights.TIER_LEGENDARY) == 4,
            "movies: the stars are paid 0 / 1 / 2 / 4 by the house")

        // ---------- attendance: authored, deterministic ----------
        run {
            val s = fresh(); setDay(s, 1)
            val a1 = MovieNights.attendance(s)
            check(a1 == MovieNights.attendance(s),
                "movies: attendance is deterministic in the state")
            val f = MovieNights.featureFor(s)
            check(a1.containsAll(f.stars) && a1.size in f.stars.size..MovieNights.HOUSE_CAP,
                "movies: the stars always come; the house caps at ${MovieNights.HOUSE_CAP}")
            check(MovieNights.NEVER_ATTENDS.none { it in a1 },
                "movies: the never-come never come (Towelie, Crabtree)")
            check(MovieNights.gatheringBlock(s, a1.first(), 12 * 60) == null &&
                MovieNights.gatheringBlock(s, a1.first(),
                    MovieNights.DOORS_FROM + 30)?.location == "Bijou",
                "movies: the house gathers at the Bijou only in the window")
            // a close friend of a star makes the trip
            val outsider = KID_ORDER.first {
                it !in a1 && it !in MovieNights.NEVER_ATTENDS && it !in f.stars }
            s.npcBonds[Threads.pairKey(outsider, f.stars[0])] = 40
            check(outsider in MovieNights.attendance(s),
                "movies: a star's close friend (bond) is drawn to the house")
            check(MovieNights.drawOf(s, outsider, f.stars,
                MovieNights.slotOf(1)) > 0,
                "movies: draw reads the same chemistry the photos do")
        }
        run {
            // a star's arch-rival comes to heckle: find a real
            // rival pair in the relation data, then a Friday
            // feature one of them stars in
            var pinnedSlot = -1
            var rivalName = ""
            for (slot in 0 until 60 step 2) {
                val f = MovieNights.generatedFeature(slot)
                var foundRival: String? = null
                for (star in f.stars) {
                    foundRival = KID_ORDER.firstOrNull {
                        it !in f.stars &&
                            relationNote(it, star) == "arch-rivals" }
                    if (foundRival != null) break
                }
                if (foundRival != null) {
                    pinnedSlot = slot; rivalName = foundRival; break
                }
            }
            check(pinnedSlot >= 0,
                "movies: some rotation feature stars someone with an arch-rival")
            if (pinnedSlot >= 0) {
                val s = fresh(); setDay(s, dayOfSlot(pinnedSlot))
                check(MovieNights.featureFor(s) ==
                    MovieNights.generatedFeature(pinnedSlot),
                    "movies: a Friday's feature is the rotation's (slot $pinnedSlot)")
                check(rivalName in MovieNights.attendance(s),
                    "movies: the arch-rival ($rivalName) attends to heckle")
            }
        }

        // ---------- the vote headlines Saturday ----------
        run {
            val s = fresh(); setDay(s, 2)   // Saturday
            val q = Votes.questionById("bijou_matinee")!!
            s.lifeText["voteStand:${q.id}"] = "pancakes"
            s.life["voteStandDay:${q.id}"] = 0
            val hf = MovieNights.featureFor(s)
            check(hf.headline && hf.title == "The Last Pancake" &&
                hf.genreId == MovieNights.HEADLINE_GENRES["pancakes"],
                "movies: Saturday headlines the town's standing matinee pick")
            check(MovieNights.featureFor(s) == hf,
                "movies: the headline feature is deterministic too")
            check(!MovieNights.featureForDay(s, 1).headline,
                "movies: Friday is the rotation's, vote or no vote")
            val bare = fresh(); setDay(bare, 2)
            check(!MovieNights.featureFor(bare).headline,
                "movies: a Saturday with no standing pick runs the rotation")
        }

        // ---------- deference: the marquee goes dark ----------
        run {
            // a season-finale evening (Fri May 28 2027 is in
            // the spring finale's window)
            val s = fresh()
            val finaleDay = ordinalOfKey("20270528") - ordinalOfKey("20261001")
            setDay(s, finaleDay)
            check(MovieNights.isScreeningDay(s.absDay),
                "movies: the finale pin lands on a screening day")
            check(MovieNights.darkReason(s) == MovieNights.DARK_FINALE,
                "movies: a finale evening darkens the marquee")
            check(MovieNights.sessionStatus(s).kind == MovieNights.ST_DARK &&
                !MovieNights.seat(s),
                "movies: no seating on a finale evening")
            check(MovieNights.gatheringBlock(s, "Stan",
                MovieNights.DOORS_FROM + 30) == null,
                "movies: a dark house gathers nobody")
            // ... and the cadence simply resumes after the
            // window: every screening inside it is dark, the
            // first one past it is lit again
            val next = fresh()
            var resumedDay = -1
            for (d in s.absDay + 1..s.absDay + 14) {
                if (!MovieNights.isScreeningDay(d)) continue
                setDay(next, d)
                if (MovieNights.darkReason(next) == null) {
                    resumedDay = d; break
                }
            }
            check(resumedDay > s.absDay,
                "movies: the cadence resumes after the finale window")
            if (resumedDay > 0) {
                next.timeMin = MovieNights.DOORS_FROM + 15
                check(MovieNights.sessionStatus(next).kind ==
                    MovieNights.ST_SEATING,
                    "movies: the resumed night seats as usual")
            }
        }
        run {
            // a holiday with its own beat (Sat Oct 31 2026)
            val s = fresh(); setDay(s, 30)
            check(Jobs.weekdayOf(30) == 6,
                "movies: the holiday pin lands on a Saturday")
            s.holidayId = "halloween"
            check(MovieNights.darkReason(s) == MovieNights.DARK_HOLIDAY,
                "movies: a holiday beat darkens the marquee")
            check(MovieNights.darkLine(s)?.contains("Halloween") == true,
                "movies: the dark line names the reason honestly")
        }
        run {
            // the booth case's own nights at this theater
            val s = fresh(); setDay(s, 1)
            s.shenaniganId = Mystery2.MARATHON_ID
            check(MovieNights.darkReason(s) == MovieNights.DARK_CASE,
                "movies: the marathon night books the Bijou outright")
            val s2 = fresh(); setDay(s2, 1)
            s2.shenaniganId = Mystery2.ACCUSATION_ID
            check(MovieNights.darkReason(s2) == MovieNights.DARK_CASE,
                "movies: the accusation night books the Bijou outright")
            // any case's climax, judged at doors: case 1's
            // finale, fully fabricated
            val s3 = fresh(); setDay(s3, 1)
            s3.shenaniganId = Mystery.FINALE_ID
            s3.mysteryClues.addAll(Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES)
                .map { it.id })
            check(Mystery.finaleChoiceDue(
                s3.copy(timeMin = MovieNights.DOORS_FROM)),
                "movies: the fabricated climax is genuinely due at doors")
            check(MovieNights.darkReason(s3) == MovieNights.DARK_CASE,
                "movies: a due climax darkens the marquee, whatever the case")
        }

        // ---------- the full session: a perfect house ----------
        run {
            val s = fresh(); setDay(s, 1)
            s.timeMin = 12 * 60
            check(MovieNights.sessionStatus(s).kind == MovieNights.ST_BEFORE,
                "movies: before doors, the feature is announced, not seatable")
            check(!MovieNights.seat(s), "movies: no seating before doors")
            s.timeMin = MovieNights.DOORS_FROM + 15
            check(MovieNights.sessionStatus(s).kind == MovieNights.ST_SEATING,
                "movies: doors open onto the seating offer")
            val coinsBefore = s.inventory[Minigames.COIN_ITEM] ?: 0
            check(MovieNights.seat(s), "movies: the seat is taken")
            check((s.inventory[Minigames.COIN_ITEM] ?: 0) == coinsBefore,
                "movies: admission is free — the town already paid for the print")
            var prompts = 0; var beats = 0
            var sawCredits = false
            while (beats < 40) {
                val beat = MovieNights.sessionBeat(s) ?: break
                beats++
                when (beat.kind) {
                    "prompt" -> {
                        prompts++
                        val card = MovieNights.featureFor(s)
                            .cards[beat.cardIndex]
                        val res = MovieNights.react(s,
                            MovieNights.rightFor(card.beat))
                        check(res != null && res.contains("+2"),
                            "movies: the right reaction pays +2")
                    }
                    "credits" -> {
                        sawCredits = true
                        check(beat.text.contains("LEGENDARY"),
                            "movies: a perfect card rolls legendary credits")
                        MovieNights.advance(s)
                    }
                    else -> MovieNights.advance(s)
                }
            }
            check(prompts == 3 && sawCredits,
                "movies: three prompts, then the credits ($prompts)")
            val f = MovieNights.featureFor(s)
            val rec = MovieNights.recordFor(s, 1)
            check(rec != null && rec.tier == MovieNights.TIER_LEGENDARY &&
                rec.buzz == 6 && rec.title == f.title,
                "movies: the night is recorded at its buzz")
            check(MovieNights.attendedCount(s) == 1 &&
                MovieNights.bestBuzz(s) == 6 && MovieNights.featDone(s),
                "movies: the feat lands with the legendary house")
            for (star in f.stars) {
                check((s.friendship[star] ?: 0) == MovieNights.PAY_LEGENDARY,
                    "movies: $star takes the legendary pay (+4)")
                check(MovieNights.TOPIC in
                    NpcMemoryStore.getOrCreate(star).topics,
                    "movies: $star carries the movie-night thread into tomorrow")
            }
            check(s.events.any { it.startsWith("🎬") } &&
                s.townLog.any { it.contains("🎬") },
                "movies: the ticker and the town log carry the night")
            check(MovieNights.sessionStatus(s).kind == MovieNights.ST_DONE &&
                !MovieNights.seat(s),
                "movies: one feature a night, and it's seen")
            // the save round-trip carries the night
            val back = decodeGameState(encodeGameState(s))
            check(MovieNights.recordFor(back, 1)?.tier ==
                MovieNights.TIER_LEGENDARY &&
                MovieNights.attendedCount(back) == 1 &&
                MovieNights.history(back).size == 1,
                "movies: the record survives the save round-trip")
        }

        // ---------- a whiffed house, and the rollover settle ----------
        run {
            val s = fresh(); setDay(s, 8)   // the next Friday
            s.timeMin = MovieNights.DOORS_FROM + 30
            check(MovieNights.seat(s), "movies: seated for the whiff card")
            var guard = 0
            while (guard++ < 40) {
                val beat = MovieNights.sessionBeat(s) ?: break
                if (beat.kind == "prompt") {
                    val card = MovieNights.featureFor(s).cards[beat.cardIndex]
                    // gasp at the comedy, laugh at the heart…
                    val wrong = listOf("laugh", "gasp", "applaud")
                        .first { it != MovieNights.rightFor(card.beat) &&
                            it != MovieNights.closeFor(card.beat) &&
                            it != "heckle" }
                    MovieNights.react(s, wrong)
                } else if (beat.kind == "credits") break
                else MovieNights.advance(s)
            }
            val f = MovieNights.featureFor(s)
            check(MovieNights.buzzNow(s) == 0,
                "movies: three whiffs hold the buzz at 0")
            // leave before the credits: midnight settles it
            setDay(s, 9)
            MovieNights.dailyRollover(s)
            val rec = MovieNights.recordFor(s, 8)
            check(rec != null && rec.tier == MovieNights.TIER_DEAD &&
                rec.buzz == 0,
                "movies: an abandoned session settles at its buzz, dead house")
            check(MovieNights.attendedCount(s) == 1,
                "movies: the settle counts the attendance")
            check(f.stars.all { (s.friendship[it] ?: 0) == 0 },
                "movies: no credits, no star pay — the bow never happened")
            check(s.life["movieSeat:8"] == null &&
                s.lifeText["movieFeat:8"] == null,
                "movies: the settled day's session keys are pruned")
        }

        // ---------- audience lines: only from the room ----------
        run {
            val s = fresh(); setDay(s, 1)
            s.timeMin = MovieNights.DOORS_FROM + 30
            val f = MovieNights.featureFor(s)
            // park the whole town elsewhere: the room holds
            // exactly who this test puts in it
            s.agents.values.forEach {
                if (!it.isPlayer) {
                    it.location = "Raisins"; it.waypoints.clear()
                }
            }
            val me = s.agents.values.first { it.isPlayer }
            me.location = "Bijou"; s.playerInside = true
            val fallback = MovieNights.reactionLine(s, f, 0)
            check(KID_ORDER.none { fallback.contains(it) },
                "movies: an empty house answers namelessly")
            val guest = f.stars.first()
            s.agents[guest]?.let {
                it.location = "Bijou"; it.waypoints.clear(); it.asleep = false
            }
            val line = MovieNights.reactionLine(s, f, 1)
            check(line.contains(guest),
                "movies: the reaction names who's actually in the room")
            check(KID_ORDER.filter { it != guest }
                .none { line.contains(it) },
                "movies: no absent name is ever put in the room")
            check(MovieNights.presentCast(s) == listOf(guest),
                "movies: presence reads real placement, like the secrets' witnesses")
        }

        // ---------- announcements: report, marquee, phone ----------
        run {
            val a = fresh(); setDay(a, 1)
            val b = fresh(); setDay(b, 1)
            check(MovieNights.morningNote(a) != null &&
                MovieNights.morningNote(a) == MovieNights.morningNote(b),
                "movies: the morning announcement is deterministic")
            check(MovieNights.morningNote(a)!!.contains("🎬") &&
                MovieNights.morningNote(a)!!.contains(
                    MovieNights.featureFor(a).title),
                "movies: the report names tonight's feature")
            val sun = fresh(); setDay(sun, 3)
            check(MovieNights.morningNote(sun) == null &&
                MovieNights.textSender(sun) == null,
                "movies: no announcement, no text, on an off day")
            check(MovieNights.textSender(a) ==
                MovieNights.featureFor(a).stars[0],
                "movies: tonight's first star is the morning texter")
            check(MovieNights.lookText(a, "Pond") == null &&
                MovieNights.lookText(a, "Bijou")?.contains("🎬") == true,
                "movies: the marquee speaks only at the Bijou")
            val dark = fresh(); setDay(dark, 1)
            dark.shenaniganId = Mystery2.MARATHON_ID
            check(MovieNights.lookText(dark, "Bijou") ==
                MovieNights.darkLine(dark) &&
                MovieNights.morningNote(dark) ==
                    MovieNights.darkLine(dark),
                "movies: dark nights read the same on marquee and report")
            // the phone: one star texts the show by breakfast
            val p = fresh(); setDay(p, 1); p.timeMin = 7 * 60
            Phone.dailyRollover(p)
            val star = MovieNights.featureFor(p).stars[0]
            check(p.phoneTexts.any {
                it.trigger == Phone.MOVIE && it.sender == star &&
                    it.text.isNotBlank() },
                "movies: the star's text lands in the morning harvest")
            check(Phone.MOVIE in Phone.TRIGGERS,
                "movies: the phone knows the movie trigger")
            // the Journal page, before and after a first night
            val page = MovieNights.pageLines(sun)
            check(page.first().contains("0 screenings") &&
                page.any { it.contains("admission is free") },
                "movies: the page opens honest for a newcomer")
        }

        // ---------- caps over a season of screenings ----------
        run {
            val s = fresh()
            var attended = 0
            for (day in 1..140) {
                if (!MovieNights.isScreeningDay(day)) continue
                setDay(s, day)
                if (MovieNights.isDarkTonight(s)) continue
                s.timeMin = MovieNights.DOORS_FROM + 10
                if (!MovieNights.seat(s)) continue
                var guard = 0
                while (guard++ < 40) {
                    val beat = MovieNights.sessionBeat(s) ?: break
                    when (beat.kind) {
                        "prompt" -> {
                            val card = MovieNights.featureFor(s)
                                .cards[beat.cardIndex]
                            MovieNights.react(s,
                                MovieNights.closeFor(card.beat))
                        }
                        else -> MovieNights.advance(s)
                    }
                }
                attended++
            }
            check(attended >= 20,
                "movies: the season really attended ($attended screenings)")
            check(MovieNights.attendedCount(s) == attended,
                "movies: the counter keeps every night")
            check(MovieNights.history(s).size == MovieNights.HISTORY_CAP,
                "movies: the Journal history holds its cap (${MovieNights.HISTORY_CAP})")
            check(MovieNights.history(s).all { it.tier == MovieNights.TIER_POLITE },
                "movies: an all-close card is a season of polite houses (buzz 3)")
            check(MovieNights.history(s).map { it.day }.distinct().size ==
                MovieNights.HISTORY_CAP,
                "movies: no night is recorded twice")
            val size = Json.stringify(encodeGameState(s)).length
            check(size < 512 * 1024,
                "movies: a season of movie nights keeps the save lean ($size chars)")
        }

        // ---------- a v0.7.0b save loads never having attended ----------
        run {
            val old = decodeGameState(emptyMap())
            check(MovieNights.attendedCount(old) == 0 &&
                MovieNights.history(old).isEmpty() &&
                !MovieNights.featDone(old) &&
                MovieNights.bestBuzz(old) == null,
                "movies: an old save has simply never been to the pictures")
            check(MovieNights.pageLines(old).isNotEmpty() &&
                MovieNights.sessionStatus(old).text.isNotBlank(),
                "movies: the old save's Bijou still answers")
        }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

// ================= v0.7.0d: school days =================

private fun sectionV070d(root: String) {
    println("== v0.7.0d: school days — lessons, recess, and the Friday bee ==")
    val eng = Engine(7004)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        fun fresh(): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
            return s
        }
        // Put a state on an absolute day, with the calendar
        // fields that follow from it (day 0 = Thu 2026-10-01).
        fun setDay(s: GameState, day: Int) {
            s.absDay = day
            val key = keyFromOrdinal(ordinalOfKey("20261001") + day)
            s.todayKey = key
            s.gameYear = key.substring(0, 4).toInt()
            s.gameMonth = key.substring(4, 6).toInt()
            s.gameDay = key.substring(6, 8).toInt()
        }
        // Put named cast in the classroom with the player, so
        // presence reads exactly as a real class hour reads.
        // v0.15.0g staging: the cast spawns at HOME now
        // (CastHomes) and most kids' home IS the school —
        // so the rest of the class is sent to the park
        // explicitly, or "the room" would read the whole
        // class standing in it (the truth the staging
        // below means to control, stated out loud).
        fun stage(s: GameState, vararg names: String) {
            s.playerInside = true
            for ((n, a) in s.agents) {
                if (!a.isPlayer && n in CharacterSystem.CAST_KIDS &&
                    n !in names && a.location == "Elementary") {
                    a.location = "KidsPark"
                    a.destination = "KidsPark"
                    a.waypoints.clear()
                }
            }
            for (n in names) {
                val a = s.agents[n]!!
                a.location = "Elementary"
                a.destination = "Elementary"
                a.waypoints.clear()
                a.asleep = false
            }
        }
        // Drive an open lesson to its record. False on any
        // gate refusal along the way.
        fun sitLesson(s: GameState, choice: String): Boolean {
            if (!School.startLesson(s)) return false
            var guard = 0
            while (guard++ < 12) {
                val beat = School.lessonBeat(s) ?: break
                when (beat.kind) {
                    "prompt" -> if (!School.answerLesson(s, choice))
                        return false
                    else -> School.advanceLesson(s)
                }
            }
            return School.recordFor(s, s.absDay) != null &&
                School.lessonBeat(s) == null
        }
        // Drive an entered bee to its record: perfect spelling
        // (pick the word's next letter) or a first-letter miss.
        fun playBee(s: GameState, perfect: Boolean): Boolean {
            if (!School.enterBee(s)) return false
            var guard = 0
            while (guard++ < 400) {
                val beat = School.beeBeat(s) ?: break
                when (beat.kind) {
                    "letter" -> {
                        val word = School.currentWord(s)
                        val idx = School.spellingProgress(s)
                            .split(" ").count { it != "_" }
                        val want = if (perfect) word[idx]
                        else School.letterOptions(s)
                            .first { it != word[idx] }
                        School.pickLetter(s, want)
                    }
                    "done" -> { School.advanceBee(s); break }
                    else -> School.advanceBee(s)
                }
            }
            // (the record is the completion signal: a finished
            // bee keeps answering with its done beat until the
            // chair is cleared, exactly as the fixture reads it)
            return School.beeRecordFor(s, s.absDay) != null
        }

        // ---------- dials & cadence ----------
        check(School.SCHOOL_WEEKDAYS == setOf(1, 2, 3, 4, 5),
            "school: school days are Monday–Friday (Jobs.weekdayOf)")
        check(School.CLASS_FROM == 9 * 60 && School.CLASS_TO == 15 * 60 &&
            School.RECESS_FROM == 12 * 60 && School.RECESS_TO == 13 * 60,
            "school: class 9–3, recess at the midday block")
        check(School.BEE_WEEKDAY == 5 && School.BEE_FROM == 13 * 60 &&
            School.BEE_TO == 15 * 60 && School.BEE_TO <= School.CLASS_TO,
            "school: the bee is Friday 1–3, inside the school day")
        check(School.isSchoolDay(0) && School.isSchoolDay(1) &&
            !School.isSchoolDay(3) && School.isSchoolDay(4) &&
            School.isSchoolDay(5) && !School.isSchoolDay(9),
            "school: day 0 Thu in, day 3 Sun out, day 4 Mon in")
        var schoolDays = 0
        for (d in 0 until 364) if (School.isSchoolDay(d)) schoolDays++
        check(schoolDays == 260,
            "school: 260 school days in a 364-day year, got $schoolDays")
        check(School.teacherFor(5) == "Garrison" &&
            School.teacherFor(6) == "Victoria" &&
            School.teacherFor(12) == "Garrison" &&
            School.teacherFor(13) == "Victoria",
            "school: Victoria covers Wednesdays; Garrison the rest")
        check(School.isBeeDay(1) && !School.isBeeDay(4) &&
            School.nextBeeDay(2) == 8 && School.nextBeeDay(8) == 8,
            "school: bee day is Friday; the next is never far")

        // ---------- the topic bank & rotation ----------
        check(School.TOPICS.size >= 12,
            "school: the topic bank holds at least a dozen topics")
        check(School.TOPICS.map { it.id }.distinct().size ==
            School.TOPICS.size,
            "school: topic ids are unique")
        check(School.TOPICS.all {
            it.open.isNotBlank() && it.develop.isNotBlank() &&
                it.question.isNotBlank() && it.rightLabel.isNotBlank() &&
                it.rightOutcome.isNotBlank() &&
                it.funnyLabel.isNotBlank() &&
                it.funnyOutcome.isNotBlank() &&
                it.passOutcome.isNotBlank() },
            "school: every topic carries both beats, the question, " +
                "and all three kindly outcomes")
        run {
            // determinism + rotation over a school year
            val seen = mutableSetOf<String>()
            var prev = ""
            var repeatTooSoon = false
            val recent = ArrayDeque<String>()
            var d = 0
            while (d < 364) {
                if (School.isSchoolDay(d)) {
                    val t = School.topicFor(d)
                    check(t == School.topicFor(d),
                        "school: day $d's topic is deterministic")
                    if (t.id == prev) repeatTooSoon = true
                    if (t.id in recent) repeatTooSoon = true
                    prev = t.id
                    recent.addLast(t.id)
                    if (recent.size > 10) recent.removeFirst()
                    seen += t.id
                }
                d++
            }
            check(!repeatTooSoon,
                "school: no topic repeats back-to-back or inside " +
                    "two school weeks")
            check(seen.size == School.TOPICS.size,
                "school: the whole bank teaches across a year " +
                    "(${seen.size}/${School.TOPICS.size})")
        }

        // ---------- lesson gating ----------
        run {
            val s = fresh(); setDay(s, 3)   // Sunday
            check(School.lessonStatus(s).kind == School.LS_NOT_SCHOOL_DAY &&
                !School.startLesson(s),
                "school: no lesson on a Sunday")
            setDay(s, 4)                    // Monday
            s.timeMin = 8 * 60
            check(School.lessonStatus(s).kind == School.LS_BEFORE &&
                !School.startLesson(s),
                "school: no lesson before first bell")
            s.timeMin = 12 * 60 + 30
            check(School.lessonStatus(s).kind == School.LS_RECESS &&
                !School.startLesson(s),
                "school: no lesson during recess — the yard has the hour")
            s.timeMin = 15 * 60 + 30
            check(School.lessonStatus(s).kind == School.LS_AFTER &&
                !School.startLesson(s),
                "school: no lesson after last bell")
            s.timeMin = 9 * 60 + 30
            stage(s, "Stan", "Kyle")
            check(School.lessonStatus(s).kind == School.LS_AVAILABLE,
                "school: the lesson is up in class hours")
            check(!School.answerLesson(s, "right"),
                "school: no participation before the seat is taken")
        }

        // ---------- a full lesson, right answer ----------
        run {
            val s = fresh(); setDay(s, 4)   // Monday, Garrison
            s.timeMin = 9 * 60 + 30
            stage(s, "Craig", "Tweek", "Jimmy", "Butters", "Stan")
            val topic = School.topicFor(4)
            check(School.startLesson(s), "school: the seat is taken")
            val b0 = School.lessonBeat(s)
            check(b0 != null && b0.kind == "text" &&
                b0.speaker == "Garrison" &&
                b0.text.contains(topic.open.take(24)),
                "school: beat one is the teacher's open")
            School.advanceLesson(s)
            val b1 = School.lessonBeat(s)
            check(b1 != null && b1.text.contains(topic.develop.take(24)),
                "school: beat two develops the lesson")
            val stagedNames = listOf("Craig", "Tweek", "Jimmy",
                "Butters", "Stan")
            val absentNames = listOf("Wendy", "Kyle", "Kenny",
                "Cartman", "Clyde", "Tolkien", "Bebe", "Heidi",
                "Red", "Karen", "Scott")
            check(b1 != null &&
                stagedNames.any { b1.text.contains(it) } &&
                absentNames.none { b1.text.contains(it) },
                "school: the room reacts in character — naming " +
                    "only kids actually in it")
            School.advanceLesson(s)
            val b2 = School.lessonBeat(s)
            check(b2 != null && b2.kind == "prompt" &&
                b2.text.contains(topic.question.take(24)),
                "school: beat three is the participation moment")
            val opts = School.lessonOptions(s)
            check(opts.map { it.first }.sorted() ==
                listOf("funny", "pass", "right"),
                "school: the row is right-ish / funny / pass, exactly")
            check(!School.answerLesson(s, "bogus"),
                "school: a made-up answer is no answer")
            val craigBefore = s.friendship["Craig"] ?: 0
            val garBefore = s.friendship["Garrison"] ?: 0
            check(School.answerLesson(s, "right"),
                "school: the right-ish answer is judged")
            check((s.friendship["Craig"] ?: 0) ==
                craigBefore + School.LESSON_PAY,
                "school: a classmate in the room takes the sprinkle")
            check((s.friendship["Wendy"] ?: 0) == 0,
                "school: a classmate NOT in the room takes nothing")
            check((s.friendship["Garrison"] ?: 0) ==
                garBefore + School.TEACHER_PAY,
                "school: the teacher's own bump for the right answer")
            check(School.TOPIC in
                NpcMemoryStore.getOrCreate("Craig").topics ||
                School.TOPIC in
                NpcMemoryStore.getOrCreate("Tweek").topics ||
                School.TOPIC in
                NpcMemoryStore.getOrCreate("Jimmy").topics,
                "school: the room carries the school thread home")
            val b3 = School.lessonBeat(s)
            check(b3 != null && b3.kind == "outcome" &&
                b3.text == topic.rightOutcome,
                "school: the outcome beat is the right answer's own")
            School.advanceLesson(s)
            check(School.lessonsSat(s) == 1 &&
                School.recordFor(s, 4)?.topicId == topic.id &&
                School.recordFor(s, 4)?.choice == "right",
                "school: the lesson is recorded at its wrap")
            check(School.lessonStatus(s).kind == School.LS_DONE &&
                !School.startLesson(s),
                "school: one lesson per school day, max")
            check(s.events.any { it.startsWith("🎓") } &&
                s.townLog.any { it.contains("🎓") },
                "school: the ticker and the town log carry the lesson")
        }

        // ---------- the funny answer, and the safe pass ----------
        run {
            val s = fresh(); setDay(s, 5)   // Tuesday
            s.timeMin = 10 * 60
            stage(s, "Stan", "Kyle", "Butters")
            val topic = School.topicFor(5)
            check(sitLesson(s, "funny"), "school: the funny lesson sits")
            check(School.recordFor(s, 5)?.choice == "funny" &&
                (s.friendship["Stan"] ?: 0) == School.LESSON_PAY &&
                (s.friendship["Garrison"] ?: 0) == 0,
                "school: funny pays the room, not the teacher — " +
                    "and loses nobody anything")
            val s2 = fresh(); setDay(s2, 5)
            s2.timeMin = 10 * 60
            stage(s2, "Stan", "Kyle", "Butters")
            check(sitLesson(s2, "pass"), "school: the pass lesson sits")
            check(School.recordFor(s2, 5)?.choice == "pass" &&
                (s2.friendship["Stan"] ?: 0) == School.LESSON_PAY,
                "school: passing is always safe — the sprinkle " +
                    "still lands")
            check(topic.passOutcome.isNotBlank() &&
                School.choiceMark("pass") == "✋" &&
                School.choiceMark("right") == "✓" &&
                School.choiceMark("funny") == "🎭",
                "school: the Journal's marks read the choices kindly")
        }

        // ---------- presence truthfulness ----------
        run {
            val s = fresh(); setDay(s, 4)
            s.timeMin = 10 * 60
            stage(s, "Butters", "Stan")
            val lines = School.reactionLines(s)
            check(lines.isNotEmpty(),
                "school: a staffed room reacts")
            val sigNames = listOf("Craig", "Tweek", "Jimmy",
                "Cartman", "Wendy", "Kyle", "Kenny", "Clyde",
                "Tolkien", "Bebe", "Heidi", "Red", "Karen")
            check(lines.none { l -> sigNames.any { l.contains(it) } },
                "school: no reaction names a kid who isn't there")
            val empty = fresh(); setDay(empty, 4)
            empty.timeMin = 10 * 60
            check(School.reactionLines(empty).isEmpty() &&
                School.presentKids(empty).isEmpty(),
                "school: an empty room says nothing at all")
            check(School.presentKids(s) == listOf("Butters", "Stan"),
                "school: presence reads the room, sorted and true")
        }

        // ---------- Victoria's Wednesday ----------
        run {
            val s = fresh(); setDay(s, 6)   // Wednesday
            s.timeMin = 9 * 60 + 15
            stage(s, "Wendy", "Kyle", "Stan")
            check(School.startLesson(s), "school: Wednesday seats")
            val b0 = School.lessonBeat(s)
            check(b0 != null && b0.speaker == "Victoria",
                "school: the principal teaches her named day")
            var guard = 0
            while (guard++ < 12) {
                val b = School.lessonBeat(s) ?: break
                if (b.kind == "prompt") School.answerLesson(s, "right")
                else School.advanceLesson(s)
            }
            check((s.friendship["Victoria"] ?: 0) == School.TEACHER_PAY,
                "school: the covering teacher takes the teacher's bump")
        }

        // ---------- deference: the classroom's quiet days ----------
        run {
            // a holiday with its own beat owns the day
            val s = fresh(); setDay(s, 4)
            s.holidayId = "halloween"
            s.timeMin = 10 * 60
            stage(s, "Stan", "Kyle")
            check(School.quietReason(s) == School.QUIET_HOLIDAY &&
                School.lessonStatus(s).kind == School.LS_QUIET &&
                !School.startLesson(s),
                "school: a holiday beat makes a quiet day")
            check(School.recessStatus(s).kind == School.RS_QUIET,
                "school: recess defers to the holiday too")
            // a due case climax owns it harder (fabricated the
            // way the Bijou's pins fabricate theirs)
            val c = fresh(); setDay(c, 4)
            c.shenaniganId = Mystery.FINALE_ID
            c.mysteryClues.addAll(Mystery.CLUES
                .take(Mystery.TRUTH_MIN_CLUES).map { it.id })
            c.timeMin = 10 * 60
            stage(c, "Stan", "Kyle")
            check(School.anyClimaxDueToday(c) &&
                School.quietReason(c) == School.QUIET_CASE &&
                !School.startLesson(c),
                "school: a due case climax makes a quiet day")
            check(School.quietLine(c)?.startsWith("🎓") == true,
                "school: the quiet day says so honestly")
            // a finale week owns its days
            val finaleDay = ordinalOfKey("20270528") -
                ordinalOfKey("20261001")
            var pinned = false
            for (d in finaleDay - 7..finaleDay + 7) {
                if (!School.isSchoolDay(d)) continue
                val f = fresh(); setDay(f, d)
                if (Finales.windowAt(f) != null) {
                    f.timeMin = 10 * 60
                    stage(f, "Stan", "Kyle")
                    check(School.quietReason(f) == School.QUIET_FINALE &&
                        !School.startLesson(f),
                        "school: finale week makes quiet days (day $d)")
                    pinned = true
                    break
                }
            }
            check(pinned, "school: the finale pin found its weekday")
            // and the bee defers on a quiet Friday
            val q = fresh(); setDay(q, 1)   // Friday
            q.holidayId = "halloween"
            q.timeMin = 13 * 60 + 30
            check(School.beeStatus(q) == School.BS_QUIET &&
                !School.enterBee(q),
                "school: the bee defers to a quiet Friday")
        }

        // ---------- recess ----------
        run {
            val s = fresh(); setDay(s, 4)   // Monday
            s.timeMin = 11 * 60
            stage(s, "Stan", "Kyle", "Craig", "Tweek", "Butters", "Wendy")
            check(School.recessStatus(s).kind == School.RS_NOT_MIDDAY,
                "school: no recess beat before the midday block")
            s.timeMin = 12 * 60 + 15
            val rs = School.recessStatus(s)
            check(rs.kind == School.RS_AVAILABLE && rs.beat != null &&
                rs.a != null && rs.b != null && rs.a != rs.b,
                "school: the yard fields its beat and two parties")
            check(rs.a in School.presentKids(s) &&
                rs.b in School.presentKids(s),
                "school: the parties are kids actually there")
            val beat = rs.beat!!
            val fair = beat.options.first {
                it.payA > 0 && it.payB > 0 }
            val aBefore = s.friendship[rs.a] ?: 0
            val bBefore = s.friendship[rs.b] ?: 0
            val out = School.playRecess(s, fair.id, rs.a!!, rs.b!!)
            check(out != null && out.isNotBlank(),
                "school: the fair call lands its outcome")
            check((s.friendship[rs.a] ?: 0) == aBefore + fair.payA &&
                (s.friendship[rs.b] ?: 0) == bBefore + fair.payB,
                "school: the ruling pays the parties their data")
            check(School.recessCount(s) == 1 &&
                School.recessHistory(s).single().beatId == beat.id,
                "school: the beat is recorded")
            check(School.recessStatus(s).kind == School.RS_DONE &&
                School.playRecess(s, fair.id, rs.a!!, rs.b!!) == null,
                "school: one recess beat per day, max")
            // the sided call pays only its side
            val s2 = fresh(); setDay(s2, 4)
            s2.timeMin = 12 * 60 + 15
            stage(s2, "Stan", "Kyle", "Craig", "Tweek")
            val rs2 = School.recessStatus(s2)
            val sided = rs2.beat!!.options
                .firstOrNull { (it.payA > 0) xor (it.payB > 0) }
            if (sided != null) {
                val aB = s2.friendship[rs2.a] ?: 0
                val bB = s2.friendship[rs2.b] ?: 0
                School.playRecess(s2, sided.id, rs2.a!!, rs2.b!!)
                check((s2.friendship[rs2.a] ?: 0) == aB + sided.payA &&
                    (s2.friendship[rs2.b] ?: 0) == bB + sided.payB,
                    "school: a sided call pays its side only — " +
                        "kindly, never negative")
            }
            // a weekend yard is just a yard
            val w = fresh(); setDay(w, 3)
            w.timeMin = 12 * 60 + 15
            check(School.recessStatus(w).kind == School.RS_NOT_SCHOOL_DAY,
                "school: no recess beat on a Sunday")
        }
        run {
            // the rotation across a term: every dry beat shows;
            // the snowball truce ONLY ever shows over snow
            val drySeen = mutableSetOf<String>()
            val snowSeen = mutableSetOf<String>()
            for (d in 0 until 180) {
                if (!School.isSchoolDay(d)) continue
                val s = fresh(); setDay(s, d)
                s.weatherId = "sunny"   // a fabricated DRY day
                drySeen += School.recessBeatFor(s).id
                val sn = fresh(); setDay(sn, d)
                sn.weatherId = "light_snow"
                snowSeen += School.recessBeatFor(sn).id
            }
            check("four_square" in drySeen && "note_passing" in drySeen &&
                "snowball_truce" !in drySeen,
                "school: the dry rotation holds both dry beats " +
                    "and never the truce ($drySeen)")
            check("snowball_truce" in snowSeen,
                "school: the truce rotates in over snow")
            val pinnedBeat = fresh(); setDay(pinnedBeat, 4)
            check(School.recessBeatFor(pinnedBeat) ==
                School.recessBeatFor(pinnedBeat),
                "school: the day's beat stays pinned once read")
        }

        // ---------- the bee: bracket data ----------
        run {
            check(School.WORD_TIERS.size == 5 &&
                School.WORD_TIERS.all { it.size >= 5 } &&
                School.WORD_TIERS.flatten().all { w ->
                    w.all { ch -> ch in 'a'..'z' } },
                "school: five word tiers, all lowercase bank words")
            check(School.WORD_TIERS.map { t -> t.maxOf { it.length } } ==
                School.WORD_TIERS.map { t -> t.maxOf { it.length } }
                    .sorted(),
                "school: the tiers honestly lengthen")
            val f1 = School.beeField(1)
            check(f1.size == School.FIELD_SIZE &&
                f1.distinct().size == School.FIELD_SIZE &&
                f1.all { it in CharacterSystem.CAST_KIDS },
                "school: the field is eight kids from the class")
            check(f1 == School.beeField(1),
                "school: the same Friday fields the same eight")
            val b1 = School.beeBracket(1)
            check(b1 == School.beeBracket(1),
                "school: the bracket is pure data — same day, same bee")
            check(b1.rounds.size in 1..School.MAX_ROUNDS &&
                (b1.champion == null || b1.champion in b1.field),
                "school: the bracket ends with at most one champion")
            // rounds honestly thin: standing counts never grow
            var last = School.FIELD_SIZE
            var thinOk = true
            for (r in b1.rounds) {
                if (r.remainingAfter.size > last) thinOk = false
                last = r.remainingAfter.size
            }
            check(thinOk, "school: the field only ever thins")
            // skills tell: over two years of Fridays the sharp
            // kids champion far more than the sleeve does
            var wendyKyle = 0; var cartman = 0
            var skillSum = 0; var champs = 0
            for (k in 0 until 104) {
                val champ = School.beeBracket(1 + 7 * k).champion
                    ?: continue
                champs++
                skillSum += School.skillOf(champ)
                if (champ == "Wendy" || champ == "Kyle") wendyKyle++
                if (champ == "Cartman") cartman++
            }
            check(champs > 80,
                "school: brackets produce champions ($champs/104)")
            check(skillSum.toDouble() / champs >= 5.5,
                "school: the average champion is a strong speller " +
                    "($skillSum/$champs)")
            check(wendyKyle > cartman * 3 && cartman <= 3,
                "school: Wendy & Kyle run deep; Cartman almost " +
                    "never takes it (WK $wendyKyle, C $cartman)")
            check(School.skillOf("Wendy") > School.skillOf("Cartman") &&
                School.skillOf("Kenny") >= 5,
                "school: the data says who lasts — and Kenny's " +
                    "muffle is judge-grade")
        }

        // ---------- Cartman's disqualification ----------
        run {
            var dqDay = -1
            for (k in 0 until 200) {
                val d = 1 + 7 * k
                if ("Cartman" in School.kidsStandingAfter(d, 2)) {
                    val br = School.beeBracket(d)
                    if (br.rounds.size >= School.CHEAT_ROUND &&
                        br.rounds[School.CHEAT_ROUND - 1].dq == "Cartman") {
                        dqDay = d; break
                    }
                }
            }
            check(dqDay > 0,
                "school: some Friday, Cartman lasts long enough " +
                    "to get caught (day $dqDay)")
            if (dqDay > 0) {
                val br = School.beeBracket(dqDay)
                check("Cartman" !in
                    br.rounds[School.CHEAT_ROUND - 1].remainingAfter &&
                    br.champion != "Cartman",
                    "school: the sleeve ends his bee in round " +
                        "${School.CHEAT_ROUND} — he does not win it")
            }
        }

        // ---------- the bee: entry gating ----------
        run {
            val s = fresh(); setDay(s, 0)   // Thursday
            s.timeMin = 13 * 60 + 30
            check(School.beeStatus(s) == School.BS_NOT_BEE_DAY &&
                !School.enterBee(s),
                "school: no bee on a Thursday")
            setDay(s, 1)                    // Friday
            s.timeMin = 10 * 60
            check(School.beeStatus(s) == School.BS_BEFORE &&
                !School.enterBee(s),
                "school: the chairs aren't out before 1")
            s.timeMin = 15 * 60 + 30
            check(School.beeStatus(s) == School.BS_AFTER &&
                !School.enterBee(s),
                "school: no late chairs after last bell")
            s.timeMin = 13 * 60 + 30
            check(School.beeStatus(s) == School.BS_OPEN,
                "school: Friday afternoon, the bee is open")
        }

        // ---------- the bee: a perfect run wins ----------
        run {
            val s = fresh(); setDay(s, 1)   // Friday
            s.timeMin = 13 * 60 + 30
            stage(s, "Stan", "Kyle")
            val coinsBefore = s.inventory[Minigames.COIN_ITEM] ?: 0
            check(playBee(s, perfect = true),
                "school: a perfect-spelling bee plays to its record")
            val rec = School.beeRecordFor(s, 1)!!
            check(rec.won && School.beeWon(s) == 1 &&
                School.beeEntered(s) == 1,
                "school: perfect play WINS — winnable on quality")
            check((s.inventory[Minigames.COIN_ITEM] ?: 0) ==
                coinsBefore + School.BEE_WIN_COINS,
                "school: the purse pays like every other game")
            check("bee_champion" in s.gameFeats,
                "school: the win completes the bee feat")
            check(School.beeBestRound(s) == rec.rounds &&
                rec.rounds >= 2,
                "school: the best-round record keeps the deep run " +
                    "(${rec.rounds} words)")
            check(House.decorFor(s).contains("bee_trophy") &&
                House.decorTokensFor(s).contains("bee-trophy"),
                "school: the trophy goes up on the wall at home")
            check((s.friendship[rec.other] ?: 0) == School.FINALIST_PAY,
                "school: the runner-up takes the finalist's friendship")
            check(School.beeStatus(s) == School.BS_DONE &&
                !School.enterBee(s) && !School.pickLetter(s, 'a'),
                "school: a settled bee settles exactly once")
            check(s.townLog.any { it.contains("🐝") },
                "school: the town log carries the bee")
        }

        // ---------- the bee: a miss loses, honestly ----------
        run {
            // (staged on day 22, a plain Friday — day 8 is
            // Oct 9, the fall FIELD TRIP's day since
            // v0.14.0b, and trip days stand the bee down)
            val s = fresh(); setDay(s, 22)   // a later Friday
            s.timeMin = 13 * 60 + 30
            val coinsBefore = s.inventory[Minigames.COIN_ITEM] ?: 0
            check(playBee(s, perfect = false),
                "school: a missed bee still plays to its record")
            val rec = School.beeRecordFor(s, 22)!!
            check(!rec.won && School.beeWon(s) == 0 &&
                School.beeEntered(s) == 1,
                "school: a first-letter miss LOSES — losable on quality")
            check(rec.other == School.winnerIfOut(22, 1),
                "school: the trophy goes to the bracket's own winner " +
                    "(${rec.other}) — never rigged, just data")
            check((s.inventory[Minigames.COIN_ITEM] ?: 0) == coinsBefore &&
                "bee_champion" !in s.gameFeats,
                "school: a loss pays no purse and no feat")
            check((s.friendship[rec.other] ?: 0) == 1,
                "school: the champion takes a point for the trophy")
            // a mid-run miss keeps the rounds honestly counted
            val s2 = fresh(); setDay(s2, 15)
            s2.timeMin = 13 * 60 + 30
            check(School.enterBee(s2), "school: the mid-run bee enters")
            var guard = 0; var spelledOne = false
            while (guard++ < 400) {
                val beat = School.beeBeat(s2) ?: break
                when (beat.kind) {
                    "letter" -> {
                        val word = School.currentWord(s2)
                        val idx = School.spellingProgress(s2)
                            .split(" ").count { it != "_" }
                        if (!spelledOne) {
                            School.pickLetter(s2, word[idx])
                        } else {
                            val wrong = School.letterOptions(s2)
                                .first { it != word[idx] }
                            School.pickLetter(s2, wrong)
                        }
                    }
                    "done" -> { School.advanceBee(s2); break }
                    else -> {
                        if (beat.text.startsWith("Clean.")) {
                            spelledOne = true
                        }
                        School.advanceBee(s2)
                    }
                }
            }
            val rec2 = School.beeRecordFor(s2, 15)
            check(rec2 != null && !rec2.won && rec2.rounds == 1 &&
                School.beeBestRound(s2) == 1,
                "school: one clean word then a miss records round 1")
        }

        // ---------- midnight settles a walked-away bee ----------
        run {
            val s = fresh(); setDay(s, 1)   // Friday
            s.timeMin = 13 * 60 + 30
            check(School.enterBee(s), "school: the walk-away bee enters")
            // spell the intro + field beats, then just leave
            School.advanceBee(s); School.advanceBee(s)
            setDay(s, 2)
            School.dailyRollover(s)
            val rec = School.beeRecordFor(s, 1)
            check(rec != null && !rec.won &&
                School.beeEntered(s) == 1,
                "school: midnight settles the abandoned bee as entered")
            check(s.life.keys.none {
                it.startsWith("bee") && it.endsWith(":1") },
                "school: yesterday's bee keys are pruned at rollover")
            // a lesson left open just evaporates — no credit
            val l = fresh(); setDay(l, 4)
            l.timeMin = 10 * 60
            stage(l, "Stan", "Kyle")
            check(School.startLesson(l), "school: the open lesson starts")
            setDay(l, 5)
            School.dailyRollover(l)
            check(School.lessonsSat(l) == 0 &&
                School.recordFor(l, 4) == null &&
                l.life.keys.none { it == "schoolSeat:4" },
                "school: an unfinished lesson leaves no record")
        }

        // ---------- records, page, talk, report ----------
        run {
            val old = decodeGameState(emptyMap())
            check(School.lessonsSat(old) == 0 &&
                School.beeEntered(old) == 0 &&
                School.beeHistory(old).isEmpty() &&
                School.lessonHistory(old).isEmpty() &&
                School.recessCount(old) == 0,
                "school: a v0.7.0c save loads with an empty school record")
            check(School.pageLines(old).first().contains("🎓 SCHOOL") &&
                School.pageLines(old).any {
                    it.contains("question marks") },
                "school: the page opens honest for a newcomer — " +
                    "Victoria's file joke included")
            val s = fresh(); setDay(s, 4)   // Monday
            s.timeMin = 10 * 60
            stage(s, "Stan", "Kyle", "Wendy")
            check(sitLesson(s, "right"), "school: the records lesson sits")
            val page = School.pageLines(s)
            check(page.any { it.contains(School.topicFor(4).title) } &&
                page.any { it.contains("✓") },
                "school: the page names the lesson and its mark")
            check(School.morningNote(s)?.contains(
                School.topicFor(4).title) == true,
                "school: the morning note announces today's lesson")
            val rep = House.morningReport(s, emptyList(),
                emptyMap(), 0, false, null)
            check(rep.any { it.contains(School.topicFor(4).title) },
                "school: the report itself carries the school line")
            val sun = fresh(); setDay(sun, 3)
            check(School.morningNote(sun) == null,
                "school: no school line on a Sunday")
            val fri = fresh(); setDay(fri, 1)
            check(School.morningNote(fri)?.contains("🐝") == true,
                "school: Friday's note sets up the bee")
            // the teachers remark — once a day each, and only
            // with a record to remark on
            val g1 = School.ambientLine(s, "Garrison")
            check(g1 != null && g1.speaker == "Garrison" &&
                g1.text.contains("actually listened"),
                "school: Garrison remarks on the right answer")
            check(School.ambientLine(s, "Garrison") == null,
                "school: the remark is once per teacher per day")
            check(TalkGate.owedLines(s, "Victoria")
                .any { it.text.contains("Attendance: noted") },
                "school: Victoria's remark rides the Talk rail")
            check(School.ambientLine(s, "Randy") == null &&
                School.ambientLine(s, "Chef") == null,
                "school: only the teachers remark on attendance")
            val nobody = fresh(); setDay(nobody, 4)
            check(School.ambientLine(nobody, "Victoria") == null &&
                School.ambientLine(nobody, "Garrison") == null,
                "school: no record, no remark — the file is just thin")
            // Victoria's hard-won approval at a real record
            val v = fresh()
            var day = 4
            var sat = 0
            while (sat < 12 && day < 40) {
                if (School.isSchoolDay(day)) {
                    setDay(v, day); v.timeMin = 10 * 60
                    v.holidayId = null
                    stage(v, "Stan", "Kyle")
                    if (School.lessonStatus(v).kind ==
                        School.LS_AVAILABLE && sitLesson(v, "right")) sat++
                }
                day++
            }
            check(sat == 12 && School.lessonsSat(v) == 12,
                "school: twelve real lessons sit for the file ($sat)")
            val star = School.ambientLine(v, "Victoria")
            check(star != null && star.text.contains("gold star"),
                "school: twelve lessons earn the principal's gold star")
        }

        // ---------- wiring pins (source) ----------
        run {
            val gv = File(root, "src/com/hunt3r/southparktown/GameView.kt")
                .readText()
            check(gv.contains("drawClassroomBoard") &&
                gv.contains("\"classroom\""),
                "school: the board is drawn and tappable in the classroom")
            val ga = File(root, "src/com/hunt3r/southparktown/GameActivity.kt")
                .readText()
            check(ga.contains("\"classroom\" -> schoolDialog()") &&
                ga.contains("School.lookText"),
                "school: the fixture tap and the Look line are wired")
            val tg = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
                .readText()
            check(tg.contains("School.ambientLine"),
                "school: the teachers' remarks ride Talk")
            val en = File(root, "src/com/hunt3r/southparktown/Engine.kt")
                .readText()
            check(en.contains("School.dailyRollover"),
                "school: midnight settles school")
            val ja = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt")
                .readText()
            check(ja.contains("🎓 SCHOOL") &&
                ja.contains("School.pageLines") &&
                ja.contains("School.beeEntered"),
                "school: the Journal keeps the page and the games line")
            check(!File(root, "src/com/hunt3r/southparktown/School.kt")
                .readText().contains("import android"),
                "school: School.kt is pure Kotlin (suite-testable)")
        }

        // ---------- spoiler scan ----------
        run {
            val src = File(root, "src/com/hunt3r/southparktown/School.kt")
                .readText().lowercase()
            val banned = listOf("sleepwalk", "professor chaos",
                "cameo", "strongbox", "commune", "paperwork",
                "night gardener", "stolen reel", "alibi",
                "the deed", "sleepwalking")
            val content = StringBuilder(src)
            for (t in School.TOPICS) {
                content.append(t.title).append(t.open).append(t.develop)
                    .append(t.question).append(t.rightOutcome)
                    .append(t.funnyOutcome).append(t.passOutcome)
            }
            val s = fresh(); setDay(s, 4)
            content.append(School.pageLines(s).joinToString())
                .append(School.morningNote(s) ?: "")
            val text = content.toString().lowercase()
            check(banned.none { it in text },
                "school: no case-solution content anywhere in the " +
                    "school build (scanned source + surfaces)")
        }

        // ---------- the save round-trip ----------
        run {
            val s = fresh(); setDay(s, 4)
            s.timeMin = 10 * 60
            stage(s, "Stan", "Kyle", "Craig")
            check(sitLesson(s, "funny"), "school: the trip lesson sits")
            s.timeMin = 12 * 60 + 15
            val rs = School.recessStatus(s)
            check(rs.kind == School.RS_AVAILABLE &&
                School.playRecess(s, rs.beat!!.options[0].id,
                    rs.a!!, rs.b!!) != null,
                "school: the trip recess referees")
            // (the bee rides day 15 — day 8 is the fall
            // field trip's Friday since v0.14.0b)
            setDay(s, 15); s.timeMin = 13 * 60 + 30
            check(playBee(s, perfect = true),
                "school: the trip bee wins")
            val back = decodeGameState(encodeGameState(s))
            check(School.lessonsSat(back) == 1 &&
                School.recordFor(back, 4)?.choice == "funny" &&
                School.recessCount(back) == 1 &&
                School.beeWon(back) == 1 &&
                School.beeRecordFor(back, 15)?.won == true &&
                School.beeBestRound(back) == School.beeBestRound(s),
                "school: the whole record survives the save round-trip")
        }

        // ---------- a school year, lived ----------
        run {
            val s = fresh()
            var lessonsExpected = 0
            var recessPlayed = 0
            var beesPlayed = 0
            var beesWonCount = 0
            var error: String? = null
            try {
                repeat(200) {
                    eng.onNewDay(s)
                    // first period
                    s.timeMin = 9 * 60 + 45
                    stage(s, "Stan", "Kyle", "Craig", "Tweek",
                        "Jimmy", "Wendy", "Butters", "Kenny")
                    if (School.lessonStatus(s).kind ==
                        School.LS_AVAILABLE) {
                        val choice = listOf("right", "funny", "pass")[
                            s.absDay % 3]
                        if (sitLesson(s, choice)) lessonsExpected++
                    }
                    // midday
                    s.timeMin = 12 * 60 + 15
                    val rs = School.recessStatus(s)
                    if (rs.kind == School.RS_AVAILABLE) {
                        val opt = rs.beat!!.options[s.absDay %
                            rs.beat!!.options.size]
                        if (School.playRecess(s, opt.id,
                                rs.a!!, rs.b!!) != null) recessPlayed++
                    }
                    // Friday bees, alternating perfect and human
                    if (School.isBeeDay(s.absDay)) {
                        s.timeMin = 13 * 60 + 30
                        if (School.beeStatus(s) == School.BS_OPEN) {
                            val perfect = beesPlayed % 2 == 0
                            if (playBee(s, perfect)) {
                                beesPlayed++
                                if (School.beeRecordFor(s, s.absDay)
                                        ?.won == true) beesWonCount++
                            }
                        }
                    }
                }
            } catch (t: Throwable) {
                error = "${t.javaClass.simpleName}: ${t.message}"
            }
            check(error == null, "school: the year runs clean ($error)")
            check(lessonsExpected >= 100 &&
                School.lessonsSat(s) == lessonsExpected,
                "school: a year of lessons sat ($lessonsExpected, " +
                    "quiet days honestly skipped)")
            check(recessPlayed >= 40,
                "school: recess got refereed all year ($recessPlayed)")
            check(beesPlayed >= 15 && beesWonCount >= 5 &&
                School.beeWon(s) == beesWonCount,
                "school: the year's bees — played $beesPlayed, " +
                    "won $beesWonCount on perfect Fridays")
            check(School.lessonHistory(s).size <= School.HISTORY_CAP &&
                School.beeHistory(s).size <= School.BEE_HISTORY_CAP &&
                School.recessHistory(s).size <=
                    School.RECESS_HISTORY_CAP,
                "school: the histories hold their caps across a year")
            val size = Json.stringify(encodeGameState(s)).length
            check(size < 512 * 1024,
                "school: a school year keeps the save lean ($size chars)")
        }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

private fun sectionV070e(root: String) {
    println("== v0.7.0e: playable climaxes — judged chains, tiers, the town's retelling ==")
    val eng = Engine(7005)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        fun fresh(): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
            return s
        }
        // Put a state on an absolute day, with the calendar
        // fields that follow from it (day 0 = Thu 2026-10-01).
        fun setDay(s: GameState, day: Int) {
            s.absDay = day
            val key = keyFromOrdinal(ordinalOfKey("20261001") + day)
            s.todayKey = key
            s.gameYear = key.substring(0, 4).toInt()
            s.gameMonth = key.substring(4, 6).toInt()
            s.gameDay = key.substring(6, 8).toInt()
        }
        // An event day, fabricated the way the engine starts
        // one: the def's ids, its day key, and its episode
        // record (Episodes.beginEvent, as startEvent calls
        // it). Memories reset so topic assertions are clean.
        fun eventState(defId: String, day: Int = 12): GameState {
            NpcMemoryStore.deserialize(memSnapshot)
            val s = fresh()
            setDay(s, day)
            val def = SHENANIGAN_BY_ID[defId]!!
            s.shenaniganId = defId
            s.shenaniganDay = s.todayKey
            s.lastStageSeen = 1
            Episodes.beginEvent(s, def)
            return s
        }
        fun defOf(s: GameState): ShenaniganDef =
            SHENANIGAN_BY_ID[s.shenaniganId!!]!!
        // The fabricated event's record — looked up by the
        // def's id, never by the state's (the wrap may have
        // rolled tomorrow's event into those fields already).
        fun episodeOf(s: GameState, defId: String): EpisodeRecord? =
            s.episodes.lastOrNull {
                it.kind == "event" && it.eventId == defId }
        // Play the open chain the way the dialog chain does —
        // sessionBeat by sessionBeat, judging through the
        // module's own verbs. Heroic lands every beat;
        // fumbled misses every beat (worst option, first-
        // surge break, task let go).
        fun playChain(s: GameState, heroic: Boolean): Boolean {
            var guard = 0
            while (guard++ < 60) {
                val beat = Climaxes.sessionBeat(s) ?: return false
                when (beat.kind) {
                    "intro" -> Climaxes.begin(s)
                    "result" -> Climaxes.advance(s)
                    "done" -> return true
                    "choice" -> {
                        val cb = Climaxes.currentBeat(s) ?: return false
                        val pick = if (heroic)
                            cb.options.indices.maxByOrNull {
                                cb.options[it].score }!!
                        else
                            cb.options.indices.minByOrNull {
                                cb.options[it].score }!!
                        Climaxes.choose(s, pick)
                    }
                    "stand" -> {
                        val esc = Climaxes.currentEscalation(s)
                            ?: return false
                        val pick = if (heroic) esc.holdIndex
                        else esc.options.indices.first {
                            it != esc.holdIndex }
                        Climaxes.standChoose(s, pick)
                    }
                    "task" -> {
                        val cb = Climaxes.currentBeat(s) ?: return false
                        if (heroic) {
                            when (cb.kind) {
                                Climaxes.KIND_PHOTO -> Climaxes.notePhoto(
                                    s, Climaxes.climaxLoc(defOf(s))!!)
                                Climaxes.KIND_FIND ->
                                    Climaxes.lookText(s, cb.findLoc)
                            }
                            if (Climaxes.taskAction(s, 0) != null)
                                return false
                        } else Climaxes.taskAction(s, 1)
                    }
                    else -> return false
                }
            }
            return false
        }
        // Roll time past midnight until the fabricated
        // event's episode sits finished.
        fun wrapEvent(s: GameState) {
            val dayKey = s.shenaniganDay
            val id = s.shenaniganId
            var guard = 0
            while (guard++ < 400) {
                val ep = s.episodes.lastOrNull {
                    it.kind == "event" && it.eventId == id &&
                        it.dayKey == dayKey }
                if (ep != null && ep.finished) return
                eng.advanceTime(s)
            }
        }

        // ---------- the set: ten chains, one per shenanigan ----------
        check(Climaxes.CHAINS.keys == SHENANIGANS.map { it.id }.toSet() &&
            Climaxes.CHAINS.size == 10,
            "climaxes: exactly the ten shenanigans carry chains — " +
                "no mystery def is playable this way")
        check(Climaxes.BEATS_PER_CHAIN == 3,
            "climaxes: three beats a chain is the dial")
        var standBeats = 0
        var photoBeats = 0
        var findBeats = 0
        for ((id, chain) in Climaxes.CHAINS) {
            val def = SHENANIGAN_BY_ID[id]!!
            check(chain.beats.size == Climaxes.BEATS_PER_CHAIN,
                "climaxes: $id's chain runs three beats")
            check(chain.intro.isNotBlank() && chain.closing.isNotBlank() &&
                chain.heroicLine.isNotBlank() &&
                chain.handledLine.isNotBlank() &&
                chain.fumbledLine.isNotBlank(),
                "climaxes: $id is fully written — intro, closing, " +
                    "and a how-it-went per tier")
            check(Climaxes.climaxLoc(def) != null,
                "climaxes: $id's climax has a turf")
            for (beat in chain.beats) {
                when (beat.kind) {
                    Climaxes.KIND_TALK, Climaxes.KIND_LOOK -> {
                        check(beat.text.isNotBlank() &&
                            beat.options.size == 3 &&
                            beat.options.map { it.score }.sorted() ==
                                listOf(0, 1, 2) &&
                            beat.options.all {
                                it.label.isNotBlank() &&
                                    it.result.isNotBlank() },
                            "climaxes: $id has a judged ${beat.kind} " +
                                "beat — three answers, one landed, " +
                                "one close, one missed")
                    }
                    Climaxes.KIND_STAND -> {
                        standBeats++
                        check(beat.escalations.size == 3 &&
                            beat.escalations.all {
                                it.options.size == 3 &&
                                    it.holdIndex in it.options.indices &&
                                    it.pressure.isNotBlank() } &&
                            beat.standWin.isNotBlank() &&
                            beat.standClose.isNotBlank() &&
                            beat.standMiss.isNotBlank(),
                            "climaxes: $id's STAND runs three surges " +
                                "with one hold apiece and a result " +
                                "per crack point")
                    }
                    Climaxes.KIND_PHOTO -> {
                        photoBeats++
                        check(beat.taskDone.isNotBlank() &&
                            beat.taskSkip.isNotBlank(),
                            "climaxes: $id's PHOTO beat is written " +
                                "both ways")
                    }
                    Climaxes.KIND_FIND -> {
                        findBeats++
                        check(beat.findLoc in LOCATIONS &&
                            beat.findText.isNotBlank() &&
                            beat.taskDone.isNotBlank() &&
                            beat.taskSkip.isNotBlank(),
                            "climaxes: $id's FIND beat names a real " +
                                "spot and is written both ways")
                    }
                    else -> check(false,
                        "climaxes: $id has an unknown beat kind " +
                            beat.kind)
                }
            }
        }
        check(standBeats == 3,
            "climaxes: the one new interaction is used sparingly — " +
                "three STAND beats in the whole set, got $standBeats")
        check(photoBeats == 4 && findBeats == 2,
            "climaxes: four PHOTO beats and two FIND beats ride " +
                "the existing verbs (got $photoBeats/$findBeats)")

        // ---------- tier math at the thresholds ----------
        check(Climaxes.tierFromScores(listOf(2, 2, 2)) == "heroic",
            "tiers: all landed is HEROIC")
        check(Climaxes.tierFromScores(listOf(2, 2, 1)) == "handled" &&
            Climaxes.tierFromScores(listOf(2, 1, 0)) == "handled" &&
            Climaxes.tierFromScores(listOf(1, 1, 1)) == "handled" &&
            Climaxes.tierFromScores(listOf(1, 1, 0)) == "handled",
            "tiers: one miss (or none landed clean) is GOT IT DONE")
        check(Climaxes.tierFromScores(listOf(2, 0, 0)) == "fumbled" &&
            Climaxes.tierFromScores(listOf(0, 0, 2)) == "fumbled" &&
            Climaxes.tierFromScores(listOf(0, 0, 0)) == "fumbled",
            "tiers: most beats missed is FUMBLED")
        check(Climaxes.outcomeForTier("absent") == null &&
            Climaxes.outcomeForTier("heroic") != null &&
            Climaxes.topicForTier("heroic") == Climaxes.TOPIC_HEROIC &&
            Climaxes.topicForTier("handled") == Climaxes.TOPIC_HANDLED &&
            Climaxes.topicForTier("fumbled") == Climaxes.TOPIC_FUMBLED &&
            Climaxes.topicForTier("absent") == null,
            "tiers: only played tiers carry an outcome line and " +
                "a retelling topic")

        // ---------- the rail: live window, turf, causers ----------
        run {
            val s = eventState("mole_panic")
            val def = defOf(s)
            val turf = Climaxes.climaxLoc(def)!!
            s.timeMin = 13 * 60
            check(TalkGate.gateFor(s, "Kenny", turf).rail ==
                TalkGate.Rail.CLIMAX,
                "rail: a causer at the turf in the climax stage " +
                    "gates to CLIMAX")
            check(Climaxes.talkStepFor(s, "Cartman", turf),
                "rail: any causer can host the chain")
            check(!Climaxes.talkStepFor(s, "Kyle", turf),
                "rail: a bystander doesn't host the climax")
            check(!Climaxes.talkStepFor(s, "Kenny", "MainStreet"),
                "rail: the climax doesn't play off its turf")
            s.timeMin = 10 * 60
            check(!Climaxes.talkStepFor(s, "Kenny", turf),
                "rail: no climax before the climax stage")
            s.timeMin = 20 * 60
            check(!Climaxes.talkStepFor(s, "Kenny", turf),
                "rail: no climax after the climax stage")
            s.timeMin = 13 * 60
            check(Climaxes.sessionBeat(s)?.kind == "intro",
                "rail: the chain opens on its intro card")
            // the stage hook advertises the peak, once staged
            val before = s.events.size
            Climaxes.noteStage(s, def, 1)
            check(s.events.size == before,
                "rail: earlier stages stay silent about the climax")
            Climaxes.noteStage(s, def, 2)
            check(s.events.lastOrNull()?.contains("CLIMAX") == true,
                "rail: the climax stage's ticker names the peak")
            // earlier stages: Look and Photo hear nothing
            s.timeMin = 10 * 60
            check(Climaxes.lookText(s, turf) == null,
                "rail: a stage-1 Look at the turf is an ordinary look")
        }

        // ---------- content scans: this is episode content ----------
        // The chains are this build's own writing about the
        // events' public stories — nothing here may touch a
        // case's workings (the standing spoiler discipline).
        run {
            val allText = Climaxes.CHAINS.values.flatMap { chain ->
                listOf(chain.intro, chain.closing, chain.heroicLine,
                    chain.handledLine, chain.fumbledLine) +
                    chain.beats.flatMap { b ->
                        listOf(b.text, b.standWin, b.standClose,
                            b.standMiss, b.taskDone, b.taskSkip,
                            b.findText) +
                            b.options.flatMap { listOf(it.label, it.result) } +
                            b.escalations.flatMap {
                                listOf(it.pressure) + it.options }
                    }
            }.joinToString("\n").lowercase()
            for (banned in listOf("sleepwalk", "professor chaos",
                "bijou", "reel", "strongbox", "deed", "confession",
                "gardener", "mckay", "mackey")) {
                check(!allText.contains(banned),
                    "climaxes: no chain text touches case workings " +
                        "('$banned' stays out)")
            }
        }

        // ---------- every event: the heroic path completes ----------
        for (def in SHENANIGANS) {
            val chain = Climaxes.CHAINS[def.id]!!
            val s = eventState(def.id)
            s.timeMin = 13 * 60
            check(playChain(s, true),
                "heroic ${def.id}: the chain plays to its closing card")
            check(Climaxes.scoresOf(s, def).all { it == 2 },
                "heroic ${def.id}: every beat landed")
            check(s.participation == 6,
                "heroic ${def.id}: three resolved beats paid " +
                    "participation 6 into the event's own ledger")
            val friendsBefore = def.causers.associateWith {
                s.friendship[it] ?: 0 }
            wrapEvent(s)
            val ep = episodeOf(s, def.id)
            check(ep != null && ep.finished,
                "heroic ${def.id}: the episode still resolves")
            if (ep != null) {
                check(ep.climaxTier == "heroic",
                    "heroic ${def.id}: the record carries the tier")
                check(ep.outcome == Climaxes.outcomeForTier("heroic"),
                    "heroic ${def.id}: the wrap speaks the tier's line")
                check(ep.recap.any { it.contains(chain.heroicLine) },
                    "heroic ${def.id}: the Journal recap tells how " +
                        "it went")
                check(Episodes.page(ep, 3).body.any {
                    it.contains(chain.heroicLine) },
                    "heroic ${def.id}: the episode page shows it")
                check(Episodes.climaxTierOf(ep) == "heroic",
                    "heroic ${def.id}: the tier reads back as itself")
            }
            check(def.causers.all {
                (s.friendship[it] ?: 0) == (friendsBefore[it] ?: 0) + 2 },
                "heroic ${def.id}: the causers are paid +2 friendship")
            check(def.causers.filter { it in KID_ORDER }.all {
                Climaxes.TOPIC_HEROIC in
                    (NpcMemoryStore.get(it)?.topics ?: emptyList()) },
                "heroic ${def.id}: the causers carry the flattering " +
                    "retelling topic")
            check(s.lifeText["mark:${Climaxes.climaxLoc(def)}"]
                ?.contains(Climaxes.outcomeForTier("heroic")!!) == true,
                "heroic ${def.id}: the turf's mark remembers the " +
                    "heroic outcome")
        }

        // ---------- every event: the fumbled path completes ----------
        for (def in SHENANIGANS) {
            val chain = Climaxes.CHAINS[def.id]!!
            val s = eventState(def.id)
            s.timeMin = 13 * 60
            check(playChain(s, false),
                "fumbled ${def.id}: even a disaster plays to its " +
                    "closing card")
            check(Climaxes.scoresOf(s, def).all { it == 0 },
                "fumbled ${def.id}: every beat missed")
            val friendsBefore = def.causers.associateWith {
                s.friendship[it] ?: 0 }
            wrapEvent(s)
            val ep = episodeOf(s, def.id)
            check(ep != null && ep.finished && ep.climaxTier == "fumbled",
                "fumbled ${def.id}: the episode resolves AT the " +
                    "fumbled tier — funny, never stranded")
            if (ep != null) {
                check(ep.outcome == Climaxes.outcomeForTier("fumbled"),
                    "fumbled ${def.id}: the town's version stars " +
                        "the fumble")
                check(ep.recap.any { it.contains(chain.fumbledLine) },
                    "fumbled ${def.id}: the Journal keeps the roast")
            }
            check(def.causers.all {
                (s.friendship[it] ?: 0) == (friendsBefore[it] ?: 0) },
                "fumbled ${def.id}: no friendship paid, none taken — " +
                    "a fumble costs nothing but pride")
            check(def.causers.filter { it in KID_ORDER }.all {
                Climaxes.TOPIC_FUMBLED in
                    (NpcMemoryStore.get(it)?.topics ?: emptyList()) },
                "fumbled ${def.id}: the causers carry the roasting " +
                    "retelling topic")
        }

        // ---------- every event: absent is byte-unchanged ----------
        for (def in SHENANIGANS) {
            val s = eventState(def.id)
            s.timeMin = 13 * 60
            wrapEvent(s)
            val ep = episodeOf(s, def.id)
            check(ep != null && ep.finished,
                "absent ${def.id}: the episode resolves as always")
            if (ep != null) {
                check(ep.outcome ==
                    "You mostly watched it burn from a safe distance.",
                    "absent ${def.id}: the legacy outcome line, " +
                        "word for word")
                check(ep.climaxTier == "absent" && ep.climaxHow == "",
                    "absent ${def.id}: the record quietly says absent " +
                        "and nothing more")
                check(ep.recap.none { it.contains("🎬 The climax") },
                    "absent ${def.id}: no climax line enters the " +
                        "credits")
            }
            check(def.causers.filter { it in KID_ORDER }.all { name ->
                val topics = NpcMemoryStore.get(name)?.topics
                    ?: emptyList()
                Climaxes.TOPIC_HEROIC !in topics &&
                    Climaxes.TOPIC_HANDLED !in topics &&
                    Climaxes.TOPIC_FUMBLED !in topics },
                "absent ${def.id}: no retelling is planted for a " +
                    "climax nobody played")
            check(s.lifeText["mark:${Climaxes.climaxLoc(def)}"]
                ?.contains("safe distance") == true,
                "absent ${def.id}: the turf's mark is the legacy mark")
        }
        // the legacy outcome still scales with participation
        run {
            val s = eventState("pirate_week")
            s.timeMin = 13 * 60
            s.participation = 5
            wrapEvent(s)
            check(episodeOf(s, "pirate_week")?.outcome ==
                "You were in the thick of it — the town noticed.",
                "absent: a hands-on day without the chain keeps " +
                    "the top legacy outcome")
            check(episodeOf(s, "pirate_week")?.climaxTier == "absent",
                "absent: participation alone never invents a tier")
        }
        // an opened-but-unplayed chain is absent too
        run {
            val s = eventState("gold_fever")
            s.timeMin = 13 * 60
            Climaxes.begin(s)
            wrapEvent(s)
            check(episodeOf(s, "gold_fever")?.climaxTier == "absent" &&
                episodeOf(s, "gold_fever")?.outcome ==
                    "You mostly watched it burn from a safe distance.",
                "absent: stepping in and never playing a beat " +
                    "settles exactly like never showing")
        }

        // ---------- interruption settles at the tier earned ----------
        run {
            // one beat landed, then the day rolls over it
            val s = eventState("mole_panic")
            val def = defOf(s)
            s.timeMin = 13 * 60
            Climaxes.begin(s)
            val beat0 = Climaxes.currentBeat(s)!!
            Climaxes.choose(s, beat0.options.indexOfFirst {
                it.score == 2 })
            Climaxes.advance(s)
            wrapEvent(s)
            val ep = episodeOf(s, def.id)
            check(ep != null && ep.finished &&
                ep.climaxTier == "fumbled",
                "interruption: one landed beat and two unplayed " +
                    "settles FUMBLED — the episode never strands")
            check(ep?.recap?.any {
                it.contains(Climaxes.CHAINS[def.id]!!.fumbledLine) } == true,
                "interruption: the settled tier still writes its line")
        }
        run {
            // two beats landed, then sleep takes the third
            val s = eventState("chinpo_craze")
            val def = defOf(s)
            s.timeMin = 13 * 60
            Climaxes.begin(s)
            repeat(2) {
                val cb = Climaxes.currentBeat(s)!!
                Climaxes.choose(s, cb.options.indexOfFirst {
                    it.score == 2 })
                Climaxes.advance(s)
            }
            wrapEvent(s)
            check(episodeOf(s, def.id)?.climaxTier == "handled",
                "interruption: two landed beats and one unplayed " +
                    "settles GOT IT DONE")
            check(def.causers.all {
                (s.friendship[it] ?: 0) == 1 },
                "interruption: the handled tier pays its +1")
        }
        run {
            // interrupted mid-STAND: the surge count doesn't
            // leak into the tier — the unplayed beat is a miss
            val s = eventState("silent_challenge")
            s.timeMin = 13 * 60
            Climaxes.begin(s)
            val cb = Climaxes.currentBeat(s)!!
            Climaxes.choose(s, cb.options.indexOfFirst {
                it.score == 2 })
            Climaxes.advance(s)
            val esc = Climaxes.currentEscalation(s)!!
            Climaxes.standChoose(s, esc.holdIndex)   // one surge held
            wrapEvent(s)
            check(episodeOf(s, "silent_challenge")?.climaxTier ==
                "fumbled" &&
                episodeOf(s, "silent_challenge")?.finished == true,
                "interruption: a half-held STAND settles with the " +
                    "day, at the tier earned so far")
        }

        // ---------- settle exactly once, across save/reload ----------
        run {
            val s = eventState("coon_sightings")
            val def = defOf(s)
            s.timeMin = 13 * 60
            // play one beat, then save mid-chain and reload
            Climaxes.begin(s)
            val cb = Climaxes.currentBeat(s)!!
            Climaxes.choose(s, cb.options.indexOfFirst {
                it.score == 2 })
            Climaxes.advance(s)
            val doc = encodeGameState(s)
            val s2 = decodeGameState(doc)
            check(s2.shenaniganId == def.id &&
                Climaxes.scoresOf(s2, def) ==
                    Climaxes.scoresOf(s, def) &&
                Climaxes.sessionBeat(s2)?.kind ==
                    Climaxes.sessionBeat(s)?.kind,
                "settle: a mid-chain save reloads with the chain " +
                    "exactly where it stood")
            check(playChain(s2, true),
                "settle: the reloaded chain still completes")
            val dayKey2 = s2.shenaniganDay
            wrapEvent(s2)
            val ep = s2.episodes.lastOrNull {
                it.kind == "event" && it.eventId == def.id &&
                    it.dayKey == dayKey2 }
            check(ep?.climaxTier == "heroic",
                "settle: the reloaded run wraps heroic through " +
                    "the engine's own rollover")
            // and the finished record itself round-trips
            val s3 = decodeGameState(encodeGameState(s2))
            val ep3 = s3.episodes.lastOrNull {
                it.kind == "event" && it.eventId == def.id }
            check(ep3?.climaxTier == "heroic" &&
                ep3?.recap == ep?.recap,
                "settle: the tier and the credits survive the " +
                    "save format whole")
        }
        run {
            // the wrap unit itself, called the way
            // rollShenanigan calls it — twice. The second
            // call is refused and pays nothing again.
            val s = eventState("upside_down_day")
            val def = defOf(s)
            s.timeMin = 13 * 60
            check(playChain(s, true),
                "settle: the unit-test chain completes")
            val w1 = Climaxes.wrap(s, def)
            check(w1?.tier == "heroic" &&
                w1?.outcome == Climaxes.outcomeForTier("heroic") &&
                w1?.how == Climaxes.CHAINS[def.id]!!.heroicLine,
                "settle: the wrap returns the tier, its outcome " +
                    "line and its how-it-went")
            val friendsAfter = def.causers.associateWith {
                s.friendship[it] ?: 0 }
            check(Climaxes.wrap(s, def) == null,
                "settle: a second wrap of the same climax is " +
                    "refused outright")
            check(def.causers.all {
                (s.friendship[it] ?: 0) == friendsAfter[it] },
                "settle: the refusal pays nothing twice")
        }

        // ---------- STAND: the truth table, and the teaching ----------
        run {
            // drive mole_panic to its STAND beat (beat 1),
            // then answer the surges as scripted
            fun standState(): GameState {
                val s = eventState("mole_panic")
                s.timeMin = 13 * 60
                Climaxes.begin(s)
                val cb = Climaxes.currentBeat(s)!!
                Climaxes.choose(s, cb.options.indexOfFirst {
                    it.score == 2 })
                Climaxes.advance(s)
                return s
            }
            val chain = Climaxes.CHAINS["mole_panic"]!!
            val standBeat = chain.beats[1]
            // hold all three → landed, with the win text
            run {
                val s = standState()
                repeat(3) {
                    val esc = Climaxes.currentEscalation(s)!!
                    Climaxes.standChoose(s, esc.holdIndex)
                }
                check(Climaxes.scoresOf(s, defOf(s))[1] == 2 &&
                    Climaxes.sessionBeat(s)?.text == standBeat.standWin,
                    "stand: holding all three surges lands the beat")
            }
            // hold, hold, crack on the third → close
            run {
                val s = standState()
                repeat(2) {
                    val esc = Climaxes.currentEscalation(s)!!
                    Climaxes.standChoose(s, esc.holdIndex)
                }
                val esc = Climaxes.currentEscalation(s)!!
                Climaxes.standChoose(s, esc.options.indices.first {
                    it != esc.holdIndex })
                check(Climaxes.scoresOf(s, defOf(s))[1] == 1 &&
                    Climaxes.sessionBeat(s)?.text == standBeat.standClose,
                    "stand: cracking only on the last surge is a " +
                        "near thing")
            }
            // crack on the first or second surge → missed
            for (crackAt in 0..1) {
                val s = standState()
                repeat(crackAt) {
                    val esc = Climaxes.currentEscalation(s)!!
                    Climaxes.standChoose(s, esc.holdIndex)
                }
                val esc = Climaxes.currentEscalation(s)!!
                Climaxes.standChoose(s, esc.options.indices.first {
                    it != esc.holdIndex })
                check(Climaxes.scoresOf(s, defOf(s))[1] == 0 &&
                    Climaxes.sessionBeat(s)?.text == standBeat.standMiss,
                    "stand: cracking on surge ${crackAt + 1} misses " +
                        "the beat")
            }
            // the teaching rides the first STAND a save meets,
            // and only the first — across events, in one save
            run {
                val s = standState()
                check(Climaxes.sessionBeat(s)?.text
                    ?.contains("HOLD YOUR GROUND") == true,
                    "stand: the first use teaches the rule up front")
                repeat(3) {
                    val esc = Climaxes.currentEscalation(s)!!
                    Climaxes.standChoose(s, esc.holdIndex)
                }
                check(s.lifeText["climax:taught"] == "1",
                    "stand: resolving a STAND marks the save taught")
                // the same save, a later event, its own STAND:
                // no second lesson
                val s3 = decodeGameState(encodeGameState(s))
                val def3 = SHENANIGAN_BY_ID["silent_challenge"]!!
                s3.shenaniganId = def3.id
                s3.shenaniganDay = s3.todayKey
                Episodes.beginEvent(s3, def3)
                s3.timeMin = 13 * 60
                Climaxes.begin(s3)
                val cb = Climaxes.currentBeat(s3)!!
                Climaxes.choose(s3, cb.options.indexOfFirst {
                    it.score == 2 })
                Climaxes.advance(s3)
                check(Climaxes.sessionBeat(s3)?.kind == "stand" &&
                    Climaxes.sessionBeat(s3)?.text
                        ?.contains("HOLD YOUR GROUND") == false,
                    "stand: a taught save is never taught twice")
            }
        }

        // ---------- task beats: the deed gates the landing ----------
        run {
            // PHOTO (chinpo_craze, beat 2): the shutter is the
            // verb — right turf, live window, or it doesn't count
            val s = eventState("chinpo_craze")
            val def = defOf(s)
            val turf = Climaxes.climaxLoc(def)!!
            s.timeMin = 13 * 60
            Climaxes.begin(s)
            repeat(2) {
                val cb = Climaxes.currentBeat(s)!!
                Climaxes.choose(s, cb.options.indexOfFirst {
                    it.score == 2 })
                Climaxes.advance(s)
            }
            check(Climaxes.sessionBeat(s)?.kind == "task",
                "photo: the chain reaches its task card")
            check(Climaxes.taskAction(s, 0) != null &&
                Climaxes.scoresOf(s, def)[2] == null,
                "photo: showing them nothing lands nothing — " +
                    "the chain waits")
            Climaxes.notePhoto(s, "Church")
            check(Climaxes.taskAction(s, 0) != null,
                "photo: a shot off the turf doesn't count")
            s.timeMin = 20 * 60
            Climaxes.notePhoto(s, turf)
            s.timeMin = 13 * 60
            check(Climaxes.taskAction(s, 0) != null,
                "photo: a shot after the window doesn't count")
            Climaxes.notePhoto(s, turf)
            check(Climaxes.taskAction(s, 0) == null &&
                Climaxes.scoresOf(s, def)[2] == 2,
                "photo: a live shot on the turf lands the beat")
        }
        run {
            // FIND (pirate_week): a careful Look at the spot
            // turns the thing up — once, in the window
            val s = eventState("pirate_week")
            val def = defOf(s)
            val findBeat = Climaxes.CHAINS[def.id]!!.beats
                .first { it.kind == Climaxes.KIND_FIND }
            s.timeMin = 10 * 60
            check(Climaxes.lookText(s, findBeat.findLoc) == null,
                "find: no turning-up before the climax is live")
            s.timeMin = 13 * 60
            check(Climaxes.lookText(s, findBeat.findLoc) ==
                findBeat.findText,
                "find: the Look in the window finds it")
            check(Climaxes.lookText(s, findBeat.findLoc) !=
                findBeat.findText,
                "find: it turns up exactly once")
            // and the find alone doesn't resolve the beat —
            // it still has to be carried back to a host
            Climaxes.begin(s)
            repeat(2) {
                val cb = Climaxes.currentBeat(s)!!
                Climaxes.choose(s, cb.options.indexOfFirst {
                    it.score == 2 })
                Climaxes.advance(s)
            }
            check(Climaxes.taskAction(s, 0) == null &&
                Climaxes.scoresOf(s, def)[2] == 2,
                "find: carrying it back lands the beat")
        }

        // ---------- the retellings differ by tier ----------
        run {
            fun bankFor(topic: String): Set<String> {
                val mem = NpcMemory(meets = 3,
                    topics = mutableListOf(topic))
                val out = mutableSetOf<String>()
                for (seed in 0..199)
                    Threads.followUp(mem, kotlin.random.Random(seed))
                        ?.let { out.add(it) }
                return out
            }
            val saveBank = bankFor(Climaxes.TOPIC_HEROIC)
            val dayBank = bankFor(Climaxes.TOPIC_HANDLED)
            val fumbleBank = bankFor(Climaxes.TOPIC_FUMBLED)
            check(saveBank.size == 3 && dayBank.size == 3 &&
                fumbleBank.size == 3,
                "threads: each tier's topic holds a three-line bank")
            check(saveBank.intersect(dayBank).isEmpty() &&
                saveBank.intersect(fumbleBank).isEmpty() &&
                dayBank.intersect(fumbleBank).isEmpty(),
                "threads: the retellings are three different " +
                    "tellings — flattering, warm, and the roast")
            check(saveBank.all { it.contains(Climaxes.TOPIC_HEROIC) } &&
                fumbleBank.all { it.contains(Climaxes.TOPIC_FUMBLED) },
                "threads: the lines speak the topic they retell")
        }

        // ---------- legacy saves: the before-records ----------
        run {
            // a finished heroic episode, re-read from an old
            // save's shape (no tier keys at all)
            val s = eventState("mole_panic")
            s.timeMin = 13 * 60
            check(playChain(s, true), "legacy: setup chain completes")
            wrapEvent(s)
            val ep = episodeOf(s, "mole_panic")!!
            val oldShape = ep.toMap() - "climaxTier" - "climaxHow"
            val legacy = Episodes.fromMap(oldShape)!!
            check(legacy.climaxTier == "",
                "legacy: the old shape loads with no tier written")
            check(Episodes.climaxTierOf(legacy) == "legacy",
                "legacy: a finished pre-climax record reads as " +
                    "the before-record")
            check(Episodes.climaxTierForMemory(legacy) == "handled",
                "legacy: for memory purposes the before-record " +
                    "counts as GOT IT DONE")
            // unfinished and non-event records have no tier
            val unfinished = Episodes.fromMap(
                ep.toMap() + ("finished" to false) -
                    "climaxTier" - "climaxHow")!!
            check(Episodes.climaxTierOf(unfinished) == "",
                "legacy: an unfinished record claims no tier")
            val holiday = Episodes.fromMap(
                ep.toMap() + mapOf("kind" to "holiday") -
                    "climaxTier" - "climaxHow")!!
            check(Episodes.climaxTierOf(holiday) == "",
                "legacy: a holiday record is not a climax record")
            val mysteryish = Episodes.fromMap(
                ep.toMap() + mapOf("eventId" to Mystery.FINALE_ID) -
                    "climaxTier" - "climaxHow")!!
            check(Episodes.climaxTierOf(mysteryish) == "",
                "legacy: a mystery finale's record is never read " +
                    "as a shenanigan climax")
            // and a stored tier always wins over the mapping
            check(Episodes.climaxTierOf(ep) == "heroic",
                "legacy: a record WITH a tier keeps its own tier")
        }

        // ---------- wiring ----------
        run {
            val gaSrc = File(root,
                "src/com/hunt3r/southparktown/GameActivity.kt").readText()
            check(gaSrc.contains("TalkGate.Rail.CLIMAX") &&
                gaSrc.contains("presentClimaxBeat") &&
                gaSrc.contains("Climaxes.notePhoto") &&
                gaSrc.contains("Climaxes.lookText"),
                "wiring: the Activity hosts the climax dialog, " +
                    "hears the shutter, and routes the Look")
            val engSrc = File(root,
                "src/com/hunt3r/southparktown/Engine.kt").readText()
            check(engSrc.contains("Climaxes.wrap(state, d)") &&
                engSrc.contains("Climaxes.noteStage(state, def, st)") &&
                engSrc.contains("climaxTier = climax?.tier"),
                "wiring: the engine settles climaxes at the wrap " +
                    "and advertises them at the stage hook")
            val tgSrc = File(root,
                "src/com/hunt3r/southparktown/TalkGate.kt").readText()
            val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
            val iFin = gateBody.indexOf("Rail.FINALE")
            val iCx = gateBody.indexOf("Rail.CLIMAX")
            val iDin = gateBody.indexOf("Rail.DINNER")
            check(0 <= iFin && iFin < iCx && iCx < iDin,
                "wiring: the CLIMAX rail sits between FINALE and " +
                    "DINNER in the gate itself")
        }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

private fun sectionV070f(root: String) {
// ================= v0.7.0f: mystery arc #5, "The Two Confessions" =================
// Queue #7 item 6. The fifth case keeps the discipline of the
// first four — chapters on the episode machinery, fair
// evidence, a gated dialogue-safe finale, permanent marks,
// retirement — with a fifth skeleton: CONFESSION FORENSICS.
// Two townsfolk confess, in detail; the investigation is a
// LEDGER of checkable claims, and the board scores claims,
// never people. The shape of the answer is never printed in
// this section beyond what the spoiler scan hunts for; the
// pins below test mechanics (a claim reads only what its
// evidence settled), not the story.
    println("== v0.7.0f: mystery arc #5 — the two confessions ==")
    val eng5 = Engine(7070)
    fun baseInf5(id: String) = FACTIONS.first { it.id == id }.baseInfluence

    // ---------- def integrity ----------
    check(Mystery5.CHAPTERS5.size == 4, "confessions: four chapters")
    check(Mystery5.CHAPTERS5.map { it.id }.distinct().size == 4,
        "confessions: chapter ids are unique")
    check(Mystery5.CHAPTERS5[3].id == Mystery5.FINALE5_ID,
        "confessions: the last chapter is the finale (the confrontation)")
    val regularIds5 = SHENANIGANS.map { it.id }.toSet()
    for (def in Mystery5.CHAPTERS5) {
        check(def.stages.size == 4 && def.causers.isNotEmpty() &&
            def.episodeTitles.size == 2 && def.coldOpen.isNotEmpty() &&
            def.theme.header.isNotBlank(),
            "confessions: ${def.id} carries the full episode kit " +
                "(4 stages, causers, 2 titles, cold open)")
        check(def.id !in regularIds5 && SHENANIGAN_BY_ID[def.id] == def,
            "confessions: ${def.id} is not in the random pool but resolves by id")
        check(def.id !in Mystery.ARC_CHAPTERS.map { it.id } &&
            def.id !in Mystery2.BEATS.map { it.id } &&
            def.id !in Mystery3.CHAPTERS3.map { it.id } &&
            def.id !in Mystery4.CHAPTERS4.map { it.id },
            "confessions: ${def.id} is its own case, not an earlier one")
    }
    check(SHENANIGANS.size == 10, "confessions: the random pool is still the ten")
    check(Mystery5.CHAPTERS5.map { it.stages[2].clusterLoc } ==
        listOf("StarksPond", "CityHall", "JimbosGuns", "CityHall"),
        "confessions: the climaxes gather at the pond, the hall, the shop, the hall")
    check(Mystery5.CHAPTERS5[3].causers.toSet() == Mystery5.CONFESSORS.toSet(),
        "confessions: the finale's causers are BOTH confessors — both in the room")
    check(Mystery5.CONFESSORS.size == 2 &&
        Mystery5.CONFESSORS.all { it in AGENT_PROFILES },
        "confessions: two confessors, both real cast")

    // ---------- the claim registry ----------
    check(Mystery5.CLAIMS5.size == 10, "confessions: ten claims on the ledger")
    check(Mystery5.CLAIMS5.map { it.id }.distinct().size == 10,
        "confessions: claim ids are unique")
    check(Mystery5.CONFESSORS.all { Mystery5.claimsOf(it).size == 5 },
        "confessions: five claims per confession (four checkable, one core)")
    check(Mystery5.CLAIMS5.count { it.clueId != null } == 8 &&
        Mystery5.CLAIMS5.count { it.clueId == null } == 2,
        "confessions: eight claims are checkable; the two cores are not")
    for (claim in Mystery5.CLAIMS5) {
        check(claim.text.isNotBlank(), "confessions: ${claim.id} states itself")
        if (claim.clueId != null) {
            check(claim.clueId in Mystery5.CLUE5_IDS &&
                Mystery5.claimTestedBy(claim.clueId) == claim,
                "confessions: ${claim.id} is tested by real evidence, exactly once")
            check(claim.verdict != Mystery5.Verdict.UNTESTED,
                "confessions: ${claim.id}'s evidence settles it one way or the other")
        } else {
            check(claim.verdict == Mystery5.Verdict.UNTESTED,
                "confessions: ${claim.id} (the taking itself) carries no preset verdict")
        }
    }
    check(Mystery5.claimsOf("Butters").all { it.minChapter == 1 } &&
        Mystery5.claimsOf("Ned").all { it.minChapter == 2 },
        "confessions: claims open WITH their confessions — the first in " +
            "chapter 2, the second (re-opening the case) in chapter 3")

    // ---------- the evidence registry ----------
    check(Mystery5.CLUES5.size == 12, "confessions: twelve pieces of evidence")
    check(Mystery5.CLUES5.map { it.id }.distinct().size == 12 &&
        Mystery5.CLUES5.all { it.id in Mystery5.CLUE5_IDS },
        "confessions: evidence ids are unique")
    check(Mystery5.CLUES5.count { it.kind == Mystery5.Kind5.WITNESS } == 5 &&
        Mystery5.CLUES5.count { it.kind == Mystery5.Kind5.LOOK } == 5 &&
        Mystery5.CLUES5.count { it.kind == Mystery5.Kind5.PARTICIPATION } == 2,
        "confessions: evidence splits 5 tellings / 5 looks / 2 hands-on")
    for (clue in Mystery5.CLUES5) {
        check(clue.detail.isNotBlank(), "confessions: ${clue.id} carries its flavor")
        check(clue.minChapter in 0..2,
            "confessions: ${clue.id} opens inside the investigation chapters")
        when {
            clue.spoken != null -> check(
                clue.npc != null && clue.npc in AGENT_PROFILES,
                "confessions: ${clue.id}'s witness is a real cast member who speaks")
            clue.chapterDefId != null -> check(
                clue.chapterDefId in Mystery5.CHAPTER5_BY_ID,
                "confessions: ${clue.id} is earned at a real confession chapter")
            else -> check(
                clue.locId != null && clue.locId in LOCATIONS &&
                    !clue.foundText.isNullOrBlank(),
                "confessions: ${clue.id} is found at a real location")
        }
    }
    check(Mystery5.CONFRONT_MIN_CLUES in 1 until Mystery5.CLUES5.size,
        "confessions: the confrontation gate sits inside the evidence count")
    check(Mystery5.CHOICE_KEYS.size == 3 &&
        Mystery5.BRANCH_KEYS == Mystery5.CHOICE_KEYS + Mystery5.DEFAULT_BRANCH,
        "confessions: three calls can be made; the fourth is the default")

    // ---------- THE LEDGER INVARIANT ----------
    // A claim reads ONLY what its own evidence settled, and
    // only once that evidence is actually in hand. The core
    // claim of a confession (the taking itself) can never be
    // CONFIRMED by any evidence at all — that asymmetry is
    // the case's whole lesson, pinned over every subset of
    // the eight testable pieces.
    val sLedger0 = eng5.newState()
    sLedger0.arc5Started = true; sLedger0.arc5Chapter = 4
    check(Mystery5.CLAIMS5.all {
        Mystery5.claimStatus(sLedger0, it) == Mystery5.Verdict.UNTESTED },
        "confessions: with no evidence in hand, every claim is UNTESTED — " +
            "however sure the town feels")
    val testableClueIds = Mystery5.CLAIMS5.mapNotNull { it.clueId }
    var subsetsChecked = 0
    for (mask in 0 until (1 shl testableClueIds.size)) {
        val s = eng5.newState()
        for (i in testableClueIds.indices) {
            if (mask and (1 shl i) != 0) s.mystery5Clues.add(testableClueIds[i])
        }
        for (claim in Mystery5.CLAIMS5) {
            val st = Mystery5.claimStatus(s, claim)
            if (claim.clueId != null) {
                val expect = if (claim.clueId in s.mystery5Clues)
                    claim.verdict else Mystery5.Verdict.UNTESTED
                check(st == expect,
                    "confessions: ${claim.id} reads $expect with evidence " +
                        "${s.mystery5Clues} (got $st)")
            } else {
                check(st != Mystery5.Verdict.CONFIRMED,
                    "confessions: the core claim ${claim.id} can NEVER be " +
                        "confirmed by evidence (subset $mask)")
                val own = Mystery5.claimsOf(claim.confessor)
                    .filter { it.clueId != null }
                val allBroken = own.all {
                    Mystery5.claimStatus(s, it) == Mystery5.Verdict.BROKEN }
                check((st == Mystery5.Verdict.BROKEN) == allBroken,
                    "confessions: ${claim.id} breaks exactly when its whole " +
                        "statement has broken (subset $mask)")
            }
        }
        subsetsChecked++
    }
    check(subsetsChecked == 256,
        "confessions: the ledger invariant held over all 256 evidence subsets")
    // granting is the only door in, and it is once-only
    val sGrant = eng5.newState()
    sGrant.arc5Started = true; sGrant.arc5Chapter = 2
    check(Mystery5.grantClue5(sGrant, "dock_dredge") &&
        !Mystery5.grantClue5(sGrant, "dock_dredge") &&
        !Mystery5.grantClue5(sGrant, "not_a_clue"),
        "confessions: evidence grants once, and only real evidence grants")
    check(Mystery5.claimStatus(sGrant,
        Mystery5.CLAIM5_BY_ID.getValue("butters_sank")) == Mystery5.Verdict.BROKEN &&
        Mystery5.claimStatus(sGrant,
            Mystery5.CLAIM5_BY_ID.getValue("butters_alone")) == Mystery5.Verdict.UNTESTED,
        "confessions: one piece of evidence flips exactly its own claim")
    check(sGrant.events.any { it.contains("EVIDENCE 1/12") },
        "confessions: a found piece hits the ticker")

    // ---------- evidence: the witnesses ----------
    val sWit5 = eng5.newState()
    sWit5.arcRetired = true; sWit5.arc2Retired = true; sWit5.arc3Retired = true
    sWit5.arc4Retired = true; sWit5.arc5Started = true; sWit5.arc5Chapter = 2
    check(Mystery5.witnessLine5(sWit5, "Linda")?.speaker == "Linda" &&
        "home_by_five" in sWit5.mystery5Clues,
        "confessions: the mother testifies to the dusk that wasn't")
    check(Mystery5.witnessLine5(sWit5, "Jimbo")?.speaker == "Jimbo" &&
        "lure_true_weight" in sWit5.mystery5Clues,
        "confessions: the weighmaster testifies to the weight that is")
    check(Mystery5.witnessLine5(sWit5, "Scott") == null,
        "confessions: the winner's telling waits for the second confession")
    sWit5.arc5Chapter = 3
    check(Mystery5.witnessLine5(sWit5, "Scott")?.speaker == "Scott" &&
        "carried_witness" in sWit5.mystery5Clues,
        "confessions: the winner followed the plaque the whole way")
    check(Mystery5.witnessLine5(sWit5, "McDaniels")?.speaker == "McDaniels" &&
        "dock_window" in sWit5.mystery5Clues,
        "confessions: the Mayor's office logged the quiet ten minutes")
    check(Mystery5.witnessLine5(sWit5, "Barbrady")?.speaker == "Barbrady" &&
        "herring_dusk" in sWit5.mystery5Clues,
        "confessions: the patrolman's dusk accounts for the herring")
    check(Mystery5.witnessLine5(sWit5, "Butters") == null &&
        Mystery5.witnessLine5(sWit5, "Ned") == null &&
        Mystery5.witnessLine5(sWit5, "Cartman") == null,
        "confessions: neither confessor is a witness in their own case")
    check(Mystery5.witnessLine5(sWit5, "Linda") == null,
        "confessions: a telling is once-only (the grant already landed)")

    // ---------- the statements, reheard ----------
    val sStmt = eng5.newState()
    sStmt.arc5Started = true; sStmt.arc5Chapter = 1
    check(Mystery5.confessionLine5(sStmt, "Butters") == null,
        "confessions: no statement exists before the first confession")
    sStmt.arc5Chapter = 2
    check(Mystery5.confessionLine5(sStmt, "Butters")?.speaker == "Butters",
        "confessions: the first statement can be re-heard once made")
    check(Mystery5.confessionLine5(sStmt, "Ned") == null,
        "confessions: the second statement doesn't exist yet — the case " +
            "still thinks it's solved")
    sStmt.arc5Chapter = 3
    check(Mystery5.confessionLine5(sStmt, "Ned")?.speaker == "Ned",
        "confessions: the second statement joins the record in chapter 3")
    val stmtA = Mystery5.confessionLine5(sStmt, "Butters")!!.text
    sStmt.absDay += 1
    check(Mystery5.confessionLine5(sStmt, "Butters")!!.text != stmtA,
        "confessions: the rehearing rotates by the day")
    sStmt.arc5Retired = true
    check(Mystery5.confessionLine5(sStmt, "Butters") == null,
        "confessions: once the case closes, the statements rest")

    // ---------- evidence: looks ----------
    val sLook5 = eng5.newState()
    sLook5.arc5Started = true; sLook5.arc5Chapter = 1
    check(Mystery5.lookClueText5(sLook5, "CityHall") == null,
        "confessions: no finds before the first confession opens the file")
    sLook5.arc5Chapter = 2
    check(Mystery5.lookClueText5(sLook5, "CityHall") != null &&
        "plaque_rivets" in sLook5.mystery5Clues,
        "confessions: the plaque in the drawer is RIVETED, up close")
    check(Mystery5.lookClueText5(sLook5, "StarksPond") != null &&
        "dock_dredge" in sLook5.mystery5Clues,
        "confessions: the dredged pond gave back everything but a lure")
    sLook5.arc5Chapter = 3
    check(Mystery5.lookClueText5(sLook5, "CityHall") != null &&
        "record_weight" in sLook5.mystery5Clues,
        "confessions: the record book's first page out-waits everybody")
    check(Mystery5.lookClueText5(sLook5, "JimbosGuns") != null &&
        "polish_cloth" in sLook5.mystery5Clues,
        "confessions: the snagged cloth is on the back counter")
    check(Mystery5.lookClueText5(sLook5, "JimbosGuns") != null &&
        "fake_making" in sLook5.mystery5Clues,
        "confessions: the fake, appraised — days of work, school-bottle gold")
    check(Mystery5.lookClueText5(sLook5, "JimbosGuns") == null &&
        Mystery5.lookClueText5(sLook5, "Bank") == null,
        "confessions: the shop holds exactly its two finds; the Bank none")

    // ---------- evidence: participation ----------
    val sPart5 = eng5.newState()
    sPart5.arc5Started = true; sPart5.arc5Chapter = 1
    sPart5.shenaniganId = Mystery5.CHAPTERS5[0].id
    sPart5.shenaniganDay = sPart5.todayKey
    sPart5.timeMin = 60
    eng5.player(sPart5).location = "StarksPond"
    eng5.bumpParticipation(sPart5, "StarksPond")
    check("plaque_light" in sPart5.mystery5Clues,
        "confessions: holding the plaque at the handover earns its lightness")
    val sPart5b = eng5.newState()
    sPart5b.arc5Started = true; sPart5b.arc5Chapter = 3
    sPart5b.shenaniganId = Mystery5.CHAPTERS5[2].id
    sPart5b.shenaniganDay = sPart5b.todayKey
    sPart5b.timeMin = 60
    eng5.player(sPart5b).location = "JimbosGuns"
    eng5.bumpParticipation(sPart5b, "JimbosGuns")
    check("till_ledger" in sPart5b.mystery5Clues,
        "confessions: inventory night earns the ledger — the wrong gold, receipted")
    val sFar5 = eng5.newState()
    sFar5.arc5Started = true; sFar5.arc5Chapter = 1
    sFar5.shenaniganId = Mystery5.CHAPTERS5[0].id
    sFar5.shenaniganDay = sFar5.todayKey; sFar5.timeMin = 60
    eng5.player(sFar5).location = "Mall"
    eng5.bumpParticipation(sFar5, "Mall")
    check(sFar5.mystery5Clues.isEmpty(),
        "confessions: no finds away from a chapter's turf")

    // ---------- both confessions fully checkable; the standing evidence ----------
    // Every checkable claim's evidence is reachable through
    // its own channel — so a complete ledger is assemble-able
    // in one playthrough, and the board can reach its final
    // shape: one core BROKEN, the other core standing.
    val sFull = eng5.newState()
    sFull.arc5Started = true; sFull.arc5Chapter = 4
    for (clue in Mystery5.CLUES5) Mystery5.grantClue5(sFull, clue.id)
    check(Mystery5.clueCount5(sFull) == 12,
        "confessions: the full evidence set is grantable")
    check(Mystery5.collapsedConfessor(sFull) == "Butters",
        "confessions: with everything in hand, exactly one confession " +
            "has collapsed claim by claim")
    check(Mystery5.claimStatus(sFull,
        Mystery5.CLAIM5_BY_ID.getValue("ned_took")) == Mystery5.Verdict.UNTESTED &&
        Mystery5.claimsOf("Ned").filter { it.clueId != null }.all {
            Mystery5.claimStatus(sFull, it) == Mystery5.Verdict.CONFIRMED },
        "confessions: the surviving confession survives in every part — " +
            "and its core STILL reads untested. Surviving isn't guilty.")
    val boardFull = Mystery5.boardLines5(sFull)
    check(boardFull.any { it.contains("BUTTERS") && it.contains("LEDGER") } &&
        boardFull.any { it.contains("NED") && it.contains("LEDGER") } &&
        boardFull.any { it.contains("✔ CONFIRMED") } &&
        boardFull.any { it.contains("✖ BROKEN") },
        "confessions: the board carries both ledgers, scored in the open")
    check(!Mystery5.boardVisible5(eng5.newState()),
        "confessions: no board before the case exists")

    // ---------- scheduling: behind the gardener, always ----------
    val sGate5 = eng5.newState()
    sGate5.absDay = 500
    check(Mystery5.dueChapter5(sGate5) == null && sGate5.arc5DueAbsDay == -1,
        "confessions: the case does not even schedule behind an open season arc")
    sGate5.arcRetired = true; sGate5.arc2Retired = true; sGate5.arc3Retired = true
    check(Mystery5.dueChapter5(sGate5) == null && sGate5.arc5DueAbsDay == -1,
        "confessions: nor behind the booth, buried or gardener cases")
    sGate5.arc4Retired = true; sGate5.arc4RetiredDay = 480
    sGate5.absDay = 485
    check(Mystery5.dueChapter5(sGate5) == null && sGate5.arc5DueAbsDay == 490,
        "confessions: chapter 1 books ten days after the gardener retires")
    sGate5.absDay = 489
    check(Mystery5.dueChapter5(sGate5) == null, "confessions: chapter 1 is never early")
    sGate5.absDay = 490
    check(Mystery5.dueChapter5(sGate5)?.id == Mystery5.CHAPTERS5[0].id,
        "confessions: on the booked day, derby day is due")
    sGate5.holidayId = "christmas"
    check(Mystery5.dueChapter5(sGate5) == null,
        "confessions: a holiday keeps its day — the chapter defers")
    sGate5.holidayId = null
    check(Mystery5.dueChapter5(sGate5)?.id == Mystery5.CHAPTERS5[0].id,
        "confessions: and airs the day after the holiday")
    for (i in 0 until Mystery5.CHAPTERS5.size) {
        Mystery5.noteChapterStarted5(sGate5, Mystery5.CHAPTERS5[i])
        check(sGate5.arc5Chapter == i + 1,
            "confessions: chapter ${i + 1} is booked as it airs")
        sGate5.absDay = sGate5.arc5DueAbsDay - 1
        check(Mystery5.dueChapter5(sGate5) == null,
            "confessions: chapter ${i + 2} respects the week's gap")
        sGate5.absDay = sGate5.arc5DueAbsDay
        check(Mystery5.dueChapter5(sGate5)?.id ==
            Mystery5.CHAPTERS5.getOrNull(i + 1)?.id,
            "confessions: chapter ${i + 2} is due a week on")
    }
    check(Mystery5.dueChapter5(sGate5) == null,
        "confessions: nothing is due past the confrontation")

    // ---------- the confrontation gate ----------
    fun confState(clues: Int): GameState {
        val s = eng5.newState()
        s.arcRetired = true; s.arc2Retired = true; s.arc3Retired = true
        s.arc4Retired = true; s.arc5Started = true; s.arc5Chapter = 4
        s.shenaniganId = Mystery5.FINALE5_ID
        s.shenaniganDay = s.todayKey
        for (c in Mystery5.CLUES5.take(clues)) s.mystery5Clues.add(c.id)
        return s
    }
    val finDef5 = Mystery5.CHAPTER5_BY_ID[Mystery5.FINALE5_ID]!!
    check(!Mystery5.confrontationDue(confState(7).apply { timeMin = 19 * 60 }),
        "confessions: seven pieces is NOT enough to face them both")
    check(!Mystery5.confrontationDue(confState(8).apply { timeMin = 10 * 60 }),
        "confessions: the confrontation waits for the climax stage, not the morning")
    val sConf = confState(8); sConf.timeMin = 19 * 60
    check(Mystery5.confrontationDue(sConf),
        "confessions: eight pieces at the climax opens the confrontation (the boundary)")
    check(Finales.climaxPending(sConf),
        "confessions: a due confrontation holds the season finales' calls, like every climax")
    check(!Mystery5.confrontationDue(confState(10).apply {
        timeMin = 19 * 60; shenaniganId = Mystery5.CHAPTERS5[0].id }),
        "confessions: the confrontation belongs to the last chapter alone")
    check(!Mystery5.chooseConfrontation(sConf, "maybe"),
        "confessions: only the three calls can be made in that room")
    check(Mystery5.chooseConfrontation(sConf, "clear") && sConf.arc5Choice == "clear",
        "confessions: a call can be locked at the confrontation")
    check(!Mystery5.confrontationDue(sConf) &&
        !Mystery5.chooseConfrontation(sConf, "name"),
        "confessions: a locked call closes the confrontation")

    // ---------- the wrap: four landings ----------
    fun wrappedConf(clues: Int, choice: String): GameState {
        val s = confState(clues)
        s.arc5Choice = choice
        Episodes.beginEvent(s, finDef5)
        s.lastEventWeek = 39
        s.timeMin = 1430
        eng5.advanceTime(s)
        return s
    }
    // CLEAR: both set aside on the evidence — and the long tail
    val sClearBase = confState(12)
    sClearBase.arc5Choice = "clear"
    sClearBase.friendship["Butters"] = 10
    sClearBase.friendship["Ned"] = 10
    sClearBase.friendship["Jimbo"] = 10
    Episodes.beginEvent(sClearBase, finDef5)
    sClearBase.lastEventWeek = 39
    sClearBase.timeMin = 1430
    eng5.advanceTime(sClearBase)
    val sClear = sClearBase
    check(sClear.arc5Retired && sClear.arc5Branch == "clear",
        "confessions: clearing retires the case on the evidence")
    check(sClear.episodes.last { it.eventId == Mystery5.FINALE5_ID }
        .recap.any { it.contains("CLEARED, ON THE EVIDENCE") },
        "confessions: the cleared ending's credits say what the call was")
    check((sClear.friendship["Butters"] ?: 0) == 13 &&
        (sClear.friendship["Ned"] ?: 0) == 13 &&
        (sClear.friendship["Jimbo"] ?: 0) == 12,
        "confessions: the cleared warm to the one who read the ledger (+3/+3/+2)")
    check(sClear.lifeText["mark:StarksPond"]?.contains("believed neither") == true &&
        Mystery5.statusStamp5(sClear).contains("CLEARED"),
        "confessions: the pond keeps the clearing's mark")
    check(sClear.arc5LurePending && !sClear.arc5LureReturned,
        "confessions: after a clearing, something is still out there")
    check(!Mystery5.noteLureReturned(sClear),
        "confessions: it does not come home the same week it was cleared")
    sClear.absDay += Mystery5.LURE_RETURN_DELAY_DAYS
    check(Mystery5.noteLureReturned(sClear) && sClear.arc5LureReturned &&
        !sClear.arc5LurePending,
        "confessions: a week on, the lure comes home — anonymously")
    check(sClear.lifeText["mark:StarksPond"]?.contains("back on its plaque") == true &&
        Mystery5.boardLines5(sClear).any { it.contains("came home") },
        "confessions: the pond and the board record the homecoming")
    check(!Mystery5.noteLureReturned(sClear),
        "confessions: the homecoming lands exactly once")
    check(Mystery5.aftermathLine5(sClear, "Ned")?.speaker == "Ned" &&
        Mystery5.aftermathLine5(sClear, "Butters")?.speaker == "Butters",
        "confessions: in the cleared town, both have their thank-you to say")
    val thanksA = Mystery5.aftermathLine5(sClear, "Ned")!!.text
    sClear.absDay += 1
    check(Mystery5.aftermathLine5(sClear, "Ned")!!.text != thanksA,
        "confessions: the thank-you rotates by the day (standing, not stuck)")

    // BELIEVE: the survivor's word taken — a scar and a standing objection
    val sBelBase = confState(11)
    sBelBase.arc5Choice = "believe"
    sBelBase.friendship["Ned"] = 20
    Episodes.beginEvent(sBelBase, finDef5)
    sBelBase.lastEventWeek = 39
    sBelBase.timeMin = 1430
    eng5.advanceTime(sBelBase)
    val sBelieve = sBelBase
    check(sBelieve.arc5Retired && sBelieve.arc5Branch == "believe",
        "confessions: believing retires the case on the survivor's word")
    check((sBelieve.friendship["Ned"] ?: 0) == 20 - Mystery5.BELIEVE_SCAR,
        "confessions: being believed costs him anyway (-${Mystery5.BELIEVE_SCAR}) — " +
            "a name in a file is a name in a file")
    check(sBelieve.lifeText["mark:CityHall"]?.contains("Ned's") == true &&
        Mystery5.statusStamp5(sBelieve).contains("BELIEVED"),
        "confessions: the hall keeps the belief's mark")
    check(!sBelieve.arc5LurePending && !sBelieve.arc5LureReturned,
        "confessions: no homecoming follows a believed file")
    check(Mystery5.aftermathLine5(sBelieve, "Jimbo")?.speaker == "Jimbo" &&
        Mystery5.aftermathLine5(sBelieve, "Ned") == null,
        "confessions: in the believed town, the objection stands — " +
            "from the best friend, to your face, forever")

    // NAME: the collapsed one named — a bigger scar, a mother's objection
    val sNameBase5 = confState(12)
    sNameBase5.arc5Choice = "name"
    sNameBase5.friendship["Butters"] = 20
    Episodes.beginEvent(sNameBase5, finDef5)
    sNameBase5.lastEventWeek = 39
    sNameBase5.timeMin = 1430
    eng5.advanceTime(sNameBase5)
    val sNamed = sNameBase5
    check(sNamed.arc5Retired && sNamed.arc5Branch == "name",
        "confessions: naming retires the case on the collapsed story")
    check((sNamed.friendship["Butters"] ?: 0) == 20 - Mystery5.NAME_SCAR,
        "confessions: the named one carries the grounding (-${Mystery5.NAME_SCAR})")
    check(sNamed.lifeText["mark:CityHall"]?.contains("Butters'") == true &&
        Mystery5.statusStamp5(sNamed).contains("NAMED"),
        "confessions: the hall keeps the naming's mark")
    check(Mystery5.aftermathLine5(sNamed, "Linda")?.speaker == "Linda" &&
        Mystery5.aftermathLine5(sNamed, "Butters") == null,
        "confessions: in the named town, the objection stands — " +
            "from his mother, standing in her doorway")
    check(sNamed.episodes.last { it.eventId == Mystery5.FINALE5_ID }
        .outcome.contains("grounded") == true,
        "confessions: the naming's outcome carries the cost, plainly")

    // COLD: no call was ever made
    val sCold5 = wrappedConf(4, "")
    check(sCold5.arc5Retired && sCold5.arc5Branch == "cold",
        "confessions: an unmade call lets the file go cold on its own")
    check(sCold5.lifeText["mark:StarksPond"]?.contains("catching the light wrong") == true,
        "confessions: the cold case's mark is the fake still hanging")
    check(Mystery5.aftermathLine5(sCold5, "Linda") == null &&
        Mystery5.aftermathLine5(sCold5, "Jimbo") == null &&
        Mystery5.aftermathLine5(sCold5, "Ned") == null,
        "confessions: in the cold town, nobody has a standing line — " +
            "nobody was given anything to stand on")

    // DEGRADED: a call locked without the evidence behind it
    // (impossible through the UI — confrontations never open
    // early) settles cold rather than free.
    val sDegraded = wrappedConf(5, "clear")
    check(sDegraded.arc5Retired && sDegraded.arc5Branch == "cold",
        "confessions: an unbacked call degrades to cold at the wrap")

    // ---------- endings persist & speak ----------
    for ((s, branch) in listOf(sClear to "clear", sBelieve to "believe",
        sNamed to "name", sCold5 to "cold")) {
        check(Mystery5.ambientCallback5(s, Random(5)) != null &&
            Mystery5.statusStamp5(s).isNotBlank() &&
            Mystery5.currentTheory5(s).contains("file", ignoreCase = true),
            "confessions: the '$branch' ending lives on — callbacks, " +
                "stamp, and the town's settled version")
    }
    check(Mystery5.ambientCallback5(eng5.newState(), Random(5)) == null,
        "confessions: no callbacks before the case closes")

    // ---------- saves: additive, round-trip, pre-0.7.0f ----------
    val sSave5 = eng5.newState()
    sSave5.arcRetired = true; sSave5.arc2Retired = true; sSave5.arc3Retired = true
    sSave5.arc4Retired = true; sSave5.arc4RetiredDay = 60
    sSave5.arc5Started = true; sSave5.arc5Chapter = 3
    sSave5.arc5DueAbsDay = 88
    sSave5.mystery5Clues.addAll(listOf("plaque_light", "dock_dredge", "home_by_five"))
    val back5 = decodeGameState(encodeGameState(sSave5))
    check(back5.arc5Started && back5.arc5Chapter == 3 &&
        back5.arc5DueAbsDay == 88 && !back5.arc5Retired &&
        back5.mystery5Clues == sSave5.mystery5Clues,
        "confessions: a mid-case save round-trips chapter, due day and evidence")
    val docOld5 = encodeGameState(sSave5).toMutableMap()
    docOld5.remove("arc5"); docOld5.remove("mystery5Clues")
    val backOld5 = decodeGameState(docOld5)
    check(!backOld5.arc5Started && backOld5.arc5Chapter == 0 &&
        backOld5.mystery5Clues.isEmpty() && !backOld5.arc5Retired,
        "confessions: a pre-v0.7.0f save loads with the fifth case " +
            "simply not yet queued")
    val sDone5 = eng5.newState()
    sDone5.arc5Retired = true; sDone5.arc5Branch = "clear"
    sDone5.arc5LureReturned = true
    val backDone5 = decodeGameState(encodeGameState(sDone5))
    check(backDone5.arc5Retired && backDone5.arc5Branch == "clear" &&
        backDone5.arc5LureReturned,
        "confessions: a closed case (and its homecoming) round-trips")

    // ---------- the five-case lifetime, driven ----------
    // One unattended life, day by day: the cases must queue
    // strictly one behind the next and ALL retire — the
    // fifth included — with the slot empty at the end.
    val engLife5 = Engine(5150)
    val life5 = engLife5.newState()
    var lifeDays = 0
    var arc5StartedAfterArc4 = false
    while (lifeDays < 900 && !(life5.arcRetired && life5.arc2Retired &&
        life5.arc3Retired && life5.arc4Retired && life5.arc5Retired)) {
        engLife5.onNewDay(life5)
        if (life5.arc5Started && life5.arc4Retired) arc5StartedAfterArc4 = true
        if (life5.arc5Started) {
            check(life5.arc4Retired,
                "confessions: the fifth case never opens over the fourth " +
                    "(day $lifeDays)")
        }
        lifeDays++
    }
    check(life5.arc5Retired && life5.arc5Branch in Mystery5.BRANCH_KEYS,
        "confessions: all five cases retired in one lifetime " +
            "(arc #5 branch '${life5.arc5Branch}' after $lifeDays days)")
    check(arc5StartedAfterArc4 && Mystery5.dueChapter5(life5) == null,
        "confessions: the fifth case opened only behind the fourth, " +
            "and nothing demands the slot after it")

    // ---------- wiring ----------
    val mystery5Src = File(root, "src/com/hunt3r/southparktown/Mystery5.kt").readText()
    val engineSrc5 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val gameActivitySrc5 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc5 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val prefsSrc5 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc5 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    val talkGateSrc5 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val finalesSrc5 = File(root, "src/com/hunt3r/southparktown/Finales.kt").readText()
    val movieSrc5 = File(root, "src/com/hunt3r/southparktown/MovieNights.kt").readText()
    val walkSrc5 = File(root, "src/com/hunt3r/southparktown/Walk.kt").readText()
    val schoolSrc5 = File(root, "src/com/hunt3r/southparktown/School.kt").readText()
    check(!mystery5Src.contains("import android"),
        "confessions: Mystery5.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc5.contains("Mystery5.dueChapter5") &&
        engineSrc5.contains("Mystery5.resolveConfrontation") &&
        engineSrc5.contains("Mystery5.noteParticipation5") &&
        engineSrc5.contains("Mystery5.noteLureReturned") &&
        engineSrc5.contains("Mystery5.ambientCallback5"),
        "confessions: the engine airs the chapters, resolves the " +
            "confrontation, feeds participation, lands the homecoming, " +
            "keeps the callbacks")
    check(talkGateSrc5.contains("Mystery5.witnessLine5") &&
        talkGateSrc5.contains("Mystery5.confessionLine5") &&
        talkGateSrc5.contains("Mystery5.aftermathLine5") &&
        gameActivitySrc5.contains("Mystery5.lookClueText5") &&
        gameActivitySrc5.contains("Mystery5.chooseConfrontation") &&
        gameActivitySrc5.contains("maybeShowConfrontation"),
        "confessions: TalkGate and GameActivity wire the tellings, " +
            "the statements, the aftermath, the looks, the confrontation")
    check(journalSrc5.contains("Mystery5.boardLines5"),
        "confessions: the Journal renders the fifth case's board")
    check(prefsSrc5.contains("\"arc5\" to mapOf") &&
        prefsSrc5.contains("\"mystery5Clues\" to"),
        "confessions: the save doc carries the fifth case additively")
    check(shenanigansSrc5.contains("Mystery5.CHAPTERS5"),
        "confessions: the fifth case's chapters resolve by id")
    check(finalesSrc5.contains("Mystery5.confrontationDue") &&
        movieSrc5.contains("Mystery5.confrontationDue") &&
        walkSrc5.contains("Mystery5.confrontationDue") &&
        schoolSrc5.contains("Mystery5.confrontationDue"),
        "confessions: every deference list stands down for the " +
            "confrontation — two climaxes never stack")

    // ---------- version ----------
    val manifestSrc5 = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc5.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc5.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "confessions: the manifest carries 67 / 0.9.0a")

    // ---------- THE SPOILER WALL ----------
    // Nothing the player can read before the confrontation's
    // own payoff may state or imply the answer: no return, no
    // motive, no verdict on either confession, no maker. The
    // scan covers the chapters, the evidence text, the
    // statements, the mid-case board, and the changelog entry.
    val banned5 = listOf("neither of them did", "both innocent",
        "false confession", "protecting jimbo", "shield",
        "came back", "comes back", "brought it back",
        "gave it back", "doorstep", "bait-shop step",
        "exonerate", "didn't do it", "did not do it")
    val preReveal5 = mutableListOf<String>()
    for (def in Mystery5.CHAPTERS5) {
        preReveal5.add(def.title); preReveal5.add(def.cause); preReveal5.add(def.blurb)
        for (st in def.stages) {
            preReveal5.add(st.title); preReveal5.add(st.banner)
            preReveal5.add(st.journalNote); preReveal5.add(st.objective)
        }
        for (l in def.coldOpen) preReveal5.add(l.text)
    }
    for (clue in Mystery5.CLUES5) {
        preReveal5.add(clue.title); preReveal5.add(clue.detail)
        clue.spoken?.let { preReveal5.add(it) }
        clue.foundText?.let { preReveal5.add(it) }
    }
    val sMid5 = eng5.newState()
    sMid5.arc5Started = true; sMid5.arc5Chapter = 3
    for (clueId in listOf("plaque_light", "plaque_rivets", "dock_dredge",
        "home_by_five", "lure_true_weight", "carried_witness",
        "polish_cloth", "fake_making")) {
        Mystery5.grantClue5(sMid5, clueId)
    }
    preReveal5.addAll(Mystery5.boardLines5(sMid5))
    for (who in Mystery5.CONFESSORS) {
        Mystery5.confessionLine5(sMid5, who)?.let { preReveal5.add(it.text) }
        sMid5.absDay += 1
        Mystery5.confessionLine5(sMid5, who)?.let { preReveal5.add(it.text) }
    }
    val readme5 = File(root, "docs/CHANGELOG.md").readText()
    val entry5 = readme5.substringAfter("### v0.7.0f")
        .substringBefore("### v0.7.0e")
    preReveal5.add(entry5)
    for (term in banned5) {
        check(preReveal5.none { it.contains(term, ignoreCase = true) },
            "confessions: no pre-reveal surface breathes '$term' " +
                "(the wall holds: premise and claims only)")
    }
    check(entry5.contains("Two Confessions") && entry5.contains("ledger"),
        "confessions: the changelog carries the premise and the shape — and stops there")
}


// ================= v0.7.0g: polish & performance pass #7 =================
// The Queue #7 audit, same discipline as passes #1–#6:
// measure the queue's surfaces the way the town actually
// lives them, tighten what the measuring exposes, change
// no behavior. The lifetime soak grew the full set in
// sectionV030g (secrets under their gates, movie nights,
// school days, climaxes PLAYED, a five-case lifetime);
// this section carries veteran save VI, the newest
// screens' fit, the nine-rail gate in its final form,
// the queue's seams, the sixth distance check on the peak
// budget, and the tuning-ledger sweep.
private fun sectionV070g(root: String) {
    println("== v0.7.0g: polish & performance pass #7 — the Queue #7 audit ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.7.0g"),
        "v0.7.0g: the README carries this build's changelog entry")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.7.0g: the source tree and its description agree — " +
            "97 Kotlin files (counted $ktCount; the count moved " +
            "with v0.10.0c's Play.kt, v0.10.0d's " +
            "GroupChats.kt, v0.10.0e's Stand.kt and " +
            "v0.10.0f's Mystery8.kt, v0.11.0c's " +
            "Sleepovers.kt and v0.11.0d's CastDataWave6.kt, the pin " +
            "updated in place)")

    // Play the open climax chain the way the dialog chain
    // does — sessionBeat by sessionBeat, judging through
    // the module's own verbs (sectionV070e's driver, kept
    // local here for the contention stack and the seam).
    fun playChainQ7(s: GameState, heroic: Boolean): Boolean {
        var guard = 0
        while (guard++ < 60) {
            val beat = Climaxes.sessionBeat(s) ?: return false
            when (beat.kind) {
                "intro" -> Climaxes.begin(s)
                "result" -> Climaxes.advance(s)
                "done" -> return true
                "choice" -> {
                    val cb = Climaxes.currentBeat(s) ?: return false
                    val pick = if (heroic)
                        cb.options.indices.maxByOrNull {
                            cb.options[it].score }!!
                    else
                        cb.options.indices.minByOrNull {
                            cb.options[it].score }!!
                    Climaxes.choose(s, pick)
                }
                "stand" -> {
                    val esc = Climaxes.currentEscalation(s)
                        ?: return false
                    val pick = if (heroic) esc.holdIndex
                    else esc.options.indices.first {
                        it != esc.holdIndex }
                    Climaxes.standChoose(s, pick)
                }
                "task" -> {
                    val cb = Climaxes.currentBeat(s) ?: return false
                    if (heroic) {
                        when (cb.kind) {
                            Climaxes.KIND_PHOTO -> Climaxes.notePhoto(
                                s, Climaxes.climaxLoc(
                                    SHENANIGAN_BY_ID[s.shenaniganId!!]!!)!!)
                            Climaxes.KIND_FIND ->
                                Climaxes.lookText(s, cb.findLoc)
                        }
                        if (Climaxes.taskAction(s, 0) != null)
                            return false
                    } else Climaxes.taskAction(s, 1)
                }
                else -> return false
            }
        }
        return false
    }
    // Drive an entered bee to its record, spelling perfectly.
    fun playBeeQ7(s: GameState): Boolean {
        if (!School.enterBee(s)) return false
        var guard = 0
        while (guard++ < 400) {
            val beat = School.beeBeat(s) ?: break
            when (beat.kind) {
                "letter" -> {
                    val word = School.currentWord(s)
                    val idx = School.spellingProgress(s)
                        .split(" ").count { it != "_" }
                    School.pickLetter(s, word[idx])
                }
                "done" -> { School.advanceBee(s); break }
                else -> School.advanceBee(s)
            }
        }
        return School.beeRecordFor(s, s.absDay) != null
    }

    run {
        // ---------- veteran save VI ----------
        // The veteran V body, carried whole, with Queue #7's
        // state laid over it at its own caps: all twelve
        // secrets found, a movie history counted full, the
        // school histories at their caps, climax tiers on
