                trigger = Phone.HELLO, absDay = 699, dayKey = "20280615",
                text = "A maximally long town text about absolutely everything " +
                    "that happened today, in complete detail, with opinions ($seq)".padEnd(280, '·'),
                read = k % 3 != 0))
        }
        for (kind in listOf(Phone.FEAT, Phone.PHOTO, Phone.ERRAND, Phone.PULL))
            repeat(6) { vet.phoneNotes.add("699|$kind|Stan|") }
        vet.phoneMeta["seq"] = seq
        vet.phoneMeta["lastRoll"] = 699
        vet.phoneMeta["replies"] = 3
        for (def in Finales.DEFS) {
            vet.lifeText["finMark:${def.id}"] = def.choices[0].markText
            vet.life["finMarkYear:${def.id}"] = 2028
            vet.lifeText["finMarkBy:${def.id}"] = "you"
            vet.lifeText["finMarkWinner:${def.id}"] = def.choices[0].winner
            vet.life["fin:${def.id}:2028:mask"] =
                (1 shl def.steps.size) - 1
            vet.life["fin:${def.id}:2028:choice"] = 0
            vet.life["fin:${def.id}:2028:done"] = 1
            vet.life["finRuns:${def.id}"] = 2
            vet.life["finPlayed:${def.id}"] = 2
        }
        val castListV = CharacterSystem.CAST.keys.toList()
        repeat(Commissions.STATE_CAP) { i ->
            vet.commissions.add(Commission(
                id = "c290:$i", asker = castListV[i % 54],
                subjects = listOf(castListV[(i + 5) % 54]),
                locId = "MainStreet", condKind = "", condValue = "",
                text = "The longest-standing commission in town, part $i.",
                pay = 5, week = 290, acceptedDay = 699,
                expiresDay = 706, done = i >= Commissions.MAX_PLATE))
        }
        vet.commissionsDone = 500
        repeat(Commissions.RECENT_CAP) { i ->
            vet.commissionRecent.add(CommissionNote("c28$i:0", "20280614",
                "✔ The longest print run in town — a print for a friend ($i)"))
        }
        vet.photos.forEachIndexed { i, p ->
            if (i % 6 == 0) {
                p.commissionAsker = "Stan"
                p.commissionText = "The longest-standing commission in town."
            }
        }
        for (h in Dinners.HOUSEHOLDS) {
            vet.life["dinAttended:${h.id}"] = 60
            vet.life["dinHosted:${h.id}"] = 25
        }
        repeat(10) {
            val q = Votes.currentQuestion(vet)
            Votes.castVote(vet, q.options[it % q.options.size].id)
            vet.absDay += 7
            Votes.dailyRollover(vet)
        }
        vet.lifeText["jobId"] = "shop"
        vet.life["jobSince"] = 100
        vet.life["jobShifts"] = 300
        vet.life["jobStreak"] = 12
        vet.life["jobMissStreak"] = 0
        vet.life["jobWeekPay"] = 250
        vet.life["jobEarned"] = 99999
        vet.lifeText["jobPaydayLine"] =
            "💼 Payday: a long season of shifts, settled in full."
        vet.life["jobTotal:farm"] = 200
        vet.life["jobTotal:paper"] = 200
        vet.life["jobTotal:shop"] = 200
        vet.life["jobShiftDay"] = vet.absDay
        vet.life["jobClocked"] = 0
        vet.life["jobShiftDone"] = 1
        vet.life["jobMask"] = 7
        vet.life["jobSettledDay"] = vet.absDay - 1
        // ---- Queue #7's state, at its caps ----
        // every secret found, each with its discovery record
        for ((i, secret) in Secrets.SECRETS.withIndex()) {
            vet.lifeText["secret:${secret.id}"] =
                "${600 + i}|${secret.locId ?: "MainStreet"}"
        }
        // a movie history counted full: twelve nights across
        // all four buzz tiers, in the module's own record
        // format, with the lifetime counters deep
        val tierCycle = listOf(MovieNights.TIER_LEGENDARY,
            MovieNights.TIER_BUZZING, MovieNights.TIER_POLITE,
            MovieNights.TIER_DEAD)
        val buzzFor = mapOf(MovieNights.TIER_LEGENDARY to 6,
            MovieNights.TIER_BUZZING to 5,
            MovieNights.TIER_POLITE to 3,
            MovieNights.TIER_DEAD to 0)
        val movieRecs = (0 until MovieNights.HISTORY_CAP).map { i ->
            val tier = tierCycle[i % tierCycle.size]
            listOf((640 + i).toString(), "s${i % 8}",
                "The Longest Feature In Town, Part ${i + 1}",
                listOf(KID_ORDER[i % KID_ORDER.size],
                    KID_ORDER[(i + 3) % KID_ORDER.size])
                    .joinToString(","),
                tier, buzzFor[tier].toString()).joinToString("|")
        }
        movieRecs.forEachIndexed { i, rec ->
            vet.lifeText["movieRec:${640 + i}"] = rec }
        vet.lifeText["movieHistory"] = movieRecs.joinToString(";")
        vet.life["movieAttended"] = 120
        vet.life["movieBestBuzz"] = MovieNights.BUZZ_LEGENDARY
        // the school histories at their caps, and the
        // lifetime counters deep
        vet.lifeText["schoolHist"] =
            (0 until School.HISTORY_CAP).joinToString(";") { i ->
                "${600 + i}|" +
                    School.TOPICS[i % School.TOPICS.size].id +
                    "|${listOf("right", "funny", "pass")[i % 3]}" }
        vet.lifeText["beeHist"] =
            (0 until School.BEE_HISTORY_CAP).joinToString(";") { i ->
                "${601 + i * 7}|${if (i % 3 == 0) 1 else 0}|" +
                    "${2 + i % 5}|${KID_ORDER[i % KID_ORDER.size]}" }
        vet.lifeText["recessHist"] =
            (0 until School.RECESS_HISTORY_CAP).joinToString(";") { i ->
                "${600 + i}|" +
                    School.RECESS_BEATS[i % School.RECESS_BEATS.size].id }
        vet.life["school:lessons"] = 400
        vet.life["school:recess"] = 200
        vet.life["school:beeIn"] = 60
        vet.life["school:beeWon"] = 20
        vet.life["school:beeBest"] = 8
        // the fifth case, closed, its full evidence set held
        for (c in Mystery5.CLUES5) vet.mystery5Clues.add(c.id)
        vet.arc5Started = true; vet.arc5Chapter = 4
        vet.arc5Retired = true
        vet.arc5Branch = Mystery5.DEFAULT_BRANCH
        vet.arc5RetiredDay = 698; vet.arc5DueAbsDay = -1
        val vetJson = Json.stringify(encodeGameState(vet))
        println("veteran VI game_state: ${vetJson.length} chars serialized")
        check(vetJson.length < 512 * 1024,
            "veteran VI: the saturated save (Queue #7 included) stays " +
                "under the 512K ceiling (got ${vetJson.length})")
        check(vetJson.length > 326_133,
            "veteran VI: today's full state outgrows veteran V's " +
                "326,133 — the growth is the queue's own records, " +
                "each one capped (got ${vetJson.length})")
        @Suppress("UNCHECKED_CAST")
        val vetBack = decodeGameState(Json.parse(vetJson) as Map<String, Any?>)
        check(vetBack.errands.size == Errands.STATE_CAP &&
            vetBack.photos.size == 60 && StoryArcs.allDone(vetBack) &&
            vetBack.busPass && vetBack.walkTrips == 900,
            "veteran VI: the veteran V body still round-trips whole")
        check(vetBack.arc4Retired && vetBack.arc4Branch == "guard" &&
            vetBack.mystery4Clues.size == Mystery4.CLUES4.size &&
            Dinners.totalAttended(vetBack) == 7 * 60 &&
            Jobs.lifetimeEarned(vetBack) == 99999 &&
            Votes.history(vetBack).size == Votes.HISTORY_CAP,
            "veteran VI: Queue #6's layer still round-trips whole")
        check(Secrets.foundCount(vetBack) == Secrets.SECRET_COUNT &&
            Secrets.featDone(vetBack),
            "veteran VI: all twelve secrets round-trip found, " +
                "the Sleuth feat standing")
        check(MovieNights.history(vetBack).size ==
            MovieNights.HISTORY_CAP &&
            MovieNights.attendedCount(vetBack) == 120 &&
            MovieNights.bestBuzz(vetBack) ==
            MovieNights.BUZZ_LEGENDARY &&
            MovieNights.featDone(vetBack) &&
            MovieNights.recordFor(vetBack, 645)?.tier ==
            MovieNights.TIER_BUZZING,
            "veteran VI: the movie history round-trips at its " +
                "cap, counters and best buzz intact")
        check(School.lessonHistory(vetBack).size ==
            School.HISTORY_CAP &&
            School.beeHistory(vetBack).size ==
            School.BEE_HISTORY_CAP &&
            School.recessHistory(vetBack).size ==
            School.RECESS_HISTORY_CAP &&
            School.lessonsSat(vetBack) == 400 &&
            School.beeEntered(vetBack) == 60 &&
            School.beeWon(vetBack) == 20,
            "veteran VI: the school histories round-trip at " +
                "their caps, counters intact")
        check(vetBack.arc5Retired &&
            vetBack.arc5Branch == Mystery5.DEFAULT_BRANCH &&
            vetBack.mystery5Clues.size == Mystery5.CLUES5.size &&
            vetBack.arc5Chapter == 4 &&
            Mystery5.dueChapter5(vetBack) == null,
            "veteran VI: the fifth case's typed state " +
                "round-trips closed, its evidence set complete")
        check(vetBack.episodes.count { it.climaxTier.isNotEmpty() } == 3 &&
            vetBack.episodes.any {
                it.climaxTier == Climaxes.TIER_HEROIC &&
                    it.recap.any { l -> l.contains("🎬 The climax, your way:") } },
            "veteran VI: the played climaxes' tiers and credits " +
                "lines round-trip on the album")

        // ---------- fit QA: Queue #7's newest screens ----------
        // The same Chrome discipline on the pages the queue
        // added, composed off this same saturated state —
        // the fullest each page can ever be. The claim
        // board reads off the closed case with its full
        // evidence held: checkable claims settled, core
        // claims standing untested, as the ledger rules.
        val board = Mystery5.boardLines5(vetBack)
        val stampCounts = listOf("CONFIRMED", "BROKEN", "UNTESTED")
            .associateWith { st -> board.count { it.contains(st) } }
        println("fitQA board stamps: $stampCounts")
        check(Mystery5.boardVisible5(vetBack) &&
            (stampCounts["CONFIRMED"] ?: 0) >= 1 &&
            (stampCounts["UNTESTED"] ?: 0) >= 1,
            "fitQA: the closed case's board shows settled " +
                "claims and standing core claims side by side")
        val q7Lines = mutableListOf<String>()
        q7Lines += Secrets.pageLines(vetBack)
        q7Lines += MovieNights.pageLines(vetBack)
        q7Lines += School.pageLines(vetBack)
        q7Lines += board
        for (ep in vetBack.episodes)
            if (ep.climaxTier.isNotEmpty()) q7Lines += ep.recap
        check(Secrets.pageLines(vetBack).first()
            .contains("TOWN SECRETS") &&
            Secrets.pageLines(vetBack).first().contains("12 of 12") &&
            MovieNights.pageLines(vetBack).first()
            .contains("MOVIE NIGHTS") &&
            School.pageLines(vetBack).first().contains("SCHOOL"),
            "fitQA: the Queue #7 Journal pages carry their titles")
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { s: String -> s.length * 10f * fs }
            for (line in q7Lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a Queue #7 screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a Queue #7 screen line never collapses at fs $fs")
            }
        }
    }

    run {
        // ---------- the rail order, final form ----------
        // Nine rails now. First the source pin, scoped to
        // gateFor's own body — the order the judges are
        // TRIED is the order a stacked conversation peels
        // in. (v0.6.0g pinned this order with CLIMAX already
        // in place; this pass re-pins it as the final form
        // and proves it live, below.)
        val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        val railOrder = listOf("Rail.DELIVER", "Rail.HOLIDAY_BEAT",
            "Rail.FINALE", "Rail.CLIMAX", "Rail.DINNER", "Rail.WORK",
            "Rail.FACTION_MISSION", "Rail.ERRAND_ASK", "Rail.DIALOGUE")
        val railIdx = railOrder.map { gateBody.indexOf(it) }
        check(railIdx.all { it >= 0 } &&
            railIdx.zipWithNext().all { (a, b) -> a < b },
            "rail order: gateFor tries DELIVER, HOLIDAY_BEAT, " +
                "FINALE, CLIMAX, DINNER, WORK, FACTION_MISSION, " +
                "ERRAND_ASK and DIALOGUE in exactly that order — " +
                "the final form, nine rails")

        // Then the fullest live stack the cast data allows,
        // honestly extended: v0.6.0g's Randy stack peels
        // eight rails on the one man who can hold them. The
        // ninth — CLIMAX — joins on the same fabricated day:
        // the event standing at its peak that evening is the
        // Tegridy takeover, Randy's own doing, and its
        // climax turf is the farm the whole stack already
        // stands on. Every rail armed through its own
        // module's state, every peel through its own judge.
        val eng = Engine(707_007)
        var stack: GameState? = null
        var stackYear = -1
        outer@ for (y in 2027..2060) {
            for (ad in 999..1400 step 7) {   // ad % 7 == 5: a Tuesday
                val cand = eng.newState()
                eng.createPlayer(cand, "Stack", DEFAULT_APPEARANCE)
                cand.absDay = ad
                cand.gameYear = y; cand.gameMonth = 5; cand.gameDay = 28
                cand.todayKey = "%04d0528".format(y)
                Dinners.dailyRollover(cand)
                if (Dinners.todaysInvite(cand)?.id != "marsh") continue
                if (Errands.askFor(cand, "Randy") == null) continue
                stack = cand; stackYear = y
                break@outer
            }
        }
        check(stack != null,
            "contention: a spring Tuesday exists where the Marsh " +
                "table is set and Randy has something to ask")
        val s = stack!!
        s.timeMin = 8 * 60 + 30
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        Jobs.lookText(s, "TegridyFarms")
        Jobs.lookText(s, "TegridyFarms")
        check(Jobs.currentJob(s)?.id == "farm" && Jobs.clockedIn(s) &&
            Jobs.talkStepFor(s, "Randy", "TegridyFarms")?.kind == "TASK",
            "contention: the farm inspection stands armed on Randy")
        s.factionStates["parents"]!!.playerStanding = 50
        FactionMissions.offerFor(s, "Sharon")?.let {
            FactionMissions.accept(s, it) }
        FactionMissions.lookText(s, "MainStreet")
        val parentsChain = FactionMissions.CHAINS
            .first { it.factionId == "parents" }
        FactionMissions.offerFor(s, parentsChain.beats[1].offerNpc)?.let {
            FactionMissions.accept(s, it) }
        s.inventory["hot_chocolate"] = 1
        FactionMissions.onGive(s, "Barbrady", "hot_chocolate")
        FactionMissions.offerFor(s, "McDaniels")?.let {
            FactionMissions.accept(s, it) }
        check(FactionMissions.talkBeatFor(s, "Randy") != null,
            "contention: the Watch report stands armed on Randy")
        val springDef = Finales.defById("spring")!!
        Finales.dailyRollover(s)
        Finales.lookText(s, springDef.steps[1].loc!!)
        s.agents[springDef.steps[2].who]!!.location =
            springDef.steps[2].loc ?: "KidsPark"
        Finales.judgeTalk(s, springDef.steps[2].who!!)
        s.agents["Randy"]!!.location = springDef.steps[3].loc ?: "KidsPark"
        check(Finales.talkStepFor(s, "Randy") != null,
            "contention: the spring confession stands armed on Randy")
        s.holidayId = "july4"
        s.life["hb:july4:$stackYear:mask"] = 1
        check(HolidayBeats.talkStepFor(s, "Randy") != null,
            "contention: the rehearsal deputizing stands armed on Randy")
        s.errands.add(Errand(id = "stack-deliver", source = Errands.BOARD,
            asker = "Ned", type = "DELIVER", text = "t", hint = "h",
            targetName = "Randy", itemId = "fishing_lure",
            dayKey = s.todayKey, acceptedDay = s.absDay))
        s.inventory["fishing_lure"] =
            (s.inventory["fishing_lure"] ?: 0) + 1
        check(Errands.active(s).any {
            it.type == "DELIVER" && it.targetName == "Randy" },
            "contention: a delivery stands addressed to Randy")
        // the day's event, standing at its peak on the farm
        s.shenaniganId = "tegridy_takeover"
        s.shenaniganDay = s.todayKey
        // the evening: the Marsh welcome lands, and the table
        // talk that follows is his
        s.timeMin = 17 * 60 + 45
        Dinners.judgeTalk(s, "Sharon")
        check(Dinners.talkStepFor(s, "Randy") != null,
            "contention: the Marsh table talk stands armed on Randy")
        check(Climaxes.talkStepFor(s, "Randy", "TegridyFarms"),
            "contention: the harvest climax stands armed on its " +
                "own causer, on its own turf, in its window")
        check(Errands.askFor(s, "Randy") != null,
            "contention: Randy's ask survived the arming")
        // TOTAL CONTENTION — every rail he can hold, one man,
        // one tap. The peel runs the final order end to end.
        var g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DELIVER,
            "contention: a delivery outranks everything (got ${g.rail})")
        Errands.deliverTo(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.HOLIDAY_BEAT,
            "contention: the holiday beat is next (got ${g.rail})")
        HolidayBeats.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.FINALE,
            "contention: the finale is next (got ${g.rail})")
        Finales.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.CLIMAX,
            "contention: the climax is next — between the finale " +
                "and the dinner, where v0.7.0e put it (got ${g.rail})")
        check(playChainQ7(s, heroic = true),
            "contention: the harvest chain plays out on the " +
                "gate's own turf")
        check(Climaxes.isComplete(s,
            SHENANIGAN_BY_ID["tegridy_takeover"]!!),
            "contention: the played chain stands complete")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DINNER,
            "contention: the dinner beat is next (got ${g.rail})")
        Dinners.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.WORK &&
            g.jobStep?.kind == "TASK",
            "contention: the inspection is next (got ${g.rail})")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.WORK &&
            g.jobStep?.kind == "CLOCK_OUT",
            "contention: a finished shift still holds the work " +
                "rail — the clock-out is owed (got ${g.rail})")
        Jobs.judgeTalk(s, "Randy", "TegridyFarms")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.FACTION_MISSION,
            "contention: the faction beat is next (got ${g.rail})")
        FactionMissions.judgeTalk(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.ERRAND_ASK,
            "contention: the direct ask is next (got ${g.rail})")
        Errands.markAsked(s, "Randy")
        g = TalkGate.gateFor(s, "Randy", "TegridyFarms")
        check(g.rail == TalkGate.Rail.DIALOGUE,
            "contention: and at the bottom of the whole ladder, " +
                "a conversation (got ${g.rail})")
    }

    run {
        // ---------- the Queue #7 seams ----------
        val engS = Engine(707_101)

        // ---- movie nights × votes: the headline expires ----
        // with the outcome that bought it. A standing Bijou
        // count programs Saturday's feature; when the
        // outcome lapses on its own schedule, Saturday
        // returns to the rotation — the marquee never keeps
        // a headline the town stopped paying for.
        var bijouWeek = -1
        for (w in 0..40) {
            val probe = engS.newState()
            probe.absDay = w * 7
            if (Votes.currentQuestion(probe).id == "bijou_matinee") {
                bijouWeek = w; break
            }
        }
        check(bijouWeek >= 0,
            "seam: the matinee question comes up in the rotation")
        val sM = engS.newState()
        engS.createPlayer(sM, "Marquee", DEFAULT_APPEARANCE)
        sM.absDay = bijouWeek * 7 + 1
        val qM = Votes.currentQuestion(sM)
        check(qM.id == "bijou_matinee",
            "seam: the probed week asks the matinee question")
        Votes.castVote(sM, qM.options[0].id)
        sM.absDay += 7
        Votes.dailyRollover(sM)
        check(Votes.standingOption(sM, qM) != null,
            "seam: the matinee count stands")
        var sat = sM.absDay
        while (Jobs.weekdayOf(sat) != 6) sat++
        check(MovieNights.featureForDay(sM, sat).headline,
            "seam: while the outcome stands, Saturday's feature " +
                "is the vote's pick")
        repeat(Votes.OUTCOME_WEEKS + 2) {
            sM.absDay += 7
            Votes.dailyRollover(sM)
        }
        check(Votes.standingOption(sM, qM) == null,
            "seam: the outcome lapses on its own schedule")
        var sat2 = sM.absDay
        while (Jobs.weekdayOf(sat2) != 6) sat2++
        check(!MovieNights.featureForDay(sM, sat2).headline,
            "seam: with the outcome gone, Saturday returns to " +
                "the rotation — the headline expired with it")

        // ---- secrets × votes: standings only, never history ----
        val sB = engS.newState()
        engS.createPlayer(sB, "Ballot", DEFAULT_APPEARANCE)
        val box = Secrets.secretById("the_third_box")!!
        check(!Secrets.gateOpen(sB, box),
            "seam: with no count standing, the third box is scenery")
        val qB = Votes.currentQuestion(sB)
        Votes.castVote(sB, qB.options[0].id)
        sB.absDay += 7
        Votes.dailyRollover(sB)
        check(Secrets.gateOpen(sB, box),
            "seam: a standing outcome — any standing outcome — " +
                "opens the City Hall gate")
        // A standing ages on the calendar (OUTCOME_WEEKS of
        // days from its count) while its history entry is
        // forever. Age this one past its life without
        // booking any new count, and the two records part
        // ways — the gate follows the standing down.
        sB.absDay += Votes.OUTCOME_WEEKS * 7 + 7
        check(Votes.standingOption(sB, qB) == null &&
            Votes.history(sB).any { it.questionId == qB.id } &&
            !Secrets.gateOpen(sB, box),
            "seam: aged past its outcome-weeks the standing " +
                "is gone while its count stays in the history " +
                "book — the gate reads standings, never history")

        // ---- arc #5 × the four deference lists, live ----
        // v0.7.0f pinned the lists in source; this pass stands
        // the confrontation up and watches all four stand
        // down on the one state, each through its own read.
        val finalesSrc = File(root,
            "src/com/hunt3r/southparktown/Finales.kt").readText()
        val movieSrc = File(root,
            "src/com/hunt3r/southparktown/MovieNights.kt").readText()
        val schoolSrc = File(root,
            "src/com/hunt3r/southparktown/School.kt").readText()
        val walkSrc = File(root,
            "src/com/hunt3r/southparktown/Walk.kt").readText()
        check(finalesSrc.substring(
            finalesSrc.indexOf("fun climaxPending"))
            .take(500).contains("Mystery5.confrontationDue") &&
            movieSrc.substring(
            movieSrc.indexOf("fun anyClimaxDueTonight"))
            .take(600).contains("Mystery5.confrontationDue") &&
            schoolSrc.substring(
            schoolSrc.indexOf("fun anyClimaxDueToday"))
            .take(500).contains("Mystery5.confrontationDue") &&
            walkSrc.substring(walkSrc.indexOf("fun caseCritical"))
            .take(500).contains("Mystery5.confrontationDue"),
            "seam: each deference list names the fifth case's " +
                "confrontation in its own due-function")
        val sD = engS.newState()
        sD.arcRetired = true; sD.arc2Retired = true
        sD.arc3Retired = true; sD.arc4Retired = true
        sD.arc5Started = true; sD.arc5Chapter = 4
        sD.shenaniganId = Mystery5.FINALE5_ID
        sD.shenaniganDay = sD.todayKey
        for (c in Mystery5.CLUES5.take(Mystery5.CONFRONT_MIN_CLUES))
            sD.mystery5Clues.add(c.id)
        sD.timeMin = 19 * 60
        check(Mystery5.confrontationDue(sD),
            "seam: the confrontation stands due")
        check(MovieNights.darkReason(sD) == MovieNights.DARK_CASE &&
            MovieNights.isDarkTonight(sD),
            "seam: the Bijou goes dark for the fifth case's climax")
        check(School.quietReason(sD) == School.QUIET_CASE,
            "seam: the school day quiets for the fifth case's climax")
        check(Finales.climaxPending(sD),
            "seam: the finales hold for the fifth case's climax")
        check(Walk.caseCritical(sD),
            "seam: the road quiets for the fifth case's climax")

        // ---- school × climaxes: one Friday afternoon ----
        // A bee Friday and an event climax share the turf
        // clock, not a system: an EVENT climax is not a CASE
        // climax, so the school day runs, the bee spells,
        // and the chain still plays inside its own window.
        val sF = engS.newState()
        engS.createPlayer(sF, "Spelling", DEFAULT_APPEARANCE)
        sF.absDay = 1; sF.gameDay = 2; sF.todayKey = "20261002"
        sF.shenaniganId = "gold_fever"
        sF.shenaniganDay = sF.todayKey
        sF.timeMin = 13 * 60 + 30
        check(School.isBeeDay(sF.absDay) &&
            School.quietReason(sF) == null,
            "seam: a shenanigan climax is not a case climax — " +
                "the school day runs")
        check(School.beeStatus(sF) == School.BS_OPEN &&
            Climaxes.isLive(sF),
            "seam: bee and climax both stand open on the same " +
                "Friday afternoon")
        check(playBeeQ7(sF) &&
            School.beeRecordFor(sF, sF.absDay)?.won == true,
            "seam: the bee spells out and wins on climax afternoon")
        check(playChainQ7(sF, heroic = true) &&
            Climaxes.tierOf(sF,
                SHENANIGAN_BY_ID["gold_fever"]!!) ==
            Climaxes.TIER_HEROIC,
            "seam: the chain plays after the bee, inside its " +
                "window, and lands heroic")
        check(School.beeRecordFor(sF, sF.absDay)?.won == true,
            "seam: neither book ate the other — the bee record " +
                "stands with the tier")

        // ---- wave-3 cast × crowds: the matrix, extended ----
        // v0.7.0a's seam ran the real chemistry at every
        // headcount to 44 — the size of the cast when it was
        // written. The town is 54 now; the audit extends
        // the same matrix over the wave-3 headcounts.
        val castNames7 = CharacterSystem.CAST.keys.toList()
        val rivalPairs7 = mutableSetOf<Set<String>>()
        for (a in castNames7) for (b in castNames7)
            if (a < b && relationNote(a, b) == "arch-rivals")
                rivalPairs7.add(setOf(a, b))
        val fullChem7 = Crowds.Chem(
            scriptPairs = PAIR_SCRIPTS.keys
                .filter { it.size == 2 }.toSet(),
            rivalPairs = rivalPairs7,
            factionOf = FACTION_OF_CAST)
        for (total in 45..54) {
            val names = castNames7.take(total)
            val lay = Crowds.layout(names, fullChem7)
            check(lay != null && lay.placed.size == total,
                "seam: a crowd of $total lays out whole")
            if (lay == null) continue
            for (inside in listOf(false, true)) {
                val feet0 = if (inside) Depth.FRONT_FEET_IN
                    else Depth.FRONT_FEET_OUT
                val fgTop = if (inside) Depth.FG_TOP_IN
                    else Depth.FG_TOP_OUT
                var chinOk = true
                for (p in lay.placed) {
                    val feet = feet0 - p.frontness *
                        Depth.FH_BASE_MAX * 0.54f
                    if (Depth.worstChin(feet) >= fgTop) chinOk = false
                }
                check(chinOk,
                    "seam: crowd of $total " +
                        (if (inside) "indoors" else "outdoors") +
                        " — no clustered row pushes a face into " +
                        "the frieze")
            }
            var sepOk = true
            for ((_, row) in lay.placed.groupBy { it.frontness }) {
                val byX = row.sortedBy { it.xFrac }
                for (i in 1 until byX.size)
                    if (byX[i].xFrac - byX[i - 1].xFrac <
                        Crowds.MIN_SEP - 0.0001f) sepOk = false
            }
            check(sepOk,
                "seam: crowd of $total — the MIN_SEP floor holds " +
                    "at maximum realistic density")
        }
    }

    run {
        // ---------- the peak budget, sixth distance ----------
        // The same pins as v0.4.0e, on today's render set.
        // And the census, counted honestly after wave 3:
        // Queue #7 shipped five systems and not one new
        // audio family — but the bark table grew with the
        // cast, ten new rhythm signatures for ten new
        // townsfolk, and that growth is what's pinned.
        val pb = SoundGen.PeakBudget
        println("budget v0.7.0g: named ${pb.namedStack()}, " +
            "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
            "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
            "amb ${pb.ambiencePeakOut()}, bark signatures " +
            "${Barks.PATTERNS.size} (" +
            "${Barks.PATTERNS.values.distinct().size} distinct)")
        check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
            "budget: the named stack has not drifted since v0.4.0e " +
                "(got ${pb.namedStack()})")
        check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
            "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
        check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
            "budget: the bark stack has not drifted (got ${pb.barkStack()})")
        check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
            pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
            "budget: neither barks nor mood contours out-peak the plain blip")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val post = AudioSettings.DEFAULT.gain(
                AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
                pb.peakOf(SoundGen.renderAmbience(bed))
            check(post <= pb.ambiencePeakOut() + 0.002f,
                "budget: bed $bed stays inside the ambience allocation")
        }
        check(SoundGen.SFX_IDS.size == 21 &&
            SoundGen.BlipFam.values().size == 7 &&
            SoundGen.BlipMood.values().size == 4 &&
            SoundGen.AmbBed.values().size == 6,
            "budget: the family census is unchanged — 21 named " +
                "effects, 7 blip families, 4 moods, 6 ambience " +
                "beds. Queue #7 added no audio family (got " +
                "${SoundGen.SFX_IDS.size}/${SoundGen.BlipFam.values().size}/" +
                "${SoundGen.BlipMood.values().size}/${SoundGen.AmbBed.values().size})")
        check(Barks.PATTERNS.size == CharacterSystem.CAST.size &&
            Barks.PATTERNS.keys == CharacterSystem.CAST.keys,
            "budget: the bark census after wave 4 — one rhythm " +
                "signature per cast member, all 62 of them, the " +
                "eight newcomers included (got ${Barks.PATTERNS.size})")
    }

    run {
        // ---------- the tuning ledger, swept for Queue #7 ----------
        // Every paper-tuned Queue #7 constant, named in the
        // ledger section itself — scoped to the section, so
        // a dial that only ever made a changelog doesn't
        // count. (Cast wave 3 tuned no dials — its numbers
        // are the sheets', and the sheets are the spec.)
        val tuning = File(root, "docs/TUNING.md").readText()
        val ledgerStart = tuning.indexOf("## Tuning ledger")
        val ledgerEnd = tuning.length
        check(ledgerStart >= 0 && ledgerEnd > ledgerStart,
            "ledger: the ledger section stands ahead of the changelog")
        val ledger = tuning.substring(ledgerStart, ledgerEnd)
        val q7Dials = listOf(
            // town secrets (v0.7.0b)
            "SECRET_COUNT", "FEAT_THRESHOLD",
            // movie nights (v0.7.0c)
            "DOORS_FROM", "LAST_SEATING", "HOUSE_CAP",
            "NO_REPEAT_SLOTS", "FRIEND_CHEMISTRY",
            "BUZZ_POLITE", "BUZZ_BUZZING", "BUZZ_LEGENDARY",
            "PAY_POLITE", "PAY_BUZZING", "PAY_LEGENDARY",
            "HISTORY_CAP",
            // school days (v0.7.0d)
            "SCHOOL_WEEKDAYS", "CLASS_FROM", "CLASS_TO",
            "RECESS_FROM", "RECESS_TO", "VICTORIA_WEEKDAY",
            "LESSON_PAY", "TEACHER_PAY", "SPRINKLE_CAP",
            "BEE_WEEKDAY", "BEE_FROM", "BEE_TO", "FIELD_SIZE",
            "CHEAT_ROUND", "MAX_ROUNDS", "BEE_WIN_COINS",
            "FINALIST_PAY", "BEE_HISTORY_CAP", "RECESS_HISTORY_CAP",
            // playable climaxes (v0.7.0e)
            "BEATS_PER_CHAIN", "SCORE_LANDED", "SCORE_CLOSE",
            "SCORE_MISSED", "BEAT_PARTICIPATION",
            "PAY_HEROIC", "PAY_HANDLED", "PAY_FUMBLED",
            // mystery #5 (v0.7.0f)
            "OPEN_DELAY_DAYS", "CHAPTER_GAP_DAYS",
            "CONFRONT_MIN_CLUES", "LURE_RETURN_DELAY_DAYS",
            "NAME_SCAR", "BELIEVE_SCAR")
        for (dial in q7Dials) {
            check(dial in ledger,
                "ledger: Queue #7's $dial is named in the ledger")
        }
        check(readme.substringAfter("### v0.7.0g")
            .substringBefore("### v0.7.0f").contains("Queue #7"),
            "ledger: the v0.7.0g changelog closes the queue it audits")
    }
}


/** v0.8.0a section (Queue #8, item 1 — cast expansion wave 4):
 *  +8 named townsfolk, the cast 54 -> 62. The picks complete
 *  constellations the way wave 3 did: Ike finishes the
 *  Broflovskis (Kyle's, Gerald's and Sheila's banks have talked
 *  about him since the early waves), Kevin McCormick — the full
 *  two-token name everywhere, never "Kevin", which is Kevin
 *  Stoley — finishes the McCormicks, Shelley finishes the
 *  Marshes, and Laura finishes the Tuckers. Yates gives Barbrady
 *  a sergeant, Adler completes the Elementary staff, Lu Kim
 *  gives City Wok its owner the way Skeeter gave the bar its,
 *  and Mephesto is the town's own geneticist, mined from the
 *  lorebook's named pool with wave-2/3 discipline. The
 *  54-count pins elsewhere moved to 62 honestly; wave-specific
 *  facts (wave-3 homes/factions, the Black household) are
 *  untouched. */
private fun sectionV080a(root: String) {
    println("== v0.8.0a: cast expansion wave 4 ==")
    val wave4 = listOf("Ike", "Kevin McCormick", "Shelley",
        "Laura", "Mephesto", "Yates", "Adler", "Lu Kim")
    val wave4Kids = listOf("Ike", "Kevin McCormick", "Shelley")
    val wave4Adults = listOf("Laura", "Mephesto", "Yates", "Adler", "Lu Kim")

    // ---------- the roster arithmetic ----------
    check(WAVE4_ORDER == wave4, "wave4: the wave roster is the pinned eight")
    check(KID_ORDER.size == 98 && KID_ORDER.distinct().size == 98,
        "wave4: KID_ORDER carries 98 distinct names")
    check(AGENT_PROFILES.size == 98, "wave4: 98 agent profiles")
    check(KID_HOUSE.size == 98, "wave4: 98 homes")
    check(CharacterSystem.CAST_KIDS.size + CharacterSystem.CAST_ADULTS.size == 98 &&
        (CharacterSystem.CAST_KIDS intersect CharacterSystem.CAST_ADULTS).isEmpty(),
        "wave4: 42 kids + 56 adults, disjoint")
    check(wave4Kids.all { it in CharacterSystem.CAST_KIDS } &&
        wave4Adults.all { it in CharacterSystem.CAST_ADULTS },
        "wave4: the age split matches the wave roster")
    check(CharacterSystem.CAST.keys == AGENT_PROFILES.keys,
        "wave4: CAST and AGENT_PROFILES describe the same 70")
    check("Kevin" in CharacterSystem.CAST && "Kevin McCormick" in CharacterSystem.CAST,
        "wave4: Kevin Stoley and Kevin McCormick are two distinct citizens")
    // the visitor pool regenerates from the alias table: all
    // eight lore names are excluded from it by construction
    val w4LoreNames = wave4.map { LORE_CHAR_ALIASES.getValue(it) }.toSet()
    check(VisitorSystem.eligible().none { it.name in w4LoreNames || it.name in wave4 },
        "wave4: the visitor pool excludes all eight newcomers")
    check(CharacterSystem.CAST_BANDS["Shelley"] == AgeBand.YOUNG_TEEN &&
        CharacterSystem.CAST_BANDS["Kevin McCormick"] == AgeBand.YOUNG_TEEN &&
        CharacterSystem.CAST_BANDS["Ike"] == AgeBand.KID,
        "wave4: the teens band YOUNG_TEEN, the toddler bands KID")

    // ---------- every newcomer is a full citizen ----------
    for (n in wave4) {
        check(n in AGENT_PROFILES, "wave4: $n has a profile")
        check(n in KidArt.SHEETS, "wave4: $n has a sheet spec")
        check(n in LINE_BANKS && n in DAILY_TOPICS && n in SPEECH_RULES,
            "wave4: $n has banks, topics, and a voice card")
        check(n in FRIEND_GREETINGS && n in RESPONSE_BANKS && n in SLEEPY_LINES,
            "wave4: $n has greetings, responses, and sleepy lines")
        check(n in SoundGen.BLIP_FAMILIES, "wave4: $n has a voice blip family")
        check(n in LORE_CHAR_ALIASES, "wave4: $n has a lore alias")
        check(LoreBook.charLore(n) != null, "wave4: $n resolves lorebook entries")
        check(factionOfCast(n) != null, "wave4: $n holds exactly one faction")
    }

    // ---------- homes: the constellation houses ----------
    check(KID_HOUSE["Ike"] == "KyleHouse" && KID_HOUSE["Kevin McCormick"] == "KennysHouse" &&
        KID_HOUSE["Shelley"] == "StanHouse" && KID_HOUSE["Laura"] == "MainStreet" &&
        KID_HOUSE["Mephesto"] == "MainStreet" && KID_HOUSE["Yates"] == "CityHall" &&
        KID_HOUSE["Adler"] == "Elementary" && KID_HOUSE["Lu Kim"] == "CityWok",
        "wave4: homes complete the families and the workplaces")

    // ---------- schedules: seven real blocks, workplaces held ----------
    val wave4Blocks = setOf("08:00", "09:00", "12:00", "15:00", "16:30", "18:00", "21:00")
    for (n in wave4) {
        val p = AGENT_PROFILES.getValue(n)
        check(p.agenda.keys == wave4Blocks, "wave4: $n keeps the 7-block day")
        check(p.agenda.values.all { it.location in LOCATIONS },
            "wave4: $n is scheduled at real locations only")
        check(p.description.length > 200,
            "wave4: $n's description carries full lore (got ${p.description.length})")
    }
    check(AGENT_PROFILES.getValue("Lu Kim").agenda.values.count { it.location == "CityWok" } >= 4,
        "wave4: City Wok's owner works his own wok")
    check(AGENT_PROFILES.getValue("Adler").agenda.values.count { it.location == "Elementary" } >= 4,
        "wave4: the shop teacher holds the school's shop hours")
    check(AGENT_PROFILES.getValue("Yates").agenda.values.count { it.location == "CityHall" } >= 3,
        "wave4: the sergeant keeps his desk at City Hall")
    check(AGENT_PROFILES.getValue("Ike").agenda.values.count { it.location == "KyleHouse" } >= 3 &&
        AGENT_PROFILES.getValue("Kevin McCormick").agenda.values.count { it.location == "KennysHouse" } >= 3 &&
        AGENT_PROFILES.getValue("Shelley").agenda.values.count { it.location == "StanHouse" } >= 3,
        "wave4: the family kids live at their family houses")

    // ---------- factions ----------
    check(FACTION_OF_CAST.size == 98, "wave4: every cast member holds exactly one faction")
    check(FACTION_OF_CAST["Ike"] == "boys_crew" && FACTION_OF_CAST["Kevin McCormick"] == "boys_crew" &&
        FACTION_OF_CAST["Shelley"] == "girls_circle" &&
        FACTION_OF_CAST["Laura"] == "parents" && FACTION_OF_CAST["Mephesto"] == "parents" &&
        FACTION_OF_CAST["Yates"] == "parents" && FACTION_OF_CAST["Adler"] == "school_staff" &&
        FACTION_OF_CAST["Lu Kim"] == "tegridy_crew",
        "wave4: one faction each, the natural one")

    // ---------- the measured figure still rules ----------
    val w4Specs = wave4.associateWith { KidArt.SHEETS.getValue(it) }
    for (n in wave4Kids) {
        val spec = w4Specs.getValue(n)
        val tol = 0.011f
        check(!spec.tall && spec.measured != null &&
            spec.measured!!.headShare in 0.60f..(0.66f + tol),
            "wave4: $n is a measured kid, head in band")
    }
    for (n in wave4Adults) {
        val spec = w4Specs.getValue(n)
        val m = spec.measured!!
        check(spec.tall && m.headShare in 0.33f..0.37f &&
            m.legShare >= m.torsoShare - 0.011f,
            "wave4: $n is a measured adult: head ~1/3, legs >= torso")
    }
    val w4Shapes = w4Specs.values.map { s ->
        val m = s.measured!!
        Triple(m.headShare, m.heightRel, s.width)
    }
    check(w4Shapes.distinct().size == 8, "wave4: no two newcomers share a silhouette")
    // Ike is the smallest figure in town; Kevin McCormick
    // towers over the whole core crew; only Michael stands
    // taller among the kids.
    check(w4Specs.getValue("Ike").measured!!.heightRel <
        KidArt.SHEETS.getValue("Karen").measured!!.heightRel &&
        w4Specs.getValue("Ike").measured!!.heightRel <
        KidArt.SHEETS.getValue("Timmy").measured!!.heightRel,
        "wave4: Ike is the smallest standing figure in town")
    check(w4Specs.getValue("Kevin McCormick").measured!!.heightRel >
        listOf("Cartman", "Stan", "Kyle", "Kenny", "Butters", "Tolkien")
            .maxOf { KidArt.SHEETS.getValue(it).measured!!.heightRel } &&
        w4Specs.getValue("Kevin McCormick").measured!!.heightRel >
        w4Specs.getValue("Shelley").measured!!.heightRel,
        "wave4: the eldest McCormick towers over the core crew")
    // signatures: the braces, the beard, the shades, the apron
    check(w4Specs.getValue("Shelley").face == "braces",
        "wave4: Shelley's braces are drawn")
    check(w4Specs.getValue("Mephesto").beard && w4Specs.getValue("Mephesto").top == "#e8e6df",
        "wave4: Mephesto wears the beard and the lab coat")
    check(w4Specs.getValue("Yates").mustache && w4Specs.getValue("Yates").sunglasses,
        "wave4: Yates wears the mustache and the aviators")
    check(w4Specs.getValue("Adler").special == "apron",
        "wave4: Adler wears the shop apron")
    check(w4Specs.getValue("Lu Kim").tie && w4Specs.getValue("Lu Kim").hairColor == "#141414",
        "wave4: Lu Kim wears the bow tie over black hair")
    check(w4Specs.getValue("Laura").hairStyle == "bob" && w4Specs.getValue("Laura").lipstick,
        "wave4: Laura wears the bob and the lipstick")

    // ---------- showdown dodge ----------
    check(Showdown.dodgeFor("Ike") in 0.05f..0.45f &&
        Showdown.dodgeFor("Shelley") in 0.05f..0.45f &&
        Showdown.dodgeFor("Kevin McCormick") in 0.05f..0.45f,
        "wave4: every newcomer kid has a sane dodge chance")
    check(Showdown.dodgeFor("Kevin McCormick") <
        Showdown.dodgeFor("Shelley") &&
        Showdown.dodgeFor("Shelley") <
        Showdown.dodgeFor("Ike"),
        "wave4: the big target is easiest to hit, the toddler hardest")

    // ---------- the Friday bee takes their measure ----------
    check(School.skillOf("Shelley") == 6 && School.skillOf("Kevin McCormick") == 4 &&
        School.skillOf("Ike") == 2,
        "wave4: bee skills — the spite-reader, the dropout, the toddler")

    // ---------- relations: every scripted pair is related ----------
    for (pair in WAVE4_PAIR_SCRIPTS.keys) {
        check(relationNote(pair.first(), pair.last()) != null,
            "wave4: relation note for ${pair.joinToString("/")}")
    }
    check(relationNote("Ike", "Kyle")?.contains("kick") == true,
        "wave4: the Broflovski brothers' note knows the house rule")
    check(relationNote("Shelley", "Stan")?.contains("diary") == true,
        "wave4: the Marsh siblings' note knows the diary")
    check(relationNote("Mephesto", "Chef")?.contains("weirder") == true,
        "wave4: the old friends' note knows the weirder years")

    // ---------- dinners: the completed families sit down together ----------
    check(Dinners.HOUSEHOLDS.first { it.id == "marsh" }.members ==
        listOf("Randy", "Sharon", "Stan", "Shelley"),
        "wave4: the Marsh table seats the big sister")
    check(Dinners.HOUSEHOLDS.first { it.id == "broflovski" }.members ==
        listOf("Gerald", "Sheila", "Kyle", "Ike"),
        "wave4: the Broflovski table seats the little brother")
    check(Dinners.householdOf("Shelley")?.id == "marsh" &&
        Dinners.householdOf("Ike")?.id == "broflovski" &&
        Dinners.householdOf("Shelley")?.house == KID_HOUSE["Shelley"] &&
        Dinners.householdOf("Ike")?.house == KID_HOUSE["Ike"],
        "wave4: dinner households resolve at the houses the kids live in")
    // the wave-3 completions stay as wave 3 left them
    check(Dinners.HOUSEHOLDS.first { it.id == "black" }.members == listOf("Tolkien", "Steve", "Linda Black"),
        "wave4: the Black household stands as wave 3 seated it, " +
            "plus Linda Black (wave 6, v0.11.0d)")

    // ---------- spawn: a fresh town seats all sixty-two ----------
    val engW = Engine(808)
    val sW = engW.newState()
    check(wave4.all { it in sW.agents }, "wave4: a new state seats all eight newcomers")
    check(sW.agents.size >= 98, "wave4: the roster spawns at 98+")

    // ---------- the fan sheets carry all sixty-two ----------
    try {
        val params = File("/home/hatch/workspace/goals/" +
            "south-park-interactive-town/files/sheets/tools/params.json")
            .readText()
        check(KID_ORDER.all { params.contains("\"name\": \"$it\"") },
            "wave4: sheet params contain every one of the 98")
        check(params.split("\"name\":").size - 1 == 98,
            "wave4: sheet params hold exactly 98 characters")
    } catch (e: Exception) {
        check(false, "wave4: sheet params readable (${e.message})")
    }
}

// ================= v0.8.0b: Faction Capstones =================
// Queue #8 item 2. Every faction chain (v0.5.0d) gets its
// endgame: ONE capstone per faction, a second three-beat
// chain gated at Beloved (60 — the standingLabel table's own
// top threshold), offered through the same Talk-gate rail,
// judged by the same verbs plus three other systems' own
// funnels (a Bijou screening PHOTO, a Votes count, a Jobs
// clock-out). Beat 3 is a ceremony: the faction gathers at
// its place in the late-afternoon window (agenda override),
// the senior hosts, and the uniform reward lands — a drawn
// trace (Depth BACKGROUND, claimed once) + a title + the
// 🏛 CAPSTONES Journal page. Capstone beats pay NO standing;
// finishing costs the missions' RIVAL_COST with the declared
// rival. Below the gate there is no menu — the senior's
// hintLine, once a day, inside owedLines. State: zero new
// save keys (capMask/capActive in the life map).
private fun sectionV080b(root: String) {
    println("== v0.8.0b: Faction Capstones — the big ask ==")
    val eng = Engine(80802)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        fun freshState(): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "Family", DEFAULT_APPEARANCE)
            return s
        }
        fun cap(fid: String) = Capstones.chainById(fid)!!
        fun cbeat(fid: String, n: Int) = cap(fid).beats[n - 1]
        fun mbeat(fid: String, n: Int) = FactionMissions.chainById(fid)!!.beats[n - 1]
        fun photoAt(locId: String) = PhotoRecord(
            id = "cap-photo", dayKey = "20261001", dateLabel = "10/1",
            timeMin = 720, locId = locId, inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = emptyList())
        /** Land an ARMED mission beat through its verb's real judge. */
        fun landMission(s: GameState, b: FactionBeat): Boolean = when (b.verb) {
            "TALK" -> FactionMissions.judgeTalk(s, b.targetNpc!!).any { it.beat == b }
            "GIVE" -> {
                s.inventory[b.itemId!!] = (s.inventory[b.itemId] ?: 0) + 1
                FactionMissions.onGive(s, b.targetNpc!!, b.itemId!!).any { it.beat == b }
            }
            "LOOK" -> {
                s.timeMin = if (b.minMin > 0) b.minMin else 720
                FactionMissions.lookText(s, b.locId!!) != null
            }
            "PHOTO" -> FactionMissions.onPhoto(s, photoAt(b.locId!!)).any { it.beat == b }
            "CATCH" -> FactionMissions.onCatch(s, b.fishId ?: "pond_smelt").any { it.beat == b }
            "SHOWDOWN" -> FactionMissions.onShowdown(s, true, b.targetNpc ?: "Stan")
                .any { it.beat == b }
            "TACO" -> FactionMissions.onTaco(s, b.tacoMin!!).any { it.beat == b }
            else -> false
        }
        /** One full town-job shift through Jobs' own judges —
         *  the clock-out hit the funnel returns (the JOB
         *  beat's line rides it when one is armed). */
        fun driveShift(s: GameState): JobHit? {
            val paper = Jobs.defById("paper")!!
            if (Jobs.currentJob(s) == null) {
                var g = 0
                while (!Jobs.isShiftDay(s.absDay, paper) && g++ < 10) s.absDay++
                s.timeMin = 8 * 60 + 30
                Jobs.judgeTalk(s, Jobs.bossFor(s, paper), Jobs.workplaceFor(s, paper))
            }
            val job = Jobs.currentJob(s) ?: return null
            var g2 = 0
            while (!Jobs.isShiftDay(s.absDay, job) && g2++ < 10) s.absDay++
            s.timeMin = 8 * 60 + 30
            if (!Jobs.clockedIn(s))
                Jobs.judgeTalk(s, Jobs.bossFor(s, job), Jobs.workplaceFor(s, job))
            for (t in Jobs.tasksFor(s, job)) when (t.kind) {
                "LOOK" -> Jobs.lookText(s, t.target)
                "TALK" -> Jobs.judgeTalk(s, t.target, Jobs.workplaceFor(s, job))
            }
            return Jobs.judgeTalk(s, Jobs.bossFor(s, job), Jobs.workplaceFor(s, job))
        }
        /** Land an ARMED capstone beat through its own judge —
         *  for VOTE and JOB, through the other system's funnel. */
        fun landCap(s: GameState, b: CapstoneBeat): Boolean = when (b.verb) {
            "TALK" -> {
                if (b.locId != null) {
                    s.agents[b.targetNpc!!]?.let {
                        it.location = b.locId; it.destination = b.locId
                        it.waypoints.clear()
                    }
                    s.timeMin = b.minMin
                }
                Capstones.judgeTalk(s, b.targetNpc!!).any { it.beat == b }
            }
            "GIVE" -> {
                s.inventory[b.itemId!!] = (s.inventory[b.itemId] ?: 0) + 1
                Capstones.onGive(s, b.targetNpc!!, b.itemId!!).any { it.beat == b }
            }
            "LOOK" -> {
                s.timeMin = if (b.minMin > 0) b.minMin else 720
                val before = Capstones.beatsDone(s, b.factionId)
                Capstones.lookText(s, b.locId!!)
                Capstones.beatsDone(s, b.factionId) == before + 1
            }
            "PHOTO" -> {
                if (b.needsScreening) {
                    var g = 0
                    s.timeMin = MovieNights.DOORS_FROM + 30
                    while (!Capstones.screeningLive(s) && g++ < 40) {
                        s.absDay++; s.timeMin = MovieNights.DOORS_FROM + 30
                    }
                }
                Capstones.onPhoto(s, photoAt(b.locId!!)).any { it.beat == b }
            }
            "CATCH" -> Capstones.onCatch(s, b.fishId ?: "pond_smelt").any { it.beat == b }
            "SHOWDOWN" -> Capstones.onShowdown(s, true, b.targetNpc ?: "Stan")
                .any { it.beat == b }
            "TACO" -> Capstones.onTaco(s, b.tacoMin!!).any { it.beat == b }
            "VOTE" -> {
                val q = Votes.currentQuestion(s)
                Votes.castVote(s, q.options[0].id)
                Votes.countWeek(s, Jobs.weekIndex(s.absDay))
                Capstones.beatsDone(s, b.factionId) == b.beat
            }
            "JOB" -> driveShift(s) != null &&
                Capstones.beatsDone(s, b.factionId) == b.beat
            else -> false
        }
        /** Befriend [name] up to [target] friendship the way
         *  play does — tier threshold by tier threshold, so
         *  every crossing pays relAdjust's +3 standing nudge. */
        fun befriendTo(s: GameState, name: String, target: Int) {
            var guard = 0
            while ((s.friendship[name] ?: 0) < target && guard++ < 10) {
                val cur = s.friendship[name] ?: 0
                val next = when { cur < 10 -> 10; cur < 30 -> 30; else -> 60 }
                eng.relAdjust(s, name, next - cur)
            }
        }
        /** Walk's road pitch, performed literally: a present
         *  member's ten-pace pitch is worth a clamped +2
         *  (Walk.firePoolBeat's own math). The deterministic
         *  income (chains, tier crossings) is always spent
         *  first — pitches are the road's slow remainder. */
        fun pitchUnit(s: GameState, fid: String) {
            val fs = s.factionStates[fid]!!
            fs.playerStanding = (fs.playerStanding + 2).coerceIn(-50, 100)
        }
        /** One honest income step toward [fid]'s next gate:
         *  befriend its least-befriended member one tier;
         *  when every member is a Close Friend, walk a pitch. */
        fun incomeStep(s: GameState, fid: String) {
            val members = FACTION_BY_ID[fid]!!.members
            val m = members.minByOrNull { s.friendship[it] ?: 0 }!!
            if ((s.friendship[m] ?: 0) < 60) befriendTo(s, m,
                when { (s.friendship[m] ?: 0) < 10 -> 10
                    (s.friendship[m] ?: 0) < 30 -> 30
                    else -> 60 })
            else pitchUnit(s, fid)
        }
        fun runChain(s: GameState, fid: String) {
            var guard = 0
            while (!FactionMissions.chainDone(s, fid) && guard++ < 800) {
                val nb = FactionMissions.nextBeat(s, fid) ?: break
                if (FactionMissions.offerFor(s, nb.offerNpc) == nb &&
                    FactionMissions.accept(s, nb)) {
                    check(landMission(s, nb),
                        "capstones: $fid chain beat ${nb.beat} lands through its judge")
                } else incomeStep(s, fid)
            }
        }
        fun runCapstone(s: GameState, fid: String) {
            var guard = 0
            while (!Capstones.capstoneDone(s, fid) && guard++ < 1200) {
                val nb = Capstones.nextBeat(s, fid) ?: break
                if (Capstones.offerFor(s, nb.offerNpc) == nb &&
                    Capstones.accept(s, nb)) {
                    check(landCap(s, nb),
                        "capstones: $fid capstone beat ${nb.beat} (${nb.verb}) lands through its judge")
                } else incomeStep(s, fid)
            }
        }

        run {
            // ---------- the registry: eight capstones, one shape ----------
            check(Capstones.CHAINS.size == 8, "capstones: exactly 8 capstones")
            check(Capstones.CHAINS.map { it.factionId } == FACTIONS.map { it.id },
