            check(Capstones.lookText(s, "Mall")
                ?.contains(cap("girls_circle").markLabel) == true,
                "capstones girls: a careful Look at the Mall names the trace")
            check(NpcMemoryStore.get("Wendy")?.topics
                ?.contains(Capstones.TOPIC_DONE) == true &&
                NpcMemoryStore.get("Wendy")?.topics
                    ?.contains(Capstones.TOPIC_PENDING) != true,
                "capstones girls: the members' topic turns — the ask is answered now")
            // once-only: the rite cannot be re-armed or re-landed
            check(Capstones.offerFor(s, "Wendy") == null &&
                Capstones.activeBeat(s, "girls_circle") == null,
                "capstones girls: a set capstone offers nothing more")
            s.agents["Wendy"]!!.location = "Mall"
            s.timeMin = Capstones.CEREMONY_FROM
            check(Capstones.judgeTalk(s, "Wendy").isEmpty() &&
                Capstones.mask(s, "girls_circle") == 7,
                "capstones girls: the ceremony cannot land twice")
            // the morning after: one line, then silence
            s.absDay++
            check(Capstones.morningNote(s)
                ?.contains(cap("girls_circle").playerTitle) == true,
                "capstones girls: the morning report says the title once, the day after")
            s.absDay++
            check(Capstones.morningNote(s) == null,
                "capstones girls: and only once")
            // the Journal page tells the whole story
            val page = Capstones.pageLines(s)
            check(page.any { it.contains("🏛 CAPSTONES") } &&
                page.any { it.contains(cap("girls_circle").playerTitle) } &&
                page.any { it.contains("their chain comes first") },
                "capstones girls: the CAPSTONES page records the set one and the unrun chains")
        }

        run {
            // ---------- the screening PHOTO: the right room, the right night ----------
            val s = freshState()
            runChain(s, "boys_crew")
            var guard = 0
            while (Capstones.offerFor(s, "Cartman") == null && guard++ < 200)
                incomeStep(s, "boys_crew")
            check(Capstones.accept(s, cbeat("boys_crew", 1)) &&
                landCap(s, cbeat("boys_crew", 1)),
                "capstones screening: the naming lands (setup)")
            check(Capstones.accept(s, cbeat("boys_crew", 2)),
                "capstones screening: the premiere still arms (setup)")
            // a weekday evening at the Bijou: just a room
            var d = s.absDay
            while (MovieNights.isScreeningDay(d)) d++
            s.absDay = d; s.timeMin = MovieNights.DOORS_FROM + 30
            check(Capstones.onPhoto(s, photoAt("Bijou")).isEmpty() &&
                Capstones.activeBeat(s, "boys_crew") == cbeat("boys_crew", 2),
                "capstones screening: a photo on a non-screening night lands nothing")
            // a screening day at noon: the house isn't live
            d = s.absDay
            while (!MovieNights.isScreeningDay(d)) d++
            s.absDay = d; s.timeMin = 720
            check(!Capstones.screeningLive(s) &&
                Capstones.onPhoto(s, photoAt("Bijou")).isEmpty(),
                "capstones screening: at noon the premiere still is just a photo")
            // the screening, but the wrong room
            s.timeMin = MovieNights.DOORS_FROM + 30
            var g2 = 0
            while (!Capstones.screeningLive(s) && g2++ < 40) {
                s.absDay++; s.timeMin = MovieNights.DOORS_FROM + 30
            }
            check(Capstones.screeningLive(s),
                "capstones screening: a live house exists within the month (setup)")
            check(Capstones.onPhoto(s, photoAt("Mall")).isEmpty(),
                "capstones screening: a photo at the Mall during the show lands nothing")
            check(Capstones.onPhoto(s, photoAt("Bijou")).any {
                it.beat == cbeat("boys_crew", 2)
            }, "capstones screening: the still lands in the live house")
        }

        run {
            // ---------- the JOB funnel: show up, on the record ----------
            val s = freshState()
            runChain(s, "parents")
            var guard = 0
            while (Capstones.offerFor(s, "McDaniels") == null && guard++ < 300)
                incomeStep(s, "parents")
            check(Capstones.accept(s, cbeat("parents", 1)) &&
                landCap(s, cbeat("parents", 1)),
                "capstones work: the roster lands (setup)")
            check(Capstones.onShiftCompleted(s).isEmpty(),
                "capstones work: with no JOB beat armed, a settled shift lands nothing")
            // a full shift BEFORE the beat is armed: honest
            // work, but the roster wasn't open for it
            val preHit = driveShift(s)
            check(preHit != null && Jobs.shiftDoneToday(s) &&
                Capstones.beatsDone(s, "parents") == 1,
                "capstones work: a shift worked before the ask counts for the job, " +
                    "not the capstone")
            check(Capstones.accept(s, cbeat("parents", 2)),
                "capstones work: the JOB beat arms")
            s.absDay++
            val hit = driveShift(s)
            check(Capstones.beatsDone(s, "parents") == 2,
                "capstones work: a full shift, clock-in to clock-out, lands the beat")
            check(hit?.text?.contains("🏛") == true,
                "capstones work: the beat's line rides the clock-out text")
        }

        run {
            // ---------- ALL EIGHT, one long save — and the save keeps them ----------
            val s = freshState()
            for (fid in FACTIONS.map { it.id }) {
                runChain(s, fid)
                check(FactionMissions.chainDone(s, fid),
                    "capstones all-eight: the $fid chain completes (setup)")
                runCapstone(s, fid)
                check(Capstones.capstoneDone(s, fid),
                    "capstones all-eight: the $fid capstone is set — its gate was " +
                        "reached in this same save, rival costs and all")
            }
            check(Capstones.capstonesDone(s) == 8,
                "capstones all-eight: all eight capstones stand in one save")
            check(Capstones.titlesEarned(s).size == 8,
                "capstones all-eight: eight titles carried")
            check(Capstones.markTokensByLoc(s).values.flatten().toSet() ==
                Capstones.MARK_TOKENS,
                "capstones all-eight: all eight traces stand")
            check(Capstones.pageLines(s).first().contains("8 of 8"),
                "capstones all-eight: the page says so")
            // no lockout, stated positively: every faction
            // still stands above the floor the whole system
            // can ever charge it (chain 4 + capstone 4)
            for (fid in FACTIONS.map { it.id })
                check(Capstones.standingOf(s, fid) > -50,
                    "capstones all-eight: $fid was never locked out by the costs")
            // the morning after the last one, the report speaks
            s.absDay++
            check(Capstones.morningNote(s) != null,
                "capstones all-eight: the morning report notes the latest setting")
            // round-trip: masks, titles, traces survive whole
            val back = decodeGameState(encodeGameState(s))
            check(Capstones.capstonesDone(back) == 8 &&
                Capstones.titlesEarned(back) == Capstones.titlesEarned(s) &&
                Capstones.markTokensByLoc(back) == Capstones.markTokensByLoc(s),
                "capstones save: a save with all eight set round-trips whole")
            // and a pre-capstone save simply hasn't any
            val legacy = decodeGameState(encodeGameState(freshState()))
            check(Capstones.capstonesDone(legacy) == 0 &&
                Capstones.markTokensByLoc(legacy).isEmpty() &&
                Capstones.pageLines(legacy).any { it.contains("their chain comes first") },
                "capstones save: an old save loads with every capstone unasked")
        }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

// ================= v0.8.0c: Errand Emergencies =================
// Queue #8 item 3 — the errand system's third expansion
// (asks v0.4.0b, chains v0.6.0b): the favor that can't
// wait. Emergencies.kt owns the day, the clock and the
// outcomes; this section pins the contract end to end:
// the day's scenario is a pure function of the seed (one
// a day, inside the chance band), the deadline is the
// Walk graph's OWN minutes plus the allowance — across
// every (offer, stop) pair the generator can produce —
// the clock settles on the real tick and on Walk-priced
// minutes alike, success is judged by the ordinary verbs
// and pays rescue rates with the thread and the feats,
// failure costs exactly an abandoned errand's sigh and
// nothing else, the big moments own the town while they
// own it, the plate is never evicted, and a live deadline
// round-trips a save to the minute.
private fun sectionV080c(root: String) {
    println("== v0.8.0c: errand emergencies — the favor that can't wait ==")
    val eng = Engine(80803)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Emergencies.kt").readText()
        check(engSrc.contains("const val EMERG_CHANCE = 0.40") &&
            engSrc.contains("object Emergencies"),
            "emergencies: the module and its chance dial exist")

        val monthLens =
            intArrayOf(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
        fun keyOf(y: Int, m: Int, d: Int) = "%04d%02d%02d".format(y, m, d)
        fun freshOn(y: Int, m: Int, d: Int,
                    timeMin: Int = 10 * 60): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "Responder", DEFAULT_APPEARANCE)
            s.gameYear = y; s.gameMonth = m; s.gameDay = d
            s.todayKey = keyOf(y, m, d)
            s.timeMin = timeMin
            return s
        }
        fun nextDay(y: Int, m: Int, d: Int): Triple<Int, Int, Int> {
            var mm = m; var dd = d + 1; var yy = y
            if (dd > monthLens[mm - 1]) {
                dd = 1; mm++
                if (mm > 12) { mm = 1; yy++ }
            }
            return Triple(yy, mm, dd)
        }
        /* The first date from 2027-01-01 whose seeded
         * scenario is [scId] — the day generator is a pure
         * function of the date, so the search is exact.
         * Dates inside a season-finale window are skipped:
         * the finale owns those days outright (the first
         * "filing" date is 2027-02-28, the winter finale's
         * last day — the offer is correctly suppressed
         * there, and the deference pins below prove it). */
        fun scenarioState(scId: String,
                          timeMin: Int = 10 * 60): GameState? {
            var (y, m, d) = Triple(2027, 1, 1)
            repeat(1600) {
                val s = freshOn(y, m, d, timeMin)
                if (Emergencies.todaysScenario(s)?.id == scId &&
                    Finales.windowAt(s) == null) return s
                val n = nextDay(y, m, d)
                y = n.first; m = n.second; d = n.third
            }
            return null
        }
        fun park(s: GameState, name: String, loc: String) {
            s.agents[name]?.let {
                it.location = loc; it.destination = loc
                it.waypoints.clear()
            }
        }
        fun coinsOf(s: GameState): Int = Minigames.capsuleCoins(s)

        // ---------- the scenario registry ----------
        val scs = Emergencies.SCENARIOS
        check(scs.size >= 6,
            "emergencies: at least six authored scenarios (have ${scs.size})")
        check(scs.size == 8 && scs.map { it.id }.distinct().size == scs.size,
            "emergencies: eight scenarios, ids distinct")
        check(scs.map { it.type }.toSet() ==
            setOf("FETCH", "DELIVER", "FIND", "FIX"),
            "emergencies: the scenarios span all four verbs")
        val deny = listOf("sleepwalk", "professor chaos", "cameo",
            "strongbox", "commune", "the deed", "confessor",
            "confession", "culprit", "golden lure", "whittled")
        for (sc in scs) {
            val prose = listOf(sc.offerText, sc.shout, sc.successLine,
                sc.copingLine).joinToString(" ").lowercase()
            check(sc.asker in KID_ORDER && sc.offerText.isNotBlank() &&
                sc.shout.isNotBlank() && sc.successLine.isNotBlank() &&
                sc.copingLine.isNotBlank() && sc.shortTitle.isNotBlank() &&
                deny.none { it in prose },
                "emergencies: ${sc.id} is fully written (asker, offer, " +
                    "shout, success, coping) and touches no arc's answer")
            when (sc.type) {
                "DELIVER" -> check(sc.targetName in KID_ORDER &&
                    sc.targetName != sc.asker,
                    "emergencies: ${sc.id} delivers to a real townsfolk, " +
                        "not its asker")
                "FIND" -> check(sc.itemId.orEmpty() in Errands.FIND_POOL &&
                    sc.targetLoc.orEmpty() in LOCATIONS,
                    "emergencies: ${sc.id} hunts a findable thing in a " +
                        "real place")
                "FIX" -> check(
                    (sc.fixKind == "bench" &&
                        Errands.FIX_SPOTS.any {
                            it.kind == "bench" && it.locId == sc.targetLoc }) ||
                        (sc.fixKind == "lamp" && sc.targetLoc == null),
                    "emergencies: ${sc.id} fixes a real spot the FIX " +
                        "verb judges")
                "FETCH" -> check(Errands.sourceOf(sc.itemId.orEmpty()) == "stand" &&
                    sc.pickupLoc.orEmpty() in LOCATIONS,
                    "emergencies: ${sc.id} fetches an item from where " +
                        "it honestly comes from")
            }
        }
        check(Emergencies.EMERG_CHANCE in 0.30..0.50,
            "emergencies: the chance dial sits in the 30–50% band " +
                "(${Emergencies.EMERG_CHANCE})")
        check(Emergencies.RESCUE_FEATS.map { it.id } ==
            listOf("rescue_1", "rescue_10") &&
            Emergencies.RESCUE_FEATS.map { it.at } == listOf(1, 10) &&
            Emergencies.RESCUE_FEATS.all { it.desc.isNotBlank() },
            "emergencies: the rescue feats — First Responder at 1, " +
                "Steady Hands at 10")

        // ---------- feasibility: the whole space ----------
        // The deadline formula, pinned against the Walk
        // graph's own matrix for every ordered pair in
        // town (the generator's 1-stop space) and, by
        // aggregation, every chained triple (its 2-stop
        // space — the FETCH runs).
        val fs = freshOn(2027, 3, 3, 10 * 60)
        val locIds = LOCATIONS.keys.toList()
        for (a in locIds) for (b in locIds) {
            val route = Walk.routeMinutes(fs, a, b)
            val dl = Emergencies.deadlineFor(fs, a, listOf(b))
            check(dl - fs.timeMin ==
                route + Emergencies.allowance(1) && route >= 0,
                "emergencies: feasibility $a → $b — the deadline is " +
                    "the true walk ($route) plus the allowance, never less")
        }
        var tripleBad = 0
        for (a in locIds) for (b in locIds) for (c in locIds) {
            val expect = fs.timeMin + Walk.routeMinutes(fs, a, b) +
                Walk.routeMinutes(fs, b, c) + Emergencies.allowance(2)
            if (Emergencies.deadlineFor(fs, a, listOf(b, c)) != expect)
                tripleBad++
        }
        check(tripleBad == 0,
            "emergencies: feasibility across every chained triple — " +
                "the two-stop deadline is the sum of its true legs " +
                "($tripleBad mismatches)")
        check(Emergencies.allowance(1) ==
            Emergencies.WORK_MIN_PER_STOP + Emergencies.SLACK_MIN &&
            Emergencies.allowance(2) ==
            2 * Emergencies.WORK_MIN_PER_STOP + Emergencies.SLACK_MIN,
            "emergencies: the allowance is work-per-stop plus the " +
                "flat slack, exactly")

        // ---------- the day: one, seeded, in band ----------
        var carry = 0
        var (cy, cm, cd) = Triple(2027, 1, 1)
        repeat(400) {
            if (Emergencies.todaysScenario(freshOn(cy, cm, cd)) != null)
                carry++
            val n = nextDay(cy, cm, cd)
            cy = n.first; cm = n.second; cd = n.third
        }
        val share = carry / 400.0
        check(share in 0.25..0.55 && carry > 0,
            "emergencies: the soak — ${carry}/400 days carry one " +
                "(share ${"%.2f".format(share)}, inside the band " +
                "around the ${Emergencies.EMERG_CHANCE} dial)")
        val detA = Emergencies.todaysScenario(freshOn(2027, 6, 15))?.id
        val detB = Emergencies.todaysScenario(freshOn(2027, 6, 15))?.id
        check(detA == detB,
            "emergencies: the day's scenario is a pure function of " +
                "the date — same day, same emergency")

        // ---------- the offer ----------
        val os = scenarioState("slip_run")!!
        park(os, "Victoria", "Elementary"); park(os, "Sheila", "KyleHouse")
        val offer = Emergencies.pendingOffer(os, "Sheila", "KyleHouse")
        check(offer != null,
            "emergencies: meeting the asker on her day offers it")
        check(offer!!.deadlineMin > os.timeMin &&
            offer.deadlineMin <= Barks.QUIET_START &&
            offer.deadlineMin - os.timeMin ==
            offer.routeMin + Emergencies.allowance(1) &&
            offer.routeMin ==
            Walk.routeMinutes(os, "KyleHouse", "Elementary"),
            "emergencies: the offered deadline is honest — now + " +
                "the true walk + the allowance, inside the day")
        check(offer.errand.source == Errands.EMERG &&
            offer.errand.emergScenario == "slip_run" &&
            offer.errand.emergDeadline == offer.deadlineMin &&
            Errands.objective(offer.errand).startsWith("⏰"),
            "emergencies: the offer's errand carries its clock, " +
                "its scenario, and its ⏰")
        check(Emergencies.pendingOffer(os, "Kyle", "KyleHouse") == null,
            "emergencies: only the scenario's asker offers it")
        check(TalkGate.gateFor(os, "Sheila", "KyleHouse").rail ==
            TalkGate.Rail.EMERG_OFFER,
            "emergencies: the Talk gate rails the offer above a " +
                "fresh ask")
        Emergencies.markOffered(os, "Sheila")
        check(Emergencies.pendingOffer(os, "Sheila", "KyleHouse") == null &&
            TalkGate.gateFor(os, "Sheila", "KyleHouse").rail !=
            TalkGate.Rail.EMERG_OFFER,
            "emergencies: an offer made is an offer spent for the day")
        val tgSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        check(gateBody.indexOf("Emergencies.pendingOffer") >
            gateBody.indexOf("Capstones.offerFor") &&
            gateBody.indexOf("Emergencies.pendingOffer") <
            gateBody.indexOf("Errands.pendingAsk"),
            "emergencies: in the gate's own order the offer sits " +
                "below the set pieces and above the ask")
        // a DELIVER in hand still outranks the un-offered emergency
        val ds = scenarioState("slip_run")!!
        park(ds, "Victoria", "Elementary"); park(ds, "Sheila", "KyleHouse")
        ds.errands.add(Errand("held:d", Errands.ASK, "Stan", "DELIVER",
            "a parcel with Sheila's name on it", "",
            targetName = "Sheila", dayKey = ds.todayKey,
            acceptedDay = ds.absDay))
        check(TalkGate.gateFor(ds, "Sheila", "KyleHouse").rail ==
            TalkGate.Rail.DELIVER,
            "emergencies: a parcel for the asker still lands before " +
                "her emergency is offered")

        // ---------- the shout ----------
        val ss = scenarioState("slip_run")!!
        park(ss, "Victoria", "Elementary"); park(ss, "Sheila", "KyleHouse")
        eng.player(ss).location = "KyleHouse"
        eng.player(ss).destination = "KyleHouse"
        val shout = Emergencies.entryShout(ss)
        check(shout != null && shout.contains("Sheila") &&
            ss.events.any { it.startsWith("🚨") },
            "emergencies: walking into the asker's space earns " +
                "the shout, once, on the ticker")
        check(Emergencies.entryShout(ss) == null,
            "emergencies: the shout does not repeat")
        val far = scenarioState("slip_run")!!
        park(far, "Victoria", "Elementary"); park(far, "Sheila", "KyleHouse")
        eng.player(far).location = "BusStop"
        eng.player(far).destination = "BusStop"
        check(Emergencies.entryShout(far) == null,
            "emergencies: no shout from across town")

        // ---------- quiet hours & infeasible evenings ----------
        val qDay = scenarioState("slip_run", 23 * 60)
        check(qDay != null && Emergencies.todaysScenario(qDay) != null &&
            Emergencies.pendingOffer(qDay, "Sheila", "KyleHouse") == null,
            "emergencies: never offered in quiet hours")
        val qDawn = scenarioState("slip_run", 5 * 60)!!
        check(Emergencies.pendingOffer(qDawn, "Sheila", "KyleHouse") == null,
            "emergencies: never offered before the town wakes")
        val late = scenarioState("slip_run", 22 * 60)!!
        val farLoc = locIds.maxByOrNull {
            Walk.routeMinutes(late, "KyleHouse", it) }!!
        park(late, "Sheila", "KyleHouse"); park(late, "Victoria", farLoc)
        check(Walk.routeMinutes(late, "KyleHouse", farLoc) > 0 &&
            Emergencies.pendingOffer(late, "Sheila", "KyleHouse") == null,
            "emergencies: a route that can't honestly finish " +
                "before quiet hours is never offered")

        // ---------- deference: the big moments own the town ----------
        val plain = freshOn(2027, 3, 3, 10 * 60)
        check(!Emergencies.momentOwned(plain),
            "emergencies: a plain midday is unowned")
        val hol = freshOn(2027, 3, 3, 10 * 60)
        hol.holidayId = "christmas"
        check(Emergencies.momentOwned(hol),
            "emergencies: a holiday beat owns the moment")
        val fin = freshOn(2027, 5, 25, 10 * 60)
        fin.life["fin:spring:2027:start"] = 5
        check(Finales.windowAt(fin) != null &&
            Emergencies.momentOwned(fin),
            "emergencies: a season finale week owns the moment")
        val caseS = freshOn(2027, 3, 3, 13 * 60)
        caseS.shenaniganId = Mystery.FINALE_ID
        caseS.mysteryClues += Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES)
            .map { it.id }
        check(Walk.caseCritical(caseS) && Emergencies.momentOwned(caseS),
            "emergencies: a case climax on the table owns the moment")
        val scrDay = (0..13).first { MovieNights.isScreeningDay(it) }
        val scr = freshOn(2027, 3, 3, MovieNights.DOORS_FROM + 30)
        scr.absDay = scrDay
        check(!MovieNights.isDarkTonight(scr) &&
            Emergencies.momentOwned(scr),
            "emergencies: a live Bijou screening owns the moment")
        val beeDay = (0..13).first { School.isBeeDay(it) }
        val bee = freshOn(2027, 3, 3, 13 * 60 + 30)
        bee.absDay = beeDay
        check(Emergencies.momentOwned(bee),
            "emergencies: the spelling bee's hours own the moment")
        val beeEarly = freshOn(2027, 3, 3, 12 * 60 + 30)
        beeEarly.absDay = beeDay
        check(!Emergencies.momentOwned(beeEarly),
            "emergencies: the bee owns its hours, not the morning")
        val fid = Capstones.CHAINS.first().factionId
        val cer = freshOn(2027, 3, 3, 16 * 60)
        cer.life["capActive:$fid"] = 3
        check(Emergencies.momentOwned(cer),
            "emergencies: an armed capstone ceremony owns its window")
        val cerEarly = freshOn(2027, 3, 3, 12 * 60)
        cerEarly.life["capActive:$fid"] = 3
        check(!Emergencies.momentOwned(cerEarly),
            "emergencies: the ceremony owns its window, not the day")
        // the integration: owned moments suppress the offer itself
        val owned = scenarioState("slip_run")!!
        park(owned, "Victoria", "Elementary")
        park(owned, "Sheila", "KyleHouse")
        owned.holidayId = "christmas"
        check(Emergencies.pendingOffer(owned, "Sheila", "KyleHouse") == null,
            "emergencies: with a bigger moment live, the offer " +
                "does not fire")
        owned.holidayId = null
        check(Emergencies.pendingOffer(owned, "Sheila", "KyleHouse") != null,
            "emergencies: the moment released, the offer returns")

        // ---------- decline: the day is spent, and that is all ----------
        val dc = scenarioState("slip_run")!!
        Emergencies.decline(dc)
        check(Emergencies.todaysScenario(dc) == null &&
            Emergencies.pendingOffer(dc, "Sheila", "KyleHouse") == null,
            "emergencies: a declined emergency does not re-fire " +
                "that day")

        // ---------- rescue: DELIVER ----------
        val rs = scenarioState("slip_run")!!
        park(rs, "Victoria", "Elementary"); park(rs, "Sheila", "KyleHouse")
        val rOffer = Emergencies.pendingOffer(rs, "Sheila", "KyleHouse")!!
        val placed = Emergencies.accept(rs, rOffer)
        check(placed != null && Emergencies.liveEmergency(rs) != null &&
            Emergencies.accept(rs, rOffer) == null,
            "emergencies: accept puts it on the clock; a second " +
                "accept is refused while one runs")
        check(Emergencies.todaysScenario(rs) == null,
            "emergencies: the accepted day carries no second one")
        val dFr = (Errands.FRIENDSHIP["DELIVER"] ?: 0) +
            Emergencies.RESCUE_FRIENDSHIP_BONUS
        val dCoins = (Errands.COINS["DELIVER"] ?: 0) +
            Emergencies.RESCUE_COIN_BONUS
        val dComp = Errands.deliverTo(rs, "Victoria")
        check(dComp != null && dComp.errand.id == placed!!.id &&
            dComp.reward.friendship == dFr && dComp.reward.coins == dCoins,
            "emergencies: a landed rescue pays its verb's rates " +
                "plus the rescue bonus (+$dFr 💛, +$dCoins 🪙)")
        check(Emergencies.rescuesDone(rs) == 1 && rs.errandsDoneCount == 1 &&
            rs.lifeText["errandThanks:Sheila"] ==
            Emergencies.scenarioById("slip_run")!!.successLine &&
            NpcMemoryStore.get("Sheila")?.topics
                ?.contains(Emergencies.RESCUE_TOPIC) == true &&
            rs.events.any { it.contains("🚨 RESCUE") },
            "emergencies: the rescue is counted, thanked in the " +
                "asker's own words, and threaded in their memory")
        check(Emergencies.rescueFeatEarned(rs, Emergencies.RESCUE_FEATS[0]) &&
            !Emergencies.rescueFeatEarned(rs, Emergencies.RESCUE_FEATS[1]),
            "emergencies: First Responder lands at one rescue; " +
                "Steady Hands waits")
        val threadsSrc = File(root,
            "src/com/hunt3r/southparktown/Threads.kt").readText()
        check(threadsSrc.contains("\"rescue\" to listOf("),
            "emergencies: Threads carries a follow-up bank for " +
                "the rescue topic")
        // the morning after a rescue
        rs.absDay += 1
        check(House.morningReport(rs, emptyList(), emptyMap(), 0,
            false, null).any {
                it.startsWith("🚨 Yesterday:") && it.contains("Sheila") },
            "emergencies: the morning report keeps yesterday's rescue")

        // ---------- rescue: FIND / FIX / FETCH ----------
        fun rescueVia(scId: String, judge: (GameState) -> Any?): Int {
            val s = scenarioState(scId) ?: return -1
            val sc = Emergencies.scenarioById(scId)!!
            val at = s.agents[sc.asker]?.location ?: return -2
            val o = Emergencies.pendingOffer(s, sc.asker, at) ?: return -3
            Emergencies.accept(s, o) ?: return -4
            judge(s) ?: return -5
            return Emergencies.rescuesDone(s)
        }
        check(rescueVia("ticket_stub") {
            if (Errands.recoverFind(it, "KidsPark") != null) null else
                Errands.recoverFind(it, "BusStop")
        } == 1,
            "emergencies: a FIND rescue is judged at its place — " +
                "the wrong park finds nothing, the bus stop lands it")
        check(rescueVia("bench_photo") {
            if (Errands.onFixTap(it, "bench", "BusStop") != null) null else
                Errands.onFixTap(it, "bench", "KidsPark")
        } == 1,
            "emergencies: a FIX rescue is judged at its spot — " +
                "the wrong bench wobbles on, the right one lands it")
        check(rescueVia("lamp_telescope") {
            Errands.onFixTap(it, "lamp", Errands.flickerLoc(it.absDay))
        } == 1,
            "emergencies: the lamp rescue is judged at tonight's " +
                "flickering light")
        check(rescueVia("lemonade_run") {
            it.inventory["lemonade"] =
                (it.inventory["lemonade"] ?: 0) + 1
            Errands.handInFetch(it, "Nichole", "lemonade")
        } == 1,
            "emergencies: a FETCH rescue is judged by the hand-in, " +
                "stand lemonade and all")
        check(rescueVia("filing") {
            park(it, "McDaniels", "CityHall")
            Errands.deliverTo(it, "McDaniels")
        } == 1,
            "emergencies: the second DELIVER rescue lands at City Hall")

        // ---------- feats across the threshold ----------
        val fs10 = scenarioState("ticket_stub")!!
        fs10.life["rescuesDone"] = 9
        val fAt = fs10.agents["Clyde"]!!.location
        val fOffer = Emergencies.pendingOffer(fs10, "Clyde", fAt)!!
        Emergencies.accept(fs10, fOffer)
        Errands.recoverFind(fs10, "BusStop")
        check(Emergencies.rescuesDone(fs10) == 10 &&
            Emergencies.rescueFeatEarned(fs10, Emergencies.RESCUE_FEATS[1]) &&
            fs10.events.any { it.contains("Steady Hands") },
            "emergencies: the tenth rescue crosses Steady Hands, " +
                "announced on the ticker")

        // ---------- the clock: ticks ----------
        val cs = scenarioState("ticket_stub")!!
        val cAt = cs.agents["Clyde"]!!.location
        val cOffer = Emergencies.pendingOffer(cs, "Clyde", cAt)!!
        val cPlaced = Emergencies.accept(cs, cOffer)!!
        val dl = cPlaced.emergDeadline
        val frC = cs.friendship["Clyde"] ?: 0
        val coinsC = coinsOf(cs)
        val doneC = cs.errandsDoneCount
        var guard = 0
        while (cs.timeMin + 15 < dl && guard++ < 200) eng.inGameTick(cs)
        check(Emergencies.liveEmergency(cs) != null &&
            cs.timeMin < dl,
            "emergencies: the clock — alive on the last tick " +
                "before the deadline")
        var expiredAt = -1
        guard = 0
        while (guard++ < 40) {
            eng.inGameTick(cs)
            if (Emergencies.liveEmergency(cs) == null) {
                expiredAt = cs.timeMin; break
            }
        }
        check(expiredAt >= dl && expiredAt < dl + 15,
            "emergencies: the clock settles on the first tick at " +
                "or past the deadline (due $dl, settled $expiredAt) " +
                "— no rubber-banding, no secret extension")
        check((cs.friendship["Clyde"] ?: 0) == frC &&
            coinsOf(cs) == coinsC && cs.errandsDoneCount == doneC &&
            Emergencies.rescuesDone(cs) == 0,
            "emergencies: failure's ceiling — friendship, coins " +
                "and counts exactly where they were; the ONLY cost " +
                "is the moment")
        val coping = Emergencies.scenarioById("ticket_stub")!!.copingLine
        check(cs.lifeText["emergCoping:Clyde"] == coping &&
            cs.errandsRecent.any { "the town coped" in it.line } &&
            Emergencies.todaysScenario(cs) == null &&
            Emergencies.pendingOffer(cs, "Clyde", cAt) == null,
            "emergencies: a lapsed rescue leaves its coping beat, " +
                "its recent note, and no re-fire that day")
        check(TalkGate.owedLines(cs, "Clyde").any { it.text == coping } &&
            TalkGate.owedLines(cs, "Clyde").none { it.text == coping },
            "emergencies: the coping beat plays once, at the next " +
                "meeting, on the owed-lines rail")
        cs.absDay += 1
        check(House.morningReport(cs, emptyList(), emptyMap(), 0,
            false, null).any {
                it.startsWith("🚨 Yesterday:") && it.contains("Clyde") &&
                    it.contains("town coped") },
            "emergencies: the morning report notes the moment " +
                "that passed — the town coped, in one line")

        // ---------- the clock: Walk-priced minutes ----------
        val ws = scenarioState("ticket_stub")!!
        val wAt = ws.agents["Clyde"]!!.location
        val wOffer = Emergencies.pendingOffer(ws, "Clyde", wAt)!!
        val wPlaced = Emergencies.accept(ws, wOffer)!!
        Walk.applyMinutes(ws, (wPlaced.emergDeadline - ws.timeMin) + 30)
        check(Emergencies.liveEmergency(ws) == null &&
            ws.lifeText["emergCoping:Clyde"] != null,
            "emergencies: walking the route's true minutes plus " +
                "change spends the clock — travel is time")

        // ---------- dropping one by hand ----------
        val xs = scenarioState("ticket_stub")!!
        val xAt = xs.agents["Clyde"]!!.location
        val xOffer = Emergencies.pendingOffer(xs, "Clyde", xAt)!!
        val xPlaced = Emergencies.accept(xs, xOffer)!!
        val frX = xs.friendship["Clyde"] ?: 0
        val sigh = Errands.abandon(xs, xPlaced.id)
        check(sigh != null && Emergencies.liveEmergency(xs) == null &&
            xs.lifeText["emergCoping:Clyde"] != null &&
            (xs.friendship["Clyde"] ?: 0) == frX &&
            Emergencies.rescuesDone(xs) == 0,
            "emergencies: putting one down costs the abandoned " +
                "errand's sigh and nothing more — and the town copes")

        // ---------- the plate: its own slot ----------
        val ps = scenarioState("slip_run")!!
        park(ps, "Victoria", "Elementary"); park(ps, "Sheila", "KyleHouse")
        var filled = 0
        for (e in Errands.boardOpen(ps))
            if (Errands.accept(ps, e)) filled++
        var fi = 0
        while (Errands.activeCount(ps) < Errands.MAX_ACTIVE && fi < 12) {
            fi++
            Errands.accept(ps, Errand("fill:$fi", Errands.ASK, "Stan",
                "FETCH", "a filler favor", "", itemId = "flower",
                dayKey = ps.todayKey))
        }
        check(Errands.activeCount(ps) == Errands.MAX_ACTIVE,
            "emergencies: plate setup — six held errands")
        val heldIds = Errands.active(ps).map { it.id }.toSet()
        val pOffer = Emergencies.pendingOffer(ps, "Sheila", "KyleHouse")!!
        val pPlaced = Emergencies.accept(ps, pOffer)
        check(pPlaced != null && Errands.activeCount(ps) ==
            Errands.MAX_ACTIVE + 1 &&
            heldIds.all { id -> Errands.active(ps).any { it.id == id } },
            "emergencies: the rescue takes its OWN slot — seven " +
                "active, nothing evicted, nothing dropped")
        check(!Errands.accept(ps, Errand("fill:overflow", Errands.ASK,
            "Stan", "FETCH", "one too many", "", itemId = "flower",
            dayKey = ps.todayKey)),
            "emergencies: the ordinary cap still holds with an " +
                "emergency aboard")

        // ---------- the Journal page ----------
        val pg = Errands.pageLines(ps)
        check(pg.any { it.startsWith("🚨 EMERGENCY") &&
            it.contains(minutesToTimeStr(pPlaced!!.emergDeadline)) &&
            it.contains("min left") } &&
            pg.any { it.startsWith("ON YOUR PLATE (6/") },
            "emergencies: the Journal marks the emergency ⏰ with " +
                "its deadline, and the plate counts only its own six")
        check(Errands.pageLines(rs).first()
            .contains("🚨 1 emergencies answered"),
            "emergencies: the Journal header counts the rescues run")

        // ---------- saves: the deadline round-trips ----------
        val sv = scenarioState("ticket_stub")!!
        val sAt = sv.agents["Clyde"]!!.location
        val sOffer = Emergencies.pendingOffer(sv, "Clyde", sAt)!!
        val sPlaced = Emergencies.accept(sv, sOffer)!!
        val back = decodeGameState(encodeGameState(sv))
        val e2 = Emergencies.liveEmergency(back)
        check(e2 != null && e2.emergDeadline == sPlaced.emergDeadline &&
            e2.emergScenario == "ticket_stub" &&
            Errands.recoverFind(back, "BusStop") != null &&
            Emergencies.rescuesDone(back) == 1,
            "emergencies: a save/load mid-emergency preserves the " +
                "deadline to the minute — and it still lands")
        val legacy = Errand.fromMap(mapOf("id" to "old:1",
            "source" to "ASK", "asker" to "Stan", "type" to "FETCH",
            "text" to "an old favor", "hint" to "somewhere"))
        check(legacy != null && legacy.emergDeadline == -1 &&
            legacy.emergScenario == "",
            "emergencies: a pre-0.8.0c errand record loads with " +
                "no clock on it")
        val single = Errand("one:1", Errands.ASK, "Stan", "FETCH",
            "a plain favor", "", itemId = "flower")
        check(single.toMap().keys.none { it.startsWith("emerg") },
            "emergencies: ordinary errands serialize exactly as " +
                "they always have — the new fields ride EMERG only")
        val freshBack = decodeGameState(encodeGameState(freshOn(2027, 4, 1)))
        check(Emergencies.liveEmergency(freshBack) == null &&
            Emergencies.rescuesDone(freshBack) == 0,
            "emergencies: a fresh-shaped save loads quiet — no " +
                "phantom emergency, no phantom rescues")
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

// ================= v0.8.0d: the town yearbook =================
// Every spring the Elementary judges the player's album and
// prints it back: six categories scored from record fields
// alone, starred photos nudged by a stated bonus, the
// winners kept as record copies inside the volume, the
// argument planted as memory topics. This section pins the
// calendar, the formulas, the determinism, the shelf cap,
// and the judges' factual discipline — a note may only say
// what its record can prove.
private fun sectionV080d(root: String) {
    println("== v0.8.0d: the town yearbook — your album, judged ==")
    val eng = Engine(80804)
    val memSnapshot = NpcMemoryStore.serialize()
    try {
        val ybSrc = File(root,
            "src/com/hunt3r/southparktown/Yearbook.kt").readText()
        check(ybSrc.contains("object Yearbook") &&
            ybSrc.contains("const val STAR_BONUS = 15"),
            "yearbook: the module and its star dial exist")
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engSrc.contains("Yearbook.dailyRollover(state)"),
            "yearbook: the rollover is wired into onNewDay")
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(journalSrc.contains("📖 YEARBOOK") &&
            journalSrc.contains("Star for the yearbook"),
            "yearbook: the Journal carries the shelf and the " +
                "album's star toggle")

        fun keyOf(y: Int, m: Int, d: Int) = "%04d%02d%02d".format(y, m, d)
        fun absOfKey(key: String): Int =
            ordinalOfKey(key) - ordinalOfKey("20261001")
        fun freshOn(y: Int, m: Int, d: Int,
                    timeMin: Int = 10 * 60): GameState {
            val s = eng.newState()
            eng.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
            s.gameYear = y; s.gameMonth = m; s.gameDay = d
            s.todayKey = keyOf(y, m, d)
            s.absDay = absOfKey(s.todayKey)
            s.timeMin = timeMin
            return s
        }
        fun setDate(s: GameState, y: Int, m: Int, d: Int) {
            s.gameYear = y; s.gameMonth = m; s.gameDay = d
            s.todayKey = keyOf(y, m, d)
            s.absDay = absOfKey(s.todayKey)
        }
        fun fig(name: String, reaction: String = "neutral",
                pose: String = "none", kind: String = "cast") =
            PhotoFigure(name, kind,
                if (reaction == "goofy") "goofy"
                else if (reaction == "happy" ||
                    reaction == "bomb") "happy" else "idle",
                pose, null, reaction, 0)
        fun rec(id: String, key: String,
                npcs: List<PhotoFigure> = emptyList(),
                timeMin: Int = 12 * 60, locId: String = "StarksPond",
                inside: Boolean = false, weatherId: String = "sunny",
                followers: Int = 0, composition: String = "",
                refused: List<String> = emptyList(), asker: String = "",
                starred: Boolean = false): PhotoRecord =
            PhotoRecord(id = id, dayKey = key,
                dateLabel = if (key.length == 8)
                    "${key.substring(4, 6).toInt()}/" +
                        "${key.substring(6, 8).toInt()}" else "",
                timeMin = timeMin, locId = locId, inside = inside,
                weatherId = weatherId, appearance = DEFAULT_APPEARANCE,
                figures = listOf(
                    PhotoFigure("New Kid", "player", "happy")) + npcs,
                refused = refused, caption = "cap $id",
                followersGained = followers, seed = 7L,
                absDay = absOfKey(key), composition = composition,
                commissionAsker = asker,
                commissionText = if (asker.isEmpty()) "" else "the ask",
                starred = starred)

        // ---------- the registry & the masthead ----------
        check(Yearbook.CATEGORIES.size == 6 &&
            Yearbook.CATEGORIES.map { it.id }.distinct().size == 6,
            "yearbook: six categories, ids distinct")
        check(Yearbook.CATEGORIES.map { it.id } == listOf(
            "group", "selfie", "sky", "commissioned", "busy",
            "favorite"),
            "yearbook: the category slate is the designed six")
        check(Yearbook.EDITORS.map { it.name } ==
            listOf("Wendy", "Jimmy", "Cartman") &&
            Yearbook.EDITORS.all { it.name in KID_ORDER },
            "yearbook: three cast editors judge the book")
        check(Yearbook.STAR_BONUS == 15 &&
            Yearbook.FULL_VOLUMES == 3 &&
            Yearbook.THIN_COUNT == 6 &&
            Yearbook.ARGUMENT_DAYS == 4,
            "yearbook: the dials sit at their ledger values " +
                "(star 15, shelf 3, thin 6, argument 4)")
        check((0..2).map { Yearbook.judgeFor(2027, it).name }
            .toSet().size == 3,
            "yearbook: one volume spreads its pages across " +
                "all three editors")

        // ---------- the calendar ----------
        check(Yearbook.schoolYearOf("20261001") == 2027 &&
            Yearbook.schoolYearOf("20270531") == 2027 &&
            Yearbook.schoolYearOf("20270601") == 2028 &&
            Yearbook.schoolYearOf("20280101") == 2028 &&
            Yearbook.schoolYearOf("20260531") == 2026,
            "yearbook: the school year runs June to May, named " +
                "for its closing spring")
        check(Yearbook.schoolYearOf("") == null &&
            Yearbook.schoolYearOf("20269901") == null,
            "yearbook: an unreadable date belongs to no year — " +
                "the book never re-dates a photo")
        check(Yearbook.endKeyOf(2027) == "20270531" &&
            Finales.seasonEndMonthDay(Season.SPRING, 2027) ==
                (5 to 31),
            "yearbook: the year closes on spring's last day, " +
                "the boundary Finales already computes")
        check(Yearbook.labelOf(2027) == "2026–27",
            "yearbook: the 2027 book wears the 2026–27 label")
        check(Yearbook.mostRecentEndedYear(freshOn(2027, 6, 1)) == 2027 &&
            Yearbook.mostRecentEndedYear(freshOn(2027, 5, 31)) == 2026 &&
            Yearbook.mostRecentEndedYear(freshOn(2028, 1, 15)) == 2027,
            "yearbook: the ended year turns over on June 1")

        // ---------- scoring: fields only, by hand ----------
        val groupRec = rec("g1", "20270310",
            listOf(fig("Stan", "goofy", "backToBack"),
                fig("Kyle", "goofy", "backToBack"),
                fig("Wendy", "happy")),
            followers = 10, composition = "squad")
        check(Yearbook.rawScore(Yearbook.CAT_GROUP, groupRec) == 58 &&
            Yearbook.scoreOf(Yearbook.CAT_GROUP, groupRec) == 58,
            "yearbook: group = 12/npc + 6/back-to-back pair + " +
                "3/goofy + followers (3 npcs, 1 pair, 2 goofy, " +
                "10 followers = 58)")
        val groupStar = rec("g2", "20270310",
            listOf(fig("Stan", "goofy", "backToBack"),
                fig("Kyle", "goofy", "backToBack"),
                fig("Wendy", "happy")),
            followers = 10, composition = "squad", starred = true)
        check(Yearbook.scoreOf(Yearbook.CAT_GROUP, groupStar) == 73,
            "yearbook: a star is worth exactly +15 on top of " +
                "the fields")
        val selfieRec = rec("s1", "20270311",
            listOf(fig("Kenny", "goofy")), followers = 20)
        check(Yearbook.rawScore(Yearbook.CAT_SELFIE, selfieRec) == 28,
            "yearbook: selfie = followers + 6/goofy + 3/happy " +
                "+ 2/npc (20 + 6 + 0 + 2 = 28)")
        check(!Yearbook.qualifies(Yearbook.CAT_SELFIE, groupRec) &&
            !Yearbook.qualifies(Yearbook.CAT_SELFIE,
                rec("s2", "20270311",
                    listOf(fig("Stan"), fig("Kyle"), fig("Wendy")))) &&
            !Yearbook.qualifies(Yearbook.CAT_SELFIE,
                rec("s3", "20270311")),
            "yearbook: selfies are the classic frame with one " +
                "or two townsfolk — groups, crowds and solo " +
                "shots need not apply")
        val commRec = rec("c1", "20270312",
            listOf(fig("Stan"), fig("Kyle")),
            followers = 5, asker = "Wendy")
        check(Yearbook.rawScore(Yearbook.CAT_COMMISSIONED,
            commRec) == 25 &&
            Yearbook.qualifies(Yearbook.CAT_COMMISSIONED, commRec) &&
            !Yearbook.qualifies(Yearbook.CAT_COMMISSIONED, selfieRec),
            "yearbook: commissioned = followers + 5/npc + 10 " +
                "for the stamp (5 + 10 + 10 = 25), and only " +
                "prints qualify")
        val busyRec = rec("b1", "20270313",
            listOf(fig("Stan"), fig("Kyle"), fig("Wendy"),
                fig("Craig")),
            refused = listOf("Cartman", "Butters"))
        check(Yearbook.rawScore(Yearbook.CAT_BUSY, busyRec) == 62 &&
            !Yearbook.qualifies(Yearbook.CAT_BUSY, selfieRec),
            "yearbook: busy = 10/figure + 4/refusal + npcs " +
                "(5 in frame, 2 refused, 4 npcs = 62), gated " +
                "at four in the frame")
        check(Yearbook.rawScore(Yearbook.CAT_FAVORITE,
            rec("f1", "20270314", listOf(fig("Stan")),
                followers = 7)) == 17,
            "yearbook: favorite = 2 x followers + 3/npc " +
                "(14 + 3 = 17) — the town's love, in its own " +
                "currency")

        // the sky: hunt a real aurora night off SkyState's
        // own math, then judge a photo taken under it
        var aurora: Pair<String, Int>? = null
        for (abs in 0..800) {
            val k = keyFromOrdinal(ordinalOfKey("20261001") + abs)
            val mo = k.substring(4, 6).toInt()
            if (SkyState.specialAt(abs, 23 * 60, "sunny",
                    seasonFor(mo)) == SkyState.AURORA) {
                aurora = k to abs; break
            }
        }
        check(aurora != null,
            "yearbook: an aurora night exists in the first " +
                "two years of sky")
        val skyRec = rec("k1", aurora!!.first, timeMin = 23 * 60)
        check(Yearbook.skySpecialOf(skyRec) == SkyState.AURORA &&
            Yearbook.rawScore(Yearbook.CAT_SKY, skyRec) == 45,
            "yearbook: sky = special (aurora 40) + weather " +
                "drama (sunny 2) + night (3) = 45, all off the " +
                "record's own fields")
        val plainSky = rec("k2", "20270315", timeMin = 12 * 60,
            weatherId = "cloudy")
        check(Yearbook.skySpecialOf(plainSky) == SkyState.NONE &&
            Yearbook.rawScore(Yearbook.CAT_SKY, plainSky) == 4 &&
            !Yearbook.qualifies(Yearbook.CAT_SKY,
                rec("k3", "20270315", inside = true)),
            "yearbook: a plain cloudy noon scores its drama " +
                "(4) and no special; interiors have no sky")

        // ties break by the earlier day, then the id — the
        // same album ranks identically forever
        val tieA = rec("tie-b", "20270301", listOf(fig("Stan")),
            followers = 5)
        val tieB = rec("tie-a", "20270302", listOf(fig("Kyle")),
            followers = 5)
        val tieC = rec("tie-a", "20270301", listOf(fig("Wendy")),
            followers = 5)
        check(Yearbook.ranked(Yearbook.CAT_FAVORITE,
            listOf(tieA, tieB, tieC)).map { it.id } ==
            listOf("tie-a", "tie-b", "tie-a") &&
            Yearbook.ranked(Yearbook.CAT_FAVORITE,
                listOf(tieA, tieB, tieC))[0] === tieC,
            "yearbook: equal scores rank by earlier day, then " +
                "id — deterministic to the record")

        // ---------- judging: determinism & the volume ----------
        fun judgedState(): GameState {
            val s = freshOn(2027, 3, 20)
            s.photos += groupRec
            s.photos += selfieRec
            s.photos += commRec
            s.photos += busyRec
            s.photos += skyRec
            s.photos += rec("x1", "20261225",
                listOf(fig("Butters", "happy")), followers = 30)
            s.photos += rec("x2", "20270615",
                listOf(fig("Stan")), followers = 99)  // next year
            s.photos += rec("x3", "20260520",
                listOf(fig("Stan")), followers = 99)  // last year
            return s
        }
        val js = judgedState()
        val bookA = Yearbook.judge(js, 2027).volume
        val bookB = Yearbook.judge(js, 2027).volume
        check(bookA == bookB,
            "yearbook: the same album makes the same book, " +
                "twice in a row, to the letter")
        val jsBack = decodeGameState(encodeGameState(js))
        check(Yearbook.judge(jsBack, 2027).volume == bookA,
            "yearbook: a save/reload between judgings changes " +
                "nothing — the book is a pure function of the album")
        check(bookA.photoCount == 6 && bookA.entries.size == 6 &&
            !bookA.pamphlet && !bookA.indexOnly,
            "yearbook: only the school year's own six photos " +
                "were judged — no borrowing across the turn")
        check(bookA.entries.all { e ->
            val cat = Yearbook.categoryById(e.categoryId)!!
            e.record == null ||
                (Yearbook.ranked(cat, Yearbook.albumFor(js, 2027))
                    .firstOrNull()?.id == e.record!!.id &&
                    e.score == Yearbook.scoreOf(cat, e.record!!))
            },
            "yearbook: every page's winner is its category's " +
                "top-ranked record, at its judged score")
        check(bookA.entries.first {
            it.categoryId == "sky" }.record?.id == "k1",
            "yearbook: the aurora frame takes the sky page")
        check(bookA.winnersLine.contains("🏆") &&
            bookA.winnersLine.split("·").size ==
                bookA.entries.count { it.record != null },
            "yearbook: the index line names every page that " +
                "has a winner")

        // ---------- the judges' factual discipline ----------
        // Every note the banks can produce, over a matrix of
        // records: any cast name it speaks must be standing
        // in the frame (or have commissioned it); any place
        // it names must be the record's place; any sky or
        // weather word must be the record's own.
        val locNames = LOCATIONS.values.map { it.name }
        val skyWords = mapOf("aurora" to SkyState.AURORA,
            "meteor" to SkyState.METEOR,
            "harvest moon" to SkyState.HARVEST)
        val weatherWords = listOf("blizzard", "fog", "rain",
            "snow", "sunny", "cloudy", "wind")
        var noteCount = 0
        for (judge in Yearbook.EDITORS) {
            for (cat in Yearbook.CATEGORIES) {
                val variants = listOf(
                    rec("n1", "20270310", listOf(fig("Stan")),
                        asker = ""),
                    rec("n2", aurora!!.first,
                        listOf(fig(judge.name, "happy"),
                            fig("Kyle", "goofy", "backToBack"),
                            fig("Wendy", "goofy", "backToBack")),
                        timeMin = 23 * 60, followers = 12,
                        composition = "stacked", asker = "McDaniels",
                        locId = "Bijou"),
                    rec("n3", "20270105",
                        listOf(fig("Cartman"), fig("Kenny"),
                            fig("Butters"), fig("Craig")),
                        weatherId = "blizzard", followers = 3,
                        locId = "Elementary", refused =
                            listOf("Token")),
                    rec("n4", "20270401", inside = true,
                        locId = "CityHall"))
                for (v in variants) {
                    val note = Yearbook.noteFor(judge, cat, v)
                    noteCount++
                    val low = note.lowercase()
                    val allowedNames = v.npcs.map { it.name } +
                        listOf(v.commissionAsker)
                    check(KID_ORDER.none { n ->
                        n in note && n !in allowedNames },
                        "yearbook notes: ${judge.name}/${cat.id} " +
                            "names nobody outside the record")
                    check(locNames.none { ln ->
                        ln in note &&
                            ln != (LOCATIONS[v.locId]?.name ?: "") },
                        "yearbook notes: ${judge.name}/${cat.id} " +
                            "places the photo somewhere it wasn't")
                    check(skyWords.none { (w, kind) ->
                        w in low && Yearbook.skySpecialOf(v) != kind },
                        "yearbook notes: ${judge.name}/${cat.id} " +
                            "praises a sky the record never had")
                    check(weatherWords.none { w ->
                        w in low && w !in
                            (WEATHER[v.weatherId]?.label
                                ?: "").lowercase() &&
                            w !in Yearbook.skySpecialOf(v) },
                        "yearbook notes: ${judge.name}/${cat.id} " +
                            "swears to weather the record never had")
                }
            }
        }
        check(noteCount == 3 * 6 * 4,
            "yearbook notes: the full judge x category x " +
                "record matrix was audited ($noteCount notes)")

        // ---------- blank, thin and zero years ----------
        val thinState = freshOn(2027, 2, 1)
        thinState.photos += rec("t1", "20270110",
            listOf(fig("Stan", "happy")), followers = 4)
        thinState.photos += rec("t2", "20270112",
            listOf(fig("Kyle", "goofy")), followers = 9)
        val thinBook = Yearbook.judge(thinState, 2027).volume
        check(thinBook.photoCount == 2 && thinBook.pamphlet &&
            thinBook.entries.size == 6 &&
            thinBook.entries.count { it.record == null } == 3 &&
            thinBook.entries.filter { it.record == null }
                .map { it.categoryId }.toSet() ==
                setOf("group", "commissioned", "busy") &&
            thinBook.entries.first {
                it.categoryId == "favorite" }.record?.id == "t2" &&
            thinBook.entries.first {
                it.categoryId == "sky" }.record?.id == "t1",
            "yearbook: a two-photo year is a pamphlet — group, " +
                "commissioned and busy stay blank, the sky " +
                "crowns the earlier frame on the tie, the " +
                "favorite still crowns")
        check(thinBook.entries.filter { it.record == null }
            .all { it.note.contains("just a nice border") },
            "yearbook: a blank page says so — no invented " +
                "winner, just the border")
        val zeroBook = Yearbook.judge(freshOn(2027, 2, 1), 2027).volume
        check(zeroBook.photoCount == 0 && zeroBook.entries.isEmpty() &&
            !zeroBook.pamphlet &&
            zeroBook.winnersLine ==
                "covers only — no photos this year",
            "yearbook: a photoless year publishes covers " +
                "only — no fake pages at all")

        // ---------- publication: the turn, once ----------
        val pub = freshOn(2027, 5, 31)
        pub.photos += rec("p1", "20270301",
            listOf(fig("Stan", "happy"),
                fig("Kyle", "goofy")), followers = 12)
        pub.photos += rec("p2", "20270302",
            listOf(fig("Wendy")), followers = 3)
        Yearbook.dailyRollover(pub)
        check(pub.yearbooks.isEmpty(),
            "yearbook: May 31 publishes nothing — the year " +
                "hasn't ended yet")
        setDate(pub, 2027, 6, 1)
        val eventsBefore = pub.events.toList()
        Yearbook.dailyRollover(pub)
        check(pub.yearbooks.size == 1 &&
            pub.yearbooks[0].year == 2027 &&
            pub.yearbooks[0].photoCount == 2 &&
            pub.yearbooks[0].pamphlet,
            "yearbook: June 1 prints the year that ended — " +
                "a proud little pamphlet of two")
        check(House.newEvents(eventsBefore, pub.events)
            .any { it.startsWith("📖 The 2026–27 yearbook") } &&
            pub.townLog.any { "yearbook published" in it },
            "yearbook: publication announces itself on the " +
                "ticker the morning report reads, and in the " +
                "town log")
        Yearbook.dailyRollover(pub)
        setDate(pub, 2027, 6, 2)
        Yearbook.dailyRollover(pub)
        check(pub.yearbooks.size == 1,
            "yearbook: the stored volume is the guard — the " +
                "year settles exactly once")
        // the real wiring: one genuine midnight crossing
        val wire = freshOn(2027, 5, 31, 23 * 60)
        wire.photos += rec("w1", "20270410",
            listOf(fig("Stan")), followers = 6)
        eng.onNewDay(wire)
        check(wire.todayKey == "20270601" &&
            wire.yearbooks.size == 1 &&
            wire.yearbooks[0].year == 2027,
            "yearbook: Engine.onNewDay across the turn " +
                "publishes the book by itself")
        // a dormant legacy save wakes past the turn and
        // still gets its book — the year's photos were its own
        val dormant = freshOn(2027, 6, 15)
        dormant.photos += rec("d1", "20261020",
            listOf(fig("Kenny", "goofy")), followers = 15)
        Yearbook.dailyRollover(dormant)
        check(dormant.yearbooks.size == 1 &&
            dormant.yearbooks[0].photoCount == 1,
            "yearbook: a save that slept through the turn " +
                "publishes its ended year on the next rollover")
        // ...but a year the save never lived gets no book
        val newborn = freshOn(2026, 10, 2)
        Yearbook.dailyRollover(newborn)
        check(newborn.yearbooks.isEmpty(),
            "yearbook: the year before the game began is " +
                "never published — the save wasn't there")

        // ---------- the argument ----------
        val arg = freshOn(2027, 6, 1)
        arg.photos += rec("a1", "20270301",
            listOf(fig("Stan", "goofy", "backToBack"),
                fig("Kyle", "goofy", "backToBack")),
            followers = 20, composition = "squad")
        arg.photos += rec("a2", "20270302",
            listOf(fig("Butters", "happy")), followers = 19,
            composition = "lineup")
        // the memory store is global and earlier lifetimes
        // have published books of their own — scrub the
        // subjects' yearbook topics so THIS publication is
        // the only planter on trial
        for (n in listOf("Stan", "Kyle", "Butters", "Craig")) {
            NpcMemoryStore.getOrCreate(n).topics.removeAll {
                it == Yearbook.TOPIC_WIN || it == Yearbook.TOPIC_SNUB }
        }
        Yearbook.dailyRollover(arg)
        check(Yearbook.TOPIC_WIN in
            (NpcMemoryStore.get("Stan")?.topics ?: emptyList()) &&
            Yearbook.TOPIC_WIN in
            (NpcMemoryStore.get("Kyle")?.topics ?: emptyList()),
            "yearbook: the cast in a winning frame carry " +
                "'yearbook famous' the morning it prints")
        check(Yearbook.TOPIC_SNUB in
            (NpcMemoryStore.get("Butters")?.topics ?: emptyList()),
            "yearbook: the runner-up's cast carry 'yearbook " +
                "snub' — the argument is real")
        check(Yearbook.TOPIC_WIN !in
            (NpcMemoryStore.get("Craig")?.topics ?: emptyList()) &&
            Yearbook.TOPIC_SNUB !in
            (NpcMemoryStore.get("Craig")?.topics ?: emptyList()),
            "yearbook: nobody outside the frames gets a topic")
        val winMem = NpcMemory()
        winMem.meets = 3
        winMem.topics += Yearbook.TOPIC_WIN
        val winLine = Threads.followUp(winMem, kotlin.random.Random(4))
        check(winLine != null && "{topic}" !in winLine &&
            Yearbook.TOPIC_WIN in winLine,
            "yearbook: Threads has a bank for the winners — " +
                "the basking is speakable")
        val snubMem = NpcMemory()
        snubMem.meets = 3
        snubMem.topics += Yearbook.TOPIC_SNUB
        val snubLine = Threads.followUp(snubMem,
            kotlin.random.Random(4))
        check(snubLine != null && "{topic}" !in snubLine &&
            Yearbook.TOPIC_SNUB in snubLine,
            "yearbook: Threads has a bank for the snubbed — " +
                "the grumble is speakable too")
        check(Yearbook.arguingAbout(arg, arg.yearbooks[0]) &&
            !Yearbook.arguingAbout(
                freshOn(2027, 6, 20).also {
                    it.absDay = arg.absDay + 30 },
                arg.yearbooks[0].copy(publishedAbsDay = arg.absDay)),
            "yearbook: the town argues for its few days, " +
                "then lets it go")

        // ---------- the shelf cap ----------
        val shelf = freshOn(2027, 6, 1)
        for (yr in 2027..2031) {
            setDate(shelf, yr, 6, 1)
            shelf.photos.removeAll {
                Yearbook.schoolYearOf(it.dayKey) != yr }
            shelf.photos += rec("sh$yr", keyOf(yr - 1, 11, 5),
                listOf(fig("Stan")), followers = yr % 50)
            Yearbook.dailyRollover(shelf)
        }
        check(shelf.yearbooks.size == 5 &&
            shelf.yearbooks.count { !it.indexOnly } ==
                Yearbook.FULL_VOLUMES &&
            shelf.yearbooks.take(2).all { it.indexOnly &&
                it.entries.isEmpty() &&
                it.winnersLine.isNotEmpty() } &&
            shelf.yearbooks.map { it.year } ==
                listOf(2027, 2028, 2029, 2030, 2031),
            "yearbook: five volumes deep, the newest three " +
                "stand whole and the elders keep their index " +
                "lines — nothing silently dropped")

        // ---------- decor: the shelf at home ----------
        check(House.decorById("yearbook_shelf")?.token ==
            "yearbook-shelf" &&
            "yearbook_shelf" !in House.decorFor(freshOn(2027, 1, 1)) &&
            "yearbook_shelf" in House.decorFor(pub) &&
            "yearbook-shelf" in House.decorTokensFor(pub),
            "yearbook: the first published volume raises " +
                "the shelf at home — derived, like every piece")

        // ---------- the album keeps its stars ----------
        val fade = freshOn(2027, 3, 1)
        Photos.applyPhoto(fade, rec("yb-star", "20270301",
            listOf(fig("Stan")), starred = true))
        fade.photos.first { it.id == "yb-star" }.starred = true
        for (i in 0 until 65) {
            Photos.applyPhoto(fade, rec("yb-u%02d".format(i),
                "20270301", listOf(fig("Kyle"))))
        }
        check(fade.photos.size == Photos.ALBUM_CAP &&
            fade.photos.any { it.id == "yb-star" } &&
            fade.photos.none { it.id == "yb-u00" } &&
            fade.photos.any { it.id == "yb-u64" },
            "yearbook: the album cap sheds the oldest " +
                "unstarred photo and keeps a starred keeper, " +
                "like a commissioned print")

        // ---------- save round-trips ----------
        val rt = judgedState()
        setDate(rt, 2027, 6, 1)
        Yearbook.dailyRollover(rt)
        rt.photos.first { it.id == "g1" }.starred = true
        val rtBack = decodeGameState(encodeGameState(rt))
        check(rtBack.yearbooks == rt.yearbooks &&
            rtBack.photos.first { it.id == "g1" }.starred &&
            Yearbook.judge(rtBack, 2028).volume.photoCount == 1,
            "yearbook: volumes and stars round-trip whole " +
                "through the real save path — and the stray " +
                "June photo waits for its own year's book")
        check(rtBack.yearbooks[0].entries
            .first { it.categoryId == "group" }.record?.id == "g1",
            "yearbook: the winning record rides INSIDE the " +
                "volume — the page survives the album cap")
        val legacyDoc = encodeGameState(rt).toMutableMap()
        legacyDoc.remove("yearbooks")
        (legacyDoc["photos"] as? List<*>)?.forEach {
            (it as? MutableMap<String, Any?>)?.remove("starred") }
        val legacy = decodeGameState(legacyDoc)
        check(legacy.yearbooks.isEmpty() &&
            legacy.photos.none { it.starred } &&
            Yearbook.albumFor(legacy, 2027).size == 6,
            "yearbook: a pre-0.8.0d save loads with no " +
                "volumes and unstarred photos — its album " +
                "belongs to the current year")
        setDate(legacy, 2027, 6, 1)
        Yearbook.dailyRollover(legacy)
        check(legacy.yearbooks.size == 1 &&
            legacy.yearbooks[0].photoCount == 6,
            "yearbook: the legacy save's first turn judges " +
                "the album it already had")

        // ---------- the page reads honestly ----------
        val page = Yearbook.pageLines(rtBack)
        check(page.any { "2026–27" in it || "volume" in it } &&
            page.any { "in the running" in it &&
                "+${Yearbook.STAR_BONUS}" in it },
            "yearbook: the shelf page reports the volumes " +
                "and this year's standings, star's worth stated")
        check(Yearbook.coverLines(zeroBook).any {
            "covers and" in it } &&
            Yearbook.coverLines(thinBook).any {
                "pamphlet is PROUD" in it } &&
            Yearbook.indexLine(bookA).startsWith("📖 2026–27"),
            "yearbook: covers tell the truth at every " +
                "thickness")

        // ---------- THE SPOILER WALL ----------
        // The judges, the page and the announcement argue
        // about PHOTOS. Nothing here may touch any case's
        // answer — the same denylist the other modules scan.
        val deny = listOf("sleepwalk", "professor chaos",
            "cameo", "strongbox", "commune", "the deed",
            "golden lure", "whittled", "night gardener",
            "confession", "culprit")
        val surfaces = mutableListOf<String>()
        surfaces += page
        surfaces += Yearbook.coverLines(bookA)
        surfaces += Yearbook.coverLines(thinBook)
        surfaces += Yearbook.indexLine(bookA)
        for (v in listOf(bookA, thinBook))
            for (e in v.entries) surfaces += e.note
        check(deny.none { d ->
            surfaces.any { d in it.lowercase() } },
            "yearbook: no judge, page or cover breathes a " +
                "word of any case's answer")
        val readme = File(root, "docs/CHANGELOG.md").readText()
        val entryStart = readme.indexOf("### v0.8.0d")
        val entryEnd = readme.indexOf("### v0.8.0c")
        check(entryStart >= 0 && entryEnd > entryStart &&
            deny.none { d -> d in readme.substring(entryStart,
                entryEnd).lowercase() },
            "yearbook: the changelog entry exists and keeps " +
                "the spoiler wall")
        check(readme.contains("82 Kotlin files"),
            "yearbook: the README's source count moved with " +
                "the new module")
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}

// ================= v0.8.0e: the rival =================
/** Queue #8 item 5: somebody in town has decided you are
 *  their measuring stick. One of seven authored kids is
 *  crowned by a pure function of the save's creation
 *  identity, revealed in a played contested beat, and the
 *  rivalry runs on the town's own rails — the real duel,
 *  the bee's bracket, the catch table, photo milestones,
 *  played climax tiers — plus one honest-clock race whose
 *  ties are arithmetically impossible. This section pins
 *  selection determinism and pool honesty, the fairness
 *  distributions (the rival wins a real share, on their
 *  authored stats), score/topic/phone factuality, prank
 *  reversibility byte-for-byte outside the module's own
 *  keys, standing derivation from answer histories, the
 *  free decline, deference non-firing, and round-trips. */
private fun sectionV080e(root: String) {
    println("== v0.8.0e: the rival — somebody's measuring stick ==")
    val memSnapshot = NpcMemoryStore.serialize()
    try {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.8.0e"),
        "v0.8.0e: the README carries this build's changelog entry")

    val engE = Engine(808_080)
    fun freshPlayer(name: String, app: Map<String, String>): GameState {
        val s = engE.newState()
        engE.createPlayer(s, name, app)
        return s
    }
    // a calm stage: Wednesday 2027-02-10, mid-morning — no
    // holiday, no finale week, outside the bee's hours.
    fun calm(s: GameState, day: Int) {
        s.absDay = day
        s.gameYear = 2027; s.gameMonth = 2; s.gameDay = 10
        s.todayKey = "20270210"; s.timeMin = 10 * 60
        s.holidayId = null
    }
    fun revealedSave(name: String, day: Int): GameState {
        val s = freshPlayer(name, DEFAULT_APPEARANCE)
        calm(s, day)
        Rival.playReveal(s, 1)   // called it even: no esc/mercy seed
        return s
    }
    fun saveForRival(want: String): GameState {
        for (i in 0..600) {
            val s = freshPlayer("Seeker$i", DEFAULT_APPEARANCE)
            if (Rival.pickFor(s) == want) return s
        }
        error("no fabricated identity crowns $want")
    }
    fun stripRivalKeys(doc: Map<String, Any?>): Map<String, Any?> {
        val out = doc.toMutableMap()
        out["life"] = (doc["life"] as? Map<String, Any?>)
            ?.filterKeys { !it.startsWith("rival") }
        out["lifeText"] = (doc["lifeText"] as? Map<String, Any?>)
            ?.filterKeys { !it.startsWith("rival") }
        return out
    }

    run {
        // ---------- the pool: honest and authored ----------
        // v0.9.0a: wave 5's Nathan — the born nemesis — takes
        // the pool to eight; v0.11.0d: wave 6's Terrance
        // Mephesto — the ORIGINAL rival — appends ninth, last;
        // every other pin in this block is the pool's own
        // arithmetic and stretches with it.
        check(Rival.POOL.size == 9,
            "rival: the eligibility pool holds nine kids")
        check(Rival.POOL.all { it.name in CharacterSystem.CAST_KIDS },
            "rival: every pool member is kid cast — full citizens, " +
                "bee-eligible, showdown-legal, textable")
        check(Rival.POOL.map { it.name }.distinct().size == 9,
            "rival: the pool names nine different kids")
        check(Rival.POOL.none { it.name == "Kenny" || it.name == "Butters" },
            "rival: Kenny (muffled — the rivalry needs clean text) " +
                "and Butters (too sweet) are honestly excluded")
        check(Rival.POOL.all { it.paceHalf % 2 != 0 },
            "rival: every authored pace is an ODD number of " +
                "half-minutes — the race's tie-proof starts here")
        check(Rival.POOL.all {
                Showdown.dodgeFor(it.name) in 0.05..0.45 &&
                School.skillOf(it.name) in 1..10 && it.nerve in 1..10 },
            "rival: every member's dodge and spelling skill read " +
                "live off the duel and bee tables — no shadow stats")
        check(Rival.POOL.all { it.why.isNotBlank() &&
                it.crownLine.contains("{you}") &&
                it.offerLine.isNotBlank() && it.winLine.isNotBlank() &&
                it.loseLine.isNotBlank() },
            "rival: every member carries their case for the crown " +
                "and a full set of authored lines")
    }

    run {
        // ---------- selection: deterministic, stable ----------
        val a1 = freshPlayer("Rex", DEFAULT_APPEARANCE)
        val a2 = freshPlayer("Rex", DEFAULT_APPEARANCE)
        check(Rival.pickFor(a1) == Rival.pickFor(a2) &&
            Rival.pickFor(a1) in Rival.POOL.map { it.name },
            "rival: the same creation identity crowns the same " +
                "kid, twice, from the pool")
        val picks = (0..23).map {
            Rival.pickFor(freshPlayer("Kid$it", DEFAULT_APPEARANCE)) }
        check(picks.distinct().size >= 4,
            "rival: different saves crown different rivals — " +
                "${picks.distinct().size} distinct across 24 identities")
        val enc = encodeGameState(a1)
        val dec = decodeGameState(enc)
        check(Rival.pickFor(dec) == Rival.pickFor(a1) &&
            Rival.rivalOf(dec) == Rival.rivalOf(a1),
            "rival: the pick survives a save round-trip untouched")
        // a pre-0.8.0e save: no rival keys at all — the same
        // rule applied to its creation identity crowns it.
        val legacy = freshPlayer("Old Save", DEFAULT_APPEARANCE)
        check(legacy.life.keys.none { it.startsWith("rival") } &&
            legacy.lifeText.keys.none { it.startsWith("rival") },
            "rival: a fresh (pre-feature) save carries no rival state")
        Rival.dailyRollover(legacy)
        check(legacy.lifeText["rival"] == Rival.pickFor(legacy),
            "rival: the first midnight records the rule's pick — " +
                "legacy saves gain their rival by the same rule")
        // once recorded, the name is read back, never re-rolled
        val stored = freshPlayer("Stored", DEFAULT_APPEARANCE)
        stored.lifeText["rival"] = "Craig"
        check(Rival.rivalOf(stored) == "Craig",
            "rival: a recorded crown is the crown, whatever the " +
                "bare rule would say today")
        // the reveal falls due in the first days, by seed
        val dues = (0..15).map {
            Rival.revealDueDay(freshPlayer("Due$it", DEFAULT_APPEARANCE)) }
        check(dues.all { it in 1..3 } && dues.distinct().size >= 2,
            "rival: reveal days land in 1..3 and vary by seed")
    }

    run {
        // ---------- the reveal: a played, gated beat ----------
        val s = freshPlayer("Bea", DEFAULT_APPEARANCE)
        val rival = Rival.rivalOf(s)
        val due = Rival.revealDueDay(s)
        calm(s, due - 1)
        check(!Rival.revealDue(s) && Rival.talkStepFor(s, rival) == null,
            "rival: the day before its due, nothing stirs")
        calm(s, due)
        check(Rival.revealDue(s) &&
            Rival.talkStepFor(s, rival)?.kind == "reveal",
            "rival: on its day, talking to them IS the reveal")
        check(Rival.talkStepFor(s,
                CharacterSystem.CAST_KIDS.first { it != rival }) == null,
            "rival: nobody else carries the moment")
        // the gate pin searches for an identity whose rival
        // carries no higher rail's business on the day (the
        // faction leaders open with their chains' offers —
        // the ladder's own order, honestly respected)
        var gateOk = false
        for (i in 0..300) {
            val gs = freshPlayer("Gate$i", DEFAULT_APPEARANCE)
            val gr = Rival.rivalOf(gs)
            calm(gs, Rival.revealDueDay(gs))
            if (TalkGate.gateFor(gs, gr,
                    engE.player(gs).location).rail ==
                TalkGate.Rail.RIVAL) { gateOk = true; break }
        }
        check(gateOk,
            "rival: the Talk gate rails the reveal on RIVAL")
        check(Rival.revealText(s).contains(rival) &&
            Rival.revealOptions(s).size == 3,
            "rival: the beat names them and offers three answers")
        // every answer crowns; the answers differ in seed
        val esc0 = Rival.escalations(s)
        val text = Rival.playReveal(s, 0)
        check(Rival.revealed(s) && text.contains("THE RIVAL") &&
            Rival.escalations(s) == esc0 + 1,
            "rival: taking the glory crowns them AND seeds the " +
                "rivalry's first escalation")
        check("the rivalry" in
            (NpcMemoryStore.get(rival)?.topics ?: emptyList()),
            "rival: the crowning plants 'the rivalry' in their memory")
        val sLet = freshPlayer("Bea2", DEFAULT_APPEARANCE)
        calm(sLet, Rival.revealDueDay(sLet))
        Rival.playReveal(sLet, 2)
        check(Rival.mercies(sLet) == 1 && Rival.escalations(sLet) == 0,
            "rival: yielding the glory seeds the first mercy instead")
        val sEven = freshPlayer("Bea3", DEFAULT_APPEARANCE)
        calm(sEven, Rival.revealDueDay(sEven))
        Rival.playReveal(sEven, 1)
        check(Rival.mercies(sEven) == 0 && Rival.escalations(sEven) == 0 &&
            Rival.nextChallengeDay(sEven) in sEven.absDay + 2..sEven.absDay + 3,
            "rival: calling it even seeds neither — and the first " +
                "challenge follows within days")
        // the morning line: yesterday's crowning is reported
        val sNote = revealedSave("Note", 40)
        sNote.life["rivalBeatDay"] = 39
        check(Rival.morningNote(sNote) == sNote.lifeText["rivalBeat"],
            "rival: the morning report carries yesterday's beat " +
                "in its own recorded words")
    }

    run {
        // ---------- scheduling & the free decline ----------
        val s = revealedSave("Sched", 50)
        val rival = Rival.rivalOf(s)
        calm(s, Rival.nextChallengeDay(s))
        check(Rival.challengeLive(s),
            "rival: on the scheduled day, a challenge is live")
        val hit = Rival.talkStepFor(s, rival)
        check(hit?.kind == "offer" && hit.offerKind.isNotEmpty(),
            "rival: the live challenge is offered in person")
        check(Rival.offerText(s, hit!!.offerKind)
                .contains(Rival.kindLabel(hit.offerKind)) &&
            Rival.offerText(s, hit.offerKind).contains("costs nothing"),
            "rival: the offer names the contest and says the " +
                "quiet part: free")
        val coinsBefore = Minigames.capsuleCoins(s)
        val bytesBefore = stripRivalKeys(encodeGameState(s))
        val nextBefore = Rival.nextChallengeDay(s)
        Rival.decline(s)
        check(Rival.nextChallengeDay(s) - nextBefore ==
            Rival.DECLINE_GAP + (Rival.saveSeed(s) % 3).toInt() &&
            Minigames.capsuleCoins(s) == coinsBefore &&
            stripRivalKeys(encodeGameState(s)) == bytesBefore,
            "rival: declining moves ONLY the next-challenge day, " +
                "by its authored gap — the rest of the save is " +
                "byte-identical, coins included")
        check(Rival.talkStepFor(s, rival) == null,
            "rival: a declined challenge does not nag — the rail " +
                "goes quiet until the next scheduled day")
        // an armed contest lapses free and silent
        val sLapse = revealedSave("Lapse", 60)
        Rival.accept(sLapse, Rival.K_FISHING)
        check(Rival.pendingKind(sLapse) == Rival.K_FISHING,
            "rival: accepting arms the contest")
        sLapse.absDay += Rival.PENDING_LAPSE_DAYS + 1
        Rival.dailyRollover(sLapse)
        check(Rival.pendingKind(sLapse) == null &&
            Rival.contestsPlayed(sLapse) == 0,
            "rival: an ignored contest lapses — no record, no " +
                "penalty, no grudge entry")
        // the gate's own order: RIVAL between the emergency
        // offer and the fresh ask
        val tgSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt").readText()
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        check(gateBody.indexOf("Emergencies.pendingOffer") <
            gateBody.indexOf("Rival.talkStepFor") &&
            gateBody.indexOf("Rival.talkStepFor") <
            gateBody.indexOf("Errands.pendingAsk"),
            "rival: in the gate's own order the RIVAL rail sits " +
                "below the emergency and above the fresh ask")
        check(TalkGate.Rail.RIVAL.ordinal ==
            TalkGate.Rail.EMERG_OFFER.ordinal + 1 &&
            TalkGate.Rail.ERRAND_ASK.ordinal ==
            TalkGate.Rail.RIVAL.ordinal + 1,
            "rival: the rail enum agrees — EMERG_OFFER, RIVAL, ASK")
    }

    // a scripted duel: the player's half is a fixed script
    // (center-bar throws; a dodge tap at a fixed millisecond,
    // or never), the rival's half is ShowdownDuel's own math
    // on their authored dodge — the same object the game runs.
    fun scriptDuel(seed: Long, opp: String, tapMs: Long?,
                   wild: Boolean): ShowdownDuel {
        val d = ShowdownDuel(seed, opp)
        var guard = 0
        while (!d.over && guard++ < 300) {
            d.resolveThrow(if (wild) 0.97f else 0.5f)
            if (!d.over) d.resolveDodge(tapMs)
        }
        return d
    }

    run {
        // ---------- showdown: fairness on the real duel ----------
        var playerWins = 0; var duels = 0
        val rateByMember = mutableMapOf<String, Double>()
        for (def in Rival.POOL) {
            val s = saveForRival(def.name)
            calm(s, 70); Rival.playReveal(s, 1)
            var w = 0; val n = 300
            for (i in 1..n) {
                val d = scriptDuel(i * 31L + def.name.length, def.name,
                    tapMs = 300L, wild = false)
                s.lifeText["rivalPending"] = Rival.K_SHOWDOWN
                s.life["rivalPendingDay"] = s.absDay
                Rival.onShowdown(s, d.youWon, def.name)
                if (d.youWon) w++
            }
            rateByMember[def.name] = w.toDouble() / n
            playerWins += w; duels += n
            check(Rival.contestsPlayed(s) == n,
                "rival: every scripted duel against ${def.name} " +
                    "settled through the contest funnel")
        }
        val playerShare = playerWins.toDouble() / duels
        check(playerShare in 0.30..0.90,
            "rival: a mediocre scripted player wins a real share " +
                "but not the town — player share " +
                "${"%.2f".format(playerShare)} over $duels duels")
        check(1.0 - playerShare >= 0.10,
            "rival: the pool, on its authored dodge stats, takes " +
                "at least a tenth of honest duels")
        check(rateByMember.getValue("Tweek") <
            rateByMember.getValue("Clyde"),
            "rival: the authored dodge drives the outcome — " +
                "Tweek (0.40) is harder to beat than Clyde (0.25): " +
                "${rateByMember.getValue("Tweek")} vs " +
                "${rateByMember.getValue("Clyde")}")
        check(rateByMember.getValue("Craig") <=
            rateByMember.getValue("Clyde") + 0.03,
            "rival: Craig (0.35) is no easier than Clyde (0.25)")
        // a sloppy script loses the majority — the contest is
        // the player's to lose, not a coronation either way
        var sloppyWins = 0; var sloppyN = 0
        for (def in Rival.POOL) {
            for (i in 1..120) {
                val d = scriptDuel(i * 17L + 5, def.name,
                    tapMs = null, wild = true)
                if (d.youWon) sloppyWins++
                sloppyN++
            }
        }
        check(sloppyWins.toDouble() / sloppyN < 0.5,
            "rival: wild throws and no dodging lose the majority " +
                "(${sloppyWins}/$sloppyN) — skill is the player's stat")
        // the funnel's guards: wrong opponent, no arm — no record
        val g = revealedSave("Guard", 80)
        val gRival = Rival.rivalOf(g)
        Rival.onShowdown(g, true, "Stan")
        check(Rival.contestsPlayed(g) == 0,
            "rival: beating somebody else is not a contest")
        Rival.accept(g, Rival.K_SHOWDOWN)
        Rival.onShowdown(g, true,
            CharacterSystem.CAST_KIDS.first { it != gRival })
        check(Rival.contestsPlayed(g) == 0 &&
            Rival.pendingKind(g) == Rival.K_SHOWDOWN,
            "rival: a duel with a third party leaves the armed " +
                "contest armed")
        Rival.onShowdown(g, false, gRival)
        check(Rival.contestsPlayed(g) == 1 &&
            (g.life["rivalThem"] ?: 0) == 1 &&
            Rival.pendingKind(g) == null,
            "rival: the rival's win counts exactly like yours — " +
                "the scoreboard has no favorite")
    }

    run {
        // ---------- fishing: the same table, both directions ----------
        fun playerCast(rng: Random): Pair<FishSpecies, Int> {
            val total = FISH_TABLE.sumOf { it.weight }
            var roll = rng.nextInt(total)
            var sp = FISH_TABLE.last()
            for (c in FISH_TABLE) {
                roll -= c.weight
                if (roll < 0) { sp = c; break }
            }
            return sp to (sp.minCm +
                rng.nextInt(sp.maxCm - sp.minCm + 1))
        }
        val bootName = FISH_TABLE.first { it.id == "old_boot" }.name
        var youW = 0; var themW = 0; var draws = 0; var bootCases = 0
        var total = 0
        for (def in Rival.POOL) {
            val s = saveForRival(def.name)
            calm(s, 90); Rival.playReveal(s, 1)
            for (i in 1..286) {
                Rival.accept(s, Rival.K_FISHING)
                val (sp, cm) = playerCast(Random(777_000L + total))
                Rival.onCatch(s, sp, cm)
                total++
                when (s.lifeText["rivalLastWinner"]) {
                    "you" -> youW++
                    "them" -> themW++
                    else -> draws++
                }
                if (sp.id == "old_boot") {
                    val detail = Rival.contestLog(s).last().detail
                    val theirPart = detail.substringAfter("vs their ", "")
                    if (theirPart.isNotEmpty() &&
                        !theirPart.startsWith(bootName)) {
                        bootCases++
                        check(s.lifeText["rivalLastWinner"] == "them",
                            "rival: a boot is not a fish — it loses " +
                                "to any real catch of theirs")
                    }
                }
            }
        }
        val themShare = themW.toDouble() / total
        val youShare = youW.toDouble() / total
        check(total >= 2000 && themShare in 0.25..0.75 &&
            youShare in 0.25..0.75,
            "rival: 2,000 seeded fishing duels split honestly — " +
                "you ${"%.2f".format(youShare)}, them " +
                "${"%.2f".format(themShare)}, drawn " +
                "${"%.2f".format(draws.toDouble() / total)}")
        check(bootCases >= 5,
            "rival: the boot rule was exercised ($bootCases cases)")
    }

    run {
        // ---------- the race: the honest clock, ties impossible ----------
        for (def in Rival.POOL) for (route in listOf(10, 14, 21, 33)) {
            for (mins in 1..60) {
                check(mins * 2 != route * 2 + def.paceHalf,
                    "rival: parity — a whole-minute player can never " +
                        "tie ${def.name}'s odd-half posted time")
            }
        }
        // a par runner: exactly the route minutes
        fun raceFixture(want: String): Triple<GameState, Rival.RivalAccept, Int> {
            val s = saveForRival(want)
            calm(s, 100); Rival.playReveal(s, 1)
            engE.player(s).location = "KidsPark"
            s.timeMin = 8 * 60
            val acc = Rival.accept(s, Rival.K_RACE)
            val route = Walk.routeMinutes(s, "KidsPark", acc.raceTarget!!)
            return Triple(s, acc, route)
        }
        val (tw, twAcc, twRoute) = raceFixture("Tweek")
        check(twRoute >= Rival.RACE_MIN_ROUTE &&
            Rival.raceLive(tw),
            "rival: the race arms at a real Walk-graph distance")
        tw.timeMin += twRoute   // par: neither fast nor slow
        val twLine = Rival.raceArrival(tw, twAcc.raceTarget!!)
        check(twLine != null && Rival.contestLog(tw).last().winner == "them",
            "rival: par loses to Tweek — pressure makes him faster " +
                "(his −5 halves are under your whole minutes)")
        check(Rival.raceArrival(tw, twAcc.raceTarget!!) == null,
            "rival: a race settles exactly once")
        val (cl, clAcc, clRoute) = raceFixture("Clyde")
        cl.timeMin += clRoute
        Rival.raceArrival(cl, clAcc.raceTarget!!)
        check(Rival.contestLog(cl).last().winner == "you",
            "rival: par beats Clyde — he stops to check his " +
                "reflection (+5 halves)")
        // a race the day forgets, and a clock that lies
        val (lz, lzAcc, _) = raceFixture("Wendy")
        lz.absDay += 1
        Rival.dailyRollover(lz)
        check(!Rival.raceLive(lz) && Rival.contestsPlayed(lz) == 0,
            "rival: an unfinished race lapses at the rollover — " +
                "no record, no penalty")
        val (ab, abAcc, _) = raceFixture("Wendy")
        ab.timeMin += 700
        check(Rival.raceArrival(ab, abAcc.raceTarget!!) == null &&
            Rival.contestsPlayed(ab) == 0 && !Rival.raceLive(ab),
            "rival: an absurd elapsed time reads as a race that " +
                "never happened — cleared, unrecorded")
    }

    run {
        // ---------- followers: a race judged by days ----------
        val s = saveForRival("Kyle")
        calm(s, 110); Rival.playReveal(s, 1)
        s.followers = 24
        Rival.onFollowers(s)
        check((s.life["rivalRaceYouDay"] ?: 0) == 0,
            "rival: with no race armed, a photo milestone records " +
                "nothing for the rivalry")
        Rival.accept(s, Rival.K_FOLLOWERS)
        val target = s.life["rivalTarget"] ?: -1
        check(target in Photos.MILESTONES && target > s.followers &&
            target > (s.life["rivalFollowers"] ?: 0),
            "rival: the follower race aims at the next milestone " +
                "above BOTH tallies")
        s.life["rivalFollowers"] = target - 10
        s.followers = target
        Rival.onFollowers(s)
        check((s.life["rivalRaceYouDay"] ?: 0) == s.absDay,
            "rival: your crossing day is recorded at the photo " +
                "funnel, not settled on the spot")
        Rival.dailyRollover(s)
        check(Rival.contestLog(s).any {
                it.kind == Rival.K_FOLLOWERS && it.winner == "you" },
            "rival: the earlier crossing takes the follower race " +
                "at the rollover")
        // their night posting can take it instead
        val s2 = saveForRival("Kyle")
        calm(s2, 111); Rival.playReveal(s2, 1)
        s2.followers = 24
        Rival.accept(s2, Rival.K_FOLLOWERS)
        val target2 = s2.life["rivalTarget"] ?: -1
        s2.life["rivalFollowers"] = target2 - 1
        Rival.dailyRollover(s2)
        check(Rival.contestLog(s2).any {
                it.kind == Rival.K_FOLLOWERS && it.winner == "them" },
            "rival: their authored post pace crosses first — " +
                "the race is theirs, honestly")
        // the offer retires at the last milestone
        val s3 = revealedSave("Top", 112)
        s3.followers = Photos.MILESTONES.last()
        check(Rival.offerKindFor(s3) != Rival.K_FOLLOWERS,
            "rival: at the final milestone there is no follower " +
                "race left to offer")
    }

    run {
        // ---------- the bee: a standing contest, bracket-judged ----------
        val s = saveForRival("Wendy")
        calm(s, 120); Rival.playReveal(s, 1)
        val beeDay = (0..600).first { "Wendy" in School.beeField(it) }
        s.absDay = beeDay
        Rival.onBeeSettled(s, School.BeeRecord(beeDay, true, 5, "Craig"))
        check(Rival.contestLog(s).count { it.kind == Rival.K_BEE } == 1 &&
            s.lifeText["rivalLastWinner"] == "you",
            "rival: you won the bee, they were in the field — " +
                "the subplot scores it for you")
        val s2 = saveForRival("Wendy")
        calm(s2, 121); Rival.playReveal(s2, 1)
        s2.absDay = beeDay
        Rival.onBeeSettled(s2, School.BeeRecord(beeDay, false, 2, "Wendy"))
        check(s2.lifeText["rivalLastWinner"] == "them",
            "rival: the bee went to the rival herself — scored " +
                "for them off the same record")
        val s3 = saveForRival("Wendy")
        calm(s3, 122); Rival.playReveal(s3, 1)
        s3.absDay = beeDay
        val rec3 = School.BeeRecord(beeDay, false, 3, "Craig")
        Rival.onBeeSettled(s3, rec3)
        Rival.onBeeSettled(s3, rec3)
        check(Rival.contestLog(s3).count { it.kind == Rival.K_BEE } == 1,
            "rival: a shared bee settles exactly once, however " +
                "deep each of you ran")
        val s4 = revealedSave("NoBee", 123)
        val otherDay = (0..600).first {
            Rival.rivalOf(s4) !in School.beeField(it) }
        s4.absDay = otherDay
        Rival.onBeeSettled(s4,
            School.BeeRecord(otherDay, true, 5, "Craig"))
        check(Rival.contestLog(s4).none { it.kind == Rival.K_BEE },
            "rival: a bee they weren't in is not a contest")
    }

    run {
        // ---------- climaxes: their tier from their nerve ----------
        fun climaxShares(want: String): Triple<Double, Double, Double> {
            val s = saveForRival(want)
            calm(s, 130); Rival.playReveal(s, 1)
            var you = 0; var them = 0; var draw = 0
            for (i in 1..500) {
                val ep = EpisodeRecord(
                    key = "ev$i@dk$i", kind = "event", eventId = "ev$i",
                    eventTitle = "T", title = "T", treatment = "",
                    causers = listOf(want), dayKey = "dk$i",
                    dateLabel = "2/10",
                    finished = true, climaxTier = "handled")
                Rival.onClimaxSettled(s, ep)
                when (s.lifeText["rivalLastWinner"]) {
                    "you" -> you++
                    "them" -> them++
                    else -> draw++
                }
            }
            return Triple(you / 500.0, them / 500.0, draw / 500.0)
        }
        val (wYou, wThem, _) = climaxShares("Wendy")
        val (tYou, tThem, _) = climaxShares("Tweek")
        check(wThem in 0.25..0.55 && wYou == 0.0,
            "rival: Wendy's nerve (9) rolls heroic or handled " +
                "against your handled — them ${"%.2f".format(wThem)}, " +
                "never fumbled")
        check(tYou >= 0.60 && tThem == 0.0,
            "rival: Tweek's nerve (4) fumbles most shared climaxes " +
                "— you ${"%.2f".format(tYou)} — and never heroics " +
                "one out of thin air")
        check(wThem > tThem,
            "rival: the nerve stat orders the climax table, as authored")
        // the guards: legacy, absent, not-a-causer, unfinished
        val g = revealedSave("ClimaxGuard", 131)
        val gRival = Rival.rivalOf(g)
        val base = EpisodeRecord(
            key = "g1@dk", kind = "event",
            eventId = Climaxes.CHAINS.keys.first(),
            eventTitle = "T", title = "T", treatment = "",
            causers = listOf(gRival), dayKey = "dk",
            dateLabel = "2/10", finished = true, climaxTier = "")
        Rival.onClimaxSettled(g, base)
        check(Rival.contestsPlayed(g) == 0,
            "rival: a legacy (pre-playable) climax judges nothing")
        val absent = base.copy(key = "g2@dk", climaxTier = "absent")
        Rival.onClimaxSettled(g, absent)
        check(Rival.contestsPlayed(g) == 0,
            "rival: an absent tier judges nothing — you weren't " +
                "in the chain to be measured")
        val notCauser = base.copy(key = "g3@dk", climaxTier = "heroic",
            causers = listOf("Stan"))
        Rival.onClimaxSettled(g, notCauser)
        check(Rival.contestsPlayed(g) == 0,
            "rival: an event they didn't cause is not a contest")
        val played = base.copy(key = "g4@dk", climaxTier = "heroic")
        Rival.onClimaxSettled(g, played)
        Rival.onClimaxSettled(g, played)
        check(Rival.contestsPlayed(g) == 1,
            "rival: a shared played climax settles exactly once")
    }

    run {
        // ---------- the score: one factual sentence ----------
        val s = revealedSave("Score", 140)
        val rival = Rival.rivalOf(s)
        s.life["rivalYou"] = 3; s.life["rivalThem"] = 1
        s.life["rivalDraws"] = 1
        val ahead = Rival.scoreLine(s)
        check(ahead.contains("ahead of $rival") &&
            ahead.contains("3–1") && ahead.contains("by two contests") &&
            ahead.contains("one drawn"),
            "rival: the score line states the leader, the tally " +
                "and the margin in words — \"$ahead\"")
        s.life["rivalYou"] = 1; s.life["rivalThem"] = 4
        s.life["rivalDraws"] = 0
        check(Rival.scoreLine(s).contains("$rival leads you 4–1") &&
            Rival.scoreLine(s).contains("by three contests"),
            "rival: behind is stated just as plainly")
        s.life["rivalYou"] = 2; s.life["rivalThem"] = 1
        check(Rival.scoreLine(s).contains("by one contest."),
            "rival: a margin of one is one contest, singular")
        s.life["rivalYou"] = 2; s.life["rivalThem"] = 2
        check(Rival.scoreLine(s).contains("level at 2–2"),
            "rival: level is level")
        s.lifeText["rivalLog"] = "${s.absDay}|${Rival.K_FISHING}|you|" +
            "your Pond Smelt 30 cm vs their Pond Smelt 9 cm"
        val sentence = Rival.lastResultSentence(s) ?: ""
        check(sentence.contains("the fishing duel") &&
            sentence.contains("took") && sentence.contains(rival),
            "rival: the last-result sentence is built from the " +
                "record — kind, winner, name")
        // the topic, its bank and its tag
        val rivalMem = NpcMemory(meets = 2,
            topics = mutableListOf("the rivalry"))
        val bankOuts = (1..40).mapNotNull {
            Threads.followUp(rivalMem, kotlin.random.Random(it.toLong())) }
            .distinct()
        check(bankOuts.size >= 3 &&
            bankOuts.all { it.contains("the rivalry") },
            "rival: 'the rivalry' has a Threads bank in the form — " +
                "${bankOuts.size} distinct follow-ups sampled")
        check(NpcMemoryStore.topicOf(
                "we need a rematch, the scoreboard says so") ==
            "the rivalry",
            "rival: talk of rematches and scoreboards files " +
                "under 'the rivalry'")
        // the phone: a new trigger, banks by the recorded winner
        check(Phone.RIVAL in Phone.TRIGGERS &&
            Phone.RIVAL_AHEAD_LINES.size >= 3 &&
            Phone.RIVAL_BEHIND_LINES.size >= 3 &&
            Phone.RIVAL_DRAW_LINES.size >= 2 &&
            (Phone.RIVAL_AHEAD_LINES + Phone.RIVAL_BEHIND_LINES +
                Phone.RIVAL_DRAW_LINES).all { "{x}" in it },
            "rival: the phone carries a RIVAL trigger with taunt, " +
                "grudging and draw banks, all slotted with the contest")
        val dueS = revealedSave("Texts", 141)
        dueS.life["rivalLastDay"] = dueS.absDay
        dueS.lifeText["rivalLastWinner"] = "them"
        dueS.lifeText["rivalLastKind"] = Rival.K_FISHING
        val due = Rival.textDue(dueS)
        check(due != null && due.rival == Rival.rivalOf(dueS) &&
            due.kindLabel == "the fishing duel" && due.winner == "them",
            "rival: the morning after a result, a text is due " +
                "from the rival about that contest")
        Rival.markTexted(dueS)
        check(Rival.textDue(dueS) == null,
            "rival: a sent text stamps itself — once per result")
        dueS.life["rivalLastDay"] = dueS.absDay - 5
        check(Rival.textDue(dueS) == null,
            "rival: a stale result does not text late")
        // and the harvest actually sends it, from them
        val harv = revealedSave("Harvest", 142)
        harv.life["rivalLastDay"] = harv.absDay
        harv.lifeText["rivalLastWinner"] = "you"
        harv.lifeText["rivalLastKind"] = Rival.K_RACE
        Phone.dailyRollover(harv)
        check(harv.phoneTexts.any { it.trigger == Phone.RIVAL &&
                it.sender == Rival.rivalOf(harv) &&
                it.text.contains("cross-town race") },
            "rival: the phone's morning harvest delivers the " +
                "rival's text, about the race, from the rival")
        // ambient: their line while fresh, the town's gossip
        val amb = revealedSave("Ambient", 143)
        val aRival = Rival.rivalOf(amb)
        Rival.accept(amb, Rival.K_FISHING)
        Rival.onCatch(amb, FISH_TABLE.first { !it.joke && !it.rare }, 30)
        val own = Rival.ambientLine(amb, aRival)
        check(own != null && own.text.contains("fishing duel"),
            "rival: beaten yesterday, they have a line about it today")
        check(Rival.ambientLine(amb, aRival) == null,
            "rival: the line is once a day, not a loop")
        val carrier = CharacterSystem.CAST_KIDS.first { it != aRival }
        val gossip = Rival.ambientLine(amb, carrier)
        check(gossip != null &&
            gossip.text.contains(Rival.scoreLine(amb)) &&
            gossip.text.contains("fishing duel"),
            "rival: the town's gossip quotes the score line " +
                "itself — no surface can disagree with the board")
        amb.absDay += Rival.FRESH_DAYS + 1
        check(Rival.ambientLine(amb,
                CharacterSystem.CAST_KIDS.first { it != aRival }) == null,
            "rival: gossip goes stale on schedule")
    }

    run {
        // ---------- pranks: dressing, an answer, no trace ----------
        check(Rival.PRANKS.size == 6 &&
            Rival.PRANKS.map { it.id }.distinct().size == 6 &&
            Rival.PRANKS.all { it.found.isNotBlank() &&
                it.confess.isNotBlank() && it.backVow.isNotBlank() &&
                it.mercyLine.isNotBlank() && it.counter.isNotBlank() },
            "rival: six authored pranks, each with its spot text, " +
                "confession, and both answers' lines")
        // plant one through the rollover itself (seeded chance:
        // walk the mornings until one lands)
        val s = revealedSave("Pranked", 150)
        s.life["rivalNextDay"] = s.absDay + 500   // no challenge noise
        s.life["rivalPrankNext"] = s.absDay
        var guard = 0
        while (!Rival.prankActive(s) && guard++ < 60) {
            s.absDay++
            Rival.dailyRollover(s)
        }
        check(Rival.prankActive(s),
            "rival: a due prank plants itself on a quiet morning")
        val loc = Rival.prankLoc(s)!!
        val found = Rival.lookText(s, loc)
        check(found != null && found.contains("💢") &&
            Rival.prankFound(s),
            "rival: Looking at the prank's spot finds it, signed")
        check(Rival.lookText(s, loc) == null,
            "rival: the find is once — after that it's just a " +
                "thing you know")
        check(Rival.talkStepFor(s, Rival.rivalOf(s))?.kind == "prank",
            "rival: a found prank is answered in person")
        val bytesBefore = stripRivalKeys(encodeGameState(s))
        val mercyBefore = Rival.mercies(s)
        val answer = Rival.answerPrank(s, back = false)
        check(answer.isNotBlank() && !Rival.prankActive(s) &&
            Rival.mercies(s) == mercyBefore + 1 &&
            stripRivalKeys(encodeGameState(s)) == bytesBefore,
            "rival: LET IT GO — mercy recorded, and outside the " +
                "rivalry's own keys the save is byte-identical")
        // PRANK BACK: escalation now, the counter by morning
        val s2 = revealedSave("PrankBack", 170)
        s2.lifeText["rivalPrank"] = Rival.PRANKS[0].id
        s2.life["rivalPrankDay"] = s2.absDay
        s2.life["rivalPrankFound"] = 1
        s2.lifeText["rivalPrankLoc"] = "KidsPark"
        val escBefore = Rival.escalations(s2)
        Rival.answerPrank(s2, back = true)
        check(Rival.escalations(s2) == escBefore + 1 &&
            (s2.life["rivalPrankBackDay"] ?: 0) == s2.absDay + 1,
            "rival: PRANK BACK escalates and schedules the counter")
        val eventsBefore = s2.events.size
        s2.absDay++
        Rival.dailyRollover(s2)
        check(s2.events.size > eventsBefore &&
            s2.lifeText["rivalPrankBack"] == null,
            "rival: the counter-prank lands on the morning ticker " +
                "and leaves no state behind")
        // an unanswered prank evaporates, unrecorded
        val s3 = revealedSave("PrankFade", 180)
        s3.lifeText["rivalPrank"] = Rival.PRANKS[1].id
        s3.life["rivalPrankDay"] = s3.absDay - Rival.PRANK_EXPIRE_DAYS - 1
        Rival.dailyRollover(s3)
        check(!Rival.prankActive(s3) &&
            Rival.escalations(s3) == 0 && Rival.mercies(s3) == 0,
            "rival: an old prank evaporates silently — no " +
                "escalation, no mercy, no record")
    }

    run {
        // ---------- standings: derived from the answers ----------
        fun standingFixture(esc: Int, mercy: Int): GameState {
            val s = revealedSave("Standing", 190)
            s.life["rivalEsc"] = esc; s.life["rivalMercy"] = mercy
            return s
        }
        check(Rival.standingOf(standingFixture(0, 0)) ==
            Rival.WORTHY && Rival.standingOf(standingFixture(1, 1)) ==
            Rival.WORTHY,
            "rival: contested hard and kept clean is the default " +
                "arc — WORTHY OPPONENT")
        check(Rival.standingOf(standingFixture(3, 0)) == Rival.NEMESIS &&
            Rival.standingOf(standingFixture(3, 2)) == Rival.NEMESIS,
            "rival: escalation at every turn, majority kept — NEMESIS")
        check(Rival.standingOf(standingFixture(0, 2)) ==
            Rival.FRIENDLY && Rival.standingOf(standingFixture(2, 3)) ==
            Rival.FRIENDLY,
            "rival: de-escalation whenever offered, majority kept " +
                "— FRIENDLY RIVAL")
        check(Rival.standingOf(standingFixture(1, 0)) == Rival.WORTHY &&
            Rival.standingOf(standingFixture(0, 1)) == Rival.WORTHY,
            "rival: a single answer is a lean, not a standing — " +
                "it takes two to tip the derivation")
        // the lock: at ten contests, a small played beat
        fun lockFixture(esc: Int, mercy: Int, you: Int, them: Int): GameState {
            val s = standingFixture(esc, mercy)
            s.life["rivalYou"] = you; s.life["rivalThem"] = them
            return s
        }
        val worthy = lockFixture(1, 1, 5, 5)
        check(Rival.lockReady(worthy) &&
            Rival.talkStepFor(worthy, Rival.rivalOf(worthy))?.kind == "lock",
            "rival: at ten contests the lock beat offers itself")
        val lockText = Rival.playLock(worthy)
        check(Rival.locked(worthy) &&
            worthy.lifeText["rivalStanding"] == Rival.WORTHY &&
            lockText.contains("handshake"),
            "rival: the worthy lock is a handshake held a second " +
                "too long — and the standing is recorded")
        check(Rival.playLock(worthy).isEmpty(),
            "rival: the standing locks exactly once")
        val nemesis = lockFixture(4, 0, 6, 4)
        check(Rival.playLock(nemesis).contains("shove"),
            "rival: the nemesis lock is a shove — and then tacos")
        val friendly = lockFixture(0, 4, 3, 7)
        check(Rival.playLock(friendly).contains("crack up"),
            "rival: the friendly lock is both of you cracking up")
        check(Rival.standingLine(friendly).isNotBlank() &&
            Rival.pageLines(friendly).any { it.contains("FRIENDLY RIVAL") },
            "rival: the Journal page displays the locked standing")
        val under = lockFixture(0, 0, 4, 5)
        check(!Rival.lockReady(under) && Rival.playLock(under).isEmpty(),
            "rival: nine contests is not the lock — the arc is " +
                "still being written")
    }

    run {
        // ---------- deference: the big moments own the town ----------
        val s = freshPlayer("Defer", DEFAULT_APPEARANCE)
        val rival = Rival.rivalOf(s)
        calm(s, Rival.revealDueDay(s))
        check(Rival.talkStepFor(s, rival)?.kind == "reveal",
            "rival: control — the reveal fires on a plain day")
        s.holidayId = "christmas"
        check(Emergencies.momentOwned(s) &&
            Rival.talkStepFor(s, rival) == null,
            "rival: a holiday beat owns the moment — no crowning " +
                "under the tree")
        s.holidayId = null
        s.errands.add(Errand("e1", Errands.EMERG, "Sheila", "DELIVER",
            "a parcel", "", targetName = "Victoria",
            dayKey = s.todayKey, acceptedDay = s.absDay,
            emergDeadline = s.timeMin + 60))
        check(Rival.talkStepFor(s, rival) == null,
            "rival: a live emergency's clock owns the moment too")
        s.errands.clear()
        check(Rival.talkStepFor(s, rival)?.kind == "reveal",
            "rival: the moment released, the reveal returns")
        // bee hours suppress a challenge offer the same way
        val beeDay = (0..13).first { School.isBeeDay(it) }
        val b = revealedSave("DeferBee", 200)
        b.absDay = maxOf(beeDay, Rival.nextChallengeDay(b))
        b.gameYear = 2027; b.gameMonth = 2; b.gameDay = 10
        b.todayKey = "20270210"; b.holidayId = null
        b.timeMin = School.BEE_FROM + 30
        // align: force the challenge live ON the bee day itself
        b.absDay = beeDay
        b.life["rivalNextDay"] = beeDay
        check(School.isBeeDay(b.absDay) && Rival.challengeLive(b) &&
            Emergencies.momentOwned(b) &&
            Rival.talkStepFor(b, Rival.rivalOf(b)) == null,
            "rival: during the bee's hours, no challenge is offered")
        b.timeMin = 10 * 60
        check(Rival.talkStepFor(b, Rival.rivalOf(b))?.kind == "offer",
            "rival: the bee over, the morning's challenge offers " +
                "as usual")
    }

    run {
        // ---------- round-trips: mid-flight states ----------
        val s = saveForRival("Clyde")
        calm(s, 210); Rival.playReveal(s, 1)
        engE.player(s).location = "KidsPark"; s.timeMin = 8 * 60
        val acc = Rival.accept(s, Rival.K_RACE)
        val dec = decodeGameState(encodeGameState(s))
        check(Rival.raceLive(dec) &&
            dec.lifeText["rivalRaceTo"] == acc.raceTarget,
            "rival: a live race survives a save round-trip")
        val route = Walk.routeMinutes(dec, "KidsPark", acc.raceTarget!!)
        dec.timeMin += route
        Rival.raceArrival(dec, acc.raceTarget!!)
        check(Rival.contestLog(dec).last().winner == "you",
            "rival: and it still settles, on the decoded clock")
        val lockedS = revealedSave("RoundTrip", 220)
        lockedS.life["rivalYou"] = 6; lockedS.life["rivalThem"] = 4
        lockedS.life["rivalMercy"] = 3
        Rival.playLock(lockedS)
        val dec2 = decodeGameState(encodeGameState(lockedS))
        check(Rival.locked(dec2) &&
            Rival.standingOf(dec2) == Rival.standingOf(lockedS) &&
            Rival.scoreLine(dec2) == Rival.scoreLine(lockedS) &&
            Rival.contestLog(dec2).size == Rival.contestLog(lockedS).size,
            "rival: a locked standing and the whole board survive " +
                "the round-trip")
        // the Journal page, both sides of the crown
        val un = freshPlayer("Unrevealed", DEFAULT_APPEARANCE)
        check(Rival.pageLines(un)[0] == "🆚 THE RIVAL" &&
            Rival.pageLines(un).any { it.contains("Nobody has claimed you yet") },
            "rival: before the crown, the page says so honestly")
        val page = Rival.pageLines(lockedS)
        check(page[0].contains(Rival.rivalOf(lockedS)) &&
            page.any { it.contains("🏆") } &&
            page.any { it.contains("the board") || it.contains("No contests yet") },
            "rival: the page carries the name, the score line and " +
                "the ledger")
    }

    run {
        // ---------- a lived rivalry: 240 days at module level ----------
        val s = freshPlayer("Lived", DEFAULT_APPEARANCE)
        engE.player(s).location = "KidsPark"
        var maxPendingAge = 0
        for (d in 1..240) {
            s.absDay = d
            s.gameYear = 2027; s.gameMonth = 2; s.gameDay = 10
            s.todayKey = "20270210"; s.timeMin = 10 * 60; s.holidayId = null
            Rival.dailyRollover(s)
            if (Rival.revealDue(s)) Rival.playReveal(s, d % 3)
            val pk = Rival.pendingKind(s)
            if (pk != null) {
                val age = d - (s.life["rivalPendingDay"] ?: d)
                if (age > maxPendingAge) maxPendingAge = age
            }
            if (Rival.prankActive(s) && !Rival.prankFound(s))
                Rival.lookText(s, Rival.prankLoc(s)!!)
            if (Rival.prankActive(s) && Rival.prankFound(s))
                Rival.answerPrank(s, back = d % 2 == 0)
            val hit = Rival.talkStepFor(s, Rival.rivalOf(s)) ?: continue
            when (hit.kind) {
                "lock" -> Rival.playLock(s)
                "resume" -> Rival.onShowdown(s, d % 3 != 0, Rival.rivalOf(s))
                "offer" -> {
                    if (d % 3 == 0) { Rival.decline(s) }
                    else when (hit.offerKind) {
                        Rival.K_SHOWDOWN -> {
                            Rival.accept(s, hit.offerKind)
                            Rival.onShowdown(s, d % 2 == 0, Rival.rivalOf(s))
                        }
                        Rival.K_FISHING -> {
                            Rival.accept(s, hit.offerKind)
                            val sp = FISH_TABLE[d % 5]
                            Rival.onCatch(s, sp, sp.minCm + 3)
                        }
                        Rival.K_RACE -> {
                            val a = Rival.accept(s, hit.offerKind)
                            val from = engE.player(s).location
                            val r = Walk.routeMinutes(s, from, a.raceTarget!!)
                            s.timeMin += r + 1
                            engE.player(s).location = a.raceTarget!!
                            Rival.raceArrival(s, a.raceTarget!!)
                            engE.player(s).location = "KidsPark"
                            s.timeMin = 10 * 60
                        }
                        Rival.K_FOLLOWERS -> {
                            Rival.accept(s, hit.offerKind)
                            s.followers = s.life["rivalTarget"] ?: s.followers
                            Rival.onFollowers(s)
                        }
                    }
                }
            }
        }
        check(Rival.revealed(s) && Rival.contestsPlayed(s) >= 8,
            "rival: a lived 240 days reveal the rivalry and play " +
                "it — ${Rival.contestsPlayed(s)} contests settled")
        check(Rival.contestLog(s).size <= Rival.LOG_CAP,
            "rival: the ledger caps at ${Rival.LOG_CAP} — the " +
                "counters keep the whole history")
        check((s.life["rivalYou"] ?: 0) + (s.life["rivalThem"] ?: 0) +
            (s.life["rivalDraws"] ?: 0) == Rival.contestsPlayed(s),
            "rival: the counters and the played count agree")
        check(maxPendingAge <= Rival.PENDING_LAPSE_DAYS + 1,
            "rival: no armed contest ever strands past its lapse " +
                "(worst age seen: $maxPendingAge)")
        check(Rival.contestLog(s).all {
                it.winner in listOf("you", "them", "draw") },
            "rival: every settled contest has a lawful winner")
    }

    run {
        // ---------- fit QA + the spoiler wall ----------
        val rich = revealedSave("FitQA", 230)
        rich.life["rivalYou"] = 7; rich.life["rivalThem"] = 5
        rich.life["rivalDraws"] = 2
        rich.lifeText["rivalLog"] = (1..6).joinToString(";") {
            "${200 + it}|fishing|you|your Golden Carp 41 cm vs " +
                "their Pond Smelt 9 cm" }
        val lines = Rival.pageLines(rich) +
            Rival.PRANKS.flatMap { listOf(it.found, it.confess,
                it.backVow, it.mercyLine, it.counter) } +
            Rival.POOL.flatMap { listOf(it.why, it.crownLine,
                it.offerLine, it.winLine, it.loseLine) }
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { t: String -> t.length * 10f * fs }
            for (line in lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "rival: a rival screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "rival: a rival screen line never collapses at fs $fs")
            }
        }
        val deny = listOf("sleepwalk", "professor chaos",
            "cameo", "strongbox", "commune", "the deed",
            "golden lure", "whittled", "night gardener",
            "confession", "culprit")
        val surfaces = mutableListOf<String>()
        surfaces += lines
        surfaces += (Phone.RIVAL_AHEAD_LINES + Phone.RIVAL_BEHIND_LINES +
            Phone.RIVAL_DRAW_LINES)
        val wallMem = NpcMemory(meets = 2,
            topics = mutableListOf("the rivalry"))
        surfaces += (1..40).mapNotNull {
            Threads.followUp(wallMem, kotlin.random.Random(it.toLong())) }
        surfaces += Rival.pageLines(freshPlayer("Wall", DEFAULT_APPEARANCE))
        for (nm in listOf("WallA", "WallB", "WallC", "WallD", "WallE",
                "WallF", "WallG", "WallH")) {
            val fs2 = freshPlayer(nm, DEFAULT_APPEARANCE)
            surfaces += Rival.revealText(fs2)
            surfaces += Rival.revealOptions(fs2)
        }
        check(deny.none { d -> surfaces.any { d in it.lowercase() } },
            "rival: no pool line, prank, text, page or reveal " +
                "frame breathes a word of any case's answer")
        val entryStart = readme.indexOf("### v0.8.0e")
        val entryEnd = readme.indexOf("### v0.8.0d")
        check(entryStart >= 0 && entryEnd > entryStart &&
            deny.none { d -> d in readme.substring(entryStart,
                entryEnd).lowercase() },
            "rival: the changelog entry exists and keeps the " +
                "spoiler wall")
        check(readme.contains("82 Kotlin files"),
            "rival: the README's source count moved with the " +
                "new module")
    }
    } finally {
        NpcMemoryStore.deserialize(memSnapshot)
    }
}


// ============ v0.8.0f: MYSTERY #6 — THE COURT OF PUBLIC OPINION ============
// A sixth case, a sixth shape: the antagonist is the town's
// own certainty. The suite's burden here is the METER — it
// must be PROVEN derived, not merely asserted derived: every
// subset of witnessed gossip × proven evidence × public
// stances is recomputed from the raw registries by arithmetic
// written HERE, and the module's meter must agree everywhere.
// Then the two-column board's separation, the presentation
// gate, the pressure bands, the meeting's published
// arithmetic across the meter × evidence × call space, the
// four landings, six-case lifetime, additive saves, and the
// spoiler wall over every player-facing word of it.
private fun sectionV080f(root: String) {
    println("== v0.8.0f: mystery #6 — the court of public opinion ==")
    val eng6 = Engine(680)

    // ---------- independent recomputation (the suite's own math) ----------
    fun stanceDelta(stance: String?): Int = when (stance) {
        "back" -> Mystery6.VOICE_BACK
        "question" -> Mystery6.VOICE_QUESTION
        else -> Mystery6.VOICE_SILENT
    }
    fun recomputeConviction(gossip: Set<String>, clues: Set<String>,
                            voice: Map<String, String>): Int {
        var m = Mystery6.METER_BASE
        for (g in Mystery6.GOSSIP6) if (g.id in gossip) m += g.accusedDelta
        for (c in Mystery6.CLUES6) if (c.id in clues) m += c.opinion
        for (g in Mystery6.GOSSIP6) if (g.id in gossip)
            m += stanceDelta(voice[g.id])
        return m.coerceIn(0, 100)
    }
    fun recomputeSuspicion(name: String, gossip: Set<String>,
                           clues: Set<String>): Int {
        var m = 0
        for (g in Mystery6.GOSSIP6) if (g.id in gossip)
            m += g.suspicion[name] ?: 0
        for (c in Mystery6.CLUES6) if (c.id in clues)
            m += c.suspicion[name] ?: 0
        return m.coerceIn(0, 100)
    }
    fun recomputeWeight(clues: Set<String>): Int =
        Mystery6.CLUES6.filter { it.id in clues }.sumOf { it.weight }
    fun expectedBranch(meter: Int, weight: Int, choice: String): String {
        val sc = when (choice) {
            "present" -> meter - weight
            "back" -> meter + Mystery6.BACK_BOOST
            "speak" -> meter - Mystery6.SPEAK_RELIEF
            else -> meter
        }
        return when {
            sc >= Mystery6.VERDICT_CONVICT_AT -> "convicted"
            sc >= Mystery6.VERDICT_HUNG_AT -> "hung"
            else -> "cleared"
        }
    }

    // ---------- the chapter defs ----------
    val ch6 = Mystery6.CHAPTERS6
    check(ch6.size == 4 && ch6.map { it.id }.toSet().size == 4,
        "opinion: the case is four chapters, uniquely id'd")
    check(ch6.all { it.theme.icon.isNotBlank() &&
        it.theme.header.isNotBlank() && it.causers.isNotEmpty() },
        "opinion: every chapter carries its theme and its credited causers")
    check(ch6.all { d -> d.stages.size == 4 && d.episodeTitles.size == 2 &&
        d.coldOpen.size == 2 && d.coldOpen.all { it.text.isNotBlank() } },
        "opinion: every chapter carries the full episode kit")
    check(ch6.none { d -> SHENANIGANS.any { it.id == d.id } },
        "opinion: no chapter sits in the random event pool")
    check(ch6.all { Mystery6.CHAPTER6_BY_ID[it.id] == it &&
        SHENANIGAN_BY_ID[it.id] == it },
        "opinion: every chapter resolves by id, in the case and in the game")
    check(ch6[0].stages.any { it.clusterLoc == "MainStreet" } &&
        ch6[1].stages.any { it.clusterLoc == "TweekBros" } &&
        ch6[2].stages.any { it.clusterLoc == "Elementary" } &&
        ch6[3].stages.any { it.clusterLoc == "CityHall" },
        "opinion: the chapters walk the wall, the retelling, the second look, the hall")
    val finDef6 = Mystery6.CHAPTER6_BY_ID[Mystery6.FINALE6_ID]!!
    check(finDef6.causers.containsAll(listOf("McDaniels", "Henrietta")),
        "opinion: the meeting is chaired by the mayor and answered by the accused")

    // ---------- the registries ----------
    check(Mystery6.GOSSIP6.size == 5 &&
        Mystery6.GOSSIP6.map { it.id }.toSet().size == 5,
        "opinion: five tellings, uniquely id'd")
    check(Mystery6.GOSSIP6.all { it.carrier in AGENT_PROFILES &&
        it.minChapter in 0..2 },
        "opinion: every telling has a real carrier and a sane chapter gate")
    check(Mystery6.BELIEFS6.size == Mystery6.GOSSIP6.size &&
        Mystery6.BELIEFS6.all { b ->
            Mystery6.GOSSIP6_BY_ID.containsKey(b.gossipId) &&
                b.testedBy != null && b.testedBy in Mystery6.CLUE6_IDS },
        "opinion: every belief is one telling's shadow, tested by real evidence")
    val clues6 = Mystery6.CLUES6
    check(clues6.size == 12 && Mystery6.CLUE6_IDS.size == 12,
        "opinion: the evidence is twelve pieces")
    check(clues6.count { it.kind == Mystery6.Kind6.WITNESS } == 5 &&
        clues6.count { it.kind == Mystery6.Kind6.LOOK } == 5 &&
        clues6.count { it.kind == Mystery6.Kind6.PARTICIPATION } == 2,
        "opinion: the verbs run 5 witness / 5 look / 2 participation")
    check(clues6.all { c -> c.minChapter in 0..2 &&
        when (c.kind) {
            Mystery6.Kind6.WITNESS ->
                c.npc != null && c.npc in AGENT_PROFILES &&
                    !c.spoken.isNullOrBlank()
            Mystery6.Kind6.LOOK ->
                c.locId != null && c.locId in LOCATIONS &&
                    !c.foundText.isNullOrBlank()
            Mystery6.Kind6.PARTICIPATION ->
                c.chapterDefId != null &&
                    c.chapterDefId in Mystery6.CHAPTER6_BY_ID
        } },
        "opinion: every piece names a real witness, place, or chapter")
    check(clues6.count { c -> Mystery6.BELIEFS6.any { it.testedBy == c.id } } >= 3,
        "opinion: at least three pieces exist solely to test the town's favorite story")

    // ---------- the meter, recomputed over every subset ----------
    val sweep = eng6.newState()
    sweep.arc6Started = true
    var subsetsOk = true
    for (mask in 0 until (1 shl Mystery6.GOSSIP6.size)) {
        val g = Mystery6.GOSSIP6.filterIndexed { i, _ -> mask and (1 shl i) != 0 }
            .map { it.id }.toSet()
        sweep.arc6Gossip.clear(); sweep.arc6Gossip.addAll(g)
        sweep.mystery6Clues.clear(); sweep.arc6Voice.clear()
        if (Mystery6.conviction(sweep) != recomputeConviction(g, emptySet(), emptyMap()))
            subsetsOk = false
        for (name in Mystery6.NAMES_IN_PLAY)
            if (Mystery6.suspicion(sweep, name) !=
                recomputeSuspicion(name, g, emptySet())) subsetsOk = false
    }
    check(subsetsOk,
        "opinion: the meter over all ${1 shl 5} gossip subsets — witnessed " +
            "tellings only, exactly as recomputed")
    var clueSweepOk = true
    for (mask in 0 until (1 shl clues6.size)) {
        val c = clues6.filterIndexed { i, _ -> mask and (1 shl i) != 0 }
            .map { it.id }.toSet()
        sweep.arc6Gossip.clear(); sweep.arc6Voice.clear()
        sweep.mystery6Clues.clear(); sweep.mystery6Clues.addAll(c)
        if (Mystery6.conviction(sweep) != recomputeConviction(emptySet(), c, emptyMap()))
            clueSweepOk = false
        if (Mystery6.presentedWeight(sweep) != recomputeWeight(c))
            clueSweepOk = false
        for (name in Mystery6.NAMES_IN_PLAY)
            if (Mystery6.suspicion(sweep, name) !=
                recomputeSuspicion(name, emptySet(), c)) clueSweepOk = false
    }
    check(clueSweepOk,
        "opinion: the meter and the presented weight over all ${1 shl 12} " +
            "evidence subsets — proven pieces only, exactly as recomputed")
    var voiceSweepOk = true
    val allGossip = Mystery6.GOSSIP6.map { it.id }.toSet()
    for (code in 0 until 1024) {
        var n = code
        val voice = mutableMapOf<String, String>()
        for (g in Mystery6.GOSSIP6) {
            when (n % 4) {
                1 -> voice[g.id] = "back"
                2 -> voice[g.id] = "question"
                3 -> voice[g.id] = "silent"
            }
            n /= 4
        }
        sweep.arc6Gossip.clear(); sweep.arc6Gossip.addAll(allGossip)
        sweep.mystery6Clues.clear()
        sweep.arc6Voice.clear(); sweep.arc6Voice.putAll(voice)
        if (Mystery6.conviction(sweep) !=
            recomputeConviction(allGossip, emptySet(), voice)) voiceSweepOk = false
    }
    check(voiceSweepOk,
        "opinion: the meter over all 4^5 stance assignments — your voice " +
            "counts exactly where you used it, and only on witnessed tellings")
    val rnd6 = Random(60606)
    var mixedOk = true
    repeat(300) {
        val g = Mystery6.GOSSIP6.filter { rnd6.nextBoolean() }.map { it.id }.toSet()
        val c = clues6.filter { rnd6.nextBoolean() }.map { it.id }.toSet()
        val v = g.associateWith {
            listOf("back", "question", "silent")[rnd6.nextInt(3)] }
        sweep.arc6Gossip.clear(); sweep.arc6Gossip.addAll(g)
        sweep.mystery6Clues.clear(); sweep.mystery6Clues.addAll(c)
        sweep.arc6Voice.clear(); sweep.arc6Voice.putAll(v)
        if (Mystery6.conviction(sweep) != recomputeConviction(g, c, v)) mixedOk = false
        if (Mystery6.presentedWeight(sweep) != recomputeWeight(c)) mixedOk = false
    }
    check(mixedOk,
        "opinion: 300 seeded mixed states — gossip × evidence × voice — " +
            "all recomputed exactly")
    // unwitnessed events move NOTHING: chapters aired, a stance
    // recorded for a telling never heard, evidence unproven —
    // the meter sits at its base.
    val deaf = eng6.newState()
    deaf.arc6Started = true; deaf.arc6Chapter = 3
    deaf.arc6Voice["instant_verdict"] = "back"
    check(Mystery6.conviction(deaf) == Mystery6.METER_BASE &&
        Mystery6.suspicion(deaf, "Adler") == 0 &&
        Mystery6.suspicion(deaf, "Randy") == 0,
        "opinion: a player who heard nothing has a town that decided " +
            "nothing extra — unwitnessed events move no needle")
    // the red herring is clearable by proof, to zero, on both names
    val herring = eng6.newState()
    herring.arc6Gossip.addAll(allGossip); herring.mystery6Clues.addAll(Mystery6.CLUE6_IDS)
    check(Mystery6.suspicion(herring, "Adler") == 0 &&
        Mystery6.suspicion(herring, "Randy") == 0,
        "opinion: with everything proven, both muttered-about names " +
            "stand at zero — the herrings are clearable by proof")
    check(recomputeConviction(emptySet(), Mystery6.CLUE6_IDS, emptyMap()) <
        Mystery6.VERDICT_HUNG_AT,
        "opinion: the proven record ALONE acquits — an innocent reading " +
            "of the accused is supported by evidence, not a trick")


    // ---------- the grants: four verbs, one discipline ----------
    fun caseAt(chapter: Int): GameState {
        val s = eng6.newState()
        s.arcRetired = true; s.arc2Retired = true; s.arc3Retired = true
        s.arc4Retired = true; s.arc5Retired = true
        s.arc6Started = true; s.arc6Chapter = chapter
        return s
    }
    val sWit = caseAt(2)
    check(Mystery6.witnessLine6(sWit, "Bradley")?.speaker == "Bradley" &&
        "the_sketchbook" in sWit.mystery6Clues &&
        Mystery6.witnessLine6(sWit, "Bradley") == null,
        "opinion: the boy with the sketchbook tells his proof once, and it lands")
    check(Mystery6.witnessLine6(caseAt(1), "Bradley") == null,
        "opinion: the sketchbook's proof waits for the second look")
    check(Mystery6.witnessLine6(caseAt(2), "Cartman") == null &&
        Mystery6.witnessLine6(caseAt(3), "Skeeter")?.speaker == "Skeeter" &&
        Mystery6.witnessLine6(caseAt(2), "Skeeter") == null,
        "opinion: witnesses speak in their chapter, and only witnesses speak")
    val sGos = caseAt(1)
    val gosLine = Mystery6.gossipLine6(sGos, "McDaniels")
    check(gosLine?.speaker == "McDaniels" &&
        "instant_verdict" in sGos.arc6Gossip &&
        Mystery6.pendingStanceGossip(sGos)?.id == "instant_verdict" &&
        Mystery6.gossipLine6(sGos, "McDaniels") == null,
        "opinion: a telling is witnessed once, from its carrier's own mouth, " +
            "and opens exactly one stance")
    check(Mystery6.gossipLine6(caseAt(1), "Gerald") == null &&
        Mystery6.gossipLine6(caseAt(2), "Gerald") != null,
        "opinion: later tellings wait for their chapters")
    val sVoice = caseAt(1)
    check(!Mystery6.chooseStance(sVoice, "instant_verdict", "back"),
        "opinion: no stance can be taken on a telling never witnessed")
    Mystery6.gossipLine6(sVoice, "McDaniels")
    val beforeVoice = Mystery6.conviction(sVoice)
    check(Mystery6.chooseStance(sVoice, "instant_verdict", "question") &&
        Mystery6.conviction(sVoice) == beforeVoice + Mystery6.VOICE_QUESTION &&
        Mystery6.pendingStanceGossip(sVoice) == null &&
        !Mystery6.chooseStance(sVoice, "instant_verdict", "back"),
        "opinion: a stance moves the needle by exactly its printed amount, once")
    val sLook = caseAt(1)
    check(Mystery6.lookClueText6(sLook, "MainStreet") != null &&
        "handprints_spared" in sLook.mystery6Clues &&
        Mystery6.lookClueText6(sLook, "MainStreet") == null &&
        Mystery6.lookClueText6(sLook, "Church") == null,
        "opinion: the wall gives its first fact to the first close look, once")
    val sLook2 = caseAt(2)
    Mystery6.lookClueText6(sLook2, "MainStreet")
    check(Mystery6.lookClueText6(sLook2, "MainStreet") != null &&
        "ladder_and_boot" in sLook2.mystery6Clues,
        "opinion: the second look at the wall finds the ladder's testimony")
    val sPart = caseAt(1)
    Mystery6.noteParticipation6(sPart, Mystery6.CHAPTERS6[0].id)
    check("saw_it_first" in sPart.mystery6Clues,
        "opinion: being at the unveiling is itself evidence")
    val sPart3 = caseAt(3)
    Mystery6.noteParticipation6(sPart3, Mystery6.CHAPTERS6[2].id)
    check("shop_accounted" in sPart3.mystery6Clues,
        "opinion: counting the shop's shelves with its keeper closes the herring's ledger")
    val sPart0 = eng6.newState()
    Mystery6.noteParticipation6(sPart0, Mystery6.CHAPTERS6[0].id)
    check(sPart0.mystery6Clues.isEmpty(),
        "opinion: participation before the case exists grants nothing")

    // ---------- the two columns, strictly separate ----------
    val sBoard = caseAt(2)
    sBoard.arc6Gossip.addAll(listOf("instant_verdict", "the_poem"))
    sBoard.arc6Voice["the_poem"] = "question"
    sBoard.mystery6Clues.addAll(listOf("the_sketchbook", "handprints_spared"))
    val boardText = Mystery6.boardLines6(sBoard).joinToString("\n")
    val bInstant = Mystery6.BELIEFS6.first { it.gossipId == "instant_verdict" }
    val bPoem = Mystery6.BELIEFS6.first { it.gossipId == "the_poem" }
    val bSeen = Mystery6.BELIEFS6.first { it.gossipId == "seen_at_wall" }
    check(boardText.contains(bInstant.text) && boardText.contains(bPoem.text),
        "opinion: witnessed tellings stand on the board as beliefs, sourced")
    check(!boardText.contains(bSeen.text),
        "opinion: a belief whose telling was never witnessed does not " +
            "exist — even when its testing evidence is already held")
    check(!Mystery6.beliefStanding(sBoard, bSeen) &&
        Mystery6.beliefHasHeldEvidence(sBoard, bSeen),
        "opinion: holding a belief's testing evidence never, by itself, " +
            "puts the belief on the board or corrects it — the columns " +
            "do not touch")
    check(boardText.indexOf("THE STORY") in 0 until boardText.indexOf("THE EVIDENCE") &&
        boardText.indexOf(bInstant.text) < boardText.indexOf("THE EVIDENCE") &&
        boardText.indexOf("The sketchbook is full of the mural") >
            boardText.indexOf("THE EVIDENCE"),
        "opinion: the board's columns are physically separate — beliefs " +
            "above the line, proof below it, nothing across")
    check(!boardText.contains("The ladder and the bootprint") &&
        boardText.contains("THE SCORE, AS IT STANDS") &&
        boardText.contains("YOUR VOICE SO FAR"),
        "opinion: unproven pieces stay unnamed, and the board publishes " +
            "the meeting's arithmetic and your voice while the case runs")
    var fateOk = true
    for (mask in 0 until (1 shl clues6.size)) {
        val c = clues6.filterIndexed { i, _ -> mask and (1 shl i) != 0 }
            .map { it.id }.toSet()
        val st = caseAt(2)
        st.arc6Gossip.addAll(allGossip); st.mystery6Clues.addAll(c)
        for (b in Mystery6.BELIEFS6) {
            if (Mystery6.beliefFate(st, b) != "STANDING") fateOk = false
            if (Mystery6.beliefHasHeldEvidence(st, b) !=
                (b.testedBy != null && b.testedBy in c)) fateOk = false
        }
    }
    check(fateOk,
        "opinion: mid-case, over every evidence subset, every belief " +
            "stands untouched — held evidence marks it, never corrects it")
    val sFate = caseAt(4)
    sFate.arc6Gossip.addAll(allGossip)
    sFate.mystery6Clues.addAll(Mystery6.CLUE6_IDS)
    sFate.arc6Retired = true; sFate.arc6Branch = "cleared"; sFate.arc6Presented = true
    check(Mystery6.beliefFate(sFate, bInstant) == "PUT TO THE MEETING",
        "opinion: a belief whose testing proof was presented is recorded as such")
    sFate.arc6Presented = false
    check(Mystery6.beliefFate(sFate, bInstant) == "HELD, NEVER PRESENTED",
        "opinion: the same proof, held but never presented, is remembered differently")
    bInstant.testedBy?.let { sFate.mystery6Clues.remove(it) }
    check(Mystery6.beliefFate(sFate, bInstant) == "STILL STANDING",
        "opinion: and a belief never tested at all simply stands")

    // ---------- the pressure: the meter, lived ----------
    check(Mystery6.bandOf(0) == 0 && Mystery6.bandOf(39) == 0 &&
        Mystery6.bandOf(40) == 1 && Mystery6.bandOf(59) == 1 &&
        Mystery6.bandOf(60) == 2 && Mystery6.bandOf(79) == 2 &&
        Mystery6.bandOf(80) == 3 && Mystery6.bandOf(100) == 3,
        "opinion: the pressure bands break exactly where the board says they break")
    val sCalm = caseAt(2)
    sCalm.mystery6Clues.addAll(listOf("the_sketchbook", "ladder_and_boot"))
    check(Mystery6.conviction(sCalm) < 40 &&
        Mystery6.pressureLine6(sCalm, "Henrietta") == null &&
        Mystery6.pressureLookText6(sCalm, "MainStreet") == null,
        "opinion: under a soft meter, the accused's days are her own")
    val sHot = caseAt(2)
    sHot.arc6Gossip.addAll(listOf("instant_verdict", "the_poem", "seen_at_wall"))
    check(Mystery6.bandOf(Mystery6.conviction(sHot)) >= 2 &&
        Mystery6.pressureLine6(sHot, "Henrietta") != null &&
        Mystery6.pressureLine6(sHot, "Bradley") != null &&
        Mystery6.pressureLookText6(sHot, "MainStreet") != null &&
        Mystery6.pressureLookText6(sHot, "Elementary") != null &&
        Mystery6.pressureLookText6(sHot, "Church") == null,
        "opinion: at a hardened meter the shunning is drawn in Talk and in Look")
    val band1Line = Mystery6.pressureLine6(caseAt(1), "Henrietta")
    val band3State = caseAt(2)
    band3State.arc6Gossip.addAll(allGossip)
    band3State.arc6Voice.putAll(allGossip.associateWith { "back" })
    check(Mystery6.bandOf(Mystery6.conviction(band3State)) == 3 &&
        band1Line != null &&
        Mystery6.pressureLine6(band3State, "Henrietta") != null &&
        (0..2).map { d ->
            band3State.absDay = d
            Mystery6.pressureLine6(band3State, "Henrietta")!!.text
        }.toSet().size >= 2,
        "opinion: the accused speaks differently as the town hardens — " +
            "her register is the meter, worn")
    val sTick = caseAt(2)
    sTick.life["arc6Band"] = 0
    sTick.arc6Gossip.addAll(listOf("instant_verdict", "the_poem", "seen_at_wall"))
    Mystery6.noteNewDay6(sTick)
    val hardens = sTick.events.count { it.contains("HARDENS") }
    Mystery6.noteNewDay6(sTick)
    check(hardens == 1 && sTick.events.count { it.contains("HARDENS") } == 1,
        "opinion: the morning ticker reports a hardening exactly once")
    sTick.mystery6Clues.addAll(Mystery6.CLUE6_IDS)
    Mystery6.noteNewDay6(sTick)
    check(sTick.events.count { it.contains("LOOSENS") } == 1,
        "opinion: and a loosening is news too, said quieter, once")

    // ---------- scheduling: behind the confessions, spaced ----------
    val sPre6 = eng6.newState()
    check(Mystery6.dueChapter6(sPre6) == null,
        "opinion: the case cannot open before the confessions retire")
    val sGate6 = eng6.newState()
    sGate6.arc5Retired = true; sGate6.arc5RetiredDay = 40
    sGate6.absDay = 49
    check(Mystery6.dueChapter6(sGate6) == null,
        "opinion: nine days after the fifth case is not ten")
    sGate6.absDay = 50
    check(Mystery6.dueChapter6(sGate6)?.id == Mystery6.CHAPTERS6[0].id,
        "opinion: on the tenth day, the unveiling is due")
    Mystery6.noteChapterStarted6(sGate6, Mystery6.CHAPTERS6[0])
    check(sGate6.arc6Started && sGate6.arc6Chapter == 1 &&
        sGate6.arc6DueAbsDay == 57,
        "opinion: chapter one books chapter two a week out")
    sGate6.absDay = 57
    check(Mystery6.dueChapter6(sGate6)?.id == Mystery6.CHAPTERS6[1].id,
        "opinion: chapter two is due on its day, a week after the first")
    sGate6.holidayId = "some_holiday"
    check(Mystery6.dueChapter6(sGate6) == null,
        "opinion: a holiday defers the chapter — holidays keep their day")
    sGate6.holidayId = null


    // ---------- the meeting: gate, calls, published arithmetic ----------
    fun meetState(clues: Int): GameState {
        val s = eng6.newState()
        s.arcRetired = true; s.arc2Retired = true; s.arc3Retired = true
        s.arc4Retired = true; s.arc5Retired = true
        s.arc6Started = true; s.arc6Chapter = 4
        s.shenaniganId = Mystery6.FINALE6_ID
        s.shenaniganDay = s.todayKey
        for (c in clues6.take(clues)) s.mystery6Clues.add(c.id)
        return s
    }
    check(!Mystery6.meetingDue(meetState(5).apply { timeMin = 19 * 60 }),
        "opinion: five pieces is NOT enough to call the meeting")
    check(!Mystery6.meetingDue(meetState(6).apply { timeMin = 10 * 60 }),
        "opinion: the meeting waits for the climax stage, not the morning")
    val sMeet = meetState(6); sMeet.timeMin = 19 * 60
    check(Mystery6.meetingDue(sMeet),
        "opinion: six pieces at the climax opens the meeting (the boundary)")
    check(Finales.climaxPending(sMeet),
        "opinion: a due meeting holds the season finales' calls, like every climax")
    check(!Mystery6.chooseMeeting(sMeet, "maybe"),
        "opinion: only the four calls can be made in that room")
    check(Mystery6.chooseMeeting(sMeet, "present") && sMeet.arc6Choice == "present" &&
        sMeet.arc6Presented,
        "opinion: presenting is a call, and the record keeps that it was made")
    check(!Mystery6.meetingDue(sMeet) && !Mystery6.chooseMeeting(sMeet, "back"),
        "opinion: a locked call closes the meeting")

    // the whole space, against the suite's own arithmetic
    val gridInputs = listOf(
        Triple(emptySet<String>(), emptySet<String>(), emptyMap<String, String>()),
        Triple(allGossip, emptySet<String>(), emptyMap<String, String>()),
        Triple(emptySet<String>(), Mystery6.CLUE6_IDS, emptyMap<String, String>()),
        Triple(allGossip, Mystery6.CLUE6_IDS, emptyMap<String, String>()),
        Triple(allGossip, Mystery6.CLUE6_IDS,
            allGossip.associateWith { "back" }),
        Triple(setOf("instant_verdict", "the_poem"),
            setOf("the_sketchbook", "ladder_and_boot", "handprints_spared",
                "her_media", "poem_context", "saw_it_first"), emptyMap<String, String>()),
        Triple(setOf("seen_at_wall"), clues6.take(6).map { it.id }.toSet(),
            mapOf("seen_at_wall" to "question")),
        Triple(allGossip, clues6.take(9).map { it.id }.toSet(),
            mapOf("the_poem" to "question", "randy_squeaks" to "back")))
    var gridOk = true
    for ((g, c, v) in gridInputs) {
        val st = eng6.newState()
        st.arc6Started = true
        st.arc6Gossip.addAll(g); st.mystery6Clues.addAll(c); st.arc6Voice.putAll(v)
        val meter = recomputeConviction(g, c, v)
        val weight = recomputeWeight(c)
        if (Mystery6.conviction(st) != meter) gridOk = false
        for (choice in Mystery6.CHOICE_KEYS) {
            if (Mystery6.branchForScore(Mystery6.meetingScore(st, choice)) !=
                expectedBranch(meter, weight, choice)) gridOk = false
        }
    }
    check(gridOk,
        "opinion: across the meter × evidence × call space, the meeting " +
            "lands exactly where the board's published arithmetic says")

    // ---------- the wrap: four landings, driven ----------
    val sixLight = setOf("saw_it_first", "the_tin", "handprints_spared",
        "poem_context", "sharon_account", "adler_meeting")
    fun wrappedMeet(choice: String, gossip: Set<String>,
                    clues: Set<String>, voice: Map<String, String>): GameState {
        val s = eng6.newState()
        s.arcRetired = true; s.arc2Retired = true; s.arc3Retired = true
        s.arc4Retired = true; s.arc5Retired = true
        s.arc6Started = true; s.arc6Chapter = 4
        s.shenaniganId = Mystery6.FINALE6_ID
        s.shenaniganDay = s.todayKey
        s.arc6Gossip.addAll(gossip); s.mystery6Clues.addAll(clues)
        s.arc6Voice.putAll(voice)
        s.arc6Choice = choice
        if (choice == "present") s.arc6Presented = true
        Episodes.beginEvent(s, finDef6)
        s.lastEventWeek = 39
        s.timeMin = 1430
        eng6.advanceTime(s)
        return s
    }
    // CLEARED: the full file, presented
    val sClearBase6 = wrappedMeet("present", emptySet(),
        Mystery6.CLUE6_IDS, emptyMap())
    check(sClearBase6.arc6Retired && sClearBase6.arc6Branch == "cleared" &&
        sClearBase6.arc6Presented,
        "opinion: the full file, presented, clears her — on the record")
    check(sClearBase6.episodes.last { it.eventId == Mystery6.FINALE6_ID }
        .recap.any { it.contains("CLEARED, ON THE EVIDENCE") },
        "opinion: the cleared ending's credits say what the call was")
    check((sClearBase6.friendship["Henrietta"] ?: 0) == 4 &&
        (sClearBase6.friendship["Bradley"] ?: 0) == 3,
        "opinion: the cleared warm to the one who put facts on the table")
    check(sClearBase6.lifeText["mark:MainStreet"]?.contains("cleared in the room") == true &&
        Mystery6.statusStamp6(sClearBase6).contains("CLEARED"),
        "opinion: the wall keeps the clearing's mark")
    check(sClearBase6.arc6WallPending && !sClearBase6.arc6WallRestored &&
        !Mystery6.noteWallRestored(sClearBase6),
        "opinion: after a clearing, the corner is not back yet")
    sClearBase6.absDay += Mystery6.WALL_RETURN_DELAY_DAYS
    check(Mystery6.noteWallRestored(sClearBase6) && sClearBase6.arc6WallRestored &&
        !Mystery6.noteWallRestored(sClearBase6),
        "opinion: a week on, the corner comes back — unsigned, exactly once")
    check(Mystery6.aftermathLine6(sClearBase6, "McDaniels")?.speaker == "McDaniels",
        "opinion: in the cleared town, the chair still insists the wall is owed an answer")
    // CONVICTED: the story at full throat, backed in the room
    val sConv = wrappedMeet("back", allGossip, sixLight,
        allGossip.associateWith { "back" })
    check(sConv.arc6Retired && sConv.arc6Branch == "convicted",
        "opinion: the story at full throat, backed, convicts")
    check((sConv.friendship["Henrietta"] ?: 0) == 0 &&
        (0 - Mystery6.CONVICT_SCAR) < 0 &&
        sConv.lifeText["mark:MainStreet"]?.contains("by order of the meeting") == true,
        "opinion: the convicted landing marks the wall and the sentence stands")
    val sConvBase = eng6.newState()
    sConvBase.friendship["Henrietta"] = 20
    sConvBase.arc6Retired = false
    Mystery6.applyMeetingEffects(sConvBase, "convicted")
    check((sConvBase.friendship["Henrietta"] ?: 0) == 20 - Mystery6.CONVICT_SCAR &&
        (sConvBase.friendship["Bradley"] ?: 0) == 0,
        "opinion: conviction scars the accused (-${Mystery6.CONVICT_SCAR}) — " +
            "community service is still a sentence")
    check(Mystery6.aftermathLine6(sConv, "Bradley")?.speaker == "Bradley" &&
        sConv.episodes.last { it.eventId == Mystery6.FINALE6_ID }
            .recap.any { it.contains("CONVICTED, ON THE STORY") },
        "opinion: in the convicted town, her brother objects — standing, forever")
    // HUNG: the full story AND the full file, and silence
    val sHung = wrappedMeet("land", allGossip, Mystery6.CLUE6_IDS, emptyMap())
    check(sHung.arc6Retired && sHung.arc6Branch == "hung" &&
        !sHung.arc6WallPending,
        "opinion: story and file at full weight, unspoken, hang the room")
    check(Mystery6.aftermathLine6(sHung, "Victoria")?.speaker == "Victoria" &&
        Mystery6.statusStamp6(sHung).contains("NO VERDICT"),
        "opinion: in the hung town, the clerk files it where it matters")
    // COLD: the meeting happened without you
    val sCold6 = wrappedMeet("", allGossip, Mystery6.CLUE6_IDS, emptyMap())
    check(sCold6.arc6Retired && sCold6.arc6Branch == "cold" &&
        !sCold6.arc6Presented,
        "opinion: an unattended meeting lands cold, whatever you were holding")
    check(sCold6.episodes.last { it.eventId == Mystery6.FINALE6_ID }
        .recap.any { it.contains("BY ACCLAMATION") } &&
        Mystery6.aftermathLine6(sCold6, "Bradley")?.speaker == "Bradley",
        "opinion: the cold landing keeps the empty chair in the record")
    // DEGRADED: a call locked without the evidence behind it
    val sDeg6 = wrappedMeet("present", emptySet(),
        clues6.take(5).map { it.id }.toSet(), emptyMap())
    check(sDeg6.arc6Retired && sDeg6.arc6Branch == "cold" && !sDeg6.arc6Presented,
        "opinion: an unbacked call degrades to cold at the wrap, presented or not")
    // the endings live on
    for ((s, branch) in listOf(sClearBase6 to "cleared", sConv to "convicted",
        sHung to "hung", sCold6 to "cold")) {
        check(Mystery6.ambientCallback6(s, Random(6)) != null &&
            Mystery6.statusStamp6(s).isNotBlank() &&
            Mystery6.boardLines6(s).any { it.startsWith("🏁") },
            "opinion: the '$branch' ending lives on — callbacks, stamp, closed board")
    }
    check(Mystery6.ambientCallback6(eng6.newState(), Random(6)) == null,
        "opinion: no callbacks before the case closes")

    // ---------- saves: additive, round-trip, pre-0.8.0f ----------
    val sSave6 = caseAt(2)
    sSave6.arc6DueAbsDay = 88
    sSave6.arc6Gossip.addAll(listOf("instant_verdict", "the_poem"))
    sSave6.arc6Voice["the_poem"] = "question"
    sSave6.mystery6Clues.addAll(listOf("the_sketchbook", "the_tin"))
    val back6 = decodeGameState(encodeGameState(sSave6))
    check(back6.arc6Started && back6.arc6Chapter == 2 &&
        back6.arc6DueAbsDay == 88 && !back6.arc6Retired &&
        back6.arc6Gossip == sSave6.arc6Gossip &&
        back6.arc6Voice == sSave6.arc6Voice &&
        back6.mystery6Clues == sSave6.mystery6Clues &&
        Mystery6.conviction(back6) == Mystery6.conviction(sSave6),
        "opinion: a mid-case save round-trips — and the meter, being " +
            "derived, comes back identical without ever being stored")
    val docOld6 = encodeGameState(sSave6).toMutableMap()
    docOld6.remove("arc6"); docOld6.remove("mystery6Clues")
    docOld6.remove("arc6Gossip"); docOld6.remove("arc6Voice")
    val backOld6 = decodeGameState(docOld6)
    check(!backOld6.arc6Started && backOld6.arc6Chapter == 0 &&
        backOld6.mystery6Clues.isEmpty() && backOld6.arc6Gossip.isEmpty() &&
        backOld6.arc6Voice.isEmpty() && !backOld6.arc6Retired,
        "opinion: a pre-v0.8.0f save loads with the sixth case simply " +
            "not yet queued")
    val sDone6 = eng6.newState()
    sDone6.arc6Retired = true; sDone6.arc6Branch = "cleared"
    sDone6.arc6WallRestored = true; sDone6.arc6Presented = true
    val backDone6 = decodeGameState(encodeGameState(sDone6))
    check(backDone6.arc6Retired && backDone6.arc6Branch == "cleared" &&
        backDone6.arc6WallRestored && backDone6.arc6Presented,
        "opinion: a closed case (and its restored corner) round-trips")

    // ---------- the six-case lifetime, driven ----------
    val engLife6 = Engine(6160)
    val life6 = engLife6.newState()
    var days6 = 0
    var arc6AfterArc5 = true
    while (days6 < 1600 && !(life6.arcRetired && life6.arc2Retired &&
        life6.arc3Retired && life6.arc4Retired && life6.arc5Retired &&
        life6.arc6Retired)) {
        engLife6.onNewDay(life6)
        if (life6.arc6Started) {
            check(life6.arc5Retired,
                "opinion: the sixth case never opens over the fifth " +
                    "(day $days6)")
            if (!life6.arc5Retired) arc6AfterArc5 = false
        }
        days6++
    }
    check(life6.arcRetired && life6.arc2Retired && life6.arc3Retired &&
        life6.arc4Retired && life6.arc5Retired && life6.arc6Retired,
        "opinion: one unattended life retires ALL SIX cases in order " +
            "(took $days6 days)")
    check(arc6AfterArc5,
        "opinion: the sixth case never opened before the fifth closed")
    check(life6.arc6Branch in Mystery6.BRANCH_KEYS &&
        Mystery6.dueChapter6(life6) == null,
        "opinion: the sixth case lands a real ending and the queue is empty")

    // ---------- wiring ----------
    val engineSrc6 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val talkSrc6 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val gameSrc6 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc6 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val prefsSrc6 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenSrc6 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    check(engineSrc6.contains("Mystery6.noteParticipation6") &&
        engineSrc6.contains("Mystery6.resolveMeeting") &&
        engineSrc6.contains("Mystery6.applyMeetingEffects") &&
        engineSrc6.contains("Mystery6.noteWallRestored") &&
        engineSrc6.contains("Mystery6.dueChapter6") &&
        engineSrc6.contains("Mystery6.noteNewDay6") &&
        engineSrc6.contains("Mystery6.ambientCallback6"),
        "opinion: the engine rolls, resolves, ripples, restores, ticks " +
            "and remembers the sixth case")
    check(talkSrc6.contains("Mystery6.witnessLine6") &&
        talkSrc6.contains("Mystery6.gossipLine6") &&
        talkSrc6.contains("Mystery6.pressureLine6") &&
        talkSrc6.contains("Mystery6.aftermathLine6"),
        "opinion: Talk owes the case its proofs, its tellings, its " +
            "pressure and its standing lines")
    check(gameSrc6.contains("Mystery6.lookClueText6") &&
        gameSrc6.contains("Mystery6.pressureLookText6") &&
        gameSrc6.contains("maybeShowMeeting") &&
        gameSrc6.contains("maybeShowVoice"),
        "opinion: Look finds the facts and the pressure; the meeting " +
            "and the voice present at safe moments")
    check(journalSrc6.contains("Mystery6.boardLines6") &&
        prefsSrc6.contains("\"arc6Voice\"") &&
        shenSrc6.contains("Mystery6.CHAPTERS6"),
        "opinion: the board renders, the save keeps the voice, the " +
            "registry holds the chapters")
    check(listOf("MovieNights.kt", "School.kt", "Walk.kt", "Finales.kt")
        .all { File(root, "src/com/hunt3r/southparktown/$it").readText()
            .contains("Mystery6.meetingDue") },
        "opinion: every deference list knows the meeting outranks it")

    // ---------- version + the spoiler wall ----------
    val manifestSrc6 = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc6.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc6.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "opinion: the manifest carries 67 / 0.9.0a")
    val readme6 = File(root, "docs/CHANGELOG.md").readText()
    val entryStart6 = readme6.indexOf("### v0.8.0f")
    val entryEnd6 = readme6.indexOf("### v0.8.0e")
    check(entryStart6 >= 0 && entryEnd6 > entryStart6,
        "opinion: the README carries this build's changelog entry")
    val entry6 = if (entryStart6 >= 0 && entryEnd6 > entryStart6)
        readme6.substring(entryStart6, entryEnd6) else ""
    check(entry6.lowercase().contains("court of public opinion") &&
        entry6.lowercase().contains("conviction meter"),
        "opinion: the changelog names the case and its meter")
    val midBoard = caseAt(2)
    midBoard.arc6Gossip.addAll(allGossip)
    midBoard.mystery6Clues.addAll(listOf("the_sketchbook", "the_tin",
        "patrol_log", "her_media"))
    val corpusParts = mutableListOf<String>()
    for (d in ch6) {
        corpusParts.add(d.title); corpusParts.add(d.cause); corpusParts.add(d.blurb)
        for (st in d.stages) {
            corpusParts.add(st.title); corpusParts.add(st.banner)
            corpusParts.add(st.journalNote); corpusParts.add(st.objective)
        }
        corpusParts.addAll(d.episodeTitles)
        for (l in d.coldOpen) corpusParts.add(l.text)
    }
    for (g in Mystery6.GOSSIP6) { corpusParts.add(g.spoken); corpusParts.add(g.storyShort) }
    for (b in Mystery6.BELIEFS6) { corpusParts.add(b.text); corpusParts.add(b.source) }
    for (c in clues6) {
        corpusParts.add(c.title); corpusParts.add(c.detail)
        corpusParts.add(c.spoken ?: ""); corpusParts.add(c.foundText ?: "")
    }
    corpusParts.add(Mystery6.boardLines6(midBoard).joinToString("\n"))
    corpusParts.add(Mystery6.forecastLine6(midBoard))
    for (band in 1..3) {
        val st = caseAt(2)
        st.arc6Gossip.addAll(when (band) {
            1 -> listOf("the_poem")
            2 -> listOf("instant_verdict", "the_poem", "seen_at_wall")
            else -> allGossip.toList()
        })
        if (band == 3) st.arc6Voice.putAll(allGossip.associateWith { "back" })
        corpusParts.add(Mystery6.pressureLine6(st, "Henrietta")?.text ?: "")
        corpusParts.add(Mystery6.pressureLine6(st, "Bradley")?.text ?: "")
    }
    corpusParts.add(entry6)
    val corpus6 = corpusParts.joinToString("\n").lowercase()
    val deny6 = listOf(
        "the mayor did", "mcdaniels did it", "the mayor painted",
        "mcdaniels painted", "painted it herself", "painted over it herself",
        "her own face", "henrietta is innocent", "she is innocent",
        "didn't paint", "did not paint", "never touched the wall",
        "framed", "scapegoat", "wrongly convicted", "set her up",
        "the hand was", "the vandal was")
    check(deny6.none { it in corpus6 },
        "opinion: the spoiler wall holds over every pre-reveal word — " +
            "chapters, tellings, beliefs, evidence, board, pressure, changelog")
}


// ================= v0.8.0g: polish & performance pass #8 =================
