        // five yearbooks: the shelf's own shape — the
        // newest three whole (six judged entries each,
        // records fat, one category honestly blank in
        // the middle book), the elders index-only
        fun ybEntries(year: Int, blankAt: Int): List<YearbookEntry> =
            Yearbook.CATEGORIES.mapIndexed { ci, cat ->
                if (ci == blankAt) YearbookEntry(
                    categoryId = cat.id,
                    judge = Yearbook.judgeFor(year, ci).name,
                    score = 0,
                    note = "No entry. The slot stays empty in " +
                        "print, which the judges call honesty.",
                    record = null)
                else YearbookEntry(
                    categoryId = cat.id,
                    judge = Yearbook.judgeFor(year, ci).name,
                    score = 90 + ci * 11 + year % 7,
                    note = "A judge's note at full length: the " +
                        "frame holds the whole town, the light " +
                        "did what the light does, and nobody " +
                        "in it is pretending otherwise.",
                    record = fatGroup("yv-$year-${cat.id}",
                        600 + year % 60 + ci, ci % 2 == 0))
            }
        fun ybVol(year: Int, full: Boolean, photos: Int,
                  blankAt: Int = -1): YearbookVolume =
            YearbookVolume(
                year = year, photoCount = photos,
                publishedKey = Yearbook.endKeyOf(year),
                publishedAbsDay = 500 + year % 90,
                pamphlet = false, indexOnly = !full,
                winnersLine = if (full) "" else
                    "Best Group Shot: the whole class, posed " +
                        "and crashed · Town Favorite: the one " +
                        "with absolutely everybody in it",
