                    else emptyList())
        vet.yearbooks += ybVol(2023, full = false, photos = 41)
        vet.yearbooks += ybVol(2024, full = false, photos = 52)
        vet.yearbooks += ybVol(2025, full = true, photos = 63)
        vet.yearbooks += ybVol(2026, full = true, photos = 58,
