                    "for days afterwards, part ${i + 1}"
            }
        vet.lifeText["rivalStanding"] = Rival.WORTHY
        vet.lifeText["rivalBeat"] = "🆚 Some race, some morning, " +
            "a long time ago now — the town still argues it."
        vet.life["rivalBeatDay"] = 699
        vet.lifeText["rivalLastKind"] = Rival.K_RACE
        vet.lifeText["rivalLastWinner"] = "you"
        vet.life["rivalLastDay"] = 699
        // the sixth case, closed, its full file held, the
