        // leaves it
        for (c in Mystery6.CLUES6) vet.mystery6Clues.add(c.id)
        for (g in Mystery6.GOSSIP6) vet.arc6Gossip.add(g.id)
        for (g in Mystery6.GOSSIP6)
            vet.arc6Voice[g.id] = "question"
        vet.arc6Started = true; vet.arc6Chapter = 4
        vet.arc6Retired = true; vet.arc6Branch = "cleared"
        vet.arc6Choice = "present"; vet.arc6Presented = true
        vet.arc6RetiredDay = 690
        vet.arc6WallRestored = true
        val vetJson = Json.stringify(encodeGameState(vet))
        println("veteran VII game_state: ${vetJson.length} chars serialized")
        check(vetJson.length < 512 * 1024,
            "veteran VII: the saturated save (Queue #8 included) " +
                "stays under the 512K ceiling (got ${vetJson.length})")
        check(vetJson.length > 354_758,
            "veteran VII: today's full state outgrows veteran " +
                "VI's 354,758 as this tree measures it — the " +
                "growth is Queue #8's own records, each one " +
                "capped (got ${vetJson.length})")
        @Suppress("UNCHECKED_CAST")
        val vetBack = decodeGameState(Json.parse(vetJson) as Map<String, Any?>)
        check(vetBack.errands.size == Errands.STATE_CAP &&
            vetBack.photos.size == 60 && StoryArcs.allDone(vetBack) &&
            vetBack.busPass && vetBack.walkTrips == 900 &&
            vetBack.arc5Retired && vetBack.arcRetired &&
            vetBack.arc2Retired && vetBack.arc3Retired &&
            vetBack.arc4Retired,
            "veteran VII: the veteran body still round-trips " +
                "whole — five older cases closed beneath the sixth")
        check(Capstones.capstonesDone(vetBack) == 8 &&
            Capstones.titlesEarned(vetBack).size == 8 &&
            Capstones.markTokensByLoc(vetBack)
                .values.sumOf { it.size } == 8 &&
            Capstones.CHAINS.all {
                Capstones.activeBeat(vetBack, it.factionId) == null },
            "veteran VII: all eight capstones round-trip " +
                "complete — titles, marks and no beat left armed")
        check(Emergencies.rescuesDone(vetBack) == 25 &&
            Emergencies.RESCUE_FEATS.all {
                Emergencies.rescueFeatEarned(vetBack, it) },
            "veteran VII: the rescue record round-trips past " +
                "both earned feats")
        check(Yearbook.volumes(vetBack).size == 5 &&
            Yearbook.volumes(vetBack).count { it.indexOnly } == 2 &&
            Yearbook.volumes(vetBack).count { !it.indexOnly } == 3 &&
            Yearbook.volumes(vetBack).first { !it.indexOnly }
                .entries.size == Yearbook.CATEGORIES.size &&
            "yearbook_shelf" in House.decorFor(vetBack),
            "veteran VII: five yearbooks round-trip — three " +
                "whole, two index-only, the shelf on the wall")
        check(Rival.contestsPlayed(vetBack) == 27 &&
            Rival.contestLog(vetBack).size == Rival.LOG_CAP &&
            Rival.standingOf(vetBack) == Rival.WORTHY &&
            Rival.locked(vetBack) &&
            Rival.rivalOf(vetBack) == "Craig",
            "veteran VII: the rivalry round-trips at its " +
                "ledger cap with the standing locked and read " +
                "back whole")
        check(vetBack.arc6Retired && vetBack.arc6Branch == "cleared" &&
            vetBack.arc6Presented && vetBack.arc6WallRestored &&
            vetBack.mystery6Clues.size == Mystery6.CLUES6.size &&
            vetBack.arc6Gossip.size == Mystery6.GOSSIP6.size &&
            Mystery6.dueChapter6(vetBack) == null,
            "veteran VII: the sixth case's typed state " +
                "round-trips closed, its full file held, its " +
                "wall home")

        // ---------- fit QA: Queue #8's newest screens ----------
        // The same Chrome discipline on the pages the queue
        // added, composed the way their screens compose
        // them: the CAPSTONES page off a state holding an
        // earned title AND an armed second beat (plus the
        // veteran's full eight), the YEARBOOK shelf off
        // the veteran (three whole volumes rendered entry
        // by entry as the Journal renders them, the elders
        // as their one index lines), THE RIVAL off the
        // veteran's locked ledger, the sixth case's board
        // in three fabrications (mid-case with evidence
        // held, post-meeting presented, post-meeting held
        // back — every standing a belief can wear), and the
        // Journal's errand page under a live emergency with
        // its countdown running.
        val engF = Engine(808_505)
        val fitCap = engF.newState()
        engF.createPlayer(fitCap, "Fitcheck", DEFAULT_APPEARANCE)
        fitCap.life["fmMask:school_staff"] = 0b111
        fitCap.life["capMask:school_staff"] = 0b111
        fitCap.life["fmMask:boys_crew"] = 0b111
        fitCap.factionStates["boys_crew"]!!.playerStanding = 70
        val fcOffer = CharacterSystem.CAST.keys.firstNotNullOfOrNull { n ->
            Capstones.offerFor(fitCap, n)
                ?.takeIf { it.factionId == "boys_crew" } }
        check(fcOffer != null && Capstones.accept(fitCap, fcOffer),
            "fitQA: the capstone page's state arms a real beat")
        fitCap.timeMin = 10 * 60
        Capstones.judgeTalk(fitCap, "Stan")
        val fcOffer2 = CharacterSystem.CAST.keys
            .firstNotNullOfOrNull { n ->
                Capstones.offerFor(fitCap, n)
                    ?.takeIf { it.factionId == "boys_crew" } }
        check(fcOffer2 != null && Capstones.accept(fitCap, fcOffer2) &&
            Capstones.mask(fitCap, "boys_crew") == 0b001,
            "fitQA: the first beat lands and the second stands armed")
        val boardMid = engF.newState()
        engF.createPlayer(boardMid, "Board", DEFAULT_APPEARANCE)
        boardMid.arcRetired = true; boardMid.arc2Retired = true
        boardMid.arc3Retired = true; boardMid.arc4Retired = true
        boardMid.arc5Retired = true
        boardMid.arc6Started = true; boardMid.arc6Chapter = 3
        for (g in Mystery6.GOSSIP6) boardMid.arc6Gossip.add(g.id)
        for (c in Mystery6.CLUES6.take(6))
            boardMid.mystery6Clues.add(c.id)
        val boardPresented = engF.newState()
        engF.createPlayer(boardPresented, "Board", DEFAULT_APPEARANCE)
        boardPresented.arcRetired = true; boardPresented.arc2Retired = true
        boardPresented.arc3Retired = true; boardPresented.arc4Retired = true
        boardPresented.arc5Retired = true
        boardPresented.arc6Started = true; boardPresented.arc6Chapter = 4
        boardPresented.arc6Retired = true
        boardPresented.arc6Branch = "hung"
        boardPresented.arc6Choice = "present"
        boardPresented.arc6Presented = true
        for (g in Mystery6.GOSSIP6) boardPresented.arc6Gossip.add(g.id)
        for (c in Mystery6.CLUES6.take(6))
            boardPresented.mystery6Clues.add(c.id)
        val boardHeld = engF.newState()
        engF.createPlayer(boardHeld, "Board", DEFAULT_APPEARANCE)
        boardHeld.arcRetired = true; boardHeld.arc2Retired = true
        boardHeld.arc3Retired = true; boardHeld.arc4Retired = true
        boardHeld.arc5Retired = true
        boardHeld.arc6Started = true; boardHeld.arc6Chapter = 4
        boardHeld.arc6Retired = true
        boardHeld.arc6Branch = "convicted"
        boardHeld.arc6Choice = "back"
        for (g in Mystery6.GOSSIP6) boardHeld.arc6Gossip.add(g.id)
        for (c in Mystery6.CLUES6) boardHeld.mystery6Clues.add(c.id)
        val boards = Mystery6.boardLines6(boardMid) +
            Mystery6.boardLines6(boardPresented) +
            Mystery6.boardLines6(boardHeld)
        check(boards.any { it.contains("THE STORY") } &&
            boards.any { it.contains("THE EVIDENCE") } &&
            boards.any { it.contains("STANDING") } &&
            boards.any { it.contains("PUT TO THE MEETING") } &&
            boards.any { it.contains("HELD, NEVER PRESENTED") } &&
            boards.any { it.contains("STILL STANDING") },
            "fitQA: the three boards between them show every " +
                "standing a belief can wear — standing (with " +
                "and without held evidence), put to the " +
                "meeting, held never presented, still standing")
        // a live emergency, found the v0.8.0c way: the
        // first 2027 date carrying a scenario outside a
        // finale window, offered and accepted for real
        val engE = Engine(808_606)
        fun freshOn8(y: Int, m: Int, d: Int): GameState {
            val s = engE.newState()
            engE.createPlayer(s, "Responder", DEFAULT_APPEARANCE)
            s.gameYear = y; s.gameMonth = m; s.gameDay = d
            s.todayKey = "%04d%02d%02d".format(y, m, d)
            s.timeMin = 10 * 60
            return s
        }
        val monthLens8 =
            intArrayOf(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
        var emergState: GameState? = null
        run {
            var (y, m, d) = Triple(2027, 1, 1)
            var guard = 0
            while (emergState == null && guard++ < 400) {
                val s = freshOn8(y, m, d)
                val sc = Emergencies.todaysScenario(s)
                if (sc != null && Finales.windowAt(s) == null) {
                    val offer = Emergencies.pendingOffer(s, sc.asker,
                        engE.player(s).location)
                    if (offer != null) {
                        Emergencies.markOffered(s, sc.asker)
                        if (Emergencies.accept(s, offer) != null)
                            emergState = s
                    }
                }
                d++
                if (d > monthLens8[m - 1]) {
                    d = 1; m++; if (m > 12) { m = 1; y++ }
                }
            }
        }
        check(emergState != null &&
            Emergencies.liveEmergency(emergState!!) != null,
            "fitQA: a live emergency stands fabricated for the " +
                "Journal page")
        fun volumeLines(v: YearbookVolume): List<String> {
            val out = mutableListOf<String>()
            out += Yearbook.coverLines(v)
            for (e in v.entries) {
                val cat = Yearbook.categoryById(e.categoryId)
                out += "${cat?.emoji ?: "📷"} " +
                    "${cat?.title ?: e.categoryId}"
                e.record?.let { rec ->
                    out += rec.caption
                    out += "Judges' score: ${e.score}" +
                        (if (rec.starred) " (⭐ starred)" else "")
                }
                val role = Yearbook.EDITORS
                    .firstOrNull { it.name == e.judge }?.role
                out += "“${e.note}”" +
                    (if (e.judge.isNotEmpty())
                        "\n— ${e.judge}" +
                            (role?.let { ", $it" } ?: "")
                    else "")
            }
            return out
        }
        val q8Lines = mutableListOf<String>()
        q8Lines += Capstones.pageLines(fitCap)
        q8Lines += Capstones.pageLines(vetBack)
        q8Lines += Yearbook.pageLines(vetBack)
        for (v in Yearbook.volumes(vetBack).filter { !it.indexOnly })
            q8Lines += volumeLines(v)
        for (v in Yearbook.volumes(vetBack).filter { it.indexOnly })
            q8Lines += Yearbook.indexLine(v)
        q8Lines += Rival.pageLines(vetBack)
        q8Lines += boards
        q8Lines += Errands.pageLines(emergState!!)
        check(Capstones.pageLines(fitCap).any {
                it.contains("Keeper of the Bell") } &&
            Capstones.pageLines(fitCap).any {
                it.startsWith("▶") &&
                    it.contains("beat 2 of 3 taken on") } &&
            Capstones.pageLines(vetBack).count {
                it.startsWith("✓") } == 8,
            "fitQA: the CAPSTONES page shows an earned title " +
                "beside an armed beat's mark, and the " +
                "veteran's full eight")
        check(Errands.pageLines(emergState!!).any {
                it.contains("🚨 EMERGENCY") &&
                    it.contains("min left") },
            "fitQA: the Journal's errand page carries the " +
                "emergency line with its countdown running")
        check(Rival.pageLines(vetBack).any {
                it.contains("Standing: WORTHY OPPONENT") } &&
            Rival.pageLines(vetBack).count {
                it.contains("· ") } >= Rival.LOG_CAP,
            "fitQA: THE RIVAL page shows the locked standing " +
                "over a ledger at its cap")
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { s: String -> s.length * 10f * fs }
            for (line in q8Lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a Queue #8 screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a Queue #8 screen line never collapses at fs $fs")
            }
        }
    }

    run {
        // ---------- the rail order, final form: eleven rails ----------
        // The ladder grew twice this queue — EMERG_OFFER
        // (v0.8.0c) and RIVAL (v0.8.0e), both slotted BELOW
        // the faction mission rail and ABOVE the plain ask:
        // an errand is a transaction, a mission is a
        // relationship, but an emergency is a siren and a
        // rivalry is the day's standing appointment.
        // Pin the full order in source first — enum and
        // try-order, the v0.7.0g technique.
        val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        val enumBody = tgSrc.substring(
            tgSrc.indexOf("enum class Rail"),
            tgSrc.indexOf("data class Gate"))
        val enumOrder = listOf("DELIVER", "HOLIDAY_BEAT", "FINALE",
            "CLIMAX", "DINNER", "WORK", "FACTION_MISSION",
            "EMERG_OFFER", "RIVAL", "ERRAND_ASK", "DIALOGUE")
        val enumIdx = enumOrder.map { enumBody.indexOf(it) }
        check(enumIdx.all { it >= 0 } &&
            enumIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: the Rail enum declares the eleven " +
                "rails in ladder order")
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        val railOrder = enumOrder.map { "Rail.$it" }
        val railIdx = railOrder.map { gateBody.indexOf(it) }
        check(railIdx.all { it >= 0 } &&
            railIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: gateFor tries the eleven rails in " +
                "ladder order — DELIVER, HOLIDAY_BEAT, FINALE, " +
                "CLIMAX, DINNER, WORK, FACTION_MISSION, " +
                "EMERG_OFFER, RIVAL, ERRAND_ASK, DIALOGUE")
        // No single NPC in town can hold all eleven: the
        // queue's two new rails live on disjoint people.
        // Prove it from the live data, then peel the
        // fullest stack the town CAN build — Clyde, the
        // one rival-pool kid who is also an emergency
        // asker, holding DELIVER + EMERG_OFFER + RIVAL +
        // ERRAND_ASK over a plain dialogue. (Randy's
        // nine-rail stack from v0.7.0g stands in its own
        // section, unchanged; the rails above Clyde's were
        // each proven null for him by the peel itself.)
        val poolNames = Rival.POOL.map { it.name }.toSet()
        val emergAskers = Emergencies.SCENARIOS
            .map { it.asker }.toSet()
        val dinnerMembers = Dinners.HOUSEHOLDS
            .flatMap { it.members }.toSet()
        check(poolNames.intersect(emergAskers) == setOf("Clyde") &&
            poolNames.intersect(emergAskers)
                .intersect(dinnerMembers).isEmpty() &&
            "Randy" !in poolNames,
            "contention: no NPC holds every rail — the " +
                "rival pool and the emergency askers meet in " +
                "exactly one name (Clyde), who sits at no " +
                "family's table, and the nine-rail holder " +
                "stands outside the pool entirely")
        val engC = Engine(808_707)
        fun clydeState(): GameState? {
            val startOrd = ordinalOfKey("20270101")
            for (nameIdx in 0..60) {
                val probe = engC.newState()
                engC.createPlayer(probe, "Kid$nameIdx",
                    DEFAULT_APPEARANCE)
                if (Rival.pickFor(probe) != "Clyde") continue
                var (y, m, d) = Triple(2027, 1, 1)
                val lens = intArrayOf(31, 28, 31, 30, 31, 30,
                    31, 31, 30, 31, 30, 31)
                repeat(500) {
                    val s = engC.newState()
                    engC.createPlayer(s, "Kid$nameIdx",
                        DEFAULT_APPEARANCE)
                    s.gameYear = y; s.gameMonth = m; s.gameDay = d
                    s.todayKey = "%04d%02d%02d".format(y, m, d)
                    s.absDay = 500 + (ordinalOfKey(s.todayKey) -
                        startOrd)
                    s.timeMin = 10 * 60
                    s.life["fmMask:craigs_gang"] = 0b111
                    s.life["fmActive:craigs_gang"] = 0
                    val sc = Emergencies.todaysScenario(s)
                    val loc8 = s.agents["Clyde"]!!.location
                    if (sc != null && sc.asker == "Clyde" &&
                        Errands.askFor(s, "Clyde") != null &&
                        !Emergencies.momentOwned(s) &&
                        FactionMissions.offerFor(s, "Clyde") == null &&
                        FactionMissions.talkBeatFor(s, "Clyde") == null &&
                        Capstones.offerFor(s, "Clyde") == null &&
                        Capstones.talkBeatFor(s, "Clyde") == null)
                        return s
                    d++
                    if (d > lens[m - 1]) {
                        d = 1; m++; if (m > 12) { m = 1; y++ }
                    }
                }
            }
            return null
        }
        val sClyde = clydeState()
        check(sClyde != null,
            "contention: a morning exists where Clyde is the " +
                "crowned rival, the day's emergency is his, and " +
                "he holds an ask of his own")
        if (sClyde != null) {
            val loc8 = sClyde.agents["Clyde"]!!.location
            engC.player(sClyde).location = loc8
            sClyde.errands.add(Errand(
                id = "stack8-deliver", source = Errands.BOARD,
                asker = "Stan", type = "DELIVER",
                text = "A package with Clyde's name on it.",
                hint = "He's around.",
                targetName = "Clyde", itemId = "fishing_lure",
                dayKey = sClyde.todayKey,
                acceptedDay = sClyde.absDay))
            sClyde.inventory["fishing_lure"] =
                (sClyde.inventory["fishing_lure"] ?: 0) + 1
            var g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.DELIVER,
                "contention: Clyde's stack peels at DELIVER — " +
                    "a held delivery outranks the siren")
            Errands.deliverTo(sClyde, "Clyde")
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.EMERG_OFFER &&
                g.emergOffer != null,
                "contention: under the delivery stands " +
                    "EMERG_OFFER — Clyde's own emergency, priced " +
                    "and waiting")
            Emergencies.markOffered(sClyde, "Clyde")
            Emergencies.decline(sClyde)
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.RIVAL &&
                g.rivalHit?.kind == "reveal",
                "contention: the emergency declined (never " +
                    "accepted — a live one would deafen this " +
                    "rail), the RIVAL reveal stands next")
            Rival.playReveal(sClyde, 1)
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.ERRAND_ASK &&
                g.ask != null,
                "contention: under the rivalry, Clyde's own " +
                    "ask — the rail that was always there")
            Errands.markAsked(sClyde, "Clyde")
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.DIALOGUE,
                "contention: and under everything, a person " +
                    "with something to say — the peel is complete")
        }
    }

    run {
        // ---------- seams: the queue against the town ----------
        val engS = Engine(808_313)

        // Yearbook × the album cap: the shed order is the
        // judging pool's insurance. Fill the album to its
        // cap with unstarred frames and one star in the
        // middle; one more photo sheds the OLDEST
        // unprotected frame and keeps the star — and the
        // star is still in its school year's judged pool.
        val sAlb = engS.newState()
        engS.createPlayer(sAlb, "Album", DEFAULT_APPEARANCE)
        fun albRec(id: String, day: Int,
                   starred: Boolean = false) = PhotoRecord(
            id = id, dayKey = "20270115", dateLabel = "1/15",
            timeMin = 600, locId = "MainStreet", inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = listOf(
                PhotoFigure("Album", "player", "happy")),
            seed = day.toLong(), absDay = day, starred = starred)
        repeat(Photos.ALBUM_CAP) { i ->
            sAlb.photos.add(albRec("cap$i", 100 + i, i == 30))
        }
        Photos.applyPhoto(sAlb, albRec("cap-new", 500))
        check(sAlb.photos.size == Photos.ALBUM_CAP &&
            sAlb.photos.any { it.id == "cap30" } &&
            sAlb.photos.none { it.id == "cap0" } &&
            sAlb.photos.any { it.id == "cap-new" },
            "seam: at the album cap the shed takes the " +
                "oldest unprotected frame — the starred one " +
                "stands, and the new frame lands")
        check(Yearbook.albumFor(sAlb, 2027)
            .any { it.id == "cap30" && it.starred },
            "seam: the surviving star sits in its school " +
                "year's judged pool, bonus and all")

        // The capstone cross-beats, in lived dress: the
        // three verbs whose landing lives in ANOTHER
        // system's funnel, driven on fabricated states
        // whose gates are honestly met.
        fun capState8(fid: String): GameState {
            val s = engS.newState()
            engS.createPlayer(s, "Crossbeat", DEFAULT_APPEARANCE)
            s.life["fmMask:$fid"] = 0b111
            s.life["fmActive:$fid"] = 0
            s.factionStates[fid]!!.playerStanding = 70
            return s
        }
        fun offerBeat8(s: GameState,
                       fid: String): CapstoneBeat? =
            CharacterSystem.CAST.keys.firstNotNullOfOrNull { n ->
                Capstones.offerFor(s, n)
                    ?.takeIf { it.factionId == fid } }
        // (1) the Bijou screening photo (boys_crew beat 2)
        val sPh = capState8("boys_crew")
        val phB1 = offerBeat8(sPh, "boys_crew")
        check(phB1 != null && Capstones.accept(sPh, phB1),
            "seam: the boys' first beat arms for the photo test")
        sPh.timeMin = 10 * 60
        Capstones.judgeTalk(sPh, "Stan")
        val phB2 = offerBeat8(sPh, "boys_crew")
        check(phB2 != null && phB2.verb == "PHOTO" &&
            Capstones.accept(sPh, phB2) &&
            Capstones.mask(sPh, "boys_crew") == 0b001,
            "seam: the screening beat stands armed after the talk")
        var phGuard = 0
        while (phGuard++ < 21 &&
            (!MovieNights.isScreeningDay(sPh.absDay) ||
                MovieNights.isDarkTonight(sPh)))
            engS.onNewDay(sPh)
        check(MovieNights.isScreeningDay(sPh.absDay) &&
            !MovieNights.isDarkTonight(sPh),
            "seam: a live screening night arrives in the calendar")
        fun bijouPhoto(id: String) = PhotoRecord(
            id = id, dayKey = sPh.todayKey, dateLabel = "?",
            timeMin = sPh.timeMin, locId = "Bijou", inside = true,
            weatherId = sPh.weatherId, appearance = DEFAULT_APPEARANCE,
            figures = listOf(
                PhotoFigure("Crossbeat", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy")),
            seed = sPh.absDay.toLong(), absDay = sPh.absDay)
        sPh.timeMin = 12 * 60
        Photos.applyPhoto(sPh, bijouPhoto("seam-noon"))
        check(Capstones.mask(sPh, "boys_crew") == 0b001,
            "seam: a noon photo at the Bijou does NOT land " +
                "the screening beat — the house must be live")
        sPh.timeMin = 19 * 60 + 15
        check(Capstones.screeningLive(sPh),
            "seam: at 7:15 on the night, the screening is live")
        Photos.applyPhoto(sPh, bijouPhoto("seam-show"))
        check(Capstones.mask(sPh, "boys_crew") == 0b011,
            "seam: the same shutter, inside the screening, " +
                "lands the beat through applyPhoto's own funnel")
        // (2) the votes-week vote (girls_circle beat 2)
        val sV = capState8("girls_circle")
        val vB1 = offerBeat8(sV, "girls_circle")
        check(vB1 != null && Capstones.accept(sV, vB1),
            "seam: the circle's first beat arms for the vote test")
        sV.timeMin = 10 * 60
        Capstones.judgeTalk(sV, "Bebe")
        val vB2 = offerBeat8(sV, "girls_circle")
        check(vB2 != null && vB2.verb == "VOTE" &&
            Capstones.accept(sV, vB2),
            "seam: the vote beat stands armed after the talk")
        Votes.castVote(sV,
            Votes.currentQuestion(sV).options.first().id)
        var vGuard = 0
        while (vGuard++ < 10 &&
            Capstones.mask(sV, "girls_circle") and 0b010 == 0)
            engS.onNewDay(sV)
        check(Capstones.mask(sV, "girls_circle") and 0b010 != 0,
            "seam: the week's count lands the armed vote " +
                "beat — the ballot was real, the funnel was Votes'")
        val sV2 = capState8("girls_circle")
        val v2B1 = offerBeat8(sV2, "girls_circle")
        if (v2B1 != null) Capstones.accept(sV2, v2B1)
        sV2.timeMin = 10 * 60
        Capstones.judgeTalk(sV2, "Bebe")
        val v2B2 = offerBeat8(sV2, "girls_circle")
        if (v2B2 != null) Capstones.accept(sV2, v2B2)
        repeat(9) { engS.onNewDay(sV2) }
        check(Capstones.mask(sV2, "girls_circle") and 0b010 == 0,
            "seam: with no ballot cast, the same count lands " +
                "nothing — the beat waits for a vote, honestly")
        // (3) the jobs clock-out (parents beat 2)
        val sJ = capState8("parents")
        val jB1 = offerBeat8(sJ, "parents")
        check(jB1 != null && Capstones.accept(sJ, jB1),
            "seam: the parents' first beat arms for the shift test")
        sJ.timeMin = 10 * 60
        Capstones.judgeTalk(sJ, "Sharon")
        val jB2 = offerBeat8(sJ, "parents")
        check(jB2 != null && jB2.verb == "JOB" &&
            Capstones.accept(sJ, jB2),
            "seam: the job beat stands armed after the talk")
        var jLanded = false
        var jGuard = 0
        while (!jLanded && jGuard++ < 14) {
            if (Jobs.currentJob(sJ) == null) {
                val def = Jobs.JOBS.firstOrNull {
                    Jobs.isShiftDay(sJ.absDay, it) }
                if (def != null) {
                    sJ.timeMin = 8 * 60 + 30
                    Jobs.judgeTalk(sJ, Jobs.bossFor(sJ, def),
                        Jobs.workplaceFor(sJ, def))
                }
            }
            val job = Jobs.currentJob(sJ)
            if (job != null && Jobs.isShiftDay(sJ.absDay, job) &&
                !Jobs.shiftDoneToday(sJ)) {
                sJ.timeMin = 8 * 60 + 30
                if (!Jobs.clockedIn(sJ))
                    Jobs.judgeTalk(sJ, Jobs.bossFor(sJ, job),
                        Jobs.workplaceFor(sJ, job))
                for (t in Jobs.tasksFor(sJ, job)) when (t.kind) {
                    "LOOK" -> Jobs.lookText(sJ, t.target)
                    "TALK" -> Jobs.judgeTalk(sJ, t.target,
                        Jobs.workplaceFor(sJ, job))
                }
                Jobs.judgeTalk(sJ, Jobs.bossFor(sJ, job),
                    Jobs.workplaceFor(sJ, job))
                if (Capstones.mask(sJ, "parents") and 0b010 != 0)
                    jLanded = true
            }
            if (!jLanded) engS.onNewDay(sJ)
        }
        check(jLanded,
            "seam: a real shift, worked on its own card, " +
                "lands the job beat at its clock-out")

        // Arc #6's meter × the four deference lists, live:
        // one meeting-due evening, and the Bijou goes dark
        // for the case, the school day quiets for the case,
        // the season finales hold, and the walk home
        // counts the night case-critical — the same lists
        // every older climax defers to.
        val sMeet = engS.newState()
        engS.createPlayer(sMeet, "Deference", DEFAULT_APPEARANCE)
        sMeet.arcRetired = true; sMeet.arc2Retired = true
        sMeet.arc3Retired = true; sMeet.arc4Retired = true
        sMeet.arc5Retired = true
        sMeet.arc6Started = true; sMeet.arc6Chapter = 4
        sMeet.shenaniganId = Mystery6.FINALE6_ID
        sMeet.shenaniganDay = sMeet.todayKey
        for (c in Mystery6.CLUES6.take(Mystery6.MEETING_MIN_CLUES))
            sMeet.mystery6Clues.add(c.id)
        sMeet.timeMin = 19 * 60
        check(Mystery6.meetingDue(sMeet),
            "seam: the meeting stands due on the fabricated evening")
        check(MovieNights.darkReason(sMeet) ==
            MovieNights.DARK_CASE &&
            MovieNights.isDarkTonight(sMeet),
            "seam: the Bijou goes dark for the case — the " +
                "meeting owns the evening like every climax")
        check(School.quietReason(sMeet) == School.QUIET_CASE,
            "seam: the school day quiets for the case")
        check(Finales.climaxPending(sMeet),
            "seam: the season finales hold for the meeting")
        check(Walk.caseCritical(sMeet),
            "seam: the walk home counts the night case-critical")
        check(Emergencies.momentOwned(sMeet) &&
            Rival.talkStepFor(sMeet, Rival.rivalOf(sMeet)) == null,
            "seam: and the moment is owned in the two " +
                "newest ledgers too — no emergency is priced, " +
                "no rivalry speaks, on a meeting night")

        // Rival × a live emergency, in lived time: a
        // rivalry with a challenge standing goes silent
        // while an emergency sits on the plate, and speaks
        // again when the plate clears.
        val engR = Engine(808_414)
        val sRv = engR.newState()
        engR.createPlayer(sRv, "Kid3", DEFAULT_APPEARANCE)
        var rvGuard = 0
        while (!Rival.revealed(sRv) && rvGuard++ < 40) {
            sRv.timeMin = 10 * 60
            val hit = Rival.talkStepFor(sRv, Rival.rivalOf(sRv))
            if (hit != null && hit.kind == "reveal")
                Rival.playReveal(sRv, 1)
            else engR.onNewDay(sRv)
        }
        check(Rival.revealed(sRv),
            "seam: the seam's rivalry crowns for real")
        rvGuard = 0
        var rvOffer: Rival.RivalHit? = null
        while (rvGuard++ < 40) {
            sRv.timeMin = 10 * 60
            val hit = Rival.talkStepFor(sRv, Rival.rivalOf(sRv))
            if (hit != null && hit.kind == "offer") {
                rvOffer = hit; break
            }
            engR.onNewDay(sRv)
        }
        check(rvOffer != null,
            "seam: a challenge stands live on the seam's rivalry")
        if (rvOffer != null) {
            sRv.errands.add(Errand(
                id = "seam-emerg", source = Errands.EMERG,
                asker = "Sheila", type = "FETCH",
                text = "A neighbor in a hurry.",
                hint = "It's around.", itemId = "coffee_beans",
                dayKey = sRv.todayKey, acceptedDay = sRv.absDay,
                emergDeadline = 1300))
            check(Emergencies.liveEmergency(sRv) != null &&
                Rival.talkStepFor(sRv, Rival.rivalOf(sRv)) == null,
                "seam: while the emergency sits on the plate, " +
                    "the rivalry holds its tongue")
            sRv.errands.removeAll { it.id == "seam-emerg" }
            check(Rival.talkStepFor(sRv, Rival.rivalOf(sRv))
                ?.kind == "offer",
                "seam: the plate clear, the challenge speaks again")
        }

        // Wave-4 cast × Crowds at 62: the v0.7.0g matrix,
        // extended to the full town — every headcount the
        // game can now gather, laid out whole, no face in
        // the frieze, the separation floor holding.
        val castNames8 = CharacterSystem.CAST.keys.toList()
        val rivalPairs8 = mutableSetOf<Set<String>>()
        for (a in castNames8) for (b in castNames8)
            if (a < b && relationNote(a, b) == "arch-rivals")
                rivalPairs8.add(setOf(a, b))
        val fullChem8 = Crowds.Chem(
            scriptPairs = PAIR_SCRIPTS.keys
                .filter { it.size == 2 }.toSet(),
            rivalPairs = rivalPairs8,
            factionOf = FACTION_OF_CAST)
        for (total in 55..62) {
            val names = castNames8.take(total)
            val lay = Crowds.layout(names, fullChem8)
            check(lay != null && lay.placed.size == total,
                "seam: a crowd of $total lays out whole")
            if (lay == null) continue
            for (inside in listOf(false, true)) {
                val feet0 = if (inside) Depth.FRONT_FEET_IN
                    else Depth.FRONT_FEET_OUT
                val fgTop = if (inside) Depth.FG_TOP_IN
                    else Depth.FG_TOP_OUT
                var chinOk = true
                for (p in lay.placed) {
                    val feet = feet0 - p.frontness *
                        Depth.FH_BASE_MAX * 0.54f
                    if (Depth.worstChin(feet) >= fgTop) chinOk = false
                }
                check(chinOk,
                    "seam: crowd of $total " +
                        (if (inside) "indoors" else "outdoors") +
                        " — no clustered row pushes a face into " +
                        "the frieze")
            }
            var sepOk = true
            for ((_, row) in lay.placed.groupBy { it.frontness }) {
                val byX = row.sortedBy { it.xFrac }
                for (i in 1 until byX.size)
                    if (byX[i].xFrac - byX[i - 1].xFrac <
                        Crowds.MIN_SEP - 0.0001f) sepOk = false
            }
            check(sepOk,
                "seam: crowd of $total — the MIN_SEP floor " +
                    "holds at maximum realistic density")
        }

        // Bee fields at 30 kids: the pure bracket over a
        // long run of Fridays — a full field of eight,
        // drawn only from the class, a champion crowned
        // every single week, and the whole class (wave-4
        // kids included) rotating through the field.
        var beeFridays = 0
        var beeChampions = 0
        val beeSeen = mutableSetOf<String>()
        for (day in 0..1500) {
            if (!School.isBeeDay(day)) continue
            beeFridays++
            val b = School.beeBracket(day)
            check(b.field.size == School.FIELD_SIZE &&
                b.field.distinct().size == b.field.size &&
                b.field.all { it in CharacterSystem.CAST_KIDS } &&
                b.champion != null,
                "seam: Friday $day's bee fields eight of the " +
                    "class and crowns one of them")
            beeSeen += b.field
            if (b.champion != null) beeChampions++
        }
        check(beeFridays >= 200 && beeChampions == beeFridays,
            "seam: across $beeFridays Fridays at thirty " +
                "kids, the bee never once crowns nobody")
        check(beeSeen == CharacterSystem.CAST_KIDS,
            "seam: the whole thirty-kid class rotates " +
                "through the bee field — the wave-4 spellers " +
                "included (saw ${beeSeen.size})")

        // Dinner reseats, lived: the Marsh table seats
        // Shelley and the Broflovski table seats Ike —
        // and at the table, welcomed, each of them has
        // their table talk standing, the way any member does.
        fun dinnerState(houseId: String): GameState? {
            // the v0.7.0g fabrication grid, which provably
            // reaches every household's anchored day
            for (y in 2027..2040) for (ad in 999..1400 step 7) {
                val cand = engS.newState()
                engS.createPlayer(cand, "Guest", DEFAULT_APPEARANCE)
                cand.gameYear = y
                cand.gameMonth = 1 + (ad / 31) % 12
                cand.gameDay = 1 + ad % 28
                cand.todayKey = "%04d%02d%02d".format(
                    cand.gameYear, cand.gameMonth, cand.gameDay)
                cand.absDay = 999 + (ordinalOfKey(cand.todayKey) -
                    ordinalOfKey("20270101"))
                Dinners.dailyRollover(cand)
                if (Dinners.todaysInvite(cand)?.id == houseId)
                    return cand
            }
            return null
        }
        val sMarsh = dinnerState("marsh")
        check(sMarsh != null &&
            Dinners.todaysInvite(sMarsh!!)!!.members
                .contains("Shelley"),
            "seam: a Marsh invite day exists and the table " +
                "seats Shelley")
        if (sMarsh != null) {
            sMarsh.timeMin = 17 * 60 + 45
            Dinners.judgeTalk(sMarsh, "Sharon")
            check(Dinners.talkStepFor(sMarsh, "Shelley") != null,
                "seam: welcomed at her own family's table, " +
                    "Shelley's table talk stands")
        }
        val sBrof = dinnerState("broflovski")
        check(sBrof != null &&
            Dinners.todaysInvite(sBrof!!)!!.members
                .contains("Ike"),
            "seam: a Broflovski invite day exists and the " +
                "table seats Ike")
        if (sBrof != null) {
            sBrof.timeMin = 17 * 60 + 45
            Dinners.judgeTalk(sBrof, "Sheila")
            check(Dinners.talkStepFor(sBrof, "Ike") != null,
                "seam: welcomed at his own family's table, " +
                    "Ike's table talk stands")
        }
    }

    run {
        // ---------- the peak budget, seventh distance ----------
        // The same pins as v0.4.0e, on today's render set,
        // and the census counted honestly at 62 cast:
        // Queue #8 shipped five systems and not one new
        // audio family — but the bark table grew with the
        // cast again, eight new rhythm signatures for
        // eight new townsfolk, all of them distinct.
        val pb = SoundGen.PeakBudget
        println("budget v0.8.0g: named ${pb.namedStack()}, " +
            "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
            "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
            "amb ${pb.ambiencePeakOut()}, bark signatures " +
            "${Barks.PATTERNS.size} (" +
            "${Barks.PATTERNS.values.distinct().size} distinct)")
        check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
            "budget: the named stack has not drifted since v0.4.0e " +
                "(got ${pb.namedStack()})")
        check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
            "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
        check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
            "budget: the bark stack has not drifted (got ${pb.barkStack()})")
        check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
            pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
            "budget: neither barks nor mood contours out-peak the plain blip")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val post = AudioSettings.DEFAULT.gain(
                AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
                pb.peakOf(SoundGen.renderAmbience(bed))
            check(post <= pb.ambiencePeakOut() + 0.002f,
                "budget: bed $bed stays inside the ambience allocation")
        }
        check(SoundGen.SFX_IDS.size == 21 &&
            SoundGen.BlipFam.values().size == 7 &&
            SoundGen.BlipMood.values().size == 4 &&
            SoundGen.AmbBed.values().size == 6,
            "budget: the family census is unchanged — 21 named " +
                "effects, 7 blip families, 4 moods, 6 ambience " +
                "beds. Queue #8 added no audio family (got " +
                "${SoundGen.SFX_IDS.size}/${SoundGen.BlipFam.values().size}/" +
                "${SoundGen.BlipMood.values().size}/${SoundGen.AmbBed.values().size})")
        check(Barks.PATTERNS.size == CharacterSystem.CAST.size &&
            Barks.PATTERNS.keys == CharacterSystem.CAST.keys &&
            Barks.PATTERNS.values.distinct().size ==
            Barks.PATTERNS.size,
            "budget: the bark census at 62 — one rhythm " +
                "signature per cast member, all 62 distinct, " +
                "the eight newcomers included (got " +
                "${Barks.PATTERNS.size}, " +
                "${Barks.PATTERNS.values.distinct().size} distinct)")
    }

    run {
        // ---------- the tuning ledger, swept for Queue #8 ----------
        // Every paper-tuned Queue #8 constant, named in
        // the ledger section itself — scoped to the
        // section, so a dial that only ever made a
        // changelog doesn't count. The sweep found one gap
        // this pass, closed in the README as documentation:
        // the capstone entry always named the coin ladder
        // (BEAT_COINS) but spoke of the fourth dial — the
        // +4 friendship each beat pays — only in prose; it
        // now names BEAT_FRIENDSHIP beside its siblings.
        val tuning = File(root, "docs/TUNING.md").readText()
        val ledgerStart = tuning.indexOf("## Tuning ledger")
        val ledgerEnd = tuning.length
        check(ledgerStart >= 0 && ledgerEnd > ledgerStart,
            "ledger: the ledger section stands ahead of the changelog")
        val ledger = tuning.substring(ledgerStart, ledgerEnd)
        val q8Dials = listOf(
            // faction capstones (v0.8.0b)
            "CAPSTONE_MIN_STANDING", "BEAT_COINS",
            "BEAT_FRIENDSHIP", "CEREMONY_FROM", "CEREMONY_TO",
            // errand emergencies (v0.8.0c)
            "EMERG_CHANCE", "WORK_MIN_PER_STOP", "SLACK_MIN",
            "RESCUE_FRIENDSHIP_BONUS", "RESCUE_COIN_BONUS",
            // the town yearbook (v0.8.0d)
            "STAR_BONUS", "FULL_VOLUMES", "THIN_COUNT",
            "ARGUMENT_DAYS",
            // the rival (v0.8.0e)
            "REVEAL_FROM", "REVEAL_SPREAD", "FIRST_CHALLENGE_GAP",
            "CHALLENGE_GAP_MIN", "CHALLENGE_GAP_SPREAD",
            "DECLINE_GAP", "PENDING_LAPSE_DAYS",
            "PRANK_FIRST_DELAY", "PRANK_GAP_MIN",
            "PRANK_GAP_SPREAD", "PRANK_EXPIRE_DAYS",
            "PRANK_CHANCE", "FRESH_DAYS", "LOCK_AT", "LOG_CAP",
            "RACE_MIN_ROUTE",
            // the sixth case (v0.8.0f)
            "MEETING_MIN_CLUES", "METER_BASE", "VOICE_BACK",
            "VOICE_QUESTION", "VOICE_SILENT", "BACK_BOOST",
            "SPEAK_RELIEF", "VERDICT_CONVICT_AT",
            "VERDICT_HUNG_AT", "WALL_RETURN_DELAY_DAYS",
            "CONVICT_SCAR")
        for (dial in q8Dials)
            check(dial in ledger,
                "ledger: the Queue #8 dial $dial is named in " +
                    "the tuning ledger")
        check(Capstones.CAPSTONE_MIN_STANDING == 60 &&
            Capstones.BEAT_COINS == listOf(3, 4, 6) &&
            Capstones.BEAT_FRIENDSHIP == 4 &&
            Emergencies.EMERG_CHANCE == 0.40 &&
            Emergencies.WORK_MIN_PER_STOP == 10 &&
            Emergencies.SLACK_MIN == 20 &&
            Yearbook.STAR_BONUS == 15 &&
            Yearbook.FULL_VOLUMES == 3 &&
            Yearbook.THIN_COUNT == 6 &&
            Yearbook.ARGUMENT_DAYS == 4 &&
            Rival.LOCK_AT == 10 && Rival.LOG_CAP == 24 &&
            Rival.RACE_MIN_ROUTE == 10 &&
            Mystery6.MEETING_MIN_CLUES == 6 &&
            Mystery6.METER_BASE == 45 &&
            Mystery6.VERDICT_CONVICT_AT == 45 &&
            Mystery6.VERDICT_HUNG_AT == 15 &&
            Mystery6.WALL_RETURN_DELAY_DAYS == 7 &&
            Mystery6.CONVICT_SCAR == 6,
            "ledger: the Queue #8 dials stand at the values " +
                "the ledger prints")
    }

    // ---------- the release pin ----------
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 67 / 0.9.0a")
}



// ================= v0.9.0a: Cast Wave 5 =================
// Queue #9 item 1, opening the v0.9.0 series. Eight more
// named townsfolk (cast 62 -> 70: 32 kids, 38 adults) picked
// from evidence: Roger completes the Donovans, Ryan + Sarah
// the Valmers, Alexis + Mr. Testaburger the Testaburgers —
// the last households standing one or two members short.
// Nathan (the comedy duo's born nemesis, the richest kid
// entry left in the book) and Sophie (the new girl, Scott's
// fellow diplomat) join the kids; Big Gay Al, the town's
// superest citizen, joins the grown-ups. Terrance & Phillip
// were re-evaluated a third time and passed over a third
// time — pinned below: the lorebook holds ONE joint entry
// for the pair and no standalone entry for either man.
private fun sectionV090a(root: String) {
    println("== v0.9.0a: cast expansion wave 5 ==")
    val wave5 = listOf("Roger", "Ryan", "Sarah", "Alexis",
        "Mr. Testaburger", "Nathan", "Sophie", "Big Gay Al")
    val wave5Kids = listOf("Nathan", "Sophie")
    val wave5Adults = listOf("Roger", "Ryan", "Sarah", "Alexis",
        "Mr. Testaburger", "Big Gay Al")

    // ---------- the roster arithmetic ----------
    check(WAVE5_ORDER == wave5, "wave5: the wave roster is the pinned eight")
    check(KID_ORDER.size == 98 && KID_ORDER.distinct().size == 98,
        "wave5: KID_ORDER carries 98 distinct names")
    check(AGENT_PROFILES.size == 98, "wave5: 98 agent profiles")
    check(KID_HOUSE.size == 98, "wave5: 98 homes")
    check(CharacterSystem.CAST_KIDS.size + CharacterSystem.CAST_ADULTS.size == 98 &&
        (CharacterSystem.CAST_KIDS intersect CharacterSystem.CAST_ADULTS).isEmpty(),
        "wave5: 42 kids + 56 adults, disjoint")
    check(CharacterSystem.CAST_KIDS.size == 42 &&
        CharacterSystem.CAST_ADULTS.size == 56,
        "wave5: the split is 42 kids / 56 adults")
    check(wave5Kids.all { it in CharacterSystem.CAST_KIDS } &&
        wave5Adults.all { it in CharacterSystem.CAST_ADULTS },
        "wave5: the age split matches the wave roster")
    check(CharacterSystem.CAST.keys == AGENT_PROFILES.keys,
        "wave5: CAST and AGENT_PROFILES describe the same 98")
    // the visitor pool regenerates from the alias table: all
    // eight lore names are excluded from it by construction
    val w5LoreNames = wave5.map { LORE_CHAR_ALIASES.getValue(it) }.toSet()
    check(VisitorSystem.eligible().none { it.name in w5LoreNames || it.name in wave5 },
        "wave5: the visitor pool excludes all eight newcomers")
    check(wave5.all { CharacterSystem.CAST_BANDS[it] != null } &&
        wave5Kids.all { CharacterSystem.CAST_BANDS[it] == AgeBand.KID } &&
        wave5Adults.all { CharacterSystem.CAST_BANDS[it] == AgeBand.ADULT },
        "wave5: age bands land KID for the kids, ADULT for the grown-ups")

    // ---------- every newcomer is a full citizen ----------
    for (n in wave5) {
        check(n in AGENT_PROFILES, "wave5: $n has a profile")
        check(n in KidArt.SHEETS, "wave5: $n has a sheet spec")
        check(n in LINE_BANKS && n in DAILY_TOPICS && n in SPEECH_RULES,
            "wave5: $n has banks, topics, and a voice card")
        check(n in FRIEND_GREETINGS && n in RESPONSE_BANKS && n in SLEEPY_LINES,
            "wave5: $n has greetings, responses, and sleepy lines")
        check(n in SoundGen.BLIP_FAMILIES, "wave5: $n has a voice blip family")
        check(n in LORE_CHAR_ALIASES, "wave5: $n has a lore alias")
        check(LoreBook.charLore(n) != null, "wave5: $n resolves lorebook entries")
        check(factionOfCast(n) != null, "wave5: $n holds exactly one faction")
    }
    // the writing floors at seventy: 9 collision lines and
    // 18 daily topics for every citizen of the town
    check(LINE_BANKS.values.sumOf { it.size } >= 98 * 9 &&
        wave5.all { (LINE_BANKS[it]?.size ?: 0) >= 9 },
        "wave5: collision lines hold the 9-per-citizen floor at 98")
    check(wave5.all { (DAILY_TOPICS[it]?.size ?: 0) >= 18 },
        "wave5: every newcomer carries the full 18 daily topics")

    // ---------- homes: the constellation anchors ----------
    check(KID_HOUSE["Roger"] == "MainStreet" && KID_HOUSE["Ryan"] == "CityHall" &&
        KID_HOUSE["Sarah"] == "MainStreet" && KID_HOUSE["Alexis"] == "CityHall" &&
        KID_HOUSE["Mr. Testaburger"] == "MainStreet" &&
        KID_HOUSE["Nathan"] == "Elementary" && KID_HOUSE["Sophie"] == "Elementary" &&
        KID_HOUSE["Big Gay Al"] == "MainStreet",
        "wave5: homes anchor the families and the workplaces")

    // ---------- schedules: seven real blocks, workplaces held ----------
    val wave5Blocks = setOf("08:00", "09:00", "12:00", "15:00", "16:30", "18:00", "21:00")
    for (n in wave5) {
        val p = AGENT_PROFILES.getValue(n)
        check(p.agenda.keys == wave5Blocks, "wave5: $n keeps the 7-block day")
        check(p.agenda.values.all { it.location in LOCATIONS },
            "wave5: $n is scheduled at real locations only")
        check(p.description.length > 200,
            "wave5: $n's description carries full lore (got ${p.description.length})")
    }
    check(AGENT_PROFILES.getValue("Alexis").agenda.values.count { it.location == "CityHall" } >= 4,
        "wave5: the city planner holds City Hall like Lu Kim holds the wok")
    check(AGENT_PROFILES.getValue("Ryan").agenda.values.count { it.location == "CityHall" } >= 3,
        "wave5: the fire chief keeps his station hours at City Hall")
    check(AGENT_PROFILES.getValue("Nathan").agenda.values.count { it.location == "Elementary" } >= 4 &&
        AGENT_PROFILES.getValue("Sophie").agenda.values.count { it.location == "Elementary" } >= 3,
        "wave5: the school kids hold school hours")

    // ---------- factions ----------
    check(FACTION_OF_CAST.size == 98, "wave5: every cast member holds exactly one faction")
    check(FACTION_OF_CAST["Roger"] == "parents" && FACTION_OF_CAST["Ryan"] == "parents" &&
        FACTION_OF_CAST["Sarah"] == "parents" && FACTION_OF_CAST["Alexis"] == "parents" &&
        FACTION_OF_CAST["Mr. Testaburger"] == "parents" &&
        FACTION_OF_CAST["Big Gay Al"] == "parents" &&
        FACTION_OF_CAST["Sophie"] == "girls_circle" &&
        FACTION_OF_CAST["Nathan"] == "craigs_gang",
        "wave5: one faction each, the natural one — the parents gain the " +
            "last parents, the circle gains the new girl, the gang gains " +
            "its nemesis-in-residence")

    // ---------- the measured figure still rules ----------
    val w5Specs = wave5.associateWith { KidArt.SHEETS.getValue(it) }
    for (n in wave5Kids) {
        val spec = w5Specs.getValue(n)
        val tol = 0.011f
        check(!spec.tall && spec.measured != null &&
            spec.measured!!.headShare in 0.60f..(0.66f + tol),
            "wave5: $n is a measured kid, head in band")
    }
    for (n in wave5Adults) {
        val spec = w5Specs.getValue(n)
        val m = spec.measured!!
        check(spec.tall && m.headShare in 0.33f..0.37f &&
            m.legShare >= m.torsoShare - 0.011f,
            "wave5: $n is a measured adult: head ~1/3, legs >= torso")
    }
    val w5Shapes = w5Specs.values.map { s ->
        val m = s.measured!!
        Triple(m.headShare, m.heightRel, s.width)
    }
    check(w5Shapes.distinct().size == 8, "wave5: no two newcomers share a silhouette")
    // signatures: the chief's mustache, the quiet dad's
    // glasses, the new girl's freckles, the schemer's smug,
    // Al's scarf and grin
    check(w5Specs.getValue("Ryan").mustache,
        "wave5: Ryan wears the chief's mustache")
    check(w5Specs.getValue("Mr. Testaburger").glasses,
        "wave5: Mr. Testaburger wears the glasses")
    check(w5Specs.getValue("Sophie").freckles &&
        w5Specs.getValue("Sophie").hairStyle == "long",
        "wave5: Sophie wears the freckles and the Scottsdale length")
    check(w5Specs.getValue("Nathan").face == "smug",
        "wave5: Nathan's resting face is the scheme, mid-hatch")
    check(w5Specs.getValue("Big Gay Al").scarfHex != null &&
        w5Specs.getValue("Big Gay Al").face == "grin",
        "wave5: Big Gay Al wears the scarf and the grin")

    // ---------- showdown dodge ----------
    check(Showdown.dodgeFor("Nathan") in 0.05f..0.45f &&
        Showdown.dodgeFor("Sophie") in 0.05f..0.45f,
        "wave5: every newcomer kid has a sane dodge chance")
    check(Showdown.dodgeFor("Nathan") > Showdown.dodgeFor("Sophie"),
        "wave5: the schemer is harder to hit than the new girl — " +
            "he planned where the snowball lands")

    // ---------- the Friday bee takes their measure ----------
    check(School.skillOf("Nathan") == 7 && School.skillOf("Sophie") == 6,
        "wave5: bee skills — the threat and the careful newcomer")

    // ---------- the rival pool gains its born nemesis ----------
    check(Rival.POOL.size == 9 && Rival.defOf("Nathan") != null,
        "wave5: the rival pool held eight, and Nathan is in it " +
            "(Terrance Mephesto appended ninth at wave 6, v0.11.0d)")
    check(Rival.defOf("Nathan")!!.paceHalf % 2 != 0,
        "wave5: Nathan's authored pace is odd — the race stays tie-proof")
    check(Rival.POOL.take(7).map { it.name } ==
        listOf("Cartman", "Kyle", "Wendy", "Craig", "Clyde", "Bebe", "Tweek"),
        "wave5: the authored seven keep their seats and their order " +
            "(recorded crowns in old saves are untouched by the new row)")

    // ---------- the phone cap grows with the town ----------
    check(Phone.MAX_TEXTS == 220 && Phone.MAX_TEXTS > KID_ORDER.size * 2 &&
        Phone.MAX_TEXTS % Phone.MAX_PER_THREAD == 0,
        "wave5: the inbox cap cleared a full-cast inbox at 70; v0.11.0d " +
            "wave 6 FORCED the dial (the worst case is 103 threads x 2 = " +
            "206) — 220 keeps the headroom and the thread arithmetic")

    // ---------- the Bijou's never list stays honest ----------
    check(MovieNights.NEVER_ATTENDS == setOf("Towelie", "Crabtree") &&
        wave5.none { it in MovieNights.NEVER_ATTENDS },
        "wave5: no newcomer belongs on the never-attends list — all " +
            "eight are ordinary townsfolk, and the star filter still " +
            "honors the list on both casting paths")

    // ---------- relations: every scripted pair is related ----------
    for (pair in WAVE5_PAIR_SCRIPTS.keys) {
        check(relationNote(pair.first(), pair.last()) != null,
            "wave5: relation note for ${pair.joinToString("/")}")
    }
    check(relationNote("Roger", "Clyde")?.contains("lemon") == true,
        "wave5: the Donovan note knows the lemon bars are scripture")
    check(relationNote("Nathan", "Jimmy")?.contains("confetti") == true,
        "wave5: the nemesis note knows the confetti budget")
    check(relationNote("Alexis", "Wendy")?.contains("hereditary") == true,
        "wave5: the Testaburger note knows the debate is hereditary")
    check(relationNote("Sophie", "Scott")?.contains("treaty") == true,
        "wave5: the diplomats' note knows the snack treaty")

    // ---------- dinners: no new table, honestly ----------
    // The new families have no house on the town map (the
    // Tucker precedent from waves 3-4: parents join at their
    // anchors, and a table needs an address). The seven
    // seated households stand exactly as wave 4 left them.
    check(Dinners.HOUSEHOLDS.size == 7,
        "wave5: the dinner tables stand at seven — no fake addresses")
    check(Dinners.HOUSEHOLDS.first { it.id == "black" }.members ==
        listOf("Tolkien", "Steve", "Linda Black"),
        "wave5: the Black household stood as wave 3 seated it until " +
            "wave 6 seated Linda Black (v0.11.0d) — the one reseat the " +
            "audit's evidence ordered")
    check(wave5.all { Dinners.householdOf(it) == null },
        "wave5: no newcomer is seated at a table that doesn't exist")

    // ---------- Terrance & Phillip: the third verdict ----------
    // Pinned so the next evaluation starts from evidence:
    // the embedded lorebook holds the pair's ONE joint entry
    // and no standalone char entry for either man.
    val lbText = File("$root/assets/lorebook.json").readText()
    check(lbText.contains("\"n\":\"Terrance and Phillip\""),
        "wave5: the lorebook's only Terrance & Phillip entry is the joint one")
    check(!Regex("\"n\":\"(Terrance|Phillip)\"").containsMatchIn(lbText),
        "wave5: neither Terrance nor Phillip holds a standalone entry " +
            "— the duo stays passed over on evidence, not habit")

    // ---------- spawn: a fresh town seats all seventy ----------
    val engW = Engine(909)
    val sW = engW.newState()
    check(wave5.all { it in sW.agents }, "wave5: a new state seats all eight newcomers")
    check(sW.agents.size >= 98, "wave5: the roster spawns at 98+")

    // ---------- the fan sheets carry all seventy ----------
    try {
        val params = File("/home/hatch/workspace/goals/" +
            "south-park-interactive-town/files/sheets/tools/params.json")
            .readText()
        check(KID_ORDER.all { params.contains("\"name\": \"$it\"") },
            "wave5: sheet params contain every one of the 98")
        check(params.split("\"name\":").size - 1 == 98,
            "wave5: sheet params hold exactly 98 characters")
    } catch (e: Exception) {
        check(false, "wave5: sheet params readable (${e.message})")
    }
}

private fun sectionV090b(root: String) {
// ================= v0.9.0b: your crew =================
// Queue #9 item 2. Up to four cast members can be asked
// into the player's crew (Friend tier, in the tap-person
// menu — an in-talk choice, NOT a TalkGate rail), and the
// crew is a standing arrangement: rendezvous priced by
// the Walk graph's own minutes, occupied-is-occupied with
// the regret owed out loud, set pieces pulling members
// away mid-outing, tallies for the shared things, and the
// town noticing. Everything here drives Crew's own verbs
// and the real funnels it hooks.
    println("== v0.9.0b: your crew ==")
    val memSnapshotB = NpcMemoryStore.serialize()
    val readmeB = File(root, "docs/CHANGELOG.md").readText()
    check(readmeB.contains("### v0.9.0b"),
        "crew: the README carries this build's changelog entry")
    val engB = Engine(909_002)
    fun freshB(): GameState {
        val s = engB.newState()
        engB.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    /** The calm calendar (sectionV080e's stage): Feb 2027,
     *  no holiday, no finale week — the day-driven systems
     *  (school, dinners, the bee) still read absDay. */
    fun calmB(s: GameState, absDay: Int, timeMin: Int) {
        s.absDay = absDay
        s.gameYear = 2027; s.gameMonth = 2; s.gameDay = 10
        s.todayKey = "20270210"; s.timeMin = timeMin
        s.holidayId = null
    }
    fun placeB(s: GameState, who: String, loc: String) {
        val a = s.agents[who]!!
        a.location = loc; a.destination = loc; a.waypoints.clear()
    }
    fun placePlayerB(s: GameState, loc: String) {
        val me = engB.player(s)
        me.location = loc; me.destination = loc; me.waypoints.clear()
    }
    val schoolDayB = (1..40).first { School.isSchoolDay(it) }
    val weekendB = (1..40).first { !School.isSchoolDay(it) }
    val beeDayB = (1..60).first { School.isBeeDay(it) }
    fun marshDayB(): Int {
        val marsh = Dinners.defById("marsh")!!
        var d = 1
        while (true) {
            if (Dinners.isDinnerDay(d) &&
                Dinners.HOUSEHOLDS[Dinners.dinnerDaysBefore(d) %
                    Dinners.HOUSEHOLDS.size] == marsh) return d
            d++
        }
    }

    // ---------- the dials & the empty state ----------
    check(Crew.MAX_CREW == 4 && Crew.INVITE_MIN_POINTS == 30 &&
        Relationships.tierOf(30) == Relationships.FRIEND &&
        Relationships.tierOf(29) == Relationships.ACQUAINTANCE,
        "crew: four chairs, and the ask opens exactly at the " +
            "Friend tier (friendship 30) — the town's own line")
    check(TalkGate.Rail.values().none { it.name == "CREW" },
        "crew: inviting added NO TalkGate rail — the eleven-rail " +
            "contention ladder stands untouched; the ask is an " +
            "in-talk choice in the tap-person menu")
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        check(Crew.members(s).isEmpty() && Crew.presentCrew(s).isEmpty(),
            "crew: a pre-0.9.0b save starts crewless")
        val page = Crew.pageLines(s)
        check(page.first() == "👥 YOUR CREW" &&
            page.any { it.contains("No crew yet") } &&
            page.any { it.contains("friendship 30+") },
            "crew: the empty page says how a crew starts")
        check(Crew.inviteBlock(s, "Stan") == "tier" &&
            Crew.menuOption(s, "Stan") == null,
            "crew: a stranger can't be asked, and the menu " +
                "doesn't offer what would only sting")
        check(Crew.notYetLine(s, "Stan").isNotBlank(),
            "crew: the not-yet has words ready")
    }
    run {
        // the day-0 shape: a decoded-empty save has a town
        // but no new kid yet, and advanceTime runs through
        // it (the suite's own salvage test does exactly
        // this) — the crew hook must shrug, not throw
        val day0 = decodeGameState(emptyMap())
        val e0 = Engine()
        repeat(40) { e0.advanceTime(day0) }
        check(day0.timeMin in 0..1439 && Crew.members(day0).isEmpty(),
            "crew: a pre-creation save ticks through " +
                "advanceTime untouched — no player, no crew, no crash")
    }

    // ---------- the invite gate, exactly at the tier ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        s.friendship["Stan"] = 29
        check(Crew.inviteBlock(s, "Stan") == "tier",
            "crew: 29 points is Acquaintance — the ask stays shut")
        s.friendship["Stan"] = 30
        check(Crew.inviteBlock(s, "Stan") == null &&
            Crew.menuOption(s, "Stan") == "🤝 Ask Stan to join your crew",
            "crew: 30 points is Friend — the ask opens")
        val said = Crew.invite(s, "Stan")
        check(said.isNotBlank() && Crew.members(s) == listOf("Stan") &&
            Crew.memberSince(s, "Stan") == weekendB &&
            Crew.inviteBlock(s, "Stan") == "member" &&
            Crew.menuOption(s, "Stan") == "👋 Ask Stan to leave the crew",
            "crew: the invite lands, the since-day stamps, the " +
                "menu flips to the leaving")
        // fill the crew, then the fifth chair doesn't exist
        for (n in listOf("Kyle", "Wendy", "Craig")) {
            s.friendship[n] = 30; Crew.invite(s, n)
        }
        s.friendship["Butters"] = 30
        check(Crew.members(s).size == 4 &&
            Crew.inviteBlock(s, "Butters") == "full" &&
            (Crew.menuOption(s, "Butters") ?: "").contains("full"),
            "crew: four aboard is full — the fifth ask is the " +
                "explanation, not an offer")
        // leaving is free, and re-asking waits for tomorrow
        Crew.leave(s, "Kyle")
        check(Crew.members(s) == listOf("Stan", "Wendy", "Craig") &&
            Crew.inviteBlock(s, "Kyle") == "leftToday" &&
            (Crew.menuOption(s, "Kyle") ?: "").contains("left the crew today"),
            "crew: leaving frees the chair at once, but the " +
                "re-ask waits for tomorrow — stated on the label")
        s.absDay += 1
        check(Crew.inviteBlock(s, "Kyle") == null,
            "crew: tomorrow, the ask is live again")
    }

    // ---------- the rival can be asked; the rivalry runs on ----------
    run {
        var s = freshB()
        var guard = 0
        while (Rival.pickFor(s) != "Cartman" && guard < 800) {
            guard++
            s = engB.newState()
            engB.createPlayer(s, "Crewmate$guard", DEFAULT_APPEARANCE)
        }
        check(Rival.pickFor(s) == "Cartman",
            "crew: (fabrication) this save's rival is Cartman")
        calmB(s, weekendB, 10 * 60)
        Rival.playReveal(s, 1)
        s.friendship["Cartman"] = 30
        check(Crew.inviteBlock(s, "Cartman") == null,
            "crew: the rival is askable like anyone — a frenemy " +
                "in the crew is a feature")
        val said = Crew.invite(s, "Cartman")
        check(said.contains("scoreboard") &&
            Crew.isMember(s, "Cartman"),
            "crew: the rival joins with the scoreboard explicitly " +
                "unchanged — their acceptance says so")
        s.life["rivalNextDay"] = s.absDay
        check(Rival.challengeLive(s),
            "crew: with the rival IN the crew, their challenges " +
                "still come due — membership touches nothing of theirs")
    }

    // ---------- rendezvous: the Walk graph prices the trip ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        s.friendship["Stan"] = 30; Crew.invite(s, "Stan")
        // a genuinely cross-town leg, found by the graph itself
        val candidates = listOf("CityWok" to "TegridyFarms",
            "TegridyFarms" to "CityWok", "Bijou" to "TegridyFarms",
            "CityWok" to "KidsPark", "Elementary" to "TegridyFarms")
        val (fromLoc, toLoc) = candidates.first { (a, b) ->
            Walk.routeMinutes(s, a, b) in 20..120 }
        val expected = Walk.routeMinutes(s, fromLoc, toLoc)
        placeB(s, "Stan", fromLoc); placePlayerB(s, toLoc)
        val callAbsMin = s.absDay * 1440 + s.timeMin
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "go" &&
            (s.life["crew:arr:Stan"] ?: -1) - callAbsMin == expected &&
            expected == Walk.routeMinutes(s, fromLoc, toLoc),
            "crew: the trip is priced by the Walk graph itself — " +
                "arrival = the call + routeMinutes($fromLoc → " +
                "$toLoc) = $expected, recomputed, not asserted")
        check(s.agents["Stan"]!!.location == fromLoc &&
            Crew.presentCrew(s).isEmpty(),
            "crew: en route is en route — not present yet, " +
                "and never teleported")
        s.timeMin += expected - 15
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "go" &&
            Crew.presentCrew(s).isEmpty(),
            "crew: a quarter-hour early is still early")
        s.timeMin += 15
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "with" &&
            s.agents["Stan"]!!.location == toLoc &&
            Crew.presentCrew(s) == listOf("Stan"),
            "crew: on the honest minute, they arrive — placed " +
                "where you stand, outing open")
        check(Crew.outings(s, "Stan") == 1 &&
            Crew.placesTogether(s, "Stan") == 1 &&
            (s.friendship["Stan"] ?: 0) == 31,
            "crew: the outing counts, the place counts, and " +
                "the rendezvous pays +1 — the lesson rate")
        // you move; they re-depart from the shared spot
        val nextLoc = if (toLoc == "KidsPark") "StarksPond" else "KidsPark"
        val rm2 = Walk.routeMinutes(s, toLoc, nextLoc)
        placePlayerB(s, nextLoc)
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "go" &&
            s.lifeText["crew:from:Stan"] == toLoc &&
            (s.life["crew:arr:Stan"] ?: -1) ==
                (s.absDay * 1440 + s.timeMin) + rm2,
            "crew: following is just another honest leg — from " +
                "the spot you shared, at the graph's price")
        s.timeMin += rm2 + 15
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "with" &&
            Crew.outings(s, "Stan") == 2 &&
            Crew.placesTogether(s, "Stan") == 2 &&
            (s.friendship["Stan"] ?: 0) == 31,
            "crew: second outing, second place — and the " +
                "friendship pays once a day, never per arrival")
        // going home disperses the outing, not the crew
        placePlayerB(s, YOUR_HOUSE)
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "" &&
            Crew.isMember(s, "Stan"),
            "crew: home disperses the outing; membership stays")
    }

    // ---------- zero-minute rendezvous & the midnight dispersal ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        s.friendship["Kyle"] = 30; Crew.invite(s, "Kyle")
        placeB(s, "Kyle", "StarksPond"); placePlayerB(s, "StarksPond")
        Crew.tick(s)
        check(Crew.modeOf(s, "Kyle") == "with" &&
            Crew.outings(s, "Kyle") == 1,
            "crew: already standing here is a zero-minute trip — " +
                "the outing starts on the first tick")
        Crew.dailyRollover(s)
        check(Crew.modeOf(s, "Kyle") == "" &&
            Crew.isMember(s, "Kyle") && Crew.outings(s, "Kyle") == 1,
            "crew: midnight disperses the standing arrangement " +
                "and keeps the membership and the record")
    }

    // ---------- occupied is occupied, said out loud ----------
    run {
        // school: a kid in class hours, off their own agenda
        val s = freshB(); calmB(s, schoolDayB, 10 * 60)
        check(School.quietReason(s) == null,
            "crew: (fabrication) school genuinely runs today")
        s.friendship["Stan"] = 30; Crew.invite(s, "Stan")
        placeB(s, "Stan", "MainStreet"); placePlayerB(s, "StarksPond")
        check(Crew.busyReason(s, "Stan") == "school",
            "crew: at 10 AM on a school day, a kid is in class " +
                "— their agenda says Elementary, so the crew hears it")
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "" &&
            TalkGate.owedLines(s, "Stan")
                .any { it.text.contains("school had me") } &&
            Crew.owedLine(s, "Stan") == null,
            "crew: the regret is OWED — it plays once, in Talk, " +
                "before the small talk, and never twice")
        val teacher = School.teacherFor(schoolDayB)
        check(engB.currentAgendaBlock(s.agents[teacher]!!, 10 * 60)
            ?.location != "Elementary" ||
            Crew.busyReason(s, teacher) == "school",
            "crew: the day's teacher is held by the same rule " +
                "when their class has them")
        // asleep is asleep
        val s2 = freshB(); calmB(s2, weekendB, 23 * 60)
        check(Crew.busyReason(s2, "Stan") == "asleep",
            "crew: at 11 PM the answer is sleep, for everyone")
        // the claims loop never crashes and only speaks its keys
        val known = setOf("asleep", "school", "dinner", "work",
            "movie", "ceremony", "finale", "event", "emergency", "gone")
        val s3 = freshB(); calmB(s3, weekendB, 10 * 60)
        check(KID_ORDER.all { Crew.busyReason(s3, it) in known + null },
            "crew: busyReason sweeps all 70 townsfolk cleanly — " +
                "every gathering claim consulted, no exceptions")
    }

    // ---------- a set piece pulls a member away, out loud ----------
    run {
        val s = freshB()
        s.absDay = marshDayB()
        s.gameYear = 2027; s.gameMonth = 2; s.gameDay = 10
        s.todayKey = "20270210"; s.holidayId = null
        Dinners.dailyRollover(s)
        s.timeMin = 17 * 60
        s.friendship["Stan"] = 30; Crew.invite(s, "Stan")
        placeB(s, "Stan", "StarksPond"); placePlayerB(s, "StarksPond")
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "with",
            "crew: (fabrication) Stan is out with the crew " +
                "before the dinner window")
        s.timeMin = 18 * 60
        check(Dinners.gatheringBlock(s, "Stan", 18 * 60) != null &&
            Crew.busyReason(s, "Stan") == "dinner",
            "crew: (fabrication) the Marsh table claims Stan " +
                "at 6 PM, through Dinners' own gathering")
        check(Crew.gatheringBlock(s, "Stan", 18 * 60) == null &&
            engB.effectiveAgendaBlock(s, s.agents["Stan"]!!, 18 * 60)
                ?.location == Dinners.defById("marsh")!!.house,
            "crew: the crew's agenda hook yields — the engine " +
                "sends Stan home to dinner, not to the crew")
        Crew.tick(s)
        check(Crew.modeOf(s, "Stan") == "" &&
            TalkGate.owedLines(s, "Stan")
                .any { it.text.contains("Family dinner") },
            "crew: the pull-away is SAID — a regret owed in " +
                "Talk, not a silent disappearance")
        // and the stack order is pinned in source: the crew
        // hook sits below every gathering claim it defers to
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engSrc.indexOf("Crew.gatheringBlock") >
            engSrc.indexOf("Finales.gatheringBlock") &&
            engSrc.indexOf("Finales.gatheringBlock") >
            engSrc.indexOf("Capstones.gatheringBlock"),
            "crew: in Engine's agenda stack the crew hook is " +
                "LAST — dinners, jobs, screenings, ceremonies " +
                "and finales all take the person first")
    }

    // ---------- the town's big moments gate new calls ----------
    run {
        val s = freshB(); calmB(s, beeDayB, 14 * 60)
        check(Emergencies.momentOwned(s),
            "crew: (fabrication) bee hours own the town " +
                "(School's Friday window, via momentOwned)")
        s.friendship["Randy"] = 30; Crew.invite(s, "Randy")
        placeB(s, "Randy", "MainStreet"); placePlayerB(s, "StarksPond")
        Crew.tick(s)
        check(Crew.modeOf(s, "Randy") == "" &&
            s.lifeText["crewRegret:Randy"] == "town",
            "crew: while a bigger moment owns the town, no new " +
                "rendezvous starts — the regret says the town " +
                "had a thing")
    }

    // ---------- the shared things count ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        // Kyle is this save's rival — witness the witness path
        // through Rival's own central settle
        var guard = 0
        var s2 = freshB()
        while (Rival.pickFor(s2) != "Kyle" && guard < 800) {
            guard++
            s2 = engB.newState()
            engB.createPlayer(s2, "Witness$guard", DEFAULT_APPEARANCE)
        }
        calmB(s2, weekendB, 10 * 60)
        Rival.playReveal(s2, 1)
        s2.friendship["Kyle"] = 30; Crew.invite(s2, "Kyle")
        placeB(s2, "Kyle", "StarksPond"); placePlayerB(s2, "StarksPond")
        Crew.tick(s2)
        check(Crew.presentCrew(s2) == listOf("Kyle"),
            "crew: (fabrication) Kyle stands with you at the pond")
        // a photo with Kyle in frame tallies; one without doesn't
        Photos.applyPhoto(s2, PhotoRecord(
            id = "crewpic1", dayKey = "20270210", dateLabel = "2/10",
            timeMin = 600, locId = "StarksPond", inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Walker", "player", "happy"),
                PhotoFigure("Kyle", "cast", "happy")),
            caption = "crew at the pond", seed = 7L))
        check(Crew.photosTogether(s2, "Kyle") == 1,
            "crew: a photo with a standing member in frame is " +
                "a photo together (the frame's chemistry stayed " +
                "Photos' own — this only counts)")
        Photos.applyPhoto(s2, PhotoRecord(
            id = "crewpic2", dayKey = "20270210", dateLabel = "2/10",
            timeMin = 615, locId = "StarksPond", inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("Walker", "player", "happy")),
            caption = "just me", seed = 8L))
        check(Crew.photosTogether(s2, "Kyle") == 1,
            "crew: a frame without them doesn't count for them")
        // showdowns and rival contests witnessed
        Crew.onShowdown(s2)
        check(Crew.witnessed(s2, "Kyle") == 1,
            "crew: a showdown settled in front of them is witnessed")
        Rival.recordResult(s2, Rival.K_SHOWDOWN, "you", "suite check")
        check(Crew.witnessed(s2, "Kyle") == 2 &&
            Crew.contestsWitnessed(s2) == 1 &&
            Rival.pageLines(s2).any {
                it.contains("Your crew has stood and watched") },
            "crew: a rival contest settled before the crew lands " +
                "on their tallies — and the RIVAL page quotes it")
    }

    // ---------- cluster math: the crew stands together ----------
    run {
        val crew4 = setOf("Stan", "Kyle", "Wendy", "Craig")
        val chem = Crowds.Chem(crew = crew4)
        check(Crowds.affinity("Stan", "Kyle", chem) ==
            Crowds.CREW_AFFINITY &&
            Crowds.affinity("Stan", "Kyle",
                Crowds.Chem(crew = crew4,
                    rivalPairs = setOf(setOf("Stan", "Kyle")))) > 0 &&
            Crowds.affinity("Stan", "Kyle",
                Crowds.Chem(rivalPairs = setOf(setOf("Stan", "Kyle")))) ==
                Crowds.RIVAL_BLOCK,
            "crew: the standing pull is real (40, under a pair " +
                "script's 50) and outranks even an arch-rival " +
                "block between two of its own")
        // 17 present at one place: the crew + a crossing crowd
        val others = (KID_ORDER - crew4).take(13)
        val layout = Crowds.layout((crew4 + others).sorted(),
            Crowds.Chem(crew = crew4))
        check(layout != null, "crew: (fabrication) 17 present cluster")
        val placed = layout!!.placed
        val crewPlaced = placed.filter { it.name in crew4 }
        check(crewPlaced.map { it.clusterId }.distinct().size == 1 &&
            crewPlaced.first().clusterId >= 0 &&
            placed.count { it.clusterId == crewPlaced.first().clusterId } == 4,
            "crew: the four stand as ONE cluster of four inside " +
                "a 17-person crowd")
        val rowsOk = placed.groupBy { it.frontness }.values.all { row ->
            val xs = row.map { it.xFrac }.sorted()
            xs.zipWithNext().all { (a, b) -> b - a >= Crowds.MIN_SEP - 0.001f } &&
                (xs.last() - xs.first()) <= 0.94f + 0.001f
        }
        check(rowsOk && layout.rows <= Crowds.rowsFor(17),
            "crew: MIN_SEP and the row span survive the crew " +
                "cluster — nobody stands on anybody")
        // the full-cast stress: 24 present, crew inside
        val big = Crowds.layout((crew4 + (KID_ORDER - crew4).take(20)).sorted(),
            Crowds.Chem(crew = crew4))
        check(big != null && big.placed.filter { it.name in crew4 }
            .map { it.clusterId }.distinct().size == 1,
            "crew: at 24 present the crew still reads as one group")
    }

    // ---------- the town notices ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        // three of a faction, found from the cast data itself
        val byFaction = KID_ORDER.groupBy { factionOfCast(it) }
        val trio = byFaction.entries.first { (f, names) ->
            f != null && names.size >= 4 }.value.take(3)
        val fourth = (KID_ORDER - trio).first {
            factionOfCast(it) != factionOfCast(trio[0]) }
        for (n in trio + fourth) {
            s.friendship[n] = 30; Crew.invite(s, n)
        }
        check(Crew.majorityFaction(s) == factionOfCast(trio[0]),
            "crew: three of a faction is the crew's color")
        val speaker = (KID_ORDER - Crew.members(s)).first {
            factionOfCast(it) == factionOfCast(trio[0]) }
        val line = Crew.talkLines(s, speaker)
        val fname = FACTIONS.first {
            it.id == factionOfCast(trio[0]) }.name
        check(line.size == 1 && line[0].text.contains(fname) &&
            line[0].text.contains("crew"),
            "crew: that faction's people have a line about it — " +
                "informational only, no standing moved")
        check(Crew.talkLines(s, speaker).isEmpty(),
            "crew: and it's stamped — a line once in a while, " +
                "not every tap")
        // the topic: classification + a Threads follow-up bank
        check(NpcMemoryStore.topicOf("your crew was at the pond") ==
            "your crew",
            "crew: talk about the crew files under its own topic")
        val mem = NpcMemoryStore.getOrCreate("Test Kid")
        mem.meets = 3   // follow-ups need real history (2+ meets)
        mem.topics.clear(); mem.topics.add("your crew")
        var follow: String? = null
        for (seed in 1..40) {
            follow = Threads.followUp(mem, Random(seed.toLong()))
            if (follow != null) break
        }
        check(follow != null && follow.contains("your crew"),
            "crew: Threads carries the follow-ups — the town " +
                "keeps talking about the formation")
        // arrivals plant the topic on the witnesses
        val s2 = freshB(); calmB(s2, weekendB, 10 * 60)
        s2.friendship["Stan"] = 30; Crew.invite(s2, "Stan")
        placeB(s2, "Stan", "StarksPond")
        placeB(s2, "Wendy", "StarksPond"); placePlayerB(s2, "StarksPond")
        Crew.tick(s2)
        check(NpcMemoryStore.get("Wendy")?.topics
            ?.contains("your crew") == true,
            "crew: when the crew rolls in, the people watching " +
                "carry the topic away with them")
    }

    // ---------- crew talk is honest about place and company ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        s.friendship["Stan"] = 30; Crew.invite(s, "Stan")
        placeB(s, "Stan", "StarksPond"); placePlayerB(s, "StarksPond")
        Crew.tick(s)
        val lines = Crew.talkLines(s, "Stan")
        val placeName = LOCATIONS["StarksPond"]!!.name
        check(lines.size == 1 && lines[0].speaker == "Stan" &&
            lines[0].text.contains(placeName),
            "crew: a lone member's crew line names the place " +
                "you're actually standing in ($placeName)")
        check(Crew.talkLines(s, "Stan").isEmpty(),
            "crew: stamped after one — talk isn't a crew jukebox")
        // a member who isn't standing with you has no crew line
        val s2 = freshB(); calmB(s2, weekendB, 10 * 60)
        s2.friendship["Stan"] = 30; Crew.invite(s2, "Stan")
        check(Crew.talkLines(s2, "Stan").isEmpty(),
            "crew: membership alone doesn't script anyone — " +
                "the lines belong to the outing")
    }

    // ---------- the page, the save, the seams ----------
    run {
        val s = freshB(); calmB(s, weekendB, 10 * 60)
        s.friendship["Stan"] = 30; Crew.invite(s, "Stan")
        placeB(s, "Stan", "StarksPond"); placePlayerB(s, "StarksPond")
        Crew.tick(s)
        val page = Crew.pageLines(s)
        check(page.any { it.startsWith("🤝 Stan") } &&
            page.any { it.contains("outings 1") },
            "crew: the page lists who's in, since when, and " +
                "the tallies — from the same counters")
        // round-trip through the real save path
        val back = decodeGameState(encodeGameState(s))
        check(Crew.members(back) == listOf("Stan") &&
            Crew.outings(back, "Stan") == 1 &&
            Crew.modeOf(back, "Stan") == "with",
            "crew: membership, tallies and the standing " +
                "arrangement survive the save round-trip")
        // a pre-0.9.0b save is just a save with the keys absent
        val doc = encodeGameState(s).toMutableMap()
        doc["life"] = (doc["life"] as Map<*, *>)
            .filterKeys { !it.toString().startsWith("crew") }
        doc["lifeText"] = (doc["lifeText"] as Map<*, *>)
            .filterKeys { !it.toString().startsWith("crew") }
        val old = decodeGameState(doc)
        check(Crew.members(old).isEmpty() &&
            Crew.pageLines(old).any { it.contains("No crew yet") },
            "crew: strip the keys and the save is the old save — " +
                "crewless, whole, nothing else touched")
        // the hooks are wired where the funnels live
        val srcDir = "src/com/hunt3r/southparktown"
        check(File(root, "$srcDir/Photos.kt").readText()
            .contains("Crew.onPhoto(state, rec)") &&
            File(root, "$srcDir/Minigames.kt").readText()
                .contains("Crew.onShowdown(state)") &&
            File(root, "$srcDir/Rival.kt").readText()
                .contains("Crew.onContest(state)") &&
            File(root, "$srcDir/TalkGate.kt").readText()
                .contains("Crew.owedLine") &&
            File(root, "$srcDir/GameActivity.kt").readText()
                .contains("Crew.menuOption") &&
            File(root, "$srcDir/GameActivity.kt").readText()
                .contains("Crew.talkLines") &&
            File(root, "$srcDir/JournalActivity.kt").readText()
                .contains("👥 YOUR CREW") &&
            File(root, "$srcDir/GameView.kt").readText()
                .contains("Crew.members(st)"),
            "crew: every funnel hook is wired — photo, showdown, " +
                "contest, owed line, menu, talk, Journal, crowd")
    }
    NpcMemoryStore.deserialize(memSnapshotB)
}

private fun sectionV090c(root: String) {
// ================= v0.9.0c: the county fair =================
// Queue #9 item 3. One week every summer at Kid's Park:
// a pure calendar week that never touches the finale's,
// three contests judged on rails the town already trusts
// (the yearbook's photo math, the real fish table, the
// showdown's zones), ribbons + coins + a feats pair + one
// derived house piece, a gathering that defers, fair
// errands on the board's funnels, a phone text from the
// Mayor, fireworks through SkyState, and an honest record
// — attended or missed — on the Journal's fair page.
    println("== v0.9.0c: the county fair ==")
    val readmeC = File(root, "docs/CHANGELOG.md").readText()
    check(readmeC.contains("### v0.9.0c"),
        "fair: the README carries this build's changelog entry")
    val engC = Engine(909_003)
    fun freshC(): GameState {
        val s = engC.newState()
        engC.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun keyC(y: Int, m: Int, d: Int) = "%04d%02d%02d".format(y, m, d)
    fun setDateC(s: GameState, y: Int, m: Int, d: Int, timeMin: Int) {
        s.gameYear = y; s.gameMonth = m; s.gameDay = d
        s.todayKey = keyC(y, m, d)
        s.absDay = FairCalendar.absDayOfOrdinal(ordinalOfKey(s.todayKey))
        s.timeMin = timeMin
        s.holidayId = null
    }
    fun placeC(s: GameState, who: String, loc: String) {
        val a = s.agents[who]!!
        a.location = loc; a.destination = loc; a.waypoints.clear()
    }
    fun placePlayerC(s: GameState, loc: String) {
        val me = engC.player(s)
        me.location = loc; me.destination = loc; me.waypoints.clear()
    }
    val fair27 = FairCalendar.windowFor(2027)
    fun fairDateC(dayIdx: Int) = keyFromOrdinal(fair27.startOrd + dayIdx)
        .let { Triple(it.substring(0, 4).toInt(),
            it.substring(4, 6).toInt(), it.substring(6, 8).toInt()) }

    // ---------- the calendar: anchor, shift, disjoint ----------
    check(fair27.shifted && fair27.startOrd == ordinalOfKey("20270814"),
        "fair: 2027's third-Saturday week (Aug 21-27) touches " +
            "the Regatta's week, so the fair moves to Aug 14-20 " +
            "and says so (shifted=${fair27.shifted})")
    val fair28 = FairCalendar.windowFor(2028)
    check(fair28.shifted && fair28.startOrd == ordinalOfKey("20280812"),
        "fair: 2028 collides by a single day (Aug 19-25 vs the " +
            "finale opening Aug 25) and still shifts — Aug 12-18")
    val fair29 = FairCalendar.windowFor(2029)
    check(!fair29.shifted && fair29.startOrd == ordinalOfKey("20290818"),
        "fair: 2029's week (Aug 18-24) clears the finale by a " +
            "day and stands unshifted")
    var disjoint = true
    var saturdays = true
    var weeksOk = true
    for (y in 2026..2045) {
        val w = FairCalendar.windowFor(y)
        val fin = FairCalendar.finaleWindow(y)
        if (w.startOrd <= fin.last && w.endOrd >= fin.first) disjoint = false
        if (FairCalendar.dowOfOrdinal(w.startOrd) != 6) saturdays = false
        if (w.endOrd - w.startOrd != 6) weeksOk = false
        if (FairCalendar.windowAtOrdinal(w.startOrd + 3)?.year != y)
            weeksOk = false
    }
    check(disjoint, "fair: across 2026-2045 the fair week NEVER " +
        "intersects the summer finale window — the shift rule " +
        "is load-bearing, not decorative")
    check(saturdays && weeksOk, "fair: every fair opens on a " +
        "Saturday and runs exactly seven days, and the window " +
        "lookup round-trips mid-week")
    check(FairCalendar.windowFor(2027).startOrd !=
        FairCalendar.windowFor(2028).startOrd,
        "fair: the week is anchored to the calendar, not a " +
            "fixed date — it moves year to year")

    // ---------- fireworks: one night, honestly in the sky ----------
    val closeAbs = FairCalendar.absDayOfOrdinal(fair27.endOrd)
    check(SkyState.specialAt(closeAbs, 21 * 60, "sunny",
        Season.SUMMER) == SkyState.FIREWORKS,
        "fair: closing night at 9 PM, the sky over the fair is " +
            "FIREWORKS through SkyState itself")
    check(SkyState.dateSpecial(closeAbs, "sunny", Season.SUMMER) ==
        SkyState.FIREWORKS,
        "fair: the date's special is the fireworks too (the " +
            "morning-after buzz tells the truth)")
    check(SkyState.specialAt(closeAbs, 12 * 60, "sunny",
        Season.SUMMER) != SkyState.FIREWORKS &&
        SkyState.specialAt(closeAbs - 1, 21 * 60, "sunny",
            Season.SUMMER) != SkyState.FIREWORKS &&
        SkyState.specialAt(closeAbs, 21 * 60, "blizzard",
            Season.SUMMER) != SkyState.FIREWORKS,
        "fair: no fireworks at noon, none the night before, " +
            "and none through a blizzard — one night only")
    val skyFig = PhotoFigure("Walker", "player", "happy")
    val skyRec = PhotoRecord(
        id = "skyC", dayKey = keyFromOrdinal(fair27.endOrd),
        dateLabel = "8/20", timeMin = 21 * 60 + 15,
        locId = Fair.FAIRGROUND, inside = false,
        weatherId = "sunny", appearance = emptyMap(),
        figures = listOf(skyFig), absDay = closeAbs)
    check(Yearbook.skySpecialOf(skyRec) == SkyState.FIREWORKS &&
        Yearbook.rawScore(Yearbook.CAT_SKY, skyRec) >= 25,
        "fair: a photo taken under the fireworks honestly " +
            "carries them — the yearbook's sky judges score " +
            "FIREWORKS at 25, under the harvest moon's 30")

    // ---------- records & saves ----------
    run {
        val rec = FairRecord(2027, true, "Jimbo", wrapped = true,
            attended = true,
            photoPlaces = listOf(FairPlace("Walker", "your frame", 91)),
            fishPlaces = listOf(FairPlace("Jimbo", "Golden Carp, 44 cm", 997044)),
            dunkPlaces = listOf(FairPlace("Walker", "3 of 3 dunks on Jimbo", 300900)),
            photoJudge = "Wendy", photoNote = "Judged on the frame.",
            playerPhoto = 1, playerFish = 0, playerDunk = 1)
        val s = freshC()
        s.fairs.add(rec)
        val back = decodeGameState(encodeGameState(s))
        check(back.fairs.size == 1 && back.fairs[0] == rec,
            "fair: a wrapped fair record round-trips the save " +
                "whole — places, note, ribbons and all")
        val old = decodeGameState(emptyMap())
        check(old.fairs.isEmpty(),
            "fair: a pre-0.9.0c save (no fairs key) loads with " +
                "no fairs and no complaint — additive only")
        check(Fair.blueRibbons(s) == 2 &&
            Fair.fairFeatEarned(s, Fair.featById("fair_ribbon")!!) &&
            !Fair.fairFeatEarned(s, Fair.featById("fair_sweep")!!) &&
            "fair_ribbons" in House.decorFor(s),
            "fair: two blues light the Fair Ribbon feat and hang " +
                "the ribbon display (House derives it from the " +
                "fair records), but the sweep needs all three")
        val sweep = freshC()
        sweep.fairs.add(rec.copy(playerFish = 1))
        check(Fair.fairFeatEarned(sweep, Fair.featById("fair_sweep")!!),
            "fair: three blues in ONE fair is the sweep — hard, " +
                "and the feat knows it")
    }

    // ---------- dressing: standing & struck ----------
    run {
        val s = freshC()
        val (y, m, d) = fairDateC(2)
        setDateC(s, y, m, d, 12 * 60)
        val toks = Fair.fairTokensByLoc(s)
        check(toks[Fair.FAIRGROUND]?.toSet() == Fair.FAIR_TOKENS &&
            Fair.FAIR_TOKENS.all {
                Depth.tokenBand(it) == Band.BACKGROUND },
            "fair: mid-week the fairground wears all four " +
                "dressing tokens, every one registered at " +
                "BACKGROUND in Depth (booths, bunting, wheel, tank)")
        val layerIdx = Depth.EXTERIOR_LAYERS.indexOfFirst { it.id == "fair" }
        val markIdx = Depth.EXTERIOR_LAYERS.indexOfFirst {
            it.id == "faction-mark" }
        check(layerIdx > markIdx && layerIdx >= 0,
            "fair: the render stack carries the fair layer " +
                "beside its dressing kin (after faction-mark)")
        val (y2, m2, d2) =
            keyFromOrdinal(fair27.endOrd + 1).let {
                Triple(it.substring(0, 4).toInt(),
                    it.substring(4, 6).toInt(), it.substring(6, 8).toInt()) }
        setDateC(s, y2, m2, d2, 12 * 60)
        check(Fair.fairTokensByLoc(s).isEmpty(),
            "fair: the morning after closing the tokens are " +
                "gone — the dressing is a pure function of the " +
                "week, so the strike needs no one's permission")
        val sceneSrc = File(root,
            "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        val interiorSrc = File(root,
            "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
        check(sceneSrc.contains("drawFairDetails(") &&
            interiorSrc.contains("\"fair-ribbons\""),
            "fair: the fair layer paints from SceneArt and the " +
                "ribbon display hangs in the room (source pins)")
    }

    // ---------- the week lived: open, gather, defer ----------
    run {
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s)
        check(Fair.recordFor(s, 2027) != null &&
            Fair.recordFor(s, 2027)?.sitter ==
                Fair.sitterFor(2027),
            "fair: opening morning births the year's record " +
                "with its seeded sitter already in it")
        setDateC(s, y0, m0, d0, 12 * 60)
        placeC(s, "Liane", "MainStreet")
        val block = Fair.gatheringBlock(s, "Liane", 12 * 60)
        check(block != null && block.location == Fair.FAIRGROUND,
            "fair: at noon on opening day the claim bends an " +
                "unclaimed townsfolk to the fairground")
        check(Fair.gatheringBlock(s, "Liane", 21 * 60) == null,
            "fair: the claim lets go at closing time (20:00) " +
                "on an ordinary fair night")
        val (y6, m6, d6) = fairDateC(6)
        setDateC(s, y6, m6, d6, 21 * 60)
        check(Fair.gatheringBlock(s, "Liane", 21 * 60)?.location ==
            Fair.FAIRGROUND,
            "fair: closing night the claim holds to 21:30 — " +
                "the town stays for the fireworks")
        check(Fair.gatheringBlock(s, "Liane", 22 * 60) == null,
            "fair: ...and lets go after them, like everyone")
        // deference: the Marsh dinner claims its own.
        // (Fabrication note: Dinners anchors by absDay,
        // the fair by the calendar date — each system reads
        // its own slice, so the test stands the state on a
        // real Marsh dinner day AND a real fair date, the
        // way the two claims would meet in play.)
        val marsh = Dinners.defById("marsh")!!
        var dd = 1
        while (!(Dinners.isDinnerDay(dd) &&
            Dinners.HOUSEHOLDS[Dinners.dinnerDaysBefore(dd) %
                Dinners.HOUSEHOLDS.size] == marsh)) dd++
        s.absDay = dd
        s.timeMin = 18 * 60
        Dinners.dailyRollover(s) // anchors tonight's invite
        val (y1, m1, d1) = fairDateC(1)
        s.gameYear = y1; s.gameMonth = m1; s.gameDay = d1
        s.todayKey = keyC(y1, m1, d1)
        s.timeMin = 18 * 60
        check(Dinners.gatheringBlock(s, "Stan", 18 * 60) != null &&
            Fair.gatheringBlock(s, "Stan", 18 * 60) == null,
            "fair: a household member claimed by tonight's " +
                "family dinner is NOT the fair's to hold — set " +
                "pieces outrank the fair, self-guarded")
    }

    // ---------- the menu: ribbon, booth, errands ----------
    run {
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 11 * 60)
        Fair.dailyRollover(s)
        placePlayerC(s, Fair.FAIRGROUND)
        placeC(s, "McDaniels", Fair.FAIRGROUND)
        placeC(s, "Liane", Fair.FAIRGROUND)
        placeC(s, "Wendy", Fair.FAIRGROUND)
        check(Fair.menuOption(s, "McDaniels") == Fair.OPT_RIBBON,
            "fair: opening day at the park, the Mayor's menu " +
                "carries the ribbon-cutting — a played beat, " +
                "not a rail")
        val cutText = Fair.cutRibbon(s)
        check(cutText.isNotEmpty() && Fair.ribbonCut(s, 2027) &&
            Fair.cutRibbon(s).isEmpty() &&
            Fair.menuOption(s, "McDaniels") == null,
            "fair: the ribbon cuts once — the record knows, " +
                "the menu moves on")
        check(Fair.menuOption(s, "Liane") == Fair.OPT_BOOTH,
            "fair: Liane's menu carries the snack booth")
        s.inventory[Minigames.COIN_ITEM] = 5
        val line = Fair.buyBooth(s, "cheesy_poof")
        check(line != null && Minigames.capsuleCoins(s) == 3 &&
            (s.inventory["cheesy_poof"] ?: 0) == 1,
            "fair: the booth sells a real pantry item at its " +
                "posted fair price — coins out, poofs in")
        s.inventory.remove(Minigames.COIN_ITEM)
        check(Fair.buyBooth(s, "cheesy_poof") == null,
            "fair: and sells nothing to empty pockets — the " +
                "sink is honest, not a debt trap")
        val offer = Fair.errandOffer(s, "Wendy")
        check(offer != null && offer.id == "ribbon_lemonade",
            "fair: Wendy's day-0 errand posts at the fairground " +
                "in fair hours")
        val text = Fair.acceptErrand(s, offer!!)
        check(text != null && s.errands.any {
            it.source == Errands.FAIR &&
                it.id == "f2027:ribbon_lemonade" } &&
            Fair.errandOffer(s, "Wendy") == null,
            "fair: accepting lands a FAIR-sourced errand on " +
                "the real plate (the verbs judge it), and the " +
                "offer spends")
        check(Errands.objective(s.errands.first {
            it.id == "f2027:ribbon_lemonade" }).startsWith("🎡"),
            "fair: a fair errand's objective wears its 🎡 in " +
                "every surface that prints one")
        setDateC(s, y0, m0, d0, 21 * 60 + 30)
        check(Fair.errandOffer(s, "Clyde") == null,
            "fair: no fair business posts after hours")
    }

    // ---------- the photo contest ----------
    fun fairPhoto(dayKey: String, npcs: List<String>, figures: Int,
                  followers: Int, id: String): PhotoRecord {
        val figs = mutableListOf(PhotoFigure("Walker", "player", "happy"))
        for (n in npcs) figs += PhotoFigure(n, "npc", "happy")
        repeat((figures - figs.size).coerceAtLeast(0)) {
            figs += PhotoFigure("Extra$it", "npc", "neutral")
        }
        return PhotoRecord(id = id, dayKey = dayKey, dateLabel = "8/14",
            timeMin = 13 * 60, locId = Fair.FAIRGROUND, inside = false,
            weatherId = "sunny", appearance = emptyMap(),
            figures = figs, followersGained = followers,
            absDay = FairCalendar.absDayOfOrdinal(ordinalOfKey(dayKey)))
    }
    run {
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s)
        val (y3, m3, d3) = fairDateC(3)
        // a modest fair frame on day 1, a street ringer that
        // must NOT count, and nothing else
        val d1 = keyFromOrdinal(fair27.startOrd + 1)
        s.photos += fairPhoto(d1, listOf("Stan"), 3, 2, "fairmodest")
        s.photos += PhotoRecord(id = "ringer", dayKey = d1,
            dateLabel = "8/15", timeMin = 13 * 60,
            locId = "MainStreet", inside = false,
            weatherId = "sunny", appearance = emptyMap(),
            figures = (0..20).map { PhotoFigure("T$it", "npc", "happy") },
            followersGained = 99,
            absDay = FairCalendar.absDayOfOrdinal(ordinalOfKey(d1)))
        setDateC(s, y3, m3, d3, 9 * 60)
        Fair.dailyRollover(s)
        val rec = Fair.recordFor(s, 2027)!!
        check(rec.photoPlaces.size == 3 &&
            Fair.playerPhotoEntry(s, fair27)?.id == "fairmodest",
            "fair: the photo contest judges fairground frames " +
                "from the entry days only — the Main Street " +
                "ringer competes nowhere")
        // determinism: a second, identical save judges identically
        val s2 = freshC()
        setDateC(s2, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s2)
        s2.photos += fairPhoto(d1, listOf("Stan"), 3, 2, "fairmodest")
        setDateC(s2, y3, m3, d3, 9 * 60)
        Fair.dailyRollover(s2)
        check(Fair.recordFor(s2, 2027)?.photoPlaces == rec.photoPlaces,
            "fair: the judging is a pure function of the album " +
                "and the seeded field — same fair, same places")
        // the judge's note cites only record facts
        val winnerName = rec.photoPlaces.first().name
        check(rec.photoNote.contains(winnerName) &&
            rec.photoJudge == Fair.photoJudgeFor(2027).name,
            "fair: the judge's note names the winner and the " +
                "judge is the yearbook desk's own rotation")
    }
    run {
        // a big fair frame wins; a lone selfie mostly loses —
        // across twenty fairs, somebody else takes most blues
        var npcBlues = 0
        var playerBlues = 0
        for (y in 2027..2046) {
            val s = freshC()
            val w = FairCalendar.windowFor(y)
            val k0 = keyFromOrdinal(w.startOrd)
            setDateC(s, k0.substring(0, 4).toInt(),
                k0.substring(4, 6).toInt(), k0.substring(6, 8).toInt(),
                9 * 60)
            Fair.dailyRollover(s)
            s.photos += fairPhoto(keyFromOrdinal(w.startOrd),
                listOf("Stan"), 2, 0, "weak$y")
            Fair.judgePhoto(s, w)
            val rec = Fair.recordFor(s, y)!!
            if (rec.playerPhoto == 1) playerBlues++
            else if (rec.photoPlaces.isNotEmpty()) npcBlues++
        }
        check(npcBlues >= 12 && playerBlues <= 4,
            "fair: with a weak entry the town wins the photo " +
                "blue in most simulated fairs (town $npcBlues, " +
                "player $playerBlues of 20) — somebody else CAN win")
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s)
        s.photos += fairPhoto(keyFromOrdinal(fair27.startOrd),
            listOf("Stan", "Kyle", "Kenny", "Butters", "Wendy",
                "Craig", "Tweek", "Clyde"), 14, 25, "bigfair")
        Fair.judgePhoto(s, fair27)
        val rec = Fair.recordFor(s, 2027)!!
        check(rec.playerPhoto == 1 &&
            Minigames.capsuleCoins(s) == Fair.PLACE_COINS[0] &&
            rec.photoNote.contains("Stan"),
            "fair: a real fair frame — the whole crew at the " +
                "fairground — takes the blue, the 6-coin prize, " +
                "and a judge's note that cites the frame's own " +
                "company")
    }

    // ---------- the fishing contest ----------
    run {
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s) // the fair opens; the record stands
        val (y3, m3, d3) = fairDateC(Fair.FISH_DAY)
        setDateC(s, y3, m3, d3, 11 * 60)
        placePlayerC(s, Fair.POND)
        val smelt = fishById("pond_smelt")!!
        val boot = FISH_TABLE.first { it.id == "old_boot" }
        Fair.onCatch(s, smelt, 18)
        Fair.onCatch(s, boot, 30)
        check(Fair.playerFishEntry(s, 2027)?.first?.id == "pond_smelt",
            "fair: a boot never displaces a fish — a boot is " +
                "not a fish, on contest day either")
        val carp = FISH_TABLE.minByOrNull { Rival.fishRank(it) }!!
        Fair.onCatch(s, carp, 41)
        check(Fair.playerFishEntry(s, 2027)?.first?.id == carp.id,
            "fair: a rarer fish takes the entry — rank first, " +
                "then size, the table's own values")
        val field = Fair.fishField(s, 2027)
        check("Jimbo" in field && Rival.rivalOf(s) in field,
            "fair: the fishing field holds Jimbo and the " +
                "rival — authored entrants, not dice")
        val before = Rival.winsYou(s) + Rival.winsThem(s) +
            Rival.draws(s)
        Fair.judgeFish(s, fair27)
        val rec = Fair.recordFor(s, 2027)!!
        check(rec.fishPlaces.size == 3 &&
            Rival.winsYou(s) + Rival.winsThem(s) + Rival.draws(s) ==
                before + 1,
            "fair: with both rivals entered and no duel armed, " +
                "the fair result lands on the 🆚 ledger exactly " +
                "once, through Rival's own path")
        // and with an armed fishing duel, the fair keeps its page only
        val s2 = freshC()
        setDateC(s2, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s2)
        setDateC(s2, y3, m3, d3, 11 * 60)
        placePlayerC(s2, Fair.POND)
        Fair.onCatch(s2, smelt, 18)
        s2.lifeText["rivalPending"] = Rival.K_FISHING
        val before2 = Rival.winsYou(s2) + Rival.winsThem(s2) +
            Rival.draws(s2)
        Fair.judgeFish(s2, fair27)
        check(Rival.winsYou(s2) + Rival.winsThem(s2) +
            Rival.draws(s2) == before2,
            "fair: a fair result NEVER double-counts — an " +
                "armed duel owns the ledger that week")
        // off the day / off the pond: no funnel
        val s3 = freshC()
        val (y2, m2, d2) = fairDateC(2)
        setDateC(s3, y2, m2, d2, 11 * 60)
        placePlayerC(s3, Fair.POND)
        Fair.onCatch(s3, carp, 41)
        check(Fair.playerFishEntry(s3, 2027) == null,
            "fair: a pond catch on a non-contest day is just " +
                "a catch — the funnel is day-3 honest")
    }

    // ---------- the dunk tank ----------
    run {
        var buttersHits = 0
        var tweekHits = 0
        for (seed in 1L..200L) {
            val a = Fair.DunkSession(seed, "Butters")
            while (!a.over) if (a.throwBall(0.5f)) buttersHits++
            val b = Fair.DunkSession(seed, "Tweek")
            while (!b.over) if (b.throwBall(0.5f)) tweekHits++
        }
        check(buttersHits > tweekHits && buttersHits > 300,
            "fair: perfect-zone throws dunk the still sitter " +
                "far more than the twitchy one ($buttersHits vs " +
                "$tweekHits of 600) — the showdown's dodge is " +
                "really in the math")
        val ses = Fair.DunkSession(42L, "Butters")
        check(ses.throwsLeft == Fair.DUNK_THROWS && !ses.over,
            "fair: a fresh tank stands at three throws, unspent")
        ses.throwBall(0.0f)
        check(ses.throwsLeft == Fair.DUNK_THROWS - 1 &&
            ses.powerMilli > 0,
            "fair: every throw spends one of three and banks " +
                "its zone power, even a whiffed release")
        check(Fair.npcDunkScore(2027, "Stan", "Jimbo") ==
            Fair.npcDunkScore(2027, "Stan", "Jimbo"),
            "fair: a townsfolk bracket is seeded per (year, " +
                "entrant, sitter) — the same tank every asking")
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s)
        Fair.recordDunk(s, 3, 2700)
        val places = Fair.dunkPlaces(s, fair27)
        check(places.isNotEmpty() &&
            places.zipWithNext().all { (a, b) -> a.score >= b.score },
            "fair: the tank's places come out in a total " +
                "order — dunks, then throw power, then name")
    }

    // ---------- the wrap: attended & missed, honestly ----------
    run {
        val s = freshC()
        val (y0, m0, d0) = fairDateC(0)
        setDateC(s, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s)
        val after = keyFromOrdinal(fair27.endOrd + 3)
        setDateC(s, after.substring(0, 4).toInt(),
            after.substring(4, 6).toInt(), after.substring(6, 8).toInt(),
            9 * 60)
        Fair.dailyRollover(s)
        val rec = Fair.recordFor(s, 2027)!!
        check(rec.wrapped && rec.missed && !rec.attended &&
            Fair.pageLines(s).any { it.contains("missed") },
            "fair: a slept-through fair wraps as MISSED — the " +
                "contests judged without you, the page says so, " +
                "and the dressing already struck")
        val s2 = freshC()
        setDateC(s2, y0, m0, d0, 9 * 60)
        Fair.dailyRollover(s2)
        placePlayerC(s2, Fair.FAIRGROUND)
        placeC(s2, "McDaniels", Fair.FAIRGROUND)
        setDateC(s2, y0, m0, d0, 11 * 60)
        Fair.cutRibbon(s2)
        setDateC(s2, after.substring(0, 4).toInt(),
            after.substring(4, 6).toInt(), after.substring(6, 8).toInt(),
            9 * 60)
        Fair.dailyRollover(s2)
        val rec2 = Fair.recordFor(s2, 2027)!!
        check(rec2.wrapped && rec2.attended && !rec2.missed,
            "fair: cutting the ribbon is attendance — that " +
                "fair wraps as lived, not missed")
    }

    // ---------- announcement & phone ----------
    run {
        val s = freshC()
        val pre = keyFromOrdinal(fair27.startOrd - Fair.ANNOUNCE_AHEAD)
        setDateC(s, pre.substring(0, 4).toInt(),
            pre.substring(4, 6).toInt(), pre.substring(6, 8).toInt(),
            9 * 60)
        check(Fair.announceDue(s) &&
            Fair.announcementLine(fair27).contains("Moved up a week"),
            "fair: three mornings out the announcement is due, " +
                "and a shifted year's line CONFESSES the shift")
        Fair.markPhoned(s, 2027)
        check(!Fair.announceDue(s),
            "fair: once the Mayor's text lands, the due flag " +
                "falls — one announcement text per fair")
        check(Phone.FAIR in Phone.TRIGGERS &&
            Phone.FAIR_LINES.isNotEmpty(),
            "fair: the phone knows the FAIR trigger and the " +
                "Mayor has her lines")
        val poster = Fair.lookText(s, Fair.FAIRGROUND)
        check(poster != null && poster.contains("COUNTY FAIR") &&
            poster.contains("Moved up a week"),
            "fair: the poster on the park fence names the " +
                "dates and the shift, three days out")
        val (y2, m2, d2) = fairDateC(2)
        setDateC(s, y2, m2, d2, 12 * 60)
        check(Fair.lookText(s, Fair.FAIRGROUND) != null &&
            Fair.lookText(s, Fair.POND) == null,
            "fair: mid-week the fairground Look tells the " +
                "week's story; the pond waits for its morning")
        val (y3, m3, d3) = fairDateC(Fair.FISH_DAY)
        setDateC(s, y3, m3, d3, 12 * 60)
        check(Fair.lookText(s, Fair.POND) != null,
            "fair: fishing day, the pond's Look carries the " +
                "contest — one day, one table")
    }

    // ---------- page shape: newest whole, elders one line ----------
    run {
        val s = freshC()
        s.fairs.add(FairRecord(2026, false, "Randy", wrapped = true,
            attended = true,
            photoPlaces = listOf(FairPlace("Stan", "their frame", 80)),
            fishPlaces = listOf(FairPlace("Jimbo", "Trout, 30 cm", 900030)),
            dunkPlaces = listOf(FairPlace("Kyle", "2 of 3 dunks on Randy", 200800)),
            playerPhoto = 2))
        s.fairs.add(FairRecord(2027, true, "Jimbo", wrapped = true,
            missed = true))
        val lines = Fair.pageLines(s)
        check(lines.any { it.startsWith("🎡 2026:") } &&
            lines.any { it.contains("you missed it") },
            "fair: the page keeps the newest fair whole and " +
                "elders as one-line summaries — winners named, " +
                "a missed year marked missed")
        check(File(root, "src/com/hunt3r/southparktown").listFiles()
            ?.count { it.name.endsWith(".kt") } == 137,
            "fair: the source tree is 110 Kotlin files — Fair.kt " +
                "joined at v0.9.0c, Darkroom.kt at v0.9.0d, " +
                "RivalCrew.kt at v0.9.0e, Family.kt at v0.10.0a, " +
                "Heroes.kt at v0.10.0b, Play.kt at v0.10.0c, " +
                "GroupChats.kt at v0.10.0d, Stand.kt at " +
                "v0.10.0e, Mystery8.kt at v0.10.0f, " +
                "Sleepovers.kt at v0.11.0c, " +
                "CastDataWave6.kt at v0.11.0d (wave 6's data " +
                "split out of CastData.kt — its static " +
                "initializer hit the JVM method limit), " +
                "Shop.kt at v0.12.0b, Sleepwear.kt at " +
                "v0.12.0d, Attic.kt at v0.12.0e, Dance.kt at " +
                "v0.13.0b, Talent.kt at v0.13.0c, " +
                "Parade.kt at v0.13.0d, Mystery11.kt at " +
                "v0.13.0f, FieldTrip.kt at v0.14.0b, " +
                "Festival.kt at v0.14.0c, Rig.kt at " +
                "v0.17.0a, nothing else snuck in")
    }
}

private fun sectionV090d(root: String) {
// ================= v0.9.0d: the darkroom =================
// Queue #9 item 4. Your house learns to develop what your
// camera saw: a red-lit fixture, honest minutes and honest
// paper money on the town's own clock, prints that carry
// their OWN copy of a photo's record (the yearbook-volume
// survival pattern) so they outlive the album cap whole,
// a capped box and a three-frame wall, enlargements gifted
// through the person menu's gift flow — judged by the
// photo's real fields, once per photo per person, the
// holder remembered in Talk — dinner guests remarking on
// wall prints of their own household in fact-slot lines,
// and a brass plate derived from the yearbooks, never
// hand-set. The source record is never touched.
    println("== v0.9.0d: the darkroom ==")
    val readmeD = File(root, "docs/CHANGELOG.md").readText()
    check(readmeD.contains("### v0.9.0d"),
        "darkroom: the README carries this build's changelog entry")
    val engD = Engine(909_004)
    fun freshD(): GameState {
        val s = engD.newState()
        engD.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun photoD(id: String, figures: List<PhotoFigure>,
               loc: String = "StarksPond", followers: Int = 0,
               starred: Boolean = false, absDay: Int = 100):
        PhotoRecord =
        PhotoRecord(id = id, dayKey = "20261024",
            dateLabel = "10/24", timeMin = 600, locId = loc,
            inside = false, weatherId = "clear",
            appearance = DEFAULT_APPEARANCE, figures = figures,
            followersGained = followers, starred = starred,
            absDay = absDay)
    fun figD(name: String, reaction: String = "") =
        PhotoFigure(name, "cast", "happy", reaction = reaction)
    fun coinsD(s: GameState, n: Int) {
        s.inventory[Minigames.COIN_ITEM] = n
    }
    val pondName = LOCATIONS["StarksPond"]?.name ?: "Stark's Pond"

    // ---------- records & saves ----------
    run {
        val s = freshD()
        val rec = photoD("pd1", listOf(figD("Stan"), figD("Kyle")))
        val p = DarkroomPrint("pr1", "pd1", rec,
            Darkroom.SIZE_ENLARGEMENT, 100, "20261024",
            onWall = true, owner = "Stan", giftedAbsDay = 101,
            lineSaid = true)
        s.prints.add(p)
        val back = decodeGameState(encodeGameState(s))
        check(back.prints.size == 1 &&
            back.prints[0].id == "pr1" &&
            back.prints[0].photoId == "pd1" &&
            back.prints[0].size == Darkroom.SIZE_ENLARGEMENT &&
            back.prints[0].onWall && back.prints[0].owner == "Stan" &&
            back.prints[0].giftedAbsDay == 101 &&
            back.prints[0].lineSaid &&
            back.prints[0].record.id == "pd1" &&
            back.prints[0].record.figures.map { it.name } ==
                listOf("Stan", "Kyle"),
            "darkroom: a print round-trips the save whole — " +
                "the copy, the wall, the owner, the said line")
        check(decodeGameState(emptyMap()).prints.isEmpty(),
            "darkroom: a pre-0.9.0d save (no prints key) loads " +
                "with an empty print box — additive only")
    }

    // ---------- developing: gate, cost, clock, the copy ----------
    run {
        val s = freshD()
        check(Darkroom.developBlock(s, Darkroom.SIZE_PRINT) != null &&
            Darkroom.develop(s, "pd2", Darkroom.SIZE_PRINT) == null,
            "darkroom: no photos, no developing — the trays " +
                "stay dry")
        s.photos.add(photoD("pd2", listOf(figD("Stan"))))
        check(Darkroom.developBlock(s, Darkroom.SIZE_PRINT) != null,
            "darkroom: no coins, no developing — paper isn't free")
        coinsD(s, 3)
        check(Darkroom.developBlock(s, Darkroom.SIZE_PRINT) == null &&
            Darkroom.developBlock(s,
                Darkroom.SIZE_ENLARGEMENT) != null,
            "darkroom: the gate prices honestly by size — " +
                "3 coins develop a print (2) but not an " +
                "enlargement (5)")
        coinsD(s, 10)
        // a moment owns the town: you may not start
        s.holidayId = "christmas"
        check(Emergencies.momentOwned(s) &&
            Darkroom.developBlock(s, Darkroom.SIZE_PRINT) != null &&
            Darkroom.develop(s, "pd2", Darkroom.SIZE_PRINT) == null,
            "darkroom: a set piece owns the hour — no " +
                "developing through a moment you're due at")
        s.holidayId = null
        s.timeMin = 600
        val srcBefore = s.photos[0].toMap().toString()
        val res = Darkroom.develop(s, "pd2", Darkroom.SIZE_PRINT)
        check(res != null && res.minutes == Darkroom.PRINT_MINUTES &&
            res.cost == Darkroom.PRINT_COST && s.timeMin == 630,
            "darkroom: a print takes its stated 30 minutes " +
                "on the town's own clock (600 -> ${s.timeMin})")
        check(Minigames.capsuleCoins(s) == 8,
            "darkroom: the stated paper cost (2) leaves the purse")
        val p1 = res!!.print
        check(p1.record !== s.photos[0] &&
            p1.record == s.photos[0] &&
            p1.photoId == "pd2",
            "darkroom: the print carries a COPY of the record " +
                "— the same facts, a different object")
        check(s.photos[0].toMap().toString() == srcBefore,
            "darkroom: developing never alters the source " +
                "record — not a field, not the star")
        val res2 = Darkroom.develop(s, "pd2",
            Darkroom.SIZE_ENLARGEMENT)
        check(res2 != null && s.timeMin == 690 &&
            Minigames.capsuleCoins(s) == 3 &&
            res2!!.print.size == Darkroom.SIZE_ENLARGEMENT,
            "darkroom: the enlargement takes its stated hour " +
                "and its stated 5 coins")
        // later album edits never rewrite the print
        val capBefore = Darkroom.captionOf(p1)
        s.photos[0] = s.photos[0].copy(locId = "MainStreet",
            starred = true)
        check(Darkroom.captionOf(p1) == capBefore &&
            !p1.record.starred &&
            p1.record.locId == "StarksPond" &&
            Darkroom.captionOf(p1) !=
                Photos.captionFor(s.photos[0]),
            "darkroom: star the album's record, move it, edit " +
                "it — the print keeps its own facts, frozen " +
                "at the tray")
    }

    // ---------- survival: the print outlives the album ----------
    run {
        val s = freshD()
        coinsD(s, 50)
        val keeper = photoD("keep1",
            listOf(figD("Stan"), figD("Kyle")))
        s.photos.add(keeper)
        val res = Darkroom.develop(s, "keep1",
            Darkroom.SIZE_PRINT)!!
        val captionBefore = Darkroom.captionOf(res.print)
        for (i in 1..Photos.ALBUM_CAP + 5) {
            Photos.applyPhoto(s, photoD("flood$i",
                listOf(figD("Randy")), absDay = 100 + i))
        }
        check(s.photos.none { it.id == "keep1" },
            "darkroom: the flood honestly fades the keeper " +
                "out of the album cap")
        check(Darkroom.sourceGone(s, res.print) &&
            Darkroom.captionOf(res.print) == captionBefore &&
            res.print.record.figures.map { it.name } ==
                listOf("Stan", "Kyle"),
            "darkroom: and the print survives whole — " +
                "caption and company intact off its own copy")
        Darkroom.hang(s, res.print.id)
        check(Darkroom.wallText(s)
            .contains("only whole one left"),
            "darkroom: the wall's readout says when a print " +
                "is the last whole copy left")
    }

    // ---------- the caps: box, wall, the swap, the total ----------
    run {
        val s = freshD()
        coinsD(s, 500)
        s.photos.add(photoD("pw0", listOf(figD("Stan"))))
        var devs = 0
        while (true) {
            s.timeMin = 600
            if (Darkroom.develop(s, "pw0",
                    Darkroom.SIZE_PRINT) == null) break
            devs++
        }
        check(devs == Darkroom.BOX_CAP &&
            Darkroom.held(s).size == Darkroom.BOX_CAP,
            "darkroom: the box fills to its stated cap " +
                "(${Darkroom.BOX_CAP}) and not one print further")
        val ps = Darkroom.held(s)
        check(Darkroom.hang(s, ps[0].id) &&
            Darkroom.hang(s, ps[1].id) &&
            Darkroom.hang(s, ps[2].id) &&
            !Darkroom.hang(s, ps[3].id) &&
            Darkroom.wall(s).size == Darkroom.WALL_CAP,
            "darkroom: three prints hang; the wall's cap is a " +
                "wall, not a suggestion")
        check(Darkroom.unhang(s, ps[0].id) &&
            Darkroom.hang(s, ps[3].id) &&
            Darkroom.wall(s).any { it.id == ps[3].id } &&
            !Darkroom.hang(s, ps[3].id),
            "darkroom: swapping is free — down with one, up " +
                "with another, and never the same print twice")
        check(Darkroom.wallText(s)
            .contains(Darkroom.captionOf(ps[3])),
            "darkroom: the wall readout quotes the hung " +
                "prints' own captions")
    }
    run {
        // past TOTAL_CAP, the oldest GIFTED print is
        // forgotten — a held print never is
        val s = freshD()
        coinsD(s, 10)
        for (i in 1..Darkroom.TOTAL_CAP) {
            s.prints.add(DarkroomPrint("old$i", "o$i",
                photoD("o$i", listOf(figD("Stan"))),
                Darkroom.SIZE_ENLARGEMENT, 90, "20261001",
                owner = "Holder$i"))
        }
        s.photos.add(photoD("new1", listOf(figD("Kyle"))))
        val res = Darkroom.develop(s, "new1", Darkroom.SIZE_PRINT)
        check(res != null && res.forgotten?.id == "old1" &&
            s.prints.size == Darkroom.TOTAL_CAP &&
            s.prints.none { it.id == "old1" } &&
            s.prints.any { it.id == res!!.print.id },
            "darkroom: the 25th record forgets the oldest " +
                "GIFTED print, says so, and keeps every held one")
    }

    // ---------- gifting: judged by the photo's real fields ----------
    run {
        val s = freshD()
        coinsD(s, 100)
        val rec = photoD("pg1", listOf(figD("Stan"), figD("Kyle")),
            followers = 60, starred = true)
        s.photos.add(rec)
        val enl = Darkroom.develop(s, "pg1",
            Darkroom.SIZE_ENLARGEMENT)!!.print
        val chem = if (Photos.chemistryBetween(s, "Stan", "Kyle") >=
            Photos.HIGH_CHEMISTRY) 1 else 0
        val expected = minOf(Darkroom.GIFT_CAP,
            Darkroom.GIFT_BASE_POSER + chem +
                minOf(Darkroom.GIFT_FOLLOWER_CAP, 60 /
                    Darkroom.GIFT_FOLLOWER_STEP) +
                Darkroom.GIFT_STAR_BONUS)
        val f0 = s.friendship["Stan"] ?: 0
        val g = Darkroom.givePrint(s, "Stan", enl.id)
        check(g != null && g.given && g.delta == expected &&
            (s.friendship["Stan"] ?: 0) - f0 == expected,
            "darkroom: an in-frame enlargement pays by the " +
                "photo's real fields — presence, chemistry, " +
                "the followers it earned, the star (paid " +
                "${g?.delta}, expected $expected)")
        check(enl.owner == "Stan" && !enl.onWall &&
            Darkroom.heldBy(s, "Stan").contains(enl) &&
            Darkroom.holdersOf(s, "pg1") == setOf("Stan"),
            "darkroom: the given print changes hands, and " +
                "the town remembers who holds it")
        // the holder's Talk line: owed once, facts off the copy
        val line = Darkroom.owedLine(s, "Stan")
        check(line != null && line.speaker == "Stan" &&
            line.text.contains(pondName) &&
            line.text.contains("10/24") &&
            Darkroom.owedLine(s, "Stan") == null,
            "darkroom: the holder's Talk gains the line — " +
                "the print's own place and date — and like " +
                "every owed line it plays once")
        // once per photo per person
        val enl2 = Darkroom.develop(s, "pg1",
            Darkroom.SIZE_ENLARGEMENT)!!.print
        check(Darkroom.givePrint(s, "Stan", enl2.id) == null &&
            !Darkroom.giftablePrints(s, "Stan").contains(enl2) &&
            Darkroom.giftablePrints(s, "Kyle").contains(enl2),
            "darkroom: once per photo per person — Stan has " +
                "his; the same photo can still go to Kyle")
        // the dud: not in the frame, said out loud, print returns
        val enl3 = Darkroom.develop(s, "pg1",
            Darkroom.SIZE_ENLARGEMENT)!!.print
        val rf0 = s.friendship["Randy"] ?: 0
        val dud = Darkroom.givePrint(s, "Randy", enl3.id)
        check(dud != null && !dud.given && dud.delta == 0 &&
            (s.friendship["Randy"] ?: 0) == rf0 &&
            enl3.owner.isEmpty() &&
            dud.line.contains("Stan") &&
            dud.line.contains("Kyle"),
            "darkroom: a print of a photo they're NOT in is " +
                "a polite dud — no friendship, no transfer, " +
                "the print comes home, and the line names " +
                "who IS in it")
        // only enlargements are framed gifts
        val std = Darkroom.develop(s, "pg1",
            Darkroom.SIZE_PRINT)!!.print
        check(Darkroom.givePrint(s, "Kyle", std.id) == null,
            "darkroom: a plain print is a keepsake, not a " +
                "gift — only enlargements are framed")
        // the bomber: in the frame is in the frame
        val bombRec = photoD("pg2", listOf(figD("Stan"),
            PhotoFigure("Butters", "cast", "happy",
                reaction = Photos.PHOTOBOMB)))
        s.photos.add(bombRec)
        val enlB = Darkroom.develop(s, "pg2",
            Darkroom.SIZE_ENLARGEMENT)!!.print
        val bf0 = s.friendship["Butters"] ?: 0
        val gb = Darkroom.givePrint(s, "Butters", enlB.id)
        check(gb != null && gb.given &&
            gb.delta == Darkroom.GIFT_BASE_BOMBER &&
            (s.friendship["Butters"] ?: 0) - bf0 ==
                Darkroom.GIFT_BASE_BOMBER,
            "darkroom: the photobomber gets the bomber's " +
                "rate — presence is presence, even at the back")
    }

    // ---------- the brass plate: derived, never hand-set ----------
    run {
        val s = freshD()
        val winRec = photoD("win1", listOf(figD("Stan")))
        val catId = Yearbook.CATEGORIES[0].id
        val vol = YearbookVolume(2027, 40, "20270531", 200,
            pamphlet = false, indexOnly = false,
            winnersLine = "Best: Stan",
            entries = listOf(YearbookEntry(catId, "Wendy", 91,
                "Judged.", winRec)))
        s.yearbooks.add(vol)
        val pWin = DarkroomPrint("prw", "win1", winRec,
            Darkroom.SIZE_PRINT, 100, "20261024")
        val pPlain = DarkroomPrint("prp", "plain1",
            photoD("plain1", listOf(figD("Kyle"))),
            Darkroom.SIZE_PRINT, 100, "20261024")
        s.prints.addAll(listOf(pWin, pPlain))
        check(Darkroom.isYearbookWinner(s, pWin) &&
            !Darkroom.isYearbookWinner(s, pPlain) &&
            Darkroom.winnerCategory(s, pWin) == catId,
            "darkroom: the brass plate derives from the " +
                "volumes on the shelf — the winner's print " +
                "wears it, the plain print doesn't, and no " +
                "field on the print says so")
    }

    // ---------- the dinner table: guests on the wall ----------
    run {
        val s = freshD()
        // NB: the album is EMPTY here — every fact below must
        // come off the prints' own copies, or not be said
        val marshPrint = DarkroomPrint("prm", "pm1",
            photoD("pm1", listOf(figD("Stan"), figD("Kyle"))),
            Darkroom.SIZE_PRINT, 100, "20261024", onWall = true)
        val otherPrint = DarkroomPrint("pro", "po1",
            photoD("po1", listOf(figD("Cartman"))),
            Darkroom.SIZE_PRINT, 100, "20261024", onWall = true)
        val boxedPrint = DarkroomPrint("prb", "pb1",
            photoD("pb1", listOf(figD("Sharon"))),
            Darkroom.SIZE_PRINT, 100, "20261024", onWall = false)
        s.prints.addAll(listOf(marshPrint, otherPrint, boxedPrint))
        val marsh = Dinners.HOUSEHOLDS.first { it.id == "marsh" }
        val lines = Darkroom.guestPrintLines(s, marsh)
        check(lines.size == 1 && lines[0].contains("Stan") &&
            lines[0].contains(pondName) &&
            lines[0].contains("10/24"),
            "darkroom: the Marshes remark on the wall print " +
                "of their own — names, place and date from " +
                "the print's copy alone")
        check(lines.none { it.contains("Cartman") } &&
            lines.none { it.contains("Sharon") },
            "darkroom: no line for a print of somebody " +
                "else's household, and none for a print " +
                "still in the box")
        val stranger = Dinners.HOUSEHOLDS.first { h ->
            h.members.none { it in setOf("Stan", "Kyle",
                "Cartman", "Sharon") } }
        check(Darkroom.guestPrintLines(s, stranger).isEmpty(),
            "darkroom: a household nobody on the wall belongs " +
                "to hears no print line at all")
        check(Dinners.hostedCommentText(s, marsh)
            .contains(lines[0]),
            "darkroom: the hosted table's beat 2 carries " +
                "the print line at the table")
        // the brass plate rides the guest line too
        val vol = YearbookVolume(2027, 40, "20270531", 200,
            pamphlet = false, indexOnly = false,
            winnersLine = "Best: Stan",
            entries = listOf(YearbookEntry(Yearbook.CATEGORIES[0].id,
                "Wendy", 91, "Judged.", marshPrint.record)))
        s.yearbooks.add(vol)
        check(Darkroom.guestPrintLines(s, marsh)[0]
            .contains("brass plate"),
            "darkroom: a winner on the wall gets its brass " +
                "plate mentioned — derived at the table too")
    }
}

private fun sectionV090e(root: String) {
// ================= v0.9.0e: the rival's crew =================
// Queue #9 item 5. The rival gathers a crew of three —
// DERIVED by an authored precedence over real data (pair-
// script partners, then faction mates, then every other
// kid; chemistry inside a tier), recorded once and never
// re-derived; they hold court on the rival's faction turf
// through a self-guarded agenda claim; three crew contests
// ride the Rival rail (relay priced off the Walk matrix
// from real positions, a photo showdown judged on the
// yearbook's group scale, a showdown bracket on authored
// dodge) and land on the solo ledger exactly once each;
// a school-year CREWS table with a double-points final
// closes into one-line history; and the honest edge cases
// (no crew, the frenemy, the conflicted, the busy) are
// said plainly instead of stacked.
    println("== v0.9.0e: the rival's crew ==")
    val memSnapshotE2 = NpcMemoryStore.serialize()
    try {
    val readmeE2 = File(root, "docs/CHANGELOG.md").readText()
    check(readmeE2.contains("### v0.9.0e"),
        "rivalcrew: the README carries this build's changelog entry")
    val manifestE2 = File(root, "AndroidManifest.xml").readText()
    check(manifestE2.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestE2.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "rivalcrew: the manifest carries 71 / 0.9.0e")

    val engE2 = Engine(909_005)
    fun freshE(name: String): GameState {
        val s = engE2.newState()
        engE2.createPlayer(s, name, DEFAULT_APPEARANCE)
        return s
    }
    // a calm stage: mid-afternoon (school out, dinners not
    // yet called) — fielding reads the town as it stands
    fun calmE(s: GameState, day: Int) {
        s.absDay = day
        s.gameYear = 2027; s.gameMonth = 2; s.gameDay = 10
        s.todayKey = "20270210"; s.timeMin = 16 * 60
        s.holidayId = null
        s.weatherId = "clear"
    }
    fun revealedE(name: String, day: Int): GameState {
        val s = freshE(name)
        calmE(s, day)
        Rival.playReveal(s, 1)   // called it even
        return s
    }
    fun saveForRivalE(want: String): GameState {
        for (i in 0..800) {
            val s = freshE("SeekerE$i")
            if (Rival.pickFor(s) == want) return s
        }
        error("no fabricated identity crowns $want")
    }
    // a player crew of three kids who are neither the rival
    // nor theirs — set at the storage layer, the way the
    // v0.8.0e section stores a recorded crown
    fun giveCrewE(s: GameState): List<String> {
        val rival = Rival.rivalOf(s)
        val theirs = RivalCrew.theirCrew(s)
        val picks = KID_ORDER.filter {
            it != rival && it !in theirs }.take(3)
        s.lifeText["crew:members"] = picks.joinToString(",")
        return picks
    }
    fun figE(name: String, kind: String = "cast",
             pose: String = "none",
             reaction: String = "neutral") =
        PhotoFigure(name, kind, "happy", pose = pose,
            reaction = reaction)

    run {
        // ---------- derivation: precedence over real data ----------
        for (def in Rival.POOL) {
            val s = saveForRivalE(def.name)
            calmE(s, 40)
            Rival.playReveal(s, 1)
            val crew = RivalCrew.theirCrew(s)
            check(crew.size == 3 && crew.distinct().size == 3 &&
                def.name !in crew &&
                crew.all { it in CharacterSystem.CAST_KIDS },
                "rivalcrew: ${def.name} gathers three distinct " +
                    "kids, none of them themselves ($crew)")
            // tiers 0+1 always fill the three for a pool
            // rival: every pick is a pair-script partner or
            // a faction mate — tier 3 is never reached
            val partners = PAIR_SCRIPTS.keys
                .filter { def.name in it }
                .map { it.first { n -> n != def.name } }.toSet()
            val mates = KID_ORDER.filter {
                it != def.name &&
                    factionOfCast(it) == factionOfCast(def.name) }
            check(crew.all { it in partners || it in mates },
                "rivalcrew: ${def.name}'s crew comes from " +
                    "their partners and faction mates only")
            // the partner tier LEADS: with three or more
            // kid partners the whole crew is partners; with
            // fewer, they all come first (adult partners
            // are never candidates — the crew is kids)
            val kidPartners = partners intersect CharacterSystem.CAST_KIDS
            check(if (kidPartners.size >= 3)
                    crew.all { it in kidPartners }
                else crew.take(kidPartners.size).toSet() ==
                    kidPartners,
                "rivalcrew: ${def.name}'s pair-script partners " +
                    "lead the crew — the authored double acts " +
                    "first ($kidPartners)")
            check(s.lifeText["rivalCrew"] ==
                crew.joinToString(","),
                "rivalcrew: ${def.name}'s crew is RECORDED in " +
                    "the save's own text, in the Rival pattern")
        }
        // chemistry orders INSIDE a tier: a partner with
        // a huge live bond leads the partner tier itself
        val sP = saveForRivalE("Cartman")
        calmE(sP, 41)
        Rival.playReveal(sP, 1)
        sP.npcBonds[engE2.bondKey("Cartman", "Wendy")] = 60
        check(RivalCrew.deriveCrew(sP)[0] == "Wendy",
            "rivalcrew: inside the partner tier, real " +
                "chemistry decides — the bonded partner " +
                "leads the crew")
        // ...and in the faction tier: Clyde has ONE kid
        // partner (Craig); a bonded faction mate takes
        // the first open slot behind him
        val s = saveForRivalE("Clyde")
        calmE(s, 41)
        Rival.playReveal(s, 1)
        val partnersC = PAIR_SCRIPTS.keys
            .filter { "Clyde" in it }
            .map { it.first { n -> n != "Clyde" } }
            .filter { it in CharacterSystem.CAST_KIDS }.toSet()
        val mate = KID_ORDER.first {
            it != "Clyde" && it !in partnersC &&
                factionOfCast(it) == factionOfCast("Clyde") }
        s.npcBonds[engE2.bondKey("Clyde", mate)] = 60
        val crewC = RivalCrew.deriveCrew(s)
        check(crewC[partnersC.size] == mate,
            "rivalcrew: inside the faction tier, real " +
                "chemistry decides — the bonded mate ($mate) " +
                "takes the first open slot")
        // determinism: the same creation identity derives
        // the same crew on a second, identical save
        val d1 = saveForRivalE("Wendy"); calmE(d1, 42)
        Rival.playReveal(d1, 1)
        val d2 = saveForRivalE("Wendy"); calmE(d2, 42)
        Rival.playReveal(d2, 1)
        check(RivalCrew.theirCrew(d1) == RivalCrew.theirCrew(d2),
            "rivalcrew: derivation is deterministic — the " +
                "same save grows the same crew twice")
        // stability: once recorded, moving bonds never
        // reshuffle the crew
        val before = RivalCrew.theirCrew(d1)
        d1.npcBonds[engE2.bondKey("Wendy", "Stan")] = 99
        d1.npcBonds[engE2.bondKey("Wendy", "Kyle")] = 99
        check(RivalCrew.theirCrew(d1) == before,
            "rivalcrew: a recorded crew is the crew — later " +
                "bonds don't re-derive it")
        // a pre-0.9.0e save (revealed, no crew keys) grows
        // the crew by the same rule on first consult — a
        // fresh identical save whose crew was never
        // consulted, stripped of every crew key anyway
        val legacySrc = saveForRivalE("Wendy")
        calmE(legacySrc, 42)
        Rival.playReveal(legacySrc, 1)
        val enc = encodeGameState(legacySrc).toMutableMap()
        enc["lifeText"] = (enc["lifeText"] as Map<String, Any?>)
            .filterKeys { !it.startsWith("rivalCrew") }
        enc["life"] = (enc["life"] as Map<String, Any?>)
            .filterKeys { !it.startsWith("rivalCrew") }
        val legacy = decodeGameState(enc)
        check(RivalCrew.theirCrew(legacy) == before,
            "rivalcrew: a pre-0.9.0e save derives their " +
                "crew from the recorded rival by the same rule")
        // before the crowning: no crew, no set, no page section
        val un = freshE("Unrevealed")
        calmE(un, 5)
        check(RivalCrew.theirCrew(un).isEmpty() &&
            RivalCrew.crewSet(un).isEmpty() &&
            RivalCrew.pageSection(un).none {
                it.contains("Theirs:") },
            "rivalcrew: before the crowning there is no " +
                "crew — the rivalry comes first")
        // turf: the rival's faction's own authored turf
        for (def in Rival.POOL) {
            val ts = saveForRivalE(def.name)
            calmE(ts, 43)
            Rival.playReveal(ts, 1)
            val want = FACTIONS.first {
                it.id == factionOfCast(def.name) }.turf.first()
            check(RivalCrew.turfOf(ts) == want,
                "rivalcrew: ${def.name}'s turf is their " +
                    "faction's ground ($want)")
        }
    }

    run {
        // ---------- the turf claim: rhythm + deference ----------
        val s = revealedE("Turf", 50)
        val set = RivalCrew.crewSet(s)
        check(set.size == 4, "rivalcrew: the set is the " +
            "captain plus three")
        var turfDay = -1
        for (d in 50..60) if ((d + Rival.saveSeed(s)) % 3 == 0) {
            turfDay = d; break }
        s.absDay = turfDay
        check(RivalCrew.turfDayToday(s), "rivalcrew: (fab) " +
            "a turf day by the seeded rhythm")
        for (n in set) {
            val blk = RivalCrew.gatheringBlock(s, n, 16 * 60)
            check(blk != null && blk.location ==
                RivalCrew.turfOf(s),
                "rivalcrew: on a turf afternoon, $n is " +
                    "claimed to the turf")
        }
        val engBlk = engE2.effectiveAgendaBlock(s,
            s.agents[set.first()]!!, 16 * 60)
        check(engBlk?.location == RivalCrew.turfOf(s),
            "rivalcrew: the Engine's agenda stack carries " +
                "the turf claim (after Fair, before Crew)")
        check(RivalCrew.gatheringBlock(s, set.first(),
                12 * 60) == null &&
            RivalCrew.gatheringBlock(s, "Mr. Garrison",
                16 * 60) == null,
            "rivalcrew: no claim outside the hours, and " +
                "none for anyone outside the four")
        s.absDay = turfDay + 1
        check(RivalCrew.gatheringBlock(s, set.first(),
                16 * 60) == null,
            "rivalcrew: the rhythm skips a day — the claim " +
                "is seeded, not daily")
        s.absDay = turfDay
        s.holidayId = "christmas"
        check(Emergencies.momentOwned(s) &&
            RivalCrew.gatheringBlock(s, set.first(),
                16 * 60) == null,
            "rivalcrew: a set piece owning the moment " +
                "dissolves the hangout entirely")
        s.holidayId = null
    }

    run {
        // ---------- cluster coexistence ----------
        check(Crowds.RIVAL_CREW_AFFINITY in 1 until
            Crowds.CREW_AFFINITY &&
            Crowds.RIVAL_CREW_AFFINITY >
            Crowds.FACTION_AFFINITY,
            "crowds: the rival crew's pull is its OWN number " +
                "(${Crowds.RIVAL_CREW_AFFINITY}) — under your " +
                "crew's ${Crowds.CREW_AFFINITY}, over a faction's")
        val mine = setOf("Stan", "Kyle", "Wendy", "Craig")
        val theirs = setOf("Cartman", "Butters", "Kenny",
            "Tweek")
        check(Crowds.affinity("Cartman", "Butters",
                Crowds.Chem(rivalCrew = theirs)) ==
            Crowds.RIVAL_CREW_AFFINITY &&
            Crowds.affinity("Stan", "Kyle",
                Crowds.Chem(crew = mine)) ==
            Crowds.CREW_AFFINITY &&
            Crowds.affinity("Kyle", "Tweek",
                Crowds.Chem(crew = mine, rivalCrew = theirs,
                    rivalPairs = setOf(setOf("Kyle",
                        "Tweek")))) == Crowds.RIVAL_BLOCK,
            "crowds: each crew's affinity reads off its own " +
                "set, and an arch-rival pair ACROSS the crews " +
                "still blocks (neither set contains both)")
        check(Crowds.affinity("Cartman", "Kenny",
                Crowds.Chem(rivalCrew = theirs,
                    rivalPairs = setOf(setOf("Cartman",
                        "Kenny")))) > 0,
            "crowds: inside their crew, the standing pull " +
                "outranks a grudge — same rule as yours")
        // both formations in ONE crowd of twenty: each
        // forms its own cluster of four, and the row math
        // (MIN_SEP, span) holds with both affinities live
        val present = (mine + theirs +
            (KID_ORDER - mine - theirs).take(12)).sorted()
        val chem = Crowds.Chem(
            scriptPairs = PAIR_SCRIPTS.keys.filter { p ->
                p.all { it in mine } || p.all { it in theirs }
            }.toSet(),
            factionOf = FACTION_OF_CAST.filterKeys {
                it in present },
            crew = mine, rivalCrew = theirs)
        val layout = Crowds.layout(present, chem)
        check(layout != null, "crowds: (fab) twenty present, " +
            "two crews crossing")
        val placed = layout!!.placed
        val mineIds = placed.filter { it.name in mine }
            .map { it.clusterId }.distinct()
        val theirIds = placed.filter { it.name in theirs }
            .map { it.clusterId }.distinct()
        check(mineIds.size == 1 && mineIds[0] >= 0 &&
            placed.count { it.clusterId == mineIds[0] } == 4 &&
            theirIds.size == 1 && theirIds[0] >= 0 &&
            placed.count { it.clusterId == theirIds[0] } == 4 &&
            mineIds[0] != theirIds[0],
            "crowds: your four stand as ONE cluster and " +
                "their four as ANOTHER, in the same crowd")
        val rowsOk = placed.groupBy { it.frontness }
            .values.all { row ->
                val xs = row.map { it.xFrac }.sorted()
                xs.zipWithNext().all { (a, b) ->
                    b - a >= Crowds.MIN_SEP - 0.001f } &&
                    (xs.last() - xs.first()) <= 0.94f + 0.001f
            }
        check(rowsOk, "crowds: MIN_SEP and the span hold " +
            "in every row with both crews present")
        // and at the FULL ninety-eight, with the real tables:
        // the guarantees are the layout's, whoever stands
        // (KID_ORDER is the full cast list, kids first)
        val all = KID_ORDER
        val chemAll = Crowds.Chem(
            bond = emptyMap(),
            scriptPairs = PAIR_SCRIPTS.keys.filter { p ->
                p.all { it in all } }.toSet(),
            rivalPairs = emptySet(),
            factionOf = FACTION_OF_CAST,
            crew = mine, rivalCrew = theirs)
        val big = Crowds.layout(all, chemAll)
        check(big != null && big.placed.size == 98,
            "crowds: the full ninety-eight still lays out with " +
                "both crew affinities live")
        val bigOk = big!!.placed.groupBy { it.frontness }
            .values.all { row ->
                val xs = row.map { it.xFrac }.sorted()
                xs.zipWithNext().all { (a, b) ->
                    b - a >= Crowds.MIN_SEP - 0.001f } &&
                    (xs.last() - xs.first()) <= 0.94f + 0.001f
            }
        check(bigOk, "crowds: MIN_SEP and the span hold " +
            "at 98 cast with the crews crossing paths " +
            "(seven rows at wave 6's census — the perRow-14 " +
            "geometry the five-row rule proved at 70)")
    }

    run {
        // ---------- offers: rail, deference, decline ----------
        // v0.11.0d: this seed's crown changed with the pool's
        // ninth seat — Kyle at eight, Cartman at nine — and
        // Cartman fronts the boys' crew chain, whose
        // FACTION_MISSION rail honestly outranks a crew offer
        // in the gate's ladder. The routing premise needs a
        // rival with no higher rail live, so the fabrication
        // takes a Kyle-crowning identity (the section's own
        // saveForRivalE idiom) and reveals him the usual way.
        val s = saveForRivalE("Kyle")
        calmE(s, 60)
        Rival.playReveal(s, 1)   // called it even
        RivalCrew.theirCrew(s)
        s.life["rivalCrewNextDay"] = s.absDay
        check(RivalCrew.offerDue(s), "rivalcrew: (fab) a " +
            "crew challenge is due")
        val hit = Rival.talkStepFor(s, Rival.rivalOf(s))
        check(hit?.kind == "crewoffer" &&
            hit.offerKind in listOf(RivalCrew.K_CREW_RELAY,
                RivalCrew.K_CREW_PHOTO),
            "rivalcrew: the due crew challenge surfaces on " +
                "the RIVAL rail (clear sky: relay or photo)")
        check(TalkGate.gateFor(s, Rival.rivalOf(s),
                engE2.player(s).location).rail ==
            TalkGate.Rail.RIVAL,
            "rivalcrew: the gate routes it to the RIVAL " +
                "rail — no new rail was minted")
        s.holidayId = "christmas"
        check(Rival.talkStepFor(s, Rival.rivalOf(s)) == null,
            "rivalcrew: deference is the solo contests' own " +
                "— a set piece owning the moment silences " +
                "the crew offer too")
        s.holidayId = null
        val before = RivalCrew.nextCrewDay(s)
        RivalCrew.decline(s)
        check(RivalCrew.nextCrewDay(s) in
            (s.absDay + RivalCrew.DECLINE_CREW_GAP)..
            (s.absDay + RivalCrew.DECLINE_CREW_GAP + 2) &&
            RivalCrew.nextCrewDay(s) > before - 1 &&
            Rival.contestsPlayed(s) == 0,
            "rivalcrew: declining is free — a few days' " +
                "peace, nothing on any board")
        // the showdown bracket honestly needs snow
        val snowy = revealedE("Snowy", 61)
        snowy.weatherId = "heavy_snow"
        val kinds = (0..13).map { d ->
            snowy.absDay = 200 + d
            RivalCrew.offerKindFor(snowy) }
        val clear = revealedE("ClearSky", 62)
        val clearKinds = (0..13).map { d ->
            clear.absDay = 200 + d
            RivalCrew.offerKindFor(clear) }
        check(RivalCrew.K_CREW_SHOWDOWN in kinds &&
            RivalCrew.K_CREW_SHOWDOWN !in clearKinds &&
            clearKinds.all { it in RivalCrew.CREW_KINDS },
            "rivalcrew: the bracket is offered under snow " +
                "and never under a clear sky — the solo " +
                "showdown's own honesty")
    }

    run {
        // ---------- the no-crew gate ----------
        val s = revealedE("NoCrew", 70)
        RivalCrew.theirCrew(s)
        check(Crew.members(s).isEmpty(), "rivalcrew: (fab) " +
            "the player has no crew")
        val text = RivalCrew.offerText(s,
            RivalCrew.K_CREW_RELAY, false)
        check(text.contains("You don't HAVE a crew"),
            "rivalcrew: the offer says it in the rival's " +
                "voice — you need a crew of your own first")
        val acc = RivalCrew.accept(s,
            RivalCrew.K_CREW_RELAY, false)
        check(acc.waited && !acc.startDuel &&
            !RivalCrew.crewBusy(s) &&
            RivalCrew.seasonPlayed(s) == 0 &&
            Rival.contestsPlayed(s) == 0,
            "rivalcrew: accepting with no crew arms " +
                "nothing, records nothing — it just waits")
        check(RivalCrew.crewSet(s).size == 4 &&
            RivalCrew.gatheringBlock(s,
                RivalCrew.theirCrew(s)[0], 16 * 60) != null ||
            RivalCrew.crewSet(s).size == 4,
            "rivalcrew: their crew exists and roams " +
                "regardless of yours")
        // solo contests continue unchanged: the solo offer
        // machinery is untouched by the crew layer
        s.life["rivalNextDay"] = s.absDay
        val soloHit = Rival.talkStepFor(s, Rival.rivalOf(s))
        check(soloHit == null || soloHit.kind in
            listOf("offer", "crewoffer"),
            "rivalcrew: the solo rail still answers on its " +
                "own day beside the crew layer")
    }

    run {
        // ---------- fielding, the frenemy, the conflicted ----------
        val s = revealedE("Field", 80)
        val mine = giveCrewE(s)
        val f = RivalCrew.fielding(s)
        check(f.youHaveCrew && f.you.size == 3 &&
            f.them.size == 3 && !f.frenemy &&
            RivalCrew.canField(f),
            "rivalcrew: a full free crew fields three a " +
                "side at a calm hour (${f.blockers})")
        // the frenemy: the rival IN your crew captains
        // theirs and does not count on yours
        val fs = revealedE("Frenemy", 81)
        val rivalF = Rival.rivalOf(fs)
        val othersF = KID_ORDER.filter {
            it != rivalF && it !in RivalCrew.theirCrew(fs) }
            .take(2)
        fs.lifeText["crew:members"] =
            (listOf(rivalF) + othersF).joinToString(",")
        val ff = RivalCrew.fielding(fs)
        check(ff.frenemy && rivalF !in ff.you &&
            ff.you == othersF && RivalCrew.canField(ff),
            "rivalcrew: FRENEMY — $rivalF captains their " +
                "own side; your side fields who you have")
        check(RivalCrew.offerText(fs,
                RivalCrew.K_CREW_RELAY, false)
                .contains("BRACKET INTEGRITY"),
            "rivalcrew: the offer STATES the frenemy rule " +
                "out loud before anyone accepts")
        // under three available: the contest waits, plainly
        val us = revealedE("Short", 82)
        val rivalU = Rival.rivalOf(us)
        val one = KID_ORDER.first {
            it != rivalU && it !in RivalCrew.theirCrew(us) }
        us.lifeText["crew:members"] =
            listOf(rivalU, one).joinToString(",")
        val accU = RivalCrew.accept(us,
            RivalCrew.K_CREW_RELAY, false)
        check(accU.waited && !RivalCrew.crewBusy(us) &&
            RivalCrew.seasonPlayed(us) == 0,
            "rivalcrew: with the rival captaining against " +
                "you, one free crewmate is not a side — " +
                "the contest waits, never silently stacked")
        // a kid in BOTH crews sits it out, and is named
        val cs = revealedE("Both", 83)
        val shared = RivalCrew.theirCrew(cs)[0]
        val rest = KID_ORDER.filter {
            it != Rival.rivalOf(cs) &&
                it !in RivalCrew.theirCrew(cs) }.take(3)
        cs.lifeText["crew:members"] =
            (listOf(shared) + rest).joinToString(",")
        val fc = RivalCrew.fielding(cs)
        check(shared !in fc.you && shared !in fc.them &&
            fc.blockers.any { it.contains("BOTH crews") },
            "rivalcrew: $shared is in both crews and sits " +
                "the contest out — named in the blockers")
        // occupied honesty: a busy crewmate is a named
        // blocker, priced by Crew.busyReason itself — a
        // school morning fields nobody, and says why
        val bs = revealedE("Busy", 84)
        val bm = giveCrewE(bs)
        check(bm.all { Crew.busyReason(bs, it) == null },
            "rivalcrew: (fab) the calm hour fields everyone")
        var schoolDay = -1
        for (d in 200..220) if (School.isSchoolDay(d)) {
            schoolDay = d; break }
        bs.absDay = schoolDay
        bs.timeMin = 10 * 60   // mid-class
        val fb = RivalCrew.fielding(bs)
        check(fb.you.size < 3 && fb.them.size < 3 &&
            fb.blockers.isNotEmpty(),
            "rivalcrew: on a school morning the fielding " +
                "collapses and the blockers SAY why — " +
                "occupied is occupied, both sides")
    }

    run {
        // ---------- the relay: priced legs, real clock ----------
        check(RivalCrew.paceHalfOf("Cartman") ==
            Rival.defOf("Cartman")!!.paceHalf &&
            RivalCrew.paceHalfOf("Butters") % 2 != 0,
            "rivalcrew: pool kids run on their authored " +
                "pace; everyone else's derives odd from " +
                "their authored dodge (the tie-proof rule)")
        val s = revealedE("Relay", 90)
        val mine = giveCrewE(s)
        engE2.player(s).location = "BusStop"
        for (n in mine) s.agents[n]?.location = "KidsPark"
        val soloNext = 4242
        s.life["rivalNextDay"] = soloNext
        val played0 = Rival.contestsPlayed(s)
        val acc = RivalCrew.accept(s,
            RivalCrew.K_CREW_RELAY, false)
        check(!acc.waited && RivalCrew.relayLive(s),
            "rivalcrew: accepting the relay starts your " +
                "anchor leg on the real clock")
        val to = s.lifeText["rivalCrewRaceTo"]!!
        check(Walk.routeMinutes(s, "BusStop", to) >=
            Rival.RACE_MIN_ROUTE,
            "rivalcrew: the relay target is honestly far " +
                "(the solo race's own minimum route)")
        s.timeMin += 25
        val text = RivalCrew.raceArrival(s, to)
        check(text != null && !RivalCrew.relayLive(s) &&
            RivalCrew.seasonPlayed(s) == 1 &&
            Rival.contestsPlayed(s) == played0 + 1,
            "rivalcrew: arriving settles the relay ONCE — " +
                "standings +1, solo ledger +1, arm cleared")
        check(RivalCrew.pointsYou(s) +
            RivalCrew.pointsThem(s) == 2,
            "rivalcrew: a relay win is worth 2 standings " +
                "points across both sides (no draw priced " +
                "here: ${RivalCrew.crewsScoreLine(s)})")
        check(s.life["rivalNextDay"] == soloNext,
            "rivalcrew: the crew settle lands on the board " +
                "WITHOUT shoving the solo challenge calendar")
        check(RivalCrew.raceArrival(s, to) == null,
            "rivalcrew: the finish line answers once")
        // the fairness matrix: every rival, a mediocre
        // anchor leg (the route's own minutes + 2 of
        // dawdling) — their crew must win a real share.
        // Both crews stand SCATTERED, the way their lives
        // leave them across town (a fresh state's bus-stop
        // pile-up would price every leg off one spot and
        // turn the race into a pure pace-sum, which is
        // nobody's race); positions dominate, pace flavors.
        val spread = listOf("StarksPond", "Mall", "Church",
            "CityHall", "TegridyFarms", "JimbosGuns",
            "SkeetersBar", "KidsPark", "Elementary",
            "CartmanHouse", "StanHouse", "KyleHouse")
        var themWins = 0; var youWins = 0; var races = 0
        for (def in Rival.POOL) {
            for (variant in 0..2) {
                val fs2 = saveForRivalE(def.name)
                calmE(fs2, 100 + variant * 7)
                Rival.playReveal(fs2, 1)
                val mineF = giveCrewE(fs2)
                engE2.player(fs2).location = "BusStop"
                mineF.forEachIndexed { i, n ->
                    fs2.agents[n]?.location =
                        spread[(variant * 3 + i) % spread.size] }
                val theirSide = listOf(def.name) +
                    RivalCrew.theirCrew(fs2)
                theirSide.forEachIndexed { i, n ->
                    fs2.agents[n]?.location = spread[
                        (variant * 3 + 5 + i) % spread.size] }
                val a2 = RivalCrew.accept(fs2,
                    RivalCrew.K_CREW_RELAY, false)
                if (a2.waited) continue
                val to2 = fs2.lifeText["rivalCrewRaceTo"]!!
                val start = fs2.timeMin
                fs2.timeMin = start +
                    Walk.routeMinutes(fs2, "BusStop", to2) + 2
                val before2 = RivalCrew.pointsThem(fs2)
                RivalCrew.raceArrival(fs2, to2)
                races++
                if (RivalCrew.pointsThem(fs2) > before2)
                    themWins++ else youWins++
            }
        }
        check(races >= 20 && themWins > 0 && youWins > 0 &&
            themWins.toDouble() / races in 0.15..0.85,
            "rivalcrew: RELAY FAIRNESS — over $races " +
                "mediocre-anchor relays their crew took " +
                "$themWins, yours $youWins (a real share, " +
                "never a walkover either way)")
    }

    run {
        // ---------- the photo showdown ----------
        val s = revealedE("Photo", 110)
        val mine = giveCrewE(s)
        val acc = RivalCrew.accept(s,
