            appearance = DEFAULT_APPEARANCE,
            figures = listOf(figE("Walker", "player"),
                figE(mine[0]), figE("Mr. Garrison")),
            composition = "lineup", absDay = 110)
        RivalCrew.onPhoto(s, thin)
        check(RivalCrew.seasonPlayed(s) == 0,
            "rivalcrew: one fielded crewmate in frame is " +
                "not a crew photo — the arm honestly waits")
        // the real thing: your crew at the turf, posed
        val frame = PhotoRecord(id = "pc3", dayKey = "20270210",
            dateLabel = "2/10", timeMin = 960, locId = turf,
            inside = false, weatherId = "clear",
            appearance = DEFAULT_APPEARANCE,
            figures = listOf(figE("Walker", "player"),
                figE(mine[0], pose = "backToBack"),
                figE(mine[1], pose = "backToBack"),
                figE(mine[2], reaction = Photos.GOOFY)),
            composition = "lineup", absDay = 110)
        val yourScore = Yearbook.scoreOf(Yearbook.CAT_GROUP,
