        check(yourScore == 12 * 3 + 6 * 1 + 3 * 1,
            "rivalcrew: your frame scores by the yearbook's " +
                "own group math (12 a head, 6 a posed pair, " +
                "3 a goofy face) — no shadow scale")
        RivalCrew.onPhoto(s, frame)
        check(RivalCrew.seasonPlayed(s) == 1 &&
            RivalCrew.crewPending(s).isEmpty() &&
            Rival.contestsPlayed(s) == played0 + 1,
            "rivalcrew: the qualifying frame settles the " +
                "showdown ONCE — standings and ledger agree")
        // their scale: same fields, rolled from real
        // chemistry — a fair fight against a decent frame
        val side = RivalCrew.crewSet(s).toList()
        var theirWins = 0; var trials = 0
        for (seed in 1..400L) {
            val sc = RivalCrew.theirPhotoScore(s, side, seed)
            if (sc > 57) theirWins++
            trials++
        }
        check(theirWins.toDouble() / trials in 0.2..0.8,
            "rivalcrew: PHOTO FAIRNESS — their rolled frame " +
                "beats a solid 57-point frame in " +
                "${theirWins * 100 / trials}% of 400 rolls " +
                "(same scale, real chemistry, honest jitter)")
        val range = (1..400L).map {
            RivalCrew.theirPhotoScore(s, side, it) }
        check(range.min() >= 48 && range.max() <= 84,
            "rivalcrew: their frame lives on the yearbook " +
                "scale's own ground (48 floor for four " +
                "heads, 84 the ceiling the fields allow)")
    }

    run {
