        val evenShare = (1..300L).count { seed ->
            RivalCrew.simDuel("Stan", "Kyle",
                yoursFirst = seed % 2L == 0L, seed = seed) }
            .toDouble() / 300
        check(evenShare in 0.35..0.65,
