    run {
        // ---------- standings, the final, season close ----------
        val s = revealedE("Season", 130)
        giveCrewE(s)
        RivalCrew.dailyRollover(s)   // stamps the season
        check(RivalCrew.seasonStored(s) ==
            RivalCrew.seasonOf(s),
            "rivalcrew: the standings anchor to the school " +
                "year (the yearbook's June-to-May rhythm)")
        val coins0 = Minigames.capsuleCoins(s)
        val played0 = Rival.contestsPlayed(s)
        RivalCrew.settleCrewContest(s,
            RivalCrew.K_CREW_RELAY, "you", "suite leg", false)
        RivalCrew.settleCrewContest(s,
            RivalCrew.K_CREW_PHOTO, "draw", "suite frame",
            false)
        check(RivalCrew.pointsYou(s) == 3 &&
            RivalCrew.pointsThem(s) == 1 &&
            RivalCrew.seasonPlayed(s) == 2 &&
            Rival.contestsPlayed(s) == played0 + 2,
            "rivalcrew: bookkeeping — a win is 2, a draw 1 " +
                "each, and each settle lands on the solo " +
                "ledger exactly once")
        check(Minigames.capsuleCoins(s) == coins0 &&
            s.showdown.isEmpty(),
            "rivalcrew: crew contests move standings and " +
                "the ledger ONLY — no coins, no duel record, " +
                "no economy")
        check("the crews" in (NpcMemoryStore
                .get(Rival.rivalOf(s))?.topics
                ?: emptyList()),
            "rivalcrew: a settle plants 'the crews' on " +
                "the participants — the town gets its topic")
        check(NpcMemoryStore.topicWords("the crews").size >= 3,
            "rivalcrew: 'the crews' is a registered topic " +
                "tag (the Threads pattern)")
        val goss = RivalCrew.gossipLine(s, "Mr. Garrison")
        check(goss != null && goss.text.contains(
                RivalCrew.crewsScoreLine(s)),
            "rivalcrew: a bystander's owed line quotes " +
                "the REAL standings sentence, verbatim")
        check(RivalCrew.gossipLine(s, "Mr. Garrison") == null &&
            RivalCrew.gossipLine(s, Rival.rivalOf(s)) == null,
            "rivalcrew: gossip is once a day per carrier, " +
                "and participants don't gossip about themselves")
        val page = Rival.pageLines(s)
        check(page.any { it.contains("THE CREWS") } &&
            page.any { it.contains("Theirs:") } &&
            page.any { it.contains("Yours:") },
            "rivalcrew: the 🆚 page carries the crews " +
                "section with both rosters")
        // the final: last three weeks, season played, due
        s.gameYear = 2027; s.gameMonth = 5; s.gameDay = 20
        s.todayKey = "20270520"
        check(RivalCrew.daysLeftInSchoolYear(s) == 11,
            "rivalcrew: (fab) eleven days of school year left")
        s.life["rivalCrewNextDay"] = s.absDay
        check(RivalCrew.finalDue(s), "rivalcrew: the " +
            "final is due — season played, year nearly " +
            "out, challenge day reached")
        val fHit = Rival.talkStepFor(s, Rival.rivalOf(s))
        check(fHit?.kind == "crewoffer" && fHit.crewFinal,
            "rivalcrew: the final takes the rail as a crew " +
                "offer, flagged — and outranks the solo day")
        val mercy0 = Rival.mercies(s)
        val stanceText = RivalCrew.playFinalStance(s, 2)
        check(Rival.mercies(s) == mercy0 + 1 &&
            stanceText.isNotBlank(),
            "rivalcrew: the captains' beat plays — your " +
                "stance answers on the standing ledgers, " +
                "the established pattern")
        val py = RivalCrew.pointsYou(s)
        val pt = RivalCrew.pointsThem(s)
        RivalCrew.settleCrewContest(s,
            RivalCrew.K_CREW_SHOWDOWN, "you",
            "suite final", true)
        check(RivalCrew.pointsYou(s) == py + 4 &&
            RivalCrew.pointsThem(s) == pt &&
            RivalCrew.finalPlayedSeason(s) == 2027,
            "rivalcrew: the final is worth DOUBLE — 4 " +
                "points for the win, and the season's final " +
                "is marked played")
        check(!RivalCrew.finalDue(s), "rivalcrew: one " +
            "final a season — after it, no second crown")
        // the turn: June 1 closes the book into one line
        s.gameYear = 2027; s.gameMonth = 6; s.gameDay = 1
        s.todayKey = "20270601"; s.absDay += 12
        RivalCrew.dailyRollover(s)
        val hist = RivalCrew.historyLines(s)
        check(hist.size == 1 && hist[0].contains("2026–27") &&
            hist[0].contains("final played") &&
            RivalCrew.pointsYou(s) == 0 &&
            RivalCrew.seasonPlayed(s) == 0 &&
            RivalCrew.seasonStored(s) == 2028,
            "rivalcrew: the season closes into ONE history " +
                "line and the new book opens blank")
        // history is capped: four elders and no more
        s.lifeText["rivalCrewHistory"] =
            (1..4).map { "line$it" }.joinToString(";")
        s.life["rivalCrewSeason"] = 2028
        s.life["rivalCrewPtsYou"] = 5
        s.life["rivalCrewSeasonPlayed"] = 3
        s.gameYear = 2028; s.gameMonth = 6; s.gameDay = 1
        s.todayKey = "20280601"; s.absDay += 365
        RivalCrew.dailyRollover(s)
        check(RivalCrew.historyLines(s).size == 4,
            "rivalcrew: past seasons stay one line each, " +
                "four deep — the shelf doesn't grow")
        // stale arms lapse free, like the solo contests'
        val ls = revealedE("Lapse", 140)
        giveCrewE(ls)
        RivalCrew.accept(ls, RivalCrew.K_CREW_PHOTO, false)
        check(RivalCrew.crewPending(ls) ==
            RivalCrew.K_CREW_PHOTO, "rivalcrew: (fab) armed")
        ls.absDay += Rival.PENDING_LAPSE_DAYS + 1
        RivalCrew.dailyRollover(ls)
        check(RivalCrew.crewPending(ls).isEmpty() &&
            RivalCrew.seasonPlayed(ls) == 0,
            "rivalcrew: an armed crew contest left hanging " +
                "lapses free — nothing recorded, ever")
        // the whole state of the crews round-trips a save
        val enc2 = encodeGameState(s)
        val dec2 = decodeGameState(enc2)
        check(RivalCrew.theirCrew(dec2) ==
            RivalCrew.theirCrew(s) &&
            RivalCrew.historyLines(dec2) ==
            RivalCrew.historyLines(s) &&
            RivalCrew.seasonStored(dec2) == 2029,
            "rivalcrew: crew, standings and history all " +
                "survive a save round-trip")
    }
    } finally {
        NpcMemoryStore.deserialize(memSnapshotE2)
    }
}


// ================= v0.9.0f: mystery #7 — the case told backwards =================
// Queue #9 item 6. The seventh case is a seventh shape: it
// opens with its own ending (a public taking, witnessed
// cold), investigates in REVERSE story-time (the taking,
// the night before, the ledger, the fire winter), and
// keeps its board as a TIMELINE in true chronological
// order, filled in backwards. Each movement is COMMITTED
// as a reconstruction (easy or checked reading); verdicts
// are DERIVED from the recorded inputs (commits, evidence
// in hand, chapters begun) and recomputed here against
// the suite's own math over the whole subset space. Two
// pieces are context-locked — held inert, unspendable —
// until their chapter; the suite proves an inert piece
// cannot be spent: it counts toward nothing, confirms
// nothing, breaks nothing. The confrontation's own
// reconstruction is committed first, on the least
// evidence, and MUST break when the ledger surfaces.
// The finale (the homecoming: the confrontation again)
// gates its calls on the FINAL state of the timeline.
private fun sectionV090f(root: String) {
    println("== v0.9.0f: mystery #7 — the case told backwards ==")
    val eng7 = Engine(720)

    // ---------- the chapter defs ----------
    val ch7 = Mystery7.CHAPTERS7
    check(ch7.size == 4 && ch7.map { it.id }.toSet().size == 4,
        "backwards: the case is four chapters, uniquely id'd")
    check(ch7[3].id == Mystery7.FINALE7_ID,
        "backwards: the fourth chapter is the finale — the beginning, with the homecoming at its climax")
    check(ch7.all { it.theme.icon.isNotBlank() &&
        it.theme.header.isNotBlank() && it.causers.isNotEmpty() },
        "backwards: every chapter carries its theme and its credited causers")
    check(ch7.all { d -> d.stages.size == 4 && d.episodeTitles.size == 2 &&
        d.coldOpen.size == 2 && d.coldOpen.all { it.text.isNotBlank() } },
        "backwards: every chapter carries the full episode kit")
    check(ch7.none { d -> SHENANIGANS.any { it.id == d.id } },
        "backwards: no chapter sits in the random event pool")
    check(ch7.all { Mystery7.CHAPTER7_BY_ID[it.id] == it &&
        SHENANIGAN_BY_ID[it.id] == it },
        "backwards: every chapter resolves by id, in the case and in the game")
    check(ch7[0].stages.any { it.clusterLoc == "Elementary" } &&
        ch7[1].stages.any { it.clusterLoc == "KennysHouse" } &&
        ch7[2].stages.any { it.clusterLoc == "CityHall" } &&
        ch7[3].stages.any { it.clusterLoc == "Elementary" },
        "backwards: the chapters walk the assembly, the trailer, the archive, and back to the school")
    val finDef7 = Mystery7.CHAPTER7_BY_ID[Mystery7.FINALE7_ID]!!
    check(finDef7.causers.containsAll(listOf("Sheila", "Carol")),
        "backwards: the homecoming is played by the taker and the keeper")

    // ---------- the movements ----------
    val mv7 = Mystery7.MOVEMENTS7
    check(mv7.size == 4 && mv7.map { it.index } == listOf(0, 1, 2, 3),
        "backwards: four movements, declared in true chronological order")
    check(Mystery7.FILL_ORDER7.map { it.index } == listOf(3, 2, 1, 0),
        "backwards: the fill order is the exact reverse — the taking first, the beginning last")
    check(mv7.all { it.easy != it.checked && it.evidenceNeeded == 2 },
        "backwards: every movement offers two distinct readings at the same price")
    check(mv7.all { m ->
        val breaker = Mystery7.CLUE7_BY_ID[m.easyBrokenBy]
        val confirmer = Mystery7.CLUE7_BY_ID[m.checkedConfirmBy]
        breaker != null && confirmer != null &&
            breaker.movement <= m.index && confirmer.movement <= m.index },
        "backwards: every reading is tested by a piece from its own movement or an EARLIER one — the past tests the present, never the reverse")
    check(Mystery7.CLUE7_BY_ID[mv7[3].easyBrokenBy]?.movement == 1,
        "backwards: THE STING — the confrontation's easy reading is broken by a piece from the ledger movement, two movements deeper in the past")

    // ---------- the evidence registry ----------
    val clues7 = Mystery7.CLUES7
    check(clues7.size == 12 && Mystery7.CLUE7_IDS.size == 12,
        "backwards: the evidence is twelve pieces")
    check(clues7.count { it.kind == Mystery7.Kind7.WITNESS } == 5 &&
        clues7.count { it.kind == Mystery7.Kind7.LOOK } == 5 &&
        clues7.count { it.kind == Mystery7.Kind7.PARTICIPATION } == 2,
        "backwards: the verbs run 5 witness / 5 look / 2 participation")
    check((0..3).all { idx -> clues7.count { it.movement == idx } == 3 },
        "backwards: three pieces are tagged to every movement")
    check(clues7.all { c -> c.minChapter in 0..3 &&
        c.unlockChapter in c.minChapter..3 &&
        when (c.kind) {
            Mystery7.Kind7.WITNESS ->
                c.npc != null && c.npc in AGENT_PROFILES &&
                    !c.spoken.isNullOrBlank()
            Mystery7.Kind7.LOOK ->
                c.locId != null && c.locId in LOCATIONS &&
                    !c.foundText.isNullOrBlank()
            Mystery7.Kind7.PARTICIPATION ->
                c.chapterDefId != null &&
                    c.chapterDefId in Mystery7.CHAPTER7_BY_ID
        } },
        "backwards: every piece names a real witness, place, or chapter")
    val locked7 = clues7.filter { it.unlockChapter > it.minChapter }
    check(locked7.map { it.id }.toSet() ==
        setOf("daybook_line", "carbon_receipt") &&
        locked7.all { it.inertDetail != it.detail && it.inertDetail.isNotBlank() },
        "backwards: exactly two pieces are context-locked, each with an honest inert face")

    // ---------- independent recomputation (the suite's own math) ----------
    fun recompLive(s: GameState): Set<String> =
        Mystery7.CLUES7.filter {
            it.id in s.mystery7Clues && s.arc7Chapter > it.unlockChapter
        }.map { it.id }.toSet()
    fun recompVerdict(s: GameState, m: Mystery7.Movement7): String {
        val pick = s.arc7Commits[m.id] ?: return "OPEN"
        val live = recompLive(s)
        return when {
            pick == "easy" && m.easyBrokenBy in live -> "BROKEN"
            pick == "checked" && m.checkedConfirmBy in live -> "CONFIRMED"
            else -> "COMMITTED"
        }
    }
    var sweepOk = true
    for (mask in 0 until (1 shl clues7.size)) {
        val s = eng7.newState()
        s.arc7Chapter = 4
        clues7.forEachIndexed { i, c ->
            if (mask shr i and 1 == 1) s.mystery7Clues.add(c.id)
        }
        for (m in mv7) {
            s.arc7Commits[m.id] =
                if ((mask + m.index) % 2 == 0) "easy" else "checked"
            if (Mystery7.verdict7(s, m) != recompVerdict(s, m)) sweepOk = false
            if (Mystery7.liveEvidence7(s, m) !=
                recompLive(s).count {
                    Mystery7.CLUE7_BY_ID[it]!!.movement == m.index })
                sweepOk = false
        }
        if (Mystery7.liveClueIds7(s) != recompLive(s)) sweepOk = false
    }
    check(sweepOk,
        "backwards: verdicts and live-evidence counts recompute exactly over all 4096 evidence subsets")
    var lockOk = true
    for (ch in 0..5) for (c in locked7) {
        val s = eng7.newState()
        s.arc7Chapter = ch
        s.mystery7Clues.add(c.id)
        if (Mystery7.clueLive7(s, c) != (ch > c.unlockChapter)) lockOk = false
    }
    check(lockOk,
        "backwards: a locked piece is live exactly when its context chapter has begun — at every chapter boundary")

    // ---------- context-locking: an inert piece cannot be spent ----------
    val sInert = eng7.newState()
    sInert.arc7Started = true; sInert.arc7Chapter = 2
    check(Mystery7.grantClue7(sInert, "daybook_line") &&
        !Mystery7.grantClue7(sInert, "daybook_line"),
        "backwards: a piece is granted exactly once, even an unreadable one")
    check("daybook_line" in sInert.mystery7Clues &&
        !Mystery7.clueLive7(sInert,
            Mystery7.CLUE7_BY_ID["daybook_line"]!!),
        "backwards: the day-book line is IN HAND in chapter 2 and honestly inert")
    sInert.arc7Commits["m0"] = "easy"   // storage-level fab: a hasty beginning
    check(Mystery7.verdict7(sInert, mv7[0]) == "COMMITTED",
        "backwards: an inert breaker breaks NOTHING — the hasty beginning stands untested while its refutation is unreadable")
    check(Mystery7.liveEvidence7(sInert, mv7[0]) == 0,
        "backwards: an inert piece counts toward NO movement's price")
    sInert.arc7Chapter = 3
    check(Mystery7.clueLive7(sInert,
            Mystery7.CLUE7_BY_ID["daybook_line"]!!) &&
        Mystery7.verdict7(sInert, mv7[0]) == "BROKEN",
        "backwards: the SAME piece, never re-granted, turns testimony-grade when its context chapter begins — and the hasty line breaks on arrival")

    // ---------- scheduling: the seventh case queues behind the sixth ----------
    val sGate7 = eng7.newState()
    check(Mystery7.dueChapter7(sGate7) == null && sGate7.arc7DueAbsDay < 0,
        "backwards: while the sixth case is open this one does not even book a date")
    sGate7.arc6Retired = true; sGate7.arc6RetiredDay = 40
    sGate7.absDay = 45
    check(Mystery7.dueChapter7(sGate7) == null && sGate7.arc7DueAbsDay == 50,
        "backwards: chapter one books ten days out from the sixth case's retirement")
    sGate7.absDay = 50
    check(Mystery7.dueChapter7(sGate7)?.id == ch7[0].id,
        "backwards: chapter one is due on its day")
    Mystery7.noteChapterStarted7(sGate7, ch7[0])
    check(sGate7.arc7Started && sGate7.arc7Chapter == 1 &&
        sGate7.arc7DueAbsDay == 57,
        "backwards: chapter one books chapter two a week out")
    sGate7.absDay = 57
    sGate7.holidayId = "some_holiday"
    check(Mystery7.dueChapter7(sGate7) == null,
        "backwards: a holiday defers the chapter — holidays keep their day")
    sGate7.holidayId = null
    check(Mystery7.dueChapter7(sGate7)?.id == ch7[1].id,
        "backwards: chapter two is due on its day, a week after the first")

    // ---------- the play-through: fill the timeline backwards ----------
    val s = eng7.newState()
    s.arc6Retired = true; s.arc6RetiredDay = 0; s.absDay = 10
    val d1 = Mystery7.dueChapter7(s)!!
    Mystery7.noteChapterStarted7(s, d1)
    check(Mystery7.pendingCommit7(s) == null,
        "backwards: nothing can be committed on applause alone — the scene is not evidence")
    check(Mystery7.witnessLine7(s, "Kyle") != null &&
        Mystery7.witnessLine7(s, "Kyle") == null,
        "backwards: the son's telling is granted exactly once")
    check(Mystery7.lookClueText7(s, "Elementary") != null,
        "backwards: the sign-in book is found by Looking where it hangs")
    Mystery7.noteParticipation7(s, ch7[1].id)
    check("thirty_witnesses" !in s.mystery7Clues,
        "backwards: hands at the WRONG chapter's turf turn up nothing")
    Mystery7.noteParticipation7(s, ch7[0].id)
    check("thirty_witnesses" in s.mystery7Clues,
        "backwards: hands-on at the assembly grants its piece")
    check(Mystery7.pendingCommit7(s)?.id == "m3",
        "backwards: the first committable movement is the confrontation itself")
    check(!Mystery7.chooseCommit7(s, "m2", "easy"),
        "backwards: a later movement cannot be written before the confrontation — the fill order is enforced")
    check(Mystery7.chooseCommit7(s, "m3", "easy") &&
        Mystery7.verdict7(s, mv7[3]) == "COMMITTED",
        "backwards: the easy reading of the taking commits, and STANDS — its refutation is two movements deep and hasn't surfaced")
    check(Mystery7.witnessLine7(s, "Barbrady") == null,
        "backwards: the night-before's witnesses don't exist in the world before their chapter")
    Mystery7.noteChapterStarted7(s, ch7[1]); s.absDay += 7
    Mystery7.witnessLine7(s, "Barbrady")
    Mystery7.witnessLine7(s, "Carol")
    Mystery7.lookClueText7(s, "KennysHouse")
    Mystery7.lookClueText7(s, "Elementary")   // the day-book line, inert
    check(Mystery7.pendingCommit7(s)?.id == "m2" &&
        Mystery7.chooseCommit7(s, "m2", "checked") &&
        Mystery7.verdict7(s, mv7[2]) == "CONFIRMED",
        "backwards: the night before commits checked and confirms on the unsent reply")
    check(Mystery7.liveEvidence7(s, mv7[0]) == 0,
        "backwards: with the day-book inert, the beginning still has NO live evidence — it cannot be rushed")
    Mystery7.noteChapterStarted7(s, ch7[2]); s.absDay += 7
    check(Mystery7.clueLive7(s, Mystery7.CLUE7_BY_ID["daybook_line"]!!),
        "backwards: the ledger chapter unlocks the day-book — context is a chapter, not a second find")
    Mystery7.lookClueText7(s, "CityHall")     // the volume, read whole
    Mystery7.lookClueText7(s, "CityHall")     // the request slip
    Mystery7.witnessLine7(s, "Victoria")
    check(Mystery7.verdict7(s, mv7[3]) == "BROKEN",
        "backwards: THE TRAP SPRINGS — the confrontation's committed reading BREAKS the moment the ledger surfaces, with nothing re-committed and nothing edited")
    Mystery7.noteParticipation7(s, ch7[2].id)
    check("carbon_receipt" in s.mystery7Clues &&
        !Mystery7.clueLive7(s, Mystery7.CLUE7_BY_ID["carbon_receipt"]!!) &&
        Mystery7.liveEvidence7(s, mv7[0]) == 1,
        "backwards: the carbon is in hand in the ledger chapter and inert until the fire winter — the beginning still can't be bought")
    check(Mystery7.pendingCommit7(s)?.id == "m1",
        "backwards: the ledger movement is the next line to write")
    check(Mystery7.chooseCommit7(s, "m1", "easy") &&
        Mystery7.verdict7(s, mv7[1]) == "BROKEN",
        "backwards: an easy ledger reading breaks on arrival — its own keystone refutes it")
    check(Mystery7.pendingCommit7(s)?.id == "m3" &&
        Mystery7.chooseCommit7(s, "m3", "checked") &&
        Mystery7.verdict7(s, mv7[3]) == "CONFIRMED",
        "backwards: a broken line can be struck and rewritten — the confrontation, rewritten checked, confirms on the sign-in book")
    check(Mystery7.pendingCommit7(s)?.id == "m1" &&
        Mystery7.chooseCommit7(s, "m1", "checked") &&
        Mystery7.verdict7(s, mv7[1]) == "CONFIRMED",
        "backwards: the deepest broken line is revised next, and confirms")
    Mystery7.noteChapterStarted7(s, ch7[3]); s.absDay += 7
    check(Mystery7.clueLive7(s, Mystery7.CLUE7_BY_ID["carbon_receipt"]!!),
        "backwards: the fire winter wakes the carbon — the second locked piece turns testimony-grade in the finale chapter")
    Mystery7.witnessLine7(s, "Marvin")
    check(Mystery7.pendingCommit7(s)?.id == "m0" &&
        Mystery7.liveEvidence7(s, mv7[0]) == 3,
        "backwards: the beginning is committable LAST, on all three of its pieces live")
    check(Mystery7.chooseCommit7(s, "m0", "easy") &&
        Mystery7.verdict7(s, mv7[0]) == "BROKEN",
        "backwards: even at the end, a hasty beginning breaks on its own evidence — the trap has no exempt movement")
    check(Mystery7.chooseCommit7(s, "m0", "checked") &&
        Mystery7.verdict7(s, mv7[0]) == "CONFIRMED" &&
        Mystery7.originEligible7(s) && Mystery7.timelineComplete7(s),
        "backwards: the beginning, written checked, stands confirmed — the origin call is earned")

    // ---------- the finale: gates read the FINAL timeline ----------
    fun restageState(): GameState {
        val st = eng7.newState()
        st.arcRetired = true; st.arc2Retired = true; st.arc3Retired = true
        st.arc4Retired = true; st.arc5Retired = true; st.arc6Retired = true
        st.arc7Started = true; st.arc7Chapter = 4
        st.shenaniganId = Mystery7.FINALE7_ID
        st.shenaniganDay = st.todayKey
        for (c in clues7) st.mystery7Clues.add(c.id)
        st.timeMin = 13 * 60
        return st
    }
    val sNoCommits = restageState()
    check(!Mystery7.restageDue(sNoCommits),
        "backwards: the ceremony waits on a finished timeline — no commits, no homecoming call")
    val sDue = restageState()
    for (m in mv7) sDue.arc7Commits[m.id] = "checked"
    check(Mystery7.restageDue(sDue),
        "backwards: a complete timeline at the climax opens the homecoming")
    check(Finales.climaxPending(sDue) && School.anyClimaxDueToday(sDue) &&
        Walk.caseCritical(sDue) && MovieNights.anyClimaxDueTonight(sDue),
        "backwards: a due homecoming holds every deference list, like every climax before it")
    check(!Mystery7.restageDue(sDue.apply { timeMin = 10 * 60 }),
        "backwards: the homecoming waits for the climax stage, not the morning")
    sDue.timeMin = 13 * 60
    check(!Mystery7.chooseFinale7(sDue, "maybe"),
        "backwards: only the four calls can be made in that room")
    check(Mystery7.chooseFinale7(sDue, "origin") && sDue.arc7Choice == "origin",
        "backwards: the origin call locks when the beginning stands confirmed")
    check(!Mystery7.restageDue(sDue) && !Mystery7.chooseFinale7(sDue, "stand"),
        "backwards: a locked call closes the homecoming")
    val outOrigin = Mystery7.resolveRestage(sDue)
    check(outOrigin.branch == "origin" && sDue.arc7Retired &&
        sDue.arc7Branch == "origin" && sDue.arc7RetiredDay == sDue.absDay,
        "backwards: the origin call lands the origin ending and retires the case forever")
    Mystery7.applyRestageEffects(sDue, "origin")
    check(sDue.arc7CasePending && sDue.arc7CaseDay == sDue.absDay + 7 &&
        (sDue.friendship["Carol"] ?: 0) == 4 &&
        sDue.lifeText["mark:Elementary"]?.contains("mended") == true,
        "backwards: the origin landing befriends the keeper, and books the case's mending a week out")
    sDue.absDay += 6
    check(!Mystery7.noteCaseRebuilt(sDue),
        "backwards: the mended case does not arrive early")
    sDue.absDay += 1
    check(Mystery7.noteCaseRebuilt(sDue) && sDue.arc7CaseBuilt &&
        !Mystery7.noteCaseRebuilt(sDue),
        "backwards: a week on, the trowel is home under new glass — exactly once")
    check(Mystery7.aftermathLine7(sDue, "Victoria") != null &&
        Mystery7.aftermathLine7(sDue, "Carol") == null,
        "backwards: in the origin landing it is the keeper of the minutes who says the uncomfortable thing")

    // 'stand' with a confirmed timeline -> the first ending stands
    val sStand = restageState()
    for (m in mv7) sStand.arc7Commits[m.id] = "checked"
    sStand.friendship["Carol"] = 10
    check(Mystery7.chooseFinale7(sStand, "stand") &&
        Mystery7.resolveRestage(sStand).branch == "again",
        "backwards: letting it stand lands AGAIN even with the truth in hand — proven and unspoken is a landing")
    Mystery7.applyRestageEffects(sStand, "again")
    check((sStand.friendship["Carol"] ?: 0) == 6 &&
        sStand.lifeText["mark:CityHall"]?.contains("Recovered") == true &&
        !sStand.arc7CasePending,
        "backwards: the again landing scars the keeper's bond, plaques the taking at City Hall, and mends no case")
    check(Mystery7.aftermathLine7(sStand, "Carol") != null,
        "backwards: in the again landing the keeper says the uncomfortable thing, standing, forever")

    // 'change' needs a confirmed movement; lands MENDED
    val sChange = restageState()
    for (m in mv7) sChange.arc7Commits[m.id] = "easy"
    check(!Mystery7.changeEligible7(sChange.apply {
            mystery7Clues.clear() }) ,
        "backwards: with nothing live, nothing stands confirmed — the change call cannot be bought")
    val sChange2 = restageState()
    for (m in mv7) sChange2.arc7Commits[m.id] = "easy"
    sChange2.arc7Commits["m3"] = "checked"   // confirms on the sign-in book
    check(Mystery7.changeEligible7(sChange2) &&
        Mystery7.chooseFinale7(sChange2, "change") &&
        Mystery7.resolveRestage(sChange2).branch == "mended",
        "backwards: one confirmed movement carries the change call — the record is amended")

    // the origin gate reads the FINAL state: a broken beginning buys nothing
    val sBroken0 = restageState()
    for (m in mv7) sBroken0.arc7Commits[m.id] = "checked"
    sBroken0.arc7Commits["m0"] = "easy"      // broken on the live day-book
    check(Mystery7.verdict7(sBroken0, mv7[0]) == "BROKEN" &&
        !Mystery7.originEligible7(sBroken0) &&
        !Mystery7.chooseFinale7(sBroken0, "origin") &&
        Mystery7.chooseFinale7(sBroken0, "stand"),
        "backwards: a beginning written wrong cannot be spoken as the truth — the gate reads the final timeline, not the effort")

    // walk / absence -> cold
    val sWalk = restageState()
    for (m in mv7) sWalk.arc7Commits[m.id] = "checked"
    check(Mystery7.chooseFinale7(sWalk, "walk") &&
        Mystery7.resolveRestage(sWalk).branch == "cold",
        "backwards: walking away is its own landing — the rerun, unwitnessed by the one who knew")
    check(Mystery7.aftermathLine7(sWalk, "Kyle") != null,
        "backwards: in the cold landing it is the son in the wings who says the uncomfortable thing")
    val sAbsent = restageState()
    check(Mystery7.resolveRestage(sAbsent).branch == "cold" &&
        sAbsent.arc7Retired,
        "backwards: a ceremony nobody plays lands cold, and still retires")
    check(Mystery7.ambientCallback7(sAbsent, Random(7)) != null &&
        Mystery7.ambientCallback7(eng7.newState(), Random(7)) == null,
        "backwards: the ending stays in the town's mouth only once the case has closed")

    // ---------- the board: a timeline in true order ----------
    val boardMid = Mystery7.boardLines7(sInert)   // ch3, day-book live, m0 'easy' broken
    val joinedMid = boardMid.joinToString("\n")
    check(joinedMid.indexOf("1. THE FIRE WINTER") >= 0 &&
        joinedMid.indexOf("1. THE FIRE WINTER") <
            joinedMid.indexOf("4. THE TAKING"),
        "backwards: the board lays the story out beginning-first even though it was filled in backwards")
    check(joinedMid.contains("💔 BROKEN"),
        "backwards: the board shows a broken line struck, verdict derived on the spot")
    val sInertBoard = eng7.newState()
    sInertBoard.arc7Started = true; sInertBoard.arc7Chapter = 2
    Mystery7.grantClue7(sInertBoard, "daybook_line")
    val joinedInert = Mystery7.boardLines7(sInertBoard).joinToString("\n")
    check(joinedInert.contains("🔒") && joinedInert.contains("E.W.'s word") &&
        !joinedInert.contains("Enoch"),
        "backwards: an inert piece shows its inert face on the board — initials only, no name, no meaning")
    check(joinedMid.contains("SAY WHAT REALLY STARTED IT"),
        "backwards: the forecast publishes the finale's terms before the finale")
    val joinedDone = Mystery7.boardLines7(sDue).joinToString("\n")
    check(joinedDone.contains("🏁") && joinedDone.contains("keeper's ") &&
        Mystery7.boardVisible7(sDue) &&
        !Mystery7.boardVisible7(eng7.newState()),
        "backwards: the closed board keeps its record; a fresh town has no board")

    // ---------- saves ----------
    val sSave7 = eng7.newState()
    sSave7.arc7Started = true; sSave7.arc7Chapter = 3; sSave7.arc7DueAbsDay = 88
    sSave7.mystery7Clues.addAll(listOf("ledger_pages", "daybook_line", "exact_words"))
    sSave7.arc7Commits["m3"] = "easy"; sSave7.arc7Commits["m2"] = "checked"
    val back7 = decodeGameState(encodeGameState(sSave7))
    check(back7.arc7Started && back7.arc7Chapter == 3 &&
        back7.arc7DueAbsDay == 88 && !back7.arc7Retired &&
        back7.mystery7Clues == sSave7.mystery7Clues &&
        back7.arc7Commits == sSave7.arc7Commits,
        "backwards: a mid-case save round-trips chapter, due day, evidence and commitments")
    val docOld7 = encodeGameState(sSave7).toMutableMap()
    docOld7.remove("arc7"); docOld7.remove("mystery7Clues"); docOld7.remove("arc7Commits")
    val backOld7 = decodeGameState(docOld7)
    check(!backOld7.arc7Started && backOld7.arc7Chapter == 0 &&
        backOld7.mystery7Clues.isEmpty() && backOld7.arc7Commits.isEmpty() &&
        !backOld7.arc7Retired,
        "backwards: a pre-v0.9.0f save loads with the seventh case simply not yet queued")
    val docBad7 = encodeGameState(sSave7).toMutableMap()
    docBad7["mystery7Clues"] = listOf("ledger_pages", "not_a_piece")
    docBad7["arc7Commits"] = mapOf("m3" to "sideways", "m9" to "easy", "m1" to "easy")
    val backBad7 = decodeGameState(docBad7)
    check(backBad7.mystery7Clues == setOf("ledger_pages") &&
        backBad7.arc7Commits == mapOf("m1" to "easy"),
        "backwards: decode filters unknown pieces, unknown movements, and unlisted readings")

    // ---------- the seven-case lifetime, driven ----------
    // One unattended life, day by day: the cases must queue
    // strictly one behind the next and ALL retire — the
    // seventh included — with the slot empty at the end.
    val engLife7 = Engine(7170)
    val life7 = engLife7.newState()
    var lifeDays7 = 0
    var arc7StartedAfterArc6 = false
    while (lifeDays7 < 1600 && !(life7.arcRetired && life7.arc2Retired &&
        life7.arc3Retired && life7.arc4Retired && life7.arc5Retired &&
        life7.arc6Retired && life7.arc7Retired)) {
        engLife7.onNewDay(life7)
        if (life7.arc7Started && life7.arc6Retired) arc7StartedAfterArc6 = true
        if (life7.arc7Started) {
            check(life7.arc6Retired,
                "backwards: the seventh case never opens over the sixth " +
                    "(day $lifeDays7)")
        }
        lifeDays7++
    }
    check(life7.arc7Retired && life7.arc7Branch in Mystery7.BRANCH_KEYS,
        "backwards: all seven cases retired in one lifetime " +
            "(arc #7 branch '${life7.arc7Branch}' after $lifeDays7 days)")
    check(arc7StartedAfterArc6 && Mystery7.dueChapter7(life7) == null,
        "backwards: the seventh case opened only behind the sixth, " +
            "and nothing demands the slot after it")

    // ---------- wiring ----------
    val mystery7Src = File(root, "src/com/hunt3r/southparktown/Mystery7.kt").readText()
    val engineSrc7 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val gameActivitySrc7 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc7 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val prefsSrc7 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc7 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    val talkGateSrc7 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val finalesSrc7 = File(root, "src/com/hunt3r/southparktown/Finales.kt").readText()
    val movieSrc7 = File(root, "src/com/hunt3r/southparktown/MovieNights.kt").readText()
    val walkSrc7 = File(root, "src/com/hunt3r/southparktown/Walk.kt").readText()
    val schoolSrc7 = File(root, "src/com/hunt3r/southparktown/School.kt").readText()
    check(!mystery7Src.contains("import android"),
        "backwards: Mystery7.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc7.contains("Mystery7.dueChapter7") &&
        engineSrc7.contains("Mystery7.resolveRestage") &&
        engineSrc7.contains("Mystery7.noteParticipation7") &&
        engineSrc7.contains("Mystery7.noteCaseRebuilt") &&
        engineSrc7.contains("Mystery7.ambientCallback7"),
        "backwards: the engine airs the chapters, resolves the homecoming, feeds participation, lands the mended case, keeps the callbacks")
    check(talkGateSrc7.contains("Mystery7.witnessLine7") &&
        talkGateSrc7.contains("Mystery7.aftermathLine7") &&
        gameActivitySrc7.contains("Mystery7.lookClueText7") &&
        gameActivitySrc7.contains("Mystery7.chooseFinale7") &&
        gameActivitySrc7.contains("maybeShowRestage") &&
        gameActivitySrc7.contains("Mystery7.chooseCommit7") &&
        gameActivitySrc7.contains("maybeShowCommit"),
        "backwards: TalkGate and GameActivity wire the tellings, the aftermath, the looks, the homecoming, and the timeline's writing")
    check(journalSrc7.contains("Mystery7.boardLines7"),
        "backwards: the Journal renders the seventh case's timeline")
    check(prefsSrc7.contains("\"arc7\" to mapOf") &&
        prefsSrc7.contains("\"mystery7Clues\" to") &&
        prefsSrc7.contains("\"arc7Commits\" to"),
        "backwards: the save doc carries the seventh case additively")
    check(shenanigansSrc7.contains("Mystery7.CHAPTERS7"),
        "backwards: the seventh case's chapters resolve by id")
    check(finalesSrc7.contains("Mystery7.restageDue") &&
        movieSrc7.contains("Mystery7.restageDue") &&
        walkSrc7.contains("Mystery7.restageDue") &&
        schoolSrc7.contains("Mystery7.restageDue"),
        "backwards: every deference list stands down for the homecoming — two climaxes never stack")

    // ---------- version ----------
    val manifestSrc7 = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc7.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc7.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "backwards: the manifest carries 72 / 0.9.0f")

    // ---------- THE SPOILER WALL ----------
    // Nothing the player can read before the finale chapter
    // begins may state or imply the answer: no trust, no
    // asking, no names behind the initials, no verdict on
    // the keeping. The scan covers the first three
    // chapters, every piece readable before the fire
    // winter (discovery text, board text, inert faces),
    // the first three movements' candidate readings, a
    // mid-case board, and the changelog entry. The finale
    // chapter's own materials are the payoff and are not
    // scanned — the wall stands where the reveal begins.
    val banned7 = listOf("enoch", "webb", "entrust", "in trust",
        "the trust", "asked the caretaker", "asked him to take",
        "keep it safe", "first principal asked", "never stole",
        "didn't steal", "did not steal", "not a theft",
        "no theft", "stole nothing", "was given it",
        "gave it to him to keep")
    val preReveal7 = mutableListOf<String>()
    for (def in Mystery7.CHAPTERS7.take(3)) {
        preReveal7.add(def.title); preReveal7.add(def.cause); preReveal7.add(def.blurb)
        for (st in def.stages) {
            preReveal7.add(st.title); preReveal7.add(st.banner)
            preReveal7.add(st.journalNote); preReveal7.add(st.objective)
        }
        for (l in def.coldOpen) preReveal7.add(l.text)
    }
    for (clue in Mystery7.CLUES7) {
        if (clue.minChapter > 2) continue
        preReveal7.add(clue.title)
        // a locked piece's LIVE detail is readable only
        // after its context chapter — payoff-adjacent by
        // construction; its inert face is what the wall
        // guards, and the inert face is scanned.
        if (clue.unlockChapter <= 2) preReveal7.add(clue.detail)
        preReveal7.add(clue.inertDetail)
        clue.spoken?.let { preReveal7.add(it) }
        clue.foundText?.let { preReveal7.add(it) }
    }
    for (m in Mystery7.MOVEMENTS7.drop(1)) {
        preReveal7.add(m.easy); preReveal7.add(m.checked)
    }
    val sMid7 = eng7.newState()
    sMid7.arc7Started = true; sMid7.arc7Chapter = 3
    for (clueId in listOf("exact_words", "thirty_witnesses",
        "display_sheet", "neighbor_heard", "unsent_reply",
        "keeper_account", "ledger_pages", "request_slip",
        "program_note", "daybook_line")) {
        Mystery7.grantClue7(sMid7, clueId)
    }
    sMid7.arc7Commits["m3"] = "easy"
    sMid7.arc7Commits["m2"] = "checked"
    sMid7.arc7Commits["m1"] = "checked"
    preReveal7.addAll(Mystery7.boardLines7(sMid7))
    val readme7 = File(root, "docs/CHANGELOG.md").readText()
    val entry7 = readme7.substringAfter("### v0.9.0f")
        .substringBefore("### v0.9.0e")
    preReveal7.add(entry7)
    for (term in banned7) {
        check(preReveal7.none { it.contains(term, ignoreCase = true) },
            "backwards: no pre-reveal surface breathes '$term' " +
                "(the wall holds: premise and structure only)")
    }
    check(entry7.contains("backwards") && entry7.contains("timeline"),
        "backwards: the changelog carries the premise and the shape — and stops there")
}


// ================= v0.10.0f: mystery #8 — everybody was somewhere =================
// Queue #10 item 6. The eighth case is an eighth shape: an
// ALIBI GRAPH. Every alibi verifies; the impossibility is
// structural. The board holds seven alibis and four pairs
// that share an event-signature; the player judges each
// pair ONE EVENT or TWO EVENTS, and each pair's one
// settling piece grades the judgment — verdicts derived,
// never stored. This section pins the registries, the
// derivation (by independent recomputation over every
// evidence subset), the judgment discipline (standing
// judgments can't be re-judged; refuted ones must be),
// the finale's gates on the graph's final state, the
// landings and their persistence, the eight-case
// lifetime, and the spoiler wall over every pre-reveal
// surface.
private fun sectionV0100f(root: String) {
    println("== v0.10.0f: mystery #8 — everybody was somewhere ==")
    val eng8 = Engine(820)

    // ---------- the chapter defs ----------
    val ch8 = Mystery8.CHAPTERS8
    check(ch8.size == 4 && ch8.map { it.id }.toSet().size == 4,
        "alibis: the case is four chapters, uniquely id'd")
    check(ch8[3].id == Mystery8.FINALE8_ID,
        "alibis: the fourth chapter is the finale — Family Night, with item six at its climax")
    check(ch8.all { it.theme.icon.isNotBlank() &&
        it.theme.header.isNotBlank() && it.causers.isNotEmpty() },
        "alibis: every chapter carries its theme and its credited causers")
    check(ch8.all { d -> d.stages.size == 4 && d.episodeTitles.size == 2 &&
        d.coldOpen.size == 2 && d.coldOpen.all { it.text.isNotBlank() } },
        "alibis: every chapter carries the full episode kit")
    check(ch8.none { d -> SHENANIGANS.any { it.id == d.id } },
        "alibis: no chapter sits in the random event pool")
    check(ch8.all { Mystery8.CHAPTER8_BY_ID[it.id] == it &&
        SHENANIGAN_BY_ID[it.id] == it },
        "alibis: every chapter resolves by id, in the case and in the game")
    check(ch8[0].stages.any { it.clusterLoc == "Elementary" } &&
        ch8[1].stages.any { it.clusterLoc == "KidsPark" } &&
        ch8[2].stages.any { it.clusterLoc == "CityHall" } &&
        ch8[3].stages.any { it.clusterLoc == "Elementary" },
        "alibis: the chapters walk the school, the park fence, the counting house, and back to the school")
    val finDef8 = Mystery8.CHAPTER8_BY_ID[Mystery8.FINALE8_ID]!!
    check(finDef8.causers.containsAll(listOf("Victoria", "Clyde")),
        "alibis: the reading is played by the keeper of the column and the boy in its first row")

    // ---------- the alibis (the graph's nodes) ----------
    val alibis8 = Mystery8.ALIBIS8
    check(alibis8.size == 7 && Mystery8.ALIBI8_BY_ID.size == 7,
        "alibis: seven accounts stand in the graph, uniquely id'd")
    check(alibis8.all { it.suspect in AGENT_PROFILES &&
        it.place in LOCATIONS && it.account.isNotBlank() &&
        it.voucher.isNotBlank() && it.signature.isNotBlank() },
        "alibis: every account names a real person, a real place, a voucher and a carried signature")
    check(Mystery8.ALIBI8_BY_ID["alibi_clyde"]!!.voucher.contains("Garrison") &&
        Mystery8.ALIBI8_BY_ID["alibi_garrison"]!!.voucher.contains("Clyde"),
        "alibis: the buzzer pair's two accounts vouch for EACH OTHER — the graph's one mutual edge")
    check(Mystery8.PAIRS8.flatMap { listOf(it.alibiA, it.alibiB) }.toSet()
        .containsAll(alibis8.map { it.id }),
        "alibis: every account in the graph is held by at least one pair — nobody is decoration")

    // ---------- the pairs (the graph's edges) ----------
    val pairs8 = Mystery8.PAIRS8
    check(pairs8.size == 4 && pairs8.map { it.index } == listOf(0, 1, 2, 3),
        "alibis: four pairs, declared in board order")
    check(pairs8.map { it.truthSame } == listOf(true, true, false, false),
        "alibis: two pairs are one event wearing two descriptions; two are two events filed as one")
    check(pairs8.all { p ->
        val proof = Mystery8.CLUE8_BY_ID[p.proofBy]
        proof != null && proof.pair == p.index &&
            p.alibiA in Mystery8.ALIBI8_BY_ID &&
            p.alibiB in Mystery8.ALIBI8_BY_ID && p.alibiA != p.alibiB &&
            p.evidenceNeeded == 2 },
        "alibis: every pair is settled by exactly one piece tagged to itself, at the standing price")
    check(pairs8[0].minChapter == 1 && pairs8[1].minChapter == 1 &&
        pairs8[2].minChapter == 2 && pairs8[3].minChapter == 2,
        "alibis: the buzzer and the crossing open in the vouches week; the ladder and the jingle wait for the counting")

    // ---------- the evidence registry ----------
    val clues8 = Mystery8.CLUES8
    check(clues8.size == 12 && Mystery8.CLUE8_IDS.size == 12,
        "alibis: the evidence is twelve pieces")
    check(clues8.count { it.kind == Mystery8.Kind8.WITNESS } == 5 &&
        clues8.count { it.kind == Mystery8.Kind8.LOOK } == 5 &&
        clues8.count { it.kind == Mystery8.Kind8.PARTICIPATION } == 2,
        "alibis: the verbs run 5 witness / 5 look / 2 participation")
    check((0..3).all { idx -> clues8.count { it.pair == idx } == 3 },
        "alibis: three pieces are tagged to every pair")
    check(clues8.all { c -> c.minChapter in 0..3 &&
        c.unlockChapter in c.minChapter..3 &&
        when (c.kind) {
            Mystery8.Kind8.WITNESS ->
                c.npc != null && c.npc in AGENT_PROFILES &&
                    !c.spoken.isNullOrBlank()
            Mystery8.Kind8.LOOK ->
                c.locId != null && c.locId in LOCATIONS &&
                    !c.foundText.isNullOrBlank()
            Mystery8.Kind8.PARTICIPATION ->
                c.chapterDefId != null &&
                    c.chapterDefId in Mystery8.CHAPTER8_BY_ID
        } },
        "alibis: every piece names a real witness, place, or chapter")
    val locked8 = clues8.filter { it.unlockChapter > it.minChapter }
    check(locked8.map { it.id }.toSet() ==
        setOf("scoreboard_log", "library_slip") &&
        locked8.all { it.inertDetail != it.detail && it.inertDetail.isNotBlank() },
        "alibis: exactly two pieces are context-locked, each with an honest inert face")
    check(Mystery8.CLUE8_BY_ID["scoreboard_log"]!!.unlockChapter == 3 &&
        pairs8[0].proofBy == "scoreboard_log",
        "alibis: THE STING — the buzzer pair's settling piece is the log strip, unreadable until the finale chapter: the merger that matters most can only be proven in the last room")

    // ---------- independent recomputation (the suite's own math) ----------
    fun recompVerdict8(held: Set<String>,
                       judgments: Map<String, String>,
                       p: Mystery8.Pair8): String {
        val j = judgments[p.id] ?: return "OPEN"
        if (p.proofBy !in held) return "COMMITTED"
        val truth = if (p.truthSame) "same" else "different"
        return if (j == truth) "PROVEN" else "REFUTED"
    }
    var sweepOk8 = true
    for (mask in 0 until (1 shl clues8.size)) {
        val s = eng8.newState()
        s.arc8Chapter = 4
        clues8.forEachIndexed { i, c ->
            if (mask shr i and 1 == 1) s.mystery8Clues.add(c.id)
        }
        val held = s.mystery8Clues.toSet()
        // two judgment schemes over the same evidence mask,
        // so judgments and holdings vary independently
        for (scheme in 0..1) {
            val judgments = mutableMapOf<String, String>()
            for (p in pairs8) {
                val code = if (scheme == 0)
                    (mask shr (2 * p.index)) and 3
                else ((mask shr 3) + p.index) % 3
                when (code) {
                    1 -> judgments[p.id] = "same"
                    2 -> judgments[p.id] = "different"
                    3 -> judgments[p.id] = "same"
                }
            }
            s.arc8Pairs.clear(); s.arc8Pairs.putAll(judgments)
            val verdicts = pairs8.associate { p ->
                p.id to recompVerdict8(held, judgments, p) }
            for (p in pairs8) {
                if (Mystery8.pairVerdict8(s, p) != verdicts[p.id])
                    sweepOk8 = false
                if (Mystery8.liveEvidence8(s, p) !=
                    held.count { Mystery8.CLUE8_BY_ID[it]!!.pair == p.index })
                    sweepOk8 = false
            }
            val proven = verdicts.values.count { it == "PROVEN" }
            val refuted = verdicts.values.count { it == "REFUTED" }
            val allJudged = pairs8.all { it.id in judgments }
            if (Mystery8.provenCount8(s) != proven ||
                Mystery8.refutedCount8(s) != refuted ||
                Mystery8.judgedCount8(s) != judgments.size ||
                Mystery8.graphJudged8(s) != allJudged ||
                Mystery8.graphClean8(s) != (refuted == 0) ||
                Mystery8.nameEligible8(s) != (proven >= 1) ||
                Mystery8.readEligible8(s) !=
                    (verdicts[pairs8[0].id] == "PROVEN" &&
                        verdicts[pairs8[2].id] == "PROVEN" &&
                        allJudged && refuted == 0 && proven >= 3) ||
                Mystery8.liveClueIds8(s) != held)
                sweepOk8 = false
        }
    }
    check(sweepOk8,
        "alibis: verdicts, counts and both finale gates recompute exactly over all 4096 evidence subsets, under two judgment schemes")
    var lockOk8 = true
    for (ch in 0..5) for (c in locked8) {
        val s = eng8.newState()
        s.arc8Chapter = ch
        s.mystery8Clues.add(c.id)
        if (Mystery8.clueLive8(s, c) != (ch > c.unlockChapter)) lockOk8 = false
    }
    check(lockOk8,
        "alibis: a locked piece is live exactly when its context chapter has begun — at every chapter boundary")

    // ---------- discovery: witnesses, looks, hands ----------
    val sDisc = eng8.newState()
    check(Mystery8.witnessLine8(sDisc, "Mackey") == null,
        "alibis: no witness speaks before the case opens their week")
    sDisc.arc8Chapter = 2
    val mackeyLine = Mystery8.witnessLine8(sDisc, "Mackey")
    check(mackeyLine != null && mackeyLine.speaker == "Mackey" &&
        "two_buzzers" in sDisc.mystery8Clues &&
        Mystery8.witnessLine8(sDisc, "Mackey") == null,
        "alibis: a witness's telling grants its piece exactly once")
    val sLook = eng8.newState()
    sLook.arc8Chapter = 2
    val look1 = Mystery8.lookClueText8(sLook, "Elementary")
    check(look1 != null && "scoreboard_log" in sLook.mystery8Clues &&
        !Mystery8.clueLive8(sLook,
            Mystery8.CLUE8_BY_ID["scoreboard_log"]!!),
        "alibis: the log strip is found in the vouches week — in hand, honestly inert, settling nothing")
    Mystery8.lookClueText8(sLook, "Elementary")
    Mystery8.lookClueText8(sLook, "Elementary")
    check(sLook.mystery8Clues.containsAll(
            listOf("one_set_of_tracks", "setup_photo")) &&
        Mystery8.lookClueText8(sLook, "Elementary") == null,
        "alibis: the school's looks surface in the case's order — and the smudged slip is not among them yet")
    sLook.arc8Chapter = 3
    check(Mystery8.lookClueText8(sLook, "Elementary") != null &&
        "library_slip" in sLook.mystery8Clues &&
        Mystery8.lookClueText8(sLook, "KidsPark") != null &&
        "bike_bell" in sLook.mystery8Clues,
        "alibis: the counting week opens the slip at the school and the bell at the park")
    val sHands = eng8.newState()
    Mystery8.noteParticipation8(sHands, "arc8_ch1_letters")
    check(sHands.mystery8Clues.isEmpty(),
        "alibis: hands in the crowd find nothing before the first chapter airs")
    sHands.arc8Chapter = 1
    Mystery8.noteParticipation8(sHands, "arc8_ch1_letters")
    sHands.arc8Chapter = 3
    Mystery8.noteParticipation8(sHands, "arc8_ch3_the_counting")
    check(sHands.mystery8Clues.containsAll(
            listOf("marquee_crowd", "setup_shift")),
        "alibis: participation grants the crowd piece in week one and the shift piece in the counting week")

    // ---------- the judgment discipline, played ----------
    val sPlay = eng8.newState()
    sPlay.arc8Chapter = 2
    for (id in listOf("marquee_crowd", "two_buzzers",
        "guard_two_sightings", "kenny_crossing", "one_set_of_tracks"))
        Mystery8.grantClue8(sPlay, id)
    check(Mystery8.pendingPair8(sPlay)?.id == "pair_buzzer",
        "alibis: the buzzer pair is offered first, in board order, at its price")
    check(Mystery8.choosePair8(sPlay, "pair_buzzer", "different") &&
        Mystery8.pairVerdict8(sPlay, pairs8[0]) == "COMMITTED",
        "alibis: a judgment written before its settling piece surfaces stands COMMITTED, untested")
    check(!Mystery8.choosePair8(sPlay, "pair_buzzer", "same"),
        "alibis: a standing judgment cannot be re-judged — only a refuted one can")
    check(Mystery8.pendingPair8(sPlay)?.id == "pair_crossing" &&
        Mystery8.choosePair8(sPlay, "pair_crossing", "different") &&
        Mystery8.pairVerdict8(sPlay, pairs8[1]) == "REFUTED",
        "alibis: judge against the live settling piece and the judgment is refuted on arrival")
    check(Mystery8.pendingPair8(sPlay)?.id == "pair_crossing" &&
        Mystery8.choosePair8(sPlay, "pair_crossing", "same") &&
        Mystery8.pairVerdict8(sPlay, pairs8[1]) == "PROVEN",
        "alibis: a refuted pair is offered again — and, judged as the evening ran, stands proven")
    Mystery8.grantClue8(sPlay, "scoreboard_log")
    check(Mystery8.pairVerdict8(sPlay, pairs8[0]) == "COMMITTED" &&
        !Mystery8.clueLive8(sPlay,
            Mystery8.CLUE8_BY_ID["scoreboard_log"]!!),
        "alibis: the held-but-inert log strip settles nothing — holding is not knowing")
    sPlay.arc8Chapter = 4
    check(Mystery8.pairVerdict8(sPlay, pairs8[0]) == "REFUTED",
        "alibis: when the strip's context arrives, the standing judgment flips to REFUTED on its own — nothing was edited; the past simply became readable")
    for (id in listOf("ladder_folded", "setup_photo",
        "bike_bell", "two_streets", "setup_shift"))
        Mystery8.grantClue8(sPlay, id)
    check(Mystery8.pendingPair8(sPlay)?.id == "pair_ladder",
        "alibis: new judgments come before revisions — the ladder is offered while the buzzer stands struck")
    check(Mystery8.choosePair8(sPlay, "pair_ladder", "same") &&
        Mystery8.pairVerdict8(sPlay, pairs8[2]) == "REFUTED" &&
        Mystery8.choosePair8(sPlay, "pair_jingle", "different") &&
        Mystery8.pairVerdict8(sPlay, pairs8[3]) == "PROVEN",
        "alibis: the ladder misjudged stands refuted; the jingle, judged two events, stands proven")
    check(Mystery8.pendingPair8(sPlay)?.id == "pair_buzzer" &&
        Mystery8.choosePair8(sPlay, "pair_buzzer", "same") &&
        Mystery8.pairVerdict8(sPlay, pairs8[0]) == "PROVEN" &&
        Mystery8.pendingPair8(sPlay)?.id == "pair_ladder" &&
        Mystery8.choosePair8(sPlay, "pair_ladder", "different") &&
        Mystery8.pairVerdict8(sPlay, pairs8[2]) == "PROVEN",
        "alibis: struck judgments are struck and re-judged in board order until the graph is clean")
    check(Mystery8.graphJudged8(sPlay) && Mystery8.graphClean8(sPlay) &&
        Mystery8.provenCount8(sPlay) == 4 &&
        Mystery8.readEligible8(sPlay) && Mystery8.nameEligible8(sPlay) &&
        Mystery8.pendingPair8(sPlay) == null,
        "alibis: the finished graph — all judged, none refuted, four proven — carries the hard call, and offers nothing more")

    // the gates read the FINAL graph, in pieces:
    fun judgedState8(vararg judgments: Pair<String, String>): GameState {
        val st = eng8.newState()
        st.arc8Chapter = 4
        for (c in clues8) st.mystery8Clues.add(c.id)
        for ((pid, j) in judgments) st.arc8Pairs[pid] = j
        return st
    }
    val sThree = judgedState8("pair_buzzer" to "same",
        "pair_crossing" to "same", "pair_ladder" to "different",
        "pair_jingle" to "same")   // jingle judged wrong: refuted
    check(!Mystery8.readEligible8(sThree) && !Mystery8.graphClean8(sThree),
        "alibis: one refuted judgment still standing on the graph buys the hard call nothing")
    val sCommitted = judgedState8("pair_buzzer" to "same",
        "pair_ladder" to "different", "pair_jingle" to "different")
    check(!Mystery8.graphJudged8(sCommitted) &&
        !Mystery8.readEligible8(sCommitted) && Mystery8.nameEligible8(sCommitted),
        "alibis: an unfinished graph — however proven its edges — cannot be read aloud; it can still name")
    val sThin = judgedState8("pair_buzzer" to "different",
        "pair_crossing" to "different", "pair_ladder" to "same",
        "pair_jingle" to "same")
    check(Mystery8.graphJudged8(sThin) && Mystery8.provenCount8(sThin) == 0 &&
        !Mystery8.nameEligible8(sThin) && !Mystery8.readEligible8(sThin),
        "alibis: a fully judged graph with every pair refuted carries no call at all — the town will not follow a struck graph")

    // ---------- scheduling ----------
    val sGate8 = eng8.newState()
    check(Mystery8.dueChapter8(sGate8) == null &&
        sGate8.arc8DueAbsDay == -1,
        "alibis: while the backwards case is open this one does not even book its date")
    sGate8.arc7Retired = true; sGate8.arc7RetiredDay = 100
    sGate8.absDay = 100
    check(Mystery8.dueChapter8(sGate8) == null &&
        sGate8.arc8DueAbsDay == 110,
        "alibis: the first chapter books ten days out from the seventh case's retirement")
    sGate8.absDay = 109
    check(Mystery8.dueChapter8(sGate8) == null,
        "alibis: not a day early")
    sGate8.absDay = 110
    check(Mystery8.dueChapter8(sGate8) == ch8[0],
        "alibis: on the tenth day the sign is read")
    sGate8.holidayId = "thanksgiving"
    check(Mystery8.dueChapter8(sGate8) == null,
        "alibis: a holiday keeps its day — the chapter defers")
    sGate8.holidayId = null
    Mystery8.noteChapterStarted8(sGate8, ch8[0])
    check(sGate8.arc8Started && sGate8.arc8Chapter == 1 &&
        sGate8.arc8DueAbsDay == 117,
        "alibis: chapter one books the next a week out")
    sGate8.absDay = 117
    check(Mystery8.dueChapter8(sGate8) == ch8[1],
        "alibis: the vouches walk a week later")
    Mystery8.noteChapterStarted8(sGate8, ch8[1])
    Mystery8.noteChapterStarted8(sGate8, ch8[2])
    Mystery8.noteChapterStarted8(sGate8, ch8[3])
    check(sGate8.arc8Chapter == 4 && Mystery8.dueChapter8(sGate8) == null,
        "alibis: after the reading airs, the slot is empty")

    // ---------- the finale: gates read the FINAL graph ----------
    fun readingState8(): GameState {
        val st = eng8.newState()
        st.arcRetired = true; st.arc2Retired = true; st.arc3Retired = true
        st.arc4Retired = true; st.arc5Retired = true; st.arc6Retired = true
        st.arc7Retired = true
        st.arc8Started = true; st.arc8Chapter = 4
        st.shenaniganId = Mystery8.FINALE8_ID
        st.shenaniganDay = st.todayKey
        for (c in clues8) st.mystery8Clues.add(c.id)
        st.timeMin = 13 * 60
        return st
    }
    fun settleGraph8(st: GameState) {
        st.arc8Pairs["pair_buzzer"] = "same"
        st.arc8Pairs["pair_crossing"] = "same"
        st.arc8Pairs["pair_ladder"] = "different"
        st.arc8Pairs["pair_jingle"] = "different"
    }
    val sNoJudgments = readingState8()
    check(!Mystery8.readingDue(sNoJudgments),
        "alibis: the reading waits on a finished graph — no judgments, no item-six call")
    val sDue8 = readingState8()
    settleGraph8(sDue8)
    check(Mystery8.readingDue(sDue8),
        "alibis: a complete graph at the climax opens the reading")
    check(Finales.climaxPending(sDue8) && School.anyClimaxDueToday(sDue8) &&
        Walk.caseCritical(sDue8) && MovieNights.anyClimaxDueTonight(sDue8),
        "alibis: a due reading holds every deference list, like every climax before it")
    check(!Mystery8.readingDue(sDue8.apply { timeMin = 10 * 60 }),
        "alibis: the reading waits for the climax stage, not the morning")
    sDue8.timeMin = 13 * 60
    check(!Mystery8.chooseFinale8(sDue8, "maybe"),
        "alibis: only the four calls can be made in that room")
    check(Mystery8.chooseFinale8(sDue8, "read") && sDue8.arc8Choice == "read",
        "alibis: the read call locks when the graph's final state can carry it")
    check(!Mystery8.readingDue(sDue8) && !Mystery8.chooseFinale8(sDue8, "stand"),
        "alibis: a locked call closes the reading")
    val outAligned = Mystery8.resolveReading(sDue8)
    check(outAligned.branch == "aligned" && sDue8.arc8Retired &&
        sDue8.arc8Branch == "aligned" && sDue8.arc8RetiredDay == sDue8.absDay &&
        outAligned.outcome.isNotBlank() && outAligned.recapLines.size == 2,
        "alibis: the read call lands the aligned ending and retires the case forever")
    Mystery8.applyReadingEffects(sDue8, "aligned")
    check(sDue8.arc8LetterPending && sDue8.arc8LetterDay == sDue8.absDay + 7 &&
        (sDue8.friendship["Clyde"] ?: 0) == 4 &&
        sDue8.lifeText["mark:Elementary"]?.contains("COUNTED RIGHT") == true,
        "alibis: the aligned landing befriends the boy the count fell on, and books the letter's return a week out")
    sDue8.absDay += 6
    check(!Mystery8.noteLetterReturned(sDue8),
        "alibis: the letter does not come back early")
    sDue8.absDay += 1
    check(Mystery8.noteLetterReturned(sDue8) && sDue8.arc8LetterBack &&
        !Mystery8.noteLetterReturned(sDue8),
        "alibis: a week on, the tray is full again — exactly once, unwitnessed")
    check(Mystery8.aftermathLine8(sDue8, "Clyde") != null &&
        Mystery8.aftermathLine8(sDue8, "Garrison") == null,
        "alibis: in the aligned landing it is the spared boy who says the uncomfortable thing")

    // 'name' with a proven-but-unreadable graph -> the naming
    val sName = readingState8()
    sName.arc8Pairs["pair_buzzer"] = "different"
    sName.arc8Pairs["pair_crossing"] = "same"
    sName.arc8Pairs["pair_ladder"] = "same"
    sName.arc8Pairs["pair_jingle"] = "same"
    check(Mystery8.graphJudged8(sName) && Mystery8.nameEligible8(sName) &&
        !Mystery8.readEligible8(sName) &&
        !Mystery8.chooseFinale8(sName, "read"),
        "alibis: one proven pair carries a naming — it cannot carry a reading")
    sName.friendship["Clyde"] = 10
    check(Mystery8.chooseFinale8(sName, "name") &&
        Mystery8.resolveReading(sName).branch == "accused",
        "alibis: naming lands the accused ending — the game never admits the call was wrong")
    Mystery8.applyReadingEffects(sName, "accused")
    check((sName.friendship["Clyde"] ?: 0) == 6 &&
        !sName.arc8LetterPending &&
        sName.lifeText["mark:Elementary"]?.contains("closed") == true,
        "alibis: the accused landing scars the named boy's bond, returns no letter, and closes the tray")
    check(Mystery8.aftermathLine8(sName, "Garrison") != null &&
        Mystery8.aftermathLine8(sName, "Clyde") == null,
        "alibis: in the accused landing the objector is the voucher — he was there, and he knows what he heard, forever")

    // 'stand' with a settled graph -> the count stands
    val sStand8 = readingState8()
    settleGraph8(sStand8)
    check(Mystery8.chooseFinale8(sStand8, "stand") &&
        Mystery8.resolveReading(sStand8).branch == "stood",
        "alibis: letting the count stand lands STOOD even with the whole graph proven — proven and unread is a landing")
    Mystery8.applyReadingEffects(sStand8, "stood")
    check((sStand8.friendship["Victoria"] ?: 0) == 2 &&
        Mystery8.aftermathLine8(sStand8, "Bebe") != null,
        "alibis: the stood landing warms the principal — and the girl who counted twice says the uncomfortable thing")

    // a locked 'read' the final graph can't carry degrades cold
    val sDegraded = readingState8()
    settleGraph8(sDegraded)
    sDegraded.arc8Pairs["pair_ladder"] = "same"   // refuted, standing struck
    sDegraded.arc8Choice = "read"
    check(Mystery8.resolveReading(sDegraded).branch == "cold",
        "alibis: the wrap re-gates the call against the final graph — a read the graph can't carry lands cold")

    // walk / absence -> cold
    val sWalk8 = readingState8()
    settleGraph8(sWalk8)
    check(Mystery8.chooseFinale8(sWalk8, "walk") &&
        Mystery8.resolveReading(sWalk8).branch == "cold",
        "alibis: walking away is its own landing — item six, settled by adjacency")
    check(Mystery8.aftermathLine8(sWalk8, "Stan") != null,
        "alibis: in the cold landing it is the boy at the fence who says the uncomfortable thing")
    val sAbsent8 = readingState8()
    check(Mystery8.resolveReading(sAbsent8).branch == "cold" &&
        sAbsent8.arc8Retired,
        "alibis: a program nobody plays lands cold, and still retires")
    check(Mystery8.ambientCallback8(sAbsent8, Random(8)) != null &&
        Mystery8.ambientCallback8(eng8.newState(), Random(8)) == null,
        "alibis: the ending stays in the town's mouth only once the case has closed")

    // ---------- the board: a graph, re-counted on every read ----------
    val sBoard = eng8.newState()
    sBoard.arc8Started = true; sBoard.arc8Chapter = 3
    for (id in listOf("marquee_crowd", "two_buzzers", "scoreboard_log",
        "guard_two_sightings", "kenny_crossing", "one_set_of_tracks",
        "setup_photo", "ladder_folded", "library_slip",
        "two_streets", "bike_bell", "setup_shift"))
        Mystery8.grantClue8(sBoard, id)
    sBoard.arc8Pairs["pair_buzzer"] = "same"      // proof inert: COMMITTED
    sBoard.arc8Pairs["pair_ladder"] = "same"     // proof live: REFUTED
    val joinedBoard = Mystery8.boardLines8(sBoard).joinToString("\n")
    check(joinedBoard.indexOf("THE BUZZER") >= 0 &&
        joinedBoard.indexOf("THE BUZZER") < joinedBoard.indexOf("THE CROSSING") &&
        joinedBoard.indexOf("THE CROSSING") < joinedBoard.indexOf("THE LADDER") &&
        joinedBoard.indexOf("THE LADDER") < joinedBoard.indexOf("THE JINGLE"),
        "alibis: the board lays the pairs out in board order — buzzer, crossing, ladder, jingle")
    check(joinedBoard.contains("💔 REFUTED") &&
        joinedBoard.contains("📌 COMMITTED"),
        "alibis: the board shows a refuted judgment struck and a committed one standing, verdicts derived on the spot")
    check(joinedBoard.contains("🔒") &&
        joinedBoard.contains("smudged") &&
        !joinedBoard.contains("There was no other"),
        "alibis: an inert piece shows its inert face on the board — a smudge and a faded strip, no meanings")
    check(joinedBoard.contains("READ THE GRAPH ALOUD"),
        "alibis: the forecast publishes the finale's terms before the finale")
    val joinedDone8 = Mystery8.boardLines8(sDue8).joinToString("\n")
    check(joinedDone8.contains("🏁") && joinedDone8.contains("full") &&
        Mystery8.boardVisible8(sDue8) &&
        !Mystery8.boardVisible8(eng8.newState()),
        "alibis: the closed board keeps its record — the returned letter on it; a fresh town has no board")

    // ---------- saves ----------
    val sSave8 = eng8.newState()
    sSave8.arc8Started = true; sSave8.arc8Chapter = 3; sSave8.arc8DueAbsDay = 88
    sSave8.mystery8Clues.addAll(listOf("scoreboard_log", "two_buzzers", "one_set_of_tracks"))
    sSave8.arc8Pairs["pair_buzzer"] = "different"; sSave8.arc8Pairs["pair_crossing"] = "same"
    val back8 = decodeGameState(encodeGameState(sSave8))
    check(back8.arc8Started && back8.arc8Chapter == 3 &&
        back8.arc8DueAbsDay == 88 && !back8.arc8Retired &&
        back8.mystery8Clues == sSave8.mystery8Clues &&
        back8.arc8Pairs == sSave8.arc8Pairs,
        "alibis: a mid-case save round-trips chapter, due day, evidence and judgments")
    val docOld8 = encodeGameState(sSave8).toMutableMap()
    docOld8.remove("arc8"); docOld8.remove("mystery8Clues"); docOld8.remove("arc8Pairs")
    val backOld8 = decodeGameState(docOld8)
    check(!backOld8.arc8Started && backOld8.arc8Chapter == 0 &&
        backOld8.mystery8Clues.isEmpty() && backOld8.arc8Pairs.isEmpty() &&
        !backOld8.arc8Retired,
        "alibis: a pre-v0.10.0f save loads with the eighth case simply not yet queued")
    val docBad8 = encodeGameState(sSave8).toMutableMap()
    docBad8["mystery8Clues"] = listOf("two_buzzers", "not_a_piece")
    docBad8["arc8Pairs"] = mapOf("pair_buzzer" to "sideways",
        "pair_nope" to "same", "pair_ladder" to "same")
    docBad8["arc8"] = mapOf("chapter" to 3, "branch" to "bogus",
        "choice" to "bogus", "started" to true)
    val backBad8 = decodeGameState(docBad8)
    check(backBad8.mystery8Clues == setOf("two_buzzers") &&
        backBad8.arc8Pairs == mapOf("pair_ladder" to "same") &&
        backBad8.arc8Branch.isEmpty() && backBad8.arc8Choice.isEmpty(),
        "alibis: a tampered save is filtered to the registries — bogus pieces, pairs, judgments and landings dropped")
    val sDone8 = eng8.newState()
    sDone8.arc8Retired = true; sDone8.arc8Branch = "aligned"
    sDone8.arc8LetterBack = true
    val backDone8 = decodeGameState(encodeGameState(sDone8))
    check(backDone8.arc8Retired && backDone8.arc8Branch == "aligned" &&
        backDone8.arc8LetterBack,
        "alibis: a closed case (and its returned letter) round-trips")

    // ---------- the eight-case lifetime, driven ----------
    val engLife8 = Engine(8180)
    val life8 = engLife8.newState()
    var lifeDays8 = 0
    var arc8AfterArc7 = true
    var arc8OpenedBehind7 = false
    while (lifeDays8 < 1600 && !(life8.arcRetired && life8.arc2Retired &&
        life8.arc3Retired && life8.arc4Retired && life8.arc5Retired &&
        life8.arc6Retired && life8.arc7Retired && life8.arc8Retired)) {
        engLife8.onNewDay(life8)
        if (life8.arc8Started) {
            check(life8.arc7Retired,
                "alibis: the eighth case never opens over the seventh " +
                    "(day $lifeDays8)")
            if (!life8.arc7Retired) arc8AfterArc7 = false
            if (life8.arc7Retired) arc8OpenedBehind7 = true
        }
        lifeDays8++
    }
    check(life8.arcRetired && life8.arc2Retired && life8.arc3Retired &&
        life8.arc4Retired && life8.arc5Retired && life8.arc6Retired &&
        life8.arc7Retired && life8.arc8Retired,
        "alibis: one unattended life retires ALL EIGHT cases in order " +
            "(took $lifeDays8 days)")
    check(arc8AfterArc7 && arc8OpenedBehind7 &&
        life8.arc8Branch in Mystery8.BRANCH_KEYS &&
        Mystery8.dueChapter8(life8) == null,
        "alibis: the eighth case opened only behind the seventh, lands a real ending, and the queue is empty")

    // ---------- wiring ----------
    val mystery8Src = File(root, "src/com/hunt3r/southparktown/Mystery8.kt").readText()
    val engineSrc8 = File(root, "src/com/hunt3r/southparktown/Engine.kt").readText()
    val gameActivitySrc8 = File(root, "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val journalSrc8 = File(root, "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val prefsSrc8 = File(root, "src/com/hunt3r/southparktown/Prefs.kt").readText()
    val shenanigansSrc8 = File(root, "src/com/hunt3r/southparktown/Shenanigans.kt").readText()
    val talkGateSrc8 = File(root, "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val finalesSrc8 = File(root, "src/com/hunt3r/southparktown/Finales.kt").readText()
    val movieSrc8 = File(root, "src/com/hunt3r/southparktown/MovieNights.kt").readText()
    val walkSrc8 = File(root, "src/com/hunt3r/southparktown/Walk.kt").readText()
    val schoolSrc8 = File(root, "src/com/hunt3r/southparktown/School.kt").readText()
    check(!mystery8Src.contains("import android"),
        "alibis: Mystery8.kt stays pure Kotlin (JVM-testable)")
    check(engineSrc8.contains("Mystery8.dueChapter8") &&
        engineSrc8.contains("Mystery8.noteChapterStarted8") &&
        engineSrc8.contains("Mystery8.resolveReading") &&
        engineSrc8.contains("Mystery8.applyReadingEffects") &&
        engineSrc8.contains("Mystery8.noteParticipation8") &&
        engineSrc8.contains("Mystery8.noteLetterReturned") &&
        engineSrc8.contains("Mystery8.ambientCallback8"),
        "alibis: the engine airs the chapters, resolves the reading, feeds participation, lands the returned letter, keeps the callbacks")
    check(talkGateSrc8.contains("Mystery8.witnessLine8") &&
        talkGateSrc8.contains("Mystery8.aftermathLine8") &&
        gameActivitySrc8.contains("Mystery8.lookClueText8") &&
        gameActivitySrc8.contains("Mystery8.chooseFinale8") &&
        gameActivitySrc8.contains("maybeShowReading") &&
        gameActivitySrc8.contains("Mystery8.choosePair8") &&
        gameActivitySrc8.contains("maybeShowPair"),
        "alibis: TalkGate and GameActivity wire the tellings, the aftermath, the looks, the reading, and the graph's judging")
    check(journalSrc8.contains("Mystery8.boardLines8"),
        "alibis: the Journal renders the eighth case's graph")
    check(prefsSrc8.contains("\"arc8\" to mapOf") &&
        prefsSrc8.contains("\"mystery8Clues\" to") &&
        prefsSrc8.contains("\"arc8Pairs\" to"),
        "alibis: the save doc carries the eighth case additively")
    check(shenanigansSrc8.contains("Mystery8.CHAPTERS8"),
        "alibis: the eighth case's chapters resolve by id")
    check(finalesSrc8.contains("Mystery8.readingDue") &&
        movieSrc8.contains("Mystery8.readingDue") &&
        walkSrc8.contains("Mystery8.readingDue") &&
        schoolSrc8.contains("Mystery8.readingDue"),
        "alibis: every deference list stands down for the reading — two climaxes never stack")

    // ---------- version ----------
    val manifestSrc8 = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc8.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc8.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "alibis: the manifest carries 83 / 0.11.0c")

    // ---------- THE SPOILER WALL ----------
    // Nothing the player can read before the finale chapter
    // begins may state or imply the answer: not which pairs
    // are which, not whose stretch the corrected count
    // leaves open, not the evening's true shape. The scan
    // covers the first three chapters, every piece readable
    // before Family Night (discovery text, board text,
    // inert faces), the alibis and pair texts the board
    // prints, a mid-case board, the forecast, and the
    // changelog entry. The finale chapter's own materials
    // are the payoff and are not scanned — the wall stands
    // where the reveal begins.
    val banned8 = listOf("adler did", "adler took", "adler re-lettered",
        "did it himself", "did it herself", "pocketed", "in his cuff",
        "in her cuff", "slogan vote", "lost the vote",
        "hated the slogan", "voted against the slogan",
        "5:47", "17:47", "seventeen forty", "thirteen minutes",
        "nine minutes", "the true window", "the real window",
        "front hall", "slipped out", "slipped away",
        "detention ended early", "let out early", "let him out early",
        "clyde is innocent", "clyde didn't", "clyde did not",
        "didn't do it", "did not do it", "never did it",
        "took the letter", "the letter home", "one buzz in the evening",
        "buzzed only once", "buzzed once", "single buzz",
        "the gap in", "six minutes", "unwatched stretch",
        "far wing, past", "while the sign was being")
    val preReveal8 = mutableListOf<String>()
    for (def in Mystery8.CHAPTERS8.take(3)) {
        preReveal8.add(def.title); preReveal8.add(def.cause); preReveal8.add(def.blurb)
        for (st in def.stages) {
            preReveal8.add(st.title); preReveal8.add(st.banner)
            preReveal8.add(st.journalNote); preReveal8.add(st.objective)
        }
        for (l in def.coldOpen) preReveal8.add(l.text)
    }
    for (clue in Mystery8.CLUES8) {
        if (clue.minChapter > 2) continue
        preReveal8.add(clue.title)
        // a locked piece's LIVE detail is readable only
        // after its context chapter — payoff-adjacent by
        // construction; its inert face is what the wall
        // guards, and the inert face is scanned.
        if (clue.unlockChapter <= 2) preReveal8.add(clue.detail)
        preReveal8.add(clue.inertDetail)
        clue.spoken?.let { preReveal8.add(it) }
        clue.foundText?.let { preReveal8.add(it) }
    }
    for (a in Mystery8.ALIBIS8) {
        preReveal8.add(a.account); preReveal8.add(a.signature)
        preReveal8.add(a.voucher)
    }
    for (p in Mystery8.PAIRS8) {
        preReveal8.add(p.title); preReveal8.add(p.signatureText)
    }
    preReveal8.addAll(Mystery8.boardLines8(sBoard))
    val readme8 = File(root, "docs/CHANGELOG.md").readText()
    val entry8 = readme8.substringAfter("### v0.10.0f")
        .substringBefore("### v0.10.0e")
    preReveal8.add(entry8)
    for (term in banned8) {
        check(preReveal8.none { it.contains(term, ignoreCase = true) },
            "alibis: no pre-reveal surface breathes '$term' " +
                "(the wall holds: premise and structure only)")
    }
    check(entry8.contains("alibi graph") && entry8.contains("pairs"),
        "alibis: the changelog carries the premise and the shape — and stops there")
}

// ================= v0.9.0g: polish & performance pass #9 =================
// Queue #9 item 7 — the Queue #9 closer, audit-only, the
// v0.7.0g/v0.8.0g shape: this build adds NO feature. The
// 400-day audit soak below lives every Queue #9 surface
// in one long save (the 70-cast town, your crew's
// outings, a county fair week, darkroom prints outliving
// their album sources, the rival and the rival's crew,
// and the seventh case queuing behind the sixth with no
// overlap), a dedicated drive re-proves the seven-case
// lifetime, veteran save VIII re-measures the saturated
// save against the 512K ceiling, fit QA reads the queue's
// five new screens at both font scales, the eleven-rail
// TalkGate ladder is pinned in source and peeled live
// under fabricated total contention, the peak budget and
// audio census are re-measured, and the tuning-ledger
// sweep covers every Queue #9 constant. Production code
// changes only where the audit proves a defect.
// ================= v0.10.0g: polish & performance pass #10 =================
// Queue #10 item 7, the queue closer — an audit build in the
// v0.5.0i…v0.9.0g shape: the 400-day soak extended over the
// whole queue (your family, hero nights, the school play,
// group chats, your stand), the eight-case lifetime driven
// again, veteran save IX re-measured, the contention stack
// re-pinned at twelve agenda seats and eleven rails, fit QA
// on the queue's screens, the censuses re-counted and the
// tuning ledger swept for the queue's dials. The default is
// ZERO production changes — a production fix needs a failing
// check with its evidence first, in the open.
private fun sectionV0100g(root: String) {
    println("== v0.10.0g: polish & performance pass #10 — the Queue #10 audit ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.10.0g"),
        "v0.10.0g: the README carries this build's changelog entry")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.10.0g: the source tree and its description agree — " +
            "97 Kotlin files (the audit added none; the count " +
            "moved later with v0.11.0d's CastDataWave6.kt) (counted $ktCount)")

    // ---------- helpers the audit's drives share ----------
    fun setDayG(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun stageRoomG(s: GameState, names: Collection<String>) {
        for ((_, a) in s.agents) {
            a.location = if (a.isPlayer || a.name in names)
                "Elementary" else "KidsPark"
            a.destination = a.location
            a.asleep = false
            a.waypoints.clear()
        }
        s.playerInside = true
    }
    /** A real production, driven through the play's own
     *  machinery: a track chosen on audition day, every
     *  rehearsal attended on the cast track, opening night
     *  played in a staged full house, the review landed the
     *  morning after. Returns the state and its record. */
    fun driveProductionG(year: Int, seed: Int,
        audience: Boolean): Pair<GameState, Play.PlayRecord?> {
        val engP = Engine(seed.toLong())
        val sp = engP.newState()
        engP.createPlayer(sp, "Veteran", DEFAULT_APPEARANCE)
        val schP = PlayCalendar.scheduleFor(year)
        sp.friendship[Play.DIRECTOR] = 60
        setDayG(sp, schP.auditionDay); sp.timeMin = 16 * 60
        if (audience) Play.chooseAudience(sp)
        else Play.chooseAudition(sp, "deadpan")
        if (!audience) for (d in schP.rehearsalDays) {
            setDayG(sp, d); sp.timeMin = 16 * 60
            Play.attendRehearsal(sp)
        }
        val rec0 = Play.record(sp, year)
        if (rec0 != null) {
            val membersP = rec0.memberKids()
            for (i in membersP.indices)
                for (j in i + 1 until membersP.size)
                    sp.npcBonds[Threads.pairKey(membersP[i],
                        membersP[j])] = 6
            setDayG(sp, schP.openingDay); sp.timeMin = 19 * 60
            stageRoomG(sp, membersP + Play.DIRECTOR + listOf(
                "Randy", "Sharon", "Gerald", "Sheila", "Liane",
                "Stephen", "Linda", "Stuart", "Carol", "Steve",
                "Laura", "Mr. Tweek", "Mrs. Tweek", "Marvin"))
            if (Play.finaleDue(sp))
                Play.playFinale(sp, if (audience) 0 else 1)
            setDayG(sp, schP.openingDay + 1)
            Play.dailyRollover(sp)
        }
        return sp to Play.record(sp, year)
    }
    /** A stand with a real traded stretch behind it:
     *  permitted, stocked, staffed by its owner with a
     *  crowd really present, wrapped day by day through
     *  its own rollover until the rival's crew reviews it
     *  off the books. */
    fun driveStandG(seed: Int): GameState {
        val engS2 = Engine(seed.toLong())
        val ss = engS2.newState()
        engS2.createPlayer(ss, "Veteran", DEFAULT_APPEARANCE)
        Minigames.awardCoins(ss, 500)
        setDayG(ss, 30)
        Rival.playReveal(ss, 1)
        RivalCrew.theirCrew(ss)
        Stand.setup(ss, "MainStreet")
        Stand.setPrice(ss, "lemonade", 2)
        val crowdS = listOf("Stan", "Kyle", "Butters",
            "Wendy", "Craig", "Clyde")
        for (d in 0 until 8) {
            setDayG(ss, 30 + d)
            Stand.dailyRollover(ss)
            ss.timeMin = 9 * 60
            if (Stand.onHand(ss, "lemonade") < 6)
                Stand.order(ss, "lemonade", 10)
            if (d == 0) Stand.order(ss, "snack_cake", 6)
            Stand.openStand(ss, null)
            val meS = engS2.player(ss)
            meS.location = "MainStreet"
            meS.destination = "MainStreet"
            meS.waypoints.clear()
            for (cn in crowdS) {
                val a = ss.agents[cn]!!
                a.location = "MainStreet"
                a.destination = "MainStreet"
                a.asleep = false
                a.waypoints.clear()
            }
            for (t in 0 until 10) {
                ss.timeMin = 10 * 60 + t * 30
                Stand.tick(ss)
            }
        }
        setDayG(ss, 38)
        Stand.dailyRollover(ss)
        return ss
    }

    run {
        // ---------- the audit soak: 400 lived days ----------
        // One fresh town driven day by day through the real
        // rollover, with the lifer actually USING Queue #10:
        // the family arrives, the table is sat at on its
        // {0,2,4} rhythm and the allowance honestly earned,
        // chores are taken (and one deliberately let lapse),
        // a hero is made and patrolled on Wednesdays and
        // Saturdays until the caper closes and the mask is
        // on its hook, a full production is lived from
        // poster to review with its poster printed in the
        // darkroom, the three group rooms are born of the
        // life itself, and a stand is permitted, stocked,
        // staffed by self and crew, traded and reviewed —
        // its last lemonade left to spoil on the books.
        // The memory store is process-global, so the year
        // hands it back the way it found it.
        val memSnapshot10 = NpcMemoryStore.serialize()
        val eng = Engine(910_010)
        val s = eng.newState()
        eng.createPlayer(s, "Auditor", DEFAULT_APPEARANCE)
        s.inventory[Minigames.COIN_ITEM] = 600
        s.friendship[Play.DIRECTOR] = 60
        repeat(2) { eng.onNewDay(s) }
        Rival.playReveal(s, 1)
        RivalCrew.theirCrew(s)
        for (n in listOf("Stan", "Kyle", "Wendy", "Craig")) {
            s.friendship[n] = 80
            Crew.invite(s, n)
        }
        check(Crew.members(s).size == 4,
            "audit soak Q10: the lifer starts with a full " +
                "crew of four, asked at the Friend tier")
        var dinnersSat = 0
        var dinnerNights = 0
        var patrolDinnerOverlap = false
        var allowanceMornings = 0
        var lastAllowanceDay = -1
        var choreSkipped = false
        var choreSkipDoneMark = -1
        var choreLapsed = false
        var playAuditioned = false
        var livedYear = -1
        var rehearsalsAttended = 0
        var openingPlayed = false
        var posterPrint: DarkroomPrint? = null
        var standSetup = false
        var prevStaffed = 0
        var crewStaffed = 0
        var staffSnapshot: String? = null
        var arcOverlap = false
        var maxLifeText10 = 0
        var soakError: String? = null
        // group rooms are counted CUMULATIVELY across the
        // year: the phone store is a rolling window (its
        // cap evicts the oldest texts), so a room's season
        // is measured by everything it ever posted, not by
        // what happens to survive to day 400
        val groupSeen = mutableMapOf<String, MutableSet<String>>()
        fun openArcCount(): Int = listOf(
            s.arcStarted && !s.arcRetired,
            s.arc2Started && !s.arc2Retired,
            s.arc3Started && !s.arc3Retired,
            s.arc4Started && !s.arc4Retired,
            s.arc5Started && !s.arc5Retired,
            s.arc6Started && !s.arc6Retired,
            s.arc7Started && !s.arc7Retired,
            s.arc8Started && !s.arc8Retired).count { it }
        try {
            for (dayIdx in 0 until 400) {
                eng.onNewDay(s)
                for (t in s.phoneTexts)
                    if (t.trigger == Phone.GROUP)
                        groupSeen.getOrPut(t.thread) {
                            mutableSetOf() }.add(t.id)
                // the lifer actually reads their phone —
                // a sealed unread inbox halts the harvest
                // by design ("the town does not shout into
                // the void"), and no lifer goes 400 days
                // without opening it
                for (t in s.phoneTexts) t.read = true
                if (openArcCount() > 1) arcOverlap = true
                maxLifeText10 = maxOf(maxLifeText10, s.lifeText.size)
                val allowDay = s.life["famAllowanceDay"] ?: -1
                if (allowDay > lastAllowanceDay) {
                    lastAllowanceDay = allowDay
                    allowanceMornings++
                }
                val sdNow = Stand.staffedDays(s)
                if (sdNow > prevStaffed) {
                    val who = staffSnapshot
                    if (who != null && who != "you") crewStaffed++
                    prevStaffed = sdNow
                }
                s.timeMin = 10 * 60
                // ---- the family ----
                if (!Family.arrived(s) && Family.arrivalDue(s))
                    Family.chooseStance(s, "warm")
                if (Family.arrived(s)) {
                    if (choreSkipped && !choreLapsed &&
                        Family.activeChore(s) == null &&
                        (s.life["famChoreDone"] ?: 0) ==
                            choreSkipDoneMark)
                        choreLapsed = true
                    Family.reply(s, Family.MOM, s.absDay * 3 + 1)
                    Family.reply(s, Family.DAD, s.absDay * 5 + 2)
                    val chore = Family.activeChore(s)
                    if (chore != null) {
                        if (!choreSkipped && s.absDay > 200) {
                            choreSkipped = true
                            choreSkipDoneMark =
                                s.life["famChoreDone"] ?: 0
                        } else when (chore) {
                            "table" ->
                                Family.noteFixture(s, "table")
                            "photo" -> {
                                val rec = PhotoRecord(
                                    id = "soak-famphoto${s.absDay}",
                                    dayKey = s.todayKey,
                                    dateLabel = "home",
                                    timeMin = s.timeMin,
                                    locId = YOUR_HOUSE, inside = true,
                                    weatherId = s.weatherId,
                                    appearance = DEFAULT_APPEARANCE,
                                    figures = listOf(
                                        PhotoFigure("Auditor",
                                            "player", "happy"),
                                        PhotoFigure(Family.MOM,
                                            "resident", "happy")),
                                    seed = 910_010L + s.absDay,
                                    absDay = s.absDay)
                                Photos.applyPhoto(s, rec)
                                Family.notePhoto(s, rec)
                            }
                            "fetch" -> {
                                val item = Family.choreFetchItem(s)
                                val by = s.lifeText["famChoreBy"]
                                    ?: Family.MOM
                                if (item != null) {
                                    s.inventory[item] =
                                        (s.inventory[item] ?: 0) + 1
                                    Family.reply(s, by,
                                        s.absDay * 7 + 3)
                                }
                            }
                        }
                    }
                }
                if (Family.dinnerTonight(s)) {
                    dinnerNights++
                    if (Heroes.isPatrolNight(s.absDay))
                        patrolDinnerOverlap = true
                    s.timeMin = 18 * 60
                    Family.judgeTalk(s, Family.MOM)
                    Family.judgeTalk(s, Family.DAD)
                    Family.lookText(s, YOUR_HOUSE)
                    if (Family.dinStepsDone(s) == 3) dinnersSat++
                }
                // ---- the hero ----
                if (!Heroes.heroCreated(s) && Heroes.creationDue(s))
                    Heroes.createHero(s, "Captain Curfew", "speed")
                if (Heroes.isPatrolNight(s.absDay) &&
                    Heroes.heroCreated(s)) {
                    s.timeMin = 20 * 60
                    val stage = Heroes.caperStage(s)
                    if (!Heroes.caperDone(s) && stage in 1..4) {
                        val ch = Heroes.CHAPTERS[stage - 1]
                        eng.player(s).location = ch.locId
                        if (Heroes.caperBeatDue(s) == ch)
                            Heroes.playCaperBeat(s, true)
                    } else if (!Heroes.caperDone(s) && stage >= 5) {
                        eng.player(s).location = "KidsPark"
                        if (Heroes.finaleDue(s))
                            Heroes.playFinale(s, "name")
                    } else {
                        val spot = Heroes.PATROL_SPOTS[
                            (s.absDay / 7) %
                                Heroes.PATROL_SPOTS.size]
                        eng.player(s).location = spot
                        Heroes.lookText(s, spot)
                        Heroes.tick(s)
                    }
                }
                // ---- the play ----
                val sch = Play.schedule(s)
                if (s.absDay == sch.auditionDay && !playAuditioned) {
                    s.timeMin = 16 * 60
                    if (Play.chooseAudition(s, "deadpan") != null) {
                        playAuditioned = true
                        livedYear = sch.year
                    }
                }
                if (s.absDay in sch.rehearsalDays) {
                    s.timeMin = 16 * 60
                    if (Play.rehearsalOpen(s) &&
                        Play.attendRehearsal(s) != null)
                        rehearsalsAttended++
                }
                if (s.absDay in sch.openingDay..sch.openingDay + 2 &&
                    !openingPlayed) {
                    val rec = Play.currentRecord(s)
                    if (rec != null) {
                        s.timeMin = 19 * 60
                        stageRoomG(s, rec.memberKids() +
                            Play.DIRECTOR + listOf(
                                "Randy", "Sharon", "Gerald", "Sheila",
                                "Liane", "Stephen", "Linda", "Stuart",
                                "Carol", "Steve", "Laura", "Marvin"))
                        if (Play.finaleDue(s)) {
                            Play.playFinale(s, 1)
                            if (Play.currentRecord(s)?.night ==
                                "played") openingPlayed = true
                        }
                    }
                }
                if (openingPlayed && posterPrint == null) {
                    val rec = Play.currentRecord(s)
                    if (rec != null && rec.posterId.isNotEmpty()) {
                        s.timeMin = 11 * 60
                        posterPrint = Darkroom.develop(s,
                            rec.posterId, Darkroom.SIZE_PRINT)?.print
                    }
                }
                // ---- the stand ----
                if (!standSetup && s.absDay >= 6) {
                    Stand.setup(s, "MainStreet")
                    standSetup = Stand.hasStand(s)
                    if (standSetup) {
                        Stand.setPrice(s, "lemonade", 2)
                        Stand.order(s, "lemonade", 12)
                        Stand.order(s, "snack_cake", 6)
                    }
                }
                if (standSetup && dayIdx < 390 && s.absDay % 2 == 0) {
                    if (Stand.onHand(s, "lemonade") < 4) {
                        s.timeMin = 9 * 60
                        Stand.order(s, "lemonade", 8)
                    }
                    var crewWorked = false
                    if (s.absDay % 14 == 6) {
                        val member = Crew.members(s).firstOrNull()
                        if (member != null) {
                            s.timeMin = 16 * 60
                            val line = Stand.openStand(s, member)
                            if (line.contains("walking over") ||
                                line.contains("on the counter")) {
                                val a = s.agents[member]!!
                                a.location = "MainStreet"
                                a.destination = "MainStreet"
                                a.asleep = false
                                a.waypoints.clear()
                                crewWorked = true
                                for (t in 0 until 6) {
                                    s.timeMin = 16 * 60 + 30 + t * 30
                                    Stand.tick(s)
                                }
                            }
                        }
                    }
                    if (!crewWorked) {
                        s.timeMin = 9 * 60
                        Stand.openStand(s, null)
                        val me = eng.player(s)
                        me.location = "MainStreet"
                        me.destination = "MainStreet"
                        me.waypoints.clear()
                        for (cn in listOf("Stan", "Kyle", "Butters",
                            "Wendy", "Craig", "Clyde")) {
                            val a = s.agents[cn]!!
                            a.location = "MainStreet"
                            a.destination = "MainStreet"
                            a.asleep = false
                            a.waypoints.clear()
                        }
                        for (t in 0 until 8) {
                            s.timeMin = 10 * 60 + t * 30
                            Stand.tick(s)
                        }
                    }
                    s.timeMin = 10 * 60
                }
                staffSnapshot = s.lifeText["standStaff"]
                if (dayIdx == 392 && standSetup) {
                    // the last batch is left on the crate —
                    // it spoils into the books, honestly
                    s.timeMin = 9 * 60
                    Stand.order(s, "lemonade", 12)
                }
            }
        } catch (e: Exception) {
            soakError = "${e.javaClass.simpleName}: ${e.message}"
        }
        check(soakError == null,
            "audit soak Q10: 400 days of the full Queue #10 " +
                "stack without an exception (got $soakError)")
        check(s.absDay >= 400,
            "audit soak Q10: the calendar advanced the full " +
                "400 days (got ${s.absDay})")
        check(!arcOverlap,
            "audit soak Q10: never two cases open at once in " +
                "400 lived days — the queue's discipline held " +
                "inside a life that was busy with everything else")
        check(Family.arrived(s) && Family.stance(s) == "warm",
            "audit soak Q10: the family arrived and the " +
                "arrival's stance stands for the save's life")
        println("audit soak Q10: dinners sat=$dinnersSat of " +
            "$dinnerNights family nights, allowance mornings=" +
            "$allowanceMornings, chores done=" +
            "${s.life["famChoreDone"] ?: 0} (one lapsed: " +
            "$choreLapsed), patrol nights=" +
            "${s.life["heroPatrolNights"] ?: 0}, caper done=" +
            "${Heroes.caperDone(s)}, play year=$livedYear " +
            "rehearsals=$rehearsalsAttended opening=$openingPlayed, " +
            "stand staffed=${Stand.staffedDays(s)} (crew " +
            "$crewStaffed), sold=${Stand.books(s).totalSold} " +
            "spoiled=${Stand.books(s).totalSpoiled}, maxLifeText=" +
            "$maxLifeText10")
        check(dinnerNights >= 100 && dinnersSat >= 60,
            "audit soak Q10: family dinners stood on their " +
                "{0,2,4} rhythm all year and the lifer sat at " +
                "the table — $dinnersSat full tables of " +
                "$dinnerNights family nights (the rest deferred " +
                "honestly, never faked)")
        check(!patrolDinnerOverlap,
            "audit soak Q10: not one evening in 400 days was " +
                "both a family-dinner night and a patrol night " +
                "— the disjoint rhythms, lived")
        check(allowanceMornings >= 20,
            "audit soak Q10: the allowance landed on the " +
                "week's first morning again and again, earned " +
                "by the table (mornings $allowanceMornings)")
        check((s.life["famChoreDone"] ?: 0) >= 5 && choreLapsed,
            "audit soak Q10: chores were offered, taken and " +
                "settled through the real verbs — and one was " +
                "left undone and lapsed free at midnight, " +
                "exactly as promised (done " +
                "${s.life["famChoreDone"] ?: 0})")
        check(Family.latestFamilyPhoto(s) != null,
            "audit soak Q10: a family photo was taken at " +
                "home, so the frame on the wall is full")
        check((s.life["heroPatrolNights"] ?: 0) >= 25 &&
            Heroes.caperDone(s) &&
            House.decorFor(s).contains("hero_mask"),
            "audit soak Q10: patrols stood across the year's " +
                "Wednesdays and Saturdays (nights " +
                "${s.life["heroPatrolNights"] ?: 0}), the caper " +
                "played to its ending, and the mask hangs by " +
                "the door — the decor census's 17th piece, derived")
        val playRec = if (livedYear > 0) Play.record(s, livedYear)
            else null
        check(playAuditioned && rehearsalsAttended >= 2 &&
            openingPlayed && playRec != null &&
            playRec.verdict in listOf("triumph", "solid",
                "disaster") && playRec.review.isNotEmpty(),
            "audit soak Q10: a full production was lived — " +
                "auditioned, rehearsed ($rehearsalsAttended of " +
                "4), opened, judged (${playRec?.verdict}) and " +
                "reviewed in the morning-after words")
        check(posterPrint != null && playRec != null &&
