        val famTexts = groupSeen[GroupChats.FAMILY_ID]?.size ?: 0
        val playTexts = groupSeen[GroupChats.PLAY_ID]?.size ?: 0
        check(crewTexts >= 10 && famTexts >= 5 && playTexts >= 4,
            "audit soak Q10: all three group rooms were born " +
                "of the life and kept talking — crew $crewTexts, " +
                "family $famTexts, play $playTexts texts across " +
                "the year, counted cumulatively (the store " +
                "itself is a capped rolling window)")
