    run {
        // ---------- fit QA: Queue #10's newest screens ----------
        // The Chrome discipline on the surfaces the queue
        // added, composed the way their screens compose
        // them: the 🪪 YOU card with the hero line riding
        // it, the family frame dialog (empty and filled),
        // the 🦸 HERO LOG off a closed caper, the 🎭
        // SCHOOL PLAY page off a played production, the
        // 💰 YOUR STAND books off a traded season, a group
        // thread screen (the play room's long member line,
        // its header and its bubbles), and the eighth
        // case's alibi board with PROVEN and REFUTED
        // verdicts standing side by side.
        val engF = Engine(910_505)
        // the YOU card, composed from the same pure calls
        // JournalActivity makes
        val fitYou = engF.newState()
        engF.createPlayer(fitYou, "Fitcheck", DEFAULT_APPEARANCE)
        Heroes.createHero(fitYou, "Captain Curfew", "speed")
        for (ch in FactionMissions.CHAINS)
            fitYou.life["fmMask:${ch.factionId}"] = 0b111
        for (ch in Capstones.CHAINS)
            fitYou.life["capMask:${ch.factionId}"] = 0b111
        for (n in listOf("Stan", "Kyle", "Wendy"))
            fitYou.friendship[n] = 95
        fitYou.convertedResidents.addAll(listOf(
            "Alexandria Featherstonehaugh",
            "Bartholomew With A Very Long Name Indeed"))
        val youLines = mutableListOf<String>()
        youLines += "Fitcheck"
        youLines += "⚔️ Standings: " + FACTIONS.joinToString(" · ") { f ->
            val fs = fitYou.factionStates[f.id]
            "${f.name} ${fs?.let {
                Factions.standingLabel(it.playerStanding) } ?: "—"}" }
        val scoredYou = fitYou.friendship.entries
            .sortedByDescending { it.value }.take(3)
        if (scoredYou.isNotEmpty())
            youLines += "💛 Closest: " + scoredYou.joinToString(", ") {
                (n, p) -> "$n (${Relationships.tierLabel(p)})" }
        val titlesYou = FactionMissions.titlesEarned(fitYou)
        if (titlesYou.isNotEmpty())
            youLines += "⚔️ Titles: ${titlesYou.joinToString(" · ")}"
        Heroes.youCardLine(fitYou)?.let { youLines += it }
        val capTitlesYou = Capstones.titlesEarned(fitYou)
        if (capTitlesYou.isNotEmpty())
            youLines += "🏛 Capstone titles: " +
                capTitlesYou.joinToString(" · ")
        youLines += "🎪 Town history so far: " +
            "${fitYou.townLog.size} entries in the log · " +
            "🏠 Moved in because of you: " +
            fitYou.convertedResidents.joinToString(", ")
        check(Heroes.youCardLine(fitYou)?.contains("Captain Curfew") == true &&
            titlesYou.isNotEmpty() && capTitlesYou.isNotEmpty(),
            "fitQA: (staging) the YOU card carries the hero " +
                "line beside the earned titles")
        // the family frame dialog, both faces
        val frameLines = listOf(
            "👨‍👩‍👧 An empty frame, hung with intent. Take a " +
                "photo at home with Mom or Dad in it and this " +
                "spot is theirs.",
            "👨‍👩‍👧 The family photo — Sat, Jun 14, right " +
                "here at home. The frame waited for a real " +
                "one, and got it.")
        // the HERO LOG off a closed caper
        val fitHero = engF.newState()
        engF.createPlayer(fitHero, "Fitcheck", DEFAULT_APPEARANCE)
        Heroes.createHero(fitHero, "Captain Curfew", "speed")
        fitHero.life["heroPatrolNights"] = 57
        fitHero.life["heroAssists"] = 83
        fitHero.life["heroIncidents"] = 31
        fitHero.life["heroEscorts"] = 22
        fitHero.life["caperStage"] = 6
        fitHero.life["caperHelped"] = 4
        fitHero.lifeText["caperStance"] = "name"
        fitHero.lifeText["mark:hero_caper"] = "name"
        val heroLines = Heroes.pageLines(fitHero)
        check(heroLines.first().contains("Captain Curfew") &&
            heroLines.any { it.contains("CLOSED") },
            "fitQA: the HERO LOG page opens on the hero's " +
                "own name line and closes the caper in its " +
                "own words")
        // the SCHOOL PLAY page off a played production
        val (fitPlayState, fitPlayRec) =
            driveProductionG(2027, 910_909, audience = false)
        val playLines = Play.pageLines(fitPlayState)
        check(fitPlayRec != null && playLines.any {
                it.contains("VERDICT") },
            "fitQA: the SCHOOL PLAY page carries its verdict")
        // the group thread screen off that same production:
        // the room's header (title + the long member line)
        // and bubbles in the phone's labeled form
        val groupLines = mutableListOf<String>()
        groupLines += GroupChats.titleFor(fitPlayState,
            GroupChats.PLAY_ID)
        groupLines += GroupChats.memberLine(fitPlayState,
            GroupChats.PLAY_ID)
        groupLines += "Stan: places, everybody — the " +
            "mountain is not going to move itself, WHICH IS " +
            "THE WHOLE POINT OF THE PLAY"
        groupLines += GroupChats.memberLine(fitPlayState,
            GroupChats.FAMILY_ID)
        check(GroupChats.membersOf(fitPlayState,
                GroupChats.PLAY_ID).size >= 10,
            "fitQA: the play room's member line is the long " +
                "one — cast, ensemble and the director " +
                "(${GroupChats.membersOf(fitPlayState, GroupChats.PLAY_ID).size} names)")
        // the STAND page off a traded scratch
        val fitStand = driveStandG(910_910)
        val standLines = Stand.pageLines(fitStand)
        check(standLines.first().contains("YOUR STAND") &&
            Stand.books(fitStand).totalSold > 0,
            "fitQA: the YOUR STAND page heads its books off " +
                "a season that actually traded")
        // the alibi board: verdicts side by side
        val boardQ = engF.newState()
        engF.createPlayer(boardQ, "Board", DEFAULT_APPEARANCE)
        boardQ.arc8Started = true; boardQ.arc8Chapter = 3
        for (c in Mystery8.CLUES8) boardQ.mystery8Clues.add(c.id)
        Mystery8.PAIRS8.forEachIndexed { i, p ->
            val truth = if (p.truthSame) "same" else "different"
            when (i) {
                0, 2 -> boardQ.arc8Pairs[p.id] = truth
                1 -> boardQ.arc8Pairs[p.id] =
                    if (truth == "same") "different" else "same"
            }
        }
        val boardLines = Mystery8.boardLines8(boardQ)
        val boardJoined = boardLines.joinToString("\n")
        check(boardJoined.contains("PROVEN") &&
            boardJoined.contains("REFUTED") &&
            boardJoined.contains("OPEN"),
            "fitQA: the alibi board stands PROVEN, REFUTED " +
                "and OPEN verdicts side by side, derived — " +
                "never stored")
        val q10Lines = mutableListOf<String>()
        q10Lines += "🦸 HERO LOG"
        q10Lines += youLines
        q10Lines += frameLines
        q10Lines += heroLines
        q10Lines += playLines
        q10Lines += groupLines
        q10Lines += standLines
        q10Lines += boardLines
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { s: String -> s.length * 10f * fs }
            for (line in q10Lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a Queue #10 screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a Queue #10 screen line never " +
                        "collapses at fs $fs")
            }
        }
    }

    run {
        // ---------- the rail order, final form: eleven rails ----------
        // Queue #10 added NO rail either — the family talk
        // is its own sheet, hero-register lines ride the
        // dialogue layer, the play and the stand speak
        // through fixtures and menus. The ladder stands
        // exactly as v0.8.0g pinned it. Pin the full order
        // in source first — enum and try-order.
        val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        val enumBody = tgSrc.substring(
            tgSrc.indexOf("enum class Rail"),
            tgSrc.indexOf("data class Gate"))
        val enumOrder = listOf("DELIVER", "HOLIDAY_BEAT", "FINALE",
            "CLIMAX", "DINNER", "WORK", "FACTION_MISSION",
            "EMERG_OFFER", "RIVAL", "ERRAND_ASK", "DIALOGUE")
        val enumIdx = enumOrder.map { enumBody.indexOf(it) }
        check(enumIdx.all { it >= 0 } &&
            enumIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: the Rail enum declares the eleven " +
                "rails in ladder order")
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        val railOrder = enumOrder.map { "Rail.$it" }
        val railIdx = railOrder.map { gateBody.indexOf(it) }
        check(railIdx.all { it >= 0 } &&
            railIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: gateFor tries the eleven rails in " +
                "ladder order — DELIVER, HOLIDAY_BEAT, FINALE, " +
                "CLIMAX, DINNER, WORK, FACTION_MISSION, " +
                "EMERG_OFFER, RIVAL, ERRAND_ASK, DIALOGUE")
        check(TalkGate.Rail.values().size == 11,
            "contention: eleven rails exactly — Queue #10 " +
                "added none (the family sheet is its own door, " +
                "pinned in v0.10.0a's section)")
    }

    run {
        // ---------- the agenda stack at twelve seats ----------
        // The full claim order in Engine.effectiveAgendaBlock,
        // read off the code (not off any brief): each later
        // seat's claim refines the earlier ones, and the
        // crew hook still sits LAST — set pieces take the
        // person first, always.
        val engSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt")
            .readText()
        val stackOrder = listOf("Dinners.gatheringBlock",
            "Family.gatheringBlock", "Jobs.gatheringBlock",
            "MovieNights.gatheringBlock",
            "Capstones.gatheringBlock", "Finales.gatheringBlock",
            "Fair.gatheringBlock", "RivalCrew.gatheringBlock",
            "Heroes.gatheringBlock", "Play.gatheringBlock",
            "Stand.gatheringBlock", " Crew.gatheringBlock")
        val stackIdx = stackOrder.map { engSrc.indexOf(it) }
        check(stackIdx.all { it >= 0 } &&
            stackIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: the agenda stack seats twelve " +
                "claims in the code's own order — dinners, " +
                "the family's table hard by them, jobs, movie " +
                "nights, capstones, finales, the fair, the " +
                "rival crew's turf, patrol, rehearsals, the " +
                "stand, and your crew's hook last of all")
        // the family's table sits INSIDE the dinner family,
        // second seat — finales and fairs still outrank it
        // in effect because their claims refine it (the
        // family module defers to both, pinned in its own
        // section); pin the seat itself here.
        check(stackIdx[1] == engSrc.indexOf("Family.gatheringBlock") &&
            stackOrder[1] == "Family.gatheringBlock",
            "contention: the family dinner's seat is the " +
                "stack's second, immediately after the cast " +
                "households' — the two tables share one family " +
                "of claims")
    }

    run {
        // ---------- seams: the queue against the town ----------
        // (1) family dinner × hosted dinner: on a night the
        // player HOSTS a cast household, the family's own
        // table stands down — one house, one dinner.
        val engX = Engine(910_606)
        val sHost = engX.newState()
        engX.createPlayer(sHost, "Host", DEFAULT_APPEARANCE)
        var hostDay = -1
        for (d in 0..13) if (d % 7 in Family.DINNER_WEEKDAYS) {
            hostDay = d; break
        }
        sHost.absDay = 3
        Family.chooseStance(sHost, "warm")
        sHost.absDay = hostDay
        sHost.life["hostDay"] = hostDay
        sHost.lifeText["hostHousehold"] = Dinners.HOUSEHOLDS[0].id
        check(Dinners.hostingTonight(sHost) != null &&
            !Family.dinnerTonight(sHost),
            "seam: a hosted night is the cast's — the " +
                "family table stands down in its own house " +
                "(day $hostDay is a family rhythm night, and " +
                "still the folks don't set their table)")
        sHost.life.remove("hostDay")
        check(Family.dinnerTonight(sHost),
            "seam: un-host the night and the family's table " +
                "is back — the stand-down was the hosting, " +
                "nothing else")
        // (2) patrol × family dinner, swept arithmetically:
        // two full years of evenings, never both.
        val sSweep = engX.newState()
        engX.createPlayer(sSweep, "Sweep", DEFAULT_APPEARANCE)
        sSweep.absDay = 3
        Family.chooseStance(sSweep, "fine")
        var bothCount = 0
        for (d in 0 until 730) {
            sSweep.absDay = d
            if (Family.dinnerTonight(sSweep) &&
                Heroes.isPatrolNight(d)) bothCount++
        }
        check(bothCount == 0,
            "seam: across 730 swept evenings, no night is " +
                "both a family dinner and a patrol — the " +
                "{0,2,4} table and the {3,6} patrol are " +
                "disjoint by construction, not by luck")
        // (3) play rehearsals × school lessons: rehearsals
        // begin the minute class lets out, and the claim
        // holds its cast in the rehearsal window only.
        check(Play.REH_FROM >= School.CLASS_TO,
            "seam: rehearsals start at ${Play.REH_FROM}, " +
                "class ends at ${School.CLASS_TO} — the play " +
                "never pulls a kid out of a lesson")
        val sReh = engX.newState()
        engX.createPlayer(sReh, "Reh", DEFAULT_APPEARANCE)
        val schR = PlayCalendar.scheduleFor(2027)
        setDayG(sReh, schR.rehearsalDays[0])
        Play.runCasting(sReh, 2027, null)
        val recR = Play.record(sReh, 2027)
        val castKid = recR?.memberKids()?.firstOrNull()
        check(recR != null && castKid != null &&
            Play.gatheringBlock(sReh, castKid!!, 16 * 60) != null &&
            Play.gatheringBlock(sReh, castKid, 14 * 60) == null,
            "seam: on a rehearsal afternoon the claim holds " +
                "its cast at 4 PM — and at 2 PM, class hours, " +
                "it holds nobody")
        // (4) stand staffing × the crew's occupied rules:
        // an asleep crewmate is refused in plain words; the
        // same crewmate awake works the wrap for friendship.
        val sStand = engX.newState()
        engX.createPlayer(sStand, "Shop", DEFAULT_APPEARANCE)
        Minigames.awardCoins(sStand, 200)
        sStand.friendship["Stan"] = 30
        Crew.invite(sStand, "Stan")
        Stand.setup(sStand, "MainStreet")
        sStand.agents["Stan"]!!.asleep = true
        sStand.timeMin = 9 * 60
        val busyLine = Stand.openStand(sStand, "Stan")
        check(!Stand.isOpen(sStand) && busyLine.contains("can't"),
            "seam: an occupied crewmate can't be assigned " +
                "to the stand, and the refusal names the " +
                "crew's own rule ($busyLine)")
        // (5) the eighth case × the school day: a due
        // reading quiets the classroom like every climax
        // before it — and an unjudged graph quiets nothing.
        val sRead = engX.newState()
        engX.createPlayer(sRead, "Read", DEFAULT_APPEARANCE)
        setDayG(sRead, 40)
        sRead.timeMin = 13 * 60
        sRead.arc8Started = true
        sRead.shenaniganId = Mystery8.FINALE8_ID
        sRead.shenaniganDay = sRead.todayKey
        for (p in Mystery8.PAIRS8)
            sRead.arc8Pairs[p.id] = "same"
        check(Mystery8.readingDue(sRead.copy(timeMin = 13 * 60)) &&
            School.quietReason(sRead) == School.QUIET_CASE &&
            Finales.climaxPending(sRead),
            "seam: with the graph fully judged and the " +
                "reading due, the school day stands quiet — " +
                "the eighth case owns its day like the seven " +
                "before it")
        sRead.arc8Pairs.clear()
        check(School.quietReason(sRead) == null &&
            !Finales.climaxPending(sRead),
            "seam: an unjudged graph demands nothing — the " +
                "classroom runs, the day is ordinary")
        // (6) group posts × the solo harvest: two rooms
        // born on one morning land inside the group ceiling
        // and the morning's whole budget, across two
        // mornings at the latest.
        val sg = engX.newState()
        engX.createPlayer(sg, "NewKid", DEFAULT_APPEARANCE)
        setDayG(sg, 3)
        sg.friendship["Stan"] = 30
        Crew.invite(sg, "Stan")
        Family.chooseStance(sg, "warm")
        var morningsOk = true
        for (m in 4..5) {
            setDayG(sg, m)
            val before = sg.phoneTexts.size
            Phone.dailyRollover(sg)
            val landed = sg.phoneTexts.drop(before)
            if (landed.count { it.trigger == Phone.GROUP } >
                GroupChats.MAX_GROUP_PER_DAY) morningsOk = false
            if (landed.size > Phone.MAX_NEW_PER_DAY)
                morningsOk = false
        }
        check(morningsOk &&
            sg.phoneTexts.any { it.thread == GroupChats.CREW_ID } &&
            sg.phoneTexts.any { it.thread == GroupChats.FAMILY_ID },
            "seam: two rooms born of one week's life land " +
                "inside the group ceiling (≤2 a morning) and " +
                "the phone's whole morning budget (≤4) — the " +
                "rooms share the harvest, they don't flood it")
    }

    run {
        // ---------- the peak budget, ninth distance ----------
        // The same pins as v0.4.0e, on today's render set,
        // and the censuses counted honestly: Queue #10
        // shipped five systems and not one new audio family;
        // the house gained its 17th decor piece (the hero
        // mask, derived — the census counts the catalogue).
        val pb = SoundGen.PeakBudget
        println("budget v0.10.0g: named ${pb.namedStack()}, " +
            "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
            "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
            "amb ${pb.ambiencePeakOut()}, bark signatures " +
            "${Barks.PATTERNS.size} (" +
            "${Barks.PATTERNS.values.distinct().size} distinct), " +
            "decor ${House.DECOR.size}")
        check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
            "budget: the named stack has not drifted since v0.4.0e " +
                "(got ${pb.namedStack()})")
        check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
            "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
        check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
            "budget: the bark stack has not drifted (got ${pb.barkStack()})")
        check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
            pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
            "budget: neither barks nor mood contours out-peak the plain blip")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val post = AudioSettings.DEFAULT.gain(
                AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
                pb.peakOf(SoundGen.renderAmbience(bed))
            check(post <= pb.ambiencePeakOut() + 0.002f,
                "budget: bed $bed stays inside the ambience allocation")
        }
        check(SoundGen.SFX_IDS.size == 21 &&
            SoundGen.BlipFam.values().size == 7 &&
            SoundGen.BlipMood.values().size == 4 &&
            SoundGen.AmbBed.values().size == 6,
            "budget: the family census is unchanged — 21 named " +
                "effects, 7 blip families, 4 moods, 6 ambience " +
                "beds. Queue #10 added no audio family (got " +
                "${SoundGen.SFX_IDS.size}/${SoundGen.BlipFam.values().size}/" +
                "${SoundGen.BlipMood.values().size}/${SoundGen.AmbBed.values().size})")
        check(Barks.PATTERNS.size == CharacterSystem.CAST.size &&
            Barks.PATTERNS.size == 98 &&
            Barks.PATTERNS.keys == CharacterSystem.CAST.keys &&
            Barks.PATTERNS.values.distinct().size ==
            Barks.PATTERNS.size,
            "budget: the bark census at 98 — one rhythm " +
                "signature per cast member, all 98 distinct " +
                "(got ${Barks.PATTERNS.size}, " +
                "${Barks.PATTERNS.values.distinct().size} distinct)")
        check(House.DECOR.size == 17 &&
            House.DECOR.any { it.id == "hero_mask" } &&
            House.SHELF_SLOTS == 12,
            "census: the house catalogue stands at 17 decor " +
                "pieces — the hero mask the newest, derived " +
                "like every piece — over a 12-slot trophy " +
                "shelf (got ${House.DECOR.size})")
    }

    run {
        // ---------- the tuning ledger, swept for Queue #10 ----------
        // Every paper-tuned Queue #10 constant, named in
        // the ledger section itself — scoped to the
        // section, so a dial that only ever made a
        // changelog doesn't count. (The cases entry already
        // closes with the eighth case — v0.10.0f's own
        // changelog carried it there; the sweep proves it.)
        val tuning = File(root, "docs/TUNING.md").readText()
        val ledgerStart = tuning.indexOf("## Tuning ledger")
        val ledgerEnd = tuning.length
        check(ledgerStart >= 0 && ledgerEnd > ledgerStart,
            "ledger: the ledger section stands ahead of the changelog")
        val ledger = tuning.substring(ledgerStart, ledgerEnd)
        val q10Dials = listOf(
            // your family (v0.10.0a)
            "ARRIVAL_ABS_DAY", "DINNER_WEEKDAYS", "GUEST_CHANCE",
            "ALLOWANCE_COINS", "ALLOWANCE_WEEKDAY",
            // hero nights (v0.10.0b)
            "PATROL_WEEKDAYS", "PATROL_FROM", "PATROL_TO",
            "PATROL_SPOTS",
            // the school play (v0.10.0c)
            "REHEARSALS", "REH_FROM", "REH_TO", "FINAL_FROM",
            "FINAL_TO", "GRACE_DAYS", "NPC_ATTEND_PCT",
            "REHEARSAL_PAY", "STAGE_NERVE",
            // group chats (v0.10.0d)
            "MAX_GROUP_PER_DAY", "MAX_TEXTS",
            // your stand (v0.10.0e)
            "PERMIT_COST", "KIT_COST", "MOVE_COST", "STAND_LOCS",
            "OPEN_FROM", "OPEN_TO", "ORDER_CAP", "PRICE_MAX_MULT",
            "BASE_CHANCE", "BUY_CAP_DAY", "CREW_EFFICIENCY",
            "STAFF_FRIENDSHIP", "REVIEW_DAYS", "REVIEW_EVERY",
            "REVIEW_LIFT", "REVIEW_LIFT_DAYS",
            // mystery #8 (v0.10.0f)
            "OPEN_DELAY_DAYS", "CHAPTER_GAP_DAYS",
            "LETTER_RETURN_DELAY_DAYS")
        for (dial in q10Dials)
            check(dial in ledger,
                "ledger: the Queue #10 dial $dial is named in " +
                    "the tuning ledger")
        check(ledger.contains("LETTER_RETURN_DELAY_DAYS") &&
            ledger.contains("Mystery8"),
            "ledger: the cases entry closes with the eighth " +
                "case — its delays named beside the seven " +
                "before it")
        check(Family.ALLOWANCE_COINS == 3 &&
            Family.ALLOWANCE_WEEKDAY == 0 &&
            Family.DINNER_WEEKDAYS == setOf(0, 2, 4) &&
            Family.ARRIVAL_ABS_DAY == 3 &&
            Heroes.PATROL_WEEKDAYS == setOf(3, 6) &&
            Heroes.PATROL_FROM == 19 * 60 + 30 &&
            Heroes.PATROL_TO == 22 * 60 &&
            Play.REHEARSALS == 4 && Play.REH_FROM == 15 * 60 &&
            Play.REH_TO == 17 * 60 &&
            Play.NPC_ATTEND_PCT == 82 &&
            GroupChats.MAX_GROUP_PER_DAY == 2 &&
            Phone.MAX_TEXTS == 220 &&
            Stand.PERMIT_COST == 10 && Stand.KIT_COST == 15 &&
            Stand.MOVE_COST == 5 && Stand.ORDER_CAP == 12 &&
            Stand.PRICE_MAX_MULT == 3 &&
            Stand.BASE_CHANCE == 0.30 &&
            Stand.BUY_CAP_DAY == 2 &&
            Stand.CREW_EFFICIENCY == 0.7 &&
            Stand.STAFF_FRIENDSHIP == 1 &&
            Stand.REVIEW_DAYS == 5 && Stand.REVIEW_EVERY == 10 &&
            Stand.REVIEW_LIFT == 1.5 &&
            Stand.REVIEW_LIFT_DAYS == 7 &&
            Mystery8.OPEN_DELAY_DAYS == 10 &&
            Mystery8.CHAPTER_GAP_DAYS == 7 &&
            Mystery8.LETTER_RETURN_DELAY_DAYS == 7,
            "ledger: the Queue #10 dials stand at the values " +
                "the ledger prints")
    }

    // ---------- the release pin ----------
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
}

private fun sectionV090g(root: String) {
    println("== v0.9.0g: polish & performance pass #9 — the Queue #9 audit ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.9.0g"),
        "v0.9.0g: the README carries this build's changelog entry")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.9.0g: the source tree and its description agree — " +
            "97 Kotlin files (the audit added none; the count " +
            "moved later with v0.10.0c's Play.kt, v0.10.0d's " +
            "GroupChats.kt, v0.10.0e's Stand.kt and " +
            "v0.10.0f's Mystery8.kt, v0.11.0c's Sleepovers.kt " +
            "and v0.11.0d's CastDataWave6.kt) " +
            "(counted $ktCount)")

    run {
        // ---------- the audit soak: 400 lived days ----------
        // One fresh town driven day by day through the real
        // rollover, with the lifer actually USING Queue #9:
        // a crew recruited and rendezvoused on the Walk
        // graph, the August fair attended and entered, a
        // print developed off the fair frame and left to
        // outlive its source at the album cap, crew-vs-crew
        // contests taken as the rival brings them, and the
        // wave-5 newcomers met in the wild. The memory
        // store is process-global, so the year hands it
        // back the way it found it.
        val memSnapshot9 = NpcMemoryStore.serialize()
        val engA = Engine(909_007)
        val sA = engA.newState()
        engA.createPlayer(sA, "Auditor", DEFAULT_APPEARANCE)
        // the reveal is a day-1-to-3 beat in play (and
        // revealed() reads a revealedDay > 0), so the lifer
        // lives two honest days before the crowning — the
        // v0.9.0e sections stage it the same way
        repeat(2) { engA.onNewDay(sA) }
        val rivalA = Rival.rivalOf(sA)
        Rival.playReveal(sA, 1)
        for (n in listOf("Stan", "Kyle", "Wendy", "Craig")) {
            sA.friendship[n] = 80
            Crew.invite(sA, n)
        }
        check(Crew.members(sA).size == 4,
            "audit soak: the lifer starts with a full crew " +
                "of four, asked at the Friend tier")
        check(RivalCrew.theirCrew(sA).size == 3,
            "audit soak: the rival's crew stands derived " +
                "from day one — three kids, none of them the rival")
        sA.inventory[Minigames.COIN_ITEM] = 300
        val wave5A = listOf("Roger", "Ryan", "Sarah", "Alexis",
            "Mr. Testaburger", "Nathan", "Sophie", "Big Gay Al")
        val metA = mutableSetOf<String>()
        var outingDaysA = 0
        var crewSettlesA = 0
        var fairPhotoA = false
        var fairFishA = false
        var fairDunkA = false
        var printA: DarkroomPrint? = null
        var printSurvivedA = false
        var printHungA = false
        var arc7OverlapA = false
        var soakErrorA: String? = null
        try {
            for (dayIdx in 0 until 400) {
                engA.onNewDay(sA)
                sA.timeMin = 10 * 60
                if (sA.arc7Started && !sA.arc6Retired)
                    arc7OverlapA = true
                // wave-5 newcomers, met the Q8 way: their
                // asks when the board offers them, and their
                // faces in the Bijou's audiences
                if (dayIdx % 10 == 6) {
                    val nc = wave5A[(dayIdx / 10) % wave5A.size]
                    if (Errands.askFor(sA, nc) != null) metA += nc
                }
                if (MovieNights.isScreeningDay(sA.absDay) &&
                    !MovieNights.isDarkTonight(sA)) {
                    val f = MovieNights.featureForDay(sA, sA.absDay)
                    metA += (MovieNights.attendance(sA) + f.stars)
                        .filter { it in wave5A }
                }
                // the fair week, lived as it comes
                val wA = Fair.windowToday(sA)
                if (wA != null) {
                    val di = Fair.dayIndex(sA)
                    val meA = engA.player(sA)
                    meA.location = Fair.FAIRGROUND
                    meA.destination = Fair.FAIRGROUND
                    meA.waypoints.clear()
                    if (di in 0..Fair.PHOTO_LAST_DAY && !fairPhotoA) {
                        Photos.applyPhoto(sA, PhotoRecord(
                            id = "audit-fair-frame",
                            dayKey = sA.todayKey, dateLabel = "fair",
                            timeMin = 13 * 60, locId = Fair.FAIRGROUND,
                            inside = false, weatherId = sA.weatherId,
                            appearance = DEFAULT_APPEARANCE,
                            figures = listOf(
                                PhotoFigure("Auditor", "player", "happy"),
                                PhotoFigure("Stan", "cast", "happy",
                                    pose = "backToBack",
                                    reaction = "goofy", points = 40),
                                PhotoFigure("Kyle", "cast", "happy",
                                    pose = "backToBack",
                                    reaction = "goofy", points = 42)),
                            caption = "The whole crew at the fair, " +
                                "posed and crashed",
                            followersGained = 30,
                            seed = 909_007L + dayIdx, absDay = sA.absDay))
                        fairPhotoA = sA.photos.any {
                            it.id == "audit-fair-frame" }
                    }
                    if (di == Fair.FISH_DAY && !fairFishA) {
                        meA.location = Fair.POND
                        meA.destination = Fair.POND
                        meA.waypoints.clear()
                        val carp = FISH_TABLE.minByOrNull {
                            Rival.fishRank(it) }!!
                        Fair.onCatch(sA, carp, 41)
                        fairFishA =
                            Fair.playerFishEntry(sA, wA.year) != null
                    }
                    if (di == Fair.DUNK_DAY && !fairDunkA) {
                        Fair.recordDunk(sA, 3, 2700)
                        fairDunkA = Fair.playerDunk(sA, wA.year) != null
                    }
                }
                // the darkroom: develop the fair frame, then
                // flood the album and let the cap try to take
                // the source — the print must not notice
                if (fairPhotoA && printA == null &&
                    sA.photos.any { it.id == "audit-fair-frame" }) {
                    val res = Darkroom.develop(sA, "audit-fair-frame",
                        Darkroom.SIZE_PRINT)
                    if (res != null) printA = res.print
                }
                if (printA != null && !printSurvivedA) {
                    repeat(Photos.ALBUM_CAP + 5) { i ->
                        Photos.applyPhoto(sA, PhotoRecord(
                            id = "audit-flood$i", dayKey = sA.todayKey,
                            dateLabel = "flood", timeMin = 12 * 60,
                            locId = "MainStreet", inside = false,
                            weatherId = "sunny",
                            appearance = DEFAULT_APPEARANCE,
                            figures = listOf(
                                PhotoFigure("Auditor", "player", "happy")),
                            seed = 555_000L + i, absDay = sA.absDay))
                    }
                    printHungA = Darkroom.hang(sA, printA!!.id)
                    printSurvivedA = Darkroom.sourceGone(sA, printA!!) &&
                        Darkroom.prints(sA).any {
                            it.id == printA!!.id &&
                                it.record.id == "audit-fair-frame" }
                }
                // crew-vs-crew, when the rival brings it:
                // solo offers are declined flat (the decline
                // moves one scheduling field, nothing else),
                // crew offers are taken and settled through
                // their own funnels
                sA.timeMin = 16 * 60
                val hitA = Rival.talkStepFor(sA, rivalA)
                if (hitA != null) when (hitA.kind) {
                    "offer" -> Rival.decline(sA)
                    "lock" -> Rival.playLock(sA)
                    "crewresume" ->
                        RivalCrew.onShowdown(sA, true, rivalA)
                    "crewoffer" -> {
                        val played0 = RivalCrew.seasonPlayed(sA)
                        val acc = RivalCrew.accept(sA, hitA.offerKind,
                            hitA.crewFinal)
                        if (!acc.waited) when (hitA.offerKind) {
                            RivalCrew.K_CREW_RELAY -> {
                                val to = sA.lifeText["rivalCrewRaceTo"]
                                if (to != null) {
                                    sA.timeMin += 25
                                    RivalCrew.raceArrival(sA, to)
                                }
                            }
                            RivalCrew.K_CREW_PHOTO -> {
                                val turf = RivalCrew.turfOf(sA)
                                val fielded = (sA.lifeText[
                                    "rivalCrewFieldYou"] ?: "")
                                    .split(",")
                                    .filter { it.isNotEmpty() }
                                if (fielded.size >= 2) {
                                    val frame = PhotoRecord(
                                        id = "audit-crew-frame${sA.absDay}",
                                        dayKey = sA.todayKey,
                                        dateLabel = "crews",
                                        timeMin = 16 * 60, locId = turf,
                                        inside = false,
                                        weatherId = "clear",
                                        appearance = DEFAULT_APPEARANCE,
                                        figures = listOf(
                                            PhotoFigure("Auditor",
                                                "player", "happy")) +
                                            fielded.mapIndexed { i, n ->
                                                PhotoFigure(n, "cast",
                                                    "happy",
                                                    pose = if (i < 2)
                                                        "backToBack"
                                                    else "none",
                                                    reaction = if (i >= 2)
                                                        Photos.GOOFY
                                                    else "neutral") },
                                        composition = "lineup",
                                        absDay = sA.absDay)
                                    RivalCrew.onPhoto(sA, frame)
                                }
                            }
                            RivalCrew.K_CREW_SHOWDOWN ->
                                RivalCrew.onShowdown(sA, true, rivalA)
                        }
                        if (RivalCrew.seasonPlayed(sA) > played0)
                            crewSettlesA++
                    }
                }
                // a weekly crew outing, staged the v0.9.0b
                // way: the member walks the graph's own
                // minutes from where they stand to where
                // you stand, and the arrival is the count
                if (dayIdx % 7 == 3) {
                    val member = Crew.members(sA).firstOrNull()
                    if (member != null) {
                        val out0 = Crew.outings(sA, member)
                        val fromLoc = "CityWok"
                        val toLoc = "TegridyFarms"
                        val exp = Walk.routeMinutes(sA, fromLoc, toLoc)
                        val aA = sA.agents[member]!!
                        aA.location = fromLoc
                        aA.destination = fromLoc
                        aA.waypoints.clear()
                        val meA = engA.player(sA)
                        meA.location = toLoc
                        meA.destination = toLoc
                        meA.waypoints.clear()
                        sA.timeMin = 15 * 60 + 30
                        Crew.tick(sA)
                        sA.timeMin += exp + 15
                        Crew.tick(sA)
                        if (Crew.outings(sA, member) > out0)
                            outingDaysA++
                    }
                }
                sA.timeMin = 10 * 60
            }
        } catch (e: Exception) {
            soakErrorA = "${e.javaClass.simpleName}: ${e.message}"
        }
        check(soakErrorA == null,
            "audit soak: 400 days of the full Queue #9 stack " +
                "without an exception (got $soakErrorA)")
        check(sA.absDay >= 400,
            "audit soak: the calendar advanced the full 400 " +
                "days (got ${sA.absDay})")
        val fairRecA = Fair.recordFor(sA, 2027)
        println("audit soak Q9: newcomers met=${metA.size} $metA, " +
            "crew outing days=$outingDaysA, fair photo/fish/dunk=" +
            "$fairPhotoA/$fairFishA/$fairDunkA, fair wrapped=" +
            "${fairRecA?.wrapped} attended=${fairRecA?.attended}, " +
            "print survived=$printSurvivedA (hung $printHungA), " +
            "crew settles=$crewSettlesA (standings: " +
            "${RivalCrew.crewsScoreLine(sA)}), rival contests=" +
            "${Rival.contestsPlayed(sA)}, arc7 started=" +
            "${sA.arc7Started} retired=${sA.arc7Retired}")
        check(metA.size >= 5,
            "audit soak: the wave-5 newcomers lived in the " +
                "70-cast town — asked, attended, starred " +
                "(met ${metA.size}: $metA)")
        check(Crew.members(sA).size == 4 && outingDaysA >= 3,
            "audit soak: the crew stayed recruited all year " +
                "and rendezvoused on the Walk graph's own " +
                "minutes, week after week (outing days " +
                "$outingDaysA)")
        check(fairRecA != null && fairRecA.wrapped &&
            fairRecA.attended && !fairRecA.missed &&
            fairRecA.photoPlaces.isNotEmpty() && fairFishA && fairDunkA,
            "audit soak: a county fair week was lived inside " +
                "the year — attended, entered in all three " +
                "contests, judged and wrapped (record $fairRecA)")
        check(FairCalendar.isFireworksAbsDay(FairCalendar.absDayOfOrdinal(
                FairCalendar.windowFor(2027).closingOrd)),
            "audit soak: the fair's closing night is a " +
                "fireworks night on the fair's own calendar")
        check(printA != null && printSurvivedA && printHungA &&
            Darkroom.wall(sA).any { it.id == printA!!.id },
            "audit soak: a print developed off the fair frame " +
                "survived the album cap whole — source gone, " +
                "print on the wall, record intact")
        check(crewSettlesA >= 1 &&
            RivalCrew.seasonPlayed(sA) >= 1 &&
            Rival.contestsPlayed(sA) >= crewSettlesA &&
            RivalCrew.pointsYou(sA) + RivalCrew.pointsThem(sA) >= 2,
            "audit soak: crew-vs-crew contests were taken " +
                "and settled inside the year — standings " +
                "moved, and every settle landed on the solo " +
                "ledger exactly once (settles $crewSettlesA, " +
                "standings ${RivalCrew.crewsScoreLine(sA)})")
        check(RivalCrew.theirCrew(sA).size == 3,
            "audit soak: the rival's crew still stands at " +
                "three at day 400 — derived once, never re-rolled")
        check(!arc7OverlapA,
            "audit soak: the seventh case never opened over " +
                "the sixth in 400 lived days")
        NpcMemoryStore.clear()
        NpcMemoryStore.deserialize(memSnapshot9)
    }

    run {
        // ---------- the seven-case lifetime, driven ----------
        // One unattended life, day by day (the v0.9.0f
        // drive, re-run as the audit's own witness): the
        // cases queue strictly one behind the next and ALL
        // retire — the backwards case included — with the
        // slot empty at the end.
        val engLife9 = Engine(9190)
        val life9 = engLife9.newState()
        var days9 = 0
        var overlap9 = false
        var arc7After6 = false
        while (days9 < 1600 && !(life9.arcRetired &&
            life9.arc2Retired && life9.arc3Retired &&
            life9.arc4Retired && life9.arc5Retired &&
            life9.arc6Retired && life9.arc7Retired)) {
            engLife9.onNewDay(life9)
            if (life9.arc7Started) {
                if (!life9.arc6Retired) overlap9 = true
                if (life9.arc6Retired) arc7After6 = true
            }
            days9++
        }
        println("seven-case lifetime: all seven retired after " +
            "$days9 days (arc7 branch ${life9.arc7Branch})")
        check(!overlap9,
            "seven-case: the backwards case never opened " +
                "over the court of public opinion — not one day")
        check(life9.arc7Retired &&
            life9.arc7Branch in Mystery7.BRANCH_KEYS,
            "seven-case: all seven cases retired in one " +
                "lifetime, the seventh included (branch " +
                "'${life9.arc7Branch}' after $days9 days)")
        check(arc7After6 && Mystery7.dueChapter7(life9) == null,
            "seven-case: the seventh opened only behind the " +
                "sixth, and nothing demands the slot after it")
    }

