            playerPhoto = 1, playerFish = 1, playerDunk = 2)
        vet.fairs += FairRecord(
            year = 2027, shifted = true, sitter = "Tweek",
            wrapped = true, attended = true,
            photoPlaces = fairPlaces("frame"),
            fishPlaces = fairPlaces("catch"),
