        for (c in Mystery7.CLUES7) vet.mystery7Clues.add(c.id)
        for (m in Mystery7.MOVEMENTS7) vet.arc7Commits[m.id] = "checked"
        vet.arc7Started = true; vet.arc7Chapter = 4
        vet.arc7Retired = true; vet.arc7Branch = "origin"
        vet.arc7Choice = "origin"; vet.arc7RetiredDay = 699
        vet.arc7CaseBuilt = true
        val vetJson = Json.stringify(encodeGameState(vet))
        println("veteran VIII game_state: ${vetJson.length} chars serialized")
        check(vetJson.length < 640 * 1024,
