            vetBack.arc3Retired && vetBack.arc4Retired &&
            vetBack.arc5Retired && vetBack.arc6Retired,
            "veteran VIII: the veteran body still round-trips " +
                "whole — six older cases closed beneath the seventh")
        check(Crew.members(vetBack) ==
            listOf("Stan", "Kyle", "Wendy", "Craig") &&
            Crew.outings(vetBack, "Stan") == 25 &&
            Crew.photosTogether(vetBack, "Stan") == 18 &&
            Crew.contestsWitnessed(vetBack) == 36,
            "veteran VIII: the crew round-trips whole — four " +
                "members, their outings, photos and witnessed " +
                "contests intact")
        check(Fair.recordFor(vetBack, 2026)?.wrapped == true &&
            Fair.recordFor(vetBack, 2027)?.attended == true &&
            Fair.blueRibbons(vetBack) == 4,
            "veteran VIII: two wrapped fairs round-trip with " +
                "their places and four blue ribbons between them")
        check(vetBack.prints.size == Darkroom.TOTAL_CAP &&
            Darkroom.wall(vetBack).size == Darkroom.WALL_CAP &&
            Darkroom.held(vetBack).size == Darkroom.BOX_CAP &&
            Darkroom.heldBy(vetBack, "Stan").size == 12 &&
            vetBack.prints.any { Darkroom.sourceGone(vetBack, it) },
            "veteran VIII: the print box round-trips at its " +
                "total cap — wall full, a dozen gifted, and one " +
                "print still the last whole copy of its source")
        check(theirVet.size == 3 &&
            RivalCrew.theirCrew(vetBack) == theirVet &&
            RivalCrew.pointsYou(vetBack) == 14 &&
            RivalCrew.pointsThem(vetBack) == 11 &&
            RivalCrew.seasonPlayed(vetBack) == 9 &&
            RivalCrew.historyLines(vetBack).size == 2,
            "veteran VIII: the rival's crew round-trips — the " +
                "same three, a played season's standings, two " +
                "finished seasons in the history")
        check(vetBack.arc7Retired && vetBack.arc7Branch == "origin" &&
            vetBack.arc7CaseBuilt &&
            vetBack.mystery7Clues.size == Mystery7.CLUES7.size &&
            vetBack.arc7Commits.size == Mystery7.MOVEMENTS7.size &&
            Mystery7.dueChapter7(vetBack) == null,
            "veteran VIII: the seventh case's typed state " +
                "round-trips closed — full file, full timeline, " +
                "the case rebuilt")
    }

    run {
        // ---------- fit QA: Queue #9's newest screens ----------
        // The Chrome discipline on the pages the queue
        // added, composed the way their screens compose
        // them: the YOUR CREW page off a full crew with a
        // season behind it, the COUNTY FAIR page off a
        // wrapped, attended fair, the darkroom's print
        // wall off a full wall of fat prints, the rival
        // page's CREWS standings off a played season, and
        // the seventh case's timeline board off a closed
        // case (every verdict the board can show).
        val engF = Engine(909_505)
        val fitCrew = engF.newState()
        engF.createPlayer(fitCrew, "Fitcheck", DEFAULT_APPEARANCE)
        for (n in listOf("Stan", "Kyle", "Wendy", "Craig")) {
            fitCrew.friendship[n] = 80
            Crew.invite(fitCrew, n)
            fitCrew.life["crew:out:$n"] = 12
            fitCrew.life["crew:pic:$n"] = 7
            fitCrew.life["crew:wit:$n"] = 4
            fitCrew.lifeText["crew:places:$n"] =
                "KidsPark,StarksPond,Bijou,CityHall,MainStreet"
        }
        fitCrew.life["crew:witTotal"] = 16
        val fitFair = engF.newState()
        engF.createPlayer(fitFair, "Fitcheck", DEFAULT_APPEARANCE)
        fitFair.fairs += FairRecord(
            year = 2027, shifted = true, sitter = "Tweek",
            wrapped = true, attended = true,
            photoPlaces = listOf(
                FairPlace("You", "your fairground frame, the whole crew posed", 165),
                FairPlace("Wendy", "a frame with the ferris wheel behind", 140),
                FairPlace("Jimmy", "a frame caught mid-laugh", 120)),
            fishPlaces = listOf(
                FairPlace("Jimbo", "the rarest fish on the table, at length", 150),
                FairPlace("You", "your catch, honestly measured", 130),
                FairPlace("Craig", "a catch reeled in without expression", 110)),
            dunkPlaces = listOf(
                FairPlace("You", "three throws, three splashes", 90),
                FairPlace("Kyle", "two throws, two splashes", 60),
                FairPlace("Bebe", "one throw, one splash", 30)),
            photoJudge = "Wendy",
            photoNote = "The frame holds the whole fairground, " +
                "the bunting, the booths and absolutely everybody " +
                "in it pretending not to pose.",
            playerPhoto = 1, playerFish = 2, playerDunk = 1)
        fitFair.fairs += FairRecord(
            year = 2026, shifted = false, sitter = "Butters",
            wrapped = true, attended = false, missed = true)
        val fitWall = engF.newState()
        engF.createPlayer(fitWall, "Fitcheck", DEFAULT_APPEARANCE)
        repeat(Darkroom.WALL_CAP) { i ->
            fitWall.prints += DarkroomPrint(
                id = "fitpr$i", photoId = "fitph$i",
                record = PhotoRecord(
                    id = "fitph$i", dayKey = "20270815",
                    dateLabel = "8/15", timeMin = 800,
                    locId = "KidsPark", inside = false,
                    weatherId = "sunny",
                    appearance = DEFAULT_APPEARANCE,
                    figures = listOf(
                        PhotoFigure("Fitcheck", "player", "happy"),
                        PhotoFigure("Stan", "cast", "happy"),
                        PhotoFigure("Kyle", "cast", "goofy")),
                    caption = "A fairground caption long enough " +
                        "to wrap the whole print wall, part ${i + 1}",
                    followersGained = 30, seed = 700L + i,
                    absDay = 320, starred = i == 0),
                size = if (i == 0) Darkroom.SIZE_ENLARGEMENT
                    else Darkroom.SIZE_PRINT,
                madeAbsDay = 321, madeKey = "20270816",
                onWall = true)
        }
        val fitRival = engF.newState()
        engF.createPlayer(fitRival, "Fitcheck", DEFAULT_APPEARANCE)
        fitRival.absDay = 40
        Rival.playReveal(fitRival, 1)
        RivalCrew.theirCrew(fitRival)
        RivalCrew.settleCrewContest(fitRival,
            RivalCrew.K_CREW_RELAY, "you", "a relay at the turf", false)
        RivalCrew.settleCrewContest(fitRival,
            RivalCrew.K_CREW_PHOTO, "draw", "a frame at the turf", false)
        val boardDone = engF.newState()
        engF.createPlayer(boardDone, "Board", DEFAULT_APPEARANCE)
        boardDone.arcRetired = true; boardDone.arc2Retired = true
        boardDone.arc3Retired = true; boardDone.arc4Retired = true
        boardDone.arc5Retired = true; boardDone.arc6Retired = true
        boardDone.arc7Started = true; boardDone.arc7Chapter = 4
        boardDone.arc7Retired = true; boardDone.arc7Branch = "origin"
        for (c in Mystery7.CLUES7) boardDone.mystery7Clues.add(c.id)
        for (m in Mystery7.MOVEMENTS7)
            boardDone.arc7Commits[m.id] = "checked"
        boardDone.arc7Commits["m1"] = "easy"
        val boardLines = Mystery7.boardLines7(boardDone)
        check(Crew.pageLines(fitCrew).first() == "👥 YOUR CREW" &&
            Crew.pageLines(fitCrew).any { it.contains("Stan") },
            "fitQA: the YOUR CREW page heads a full crew")
        check(Fair.pageLines(fitFair).any { it.contains("2027") } &&
            Fair.pageLines(fitFair).any { it.contains("missed") },
            "fitQA: the COUNTY FAIR page shows the wrapped " +
                "fair whole and last year's miss as its line")
        check(Darkroom.wall(fitWall).size == Darkroom.WALL_CAP &&
            Darkroom.wallText(fitWall).isNotBlank(),
            "fitQA: the print wall stands full at three")
        check(Rival.pageLines(fitRival).any {
                it.contains("THE CREWS") } &&
            RivalCrew.crewsScoreLine(fitRival).isNotBlank(),
            "fitQA: THE RIVAL page carries the CREWS standings " +
                "off a played season")
        val boardJoined = boardLines.joinToString("\n")
        check(boardJoined.indexOf("1. THE FIRE WINTER") >= 0 &&
            boardJoined.indexOf("1. THE FIRE WINTER") <
                boardJoined.indexOf("4. THE TAKING") &&
            boardJoined.contains("CONFIRMED") &&
            boardJoined.contains("BROKEN"),
            "fitQA: the timeline board lays the story out in " +
                "true order with confirmed and broken lines " +
                "standing side by side")
        val q9Lines = mutableListOf<String>()
        q9Lines += Crew.pageLines(fitCrew)
        q9Lines += Fair.pageLines(fitFair)
        q9Lines += Darkroom.wallText(fitWall).lines()
        q9Lines += Rival.pageLines(fitRival)
        q9Lines += boardLines
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { s: String -> s.length * 10f * fs }
            for (line in q9Lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a Queue #9 screen line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a Queue #9 screen line never collapses at fs $fs")
            }
        }
    }

    run {
        // ---------- the rail order, final form: eleven rails ----------
        // Queue #9 added NO rail — the crew ask is an
        // in-talk choice, the crew contests ride the RIVAL
        // rail, the fair and the darkroom speak through
        // fixtures and menus. The ladder stands exactly as
        // v0.8.0g pinned it. Pin the full order in source
        // first — enum and try-order, the v0.7.0g technique.
        val tgSrc = File(root, "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        val enumBody = tgSrc.substring(
            tgSrc.indexOf("enum class Rail"),
            tgSrc.indexOf("data class Gate"))
        val enumOrder = listOf("DELIVER", "HOLIDAY_BEAT", "FINALE",
            "CLIMAX", "DINNER", "WORK", "FACTION_MISSION",
            "EMERG_OFFER", "RIVAL", "ERRAND_ASK", "DIALOGUE")
        val enumIdx = enumOrder.map { enumBody.indexOf(it) }
        check(enumIdx.all { it >= 0 } &&
            enumIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: the Rail enum declares the eleven " +
                "rails in ladder order")
        val gateBody = tgSrc.substring(tgSrc.indexOf("fun gateFor"))
        val railOrder = enumOrder.map { "Rail.$it" }
        val railIdx = railOrder.map { gateBody.indexOf(it) }
        check(railIdx.all { it >= 0 } &&
            railIdx.zipWithNext().all { (a, b) -> a < b },
            "contention: gateFor tries the eleven rails in " +
                "ladder order — DELIVER, HOLIDAY_BEAT, FINALE, " +
                "CLIMAX, DINNER, WORK, FACTION_MISSION, " +
                "EMERG_OFFER, RIVAL, ERRAND_ASK, DIALOGUE")
        check(TalkGate.Rail.values().size == 11,
            "contention: eleven rails exactly — Queue #9 " +
                "added none (the crew ask is a menu choice, " +
                "pinned in v0.9.0b's own section)")
        // No single NPC in town can hold all eleven: the
        // queue's two newest rails live on disjoint people.
        // Prove it from the live data, then peel the
        // fullest stack the town CAN build — Clyde, the
        // one rival-pool kid who is also an emergency
        // asker, holding DELIVER + EMERG_OFFER + RIVAL +
        // ERRAND_ASK over a plain dialogue. (Randy's
        // nine-rail stack from v0.7.0g stands in its own
        // section, unchanged.)
        val poolNames = Rival.POOL.map { it.name }.toSet()
        val emergAskers = Emergencies.SCENARIOS
            .map { it.asker }.toSet()
        val dinnerMembers = Dinners.HOUSEHOLDS
            .flatMap { it.members }.toSet()
        check(poolNames.intersect(emergAskers) == setOf("Clyde") &&
            poolNames.intersect(emergAskers)
                .intersect(dinnerMembers).isEmpty() &&
            "Randy" !in poolNames,
            "contention: no NPC holds every rail — the " +
                "rival pool and the emergency askers meet in " +
                "exactly one name (Clyde), who sits at no " +
                "family's table, and the nine-rail holder " +
                "stands outside the pool entirely")
        val engC = Engine(909_707)
        fun clydeState(): GameState? {
            val startOrd = ordinalOfKey("20270101")
            for (nameIdx in 0..60) {
                val probe = engC.newState()
                engC.createPlayer(probe, "Kid$nameIdx",
                    DEFAULT_APPEARANCE)
                if (Rival.pickFor(probe) != "Clyde") continue
                var (y, m, d) = Triple(2027, 1, 1)
                val lens = intArrayOf(31, 28, 31, 30, 31, 30,
                    31, 31, 30, 31, 30, 31)
                repeat(500) {
                    val s = engC.newState()
                    engC.createPlayer(s, "Kid$nameIdx",
                        DEFAULT_APPEARANCE)
                    s.gameYear = y; s.gameMonth = m; s.gameDay = d
                    s.todayKey = "%04d%02d%02d".format(y, m, d)
                    s.absDay = 500 + (ordinalOfKey(s.todayKey) -
                        startOrd)
                    s.timeMin = 10 * 60
                    s.life["fmMask:craigs_gang"] = 0b111
                    s.life["fmActive:craigs_gang"] = 0
                    val sc = Emergencies.todaysScenario(s)
                    val loc8 = s.agents["Clyde"]!!.location
                    if (sc != null && sc.asker == "Clyde" &&
                        Errands.askFor(s, "Clyde") != null &&
                        !Emergencies.momentOwned(s) &&
                        FactionMissions.offerFor(s, "Clyde") == null &&
                        FactionMissions.talkBeatFor(s, "Clyde") == null &&
                        Capstones.offerFor(s, "Clyde") == null &&
                        Capstones.talkBeatFor(s, "Clyde") == null)
                        return s
                    d++
                    if (d > lens[m - 1]) {
                        d = 1; m++; if (m > 12) { m = 1; y++ }
                    }
                }
            }
            return null
        }
        val sClyde = clydeState()
        check(sClyde != null,
            "contention: a morning exists where Clyde is the " +
                "crowned rival, the day's emergency is his, and " +
                "he holds an ask of his own")
        if (sClyde != null) {
            val loc8 = sClyde.agents["Clyde"]!!.location
            engC.player(sClyde).location = loc8
            sClyde.errands.add(Errand(
                id = "stack9-deliver", source = Errands.BOARD,
                asker = "Stan", type = "DELIVER",
                text = "A package with Clyde's name on it.",
                hint = "He's around.",
                targetName = "Clyde", itemId = "fishing_lure",
                dayKey = sClyde.todayKey,
                acceptedDay = sClyde.absDay))
            sClyde.inventory["fishing_lure"] =
                (sClyde.inventory["fishing_lure"] ?: 0) + 1
            var g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.DELIVER,
                "contention: Clyde's stack peels at DELIVER — " +
                    "a held delivery outranks the siren")
            Errands.deliverTo(sClyde, "Clyde")
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.EMERG_OFFER &&
                g.emergOffer != null,
                "contention: under the delivery stands " +
                    "EMERG_OFFER — Clyde's own emergency, priced " +
                    "and waiting")
            Emergencies.markOffered(sClyde, "Clyde")
            Emergencies.decline(sClyde)
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.RIVAL &&
                g.rivalHit?.kind == "reveal",
                "contention: the emergency declined (never " +
                    "accepted — a live one would deafen this " +
                    "rail), the RIVAL reveal stands next")
            Rival.playReveal(sClyde, 1)
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.ERRAND_ASK &&
                g.ask != null,
                "contention: under the rivalry, Clyde's own " +
                    "ask — the rail that was always there")
            Errands.markAsked(sClyde, "Clyde")
            g = TalkGate.gateFor(sClyde, "Clyde", loc8)
            check(g.rail == TalkGate.Rail.DIALOGUE,
                "contention: and under everything, a person " +
                    "with something to say — the peel is complete")
        }
    }

    run {
        // ---------- seams: the queue against the town ----------
        // The agenda stack's Q9 seats, pinned in source:
        // the fair's claim, the rival crew's turf claim,
        // then the crew's own hook LAST — set pieces pull
        // crew members away, never the reverse.
        val engSrc = File(root, "src/com/hunt3r/southparktown/Engine.kt")
            .readText()
        val stackOrder = listOf("Finales.gatheringBlock",
            "Fair.gatheringBlock", "RivalCrew.gatheringBlock",
            "Crew.gatheringBlock")
        val stackIdx = stackOrder.map { engSrc.indexOf(it) }
        check(stackIdx.all { it >= 0 } &&
            stackIdx.zipWithNext().all { (a, b) -> a < b },
            "seam: the agenda stack seats the fair after " +
                "the finales, the rival's crew after the fair, " +
                "and your crew's hook last of all")
        // A due homecoming owns the moment, and the rival
        // crew's turf hangout dissolves under it — the
        // v0.9.0e fabrication, restaged for the seventh
        // case's climax.
        val engS = Engine(909_313)
        val sTurf = engS.newState()
        engS.createPlayer(sTurf, "Seam", DEFAULT_APPEARANCE)
        sTurf.absDay = 40
        Rival.playReveal(sTurf, 1)
        val theirS = RivalCrew.theirCrew(sTurf)
        var turfDay = -1
        for (d in 40..52) {
            sTurf.absDay = d
            if (RivalCrew.turfDayToday(sTurf)) { turfDay = d; break }
        }
        check(turfDay >= 0 && theirS.isNotEmpty(),
            "seam: (fabrication) a turf day stands in the " +
                "rival crew's rhythm")
        if (turfDay >= 0) {
            sTurf.absDay = turfDay
            sTurf.timeMin = 16 * 60
            check(RivalCrew.gatheringBlock(sTurf, theirS.first(),
                    16 * 60) != null,
                "seam: on a turf afternoon the hangout claims " +
                    "its people")
            sTurf.arcRetired = true; sTurf.arc2Retired = true
            sTurf.arc3Retired = true; sTurf.arc4Retired = true
            sTurf.arc5Retired = true; sTurf.arc6Retired = true
            sTurf.arc7Started = true; sTurf.arc7Chapter = 4
            sTurf.shenaniganId = Mystery7.FINALE7_ID
            sTurf.shenaniganDay = sTurf.todayKey
            for (c in Mystery7.CLUES7) sTurf.mystery7Clues.add(c.id)
            for (m in Mystery7.MOVEMENTS7)
                sTurf.arc7Commits[m.id] = "checked"
            sTurf.timeMin = 13 * 60
            check(Mystery7.restageDue(sTurf) &&
                Emergencies.momentOwned(sTurf) &&
                RivalCrew.gatheringBlock(sTurf, theirS.first(),
                    16 * 60) == null,
                "seam: a due homecoming owns the moment — " +
                    "the turf hangout dissolves under the " +
                    "seventh case's climax, like every set " +
                    "piece before it")
        }
        // The album cap × the darkroom, in miniature (the
        // audit soak lived it at scale): a starred source
        // is protected from the shed, an unstarred print's
        // source is not — and the print reads whole either
        // way, because the print is a copy, not a pointer.
        val sCap = engS.newState()
        engS.createPlayer(sCap, "Album", DEFAULT_APPEARANCE)
        sCap.inventory[Minigames.COIN_ITEM] = 50
        fun capRec(id: String, day: Int) = PhotoRecord(
            id = id, dayKey = "20270115", dateLabel = "1/15",
            timeMin = 600, locId = "MainStreet", inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = listOf(
                PhotoFigure("Album", "player", "happy")),
            seed = day.toLong(), absDay = day)
        Photos.applyPhoto(sCap, capRec("seam-keep", 100))
        val seamPrint = Darkroom.develop(sCap, "seam-keep",
            Darkroom.SIZE_PRINT)?.print
        check(seamPrint != null,
            "seam: the miniature develops its print")
        repeat(Photos.ALBUM_CAP + 5) { i ->
            Photos.applyPhoto(sCap, capRec("seam-flood$i", 200 + i))
        }
        check(seamPrint != null &&
            Darkroom.sourceGone(sCap, seamPrint) &&
            seamPrint.record.id == "seam-keep" &&
            Darkroom.prints(sCap).any { it.id == seamPrint.id },
            "seam: the flood sheds the source and the print " +
                "stands whole — the wall's promise, in miniature")
    }

    run {
        // ---------- the peak budget, eighth distance ----------
        // The same pins as v0.4.0e, on today's render set,
        // and the census counted honestly at 70 cast:
        // Queue #9 shipped five systems and not one new
        // audio family — but the bark table grew with the
        // cast again in wave 5, eight new rhythm signatures
        // for eight new townsfolk, all of them distinct.
        val pb = SoundGen.PeakBudget
        println("budget v0.9.0g: named ${pb.namedStack()}, " +
            "double ${pb.doubleSfxStack()}, bark ${pb.barkStack()}, " +
            "barkOut ${pb.barkPeakOut()}, moodOut ${pb.moodBlipPeakOut()}, " +
            "amb ${pb.ambiencePeakOut()}, bark signatures " +
            "${Barks.PATTERNS.size} (" +
            "${Barks.PATTERNS.values.distinct().size} distinct)")
        check(kotlin.math.abs(pb.namedStack() - 0.947f) < 0.0025f,
            "budget: the named stack has not drifted since v0.4.0e " +
                "(got ${pb.namedStack()})")
        check(kotlin.math.abs(pb.doubleSfxStack() - 0.978f) < 0.0025f,
            "budget: the double-SFX stack has not drifted (got ${pb.doubleSfxStack()})")
        check(kotlin.math.abs(pb.barkStack() - 0.947f) < 0.0025f,
            "budget: the bark stack has not drifted (got ${pb.barkStack()})")
        check(pb.barkPeakOut() <= pb.blipPeakOut() + 0.002f &&
            pb.moodBlipPeakOut() <= pb.blipPeakOut() + 0.002f,
            "budget: neither barks nor mood contours out-peak the plain blip")
        for (bed in SoundGen.AmbBed.values()) {
            if (bed == SoundGen.AmbBed.NONE) continue
            val post = AudioSettings.DEFAULT.gain(
                AudioChannel.AMBIENCE) * pb.AMB_CHAIN *
                pb.peakOf(SoundGen.renderAmbience(bed))
            check(post <= pb.ambiencePeakOut() + 0.002f,
                "budget: bed $bed stays inside the ambience allocation")
        }
        check(SoundGen.SFX_IDS.size == 21 &&
            SoundGen.BlipFam.values().size == 7 &&
            SoundGen.BlipMood.values().size == 4 &&
            SoundGen.AmbBed.values().size == 6,
            "budget: the family census is unchanged — 21 named " +
                "effects, 7 blip families, 4 moods, 6 ambience " +
                "beds. Queue #9 added no audio family (got " +
                "${SoundGen.SFX_IDS.size}/${SoundGen.BlipFam.values().size}/" +
                "${SoundGen.BlipMood.values().size}/${SoundGen.AmbBed.values().size})")
        check(Barks.PATTERNS.size == CharacterSystem.CAST.size &&
            Barks.PATTERNS.size == 98 &&
            Barks.PATTERNS.keys == CharacterSystem.CAST.keys &&
            Barks.PATTERNS.values.distinct().size ==
            Barks.PATTERNS.size,
            "budget: the bark census at 98 — one rhythm " +
                "signature per cast member, all 98 distinct, " +
                "the eight wave-5 and twenty-eight wave-6 " +
                "newcomers included (got " +
                "${Barks.PATTERNS.size}, " +
                "${Barks.PATTERNS.values.distinct().size} distinct)")
    }

    run {
        // ---------- the tuning ledger, swept for Queue #9 ----------
        // Every paper-tuned Queue #9 constant, named in
        // the ledger section itself — scoped to the
        // section, so a dial that only ever made a
        // changelog doesn't count. The sweep found two
        // gaps this pass, closed in the README as
        // documentation: the rival's crew (v0.9.0e) had NO
        // ledger entry at all — its cadence, standings
        // and turf dials now stand beside the solo rival's
        // — and the cases entry ended at the sixth case;
        // it now closes with the seventh's delays,
        // CASE_RETURN_DELAY_DAYS among them.
        val tuning = File(root, "docs/TUNING.md").readText()
        val ledgerStart = tuning.indexOf("## Tuning ledger")
        val ledgerEnd = tuning.length
        check(ledgerStart >= 0 && ledgerEnd > ledgerStart,
            "ledger: the ledger section stands ahead of the changelog")
        val ledger = tuning.substring(ledgerStart, ledgerEnd)
        val q9Dials = listOf(
            // your crew (v0.9.0b)
            "MAX_CREW", "INVITE_MIN_POINTS", "CREW_AFFINITY",
            // the county fair (v0.9.0c)
            "FAIR_FROM", "FAIR_TO", "WATCH_TO", "ANNOUNCE_AHEAD",
            "PHOTO_LAST_DAY", "FISH_DAY", "DUNK_DAY", "DUNK_THROWS",
            "PLACE_COINS", "PHOTO_FIELD", "FISH_FIELD", "DUNK_FIELD",
            // the darkroom (v0.9.0d)
            "PRINT_COST", "PRINT_MINUTES", "ENLARGE_COST",
            "ENLARGE_MINUTES", "BOX_CAP", "WALL_CAP", "TOTAL_CAP",
            "GIFT_BASE_POSER", "GIFT_BASE_BOMBER", "GIFT_CHEM_CAP",
            "GIFT_FOLLOWER_STEP", "GIFT_FOLLOWER_CAP",
            "GIFT_STAR_BONUS", "GIFT_CAP",
            // the rival's crew (v0.9.0e)
            "CREW_GAP_MIN", "CREW_GAP_SPREAD", "FIRST_CREW_GAP",
            "DECLINE_CREW_GAP", "WAIT_GAP", "NO_CREW_GAP",
            "POINTS_WIN", "POINTS_DRAW", "FINAL_MULT",
            "FINAL_MIN_PLAYED", "FINAL_WINDOW_DAYS", "HISTORY_CAP",
            "TURF_FROM", "TURF_TO",
            // mystery #7 (v0.9.0f)
            "OPEN_DELAY_DAYS", "CHAPTER_GAP_DAYS",
            "CASE_RETURN_DELAY_DAYS",
            // wave 5's scaling dial (v0.9.0a)
            "MAX_TEXTS")
        for (dial in q9Dials)
            check(dial in ledger,
                "ledger: the Queue #9 dial $dial is named in " +
                    "the tuning ledger")
        check(Crew.MAX_CREW == 4 && Crew.INVITE_MIN_POINTS == 30 &&
            Fair.FAIR_FROM == 10 * 60 && Fair.FAIR_TO == 20 * 60 &&
            Fair.WATCH_TO == 21 * 60 + 30 &&
            Fair.PLACE_COINS == listOf(6, 4, 2) &&
            Darkroom.PRINT_COST == 2 && Darkroom.PRINT_MINUTES == 30 &&
            Darkroom.ENLARGE_COST == 5 &&
            Darkroom.ENLARGE_MINUTES == 60 &&
            Darkroom.BOX_CAP == 12 && Darkroom.WALL_CAP == 3 &&
            Darkroom.TOTAL_CAP == 24 && Darkroom.GIFT_CAP == 8 &&
            RivalCrew.CREW_GAP_MIN == 12 &&
            RivalCrew.CREW_GAP_SPREAD == 6 &&
            RivalCrew.FIRST_CREW_GAP == 3 &&
            RivalCrew.POINTS_WIN == 2 && RivalCrew.POINTS_DRAW == 1 &&
            RivalCrew.FINAL_MULT == 2 &&
            RivalCrew.FINAL_MIN_PLAYED == 2 &&
            RivalCrew.FINAL_WINDOW_DAYS == 21 &&
            RivalCrew.HISTORY_CAP == 4 &&
            RivalCrew.TURF_FROM == 15 * 60 + 30 &&
            RivalCrew.TURF_TO == 19 * 60 + 30 &&
            Mystery7.OPEN_DELAY_DAYS == 10 &&
            Mystery7.CHAPTER_GAP_DAYS == 7 &&
            Mystery7.CASE_RETURN_DELAY_DAYS == 7 &&
            Phone.MAX_TEXTS == 220,
            "ledger: the Queue #9 dials stand at the values " +
                "the ledger prints")
    }

    // ---------- the release pin ----------
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
}

// ================= v0.10.0a: your family arrives =================
// Queue #10 item 1 — the New Kid stops living alone. Mom and
// Dad arrive as HOUSEHOLD NPCs in the generated-NPC pattern:
// not cast (the census pins below hold from both sides), with
// derived looks, real jobs, a played arrival with a stance,
// family dinners on the complement rhythm, the weekly
// allowance (the build's only new coin source), chores in
// the errand pattern, family phone threads inside the
// unchanged MAX_TEXTS, and family photos through the
// darkroom's own discipline.
private fun sectionV0100a(root: String) {
    println("== v0.10.0a: your family arrives ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val tuning = File(root, "docs/TUNING.md").readText()
    check(readme.contains("### v0.10.0a"),
        "v0.10.0a: the README carries this build's changelog entry")
    val famSrc = File(root,
        "src/com/hunt3r/southparktown/Family.kt").readText()

    // ---------- census: the family is NOT cast ----------
    run {
        check(AGENT_PROFILES.size == 98 && KID_ORDER.size == 98 &&
            Family.MOM !in AGENT_PROFILES && Family.DAD !in AGENT_PROFILES &&
            Family.MOM !in KID_ORDER &&
            Family.DAD !in CharacterSystem.CAST_KIDS &&
            Family.MOM !in CharacterSystem.CAST_ADULTS,
            "family: the 98-cast census stands — Mom and Dad are in " +
                "no cast table, no kid order, no adult list")
        check(FACTIONS.none { f -> Family.PARENTS.any { it in f.members } },
            "family: no faction lists a parent (citizenship limit)")
        check(Crew.members(GameState()).isEmpty() &&
            !Crew.isMember(GameState(), Family.MOM),
            "family: a parent is never crew (citizenship limit)")
    }

    // ---------- arrival gating, incl. legacy saves ----------
    run {
        val eng = Engine(910_001)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        check(s.absDay == 0 && Family.arrivalDay(s) == Family.ARRIVAL_ABS_DAY &&
            !Family.arrivalDue(s) && !Family.arrived(s),
            "family: a new save's family arrives on day " +
                "${Family.ARRIVAL_ABS_DAY}, not before")
        s.absDay = 2
        check(!Family.arrivalDue(s),
            "family: day 2 is still the empty house")
        s.absDay = 3
        check(Family.arrivalDue(s),
            "family: the arrival is due on the morning of day 3")
        check(!Family.chooseStance(s, "bogus") && !Family.arrived(s),
            "family: an unknown stance does not play the arrival")
        check(Family.chooseStance(s, "fine") && Family.arrived(s) &&
            Family.stance(s) == "fine" && !Family.arrivalDue(s),
            "family: the stance plays the arrival and is remembered")
        check(!Family.chooseStance(s, "warm"),
            "family: the arrival plays exactly once")
        // a legacy save (absDay long past day 3, no family keys)
        val old = eng.newState()
        eng.createPlayer(old, "Veteran", DEFAULT_APPEARANCE)
        old.absDay = 50
        check(Family.arrivalDay(old) == 50 && Family.arrivalDue(old),
            "family: a pre-0.10.0a save gets its family on the next " +
                "eligible morning (its arrival day is today, day 50)")
        old.absDay = 51
        check(Family.arrivalDay(old) == 50,
            "family: the stamped arrival day never slides")
    }

    // ---------- looks: derived vs authored ----------
    run {
        val eng = Engine(910_002)
        val app = DEFAULT_APPEARANCE + mapOf(
            "skin" to "deep", "hair_style" to "mop",
            "hair_color" to "black")
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", app)
        val skinHex = creatorOpt("skin", "deep").color
        val hairHex = creatorOpt("hair_color",
            validateAppearance(app)["hair_color"]!!).color
        val mom = Family.specFor(s, Family.MOM)
        val dad = Family.specFor(s, Family.DAD)
        check(mom.skin == skinHex && dad.skin == skinHex,
            "family: both parents wear the player's exact skin hex " +
                "($skinHex) — the honest genetic echo")
        check(mom.hairColor == hairHex &&
            dad.hairColor == darkerHex(hairHex!!) &&
            dad.beardColor == hairHex,
            "family: Mom's hair is your hair color; Dad's is the same " +
                "hex darkened, and his beard wears yours exactly")
        check(mom.tall && dad.tall && mom.hairStyle == "bob" &&
            dad.hairStyle == "sidepart" && dad.beard,
            "family: adult proportions (tall band, unmeasured like " +
                "generated NPCs); hairstyles and clothes are authored")
        val bald = eng.newState()
        eng.createPlayer(bald, "NewKid", DEFAULT_APPEARANCE)
        check(Family.specFor(bald, Family.DAD).hairStyle == "bald",
            "family: a bald New Kid's dad is bald too")
        check(Family.specFor(Family.MOM, app) == mom &&
            Family.specFor(Family.DAD, app) == dad,
            "family: the photo path derives from a record's own " +
                "appearance map and agrees with the live derivation")
    }

    // ---------- presence & agendas ----------
    run {
        val eng = Engine(910_003)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 3
        check(Family.presentAt(s, YOUR_HOUSE, true).isEmpty(),
            "family: nobody is home before the arrival plays")
        Family.chooseStance(s, "warm")
        // a weekday morning: both home; a weekday midday: at work
        var wd = 4
        s.absDay = wd
        while (isWeekend(s)) { wd++; s.absDay = wd }
        s.timeMin = 8 * 60
        val homeMorning = Family.presentAt(s, YOUR_HOUSE, true)
        check(homeMorning.map { it.persona.loreName }.toSet() ==
            setOf(Family.MOM, Family.DAD),
            "family: both parents are home on a weekday morning")
        s.timeMin = 12 * 60
        check(Family.presentAt(s, Family.MOM_WORK, true)
                .any { it.persona.loreName == Family.MOM } &&
            Family.presentAt(s, Family.DAD_WORK, true)
                .any { it.persona.loreName == Family.DAD } &&
            Family.presentAt(s, YOUR_HOUSE, true).isEmpty(),
            "family: midday finds Mom at the Bank and Dad at the " +
                "Post Office — real jobs at real places")
        check(Family.presentAt(s, Family.MOM_WORK, false).isEmpty(),
            "family: at work they stand indoors, like residents do")
        s.timeMin = 23 * 60
        check(Family.blockAt(s, Family.MOM) == null &&
            Family.blockAt(s, Family.DAD) == null,
            "family: at night the parents are offstage, asleep")
        // a holiday: work yields, like cast agendas — the
        // morning is home (a midday may be a family outing,
        // but it is never the office)
        s.absDay = wd; s.timeMin = 12 * 60
        s.holidayId = HOLIDAYS.first().id
        check(Family.blockAt(s, Family.MOM)?.first != Family.MOM_WORK &&
            Family.blockAt(s, Family.DAD)?.first != Family.DAD_WORK,
            "family: on a holiday the work block yields")
        s.timeMin = 9 * 60
        check(Family.blockAt(s, Family.MOM)?.first == YOUR_HOUSE &&
            Family.blockAt(s, Family.DAD)?.first == YOUR_HOUSE,
            "family: a holiday morning is a home morning")
        s.holidayId = null
        // the persona shape
        val pm = Family.persona(s, Family.MOM)
        val pd = Family.persona(s, Family.DAD)
        check(pm.resident && pd.resident && pm.factionId == null &&
            pm.home == YOUR_HOUSE && pm.workLoc == Family.MOM_WORK &&
            pd.workLoc == Family.DAD_WORK &&
            pm.band == AgeBand.ADULT && pd.band == AgeBand.ADULT,
            "family: personas are resident household NPCs — home " +
                "here, work anchored, no faction, adult band")
        val sizes = Family.bankSizes(Family.MOM)
        check(sizes == Family.bankSizes(Family.DAD) &&
            sizes["greetings"] == 5 && sizes["evenings"] == 4 &&
            sizes["topics"] == 8 && sizes["general"] == 6 &&
            sizes["serve"] == 3 && sizes["moments"] == 3 &&
            sizes["choreAsks"] == 6 && sizes["byes"] == 3,
            "family: each parent carries a real authored bank " +
                "(41 lines: 5 greetings, 4 evenings, 8 topics, " +
                "6 general, 3 serve, 3 moments, 6 chore asks, " +
                "3 ambient, 3 byes) (sizes $sizes)")
        // the stance echo opens the first real talk
        check(Family.greeting(s, Family.MOM) ==
            Family.stanceEchoLine(Family.MOM, "warm"),
            "family: the first talk after the move carries the " +
                "stance echo")
        // replies are real lines, and talking never writes friendship
        var allReal = true
        for (seed in 0..40) {
            if (Family.reply(s, Family.MOM, seed).isBlank()) allReal = false
            if (Family.reply(s, Family.DAD, seed).isBlank()) allReal = false
        }
        check(allReal && Family.points(s, Family.MOM) > 0,
            "family: replies land across the rotation for both parents")
        check(!s.friendship.containsKey(Family.MOM) &&
            !s.friendship.containsKey(Family.DAD),
            "family: family warmth NEVER writes state.friendship")
    }

    // ---------- family dinners: rhythm, beats, deference ----------
    run {
        check(Family.DINNER_WEEKDAYS.intersect(Dinners.DINNER_WEEKDAYS)
                .isEmpty() && Family.DINNER_WEEKDAYS.size == 3,
            "family: the family table's rhythm {0,2,4} is the exact " +
                "complement of the cast households' {1,3,5} — the " +
                "two tables can never claim the same evening")
        check(famSrc.contains("Dinners.hostingTonight(state)") &&
            famSrc.contains("Dinners.beatsDeferred(state)") &&
            famSrc.contains("HolidayBeats.activeBeat(state)"),
            "family: dinner deference is structural — a hosted " +
                "night, a holiday beat, or a climax pending each " +
                "stand the family table down")
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        val di = engSrc.indexOf("Dinners.gatheringBlock")
        val fi = engSrc.indexOf("Family.gatheringBlock")
        val ji = engSrc.indexOf("Jobs.gatheringBlock")
        check(di >= 0 && fi > di && ji > fi,
            "family: in Engine's agenda stack the family guest's " +
                "claim sits with the dinners, before jobs — finales " +
                "and the fair further down still win the kid")
        val eng = Engine(910_004)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 3; Family.chooseStance(s, "warm")
        s.absDay = 10   // 10 % 7 = 3 — not a family night
        check(!Family.dinnerTonight(s),
            "family: no family dinner on an off-rhythm night")
        s.absDay = 11   // 11 % 7 = 4 — a family night
        s.timeMin = 12 * 60
        check(Family.dinnerTonight(s) && Family.judgeTalk(s, Family.MOM) == null,
            "family: the table is tonight's, but its beats wait " +
                "for the dinner window")
        s.timeMin = 18 * 60
        val h0 = Family.judgeTalk(s, Family.MOM)
        check(h0 != null && h0.step == 0 && h0.text.contains(
                Family.dishOf(11), ignoreCase = true),
            "family: beat 0 is served by the first parent talked " +
                "to, naming tonight's dish")
        check(Family.judgeTalk(s, Family.MOM) == null,
            "family: beat 1 belongs to the OTHER end of the table")
        val h1 = Family.judgeTalk(s, Family.DAD)
        check(h1 != null && h1.step == 1,
            "family: beat 1 lands at the far end of the table")
        check(Family.lookText(s, "KidsPark") == null &&
            Family.lookText(s, YOUR_HOUSE) != null &&
            Family.dinStepsDone(s) == 3,
            "family: beat 2 is the wash-up — a Look inside your " +
                "own house, and the table is fully landed")
        check(Family.lookText(s, YOUR_HOUSE) == null,
            "family: the wash-up lands once")
    }

    // ---------- the guest ----------
    run {
        val eng = Engine(910_005)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 3; Family.chooseStance(s, "warm")
        s.friendship["Stan"] = 80; s.friendship["Kyle"] = 80
        Crew.invite(s, "Stan"); Crew.invite(s, "Kyle")
        check(Crew.members(s).size == 2,
            "family guest: (staging) a crew of two stands")
        var guestDay = -1
        var guestName: String? = null
        for (d in 30..160) {
            if (d % 7 !in Family.DINNER_WEEKDAYS) continue
            s.absDay = d
            val g = Family.guestTonight(s)
            if (g != null) {
                check(g in Crew.members(s),
                    "family guest: the invitation goes to your crew " +
                        "first (day $d: $g)")
                guestDay = d; guestName = g; break
            }
        }
        check(guestDay > 0 && guestName != null,
            "family guest: across a season of family dinners, a " +
                "guest night comes (seeded at GUEST_CHANCE)")
        if (guestName != null) {
            s.absDay = guestDay
            check(Family.gatheringBlock(s, guestName!!, 18 * 60)
                    ?.location == YOUR_HOUSE &&
                Family.gatheringBlock(s, guestName!!, 12 * 60) == null &&
                Family.gatheringBlock(s, "Cartman", 18 * 60) == null,
                "family guest: the claim holds the guest at your " +
                    "house for the window only, and nobody else")
        }
    }

    // ---------- wrap, the allowance, and the phone ----------
    run {
        val eng = Engine(910_006)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.inventory[Minigames.COIN_ITEM] = 10
        s.absDay = 3; Family.chooseStance(s, "complicated")
        // sit at the table on day 4 (a family night), all beats
        s.absDay = 4; s.timeMin = 18 * 60
        Family.judgeTalk(s, Family.MOM); Family.judgeTalk(s, Family.DAD)
        Family.lookText(s, YOUR_HOUSE)
        check(Family.dinStepsDone(s) == 3,
            "allowance: (staging) a full family dinner landed")
        eng.onNewDay(s)   // day 5: the wrap
        check((s.life["famDinLast"] ?: -1) == 4 &&
            Family.wrapFor(s, 4) == (true to true),
            "allowance: the attended table wraps at midnight, " +
                "fully landed")
        eng.onNewDay(s)   // day 6
        val before = Minigames.capsuleCoins(s)
        eng.onNewDay(s)   // day 7: absDay % 7 == 0, allowance morning
        check(Minigames.capsuleCoins(s) - before == Family.ALLOWANCE_COINS &&
            (s.life["famAllowanceDay"] ?: -1) == 7,
            "allowance: +${Family.ALLOWANCE_COINS} 🪙 lands on the " +
                "week's first morning after a week with a family " +
                "dinner sat at — and only then")
        // a family that never sits gets no allowance
        val s2 = eng.newState()
        eng.createPlayer(s2, "NewKid", DEFAULT_APPEARANCE)
        s2.inventory[Minigames.COIN_ITEM] = 10
        s2.absDay = 3; Family.chooseStance(s2, "warm")
        repeat(4) { eng.onNewDay(s2) }   // days 4..7, no dinners
        check(Minigames.capsuleCoins(s2) == 10 &&
            (s2.life["famAllowanceDay"] ?: -1) == -1,
            "allowance: no dinner at the table, no allowance — " +
                "Mom's rule, enforced by the ledger")
        // a missed table reports itself by text
        val s3 = eng.newState()
        eng.createPlayer(s3, "NewKid", DEFAULT_APPEARANCE)
        s3.absDay = 3; Family.chooseStance(s3, "fine")
        s3.absDay = 7   // a family night (7 % 7 = 0)
        check(Family.dinnerTonight(s3),
            "phone: (staging) day 7 is a family-dinner night")
        eng.onNewDay(s3)   // day 8: missed wrap + harvest
        check(Family.missedDinnerDay(s3) == 7 &&
            s3.phoneTexts.any { it.trigger == Phone.FAMILY },
            "phone: the missed table leaves a plate in the fridge " +
                "and a FAMILY text from the dinner-duty parent")
        // and a dinner morning brings the call itself
        val s4 = eng.newState()
        eng.createPlayer(s4, "NewKid", DEFAULT_APPEARANCE)
        s4.absDay = 3; Family.chooseStance(s4, "warm")
        eng.onNewDay(s4)   // day 4, a family night
        check(s4.phoneTexts.any { it.trigger == Phone.FAMILY &&
                it.text.contains("dinner", ignoreCase = true) },
            "phone: a family-dinner morning brings the dinner " +
                "call — dish, house and window, from a parent")
        check(Phone.MAX_TEXTS == 220 && (98 + 2) * 2 <= Phone.MAX_TEXTS &&
            Phone.FAMILY in Phone.TRIGGERS,
            "phone: the cap math at 70 cast + 2 family stood at " +
                "72 threads x 2 = 144 <= MAX_TEXTS 160 and the dial " +
                "did NOT move; wave 6's 98 cast forced the dial to " +
                "220 at v0.11.0d (200 <= 220); the family trigger " +
                "is registered")
        val replyRes = Phone.quickReply(s4, Family.MOM, "👍")
        check(!replyRes.bonusApplied &&
            s4.phoneTexts.none { it.thread == Family.MOM &&
                it.sender == "you" },
            "phone: family threads are receive-only — quick " +
                "replies stay cast-gated, no bubble, no bonus")
    }

    // ---------- chores: the errand pattern, family-sized ----------
    run {
        val eng = Engine(910_007)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 3; Family.chooseStance(s, "warm")
        s.timeMin = 8 * 60
        var foundKind: String? = null
        var foundDay = -1
        for (d in 10..120) {
            s.absDay = d; s.timeMin = 8 * 60
            for (p in Family.PARENTS) {
                for (seed in 0..3) {
                    Family.reply(s, p, seed)
                    if (Family.activeChore(s) != null) {
                        foundKind = Family.activeChore(s)
                        foundDay = d; break
                    }
                }
                if (foundKind != null) break
            }
            if (foundKind != null) break
        }
        check(foundKind != null && foundKind in Family.CHORE_KINDS,
            "chores: a parent offers a tiny favor in Talk within " +
                "a few weeks of mornings (got $foundKind)")
        if (foundKind != null) {
            val asker = s.lifeText["famChoreBy"] ?: Family.MOM
            val ptsBefore = Family.points(s, asker)
            val doneLine: String? = when (foundKind) {
                "table" -> {
                    check(Family.noteFixture(s, "bed") == null,
                        "chores: the wrong fixture settles nothing")
                    Family.noteFixture(s, "table")
                }
                "photo" -> {
                    val rec = PhotoRecord(
                        id = "chorephoto", dayKey = s.todayKey,
                        dateLabel = "now", timeMin = s.timeMin,
                        locId = YOUR_HOUSE, inside = true,
                        weatherId = s.weatherId,
                        appearance = DEFAULT_APPEARANCE,
                        figures = listOf(
                            PhotoFigure(asker, "resident", "happy")))
                    Family.notePhoto(s, rec)
                    "settled"
                }
                else -> {   // fetch
                    val item = Family.choreFetchItem(s)
                    check(item != null && item in Family.FETCH_ITEMS &&
                        Errands.sourceOf(item!!) != null,
                        "chores: the fetch asks for a real pantry " +
                            "staple the town's shops actually stock " +
                            "(sourceOf-pinned): $item")
                    s.inventory[item!!] = 1
                    Family.reply(s, asker, 1)
                }
            }
            check(Family.activeChore(s) == null &&
                (s.life["famChoreDone"] ?: 0) == 1 &&
                Family.points(s, asker) > ptsBefore,
                "chores: the verb settles it ($foundKind) — warmth " +
                    "paid, no coins attached (done line: $doneLine)")
            check(Minigames.capsuleCoins(s) == 0,
                "chores: a completed chore pays exactly zero coins " +
                    "— the allowance is the only new coin source")
        }
        // a stale chore lapses free at midnight
        s.lifeText["famChore"] = "table"
        s.lifeText["famChoreBy"] = Family.DAD
        s.life["famChoreDay"] = s.absDay
        val dadPts = Family.points(s, Family.DAD)
        eng.onNewDay(s)
        check(Family.activeChore(s) == null &&
            Family.points(s, Family.DAD) == dadPts,
            "chores: an undone chore lapses at rollover — no " +
                "penalty, no guilt, no record but the lapse")
    }

    // ---------- photos, the frame, and the darkroom ----------
    run {
        val eng = Engine(910_008)
        val s = eng.newState()
        val app = DEFAULT_APPEARANCE + mapOf("skin" to "tan",
            "hair_style" to "mop", "hair_color" to "black")
        eng.createPlayer(s, "NewKid", app)
        s.absDay = 3; Family.chooseStance(s, "warm")
        s.timeMin = 8 * 60
        val me = s.agents.values.first { it.isPlayer }
        me.location = YOUR_HOUSE
        val gen = Family.presentAt(s, YOUR_HOUSE, true)
            .map { it.persona }
        val rec = Photos.compose(s, emptyList(), gen, me.name, app)
        check(rec.locId == YOUR_HOUSE && Family.inPhoto(rec) &&
            rec.figures.any { it.name == Family.MOM &&
                it.kind == "resident" },
            "photos: a parent at home stands in the frame as a " +
                "household figure (kind resident)")
        s.photos.add(rec)
        check(Family.latestFamilyPhoto(s)?.id == rec.id,
            "photos: the family frame hangs the newest family " +
                "photo taken at home")
        // the darkroom: print it, gift it to Mom
        s.inventory[Minigames.COIN_ITEM] = 50
        s.timeMin = 10 * 60
        val dev = Darkroom.develop(s, rec.id, Darkroom.SIZE_ENLARGEMENT)
        check(dev != null,
            "darkroom: a family photo develops like any other")
        if (dev != null) {
            val print = dev.print
            check(Darkroom.giftablePrints(s, Family.MOM)
                    .any { it.id == print.id },
                "darkroom: the family enlargement is giftable to " +
                    "the parent in its frame")
            val ptsBefore = Family.points(s, Family.MOM)
            val gift = Darkroom.givePrint(s, Family.MOM, print.id)
            check(gift != null && gift.given &&
                gift.delta in 1..Darkroom.GIFT_CAP &&
                Family.points(s, Family.MOM) ==
                    ptsBefore + gift.delta &&
                !s.friendship.containsKey(Family.MOM) &&
                gift.line.contains("family warmth"),
                "darkroom: gifting a print TO a parent pays the " +
                    "darkroom's judged delta (+${gift?.delta}) in " +
                    "family warmth — never cast friendship")
            // the dud: a print of Mom alone, offered to Dad
            val rec2 = PhotoRecord(
                id = "momonly", dayKey = s.todayKey, dateLabel = "now",
                timeMin = s.timeMin, locId = YOUR_HOUSE, inside = true,
                weatherId = s.weatherId, appearance = app,
                figures = listOf(
                    PhotoFigure(me.name, "player", "happy"),
                    PhotoFigure(Family.MOM, "resident", "happy")))
            s.photos.add(rec2)
            val dev2 = Darkroom.develop(s, rec2.id,
                Darkroom.SIZE_ENLARGEMENT)
            if (dev2 != null) {
                val dadPts = Family.points(s, Family.DAD)
                val dud = Darkroom.givePrint(s, Family.DAD, dev2.print.id)
                check(dud != null && !dud.given &&
                    Family.points(s, Family.DAD) == dadPts,
                    "darkroom: a print without Dad in it is a polite " +
                        "dud for Dad — named, factual, handed back")
            }
        }
    }

    // ---------- mornings & the save round-trip ----------
    run {
        val eng = Engine(910_009)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 3
        check(Family.morningNote(s)?.contains("moving in") == true,
            "mornings: the arrival morning's report names the move")
        Family.chooseStance(s, "complicated")
        Family.adjustPoints(s, Family.MOM, 17)
        Family.adjustPoints(s, Family.DAD, 9)
        val momPts = Family.points(s, Family.MOM)
        val dadPts = Family.points(s, Family.DAD)
        val back = decodeGameState(encodeGameState(s))
        check(Family.arrived(back) && Family.stance(back) == "complicated" &&
            Family.points(back, Family.MOM) == momPts &&
            Family.points(back, Family.DAD) == dadPts &&
            Family.arrivalDay(back) == 3,
            "save: the family's whole state — arrival, stance, " +
                "warmth — rides the life maps through a full " +
                "encode/decode round trip, additively")
        check(back.friendship.keys.none { it in Family.PARENTS },
            "save: even after a round trip, no parent stands in " +
                "the friendship table")
    }

    // ---------- spoiler discipline ----------
    run {
        val sealed = listOf("sleepwalk", "cameo", "communal paperwork",
            "the culprit is", "strongbox contains")
        check(sealed.none { famSrc.lowercase().contains(it) },
            "family: the family's writing touches no mystery " +
                "solution — parents react to a case's public shape " +
                "only (its being open, the town talking)")
    }

    // ---------- the ledger ----------
    run {
        check(Family.ARRIVAL_ABS_DAY == 3 &&
            Family.ALLOWANCE_COINS == 3 &&
            Family.ALLOWANCE_WEEKDAY == 0 &&
            Family.DINNER_WEEKDAYS == setOf(0, 2, 4) &&
            Family.GUEST_CHANCE == 0.45 &&
            Family.FETCH_ITEMS.all { itemById(it) != null } &&
            tuning.contains("family allowance"),
            "ledger: the family dials stand at the values the " +
                "README tuning ledger prints (arrival day 3, " +
                "allowance 3 🪙 on weekday 0, dinners {0,2,4}, " +
                "guest chance 0.45) — the allowance named in the " +
                "ledger as the build's only new coin source")
    }

    // ---------- the release pin ----------
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
}

// ================= v0.10.0b: hero nights =================
// Queue #10 item 2 — after dark, the kids put on capes.
// Sixteen ORIGINAL personas (invented names, powers and
// costume specs off each kid's own measured palette), a
// twice-weekly patrol claim that yields to everything
// bigger, beats on Look/Talk/camera, a five-movement
// caper with a stance finale, crew rendezvous honesty,
// and parents with opinions. The caper's story secret is
// scanned for here the way the mysteries' solutions are:
// the chapters, the journal and the README must never
// speak it — only the finale's own lines may.
private fun sectionV0100b(root: String) {
    println("== v0.10.0b: hero nights ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val tuning = File(root, "docs/TUNING.md").readText()
    check(readme.contains("### v0.10.0b"),
        "v0.10.0b: the README carries this build's changelog entry")
    val heroSrc = File(root,
        "src/com/hunt3r/southparktown/Heroes.kt").readText()

    fun patrolDay(from: Int): Int {
        var d = from
        while (!Heroes.isPatrolNight(d)) d++
        return d
    }
    fun heroState(seed: Int): GameState {
        val eng = Engine(seed.toLong())
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = patrolDay(s.absDay)
        s.timeMin = 20 * 60
        return s
    }

    // ---------- the roster & the originality guard ----------
    run {
        check(Heroes.ROSTER.size == 16,
            "heroes: the patrol roster is sixteen personas")
        check(Heroes.ROSTER.all { it.kid in CharacterSystem.CAST_KIDS } &&
            Heroes.ROSTER.map { it.kid }.toSet().size == 16,
            "heroes: every persona belongs to a real kid cast " +
                "member, once each")
        check(Heroes.ROSTER.map { it.heroName }.toSet().size == 16 &&
            Heroes.ROSTER.all { KidArt.SHEETS.containsKey(it.kid) },
            "heroes: sixteen distinct invented names, and every " +
                "roster kid has a measured sheet to derive from")
        // the Pocket Pals pattern, extended: every
        // player-facing string the module owns is scanned
        // against the franchise denylist
        val corpus = StringBuilder()
        for (p in Heroes.ROSTER) {
            corpus.append(p.heroName).append(' ').append(p.power)
                .append(' ').append(Heroes.heroLineFor(p.kid))
                .append(' ')
        }
        for (n in Heroes.NAME_OPTIONS) corpus.append(n).append(' ')
        for ((_, label) in Heroes.POWERS) corpus.append(label).append(' ')
        for (spot in Heroes.PATROL_SPOTS)
            for (inc in Heroes.incidentsFor(spot))
                corpus.append(inc.scene).append(' ').append(inc.settled)
                    .append(' ')
        for (ch in Heroes.CHAPTERS) {
            corpus.append(ch.title).append(' ')
                .append(ch.helpLabel).append(' ').append(ch.watchLabel)
                .append(' ').append(ch.helpedText).append(' ')
                .append(ch.watchedText).append(' ')
            for (l in ch.lines) corpus.append(l.text).append(' ')
        }
        for ((_, label) in Heroes.FINALE_STANCES)
            corpus.append(label).append(' ')
        for (l in Phone.HERO_PARENT_LINES) corpus.append(l).append(' ')
        val low = corpus.toString().lowercase()
        check(Heroes.DENYLIST.none { low.contains(it) },
            "heroes: no persona name, power, chapter, incident " +
                "or parent text touches the franchise denylist — " +
                "the roster is original, in the Pocket Pals " +
                "guard's pattern")
        check(Heroes.DENYLIST.size >= 20,
            "heroes: the denylist itself stands at full strength")
    }

    // ---------- the spoiler discipline: the caper's secret ----------
    run {
        val publicText = StringBuilder()
        for (ch in Heroes.CHAPTERS) {
            publicText.append(ch.title).append(' ')
            for (l in ch.lines) publicText.append(l.text).append(' ')
            publicText.append(ch.helpedText).append(' ')
                .append(ch.watchedText).append(' ')
        }
        val entry = readme.substringAfter("### v0.10.0b")
            .substringBefore("### v0.10.0a")
        check(!publicText.contains("DogPoo") &&
            !entry.contains("DogPoo"),
            "heroes: the caper's secret is told ONLY by the " +
                "finale's own lines — the chapters, the journal " +
                "copy and the README changelog never name the " +
                "Curator (structure only, the spoiler discipline)")
        check(Heroes.pageLines(GameState()).none {
                it.contains("DogPoo") },
            "heroes: the hero log's public page keeps the secret")
    }

    // ---------- costume derivation ----------
    run {
        check(Heroes.ROSTER.all { p ->
            val sheet = KidArt.SHEETS.getValue(p.kid)
            val spec = Heroes.costumeSpec(sheet,
                Heroes.costumeCodeFor(p.kid))
            spec.backStyle == "cape" && spec.backColor == p.cape &&
                spec.top == sheet.top &&
                spec.hairStyle == sheet.hairStyle &&
                spec.hairColor == sheet.hairColor &&
                spec.special == sheet.special &&
                spec.hatId == sheet.hatId
        }, "heroes: a costume spec is the kid's OWN sheet, caped " +
            "in the persona's color — clothes, hair, hat and " +
            "specials untouched (underneath, still themselves)")
        check(Heroes.ROSTER.all { p ->
            val t = Heroes.parseCode(Heroes.costumeCodeFor(p.kid))
            t != null && t.first == p.cape && t.second == p.mask &&
                t.third == p.emblem
        }, "heroes: every persona's costume code round-trips " +
            "(cape | mask | emblem)")
        check(Heroes.parseCode("") == null &&
            Heroes.parseCode("red") == null &&
            Heroes.parseCode("#fff|#000") == null &&
            Heroes.costumeCodeFor("Randy") == "",
            "heroes: malformed codes and non-roster kids get " +
                "no costume")
        val s = heroState(920_001)
        Heroes.createHero(s, "Captain Curfew", "speed")
        val code = Heroes.playerCostumeCode(s)
        val worn = avatarSpec(DEFAULT_APPEARANCE)
        val t = Heroes.parseCode(code)
        check(t != null && t.first == worn.top &&
            t.second == darkerHex(worn.top) && t.third == "bolt",
            "heroes: YOUR costume derives from your worn " +
                "palette — the cape in your top's color, the " +
                "mask its darker shade, the emblem your power's")
    }

    // ---------- your identity: found it once, change it at the mirror ----------
    run {
        val eng = Engine(920_002)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = 1
        check(!Heroes.creationDue(s),
            "heroes: day 1 is too early — the town gets a day " +
                "to be a town first")
        s.absDay = 2
        check(Heroes.creationDue(s),
            "heroes: from day 2 the founding is due (a " +
                "pre-0.10.0b save meets it on its first " +
                "eligible safe moment)")
        check(!Heroes.createHero(s, "Captain Curfew", "bogus"),
            "heroes: an unlisted power cannot found an identity")
        check(!Heroes.changeHero(s, "The Porchlight", "speed"),
            "heroes: the mirror cannot change an identity " +
                "that doesn't exist yet")
        check(Heroes.createHero(s, "Captain Curfew", "speed") &&
            Heroes.heroCreated(s) && !Heroes.creationDue(s) &&
            Heroes.heroName(s) == "Captain Curfew" &&
            Heroes.powerLabel(s).startsWith("SUPER SPEED"),
            "heroes: the founding stores the name and the " +
                "power, once")
        check(!Heroes.createHero(s, "Kid Comet", "animals"),
            "heroes: the founding plays exactly once")
        check(Heroes.changeHero(s, "Kid Comet", "animals") &&
            Heroes.heroName(s) == "Kid Comet" &&
            (Heroes.youCardLine(s) ?: "").contains("Kid Comet"),
            "heroes: the mirror route re-founds the identity, " +
                "and the YOU card reads the new name")
        check((Heroes.pageLines(s).firstOrNull() ?: "")
                .contains("Kid Comet"),
            "heroes: the HERO LOG page leads with the identity")
        check(Heroes.pageLines(GameState()).first() == "No cape yet.",
            "heroes: the page says so plainly before any cape")
        check(!heroSrc.contains("state.coins") &&
            !heroSrc.contains("friendship["),
            "heroes: the module never moves a coin and never " +
                "writes friendship — hero work pays the HERO " +
                "tally only, and the kid underneath keeps " +
                "their real relationships")
    }

    // ---------- the cadence ----------
    run {
        check(Heroes.PATROL_WEEKDAYS == setOf(3, 6) &&
            tuning.contains("Wednesday and Saturday"),
            "heroes: patrols run Wednesday and Saturday, as " +
                "the ledger prints")
        check((0..27).count { Heroes.isPatrolNight(it) } == 8 &&
            (0..27).all {
                Heroes.isPatrolNight(it) ==
                    (Jobs.weekdayOf(it) in setOf(3, 6)) },
            "heroes: exactly two patrol nights a week, on the " +
                "calendar's own weekdays")
        check(!Heroes.inWindow(Heroes.PATROL_FROM - 1) &&
            Heroes.inWindow(Heroes.PATROL_FROM) &&
            Heroes.inWindow(Heroes.PATROL_TO - 1) &&
            !Heroes.inWindow(Heroes.PATROL_TO) &&
            Heroes.PATROL_TO == 22 * 60,
            "heroes: the window is 19:30 to the 22:00 sleep " +
                "hour — no hero is ever out past it")
        check(Heroes.PATROL_WEEKDAYS
                .intersect(Family.DINNER_WEEKDAYS).isEmpty(),
            "heroes: patrol weekdays and YOUR family-dinner " +
                "weekdays are disjoint by construction — the " +
                "patrol can never even apply on a family " +
                "dinner night")
        val s = heroState(920_003)
        check(Heroes.ROSTER.all {
                Heroes.patrolSpotFor(s, it.kid) in Heroes.PATROL_SPOTS } &&
            Heroes.ROSTER.map { Heroes.patrolSpotFor(s, it.kid) }
                .toSet().size >= 4 &&
            Heroes.patrolSpotFor(s, "Stan") ==
                Heroes.patrolSpotFor(s, "Stan"),
            "heroes: the night's posts are a pure function of " +
                "the day — the whole roster posted, spread " +
                "across the spots")
    }

    // ---------- the claim & its deference ----------
    run {
        // a patrol night Stan is FREE on: cast dinners also
        // run Wednesday nights, and a Stan at someone's table
        // is busy (the invariant below pins that side) — the
        // claim's positive case is staged on a free night
        var freeDay = -1
        run {
            val st = heroState(920_004)
            var d = st.absDay
            for (i in 0 until 24) {
                st.absDay = d
                if (Crew.busyReason(st, "Stan") == null &&
                    !Heroes.townMomentOwned(st)) {
                    freeDay = d; break
                }
                d = patrolDay(d + 1)
            }
        }
        check(freeDay > 0,
            "heroes: (staging) a patrol night finds Stan free")
        val s = heroState(920_004)
        s.absDay = freeDay
        val stan = Heroes.gatheringBlock(s, "Stan", 20 * 60)
        check(stan != null &&
            stan.location == Heroes.patrolSpotFor(s, "Stan") &&
            stan.activity.contains("The Standard"),
            "heroes: on a patrol night a roster kid is claimed " +
                "to their post, in persona")
        check(Heroes.gatheringBlock(s, "Randy", 20 * 60) == null &&
            Heroes.gatheringBlock(s, "Stan", 12 * 60) == null,
            "heroes: no claim for non-roster kids, and none " +
                "outside the window")
        val thu = heroState(920_005)
        thu.absDay = patrolDay(thu.absDay) + 1   // a Thursday
        check(!Heroes.isPatrolNight(thu.absDay) &&
            Heroes.gatheringBlock(thu, "Stan", 20 * 60) == null,
            "heroes: Thursday night, Stan is just Stan")
        // the busyReason guard, exercised both ways, on the
        // same free night the positive case used
        val busy = heroState(920_006)
        busy.absDay = freeDay
        busy.agents["Stan"]?.asleep = true
        check(Crew.busyReason(busy, "Stan") != null &&
            Heroes.gatheringBlock(busy, "Stan", 20 * 60) == null,
            "heroes: an occupied kid (here, asleep) is never " +
                "claimed — busyReason wins wholesale")
        busy.agents["Stan"]?.asleep = false
        check(Crew.busyReason(busy, "Stan") == null &&
            Heroes.gatheringBlock(busy, "Stan", 20 * 60) != null,
            "heroes: free again, the claim returns")
        // the universal invariant: across a season of patrol
        // nights, the claim NEVER fires for an occupied kid
        var invariant = true
        for (w in 0 until 12) {
            val st = heroState(920_010 + w)
            st.absDay = patrolDay(st.absDay + w * 7)
            for (p in Heroes.ROSTER) {
                if (Crew.busyReason(st, p.kid) != null &&
                    Heroes.gatheringBlock(st, p.kid, 20 * 60) != null)
                    invariant = false
            }
        }
        check(invariant,
            "heroes: across twelve patrol nights, no occupied " +
                "roster kid (dinner, work, movie, ceremony, " +
                "finale, climax, emergency) is ever claimed")
        // the crew rendezvous outranks the patrol — staged
        // on the same free night, the player standing at a
        // DIFFERENT spot than Stan's post, so the stack's
        // answer can only be the crew's
        val cs = heroState(920_020)
        cs.absDay = freeDay
        cs.friendship["Stan"] = 30
        Crew.invite(cs, "Stan")
        val engC = Engine(920_020)
        val stanPost = Heroes.patrolSpotFor(cs, "Stan")
        val playerSpot = Heroes.PATROL_SPOTS.first { it != stanPost }
        engC.player(cs).location = playerSpot
        check(Heroes.gatheringBlock(cs, "Stan", 20 * 60) != null,
            "heroes: (staging) unclaimed, Stan would patrol")
        cs.lifeText["crew:mode:Stan"] = "with"
        cs.lifeText["crew:with:Stan"] = playerSpot
        val effC = engC.effectiveAgendaBlock(cs,
            cs.agents.getValue("Stan"), 20 * 60)
        check(Heroes.gatheringBlock(cs, "Stan", 20 * 60) == null &&
            effC?.location == playerSpot,
            "heroes: a crewmate standing with you is held by " +
                "the crew's claim, not the patrol's — they " +
                "patrol WITH you, in costume, at your spot")
        cs.lifeText["crew:mode:Stan"] = ""
        check(Heroes.gatheringBlock(cs, "Stan", 20 * 60) != null,
            "heroes: off the rendezvous, the same crewmate " +
                "takes their own post")
        // the stack itself: the effective block IS the patrol
        // (on a Wednesday Kyle is free — dinners take him
        // some weeks, and those weeks the stack says dinner)
        var stackOk = false
        run {
            val eng = Engine(920_021)
            val ss = eng.newState()
            eng.createPlayer(ss, "NewKid", DEFAULT_APPEARANCE)
            ss.timeMin = 20 * 60
            var d = patrolDay(ss.absDay)
            for (i in 0 until 24) {
                ss.absDay = d
                val eff = eng.effectiveAgendaBlock(ss,
                    ss.agents.getValue("Kyle"), 20 * 60)
                if (eff?.location ==
                    Heroes.patrolSpotFor(ss, "Kyle")) {
                    stackOk = true; break
                }
                d = patrolDay(d + 1)
            }
        }
        check(stackOk,
            "heroes: through the real agenda stack, a free " +
                "Kyle's block on a patrol night is his " +
                "patrol post")
        // the moment guard, pinned both ways: a screening
        // does NOT own the streets; a holiday does
        var screeningOk = false
        run {
            val st = heroState(920_023)
            var d = st.absDay
            for (i in 0 until 24) {
                st.absDay = d
                if (Jobs.weekdayOf(d) == 6 &&
                    Capstones.screeningLive(st)) {
                    val free = Heroes.ROSTER.firstOrNull {
                        Crew.busyReason(st, it.kid) == null }
                    if (free != null &&
                        Heroes.gatheringBlock(st, free.kid,
                            20 * 60) != null) screeningOk = true
                    break
                }
                d = patrolDay(d + 1)
            }
        }
        check(screeningOk,
            "heroes: on a Saturday screening night the patrol " +
                "still works the streets — a film owns its " +
                "cinema, not the town (its audience is claimed " +
                "by the movie rail inside busyReason, honored " +
                "in full)")
        var holidayOk = false
        run {
            // Engine keeps state.holidayId in step with the
            // calendar in lived play; the guard reads it
            // through HolidayBeats.holidayOf, so the staging
            // sets the field the way a holiday morning does
            val hs = heroState(920_024)
            hs.holidayId = HOLIDAYS.first().id
            val free = Heroes.ROSTER.firstOrNull {
                Crew.busyReason(hs, it.kid) == null }
            holidayOk = HolidayBeats.holidayOf(hs) != null &&
                Heroes.townMomentOwned(hs) &&
                (free == null ||
                    Heroes.gatheringBlock(hs, free.kid,
                        20 * 60) == null)
        }
        check(holidayOk,
            "heroes: a holiday owns its night — the patrol " +
                "stands down (townMomentOwned carries the " +
                "holiday, the finale window, the case's " +
                "critical hour, the bee hours and the " +
                "ceremony window)")
        // family dinner: the guest is the family's, full stop
        val fs = heroState(920_022)
        fs.absDay = 3; Family.chooseStance(fs, "warm")
        fs.friendship["Stan"] = 80
        Crew.invite(fs, "Stan")
        var guest: String? = null
        var guestDay = -1
        for (d in 30..160) {
            if (d % 7 !in Family.DINNER_WEEKDAYS) continue
            fs.absDay = d
            val g = Family.guestTonight(fs)
            if (g != null) { guest = g; guestDay = d; break }
        }
        check(guest != null && guestDay > 0,
            "heroes: (staging) a family guest night comes")
        if (guest != null) {
            fs.absDay = guestDay
            check(Family.gatheringBlock(fs, guest, 19 * 60 + 45)
                    ?.location == YOUR_HOUSE &&
                Heroes.gatheringBlock(fs, guest, 19 * 60 + 45) == null,
                "heroes: on the guest's family-dinner night, " +
                    "Family holds them at your house and the " +
                    "patrol claim is silent — a patrol never " +
                    "eats a family dinner")
        }
    }

    // ---------- the beats: Look finds, Talk escorts ----------
    run {
        // find a patrol (night, spot) with an incident waiting
        var incState: GameState? = null
        var incSpot = ""
        for (w in 0 until 8) {
            val st = heroState(920_030 + w)
            st.absDay = patrolDay(st.absDay + w * 7)
            for (spot in Heroes.PATROL_SPOTS) {
                if (Heroes.incidentAt(st, spot) != null) {
                    incState = st; incSpot = spot; break
                }
            }
            if (incState != null) break
        }
        check(incState != null,
            "heroes: (staging) the season offers incident nights")
        if (incState != null) {
            val st = incState
            val before = Heroes.incidentAt(st, incSpot)
            val text = Heroes.lookText(st, incSpot)
            check(before != null && text != null &&
                text.contains("HERO WORK") &&
                (st.life["heroIncidents"] ?: 0) == 1 &&
                (st.life["heroAssists"] ?: 0) == 1 &&
                st.life["heroOutDay"] == st.absDay,
                "heroes: the careful Look finds the night's " +
                    "small crime and settles it in the telling — " +
                    "one incident, one assist, the night stamped")
            check(Heroes.lookText(st, incSpot) == null &&
                Heroes.incidentAt(st, incSpot) == null,
                "heroes: one incident per spot per night — the " +
                    "second Look finds a quiet street")
            check(before!!.scene.isNotBlank() &&
                before.settled.isNotBlank() &&
                Heroes.PATROL_SPOTS.all {
                    Heroes.incidentsFor(it).isNotEmpty() },
                "heroes: every patrol spot has its own " +
                    "kid-scale crime writing")
        }
        val day = heroState(920_040)
        day.timeMin = 12 * 60
        check(Heroes.incidentAt(day, "KidsPark") == null &&
            Heroes.lookText(day, "KidsPark") == null,
            "heroes: no incidents by daylight")
        // the escort, on the Walk graph's own price
        val es = heroState(920_041)
        val engE = Engine(920_041)
        Heroes.createHero(es, "Captain Curfew", "speed")
        engE.player(es).location = "KidsPark"
        es.agents["Randy"]?.location = "KidsPark"
        es.agents["Randy"]?.asleep = false
        val opt = Heroes.escortOption(es, "Randy")
        val raw = Walk.routeMinutes(es, "KidsPark",
            Heroes.escortHome(es, "Randy") ?: "")
        val mins = Heroes.escortMinutes(es, "Randy")
        check(opt != null && mins >= 15 && mins % 15 == 0 &&
            mins >= raw && mins < raw + 15,
            "heroes: the escort is offered after dark, and its " +
                "price is the Walk route rounded up to the " +
                "tick (raw ${raw}m, priced ${mins}m) — heroes " +
                "don't teleport either")
        val line = Heroes.escort(es, "Randy")
        check(line != null && line.contains("Randy") &&
            (es.life["heroEscorts"] ?: 0) == 1 &&
            (es.life["heroAssists"] ?: 0) == 1 &&
            Heroes.escortOption(es, "Randy") == null,
            "heroes: the escort settles once — tallies move, " +
                "the offer closes for the night")
        check(Heroes.escortOption(es, "Bogus") == null &&
            Heroes.escort(es, "Bogus") == null,
            "heroes: nobody escorts a person who isn't there")
        // a roster hero in costume is not an escort job
        val spot = Heroes.patrolSpotFor(es, "Stan")
        es.agents["Stan"]?.location = spot
        engE.player(es).location = spot
        check(Heroes.inCostume(es, "Stan") &&
            Heroes.escortOption(es, "Stan") == null,
            "heroes: someone already in costume doesn't need " +
                "walking home — they're ON the patrol")
    }

    // ---------- costumed talk & costumed rendering facts ----------
    run {
        val s = heroState(920_050)
        val spot = Heroes.patrolSpotFor(s, "Wendy")
        s.agents["Wendy"]?.location = spot
        s.agents["Wendy"]?.asleep = false
        check(Heroes.inCostume(s, "Wendy"),
            "heroes: a roster kid at her post in the window " +
                "is in costume")
        val line = Heroes.costumeLine(s, "Wendy")
        check(line != null && line.speaker == "Wendy" &&
            line.text == Heroes.heroLineFor("Wendy"),
            "heroes: in costume, she speaks hero register — " +
                "her persona's line, in her voice")
        check(Heroes.costumeLine(s, "Wendy") == null,
            "heroes: the hero register plays once a night each")
        val home = heroState(920_051)
        home.agents["Wendy"]?.location = "StanHouse"
        check(!Heroes.inCostume(home, "Wendy") &&
            Heroes.costumeLine(home, "Wendy") == null,
            "heroes: at home in street clothes, no costume, " +
                "no register — just Wendy")
        check(Heroes.figureCode(s,
                PhotoFigure("Wendy", "cast", "happy")) ==
            Heroes.costumeCodeFor("Wendy") &&
            Heroes.figureCode(s,
                PhotoFigure("Randy", "cast", "happy")) == "",
            "heroes: the photo figure's costume code follows " +
                "the moment — roster in costume, everyone else " +
                "in their clothes")
        val ks = File(root,
            "src/com/hunt3r/southparktown/KidArt.kt").readText()
        val gv = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        val pv = File(root,
            "src/com/hunt3r/southparktown/PhotoView.kt").readText()
        check(ks.contains("fun drawHeroFigure") &&
            ks.contains("fun drawKidHero") &&
            gv.contains("KidArt.drawKidHero") &&
            pv.contains("PaperDoll.drawDollHero") &&
            File(root, "src/com/hunt3r/southparktown/PaperDoll.kt")
                .readText().contains("KidArt.drawHeroFigure"),
            "heroes: the street (GameView) and the album " +
                "(PhotoView) both draw through KidArt's hero " +
                "pass — cape, mask and emblem from the code " +
                "(v0.16.0d: the album reaches the pass through " +
                "the PaperDoll stills path, which wraps it)")
    }

    // ---------- photos: the camera tells the truth ----------
    run {
        val s = heroState(920_060)
        val eng = Engine(920_060)
        Heroes.createHero(s, "The Porchlight", "nightsight")
        eng.player(s).location = "KidsPark"
        s.agents["Stan"]?.location = "KidsPark"
        s.agents["Stan"]?.asleep = false
        s.friendship["Stan"] = 90
        val rec = Photos.compose(s, listOf("Stan"), emptyList(),
            "NewKid", DEFAULT_APPEARANCE)
        val stanFig = rec.figures.firstOrNull { it.name == "Stan" }
        val meFig = rec.figures.firstOrNull { it.kind == "player" }
        check(stanFig != null &&
            stanFig.hero == Heroes.costumeCodeFor("Stan"),
            "heroes: a patrol-night photo freezes Stan's " +
                "costume onto his figure")
        check(meFig != null &&
            meFig.hero == Heroes.playerCostumeCode(s),
            "heroes: ...and yours, in your worn palette")
        val rt = PhotoRecord.fromMap(rec.toMap())
        check(rt != null && rt.figures
                .firstOrNull { it.name == "Stan" }?.hero ==
                stanFig?.hero,
            "heroes: the costume survives the record's own " +
                "serialization — the album and the darkroom " +
                "will render the capes forever")
        val legacy = PhotoFigure.fromMap(mapOf(
            "name" to "Stan", "kind" to "cast", "mood" to "happy",
            "pose" to "none", "reaction" to "happy", "points" to 3))
        check(legacy != null && legacy.hero == "",
            "heroes: a pre-0.10.0b figure (no hero key) loads " +
                "in street clothes — saves are additive only")
        val day = heroState(920_061)
        day.timeMin = 12 * 60
        val engD = Engine(920_061)
        engD.player(day).location = "KidsPark"
        day.agents["Stan"]?.location = "KidsPark"
        day.friendship["Stan"] = 90
        val dayRec = Photos.compose(day, listOf("Stan"),
            emptyList(), "NewKid", DEFAULT_APPEARANCE)
        check(dayRec.figures.all { it.hero == "" },
            "heroes: a daylight photo has no capes in it — " +
                "the camera lies about nothing")
    }

    // ---------- the caper, driven end to end ----------
    run {
        fun drive(helped: Int, stance: String): Pair<GameState, String?> {
            val eng = Engine(920_070L + helped * 31 + stance.length)
            val s = eng.newState()
            eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
            Heroes.createHero(s, "Captain Curfew", "speed")
            check(Heroes.caperStage(s) == 0,
                "caper: unbegun until the first midnight under " +
                    "a made hero")
            Heroes.dailyRollover(s)
            check(Heroes.caperStage(s) == 1,
                "caper: chapter one opens on that midnight")
            var played = 0
            while (Heroes.caperStage(s) in 1..4) {
                val ch = Heroes.CHAPTERS[Heroes.caperStage(s) - 1]
                s.absDay = patrolDay(s.absDay + 1)
                s.timeMin = 20 * 60
                eng.player(s).location = ch.locId
                check(Heroes.caperBeatDue(s) == ch,
                    "caper: chapter ${Heroes.caperStage(s)} " +
                        "(\"${ch.title}\") is due at its spot on " +
                        "a patrol night")
                val told = Heroes.playCaperBeat(s, played < helped)
                check(told != null &&
                    Heroes.caperStage(s) == played + 2,
                    "caper: the beat turns the chapter over")
                played++
            }
            check(played == 4 && Heroes.caperHelped(s) == helped,
                "caper: four movements, the helped count kept")
            s.absDay = patrolDay(s.absDay + 1)
            s.timeMin = 20 * 60
            eng.player(s).location = "MainStreet"
            check(!Heroes.finaleDue(s),
                "caper: the finale waits for its park")
            eng.player(s).location = "KidsPark"
            check(Heroes.finaleDue(s),
                "caper: the finale is due at Kids Park on a " +
                    "patrol night")
            check(Heroes.playFinale(s, "bogus") == null &&
                !Heroes.caperDone(s),
                "caper: an unlisted stance does not land")
            val text = Heroes.playFinale(s, stance)
            return s to text
        }
        val (named, namedText) = drive(4, "name")
        check(Heroes.caperDone(named) &&
            namedText != null && namedText.contains("LICENSED") &&
            named.lifeText["caperStance"] == "name" &&
            House.decorFor(named).contains("hero_mask") &&
            House.decorTokensFor(named).contains("hero-mask"),
            "caper: named with the reading done, the menace " +
                "is licensed — and the mask retires to its " +
                "hook by the door (the decor census's 17th " +
                "piece, derived like every piece)")
        check(Heroes.pageLines(named).any { it.contains("CLOSED") },
            "caper: the HERO LOG closes the case in its own words")
        val (gone, goneText) = drive(0, "name")
        check(Heroes.caperDone(gone) && goneText != null &&
            goneText.contains("didn't do the reading"),
            "caper: named WITHOUT the reading, the Curator is " +
                "simply gone — the helped count writes the " +
                "ending's weather")
        val (legend, _) = drive(2, "silence")
        check(Heroes.caperDone(legend) &&
            legend.lifeText["mark:hero_caper"] == "silence",
            "caper: silence keeps the legend, and the mark " +
                "remembers the stance")
        var legendSeen = false
        for (w in 0 until 40) {
            legend.absDay = patrolDay(legend.absDay + 1)
            legend.timeMin = 20 * 60
            for (spot in Heroes.PATROL_SPOTS) {
                if (Heroes.lookText(legend, spot)
                        ?.contains("six inches left") == true)
                    legendSeen = true
            }
        }
        check(legendSeen,
            "caper: after the silent ending, the Look still " +
                "finds things six inches left — the legend " +
                "provides, ambiently")
        val (joined, joinedText) = drive(3, "join")
        check(Heroes.caperDone(joined) && joinedText != null &&
            joinedText.contains("perfectly arranged"),
            "caper: the accomplice ending leaves one perfect " +
                "park and no proof")
        val bare = GameState()
        check(!Heroes.caperDone(bare) &&
            !House.decorFor(bare).contains("hero_mask"),
            "caper: no caper, no mask — the hook stays empty")
    }

    // ---------- crew & family ----------
    run {
        val s = heroState(920_080)
        val eng = Engine(920_080)
        Heroes.createHero(s, "Captain Curfew", "speed")
        s.friendship["Craig"] = 30
        Crew.invite(s, "Craig")
        val spot = Heroes.patrolSpotFor(s, "Craig")
        s.agents["Craig"]?.location = spot
        val line = Heroes.costumeLine(s, "Craig")
        check(line != null && line.text.contains("Same crew"),
            "heroes: a crewmate in costume says the quiet " +
                "part — same crew, in AND out of costume")
        // the parents' opinions, in person and on the phone
        val fs = heroState(920_081)
        fs.absDay = 3; Family.chooseStance(fs, "warm")
        Heroes.createHero(fs, "Captain Curfew", "speed")
        fs.life["heroLastPatrol"] = fs.absDay - 1
        check(Heroes.parentRemark(fs, Family.MOM) != null &&
            Heroes.parentRemark(fs, Family.MOM) == null &&
            Heroes.parentRemark(fs, Family.DAD) != null,
            "family: the morning after a patrol, each parent " +
                "delivers their cape opinion exactly once")
        val noPatrol = heroState(920_082)
        noPatrol.absDay = 3; Family.chooseStance(noPatrol, "warm")
        check(Heroes.parentRemark(noPatrol, Family.MOM) == null,
            "family: no patrol last night, no remark — the " +
                "opinions are earned")
        val lone = heroState(920_083)
        lone.life["heroLastPatrol"] = lone.absDay - 1
        check(Heroes.parentRemark(lone, Family.MOM) == null,
            "family: before the family even arrives, no " +
                "remark can land")
        check(Phone.HERO in Phone.TRIGGERS &&
            Phone.HERO_PARENT_LINES.size >= 4 &&
            Phone.MAX_TEXTS == 220,
            "phone: the HERO trigger joins the harvest, its " +
                "bank stands, and the inbox dial did not move " +
                "for the patrols (it stood at 160; wave 6's cast " +
                "forced 220 at v0.11.0d) — a patrol night earns " +
                "at most one parental text")
    }

    // ---------- the lived soak: three weeks of nights ----------
    run {
        val eng = Engine(920_090)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        Heroes.createHero(s, "The Snow Day", "weather")
        eng.player(s).location = "KidsPark"
        repeat(21 * 96) { eng.advanceTime(s) }
        val nights = s.life["heroPatrolNights"] ?: 0
        check(s.absDay >= 20 && nights in 1..6 &&
            (s.life["heroLastPatrol"] ?: -1) >= 0,
            "heroes: lived three weeks with the player parked " +
                "at the park — the patrol nights they stood " +
                "counted once each ($nights of 6), the " +
                "morning-after fact recorded, nothing crashed " +
                "and nobody was out past the sleep hour")
        check(Heroes.caperStage(s) >= 1,
            "heroes: the caper opened itself under the made " +
                "hero during the lived weeks")
    }

    // ---------- the release pin ----------
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
}
// ================= v0.10.0c: the school play =================
// Queue #10 item 3. Once a school year the Elementary mounts
// "The Mountain That Wouldn't" — an original production,
// cast deterministically from the town's real data (authored
// nerve, bee skill, chemistry with the director), rehearsed
// under agenda claims, and judged live on opening night.
// This section proves: the calendar, casting determinism
// and the player's gradient, the audition/crew/audience
// tracks, rehearsal claims + attendance bookkeeping,
// deference, the three verdicts' reachability, the poster
// record's integrity, the annual cycle + history, and save
// round-trips.
private fun sectionV0100c(root: String) {
    println("== v0.10.0c: the school play ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.10.0c"),
        "v0.10.0c: the README carries this build's changelog entry")
    val playSrc = File(root,
        "src/com/hunt3r/southparktown/Play.kt").readText()
    check(playSrc.contains("object Play"),
        "play: the module exists (Play.kt)")

    fun playState(seed: Int): GameState {
        val eng = Engine(seed.toLong())
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        return s
    }
    fun setDay(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    /** Put exactly [names] in the school room; everyone
     *  else is sent to the park, so presence reads are
     *  deterministic. */
    fun stageRoom(s: GameState, names: Collection<String>) {
        for ((_, a) in s.agents) {
            if (a.isPlayer) {
                a.location = "Elementary"; a.asleep = false
                a.waypoints.clear()
            } else if (a.name in names) {
                a.location = "Elementary"; a.asleep = false
                a.waypoints.clear()
            } else {
                a.location = "KidsPark"; a.asleep = false
                a.waypoints.clear()
            }
        }
        s.playerInside = true
    }

    // ---------- the play itself: original, whole ----------
    run {
        check(Play.TITLE == "The Mountain That Wouldn't" &&
            Play.ROLES.size == Play.ROLE_COUNT &&
            Play.ROLE_COUNT == 7,
            "play: one original production, seven named roles")
        check(Play.ROLES.map { it.id }.toSet().size == 7 &&
            Play.ROLES.all { r ->
                r.lines.size == 3 && r.lines.all { it.isNotBlank() } &&
                    r.blurb.isNotBlank() },
            "play: every role is distinct, with three authored " +
                "lines and a casting blurb")
        check(Play.DIRECTOR == "Victoria",
            "play: directed by Principal Victoria (authored " +
                "suitability: she presides over the bee and " +
                "the assemblies; Garrison keeps the lessons)")
        // the originality guard, in the Pocket Pals pattern:
        // no real musical's or episode's material anywhere
        // in the module's player-facing strings
        val corpus = StringBuilder()
        corpus.append(Play.TITLE).append(' ').append(Play.PREMISE)
        for (r in Play.ROLES) {
            corpus.append(' ').append(r.title).append(' ')
                .append(r.blurb)
            for (l in r.lines) corpus.append(' ').append(l)
        }
        for ((_, l) in Play.DELIVERIES) corpus.append(' ').append(l)
        for ((_, l) in Play.DUTIES) corpus.append(' ').append(l)
        val low = corpus.toString().lowercase()
        val denylist = listOf("hamilton", "wicked",
            "lion king", "high school musical", "mamma mia",
            "les miserables", "les misérables",
            "phantom of the opera", "hairspray", "grease",
            "west side story", "sound of music", "my fair lady",
            "oklahoma", "elementary school musical",
            "you're a good man", "defying gravity",
            "seasons of love", "memory", "all that jazz")
        check(denylist.none { low.contains(it) },
            "play: no real musical's or episode's material in " +
                "the title, premise, roles or lines — the " +
                "production is the town's own")
    }

    // ---------- the calendar ----------
    run {
        val sch = PlayCalendar.scheduleFor(2027)
        check(sch.announceDay == 18 && sch.auditionDay == 20 &&
            sch.rehearsalDays == listOf(21, 22, 25, 26) &&
            sch.openingDay == 29,
            "play: the 2027 production — poster Mon Oct 19, " +
                "auditions Wed Oct 21, rehearsals Oct 22/23/" +
                "26/27, opening Fri Oct 30 (got $sch)")
        var ok = true
        for (y in 2027..2046) {
            val sc = PlayCalendar.scheduleFor(y)
            if (!School.isSchoolDay(sc.announceDay)) ok = false
            if (sc.auditionDay <= sc.announceDay) ok = false
            if (sc.rehearsalDays.size != Play.REHEARSALS) ok = false
            if (sc.rehearsalDays.any { !School.isSchoolDay(it) })
                ok = false
            if (sc.rehearsalDays.zipWithNext()
                    .any { (a, b) -> b <= a }) ok = false
            if (sc.rehearsalDays.first() <= sc.auditionDay)
                ok = false
            if (Jobs.weekdayOf(sc.openingDay) != 5) ok = false
            if (sc.openingDay <= sc.rehearsalDays.last()) ok = false
            if (sc.openingDay - sc.announceDay !in 9..18) ok = false
        }
        check(ok, "play: two decades of productions keep the " +
            "shape — school-day poster/auditions, four school-" +
            "day rehearsals, a Friday opening, a ~2 week arc")
        // a save consulted in March joins NEXT year, with
        // no record of a production it never knew about
        val s = playState(1)
        setDay(s, 151)  // Mar 1, 2027
        check(Play.currentYear(s) == 2028 &&
            !Play.cycleLive(s) &&
            Play.allRecords(s).isEmpty(),
            "play: a pre-0.10.0c save in March joins the next " +
                "production year (2028) — no missed-play record")
        val s0 = playState(2)
        setDay(s0, 0)
        check(Play.currentYear(s0) == 2027,
            "play: a fresh save's first production is the " +
                "2027 school year's (fall 2026)")
    }

    // ---------- casting: determinism & the data ----------
    run {
        check(Play.STAGE_NERVE.keys ==
            CharacterSystem.CAST_KIDS,
            "play: the authored nerve table covers exactly " +
                "the kid cast")
        check(Rival.POOL.all {
                Play.stageNerve(it.name) == it.nerve },
            "play: the rival pool's eight keep their Rival " +
                "nerve exactly — one nerve table, two hats")
        val a = playState(3)
        val ra = Play.runCasting(a, 2027, null)
        val b = playState(4)
        val rb = Play.runCasting(b, 2027, null)
        check(ra.cast == rb.cast && ra.ensemble == rb.ensemble,
            "play: casting is deterministic — two fresh towns " +
                "cast the same show")
        check(ra.cast == mapOf(
                "mountain" to "Ike", "mayor" to "Wendy",
                "shovel" to "Kyle", "weather" to "Nathan",
                "road" to "Shelley", "plow" to "Tolkien",
                "goat" to "Kevin McCormick") &&
            ra.ensemble == listOf("Nichole", "Henrietta",
                "Cartman", "Michael"),
            "play: the 2027 cast, from the data — Ike the " +
                "Mountain (nerve 8, three lines, fearless), " +
                "Wendy the Mayor, Kyle the Kid With The " +
                "Shovel (got ${ra.cast})")
        check(ra.cast.values.toSet().size == 7 &&
            ra.ensemble.toSet().size == 4 &&
            ra.memberKids().toSet().size == 11 &&
            ra.memberKids().all {
                it in CharacterSystem.CAST_KIDS },
            "play: seven roles + four ensemble, eleven kids, " +
                "nobody double-cast")
        check(Play.passedOverKid(a, ra) == "Pete",
            "play: the closest kid who got nothing is " +
                "computed from the same scores (Pete, in 2027)")
        check((Play.castCoverage(a, ra) * 44).toInt() == 37,
            "play: the 2027 cast's seeded rehearsal coverage " +
                "is 37 of 44 member-sessions")
        // the player's gradient, judged by the same math
        val g0 = playState(5)
        check(Play.runCasting(g0, 2027, "bold").track ==
            "under" &&
            Play.runCasting(playState(6), 2027, "true").track ==
            "under",
            "play: a stranger's bold or true read earns the " +
                "understudy bench — a real outcome, not a " +
                "fail state")
        val g30 = playState(7)
        g30.friendship[Play.DIRECTOR] = 30
        val r30 = Play.runCasting(g30, 2027, "deadpan")
        check(r30.track == "ens" && r30.cast.size == 7,
            "play: a kid the director knows (friendship 30) " +
                "with a deadpan read makes the ensemble — " +
                "the gradient is real: stranger, ensemble, " +
                "named part")
        val g60 = playState(8)
        g60.friendship[Play.DIRECTOR] = 60
        val r60 = Play.runCasting(g60, 2027, "deadpan")
        check(r60.track == "cast" && r60.detail == "shovel" &&
            r60.cast["weather"] == "Kyle" &&
            Play.actorOf(r60, "shovel") == "You",
            "play: the director's kid (friendship 60, " +
                "deadpan) takes the heart role — the Kid " +
                "With The Shovel — and Kyle slides to the " +
                "Weather in the same greedy pass")
    }

    // ---------- the player's tracks ----------
    run {
        val sch = PlayCalendar.scheduleFor(2027)
        // AUDITION: the played read, judged
        val s = playState(11)
        setDay(s, sch.auditionDay); s.timeMin = 16 * 60
        check(Play.auditionOpen(s),
            "play: auditions open on the audition afternoon")
        val said = Play.chooseAudition(s, "bold")
        check(said != null && Play.playerTrack(s) == "under",
            "play: the audition runs casting with the player " +
                "in the pool — a fresh bold read lands the " +
                "understudy, and the text says what that is")
        check(Play.chooseAudition(s, "true") == null &&
            Play.chooseCrew(s, "sets") == null,
            "play: one track per kid — after choosing, the " +
                "audition verbs close")
        // CREW: its own track, casting still runs
        val sc = playState(12)
        setDay(sc, sch.auditionDay); sc.timeMin = 15 * 60 + 30
        val crewText = Play.chooseCrew(sc, "lights")
        val crec = Play.currentRecord(sc)!!
        check(crewText != null && crec.track == "crew" &&
            crec.detail == "lights" && crec.cast.size == 7,
            "play: joining crew still casts the whole show, " +
                "and your name goes on the crew line")
        // AUDIENCE: declared, and the show still happens
        val sa = playState(13)
        setDay(sa, sch.auditionDay); sa.timeMin = 16 * 60
        check(Play.chooseAudience(sa) != null &&
            Play.currentRecord(sa)?.track == "aud",
            "play: the audience track is a real declared " +
                "choice, recorded like any other")
        // closed doors: wrong day, wrong hour
        val sw = playState(14)
        setDay(sw, sch.auditionDay - 1); sw.timeMin = 16 * 60
        check(!Play.auditionOpen(sw) &&
            Play.chooseAudition(sw, "bold") == null,
            "play: no auditions before the day")
        setDay(sw, sch.auditionDay); sw.timeMin = 10 * 60
        check(!Play.auditionOpen(sw),
            "play: no auditions in the morning — 3 PM, " +
                "after class, like rehearsals")
        // the player who never comes: casting still runs
        // at the next rollover, without them
        val sn = playState(15)
        setDay(sn, sch.castDay)
        Play.dailyRollover(sn)
        val nrec = Play.currentRecord(sn)
        check(nrec != null && nrec.cast.size == 7 &&
            nrec.track.isEmpty(),
            "play: a player who never auditioned still gets " +
                "a show — cast by the morning-after rollover, " +
                "track honestly empty")
    }

    // ---------- rehearsals: claims + bookkeeping ----------
    run {
        val eng = Engine(16)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        val sch = PlayCalendar.scheduleFor(2027)
        s.friendship[Play.DIRECTOR] = 60
        setDay(s, sch.auditionDay); s.timeMin = 16 * 60
        Play.chooseAudition(s, "deadpan")   // the Shovel
        // the claim: a seeded attendee is at the school at
        // 4 PM on a rehearsal day, through the FULL stack
        setDay(s, sch.rehearsalDays[0]); s.timeMin = 16 * 60
        val rec = Play.currentRecord(s)!!
        val att = rec.memberKids().first {
            Play.npcAttends(2027, it, 0) }
        val blk = eng.effectiveAgendaBlock(s,
            s.agents[att]!!, 16 * 60)
        check(blk?.location == "Elementary" &&
            blk.activity.contains("Rehearsal"),
            "play: rehearsal afternoons claim the cast at " +
                "the Elementary (through the whole agenda " +
                "stack), 15:00–17:00")
        check(Play.gatheringBlock(s, Play.DIRECTOR, 16 * 60)
            ?.location == "Elementary",
            "play: the director is claimed at rehearsals too")
        val skipper = rec.memberKids().firstOrNull {
            !Play.npcAttends(2027, it, 0) }
        if (skipper != null) check(
            Play.gatheringBlock(s, skipper, 16 * 60) == null,
            "play: a cast member the seed kept home is not " +
                "claimed — rehearsal attendance is honest " +
                "per member per session")
        // attendance bookkeeping: one banked session a day,
        // friendship sprinkles to the room that was there
        val before = s.friendship[att] ?: 0
        check(Play.rehearsalOpen(s),
            "play: the player's rehearsal is open in the " +
                "window while they hold a part")
        val v = Play.attendRehearsal(s)
        check(v != null && v.contains("REHEARSAL 1"),
            "play: staying for rehearsal returns the " +
                "session's vignette")
        check(Play.currentRecord(s)?.attMask == 1 &&
            !Play.rehearsalOpen(s) &&
            Play.attendRehearsal(s) == null,
            "play: the session banks once (bitmask), and " +
                "the verb closes for the day")
        check((s.friendship[att] ?: 0) == before +
            Play.REHEARSAL_PAY,
            "play: the castmates in the room get the +1 " +
                "sprinkle — cheap-friendship discipline, " +
                "once per session")
        for (d in sch.rehearsalDays.drop(1)) {
            setDay(s, d); s.timeMin = 16 * 60
            Play.attendRehearsal(s)
        }
        check(Play.currentRecord(s)?.attMask == 15 &&
            Play.coverageOf(s, Play.currentRecord(s)!!,
                "You") == 1.0,
            "play: four attended sessions read as full " +
                "coverage for the night")
        // opening-night claim: cast families gather
        setDay(s, sch.openingDay); s.timeMin = 19 * 60
        val fam = Play.gatheringBlock(s, "Gerald", 19 * 60)
        check(fam?.location == "Elementary" &&
            fam.activity.contains("Opening night"),
            "play: opening night claims the cast's families " +
                "(Gerald comes to see Kyle and Ike) — the " +
                "audience is real households, not a crowd prop")
    }

    // ---------- deference ----------
    run {
        val s = playState(17)
        val sch = PlayCalendar.scheduleFor(2027)
        Play.runCasting(s, 2027, null)
        setDay(s, sch.openingDay); s.timeMin = 19 * 60
        stageRoom(s, Play.currentRecord(s)!!.memberKids() +
            Play.DIRECTOR)
        check(Play.finaleDue(s),
            "play: opening night presents at the school in " +
                "its house hours (a Bijou screening the same " +
                "Friday does not own the school's evening)")
        // a case climax due owns the night instead
        s.shenaniganId = Mystery.FINALE_ID
        for (c in Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES))
            s.mysteryClues.add(c.id)
        check(School.anyClimaxDueToday(s) &&
            !Play.nightCanHappen(s) && !Play.finaleDue(s),
            "play: with the pond case's climax due, the " +
                "night defers — the case owns the evening")
        s.arcChoice = "truth"
        check(Play.finaleDue(s),
            "play: the climax answered, the night is the " +
                "play's again")
        // wrong room, wrong hour: no set piece
        s.agents.values.first { it.isPlayer }
            .location = "KidsPark"
        check(!Play.finaleDue(s),
            "play: no set piece away from the school")
        stageRoom(s, Play.currentRecord(s)!!.memberKids())
        setDay(s, sch.openingDay); s.timeMin = 14 * 60
        check(!Play.finaleDue(s),
            "play: no set piece in the afternoon")
    }

    // ---------- the judge, pure ----------
    run {
        check(Play.verdictFor(1.0, 1.0, 1.0, false, 1.0) ==
            "triumph",
            "play: a perfect night reads TRIUMPH")
        check(Play.verdictFor(0.0, 0.0, 0.2, false, 0.0) ==
            "disaster",
            "play: an unprepared night reads BEAUTIFUL " +
                "DISASTER")
        check(Play.verdictFor(0.8, 0.3, 0.6, false, 0.5) ==
            "solid",
            "play: an honest middle night reads SOLID")
        check(Play.verdictFor(0.55, 0.3, 0.2, true, 0.6) ==
            "disaster",
            "play: a fumbled moment in a loving room is a " +
                "BEAUTIFUL DISASTER even at middling numbers " +
                "— the beloved route")
        check(Play.mishapFor(2027).isEmpty() &&
            Play.mishapFor(2028) == "shovel" &&
            Play.mishapFor(2031) == "goat",
            "play: the mishap seed — 2027 runs clean, 2028 " +
                "loses the shovel, 2031's goat wanders")
    }

    // ---------- opening night, played three ways ----------
    // TRIUMPH: the director's kid, fully rehearsed, a full
    // house, a cast whose bonds rehearsals grew.
    run {
        val s = playState(18)
        val sch = PlayCalendar.scheduleFor(2027)
        s.friendship[Play.DIRECTOR] = 60
        setDay(s, sch.auditionDay); s.timeMin = 16 * 60
        Play.chooseAudition(s, "deadpan")
        for (d in sch.rehearsalDays) {
            setDay(s, d); s.timeMin = 16 * 60
            Play.attendRehearsal(s)
        }
        var rec = Play.currentRecord(s)!!
        val members = rec.memberKids()
        for (i in members.indices)
            for (j in i + 1 until members.size)
                s.npcBonds[Threads.pairKey(members[i],
                    members[j])] = 6
        setDay(s, sch.openingDay); s.timeMin = 19 * 60
        stageRoom(s, members + Play.DIRECTOR + listOf(
            "Randy", "Sharon", "Gerald", "Sheila", "Liane",
            "Stephen", "Linda", "Stuart", "Carol", "Steve",
            "Laura", "Mr. Tweek", "Mrs. Tweek", "Marvin"))
        check(Play.finaleDue(s),
            "play: the triumph setup is due on opening night")
        val text = Play.playFinale(s, 1)  // 2027 is clean:
        // no mishap, and TRUE is the Shovel's fit
        rec = Play.currentRecord(s)!!
        check(text != null && rec.verdict == "triumph" &&
            rec.night == "played",
            "play: full preparation + grown chemistry + a " +
                "full house + a nailed moment = TRIUMPH " +
                "(got ${rec.verdict})")
        // the poster: one real photo record
        check(rec.posterId.isNotEmpty() &&
            s.photos.size == 1 &&
            s.photos[0].id == rec.posterId &&
            s.photos[0].caption.contains(Play.TITLE) &&
            s.photos[0].locId == "Elementary",
            "play: opening night mints ONE real cast photo " +
                "— composed by the photo system's own group " +
                "rules from the room, captioned with the " +
                "production, filed like any photo (the " +
                "darkroom can print it)")
        check(s.photos[0].figures.size in 2..4 &&
            s.photos[0].figures.all {
                it.name == "NewKid" ||
                    it.name in Play.crowdNow(s) },
            "play: the poster's figures are people who were " +
                "actually in the room")
        // the morning after: the review
        setDay(s, sch.openingDay + 1)
        Play.dailyRollover(s)
        rec = Play.currentRecord(s)!!
        check(rec.critic == "Jimmy" && rec.review.isNotEmpty() &&
            rec.review.contains("Jimmy") &&
            rec.review.contains("Mountain") &&
            s.townLog.any { it.contains("🎭") &&
                it.contains("TRIUMPH") },
            "play: the morning after, Jimmy (this year's " +
                "rotated critic) reviews it in fact-slot " +
                "lines, and the town log carries the verdict")
        val page = Play.pageLines(s)
        check(page.any { it.contains("VERDICT: TRIUMPH") } &&
            page.any { it.contains("THE REVIEW") } &&
            page.any { it.contains("posed finale") },
            "play: the 🎭 SCHOOL PLAY page keeps the " +
                "production whole — verdict, your part, the " +
                "review quoted, the poster noted")
        val beat = Play.phoneBeat(s)
        check(beat?.first == "Jimmy" && beat.second == "review",
            "play: the critic texts the review the morning " +
                "it lands")
    }
    // BEAUTIFUL DISASTER: a cast player who skipped every
    // rehearsal, a mishap year, a fumbled moment, a thin
    // house — found by search across production years.
    run {
        var found: String? = null
        for (y in 2027..2040) {
            if (Play.mishapFor(y).isEmpty()) continue
            val s = playState(100 + y)
            val schY = PlayCalendar.scheduleFor(y)
            s.friendship[Play.DIRECTOR] = 60
            Play.runCasting(s, y, "deadpan")
            val recY = Play.record(s, y) ?: continue
            if (recY.track != "cast" ||
                recY.detail != "shovel") continue
            setDay(s, schY.openingDay); s.timeMin = 19 * 60
            stageRoom(s, recY.memberKids() + Play.DIRECTOR)
            // skip every rehearsal (attMask stays 0) and
            // fumble the moment: BIG, when a mishap begs
            // a cover and the part begs TRUE
            if (!Play.finaleDue(s)) continue
            Play.playFinale(s, 0)
            val after = Play.record(s, y)!!
            if (after.verdict == "disaster") {
                found = "$y:${after.verdict}"; break
            }
        }
        check(found != null,
            "play: BEAUTIFUL DISASTER is reachable in real " +
                "play — a rehearsed-never cast member, a " +
                "mishap and a fumbled save (found $found)")
    }
    // SOLID: the audience track, an ordinary good night.
    run {
        val s = playState(19)
        val sch = PlayCalendar.scheduleFor(2027)
        setDay(s, sch.auditionDay); s.timeMin = 16 * 60
        Play.chooseAudience(s)
        setDay(s, sch.openingDay); s.timeMin = 19 * 60
        val rec = Play.currentRecord(s)!!
        stageRoom(s, rec.memberKids() + Play.DIRECTOR +
            listOf("Gerald", "Sheila", "Liane", "Stuart",
                "Carol"))
        check(Play.finaleDue(s), "play: an audience member " +
            "still gets the set piece — the night is " +
            "theirs to watch")
        Play.playFinale(s, 0)  // laugh first: a landed moment
        val after = Play.currentRecord(s)!!
        check(after.verdict == "solid" &&
            after.posterId.isNotEmpty(),
            "play: the audience night reads SOLID — the " +
                "cast's own coverage carries it, honestly " +
                "smaller without you in it (got " +
                "${after.verdict})")
        check(Play.trackSummary(after) ==
            "you were in the audience",
            "play: the Journal's summary of an audience " +
                "year says exactly that")
    }
    // The offstage wrap: the grace evenings pass unplayed.
    run {
        val s = playState(20)
        val sch = PlayCalendar.scheduleFor(2027)
        Play.runCasting(s, 2027, null)
        setDay(s, sch.openingDay + Play.GRACE_DAYS + 1)
        Play.dailyRollover(s)
        val rec = Play.currentRecord(s)!!
        check(rec.night == "offstage" &&
            rec.verdict.isNotEmpty() &&
            rec.posterId.isEmpty(),
            "play: unplayed past its grace evenings, the " +
                "show goes on without a set piece — judged " +
                "from the cast alone, and NO poster (nobody's " +
                "camera was there)")
        check(rec.review.isNotEmpty(),
            "play: even the offstage show gets its review " +
                "the next morning — the record is complete " +
                "either way")
    }

    // ---------- talk, threads, look, phone ----------
    run {
        val sch = PlayCalendar.scheduleFor(2027)
        val s = playState(21)
        setDay(s, sch.rehearsalDays[1]); s.timeMin = 16 * 60
        Play.runCasting(s, 2027, null)
        // the passed-over kid's ONE line
        val pete = Play.gossipLine(s, "Pete")
        check(pete != null &&
            pete.text.contains("best actor in") &&
            Play.gossipLine(s, "Pete") == null,
            "play: the passed-over kid gets one honest, " +
                "kind line — disappointed, never humiliated, " +
                "and only once")
        // a cast member mid-run quotes their real part
        var kyleLine: Line? = null
        for (d in sch.rehearsalDays) {
            setDay(s, d)
            kyleLine = Play.gossipLine(s, "Kyle")
            if (kyleLine != null) break
        }
        check(kyleLine?.text?.contains(
            "THE KID WITH THE SHOVEL") == true,
            "play: cast talk names the speaker's actual " +
                "role from the record")
        // Threads: "the play" is a follow-up topic now
        val mem = NpcMemory()
        mem.meets = 3
        mem.topics.add(Play.TOPIC)
        val fu = Threads.followUp(mem, Random(3))
        check(fu != null && fu.contains("the play"),
            "play: 'the play' is a Threads topic with its " +
                "own follow-ups")
        // Look: the poster, then the playbill after
        setDay(s, sch.announceDay + 1)
        check(Play.lookText(s, "Elementary")
            ?.contains("POSTER") == true &&
            Play.lookText(s, "KidsPark") == null,
            "play: Look at the Elementary carries the " +
                "poster during the announcement window, and " +
                "only there")
        // phone: the announcement + the cast list
        val sp = playState(22)
        setDay(sp, sch.announceDay)
        val ann = Play.phoneBeat(sp)
        check(ann?.first == "Victoria" &&
            ann.second == "announce" &&
            ann.third.contains(Play.TITLE),
            "play: announcement morning, the director " +
                "texts the production (fact-only)")
        setDay(sp, sch.castDay)
        Play.runCasting(sp, 2027, null)
        val castBeat = Play.phoneBeat(sp)
        check(castBeat?.second == "cast" &&
            castBeat.first == "Ike",
            "play: cast-list morning, the Mountain himself " +
                "texts it (Ike, three lines, already " +
                "memorized)")
        check(Phone.PLAY in Phone.TRIGGERS,
            "play: the phone has a PLAY trigger for the " +
                "production's texts")
    }

    // ---------- the annual cycle + history ----------
    run {
        val eng = Engine(23)
        val s = eng.newState()
        eng.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        val sch = PlayCalendar.scheduleFor(2027)
        // live the whole first production through the
        // engine's own clock, parked at home: announced,
        // cast by fallback, wrapped offstage, reviewed
        setDay(s, 0)
        repeat(45 * 96) { eng.advanceTime(s) }
        val rec = Play.record(s, 2027)
        check(rec != null && rec.night == "offstage" &&
            rec.review.isNotEmpty() &&
            (s.life["playAnn:2027"] ?: 0) == 1,
            "play: a lived 45 days runs the whole first " +
                "production on the engine's clock — poster, " +
                "fallback casting, offstage wrap, review — " +
                "with the player never leaving home")
        check(Play.currentYear(s) == 2027 &&
            Play.pageLines(s).any {
                it.contains("VERDICT") },
            "play: after the wrap the current page is the " +
                "finished production")
        // next year's cycle begins clean
        val sch2 = PlayCalendar.scheduleFor(2028)
        setDay(s, sch2.announceDay)
        check(Play.currentYear(s) == 2028 &&
            Play.phoneBeat(s)?.second == "announce",
            "play: the next school year mounts the next " +
                "production on schedule")
        val page = Play.pageLines(s)
        check(page.any { it.startsWith("📜 2027:") &&
            it.contains("Ike was the Mountain") },
            "play: past productions reduce to history " +
                "lines — year, verdict, the Mountain, " +
                "your part")
    }

    // ---------- save round-trip ----------
    run {
        val s = playState(24)
        val sch = PlayCalendar.scheduleFor(2027)
        s.friendship[Play.DIRECTOR] = 60
        setDay(s, sch.auditionDay); s.timeMin = 16 * 60
        Play.chooseAudition(s, "deadpan")
        setDay(s, sch.rehearsalDays[0]); s.timeMin = 16 * 60
        Play.attendRehearsal(s)
        setDay(s, sch.rehearsalDays[1]); s.timeMin = 16 * 60
        Play.attendRehearsal(s)
        val before = Play.currentRecord(s)
        val pageBefore = Play.pageLines(s)
        val back = decodeGameState(encodeGameState(s))
        check(Play.currentRecord(back) == before &&
            Play.pageLines(back) == pageBefore,
            "play: a mid-production save round-trips — " +
                "the record, your part and your rehearsal " +
                "bits intact, the page identical")
    }

    // ---------- wiring + release pins ----------
    run {
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        val actSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt")
            .readText()
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt")
            .readText()
        val talkSrc = File(root,
            "src/com/hunt3r/southparktown/TalkGate.kt")
            .readText()
        check(engSrc.contains("Play.gatheringBlock") &&
            engSrc.contains("Play.dailyRollover"),
            "play: Engine seats the agenda claim and the " +
                "morning rollover")
        check(actSrc.contains("maybeShowPlayFinale") &&
            actSrc.contains("Play.chooseAudition") &&
            actSrc.contains("Play.attendRehearsal"),
            "play: GameActivity presents opening night " +
                "from the safe-moment chain and rides the " +
                "board for auditions + rehearsals")
        check(journalSrc.contains("🎭 SCHOOL PLAY") &&
            journalSrc.contains("Play.pageLines"),
            "play: the Journal carries the 🎭 SCHOOL " +
                "PLAY page")
        check(talkSrc.contains("Play.gossipLine"),
            "play: TalkGate owes the play's lines")
        val ktCount = File(root,
            "src/com/hunt3r/southparktown").listFiles()
            ?.count { it.isFile && it.name.endsWith(".kt") }
            ?: -1
        check(ktCount == 137 && readme.contains(
            "105 Kotlin files"),
            "play: the tree is 105 Kotlin files — Play.kt at " +
                "v0.10.0c, GroupChats.kt at v0.10.0d, " +
                "Stand.kt at v0.10.0e, Mystery8.kt at " +
                "v0.10.0f, Sleepovers.kt at v0.11.0c, " +
                "CastDataWave6.kt at v0.11.0d (counted $ktCount)")
    }
    val manifestSrc = File(root,
        "AndroidManifest.xml").readText()
    check(manifestSrc.contains(
        "android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains(
            "android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
}

private fun sectionV0100d(root: String) {
// ================= v0.10.0d: group chats =================
// Queue #10 item 4. The phone learns to talk to more than
// one person at a time: a group is a THREAD KIND in the
// existing Phone store (same records, caps, unread rules,
// same morning harvest), with three earned rooms — your
// crew's chat (Crew's roster is the source), the family
// thread (the parents' second voice; the solo v0.10.0a
// threads stay), and the current production's cast-and-
// crew channel (Play's record is the source). Every
// reactive post keys off a recorded fact, replies never
// pay, and the cap math is re-derived: (70 cast + 2
// parents + 3 groups) x 2 = 150 <= MAX_TEXTS 160 — the
// dial does not move.
    println("== v0.10.0d: group chats ==")
    val memSnapshotD = NpcMemoryStore.serialize()
    val readmeD = File(root, "docs/CHANGELOG.md").readText()
    check(readmeD.contains("### v0.10.0d"),
        "v0.10.0d: the README carries this build's changelog entry")
    val gSrc = File(root,
        "src/com/hunt3r/southparktown/GroupChats.kt").readText()
    check(gSrc.contains("object GroupChats"),
        "groups: the module exists (GroupChats.kt)")
    val phoneSrcD = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    val actSrcD = File(root,
        "src/com/hunt3r/southparktown/PhoneActivity.kt").readText()
    check(phoneSrcD.contains("GroupChats.duePosts") &&
        actSrcD.contains("GroupChats.quickReply") &&
        actSrcD.contains("GroupChats.titleFor"),
        "groups: the harvest delivers due posts and the " +
            "phone renders + answers group threads")

    val engD = Engine(1_000_401)
    fun freshD(): GameState {
        val s = engD.newState()
        engD.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        return s
    }
    fun setDayD(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun morningD(s: GameState, absDay: Int) {
        setDayD(s, absDay); Phone.dailyRollover(s)
    }
    fun befriend(s: GameState, n: String) {
        // the invite gate reads friendship 30 (Friend
        // tier); once they're in, drop it back so the
        // solo HELLO roll stays quiet in these mornings
        s.friendship[n] = 30
        Crew.invite(s, n)
        s.friendship[n] = 10
    }
    fun gTexts(s: GameState, thread: String): List<PhoneText> =
        s.phoneTexts.filter { it.thread == thread }

    // ---------- the model: ids, triggers, cap math ----------
    run {
        check(GroupChats.GROUP_IDS == setOf("group:crew",
            "group:family", "group:play"),
            "groups: exactly three rooms — the crew, the " +
                "family, the production")
        check(GroupChats.GROUP_IDS.none { it in KID_ORDER } &&
            GroupChats.GROUP_IDS.none { it in Family.PARENTS },
            "groups: room ids collide with no person — a " +
                "thread is a person OR a room, never both")
        check(Phone.GROUP in Phone.TRIGGERS,
            "groups: the GROUP trigger is registered with " +
                "the phone's own trigger set")
        check((KID_ORDER.size + Family.PARENTS.size +
            GroupChats.GROUP_IDS.size) * 2 <= Phone.MAX_TEXTS &&
            Phone.MAX_TEXTS == 220,
            "groups: cap math re-derived — at the groups' ship " +
                "it read (70 cast + 2 parents + 3 groups) x 2 = " +
                "150 <= MAX_TEXTS 160 and the dial did not move; " +
                "at wave 6's 98 cast the same formula reads 206 " +
                "<= MAX_TEXTS 220")
        check(GroupChats.MAX_GROUP_PER_DAY == 2 &&
            GroupChats.MAX_GROUP_PER_DAY < Phone.MAX_NEW_PER_DAY,
            "groups: at most two group posts land in a " +
                "morning, inside the phone's own budget of four")
        val s = freshD()
        check(GroupChats.duePosts(s).isEmpty() &&
            !GroupChats.live(s, GroupChats.CREW_ID) &&
            !GroupChats.live(s, GroupChats.FAMILY_ID) &&
            !GroupChats.live(s, GroupChats.PLAY_ID),
            "groups: a fresh save has no rooms and no due " +
                "posts — existence is earned, never decorative")
        check(GroupChats.titleFor(s, GroupChats.CREW_ID)
            .contains("Crew") &&
            GroupChats.titleFor(s, GroupChats.FAMILY_ID)
            .contains("Family") &&
            GroupChats.titleFor(s, GroupChats.PLAY_ID)
            .contains(Play.TITLE),
            "groups: each room names itself (the play's " +
                "room carries the production's title)")
    }

    // ---------- decode: group + family identities survive ----------
    run {
        val cases = listOf(
            PhoneText("1", GroupChats.CREW_ID, "Stan",
                Phone.GROUP, 1, "k", "chat's open", false),
            PhoneText("2", GroupChats.FAMILY_ID, "Mom",
                Phone.GROUP, 1, "k", "family chat", false),
            PhoneText("3", GroupChats.PLAY_ID, "Victoria",
                Phone.GROUP, 1, "k", "places, everyone", false),
            PhoneText("4", GroupChats.PLAY_ID, "you",
                Phone.REPLY, 1, "k", "👍", true, "👍"),
            // the v0.10.0d decode fix: a parent's SOLO
            // thread is a legal thread (before this build
            // Family.MOM/DAD failed the cast-only identity
            // check and family texts vanished on reload)
            PhoneText("5", "Mom", "Mom", Phone.FAMILY, 1,
                "k", "dinner tonight, 6 sharp", false),
            PhoneText("6", "Dad", "Dad", Phone.FAMILY, 1,
                "k", "allowance is on the counter", false))
        for (t in cases) {
            check(PhoneText.fromMap(t.toMap()) == t,
                "groups: '${t.thread}'/'${t.sender}' " +
                    "round-trips the record decode whole")
        }
        val bogus = PhoneText("7", "group:mods", "Stan",
            Phone.GROUP, 1, "k", "a room that doesn't exist", false)
        check(PhoneText.fromMap(bogus.toMap()) == null,
            "groups: an unknown room id still decodes to " +
                "nothing — the identity set stays closed")
    }

    // ---------- the crew thread: a whole life ----------
    run {
        val s = freshD()
        var day = 40
        morningD(s, day)
        check(gTexts(s, GroupChats.CREW_ID).isEmpty(),
            "crew chat: no crew, no room — mornings pass " +
                "and nothing is invented")
        befriend(s, "Stan")
        morningD(s, ++day)
        val born = gTexts(s, GroupChats.CREW_ID)
        check(born.size == 1 && born[0].sender == "Stan" &&
            born[0].trigger == Phone.GROUP &&
            GroupChats.live(s, GroupChats.CREW_ID) &&
            GroupChats.membersOf(s, GroupChats.CREW_ID) ==
                listOf("Stan"),
            "crew chat: the room is born with the crew, " +
                "first member speaking, under the GROUP trigger")
        check(Phone.threads(s).any {
            it.name == GroupChats.CREW_ID && it.unread == 1 },
            "crew chat: the room lists in Messages with " +
                "the solo threads' unread discipline")
        befriend(s, "Kyle")
        morningD(s, ++day)
        val joinPost = gTexts(s, GroupChats.CREW_ID)
            .firstOrNull { it.absDay == day }
        check(joinPost != null && joinPost.sender == "Stan" &&
            joinPost.text.contains("Kyle"),
            "crew chat: a join is welcomed by a member who " +
                "was already in, naming the joiner")
        // ---- the shared facts: a photo, a contest, an outing ----
        // presence, in the record's own shape: mode "with"
        // and standing where the player stands
        val me = engD.player(s)
        me.location = "KidsPark"
        for (n in listOf("Stan", "Kyle")) {
            s.agents[n]!!.location = "KidsPark"
            s.lifeText["crew:mode:$n"] = "with"
        }
        val photo = PhotoRecord(
            id = "gcheck-photo-1", dayKey = s.todayKey,
            dateLabel = "2/10", timeMin = 15 * 60,
            locId = "KidsPark", inside = false,
            weatherId = "clear", appearance = emptyMap(),
            figures = listOf(
                PhotoFigure("NewKid", "player", "happy"),
                PhotoFigure("Stan", "posed", "happy"),
                PhotoFigure("Kyle", "posed", "happy")),
            absDay = s.absDay)
        s.photos.add(photo)
        Crew.onPhoto(s, photo)   // Photos' real funnel
        check(Crew.photosTogether(s, "Stan") == 1,
            "crew chat staging: the photo tally rose " +
                "through the photo funnel")
        s.lifeText["rival"] = "Cartman"
        s.life["rivalRevealedDay"] = 1
        Crew.onContest(s)        // Rival.recordResult's funnel
        check(Crew.contestsWitnessed(s) == 1,
            "crew chat staging: the witnessed tally rose " +
                "through the contest funnel")
        // the outing record, in Crew's own storage (the
        // arrival tick is Engine-time; the group layer's
        // contract is with the record's readers)
        s.life["crew:out:Stan"] = 1
        s.lifeText["crew:places:Stan"] = "StarksPond"
        morningD(s, ++day)
        var crewNow = gTexts(s, GroupChats.CREW_ID)
        val photoPost = crewNow.firstOrNull {
            it.absDay == day && it.text.contains(
                LOCATIONS["KidsPark"]!!.name) }
        val contestPost = crewNow.firstOrNull {
            it.absDay == day && it.text.contains(
                Rival.scoreLine(s)) }
        check(photoPost != null &&
            photoPost.sender in listOf("Stan", "Kyle"),
            "crew chat: the photo with two of them in " +
                "frame is posted by one of the framed, " +
                "citing the record's place")
        check(contestPost != null,
            "crew chat: the witnessed contest is posted " +
                "quoting the scoreboard's own line verbatim")
        morningD(s, ++day)
        crewNow = gTexts(s, GroupChats.CREW_ID)
        val outingPost = crewNow.firstOrNull {
            it.absDay == day && it.text.contains(
                LOCATIONS["StarksPond"]!!.name) }
        check(outingPost != null && outingPost.sender == "Stan",
            "crew chat: the outing lands the next morning " +
                "(the group ceiling paces the room), posted " +
                "by the one who went, citing the recorded place")
        // ---- leaving: noted once, by who's left ----
        Crew.leave(s, "Kyle")
        morningD(s, ++day)
        crewNow = gTexts(s, GroupChats.CREW_ID)
        val leavePost = crewNow.firstOrNull { it.absDay == day }
        check(leavePost != null && leavePost.sender == "Stan" &&
            leavePost.text.contains("Kyle"),
            "crew chat: a leaving is noted in one factual " +
                "line by a member who remains")
        val kylePostsAtLeave = crewNow.count {
            it.sender == "Kyle" }
        morningD(s, ++day); morningD(s, ++day)
        check(gTexts(s, GroupChats.CREW_ID).count {
            it.sender == "Kyle" } == kylePostsAtLeave,
            "crew chat: a leaver never posts again — the " +
                "room speaks only with who's in it")
        // ---- emptying: the door closes, the room archives ----
        Crew.leave(s, "Stan")
        morningD(s, ++day)
        crewNow = gTexts(s, GroupChats.CREW_ID)
        val byePost = crewNow.firstOrNull { it.absDay == day }
        check(byePost != null && byePost.sender == "Stan" &&
            !GroupChats.live(s, GroupChats.CREW_ID),
            "crew chat: the last leaver closes the door " +
                "with one line, and the room archives")
        val archivedCount = crewNow.size
        morningD(s, ++day); morningD(s, ++day)
        check(gTexts(s, GroupChats.CREW_ID).size ==
            archivedCount,
            "crew chat: an archived room takes no new " +
                "posts — the record stays, the chat rests")
    }

    // ---------- crew replies: members only, never pay ----------
    run {
        val s = freshD()
        var day = 60
        befriend(s, "Stan"); befriend(s, "Kyle")
        morningD(s, ++day)   // the room is born
        val friendsBefore = s.friendship.toMap()
        val coinsBefore = Minigames.capsuleCoins(s)
        var acks = 0
        for (i in 0..11) {
            setDayD(s, ++day)
            val r = GroupChats.quickReply(s,
                GroupChats.CREW_ID, Phone.QUICK_REPLIES[i % 3])
            check(!r.bonusApplied,
                "crew reply: a group reply NEVER pays " +
                    "friendship (reply $i)")
            if (r.ack != null) {
                acks++
                val ackText = gTexts(s, GroupChats.CREW_ID)
                    .lastOrNull { it.trigger == Phone.ACK }
                check(ackText != null &&
                    ackText.sender in listOf("Stan", "Kyle"),
                    "crew reply: reactions come only from " +
                        "members actually in the thread")
            }
        }
        check(acks > 0,
            "crew reply: the room answers (seeded reactions " +
                "landed across twelve replies)")
        check(s.friendship.toMap() == friendsBefore &&
            Minigames.capsuleCoins(s) == coinsBefore,
            "crew reply: twelve replies moved no " +
                "friendship and no coins — group discipline")
        check(NpcMemoryStore.getOrCreate("Stan").topics
            .contains("texting") ||
            NpcMemoryStore.getOrCreate("Kyle").topics
            .contains("texting"),
            "crew reply: a reaction plants the solo " +
                "pattern's 'texting' topic in the reactor")
        // a solo-thread reply to a parent is still refused
        // (v0.10.0a's receive-only family discipline)
        check(Phone.quickReply(s, "Mom", "👍") ==
            Phone.ReplyResult(false, null),
            "groups: the parents' SOLO threads stay " +
                "receive-only — replies moved to the room")
    }

    // ---------- archived rooms take a bubble, answer silence ----------
    run {
        val s = freshD()
        var day = 80
        befriend(s, "Stan")
        morningD(s, ++day)
        Crew.leave(s, "Stan")
        morningD(s, ++day)   // the goodbye lands; archived
        val before = gTexts(s, GroupChats.CREW_ID)
            .count { it.sender == "you" }
        repeat(3) {
            val r = GroupChats.quickReply(s,
                GroupChats.CREW_ID, "❤️")
            check(r.ack == null,
                "archived reply: nobody answers a room " +
                    "whose moment has passed")
        }
        check(gTexts(s, GroupChats.CREW_ID)
            .count { it.sender == "you" } == before + 3,
            "archived reply: your bubbles still land in " +
                "the record — the silence is the answer")
    }

    // ---------- the family thread: the second voice ----------
    run {
        val s = freshD()
        var day = 3
        setDayD(s, day)
        check(!GroupChats.live(s, GroupChats.FAMILY_ID),
            "family chat: no room before the family arrives")
        Family.chooseStance(s, "warm")
        morningD(s, ++day)
        val born = gTexts(s, GroupChats.FAMILY_ID)
        check(born.any { it.sender == "Mom" } &&
            GroupChats.membersOf(s, GroupChats.FAMILY_ID) ==
                listOf("Mom", "Dad") &&
            GroupChats.live(s, GroupChats.FAMILY_ID),
            "family chat: the room is born when the " +
                "family arrives — Mom opens it, both " +
                "parents are members")
        // dinner coordination, by the parent NOT on duty
        var dDay = day + 1
        while (true) {
            setDayD(s, dDay)
            if (Family.dinnerTonight(s)) break
            dDay++
        }
        Phone.dailyRollover(s)
        val duty = if (dDay % 2 == 0) "Mom" else "Dad"
        val dinPost = gTexts(s, GroupChats.FAMILY_ID)
            .firstOrNull { it.absDay == dDay }
        check(dinPost != null && dinPost.sender != duty &&
            dinPost.text.contains(Family.dishOf(dDay)),
            "family chat: tonight's dinner is coordinated " +
                "in the room by the parent who didn't send " +
                "the solo call, naming the real dish")
        // the morning after an attended dinner: the other
        // parent seconds it here (the record Family's own
        // wrap reads: famDinLast)
        s.life["famDinLast"] = dDay
        morningD(s, dDay + 1)
        val wrapPosts = gTexts(s, GroupChats.FAMILY_ID)
            .filter { it.absDay == dDay + 1 }
        val soloWrap = s.phoneTexts.firstOrNull {
            it.absDay == dDay + 1 &&
                it.trigger == Phone.FAMILY }
        check(wrapPosts.isNotEmpty(),
            "family chat: the morning after dinner, the " +
                "second voice lands in the room")
        if (soloWrap != null) check(
            wrapPosts.none { it.sender == soloWrap.sender },
            "family chat: the room's wrap voice is the " +
                "parent who did NOT solo-text it — the two " +
                "of them, accounted once each")
        // allowance morning: Dad seconds Mom's solo note
        val aDay = dDay + 4
        setDayD(s, aDay)
        s.life["famAllowanceDay"] = aDay
        Phone.dailyRollover(s)
        val allowPost = gTexts(s, GroupChats.FAMILY_ID)
            .firstOrNull { it.absDay == aDay &&
                it.sender == "Dad" && it.text.contains(
                    "${Family.ALLOWANCE_COINS} coins") }
        check(allowPost != null,
            "family chat: allowance morning is seconded " +
                "by Dad in the room, off Family's own stamp")
    }

    // ---------- the family thread: a missed dinner ----------
    run {
        val s = freshD()
        setDayD(s, 3)
        Family.chooseStance(s, "fine")
        morningD(s, 4)   // the room is born
        var dDay = 5
        while (true) {
            setDayD(s, dDay)
            if (Family.dinnerTonight(s)) break
            dDay++
        }
        s.life["famDinMissed"] = dDay   // Family's own record
        morningD(s, dDay + 1)
        val posts = gTexts(s, GroupChats.FAMILY_ID)
            .filter { it.absDay == dDay + 1 }
        check(posts.any { it.text.contains("fridge") },
            "family chat: a missed dinner gets the " +
                "fridge-plate line in the room too, from " +
                "the parent who didn't solo-text it")
    }

    // ---------- the play thread: casting to the review ----------
    run {
        val s = freshD()
        val sched = PlayCalendar.scheduleFor(2027)
        setDayD(s, sched.castDay)
        val rec = Play.runCasting(s, 2027, null)
        check(rec.cast.isNotEmpty() &&
            GroupChats.membersOf(s, GroupChats.PLAY_ID) ==
                rec.memberKids() + Play.DIRECTOR &&
            GroupChats.live(s, GroupChats.PLAY_ID),
            "play chat: the room's members are the " +
                "record's cast + ensemble + the director")
        morningD(s, sched.castDay + 1)
        val castPost = gTexts(s, GroupChats.PLAY_ID)
            .firstOrNull { it.absDay == sched.castDay + 1 }
        check(castPost != null &&
            castPost.sender in GroupChats.membersOf(s,
                GroupChats.PLAY_ID) &&
            castPost.text.contains(Play.TITLE),
            "play chat: the cast-list morning opens the " +
                "room, from a member, naming the production")
        morningD(s, sched.rehearsalDays[0] + 1)
        // (for the 2027 schedule rehearsals[0] IS the
        // cast day, so this post shares the cast morning —
        // find it by its session count, not by day order)
        val rehPost = gTexts(s, GroupChats.PLAY_ID)
            .firstOrNull {
                it.absDay == sched.rehearsalDays[0] + 1 &&
                    it.text.contains(
                        "of ${Play.REHEARSALS}") }
        check(rehPost != null,
            "play chat: the morning after rehearsal one, " +
                "the room counts the session (1 of " +
                "${Play.REHEARSALS})")
        morningD(s, sched.openingDay)
        val openPost = gTexts(s, GroupChats.PLAY_ID)
            .firstOrNull { it.absDay == sched.openingDay }
        check(openPost != null &&
            openPost.sender == Play.DIRECTOR,
            "play chat: opening morning, the director " +
                "calls places in the room")
        setDayD(s, sched.openingDay + Play.GRACE_DAYS + 1)
        Play.dailyRollover(s)   // the offstage wrap
        Phone.dailyRollover(s)
        val wrapped = Play.currentRecord(s)!!
        val verdictPost = gTexts(s, GroupChats.PLAY_ID)
            .firstOrNull {
                it.absDay == sched.openingDay +
                    Play.GRACE_DAYS + 1 }
        check(wrapped.verdict.isNotEmpty() &&
            verdictPost != null && verdictPost.text.contains(
                Play.verdictWord(wrapped.verdict)),
            "play chat: the morning after the night, the " +
                "room quotes the verdict the record holds")
        morningD(s, sched.openingDay + Play.GRACE_DAYS + 2)
        // (that morning's Play rollover wrote the review)
        setDayD(s, sched.openingDay + Play.GRACE_DAYS + 2)
        Play.dailyRollover(s)
        morningD(s, sched.openingDay + Play.GRACE_DAYS + 3)
        check(!GroupChats.live(s, GroupChats.PLAY_ID) &&
            GroupChats.duePosts(s).none {
                it.thread == GroupChats.PLAY_ID },
            "play chat: after the review morning the room " +
                "archives — history stays, posts stop")
    }

    // ---------- fact discipline: silence without facts ----------
    run {
        val s = freshD()
        var day = 100
        befriend(s, "Stan"); befriend(s, "Kyle")
        morningD(s, ++day)   // born; snapshots in sync
        // no photo, no outing, no contest, no rival: the
        // ONLY crew post that may be due is presence banter
        val due = GroupChats.duePosts(s)
            .filter { it.thread == GroupChats.CREW_ID }
        check(due.all { it.text in GroupChats.CREW_BANTER_LINES },
            "fact audit: with no recorded shared event, " +
                "the room can only banter — every reactive " +
                "template stays silent without its fact")
        // determinism: the same facts derive the same posts
        val s2 = freshD()
        befriend(s2, "Stan"); befriend(s2, "Kyle")
        morningD(s2, day)   // the same history: born + synced
        setDayD(s, day + 1); setDayD(s2, day + 1)
        check(GroupChats.duePosts(s2).map {
            it.thread to it.text } ==
            GroupChats.duePosts(s).map {
                it.thread to it.text },
            "fact audit: derivation is deterministic — " +
                "same facts, same morning, same posts")
    }

    // ---------- banter honesty + spoiler hygiene ----------
    run {
        val claimWords = listOf("yesterday", "won", "photo",
            "scoreboard", "contest", "outing", "beat",
            "solved", "chapter")
        for (line in GroupChats.CREW_BANTER_LINES) {
            val low = line.lowercase()
            check(claimWords.none { it in low } &&
                line.none { it.isDigit() },
                "banter audit: a presence line claims no " +
                    "event (\"$line\")")
            check(LOCATIONS.values.none {
                it.name in line },
                "banter audit: a presence line names no " +
                    "place (\"$line\")")
        }
        val deny = listOf("sleepwalk", "foil", "confiscat",
            "cameo", "strongbox", "communal", "dissolv",
            "redact", "owes you", "professor chaos",
            "alibi", "charter", "lease")
        val banks = listOf(GroupChats.CREW_BORN_LINES,
            GroupChats.CREW_JOIN_LINES,
            GroupChats.CREW_LEAVE_LINES,
            GroupChats.CREW_LEAVE_LAST_LINES,
            GroupChats.CREW_PHOTO_LINES,
            GroupChats.CREW_CONTEST_LINES,
            GroupChats.CREW_OUTING_LINES,
            GroupChats.CREW_BANTER_LINES,
            GroupChats.FAM_BORN_LINES,
            GroupChats.FAM_DINNER_LINES,
            GroupChats.FAM_AFTER_ATTENDED_LINES,
            GroupChats.FAM_AFTER_MISSED_LINES,
            GroupChats.FAM_ALLOWANCE_LINES,
            GroupChats.PLAY_CAST_MEMBER_LINES,
            GroupChats.PLAY_CAST_DIRECTOR_LINES,
            GroupChats.PLAY_REH_ATTENDED_LINES,
            GroupChats.PLAY_REH_MISSED_LINES,
            GroupChats.PLAY_REH_NEUTRAL_LINES,
            GroupChats.PLAY_OPENING_LINES,
            GroupChats.PLAY_VERDICT_LINES) +
            GroupChats.GROUP_ACK_LINES.values.toList()
        for (bank in banks) for (line in bank) {
            val low = line.lowercase()
            for (bad in deny) check(bad !in low,
                "groups hygiene: no group bank leaks \"$bad\"")
        }
    }

    // ---------- harvest discipline: budget, ceiling, the wall ----------
    run {
        val s = freshD()
        val sched = PlayCalendar.scheduleFor(2027)
        setDayD(s, sched.castDay)
        Play.runCasting(s, 2027, null)
        Family.chooseStance(s, "warm")
        befriend(s, "Stan")
        // three rooms are all due on ONE morning
        morningD(s, sched.castDay + 1)
        val dayOne = s.phoneTexts.filter {
            it.absDay == sched.castDay + 1 }
        check(dayOne.count { it.trigger == Phone.GROUP } ==
            GroupChats.MAX_GROUP_PER_DAY,
            "harvest: three rooms due, two posts land — " +
                "the group ceiling holds inside the budget")
        check(dayOne.size <= Phone.MAX_NEW_PER_DAY,
            "harvest: group posts spend the phone's own " +
                "daily budget, never beside it")
        morningD(s, sched.castDay + 2)
        morningD(s, sched.castDay + 3)
        check(gTexts(s, GroupChats.PLAY_ID).isNotEmpty() &&
            gTexts(s, GroupChats.CREW_ID).isNotEmpty() &&
            gTexts(s, GroupChats.FAMILY_ID).isNotEmpty(),
            "harvest: the deferred room lands within a " +
                "morning or two, whole — a fact waits, " +
                "stamped only when it lands")
        // the unread wall stops the room like everyone else
        val s2 = freshD()
        befriend(s2, "Stan")
        repeat(Phone.MAX_UNREAD) {
            Phone.appendText(s2, "Stan", "Stan",
                Phone.HELLO, "filler $it")
        }
        morningD(s2, 50)
        check(gTexts(s2, GroupChats.CREW_ID).isEmpty(),
            "harvest: a full inbox (30 unread) silences " +
                "group posts exactly like solo ones")
    }

    // ---------- caps + the whole save round-trips ----------
    run {
        val s = freshD()
        var day = 120
        befriend(s, "Stan"); befriend(s, "Kyle")
        morningD(s, ++day)
        Family.chooseStance(s, "warm")
        morningD(s, ++day)
        // a solo family text rides the same doc (the
        // decode regression, end to end)
        Phone.appendText(s, "Mom", "Mom", Phone.FAMILY,
            "dinner tonight, 6 sharp")
        val groupCount = s.phoneTexts.count {
            it.thread in GroupChats.GROUP_IDS }
        check(groupCount >= 2,
            "round-trip staging: crew + family rooms " +
                "both hold texts ($groupCount)")
        val back = decodeGameState(encodeGameState(s))
        check(back.phoneTexts == s.phoneTexts,
            "round-trip: every text — group rooms and " +
                "the parents' solo threads alike — survives " +
                "the save whole")
        // per-thread caps bind rooms like anyone
        val s3 = freshD()
        befriend(s3, "Stan")
        repeat(Phone.MAX_PER_THREAD + 5) {
            Phone.appendText(s3, GroupChats.CREW_ID, "Stan",
                Phone.GROUP, "old news $it")
        }
        Phone.enforceCaps(s3)
        check(gTexts(s3, GroupChats.CREW_ID).size <=
            Phone.MAX_PER_THREAD,
            "caps: a room sheds to MAX_PER_THREAD like " +
                "any thread in the store")
    }

    val manifestD = File(root, "AndroidManifest.xml").readText()
    check(manifestD.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestD.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
    NpcMemoryStore.deserialize(memSnapshotD)
}

private fun sectionV0100e(root: String) {
// ================= v0.10.0e: your stand =================
// Queue #10 item 5. A kid business, run honestly: a
// one-time City Hall permit plus a kit buys a pitch at
// one of four real outdoor spots; stock comes from the
// town's real shops at the pantry's real prices
// (Fair.BOOTH is the price list) and lives in the crate,
// never in your pockets; you price inside a stated band;
// perishables spoil on stated shelf lives INTO the
// books; the stand sells ONLY while staffed — you
// standing at it, or a crewmate who walked the real Walk
// route under the crew's occupied rules, at a stated
// efficiency, for friendship. Customers are the
// townsfolk physically present. The books are derived
// from the recorded transactions (bought == sold +
// spoiled + on hand), the rival's crew reviews the
// stand off those books after five staffed days, and an
// honestly-good review lifts traffic for a stated
// window. All state rides life/lifeText — no new save
// keys; a pre-0.10.0e save simply has no stand.
    println("== v0.10.0e: your stand ==")
    val memSnapshotE2 = NpcMemoryStore.serialize()
    val readmeE2 = File(root, "docs/CHANGELOG.md").readText()
    val tuning = File(root, "docs/TUNING.md").readText()
    check(readmeE2.contains("### v0.10.0e"),
        "v0.10.0e: the README carries this build's changelog entry")
    val standSrc = File(root,
        "src/com/hunt3r/southparktown/Stand.kt").readText()
    check(standSrc.contains("object Stand"),
        "stand: the module exists (Stand.kt)")
    val engSrcE2 = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(engSrcE2.contains("Stand.gatheringBlock") &&
        engSrcE2.contains("Stand.tick(state)") &&
        engSrcE2.contains("Stand.dailyRollover"),
        "stand: Engine seats the agenda claim, the " +
            "selling tick and the morning wrap")
    val actSrcE2 = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    val viewSrcE2 = File(root,
        "src/com/hunt3r/southparktown/GameView.kt").readText()
    val journalSrcE2 = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val threadsSrcE2 = File(root,
        "src/com/hunt3r/southparktown/Threads.kt").readText()
    check(actSrcE2.contains("standDialog()") &&
        viewSrcE2.contains("Stand.locOf") &&
        viewSrcE2.contains("\"stand\""),
        "stand: the pitch is drawn and tappable — the " +
            "stand where it's set up, a chalk pitch at " +
            "the other permitted spots")
    check(journalSrcE2.contains("💰 YOUR STAND") &&
        journalSrcE2.contains("Stand.pageLines"),
        "stand: the Journal carries the 💰 YOUR STAND page")
    check(threadsSrcE2.contains("\"your stand\"") &&
        Stand.TOPIC == "your stand",
        "stand: the review leaves a Threads topic behind")

    val engE2 = Engine(1_000_501)
    fun freshE2(): GameState {
        val s = engE2.newState()
        engE2.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        return s
    }
    fun setDayE2(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun placeE2(s: GameState, name: String, loc: String) {
        val a = s.agents[name] ?: return
        a.location = loc; a.destination = loc
        a.waypoints.clear(); a.asleep = false
    }
    fun placePlayerE2(s: GameState, loc: String) {
        val me = s.agents.values.first { it.isPlayer }
        me.location = loc; me.destination = loc
        me.waypoints.clear(); me.asleep = false
    }
    fun befriendE2(s: GameState, n: String) {
        s.friendship[n] = 30
        Crew.invite(s, n)
        s.friendship[n] = 10
    }
    // day 2 of the town is a Saturday — no school claims,
    // so staffing tests read the crew rules clean
    val day0 = 2

    // ---------- the model: pitches, stock, the band ----------
    run {
        check(Stand.STAND_LOCS == listOf("MainStreet",
            "KidsPark", "StarksPond", "BusStop") &&
            Stand.STAND_LOCS.all { it in LOCATIONS },
            "stand: four real pitches — the strip, the " +
                "park, the pond path, the bus stop")
        check(Stand.PERMIT_COST == 10 &&
            Stand.KIT_COST == 15 && Stand.MOVE_COST == 5,
            "stand: the stated money — permit 10, kit 15, " +
                "pitch fee 5, all booked as costs")
        for (def in Stand.STOCK) {
            check(itemById(def.itemId) != null &&
                Fair.boothPrice(def.itemId) == def.shopPrice,
                "stand: ${def.itemId} is a real item at " +
                    "the town's real pantry price " +
                    "(${def.shopPrice} 🪙, Fair.BOOTH's own)")
            check(def.shelfDays in 1..7 &&
                Stand.minPrice(def.itemId) == def.shopPrice &&
                Stand.maxPrice(def.itemId) ==
                    def.shopPrice * Stand.PRICE_MAX_MULT &&
                Stand.PRICE_MAX_MULT == 3,
                "stand: ${def.itemId} keeps ${def.shelfDays} " +
                    "days and prices inside the band — shop " +
                    "price to 3x, never below, never above")
        }
        check(tuning.contains("PERMIT_COST"),
            "stand: the tuning ledger names the dials")
    }

    // ---------- setup: the permit, the kit, the pitch ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        check(!Stand.hasStand(s) &&
            Stand.closedReason(s) == "No stand yet." &&
            Stand.pageLines(s).any {
                it.contains("City Hall permit") },
            "stand: a fresh save has no stand, says so " +
                "plainly, and the page explains the permit")
        val broke = Stand.setup(s, "MainStreet")
        check(!Stand.hasStand(s) && broke.contains("10 🪙"),
            "stand: no coins, no permit — and the refusal " +
                "names the price ($broke)")
        Minigames.awardCoins(s, 100)
        val badLoc = Stand.setup(s, "Elementary")
        check(!Stand.hasStand(s) &&
            Minigames.capsuleCoins(s) == 100,
            "stand: a schoolyard is not a pitch — refused, " +
                "unspent")
        val line = Stand.setup(s, "MainStreet")
        check(Stand.hasStand(s) &&
            Stand.locOf(s) == "MainStreet" &&
            Minigames.capsuleCoins(s) == 75 &&
            Stand.books(s).fees == 25 &&
            line.contains("Mayor"),
            "stand: permit + kit = 25 🪙, booked as fees, " +
                "the Mayor signed it ($line)")
        check(Stand.STOCK.all {
            Stand.priceOf(s, it.itemId) == it.shopPrice + 1 },
            "stand: opening prices are shop + 1 — a kid " +
                "markup, inside the band")
        val again = Stand.setup(s, "KidsPark")
        check(Stand.locOf(s) == "MainStreet" &&
            again.contains("already"),
            "stand: one stand, one pitch — setup twice " +
                "isn't a thing")
        val moved = Stand.move(s, "KidsPark")
        check(Stand.locOf(s) == "KidsPark" &&
            Minigames.capsuleCoins(s) == 70 &&
            Stand.books(s).fees == 30 &&
            moved.contains("pitch fee"),
            "stand: moving is allowed on stated terms — " +
                "5 🪙 pitch fee, booked ($moved)")
        check(Stand.move(s, "KidsPark").contains("already") &&
            Stand.move(s, "Mall").contains("No pitch"),
            "stand: the move refuses the same spot and " +
                "the unpermitted ones, plainly")
    }

    // ---------- prices: the band holds ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        Minigames.awardCoins(s, 100)
        Stand.setup(s, "MainStreet")
        check(Stand.setPrice(s, "lemonade", 1) &&
            Stand.priceOf(s, "lemonade") == 1,
            "stand: shop price itself is a legal price")
        check(Stand.setPrice(s, "lemonade", 3) &&
            Stand.priceOf(s, "lemonade") == 3,
            "stand: the band's ceiling (3x) is legal")
        check(!Stand.setPrice(s, "lemonade", 0) &&
            !Stand.setPrice(s, "lemonade", 4) &&
            Stand.priceOf(s, "lemonade") == 3,
            "stand: below shop and above the ceiling are " +
                "both refused — the price doesn't move")
        check(!Stand.setPrice(s, "kupa_coin", 2),
            "stand: what the stand doesn't stock has " +
                "no price")
        s.life["standPrice:lemonade"] = 99
        check(Stand.priceOf(s, "lemonade") == 3,
            "stand: even a tampered price reads clamped " +
                "to the band — the ceiling is structural")
    }

    // ---------- ordering: real shops, real prices, the crate ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        check(Stand.order(s, "lemonade", 4)
            .contains("No stand"),
            "stand: no stand, no stock")
        Minigames.awardCoins(s, 100)
        Stand.setup(s, "MainStreet")
        val before = Minigames.capsuleCoins(s)
        val line = Stand.order(s, "lemonade", 4)
        check(Stand.onHand(s, "lemonade") == 4 &&
            Minigames.capsuleCoins(s) == before - 4 &&
            Stand.books(s).stockCost == 4 &&
            Stand.books(s).bought["lemonade"] == 4 &&
            line.contains("Tweek Bros."),
            "stand: stock is bought from the named shop " +
                "at its real price, into the books ($line)")
        check(s.inventory["lemonade"] == null &&
            s.inventory["hot_chocolate"] == null &&
            s.inventory["cheesy_poof"] == null &&
            s.inventory["snack_cake"] == null,
            "stand: crate stock NEVER enters your " +
                "pockets — no laundering stock into gifts " +
                "or resale elsewhere")
        Stand.order(s, "cheesy_poof", 8)
        Stand.order(s, "cheesy_poof", 4)
        val capped = Stand.order(s, "cheesy_poof", 1)
        check(Stand.onHand(s, "cheesy_poof") == 12 &&
            capped.contains("12"),
            "stand: the shops' daily cap holds — 12 a " +
                "day, and the refusal says the number")
        setDayE2(s, day0 + 1)
        check(Stand.orderedToday(s, "cheesy_poof") == 0,
            "stand: the cap is a DAY's cap — tomorrow " +
                "the shops sell again")
    }

    // ---------- spoilage: written in, never vanished ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        Minigames.awardCoins(s, 100)
        Stand.setup(s, "MainStreet")
        Stand.order(s, "lemonade", 4)     // keeps 2 days
        Stand.order(s, "snack_cake", 4)   // keeps 6 days
        fun roll(d: Int) { setDayE2(s, d); Stand.dailyRollover(s) }
        roll(day0 + 1)
        check(Stand.books(s).totalSpoiled == 0 &&
            Stand.crateTotal(s) == 8,
            "spoilage: a day in, nothing has turned")
        roll(day0 + 3)
        var b = Stand.books(s)
        check(b.spoiled["lemonade"] == 4 &&
            Stand.onHand(s, "lemonade") == 0 &&
            Stand.onHand(s, "snack_cake") == 4 &&
            b.totalBought == b.totalSold + b.totalSpoiled +
                b.totalOnHand,
            "spoilage: past its 2 days the lemonade is " +
                "WRITTEN OFF in the books — the identity " +
                "bought == sold + spoiled + on hand holds")
        roll(day0 + 7)
        b = Stand.books(s)
        check(b.spoiled["snack_cake"] == 4 &&
            b.spoilValue == 4 * 1 + 4 * 2 &&
            b.totalBought == b.totalSpoiled &&
            Stand.crateTotal(s) == 0,
            "spoilage: the cakes turn on day 7 (shelf 6), " +
                "the write-off is valued at cost — the " +
                "stand CAN lose money and the books show it")
        check(Stand.pageLines(s).any {
            it.contains("written off") },
            "spoilage: the page shows the write-off " +
                "line, not a rug")
    }

    // ---------- the purchase model: every factor reads real state ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        Minigames.awardCoins(s, 100)
        Stand.setup(s, "MainStreet")
        Stand.order(s, "lemonade", 6)
        Stand.order(s, "hot_chocolate", 6)
        s.weatherId = "sunny"   // October: season FALL
        fun chance(npc: String, item: String,
                   crew: Boolean = false) =
            Stand.purchaseChance(s, npc, item, crew)
        // price: fair sells, gouging mostly doesn't
        Stand.setPrice(s, "lemonade", 1)
        val atShop = chance("Stan", "lemonade")
        Stand.setPrice(s, "lemonade", 2)
        val at2x = chance("Stan", "lemonade")
        Stand.setPrice(s, "lemonade", 3)
        val at3x = chance("Stan", "lemonade")
        check(atShop > at2x && at2x > at3x && at3x > 0,
            "model: the dearer the lemonade, the fewer " +
                "buy — strictly, at every step of the band")
        check(kotlin.math.abs(Stand.priceFactor(1.0) -
            1.0) < 1e-9 &&
            kotlin.math.abs(Stand.priceFactor(2.0) -
                0.62) < 1e-9 &&
            kotlin.math.abs(Stand.priceFactor(3.0) -
                0.24) < 1e-9,
            "model: the price factor is the stated curve " +
                "— 1.0 at shop, 0.62 at 2x, 0.24 at the " +
                "3x ceiling")
        // weather/season fit: cold drinks on bright days,
        // hot chocolate in the cold
        Stand.setPrice(s, "lemonade", 2)
        Stand.setPrice(s, "hot_chocolate", 2)
        val lemSun = chance("Kyle", "lemonade")
        s.weatherId = "light_snow"
        val lemSnow = chance("Kyle", "lemonade")
        val chocSnow = chance("Kyle", "hot_chocolate")
        s.weatherId = "sunny"; s.gameMonth = 7
        val chocSunSummer = chance("Kyle", "hot_chocolate")
        check(lemSun > lemSnow && chocSnow > chocSunSummer,
            "model: lemonade sells on a bright day and " +
                "sags in the snow; hot chocolate is the " +
                "snow-day drink and sags in high summer")
        // their authored loves (the gift read, exactly)
        check(Stand.loves(s, "Butters", "lemonade") &&
            Stand.loves(s, "Stan", "lemonade") &&
            !Stand.loves(s, "Kyle", "lemonade") &&
            Stand.loves(s, "Kyle", "hot_chocolate"),
            "model: loves are the items' own authored " +
                "lists — the same read gifts are judged by")
        s.weatherId = "sunny"
        check(chance("Butters", "lemonade") >
            chance("Kyle", "lemonade"),
            "model: a person who loves the item buys " +
                "more readily than one who doesn't")
        check(Stand.pickItemFor(s, "Butters") == "lemonade",
            "model: on a sunny day Butters reaches for " +
                "the lemonade he loves")
        s.weatherId = "light_snow"
        check(Stand.pickItemFor(s, "Butters") ==
            "hot_chocolate",
            "model: in the snow even Butters reaches " +
                "for the hot chocolate — fit beats habit")
        // friendship: friends buy from friends
        s.weatherId = "sunny"; s.gameMonth = 10
        s.friendship["Craig"] = 0
        val cold = chance("Craig", "lemonade")
        s.friendship["Craig"] = 100
        check(chance("Craig", "lemonade") > cold,
            "model: a close friend buys more readily " +
                "than a stranger at the same stand")
        // crew efficiency: a stated fraction of you
        val mine = chance("Craig", "lemonade", false)
        val theirs = chance("Craig", "lemonade", true)
        check(kotlin.math.abs(theirs -
            mine * Stand.CREW_EFFICIENCY) < 1e-9 &&
            Stand.CREW_EFFICIENCY == 0.7,
            "model: a crewmate sells at exactly the " +
                "stated 0.7 of the player")
    }

    // ---------- selling: presence is the claim ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        Minigames.awardCoins(s, 200)
        Stand.setup(s, "MainStreet")
        Stand.order(s, "lemonade", 12)
        Stand.setPrice(s, "lemonade", 2)
        s.weatherId = "sunny"; s.gameMonth = 7
        s.timeMin = 600
        // nobody present but you: no conjured crowds.
        // v0.15.0g staging: MainStreet HAS residents now
        // (CastHomes — ten townsfolk's home anchor is the
        // street itself, and they spawn there honestly);
        // this beat is about conjuring, so the staging
        // sends the residents to the pond explicitly —
        // the pitch is empty because the test emptied it,
        // not because the town is empty
        placePlayerE2(s, "MainStreet")
        for ((n, a) in s.agents) {
            if (!a.isPlayer && a.location == "MainStreet") {
                a.location = "StarksPond"
                a.destination = "StarksPond"
                a.waypoints.clear()
            }
        }
        Stand.openStand(s, null)
        repeat(10) { Stand.tick(s) }
        check(Stand.books(s).totalSold == 0,
            "selling: you alone at the pitch sell " +
                "nothing — customers are never conjured")
        // a real crowd, really present
        val crowd = listOf("Stan", "Kyle", "Butters",
            "Wendy", "Craig", "Clyde")
        crowd.forEach { placeE2(s, it, "MainStreet") }
        val coinsBefore = Minigames.capsuleCoins(s)
        for (t in 0 until 40) {
            s.timeMin = 600 + t * 15
            Stand.tick(s)
        }
        val b = Stand.books(s)
        check(b.totalSold >= 3 &&
            b.takings == b.totalSold * 2 &&
            Minigames.capsuleCoins(s) ==
                coinsBefore + b.takings &&
            b.totalBought == b.totalSold + b.totalSpoiled +
                b.totalOnHand,
            "selling: real people bought at the set " +
                "price — takings are sold x price to the " +
                "coin, and the crate identity holds " +
                "(sold ${b.totalSold})")
        // walk away and it sells nothing, plainly
        placePlayerE2(s, "KidsPark")
        val soldAtWalk = Stand.books(s).totalSold
        for (t in 0 until 10) {
            s.timeMin = 700 + t * 15
            Stand.tick(s)
        }
        check(Stand.books(s).totalSold == soldAtWalk &&
            Stand.staffedBy(s) == null &&
            Stand.closedReason(s).contains("sells nothing"),
            "selling: the moment you walk away the " +
                "stand stops selling — and says so")
        // one customer, all afternoon: the daily cap holds
        val s2 = freshE2(); setDayE2(s2, day0)
        Minigames.awardCoins(s2, 200)
        Stand.setup(s2, "KidsPark")
        Stand.order(s2, "lemonade", 12)
        s2.weatherId = "sunny"; s2.gameMonth = 7
        placePlayerE2(s2, "KidsPark")
        placeE2(s2, "Stan", "KidsPark")
        s2.timeMin = 600
        Stand.openStand(s2, null)
        for (t in 0 until 40) {
            s2.timeMin = 600 + t * 15
            Stand.tick(s2)
        }
        val b2 = Stand.books(s2)
        check(b2.totalSold in 1..Stand.BUY_CAP_DAY,
            "selling: one regular all afternoon buys " +
                "at most the stated ${Stand.BUY_CAP_DAY} " +
                "a day (sold ${b2.totalSold}) — thirst " +
                "has a cap")
    }

    // ---------- crew staffing: a rendezvous, with occupied rules ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        s.shenaniganId = null   // a calm town: the stack
            // read below is the stand claim's alone
        Minigames.awardCoins(s, 200)
        Stand.setup(s, "MainStreet")
        Stand.order(s, "lemonade", 12)
        s.weatherId = "sunny"; s.gameMonth = 7
        val notCrew = Stand.openStand(s, "Kyle")
        check(!Stand.isOpen(s) &&
            notCrew.contains("isn't in your crew"),
            "staffing: only your crew can be assigned — " +
                "a stranger at the till isn't a thing")
        befriendE2(s, "Stan")
        placeE2(s, "Stan", "StarksPond")
        s.timeMin = 540
        val line = Stand.openStand(s, "Stan")
        check(Stand.isOpen(s) &&
            Stand.assignedStaff(s) == "Stan" &&
            line.contains("walking over"),
            "staffing: the assignment is a rendezvous — " +
                "$line")
        check(engE2.effectiveAgendaBlock(s,
            s.agents["Stan"]!!, 600)?.location ==
            "MainStreet" &&
            Stand.gatheringBlock(s, "Stan", 600)
                ?.location == "MainStreet" &&
            Stand.gatheringBlock(s, "Kyle", 600) == null,
            "staffing: the real agenda stack seats the " +
                "assigned crewmate at the pitch — and " +
                "nobody else is claimed")
        check(Stand.staffedBy(s) == null,
            "staffing: until the Walk-priced walk lands, " +
                "nobody is selling — travel time is real")
        val fromAbs = s.life["standStaffFrom"] ?: 0
        s.timeMin = fromAbs - day0 * 1440
        placeE2(s, "Stan", "MainStreet")
        check(Stand.staffedBy(s) == "Stan",
            "staffing: arrived, present, unclaimed — " +
                "Stan is working the stand")
        placeE2(s, "Kyle", "MainStreet")
        placeE2(s, "Butters", "MainStreet")
        val startMin = s.timeMin
        for (t in 0 until 30) {
            s.timeMin = startMin + t * 15
            Stand.tick(s)
        }
        val b = Stand.books(s)
        check(b.totalSold >= 1 &&
            b.totalBought == b.totalSold + b.totalSpoiled +
                b.totalOnHand,
            "staffing: the crewmate really sells, to " +
                "people really there (sold ${b.totalSold}" +
                ") — the books balance under crew hands too")
        // the occupied oracle wins, mid-shift
        s.agents["Stan"]!!.asleep = true
        check(Stand.staffedBy(s) == null &&
            Stand.gatheringBlock(s, "Stan", 600) == null,
            "staffing: asleep (or called away) ends the " +
                "shift — the claim releases him")
        val soldThen = Stand.books(s).totalSold
        repeat(5) { Stand.tick(s) }
        check(Stand.books(s).totalSold == soldThen,
            "staffing: no seller, no sales — even with " +
                "customers standing right there")
        s.agents["Stan"]!!.asleep = false
        // the wrap: the day counts, friendship is the pay
        val ptsBefore = s.friendship["Stan"] ?: 0
        setDayE2(s, day0 + 1); Stand.dailyRollover(s)
        check(Stand.staffedDays(s) == 1 &&
            (s.friendship["Stan"] ?: 0) ==
                ptsBefore + Stand.STAFF_FRIENDSHIP &&
            !Stand.isOpen(s),
            "staffing: the staffed day counts at the " +
                "wrap and pays its stated friendship — " +
                "no coin cut, ever — and the stand " +
                "closes with the night")
        // occupied at the ask: refused, plainly
        s.agents["Stan"]!!.asleep = true
        s.timeMin = 540
        val busyLine = Stand.openStand(s, "Stan")
        check(!Stand.isOpen(s) &&
            busyLine.contains("can't"),
            "staffing: an occupied crewmate can't be " +
                "assigned, and the refusal says why " +
                "($busyLine)")
    }

    // ---------- the books & the page ----------
    run {
        val s = freshE2(); setDayE2(s, day0)
        Minigames.awardCoins(s, 300)
        Stand.setup(s, "StarksPond")
        Stand.order(s, "snack_cake", 6)
        Stand.move(s, "BusStop")
        val b = Stand.books(s)
        check(b.fees == 30 && b.stockCost == 12 &&
            b.takings == 0 && b.profit == -42,
            "books: permit + kit + a move, stock at " +
                "cost, nothing sold — the stand is 42 🪙 " +
                "in the red and the books say so exactly")
        check(Stand.STOCK.all { def ->
            (b.bought[def.itemId] ?: 0) ==
                (b.sold[def.itemId] ?: 0) +
                (b.spoiled[def.itemId] ?: 0) +
                (b.onHand[def.itemId] ?: 0) },
            "books: the identity holds per item, not " +
                "just in total")
        val lines = Stand.pageLines(s)
        check(lines.first().contains("Bus Stop") &&
            lines.any { it.contains("THE BOOKS") } &&
            lines.any { it.contains("Loss so far: 42 🪙") } &&
            lines.any { it.contains("No review yet") },
            "books: the page shows the pitch, the loss " +
                "in plain words, and the review still " +
                "to earn")
    }

    // ---------- the rival crew reviews it ----------
    run {
        // an honest stand earns the good review
        val s = freshE2(); setDayE2(s, 10)
        Rival.playReveal(s, 1)
        check(RivalCrew.theirCrew(s).size == 3,
            "review: staging — the rival's crew exists " +
                "to write it")
        Minigames.awardCoins(s, 300)
        Stand.setup(s, "MainStreet")
        Stand.setPrice(s, "lemonade", 1)
        val crowd = listOf("Stan", "Kyle", "Butters",
            "Wendy", "Craig", "Clyde", "Jimmy", "Tolkien")
        placePlayerE2(s, "MainStreet")
        crowd.forEach { placeE2(s, it, "MainStreet") }
        for (d in 0 until 5) {
            val day = 10 + d
            setDayE2(s, day)
            s.weatherId = "sunny"
            Stand.order(s, "lemonade", 4)
            s.timeMin = 600
            Stand.openStand(s, null)
            for (t in 0 until 40) {
                s.timeMin = 600 + t * 15
                Stand.tick(s)
            }
            setDayE2(s, day + 1); Stand.dailyRollover(s)
        }
        check(Stand.staffedDays(s) == 5,
            "review: five staffed days, counted at " +
                "the wraps")
        val stats = Stand.reviewStats(s)
        check(stats.sellThroughPct >= 60 &&
            stats.spoilPct <= 25,
            "review: the staging really sold through " +
                "(${stats.sellThroughPct}% sold, " +
                "${stats.spoilPct}% spoiled)")
        check(Stand.reviewText(s) != null &&
            Stand.reviewText(s)!!.contains(
                "${stats.sellThroughPct}%") &&
            Stand.reviewText(s)!!.contains(
                "${stats.markupPct}%"),
            "review: the posted review quotes the " +
                "books' own numbers — fact-slots, not " +
                "vibes")
        check(s.lifeText["standVerdict"] == "GOOD" &&
            Stand.liftActive(s) &&
            Stand.trafficFactor(s) == Stand.REVIEW_LIFT,
            "review: an honestly-good review lifts " +
                "foot traffic x${Stand.REVIEW_LIFT} for " +
                "its stated ${Stand.REVIEW_LIFT_DAYS} days")
        check(RivalCrew.theirCrew(s).all { name ->
            (NpcMemoryStore.get(name)?.topics
                ?: emptyList()).contains(Stand.TOPIC) },
            "review: the topic is planted on the " +
                "reviewers — the town can talk about " +
                "the stand")
        val lifted = Stand.purchaseChance(s, "Stan",
            "lemonade", false)
        setDayE2(s, 10 + 5 + Stand.REVIEW_LIFT_DAYS + 2)
        val expired = Stand.purchaseChance(s, "Stan",
            "lemonade", false)
        check(!Stand.liftActive(s) &&
            Stand.trafficFactor(s) == 1.0 &&
            kotlin.math.abs(lifted / expired -
                Stand.REVIEW_LIFT) < 1e-9,
            "review: the lift runs its stated days " +
                "and ends exactly — no permanent tailwind")

        // a gouged, spoiled stand earns the cutting one
        val g = freshE2(); setDayE2(g, 10)
        Rival.playReveal(g, 1); RivalCrew.theirCrew(g)
        Minigames.awardCoins(g, 300)
        Stand.setup(g, "MainStreet")
        Stand.setPrice(g, "lemonade", 3)
        placePlayerE2(g, "MainStreet")
        placeE2(g, "Stan", "MainStreet")
        for (d in 0 until 5) {
            val day = 10 + d
            setDayE2(g, day)
            g.weatherId = "blizzard"
            if (d == 0) Stand.order(g, "lemonade", 12)
            g.timeMin = 600
            Stand.openStand(g, null)
            repeat(3) { Stand.tick(g) }
            setDayE2(g, day + 1); Stand.dailyRollover(g)
        }
        val gstats = Stand.reviewStats(g)
        check(Stand.staffedDays(g) == 5 &&
            g.lifeText["standVerdict"] == "ROUGH" &&
            !Stand.liftActive(g) &&
            Stand.trafficFactor(g) == 1.0,
            "review: overpriced stock rotting in a " +
                "blizzard earns the cutting review " +
                "(${gstats.sellThroughPct}% sold, " +
                "${gstats.spoilPct}% spoiled) — and NO " +
                "lift: tone never buys traffic, only " +
                "books do")
        check(Stand.reviewText(g)!!.contains(
            "${gstats.spoilPct}%"),
            "review: the rough review quotes the " +
                "spoilage it mocks")

        // not yet, and nobody to write it
        val n = freshE2(); setDayE2(n, 10)
        Rival.playReveal(n, 1); RivalCrew.theirCrew(n)
        Minigames.awardCoins(n, 50)
        Stand.setup(n, "MainStreet")
        n.life["standStaffedDays"] = 4
        check(!Stand.maybeReview(n) &&
            Stand.reviewText(n) == null,
            "review: four staffed days is not five — " +
                "the crew waits for the stated count")
        val u = freshE2(); setDayE2(u, 10)
        Minigames.awardCoins(u, 50)
        Stand.setup(u, "MainStreet")
        u.life["standStaffedDays"] = 9
        check(!Stand.maybeReview(u) &&
            Stand.reviewText(u) == null,
            "review: no revealed rivalry, no reviewers " +
                "— the stand waits for its critics to " +
                "exist")
    }

    // ---------- economy integrity: bounded, losable, loop-free ----------
    run {
        // A simulated season of good play: the best
        // pitch, ratio-2 prices, stock matched to demand,
        // staffed every open hour, customers rotating
        // through in two-hour windows the way real
        // agendas rotate a location's crowd. The bound
        // the ledger states: within 5x a paper-route
        // season (30 🪙/week x 13 = 390 🪙) — and, per
        // staffed hour, under a paper shift's pay.
        val s = freshE2(); setDayE2(s, 20)
        Minigames.awardCoins(s, 5000)
        Stand.setup(s, "MainStreet")
        Stand.setPrice(s, "lemonade", 2)
        Stand.setPrice(s, "hot_chocolate", 2)
        Stand.setPrice(s, "cheesy_poof", 4)
        Stand.setPrice(s, "snack_cake", 4)
        val crowd = listOf("Stan", "Kyle", "Butters",
            "Wendy", "Craig", "Clyde", "Jimmy", "Tolkien",
            "Bebe", "Red", "Heidi", "Nichole")
        placePlayerE2(s, "MainStreet")
        // v0.15.0g staging: the sim's whole model is the
        // rotating crowd below — MainStreet's own
        // residents (CastHomes) are parked at the pond
        // for the season so the measured trade is the
        // model's, exactly as it was when the whole town
        // spawned frozen at the Bus Stop
        for ((n, a) in s.agents) {
            if (!a.isPlayer && n !in crowd) {
                a.location = "StarksPond"
                a.destination = "StarksPond"
                a.waypoints.clear()
            }
        }
        for (dayOff in 0 until 91) {
            val day = 20 + dayOff
            setDayE2(s, day)
            s.weatherId = listOf("sunny", "cloudy",
                "light_snow")[dayOff % 3]
            Stand.order(s, "lemonade", 8)
            Stand.order(s, "hot_chocolate", 8)
            Stand.order(s, "cheesy_poof", 4)
            Stand.order(s, "snack_cake", 4)
            s.timeMin = 480
            Stand.openStand(s, null)
            for (tickIdx in 0 until 48) {
                s.timeMin = 480 + tickIdx * 15
                for ((i, name) in crowd.withIndex()) {
                    val a = s.agents[name] ?: continue
                    val winStart = (i % 6) * 8
                    if (tickIdx in winStart until
                        winStart + 8) {
                        a.location = "MainStreet"
                        a.destination = "MainStreet"
                        a.waypoints.clear(); a.asleep = false
                    } else if (a.location == "MainStreet") {
                        a.location = "KidsPark"
                        a.destination = "KidsPark"
                    }
                }
                Stand.tick(s)
            }
            setDayE2(s, day + 1); Stand.dailyRollover(s)
        }
        val b = Stand.books(s)
        println("stand season sim: sold=${b.totalSold} " +
            "spoiled=${b.totalSpoiled} " +
            "takings=${b.takings} profit=${b.profit}")
        check(b.totalSold > 400 && b.profit > 0,
            "economy: a season of good play really " +
                "trades and really earns (sold " +
                "${b.totalSold}, profit ${b.profit} 🪙)")
        check(b.profit <= 5 * 390,
            "economy: the season's take stays within " +
                "the stated bound — 5x a paper-route " +
                "season (390 🪙), for a stand staffed " +
                "twelve hours a day, every day (profit " +
                "${b.profit} 🪙)")
        check(b.totalBought == b.totalSold +
            b.totalSpoiled + b.totalOnHand,
            "economy: after 91 days of trade the crate " +
                "identity still holds to the unit")

        // gouging + hoarding loses, in the books
        val g = freshE2(); setDayE2(g, 20)
        Minigames.awardCoins(g, 5000)
        Stand.setup(g, "MainStreet")
        for (def in Stand.STOCK)
            Stand.setPrice(g, def.itemId,
                Stand.maxPrice(def.itemId))
        val few = listOf("Stan", "Kyle", "Craig", "Clyde")
        placePlayerE2(g, "MainStreet")
        few.forEach { placeE2(g, it, "MainStreet") }
        // v0.15.0g staging: same as the season sim —
        // demand here is the four named regulars and
        // nobody else; the street's residents are at
        // the pond (see above)
        for ((n, a) in g.agents) {
            if (!a.isPlayer && n !in few) {
                a.location = "StarksPond"
                a.destination = "StarksPond"
                a.waypoints.clear()
            }
        }
        for (dayOff in 0 until 30) {
            val day = 20 + dayOff
            setDayE2(g, day)
            g.weatherId = "blizzard"
            for (def in Stand.STOCK)
                Stand.order(g, def.itemId, Stand.ORDER_CAP)
            g.timeMin = 480
            Stand.openStand(g, null)
            for (tickIdx in 0 until 48) {
                g.timeMin = 480 + tickIdx * 15
                Stand.tick(g)
            }
            setDayE2(g, day + 1); Stand.dailyRollover(g)
        }
        val gb = Stand.books(g)
        check(gb.profit < 0 && gb.totalSpoiled > 0,
            "economy: max prices + max hoarding LOSES " +
                "money — demand is capped by who's " +
                "actually there, and the overflow spoils " +
                "into the books (profit ${gb.profit} 🪙, " +
                "spoiled ${gb.totalSpoiled})")
        check(g.inventory.keys.none {
            it in Stand.STOCK.map { d -> d.itemId } },
            "economy: thirty days of stocking never put " +
                "a single stock item in the player's " +
                "pockets — there is no resale loop " +
                "because there is no second door")
    }

    // ---------- saves: additive-only ----------
    run {
        val s = freshE2(); setDayE2(s, 30)
        Minigames.awardCoins(s, 300)
        Stand.setup(s, "KidsPark")
        Stand.order(s, "lemonade", 6)
        Stand.order(s, "snack_cake", 4)
        Stand.setPrice(s, "lemonade", 3)
        val back = decodeGameState(encodeGameState(s))
        check(Stand.hasStand(back) &&
            Stand.locOf(back) == "KidsPark" &&
            Stand.crate(back) == Stand.crate(s) &&
            Stand.books(back) == Stand.books(s) &&
            Stand.priceOf(back, "lemonade") == 3,
            "saves: the stand — pitch, crate batches, " +
                "prices, the whole books — round-trips " +
                "through the real save path")
        val legacy = decodeGameState(
            encodeGameState(freshE2()))
        check(!Stand.hasStand(legacy) &&
            Stand.pageLines(legacy).first() ==
                "💰 YOUR STAND" &&
            Stand.books(legacy).profit == 0,
            "saves: a pre-0.10.0e save simply has no " +
                "stand — the keys were never there and " +
                "nothing misses them")
    }

    // ---------- spoiler hygiene ----------
    run {
        val sealed = listOf("sleepwalking",
            "strongbox", "cameo", "two confessions",
            "communal paperwork", "Cornerstone")
        check(sealed.none {
            standSrc.contains(it, ignoreCase = true) },
            "spoilers: the stand's writing never touches " +
                "any case's solution — it sells snacks")
    }

    val ktCountE2 = File(root,
        "src/com/hunt3r/southparktown").listFiles()
        ?.count { it.isFile && it.name.endsWith(".kt") }
        ?: -1
    check(ktCountE2 == 137 && readmeE2.contains(
        "105 Kotlin files"),
        "stand: the tree is 108 Kotlin files — Stand.kt " +
            "at v0.10.0e, Mystery8.kt at v0.10.0f, Garden.kt at v0.11.0b, Sleepovers.kt at v0.11.0c, " +
            "CastDataWave6.kt at v0.11.0d (counted $ktCountE2)")
    val manifestE2 = File(root,
        "AndroidManifest.xml").readText()
    check(manifestE2.contains(
        "android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestE2.contains(
            "android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
    NpcMemoryStore.deserialize(memSnapshotE2)
}

/** v0.11.0a section, extracted like the others (64 KB rule):
 *  the town newspaper — Queue #11 item 1. */
private fun sectionV0110a(root: String) {
// ================= v0.11.0a: the town newspaper =================
// Queue #11 item 1. A weekly edition written entirely from
// the record: the paper's own weather log (proven against
// real Engine.onNewDay drives), publication exactly once
// per lived week, headline precedence (case > fair > play >
// vote > rival > sky > quiet; ties to the earliest day), the
// number audit (every integer in an edition traces to a
// record), spoiler hygiene behind the sealed wall, the caps,
// and the save round-trip. State rides life/lifeText only.
println("== v0.11.0a: the town newspaper — Queue #11 item 1 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.11.0a"),
        "paper: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "paper: the source tree and its description agree — " +
            "97 Kotlin files (Newspaper.kt joined at v0.11.0a, Garden.kt at v0.11.0b, Sleepovers.kt at v0.11.0c) " +
            "(counted $ktCount)")

    // ---------- wiring pins ----------
    val npSrc = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(!npSrc.contains("import android"),
        "paper: Newspaper.kt is pure Kotlin — no platform imports")
    check(npSrc.contains("HEADLINE_CAP") && npSrc.contains("SKY_LOG_CAP"),
        "paper: the dials are named constants (HEADLINE_CAP, SKY_LOG_CAP)")
    check(npSrc.contains("highest tier present wins"),
        "paper: the headline precedence is stated in the file header")
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    val hookAt = engSrc.indexOf("Newspaper.dailyRollover(state)")
    check(hookAt > engSrc.indexOf("Stand.dailyRollover(state)") &&
        hookAt < engSrc.indexOf("Phone.dailyRollover(state)") &&
        hookAt < engSrc.indexOf("Mystery6.noteNewDay6(state)"),
        "paper: Engine.onNewDay hooks the paper after the stand, " +
            "before Mystery6 and the phone")
    val jaSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jaSrc.contains("sectionTitle(\"📰 THE PAPER\")") &&
        jaSrc.contains("Newspaper.pageLines(state)"),
        "paper: the Journal renders the 📰 THE PAPER section " +
            "from Newspaper.pageLines")

    // ---------- helpers ----------
    fun setDayP(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun paperState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    fun skyEntry(s: GameState, absDay: Int, weather: String,
        special: String) {
        val cur = Newspaper.skyLog(s)
            .filter { it.absDay != absDay } +
            Newspaper.SkyEntry(absDay, weather, special)
        s.lifeText["paperSkyLog"] = cur.sortedBy { it.absDay }
            .joinToString(";") { "${it.absDay}:${it.weatherId}:${it.special}" }
    }
    fun skyWeek(s: GameState, week: Int,
        specials: Map<Int, String> = emptyMap()) {
        for (d in week * 7..week * 7 + 6)
            skyEntry(s, d, "sunny", specials[d] ?: SkyState.NONE)
    }
    fun votePipe(s: GameState, countedDay: Int, winnerVotes: Int,
        totalVotes: Int, margin: Int) {
        val q = Votes.QUESTIONS.first()
        s.lifeText["voteLastResult"] = listOf(q.id,
            q.options.first().id, margin, winnerVotes, totalVotes,
            countedDay, Jobs.weekIndex(countedDay), 1, 0,
            q.options[1].id).joinToString("|")
    }
    fun rivalWeek(s: GameState, week: Int) {
        s.life["rivalRevealedDay"] = 1
        s.life["rivalYou"] = 2; s.life["rivalThem"] = 1
        s.life["rivalDraws"] = 0
        s.lifeText["rivalLog"] =
            "${week * 7 + 1}|showdown|you|a clean hit at the park;" +
            "${week * 7 + 3}|race|them|by a nose on Main Street"
    }

    // ---------- legacy saves: no keys, a safe page ----------
    val (_, sLeg) = paperState(11021)
    check(sLeg.life.keys.none { it.startsWith("paper") } &&
        sLeg.lifeText.keys.none { it.startsWith("paper") },
        "paper: a legacy fresh state carries no paper keys")
    val legPage = Newspaper.pageLines(sLeg)
    check(legPage.first() == "📰 THE PAPER" && legPage.size == 3,
        "paper: before the first edition the page is the " +
            "masthead and the promise")

    // ---------- headline precedence ----------
    // quiet week: no records at all, no sky logged
    val (_, sQ) = paperState(11022)
    val edQ = Newspaper.composeEdition(sQ, 3)
    check(edQ.headline == "A QUIET WEEK IN SOUTH PARK",
        "paper headline: the fallback is honest — a quiet week")
    val townQ = edQ.lines
        .dropWhile { it != "🗞 TOWN NEWS" }.drop(1)
        .takeWhile { it != "🏅 SPORTS" }
    check(townQ == listOfNotNull(Birthdays.birthdaysLine(sQ, 3)) &&
        edQ.lines.any { it.contains("No contests on the record") } &&
        edQ.lines.any { it.contains("weather log begins with this edition") },
        "paper: sections with no record print one honest line, " +
            "never filler — and a record-free week's TOWN NEWS " +
            "carries only the week's birthdays, the roster's " +
            "standing record (v0.12.0c)")
    val secIdx = listOf("🗞 TOWN NEWS", "🏅 SPORTS",
        "💰 CLASSIFIEDS", "🌦 WEATHER").map { edQ.lines.indexOf(it) }
    check(secIdx.all { it >= 0 } && secIdx == secIdx.sorted(),
        "paper: the four sections are always present, in order")
    // the sky, with a tie inside the tier: earliest day wins
    val (_, sSky) = paperState(11023)
    skyWeek(sSky, 3, mapOf(24 to SkyState.AURORA,
        22 to SkyState.METEOR))
    val edSky = Newspaper.composeEdition(sSky, 3)
    check(edSky.headline.contains("METEOR") &&
        !edSky.headline.contains("AURORA"),
        "paper headline: the sky tier names the earliest special")
    // the rivalry beats the sky; its headline quotes the record
    val (_, sRiv) = paperState(11024)
    skyWeek(sRiv, 3, mapOf(22 to SkyState.METEOR))
    rivalWeek(sRiv, 3)
    val edRiv = Newspaper.composeEdition(sRiv, 3)
    check(edRiv.headline.startsWith("THE RIVALRY") &&
        edRiv.headline.contains(Rival.scoreLine(sRiv)),
        "paper headline: the rivalry beats the sky and quotes " +
            "Rival.scoreLine verbatim")
    check(edRiv.lines.any { it == "🏆 ${Rival.scoreLine(sRiv)}" },
        "paper sports: the score line runs verbatim in SPORTS too")
    // the vote beats the rivalry
    val (_, sVote) = paperState(11025)
    skyWeek(sVote, 3, mapOf(22 to SkyState.METEOR))
    rivalWeek(sVote, 3)
    votePipe(sVote, 25, 50, 90, 10)
    val winLabel = Votes.QUESTIONS.first().options.first().label
    check(Newspaper.composeEdition(sVote, 3).headline ==
        "${winLabel.uppercase()} WINS THE VOTE",
        "paper headline: the vote beats the rivalry and the sky")
    // opening night beats the vote — facts fabricated in the
    // play's own opening week, wherever the calendar puts it
    val (_, sPlay) = paperState(11026)
    val openDay = PlayCalendar.scheduleFor(2028).openingDay
    val wPlay = Jobs.weekIndex(openDay)
    sPlay.lifeText["playRec:2028"] = listOf("1", "lead:Stan", "",
        "cast", "lead", "", "0", "played", "triumph", "poster",
        "The Critic", "").joinToString("|")
    skyWeek(sPlay, wPlay, mapOf(openDay to SkyState.FIREWORKS))
    rivalWeek(sPlay, wPlay)
    votePipe(sPlay, openDay, 50, 90, 10)
    val edPlay = Newspaper.composeEdition(sPlay, wPlay)
    check(edPlay.headline.contains("TRIUMPH") &&
        edPlay.headline.contains(Play.TITLE.uppercase()),
        "paper headline: opening night beats the vote — the " +
            "opening's week derives from PlayCalendar's schedule " +
            "for the record's own year")
    // a case closing beats opening night
    sPlay.arc8RetiredDay = openDay
    check(Newspaper.composeEdition(sPlay, wPlay).headline ==
        "THE CASE CLOSES",
        "paper headline: a case closing beats opening night")
    // the fair beats the vote and the rivalry, in its own week
    val (_, sFair) = paperState(11027)
    val wFair = Jobs.weekIndex(FairCalendar.absDayOfOrdinal(
        FairCalendar.windowFor(2027).startOrd))
    sFair.fairs.add(FairRecord(year = 2027, shifted = false,
        sitter = "", wrapped = true, attended = true,
        playerPhoto = 1))
    rivalWeek(sFair, wFair)
    votePipe(sFair, wFair * 7 + 2, 50, 90, 10)
    check(Newspaper.composeEdition(sFair, wFair).headline ==
        "THE COUNTY FAIR PACKS UP",
        "paper headline: the fair beats the vote and the rivalry")
    sFair.arc7RetiredDay = wFair * 7 + 2
    check(Newspaper.composeEdition(sFair, wFair).headline ==
        "THE CASE CLOSES",
        "paper headline: a case closing beats the fair")

    // ---------- spoiler hygiene ----------
    val (_, sCase) = paperState(11028)
    sCase.arc5RetiredDay = 24
    skyWeek(sCase, 3)
    val edCase = Newspaper.composeEdition(sCase, 3)
    check(edCase.headline == "THE CASE CLOSES",
        "paper spoiler: the case tier fires on a RetiredDay stamp")
    val caseText = edCase.lines.joinToString("\n").lowercase()
    val sealed = listOf("sleepwalking", "strongbox", "cameo",
        "two confessions", "communal paperwork", "cornerstone")
    for (term in sealed) {
        check(term !in caseText,
            "paper spoiler: the edition never prints '$term'")
        check(term !in npSrc.lowercase(),
            "paper spoiler: Newspaper.kt's source carries no '$term'")
    }
    val caseLine = edCase.lines.first { it.contains("town case") }
    check(KID_ORDER.none { it in caseLine },
        "paper spoiler: the case line names no cast member")
    check(!caseLine.contains("branch") && !caseLine.contains("choice"),
        "paper spoiler: the case line carries no branch/choice words")

    // ---------- THE AUDIT: every number traces to a record ----------
    val (_, sA) = paperState(11029)
    val auditWeathers = listOf("sunny", "rain", "cloudy",
        "light_snow", "sunny", "fog", "wind")
    for ((i, w) in auditWeathers.withIndex())
        skyEntry(sA, 35 + i, w,
            if (i == 3) SkyState.METEOR else SkyState.NONE)
    votePipe(sA, 37, 137, 201, 73)
    sA.life["rivalRevealedDay"] = 1
    sA.life["rivalYou"] = 6; sA.life["rivalThem"] = 2
    sA.life["rivalDraws"] = 1
    sA.lifeText["rivalLog"] =
        "36|showdown|you|a clean hit at the fort;" +
        "39|race|them|by a whisker at the pond"
    sA.showdown["Stan"] = ShowdownRecord(11, 3)
    sA.showdown["Kyle"] = ShowdownRecord(5, 7)
    sA.life["rivalCrewPtsYou"] = 9; sA.life["rivalCrewPtsThem"] = 4
    sA.life["rivalCrewSeasonPlayed"] = 3
    Minigames.awardCoins(sA, 500)
    Stand.setup(sA, "MainStreet")
    check(Stand.setPrice(sA, "lemonade", 3) &&
        Stand.setPrice(sA, "hot_chocolate", 2) &&
        Stand.setPrice(sA, "cheesy_poof", 5) &&
        Stand.setPrice(sA, "snack_cake", 4),
        "paper audit: the stand's distinctive prices are set")
    val edA = Newspaper.composeEdition(sA, 5)
    val intsA = Regex("\\d+").findAll(edA.lines.joinToString("\n"))
        .map { it.value.toInt() }.toSet()
    val allowed = mutableSetOf(5, 137, 201, 73, 6, 2, 1, 16, 10,
        9, 4, 3, Stand.PERMIT_COST, Stand.KIT_COST)
    allowed += Regex("\\d+").findAll(
        Yearbook.labelOf(RivalCrew.seasonOf(sA)))
        .map { it.value.toInt() }
    for (d in 35..41) {
        val k = Commissions.keyForAbsDay(sA, d)
        allowed += k.substring(4, 6).toInt()
        allowed += k.substring(6, 8).toInt()
    }
    allowed += Stand.STOCK.map { it.shopPrice }
    allowed += Stand.STOCK.map { Stand.priceOf(sA, it.itemId) }
    check(intsA.all { it in allowed },
        "paper audit: every integer in the edition traces to a " +
            "record (strays: ${intsA - allowed})")
    check(137 in intsA && 201 in intsA && 73 in intsA &&
        16 in intsA && 15 in intsA,
        "paper audit: the distinctive record values really print")
    check(edA.headline.contains(winLabel.uppercase()),
        "paper audit: the headline's name comes from the " +
            "winning record")
    // classifieds: prices and only prices
    val clsLines = edA.lines.subList(
        edA.lines.indexOf("💰 CLASSIFIEDS"),
        edA.lines.indexOf("🌦 WEATHER"))
    val clsInts = clsLines.flatMap {
        Regex("\\d+").findAll(it).map { m -> m.value.toInt() } }.toSet()
    val priceAllowed = (Stand.STOCK.map { it.shopPrice } +
        Stand.STOCK.map { Stand.priceOf(sA, it.itemId) } +
        listOf(Stand.PERMIT_COST, Stand.KIT_COST)).toSet()
    check(clsInts.isNotEmpty() &&
        clsInts.all { it in priceAllowed },
        "paper classifieds: every price is a STOCK shop price, " +
            "a priceOf value, PERMIT_COST or KIT_COST (got $clsInts)")

    // ---------- weather log truth, through real rollovers ----------
    val (engW, sW) = paperState(11030)
    val lived = mutableListOf<Pair<Int, String>>()
    repeat(10) {
        lived += sW.absDay to sW.weatherId
        engW.onNewDay(sW)
    }
    val logW = Newspaper.skyLog(sW)
    check(logW.size == 10,
        "paper sky: ten rollovers logged ten nights (got ${logW.size})")
    for ((d, w) in lived) {
        val e = logW.firstOrNull { it.absDay == d }
        check(e != null && e.weatherId == w,
            "paper sky: day $d is logged with the weather it lived")
        if (e != null) {
            val key = Commissions.keyForAbsDay(sW, d)
            val sp = SkyState.dateSpecial(d, w,
                seasonFor(key.substring(4, 6).toInt()))
            check(e.special == sp,
                "paper sky: day $d's logged special is dateSpecial's")
        }
    }

    // ---------- publication: once per lived week ----------
    val (engP, sP) = paperState(11031)
    repeat(7) { engP.onNewDay(sP) }
    check(sP.life["paperWeek"] == 0 &&
        sP.lifeText["paperLatest"] != null,
        "paper: the first edition froze at the first week's turn")
    check(sP.events.count {
        it.startsWith("📰 The weekly paper is out:") } == 1,
        "paper: the ticker announced the first edition once")
    check(Newspaper.headlineHistory(sP).map { it.first } ==
        listOf(0), "paper: the headline history holds week 0")
    val frozen0 = sP.lifeText["paperLatest"]
    repeat(7) { engP.onNewDay(sP) }
    check(sP.life["paperWeek"] == 1 &&
        sP.lifeText["paperLatest"] != frozen0,
        "paper: the second week's turn froze a new edition")
    check(Newspaper.headlineHistory(sP).map { it.first } ==
        listOf(0, 1), "paper: the headline history holds both weeks")
    Newspaper.dailyRollover(sP); Newspaper.dailyRollover(sP)
    check(Newspaper.headlineHistory(sP).size == 2 &&
        sP.life["paperWeek"] == 1,
        "paper: repeated rollovers at a boundary publish " +
            "exactly once per week")
    val pageP = Newspaper.pageLines(sP)
    check(pageP.any { it == "🗞 PAST EDITIONS" } &&
        pageP.any { it.startsWith("Week 0:") },
        "paper: the page prints the latest edition, then past " +
            "editions as headline lines")

    // ---------- the lived-week guard ----------
    val (engG, sG) = paperState(11032)
    setDayP(sG, 6)
    engG.onNewDay(sG)   // absDay 7: a turn the save never lived
    check(sG.lifeText["paperLatest"] == null &&
        Newspaper.headlineHistory(sG).isEmpty(),
        "paper: a save teleported to the boundary publishes no " +
            "week it never lived")

    // ---------- caps over many weeks ----------
    val (engC, sC) = paperState(11033)
    repeat(70) { engC.onNewDay(sC) }
    check(Newspaper.headlineHistory(sC).size ==
        Newspaper.HEADLINE_CAP,
        "paper: the headline history caps at HEADLINE_CAP over " +
            "many weeks (got ${Newspaper.headlineHistory(sC).size})")
    check(Newspaper.skyLog(sC).size == Newspaper.SKY_LOG_CAP,
        "paper: the sky log caps at SKY_LOG_CAP " +
            "(got ${Newspaper.skyLog(sC).size})")
    check(sC.life["paperWeek"] == 9,
        "paper: ten lived weeks published through week 9 " +
            "(got ${sC.life["paperWeek"]})")

    // ---------- saves: the frozen edition round-trips ----------
    val backP = decodeGameState(encodeGameState(sP))
    check(backP.lifeText["paperLatest"] == sP.lifeText["paperLatest"] &&
        backP.lifeText["paperHeadlines"] ==
            sP.lifeText["paperHeadlines"] &&
        backP.lifeText["paperSkyLog"] == sP.lifeText["paperSkyLog"],
        "paper: the frozen edition, headlines and sky log " +
            "round-trip exactly")
    check(Newspaper.pageLines(backP) == Newspaper.pageLines(sP),
        "paper: the page reads identically after a round-trip")
}
}

private fun sectionV0110b(root: String) {
// ================= v0.11.0b: your garden =================
// Queue #11 item 2. Four beds at Your House, five crops
// whose seeds are real stock at stated prices, growth read
// off the recorded sky alone (rain / hand-watering / dry
// stall / summer scorch / blizzard / winter, driven through
// Garden.dailyRollover on scripted weather), weeds on their
// cadence cutting yield, harvest into real pantry items,
// the two tables (hosted + family) serving a homegrown
// dish, the stand's crate taking homegrown only against
// the garden's provenance count, the fair's fourth contest
// judged off the growth record, the economy bound simulated
// over a full season, and the save round-trip. All state
// rides life/lifeText — a legacy save has bare beds.
println("== v0.11.0b: your garden — Queue #11 item 2 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.11.0b"),
        "garden: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "garden: the source tree and its description agree — " +
            "97 Kotlin files (Garden.kt was v0.11.0b's addition; Sleepovers.kt is v0.11.0c's) " +
            "(counted $ktCount)")

    // ---------- wiring pins ----------
    val gSrc = File(root,
        "src/com/hunt3r/southparktown/Garden.kt").readText()
    check(!gSrc.contains("import android"),
        "garden: Garden.kt is pure Kotlin — no platform imports")
    check(gSrc.contains("WEED_EVERY_DAYS") &&
        gSrc.contains("SEED_SUPPLIER"),
        "garden: the dials are named constants (weeds, seeds)")
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    val gHook = engSrc.indexOf("Garden.dailyRollover(state)")
    check(gHook > engSrc.indexOf("Stand.dailyRollover(state)") &&
        gHook < engSrc.indexOf("Newspaper.dailyRollover(state)") &&
        gHook < engSrc.indexOf("Phone.dailyRollover(state)"),
        "garden: Engine.onNewDay hooks the garden after the " +
            "stand, before the paper and the phone — the beds " +
            "and the sky log read the same ended day")
    val jaSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jaSrc.contains("sectionTitle(\"🌱 YOUR GARDEN\")") &&
        jaSrc.contains("Garden.pageLines(state)"),
        "garden: the Journal renders the 🌱 YOUR GARDEN " +
            "section from Garden.pageLines")
    val gvSrc = File(root,
        "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("Hit(\"fixture\", \"garden\""),
        "garden: the plot is drawn at Your House with its " +
            "fixture hit (the established fixture pattern)")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("\"garden\" -> gardenDialog()"),
        "garden: fixture taps route to gardenDialog()")
    // spoiler hygiene: the garden's copy never touches a
    // sealed solution (structure words only, as ever)
    for (sealed in listOf("sleepwalk", "strongbox", "cameo")) {
        check(!gSrc.lowercase().contains(sealed),
            "garden: the module's writing stays clear of " +
                "sealed ground ($sealed)")
    }

    // ---------- helpers ----------
    fun setDayG(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun absOf(key: String): Int =
        FairCalendar.absDayOfOrdinal(ordinalOfKey(key))
    fun gardenState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    /** Live one day under a scripted sky: optional morning
     *  beats happen at s.absDay, then the rollover reads
     *  that day's staged weather as the ended day's. */
    fun liveDayG(s: GameState, weather: String,
                 waterFirst: Boolean = false) {
        if (waterFirst) Garden.water(s)
        val d = s.absDay
        s.weatherId = weather
        setDayG(s, d + 1)
        Garden.dailyRollover(s)
    }

    // ---------- the registry: crops, seeds, items ----------
    check(Garden.BEDS == 4 && Garden.CROPS.size == 5,
        "garden: four beds, five crops — the plot as built")
    for (crop in Garden.CROPS) {
        val item = itemById(crop.itemId)
        check(item != null && item.tier == "gift",
            "garden: ${crop.id} harvests into a real pantry " +
                "item under the gift discipline (${crop.itemId})")
        check(crop.seedPrice > 0 && crop.months.isNotEmpty() &&
            crop.growDays in 25..60 &&
            crop.seedSupplier == Garden.SEED_SUPPLIER,
            "garden: ${crop.id} seed is real stock — " +
                "${crop.seedPrice} 🪙 from ${crop.seedSupplier}, " +
                "window ${crop.windowLabel}, ${crop.growDays} days")
        check(Garden.cropById(crop.id) == crop &&
            Garden.cropForItem(crop.itemId) == crop,
            "garden: ${crop.id} resolves both ways")
    }
    check(Garden.CROPS.count { !it.tender } == 1 &&
        Garden.cropById("potato")?.tender == false,
        "garden: exactly one hardy crop — the potato, the " +
            "forgiving Colorado staple")
    check(Dinners.PANTRY_ITEMS.containsAll(Garden.PRODUCE_IDS),
        "garden: the hosted pantry serves every produce item")
    check(Stand.PRODUCE.map { it.itemId } ==
        Garden.PRODUCE_IDS &&
        Stand.STOCK.none { it.itemId in Garden.PRODUCE_IDS },
        "garden: the stand's produce defs are the garden's " +
            "crops at stated reference prices — and no shop " +
            "stock line sells produce")

    // ---------- legacy saves: bare beds, a safe page ----------
    val (_, sLeg) = gardenState(11041)
    Garden.dailyRollover(sLeg)
    check(sLeg.life.keys.none { it.startsWith("garden") } &&
        sLeg.lifeText.keys.none { it.startsWith("garden") },
        "garden: a bare-bed save grows no garden keys by " +
            "idling — pre-0.11.0b saves simply have bare beds")
    val legPage = Garden.pageLines(sLeg)
    check(legPage.first() == "🌱 YOUR GARDEN" &&
        legPage.size == 4,
        "garden: before anything is planted the page is " +
            "the masthead and the honest how-to")

    // ---------- planting: windows, coins, occupancy ----------
    val (_, sP) = gardenState(11042)
    setDayG(sP, absOf("20270401"))
    sP.inventory[Minigames.COIN_ITEM] = 10
    val aprCoins = Minigames.capsuleCoins(sP)
    val plantLine = Garden.plant(sP, 0, "potato")
    check(Garden.bed(sP, 0)?.cropId == "potato" &&
        Minigames.capsuleCoins(sP) ==
            aprCoins - Garden.cropById("potato")!!.seedPrice &&
        (sP.life["gardenSeedSpent"] ?: 0) ==
            Garden.cropById("potato")!!.seedPrice,
        "garden: planting buys the packet at the stated " +
            "price and stores the bed ($plantLine)")
    check(Garden.plant(sP, 0, "corn")
            .contains("already growing"),
        "garden: an occupied bed refuses a second crop")
    check(Garden.plant(sP, 1, "tomato")
            .contains("goes in May") &&
        Garden.bed(sP, 1) == null &&
        Minigames.capsuleCoins(sP) ==
            aprCoins - Garden.cropById("potato")!!.seedPrice,
        "garden: out-of-window planting is refused with " +
            "the window named, and no coin moves")
    sP.inventory.remove(Minigames.COIN_ITEM)
    check(Garden.plant(sP, 2, "corn").contains("aren't there") &&
        Garden.bed(sP, 2) == null,
        "garden: no coins, no seed — refused plainly")

    // ---------- growth reads the recorded sky ----------
    val (_, sG) = gardenState(11043)
    setDayG(sG, absOf("20270401"))
    sG.inventory[Minigames.COIN_ITEM] = 100
    Garden.plant(sG, 0, "potato")
    Garden.plant(sG, 1, "corn")
    liveDayG(sG, "sunny", waterFirst = true)
    check(Garden.bed(sG, 0)?.growth == 1 &&
        Garden.bed(sG, 0)?.wateredDays == 1 &&
        Garden.bed(sG, 0)?.dryStreak == 0,
        "garden: a hand-watered dry day grows the bed — " +
            "the WATER beat counts like rain")
    liveDayG(sG, "sunny")
    check(Garden.bed(sG, 0)?.growth == 1 &&
        Garden.bed(sG, 0)?.dryStreak == 1,
        "garden: an unwatered dry day stalls growth — " +
            "no loss, no progress, stated in the record")
    liveDayG(sG, "rain")
    check(Garden.bed(sG, 0)?.growth == 2 &&
        Garden.bed(sG, 0)?.wateredDays == 2 &&
        Garden.bedLine(sG, 0).contains("2/45"),
        "garden: a rain day waters for free, and the bed " +
            "line reads the count off the record")

    // scorch: a summer sun on an unwatered bed
    val (_, sS) = gardenState(11044)
    setDayG(sS, absOf("20270520"))
    sS.inventory[Minigames.COIN_ITEM] = 50
    Garden.plant(sS, 0, "corn")
    repeat(15) { liveDayG(sS, "sunny") }
    check(Garden.bed(sS, 0)?.growth == 0 &&
        Garden.bed(sS, 0)?.scorchDays == 3 &&
        Garden.bed(sS, 0)?.dryStreak == 15,
        "garden: fifteen dry days grow nothing; the three " +
            "that fell in summer (Jun 1–3) scorched the " +
            "unwatered bed (got scorch " +
            "${Garden.bed(sS, 0)?.scorchDays})")

    // frost: a blizzard kills the tender, spares the hardy;
    // a dead bed replants in the same beat
    val (_, sF) = gardenState(11045)
    setDayG(sF, absOf("20270401"))
    sF.inventory[Minigames.COIN_ITEM] = 100
    Garden.plant(sF, 0, "potato")
    repeat(30) { liveDayG(sF, "rain") }      // → May 1
    Garden.plant(sF, 1, "tomato")            // May window
    liveDayG(sF, "blizzard")
    check(Garden.bed(sF, 1)?.dead == true &&
        Garden.bed(sF, 1)?.deadWhy == "frost",
        "garden: the blizzard froze the tender tomato " +
            "where it stood — and the record says why")
    check(Garden.bed(sF, 0)?.dead == false &&
        (Garden.bed(sF, 0)?.growth ?: 0) >= 30,
        "garden: the potato, underground and hardy, " +
            "shrugged the same blizzard off")
    check(Garden.plant(sF, 1, "corn")
            .contains("seed in bed 2") &&
        Garden.bed(sF, 1)?.cropId == "corn" &&
        Garden.bed(sF, 1)?.dead == false,
        "garden: planting over a dead bed clears it in " +
            "the same beat")

    // winter: the turn takes every tender bed, ripe or
    // not; the hardy potato stands
    val (_, sW) = gardenState(11046)
    setDayG(sW, absOf("20270731"))
    sW.inventory[Minigames.COIN_ITEM] = 100
    Garden.plant(sW, 0, "corn")              // Jul window
    liveDayG(sW, "rain", waterFirst = true)  // → Aug 1
    Garden.plant(sW, 1, "potato")            // Aug window
    repeat(39) { liveDayG(sW, "rain", waterFirst = true) }
    check(Garden.bed(sW, 0)?.ripe == true,
        "garden: the tended corn ripened on its record " +
            "(40 watered days)")
    while (sW.absDay < absOf("20271201"))
        liveDayG(sW, "cloudy")
    check(Garden.bed(sW, 0)?.dead == true &&
        Garden.bed(sW, 0)?.deadWhy == "winter",
        "garden: a ripe tender crop left standing was " +
            "taken by winter's turn — nothing dies silently")
    check(Garden.bed(sW, 1) != null &&
        Garden.bed(sW, 1)?.dead == false,
        "garden: the hardy potato, planted in its fall " +
            "window, stands through winter's turn")

    // ---------- weeds & yield; the harvest ----------
    // neglect: rain grows it, nobody weeds, yield is cut
    val (_, sN) = gardenState(11047)
    setDayG(sN, absOf("20270501"))
    sN.inventory[Minigames.COIN_ITEM] = 50
    Garden.plant(sN, 0, "tomato")
    repeat(30) { liveDayG(sN, "rain") }
    check(Garden.bed(sN, 0)?.ripe == true &&
        Garden.weedLevel(sN, Garden.bed(sN, 0)!!) ==
            Garden.WEED_CAP,
        "garden: thirty unweeded days max the weeds — a " +
            "level a week, capped, as stated")
    check(Garden.harvest(sN, 0).contains("1 ×") &&
        (sN.inventory["tomato"] ?: 0) == 1,
        "garden: the neglected bed yields the floor — " +
            "base 4 less 3 weed levels = 1 tomato")
    // tended: weeded daily, the full yield, into the pantry
    val (_, sT) = gardenState(11048)
    setDayG(sT, absOf("20270501"))
    sT.inventory[Minigames.COIN_ITEM] = 50
    Garden.plant(sT, 0, "tomato")
    repeat(30) { Garden.clearWeeds(sT); liveDayG(sT, "rain") }
    check(Garden.harvest(sT, 0).contains("4 ×") &&
        (sT.inventory["tomato"] ?: 0) == 4 &&
        Garden.grownAvailable(sT, "tomato") == 4 &&
        (sT.life["gardenHarvest:tomato"] ?: 0) == 4 &&
        Garden.bed(sT, 0) == null,
        "garden: a tended bed yields its full count into " +
            "the real pantry, provenance and all, and the " +
            "bed is bare after")
    check(Garden.harvest(sT, 0).contains("bare dirt"),
        "garden: harvesting a bare bed says so")
    check(Garden.pageLines(sT).any {
        it.contains("Lifetime picked") },
        "garden: the page keeps the season's harvest record")

    // the fair pumpkin: judged off the growth record
    val (_, sPk) = gardenState(11049)
    setDayG(sPk, absOf("20270301"))
    sPk.inventory[Minigames.COIN_ITEM] = 100
    Garden.plant(sPk, 0, "pumpkin")
    repeat(55) { Garden.clearWeeds(sPk); liveDayG(sPk, "rain") }
    val ripeBed = Garden.bed(sPk, 0)
    check(ripeBed?.ripe == true &&
        Garden.pumpkinWeight(sPk, ripeBed!!) in 44..48,
        "garden: a perfect pumpkin — 55 grown, 55 watered, " +
            "weeds cleared — weighs in the mid-forties " +
            "(got ${Garden.pumpkinWeight(sPk, ripeBed!!)})")
    Garden.harvest(sPk, 0)
    val spec1 = Garden.fairSpecimen(sPk, sPk.gameYear)
    check(spec1 != null && spec1.growthDays == 55 &&
        spec1.wateredDays == 55 &&
        (sPk.inventory["pumpkin"] ?: 0) == 1,
        "garden: the season's biggest pumpkin is kept as " +
            "the fair specimen, with its record attached")
    val spec1w = spec1?.weight ?: -1
    // a lesser pumpkin (weed-choked) doesn't displace it:
    // the weight formula takes a tenth per weed level off
    // the same honest growth record
    setDayG(sPk, absOf("20270501"))
    Garden.plant(sPk, 0, "pumpkin")
    repeat(55) { liveDayG(sPk, "rain") }   // grows, unweeded
    val weedyBed = Garden.bed(sPk, 0)
    check(weedyBed?.ripe == true &&
        Garden.weedLevel(sPk, weedyBed!!) == Garden.WEED_CAP &&
        Garden.pumpkinWeight(sPk, weedyBed) < spec1w,
        "garden: a weed-choked pumpkin weighs honestly " +
            "less off the same 55 grown days (got " +
            "${Garden.pumpkinWeight(sPk, weedyBed!!)} lb " +
            "vs $spec1w)")
    Garden.harvest(sPk, 0)
    check(Garden.fairSpecimen(sPk, sPk.gameYear)?.weight ==
        spec1w,
        "garden: the porch keeps the bigger specimen — " +
            "the fair entry is the season's best, not its last")

    // ---------- the tables serve homegrown ----------
    // hosted: the spread serves (and consumes) the produce
    val (_, sH) = gardenState(11050)
    sH.absDay = 10
    sH.life["hostDay"] = 10
    sH.lifeText["hostHousehold"] = Dinners.HOUSEHOLDS[0].id
    sH.timeMin = 18 * 60
    sH.inventory["tomato"] = 2
    val hostDef = Dinners.HOUSEHOLDS[0]
    Dinners.judgeTalk(sH, hostDef.host)
    val serveLine = Dinners.lookText(sH, YOUR_HOUSE)
    check(serveLine != null && serveLine.contains("homegrown") &&
        sH.lifeText["hostServed"] == "tomato" &&
        (sH.inventory["tomato"] ?: 0) == 1,
        "garden: a hosted dinner serves the pantry's " +
            "produce as a homegrown dish — a fact line at " +
            "the table, one real item consumed")
    // family: the folks cook the garden when it offers
    val (_, sFam) = gardenState(11051)
    sFam.absDay = 3
    Family.chooseStance(sFam, "warm")
    var famDay = -1
    for (d in 3..24) {
        sFam.absDay = d
        if (Family.dinnerTonight(sFam)) { famDay = d; break }
    }
    sFam.timeMin = 18 * 60
    sFam.inventory["tomato"] = 1
    val famHit = Family.talkStepFor(sFam, Family.MOM)
        ?: Family.talkStepFor(sFam, Family.DAD)
    check(famDay > 0 && famHit != null &&
        famHit.text.contains("homegrown"),
        "garden: on a family-dinner night the dish names " +
            "the garden's produce (day $famDay)")
    if (famHit != null) {
        Family.judgeTalk(sFam, famHit.parent)
        check((sFam.inventory["tomato"] ?: 0) == 0 &&
            Family.dishTonight(sFam).contains("homegrown"),
            "garden: the family table SERVES it — the item " +
                "leaves the pantry, and the dish keeps its " +
                "name for the evening")
    }

    // ---------- the stand: provenance or nothing ----------
    val (_, sSt) = gardenState(11052)
    setDayG(sSt, absOf("20270501"))
    sSt.inventory[Minigames.COIN_ITEM] = 200
    sSt.inventory["tomato"] = 3      // found, not grown
    Stand.setup(sSt, "MainStreet")
    val refused = Stand.stockFromGarden(sSt, "tomato", 3)
    check(Stand.onHand(sSt, "tomato") == 0 &&
        refused.contains("didn't come from your garden"),
        "garden: the crate refuses produce the garden " +
            "didn't grow — found food is lunch, not stock")
    check(Stand.order(sSt, "tomato", 1).contains("GROW"),
        "garden: produce is never ordered — the shops " +
            "don't sell it; order() says so plainly")
    Garden.plant(sSt, 0, "tomato")
    repeat(30) { Garden.clearWeeds(sSt); liveDayG(sSt, "rain") }
    Garden.harvest(sSt, 0)           // +4 grown (7 held total)
    val moved = Stand.stockFromGarden(sSt, "tomato", 99)
    check(Stand.onHand(sSt, "tomato") == 4 &&
        (sSt.inventory["tomato"] ?: 0) == 3 &&
        Garden.grownAvailable(sSt, "tomato") == 0,
        "garden: the transfer moves exactly the grown " +
            "count — pack to crate, real items ($moved)")
    val books1 = Stand.books(sSt)
    check((books1.grown["tomato"] ?: 0) == 4 &&
        books1.totalBought + books1.totalGrown ==
            books1.totalSold + books1.totalSpoiled +
            books1.totalOnHand,
        "garden: the books keep the identity with the " +
            "grown column — bought + grown == sold + " +
            "spoiled + on hand")
    Stand.setPrice(sSt, "tomato", 3)
    check(Stand.priceOf(sSt, "tomato") == 3,
        "garden: produce prices inside the stand's band " +
            "against its reference (1 🪙 → up to 3)")
    Stand.setPrice(sSt, "tomato", 9)
    check(Stand.priceOf(sSt, "tomato") <=
        Stand.maxPrice("tomato"),
        "garden: the band clamps even a tampered ask")
    check(Stand.pickItemFor(sSt, "Butters") == "tomato",
        "garden: a stocked crate offers its produce to " +
            "the town like any stock")
    setDayG(sSt, sSt.absDay + 4)
    Stand.dailyRollover(sSt)
    val books2 = Stand.books(sSt)
    check((books2.spoiled["tomato"] ?: 0) == 4 &&
        books2.totalBought + books2.totalGrown ==
            books2.totalSold + books2.totalSpoiled +
            books2.totalOnHand,
        "garden: unsold produce spoils INTO the books on " +
            "its stated shelf life (3 days), identity intact")

    // ---------- the fair: the fourth contest ----------
    val (eFair, sFair) = gardenState(11053)
    val win = FairCalendar.windowFor(2027)
    setDayG(sFair, FairCalendar.absDayOfOrdinal(win.startOrd))
    Fair.dailyRollover(sFair)        // the record is born
    check(Fair.recordFor(sFair, 2027) != null,
        "garden: staging — the 2027 fair record stands")
    sFair.lifeText["gardenFair:2027"] = "44:55:52"
    val fairCoins = Minigames.capsuleCoins(sFair)
    setDayG(sFair, FairCalendar
        .absDayOfOrdinal(win.startOrd + Fair.DUNK_DAY))
    Fair.dailyRollover(sFair)        // the weigh-in judges
    val recF = Fair.recordFor(sFair, 2027)!!
    check(recF.producePlaces.size == 3 &&
        recF.playerProduce == 1 &&
        recF.producePlaces[0].detail.contains("44 lb") &&
        recF.producePlaces[0].detail.contains("52 watered"),
        "garden: the weigh-in judged the porch specimen " +
            "off its growth record — 44 lb, 52 watered days " +
            "beats the seeded field's best (44 lb × 100)")
    check(Minigames.capsuleCoins(sFair) ==
        fairCoins + Fair.PLACE_COINS[0] &&
        recF.blues() >= 1,
        "garden: a produce blue pays the fair's ordinary " +
            "prize and counts in blues() like any ribbon")
    // no garden, no entry — the table still stands
    val (_, sFair2) = gardenState(11054)
    setDayG(sFair2, FairCalendar.absDayOfOrdinal(win.startOrd))
    Fair.dailyRollover(sFair2)
    Fair.judgeProduce(sFair2, win)
    val recF2 = Fair.recordFor(sFair2, 2027)!!
    check(recF2.producePlaces.size == 3 &&
        recF2.playerProduce == 0,
        "garden: with no specimen the weigh-in is the " +
            "town's alone — no entry is invented")
    // a slept-through fair still weighs its pumpkins
    val (_, sFair3) = gardenState(11055)
    setDayG(sFair3, FairCalendar.absDayOfOrdinal(win.startOrd))
    Fair.dailyRollover(sFair3)
    sFair3.lifeText["gardenFair:2027"] = "30:55:40"
    setDayG(sFair3, FairCalendar
        .absDayOfOrdinal(win.endOrd + 2))
    Fair.dailyRollover(sFair3)        // the wrap
    val recF3 = Fair.recordFor(sFair3, 2027)!!
    check(recF3.wrapped && recF3.producePlaces.isNotEmpty() &&
        !recF3.missed,
        "garden: the wrap judges a skipped weigh-in off " +
            "the same record, and a pumpkin on the table " +
            "means you were there")
    // the sweep counts any three of the four blues now
    val sweepRec = FairRecord(2027, false, "Jimbo",
        playerPhoto = 1, playerFish = 1, playerProduce = 1)
    val (_, sSweep) = gardenState(11056)
    sSweep.fairs.add(sweepRec)
    check(sweepRec.blues() == 3 &&
        Fair.fairFeatEarned(sSweep,
            Fair.featById("fair_sweep")!!),
        "garden: Fair Sweep reads three blues at one " +
            "fair — photo, fishing and the produce table " +
            "earn it, as the feat now says")
    // legacy records read additively: no weigh-in keys,
    // no weigh-in — and the round-trip keeps the new ones
    val legacy = FairRecord.fromMap(mapOf(
        "year" to 2026, "sitter" to "Jimbo"))
    check(legacy != null && legacy.producePlaces.isEmpty() &&
        legacy.playerProduce == 0 && legacy.blues() == 0,
        "garden: a pre-0.11.0b fair record reads with an " +
            "empty weigh-in table — additive, as ever")

    // ---------- the economy bound: a simulated season ----------
    val (_, sE) = gardenState(11057)
    setDayG(sE, absOf("20270301"))
    sE.inventory[Minigames.COIN_ITEM] = 500
    var grossCeiling = 0
    var unitsPicked = 0
    val seasonEnd = absOf("20270930")
    while (sE.absDay <= seasonEnd) {
        for (i in 0 until Garden.BEDS) {
            val b = Garden.bed(sE, i)
            when {
                b != null && b.ripe && !b.dead -> {
                    val crop = Garden.cropById(b.cropId)!!
                    val n = Garden.yieldOf(sE, b)
                    Garden.harvest(sE, i)
                    unitsPicked += n
                    grossCeiling += n *
                        (Stand.stockDef(crop.itemId)
                            ?.shopPrice ?: 0) *
                        Stand.PRICE_MAX_MULT
                }
                b == null || b.dead -> {
                    val crop = Garden.CROPS.firstOrNull {
                        Garden.plantableNow(sE, it) }
                    if (crop != null) Garden.plant(sE, i, crop.id)
                }
            }
        }
        Garden.water(sE)
        Garden.clearWeeds(sE)
        val d = sE.absDay
        sE.weatherId = if (d % 3 == 0) "rain" else "sunny"
        setDayG(sE, d + 1)
        Garden.dailyRollover(sE)
    }
    val seedSpent = sE.life["gardenSeedSpent"] ?: 0
    check(unitsPicked > 0 && seedSpent > 0,
        "garden: the simulated season actually grew food " +
            "($unitsPicked units) on real seed spend " +
            "($seedSpent 🪙)")
    check(grossCeiling < 390,
        "garden: a PERFECT season — every bed worked, " +
            "every day watered, everything valued at the " +
            "stand band's CEILING (3× reference) — grosses " +
            "$grossCeiling 🪙, under one paper-route season " +
            "(Jobs: 30 🪙/week × 13 = 390). The garden " +
            "feeds people; it is not a wage")
    check(grossCeiling - seedSpent < 200,
        "garden: net of seeds the ceiling season clears " +
            "${grossCeiling - seedSpent} 🪙 — inside the " +
            "ledger's bound with room to spare")

    // ---------- saves: the beds round-trip ----------
    val backG = decodeGameState(encodeGameState(sG))
    check(Garden.bed(backG, 0) == Garden.bed(sG, 0) &&
        Garden.bed(backG, 1) == Garden.bed(sG, 1) &&
        Garden.pageLines(backG) == Garden.pageLines(sG),
        "garden: mid-growth beds round-trip exactly — " +
            "the page reads identically after a reload")
    val backT = decodeGameState(encodeGameState(sT))
    check(Garden.grownAvailable(backT, "tomato") == 4 &&
        Garden.pageLines(backT) == Garden.pageLines(sT),
        "garden: the harvest record and provenance " +
            "counters round-trip with the save")
}
}

private fun sectionV0110c(root: String) {
// ================= v0.11.0c: sleepovers =================
// Queue #11 item 3. Friday nights only (one a week by
// construction), your crew's KIDS at your house: the plan
// runs the full occupied discipline with every refusal
// NAMED, the evening lands four beats in the dinners'
// discipline (real pantry, a fact-tied movie, a PLAYED
// pillow fight on the showdown bar, lights out), and the
// morning pays the stated rates, plants the topic, and
// writes the capped record. All state rides life/
// lifeText — a legacy save simply never hosted one.
println("== v0.11.0c: sleepovers — Queue #11 item 3 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.11.0c"),
        "sleepovers: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 83 / 0.11.0c")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "sleepovers: the source tree and its description agree — " +
            "97 Kotlin files (Sleepovers.kt is the one addition) " +
            "(counted $ktCount)")

    // ---------- wiring pins ----------
    val sSrc = File(root,
        "src/com/hunt3r/southparktown/Sleepovers.kt").readText()
    check(!sSrc.contains("import android"),
        "sleepovers: Sleepovers.kt is pure Kotlin — no platform imports")
    check(sSrc.contains("SLEEPOVER_WEEKDAY") &&
        sSrc.contains("MIN_GUESTS") && sSrc.contains("HISTORY_CAP"),
        "sleepovers: the dials are named constants (cadence, floor, cap)")
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(engSrc.contains(
        "Sleepovers.gatheringBlock(state, a.name, timeMin)"),
        "sleepovers: the agenda stack seats the claim")
    val slpClaim = engSrc.indexOf("Sleepovers.gatheringBlock")
    check(slpClaim > engSrc.indexOf("Play.gatheringBlock") &&
        slpClaim < engSrc.indexOf("Stand.gatheringBlock"),
        "sleepovers: the claim seats after the play, before the stand")
    check(engSrc.indexOf("Sleepovers.dailyRollover(state)") >
        engSrc.indexOf("Family.dailyRollover(state)") &&
        engSrc.indexOf("Sleepovers.dailyRollover(state)") <
        engSrc.indexOf("Jobs.dailyRollover(state)"),
        "sleepovers: Engine.onNewDay wraps the night beside the " +
            "family, before the jobs settle")
    check(engSrc.contains("Sleepovers.tick(state)"),
        "sleepovers: the presence tick runs in advanceTime")
    val crewSrc = File(root,
        "src/com/hunt3r/southparktown/Crew.kt").readText()
    check(crewSrc.contains("Sleepovers.claims(state, name)") &&
        crewSrc.contains("\"sleepover\""),
        "sleepovers: the crew's occupied oracle reads the claim — " +
            "busyReason can answer \"sleepover\"")
    val tgSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(tgSrc.contains("Sleepovers.talkStepFor") &&
        tgSrc.contains("sleepHit"),
        "sleepovers: the beats ride the DINNER rail — the ladder " +
            "gains no rung")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("Sleepovers.judgeTalk") &&
        gaSrc.contains("Sleepovers.lookText") &&
        gaSrc.contains("startPillowFight") &&
        gaSrc.contains("sleepoverDialog()") &&
        gaSrc.contains("Sleepovers.dressingTokens(state)"),
        "sleepovers: GameActivity judges the beats, hides the " +
            "movie in the Look, launches the fight, plans from " +
            "the bed and the person menu, and dresses the room")
    val jaSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jaSrc.contains("sectionTitle(\"🛌 SLEEPOVERS\")") &&
        jaSrc.contains("Sleepovers.pageLines(state)"),
        "sleepovers: the Journal renders the 🛌 SLEEPOVERS " +
            "section from Sleepovers.pageLines")
    val houseSrc = File(root,
        "src/com/hunt3r/southparktown/House.kt").readText()
    check(houseSrc.contains("Sleepovers.morningNote(state)"),
        "sleepovers: the wake-up report carries the morning note")
    val iaSrc = File(root,
        "src/com/hunt3r/southparktown/InteriorArt.kt").readText()
    check(iaSrc.contains("\"sleeping-bags\" in TownInfo.houseDecor"),
        "sleepovers: the bags are drawn off the decor token, " +
            "in the established dressing pattern")
    val mvSrc = File(root,
        "src/com/hunt3r/southparktown/MinigameViews.kt").readText()
    check(mvSrc.contains("class PillowFightView"),
        "sleepovers: the pillow fight has its played view")
    // spoiler hygiene: the module's writing never touches
    // sealed ground (structure words only, as ever)
    for (sealed in listOf("sleepwalk", "strongbox", "cameo",
        "professor chaos", "communal paperwork")) {
        check(!sSrc.lowercase().contains(sealed),
            "sleepovers: the module's writing stays clear of " +
                "sealed ground ($sealed)")
    }

    // ---------- helpers ----------
    fun setDayS(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun slpState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    /** The first Friday on/after [from] whose evening the
     *  town leaves free (the plan's own night-level read). */
    fun cleanFriday(s: GameState, from: Int): Int {
        var d = from
        while (d < from + 400) {
            if (Sleepovers.isSleepoverDay(d)) {
                setDayS(s, d)
                if (Sleepovers.nightBlock(s) == null) return d
            }
            d++
        }
        return -1
    }
    /** Stage a planned night directly (the save format is
     *  the contract): guests claimed, in the room, evening. */
    fun stageNight(s: GameState, guests: List<String>) {
        s.life["slpDay"] = s.absDay
        s.lifeText["slpGuests"] = guests.joinToString(",")
        s.life["slpMask"] = 0
        s.lifeText["slpLabel"] = Sleepovers.dateLabelOf(s.absDay)
        for (g in guests) {
            val a = s.agents[g] ?: continue
            a.location = YOUR_HOUSE; a.asleep = false
            a.waypoints.clear()
        }
        s.timeMin = 18 * 60 + 30
    }

    // ---------- the cadence, in ONE time space ----------
    // The polish-#10 lesson: two cadences were proven apart
    // in different spaces once, and a Saturday paid for it.
    // Here the sleepover Friday, the patrol nights and the
    // family table's rhythm are swept in the same ordinal
    // space, off the same readers the game itself calls.
    run {
        var fridays = 0
        for (d in 0 until 7 * 104) {
            if (!Sleepovers.isSleepoverDay(d)) continue
            fridays++
            check(Jobs.weekdayOf(d) == 5,
                "cadence: a sleepover day is a Friday (absDay $d)")
            check(Jobs.weekdayOf(d) !in Heroes.PATROL_WEEKDAYS,
                "cadence: a sleepover Friday is never a patrol " +
                    "night (absDay $d)")
            check(d % 7 == 1,
                "cadence: a Friday is always absDay % 7 == 1 " +
                    "(absDay $d) — the family table's {0,2,4} " +
                    "can never hold it")
            check(d % 7 !in setOf(0, 2, 4),
                "cadence: sleepover and family-dinner rhythms " +
                    "are disjoint (absDay $d)")
        }
        check(fridays == 104,
            "cadence: exactly one sleepover night a week, every " +
                "week, for two years (saw $fridays)")
        for (d in 0 until 364 step 7) {
            val inWeek = (d until d + 7)
                .count { Sleepovers.isSleepoverDay(it) }
            check(inWeek == 1,
                "cadence: the week of absDay $d holds exactly " +
                    "one Friday")
        }
        for (d in listOf(0, 1, 5, 40, 100, 365)) {
            val n = Sleepovers.nextSleepoverDay(d)
            check(Sleepovers.isSleepoverDay(n) && n in d..d + 6,
                "cadence: the next Friday from $d lands within " +
                    "the week (got $n)")
        }
        // and the family table itself agrees, read live:
        val (_, fs) = slpState(1101)
        var famClash = false
        for (d in 0 until 7 * 52) {
            if (!Sleepovers.isSleepoverDay(d)) continue
            setDayS(fs, d)
            if (Family.dinnerTonight(fs)) famClash = true
        }
        check(!famClash,
            "cadence: Family.dinnerTonight never fires on a " +
                "sleepover Friday in a year of Fridays")
    }

    // ---------- the plan: eligibility + named refusals ----------
    run {
        val (_, s) = slpState(1102)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters,Randy,Shelley"
        var fri = -1
        var d = 40
        while (d < 400) {
            if (Sleepovers.isSleepoverDay(d)) {
                setDayS(s, d)
                val p = Sleepovers.planFor(s)
                if (p.nightOk && p.okGuests.containsAll(
                        listOf("Stan", "Kyle", "Butters", "Shelley"))) {
                    fri = d; break
                }
            }
            d++
        }
        check(fri > 0, "plan: a Friday exists where the kid " +
            "crew is free (scanned to $fri)")
        val plan = Sleepovers.planFor(s)
        check(plan.canPropose,
            "plan: three-plus free kid guests propose cleanly")
        check(plan.guests.map { it.name } ==
            listOf("Stan", "Kyle", "Butters", "Shelley"),
            "plan: the guest list is the crew's kids, in crew " +
                "order — teens included (Shelley is a young teen)")
        check(plan.notGuests.map { it.name } == listOf("Randy") &&
            plan.notGuests.single().reason.contains("grown-ups"),
            "plan: the adult crew member is not a guest — " +
                "grown-ups don't do sleepovers, stated plainly")
        check(Sleepovers.menuOption(s, "Stan") != null &&
            Sleepovers.menuOption(s, "Randy") == null &&
            Sleepovers.menuOption(s, "Wendy") == null,
            "plan: the person-menu option shows for crew kids " +
                "only — not adults, not non-members")

        // a claimed guest is NAMED, with the reason: on
        // some Friday, Stan STARS in the Bijou's feature —
        // the house claims its stars at doors (MovieNights'
        // own gathering claim, read through busyReason)
        var named: Sleepovers.GuestPlan? = null
        d = 40
        while (d < 600 && named == null) {
            if (Sleepovers.isSleepoverDay(d)) {
                setDayS(s, d)
                if (Sleepovers.nightBlock(s) == null &&
                    "Stan" in MovieNights.featureFor(s).stars) {
                    val p2 = Sleepovers.planFor(s)
                    val g = p2.guests.firstOrNull { it.name == "Stan" }
                    if (g != null && !g.ok) named = g
                }
            }
            d++
        }
        check(named != null && named.reason.contains("Bijou"),
            "plan: a guest claimed by the Bijou is named with " +
                "the reason, never silently swapped " +
                "(got ${named?.reason})")

        // and the Friday dinner claim: tonight's inviting
        // household seats its own at its table — a crew kid
        // from that house is refused BY NAME for dinner,
        // while the night itself stays proposable (the
        // invitation never blocks; the claim is the kids')
        var namedDinner: Sleepovers.GuestPlan? = null
        d = 40
        while (d < 600 && namedDinner == null) {
            if (Sleepovers.isSleepoverDay(d)) {
                setDayS(s, d)
                val inv2 = Dinners.todaysInvite(s)
                if (inv2 != null && inv2.members.contains("Stan") &&
                    Sleepovers.nightBlock(s) == null) {
                    val p3 = Sleepovers.planFor(s)
                    val g = p3.guests.firstOrNull { it.name == "Stan" }
                    if (g != null && !g.ok) namedDinner = g
                }
            }
            d++
        }
        check(namedDinner != null &&
            namedDinner.reason.contains("dinner"),
            "plan: a guest claimed by their own family's " +
                "Friday table is named with the reason " +
                "(got ${namedDinner?.reason})")

        // the minimum is a floor, not a suggestion
        val (_, s2) = slpState(1103)
        s2.lifeText["crew:members"] = "Stan"
        val f2 = cleanFriday(s2, 40)
        check(f2 > 0, "plan: clean Friday found for the floor test")
        val pMin = Sleepovers.planFor(s2)
        check(!pMin.canPropose && pMin.nightReason
            .contains("at least ${Sleepovers.MIN_GUESTS}"),
            "plan: one free guest is not a sleepover — the plan " +
                "proposes a different night instead")
        check(!Sleepovers.propose(s2),
            "plan: propose() itself refuses below the floor")
        val (_, s3) = slpState(1104)
        setDayS(s3, Sleepovers.nextSleepoverDay(40))
        val pEmpty = Sleepovers.planFor(s3)
        check(!pEmpty.canPropose && pEmpty.nightReason
            .contains("No crew yet"),
            "plan: no crew, no sleepover — said plainly")
        val (_, s4) = slpState(1105)
        s4.lifeText["crew:members"] = "Randy,Sharon"
        val pGrown = Sleepovers.planFor(s4)
        check(!pGrown.canPropose && pGrown.guests.isEmpty() &&
            pGrown.notGuests.size == 2,
            "plan: an all-grown-up crew has no guests to offer")
        // not a Friday at all
        val (_, s5) = slpState(1106)
        s5.lifeText["crew:members"] = "Stan,Kyle"
        setDayS(s5, 42)   // a non-Friday (weekdayOf(42) == 4)
        check(Jobs.weekdayOf(42) != 5 &&
            Sleepovers.nightBlock(s5)?.contains("Friday") == true,
            "plan: a non-Friday names the institution and the " +
                "next Friday instead of improvising")
    }

    // ---------- deference: the town's bigger nights win ----------
    run {
        val (_, s) = slpState(1107)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri = cleanFriday(s, 40)
        check(fri > 0 && Sleepovers.nightBlock(s) == null,
            "deference: a plain Friday is free (absDay $fri)")
        // an invitation to someone else's table does NOT
        // own the night: every Friday is a rotation day,
        // so it can't (the hosted table's precedent — your
        // evening is yours). It is NAMED in the plan, and
        // the inviting household's own kids are claimed at
        // their table by the real discipline (see the plan
        // section's named refusals).
        val inv = Dinners.HOUSEHOLDS.first()
        s.life["dinInviteDay"] = s.absDay
        s.lifeText["dinInviteId"] = inv.id
        check(Sleepovers.nightBlock(s) == null &&
            Sleepovers.planFor(s).inviteFamily == inv.family,
            "deference: an outstanding invitation is named in " +
                "the plan, never a block — Friday is always a " +
                "rotation day, and the night is the player's " +
                "to spend at home")
        s.life.remove("dinInviteDay"); s.lifeText.remove("dinInviteId")
        // hosting your own table owns it too (the hosted
        // record is two keys; hostingTonight reads them)
        s.life["hostDay"] = s.absDay
        s.lifeText["hostHousehold"] = inv.id
        check(Dinners.hostingTonight(s) != null,
            "deference: (fabrication) hosting stands tonight")
        check(Sleepovers.nightBlock(s)?.contains("hosting") == true,
            "deference: hosting your own dinner tonight cancels " +
                "the sleepover — one set piece a night")
        s.life.remove("hostDay"); s.lifeText.remove("hostHousehold")
        check(Sleepovers.nightBlock(s) == null,
            "deference: with the table cleared, the Friday is " +
                "free again")
    }

    // ---------- propose, claim, cancel ----------
    run {
        val (eng, s) = slpState(1108)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        var fri = -1
        var d = 40
        while (d < 400) {
            if (Sleepovers.isSleepoverDay(d)) {
                setDayS(s, d)
                val p = Sleepovers.planFor(s)
                if (p.canPropose && p.okGuests.containsAll(
                        listOf("Stan", "Kyle", "Butters"))) {
                    fri = d; break
                }
            }
            d++
        }
        check(fri > 0, "claim: a proposable Friday found ($fri)")
        check(Sleepovers.propose(s) && Sleepovers.plannedTonight(s),
            "claim: propose() locks the night in")
        check(Sleepovers.plannedGuests(s) ==
            listOf("Stan", "Kyle", "Butters"),
            "claim: the plan holds exactly the free guests")
        check(Crew.isMember(s, "Stan"),
            "claim: proposing touches nobody's crew membership")
        // the evening, on the state clock (the gathering
        // readers all read state.timeMin, the Stand idiom)
        s.timeMin = 18 * 60 + 30
        check(Sleepovers.gatheringBlock(s, "Stan", 17 * 60) == null &&
            Sleepovers.gatheringBlock(s, "Stan", 18 * 60) != null &&
            Sleepovers.gatheringBlock(s, "Stan", 21 * 60 + 59) != null &&
            Sleepovers.gatheringBlock(s, "Stan", 22 * 60) == null,
            "claim: the window is 18:00–22:00, no earlier, no later")
        check(Sleepovers.gatheringBlock(s, "Stan", 19 * 60)
            ?.location == YOUR_HOUSE,
            "claim: the block seats the guest at your house")
        s.timeMin = 19 * 60 + 30
        check(Crew.busyReason(s, "Kyle") == "sleepover",
            "claim: the occupied oracle answers \"sleepover\" " +
                "for a claimed guest in the window")
        val agent = s.agents["Kyle"]!!
        check(eng.effectiveAgendaBlock(s, agent, 19 * 60 + 30)
            ?.location == YOUR_HOUSE,
            "claim: the agenda stack itself seats the guest at " +
                "your house for the evening")
        // a bigger claim vetoes the seat (the self-guard):
        // put Kyle to sleep and the claim stands down
        agent.asleep = true
        check(Sleepovers.gatheringBlock(s, "Kyle", 19 * 60) == null,
            "claim: a guest the town has put to sleep is not " +
                "dragged to the sleepover")
        agent.asleep = false
        // dressing: the bags are out tonight, gone on cancel
        check(Sleepovers.dressingTokens(s) ==
            setOf("sleeping-bags"),
            "claim: the sleeping bags dress the room tonight")
        check(Sleepovers.cancel(s) && !Sleepovers.plannedTonight(s) &&
            Sleepovers.dressingTokens(s).isEmpty(),
            "claim: cancel strikes the plan and the bags — " +
                "and a beat-less plan can always be called off")
    }

    // ---------- the beats: snacks off the real pantry ----------
    run {
        val (_, s) = slpState(1109)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri = cleanFriday(s, 40)
        check(fri > 0, "beats: clean Friday found ($fri)")
        stageNight(s, listOf("Stan", "Kyle", "Butters"))
        s.inventory["snack_cake"] = 2
        s.inventory["lemonade"] = 1
        // order is law: Talk offers the current beat only,
        // and the movie (a Look) never answers a Talk
        check(Sleepovers.lookText(s, YOUR_HOUSE) == null,
            "beats: the movie does not jump the snacks")
        val hit0 = Sleepovers.talkStepFor(s, "Stan")
        check(hit0 != null && hit0.stepIndex == 0,
            "beats: a Talk with a present guest offers snacks")
        check(Sleepovers.talkStepFor(s, "Wendy") == null,
            "beats: a non-guest's Talk is ordinary conversation")
        val served = Sleepovers.judgeTalk(s, "Stan")
        check(served != null && served.text.contains("Snacky Cake") &&
            served.text.contains("Lemonade"),
            "beats: the spread names what the pantry gave")
        check((s.inventory["snack_cake"] ?: 0) == 1 &&
            (s.inventory["lemonade"] ?: 0) == 0,
            "beats: the pantry paid exactly — one cake eaten " +
                "of two, the lemonade gone, nothing invented")
        check(Sleepovers.currentStep(s) == 1 &&
            Sleepovers.attendees(s).containsAll(
                listOf("Stan", "Kyle", "Butters")),
            "beats: landing a beat stamps who was in the room")

        // the bare cupboard, honestly: no family yet on a
        // brand-new save's first Friday (absDay 1), no items
        val (_, sBare) = slpState(1110)
        sBare.lifeText["crew:members"] = "Stan,Kyle"
        setDayS(sBare, 1)
        check(Sleepovers.isSleepoverDay(1) &&
            !Family.arrived(sBare),
            "beats: (fabrication) the first Friday precedes " +
                "the family's arrival")
        stageNight(sBare, listOf("Stan", "Kyle"))
        val bareHit = Sleepovers.judgeTalk(sBare, "Stan")
        check(bareHit != null && bareHit.text
            .contains("honestly empty") &&
            sBare.inventory.isEmpty(),
            "beats: an empty pantry is a smaller, honestly-" +
                "stated spread — nothing is conjured")

        // Mom covers when the family is home: same bare
        // cupboard, family arrived, Friday evening at home
        val (_, sMom) = slpState(1111)
        sMom.lifeText["crew:members"] = "Stan,Kyle"
        val friM = cleanFriday(sMom, 40)
        check(friM > 0, "beats: clean Friday for the Mom test")
        sMom.life["famArrived"] = 1
        check(Sleepovers.momHome(sMom.copy(timeMin = 19 * 60)),
            "beats: (fabrication) Mom is home on a Friday evening")
        stageNight(sMom, listOf("Stan", "Kyle"))
        val momHit = Sleepovers.judgeTalk(sMom, "Stan")
        check(momHit != null && momHit.text.contains("Mom") &&
            momHit.text.contains("parental reserves") &&
            sMom.inventory.isEmpty(),
            "beats: with the family home, Mom covers the bare " +
                "cupboard — stated as her treat, consuming nothing")
    }

    // ---------- the movie: fact-tied, both branches ----------
    run {
        val (_, s) = slpState(1112)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri = cleanFriday(s, 40)
        check(fri > 0, "movie: clean Friday found ($fri)")
        stageNight(s, listOf("Stan", "Kyle", "Butters"))
        s.life["slpMask"] = 1   // snacks landed
        val f = MovieNights.featureFor(s)
        val mt = Sleepovers.lookText(s, YOUR_HOUSE)
        check(mt != null && mt.contains(f.title) &&
            mt.contains(f.genreLabel) &&
            f.stars.all { mt.contains(it) },
            "movie: a standing screening puts the Bijou's own " +
                "feature on the TV — title, genre, stars, all " +
                "from the listing")
        check(s.lifeText["slpMovie"] ==
            "“${f.title}” (${f.genreLabel})",
            "movie: the record keeps the feature's own facts")

        // the album branch: the Bijou dark (a case owns the
        // marquee — the marathon stage), your photos play
        val (_, s2) = slpState(1113)
        s2.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri2 = cleanFriday(s2, 40)
        check(fri2 > 0, "movie: clean Friday for the album test")
        s2.shenaniganId = Mystery2.MARATHON_ID
        check(MovieNights.darkReason(s2) != null,
            "movie: (fabrication) the marquee is dark tonight")
        stageNight(s2, listOf("Stan", "Kyle", "Butters"))
        s2.life["slpMask"] = 1
        val older = PhotoRecord(
            id = "p-old", dayKey = s2.todayKey, dateLabel = "9/30",
            timeMin = 900, locId = "KidsPark", inside = false,
            weatherId = "clear", appearance = emptyMap(),
            figures = listOf(
                PhotoFigure("New Kid", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy")),
            absDay = fri2 - 3)
        val newer = PhotoRecord(
            id = "p-new", dayKey = s2.todayKey, dateLabel = "10/2",
            timeMin = 900, locId = "StarksPond", inside = false,
            weatherId = "clear", appearance = emptyMap(),
            figures = listOf(
                PhotoFigure("New Kid", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy"),
                PhotoFigure("Kyle", "cast", "happy")),
            absDay = fri2 - 1)
        s2.photos.add(older); s2.photos.add(newer)
        val ht = Sleepovers.lookText(s2, YOUR_HOUSE)
        check(ht != null && ht.contains("Stark's Pond") &&
            ht.contains("10/2") && ht.contains("Stan") &&
            ht.contains("Kyle"),
            "movie: the home movie describes YOUR photo from " +
                "its record alone — place, date, who was in frame")
        check(s2.lifeText["slpMovie"] ==
            "home movie: Stark's Pond, 10/2",
            "movie: the pick prefers the newest photo with " +
                "two guests in frame over a newer-looking claim")
        // no album at all: the honest fallback
        val (_, s3) = slpState(1114)
        s3.lifeText["crew:members"] = "Stan,Kyle"
        val fri3 = cleanFriday(s3, 40)
        check(fri3 > 0, "movie: clean Friday for the fallback")
        s3.shenaniganId = Mystery2.MARATHON_ID
        stageNight(s3, listOf("Stan", "Kyle"))
        s3.life["slpMask"] = 1
        val ft = Sleepovers.lookText(s3, YOUR_HOUSE)
        check(ft != null && ft.contains("weather") &&
            s3.lifeText["slpMovie"]!!.contains("album was empty"),
            "movie: no screening and no album — the weather " +
                "channel, stated as exactly that")
    }

    // ---------- the pillow fight: played, seeded, judged ----------
    run {
        val (_, s) = slpState(1115)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri = cleanFriday(s, 40)
        check(fri > 0, "fight: clean Friday found ($fri)")
        stageNight(s, listOf("Stan", "Kyle", "Butters"))
        s.life["slpMask"] = 3   // snacks + movie landed
        check(Sleepovers.talkStepFor(s, "Butters")?.stepIndex == 2,
            "fight: the Talk offers the pillow fight third")
        check(Sleepovers.judgeTalk(s, "Butters") == null,
            "fight: the fight is PLAYED, never judged by a " +
                "Talk — judgeTalk refuses it outright")
        val seed = Sleepovers.pillowSeed(s, "Butters")
        val a = Sleepovers.PillowSession(seed, "Butters")
        val b = Sleepovers.PillowSession(seed, "Butters")
        repeat(3) { a.swing(0.5); b.swing(0.5) }
        check(a.hits == b.hits && a.powerMilli == b.powerMilli,
            "fight: the same seed replays the same fight — " +
                "the judging is deterministic")
        check(a.hits == 3 && a.youWon,
            "fight: three perfect releases beat Butters' " +
                "dodge every time (his dodge is authored at 0.08)")
        val hit = Sleepovers.judgePillowFight(s, a)
        check(hit != null && hit.stepIndex == 2 &&
            Sleepovers.currentStep(s) == 3 &&
            s.lifeText["slpFight"]!!.startsWith("you out-pillowed"),
            "fight: judging lands the beat and writes the " +
                "record the lights-out telling will quote")
        // the loss is real too: three wild swings whiff
        val c = Sleepovers.PillowSession(seed, "Butters")
        repeat(3) { c.swing(0.0) }
        check(c.hits == 0 && !c.youWon,
            "fight: wild releases never connect — the bar is honest")
        val (_, s2) = slpState(1116)
        s2.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri2 = cleanFriday(s2, 40)
        check(fri2 > 0, "fight: clean Friday for the loss")
        stageNight(s2, listOf("Stan", "Kyle", "Butters"))
        s2.life["slpMask"] = 3
        val lost = Sleepovers.judgePillowFight(s2, c)
        check(lost != null && s2.lifeText["slpFight"]!!
            .contains("took the pillow fight"),
            "fight: a lost fight records the guest's win — " +
                "the couch follows the result, not the hope")
        // lights out closes the night
        val lo = Sleepovers.judgeTalk(s2, "Stan")
        check(lo != null && lo.stepIndex == 3 && lo.allLanded &&
            Sleepovers.currentStep(s2) == Sleepovers.STEP_COUNT,
            "fight: lights out is the last beat, and the " +
                "night reads whole")
        check(lo != null && (lo.text.contains("pillow-fight winner") ||
            lo.text.contains("couch")),
            "fight: the lights-out telling resolves the couch " +
                "off the fight's own record")
    }

    // ---------- the morning: wrap, pay, topics, record ----------
    run {
        val (_, s) = slpState(1117)
        s.lifeText["crew:members"] = "Stan,Kyle,Butters"
        val fri = cleanFriday(s, 40)
        check(fri > 0, "morning: clean Friday found ($fri)")
        stageNight(s, listOf("Stan", "Kyle", "Butters"))
        s.inventory["snack_cake"] = 1
        // play the whole night through the real judges
        Sleepovers.judgeTalk(s, "Stan")                    // snacks
        Sleepovers.lookText(s, YOUR_HOUSE)                 // movie
        val sess = Sleepovers.PillowSession(
            Sleepovers.pillowSeed(s, "Butters"), "Butters")
        repeat(3) { sess.swing(0.5) }
        Sleepovers.judgePillowFight(s, sess)               // fight
        Sleepovers.judgeTalk(s, "Kyle")                    // lights out
        check(Sleepovers.beatsLanded(s) == 4,
            "morning: (fabrication) the full night landed")
        // a group photo from the night, in the album
        s.photos.add(PhotoRecord(
            id = "p-night", dayKey = s.todayKey,
            dateLabel = Sleepovers.dateLabelOf(fri),
            timeMin = 21 * 60, locId = YOUR_HOUSE, inside = true,
            weatherId = "clear", appearance = emptyMap(),
            figures = listOf(
                PhotoFigure("New Kid", "player", "happy"),
                PhotoFigure("Stan", "cast", "happy"),
                PhotoFigure("Kyle", "cast", "happy"),
                PhotoFigure("Butters", "cast", "happy")),
            absDay = fri))
        val before = listOf("Stan", "Kyle", "Butters")
            .map { s.friendship[it] ?: 0 }
        s.life["famArrived"] = 1
        setDayS(s, fri + 1)
        Sleepovers.dailyRollover(s)
        val after = listOf("Stan", "Kyle", "Butters")
            .map { s.friendship[it] ?: 0 }
        check(after.zip(before).all { (a2, b2) -> a2 - b2 == 2 },
            "morning: a full night pays +2 per guest who came, " +
                "once — the stated full-night rate")
        check(!Sleepovers.plannedTonight(s) &&
            s.lifeText["slpGuests"] == null,
            "morning: the wrap strikes the plan — bags away, " +
                "guests back on their own agendas")
        val nights = Sleepovers.nights(s)
        check(nights.size == 1 && nights[0].beats == 4 &&
            nights[0].came.containsAll(
                listOf("Stan", "Kyle", "Butters")) &&
            nights[0].snacks.contains("Snacky Cake") &&
            nights[0].movie.isNotEmpty() &&
            nights[0].fight.contains("pillow") &&
            nights[0].photo && nights[0].pay == 2,
            "morning: the record holds the night whole — who " +
                "came, the beats, the snacks, the movie, the " +
                "fight, the photo, the pay")
        for (g in listOf("Stan", "Kyle", "Butters")) {
            val mem = NpcMemoryStore.get(g)
            check(mem != null && Sleepovers.TOPIC in mem.topics,
                "morning: the \"sleepover\" topic is planted " +
                    "in $g (Threads carries it from here)")
        }
        val memStan = NpcMemoryStore.get("Stan")!!
        memStan.meets = 3
        val fu = Threads.followUp(memStan, kotlin.random.Random(7))
        check(fu != null && fu.contains("sleepover"),
            "morning: the planted topic has follow-up lines — " +
                "the guests retell the night in conversation")
        val note = Sleepovers.morningNote(s)
        check(note != null && note.contains("pancakes") &&
            note.contains("Her treat"),
            "morning: with the family home, Mom makes " +
                "pancakes — her treat, stated as the call")

        // a partial night pays the partial rate; a night
        // that never got going pays nothing and plants none
        val (_, s2) = slpState(1118)
        s2.lifeText["crew:members"] = "Stan,Kyle"
        val fri2 = cleanFriday(s2, 40)
        check(fri2 > 0, "morning: clean Friday for the partial")
        stageNight(s2, listOf("Stan", "Kyle"))
        Sleepovers.judgeTalk(s2, "Stan")       // snacks
        Sleepovers.lookText(s2, YOUR_HOUSE)    // movie — 2 beats
        val b2 = s2.friendship["Stan"] ?: 0
        setDayS(s2, fri2 + 1)
        Sleepovers.dailyRollover(s2)
        check((s2.friendship["Stan"] ?: 0) - b2 ==
            Sleepovers.PAY_PARTIAL &&
            Sleepovers.nights(s2).single().pay ==
            Sleepovers.PAY_PARTIAL,
            "morning: two beats pay the +1 partial rate, once")
        val note2 = Sleepovers.morningNote(s2)
        check(note2 != null && !note2.contains("pancakes") &&
            note2.contains("sleeping bags"),
            "morning: without the family, the morning line " +
                "is the plain one — no invented pancakes")
        val (_, s3) = slpState(1119)
        s3.lifeText["crew:members"] = "Stan,Kyle"
        val fri3 = cleanFriday(s3, 40)
        check(fri3 > 0, "morning: clean Friday for the empty night")
        stageNight(s3, listOf("Stan", "Kyle"))
        s3.timeMin = 19 * 60
        Sleepovers.tick(s3)   // the evening passes; they were here
        val b3 = s3.friendship["Stan"] ?: 0
        setDayS(s3, fri3 + 1)
        Sleepovers.dailyRollover(s3)
        check((s3.friendship["Stan"] ?: 0) == b3 &&
            Sleepovers.nights(s3).single().pay == 0 &&
            Sleepovers.nights(s3).single().beats == 0,
            "morning: a night that never got going pays " +
                "nothing — presence alone isn't a sleepover")
        check(Sleepovers.nights(s3).single().came
            .containsAll(listOf("Stan", "Kyle")),
            "morning: the empty night still records who was " +
                "actually here — presence is evidence, pay is " +
                "for the night that happened")

        // a stale plan (the game slept through two days)
        // clears with no record and no pay
        val (_, s4) = slpState(1120)
        s4.lifeText["crew:members"] = "Stan,Kyle"
        val fri4 = cleanFriday(s4, 40)
        stageNight(s4, listOf("Stan", "Kyle"))
        setDayS(s4, fri4 + 3)
        Sleepovers.dailyRollover(s4)
        check(Sleepovers.nights(s4).isEmpty() &&
            s4.life["slpDay"] == null,
            "morning: a stale plan is struck silently — the " +
                "night simply didn't happen")

        // the record caps at HISTORY_CAP, oldest pruned
        val (_, s5) = slpState(1121)
        s5.lifeText["crew:members"] = "Stan,Kyle"
        var d5 = cleanFriday(s5, 40)
        var firstDay = -1
        repeat(Sleepovers.HISTORY_CAP + 2) {
            setDayS(s5, d5)
            stageNight(s5, listOf("Stan", "Kyle"))
            if (firstDay < 0) firstDay = d5
            setDayS(s5, d5 + 1)
            Sleepovers.dailyRollover(s5)
            d5 = Sleepovers.nextSleepoverDay(d5 + 1)
        }
        check(Sleepovers.nights(s5).size ==
            Sleepovers.HISTORY_CAP &&
            s5.lifeText["slpNight:$firstDay"] == null,
            "morning: the record keeps ${Sleepovers.HISTORY_CAP} " +
                "nights — the oldest is pruned, key and all")
    }

    // ---------- save shape: additive only ----------
    run {
        // a legacy save (no slp keys anywhere) reads as a
        // town that never hosted — every reader null-safe
        val (_, s) = slpState(1122)
        check(Sleepovers.nights(s).isEmpty() &&
            !Sleepovers.plannedTonight(s) &&
            Sleepovers.morningNote(s) == null &&
            Sleepovers.pageLines(s).first()
                .contains("No sleepovers yet"),
            "save: a pre-0.11.0c save simply never hosted one")
        // the record survives the save's own shape: life and
        // lifeText are the whole persistence for this system
        val (_, s2) = slpState(1123)
        s2.lifeText["crew:members"] = "Stan,Kyle"
        val fri = cleanFriday(s2, 40)
        stageNight(s2, listOf("Stan", "Kyle"))
        Sleepovers.judgeTalk(s2, "Stan")
        setDayS(s2, fri + 1)
        Sleepovers.dailyRollover(s2)
        val (_, back) = slpState(1124)
        back.life.putAll(s2.life)
        back.lifeText.putAll(s2.lifeText)
        setDayS(back, fri + 1)
        check(Sleepovers.nights(back) == Sleepovers.nights(s2) &&
            Sleepovers.morningNote(back) ==
            Sleepovers.morningNote(s2),
            "save: the night record round-trips through the " +
                "life/lifeText maps alone")
        // the Journal page fits its card (the fit-QA pattern)
        val lines = Sleepovers.pageLines(s2) +
            Sleepovers.pageLines(back)
        val innerW = 420f
        for (fs in listOf(1.0f, 1.3f)) {
            val mFs = { t: String -> t.length * 10f * fs }
            for (line in lines) {
                if (line.isEmpty()) continue
                val e = Chrome.ellipsize(line, innerW, measure = mFs)
                check(mFs(e) <= innerW + 0.01f,
                    "fitQA: a 🛌 SLEEPOVERS line fits at fs $fs")
                check(e.length >= 4 || e == line,
                    "fitQA: a 🛌 SLEEPOVERS line never collapses " +
                        "at fs $fs")
            }
        }
    }
}
}


// ================= v0.11.0d: Cast Wave 6 — the evidence audit =================
private fun sectionV0110d(root: String) {
    println("== v0.11.0d: cast expansion wave 6 — the evidence audit ==")
    val wave6 = listOf("Pip", "Dougie", "Jason", "Terrance Mephesto",
        "Jenny", "Flora", "Filmore", "Quaid", "Mimsy", "Tricia",
        "Mr. Slave", "Linda Black", "Harriet", "Mr. Biggle",
        "Mr. Turner", "Nancy", "Mr. Stevens", "Mrs. Stevens",
        "Mr. Stoley", "Mrs. Stoley", "Clark", "Maggie", "Mitch",
        "Bob Johnson", "Pusslicker", "Dr. Doctor", "Choksondik",
        "Strong Woman")
    val wave6Kids = listOf("Pip", "Dougie", "Jason", "Terrance Mephesto",
        "Jenny", "Flora", "Filmore", "Quaid", "Mimsy", "Tricia")
    val wave6Adults = wave6 - wave6Kids.toSet()

    // ---------- the roster arithmetic ----------
    check(WAVE6_ORDER == wave6, "wave6: the wave roster is the pinned twenty-eight")
    check(KID_ORDER.size == 98 && KID_ORDER.distinct().size == 98,
        "wave6: KID_ORDER carries 98 distinct names")
    check(AGENT_PROFILES.size == 98, "wave6: 98 agent profiles")
    check(KID_HOUSE.size == 98, "wave6: 98 homes")
    check(CharacterSystem.CAST_KIDS.size == 42 &&
        CharacterSystem.CAST_ADULTS.size == 56,
        "wave6: the split is 42 kids / 56 adults")
    check(wave6Kids.all { it in CharacterSystem.CAST_KIDS } &&
        wave6Adults.all { it in CharacterSystem.CAST_ADULTS },
        "wave6: the age split matches the wave roster")
    check(CharacterSystem.CAST.keys == AGENT_PROFILES.keys,
        "wave6: CAST and AGENT_PROFILES describe the same 98")
    val w6LoreNames = wave6.map { LORE_CHAR_ALIASES.getValue(it) }.toSet()
    check(VisitorSystem.eligible().none { it.name in w6LoreNames || it.name in wave6 },
        "wave6: the visitor pool excludes all twenty-eight newcomers")
    check(wave6.all { CharacterSystem.CAST_BANDS[it] != null } &&
        wave6Kids.all { CharacterSystem.CAST_BANDS[it] == AgeBand.KID } &&
        wave6Adults.all { CharacterSystem.CAST_BANDS[it] == AgeBand.ADULT },
        "wave6: age bands land KID for the kids, ADULT for the grown-ups")

    // ---------- every newcomer is a full citizen ----------
    for (n in wave6) {
        check(n in AGENT_PROFILES, "wave6: $n has a profile")
        check(n in KidArt.SHEETS, "wave6: $n has a sheet spec")
        check(n in LINE_BANKS && n in DAILY_TOPICS && n in SPEECH_RULES,
            "wave6: $n has banks, topics, and a voice card")
        check(n in FRIEND_GREETINGS && n in RESPONSE_BANKS && n in SLEEPY_LINES,
            "wave6: $n has greetings, responses, and sleepy lines")
        check(n in SoundGen.BLIP_FAMILIES, "wave6: $n has a voice blip family")
        check(n in LORE_CHAR_ALIASES, "wave6: $n has a lore alias")
        check(LoreBook.charLore(n) != null, "wave6: $n resolves lorebook entries")
        check(factionOfCast(n) != null, "wave6: $n holds exactly one faction")
    }
    check(wave6.all { (LINE_BANKS[it]?.size ?: 0) >= 9 },
        "wave6: collision lines hold the 9-per-citizen floor for all twenty-eight")
    check(wave6.all { (DAILY_TOPICS[it]?.size ?: 0) >= 18 },
        "wave6: every newcomer carries the full 18 daily topics")

    // ---------- homes: the constellation anchors ----------
    check(KID_HOUSE["Linda Black"] == "TolkienHouse" &&
        KID_HOUSE["Choksondik"] == "Elementary" &&
        KID_HOUSE["Strong Woman"] == "Elementary" &&
        KID_HOUSE["Mitch"] == "CityHall" &&
        KID_HOUSE["Bob Johnson"] == "CityHall" &&
        KID_HOUSE["Mr. Slave"] == "MainStreet" &&
        wave6Kids.all { KID_HOUSE[it] == "Elementary" },
