    check(LoreBook.entry("Kyle Schwartz")?.text?.contains("prison") == true,
        "audit: Kyle Schwartz's entry still has him serving ten years " +
            "for crypto fraud in Connecticut — a visitor, not a resident")
    check(LoreBook.entry("Mr. Hankey")?.text?.contains("Springfield") == true,
        "audit: Mr. Hankey's entry still records the move to Springfield")
    check(LoreBook.entry("Bill Allen")?.text?.length == 218 &&
        LoreBook.entry("Fosse McDonald")?.text?.length == 242,
        "audit: Bill and Fosse still stand as a one-gag duo — the " +
            "laugh is not a person the data can author")
    check(LoreBook.entry("Wing Han Tsang")?.text?.length == 137,
        "audit: Wing Han Tsang still stands at 137 chars — one bride " +
            "episode behind a supporting adult does not clear the floor")
    check(LoreBook.entry("Dr. Gauche")?.text?.length == 365 &&
        "Dr. Doctor" in CharacterSystem.CAST && "Dr. Gauche" !in CharacterSystem.CAST,
        "audit: the doctor's chair has two occupants in the data — the " +
            "cast takes the defining one (Dr. Doctor); Gauche is first in " +
            "line if a future wave wants the modern era")
    check(LoreBook.entry("Tom Thompson")?.text?.length == 226 &&
        LoreBook.entry("Tom (Newsman)")?.text?.length == 269 &&
        "Pusslicker" in CharacterSystem.CAST,
        "audit: the anchor's chair likewise — Pusslicker's decade " +
            "defines it; the Thompsons are its later occupants")
    check(LoreBook.entry("Heather Conduct")?.text?.length == 683 &&
        LoreBook.entry("Casey Miller")?.text?.length == 447 &&
        LoreBook.entry("Jessie")?.text?.length == 483,
        "audit: the fattest single-episode and diffuse entries still " +
            "fail on substance, not length — the audit measured both")
    // The enumeration stays live: the non-cast char census by band.
    // Any lorebook change that adds, removes, or fattens a character
    // entry moves one of these counts and forces a re-audit.
    val castLore = LORE_CHAR_ALIASES.values.toSet()
    val nonCast = LoreBook.byCat("char").filter { it.name !in castLore }
    check(nonCast.size == 2127,
        "audit: 2,127 char entries remain outside the cast (got ${nonCast.size})")
    check(nonCast.count { it.text.length >= 600 } == 8 &&
        nonCast.count { it.text.length in 400..599 } == 48 &&
        nonCast.count { it.text.length in 300..399 } == 116 &&
        nonCast.count { it.text.length in 200..299 } == 341 &&
        nonCast.count { it.text.length < 200 } == 1614,
        "audit: the non-cast bands stand at 8 / 48 / 116 / 341 / 1614 — " +
            "a lorebook change anywhere in the char entries fails this " +
            "pin and forces the next audit")
    check(nonCast.filter { it.text.length >= 600 }.map { it.name }.toSet() ==
        setOf("Jews", "Freedom Pals", "Heather Conduct", "Kenny's Rats",
            "Funnybot (Character)", "L. Ron Hubbard", "Goth Kids", "Jakartha"),
        "audit: the eight fattest non-cast entries are still two groups, " +
            "a rat pack, two celebrity/robot one-offs, a dead founder, " +
            "the already-cast goth kids as a group, and one assassin — " +
            "nobody authorable was left at the top of the book")

    // ---------- spawn: a fresh town seats all ninety-eight ----------
    val engW = Engine(909)
    val sW = engW.newState()
    check(wave6.all { it in sW.agents }, "wave6: a new state seats all twenty-eight newcomers")
    check(sW.agents.size >= 98, "wave6: the roster spawns at 98+")

    // ---------- the fan sheets carry all ninety-eight ----------
    try {
        val params = File("/home/hatch/workspace/goals/" +
            "south-park-interactive-town/files/sheets/tools/params.json")
            .readText()
        check(KID_ORDER.all { params.contains("\"name\": \"$it\"") },
            "wave6: sheet params contain every one of the 98")
        check(params.split("\"name\":").size - 1 == 98,
            "wave6: sheet params hold exactly 98 characters")
    } catch (e: Exception) {
        check(false, "wave6: sheet params readable (${e.message})")
    }
}

/** v0.11.0e section: the winter carnival. */
private fun sectionV0110e(root: String) {
// ================= v0.11.0e: the winter carnival =================
// Queue #11 item 5. The county fair's winter counterpart:
// one week in deep winter at Stark's Pond — the third
// Saturday of January, needing NO shift because the suite
// sweeps four decades of real dates in ONE ordinal space
// against every finale window, every holiday window and
// the fair's own week (the polish-#10 lesson, applied at
// design time). Ice fishing on the real catch table under
// the fair's exact ledger discipline; a snow-sculpture
// contest judged like the yearbook (a stated formula over
// the filed build record, fact-only judge notes); a hot-
// drinks synergy with the player's stand at real prices
// and real presence; a gathering claim seated with the
// fair's; and a Journal page in the fair's pattern. All
// state rides life/lifeText — zero new save fields.
println("== v0.11.0e: the winter carnival — Queue #11 item 5 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.11.0e"),
        "carnival: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 85 / 0.11.0e")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "carnival: the source tree and its description agree — " +
            "97 Kotlin files (Carnival.kt is the one addition) " +
            "(counted $ktCount)")

    // ---------- wiring pins ----------
    val cSrc = File(root,
        "src/com/hunt3r/southparktown/Carnival.kt").readText()
    check(!cSrc.contains("import android"),
        "carnival: Carnival.kt is pure Kotlin — no platform imports")
    check(cSrc.contains("COCOA_RUSH") &&
        cSrc.contains("SCULPT_PER_SESSION") &&
        cSrc.contains("FISH_DAY"),
        "carnival: the dials are named constants (rush, formula, day)")
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    val carnClaim = engSrc.indexOf("Carnival.gatheringBlock")
    check(carnClaim > engSrc.indexOf("Fair.gatheringBlock") &&
        carnClaim < engSrc.indexOf("RivalCrew.gatheringBlock"),
        "carnival: the agenda claim seats immediately after " +
            "the fair's, before the rival crew's turf — one " +
            "festival family in the stack")
    check(engSrc.indexOf("Carnival.dailyRollover(state)") >
        engSrc.indexOf("Fair.dailyRollover(state)"),
        "carnival: Engine.onNewDay runs the carnival's mornings " +
            "beside the fair's, before the phone")
    val mgSrc = File(root,
        "src/com/hunt3r/southparktown/Minigames.kt").readText()
    check(mgSrc.contains("Carnival.onCatch(state, sp, s.sizeCm)"),
        "carnival: applyCatch funnels a pond catch to the " +
            "ice fishing beside the fair's own funnel")
    val standSrc = File(root,
        "src/com/hunt3r/southparktown/Stand.kt").readText()
    check(standSrc.contains("Carnival.cocoaRush(state, itemId)"),
        "carnival: the stand's purchase chance reads the " +
            "kettle rush from Carnival — one rule, one home")
    val phoneSrc = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    check(Phone.CARNIVAL in Phone.TRIGGERS &&
        phoneSrc.contains("Carnival.announceDue(state)"),
        "carnival: the phone knows the carnival trigger and " +
            "the harvest delivers the Mayor's text")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("Carnival.lookText(state, me.location)") &&
        gaSrc.contains("Carnival.menuOption(state, npcName)") &&
        gaSrc.contains("Carnival.buildSession(state)") &&
        gaSrc.contains("Carnival.drillFirstHole(state)") &&
        gaSrc.contains("Carnival.carnivalTokensByLoc(state)"),
        "carnival: GameActivity reads the Look, offers the " +
            "first hole, files sculpture sessions from the " +
            "pond hub, and carries the dressing tokens")
    val jaSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jaSrc.contains("sectionTitle(\"🎪 WINTER CARNIVAL\")") &&
        jaSrc.contains("Carnival.pageLines(state)"),
        "carnival: the Journal renders the 🎪 WINTER CARNIVAL " +
            "section from Carnival.pageLines")
    val saSrc = File(root,
        "src/com/hunt3r/southparktown/SceneArt.kt").readText()
    check(saSrc.contains("drawCarnivalDetails(") &&
        saSrc.contains("\"carn-holes\" in toks"),
        "carnival: SceneArt draws the carnival layer off the tokens")
    val depthIdx = Depth.EXTERIOR_LAYERS.indexOfFirst { it.id == "carnival" }
    val fairIdx = Depth.EXTERIOR_LAYERS.indexOfFirst { it.id == "fair" }
    check(depthIdx > fairIdx && depthIdx > 0 &&
        Depth.EXTERIOR_LAYERS[depthIdx].band == Band.BACKGROUND,
        "carnival: Depth registers the carnival layer at " +
            "BACKGROUND, right after the fair's")
    // spoiler hygiene: the module's writing never touches
    // sealed ground (structure words only, as ever)
    for (sealed in listOf("mystery", "culprit", "solution", "whodunit")) {
        check(!cSrc.lowercase().contains(sealed),
            "carnival: the module's writing stays clear of " +
                "sealed ground ($sealed)")
    }

    // ---------- helpers ----------
    val engE = Engine(911_005)
    fun freshE(): GameState {
        val s = engE.newState()
        engE.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun keyE(y: Int, m: Int, d: Int) = "%04d%02d%02d".format(y, m, d)
    fun setDateE(s: GameState, y: Int, m: Int, d: Int, timeMin: Int) {
        s.gameYear = y; s.gameMonth = m; s.gameDay = d
        s.todayKey = keyE(y, m, d)
        s.absDay = FairCalendar.absDayOfOrdinal(ordinalOfKey(s.todayKey))
        s.timeMin = timeMin
        s.holidayId = null
    }
    fun placeE(s: GameState, who: String, loc: String) {
        val a = s.agents[who]!!
        a.location = loc; a.destination = loc; a.waypoints.clear()
    }
    fun placePlayerE(s: GameState, loc: String) {
        val me = engE.player(s)
        me.location = loc; me.destination = loc; me.waypoints.clear()
    }
    val carn27 = CarnivalCalendar.windowFor(2027)
    fun carnDateE(dayIdx: Int) = keyFromOrdinal(carn27.startOrd + dayIdx)
        .let { Triple(it.substring(0, 4).toInt(),
            it.substring(4, 6).toInt(), it.substring(6, 8).toInt()) }

    // ---------- the calendar: anchor, shape, January ----------
    check(carn27.startOrd == ordinalOfKey("20270116"),
        "carnival: 2027's carnival opens on the third " +
            "Saturday of January — Jan 16 (got " +
            "${keyFromOrdinal(carn27.startOrd)})")
    var shapeOk = true
    for (y in 2026..2065) {
        val w = CarnivalCalendar.windowFor(y)
        if (FairCalendar.dowOfOrdinal(w.startOrd) != 6) shapeOk = false
        if (w.endOrd - w.startOrd != 6) shapeOk = false
        val sk = keyFromOrdinal(w.startOrd)
        if (sk.substring(4, 6) != "01") shapeOk = false
        if (sk.substring(6, 8).toInt() !in 15..21) shapeOk = false
        if (CarnivalCalendar.windowAtOrdinal(w.startOrd + 3)?.year != y)
            shapeOk = false
        if (CarnivalCalendar.windowAtOrdinal(w.startOrd - 1) != null &&
            CarnivalCalendar.windowAtOrdinal(w.startOrd - 1)?.year == y)
            shapeOk = false
    }
    check(shapeOk, "carnival: across 2026-2065 every carnival " +
        "opens on a Saturday in mid-January (the 15th-21st), " +
        "runs exactly seven days, and the window lookup " +
        "round-trips mid-week")

    // ---------- THE SWEEP: disjointness in ONE lived space ----------
    // The polish-#10 lesson: two rhythms computed in
    // different day-spaces shared a Saturday for a month
    // of builds. Here every window — the carnival's, all
    // four season finales', every holiday's, the summer
    // fair's — is built as a range of REAL Gregorian
    // ordinals and compared in that one space, over forty
    // years of lived dates.
    fun finaleRanges(year: Int): List<IntRange> {
        val out = mutableListOf<IntRange>()
        for (season in Season.values()) {
            for (iy in (year - 1)..(year + 1)) {
                val (m, d) = Finales.seasonEndMonthDay(season, iy)
                val end = ordinalOfKey(keyE(iy, m, d))
                out += (end - (Finales.WINDOW_DAYS - 1))..end
            }
        }
        return out
    }
    fun holidayRanges(year: Int): List<IntRange> {
        val out = mutableListOf<IntRange>()
        for (h in HOLIDAYS) {
            for (yy in (year - 1)..(year + 1)) {
                val start = ordinalOfKey("%04d%s".format(yy, h.startMd))
                val end = if (h.startMd <= h.endMd)
                    ordinalOfKey("%04d%s".format(yy, h.endMd))
                else ordinalOfKey("%04d%s".format(yy + 1, h.endMd))
                out += start..end
            }
        }
        return out
    }
    fun overlaps(a: IntRange, b: IntRange): Boolean =
        a.first <= b.last && b.first <= a.last
    var vsFinales = true
    var vsHolidays = true
    var vsFair = true
    for (y in 2026..2065) {
        val w = CarnivalCalendar.windowFor(y)
        val mine = w.startOrd..w.endOrd
        if (finaleRanges(y).any { overlaps(mine, it) }) vsFinales = false
        if (holidayRanges(y).any { overlaps(mine, it) }) vsHolidays = false
        for (yy in (y - 1)..(y + 1)) {
            val f = FairCalendar.windowFor(yy)
            if (overlaps(mine, f.startOrd..f.endOrd)) vsFair = false
        }
    }
    check(vsFinales, "carnival: in one lived ordinal space, " +
        "2026-2065, the carnival week NEVER touches any " +
        "season-finale window — the winter finale keeps the " +
        "last week of February, the carnival keeps deep January")
    check(vsHolidays, "carnival: in the same space, the " +
        "carnival week NEVER touches a holiday window — " +
        "not Christmas, not New Year, not Valentine's, " +
        "none of the eight on the town's books")
    check(vsFair, "carnival: in the same space, the two " +
        "festivals never share a day — the fair keeps " +
        "August, the carnival keeps January, forever")
    // the nearest hazards, named and measured
    val w27 = CarnivalCalendar.windowFor(2027)
    val winterFin27End = ordinalOfKey(keyE(2027, 2, 28))
    val winterFin27 = (winterFin27End - 6)..winterFin27End
    check(winterFin27.first - w27.endOrd >= 30,
        "carnival: 2027's clearance to the winter finale is " +
            "a full month (${winterFin27.first - w27.endOrd} days) — " +
            "the disjointness is structural, not a near miss")
    val valentine27 = ordinalOfKey("20270214")
    check(valentine27 > w27.endOrd && valentine27 < winterFin27.first,
        "carnival: Valentine's Day threads between the " +
            "carnival and the finale without touching either")

    // ---------- the week lived: opening, gathering, the hole ----------
    run {
        val s = freshE()
        val (y0, m0, d0) = carnDateE(0)
        setDateE(s, y0, m0, d0, 9 * 60)
        check(!Carnival.isCarnivalWeek(s) ||
            Carnival.recordFor(s, 2027) == null,
            "carnival: before the opening rollover there is " +
                "week but no record — the record is born at dawn")
        Carnival.dailyRollover(s)
        check(Carnival.isCarnivalWeek(s) && Carnival.dayIndex(s) == 0 &&
            Carnival.recordFor(s, 2027) != null,
            "carnival: opening morning births the record and " +
                "the week stands")
        setDateE(s, y0, m0, d0, 12 * 60)
        val block = Carnival.gatheringBlock(s, "Liane", 12 * 60)
        check(block != null && block.location == Carnival.GROUND,
            "carnival: at noon on opening day the town gathers " +
                "at the pond")
        check(Carnival.gatheringBlock(s, "Liane", 9 * 60) == null &&
            Carnival.gatheringBlock(s, "Liane", 20 * 60) == null,
            "carnival: the claim holds carnival hours only — " +
                "10:00 to 20:00, not a minute of the morning")
        val (y6, m6, d6) = carnDateE(6)
        setDateE(s, y6, m6, d6, 21 * 60)
        check(Carnival.gatheringBlock(s, "Liane", 21 * 60)?.location ==
            Carnival.GROUND &&
            Carnival.gatheringBlock(s, "Liane", 22 * 60) == null,
            "carnival: closing night the claim runs to the " +
                "lantern skate (21:30) and no later")
        // the first hole: Jimbo, opening day, at the pond
        setDateE(s, y0, m0, d0, 12 * 60)
        placePlayerE(s, Carnival.GROUND)
        placeE(s, "Jimbo", Carnival.GROUND)
        check(Carnival.menuOption(s, "Jimbo") == Carnival.OPT_HOLE &&
            Carnival.menuOption(s, "Liane") == null,
            "carnival: the first hole is offered on Jimbo " +
                "alone, at the pond, on opening day")
        val jimboBefore = s.friendship["Jimbo"] ?: 0
        val line = Carnival.drillFirstHole(s)
        check(line.isNotEmpty() && Carnival.holeDrilled(s, 2027) &&
            (s.friendship["Jimbo"] ?: 0) == jimboBefore + 2 &&
            Carnival.drillFirstHole(s).isEmpty(),
            "carnival: drilling the first hole lands once — " +
                "the mark, Jimbo's +2, and no second drilling")
        check(Carnival.attended(s, 2027),
            "carnival: the opening beat marks the week attended")
        // look + poster
        val look0 = Carnival.lookText(s, Carnival.GROUND)
        check(look0 != null && look0.contains("OPENING DAY"),
            "carnival: the pond's Look carries opening day")
        val (yp, mp, dp) = carnDateE(0)
        val pre = freshE()
        val preOrd = carn27.startOrd - 2
        val preKey = keyFromOrdinal(preOrd)
        setDateE(pre, preKey.substring(0, 4).toInt(),
            preKey.substring(4, 6).toInt(),
            preKey.substring(6, 8).toInt(), 12 * 60)
        check(Carnival.lookText(pre, Carnival.GROUND)
            ?.contains("WINTER CARNIVAL") == true &&
            Carnival.announceDue(pre) == false,
            "carnival: two days out the poster is up at the " +
                "pond hut (the phone text waits for three-out)")
        val ann = freshE()
        val annKey = keyFromOrdinal(carn27.startOrd - 3)
        setDateE(ann, annKey.substring(0, 4).toInt(),
            annKey.substring(4, 6).toInt(),
            annKey.substring(6, 8).toInt(), 8 * 60)
        check(Carnival.announceDue(ann),
            "carnival: three mornings out the announcement is due")
        Carnival.dailyRollover(ann)
        check(ann.events.any { it.contains("winter carnival") },
            "carnival: the announcement morning puts the week " +
                "on the ticker")
    }

    // ---------- the sculpture contest ----------
    run {
        // the formula, unit-pinned off its own stated dials
        check(Carnival.sculptScore(emptyList()) == 0 &&
            Carnival.weatherAdj("blizzard") == Carnival.SCULPT_WX_SNOW &&
            Carnival.weatherAdj("fog") == Carnival.SCULPT_WX_GREY &&
            Carnival.weatherAdj("sunny") == Carnival.SCULPT_WX_SUN &&
            Carnival.weatherAdj("rain") == 0,
            "carnival: the weather read is the stated one — " +
                "snow packs, grey holds, sun melts, rain is weather")
        val perfect = (0..2).flatMap { d ->
            listOf(d to "heavy_snow", d to "heavy_snow") }
        check(Carnival.sculptScore(perfect) == 128,
            "carnival: a perfect build — six sessions, three " +
                "days, all in falling snow — scores exactly 128 " +
                "by the stated formula")
        check((0..5).all { i ->
            Carnival.npcSculptScore(2027 + i, "Stan") in
                Carnival.SCULPT_NPC_BASE..
                    (Carnival.SCULPT_NPC_BASE + Carnival.SCULPT_NPC_SPREAD - 1)
        }, "carnival: the town's seeded pieces land inside " +
            "the stated band, every year")
        check(Carnival.sculptScore(perfect) >
            Carnival.npcSculptScore(2027, "Stan") ||
            Carnival.sculptScore(perfect) >= 120,
            "carnival: a fully worked piece stands at the top " +
                "of the field's scale — the work CAN win")

        val s = freshE()
        val (y0, m0, d0) = carnDateE(0)
        setDateE(s, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(s)
        setDateE(s, y0, m0, d0, 12 * 60)
        placePlayerE(s, Carnival.GROUND)
        s.weatherId = "light_snow"
        check(Carnival.buildOpen(s),
            "carnival: a build session is on the table at the " +
                "pond on a build day in carnival hours")
        val l1 = Carnival.buildSession(s)
        val l2 = Carnival.buildSession(s)
        check(l1 != null && l2 != null &&
            Carnival.sessionsToday(s) == 2 &&
            Carnival.buildSession(s) == null,
            "carnival: two sessions a day file, the third is " +
                "refused — the day is spent")
        check(Carnival.playerSculptScore(s, 2027) == 36,
            "carnival: two snowy sessions on one day score " +
                "2×12 + 2×6 = 36 off the filed record")
        val (y1, m1, d1) = carnDateE(1)
        setDateE(s, y1, m1, d1, 12 * 60)
        s.weatherId = "sunny"
        Carnival.buildSession(s)
        check(Carnival.playerSculptScore(s, 2027) == 51,
            "carnival: a sunny comeback session adds 12 + 10 " +
                "(the second day) − 7 (the melt) — the record " +
                "keeps the weather it was built under")
        // off the ground / off the days: no session
        val away = freshE()
        setDateE(away, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(away)
        setDateE(away, y0, m0, d0, 12 * 60)
        placePlayerE(away, "KidsPark")
        check(!Carnival.buildOpen(away) &&
            Carnival.buildSession(away) == null,
            "carnival: no building from the park — the row " +
                "is at the pond")
        // judging on day 3's morning, by the yearbook desk
        val (y3, m3, d3) = carnDateE(3)
        setDateE(s, y3, m3, d3, 9 * 60)
        val coinsBefore = Minigames.capsuleCoins(s)
        Carnival.dailyRollover(s)
        val rec = Carnival.recordFor(s, 2027)!!
        check(rec.sculptPlaces.size == 3 &&
            rec.sculptJudge == Carnival.sculptJudgeFor(2027).name &&
            rec.sculptNote.isNotEmpty(),
            "carnival: judging files three places, the " +
                "yearbook desk's judge, and their note")
        check(rec.sculptPlaces.zipWithNext()
                .all { (a, b) -> a.score >= b.score },
            "carnival: the places stand in score order")
        val myPlace = rec.sculptPlaces.indexOfFirst {
            it.name == "Walker" } + 1
        check(rec.playerSculpt == myPlace,
            "carnival: your recorded place is the place the " +
                "table shows — one source of truth")
        val expectCoins = if (myPlace in 1..3)
            Fair.PLACE_COINS[myPlace - 1] else 0
        check(Minigames.capsuleCoins(s) - coinsBefore == expectCoins,
            "carnival: a placed sculpture pays the fair's " +
                "own capsule table — 6/4/2, no new economy")
        if (myPlace == 1) {
            check(rec.sculptNote.contains("3") &&
                rec.sculptNote.contains("51"),
                "carnival: a winning note cites the record — " +
                    "the sessions and the score, nothing invented")
        }
        // judging runs once
        val recBefore = Carnival.recordFor(s, 2027)
        Carnival.judgeSculpt(s, carn27)
        check(Carnival.recordFor(s, 2027) == recBefore,
            "carnival: the sculpture judging is a one-time " +
                "morning — a second call changes nothing")
        // the record round-trips through lifeText alone
        val raw = s.lifeText["carnRec:2027"]
        check(raw != null && Carnival.recordFor(s, 2027) == rec &&
            Carnival.records(s).map { it.year } == listOf(2027),
            "carnival: the whole record rides one lifeText " +
                "line and reads back whole")
    }

    // ---------- the ice fishing contest + the ledger ----------
    run {
        val s = freshE()
        val (y0, m0, d0) = carnDateE(0)
        setDateE(s, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(s)
        val (y3, m3, d3) = carnDateE(Carnival.FISH_DAY)
        setDateE(s, y3, m3, d3, 11 * 60)
        placePlayerE(s, Carnival.GROUND)
        val smelt = fishById("pond_smelt")!!
        val boot = FISH_TABLE.first { it.id == "old_boot" }
        Carnival.onCatch(s, smelt, 18)
        Carnival.onCatch(s, boot, 30)
        check(Carnival.playerFishEntry(s, 2027)?.first?.id ==
            "pond_smelt",
            "carnival: through the ice, a boot still never " +
                "displaces a fish")
        val carp = FISH_TABLE.minByOrNull { Rival.fishRank(it) }!!
        Carnival.onCatch(s, carp, 41)
        check(Carnival.playerFishEntry(s, 2027)?.first?.id == carp.id,
            "carnival: a rarer fish takes the entry — rank " +
                "first, then size, the real table's own values")
        val field = Carnival.fishField(s, 2027)
        check("Jimbo" in field && Rival.rivalOf(s) in field,
            "carnival: the ice field holds Jimbo and the " +
                "rival — authored entrants, one cast each")
        val before = Rival.winsYou(s) + Rival.winsThem(s) +
            Rival.draws(s)
        Carnival.judgeFish(s, carn27)
        val rec = Carnival.recordFor(s, 2027)!!
        check(rec.fishPlaces.size == 3 &&
            Rival.winsYou(s) + Rival.winsThem(s) + Rival.draws(s) ==
                before + 1,
            "carnival: with both rivals entered and no duel " +
                "armed, the carnival result lands on the 🆚 " +
                "ledger exactly once, through Rival's own path")
        check(s.life["carnLedger:2027"] == 1,
            "carnival: the ledger write is stamped — it can " +
                "never land twice")
        // and with an armed fishing duel, the carnival keeps its page
        val s2 = freshE()
        setDateE(s2, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(s2)
        setDateE(s2, y3, m3, d3, 11 * 60)
        placePlayerE(s2, Carnival.GROUND)
        Carnival.onCatch(s2, smelt, 18)
        s2.lifeText["rivalPending"] = Rival.K_FISHING
        val before2 = Rival.winsYou(s2) + Rival.winsThem(s2) +
            Rival.draws(s2)
        Carnival.judgeFish(s2, carn27)
        check(Rival.winsYou(s2) + Rival.winsThem(s2) +
            Rival.draws(s2) == before2,
            "carnival: a carnival result NEVER double-counts " +
                "— an armed duel owns the ledger that week")
        // off the day / off the pond: no funnel
        val s3 = freshE()
        val (y2, m2, d2) = carnDateE(2)
        setDateE(s3, y2, m2, d2, 11 * 60)
        placePlayerE(s3, Carnival.GROUND)
        Carnival.onCatch(s3, carp, 41)
        check(Carnival.playerFishEntry(s3, 2027) == null,
            "carnival: a pond catch on a non-contest day is " +
                "just a catch — the funnel is day-3 honest")
        // applyCatch itself funnels on the day (the real path)
        val s4 = freshE()
        setDateE(s4, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(s4)
        setDateE(s4, y3, m3, d3, 11 * 60)
        placePlayerE(s4, Carnival.GROUND)
        val sess = FishingSession(42L, "light_snow", 11)
        sess.tap(sess.biteAtMs)
        if (sess.outcome == FishingSession.Outcome.CAUGHT) {
            applyCatch(s4, sess)
            check(Carnival.playerFishEntry(s4, 2027) != null,
                "carnival: a real applyCatch on ice fishing " +
                    "day files the contest entry")
        } else {
            check(true, "carnival: applyCatch funnel (seed " +
                "escaped — the direct funnel pins above stand)")
        }
    }

    // ---------- hot drinks: the stand synergy ----------
    run {
        val s = freshE()
        val (y0, m0, d0) = carnDateE(0)
        setDateE(s, y0, m0, d0, 12 * 60)
        Carnival.dailyRollover(s)
        Minigames.awardCoins(s, 200)
        val stood = Stand.setup(s, Carnival.GROUND)
        check(Stand.hasStand(s) && Stand.locOf(s) == Carnival.GROUND,
            "carnival: (fabrication) the stand stands at the " +
                "pond pitch — $stood")
        // one sky for every comparison below: a cloudy day
        // prices hot chocolate and lemonade identically in
        // every season, so any difference is the rush alone
        s.weatherId = "cloudy"
        val inWeek = Stand.purchaseChance(s, "Stan",
            Carnival.COCOA_ITEM, false)
        val july = freshE()
        setDateE(july, 2027, 7, 10, 12 * 60)
        Minigames.awardCoins(july, 200)
        Stand.setup(july, Carnival.GROUND)
        july.weatherId = "cloudy"
        val inJuly = Stand.purchaseChance(july, "Stan",
            Carnival.COCOA_ITEM, false)
        check(inJuly > 0.0 && inWeek > inJuly &&
            kotlin.math.abs(inWeek / inJuly - Carnival.COCOA_RUSH) < 0.001,
            "carnival: at the pond pitch, carnival week buys " +
                "hot chocolate at exactly the stated rush " +
                "(×${Carnival.COCOA_RUSH}) — and July buys it plain")
        val lemonade = Stand.purchaseChance(s, "Stan", "lemonade", false)
        val julyStand2 = freshE()
        setDateE(julyStand2, 2027, 7, 10, 12 * 60)
        Minigames.awardCoins(julyStand2, 200)
        Stand.setup(julyStand2, Carnival.GROUND)
        julyStand2.weatherId = "cloudy"
        val lemonadeJuly = Stand.purchaseChance(julyStand2, "Stan",
            "lemonade", false)
        check(kotlin.math.abs(lemonade / lemonadeJuly - 1.0) < 0.001 ||
            lemonade == lemonadeJuly,
            "carnival: the rush is hot chocolate's alone — " +
                "lemonade prices exactly as it does in July")
        val parkPitch = freshE()
        setDateE(parkPitch, y0, m0, d0, 12 * 60)
        Minigames.awardCoins(parkPitch, 200)
        Stand.setup(parkPitch, "KidsPark")
        parkPitch.weatherId = "cloudy"
        val parkWeek = Stand.purchaseChance(parkPitch, "Stan",
            Carnival.COCOA_ITEM, false)
        check(kotlin.math.abs(parkWeek / inJuly - 1.0) < 0.001 ||
            parkWeek == inJuly,
            "carnival: a park pitch in carnival week gets no " +
                "rush — the kettle crowd is at the pond")
        check(Carnival.cocoaRush(s, Carnival.COCOA_ITEM) ==
            Carnival.COCOA_RUSH &&
            Carnival.cocoaRush(s, "lemonade") == 1.0 &&
            Carnival.cocoaRush(july, Carnival.COCOA_ITEM) == 1.0,
            "carnival: the rush reads week + pitch + item, " +
                "and nothing else in town moves")
        // the page states the synergy where the player reads it
        check(Carnival.pageLines(s).any { it.contains("kettle rush") },
            "carnival: the Journal page states the synergy " +
                "for a pond-pitched stand, in the open")
    }

    // ---------- dressing, the wrap, the page ----------
    run {
        val s = freshE()
        val (y0, m0, d0) = carnDateE(0)
        setDateE(s, y0, m0, d0, 12 * 60)
        val toks = Carnival.carnivalTokensByLoc(s)
        val saSrc2 = File(root,
            "src/com/hunt3r/southparktown/SceneArt.kt").readText()
        check(toks[Carnival.GROUND]?.toSet() == Carnival.CARN_TOKENS &&
            Carnival.CARN_TOKENS.all { saSrc2.contains("\"$it\" in toks") },
            "carnival: during the week the pond carries the " +
                "carnival tokens, and SceneArt draws every one")
        val after = freshE()
        val postKey = keyFromOrdinal(carn27.endOrd + 3)
        setDateE(after, postKey.substring(0, 4).toInt(),
            postKey.substring(4, 6).toInt(),
            postKey.substring(6, 8).toInt(), 12 * 60)
        check(Carnival.carnivalTokensByLoc(after).isEmpty(),
            "carnival: three days after closing the pond is " +
                "a pond again — the strike is the calendar turning")
        // a slept-through carnival wraps honestly missed
        val slept = freshE()
        setDateE(slept, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(slept)
        setDateE(slept, postKey.substring(0, 4).toInt(),
            postKey.substring(4, 6).toInt(),
            postKey.substring(6, 8).toInt(), 9 * 60)
        Carnival.dailyRollover(slept)
        val sleptRec = Carnival.recordFor(slept, 2027)
        check(sleptRec != null && sleptRec.wrapped && sleptRec.missed &&
            !sleptRec.attended && sleptRec.fishPlaces.size == 3 &&
            sleptRec.sculptPlaces.size == 3,
            "carnival: a slept-through week still judges both " +
                "contests off their seeds and wraps MISSED — " +
                "the record doesn't pretend you were there")
        check(Carnival.pageLines(slept).any {
            it.contains("you missed it") },
            "carnival: the page says the missed week plainly")
        // an attended carnival wraps attended, elders one-line
        val went = freshE()
        setDateE(went, y0, m0, d0, 9 * 60)
        Carnival.dailyRollover(went)
        setDateE(went, y0, m0, d0, 12 * 60)
        placePlayerE(went, Carnival.GROUND)
        placeE(went, "Jimbo", Carnival.GROUND)
        Carnival.drillFirstHole(went)
        setDateE(went, postKey.substring(0, 4).toInt(),
            postKey.substring(4, 6).toInt(),
            postKey.substring(6, 8).toInt(), 9 * 60)
        Carnival.dailyRollover(went)
        val wentRec = Carnival.recordFor(went, 2027)
        check(wentRec != null && wentRec.wrapped &&
            wentRec.attended && !wentRec.missed,
            "carnival: a lived week wraps ATTENDED")
        check(Carnival.indexLine(wentRec!!).contains("2027") &&
            Carnival.pageLines(went).any {
                it.contains("the carnival of 2027") },
            "carnival: the page shows the newest carnival " +
                "whole and indexes elders by year")
    }
}
}

// ================= v0.11.0f: mystery #9 — one more than counted =================
// Queue #11 item 6. The ninth case is a ninth shape: an
// AUDIT LEDGER. Nothing was taken; four public counts
// come back one MORE than their books hold. The board
// holds four count-sites — a counted set against its
// book, the discrepancy derived from the two numbers —
// and the player commits a reconciliation call per
// site: THE COUNT IS WRONG, THE RECORD IS WRONG, or
// SOMEONE ADDED ONE; each site's one settling piece
// grades the call — verdicts derived, never stored.
// This section pins the registries, the derivation (by
// independent recomputation over every evidence
// subset), the call discipline (standing calls can't
// be re-called; refuted ones must be), the finale's
// gates on the ledger's final state, the landings and
// their persistence, the nine-case lifetime, and the
// spoiler wall over every pre-reveal surface.
private fun sectionV0110f(root: String) {
    println("== v0.11.0f: mystery #9 — one more than counted ==")
    val eng9 = Engine(920)

    // ---------- the chapter defs ----------
    val ch9 = Mystery9.CHAPTERS9
    check(ch9.size == 4 && ch9.map { it.id }.toSet().size == 4,
        "audit: the case is four chapters, uniquely id'd")
    check(ch9[3].id == Mystery9.FINALE9_ID,
        "audit: the fourth chapter is the finale — the Reckoning, in the chamber")
    check(ch9.all { it.theme.icon.isNotBlank() &&
        it.theme.header.isNotBlank() && it.causers.isNotEmpty() },
        "audit: every chapter carries its theme and its credited causers")
    check(ch9.all { d -> d.stages.size == 4 && d.episodeTitles.size == 2 &&
        d.coldOpen.size == 2 && d.coldOpen.all { it.text.isNotBlank() } },
        "audit: every chapter carries the full episode kit")
    check(ch9.none { d -> SHENANIGANS.any { it.id == d.id } },
        "audit: no chapter sits in the random event pool")
    check(ch9.all { Mystery9.CHAPTER9_BY_ID[it.id] == it &&
        SHENANIGAN_BY_ID[it.id] == it },
        "audit: every chapter resolves by id, in the case and in the game")
    check(ch9[0].stages.any { it.clusterLoc == "CityHall" } &&
        ch9[0].stages.any { it.clusterLoc == "Elementary" } &&
        ch9[1].stages.any { it.clusterLoc == "Bijou" } &&
        ch9[2].stages.any { it.clusterLoc == "Bank" } &&
        ch9[3].stages.take(3).all { it.clusterLoc == "CityHall" } &&
        ch9[3].stages[3].clusterLoc == null,
        "audit: the chapters walk the hall, the shelf, the theater, the bank, and back to the chamber — whose last stage walks everybody home")
    val finDef9 = Mystery9.CHAPTER9_BY_ID[Mystery9.FINALE9_ID]!!
    check(finDef9.causers.containsAll(listOf("McDaniels", "Adler")),
        "audit: the reckoning is played by the keeper of the count and the man in its third row")

    // ---------- the sites (the ledger's rows) ----------
    val sites9 = Mystery9.SITES9
    check(sites9.size == 4 && Mystery9.SITE9_BY_ID.size == 4 &&
        sites9.map { it.index } == listOf(0, 1, 2, 3),
        "audit: four count-sites, declared in board order")
    check(sites9.all { it.place in LOCATIONS && it.keeper.isNotBlank() &&
        it.countedLabel.isNotBlank() && it.recordLabel.isNotBlank() },
        "audit: every site stands in a real place, kept by a named book")
    check(sites9.all { Mystery9.discrepancy9(it) == 1 },
        "audit: every site's derived discrepancy is exactly +1 — one more than counted, four times")
    check(sites9.map { it.truth } ==
        listOf("added", "record", "count", "record"),
        "audit: the four sites settle three ways — one true addition, two short books, one bad count")
    check(sites9.all { s ->
        val proof = Mystery9.CLUE9_BY_ID[s.proofBy]
        proof != null && proof.site == s.index && s.callPrice == 2 &&
            s.truth in Mystery9.CALL_KEYS },
        "audit: every site is settled by exactly one piece tagged to itself, at the standing price")
    check(sites9[0].minChapter == 1 && sites9[1].minChapter == 1 &&
        sites9[2].minChapter == 2 && sites9[3].minChapter == 2,
        "audit: the case and the seats open in the counted-in-person week; the boxes and the gallery wait for the books")

    // ---------- the evidence registry ----------
    val clues9 = Mystery9.CLUES9
    check(clues9.size == 12 && Mystery9.CLUE9_IDS.size == 12,
        "audit: the evidence is twelve pieces")
    check(clues9.count { it.kind == Mystery9.Kind9.WITNESS } == 5 &&
        clues9.count { it.kind == Mystery9.Kind9.LOOK } == 5 &&
        clues9.count { it.kind == Mystery9.Kind9.PARTICIPATION } == 2,
        "audit: the verbs run 5 witness / 5 look / 2 participation")
    check((0..3).all { idx -> clues9.count { it.site == idx } == 3 },
        "audit: three pieces are tagged to every site")
    check(clues9.all { c -> c.minChapter in 0..3 &&
        c.unlockChapter in c.minChapter..3 &&
        when (c.kind) {
            Mystery9.Kind9.WITNESS ->
                c.npc != null && c.npc in AGENT_PROFILES &&
                    !c.spoken.isNullOrBlank()
            Mystery9.Kind9.LOOK ->
                c.locId != null && c.locId in LOCATIONS &&
                    !c.foundText.isNullOrBlank()
            Mystery9.Kind9.PARTICIPATION ->
                c.chapterDefId != null &&
                    c.chapterDefId in Mystery9.CHAPTER9_BY_ID
        } },
        "audit: every piece names a real witness, place, or chapter")
    val locked9 = clues9.filter { it.unlockChapter > it.minChapter }
    check(locked9.map { it.id }.toSet() ==
        setOf("county_form", "succession_page") &&
        locked9.all { it.inertDetail != it.detail && it.inertDetail.isNotBlank() },
        "audit: exactly two pieces are context-locked, each with an honest inert face")
    check(Mystery9.CLUE9_BY_ID["county_form"]!!.unlockChapter == 2 &&
        sites9[0].proofBy == "county_form" &&
        Mystery9.CLUE9_BY_ID["succession_page"]!!.unlockChapter == 3 &&
        sites9[3].proofBy == "succession_page",
        "audit: THE STING — both load-bearing proofs are the locked pieces: the form reads only in the books week, the shorthand page only in the reckoning's: the two rows that matter most can only be proven late")

    // ---------- independent recomputation (the suite's own math) ----------
    fun recompVerdict9(held: Set<String>,
                       calls: Map<String, String>,
                       s: Mystery9.Site9): String {
        val c = calls[s.id] ?: return "OPEN"
        if (s.proofBy !in held) return "COMMITTED"
        return if (c == s.truth) "PROVEN" else "REFUTED"
    }
    var sweepOk9 = true
    for (mask in 0 until (1 shl clues9.size)) {
        val s = eng9.newState()
        s.arc9Chapter = 4
        clues9.forEachIndexed { i, c ->
            if (mask shr i and 1 == 1) s.mystery9Clues.add(c.id)
        }
        val held = s.mystery9Clues.toSet()
        // two call schemes over the same evidence mask, so
        // calls and holdings vary independently
        for (scheme in 0..1) {
            val calls = mutableMapOf<String, String>()
            for (site in sites9) {
                val code = if (scheme == 0)
                    (mask shr (2 * site.index)) and 3
                else ((mask shr 3) + site.index) % 4
                when (code) {
                    1 -> calls[site.id] = "count"
                    2 -> calls[site.id] = "record"
                    3 -> calls[site.id] = "added"
                }
            }
            s.arc9Calls.clear(); s.arc9Calls.putAll(calls)
            val verdicts = sites9.associate { site ->
                site.id to recompVerdict9(held, calls, site) }
            for (site in sites9) {
                if (Mystery9.siteVerdict9(s, site) != verdicts[site.id])
                    sweepOk9 = false
                if (Mystery9.liveEvidence9(s, site) !=
                    held.count { Mystery9.CLUE9_BY_ID[it]!!.site == site.index })
                    sweepOk9 = false
            }
            val proven = verdicts.values.count { it == "PROVEN" }
            val refuted = verdicts.values.count { it == "REFUTED" }
            val allCalled = sites9.all { it.id in calls }
            if (Mystery9.provenCount9(s) != proven ||
                Mystery9.refutedCount9(s) != refuted ||
                Mystery9.calledCount9(s) != calls.size ||
                Mystery9.ledgerCalled9(s) != allCalled ||
                Mystery9.ledgerClean9(s) != (refuted == 0) ||
                Mystery9.nameEligible9(s) != (proven >= 1) ||
                Mystery9.readEligible9(s) !=
                    (verdicts[sites9[0].id] == "PROVEN" &&
                        verdicts[sites9[3].id] == "PROVEN" &&
                        allCalled && refuted == 0 && proven >= 3) ||
                Mystery9.liveClueIds9(s) != held)
                sweepOk9 = false
        }
    }
    check(sweepOk9,
        "audit: verdicts, counts and both finale gates recompute exactly over all 4096 evidence subsets, under two call schemes")
    var lockOk9 = true
    for (ch in 0..5) for (c in locked9) {
        val s = eng9.newState()
        s.arc9Chapter = ch
        s.mystery9Clues.add(c.id)
        if (Mystery9.clueLive9(s, c) != (ch > c.unlockChapter)) lockOk9 = false
    }
    check(lockOk9,
        "audit: a locked piece is live exactly when its context chapter has begun — at every chapter boundary")

    // ---------- discovery: witnesses, looks, hands ----------
    val sDisc = eng9.newState()
    check(Mystery9.witnessLine9(sDisc, "Victoria") == null,
        "audit: no witness speaks before the case opens their week")
    sDisc.arc9Chapter = 1
    val vicLine = Mystery9.witnessLine9(sDisc, "Victoria")
    check(vicLine != null && vicLine.speaker == "Victoria" &&
        "victoria_count" in sDisc.mystery9Clues &&
        Mystery9.witnessLine9(sDisc, "Victoria") == null,
        "audit: a witness's telling grants its piece exactly once")
    val sLook = eng9.newState()
    sLook.arc9Chapter = 1
    val lookCup = Mystery9.lookClueText9(sLook, "Elementary")
    check(lookCup != null && "old_cup" in sLook.mystery9Clues &&
        Mystery9.lookClueText9(sLook, "Elementary") == null,
        "audit: the cup is found in the count week, at its shelf")
    sLook.arc9Chapter = 2
    val lookForm = Mystery9.lookClueText9(sLook, "CityHall")
    check(lookForm != null && "county_form" in sLook.mystery9Clues &&
        !Mystery9.clueLive9(sLook,
            Mystery9.CLUE9_BY_ID["county_form"]!!),
        "audit: the form is found in the counted week — in hand, honestly inert, settling nothing")
    check(Mystery9.lookClueText9(sLook, "CityHall") == null,
        "audit: the invoice and the portrait wait for the books week — the hall gives nothing more yet")
    sLook.arc9Chapter = 3
    check(Mystery9.lookClueText9(sLook, "CityHall") != null &&
        "renovation_invoice" in sLook.mystery9Clues &&
        Mystery9.lookClueText9(sLook, "CityHall") != null &&
        "extra_portrait" in sLook.mystery9Clues &&
        Mystery9.lookClueText9(sLook, "CityHall") == null &&
        Mystery9.lookClueText9(sLook, "Bank") != null &&
        "demo_box" in sLook.mystery9Clues,
        "audit: the books week opens the invoice and the portrait at the hall, and the shiny box at the bank")
    val sHands = eng9.newState()
    Mystery9.noteParticipation9(sHands, "arc9_ch2_counted")
    check(sHands.mystery9Clues.isEmpty(),
        "audit: hands in the theater find nothing before the second chapter airs")
    sHands.arc9Chapter = 2
    Mystery9.noteParticipation9(sHands, "arc9_ch2_counted")
    sHands.arc9Chapter = 3
    Mystery9.noteParticipation9(sHands, "arc9_ch3_books")
    check(sHands.mystery9Clues.containsAll(
            listOf("own_count", "succession_page")) &&
        !Mystery9.clueLive9(sHands,
            Mystery9.CLUE9_BY_ID["succession_page"]!!),
        "audit: participation grants your own count in the theater week and the shorthand page in the books week — the page in hand, inert, its context still coming")
    sHands.arc9Chapter = 4
    check(Mystery9.clueLive9(sHands,
            Mystery9.CLUE9_BY_ID["succession_page"]!!),
        "audit: the page becomes readable when the reckoning's week begins — context is a kind of paperwork")

    // ---------- the call discipline, played ----------
    val sPlay = eng9.newState()
    sPlay.arc9Chapter = 2
    for (id in listOf("victoria_count", "old_cup",
        "kenny_clicker", "own_count"))
        Mystery9.grantClue9(sPlay, id)
    check(Mystery9.pendingSite9(sPlay)?.id == "site_trophies",
        "audit: the trophy case is offered first, in board order, at its price")
    check(Mystery9.chooseCall9(sPlay, "site_trophies", "count") &&
        Mystery9.siteVerdict9(sPlay, sites9[0]) == "COMMITTED",
        "audit: a call written before its settling piece surfaces stands COMMITTED, untested")
    check(!Mystery9.chooseCall9(sPlay, "site_trophies", "added"),
        "audit: a standing call cannot be re-called — only a refuted one can")
    check(Mystery9.pendingSite9(sPlay)?.id == "site_seats" &&
        Mystery9.chooseCall9(sPlay, "site_seats", "record") &&
        Mystery9.siteVerdict9(sPlay, sites9[1]) == "COMMITTED",
        "audit: the seats called on the chart's behalf, untested — the invoice is still in its cabinet")
    Mystery9.grantClue9(sPlay, "county_form")
    check(Mystery9.siteVerdict9(sPlay, sites9[0]) == "COMMITTED" &&
        !Mystery9.clueLive9(sPlay,
            Mystery9.CLUE9_BY_ID["county_form"]!!),
        "audit: the held-but-inert form settles nothing — holding is not knowing")
    sPlay.arc9Chapter = 3
    check(Mystery9.siteVerdict9(sPlay, sites9[0]) == "REFUTED",
        "audit: when the form's context arrives, the standing call flips to REFUTED on its own — nothing was edited; the paper simply became readable")
    for (id in listOf("renovation_invoice", "butters_boxes",
        "gerald_footnote", "demo_box", "mcdaniels_gallery",
        "extra_portrait"))
        Mystery9.grantClue9(sPlay, id)
    check(Mystery9.siteVerdict9(sPlay, sites9[1]) == "PROVEN",
        "audit: the invoice, live, proves the seats call the chart couldn't make for itself")
    check(Mystery9.pendingSite9(sPlay)?.id == "site_boxes" &&
        Mystery9.chooseCall9(sPlay, "site_boxes", "record") &&
        Mystery9.siteVerdict9(sPlay, sites9[2]) == "REFUTED",
        "audit: call against the live settling piece and the call is refuted on arrival")
    check(Mystery9.pendingSite9(sPlay)?.id == "site_portraits" &&
        Mystery9.chooseCall9(sPlay, "site_portraits", "record") &&
        Mystery9.siteVerdict9(sPlay, sites9[3]) == "COMMITTED",
        "audit: new calls come before revisions — the gallery is offered while two sites stand struck; its page is still shorthand")
    check(Mystery9.pendingSite9(sPlay)?.id == "site_trophies" &&
        Mystery9.chooseCall9(sPlay, "site_trophies", "added") &&
        Mystery9.siteVerdict9(sPlay, sites9[0]) == "PROVEN",
        "audit: a refuted site is offered again — in board order, the trophy case first — and, called as the form settles it, stands proven")
    check(Mystery9.pendingSite9(sPlay)?.id == "site_boxes" &&
        Mystery9.chooseCall9(sPlay, "site_boxes", "count") &&
        Mystery9.siteVerdict9(sPlay, sites9[2]) == "PROVEN",
        "audit: the boxes' revision follows — struck calls are struck and re-called until the ledger is clean")
    Mystery9.grantClue9(sPlay, "succession_page")
    sPlay.arc9Chapter = 4
    check(Mystery9.siteVerdict9(sPlay, sites9[3]) == "PROVEN",
        "audit: the gallery's standing call proves itself the morning its page becomes readable — no edit, no re-call; context is a kind of paperwork")
    check(Mystery9.ledgerCalled9(sPlay) && Mystery9.ledgerClean9(sPlay) &&
        Mystery9.provenCount9(sPlay) == 4 &&
        Mystery9.readEligible9(sPlay) && Mystery9.nameEligible9(sPlay) &&
        Mystery9.pendingSite9(sPlay) == null,
        "audit: the finished ledger — all called, none refuted, four proven — carries the hard call, and offers nothing more")

    // the gates read the FINAL ledger, in pieces:
    fun calledState9(vararg calls: Pair<String, String>): GameState {
        val st = eng9.newState()
        st.arc9Chapter = 4
        for (c in clues9) st.mystery9Clues.add(c.id)
        for ((sid, call) in calls) st.arc9Calls[sid] = call
        return st
    }
    val sRefuted = calledState9("site_trophies" to "added",
        "site_seats" to "record", "site_boxes" to "count",
        "site_portraits" to "added")   // gallery called wrong: refuted
    check(!Mystery9.readEligible9(sRefuted) && !Mystery9.ledgerClean9(sRefuted),
        "audit: one refuted call still standing on the ledger buys the hard call nothing")
    val sUnfinished = calledState9("site_trophies" to "added",
        "site_seats" to "record", "site_boxes" to "count")
    check(!Mystery9.ledgerCalled9(sUnfinished) &&
        !Mystery9.readEligible9(sUnfinished) && Mystery9.nameEligible9(sUnfinished),
        "audit: an unfinished ledger — however proven its rows — cannot be read aloud; it can still name")
    val sAllWrong = calledState9("site_trophies" to "count",
        "site_seats" to "added", "site_boxes" to "record",
        "site_portraits" to "added")
    check(Mystery9.ledgerCalled9(sAllWrong) && Mystery9.provenCount9(sAllWrong) == 0 &&
        !Mystery9.nameEligible9(sAllWrong) && !Mystery9.readEligible9(sAllWrong),
        "audit: a fully called ledger with every row refuted carries no call at all — the town will not follow a struck ledger")


    // ---------- scheduling: behind the alibi case, at its distance ----------
    val sQ = eng9.newState()
    sQ.absDay = 220
    check(Mystery9.dueChapter9(sQ) == null,
        "audit: unscheduled while the eighth case hasn't retired — there is no schedule yet")
    sQ.arc8Retired = true; sQ.arc8RetiredDay = 219
    check(sQ.arc9DueAbsDay == -1 && Mystery9.dueChapter9(sQ) == null,
        "audit: the wait for the count starts the day the alibi case closes")
    sQ.absDay = 229
    val q1 = Mystery9.dueChapter9(sQ)
    check(q1 != null && q1.id == ch9[0].id && sQ.arc9DueAbsDay == 229,
        "audit: the count comes in exactly ten days after everybody was somewhere closed — ORDER, ADAPT, BOOK")
    check((q1!!.stages[0].clusterLoc to q1.stages[1].clusterLoc) ==
        ("CityHall" to "Elementary"),
        "audit: chapter 1 plays the hall and the school")
    sQ.holidayId = "snowday"
    check(Mystery9.dueChapter9(sQ) == null,
        "audit: a holiday holds the case's slot like any case's")
    sQ.holidayId = null
    check(Mystery9.dueChapter9(sQ)?.id == ch9[0].id,
        "audit: ...and it returns, unshifted, when the holiday passes")
    Mystery9.noteChapterStarted9(sQ, ch9[0])
    check(sQ.arc9Started && sQ.arc9Chapter == 1 && sQ.arc9DueAbsDay == 236,
        "audit: chapter 2 is booked exactly a week out")
    sQ.absDay = 235
    check(Mystery9.dueChapter9(sQ) == null,
        "audit: ...and waits the full week, however eager the counting")
    sQ.absDay = 236
    check(Mystery9.dueChapter9(sQ)?.id == ch9[1].id,
        "audit: the theater and the shelf, in person, on day seven")
    Mystery9.noteChapterStarted9(sQ, ch9[1])
    check(sQ.arc9DueAbsDay == 243, "audit: the books open a week past the counting")
    sQ.absDay = 243
    Mystery9.noteChapterStarted9(sQ, ch9[2])
    sQ.absDay = 250
    check(Mystery9.dueChapter9(sQ)?.id == ch9[3].id,
        "audit: the reckoning is due a week past the books, no earlier")
    Mystery9.noteChapterStarted9(sQ, ch9[3])
    check(sQ.arc9DueAbsDay == -1 && Mystery9.dueChapter9(sQ) == null,
        "audit: with the finale on, there is no fifth chapter to schedule")

    // ---------- the finale: the reckoning ----------
    fun auditState9(): GameState {
        val st = eng9.newState()
        for (c in clues9) st.mystery9Clues.add(c.id)
        st.arc9Started = true
        st.arc9Chapter = 4
        st.shenaniganId = Mystery9.FINALE9_ID
        st.shenaniganDay = st.todayKey
        st.timeMin = 13 * 60
        return st
    }
    fun settleLedger9(st: GameState) {
        st.arc9Calls["site_trophies"] = "added"
        st.arc9Calls["site_seats"] = "record"
        st.arc9Calls["site_boxes"] = "count"
        st.arc9Calls["site_portraits"] = "record"
    }
    val sDue9 = auditState9()
    check(!Mystery9.auditDue(sDue9),
        "audit: the reckoning will not open on an unsettled ledger — the room wants every site called")
    settleLedger9(sDue9)
    check(Mystery9.auditDue(sDue9) &&
        Finales.climaxPending(sDue9) && School.anyClimaxDueToday(sDue9) &&
        Walk.caseCritical(sDue9) && MovieNights.anyClimaxDueTonight(sDue9),
        "audit: on a settled ledger the reckoning stands due — and every door in town defers to it (the season finale, the classroom, the walk, the marquee)")
    sDue9.timeMin = 10 * 60
    check(!Mystery9.auditDue(sDue9),
        "audit: ...but not before the count's closing stages — the labeled space in the program is at the end")
    sDue9.timeMin = 13 * 60
    check(!Mystery9.chooseFinale9(sDue9, "maybe"),
        "audit: the reckoning takes only its four calls")
    check(Mystery9.chooseFinale9(sDue9, "read") &&
        sDue9.arc9Choice == "read" && !Mystery9.auditDue(sDue9) &&
        !Mystery9.chooseFinale9(sDue9, "name"),
        "audit: one call is taken, once; afterwards the reckoning is done asking")
    val out9 = Mystery9.resolveAudit(sDue9)
    check(sDue9.arc9Retired && sDue9.arc9Branch == "reconciled" &&
        sDue9.arc9RetiredDay == sDue9.absDay &&
        out9.branch == "reconciled" && out9.outcome.isNotBlank() &&
        out9.recapLines.size == 2 &&
        out9.recapLines.all { it.isNotBlank() },
        "audit: read aloud, the case reconciles — stamped the day it closed, worded as it landed")
    check(!Mystery9.noteListRestored(sDue9) &&
        !sDue9.arc9ListPending,
        "audit: the roll waits for the wrap to be reckoned — effects land at credits, not at the resolve")
    Mystery9.applyAuditEffects(sDue9, "reconciled")
    check(sDue9.arc9ListPending && sDue9.arc9ListDay == sDue9.absDay + 7 &&
        sDue9.friendship["Adler"] == 4 &&
        sDue9.lifeText["mark:CityHall"]!!.contains("RECONCILED"),
        "audit: the reckoning leaves its marks — the chamber's mark, a specialist, and a promise six days out in writing")
    val restoredDay9 = sDue9.arc9ListDay
    sDue9.absDay += 6
    check(!Mystery9.noteListRestored(sDue9) && sDue9.arc9ListPending,
        "audit: the roll is NOT reprinted early — a promise kept to the day, not the week-ish")
    sDue9.absDay += 1
    val tail9 = Mystery9.noteListRestored(sDue9)
    check(tail9 && sDue9.arc9ListRestored && !sDue9.arc9ListPending &&
        sDue9.absDay == restoredDay9 &&
        !Mystery9.noteListRestored(sDue9),
        "audit: on the seventh day the roll is whole — fourteen faces, fourteen names — exactly once")
    check(Mystery9.aftermathLine9(sDue9, "McDaniels") != null &&
        Mystery9.aftermathLine9(sDue9, "Adler") == null &&
        Mystery9.aftermathLine9(sDue9, "Victoria") == null &&
        Mystery9.aftermathLine9(sDue9, "Kenny") == null,
        "audit: the standing voice of the reconciled ending is the keeper of the count herself — the woman who wanted the face down")
    val sBlame = auditState9()
    sBlame.arc9Calls["site_trophies"] = "added"
    sBlame.arc9Calls["site_seats"] = "count"
    sBlame.arc9Calls["site_boxes"] = "record"
    sBlame.arc9Calls["site_portraits"] = "added"
    check(Mystery9.auditDue(sBlame) && !Mystery9.readEligible9(sBlame) &&
        Mystery9.nameEligible9(sBlame) &&
        !Mystery9.chooseFinale9(sBlame, "read"),
        "audit: one proven row buys a name, never a reading — the hard call stays shut on a struck ledger")
    sBlame.friendship["Adler"] = 10
    check(Mystery9.chooseFinale9(sBlame, "name") &&
        Mystery9.resolveAudit(sBlame).branch == "blamed",
