    Mystery9.applyAuditEffects(sShelf, "shelved")
    check(Mystery9.aftermathLine9(sShelf, "Victoria") != null &&
        Mystery9.aftermathLine9(sShelf, "McDaniels") == null &&
        sShelf.lifeText["mark:CityHall"]!!.contains("FILED"),
