    val sDegrade = auditState9()
    settleLedger9(sDegrade)
    sDegrade.arc9Calls["site_portraits"] = "added"
    sDegrade.arc9Choice = "read"
    check(Mystery9.resolveAudit(sDegrade).branch == "cold",
