// ---------- contention, re-pinned at the code's own seats ----------
run {
    check(TalkGate.Rail.values().toList() == listOf(
        TalkGate.Rail.DELIVER, TalkGate.Rail.HOLIDAY_BEAT,
        TalkGate.Rail.FINALE, TalkGate.Rail.CLIMAX,
        TalkGate.Rail.DINNER, TalkGate.Rail.WORK,
        TalkGate.Rail.FACTION_MISSION,
        TalkGate.Rail.EMERG_OFFER, TalkGate.Rail.RIVAL,
        TalkGate.Rail.ERRAND_ASK, TalkGate.Rail.DIALOGUE),
        "contention: the TalkGate ladder stands at eleven " +
            "rails in its order — Queue #11 added none")
    val tgSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(tgSrc.contains("Sleepovers.talkStepFor") &&
        !tgSrc.contains("Newspaper"),
        "contention: sleepovers ride the DINNER rail " +
            "through the gate, and the paper holds no rail " +
            "and appears nowhere in the gate")
    val paperSrc = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(!paperSrc.contains("TalkGate"),
        "contention: the paper never reaches for the gate " +
            "— it publishes at the rollover, not the talk")
    // the agenda stack, in Engine's actual order: each
    // gathering claim's first call in effectiveAgendaBlock
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    val stackNames = listOf("Dinners", "Family", "Jobs",
        "MovieNights", "Capstones", "Finales", "Fair",
        "Carnival", "RivalCrew", "Heroes", "Play",
        "Sleepovers", "Stand", "Crew")
    val idx = stackNames.map { nm ->
        Regex("(?<![A-Za-z])$nm\\.gatheringBlock")
            .find(engSrc)?.range?.first ?: -1 }
    check(idx.all { it >= 0 } && idx == idx.sorted() &&
        idx.distinct().size == idx.size,
        "contention: the agenda stack seats its fourteen " +
            "claims in Engine's own order — Dinners, Family, " +
            "Jobs, MovieNights, Capstones, Finales, Fair, " +
            "Carnival (with the fair, its counterpart), " +
            "RivalCrew, Heroes, Play, Sleepovers (after the " +
            "play, before the stand), Stand, Crew last")
    // cadence pairs, re-swept in ONE lived time space
    var fridays = 0
    var clash = false
    val (_, sf) = auditState(1122)
    sf.life["famArrived"] = 1
    for (d in 0 until 7 * 104) {
        if (!Sleepovers.isSleepoverDay(d)) continue
        fridays++
        if (Jobs.weekdayOf(d) in Heroes.PATROL_WEEKDAYS)
            clash = true
        if (d % 7 in setOf(0, 2, 4)) clash = true
        setDayG(sf, d)
        if (Family.dinnerTonight(sf)) clash = true
    }
    check(fridays == 104 && !clash,
        "contention: two years of Fridays swept live — " +
            "every sleepover Friday is a Friday, never a " +
            "patrol night, never on the family table's " +
            "rhythm, and Family.dinnerTonight itself never " +
            "fires on one")
    fun keyE(y: Int, m: Int, d: Int) =
        "%04d%02d%02d".format(y, m, d)
    fun finaleRanges(year: Int): List<IntRange> {
        val out = mutableListOf<IntRange>()
        for (season in Season.values()) {
            for (iy in (year - 1)..(year + 1)) {
                val (m, d) = Finales.seasonEndMonthDay(season, iy)
                val end = ordinalOfKey(keyE(iy, m, d))
                out += (end - (Finales.WINDOW_DAYS - 1))..end
            }
        }
        return out
    }
    fun holidayRanges(year: Int): List<IntRange> {
        val out = mutableListOf<IntRange>()
        for (h in HOLIDAYS) {
            for (yy in (year - 1)..(year + 1)) {
                val start = ordinalOfKey(
                    "%04d%s".format(yy, h.startMd))
                val end = if (h.startMd <= h.endMd)
                    ordinalOfKey("%04d%s".format(yy, h.endMd))
                else ordinalOfKey(
                    "%04d%s".format(yy + 1, h.endMd))
                out += start..end
            }
        }
        return out
    }
    fun overlaps(a: IntRange, b: IntRange): Boolean =
        a.first <= b.last && b.first <= a.last
    var vsFinales = true
    var vsHolidays = true
    var vsFair = true
    for (y in 2026..2065) {
        val w = CarnivalCalendar.windowFor(y)
        val mine = w.startOrd..w.endOrd
        if (finaleRanges(y).any { overlaps(mine, it) })
            vsFinales = false
        if (holidayRanges(y).any { overlaps(mine, it) })
            vsHolidays = false
        for (yy in (y - 1)..(y + 1)) {
            val f = FairCalendar.windowFor(yy)
            if (overlaps(mine, f.startOrd..f.endOrd))
                vsFair = false
        }
    }
    check(vsFinales && vsHolidays && vsFair,
        "contention: the carnival week re-swept in the one " +
            "lived ordinal space, 2026–2065 — disjoint from " +
            "every finale window, every holiday window, " +
            "and the summer fair, as v0.11.0e proved it")
    check(Garden.PLANT_MINUTES == 15 &&
        Garden.WATER_MINUTES == 15 &&
        Garden.CLEAR_MINUTES == 15 &&
        Garden.HARVEST_MINUTES == 15 &&
        Garden.BEDS * (Garden.WATER_MINUTES +
            Garden.CLEAR_MINUTES) + Garden.PLANT_MINUTES +
            Garden.HARVEST_MINUTES <= 14 * 60,
        "contention: the garden's beats against the day " +
            "clock — four 15-minute beats, a full care round " +
            "for all four beds at ninety minutes, well " +
            "inside the waking day they tick against")
}

