/** v0.12.0a section, extracted like the others (64 KB rule):
 *  the paper grows up — Queue #12 item 1. */
private fun sectionV0120a(root: String) {
// ================= v0.12.0a: the paper grows up =================
// Queue #12 item 1. The v0.11.0a paper's two recorded gaps
// close: the folded headline tiers land (season finale,
// caper close, stand review — seated in the ladder under
// the fair and the vote, over the rivalry, the existing
// tiers' relative order untouched) and the edition is
// delivered (a porch copy at Your House rendering the
// frozen edition; a one-text phone summary on publication
// morning — the headline verbatim from a rotating cast
// subscriber, the debt stamped at publication and cleared
// only when the text lands). The caper prints in PUBLIC
// SHAPE ONLY: the Hero Log's own ending phrase, borrowed
// whole from Heroes.caperPublicEnding. Ladder pairs the
// calendar can never seat in one week (the fair's shift
// rule dodges the finale windows; play openings never
// share a week with a finale wrap) are pinned in source
// order; every pair the calendar CAN seat is fabricated.
println("== v0.12.0a: the paper grows up — Queue #12 item 1 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.12.0a"),
        "paper grows: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 89 / 0.12.0b")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "paper grows: no new module — the tree stood at 98 " +
            "Kotlin files (counted $ktCount)")

    // ---------- wiring pins ----------
    val npSrc = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    val ladderTerms = listOf("1. CASE CLOSED", "2. THE FAIR",
        "3. SEASON FINALE", "4. OPENING NIGHT", "5. THE VOTE",
        "6. CAPER CLOSE", "7. STAND REVIEW", "8. THE RIVALRY",
        "9. THE SKY", "10. A QUIET WEEK")
    val ladderIdx = ladderTerms.map { npSrc.indexOf(it) }
    check(ladderIdx.all { it >= 0 } && ladderIdx == ladderIdx.sorted(),
        "paper grows: the file header states the full " +
            "ten-tier ladder in order")
    val branchTerms = listOf("caseDay != null ->", "fair != null ->",
        "finale != null ->", "play != null ->", "vote != null ->",
        "caperDay != null ->", "review ->",
        "contests.isNotEmpty() ->", "skySpecial != null ->")
    val branchIdx = branchTerms.map { npSrc.indexOf(it) }
    check(branchIdx.all { it >= 0 } && branchIdx == branchIdx.sorted(),
        "paper grows: composeEdition's branches run in the " +
            "ladder's order — the pairs the calendar can " +
            "never seat together (fair over finale, finale " +
            "over opening night) stand pinned here")
    val phSrc = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    check(phSrc.contains("const val PAPER = \"paper\"") &&
        phSrc.contains("Newspaper.summaryDue(state)") &&
        phSrc.contains("Newspaper.markSummarySent(state)"),
        "paper phone: the harvest owns a PAPER beat that " +
            "reads the paper's debt and clears it on landing")
    check(Phone.PAPER in Phone.TRIGGERS,
        "paper phone: the PAPER trigger is admitted")
    check(Phone.MAX_TEXTS == 220 &&
        (KID_ORDER.size + 2 + GroupChats.GROUP_IDS.size) * 2 <=
            Phone.MAX_TEXTS,
        "paper phone: the cap math still holds — " +
            "(${KID_ORDER.size} cast + 2 parents + " +
            "${GroupChats.GROUP_IDS.size} rooms) × 2 = " +
            "${(KID_ORDER.size + 2 + GroupChats.GROUP_IDS.size) * 2} " +
            "≤ MAX_TEXTS 220; the summary rides an existing " +
            "thread and the dial does not move")
    // admission: the closed sender set is unchanged — a
    // paper text from a cast member decodes; anything
    // pretending to be "the paper itself" does not.
    val textMap = mapOf<String, Any?>("id" to "30:paper:1",
        "thread" to "Stan", "sender" to "Stan",
        "trigger" to "paper", "absDay" to 30,
        "day" to "20261031", "text" to "paper's out",
        "read" to false, "emoji" to "")
    check(PhoneText.fromMap(textMap) != null,
        "paper phone: a subscriber's paper text decodes")
    check(PhoneText.fromMap(textMap +
        ("trigger" to "gazette")) == null,
        "paper phone: an unregistered trigger is dropped")
    check(PhoneText.fromMap(textMap +
        ("sender" to "The Gazette")) == null &&
        PhoneText.fromMap(textMap +
        ("thread" to "The Gazette")) == null,
        "paper phone: there is no Gazette thread and no " +
            "Gazette sender — the set stays closed")
    val gvSrc = File(root,
        "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("Hit(\"fixture\", \"paper\"") &&
        gvSrc.contains("Newspaper.porchLines(st)"),
        "paper porch: the step at Your House draws the " +
            "bundle and routes its tap, gated on a standing " +
            "edition")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("\"paper\" -> paperDialog()") &&
        gaSrc.contains("Newspaper.porchLines(state)"),
        "paper porch: the fixture tap opens the porch " +
            "dialog on the frozen edition")

    // ---------- helpers ----------
    fun setDayA(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun paperState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    fun skyEntry(s: GameState, absDay: Int, weather: String,
        special: String) {
        val cur = Newspaper.skyLog(s)
            .filter { it.absDay != absDay } +
            Newspaper.SkyEntry(absDay, weather, special)
        s.lifeText["paperSkyLog"] = cur.sortedBy { it.absDay }
            .joinToString(";") { "${it.absDay}:${it.weatherId}:${it.special}" }
    }
    fun skyWeek(s: GameState, week: Int,
        specials: Map<Int, String> = emptyMap()) {
        for (d in week * 7..week * 7 + 6)
            skyEntry(s, d, "sunny", specials[d] ?: SkyState.NONE)
    }
    fun votePipe(s: GameState, countedDay: Int, winnerVotes: Int,
        totalVotes: Int, margin: Int) {
        val q = Votes.QUESTIONS.first()
        s.lifeText["voteLastResult"] = listOf(q.id,
            q.options.first().id, margin, winnerVotes, totalVotes,
            countedDay, Jobs.weekIndex(countedDay), 1, 0,
            q.options[1].id).joinToString("|")
    }
    fun rivalWeek(s: GameState, week: Int) {
        s.life["rivalRevealedDay"] = 1
        s.life["rivalYou"] = 2; s.life["rivalThem"] = 1
        s.life["rivalDraws"] = 0
        s.lifeText["rivalLog"] =
            "${week * 7 + 1}|showdown|you|a clean hit at the park;" +
            "${week * 7 + 3}|race|them|by a nose on Main Street"
    }
    // the spring finale's wrap: the morning after May 31
    val wrapDay = FairCalendar.absDayOfOrdinal(
        ordinalOfKey("20270531")) + 1
    val wFin = Jobs.weekIndex(wrapDay)
    val springDef = Finales.defById("spring")!!

    // ---------- tier: SEASON FINALE ----------
    val (_, sF) = paperState(12011)
    sF.life["fin:spring:2027:done"] = 1
    check(Finales.isWrapped(sF, springDef, 2027),
        "paper finale: (staging) the spring instance stands wrapped")
    val markChoice = springDef.choices[0]
    sF.lifeText["finMark:spring"] = markChoice.markText
    sF.life["finMarkYear:spring"] = 2027
    sF.lifeText["finMarkWinner:spring"] = markChoice.winner
    sF.lifeText["finMarkBy:spring"] = "town"
    skyWeek(sF, wFin, mapOf(wFin * 7 + 1 to SkyState.METEOR))
    rivalWeek(sF, wFin)
    votePipe(sF, wrapDay, 50, 90, 10)
    val edF = Newspaper.composeEdition(sF, wFin)
    check(edF.headline == "'${springDef.title.uppercase()}' — " +
        "THE SPRING FINALE WRAPS",
        "paper finale: a wrapped finale headlines its wrap " +
            "week, over the vote, the rivalry and the sky")
    val finLine = edF.lines.first {
        it.contains("finale") && it.contains(springDef.title) }
    check(finLine.contains(markChoice.markText) &&
        finLine.contains("history credits ${markChoice.winner}"),
        "paper finale: the town line quotes the standing " +
            "mark and who history credits — the record's " +
            "own fields")
    check(finLine.contains(
        LOCATIONS[springDef.loc]?.name ?: springDef.loc),
        "paper finale: the town line names the finale's " +
            "own place")
    // the mark replaced by a later year: headline stands,
    // the quote drops — a later year's mark is not this
    // instance's news
    sF.life["finMarkYear:spring"] = 2028
    val edF2 = Newspaper.composeEdition(sF, wFin)
    check(edF2.headline == edF.headline &&
        edF2.lines.none { it.contains(markChoice.markText) },
        "paper finale: a later year's standing mark is " +
            "never quoted for this instance")
    // a finale that never wrapped headlines nothing
    val (_, sF3) = paperState(12017)
    skyWeek(sF3, wFin)
    check(Newspaper.composeEdition(sF3, wFin).headline ==
        "A QUIET WEEK IN SOUTH PARK",
        "paper finale: an unwrapped instance is not news")

    // ---------- tier: CAPER CLOSE (public shape only) ----------
    val (_, sC) = paperState(12012)
    Heroes.createHero(sC, "Captain Curfew", "speed")
    skyWeek(sC, 3, mapOf(22 to SkyState.METEOR))
    rivalWeek(sC, 3)
    sC.life["caperStage"] = 6
    sC.life["caperDoneDay"] = 24
    sC.lifeText["caperStance"] = "silence"
    sC.life["caperHelped"] = 1
    val edC = Newspaper.composeEdition(sC, 3)
    check(edC.headline == "THE CAPER CLOSES",
        "paper caper: the caper's closing day headlines " +
            "its week, over the rivalry and the sky")
    val capLine = edC.lines.first {
        it.contains("The caper closed this week") }
    check(capLine.contains("a legend the town gets to keep") &&
        capLine.contains(Heroes.caperPublicEnding(sC)!!),
        "paper caper: the town line quotes the Hero Log's " +
            "public ending phrase whole — borrowed, not told")
    check(Heroes.pageLines(sC).any {
        it.contains("CLOSED — a legend the town gets to keep") },
        "paper caper: the paper and the Hero Log agree " +
            "word for word — one public source")
    // the other stances, through the same public phrase
    sC.lifeText["caperStance"] = "name"; sC.life["caperHelped"] = 3
    check(Newspaper.composeEdition(sC, 3).lines.any {
        it.contains("the Curator, named and licensed") },
        "paper caper: the naming-and-helped ending prints " +
            "its public phrase")
    sC.life["caperHelped"] = 0
    check(Newspaper.composeEdition(sC, 3).lines.any {
        it.contains("the Curator, named and gone") },
        "paper caper: the naming ending prints its public phrase")
    sC.lifeText["caperStance"] = "join"
    check(Newspaper.composeEdition(sC, 3).lines.any {
        it.contains("one perfect park, no witnesses") },
        "paper caper: the joining ending prints its public phrase")
    sC.lifeText["caperStance"] = "silence"; sC.life["caperHelped"] = 1
    // the spoiler wall: headline, caper line, and the
    // module's own source, against the caper's sealed terms
    val sealedCaper = listOf("dogpoo", "six inches",
        "tape measure", "birdhouse", "mitten tree",
        "shifted the park", "moved the park", "curator is",
        "six inch")
    for (term in sealedCaper) {
        check(term !in (edC.headline + "\n" + capLine).lowercase(),
            "paper caper spoiler: the print never carries '$term'")
        check(term !in npSrc.lowercase(),
            "paper caper spoiler: Newspaper.kt's source " +
                "carries no '$term'")
    }
    // the whole edition, with a case closing the same
    // week, against BOTH sealed walls
    sC.arc9RetiredDay = 24
    val edBoth = Newspaper.composeEdition(sC, 3)
    val bothText = edBoth.lines.joinToString("\n").lowercase()
    for (term in sealedCaper + listOf("sleepwalking",
        "strongbox", "cameo", "communal paperwork",
        "cornerstone")) {
        check(term !in bothText,
            "paper spoiler: an edition printing both a case " +
                "close and a caper close carries no '$term'")
    }
    check(edBoth.headline == "THE CASE CLOSES",
        "paper caper: a case closing still tops the caper")

    // ---------- tier: STAND REVIEW ----------
    val (_, sR) = paperState(12013)
    skyWeek(sR, 3, mapOf(22 to SkyState.METEOR))
    rivalWeek(sR, 3)
    sR.life["standReviewDay"] = 23
    sR.lifeText["standReview"] = "the crew's review stands"
    sR.lifeText["standVerdict"] = "ROUGH"
    sR.lifeText["standReviewer"] = "Craig"
    check(Stand.reviewDay(sR) == 23 &&
        Stand.reviewVerdict(sR) == "ROUGH",
        "paper review: (staging) Stand's getters read the " +
            "standing review's own day and verdict")
    val edR = Newspaper.composeEdition(sR, 3)
    check(edR.headline == "THE STAND, REVIEWED: ROUGH",
        "paper review: a review posted in the week " +
            "headlines it, over the rivalry and the sky")
    val revLine = edR.lines.first { it.contains("posted their review") }
    check(revLine.contains("ROUGH") && revLine.contains("Craig"),
        "paper review: the town line carries the verdict " +
            "and the reviewer from the record")
    // its own day names its week — last week's review is
    // not this week's headline
    sR.life["standReviewDay"] = 40
    check(Newspaper.composeEdition(sR, 3).headline
        .startsWith("THE RIVALRY"),
        "paper review: a review from another week does " +
            "not headline this one")
    // no standing review, no tier
    sR.lifeText.remove("standReview")
    sR.life["standReviewDay"] = 23
    check(Newspaper.composeEdition(sR, 3).headline
        .startsWith("THE RIVALRY"),
        "paper review: with no review standing, the tier " +
            "stays silent")

    // ---------- the ladder, eliminated tier by tier ----------
    // week 3, everything movable standing at once:
    // case > vote > caper > review > rivalry > sky > quiet
    val (_, sL) = paperState(12014)
    skyWeek(sL, 3, mapOf(22 to SkyState.METEOR))
    rivalWeek(sL, 3)
    votePipe(sL, 25, 50, 90, 10)
    sL.life["caperStage"] = 6
    sL.life["caperDoneDay"] = 24
    sL.lifeText["caperStance"] = "silence"
    sL.life["caperHelped"] = 1
    sL.life["standReviewDay"] = 23
    sL.lifeText["standReview"] = "the crew's review stands"
    sL.lifeText["standVerdict"] = "GOOD"
    sL.lifeText["standReviewer"] = "Craig"
    sL.arc9RetiredDay = 24
    check(Newspaper.composeEdition(sL, 3).headline ==
        "THE CASE CLOSES",
        "paper ladder: with everything standing, the case closes")
    sL.arc9RetiredDay = -1
    check(Newspaper.composeEdition(sL, 3).headline
        .endsWith("WINS THE VOTE"),
        "paper ladder: strike the case — the vote wins")
    sL.lifeText.remove("voteLastResult")
    check(Newspaper.composeEdition(sL, 3).headline ==
        "THE CAPER CLOSES",
        "paper ladder: strike the vote — the caper closes")
    sL.life.remove("caperDoneDay")
    check(Newspaper.composeEdition(sL, 3).headline ==
        "THE STAND, REVIEWED: GOOD",
        "paper ladder: strike the caper — the review stands")
    sL.life.remove("standReviewDay")
    check(Newspaper.composeEdition(sL, 3).headline
        .startsWith("THE RIVALRY"),
        "paper ladder: strike the review — the rivalry")
    sL.lifeText.remove("rivalLog")
    check(Newspaper.composeEdition(sL, 3).headline
        .startsWith("SKY SHOW:"),
        "paper ladder: strike the rivalry — the sky")
    skyWeek(sL, 3)
    check(Newspaper.composeEdition(sL, 3).headline ==
        "A QUIET WEEK IN SOUTH PARK",
        "paper ladder: strike the sky — the quiet week, honest")
    // the finale's seat, eliminated the same way:
    // case > finale > vote in the wrap week
    val (_, sL2) = paperState(12015)
    sL2.life["fin:spring:2027:done"] = 1
    skyWeek(sL2, wFin, mapOf(wFin * 7 + 1 to SkyState.METEOR))
    rivalWeek(sL2, wFin)
    votePipe(sL2, wrapDay, 50, 90, 10)
    sL2.arc9RetiredDay = wrapDay
    check(Newspaper.composeEdition(sL2, wFin).headline ==
        "THE CASE CLOSES",
        "paper ladder: a case closing tops the finale too")
    sL2.arc9RetiredDay = -1
    check(Newspaper.composeEdition(sL2, wFin).headline
        .contains("FINALE WRAPS"),
        "paper ladder: strike the case — the finale wraps")
    sL2.life.remove("fin:spring:2027:done")
    check(Newspaper.composeEdition(sL2, wFin).headline
        .endsWith("WINS THE VOTE"),
        "paper ladder: strike the finale — the vote wins")

    // ---------- the number audit, over the new lines ----------
    val (_, sA) = paperState(12016)
    skyWeek(sA, wFin)
    sA.life["rivalRevealedDay"] = 1
    sA.life["rivalYou"] = 6; sA.life["rivalThem"] = 2
    sA.life["rivalDraws"] = 1
    sA.lifeText["rivalLog"] =
        "${wFin * 7 + 1}|showdown|you|a clean hit at the fort;" +
        "${wFin * 7 + 3}|race|them|by a whisker at the pond"
    votePipe(sA, wrapDay, 137, 201, 73)
    sA.life["fin:spring:2027:done"] = 1
    sA.lifeText["finMark:spring"] =
        "The gate stays as the town left it"
    sA.life["finMarkYear:spring"] = 2027
    sA.lifeText["finMarkWinner:spring"] = "a tie"
    sA.lifeText["finMarkBy:spring"] = "town"
    sA.life["caperStage"] = 6
    sA.life["caperDoneDay"] = wFin * 7 + 2
    sA.lifeText["caperStance"] = "join"
    sA.life["caperHelped"] = 3
    sA.life["standReviewDay"] = wFin * 7 + 4
    sA.lifeText["standReview"] = "the crew's review stands"
    sA.lifeText["standVerdict"] = "MIXED"
    sA.lifeText["standReviewer"] = "Craig"
    val edA = Newspaper.composeEdition(sA, wFin)
    check(edA.headline.contains("FINALE WRAPS") &&
        edA.lines.any { it.contains("posted their review") } &&
        edA.lines.any { it.contains("The caper closed this week") },
        "paper audit: the audited edition really prints " +
            "all three new town lines")
    val intsA = Regex("\\d+").findAll(edA.lines.joinToString("\n"))
        .map { it.value.toInt() }.toSet()
    val allowed = mutableSetOf(wFin, 137, 201, 73, 6, 2, 1,
        Stand.PERMIT_COST, Stand.KIT_COST)
    allowed += Stand.STOCK.map { it.shopPrice }
    for (d in wFin * 7..wFin * 7 + 6) {
        val k = Commissions.keyForAbsDay(sA, d)
        allowed += k.substring(4, 6).toInt()
        allowed += k.substring(6, 8).toInt()
    }
    check(intsA.all { it in allowed },
        "paper audit: every integer in an edition carrying " +
            "the new tiers traces to a record — the finale, " +
            "caper and review lines print no number of their " +
            "own (strays: ${intsA - allowed})")
    check(137 in intsA && 201 in intsA,
        "paper audit: the distinctive record values still print")
    check(!Regex("\\d").containsMatchIn(edA.headline),
        "paper audit: the finale headline itself is number-free")

    // ---------- the porch ----------
    val (engP, sP) = paperState(12018)
    check(Newspaper.porchLines(sP) == null,
        "paper porch: before the first edition there is " +
            "no copy on the porch")
    repeat(7) { engP.onNewDay(sP) }
    val porch1 = Newspaper.porchLines(sP)
    check(porch1 != null &&
        porch1 == sP.lifeText["paperLatest"]!!.split("\n"),
        "paper porch: after publication the porch holds " +
            "the frozen edition, line for line")
    check(porch1 == Newspaper.pageLines(sP),
        "paper porch: the porch copy and the Journal's " +
            "first page are the same edition")
    repeat(7) { engP.onNewDay(sP) }
    val porch2 = Newspaper.porchLines(sP)
    check(porch2 != null && porch2 != porch1 &&
        porch2 == sP.lifeText["paperLatest"]!!.split("\n"),
        "paper porch: the next edition replaces the copy — " +
            "the porch never shows last week's paper as this " +
            "week's")

    // ---------- the phone summary ----------
    // legacy: an edition frozen before the summary
    // existed carries no stamp — it is never texted about
    val (_, sLeg) = paperState(12019)
    sLeg.lifeText["paperLatest"] = "📰 THE SOUTH PARK GAZETTE\n" +
        "Week 4 · printed from the town's own record\n" +
        "A QUIET WEEK IN SOUTH PARK"
    sLeg.life["paperWeek"] = 4
    check(!Newspaper.summaryDue(sLeg),
        "paper phone: a pre-v0.12.0a save is never texted " +
            "about an old edition — no stamp, no debt")
    check(Newspaper.latestHeadline(sLeg) ==
        "A QUIET WEEK IN SOUTH PARK",
        "paper phone: the headline reads off the frozen " +
            "edition's third line")
    check(Newspaper.porchLines(sLeg)?.size == 3,
        "paper porch: a legacy frozen edition renders on " +
            "the porch as it stands")
    // the rotation: cast only, never Kenny, turning weekly
    val pool = KID_ORDER.filter { it != "Kenny" }
    for (w in 0..7) {
        sLeg.life["paperWeek"] = w
        check(Newspaper.summarySender(sLeg) == pool[w % pool.size],
            "paper phone: week $w's subscriber is the " +
                "rotation's pick")
    }
    check((0 until pool.size).map { w ->
        sLeg.life["paperWeek"] = w
        Newspaper.summarySender(sLeg) }.toSet().size == pool.size,
        "paper phone: over a full rotation every cast " +
            "member but Kenny carries the paper once")
    // the uncontended morning: the debt is paid in full,
    // on the subscriber's own thread, headline verbatim
    val (_, sD) = paperState(12020)
    setDayA(sD, 30)
    sD.lifeText["paperLatest"] = "📰 THE SOUTH PARK GAZETTE\n" +
        "Week 4 · printed from the town's own record\n" +
        "THE CASE CLOSES"
    sD.life["paperWeek"] = 4
    sD.life["paperSummaryDue"] = 1
    check(Newspaper.summaryDue(sD),
        "paper phone: (staging) a stamped debt reads due")
    Phone.dailyRollover(sD)
    val dTexts = sD.phoneTexts.filter { it.trigger == Phone.PAPER }
    check(dTexts.size == 1,
        "paper phone: the summary lands as exactly one " +
            "text (got ${dTexts.size})")
    if (dTexts.size == 1) {
        val t = dTexts[0]
        check(t.text.contains("THE CASE CLOSES"),
            "paper phone: the text carries the headline verbatim")
        check(t.sender == Newspaper.summarySender(sD) &&
            t.sender in KID_ORDER && t.sender != "Kenny",
            "paper phone: the sender is the week's cast " +
                "subscriber — never Kenny, whose render " +
                "would muffle the headline")
        check(t.thread == t.sender,
            "paper phone: the text rides the subscriber's " +
                "own thread")
    }
    check(!Newspaper.summaryDue(sD),
        "paper phone: the debt clears when the text lands")
    Phone.dailyRollover(sD)
    check(sD.phoneTexts.count { it.trigger == Phone.PAPER } == 1,
        "paper phone: the same morning never texts twice")
    setDayA(sD, 31)
    Phone.dailyRollover(sD)
    check(sD.phoneTexts.count { it.trigger == Phone.PAPER } == 1,
        "paper phone: with the debt paid, later mornings " +
            "stay quiet")
    // the lived drive: two editions, two summaries, and
    // the debt never survives the week (a crowded morning
    // may defer the text; it may not lose it)
    val (engT, sT) = paperState(12021)
    repeat(17) { engT.onNewDay(sT) }
    check(Newspaper.headlineHistory(sT).size == 2,
        "paper phone: (staging) two editions published in " +
            "seventeen days")
    check(sT.phoneTexts.count { it.trigger == Phone.PAPER } == 2,
        "paper phone: one summary per edition across the " +
            "lived drive (got " +
            "${sT.phoneTexts.count { it.trigger == Phone.PAPER }})")
    check(!Newspaper.summaryDue(sT),
        "paper phone: no debt is left standing")
    for (t in sT.phoneTexts.filter { it.trigger == Phone.PAPER }) {
        check(t.sender in KID_ORDER && t.sender != "Kenny" &&
            t.thread == t.sender,
            "paper phone: every lived summary rides a cast " +
                "thread in the rotation's voice")
    }

    // ---------- saves: the delivery state round-trips ----------
    val (_, sSv) = paperState(12022)
    sSv.lifeText["paperLatest"] = "📰 THE SOUTH PARK GAZETTE\n" +
        "Week 4 · printed from the town's own record\n" +
        "A QUIET WEEK IN SOUTH PARK"
    sSv.life["paperWeek"] = 4
    sSv.life["paperSummaryDue"] = 1
    val backSv = decodeGameState(encodeGameState(sSv))
    check(Newspaper.summaryDue(backSv) &&
        Newspaper.porchLines(backSv) == Newspaper.porchLines(sSv) &&
        Newspaper.summarySender(backSv) ==
            Newspaper.summarySender(sSv),
        "paper: the porch copy, the summary debt and the " +
            "rotation all survive the save path exactly")
}
}

private fun sectionV0120b(root: String) {
// ================= v0.12.0b: the general store counter =================
// Queue #12 item 2. The walk-to buy surface the garden
// named as missing in v0.11.0b lands as two counters in
// the Mall, in the Mall's own keeperless-counter pattern
// (the Good Shelf, the capsule machine, the transit
// kiosk — Wardrobe.buy's vocabulary: the location IS
// the counter). The garden centre's seed rack sells
// Garden's packets as REAL inventory at the crops' exact
// prices (derived, never re-typed); Garden.plant spends
// a held packet first and keeps its order-at-planting
// path at the same price for everyone else. The snack
// shop — the supplier Stand.STOCK has named all along —
// sells the stand list's four pantry staples into the
// real pantry at the shops' own prices. The loop proof:
// price parity across counter / stand / booth, the
// crate's walls behaviorally intact, and packets —
// ItemDef-less, on the bus pass's pattern — unable to
// enter the gift flow, the fetch pool or the pantry
// disciplines at all.
println("== v0.12.0b: the general store counter — Queue #12 item 2 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.12.0b"),
        "counters: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 89 / 0.12.0b")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "counters: one new module (Shop.kt) — the tree is at " +
            "99 Kotlin files (counted $ktCount)")

    // ---------- helpers ----------
    fun setDayS(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun absOfS(key: String): Int =
        FairCalendar.absDayOfOrdinal(ordinalOfKey(key))
    fun shopState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }

    // ---------- wiring pins ----------
    val gvSrc = File(root,
        "src/com/hunt3r/southparktown/GameView.kt").readText()
    check(gvSrc.contains("Hit(\"fixture\", \"seedrack\"") &&
        gvSrc.contains("Hit(\"fixture\", \"snackcounter\"") &&
        gvSrc.contains("drawSeedRack") &&
        gvSrc.contains("drawSnackCounter"),
        "counters: both fixtures are drawn at the Mall with " +
            "their own tap hits")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("\"seedrack\" -> seedCounterDialog()") &&
        gaSrc.contains("\"snackcounter\" -> goodsCounterDialog()") &&
        gaSrc.contains("Shop.buySeed(state, crop.id, \"Mall\")") &&
        gaSrc.contains("Shop.buyStaple(state, id, \"Mall\")"),
        "counters: the fixture taps open the two dialogs, and " +
            "the dialogs settle at the Mall counter")
    check(Shop.LOC == "Mall" && LOCATIONS["Mall"] != null,
        "counters: both tills live at the Mall")

    // ---------- prices: one number, every table ----------
    check(Shop.STAPLE_IDS == Stand.STOCK.map { it.itemId },
        "counters: the snack shop's stock IS the stand's " +
            "shop list, in order")
    for (id in Shop.STAPLE_IDS) {
        check(Shop.staplePrice(id) ==
            Stand.stockDef(id)?.shopPrice &&
            Shop.staplePrice(id) == Fair.boothPrice(id),
            "counters: $id costs the same at the counter, " +
                "the stand's restock and Liane's booth " +
                "(${Shop.staplePrice(id)} 🪙) — no spread " +
                "exists to arbitrage")
        check(id in Dinners.PANTRY_ITEMS,
            "counters: $id is a pantry staple — counter " +
                "stock lands in the dinners' own universe")
    }
    for (crop in Garden.CROPS) {
        check(Shop.seedPrice(crop.id) == crop.seedPrice,
            "counters: ${crop.id} seed reads its price off " +
                "the crop registry (${crop.seedPrice} 🪙) — " +
                "the rack and the planting order can never " +
                "drift apart")
    }

    // ---------- the seed rack: buy → hold → plant ----------
    val (_, sB) = shopState(12051)
    setDayS(sB, absOfS("20270401"))   // April
    sB.inventory[Minigames.COIN_ITEM] = 20
    val buyP = Shop.buySeed(sB, "potato", "Mall")
    check(buyP.ok && Garden.packetsHeld(sB, "potato") == 1 &&
        Minigames.capsuleCoins(sB) == 18 &&
        (sB.life["gardenSeedSpent"] ?: 0) == 2,
        "seed rack: a packet is real inventory at the exact " +
            "price, and the garden's seed-spent book grows " +
            "by it (${buyP.line})")
    Shop.buySeed(sB, "potato", "Mall")
    Shop.buySeed(sB, "pumpkin", "Mall")
    check(Garden.packetsHeld(sB, "potato") == 2 &&
        Garden.packetsHeld(sB, "pumpkin") == 1 &&
        Minigames.capsuleCoins(sB) == 13 &&
        (sB.life["gardenSeedSpent"] ?: 0) == 7,
        "seed rack: packets stack per crop; every coin is " +
            "accounted (20 − 2 − 2 − 3 = 13, spent 7)")
    val wrongLoc = Shop.buySeed(sB, "corn", "KidsPark")
    check(!wrongLoc.ok && Garden.packetsHeld(sB, "corn") == 0 &&
        Minigames.capsuleCoins(sB) == 13,
        "seed rack: the counter settles only at its own " +
            "counter — a seed bought 'at the park' is notsold")
    check(!Shop.buySeed(sB, "durian", "Mall").ok &&
        Minigames.capsuleCoins(sB) == 13,
        "seed rack: a crop the registry doesn't carry is " +
            "refused, and no coin moves")
    val (_, sPoor) = shopState(12052)
    sPoor.inventory[Minigames.COIN_ITEM] = 1
    check(!Shop.buySeed(sPoor, "pumpkin", "Mall").ok &&
        Garden.packetsHeld(sPoor, "pumpkin") == 0 &&
        Minigames.capsuleCoins(sPoor) == 1 &&
        (sPoor.life["gardenSeedSpent"] ?: 0) == 0,
        "seed rack: no coins, no packet — refused plainly, " +
            "and the book doesn't grow on a refusal")

    // planting FROM the pack: no coin, no new spend, the
    // packet is the payment
    val coinsHeld = Minigames.capsuleCoins(sB)
    val spentHeld = sB.life["gardenSeedSpent"] ?: 0
    val packLine = Garden.plant(sB, 0, "potato")
    check(Garden.bed(sB, 0)?.cropId == "potato" &&
        Garden.packetsHeld(sB, "potato") == 1 &&
        Minigames.capsuleCoins(sB) == coinsHeld &&
        (sB.life["gardenSeedSpent"] ?: 0) == spentHeld &&
        packLine.contains("from a packet"),
        "seed rack: planting spends the packet, not the " +
            "purse — and the spend book doesn't double-count " +
            "($packLine)")
    // a refused planting (out of window) never eats a packet
    Shop.buySeed(sB, "tomato", "Mall")
    val coinsT = Minigames.capsuleCoins(sB)
    val windowLine = Garden.plant(sB, 1, "tomato")
    check(windowLine.contains("goes in") &&
        Garden.bed(sB, 1) == null &&
        Garden.packetsHeld(sB, "tomato") == 1 &&
        Minigames.capsuleCoins(sB) == coinsT,
        "seed rack: April refuses a May–Jun tomato, and " +
            "the refusal costs neither packet nor coin")
    // no packet → the supplier path, exact as it ever was
    val coinsS = Minigames.capsuleCoins(sB)
    val spentS = sB.life["gardenSeedSpent"] ?: 0
    Garden.plant(sB, 2, "sunflower")
    check(Garden.bed(sB, 2)?.cropId == "sunflower" &&
        Minigames.capsuleCoins(sB) == coinsS - 2 &&
        (sB.life["gardenSeedSpent"] ?: 0) == spentS + 2,
        "seed rack: without a packet, planting orders at " +
            "the same 2 🪙 from the same rack — the counter " +
            "is an option, not a tax")
    // the garden page names the pack
    check(Garden.pageLines(sB).any {
            it.contains("Seed packets in your pack") &&
                it.contains("potato ×1") },
        "seed rack: the garden page shows the pack's shelf")

    // ---------- legacy saves & packet discipline ----------
    val (_, sLeg) = shopState(12053)
    check(Garden.packetsHeldTotal(sLeg) == 0 &&
        Garden.pageLines(sLeg).size == 4 &&
        Garden.pageLines(sLeg).none {
            it.contains("Seed packets in your pack") },
        "seed rack: a pre-0.12.0b save holds no packets and " +
            "its garden page reads exactly as before")
    setDayS(sLeg, absOfS("20270401"))
    sLeg.inventory[Minigames.COIN_ITEM] = 30
    Shop.buySeed(sLeg, "corn", "Mall")
    Shop.buySeed(sLeg, "corn", "Mall")
    repeat(40) {
        setDayS(sLeg, sLeg.absDay + 1)
        Garden.dailyRollover(sLeg)
    }
    check(Garden.packetsHeld(sLeg, "corn") == 2,
        "seed rack: packets never expire — forty days of " +
            "rollovers leave the pack exactly as stocked")
    for (id in Garden.PACKET_IDS) {
        check(itemById(id) == null,
            "packets: $id carries no ItemDef — the bus " +
                "pass's pattern, so no item system can " +
                "wander off with it")
        check(id !in Errands.FETCH_POOL &&
            id !in Dinners.PANTRY_ITEMS &&
            Stand.stockDef(id) == null &&
            Errands.sourceOf(id) == null,
            "packets: $id is in no fetch pool, no pantry " +
                "list and no stock def, and Errands' source " +
                "map doesn't know it — planting is its " +
                "only door")
    }
    check(Garden.homegrownItem(sLeg) == null,
        "packets: a pack holding only seed doesn't read " +
            "as a homegrown dish — packets are not produce")
    val giftableMirror = sLeg.inventory.entries
        .filter { it.value > 0 }
        .mapNotNull { itemById(it.key) }.map { it.id }
    check(giftableMirror.none { it in Garden.PACKET_IDS },
        "packets: the gift flow's own read (inventory → " +
            "ItemDef) can never offer a packet — there is " +
            "nothing to gift")

    // ---------- the snack shop: buy → pantry ----------
    val (_, sG) = shopState(12054)
    sG.inventory[Minigames.COIN_ITEM] = 10
    val g1 = Shop.buyStaple(sG, "lemonade", "Mall")
    check(g1.ok && (sG.inventory["lemonade"] ?: 0) == 1 &&
        Minigames.capsuleCoins(sG) == 9 &&
        Shop.goodsSpent(sG) == 1,
        "snack shop: a staple lands in the real pantry at " +
            "the shops' price, and the till's book grows " +
            "(${g1.line})")
    Shop.buyStaple(sG, "cheesy_poof", "Mall")
    check((sG.inventory["cheesy_poof"] ?: 0) == 1 &&
        Minigames.capsuleCoins(sG) == 7 &&
        Shop.goodsSpent(sG) == 3,
        "snack shop: the book accrues across the counter " +
            "(1 + 2 = 3 🪙 of lifetime spend)")
    check(!Shop.buyStaple(sG, "snack_cake", "MainStreet").ok &&
        (sG.inventory["snack_cake"] ?: 0) == 0 &&
        Minigames.capsuleCoins(sG) == 7,
        "snack shop: Main Street is not the counter — " +
            "notsold, and nothing moves")
    check(!Shop.buyStaple(sG, "pumpkin", "Mall").ok &&
        !Shop.buyStaple(sG, "flower", "Mall").ok &&
        Minigames.capsuleCoins(sG) == 7,
        "snack shop: produce and flowers are not counter " +
            "stock — the counter sells its four staples, " +
            "nothing else")
    val (_, sBroke) = shopState(12056)
    check(!Shop.buyStaple(sBroke, "lemonade", "Mall").ok &&
        Shop.goodsSpent(sBroke) == 0 &&
        (sBroke.inventory["lemonade"] ?: 0) == 0,
        "snack shop: an empty purse is refused plainly and " +
            "the book stays shut")

    // ---------- the loop proof ----------
    // The crate's doors are unchanged: Stand.order moves
    // coins into crate stock and provably never touches
    // the pantry — so a counter-bought staple has no way
    // back into a sellable crate.
    val (_, sL) = shopState(12057)
    setDayS(sL, absOfS("20270615"))
    sL.inventory[Minigames.COIN_ITEM] = 100
    Shop.buyStaple(sL, "lemonade", "Mall")
    Shop.buyStaple(sL, "lemonade", "Mall")
    val pantryBefore = sL.inventory["lemonade"] ?: 0
    Stand.setup(sL, "MainStreet")
    Stand.order(sL, "lemonade", 3)
    check((sL.inventory["lemonade"] ?: 0) == pantryBefore &&
        Stand.onHand(sL, "lemonade") == 3,
        "loop: ordering stand stock fills the crate from " +
            "coins alone — the pantry's two counter-bought " +
            "lemonades are exactly where they were")
    check(Stand.stockFromGarden(sL, "lemonade", 1)
            .contains("garden produce only") &&
        (sL.inventory["lemonade"] ?: 0) == pantryBefore,
        "loop: the garden door into the crate still refuses " +
            "a shop staple — provenance or nothing")
    check(Stand.order(sL, Garden.packetId("corn"), 1)
            .contains("doesn't stock that") &&
        Shop.buySeed(sL, "corn", "Mall").ok &&
        Stand.onHand(sL, Garden.packetId("corn")) == 0,
        "loop: a seed packet can't enter the crate by the " +
            "order door either — it isn't stock, it's seed")
    val shopSrc = File(root,
        "src/com/hunt3r/southparktown/Shop.kt").readText()
    check(!shopSrc.contains("fun sell") &&
        !shopSrc.contains("awardCoins"),
        "loop: the counter module has no sell verb and " +
            "awards no coins — both tills are one-way sinks")

    // ---------- save round-trip ----------
    val backB = decodeGameState(encodeGameState(sB))
    check(Garden.packetsHeld(backB, "potato") == 1 &&
        Garden.packetsHeld(backB, "tomato") == 1 &&
        (backB.life["gardenSeedSpent"] ?: 0) ==
            (sB.life["gardenSeedSpent"] ?: 0) &&
        Garden.bed(backB, 0)?.cropId == "potato",
        "counters: packets, the seed book and the beds all " +
            "survive the save path exactly")
    val backG = decodeGameState(encodeGameState(sG))
    check(Shop.goodsSpent(backG) == 3 &&
        (backG.inventory["lemonade"] ?: 0) == 1 &&
        (backG.inventory["cheesy_poof"] ?: 0) == 1,
        "counters: the till's book and the stocked pantry " +
            "survive the save path exactly")
}
}

private fun sectionV0120c(root: String) {
// ================= v0.12.0c: cast birthdays =================
// Queue #12 item 3. The town's birthdays, on the record:
// all 98 cast gain a date in Birthdays.DATES (exactly ONE
// lorebook-sourced — Clyde Donovan, April 10, pinned here
// against the lorebook file itself, re-derived from the
// raw entries so the split can never quietly rot); #55's
// phone beat now covers the roster; the paper prints the
// week's birthdays; a gift on the day pays a stated +3
// and draws the recipient's authored reaction line; and
// a birthday at a dinner household can stand as a small
// party on DINNERS' rails — claim, window, TalkGate rail,
// deference — with a cake beat that eats a real Snacky
// Cake or says so honestly. Disjointness is proven in
// ONE lived time space by a two-year marched sweep.
println("== v0.12.0c: cast birthdays — Queue #12 item 3 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.12.0c"),
        "birthdays: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 91 / 0.12.0d")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "birthdays: one new module (Birthdays.kt) — the tree is at " +
            "105 Kotlin files (counted $ktCount)")

    // ---------- helpers ----------
    fun setDayC(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun absOfC(key: String): Int =
        FairCalendar.absDayOfOrdinal(ordinalOfKey(key))
    fun bState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    // the first party a fresh town can stand, searched
    // forward from a start key — deterministic, because a
    // fresh state's rotation anchor derives from the day.
    fun findParty(fromKey: String, seed: Long):
            Triple<GameState, Birthdays.Party, Int>? {
        val (e, s) = bState(seed)
        var d = absOfC(fromKey)
        repeat(500) {
            setDayC(s, d)
            val p = Birthdays.partyTonight(s)
            if (p != null) return Triple(s, p, d)
            d++
        }
        return null
    }
    fun seatHousehold(s: GameState, p: Birthdays.Party) {
        for (m in p.household.members) {
            val a = s.agents[m] ?: continue
            a.location = p.household.house
            a.asleep = false
        }
        s.timeMin = 18 * 60
    }

    // ---------- wiring pins ----------
    val twSrc = File(root,
        "src/com/hunt3r/southparktown/TownLife.kt").readText()
    check(twSrc.contains("val BIRTHDAYS: Map<String, String> = Birthdays.DATES"),
        "birthdays: TownLife's registry IS Birthdays' table, by reference")
    val tgSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(tgSrc.contains("val partyHit: Birthdays.PartyHit? = null") &&
        tgSrc.contains("Birthdays.talkStepFor(state, npcName)"),
        "birthdays: the party rides the DINNER rail as a payload — no new rail")
    val enSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(enSrc.contains("Birthdays.gatheringBlock(state, a.name, timeMin)") &&
        enSrc.contains("Birthdays.dailyRollover(state)") &&
        enSrc.contains("Birthdays.GIFT_BONUS"),
        "birthdays: claim, wrap and gift dial all wired in the Engine")
    val gaSrc = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(gaSrc.contains("gate.partyHit != null") &&
        gaSrc.contains("Birthdays.judgeTalk(state, kidName)") &&
        gaSrc.contains("Birthdays.lookText(state, me.location)") &&
        gaSrc.contains("Birthdays.reactionFor(npcName)"),
        "birthdays: GameActivity judges party beats, hides the cake " +
            "in the Look, and answers gifts with the birthday line")
    val npSrc = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(npSrc.contains("Birthdays.birthdaysLine(state, week)"),
        "birthdays: the paper's TOWN NEWS carries the week's birthdays")
    val hsSrc = File(root,
        "src/com/hunt3r/southparktown/House.kt").readText()
    check(hsSrc.contains("Birthdays.morningNote(state)"),
        "birthdays: the morning report carries the party and the yield")
    val slSrc = File(root,
        "src/com/hunt3r/southparktown/Sleepovers.kt").readText()
    check(slSrc.contains("Birthdays.partyTonight(state)"),
        "birthdays: a standing party vetoes a same-night sleepover plan")
    val jaSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    check(jaSrc.contains("sectionTitle(\"🎂 BIRTHDAYS\")") &&
        jaSrc.contains("Birthdays.dateLabel(kid)"),
        "birthdays: the Journal gains the 🎂 page and the cast-card date")

    // ---------- the registry ----------
    check(Birthdays.DATES.size == 98 &&
        Birthdays.DATES.keys == CharacterSystem.CAST.keys,
        "registry: exactly the 98 cast hold dates — nobody else, " +
            "nobody missing (got ${Birthdays.DATES.size})")
    check("New Kid" !in Birthdays.DATES &&
        Birthdays.DATES.keys.none { it == "Mom" || it == "Dad" },
        "registry: the PLAYER's character holds no birthday in " +
            "this system — nor do the parents (not cast)")
    val dayCounts = intArrayOf(31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31)
    var allValid = true
    for ((name, md) in Birthdays.DATES) {
        val m = md.substring(0, 2).toIntOrNull() ?: -1
        val d = md.substring(2, 4).toIntOrNull() ?: -1
        if (md.length != 4 || m !in 1..12 ||
            d !in 1..(dayCounts.getOrElse(m - 1) { 0 }))
            allValid = false
    }
    check(allValid,
        "registry: every date is a real month/day — and no Feb 29 " +
            "exists to leak into a leap year")
    val shipped = mapOf(
        "Stan" to "1019", "Kyle" to "0526", "Cartman" to "0701",
        "Kenny" to "0322", "Butters" to "0911", "Wendy" to "1207",
        "Craig" to "0125", "Tweek" to "0817", "Jimmy" to "0206",
        "Tolkien" to "0620", "Clyde" to "0410", "Bebe" to "1103")
    check(shipped.all { Birthdays.DATES[it.key] == it.value } &&
        Birthdays.PRE_EXISTING == shipped.keys,
        "registry: #55's twelve dates stand exactly as shipped")
    val perMonth = IntArray(12)
    for (md in Birthdays.DATES.values)
        perMonth[md.substring(0, 2).toInt() - 1]++
    check(perMonth.all { it in 4..14 },
        "registry: the authored spread covers the year " +
            "(per-month ${perMonth.toList()})")
    val perDay = Birthdays.DATES.values.groupingBy { it }.eachCount()
    check(perDay.values.all { it <= 2 } &&
        perDay.count { it.value == 2 } == 4,
        "registry: shared days exist (four of them, two people " +
            "each) and no day holds more than two — real towns share")

    // ---------- the sourcing pin, vs the lorebook file ----------
    val loreRaw = File(root, "assets/lorebook.json").readText()
    check(loreRaw.contains("born April 10"),
        "sourcing: the lorebook file itself carries the words " +
            "'born April 10'")
    val monthDayRx = Regex("(January|February|March|April|May|" +
        "June|July|August|September|October|November|December)" +
        "\\s+(\\d{1,2})")
    val monthNum = listOf("January", "February", "March", "April",
        "May", "June", "July", "August", "September", "October",
        "November", "December")
    val stated = sortedMapOf<String, String>()
    for (name in KID_ORDER) {
        val text = LoreBook.charLore(name)?.text ?: continue
        val hit = monthDayRx.find(text) ?: continue
        val md = "%02d%02d".format(
            monthNum.indexOf(hit.groupValues[1]) + 1,
            hit.groupValues[2].toInt())
        stated[name] = md
    }
    check(stated == mapOf("Clyde" to "0410"),
        "sourcing: re-derived from the lorebook's own entries, " +
            "exactly ONE cast birthday is stated there — Clyde " +
            "Donovan, April 10 (derived $stated)")
    check(Birthdays.LOREBOOK_SOURCED == setOf("Clyde") &&
        Birthdays.DATES["Clyde"] == "0410",
        "sourcing: the code's split matches the file — Clyde is " +
            "lorebook-sourced, all 97 others are authored, and " +
            "the classes stay distinguishable in code")
    val clydeText = LoreBook.charLore("Clyde")?.text ?: ""
    check(clydeText.contains("born April 10 (per his Facebook " +
        "profile in \"You Have 0 Friends\")"),
        "sourcing: Clyde's date carries its citation in his " +
            "own entry, verbatim")

    // ---------- reactions ----------
    check(Birthdays.REACTIONS.size == 98 &&
        Birthdays.REACTIONS.keys == CharacterSystem.CAST.keys &&
        Birthdays.REACTIONS.values.all { it.isNotBlank() },
        "reactions: one authored birthday line per cast member")
    check(Birthdays.REACTIONS["Kenny"]!!.contains("muffled"),
        "reactions: Kenny's line is muffled — he is never " +
            "given clear speech, birthday or not")
    check(Birthdays.reactionFor("Stan") == Birthdays.REACTIONS["Stan"],
        "reactions: the reader returns the authored line")

    // ---------- derivation ----------
    val (_, sD) = bState(12031)
    setDayC(sD, absOfC("20261019"))
    check(Birthdays.birthdaysToday(sD) == listOf("Stan") &&
        Birthdays.birthdayOf(sD) == "Stan" &&
        birthdayOf(sD) == "Stan" &&
        Birthdays.isBirthday(sD, "Stan") &&
        !Birthdays.isBirthday(sD, "Kyle"),
        "derivation: Oct 19 is Stan's, through both readers")
    setDayC(sD, absOfC("20261020"))
    check(Birthdays.birthdaysToday(sD).isEmpty() &&
        Birthdays.birthdayOf(sD) == null,
        "derivation: Oct 20 belongs to nobody (the #55 pin holds)")
    setDayC(sD, absOfC("20260526"))
    check(Birthdays.birthdaysToday(sD) == listOf("Kyle", "Gerald") &&
        Birthdays.birthdayOf(sD) == "Kyle" &&
        Birthdays.isBirthday(sD, "Gerald"),
        "derivation: a shared day announces the roster-first " +
            "name (Kyle) — and is still Gerald's birthday too")
    check(Birthdays.dateLabel("Stan") == "October 19" &&
        Birthdays.shortLabel("Stan") == "10/19" &&
        Birthdays.dateLabel("Clyde") == "April 10",
        "derivation: the labels read like a calendar")
    setDayC(sD, absOfC("20261018"))
    val up = Birthdays.upcoming(sD, 3)
    check(up.first() == ("Stan" to 1),
        "derivation: the next birthday from Oct 18 is Stan's, " +
            "one day out (got ${up.first()})")

    // ---------- the paper ----------
    run {
        val (_, sP) = bState(12032)
        setDayC(sP, absOfC("20261019"))
        val week = absOfC("20261019") / 7
        val line = Birthdays.birthdaysLine(sP, week)
        check(line != null && line.contains("Stan (10/19)"),
            "paper: the week of Oct 19 prints Stan's birthday " +
                "($line)")
        // the line is EXACTLY the roster + the week's keys
        val expect = ArrayList<String>()
        for (d in 0..6) {
            val key = Commissions.keyForAbsDay(sP, week * 7 + d)
            for (n in Birthdays.birthdaysOn(key))
                expect += "$n (${Birthdays.shortLabel(n)})"
        }
        check(line == "🎂 Birthdays on the record this week: " +
            expect.joinToString(", ") + ".",
            "paper: the printed line is the derivation, whole — " +
                "names + dates only, nothing invented")
        val ed = Newspaper.composeEdition(sP, week)
        val townIdx = ed.lines.indexOf("🗞 TOWN NEWS")
        val sportsIdx = ed.lines.indexOf("🏅 SPORTS")
        val lineIdx = ed.lines.indexOf(line)
        check(townIdx >= 0 && lineIdx > townIdx && lineIdx < sportsIdx,
            "paper: the birthdays stand inside TOWN NEWS, in the " +
                "edition's fixed section order")
    }

    // ---------- the phone ----------
    run {
        // this section's own phone bench (the v0.5.0e
        // helpers are local to their section): a fresh
        // state, the day rolled by the real onNewDay, the
        // BIRTHDAY-trigger texts read off the inbox.
        val engPh = Engine(12043)
        fun freshPh(): GameState {
            val s = engPh.newState()
            engPh.createPlayer(s, "Texter", DEFAULT_APPEARANCE)
            return s
        }
        fun bTexts(s: GameState): List<PhoneText> =
            s.phoneTexts.filter { it.trigger == Phone.BIRTHDAY }
        val sPh = freshPh()
        sPh.gameDay = 18; sPh.todayKey = "20261018"
        engPh.onNewDay(sPh)
        val b = bTexts(sPh)
        check(b.size == 1 && b.single().sender == "Stan" &&
            Phone.BIRTHDAY_LINES.any { it == b.single().text },
            "phone: on the roster's birthdays the ONE fact-only " +
                "beat lands in the birthday person's own thread")
        val sPip = freshPh()
        sPip.gameDay = 23; sPip.todayKey = "20270823"
        // Pip Pirrip's authored date is Aug 24 — a wave-6
        // birthday the #55 system never knew.
        sPip.gameYear = 2027; sPip.gameMonth = 8
        engPh.onNewDay(sPip)
        val bp = bTexts(sPip)
        check(bp.size == 1 && bp.single().sender == "Pip",
            "phone: a wave-6 birthday (Pip, Aug 24) gets its " +
                "beat too — the roster is the whole roster")
        val sShared = freshPh()
        sShared.gameDay = 25; sShared.todayKey = "20260525"
        sShared.gameYear = 2026; sShared.gameMonth = 5
        engPh.onNewDay(sShared)
        val bs = bTexts(sShared)
        // RE-PINNED by v0.15.0i (shared birthdays, whole):
        // this check used to pin the yield itself — ONE
        // beat, from the roster-first name, Gerald's day
        // silent. The whole rule supersedes it: a shared
        // day sends BOTH beats, each in its own thread.
        check(bs.size == 2 &&
            bs.map { it.sender }.toSet() ==
                setOf("Kyle", "Gerald") &&
            bs.all { it.thread == it.sender },
            "phone: a shared day sends BOTH beats — " +
                "Kyle's and Gerald's, each in its own " +
                "thread (v0.15.0i re-pin: the second " +
                "name no longer yields)")
        val sNone = freshPh()
        sNone.gameDay = 19; sNone.todayKey = "20261019"
        engPh.onNewDay(sNone)
        check(bTexts(sNone).isEmpty(),
            "phone: Oct 20 — nobody's birthday, no birthday text")
    }

    // ---------- the gift dial ----------
    run {
        val (eG, sG) = bState(12033)
        val item = "cheesy_poof"
        val (basePts, baseLoved) = giftValue(itemById(item)!!,
            "Stan", emptyList())
        check(!baseLoved, "gift fixture: the poofs are a plain gift for Stan")
        setDayC(sG, absOfC("20261019"))   // Stan's birthday
        sG.friendship["Stan"] = 10
        sG.inventory[item] = 2
        val before = sG.friendship["Stan"]!!
        val msg = eG.giveGift(sG, "Stan", item)
        check(sG.friendship["Stan"] == before + basePts +
            Birthdays.GIFT_BONUS &&
            (sG.inventory[item] ?: 0) == 1 &&
            msg.contains("it's their birthday"),
            "gift: on the day, the gift pays base + " +
                "${Birthdays.GIFT_BONUS} and says so (msg: $msg)")
        setDayC(sG, absOfC("20261020"))   // the day after
        val before2 = sG.friendship["Stan"]!!
        val msg2 = eG.giveGift(sG, "Stan", item)
        check(sG.friendship["Stan"] == before2 + basePts &&
            !msg2.contains("birthday"),
            "gift: off the day, the same gift pays the plain " +
                "base — the dial is the day, nothing else")
        // the dial is the PERSON's day, not the announcer's:
        // Gerald shares Kyle's date and still gets his bonus.
        val (baseG, _) = giftValue(itemById(item)!!,
            "Gerald", emptyList())
        setDayC(sG, absOfC("20260526"))
        sG.friendship["Gerald"] = 10
        sG.inventory[item] = 1
        eG.giveGift(sG, "Gerald", item)
        check(sG.friendship["Gerald"] == 10 + baseG + Birthdays.GIFT_BONUS,
            "gift: on a shared day the bonus belongs to the " +
                "person gifted, not the announced name")
        check(Birthdays.GIFT_BONUS == 3,
            "gift: the dial is stated — a flat +3, once per " +
                "gift, only on the recipient's day")
    }

    // ---------- the party: claim, beats, cake, wrap ----------
    val found = findParty("20261001", 12034)
    check(found != null,
        "party: a fresh town can stand a birthday party")
    if (found != null) {
        val (sParty, party, partyDay) = found
        val hid = party.def.householdId
        check(party.person in party.household.members &&
            Dinners.householdOf(party.person)?.id == hid &&
            Birthdays.isBirthday(sParty, party.person),
            "party: the guest of honor is the birthday person " +
                "of the host household (${party.person}, " +
                "${party.household.family})")
        check(Birthdays.partyYield(sParty) == null &&
            Birthdays.morningNote(sParty)
                ?.contains("Birthday party tonight") == true,
            "party: while one stands, no yield is reported and " +
                "the morning report announces it (bring a cake)")
        // the claim
        val outsider = KID_ORDER.first {
            it !in party.household.members }
        check(Birthdays.gatheringBlock(sParty, party.person,
                18 * 60)?.location == party.household.house &&
            Birthdays.gatheringBlock(sParty, outsider, 18 * 60) == null &&
            Birthdays.gatheringBlock(sParty, party.person, 12 * 60) == null,
            "party: the claim holds the household at its house " +
                "in the dinner window, and nobody else, never")
        // the beats, on the rail
        seatHousehold(sParty, party)
        val gate0 = TalkGate.gateFor(sParty, party.household.host,
            party.household.house)
        check(gate0.rail == TalkGate.Rail.DINNER &&
            gate0.partyHit?.stepIndex == 0 && gate0.sleepHit == null,
            "party: the host's Talk in the window is the " +
                "welcome, on the DINNER rail")
        val nonHost = party.household.members
            .first { it != party.household.host }
        check(Birthdays.talkStepFor(sParty, nonHost) == null,
            "party: the welcome is the host's to give — a " +
                "member's Talk waits its beat")
        val hit0 = Birthdays.judgeTalk(sParty, party.household.host)
        check(hit0?.stepIndex == 0 &&
            Birthdays.stepsDone(sParty, hid) == 1,
            "party: the welcome lands")
        val hit1 = Birthdays.judgeTalk(sParty, party.person)
        check(hit1 != null && hit1.stepIndex == 1 &&
            hit1.text == party.def.wish
                .replace("{P}", party.person),
            "party: talked to directly, the guest of honor " +
                "makes the wish")
        // the cake, brought: exactly one real cake
        sParty.inventory[Birthdays.CAKE_ITEM] = 2
        val cakeText = Birthdays.lookText(sParty,
            party.household.house)
        check(cakeText == party.def.cakeBrought
            .replace("{P}", party.person) &&
            (sParty.inventory[Birthdays.CAKE_ITEM] ?: 0) == 1 &&
            Birthdays.stepsDone(sParty, hid) == 3,
            "party: the cake beat serves ONE real Snacky Cake " +
                "out of the pack (2 → 1) and lands the evening")
        check(Birthdays.lookText(sParty, party.household.house) == null &&
            (sParty.inventory[Birthdays.CAKE_ITEM] ?: 0) == 1,
            "party: the cake beat fires once — a second Look " +
                "takes nothing more")
        // the wrap: full evening pays the table's scale,
        // the guest of honor extra
        val frBefore = party.household.members
            .associateWith { sParty.friendship[it] ?: 0 }
        setDayC(sParty, partyDay + 1)
        Birthdays.dailyRollover(sParty)
        var wrapOk = true
        for (m in party.household.members) {
            var want = frBefore[m]!! +
                if (m == party.household.host)
                    Birthdays.WRAP_HOST_FULL else Birthdays.WRAP_MEMBER_FULL
            if (m == party.person) want += Birthdays.WRAP_HONOR_FULL
            if ((sParty.friendship[m] ?: 0) != minOf(100, want))
                wrapOk = false
        }
        check(wrapOk,
            "party: the full-evening wrap pays host +" +
                "${Birthdays.WRAP_HOST_FULL} / members +" +
                "${Birthdays.WRAP_MEMBER_FULL}, the guest of " +
                "honor +${Birthdays.WRAP_HONOR_FULL} more")
        check((sParty.life["bdayParties"] ?: 0) == 1 &&
            Birthdays.nightLine(sParty, hid)
                ?.contains(party.person) == true &&
            Birthdays.morningNote(sParty)?.startsWith("🎂 " +
                party.person) == true,
            "party: the night goes on the record and rides " +
                "the next morning's report")
        val jl = Birthdays.journalLines(sParty)
        check(jl.any { it.contains("parties you've been part of: 1") },
            "party: the 🎂 page counts the party")
    }

    // ---------- the party: the honest cake ----------
    run {
        val f2 = findParty("20270301", 12035)
        check(f2 != null, "party (bare): a second party stands")
        if (f2 != null) {
            val (sB, pB, _) = f2
            seatHousehold(sB, pB)
            Birthdays.judgeTalk(sB, pB.household.host)
            Birthdays.judgeTalk(sB, pB.person)
            check((sB.inventory[Birthdays.CAKE_ITEM] ?: 0) == 0,
                "party (bare): the pack holds no cake")
            val bare = Birthdays.lookText(sB, pB.household.house)
            check(bare == pB.def.cakeBare.replace("{P}", pB.person) &&
                Birthdays.stepsDone(sB, pB.def.householdId) == 3,
                "party (bare): with no cake held, the beat says " +
                    "so and the household improvises — nothing " +
                    "is consumed because nothing was brought")
        }
    }

    // ---------- the party: a partial evening, and none ----------
    run {
        val f3 = findParty("20280101", 12036)
        check(f3 != null, "party (partial): a third party stands")
        if (f3 != null) {
            val (sP3, p3, d3) = f3
            seatHousehold(sP3, p3)
            Birthdays.judgeTalk(sP3, p3.household.host)   // welcome only
            val frB = p3.household.members
                .associateWith { sP3.friendship[it] ?: 0 }
            setDayC(sP3, d3 + 1)
            Birthdays.dailyRollover(sP3)
            var ok = true
            for (m in p3.household.members) {
                var want = frB[m]!! +
                    if (m == p3.household.host)
                        Birthdays.WRAP_HOST_PART
                    else Birthdays.WRAP_MEMBER_PART
                if (m == p3.person) want += Birthdays.WRAP_HONOR_PART
                if ((sP3.friendship[m] ?: 0) != minOf(100, want))
                    ok = false
            }
            check(ok && (sP3.life["bdayParties"] ?: 0) == 1,
                "party (partial): one beat in still counts the " +
                    "evening, at the partial scale")
        }
        val f4 = findParty("20290101", 12037)
        if (f4 != null) {
            val (sP4, _, d4) = f4
            setDayC(sP4, d4 + 1)
            Birthdays.dailyRollover(sP4)
            check((sP4.life["bdayParties"] ?: 0) == 0,
                "party (missed): a party nobody reached leaves " +
                    "no record and pays nobody — the evening " +
                    "simply went elsewhere")
        }
    }

    // ---------- the yields, named ----------
    run {
        // the dinner rotation claims the evening: find an
        // eligible birthday that falls on an invitation day
        // in a marched town, and read the yield off it.
        val (eY, sY) = bState(12038)
        var yieldInvite: Pair<String, String>? = null
        var yieldNote: String? = null
        var d = absOfC("20261001")
        while (yieldInvite == null && d < absOfC("20281001")) {
            setDayC(sY, d)
            Dinners.dailyRollover(sY)
            val y = Birthdays.partyYield(sY)
            if (y != null && y.second.contains("dinner rotation")) {
                yieldInvite = y
                yieldNote = Birthdays.morningNote(sY)
            }
            d++
        }
        check(yieldInvite != null,
            "yield: some eligible birthday loses its evening " +
                "to the dinner rotation, and the yield NAMES " +
                "it ($yieldInvite)")
        check(yieldNote?.contains("no party tonight") == true &&
            yieldNote?.contains("still counts") == true,
            "yield: the morning report states the yield and " +
                "what still counts, the same morning ($yieldNote)")
        // the Journal states the yield plainly
        val (eJ, sJ) = bState(12039)
        var dJ = absOfC("20261001")
        var yieldLines: List<String>? = null
        while (yieldLines == null && dJ < absOfC("20281001")) {
            setDayC(sJ, dJ)
            Dinners.dailyRollover(sJ)
            if (Birthdays.partyYield(sJ) != null)
                yieldLines = Birthdays.journalLines(sJ)
            dJ++
        }
        check(yieldLines?.any { it.contains("No party for") &&
                it.contains("still counts") } == true,
            "yield: the 🎂 page states the yield and what " +
                "still counts, in plain words")
    }

    // ---------- the sleepover veto ----------
    run {
        // a Friday with a standing party: plan-time refusal
        val (eS, sS) = bState(12040)
        var d = absOfC("20261001")
        var vetoSeen: String? = null
        while (vetoSeen == null && d < absOfC("20281001")) {
            setDayC(sS, d)
            Dinners.dailyRollover(sS)
            if (Sleepovers.isSleepoverDay(d) &&
                Birthdays.partyTonight(sS) != null)
                vetoSeen = Sleepovers.nightBlock(sS)
            d++
        }
        check(vetoSeen?.contains("birthday party") == true,
            "veto: on a Friday a standing party owns, the " +
                "sleepover plan refuses by name ($vetoSeen)")
    }

    // ---------- the two-year sweep, ONE time space ----------
    run {
        val (eW, sW) = bState(12041)
        var parties = 0
        var eligibleDays = 0
        var inviteYields = 0
        var violations = 0
        val start = absOfC("20261001")
        for (d in start until start + 730) {
            setDayC(sW, d)
            Dinners.dailyRollover(sW)
            Birthdays.dailyRollover(sW)
            val eligible = Birthdays.birthdaysToday(sW).any {
                Dinners.householdOf(it) != null }
            val p = Birthdays.partyTonight(sW)
            if (p != null) {
                parties++
                val house = p.household
                // a standing party's evening is CLEAR of
                // every rival claim — each named, each read
                // in this same lived state. (An invitation
                // to ANOTHER table is not a rival claim —
                // it is the player's own choice between two
                // evenings; an invitation to THIS table is.)
                Dinners.todaysInvite(sW)?.let { inv ->
                    if (inv.id == house.id) violations++ }
                if (Dinners.hostingTonight(sW) != null) violations++
                if (Family.dinnerTonight(sW)) violations++
                if (Dinners.collides(sW, house)) violations++
                if (Finales.windowAt(sW) != null) violations++
                if (HolidayBeats.activeBeat(sW) != null) violations++
                if (MovieNights.anyClimaxDueTonight(sW)) violations++
                if (Dinners.beatsDeferred(sW)) violations++
                if (Play.nightCanHappen(sW)) violations++
                if (Fair.windowToday(sW) != null) violations++
                if (Carnival.windowToday(sW) != null) violations++
                if (Sleepovers.plannedTonight(sW)) violations++
                if (Birthdays.partyBlock(sW, p.def) != null) violations++
            } else if (eligible) {
                eligibleDays++
                val y = Birthdays.partyYield(sW)
                if (y == null) violations++
                else if (y.second.contains("dinner rotation"))
                    inviteYields++
            }
        }
        check(violations == 0,
            "sweep: across 730 lived days, no standing party " +
                "ever shares its evening with a rival claim, " +
                "and every eligible birthday that got no party " +
                "names a real reason ($violations violations)")
        check(parties >= 12 && eligibleDays >= 3 && inviteYields >= 1,
            "sweep: the layer actually lives — $parties parties " +
                "stood, $eligibleDays eligible birthdays yielded, " +
                "$inviteYields of them to the dinner rotation, " +
                "in two years")
    }

    // ---------- save round-trip ----------
    run {
        val f5 = findParty("20300101", 12042)
        check(f5 != null, "round-trip: a party stands in 2030")
        if (f5 != null) {
            val (sR, pR, _) = f5
            seatHousehold(sR, pR)
            Birthdays.judgeTalk(sR, pR.household.host)
            sR.inventory[Birthdays.CAKE_ITEM] = 1
            Birthdays.judgeTalk(sR, pR.person)
            Birthdays.lookText(sR, pR.household.house)
            val back = decodeGameState(encodeGameState(sR))
            check(Birthdays.stepsDone(back, pR.def.householdId) == 3 &&
                (back.inventory[Birthdays.CAKE_ITEM] ?: 0) == 0 &&
                back.lifeText["bdayPerson:${pR.def.householdId}"] ==
                    pR.person,
                "round-trip: a party mid-evening — beats, the " +
                    "eaten cake, the guest of honor — survives " +
                    "the real save path exactly")
        }
    }
}
}

private fun sectionV0120d(root: String) {
// ================= v0.12.0d: sleepwear =================
// Queue #12 item 4. Sleepover nights LOOK like sleepover
// nights, closing the gap v0.11.0c recorded. In Heroes'
// spirit exactly: a pajama code ("top|bottom|cap")
// derived deterministically from each figure's own
// sheet (top from their shirt color, bottoms from their
// pants color, softened for lamplight; hats off, the
// spec's own hair — a nightcap only for the soft-knit
// day hats), frozen onto PhotoFigure beside `hero` at
// shutter time when a photo is composed at Your House
// on a live sleepover night, and rendered through
// KidArt's one sleep pass so the album, the street
// re-render and the darkroom agree. Solids only — the
// trypophobia guard below scans the tables and the ink
// for any pattern motif at all.
println("== v0.12.0d: sleepwear — Queue #12 item 4 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.12.0d"),
        "sleepwear: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 91 / 0.12.0d")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "sleepwear: one new module (Sleepwear.kt) — the tree is at " +
            "105 Kotlin files (counted $ktCount)")

    // ---------- helpers ----------
    fun setDayD(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun slpDState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        var d = 0
        while (!Sleepovers.isSleepoverDay(d)) d++
        setDayD(s, d)
        return e to s
    }
    /** Stage a live night directly (the save format is
     *  the contract): plan standing, everyone in the
     *  room at your house, the evening open. */
    fun stageNightD(s: GameState, guests: List<String>,
                    hour: Int = 19) {
        s.life["slpDay"] = s.absDay
        s.lifeText["slpGuests"] = guests.joinToString(",")
        for (g in guests) {
            val a = s.agents[g] ?: continue
            a.location = YOUR_HOUSE; a.asleep = false
        }
        val me = s.agents.values.first { it.isPlayer }
        me.location = YOUR_HOUSE; me.asleep = false
        s.timeMin = hour * 60
    }
    val kidSheets = KidArt.SHEETS.filter { (n, _) ->
        Sleepovers.isKidBand(n) }
    check(kidSheets.isNotEmpty(),
        "sleepwear: the kid sheets are there to derive from")

    // ---------- the derivation: determinism + provenance ----------
    run {
        for ((name, spec) in kidSheets) {
            val c1 = Sleepwear.codeFor(name)
            val c2 = Sleepwear.codeFor(name)
            check(c1 == c2 && c1.isNotEmpty(),
                "sleepwear: $name's pajama code is deterministic")
            val p = Sleepwear.parseCode(c1)
            check(p != null &&
                p.first == Sleepwear.softenHex(spec.top) &&
                p.second == Sleepwear.softenHex(spec.bottom),
                "sleepwear: $name's pajamas come from their OWN " +
                    "palette — top from their shirt, bottoms from " +
                    "their pants, softened")
            check(p != null && (p.third == "cap") ==
                (spec.hatId in Sleepwear.NIGHTCAP_HATS),
                "sleepwear: $name's nightcap flag reads off their " +
                    "day hat — soft knits keep a cap, the rest " +
                    "sleep bare-headed")
        }
        check(Sleepwear.NIGHTCAP_HATS == setOf(
            "beanie", "pomhat", "ushanka", "chullo", "trapper"),
            "sleepwear: the nightcap table is exactly the five " +
                "soft-knit day hats — hat ids only, nothing else " +
                "can ride it")
        check(Sleepwear.softenHex("#c02828").let {
            val r = it.substring(1, 3).toInt(16)
            val g = it.substring(3, 5).toInt(16)
            val b = it.substring(5, 7).toInt(16)
            // hue order kept (red still leads) and the
            // saturation spread narrows: 192/40/40 spreads
            // 152 raw; the softened pair must spread less
            r > g && r > b && (r - b) < (0xc0 - 0x28)
        }, "sleepwear: softening keeps the hue family and " +
            "flattens it — a red shirt sleeps in warm rose, " +
            "not street red")
        check(Sleepwear.softenHex("not-a-color") == "not-a-color" &&
            Sleepwear.parseCode("") == null &&
            Sleepwear.parseCode("a|b") == null &&
            Sleepwear.parseCode("#fff|#000|dots") == null &&
            Sleepwear.parseCode("#fff|#000") == null,
            "sleepwear: bad codes parse to nothing, never to " +
                "a guess")
        check(Sleepwear.playerCode(DEFAULT_APPEARANCE) ==
            Sleepwear.codeFromSpec(avatarSpec(DEFAULT_APPEARANCE)) &&
            Sleepwear.playerCode(DEFAULT_APPEARANCE) ==
            Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "sleepwear: your code derives from your creator " +
                "appearance the same way, deterministically")
    }

    // ---------- the sleep spec ----------
    run {
        val capKid = kidSheets.entries.first {
            it.value.hatId in Sleepwear.NIGHTCAP_HATS }
        val bareKid = kidSheets.entries.first {
            it.value.hatId == "none" }
        val cs = Sleepwear.sleepSpec(capKid.value,
            Sleepwear.codeFor(capKid.key))
        val parsed = Sleepwear.parseCode(
            Sleepwear.codeFor(capKid.key))!!
        check(cs.top == parsed.first && cs.bottom == parsed.second &&
            cs.bottomStyle == "pants" &&
            cs.collarHex == parsed.second,
            "sleepwear: the sleep spec wears the softened pair, " +
                "pajama pants, and ONE trim — the collar band in " +
                "the bottoms' color")
        check(cs.hatId == Sleepwear.NIGHTCAP_ID &&
            cs.hatColor == parsed.first &&
            cs.hatAccent == parsed.second,
            "sleepwear: a soft-knit kid's nightcap wears the " +
                "pajama colors — top for the cap, bottoms for " +
                "its single band")
        val bs = Sleepwear.sleepSpec(bareKid.value,
            Sleepwear.codeFor(bareKid.key))
        check(bs.hatId == "none" &&
            bs.hairStyle == bareKid.value.hairStyle &&
            bs.hairColor == bareKid.value.hairColor,
            "sleepwear: hats off otherwise — the spec's own " +
                "hair, exactly as the sheet has it")
        check(!cs.placket && !cs.buttons && cs.pockets == 0 &&
            !cs.tie && !cs.backpack && cs.backStyle == "none" &&
            cs.scarfHex == null && cs.handColor == null,
            "sleepwear: the day clothes' construction strips " +
                "off — pajamas are plain, hands bare")
        check(cs.skin == capKid.value.skin &&
            cs.sig == capKid.value.sig &&
            cs.special == capKid.value.special &&
            cs.measured == capKid.value.measured,
            "sleepwear: everything that IS the kid survives — " +
                "skin, sig, special, measured proportions")
        check(Sleepwear.sleepSpec(capKid.value, "junk") ==
            capKid.value,
            "sleepwear: a bad code changes nothing — street " +
                "clothes, like a bad hero code")
        val kenny = KidArt.SHEETS["Kenny"]
        check(kenny != null && Sleepwear.sleepSpec(kenny,
            Sleepwear.codeFor("Kenny")).special == "kenny_parka",
            "sleepwear: Kenny sleeps in his parka hood — the " +
                "hero pass's rule for specials is this pass's too")
    }

    // ---------- trypophobia guard ----------
    run {
        val src = File(root,
            "src/com/hunt3r/southparktown/Sleepwear.kt").readText()
            .lowercase()
        val ink = File(root,
            "src/com/hunt3r/southparktown/CharacterSystem.kt")
            .readText().lowercase()
        for (motif in listOf("polka", "gingham", "plaid",
                "checkered", "argyle", "herringbone")) {
            check(!src.contains(motif) && !ink.contains(motif),
                "sleepwear: no pattern vocabulary anywhere near " +
                    "the night clothes ($motif)")
        }
        // the ink itself, structurally: a nightcap is exactly
        // three single shapes (dome, one band, one bobble) —
        // no role repeats, so no motif can repeat
        for ((name, spec) in kidSheets) {
            if (spec.special == "kenny_parka") continue
            val ss = Sleepwear.sleepSpec(spec, Sleepwear.codeFor(name))
            val hats = HeadStack.layers(ss)
                .filter { it.kind == InkKind.HAT }
            val roles = hats.map { it.role }
            check(roles.size <= 3 &&
                roles.distinct().size == roles.size &&
                roles.all { it in setOf("dome", "band", "trim") },
                "sleepwear: $name's night ink is single shapes " +
                    "only — no repeated motif can exist in it")
            check(hats.all { it.color == ss.top ||
                it.color == ss.bottom },
                "sleepwear: $name's nightcap wears only the " +
                    "pajama pair — two solid colors, no third")
            check(Sleepwear.sleepSpec(spec,
                Sleepwear.codeFor(name)).sig == spec.sig,
                "sleepwear: $name gains no decoration channel " +
                    "in pajamas — the sig is untouched")
        }
    }

    // ---------- the freeze ----------
    run {
        val guests = listOf("Stan", "Kyle", "Wendy")
        val (e, s) = slpDState(930_010)
        stageNightD(s, guests)
        s.agents["Cartman"]?.location = YOUR_HOUSE
        s.agents["Randy"]?.location = YOUR_HOUSE
        val rec = Photos.compose(s,
            guests + listOf("Cartman", "Randy"), emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        check(rec.locId == YOUR_HOUSE,
            "sleepwear: the staged frame is at your house")
        for (g in guests) {
            check(rec.figures.firstOrNull { it.name == g }?.sleep ==
                Sleepwear.codeFor(g),
                "sleepwear: $g freezes in their own pajamas")
        }
        check(rec.figures.firstOrNull { it.kind == "player" }
            ?.sleep == Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "sleepwear: ...and you freeze in yours")
        check(rec.figures.firstOrNull { it.name == "Cartman" }
            ?.sleep == "",
            "sleepwear: a kid at the house who is NOT a guest " +
                "of the night stays in street clothes")
        check(rec.figures.firstOrNull { it.name == "Randy" }
            ?.sleep == "",
            "sleepwear: an adult in frame never freezes — " +
                "grown-ups don't do sleepovers")
        check(rec.figures.all { it.hero == "" },
            "sleepwear: a Friday-night frame freezes no capes — " +
                "the two passes never share a moment")
        // the group composer freezes the same way
        val (e2, s2) = slpDState(930_011)
        stageNightD(s2, guests)
        val grec = Photos.composeGroup(s2, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        check(grec.figures.firstOrNull { it.name == "Stan" }
            ?.sleep == Sleepwear.codeFor("Stan") &&
            grec.figures.firstOrNull { it.kind == "player" }
                ?.sleep == Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "sleepwear: the group frame freezes identically")
        // the walls, read at the seam itself
        check(Sleepwear.figureCode(s,
                PhotoFigure("Randy", "cast", "happy"),
                YOUR_HOUSE) == "",
            "sleepwear: figureCode dresses no adult, ever")
        val (e3, s3) = slpDState(930_012)
        stageNightD(s3, listOf("Stan", "Randy"))
        check(Sleepwear.figureCode(s3,
                PhotoFigure("Randy", "cast", "happy"),
                YOUR_HOUSE) == "",
            "sleepwear: even a plan tampered to name an adult " +
                "freezes nothing on him — the kid bands are " +
                "re-checked at the seam")
        check(Sleepwear.figureCode(s,
                PhotoFigure("Aunt Flo", "resident", "happy"),
                YOUR_HOUSE) == "" &&
            Sleepwear.figureCode(s,
                PhotoFigure("Stan", "cast", "happy"),
                "KidsPark") == "",
            "sleepwear: residents never freeze, and a guest " +
                "named in a frame composed elsewhere freezes " +
                "nothing either")
    }

    // ---------- non-qualifying frames freeze nothing ----------
    run {
        val guests = listOf("Stan", "Kyle")
        // the same Friday, at noon: a day photo
        val (e1, s1) = slpDState(930_020)
        stageNightD(s1, guests, hour = 12)
        val noon = Photos.compose(s1, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        check(noon.figures.all { it.sleep == "" },
            "sleepwear: a noon frame at the house on a planned " +
                "day freezes nothing — the evening has not opened")
        // evening, live plan, but the frame is at the park
        val (e2, s2) = slpDState(930_021)
        stageNightD(s2, guests)
        s2.agents.values.first { it.isPlayer }.location =
            "KidsPark"
        for (g in guests) s2.agents[g]?.location = "KidsPark"
        val park = Photos.compose(s2, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        check(park.locId == "KidsPark" &&
            park.figures.filter { it.kind != "player" }
                .all { it.sleep == "" } &&
            park.figures.firstOrNull { it.kind == "player" }
                ?.sleep == Sleepwear.streetCode(s2) &&
            Sleepwear.streetCode(s2).isNotEmpty(),
            "sleepwear: a frame composed anywhere else freezes " +
                "nothing for the CAST, live night or not — " +
                "guests' pajamas live at the house (v0.15.0a " +
                "re-pin: the PLAYER figure abroad in the live " +
                "evening now freezes exactly streetCode — the " +
                "walk-home window the preview pass opened; " +
                "the blanket pre-0.15.0a claim is the gap that " +
                "build closed, for the player only)")
        // evening at the house, no plan standing
        val (e3, s3) = slpDState(930_022)
        s3.agents.values.first { it.isPlayer }.location =
            YOUR_HOUSE
        for (g in guests) {
            s3.agents[g]?.location = YOUR_HOUSE
            s3.agents[g]?.asleep = false
        }
        s3.timeMin = 19 * 60
        val plain = Photos.compose(s3, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        check(plain.figures.all { it.sleep == "" },
            "sleepwear: the house outside a live sleepover " +
                "freezes nothing")
    }

    // ---------- records: round-trips, non-retroactivity, coexistence ----------
    run {
        val guests = listOf("Stan", "Kyle")
        val (e, s) = slpDState(930_030)
        stageNightD(s, guests)
        val rec = Photos.compose(s, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        val rt = PhotoRecord.fromMap(rec.toMap())
        check(rt != null && rt == rec &&
            rt.figures.firstOrNull { it.name == "Stan" }?.sleep ==
                Sleepwear.codeFor("Stan"),
            "sleepwear: the freeze survives the record's own " +
                "serialization — the album and the darkroom " +
                "will render the pajamas forever")
        val jsonRt = PhotoRecord.fromMap((Json.parse(
            Json.stringify(rec.toMap())) as Map<String, Any?>))
        check(jsonRt == rec,
            "sleepwear: ...through the actual JSON save format")
        val legacy = PhotoFigure.fromMap(mapOf(
            "name" to "Stan", "kind" to "cast", "mood" to "happy",
            "pose" to "none", "reaction" to "happy", "points" to 3,
            "hero" to "#123456|#234567|star"))
        check(legacy != null && legacy.sleep == "" &&
            legacy.hero == "#123456|#234567|star",
            "sleepwear: a pre-0.12.0d figure (no sleep key) " +
                "loads in street clothes — NOT retroactive — " +
                "and its hero freeze is untouched")
        val both = PhotoFigure("Stan", "cast", "happy",
            hero = "#123456|#234567|star",
            sleep = Sleepwear.codeFor("Stan"))
        val bothRt = PhotoFigure.fromMap(both.toMap())
        check(bothRt != null && bothRt.hero == both.hero &&
            bothRt.sleep == both.sleep,
            "sleepwear: hero and sleepwear coexist on one " +
                "record, each field keeping its own freeze")
        // a street-clothes record stays street clothes
        val (e2, s2) = slpDState(930_031)
        s2.timeMin = 12 * 60
        val day = Photos.compose(s2, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        val dayRt = PhotoRecord.fromMap(day.toMap())
        check(dayRt != null &&
            dayRt.figures.all { it.sleep == "" },
            "sleepwear: an ordinary record round-trips with " +
                "empty sleep everywhere")
    }

    // ---------- render-path agreement ----------
    run {
        val ks = File(root,
            "src/com/hunt3r/southparktown/KidArt.kt").readText()
        val pv = File(root,
            "src/com/hunt3r/southparktown/PhotoView.kt").readText()
        val gv = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        check(ks.contains("fun drawSleepFigure") &&
            ks.contains("Sleepwear.sleepSpec") &&
            pv.contains("PaperDoll.drawDollSleep") &&
            File(root, "src/com/hunt3r/southparktown/PaperDoll.kt")
                .readText().contains("KidArt.drawSleepFigure") &&
            pv.contains("fig.sleep"),
            "sleepwear: the album, the street re-render and " +
                "the darkroom prints all paint records through " +
                "PhotoView — and PhotoView draws pajamas through " +
                "KidArt's one sleep pass, from the frozen code " +
                "(v0.16.0d: reached through the PaperDoll " +
                "stills path, which wraps the same pass)")
        check(gv.split("KidArt.drawSleepFigure").size - 1 == 2 &&
            gv.indexOf("KidArt.drawSleepFigure") >
                gv.indexOf("the MIRROR (right wall strip)") &&
            gv.indexOf("KidArt.drawSleepFigure") <
                gv.indexOf("the ALBUM BOOK (on the desk") &&
            gv.lastIndexOf("KidArt.drawSleepFigure") >
                gv.indexOf("private fun drawFigures"),
            "sleepwear: GameView draws the sleep pass exactly " +
                "twice (v0.15.0a re-pin: the preview pass added " +
                "the street's walk-home draw) — your reflection " +
                "in the house mirror, inside the mirror " +
                "fixture's own block, and you standing in the " +
                "street in the walk-home window, inside " +
                "drawFigures; no third surface draws it")
        // the ink renders the nightcap where the code says so
        val capKid = kidSheets.entries.first {
            it.value.hatId in Sleepwear.NIGHTCAP_HATS }
        val ss = Sleepwear.sleepSpec(capKid.value,
            Sleepwear.codeFor(capKid.key))
        val hatInk = HeadStack.layers(ss)
            .filter { it.kind == InkKind.HAT }
        check(hatInk.map { it.role }.toSet() ==
            setOf("dome", "band", "trim") &&
            !HeadStack.hatCoversHair(Sleepwear.NIGHTCAP_ID),
            "sleepwear: the nightcap inks as dome + one band + " +
                "one bobble, a perch over the kid's full hair — " +
                "not a covering hat")
        val bareKid = kidSheets.entries.first {
            it.value.hatId == "none" && it.value.special == null }
        val bss = Sleepwear.sleepSpec(bareKid.value,
            Sleepwear.codeFor(bareKid.key))
        check(HeadStack.layers(bss)
            .none { it.kind == InkKind.HAT } &&
            HeadStack.layers(bss)
                .any { it.kind == InkKind.HAIR },
            "sleepwear: a bare-headed kid's night ink is hair " +
                "only — hats off, rendered, not described")
    }
}
}

// ================= v0.12.0e: the attic =================
/** Queue #12 item 5: Your House gains an upstairs fixture
 *  whose contents are DERIVED on every read — the overflow
 *  shelf (what the trophy shelf's two caps can't hold),
 *  the family frame's outtakes (the home family photos
 *  that aren't in the frame, plus any a darkroom print
 *  still holds), and one stored box per FINISHED case,
 *  public shape only. Zero new save keys, no economy. */
private fun sectionV0120e(root: String) {
println("== v0.12.0e: the attic — Queue #12 item 5 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.12.0e"),
        "attic: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 92 / 0.12.0e")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "attic: one new module (Attic.kt) — the tree is at " +
            "105 Kotlin files (counted $ktCount)")

    // ---------- helpers ----------
    fun atticState(seed: Long): GameState {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return s
    }
    fun famPhoto(id: String, label: String, locId: String,
                 vararg names: String): PhotoRecord = PhotoRecord(
        id = id, dayKey = "20260101", dateLabel = label,
        timeMin = 600, locId = locId, inside = true,
        weatherId = "light_snow", appearance = DEFAULT_APPEARANCE,
        figures = listOf(PhotoFigure("New Kid", "player", "happy",
            reaction = "player")) + names.map {
            PhotoFigure(it, "resident", "happy", reaction = "happy") })

    // ---------- a fresh house: the attic is honestly bare ----------
    run {
        val s = atticState(940_001)
        check(Attic.isBare(s),
            "attic: a fresh save's attic is bare — nothing " +
                "overflows, no family photo, no closed case")
        check(Attic.overflowCollectibles(s).isEmpty() &&
            Attic.overflowCups(s) == 0 && Attic.outtakes(s).isEmpty() &&
            Attic.caseBoxes(s).isEmpty(),
            "attic: every derivation reads empty on a fresh save")
        val page = Attic.pageLines(s)
        check(page.any { "Bare boards" in it } &&
            page.any { "No family photos yet" in it } &&
            page.any { "No boxes yet" in it },
            "attic: the bare page SAYS so, three times, plainly")
    }

    // ---------- the overflow shelf ----------
    run {
        val s = atticState(940_002)
        // fill the shelf exactly: nothing overflows yet
        for (c in COLLECTIBLES.take(House.SHELF_SLOTS))
            s.collected.add(c.id)
        check(Attic.overflowEmpty(s) &&
            Attic.overflowLines(s).any { "Bare boards" in it },
            "attic: a collection that fits the shelf overflows " +
                "nothing — the attic shows none, honestly")
        // one past the shelf: exactly that one lives upstairs
        val extra = COLLECTIBLES[House.SHELF_SLOTS]
        s.collected.add(extra.id)
        check(Attic.overflowCollectibles(s) == listOf(extra),
            "attic: the first collectible past the shelf's " +
                "${House.SHELF_SLOTS} slots is the overflow, exactly")
        // the whole collection: the tail, in registry order,
        // disjoint from the shelf's own slots
        for (c in COLLECTIBLES) s.collected.add(c.id)
        val ov = Attic.overflowCollectibles(s)
        val shelfIds = House.shelfSlots(s).filterNotNull().toSet()
        check(ov == COLLECTIBLES.drop(House.SHELF_SLOTS) &&
            ov.none { it.icon in shelfIds } &&
            ov.size == COLLECTIBLES.size - House.SHELF_SLOTS,
            "attic: a full collection overflows exactly the " +
                "registry tail — no piece is in two places")
        // feat cups ride the same shelf, by House's own count
        check(Attic.overflowCups(s) == 0,
            "attic: no feat overflow before the cups fill")
        repeat(House.MAX_CUPS + 3) { s.photoFeats.add("pf$it") }
        check(Attic.overflowCups(s) == 3 &&
            Attic.overflowCups(s) == House.featOverflow(s) &&
            Attic.overflowLines(s).any { "+3 feat" in it },
            "attic: cups past MAX_CUPS are counted by House's " +
                "own overflow and named on the shelf")
    }

    // ---------- the family frame's outtakes ----------
    run {
        val s = atticState(940_003)
        val p1 = famPhoto("p1", "1/1", YOUR_HOUSE, "Mom")
        val p2 = famPhoto("p2", "1/2", YOUR_HOUSE, "Dad")
        val p3 = famPhoto("p3", "1/3", YOUR_HOUSE, "Mom", "Dad")
        // not outtakes: a home photo with no parent, and a
        // photo with a parent taken anywhere else
        val pHome = famPhoto("p4", "1/4", YOUR_HOUSE, "Stan")
        val pPark = famPhoto("p5", "1/5", "KidsPark", "Mom")
        s.photos.addAll(listOf(p1, p2, p3, pHome, pPark))
        check(Family.latestFamilyPhoto(s)?.id == "p3",
            "attic: the frame holds the newest home family photo")
        val outs = Attic.outtakes(s)
        check(outs.map { it.record.id } == listOf("p1", "p2") &&
            outs.all { !it.fromPrint },
            "attic: the outtakes are the OTHER home family " +
                "photos — the framed one, the parentless one " +
                "and the elsewhere one are all excluded")
        val lines = Attic.outtakeLines(s)
        check(lines.any { "In the frame downstairs" in it } &&
            lines.any { "1/1" in it } && lines.any { "1/2" in it } &&
            lines.none { "1/4" in it || "1/5" in it },
            "attic: the outtake lines carry the framed photo " +
                "and the outtakes' own public facts only")
        // one family photo only: the frame holds it, no outtakes
        val s1 = atticState(940_004)
        s1.photos.add(famPhoto("q1", "2/1", YOUR_HOUSE, "Mom"))
        check(Attic.outtakes(s1).isEmpty() &&
            Attic.outtakeLines(s1).any { "Just the one" in it },
            "attic: a single family photo leaves the outtake " +
                "shelf honestly empty")
        // a print-held family photo whose album copy faded:
        // the print is the record, and it joins the outtakes
        val gone = famPhoto("pGone", "1/6", YOUR_HOUSE, "Dad")
        s.prints.add(DarkroomPrint("pr1", "pGone", gone,
            Darkroom.SIZE_PRINT, madeAbsDay = 5, madeKey = "20260106"))
        // a print of a photo the album still holds: no double
        s.prints.add(DarkroomPrint("pr2", "p1", p1,
            Darkroom.SIZE_PRINT, madeAbsDay = 6, madeKey = "20260107"))
        val outs2 = Attic.outtakes(s)
        check(outs2.map { it.record.id } ==
            listOf("p1", "p2", "pGone") &&
            outs2.last().fromPrint &&
            Attic.outtakeLines(s).any {
                "the darkroom print still holds" in it },
            "attic: a faded family photo survives as a " +
                "print-held outtake — and an album-held print " +
                "is never listed twice")
    }

    // ---------- the stored case boxes ----------
    run {
        val s = atticState(940_005)
        check(Attic.caseBoxes(s).isEmpty() &&
            Attic.boxLines(s).any { "No boxes yet" in it },
            "attic: no finished case, no boxes")
        // an OPEN case produces NO box — the wall of the rule
        s.arc2Started = true
        check(Attic.caseBoxes(s).isEmpty(),
            "attic: an unretired case produces NO box, however " +
                "far along it stands")
        s.arcRetired = true
        val b1 = Attic.caseBoxes(s)
        check(b1.size == 1 && b1[0].number == 1 &&
            b1[0].title == Mystery.ARC_TITLE &&
            b1[0].closedDay == -1 &&
            b1[0].piecesHeld == Mystery.clueCount(s) &&
            b1[0].piecesTotal == Mystery.CLUES.size,
            "attic: case 1 boxes on its retired flag alone — " +
                "title, counts, and NO closing day invented " +
                "(its record keeps none)")
        s.arc3Retired = true; s.arc3RetiredDay = 40
        val boxes = Attic.caseBoxes(s)
        check(boxes.map { it.number } == listOf(1, 3) &&
            boxes[1].closedDay == 40 &&
            Attic.boxLines(s).any { "day 41" in it },
            "attic: case 3's box carries its real closing day; " +
                "the still-open case 2 leaves its gap honestly")
        // the full lifetime: ten retired cases, ten boxes
        val s9 = atticState(940_006)
        s9.arcRetired = true; s9.arc2Retired = true
        s9.arc3Retired = true; s9.arc4Retired = true
        s9.arc5Retired = true; s9.arc6Retired = true
        s9.arc7Retired = true; s9.arc8Retired = true
        s9.arc9Retired = true; s9.arc10Retired = true
        val all = Attic.caseBoxes(s9)
        check(all.size == 10 && Attic.CASE_TOTAL == 13 &&
            all.map { it.number } == (1..10).toList() &&
            all.map { it.title } == listOf(
                Mystery.ARC_TITLE, Mystery2.CASE_TITLE,
                Mystery3.CASE_TITLE, Mystery4.CASE_TITLE,
                Mystery5.CASE_TITLE, Mystery6.CASE_TITLE,
                Mystery7.CASE_TITLE, Mystery8.CASE_TITLE,
                Mystery9.CASE_TITLE, Mystery10.CASE_TITLE),
            "attic: ten finished cases, ten boxes, in order, " +
                "under the titles the Journal already publishes " +
                "— and an eleventh seat waits for the voice case")
    }

    // ---------- THE SPOILER WALL ----------
    run {
        // a save with every case retired on a DIFFERENT
        // landing each: the attic must print none of it
        val s = atticState(940_007)
        s.arcRetired = true; s.arcBranch = "truth"
        s.arc2Retired = true; s.arc2Branch = "solved"
        s.arc3Retired = true; s.arc3Branch = "bury"
        s.arc4Retired = true; s.arc4Branch = "name"
        s.arc5Retired = true; s.arc5Branch = "believe"
        s.arc6Retired = true; s.arc6Branch = "convicted"
        s.arc7Retired = true; s.arc7Branch = "mended"
        s.arc8Retired = true; s.arc9Retired = true
        s.arc10Retired = true; s.arc10Branch = "hung"
        s.photos.add(famPhoto("z1", "3/1", YOUR_HOUSE, "Mom"))
        s.photos.add(famPhoto("z2", "3/2", YOUR_HOUSE, "Dad"))
        for (c in COLLECTIBLES) s.collected.add(c.id)
        val titles = listOf(Mystery.ARC_TITLE, Mystery2.CASE_TITLE,
            Mystery3.CASE_TITLE, Mystery4.CASE_TITLE,
            Mystery5.CASE_TITLE, Mystery6.CASE_TITLE,
            Mystery7.CASE_TITLE, Mystery8.CASE_TITLE,
            Mystery9.CASE_TITLE, Mystery10.CASE_TITLE)
        // the public titles ride the boxes by design; the
        // wall is over everything ELSE the attic says
        val surfaces = Attic.pageLines(s).map { line ->
            titles.fold(line) { acc, t -> acc.replace(t, "") }
        }
        val deny = listOf("sleepwalk", "professor chaos",
            "cameo", "strongbox", "commune", "the deed",
            "golden lure", "whittled", "night gardener",
            "confession", "culprit")
        check(deny.none { d ->
            surfaces.any { d in it.lowercase() } },
            "attic: no page line breathes a word of any " +
                "case's answer (the shared denylist, titles " +
                "stripped — the titles are the public shape)")
        val branches = listOf("truth", "solved", "bury",
            "believe", "convicted", "mended")
        check(branches.none { b ->
            surfaces.any { b in it.lowercase() } },
            "attic: no branch word survives onto a box — " +
                "six landings set in the save, none printed")
        val src = File(root,
            "src/com/hunt3r/southparktown/Attic.kt").readText()
        check(deny.none { d -> d in src.lowercase() },
            "attic: the module's own text keeps the same wall")
        check(Attic.boxLines(s).none { "SOLVED" in it } &&
            Attic.boxLines(s).count { "closed" in it.lowercase() } >= 9,
            "attic: every box wears the one public stamp — " +
                "closed — and no other")
    }

    // ---------- purity, no economy, no new save shape ----------
    run {
        val s = atticState(940_008)
        s.arcRetired = true
        s.photos.add(famPhoto("w1", "4/1", YOUR_HOUSE, "Mom"))
        s.photos.add(famPhoto("w2", "4/2", YOUR_HOUSE, "Mom"))
        val lifeBefore = HashMap(s.life)
        val textBefore = HashMap(s.lifeText)
        val coinsBefore = Minigames.capsuleCoins(s)
        val invBefore = HashMap(s.inventory)
        val page1 = Attic.pageLines(s)
        val page2 = Attic.pageLines(s)
        check(page1 == page2,
            "attic: the page is a pure derivation — the same " +
                "save reads the same attic forever")
        check(s.life == lifeBefore && s.lifeText == textBefore &&
            Minigames.capsuleCoins(s) == coinsBefore &&
            s.inventory == invBefore,
            "attic: reading the attic writes NOTHING — no " +
                "save key, no coin, no item moves (zero new " +
                "save shape, no economy, by construction)")
        check(s.life.keys.none { "attic" in it.lowercase() } &&
            s.lifeText.keys.none { "attic" in it.lowercase() },
            "attic: no attic key exists in either save map — " +
                "an old save loads into a full attic unchanged")
        val src = File(root,
            "src/com/hunt3r/southparktown/Attic.kt").readText()
        check(!src.contains("awardCoins") &&
            !src.contains("capsuleCoins") &&
            !src.contains("Minigames"),
            "attic: the module holds no coin path at all")
    }

    // ---------- dials unmoved, fixture wired ----------
    run {
        check(House.DECOR.size == 17,
            "attic: the decor table stands at 17 — the attic " +
                "adds no piece, it shelves the overflow")
        check(Phone.MAX_TEXTS == 220,
            "attic: MAX_TEXTS stands at 220 — no dial moved")
        val gv = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        val ga = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        check(gv.contains("Hit(\"fixture\", \"attic\"") &&
            ga.contains("\"attic\" -> atticDialog()") &&
            ga.contains("Attic.pageLines"),
            "attic: the fixture is drawn at Your House and " +
                "its tap opens the derived page — the garden/" +
                "paper pattern, upstairs")
    }
}
}

private fun sectionV0120f(root: String) {
    println("== v0.12.0f: mystery #10 — the photograph nobody took ==")
    val eng10 = Engine(1155)

    // ---------- the chapter defs ----------
