    val finDef10 = Mystery10.CHAPTER10_BY_ID[Mystery10.FINALE10_ID]!!
    check(finDef10.causers.containsAll(listOf("Victoria", "Jimmy")),
        "photo: the rehanging is played by the portrait's keeper and the archive's editor")

    // ---------- the frames (the board's rows) ----------
    val frames10 = Mystery10.FRAMES10
    check(frames10.size == 4 && Mystery10.FRAME10_BY_ID.size == 4 &&
        frames10.map { it.index } == listOf(0, 1, 2, 3),
