    val sLook = eng10.newState()
    sLook.arc10Chapter = 1
    check(Mystery10.lookClueText10(sLook, "Elementary") == null,
        "photo: the hall gives nothing to a look in the hanging week — the frames' backs wait for the examination")
    sLook.arc10Chapter = 2
    val lookCard = Mystery10.lookClueText10(sLook, "Elementary")
    check(lookCard != null && "gift_card" in sLook.mystery10Clues &&
        !Mystery10.clueLive10(sLook,
            Mystery10.CLUE10_BY_ID["gift_card"]!!),
        "photo: the card is found in the frames week — in hand, honestly inert, settling nothing")
    check(Mystery10.lookClueText10(sLook, "Elementary") != null &&
        "scratch_marks" in sLook.mystery10Clues &&
        Mystery10.lookClueText10(sLook, "Elementary") == null &&
