    check(Mystery10.chooseCall10(sPlay, "frame_album", "misfiled") &&
        Mystery10.frameVerdict10(sPlay, frames10[3]) == "REFUTED",
        "photo: read against the live settling piece and the reading is refuted on arrival")
    check(Mystery10.pendingFrame10(sPlay)?.id == "frame_loaned" &&
        Mystery10.chooseCall10(sPlay, "frame_loaned", "composite") &&
        Mystery10.frameVerdict10(sPlay, frames10[0]) == "PROVEN",
        "photo: a refuted frame is offered again — in board order, the portrait first — and, read as the card settles it, stands proven")
    check(Mystery10.pendingFrame10(sPlay)?.id == "frame_album" &&
        Mystery10.chooseCall10(sPlay, "frame_album", "genuine") &&
        Mystery10.frameVerdict10(sPlay, frames10[3]) == "PROVEN",
