    Mystery10.noteChapterStarted10(sQ10, ch10[0])
    check(sQ10.arc10Started && sQ10.arc10Chapter == 1 && sQ10.arc10DueAbsDay == 236,
        "photo: chapter 2 is booked exactly a week out")
    sQ10.absDay = 235
    check(Mystery10.dueChapter10(sQ10) == null,
        "photo: ...and waits the full week, however eager the hanging")
    sQ10.absDay = 236
    check(Mystery10.dueChapter10(sQ10)?.id == ch10[1].id,
        "photo: the lobby and the lamp, in person, on day seven")
    Mystery10.noteChapterStarted10(sQ10, ch10[1])
    check(sQ10.arc10DueAbsDay == 243, "photo: the drawer opens a week past the frames")
    sQ10.absDay = 243
    Mystery10.noteChapterStarted10(sQ10, ch10[2])
    sQ10.absDay = 250
    check(Mystery10.dueChapter10(sQ10)?.id == ch10[3].id,
