    Mystery10.noteChapterStarted10(sQ10, ch10[3])
    check(sQ10.arc10DueAbsDay == -1 && Mystery10.dueChapter10(sQ10) == null,
        "photo: with the finale on, there is no fifth chapter to schedule")

    // ---------- the finale: the rehanging ----------
    fun hangingState10(): GameState {
        val st = eng10.newState()
        for (c in clues10) st.mystery10Clues.add(c.id)
        st.arc10Started = true
        st.arc10Chapter = 4
        st.shenaniganId = Mystery10.FINALE10_ID
        st.shenaniganDay = st.todayKey
        st.timeMin = 13 * 60
        return st
    }
    fun settleBoard10(st: GameState) {
        st.arc10Calls["frame_loaned"] = "composite"
        st.arc10Calls["frame_archive"] = "genuine"
        st.arc10Calls["frame_enlargement"] = "misfiled"
        st.arc10Calls["frame_album"] = "genuine"
    }
    val sDue10 = hangingState10()
    check(!Mystery10.hangingDue(sDue10),
        "photo: the rehanging will not open on an unsettled board — the room wants every frame read")
    settleBoard10(sDue10)
    check(Mystery10.hangingDue(sDue10) &&
        Finales.climaxPending(sDue10) && School.anyClimaxDueToday(sDue10) &&
