    sDue10.timeMin = 10 * 60
    check(!Mystery10.hangingDue(sDue10),
        "photo: ...but not before the opening's closing stages — the labeled space in the program is at the end")
    sDue10.timeMin = 13 * 60
    check(!Mystery10.chooseFinale10(sDue10, "maybe"),
