    sDue10.absDay += 1
    val tail10 = Mystery10.noteLabelReprinted(sDue10)
    check(tail10 && sDue10.arc10LabelDone && !sDue10.arc10LabelPending &&
        sDue10.absDay == labelDay10 &&
        !Mystery10.noteLabelReprinted(sDue10),
        "photo: on the seventh day the pair hangs together — six faces, one portrait, two frames — exactly once")
    check(Mystery10.aftermathLine10(sDue10, "Victoria") != null &&
        Mystery10.aftermathLine10(sDue10, "Stuart") == null &&
        Mystery10.aftermathLine10(sDue10, "Jimmy") == null &&
        Mystery10.aftermathLine10(sDue10, "Kenny") == null,
        "photo: the standing voice of the completed ending is the portrait's keeper herself — the woman who finished it")
    val sFrame = hangingState10()
    sFrame.arc10Calls["frame_loaned"] = "composite"
    sFrame.arc10Calls["frame_archive"] = "composite"
    sFrame.arc10Calls["frame_enlargement"] = "genuine"
    sFrame.arc10Calls["frame_album"] = "misfiled"
    check(Mystery10.hangingDue(sFrame) && !Mystery10.readEligible10(sFrame) &&
