    Mystery10.applyHangingEffects(sHang, "hung")
    check(Mystery10.aftermathLine10(sHang, "Jimmy") != null &&
        Mystery10.aftermathLine10(sHang, "Victoria") == null &&
        sHang.lifeText["mark:Elementary"]!!.contains("AS LOANED"),
        "photo: the standing voice of the hung ending is the editor whose captions stood — a hanging list that says 'see the board' to nobody")
    val sDegrade10 = hangingState10()
    settleBoard10(sDegrade10)
    sDegrade10.arc10Calls["frame_album"] = "composite"
    sDegrade10.arc10Choice = "read"
    check(Mystery10.resolveHanging(sDegrade10).branch == "unexposed",
        "photo: a read-aloud locked on a board that turns out struck lands unexposed — the rehanging reads the board, not the lock, at wrap time")
    val sWalk10 = hangingState10()
    settleBoard10(sWalk10)
    check(Mystery10.chooseFinale10(sWalk10, "walk") &&
        Mystery10.resolveHanging(sWalk10).branch == "unexposed",
        "photo: walking away from a wall you could have read aloud still lands unexposed — the room opened it without the board's voice")
    check(Mystery10.aftermathLine10(sWalk10, "Kenny") != null &&
        Mystery10.aftermathLine10(sWalk10, "Victoria") == null,
