    vet.life["gchat:crewWit"] = 36
    vet.life["gchat:famBorn"] = 3
    vet.lifeText["gchat:crewSnap"] = "Stan,Kyle,Wendy,Craig"
    vet.lifeText["gchat:crewPhoto"] = "vetxg0"
    // the counters, shopped at for real: packets into
    // the pack, staples into the pantry, both books
    // written by the tills themselves
    val seedBookBefore = vet.life["gardenSeedSpent"] ?: 0
    repeat(3) { Shop.buySeed(vet, "pumpkin", Shop.LOC) }
    repeat(2) { Shop.buySeed(vet, "corn", Shop.LOC) }
    repeat(2) { Shop.buyStaple(vet, "snack_cake", Shop.LOC) }
    Shop.buyStaple(vet, "lemonade", Shop.LOC)
    check((vet.life["gardenSeedSpent"] ?: 0) -
        seedBookBefore == 13,
        "veteran XI: (staging) the rack's buys booked " +
            "13 🪙 into the garden's one seed book — " +
            "three pumpkin packets at 3, two corn at 2")
    check(Shop.goodsSpent(vet) == 5 &&
        Garden.packetsHeld(vet, "pumpkin") == 3 &&
        Garden.packetsHeld(vet, "corn") == 2,
        "veteran XI: (staging) the till's book stands " +
            "at 5 🪙 and the pack holds the packets")
    // the collectibles, complete — the shelf downstairs
    // fills and the rest belongs to the attic
    vet.collected.addAll(COLLECTIBLES.map { it.id })
    // the paper's archive, at its caps — the latest
    // edition composed from this very state
    vet.lifeText["paperSkyLog"] =
        (0 until Newspaper.SKY_LOG_CAP).joinToString(";") { i ->
            "${686 + i}:sunny:${SkyState.NONE}" }
    vet.lifeText["paperHeadlines"] =
        (0 until Newspaper.HEADLINE_CAP).joinToString(";") { i ->
            "${50 + i}|Archived headline number $i from the " +
                "veteran's long subscription" }
    val edV = Newspaper.composeEdition(vet,
        Jobs.weekIndex(vet.arc10RetiredDay))
    vet.lifeText["paperLatest"] = edV.lines.joinToString("\n")
    vet.life["paperWeek"] = edV.week
    vet.life["paperLastWeek"] = edV.week
    check(edV.headline == "THE CASE CLOSES",
        "veteran XI: (staging) the veteran's latest " +
            "edition headlines a case closing — the tenth " +
            "case's stamp drives the ladder's top tier " +
            "like any case's")
    // the attic at this high-water, read before the
    // measure so the audit states it on the record
    check(!Attic.overflowEmpty(vet) &&
        Attic.overflowCollectibles(vet).isNotEmpty() &&
        Attic.overflowCups(vet) > 0,
        "veteran XI: (staging) the attic's overflow " +
            "shelf is loaded — collectibles past the " +
            "shelf's twelve slots and feat cups past " +
            "its six, read off the house's own counts")
    check(Attic.caseBoxes(vet).size == Attic.CASE_TOTAL,
        "veteran XI: (staging) twelve case boxes stand in " +
            "the attic — one per closed case, public " +
            "shape only")
    val vetOuttakes = Attic.outtakes(vet)
    check(vetOuttakes.any { !it.fromPrint &&
        it.record.id == "vetxfam" } &&
        vetOuttakes.any { it.fromPrint &&
            it.record.id == "vetxgonefam" },
        "veteran XI: (staging) the outtakes hold the " +
            "framed photo's elder sibling from the album " +
            "and one family photo only a darkroom print " +
            "still holds")
    val lifeSizeV = vet.life.size
    val lifeTextSizeV = vet.lifeText.size

    // ---- measure, pin, round-trip ----
    val vetJson = Json.stringify(encodeGameState(vet))
    println("veteran XI game_state: ${vetJson.length} chars serialized")
    check(vetJson.length < 640 * 1024,
        "veteran XI: the saturated save (Queue #12 " +
            "included) stays under the 640K ceiling " +
            "(got ${vetJson.length})")
    check(vetJson.length > 569_660,
        "veteran XI: today's full state outgrows " +
            "veteran X's 569,660 — the growth is Queue " +
            "#12's own records, each one capped (got " +
            "${vetJson.length})")
    @Suppress("UNCHECKED_CAST")
    val vetBack = decodeGameState(
        Json.parse(vetJson) as Map<String, Any?>)
    check(vetBack.errands.size == Errands.STATE_CAP &&
        vetBack.photos.size == 63 && StoryArcs.allDone(vetBack) &&
        vetBack.busPass && vetBack.walkTrips == 900 &&
        vetBack.arcRetired && vetBack.arc2Retired &&
        vetBack.arc3Retired && vetBack.arc4Retired &&
        vetBack.arc5Retired && vetBack.arc6Retired &&
        vetBack.arc7Retired && vetBack.arc8Retired,
        "veteran XI: the veteran body round-trips " +
            "whole — eight cases closed beneath the " +
            "ninth and tenth")
    check(vetBack.arc9Retired &&
        vetBack.arc9Branch == "reconciled" &&
        vetBack.mystery9Clues.size == Mystery9.CLUES9.size &&
        vetBack.arc9Calls.size == Mystery9.SITES9.size &&
        vetBack.arc9ListRestored,
        "veteran XI: the ninth case round-trips closed " +
            "— full file, every site called, the roll restored")
    check(vetBack.arc10Retired &&
        vetBack.arc10Branch == "complete" &&
        vetBack.mystery10Clues.size ==
            Mystery10.CLUES10.size &&
        vetBack.arc10Calls.size ==
            Mystery10.FRAMES10.size &&
        vetBack.arc10LabelDone,
        "veteran XI: the tenth case round-trips closed " +
            "— full evidence file, every frame read, " +
            "the true card printed")
    check(Crew.members(vetBack) ==
        listOf("Stan", "Kyle", "Wendy", "Craig") &&
        Crew.outings(vetBack, "Stan") == 25 &&
        Sleepovers.nights(vetBack).size ==
            Sleepovers.HISTORY_CAP &&
        Newspaper.headlineHistory(vetBack).size ==
            Newspaper.HEADLINE_CAP &&
        Newspaper.skyLog(vetBack).size ==
            Newspaper.SKY_LOG_CAP,
        "veteran XI: the capped records round-trip at " +
            "their caps — eight sleepovers, eight " +
            "archived headlines, a full sky log, the " +
            "crew whole")
    check(Carnival.recordFor(vetBack, 2027)?.wrapped == true &&
        (vetBack.life["gardenHarvest:potato"] ?: 0) > 0 &&
        Garden.fairSpecimen(vetBack, 2028) != null &&
        Stand.books(vetBack).totalGrown == 2 &&
        Fair.recordFor(vetBack, 2027)?.playerProduce == 1 &&
        vetBack.phoneTexts.size == 196,
        "veteran XI: the carnival, the garden's " +
            "tallies, the stand's grown column, the " +
            "fair's produce place and the 196-text inbox " +
            "all survive the round-trip")
    check(vetBack.life.size == lifeSizeV &&
        vetBack.lifeText.size == lifeTextSizeV &&
        (vetBack.life["shopGoodsSpent"] ?: 0) == 5 &&
        (vetBack.inventory[Garden.packetId("pumpkin")]
            ?: 0) == 3 &&
        (vetBack.inventory[Garden.packetId("corn")]
            ?: 0) == 2,
        "veteran XI: the life and lifeText maps come " +
            "through at exactly their staged sizes — " +
            "the counters' books and the seed packets " +
            "among them, nothing shed, nothing invented")
    val slpBack = vetBack.photos
        .firstOrNull { it.id == "vetxslp" }
    check(slpBack != null &&
        slpBack.figures[0].sleep ==
            Sleepwear.playerCode(DEFAULT_APPEARANCE) &&
        slpBack.figures[1].hero == heroStanV &&
        slpBack.figures[1].sleep == sleepStanV &&
        slpBack.figures[2].sleep ==
            Sleepwear.codeFor("Kyle"),
        "veteran XI: the sleepover frame round-trips " +
            "with its pajamas frozen — and Stan's hero " +
            "code still standing in its own lane on " +
            "the same figure")
    check(Attic.caseBoxes(vetBack).size ==
        Attic.CASE_TOTAL &&
        !Attic.overflowEmpty(vetBack) &&
        Attic.outtakes(vetBack).size ==
            vetOuttakes.size &&
        Attic.pageLines(vetBack) ==
            Attic.pageLines(vet),
        "veteran XI: the attic reads the round-tripped " +
            "save whole — eleven boxes, a loaded overflow " +
            "shelf, the outtakes intact, the page " +
            "byte-identical, because it stores nothing")
}
}

private fun sectionV0130a(root: String) {
    println("== v0.13.0a: the family page + home barks ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.13.0a"),
        "v0.13.0a: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 95 / 0.13.0a")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.13.0a: no new module — the page and the barks live " +
            "in Family.kt/Barks.kt; the tree stands at 103 " +
            "Kotlin files (counted $ktCount)")

    fun famState(seed: Long): GameState {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return s
    }
    fun arrivedState(seed: Long, stance: String = "warm"): GameState {
        val s = famState(seed)
        s.absDay = Family.ARRIVAL_ABS_DAY
        Family.chooseStance(s, stance)
        // a lived save's arrival day is stamped by its first
        // rollover consult; stamp it the same way here
        Family.arrivalDay(s)
        return s
    }
    fun famPhoto(id: String, label: String, vararg names: String): PhotoRecord =
        PhotoRecord(
            id = id, dayKey = "20260101", dateLabel = label,
            timeMin = 600, locId = YOUR_HOUSE, inside = true,
            weatherId = "clear", appearance = DEFAULT_APPEARANCE,
            figures = listOf(PhotoFigure("New Kid", "player", "happy",
                reaction = "player")) + names.map {
                PhotoFigure(it, "resident", "happy", reaction = "happy") })

    // ---------- the page before the arrival: honest not-yet ----------
    run {
        val s = famState(950_001)
        val before = encodeGameState(s)
        val page = Family.pageLines(s)
        check(page.first() == "👨‍👩‍👧 YOUR FAMILY" &&
            page.any { "don't live here yet" in it } &&
            page.any { "Day ${Family.ARRIVAL_ABS_DAY + 1}" in it },
            "family page: before the move, the page says so — " +
                "they're coming, on the day the arrival math " +
                "already promises, and nothing more")
        check(Family.pageLines(s) == page &&
            encodeGameState(s) == before &&
            s.life["famArrivalDay"] == null,
            "family page: rendering is pure — twice the same " +
                "lines, and the save is byte-identical after; " +
                "the page does not even stamp the arrival day")
        check(Family.barkDecide(s, true, Family.PARENTS, true,
                emptySet(), emptyMap(), 600, 0.0, 0.0, 0.0, 0) == null,
            "home barks: nobody barks in a house nobody lives " +
                "in yet — the arrival gates the voice too")
    }

    // ---------- the mid-life page: every record in its place ----------
    run {
        val s = arrivedState(950_002)
        s.absDay = 40
        s.timeMin = 10 * 60
        s.life["famPts:Mom"] = 57
        s.life["famPts:Dad"] = 23
        s.life["famDinCount"] = 5
        s.life["famDinLast"] = 38
        s.life["famDinFullDay"] = 38
        s.life["famAllowanceTotal"] = 9
        s.life["famAllowanceDay"] = 35
        s.life["famChoreDone"] = 6
        s.life["famChoreDoneBy:Mom"] = 4
        s.life["famChoreDoneBy:Dad"] = 2
        s.life["famChoreLastDone"] = 39
        val p1 = famPhoto("fp1", "1/1", Family.MOM)
        val p2 = famPhoto("fp2", "1/2", Family.DAD)
        s.photos.addAll(listOf(p1, p2))
        val before = encodeGameState(s)
        val page = Family.pageLines(s)
        check(Family.pageLines(s) == page &&
            encodeGameState(s) == before,
            "family page: a lived save renders twice, identical, " +
                "and the save is byte-identical between renders — " +
                "the page derives, it never keeps")
        check(page.any { "since Day ${Family.ARRIVAL_ABS_DAY + 1}" in it } &&
            page.any { "How the move landed — warm" in it } &&
            page.any { "took this move like a champ" in it },
            "family page: the arrival day is remembered and the " +
                "stance is stated in the family's own words")
        check(page.any { it.startsWith("Mom — ") &&
                it.endsWith(Family.whereNow(s, Family.MOM)?.second ?: "§") } &&
            page.any { "warmth 57" in it } &&
            page.any { "warmth 23" in it } &&
            page.any { "new-accounts desk at the Bank" in it } &&
            page.any { "counter at the Post Office" in it },
            "family page: who's home (the pure whereNow read, " +
                "verbatim), each parent's warmth in their own " +
                "lane, and a job line apiece")
        check(page.any { "Family dinners: 5 sat at your table" in it } &&
            page.any { "Day 39" in it && "full table" in it },
            "family page: the dinner count and the most recent " +
                "night — a full table, honestly labeled")
        check(page.any { "Allowance: 9 🪙 earned all told" in it } &&
            page.any { "Day 36" in it } &&
            page.any { "Mom's rule" in it },
            "family page: the allowance book — the lifetime " +
                "total, the last earned morning, the rule as " +
                "Mom states it")
        check(page.any { "Chores pitched in: 6" in it } &&
            page.any { "Asked by Mom: 4 · asked by Dad: 2" in it } &&
            page.none { "before this page kept" in it },
            "family page: the chore tally names its askers when " +
                "the counters cover the whole count")
        // the frame agrees with the attic, on the same save
        val framedLine = page.first { it.startsWith("🖼 The family frame:") }
        val atticFramed = Attic.outtakeLines(s)
            .first { "In the frame downstairs" in it }
        check(framedLine.contains(Photos.captionFor(p2)) &&
            framedLine.contains("(1/2)") &&
            atticFramed.contains(Photos.captionFor(p2)) &&
            atticFramed.contains("(1/2)") &&
            page.any { "other 1 hangs in the attic" in it },
            "family page: the frame's state is the attic's " +
                "frame state — same photo, same caption, same " +
                "date, read through the same functions")
        // the warmth lane is a wall: the friendship table is
        // never the page's source, even when poisoned
        val poisoned = famState(950_003)
        poisoned.absDay = s.absDay
        poisoned.timeMin = s.timeMin
        poisoned.life.putAll(s.life)
        poisoned.lifeText.putAll(s.lifeText)
        poisoned.photos.addAll(s.photos)
        poisoned.friendship[Family.MOM] = 99
        poisoned.friendship[Family.DAD] = -50
        check(Family.pageLines(poisoned) == page,
            "family page: a hostile friendship table changes " +
                "nothing the page prints — parents are read from " +
                "famPts, never from the cast's lane")
    }

    // ---------- honest edges: missed tables, empty books ----------
    run {
        val s = arrivedState(950_004)
        s.life["famDinCount"] = 2
        s.life["famDinLast"] = 20
        s.life["famDinMissed"] = 27
        val page = Family.pageLines(s)
        check(page.any { "went unsat" in it && "Day 28" in it } &&
            page.none { "Most recent:" in it },
            "family page: when the latest table night went " +
                "unsat, the page says that instead — the honest " +
                "line wins over the proud one")
        val s2 = arrivedState(950_005)
        val page2 = Family.pageLines(s2)
        check(page2.any { "Family dinners: 0 sat" in it } &&
            page2.any { "None yet" in it } &&
            page2.any { "Allowance: 0 🪙 earned" in it } &&
            page2.any { "family frame: still empty" in it },
            "family page: a family that just arrived shows " +
                "honest zeros — no dinners, no allowance, an " +
                "empty frame, nothing backfilled")
    }

    // ---------- legacy chores: the names the page can't know ----------
    run {
        val s = arrivedState(950_006)
        s.life["famChoreDone"] = 3
        val page = Family.pageLines(s)
        check(page.any { "Chores pitched in: 3" in it } &&
            page.any { "before this page kept the askers' names" in it } &&
            page.none { "Asked by Mom" in it },
            "family page: a pre-0.13.0a chore total renders " +
                "whole, with the gap stated — the page never " +
                "invents which parent asked")
        s.life["famChoreDone"] = 5
        s.life["famChoreDoneBy:Mom"] = 1
        s.life["famChoreDoneBy:Dad"] = 1
        val page2 = Family.pageLines(s)
        check(page2.any { "Asked by Mom: 1 · asked by Dad: 1" in it } &&
            page2.any { "3 more from before this page kept" in it },
            "family page: a part-legacy tally splits what the " +
                "counters know and counts the rest out loud")
        // and the live path feeds the counters from here on
        val s3 = arrivedState(950_007)
        s3.absDay = 10
        s3.lifeText["famChore"] = "table"
        s3.lifeText["famChoreBy"] = Family.DAD
        s3.life["famChoreDay"] = 10
        check(Family.noteFixture(s3, "table") != null &&
            (s3.life["famChoreDone"] ?: 0) == 1 &&
            (s3.life["famChoreDoneBy:Dad"] ?: 0) == 1 &&
            s3.life["famChoreDoneBy:Mom"] == null,
            "family page: completing a chore keeps its asker " +
                "per parent — the one new stored fact of this " +
                "build, earned because the record exists " +
                "nowhere else")
    }

    // ---------- whereNow is blockAt's honest twin ----------
    run {
        var mismatches = 0
        var probes = 0
        for (d in 0..27) {
            for (hol in listOf<String?>(null, HOLIDAYS.first().id)) {
                val s = arrivedState(950_100L + d)
                s.absDay = d
                s.life["famDinDay"] = d
                s.holidayId = hol
                for (t in listOf(5 * 60, 7 * 60, 8 * 60, 10 * 60,
                        12 * 60, 15 * 60, 17 * 60, 19 * 60,
                        21 * 60, 23 * 60)) {
                    for (p in Family.PARENTS) {
                        probes++
                        if (Family.blockAt(s, p, t) !=
                            Family.whereNow(s, p, t)) mismatches++
                    }
                }
            }
        }
        check(mismatches == 0,
            "family page: whereNow agrees with blockAt on all " +
                "$probes (day, hour, holiday) probes — the pure " +
                "mirror the page reads is the live block's twin")
        // and the page's tonight line tracks the LIVE verdict
        var tonightSeen = 0
        var tonightAgree = true
        for (d in 30..150) {
            val s = arrivedState(950_200L + d)
            s.absDay = d
            val paged = Family.pageLines(s)
                .any { "family-dinner night" in it }
            val live = Family.dinnerTonight(s)
            if (paged != live) tonightAgree = false
            if (live) tonightSeen++
        }
        check(tonightAgree && tonightSeen >= 10,
            "family page: the tonight line appears exactly on " +
                "the evenings the live dinnerTonight stands " +
                "($tonightSeen such evenings in the sweep)")
    }

    // ---------- the household bark table: walled, distinct ----------
    run {
        check(Barks.PATTERNS.size == 98 &&
            Barks.PATTERNS.keys == CharacterSystem.CAST.keys &&
            Family.MOM !in Barks.PATTERNS &&
            Family.DAD !in Barks.PATTERNS,
            "home barks: the cast table stands untouched — 98 " +
                "patterns keyed to the cast, no parent in it")
        check(Barks.HOUSEHOLD_PATTERNS.keys ==
            setOf(Family.MOM, Family.DAD) &&
            Barks.HOUSEHOLD_PATTERNS.keys.none {
                it in CharacterSystem.CAST },
            "home barks: the household table holds exactly " +
                "Mom and Dad, and nobody cast")
        val allSigs = (Barks.PATTERNS.values +
            Barks.HOUSEHOLD_PATTERNS.values)
            .map { Barks.signature(it) }
        val allHellos = (Barks.PATTERNS.values +
            Barks.HOUSEHOLD_PATTERNS.values).map { it.hello }
        check(allSigs.toSet().size == 100 &&
            allHellos.toSet().size == 100 &&
            Barks.HOUSEHOLD_PATTERNS.values.none { it.electronic },
            "home barks: all 100 rhythm signatures (and " +
                "hellos) are distinct — the parents sound like " +
                "themselves, and neither is a voice box")
        check(Barks.patternFor(Family.MOM) == null &&
            Barks.patternForAny(Family.MOM) ==
                Barks.HOUSEHOLD_PATTERNS[Family.MOM] &&
            Barks.patternForAny("Stan") == Barks.patternFor("Stan") &&
            Barks.patternForAny("Some Generated Person") == null,
            "home barks: patternFor keeps its cast-only " +
                "meaning; patternForAny resolves the household " +
                "behind it and still finds nobody else")
        check(SoundGen.renderBark(Family.MOM).isNotEmpty() &&
            SoundGen.renderBark(Family.DAD).isNotEmpty() &&
            SoundGen.renderBark(Family.MOM)
                .contentEquals(SoundGen.renderBark(Family.MOM)) &&
            SoundGen.renderBark("Some Generated Person").isEmpty(),
            "home barks: both parents' patterns render (and " +
                "render deterministically) through the same " +
                "SoundGen path the cast uses; strangers still " +
                "render silence")
    }

    // ---------- barkDecide: the barks discipline, at home ----------
    run {
        val s = arrivedState(950_300)
        s.absDay = 20
        s.timeMin = 10 * 60
        val now = s.absDay * 1440 + s.timeMin
        val both = Family.PARENTS
        val enteredMom = Family.barkDecide(s, true, both, true,
            emptySet(), emptyMap(), now, 0.0, 0.0, 0.0, 7)
        check(enteredMom != null && enteredMom.first == Family.MOM &&
            enteredMom.second in
                (Family.HOME_GREETINGS[Family.MOM] ?: emptyList()),
            "home barks: walking in, Mom hails you with a " +
                "greeting-bank line when the pick roll lands on her")
        val enteredDad = Family.barkDecide(s, true, both, true,
            emptySet(), emptyMap(), now, 0.0, 0.0, 0.99, 7)
        check(enteredDad != null && enteredDad.first == Family.DAD &&
            enteredDad.second in
                (Family.HOME_GREETINGS[Family.DAD] ?: emptyList()),
            "home barks: the pick roll walks the parents in " +
                "order — the far roll lands on Dad")
        check(Family.barkDecide(s, true, both, true, emptySet(),
                emptyMap(), now, 0.0, 0.0, 0.0, 7) == enteredMom,
            "home barks: the decision is deterministic — same " +
                "moment, same rolls, same hello")
        val lines = (0..9).mapNotNull { seed ->
            Family.barkDecide(s, true, listOf(Family.MOM), true,
                emptySet(), emptyMap(), now, 0.0, 0.0, 0.0, seed)?.second
        }
        check(lines.toSet().size >= 3,
            "home barks: the seed walks the greeting bank — " +
                "Mom has more than one way to say you're home")
        val idle = Family.barkDecide(s, true, both, false,
            emptySet(), emptyMap(), now, 0.0, 0.0, 0.0, 3)
        check(idle != null &&
            idle.second in (Family.HOME_IDLE[idle.first] ?: emptyList()),
            "home barks: lingering at home can draw an idle " +
                "line, from the idle bank")
        check(Family.barkDecide(s, true, both, false, emptySet(),
                emptyMap(), now, 0.0, 0.5, 0.0, 3) == null &&
            Family.barkDecide(s, true, both, false,
                setOf(Family.DAD), emptyMap(), now, 0.99, 0.0, 0.0, 3)
                == null,
            "home barks: a lingering moment that fails the " +
                "idle roll — or a newcomer roll that fails the " +
                "arrival chance — stays quiet")
        val newDad = Family.barkDecide(s, true, both, false,
            setOf(Family.DAD), emptyMap(), now, 0.0, 0.0, 0.0, 3)
        check(newDad != null && newDad.first == Family.DAD &&
            newDad.second in
                (Family.HOME_GREETINGS[Family.DAD] ?: emptyList()),
            "home barks: a parent who comes home while you " +
                "linger greets you — a newcomer, on the " +
                "arrival chance, with a greeting line")
        check(Family.barkDecide(s, false, both, true, emptySet(),
                emptyMap(), now, 0.0, 0.0, 0.0, 0) == null,
            "home barks: the Settings toggle silences the " +
                "house like it silences the town")
        s.timeMin = 23 * 60
        check(Family.barkDecide(s, true, both, true, emptySet(),
                emptyMap(), s.absDay * 1440 + s.timeMin,
                0.0, 0.0, 0.0, 0) == null,
            "home barks: quiet hours are quiet at home too")
        s.timeMin = 10 * 60
        check(Family.barkDecide(s, true, listOf(Family.MOM), true,
                emptySet(), mapOf(Family.MOM to now), now,
                0.0, 0.0, 0.0, 0) == null &&
            Family.barkDecide(s, true, both, true, emptySet(),
                mapOf(Family.MOM to now), now, 0.0, 0.0, 0.0, 0)
                == null,
            "home barks: the shared cooldown vetoes the pick — " +
                "and, as in town, the veto does not re-roll to " +
                "the other parent")
        // flavor only: a crowd of decisions moves nothing
        val before = encodeGameState(s)
        val momPts = Family.points(s, Family.MOM)
        var landed = 0
        for (i in 0 until 200) {
            val r = Family.barkDecide(s, true, both, i % 3 == 0,
                if (i % 5 == 0) setOf(Family.DAD) else emptySet(),
                emptyMap(), now + i, (i % 7) / 7.0, (i % 11) / 11.0,
                (i % 13) / 13.0, i)
            if (r != null) landed++
        }
        check(landed > 0 && encodeGameState(s) == before &&
            Family.points(s, Family.MOM) == momPts,
            "home barks: 200 decisions ($landed landed) move " +
                "no warmth, no coins, no state — the save is " +
                "byte-identical, because a hello is not a lever")
        check(Family.bankSizes(Family.MOM)["homeGreetings"] == 5 &&
            Family.bankSizes(Family.MOM)["homeIdle"] == 5 &&
            Family.HOME_GREETINGS[Family.MOM]?.first() ==
                Barks.HOUSEHOLD_PATTERNS[Family.MOM]?.hello &&
            Family.HOME_GREETINGS[Family.DAD]?.first() ==
                Barks.HOUSEHOLD_PATTERNS[Family.DAD]?.hello,
            "home barks: five greetings and five idle lines a " +
                "parent, and each bank opens with its pattern " +
                "hello — the bubble and the bank can't drift")
    }

    // ---------- spoiler scan, extended over the new surfaces ----------
    run {
        val sealed = listOf("sleepwalk", "cameo",
            "communal paperwork", "the culprit is",
            "strongbox contains")
        val surfaces = mutableListOf<String>()
        surfaces += Family.HOME_GREETINGS.values.flatten()
        surfaces += Family.HOME_IDLE.values.flatten()
        surfaces += Barks.HOUSEHOLD_PATTERNS.values.map { it.hello }
        val s = arrivedState(950_400)
        surfaces += Family.pageLines(s)
        val fresh = famState(950_401)
        surfaces += Family.pageLines(fresh)
        check(sealed.none { term ->
                surfaces.any { it.lowercase().contains(term) } },
            "home barks + family page: every new player-facing " +
                "line stays clear of the sealed terms — the " +
                "family spoiler scan extends over the page and " +
                "the bark banks")
        val famSrc = File(root,
            "src/com/hunt3r/southparktown/Family.kt").readText()
        check(sealed.none { famSrc.lowercase().contains(it) },
            "home barks: the Family.kt source scan still " +
                "passes with the page and the banks inside it")
    }

    // ---------- the walls stand: wiring, rails, census ----------
    run {
        check(TalkGate.Rail.values().size == 11,
            "family page: the TalkGate ladder still stands at " +
                "eleven rails — family conversation is its own " +
                "sheet, and neither the page nor the barks add one")
        val gaSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        val jaSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        check(gaSrc.contains("Family.barkDecide") &&
            jaSrc.contains("Family.pageLines"),
            "family page: the wiring is real — GameActivity " +
                "consults barkDecide at home, JournalActivity " +
                "renders the page")
        check(AGENT_PROFILES.size == 98 &&
            Family.MOM !in AGENT_PROFILES &&
            Family.DAD !in AGENT_PROFILES &&
            Family.PARENTS.none { it in CharacterSystem.CAST },
            "family page: the census stands from both sides — " +
                "a Journal page and a bark apiece did not make " +
                "anyone cast")
    }
}

// ============================================================
// v0.13.0b — THE SCHOOL DANCE: the anchor proven disjoint
// on lived dates, the ask's whole matrix (tiers, authored
// answers, finality, the stood-up switch and its memory),
// the evening's claim seating and yield set, the beats'
// exact consumption, the one photograph, the page/paper/
// phone derivations, and stag completeness — every beat
// reachable with nobody asked at all.
// ============================================================
private fun sectionV0130b(root: String) {
    println("== v0.13.0b: the school dance ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val engineSrc = File(srcDir, "Engine.kt").readText()
    val danceSrc = File(srcDir, "Dance.kt").readText()
    val gameSrc = File(srcDir, "GameActivity.kt").readText()
    val journalSrc = File(srcDir, "JournalActivity.kt").readText()
    val phoneSrc = File(srcDir, "Phone.kt").readText()
    val paperSrc = File(srcDir, "Newspaper.kt").readText()
    val viewsSrc = File(srcDir, "MinigameViews.kt").readText()
    val sleepSrc = File(srcDir, "Sleepovers.kt").readText()
    val talkSrc = File(srcDir, "TalkGate.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "v0.13.0b: the manifest carries this build (96 / 0.13.0b)")
    check(readme.contains("### v0.13.0b"),
        "v0.13.0b: the README carries this build's changelog entry")
    check(readme.contains("## Status — v0.13.0b"),
        "v0.13.0b: the README carries this build's status section")
    val ktCount = srcDir.listFiles { f -> f.extension == "kt" }
        ?.size ?: 0
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.13.0b: one new module (Dance.kt) — the tree stands " +
            "at 105 Kotlin files (found $ktCount)")

    fun danceState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    fun setDayD(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    /** Put the player in the gym on dance night. */
    fun inGym(s: GameState, year: Int) {
        setDayD(s, DanceCalendar.danceDay(year))
        s.timeMin = 18 * 60 + 30
        val me = s.agents.values.first { it.isPlayer }
        me.location = "Elementary"
        s.playerInside = true
    }
    fun seatAtGym(s: GameState, name: String) {
        s.agents[name]?.let { it.location = "Elementary" }
    }

    // ---------- the anchor: shape ----------
    run {
        var allShape = true
        var yieldYears = 0
        for (y in 2026..2100) {
            val d = DanceCalendar.danceDay(y)
            val ord = FairCalendar.ordinalOfAbsDay(d)
            val key = keyFromOrdinal(ord)
            if (key.substring(4, 6) != "02") allShape = false
            val dom = key.substring(6, 8).toInt()
            if (dom !in 8..14) allShape = false
            if (FairCalendar.dowOfOrdinal(ord) != 5)
                allShape = false   // a Friday, always
            if (!Dance.dateLabel(d).startsWith("Fri"))
                allShape = false
            if (DanceCalendar.announceDay(y) != d - 7)
                allShape = false
            if (Dance.posterYield(y)) yieldYears++
        }
        check(allShape,
            "dance calendar: the second Friday of February, " +
                "always Feb 8–14, announced exactly a week " +
                "ahead (2026–2100)")
        check(yieldYears >= 1,
            "dance calendar: the Valentine coincidence is " +
                "real in the sweep — $yieldYears year(s) in " +
                "2026–2100 have Feb 14 as the second Friday")
    }

    // ---------- the anchor: disjointness, ONE time space ----------
    run {
        var collisions = 0
        var detail = ""
        for (y in 2026..2100) {
            val d = DanceCalendar.danceDay(y)
            val dOrd = FairCalendar.ordinalOfAbsDay(d)
            // the play: the openings of the productions
            // whose falls bracket this February
            for (sy in y..(y + 1)) {
                val o = PlayCalendar.scheduleFor(sy).openingDay
                if (d in (o - 14)..(o + 14)) {
                    collisions++; detail = "play $sy" }
            }
            // the fair's week, from its own Saturday anchor
            val fOrd = FairCalendar.thirdSaturdayOrdinal(y)
            if (dOrd in fOrd..(fOrd + 6)) {
                collisions++; detail = "fair $y" }
            // the carnival's week, same construction
            val cOrd = CarnivalCalendar.thirdSaturdayOrdinal(y)
            if (dOrd in cOrd..(cOrd + 6)) {
                collisions++; detail = "carnival $y" }
            // every finale window: the last 7 days of each
            // season, derived from Finales' own anchors
            for (season in Season.values()) {
                val (em, ed) = Finales.seasonEndMonthDay(season, y)
                val endOrd = ordinalOfKey(
                    "%04d%02d%02d".format(y, em, ed))
                if (dOrd in (endOrd - 6)..endOrd) {
                    collisions++; detail = "finale $season $y" }
            }
            // the holidays: GameData's own table, as lived
            // month-days — Valentine's single day is the
            // one allowed touch, and only as the yield
            val md = (keyFromOrdinal(dOrd).substring(4, 8)).toInt()
            for (h in HOLIDAYS) {
                val from = h.startMd.toInt()
                val to = h.endMd.toInt()
                val inSpan = if (from <= to) md in from..to
                    else md >= from || md <= to
                if (inSpan && h.id != "valentine") {
                    collisions++; detail = "holiday ${h.id} $y" }
                if (inSpan && h.id == "valentine" &&
                    !Dance.posterYield(y)) {
                    collisions++; detail = "valentine-not-yield $y" }
            }
        }
        check(collisions == 0,
            "dance calendar: 2026–2100, the dance day never " +
                "lands in a play opening window, the fair " +
                "week, the carnival week, a finale window or " +
                "a holiday window — the one Valentine touch " +
                "is always the yield year ($detail)")
    }

    // ---------- the authored census + the tone wall ----------
    run {
        check(Dance.DISPOSITION.keys ==
            CharacterSystem.CAST_KIDS.toSet(),
            "dance ask: every one of the 42 kids has exactly " +
                "one authored disposition")
        check(Dance.YES_LINES.keys ==
            Dance.DISPOSITION.filterValues {
                it != Dance.NO }.keys,
            "dance ask: every glad and shy kid has an authored YES")
        check(Dance.NO_LINES.keys ==
            Dance.DISPOSITION.filterValues {
                it == Dance.NO }.keys,
            "dance ask: every NO kid has an authored kind no")
        check(Dance.YES_LINES.values.toSet().size ==
            Dance.YES_LINES.size &&
            Dance.NO_LINES.values.toSet().size ==
            Dance.NO_LINES.size,
            "dance ask: no two kids share a yes or a no — " +
                "every answer is that kid's own")
        // 🔴 the tone wall, scanned over every authored
        // line the ask can speak: courage-and-friendship
        // framing only, no romance vocabulary at all
        val spoken = Dance.YES_LINES.values +
            Dance.NO_LINES.values + Dance.SOFT_LINES +
            Dance.STOOD_LINES + Dance.AGAIN_LINES +
            listOf(Dance.adultLine("Randy"))
        val banned = listOf("kiss", "romance", "boyfriend",
            "girlfriend", "couple", "crush", "marry",
            "love you", "make out")
        check(spoken.none { line ->
            banned.any { line.lowercase().contains(it) } },
            "dance ask: the tone wall holds — no romance " +
                "vocabulary in any authored ask line")
        check(Dance.ASK_MIN_POINTS == 30 &&
            Dance.ASK_MIN_POINTS == Crew.INVITE_MIN_POINTS &&
            Dance.SHY_MIN_POINTS == 55 &&
            Dance.STOOD_UP_COST == 3 &&
            Dance.ATTEND_PCT == 65,
            "dance dials: Friend-tier ask (30, the crew " +
                "ask's floor), shy at Close (55), the " +
                "stood-up cost 3, the room seeded at 65%")
    }

    // ---------- the ask matrix ----------
    run {
        val (_, s) = danceState(13021)
        val y = 2027
        setDayD(s, DanceCalendar.announceDay(y))
        s.timeMin = 10 * 60
        // below tier: the menu says not-yet, no ask is spent
        s.friendship["Stan"] = 29
        check(Dance.menuOption(s, "Stan")?.contains(
            "not close yet") == true,
            "dance ask: below the Friend tier the menu itself " +
                "says not-yet")
        check(Dance.ask(s, "Stan").kind == "tier" &&
            Dance.record(s, y) == null,
            "dance ask: a below-tier ask spends nothing — no " +
                "record is even opened")
        // glad yes at exactly the tier
        s.friendship["Stan"] = 30
        check(Dance.menuOption(s, "Stan") ==
            "💃 Ask Stan to the dance",
            "dance ask: at the Friend tier the plain ask is offered")
        val yes1 = Dance.ask(s, "Stan")
        check(yes1.kind == "yes" &&
            Dance.record(s, y)?.date == "Stan",
            "dance ask: a glad kid says yes at 30 and the date is set")
        check(Dance.ask(s, "Stan").kind == "date" &&
            Dance.record(s, y)?.date == "Stan",
            "dance ask: asking your own date again changes nothing")
        // the switch: a second yes stands the first up
        s.friendship["Kyle"] = 40
        val yes2 = Dance.ask(s, "Kyle")
        val rec2 = Dance.record(s, y)!!
        check(yes2.kind == "yes" && rec2.date == "Kyle" &&
            rec2.stood == listOf("Stan") &&
            (s.friendship["Stan"] ?: 0) == 27,
            "dance ask: a second yes stands the first kid up — " +
                "the switch costs exactly 3 friendship, paid at " +
                "the switch, and the stood list keeps the fact")
        check(Dance.ask(s, "Stan").kind == "stood" &&
            Dance.record(s, y)?.date == "Kyle",
            "dance ask: a stood-up kid's answer to a re-ask is final")
        // shy: soft no below Close, spends nothing
        s.friendship["Butters"] = 40
        val soft = Dance.ask(s, "Butters")
        val rec3 = Dance.record(s, y)!!
        check(soft.kind == "soft" && rec3.date == "Kyle" &&
            rec3.softList == listOf("Butters") &&
            (s.friendship["Butters"] ?: 0) == 40,
            "dance ask: a shy kid below Close gives the soft " +
                "no — remembered kindly, costing nothing, " +
                "finalizing nothing")
        s.friendship["Butters"] = 55
        check(Dance.ask(s, "Butters").kind == "yes" &&
            Dance.record(s, y)?.date == "Butters" &&
            Dance.record(s, y)?.stood ==
                listOf("Stan", "Kyle") &&
            Dance.record(s, y)?.softList?.isEmpty() == true &&
            (s.friendship["Kyle"] ?: 0) == 37,
            "dance ask: at Close the shy kid says yes (and " +
                "the switch stands Kyle up in his turn)")
        // the kind final no, at any friendship
        s.friendship["Craig"] = 90
        check(Dance.ask(s, "Craig").kind == "no" &&
            Dance.record(s, y)?.noList == listOf("Craig") &&
            Dance.menuOption(s, "Craig") == null &&
            Dance.ask(s, "Craig").kind == "no" &&
            Dance.record(s, y)?.date == "Butters",
            "dance ask: the NO is kind, in-voice and final — " +
                "no menu option, no re-ask grind, even at 90")
        // adults: labeled on the menu, answered off the record
        s.friendship["Randy"] = 90
        check(Dance.menuOption(s, "Randy")?.contains(
            "grown-up") == true &&
            Dance.ask(s, "Randy").kind == "adult" &&
            Dance.record(s, y)?.date == "Butters" &&
            "Randy" !in (Dance.record(s, y)?.noList
                ?: emptyList()),
            "dance ask: a grown-up is flattered, final, and " +
                "touches no record")
        // the window: shut before the poster and at the doors
        val (_, s2) = danceState(13022)
        setDayD(s2, DanceCalendar.announceDay(y) - 1)
        s2.timeMin = 10 * 60
        s2.friendship["Stan"] = 50
        check(Dance.menuOption(s2, "Stan") == null &&
            Dance.ask(s2, "Stan").kind == "window",
            "dance ask: before the poster there is no ask")
        setDayD(s2, DanceCalendar.danceDay(y))
        s2.timeMin = 18 * 60
        check(!Dance.askWindowOpen(s2) &&
            Dance.ask(s2, "Stan").kind == "window",
            "dance ask: at the doors (18:00) the asking is over")
    }

    // ---------- the Valentine year: yielded whole ----------
    run {
        val y = (2026..2100).first { Dance.posterYield(it) }
        val (_, s) = danceState(13023)
        setDayD(s, DanceCalendar.announceDay(y))
        s.timeMin = 10 * 60
        s.friendship["Stan"] = 60
        check(!Dance.askWindowOpen(s) &&
            Dance.menuOption(s, "Stan") == null,
            "dance yield: in a Valentine year the asking " +
                "never opens (year $y)")
        check(Dance.lookText(s, "Elementary")?.contains(
            "apology") == true,
            "dance yield: the poster carries the apology " +
                "and the reason")
        inGym(s, y)
        check(!Dance.eveningLive(s) &&
            Dance.gatheringBlock(s, "Stan", 19 * 60) == null &&
            Dance.beatLabels(s).isEmpty(),
            "dance yield: the gym stands no claim and offers " +
                "no beats in a yielded year")
        setDayD(s, DanceCalendar.danceDay(y) + 1)
        Dance.dailyRollover(s)
        val rec = Dance.record(s, y)!!
        check(rec.night == "yielded" &&
            rec.yieldWhy == "valentine",
            "dance yield: the wrap records the skipped year " +
                "with its reason")
        check(Dance.phoneBeat(s) == null,
            "dance yield: a yielded year texts nobody — " +
                "nothing happened")
        check(Dance.pageLines(s).any {
            it.contains("NO DANCE THIS YEAR") },
            "dance yield: the Journal page says the year " +
                "was skipped, and why")
    }

    // ---------- the claim: seating + behavior ----------
    run {
        val order = listOf("Dinners", "Birthdays", "Family",
            "Jobs", "MovieNights", "Capstones", "Finales",
            "Fair", "Carnival", "RivalCrew", "Heroes", "Play",
            "Dance", "Talent", "Parade", "Sleepovers", "Stand", "Crew")
        val idx = order.map { nm ->
            Regex("(?<![A-Za-z])$nm\\.gatheringBlock")
                .find(engineSrc)?.range?.first ?: -1 }
        check(idx.all { it >= 0 } && idx == idx.sorted() &&
            idx.distinct().size == idx.size,
            "dance claim: the agenda stack is eighteen " +
                "seats and the dance sits after the play, " +
                "before the talent show (v0.13.0c extended " +
                "the pin, and v0.13.0d again for the " +
                "parade — pinned from Engine's own source)")
        val (_, s) = danceState(13024)
        val y = 2027
        setDayD(s, DanceCalendar.announceDay(y))
        s.timeMin = 10 * 60
        s.friendship["Kyle"] = 40
        Dance.ask(s, "Kyle")
        setDayD(s, DanceCalendar.danceDay(y))
        val date = Dance.gatheringBlock(s, "Kyle", 19 * 60)
        val room = Dance.attendees(y)
        val guest = room.first { it != "Kyle" }
        val absent = CharacterSystem.CAST_KIDS.first {
            it !in room && it != "Kyle" }
        check(date?.location == "Elementary" &&
            Dance.gatheringBlock(s, guest, 19 * 60) != null &&
            Dance.gatheringBlock(s, "Victoria", 19 * 60)
                ?.activity?.contains("Chaperoning") == true &&
            Dance.gatheringBlock(s, absent, 19 * 60) == null,
            "dance claim: on the night it seats your date, " +
                "the seeded room and the chaperone — and " +
                "nobody the seed left home")
        check(Dance.gatheringBlock(s, "Kyle", 17 * 60) == null &&
            Dance.gatheringBlock(s, "Kyle", 22 * 60) == null,
            "dance claim: the claim lives only inside " +
                "18:00–21:30")
    }

    // ---------- the evening, with a date ----------
    run {
        val (_, s) = danceState(13025)
        val y = 2027
        setDayD(s, DanceCalendar.announceDay(y))
        s.timeMin = 10 * 60
        s.friendship["Stan"] = 30
        s.friendship["Kyle"] = 40
        Dance.ask(s, "Stan")
        Dance.ask(s, "Kyle")   // Stan stood up
        inGym(s, y)
        seatAtGym(s, "Kyle"); seatAtGym(s, "Stan")
        check(Dance.beatsHere(s) &&
            Dance.beatLabels(s).first() ==
                "💃 Step into the dance",
            "dance evening: in the gym on the night, the " +
                "board offers arrival first")
        val arrival = Dance.playArrival(s)!!
        check(arrival.contains("toast that isn't one") &&
            arrival.contains("Kyle") &&
            Dance.record(s, y)!!.beatDone(Dance.BEAT_ARRIVAL) &&
            Dance.playArrival(s) == null,
            "dance evening: arrival lands its beat once — " +
                "and the stood-up kid's toast is in it, " +
                "because Stan is in the room")
        // the played slow dance
        val sess = Dance.DanceSession(42L, "Kyle")
        repeat(4) { sess.step(0.5) }
        check(sess.over && sess.held >= 3,
            "dance evening: dead-center releases hold the " +
                "song (held ${sess.held} of 4)")
        val kyleBefore = s.friendship["Kyle"] ?: 0
        val verdict = Dance.judgeSlowDance(s, sess)!!
        val pay = if (sess.result == "glorious")
            Dance.DANCE_PAY_SIDEWAYS else Dance.DANCE_PAY_GOOD
        check((s.friendship["Kyle"] ?: 0) == kyleBefore + pay &&
            Dance.record(s, y)!!.danceResult == sess.result &&
            Dance.judgeSlowDance(s,
                Dance.DanceSession(43L, "Kyle")) == null,
            "dance evening: the slow dance pays your date " +
                "in friendship (+$pay for '${sess.result}') " +
                "and lands once")
        // refreshments: exact consumption
        s.inventory["lemonade"] = 2
        s.inventory["snack_cake"] = 1
        check(Dance.servePunch(s, "lemonade") != null &&
            (s.inventory["lemonade"] ?: 0) == 1 &&
            Dance.record(s, y)!!.punchLem == 1 &&
            Dance.record(s, y)!!.beatDone(Dance.BEAT_PUNCH),
            "dance evening: a lemonade pours as punch — " +
                "exactly one consumed, the beat landed")
        check(Dance.servePunch(s, "snack_cake") != null &&
            !s.inventory.containsKey("snack_cake") &&
            Dance.record(s, y)!!.punchCake == 1,
            "dance evening: the snack cake is consumed " +
                "exactly — the last one leaves the bag")
        check(Dance.servePunch(s, "water") != null &&
            (s.inventory["lemonade"] ?: 0) == 1 &&
            Dance.servePunch(s, "cookies") == null &&
            Dance.servePunch(s, "snack_cake") == null,
            "dance evening: the cooler is free and endless; " +
                "what isn't punch-table stock isn't served, " +
                "and an empty stock serves nothing")
        // the last song: one photo, the night read back
        val photosBefore = s.photos.size
        val last = Dance.playLastSong(s)!!
        val rec = Dance.record(s, y)!!
        check(rec.night == "played" && rec.photoId.isNotEmpty() &&
            s.photos.size == photosBefore + 1 &&
            s.photos.any { it.id == rec.photoId &&
                it.caption.contains("Kyle") &&
                it.caption.contains("Sweetheart Dance") } &&
            last.contains("Kyle") &&
            Dance.playLastSong(s) == null &&
            Dance.gatheringBlock(s, "Kyle", 19 * 60) == null,
            "dance evening: the last song mints exactly ONE " +
                "photograph, captioned with the night and " +
                "your date, wraps the night as played and " +
                "releases the claim")
        // the morning after: the date texts, fact-only
        setDayD(s, DanceCalendar.danceDay(y) + 1)
        val beat = Dance.phoneBeat(s)
        check(beat != null && beat.first == "Kyle" &&
            beat.third.contains("dance"),
            "dance phone: the morning after, your date " +
                "texts — from the record, moving nothing")
        // the paper: one line, in the dance's week only
        val week = Jobs.weekIndex(rec.nightDay)
        val line = Dance.paperLine(s, week)
        check(line != null && line.contains("Kyle") &&
            line.contains("photograph") &&
            Dance.paperLine(s, week + 1) == null,
            "dance paper: one TOWN NEWS line in the dance " +
                "week — names and the photograph's " +
                "existence — and none in any other week")
    }

    // ---------- session math: nerve is the margin ----------
    run {
        val steadyKid = Play.STAGE_NERVE.entries
            .first { it.value == 9 }.key
        val shakyKid = Play.STAGE_NERVE.entries
            .first { it.value == 3 }.key
        // releases parked in the GOOD zone: power 0.78 —
        // a nerve-9 partner's multiplier (1.17) carries
        // every phrase past the good threshold; a nerve-3
        // partner's (0.87) never does. Deterministic by
        // construction, jitter ±0.03 included.
        val strong = Dance.DanceSession(7L, steadyKid)
        val shaky = Dance.DanceSession(7L, shakyKid)
        repeat(4) { strong.step(0.35); shaky.step(0.35) }
        check(strong.held == 4 && shaky.held == 0 &&
            strong.result == "steady" &&
            shaky.result == "glorious",
            "dance session: your partner's nerve is " +
                "literally your margin — the same releases " +
                "hold clean with a steady partner and go " +
                "gloriously sideways with a shaky one")
        check(Dance.DanceSession(7L, "").nerve == 5,
            "dance session: stag, the spotlight dances at " +
                "the new kid's honest nerve of 5")
    }

    // ---------- stag completeness ----------
    run {
        val (_, s) = danceState(13026)
        val y = 2027
        val friend = Dance.attendees(y).first()
        s.friendship[friend] = 50
        inGym(s, y)
        seatAtGym(s, friend)
        val arrival = Dance.playArrival(s)!!
        check(arrival.contains("stag") &&
            Dance.currentRecord(s)?.date?.isEmpty() == true,
            "dance stag: arrival reads the stag plan as the " +
                "whole plan it is")
        val sess = Dance.DanceSession(9L, "")
        repeat(4) { sess.step(0.5) }
        val friendsBefore = HashMap(s.friendship)
        check(Dance.judgeSlowDance(s, sess) != null &&
            s.friendship == friendsBefore,
            "dance stag: the spotlight slow dance plays " +
                "whole and pays nobody — there is nobody to pay")
        val photosBefore = s.photos.size
        val last = Dance.playLastSong(s)!!
        val rec = Dance.record(s, y)!!
        check(rec.night == "played" &&
            s.photos.size == photosBefore + 1 &&
            s.photos.any { it.id == rec.photoId &&
                it.caption.contains("stag") } &&
            last.contains("stag"),
            "dance stag: the last song mints the photograph " +
                "and reads the night back as stag")
        setDayD(s, DanceCalendar.danceDay(y) + 1)
        val beat = Dance.phoneBeat(s)
        check(beat != null && beat.first == friend,
            "dance stag: the morning text comes from the " +
                "closest friend who was in the room")
        check(Dance.pageLines(s).any {
            it.contains("you came stag") },
            "dance stag: the Journal page keeps the night " +
                "as a stag night, in words")
    }

    // ---------- wraps: partial, missed, yielded-by-owners ----------
    run {
        // partial: arrival only, then the morning wraps it played
        val (_, s) = danceState(13027)
        val y = 2027
        inGym(s, y)
        Dance.playArrival(s)
        setDayD(s, DanceCalendar.danceDay(y) + 1)
        Dance.dailyRollover(s)
        check(Dance.record(s, y)?.night == "played" &&
            Dance.record(s, y)?.photoId?.isEmpty() == true,
            "dance wraps: a partial night wraps as the " +
                "night it was — played, no photograph")
        // missed: the gym went on without you
        val (_, s2) = danceState(13028)
        setDayD(s2, DanceCalendar.announceDay(y))
        s2.timeMin = 10 * 60
        s2.friendship["Kyle"] = 40
        Dance.ask(s2, "Kyle")
        setDayD(s2, DanceCalendar.danceDay(y) + 1)
        Dance.dailyRollover(s2)
        val rec2 = Dance.record(s2, y)!!
        check(rec2.night == "missed" && rec2.date == "Kyle",
            "dance wraps: an untouched night wraps missed — " +
                "and the record keeps that you'd had a date")
        val mb = Dance.phoneBeat(s2)
        check(mb != null && mb.first == "Kyle" &&
            mb.second == "stood-date",
            "dance wraps: a date you didn't show for texts " +
                "the honest text")
        check(Dance.pageLines(s2).any {
            it.contains("You'd asked Kyle") },
            "dance wraps: the page keeps the missed date " +
                "gently, and in full")
        // yielded by a live owner: a holiday beat on the day
        val (_, s3) = danceState(13029)
        inGym(s3, y)
        s3.holidayId = "valentine"
        check(!Dance.eveningLive(s3) &&
            Dance.yieldReason(s3) == "holiday" &&
            s3.lifeText["danceYield:$y"] == "holiday",
            "dance yield: a holiday beat owning the Friday " +
                "yields the evening, and the reason is " +
                "stamped where it's learned")
        setDayD(s3, DanceCalendar.danceDay(y) + 1)
        Dance.dailyRollover(s3)
        check(Dance.record(s3, y)?.night == "yielded" &&
            Dance.record(s3, y)?.yieldWhy == "holiday",
            "dance yield: the wrap carries the owner's " +
                "reason into the record")
        check(danceSrc.contains("QUIET_CASE") &&
            danceSrc.contains("QUIET_FINALE") &&
            danceSrc.contains("Play.nightCanHappen"),
            "dance yield: the deference set is the town's " +
                "own — case climax, finale window and " +
                "holiday via School's quiet day, plus the " +
                "play's live night")
    }

    // ---------- page, look, integrations ----------
    run {
        val (_, s) = danceState(13030)
        val y = 2027
        setDayD(s, DanceCalendar.announceDay(y) - 3)
        s.timeMin = 10 * 60
        check(Dance.pageLines(s).any {
            it.contains("poster goes up") } &&
            Dance.lookText(s, "Elementary")?.contains(
                "DANCE — WALL") == true,
            "dance page: before the poster, the page counts " +
                "down and the gym wall is already measured")
        setDayD(s, DanceCalendar.announceDay(y))
        s.friendship["Stan"] = 30
        s.friendship["Kyle"] = 40
        Dance.ask(s, "Stan"); Dance.ask(s, "Kyle")
        val page = Dance.pageLines(s)
        check(page.any { it.contains("going with Kyle") } &&
            page.any { it.contains("Stood up along the " +
                "way: Stan") },
            "dance page: the live page states your plan and " +
                "keeps the stood-up fact in the open")
        check(Dance.lookText(s, "Elementary")?.contains(
            "POSTER") == true,
            "dance look: the poster is on the gym wall all " +
                "asking week")
        // history: next year's page remembers this one
        inGym(s, y); seatAtGym(s, "Kyle")
        Dance.playArrival(s)
        val sess = Dance.DanceSession(11L, "Kyle")
        repeat(4) { sess.step(0.5) }
        Dance.judgeSlowDance(s, sess)
        Dance.playLastSong(s)
        setDayD(s, DanceCalendar.announceDay(2028))
        s.timeMin = 10 * 60
        check(Dance.pageLines(s).any {
            it.startsWith("📜 2027:") &&
                it.contains("Kyle") },
            "dance page: past years reduce to one history " +
                "line each")
        check(journalSrc.contains("💃 THE DANCE") &&
            journalSrc.contains("Dance.pageLines(state)"),
            "dance page: the Journal renders 💃 THE DANCE " +
                "from the module's own derivation")
        check(gameSrc.contains("Dance.menuOption(state, npcName)") &&
            gameSrc.contains("danceAsk(npcName)") &&
            gameSrc.contains("Dance.lookText(state, me.location)") &&
            gameSrc.contains("startSlowDance()") &&
            viewsSrc.contains("class SlowDanceView") &&
            viewsSrc.contains("Dance.DanceSession"),
            "dance wiring: the ask rides the tap-person " +
                "menu, the slow dance launches its played " +
                "view, and Look carries the gym's dance text")
        check(phoneSrc.contains("const val DANCE") &&
            phoneSrc.contains("Dance.phoneBeat(state)") &&
            paperSrc.contains("Dance.paperLine(state, week)") &&
            sleepSrc.contains("the school dance has them tonight") &&
            !talkSrc.contains("Dance"),
            "dance wiring: one phone trigger, one paper " +
                "hook, the sleepover planner's named refusal " +
                "— and no TalkGate rail: the ladder stands " +
                "at eleven")
    }

    // ---------- the paper's dance-only week ----------
    run {
        val (_, s) = danceState(13031)
        val y = 2027
        inGym(s, y)
        Dance.playArrival(s)
        val sess = Dance.DanceSession(13L, "")
        repeat(4) { sess.step(0.5) }
        Dance.judgeSlowDance(s, sess)
        Dance.playLastSong(s)
        val week = Jobs.weekIndex(DanceCalendar.danceDay(y))
        val ed = Newspaper.composeEdition(s, week)
        check(ed.lines.any { it.contains("💃") &&
            it.contains("Sweetheart Dance") },
            "dance paper: the edition of the dance's week " +
                "carries the line in TOWN NEWS")
        check(ed.headline == "A QUIET WEEK IN SOUTH PARK",
            "dance paper: a dance-only week still headlines " +
                "the quiet-week line — the dance is section " +
                "copy, never a headline tier")
    }

    // ---------- saves: round-trip + the old save joins ----------
    run {
        val (_, s) = danceState(13032)
        val y = 2027
        setDayD(s, DanceCalendar.announceDay(y))
        s.timeMin = 10 * 60
        s.friendship["Wendy"] = 45
        Dance.ask(s, "Wendy")
        inGym(s, y); seatAtGym(s, "Wendy")
        Dance.playArrival(s)
        val back = decodeGameState(encodeGameState(s))
        val rec = Dance.record(back, y)
        check(rec != null && rec.date == "Wendy" &&
            rec.beatDone(Dance.BEAT_ARRIVAL),
            "dance saves: the record round-trips the real " +
                "save path whole")
        // a pre-0.13.0b save has no dance keys at all —
        // it joins the next dance like anyone
        val (_, old) = danceState(13033)
        check(old.lifeText.keys.none {
            it.startsWith("dance") },
            "dance saves: a fresh (pre-dance) save carries " +
                "no dance state")
        setDayD(old, DanceCalendar.announceDay(2028))
        old.timeMin = 10 * 60
        old.friendship["Wendy"] = 45
        check(Dance.ask(old, "Wendy").kind == "yes" &&
            Dance.record(old, 2028)?.date == "Wendy",
            "dance saves: the old save joins the next " +
                "dance — additive-only, nothing to migrate")
    }
}

// ============================================================
// v0.13.0c — THE TALENT SHOW: one spring night at the Bijou
// where the town performs. The anchor proven disjoint in
// one lived time space (the dance, the play's openings,
// the fair, the carnival, every finale window, every
// holiday window, 2026–2100); the Bijou's own stand-down
// registered both directions; the field derived from the
// play's data and recomputed independently here; the acts
// authored and denylist-scanned; signup and the rehearsal
// honest to the minute; scores re-derived from raw inputs;
// the tie-break order proven level by level; the winner's
// photo, paper line, yearbook line and morning-after text
// derived off the wrapped record; the audience track
// walked start to finish without entering; the claim
// seated seventeenth; and the yield set forced live.
// ============================================================
private fun sectionV0130c(root: String) {
    println("== v0.13.0c: the talent show ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val engineSrc = File(srcDir, "Engine.kt").readText()
    val talentSrc = File(srcDir, "Talent.kt").readText()
    val gameSrc = File(srcDir, "GameActivity.kt").readText()
    val journalSrc = File(srcDir, "JournalActivity.kt").readText()
    val phoneSrc = File(srcDir, "Phone.kt").readText()
    val paperSrc = File(srcDir, "Newspaper.kt").readText()
    val viewsSrc = File(srcDir, "MinigameViews.kt").readText()
    val movieSrc = File(srcDir, "MovieNights.kt").readText()
    val talkSrc = File(srcDir, "TalkGate.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "v0.13.0c: the manifest carries this build (97 / 0.13.0c)")
    check(readme.contains("### v0.13.0c"),
        "v0.13.0c: the README carries this build's changelog entry")
    check(readme.contains("## Status — v0.13.0c"),
        "v0.13.0c: the README carries this build's status section")
    val ktCount = srcDir.listFiles { f -> f.extension == "kt" }
        ?.size ?: 0
    check(ktCount == 137 && readme.contains("105 Kotlin files"),
        "v0.13.0c: one new module (Talent.kt) — the tree " +
            "stands at 105 Kotlin files (found $ktCount)")

    fun talentState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    fun setDayT(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    /** Put the player inside the Bijou. */
    fun atBijou(s: GameState, year: Int, timeMin: Int) {
        setDayT(s, TalentCalendar.showDay(year))
        s.timeMin = timeMin
        val me = s.agents.values.first { it.isPlayer }
        me.location = "Bijou"
        s.playerInside = true
    }
    fun seatAtBijou(s: GameState, name: String) {
        s.agents[name]?.let { it.location = "Bijou" }
    }

    // ---------- the anchor: shape ----------
    run {
        var allShape = true
        for (y in 2026..2100) {
            val d = TalentCalendar.showDay(y)
            val ord = FairCalendar.ordinalOfAbsDay(d)
            val key = keyFromOrdinal(ord)
            if (key.substring(4, 6) != "04") allShape = false
            val dom = key.substring(6, 8).toInt()
            if (dom !in 8..14) allShape = false
            if (FairCalendar.dowOfOrdinal(ord) != 6) {
                allShape = false   // a Saturday, always
            }
            if (!Dance.dateLabel(d).startsWith("Sat")) {
                allShape = false
            }
            if (TalentCalendar.announceDay(y) != d - 7) {
                allShape = false
            }
            if (!MovieNights.isScreeningDay(d)) {
                allShape = false   // a screening Saturday:
            }                      // the stand-down is real
        }
        check(allShape,
            "talent calendar: the second Saturday of April, " +
                "always Apr 8–14, announced exactly a week " +
                "ahead (2026–2100) — and always a Saturday " +
                "the Bijou would otherwise screen on")
    }

    // ---------- the anchor: disjointness, ONE time space ----------
    run {
        var collisions = 0
        var detail = ""
        for (y in 2026..2100) {
            val d = TalentCalendar.showDay(y)
            val dOrd = FairCalendar.ordinalOfAbsDay(d)
            // the dance: February's night, never close
            val dd = DanceCalendar.danceDay(y)
            if (abs(d - dd) <= 21) {
                collisions++; detail = "dance $y" }
            // the play: the openings of the productions
            // whose school years bracket this April
            for (sy in (y - 1)..(y + 1)) {
                val o = PlayCalendar.scheduleFor(sy).openingDay
                if (d in (o - 21)..(o + 21)) {
                    collisions++; detail = "play $sy" }
            }
            // the fair's week, from its own window (with
            // its finale shift, as lived)
            val fw = FairCalendar.windowFor(y)
            if (dOrd in fw.startOrd..fw.endOrd) {
                collisions++; detail = "fair $y" }
            // the carnival's week, same construction
            val cw = CarnivalCalendar.windowFor(y)
            if (dOrd in cw.startOrd..cw.endOrd) {
                collisions++; detail = "carnival $y" }
            // every finale window: the last 7 days of each
            // season, derived from Finales' own anchors
            for (season in Season.values()) {
                val (em, ed) = Finales.seasonEndMonthDay(season, y)
                val endOrd = ordinalOfKey(
                    "%04d%02d%02d".format(y, em, ed))
                if (dOrd in (endOrd - 6)..endOrd) {
                    collisions++; detail = "finale $season $y" }
            }
            // the holidays: GameData's own table, as lived
            // month-days — NO exceptions this time: April's
            // pocket is clean whole
            val md = keyFromOrdinal(dOrd).substring(4, 8).toInt()
            for (h in HOLIDAYS) {
                val from = h.startMd.toInt()
                val to = h.endMd.toInt()
                val inSpan = if (from <= to) md in from..to
                    else md >= from || md <= to
                if (inSpan) {
                    collisions++; detail = "holiday ${h.id} $y" }
            }
        }
        check(collisions == 0,
            "talent calendar: 2026–2100, the show day never " +
                "lands within three weeks of the dance or a " +
                "play opening, never in the fair's week, the " +
                "carnival's week, a finale window or ANY " +
                "holiday window ($detail)")
    }

    // ---------- the authored census + the walls ----------
    run {
        check(Talent.ACTS.keys ==
            CharacterSystem.CAST_KIDS.toSet(),
            "talent acts: every one of the 42 kids has " +
                "exactly one authored act")
        check(Talent.ACTS.values.all {
            it.kind in Talent.KIND_BEAT },
            "talent acts: every act's kind has a beat the " +
                "room can judge it by")
        check(Talent.ACTS.values.map { it.kind }.toSet()
            .all { kind ->
                (Talent.VIGNETTES[kind]?.size ?: 0) == 3 },
            "talent acts: every kind carries three of the " +
                "room's reads")
        check(Talent.ACTS.values.map { it.line }.toSet()
            .size == Talent.ACTS.size,
            "talent acts: no two kids share an act line — " +
                "every act is that kid's own")
        check(Talent.PLAYER_ACTS.map { it.id } ==
            listOf("sing", "jokes", "magic", "dance") &&
            Talent.PLAYER_ACTS.map { it.phrases } ==
                listOf(4, 3, 5, 4) &&
            Talent.PLAYER_ACTS.map { it.sweepMs } ==
                listOf(1150L, 900L, 1300L, 1150L),
            "talent dials: your four acts, each with its " +
                "own played shape — phrases and sweeps differ")
        check(Talent.FIELD_SIZE == 10 &&
            Talent.ANN_BACK == 7 &&
            Talent.EVE_FROM == 18 * 60 + 30 &&
            Talent.EVE_TO == 21 * 60 + 30 &&
            Talent.WINNER_COINS == 15 &&
            Talent.REHEARSE_BONUS == 6 &&
            Talent.ENTER_PAY == 1 &&
            Talent.WINNER_PAY == 2 &&
            Talent.LEGENDARY_BONUS == 1 &&
            Talent.REACT_AFTER == listOf(2, 5, 8),
            "talent dials: a field of ten, the poster a " +
                "week out, doors 18:30–21:30, a 15-coin " +
                "envelope, the rehearsal worth +6, pays " +
                "1/2/+1, three room prompts")
        // 🔴 the originality wall: every speakable talent
        // string scanned against real songs, real
        // musicals and franchise acts
        val deny = listOf("let it go", "hamilton",
            "wicked", "thriller", "beatles", "pokemon",
            "pokémon", "spongebob", "star wars",
            "harry potter", "frozen", "moana", "encanto",
            "taylor swift", "beyonce", "beyoncé",
            "backstreet", "one direction", "baby shark",
            "macarena", "bohemian", "we will rock you",
            "lightsaber", "avengers", "batman", "superman",
            "spider-man", "disney", "mario", "zelda",
            "fortnite", "minecraft", "captain diabetes",
            "mysterion", "professor chaos", "gangnam",
            "despacito", "shake it off", "ymca")
        val corpus = Talent.ACTS.values.map { it.line } +
            Talent.PLAYER_ACTS.map { it.blurb } +
            Talent.VIGNETTES.values.flatten()
        check(corpus.none { line ->
            deny.any { line.lowercase().contains(it) } },
            "talent acts: the denylist holds — no real " +
                "song, musical or franchise act anywhere " +
                "in the authored tables")
        // and the room is kind: no mockery vocabulary in
        // the authored tables either
        val harsh = listOf("pathetic", "talentless",
            "humiliat", "booed", "worst act", "terrible",
            "awful act", "cringe")
        check(corpus.none { line ->
            harsh.any { line.lowercase().contains(it) } },
            "talent tone: the judging never mocks a kid " +
                "act — no cruelty vocabulary in the tables")
    }

    // ---------- the field, derived and re-derived ----------
    run {
        fun appetiteRef(year: Int, kid: String): Int =
            Play.stageNerve(kid) * 3 +
                School.skillOf(kid) * 2 +
                Random(("talentapp:$year:$kid").hashCode()
                    .toLong()).nextInt(10)
        var fieldsOk = true
        var ordersOk = true
        for (y in listOf(2026, 2027, 2031, 2040, 2055, 2099)) {
            val expect = CharacterSystem.CAST_KIDS
                .sortedWith(compareByDescending<String> {
                    appetiteRef(y, it) }.thenBy { it })
                .take(Talent.FIELD_SIZE)
            if (Talent.field(y) != expect) fieldsOk = false
            if (Talent.appetite(y, expect.first()) !=
                appetiteRef(y, expect.first())) {
                fieldsOk = false
            }
            val order = Talent.runningOrder(y)
            if (order.toSet() != expect.toSet() ||
                order.size != Talent.FIELD_SIZE) {
                ordersOk = false
            }
            if (Talent.audience(y).any { it in expect }) {
                ordersOk = false
            }
            if (Talent.playerSlot(y) !in
                0..Talent.FIELD_SIZE) ordersOk = false
        }
        check(fieldsOk,
            "talent field: the bill is the play's nerve " +
                "and the bee's voice, weighted 3/2 with a " +
                "seeded want — recomputed independently " +
                "here, appetite and field alike")
        check(ordersOk,
            "talent field: the running order is a " +
                "permutation of the field, the house never " +
                "overlaps the bill, and your slot is " +
                "always on the bill")
        // determinism: any save, any day, same bill
        val (_, sa) = talentState(14001)
        val (_, sb) = talentState(99999)
        setDayT(sa, 100)
        setDayT(sb, 5000)
        check(Talent.field(2033) == Talent.field(2033) &&
            Talent.runningOrder(2033) ==
                Talent.runningOrder(2033) &&
            sa.absDay != sb.absDay,
            "talent field: the derivation is pure data — " +
                "the same bill from any state")
        // the host is the stage desk of the judging
        // rotation, the play critic's own chair
        check((2026..2035).all { y ->
            Talent.hostOf(y) ==
                Yearbook.judgeFor(y, 5).name },
            "talent host: Yearbook's judging rotation, " +
                "column 5 — the same desk as the play's")
    }

    // ---------- the score, derived and re-derived ----------
    run {
        fun chemRef(state: GameState, year: Int,
                    entrant: String): Double {
            val others = Talent.field(year) - entrant
            if (others.isEmpty()) return 0.25
            val avg = others.map {
                Photos.chemistryBetween(state, entrant, it) }
                .average()
            return ((avg + 2.0) / 8.0).coerceIn(0.0, 1.0)
        }
        fun scoreRef(state: GameState, year: Int,
                     kid: String): Int {
            val wobble = Random(("talentwob:$year:$kid")
                .hashCode().toLong()).nextInt(11) - 5
            return (34 + Play.stageNerve(kid) * 4 +
                School.skillOf(kid) * 2 +
                (chemRef(state, year, kid) * 14)
                    .roundToInt() + wobble)
                .coerceIn(5, 99)
        }
        var ok = true
        for (y in listOf(2027, 2031, 2040)) {
            val (_, s) = talentState(14100L + y)
            setDayT(s, TalentCalendar.showDay(y))
            for (kid in Talent.field(y)) {
                if (Talent.actScore(s, y, kid) !=
                    scoreRef(s, y, kid)) ok = false
                if (Talent.chemRoom(s, y, kid) !=
                    chemRef(s, y, kid)) ok = false
            }
        }
        check(ok,
            "talent scores: nerve ×4, voice ×2, the " +
                "room's chemistry ×14 over a base of 34, " +
                "plus the night's seeded wobble — every " +
                "entrant's meter re-derived from raw inputs")
    }

    // ---------- signup + the rehearsal: honest ----------
    run {
        val y = 2027
        val (_, s) = talentState(14201)
        // before the poster: no sheet
        setDayT(s, TalentCalendar.announceDay(y) - 1)
        s.timeMin = 10 * 60
        check(Talent.signUp(s, "sing").first == "window" &&
            !Talent.entered(s) &&
            Talent.record(s, y) == null,
            "talent signup: before poster week the sheet " +
                "isn't up — nothing is spent or recorded")
        check(Talent.signUp(s, "opera").first == "window" ||
            Talent.signUp(s, "opera").first == "bad",
            "talent signup: an unlisted act is refused")
        // poster week: enter, and the slot is the seed's
        setDayT(s, TalentCalendar.announceDay(y) + 1)
        check(Talent.signUp(s, "opera").first == "bad",
            "talent signup: only the four authored acts " +
                "are on the sheet")
        val (kind, _) = Talent.signUp(s, "sing")
        val rec = Talent.record(s, y)!!
        check(kind == "entered" && rec.playerAct == "sing" &&
            rec.playerOrder == Talent.playerSlot(y),
            "talent signup: entered, at the year's seeded " +
                "slot in the running order")
        // the rehearsal: out of hours first (the stage
        // keeps 8-to-6), then the real thirty minutes
        s.timeMin = 7 * 60
        check(Talent.rehearse(s) == null &&
            Talent.record(s, y)?.rehearsed == false,
            "talent rehearsal: before 8 AM the stage is " +
                "dark — nothing is stamped")
        s.timeMin = 10 * 60
        val before = s.absDay * 1440 + s.timeMin
        val text = Talent.rehearse(s)
        val after = s.absDay * 1440 + s.timeMin
        check(text != null && after - before == 30 &&
            Talent.record(s, y)?.rehearsed == true,
            "talent rehearsal: thirty real minutes on " +
                "the town's own clock, once, banked")
        check(Talent.rehearse(s) == null,
            "talent rehearsal: there is no second one — " +
                "prep is stated, not ground")
        // changing your act keeps the slot and the prep
        val (kind2, _) = Talent.signUp(s, "magic")
        val rec2 = Talent.record(s, y)!!
        check(kind2 == "changed" && rec2.playerAct == "magic" &&
            rec2.playerOrder == rec.playerOrder &&
            rec2.rehearsed,
            "talent signup: a changed act keeps your slot " +
                "and your rehearsal — prep is stage prep")
        // at the doors on show day, the sheet is closed
        setDayT(s, TalentCalendar.showDay(y))
        s.timeMin = Talent.EVE_FROM
        check(!Talent.signupWindowOpen(s) &&
            Talent.signUp(s, "jokes").first == "window",
            "talent signup: at doors on show day the " +
                "sheet closes — the bill is the bill")
        // the rehearsal's worth, priced exactly
        check(Talent.playerScore(0.5, true) -
            Talent.playerScore(0.5, false) ==
            Talent.REHEARSE_BONUS,
            "talent rehearsal: worth exactly " +
                "+${Talent.REHEARSE_BONUS} on the meter")
    }

    // ---------- your act, played: the session ----------
    run {
        var shapesOk = true
        for (act in Talent.PLAYER_ACTS) {
            val s = Talent.TalentSession(act, 4242L)
            repeat(act.phrases) { s.step(0.5) }
            if (!s.over || s.held != act.phrases ||
                s.quality < 0.9 || s.result != "nailed") {
                shapesOk = false
            }
            val wild = Talent.TalentSession(act, 4242L)
            repeat(act.phrases) { wild.step(0.0) }
            if (wild.held != 0 ||
                wild.result != "sideways") {
                shapesOk = false
            }
            // the same seed replays the same act
            val again = Talent.TalentSession(act, 4242L)
            repeat(act.phrases) { again.step(0.5) }
            if (again.quality != s.quality) shapesOk = false
        }
        check(shapesOk,
            "talent session: perfect releases hold every " +
                "phrase of every act shape; wild releases " +
                "hold none; the seed replays the act whole")
        val jokes = Talent.playerAct("jokes")!!
        check(jokes.holdAt > Feel.POWER_GOOD &&
            jokes.phrases == 3 && jokes.sweepMs == 900L &&
            Talent.playerAct("magic")!!.jitter >
                Talent.playerAct("sing")!!.jitter,
            "talent session: jokes sweep fastest and hold " +
                "hardest (a joke lands or dies); magic is " +
                "the shakiest hands of the four")
    }

    // ---------- the claim: seating + behavior ----------
    run {
        val order = listOf("Dinners", "Birthdays", "Family",
            "Jobs", "MovieNights", "Capstones", "Finales",
            "Fair", "Carnival", "RivalCrew", "Heroes", "Play",
            "Dance", "Talent", "Parade", "Sleepovers", "Stand", "Crew")
        val idx = order.map { nm ->
            Regex("(?<![A-Za-z])$nm\\.gatheringBlock")
                .find(engineSrc)?.range?.first ?: -1 }
        check(idx.all { it >= 0 } && idx == idx.sorted() &&
            idx.distinct().size == idx.size,
            "talent claim: the agenda stack is eighteen " +
                "seats and the talent show sits after the " +
                "dance, before the parade (pinned from " +
                "Engine's own source)")
        val y = 2027
        val (_, s) = talentState(14250)
        setDayT(s, TalentCalendar.showDay(y))
        val star = Talent.field(y).first()
        val host = Talent.hostOf(y)
        val seat = Talent.audience(y).first()
        val nobody = CharacterSystem.CAST_KIDS.first {
            it !in Talent.field(y) && it != host &&
                it !in Talent.audience(y) }
        val eve = 19 * 60 + 30
        check(Talent.gatheringBlock(s, star, eve)
            ?.location == "Bijou" &&
            Talent.gatheringBlock(s, host, eve)
                ?.location == "Bijou" &&
            Talent.gatheringBlock(s, seat, eve)
                ?.location == "Bijou" &&
            Talent.gatheringBlock(s, nobody, eve) == null,
            "talent claim: the bill, the host and the " +
                "house are at the Bijou for the evening — " +
                "and nobody else is claimed")
        check(Talent.gatheringBlock(s, star, 10 * 60) ==
            null,
            "talent claim: the morning stands no claim")
        setDayT(s, TalentCalendar.announceDay(y))
        check(Talent.gatheringBlock(s, star, eve) == null,
            "talent claim: poster day is not the show")
    }

    // ---------- the Bijou stands down, both directions ----------
    run {
        val y = 2027
        val (_, s) = talentState(14260)
        setDayT(s, TalentCalendar.showDay(y))
        s.timeMin = 12 * 60
        check(MovieNights.darkReason(s) ==
            MovieNights.DARK_TALENT &&
            MovieNights.isDarkTonight(s) &&
            MovieNights.darkLine(s)?.contains(
                "talent show") == true &&
            MovieNights.textSender(s) == null,
            "talent stand-down: on show Saturday the " +
                "marquee is dark BY NAME (the talent show " +
                "has the stage) and no screening text goes " +
                "out that morning")
        // the movie house gathers nobody that night
        s.timeMin = 19 * 60 + 30
        val house = MovieNights.attendance(s)
        check(house.isNotEmpty() && house.all {
            MovieNights.gatheringBlock(s, it,
                19 * 60 + 30) == null },
            "talent stand-down: the screening's own claim " +
                "seats nobody on talent night")
        // the Saturday before: a normal screening night
        val (_, s2) = talentState(14261)
        setDayT(s2, TalentCalendar.showDay(y) - 7)
        s2.timeMin = 12 * 60
        check(MovieNights.darkReason(s2) == null &&
            Talent.nightClaimed(s2) == false,
            "talent stand-down: a week earlier the Bijou " +
                "screens as usual — the deference is one " +
                "night a year, not a season")
        // the talent claim itself is the one standing
        check(Talent.nightClaimed(s) &&
            Talent.eveningLive(s),
            "talent stand-down: the show's own claim on " +
                "its night is live")
    }

    // ---------- the yield set, forced live ----------
    run {
        val y = 2027
        // a holiday owns the day: the show yields, and
        // the marquee names the holiday, not the show
        val (_, s) = talentState(14270)
        setDayT(s, TalentCalendar.showDay(y))
        s.timeMin = 12 * 60
        s.holidayId = "valentine"
        check(HolidayBeats.beatFor("valentine") != null &&
            School.quietReason(s) == School.QUIET_HOLIDAY,
            "talent yield (staging): a holiday beat owns " +
                "the show day")
        check(Talent.yieldReason(s) == "holiday" &&
            !Talent.eveningLive(s) &&
            !Talent.nightClaimed(s) &&
            MovieNights.darkReason(s) ==
                MovieNights.DARK_HOLIDAY &&
            Talent.gatheringBlock(s,
                Talent.field(y).first(), 19 * 60) == null,
            "talent yield: a holiday yields the show the " +
                "whole year — no claim, no stand-down in " +
                "the show's name; the marquee names the " +
                "holiday")
        val recY = Talent.record(s, y)!!
        check(recY.yieldWhy == "holiday",
            "talent yield: the reason is stamped where " +
                "it is learned")
        setDayT(s, TalentCalendar.showDay(y) + 1)
        Talent.dailyRollover(s)
        val wrapped = Talent.record(s, y)!!
        check(wrapped.night == "yielded" &&
            Talent.phoneBeat(s) == null &&
            Talent.paperLine(s, Jobs.weekIndex(
                TalentCalendar.showDay(y)))
                ?.contains("not held") == true &&
            Talent.pageLines(s).any {
                it.contains("not held") },
            "talent yield: the wrap records the skipped " +
                "year with its reason — no text, the " +
                "paper and the page carry the fact")
        // a case climax owns the day: same machinery,
        // first in the quiet-day line
        val (_, s2) = talentState(14271)
        setDayT(s2, TalentCalendar.showDay(y))
        s2.timeMin = 12 * 60
        s2.shenaniganId = Mystery.FINALE_ID
        repeat(Mystery.TRUTH_MIN_CLUES) {
            s2.mysteryClues.add("clue$it") }
        check(School.quietReason(s2) == School.QUIET_CASE &&
            Talent.yieldReason(s2) == "case" &&
            !Talent.nightClaimed(s2) &&
            MovieNights.darkReason(s2) ==
                MovieNights.DARK_CASE,
            "talent yield: a case climax yields the show " +
                "too — and the marquee names the case")
    }

    // ---------- the night, watched whole (no entry) ----------
    run {
        val y = 2027
        val (_, s) = talentState(14280)
        setDayT(s, TalentCalendar.announceDay(y))
        // never sign up: the audience track is the test
        check(!Talent.entered(s), "talent night (staging)")
        atBijou(s, y, 19 * 60)
        for (kid in Talent.field(y)) seatAtBijou(s, kid)
        seatAtBijou(s, Talent.hostOf(y))
        for (kid in Talent.audience(y).take(6)) {
            seatAtBijou(s, kid)
        }
        check(Talent.screenOpen(s) &&
            Talent.sessionOpen(s) &&
            Talent.nextBeatKind(s) == "arrive",
            "talent night: the screen is the show's, and " +
                "the first beat is the arrival")
        val friendsBefore = Talent.field(y).associateWith {
            s.friendship[it] ?: 0 }
        check(Talent.playArrival(s) != null,
            "talent night: arrival lands")
        var guard = 0
        var acts = 0
        var prompts = 0
        while (guard++ < 60) {
            val rec = Talent.currentRecord(s)!!
            when (Talent.nextBeatKind(s)) {
                "act" -> {
                    val stepBefore = rec.step
                    val text = Talent.playAct(s)
                    if (text == null) break
                    acts++
                    val rec2 = Talent.currentRecord(s)!!
                    if (rec2.step != stepBefore + 1) break
                }
                "react" -> {
                    val beat = Talent.reactBeatKind(s, rec)
                    val buzzBefore = rec.buzz
                    val resp = Talent.react(s,
                        MovieNights.rightFor(beat))
                    if (resp == null) break
                    prompts++
                    val rec2 = Talent.currentRecord(s)!!
                    if (rec2.buzz != buzzBefore +
                        MovieNights.scoreFor(beat,
                            MovieNights.rightFor(beat))) break
                }
                "results" -> break
                else -> break
            }
        }
        val preRec = Talent.currentRecord(s)!!
        check(acts == Talent.FIELD_SIZE && prompts == 3 &&
            preRec.scores.size == Talent.FIELD_SIZE &&
            Talent.nextBeatKind(s) == "results",
            "talent night: all ten acts play in posted " +
                "order and the room is prompted three " +
                "times, scored by MovieNights' own tables " +
                "(acts $acts, prompts $prompts)")
        val expectedWinner = Talent.winnerOf(s, preRec)
        val results = Talent.finishNight(s)
        val rec = Talent.currentRecord(s)!!
        check(results != null && rec.night == "played" &&
            rec.winner == expectedWinner?.first &&
            rec.winScore == expectedWinner?.second,
            "talent night: the results derive the winner " +
                "from the landed table — ${rec.winner}")
        // the pays: entrants +1, the winner +2 more, and
        // a legendary house (three perfect reactions)
        // adds its +1 to the winner again
        val tier = MovieNights.tierFor(rec.buzz)
        var paysOk = true
        for (kid in Talent.field(y)) {
            var want = (friendsBefore[kid] ?: 0) +
                Talent.ENTER_PAY
            if (kid == rec.winner) {
                want += Talent.WINNER_PAY
                if (tier == "legendary") {
                    want += Talent.LEGENDARY_BONUS
                }
            }
            if ((s.friendship[kid] ?: 0) != want) {
                paysOk = false
            }
        }
        check(paysOk && Minigames.capsuleCoins(s) == 0,
            "talent night: a played-through night pays " +
                "its stated friendship (house: $tier) and " +
                "no coins move when the winner isn't you")
        // the photograph: one, captioned with the win
        val photo = s.photos.firstOrNull {
            it.id == rec.photoId }
        check(rec.photoId.isNotEmpty() && photo != null &&
            photo.caption.contains("Talent night") &&
            photo.caption.contains(rec.winner),
            "talent night: ONE winner's photograph, " +
                "minted in the room and captioned with " +
                "the winning act")
        // the records off the wrapped night
        check(Talent.pageLines(s).any {
            it.contains("🏆 ${rec.winner} won") } &&
            Talent.pageLines(s).any {
                it.contains("watched from the house") },
            "talent page: the wrapped night reads back " +
                "whole — and says you watched, honestly")
        check(Talent.paperLine(s, Jobs.weekIndex(
            TalentCalendar.showDay(y)))
            ?.contains(rec.winner) == true &&
            Talent.yearbookLine(s, y)
                ?.contains(rec.winner) == true &&
            Talent.yearbookLine(s, y)?.contains(
                Yearbook.labelOf(y)) == true,
            "talent records: the paper's one TOWN NEWS " +
                "line and the yearbook's line both derive " +
                "the winner off the wrapped record")
        // the morning after: the winner texts the fact
        setDayT(s, TalentCalendar.showDay(y) + 1)
        Talent.dailyRollover(s)
        val beat = Talent.phoneBeat(s)
        check(beat != null && beat.first == rec.winner &&
            beat.second == "talent" &&
            beat.third.contains(rec.winScore.toString()),
            "talent phone: the morning-after text is the " +
                "winner's, fact-only, under the TALENT " +
                "trigger")
        // page purity: derived per read, byte-identical
        check(Talent.pageLines(s) == Talent.pageLines(s),
            "talent page: rendered twice, byte-identical")
    }

    // ---------- the night, entered ----------
    run {
        val y = 2027
        val (_, s) = talentState(14290)
        setDayT(s, TalentCalendar.announceDay(y) + 2)
        s.timeMin = 10 * 60
        Talent.signUp(s, "sing")
        Talent.rehearse(s)
        atBijou(s, y, 19 * 60)
        for (kid in Talent.field(y)) seatAtBijou(s, kid)
        seatAtBijou(s, Talent.hostOf(y))
        Talent.playArrival(s)
        var guard = 0
        var judged: List<String>? = null
        while (guard++ < 60) {
            when (Talent.nextBeatKind(s)) {
                "act" -> Talent.playAct(s)
                "react" -> Talent.react(s,
                    MovieNights.REACT_APPLAUD)
                "youract" -> {
                    val act = Talent.playerAct("sing")!!
                    val sess = Talent.TalentSession(act,
                        Talent.sessionSeed(s))
                    repeat(act.phrases) { sess.step(0.5) }
                    judged = Talent.judgePlayerAct(s, sess)
                    val rec = Talent.currentRecord(s)!!
                    if (rec.playerScore !=
                        Talent.playerScore(sess.quality,
                            true)) break
                }
                "results" -> break
                else -> break
            }
        }
        val rec = Talent.currentRecord(s)!!
        check(judged != null && rec.playerScore >= 90 &&
            Talent.nextBeatKind(s) == "results",
            "talent night: your act is your played beat — " +
                "a nailed, rehearsed song reads " +
                "${rec.playerScore} on the meter")
        val expected = Talent.winnerOf(s, rec)
        Talent.finishNight(s)
        val done = Talent.currentRecord(s)!!
        check(done.night == "played" &&
            done.winner == expected?.first &&
            Talent.pageLines(s).any {
                it.contains("Your act:") },
            "talent night: an entered night wraps with " +
                "your placing stated on the page")
        // your forfeit is honest too: wrap an entered
        // year the player never showed for — the slot
        // reads zero and the room still crowns a winner
        val (_, s2) = talentState(14291)
        setDayT(s2, TalentCalendar.announceDay(y))
        s2.timeMin = 10 * 60
        Talent.signUp(s2, "dance")
        setDayT(s2, TalentCalendar.showDay(y) + 1)
        Talent.dailyRollover(s2)
        val rec2 = Talent.record(s2, y)!!
        check(rec2.night == "missed" &&
            rec2.winner.isNotEmpty() &&
            rec2.winner != "You" &&
            Talent.pageLines(s2).any {
                it.contains("never took the stage") },
            "talent night: a no-show entry wraps missed — " +
                "the empty slot reads as the zero it was")
    }

    // ---------- the winner's envelope, and ties ----------
    run {
        val y = 2027
        val (_, s) = talentState(14300)
        setDayT(s, TalentCalendar.showDay(y))
        val rec = Talent.recordOrNew(s, y)
        rec.playerAct = "sing"
        rec.playerOrder = 3
        rec.playerScore = 95
        rec.nightDay = TalentCalendar.showDay(y)
        for (kid in Talent.field(y)) rec.scores[kid] = 10
        Talent.saveRecord(s, rec)
        Talent.settle(s, rec)
        check(rec.winner == "You" && rec.winScore == 95 &&
            Minigames.capsuleCoins(s) ==
                Talent.WINNER_COINS,
            "talent prizes: when you win, the envelope " +
                "settles — exactly ${Talent.WINNER_COINS} " +
                "coins, once")
        Talent.settle(s, rec)
        check(Minigames.capsuleCoins(s) ==
            Talent.WINNER_COINS,
            "talent prizes: settling twice pays once")
        // the phone, when it's you: the host sends it
        val recW = Talent.recordOrNew(s, y)
        recW.night = "played"
        Talent.saveRecord(s, recW)
        setDayT(s, TalentCalendar.showDay(y) + 1)
        val beat = Talent.phoneBeat(s)
        check(beat != null && beat.first ==
            Talent.hostOf(y),
            "talent phone: when you win, the host texts " +
                "the result — the sender set stays closed")
    }
    run {
        // the tie-break order, level by level: score,
        // then the room's chemistry, then nerve, then
        // the alphabet — against an independent sort
        fun expectedWinner(state: GameState, year: Int,
                           rec: Talent.TalentRecord): String {
            fun chem(kid: String): Double {
                val others = Talent.field(year) - kid
                if (others.isEmpty()) return 0.25
                val avg = others.map {
                    Photos.chemistryBetween(state, kid, it) }
                    .average()
                return ((avg + 2.0) / 8.0)
                    .coerceIn(0.0, 1.0)
            }
            return Talent.field(year).sortedWith(
                compareByDescending<String> {
                    rec.scores[it] ?: 0 }
                    .thenByDescending { chem(it) }
                    .thenByDescending {
                        Play.stageNerve(it) }
                    .thenBy { it }).first()
        }
        var tieYears = 0
        for (y in 2027..2056) {
            val (_, s) = talentState(14310L + y)
            setDayT(s, TalentCalendar.showDay(y))
            val rec = Talent.TalentRecord(y)
            val f = Talent.field(y)
            // quantized scores: a three-way tie at the top
            for ((i, kid) in f.withIndex()) {
                rec.scores[kid] =
                    if (i < 3) 60 else 30 + (i % 4) * 5
            }
            val got = Talent.winnerOf(s, rec)
            if (got?.first == expectedWinner(s, y, rec) &&
                got.second == 60) tieYears++
        }
        check(tieYears >= 25,
            "talent ties: across thirty fabricated " +
                "three-way ties, the winner is always the " +
                "independent sort's — score, chemistry, " +
                "nerve, alphabet ($tieYears years agree)")
        // the deep levels: equal score AND equal room —
        // two kids no field member recognizes, bonds all
        // at the default — nerve decides; nerve equal
        // too, the alphabet decides
        var nerveCase = false
        var alphaCase = false
        for (y in 2027..2100) {
            val (_, s) = talentState(14320L + y)
            setDayT(s, TalentCalendar.showDay(y))
            val f = Talent.field(y)
            val clean = f.filter { a ->
                f.none { b -> a != b &&
                    Photos.isRecognizedPair(a, b) } }
            if (clean.size < 2) continue
            for (i in clean.indices) {
                for (j in (i + 1) until clean.size) {
                    val a = clean[i]
                    val b = clean[j]
                    val rec = Talent.TalentRecord(y)
                    for (kid in f) rec.scores[kid] = 10
                    rec.scores[a] = 70
                    rec.scores[b] = 70
                    val got = Talent.winnerOf(s, rec)?.first
                    val na = Play.stageNerve(a)
                    val nb = Play.stageNerve(b)
                    when {
                        na != nb && !nerveCase -> {
                            if (got == (if (na > nb) a
                                else b)) nerveCase = true
                        }
                        na == nb && !alphaCase -> {
                            if (got == minOf(a, b)) {
                                alphaCase = true
                            }
                        }
                    }
                }
            }
            if (nerveCase && alphaCase) break
        }
        check(nerveCase && alphaCase,
            "talent ties: with score and room both equal, " +
                "nerve decides — and with nerve equal too, " +
                "the alphabet does (both levels exercised " +
                "on real fields)")
    }

    // ---------- the wraps: missed, partial, announced ----------
    run {
        val y = 2027
        // the poster ticker lands on announcement morning
        val (_, s0) = talentState(14330)
        setDayT(s0, TalentCalendar.announceDay(y))
        Talent.dailyRollover(s0)
        check(s0.events.any {
            it.contains("Poster up at the Bijou") },
            "talent rollover: the announcement morning " +
                "ticks the poster")
        // a year nobody touched: the show still happened
        val (_, s) = talentState(14331)
        setDayT(s, TalentCalendar.showDay(y) + 1)
        Talent.dailyRollover(s)
        val rec = Talent.record(s, y)
        check(rec != null && rec.night == "missed" &&
            rec.winner.isNotEmpty() &&
            s.townLog.any { it.contains("Talent night") },
            "talent rollover: an untouched year wraps " +
                "missed with the town's winner derived — " +
                "the paper and the yearbook can carry it")
        // a started night the player walked out of
        val (_, s2) = talentState(14332)
        atBijou(s2, y, 19 * 60)
        Talent.playArrival(s2)
        setDayT(s2, TalentCalendar.showDay(y) + 1)
        Talent.dailyRollover(s2)
        val rec2 = Talent.record(s2, y)!!
        check(rec2.night == "partial" &&
            (s2.friendship[Talent.field(y).first()]
                ?: 0) == 0,
            "talent rollover: a walked-out night wraps " +
                "partial and pays nobody — the movie " +
                "pattern, kept")
        // gossip: an entrant talks the run-up on their
        // seeded days, and the winner remembers after
        val (_, s3) = talentState(14333)
        var heard = false
        for (d in TalentCalendar.announceDay(y)..
            TalentCalendar.showDay(y)) {
            setDayT(s3, d)
            s3.timeMin = 10 * 60
            if (Talent.field(y).any {
                Talent.gossipLine(s3, it) != null }) {
                heard = true
            }
        }
        check(heard,
            "talent gossip: the bill talks its acts in " +
                "the run-up (the play's pattern)")
        // purity: the poster renders byte-identical
        val (_, s4) = talentState(14334)
        setDayT(s4, TalentCalendar.announceDay(y) + 1)
        s4.timeMin = 10 * 60
        check(Talent.posterText(s4) ==
            Talent.posterText(s4) &&
            Talent.posterText(s4).contains("TALENT NIGHT"),
            "talent poster: derived per read, " +
                "byte-identical, the bill posted whole")
    }

    // ---------- saves ----------
    run {
        val y = 2027
        val (_, s) = talentState(14340)
        setDayT(s, TalentCalendar.announceDay(y))
        s.timeMin = 10 * 60
        Talent.signUp(s, "magic")
        atBijou(s, y, 19 * 60)
        for (kid in Talent.field(y)) seatAtBijou(s, kid)
        Talent.playArrival(s)
        Talent.playAct(s)
        Talent.playAct(s)
        val back = decodeGameState(encodeGameState(s))
        val recB = Talent.record(back, y)
        val recA = Talent.record(s, y)
        check(recB != null && recA != null &&
            recB.scores == recA.scores &&
            recB.step == recA.step &&
            recB.playerAct == "magic" &&
            recB.arrived,
            "talent saves: a mid-night record round-trips " +
                "the real save path whole")
        // a pre-0.13.0c save has no talent keys at all —
        // it joins the next show like anyone
        val (_, old) = talentState(14341)
        check(old.lifeText.keys.none {
            it.startsWith("talent") },
            "talent saves: a fresh (pre-talent) save " +
                "carries no talent state")
        setDayT(old, TalentCalendar.announceDay(2028))
        old.timeMin = 10 * 60
        check(Talent.signUp(old, "jokes").first ==
            "entered" &&
            Talent.record(old, 2028)?.playerAct == "jokes",
            "talent saves: the old save joins the next " +
                "show — additive-only, nothing to migrate")
    }

    // ---------- wiring ----------
    run {
        check(gameSrc.contains("Talent.screenOpen(state)") &&
            gameSrc.contains("talentDialog()") &&
            gameSrc.contains("startTalentAct()") &&
            gameSrc.contains(
                "Talent.lookText(state, me.location)") &&
            viewsSrc.contains("class TalentActView") &&
            viewsSrc.contains("Talent.TalentSession"),
            "talent wiring: the screen routes to the " +
                "show in its week, your act launches its " +
                "played view, and Look carries the poster")
        check(phoneSrc.contains("const val TALENT") &&
            phoneSrc.contains("Talent.phoneBeat(state)") &&
            paperSrc.contains("Talent.paperLine(state, week)") &&
            journalSrc.contains("Talent.pageLines(state)") &&
            journalSrc.contains("Talent.yearbookLine(state, r.year)") &&
            engineSrc.contains(
                "Talent.gatheringBlock(state, a.name, timeMin)") &&
            engineSrc.contains("Talent.dailyRollover(state)"),
            "talent wiring: one phone trigger, one paper " +
                "hook, the Journal page and yearbook line, " +
                "the claim and the rollover")
        check(movieSrc.contains("DARK_TALENT") &&
            movieSrc.contains("Talent.nightClaimed(state)") &&
            talkSrc.contains(
                "Talent.gossipLine(state, npcName)") &&
            talentSrc.contains("object TalentCalendar"),
            "talent wiring: the Bijou's deference reads " +
                "the show's claim, and the talk seam is a " +
                "seam — TalkGate keeps its eleven rails")
    }
}

// ============================================================
// v0.13.0d — the town parade. The fourth seasonal anchor:
// the third Saturday of May, the whole town derived into a
// procession down Main Street. These checks pin the anchor
// in ONE lived ordinal space against every other claim on
// the town's calendar, the procession's derivation (order,
// claim priority, no double placement, purity), the claim's
// seat, the yield set, both participation tracks played
// whole, the candy economy COMPUTED at perfect play, the
// Walk closure priced on both sides of the street, and the
// record's paper/phone/Journal derivations.
// ============================================================
private fun sectionV0130d(root: String) {
    println("== v0.13.0d: the town parade ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val engineSrc = File(srcDir, "Engine.kt").readText()
    val paradeSrc = File(srcDir, "Parade.kt").readText()
    val walkSrc = File(srcDir, "Walk.kt").readText()
    val gameSrc = File(srcDir, "GameActivity.kt").readText()
    val viewSrc = File(srcDir, "GameView.kt").readText()
    val minigameSrc = File(srcDir, "MinigameViews.kt").readText()
    val journalSrc = File(srcDir, "JournalActivity.kt").readText()
    val phoneSrc = File(srcDir, "Phone.kt").readText()
    val paperSrc = File(srcDir, "Newspaper.kt").readText()
    val talkSrc = File(srcDir, "TalkGate.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "v0.13.0d: the manifest carries this build (98 / 0.13.0d)")
    check(readme.contains("### v0.13.0d"),
        "v0.13.0d: the README carries this build's changelog entry")
    check(readme.contains("## Status — v0.13.0d"),
        "v0.13.0d: the README carries this build's status section")
    val ktCount = srcDir.listFiles { f -> f.extension == "kt" }
        ?.size ?: 0
    check(ktCount == 137 && readme.contains("106 Kotlin files"),
        "v0.13.0d: one new module (Parade.kt) — the tree " +
            "stands at 106 Kotlin files (found $ktCount)")

    fun paradeState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return e to s
    }
    fun setDayP(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    /** Put the player on Main Street, outdoors. */
    fun atStreet(s: GameState, year: Int, timeMin: Int) {
        setDayP(s, ParadeCalendar.paradeDay(year))
        s.timeMin = timeMin
        val me = s.agents.values.first { it.isPlayer }
        me.location = "MainStreet"
        s.playerInside = false
    }
    fun seatAtStreet(s: GameState, name: String) {
        s.agents[name]?.let { it.location = "MainStreet" }
    }

    // ---------- the anchor: shape ----------
    run {
        var allShape = true
        for (y in 2026..2100) {
            val d = ParadeCalendar.paradeDay(y)
            val ord = FairCalendar.ordinalOfAbsDay(d)
            val key = keyFromOrdinal(ord)
            if (key.substring(4, 6) != "05") allShape = false
            val dom = key.substring(6, 8).toInt()
            if (dom !in 15..21) allShape = false
            if (FairCalendar.dowOfOrdinal(ord) != 6) {
                allShape = false   // a Saturday, always
            }
            if (!Dance.dateLabel(d).startsWith("Sat")) {
                allShape = false
            }
            if (ParadeCalendar.announceDay(y) != d - 7) {
                allShape = false
            }
        }
        check(allShape,
            "parade calendar: the third Saturday of May, " +
                "always May 15–21, announced exactly a week " +
                "ahead (2026–2100)")
    }

    // ---------- the anchor: disjointness, ONE time space ----------
    run {
        var collisions = 0
        var detail = ""
        var minTalentGap = Int.MAX_VALUE
        var minFinaleGap = Int.MAX_VALUE
        for (y in 2026..2100) {
            val d = ParadeCalendar.paradeDay(y)
            val dOrd = FairCalendar.ordinalOfAbsDay(d)
            // the dance: February's night, never close
            val dd = DanceCalendar.danceDay(y)
            if (abs(d - dd) <= 21) {
                collisions++; detail = "dance $y" }
            // the talent show: April's Saturday — measured,
            // not assumed (the parade's nearest neighbor)
            val td = TalentCalendar.showDay(y)
            if (abs(d - td) <= 21) {
                collisions++; detail = "talent $y" }
            minTalentGap = minOf(minTalentGap, d - td)
            // the play: the openings of the productions
            // whose school years bracket this May
            for (sy in (y - 1)..(y + 1)) {
                val o = PlayCalendar.scheduleFor(sy).openingDay
                if (d in (o - 21)..(o + 21)) {
                    collisions++; detail = "play $sy" }
            }
            // the fair's week, from its own window
            val fw = FairCalendar.windowFor(y)
            if (dOrd in fw.startOrd..fw.endOrd) {
                collisions++; detail = "fair $y" }
            // the carnival's week, same construction
            val cw = CarnivalCalendar.windowFor(y)
            if (dOrd in cw.startOrd..cw.endOrd) {
                collisions++; detail = "carnival $y" }
            // every finale window: the last 7 days of each
            // season, derived from Finales' own anchors
            for (season in Season.values()) {
                val (em, ed) = Finales.seasonEndMonthDay(season, y)
                val endOrd = ordinalOfKey(
                    "%04d%02d%02d".format(y, em, ed))
                if (dOrd in (endOrd - 6)..endOrd) {
                    collisions++; detail = "finale $season $y" }
                if (season == Season.SPRING) {
                    minFinaleGap = minOf(minFinaleGap,
                        (endOrd - 6) - dOrd)
                }
            }
            // the holidays: GameData's own table, as lived
            // month-days (May holds none — proven, not hoped)
            val md = keyFromOrdinal(dOrd).substring(4, 8).toInt()
            for (h in HOLIDAYS) {
                val from = h.startMd.toInt()
                val to = h.endMd.toInt()
                val inSpan = if (from <= to) md in from..to
                    else md >= from || md <= to
                if (inSpan) {
                    collisions++; detail = "holiday ${h.id} $y" }
            }
        }
        check(collisions == 0,
            "parade calendar: 2026–2100, the parade day never " +
                "lands within three weeks of the dance, the " +
                "talent show or a play opening, never in the " +
                "fair's week, the carnival's week, a finale " +
                "window or ANY holiday window ($detail)")
        check(minTalentGap >= 31 && minFinaleGap >= 4,
            "parade calendar: the measured clearances — at " +
                "least 31 days after the talent show and at " +
                "least 4 days before the spring finale's " +
                "window opens, every year (talent gap " +
                "$minTalentGap, finale gap $minFinaleGap)")
    }

    // ---------- the dials ----------
    run {
        check(Parade.PARADE_FROM == 10 * 60 &&
            Parade.PARADE_TO == 13 * 60 + 30 &&
            Parade.ANN_BACK == 7 && Parade.CHUNK == 4 &&
            Parade.FACTION_CREW_CAP == 6 &&
            Parade.THROWS_PER == 3 && Parade.CANDY_CAP == 6 &&
            Parade.MARCH_PAY == 1 &&
            Parade.PASS_DELAY_MIN == 15 &&
            Parade.PHOTO_CREW_CAP == 12,
            "parade dials: a 10:00–13:30 window, the poster " +
                "a week out, chunks of four, six riders to a " +
                "faction float, three throws a thrower, " +
                "pockets holding six, the march paying +1, " +
                "one tick to pass through, twelve in a frame")
        check(Parade.THROWERS == mapOf(
            "hh:cartman" to "snack_cake",
            "bijou" to "cheesy_poof",
            "cityhall" to "cheesy_poof") &&
            Parade.THROWERS.keys.none { it == "stand" },
            "parade dials: three throwers — the Cartman " +
                "float (snack cakes), the Bijou's float and " +
                "the Mayor's car (cheesy poofs), the stand's " +
                "own stock items; your own stand throws " +
                "nothing (no loop)")
        check(Parade.SPOTS.map { it.id } == listOf("bank",
            "bijou", "postoffice", "cityhall"),
            "parade dials: four curb spots on the real " +
                "Main Street frontage — bank steps, Bijou " +
                "marquee, post office corner, City Hall steps")
    }

    // ---------- the procession: derivation ----------
    run {
        val y = 2027
        val (_, s) = paradeState(14400)
        setDayP(s, ParadeCalendar.announceDay(y))
        val proc = Parade.procession(s, y)
        val ids = proc.map { it.id }
        val wantIds = listOf("school") +
            Dinners.HOUSEHOLDS.map { "hh:${it.id}" } +
            listOf("bijou", "fac:boys_crew", "fac:goth_kids",
                "fac:girls_circle", "fac:craigs_gang",
                "fac:parents", "fac:church_faithful",
                "fac:tegridy_crew", "cityhall")
        check(ids == wantIds,
            "parade procession: the derived order on a " +
                "plain year — the school leads, the seven " +
                "households roll, the Bijou, the seven " +
                "standing factions, and the Mayor's car " +
                "last (got $ids)")
        val hall = proc.last()
        check(hall.id == "cityhall" &&
            "McDaniels" in hall.crew &&
            "Barbrady" in hall.crew && "Yates" in hall.crew,
            "parade procession: the mayor rides last, with " +
                "the law along — claimed before any faction " +
                "float could carry her off")
        val flat = proc.flatMap { it.crew }
        check(flat.size == flat.toSet().size &&
            flat.all { it in CharacterSystem.CAST },
            "parade procession: nobody is in two places — " +
                "${flat.size} riders, every one cast, no " +
                "name aboard twice")
        var householdsWhole = true
        for (h in Dinners.HOUSEHOLDS) {
            val e = proc.first { it.id == "hh:${h.id}" }
            if (e.crew != h.members) householdsWhole = false
        }
        check(householdsWhole,
            "parade procession: every Dinners household " +
                "rides whole — families first claim, always")
        var factionsHonest = true
        for (f in FACTIONS) {
            val e = proc.firstOrNull {
                it.id == "fac:${f.id}" || (f.id ==
                    "school_staff" && it.id == "school") }
                ?: run { factionsHonest = false; null }
            if (e == null) continue
            if (e.crew.size > Parade.FACTION_CREW_CAP ||
                !e.crew.all { it in f.members }) {
                factionsHonest = false }
            val avail = f.members.filter { name ->
                name in CharacterSystem.CAST && proc.none {
                    it.id != e.id && name in it.crew } }
            if (avail.isNotEmpty() &&
                avail.first() !in e.crew) {
                factionsHonest = false }
        }
        check(factionsHonest,
            "parade procession: faction floats carry at " +
                "most the stated six riders, all true " +
                "members, the first-listed unclaimed member " +
                "always aboard")
        check(proc.first().name ==
            "South Park Elementary" &&
            proc.first().crew.all {
                it in (FACTIONS.first {
                    it.id == "school_staff" }.members) },
            "parade procession: the Elementary's float IS " +
                "the school staff's — one school, one entry, " +
                "derived from the faction table")
        check("McDaniels" !in (proc.first {
            it.id == "fac:parents" }.crew) &&
            "Randy" !in (proc.first {
                it.id == "fac:parents" }.crew),
            "parade procession: claim order is real — the " +
                "mayor rides her car (not the parents' " +
                "float) and Randy rides with his family")
        // the crowd: the whole rest of the town, at spots
        val crowd = Parade.routeCrowd(s, y)
        val placed = Parade.placedNames(s, y)
        check(crowd.toSet() intersect placed == emptySet<String>() &&
            (crowd + placed).toSet() ==
                CharacterSystem.CAST.keys.toSet() &&
            crowd.isNotEmpty(),
            "parade crowd: riders and watchers partition " +
                "the whole cast — nobody placed twice, " +
                "nobody lost")
        val spotUnion = Parade.SPOTS.flatMap {
            Parade.crowdAt(s, y, it.id) }
        check(spotUnion.toSet() == crowd.toSet() &&
            spotUnion.size == crowd.size,
            "parade crowd: the four curb spots partition " +
                "the route crowd exactly")
        // purity: the same town derives the same parade,
        // and reading it creates no record
        val proc2 = Parade.procession(s, y)
        Parade.pageLines(s)
        Parade.posterText(s)
        Parade.lookText(s, "MainStreet")
        check(proc == proc2 &&
            s.lifeText.keys.none { it.startsWith("parade") },
            "parade derivation: pure — two reads derive " +
                "the same procession, and no read (page, " +
                "poster, look) creates a parade fact")
    }

    // ---------- your entries: crew & stand ----------
    run {
        val y = 2027
        // a crew of kids with no households: they march
        val (_, s) = paradeState(14410)
        setDayP(s, ParadeCalendar.announceDay(y))
        s.lifeText["crew:members"] = "Pip,Dougie"
        val proc = Parade.procession(s, y)
        val crewE = proc.firstOrNull { it.id == "crew" }
        check(crewE != null && crewE.crew ==
            listOf("Pip", "Dougie") &&
            proc.indexOf(crewE) == proc.size - 2 &&
            "Pip" !in proc.first {
                it.id == "fac:boys_crew" }.crew &&
            Parade.marchEntryFor(s) == "crew",
            "parade entries: your crew marches as its own " +
                "entry, second from the rear — and the " +
                "Boys' Crew float rolls without them (your " +
                "people outrank their faction)")
        // a crewmate in a household rides the family float;
        // you still march under your crew's banner
        val (_, s2) = paradeState(14411)
        setDayP(s2, ParadeCalendar.announceDay(y))
        s2.lifeText["crew:members"] = "Stan,Pip"
        val proc2 = Parade.procession(s2, y)
        check(proc2.first { it.id == "crew" }.crew ==
            listOf("Pip") &&
            "Stan" in proc2.first {
                it.id == "hh:marsh" }.crew &&
            Parade.marchEntryFor(s2) == "crew",
            "parade entries: Stan rides the Marsh float " +
                "(family claims first) and your crew entry " +
                "still stands — you carry the banner")
        // no crew: the school's walking entry
        val (_, s3) = paradeState(14412)
        check(Parade.marchEntryFor(s3) == "school" &&
            Parade.procession(s3, y).none {
                it.id == "crew" },
            "parade entries: crewless, you march as a " +
                "stated free-agent walker with the school")
        // the stand float: the real crate, at your prices
        val (_, s4) = paradeState(14413)
        setDayP(s4, ParadeCalendar.announceDay(y))
        s4.lifeText["standLoc"] = "KidsPark"
        s4.lifeText["standCrate"] =
            "cheesy_poof:${s4.absDay}:3;snack_cake:${s4.absDay}:2"
        val proc4 = Parade.procession(s4, y)
        val standE = proc4.firstOrNull { it.id == "stand" }
        check(standE != null &&
            proc4.indexOf(standE) == proc4.size - 2 &&
            standE.theme.contains(
                itemById("cheesy_poof")!!.name) &&
            standE.theme.contains("×3") &&
            standE.theme.contains(
                "${Stand.priceOf(s4, "cheesy_poof")} 🪙"),
            "parade entries: the stand float rolls when " +
                "your stand stands — its line derived from " +
                "the crate's real contents at your real " +
                "prices")
        // the stand's staffer of the day rides it
        val (_, s5) = paradeState(14414)
        setDayP(s5, ParadeCalendar.paradeDay(y))
        s5.lifeText["standLoc"] = "KidsPark"
        s5.life["standOpenDay"] = s5.absDay
        s5.lifeText["standStaff"] = "Pip"
        val standE5 = Parade.procession(s5, y)
            .firstOrNull { it.id == "stand" }
        check(standE5?.crew == listOf("Pip"),
            "parade entries: the stand's assigned staffer " +
                "rides the stand float (claimed before the " +
                "factions, after the households)")
    }

    // ---------- the claim: seating + behavior ----------
    run {
        val order = listOf("Dinners", "Birthdays", "Family",
            "Jobs", "MovieNights", "Capstones", "Finales",
            "Fair", "Carnival", "RivalCrew", "Heroes", "Play",
            "Dance", "Talent", "Parade", "Sleepovers",
            "Stand", "Crew")
        val idx = order.map { nm ->
            Regex("(?<![A-Za-z])$nm\\.gatheringBlock")
                .find(engineSrc)?.range?.first ?: -1 }
        check(idx.all { it >= 0 } && idx == idx.sorted() &&
            idx.distinct().size == idx.size,
            "parade claim: the agenda stack is eighteen " +
                "seats and the parade sits after the talent " +
                "show, before sleepovers (pinned from " +
                "Engine's own source)")
        val y = 2027
        val (_, s) = paradeState(14420)
        setDayP(s, ParadeCalendar.paradeDay(y))
        val rider = Parade.procession(s, y).first {
            it.id == "hh:marsh" }.crew.first()
        val watcher = Parade.routeCrowd(s, y).first()
        val mid = 11 * 60
        check(Parade.gatheringBlock(s, rider, mid)
            ?.location == "MainStreet" &&
            Parade.gatheringBlock(s, watcher, mid)
                ?.location == "MainStreet" &&
            Parade.gatheringBlock(s, rider, mid)
                ?.activity?.contains("🎺") == true,
            "parade claim: on the day, riders and the " +
                "route crowd alike are held on Main Street " +
                "through the window")
        check(Parade.gatheringBlock(s, rider, 9 * 60) ==
            null &&
            Parade.gatheringBlock(s, rider,
                Parade.PARADE_TO + 15) == null,
            "parade claim: the street is the town's " +
                "before 10:00 and after 13:30 — the claim " +
                "stands only inside its stated window")
        setDayP(s, ParadeCalendar.announceDay(y))
        check(Parade.gatheringBlock(s, rider, mid) == null,
            "parade claim: poster day is not the parade")
    }

    // ---------- the yield set, forced live ----------
    run {
        val y = 2027
        // a holiday owns the day
        val (_, s) = paradeState(14430)
        setDayP(s, ParadeCalendar.paradeDay(y))
        s.timeMin = 11 * 60
        s.holidayId = "valentine"
        check(HolidayBeats.beatFor("valentine") != null &&
            School.quietReason(s) == School.QUIET_HOLIDAY,
            "parade yield (staging): a holiday beat owns " +
                "the parade day")
        check(Parade.yieldReason(s) == School.QUIET_HOLIDAY &&
            !Parade.dayLive(s) && !Parade.streetClosed(s) &&
            Parade.gatheringBlock(s, "Stan", 11 * 60) == null,
            "parade yield: a holiday yields the parade " +
                "the whole year — no claim, and the street " +
                "never closes")
        val recY = Parade.record(s, y)!!
        check(recY.yieldWhy == School.QUIET_HOLIDAY,
            "parade yield: the reason is stamped where " +
                "it is learned")
        setDayP(s, ParadeCalendar.paradeDay(y) + 1)
        Parade.dailyRollover(s)
        val wrapped = Parade.record(s, y)!!
        check(wrapped.wrapped == "yielded" &&
            Parade.phoneBeat(s) == null &&
            Parade.paperLine(s, Jobs.weekIndex(
                ParadeCalendar.paradeDay(y)))
                ?.contains("not held") == true &&
            Parade.pageLines(s).any {
                it.contains("not held") },
            "parade yield: the wrap records the skipped " +
                "year with its reason — no text, the paper " +
                "and the page carry the fact")
        // a case climax owns the day: same machinery
        val (_, s2) = paradeState(14431)
        setDayP(s2, ParadeCalendar.paradeDay(y))
        s2.timeMin = 11 * 60
        s2.shenaniganId = Mystery.FINALE_ID
        repeat(Mystery.TRUTH_MIN_CLUES) {
            s2.mysteryClues.add("clue$it") }
        check(School.quietReason(s2) == School.QUIET_CASE &&
            Parade.yieldReason(s2) == School.QUIET_CASE &&
            !Parade.dayLive(s2),
            "parade yield: a case climax yields the " +
                "parade too — the standard owners take " +
                "the day whole")
    }

    // ---------- the day, WATCHED whole ----------
    run {
        val y = 2027
        val (_, s) = paradeState(14440)
        // a friend on your curb, for the morning-after text
        val neighbor = Parade.crowdAt(s, y, "bijou").first()
        s.friendship[neighbor] = 60
        atStreet(s, y, 10 * 60)
        // the Bijou's riders are on the street (the claim
        // puts them there in play; the shutter needs them)
        val bijou = Parade.procession(s, y).first {
            it.id == "bijou" }
        for (name in bijou.crew) seatAtStreet(s, name)
        check(Parade.sessionOpen(s) &&
            Parade.nextBeatKind(s) == "choose",
            "parade watch: the stand is live on the day, " +
                "and the first beat is the choosing")
        check(Parade.playChoose(s, "watch", "bijou") != null,
            "parade watch: you take the Bijou-marquee spot")
        val rec0 = Parade.currentRecord(s)!!
        check(rec0.mode == "watch" && rec0.spot == "bijou",
            "parade watch: the choice is the record's")
        check(Parade.playLineup(s) != null &&
            Parade.currentRecord(s)!!.stage == 1,
            "parade watch: the lineup reads the order out")
        val perfect = (Feel.ZONE_PERFECT_LO +
            Feel.ZONE_PERFECT_HI) / 2.0
        var guard = 0
        var passes = 0
        var catches = 0
        while (guard++ < 40) {
            when (Parade.nextBeatKind(s)) {
                "pass" -> {
                    val stepBefore =
                        Parade.currentRecord(s)!!.step
                    if (Parade.playPass(s) == null) break
                    passes++
                    if (Parade.currentRecord(s)!!.step !=
                        stepBefore + 1) break
                }
                "catch" -> {
                    val thrower = Parade.catchOwed(s)!!
                    val session = Parade.CatchSession(
                        thrower, Parade.catchSeed(s, thrower))
                    while (!session.over) {
                        session.toss(perfect) }
                    val lines = Parade.judgeCatch(s, session)
                    if (lines == null) break
                    catches++
                    if (session.caught !=
                        Parade.THROWS_PER) break
                }
                else -> break
            }
        }
        check(passes == Parade.chunks(s, y).size &&
            catches == Parade.THROWERS.size,
            "parade watch: every chunk passed your spot " +
                "and all three throwers threw (passes " +
                "$passes, catches $catches)")
        val recC = Parade.currentRecord(s)!!
        check(recC.caughtTotal == Parade.CANDY_CAP &&
            (s.inventory["snack_cake"] ?: 0) == 3 &&
            (s.inventory["cheesy_poof"] ?: 0) == 3,
            "parade candy: perfect play at all three " +
                "throwers still lands exactly the cap — " +
                "3 snack cakes, 3 cheesy poofs, the third " +
                "thrower's haul bouncing to the kid next " +
                "door (caught ${recC.caughtTotal})")
        // a settled thrower cannot be milked twice
        val again = Parade.CatchSession("bijou",
            Parade.catchSeed(s, "bijou"))
        check(Parade.judgeCatch(s, again) == null,
            "parade candy: a settled catch session pays " +
                "once — no replay, no second haul")
        check(Parade.nextBeatKind(s) == "photo" &&
            Parade.photoOptions(s).any {
                it.id == "bijou" },
            "parade watch: the shutter beat offers the " +
                "floats with riders actually on the street")
        val photosBefore = s.photos.size
        check(Parade.takePhoto(s, "bijou") != null,
            "parade watch: the one photograph mints")
        val recP = Parade.currentRecord(s)!!
        val photo = s.photos.firstOrNull {
            it.id == recP.photoId }
        check(s.photos.size == photosBefore + 1 &&
            photo != null &&
            photo.caption.contains("Founders' Day Parade") &&
            photo.caption.contains("Bijou") &&
            recP.photoEntry == "bijou",
            "parade watch: exactly one photo, captioned " +
                "with the parade and your float of choice")
        check(Parade.takePhoto(s, "bijou") == null,
            "parade watch: the day mints ONE photograph")
        check(Parade.nextBeatKind(s) == "mayor" &&
            Parade.playMayor(s) != null,
            "parade watch: the Mayor's car closes the day")
        val recF = Parade.currentRecord(s)!!
        check(recF.wrapped == "played" &&
            Parade.nextBeatKind(s) == null,
            "parade watch: the day wraps as played, whole")
        // the surfaces, off the wrapped record
        setDayP(s, ParadeCalendar.paradeDay(y) + 1)
        val beat = Parade.phoneBeat(s)
        check(beat != null && beat.first == neighbor &&
            beat.second == "parade",
            "parade phone: the morning-after text comes " +
                "from the friend who stood at your spot")
        val line = Parade.paperLine(s,
            Jobs.weekIndex(ParadeCalendar.paradeDay(y)))
        check(line != null &&
            line.contains("South Park Elementary") &&
            line.contains("Mayor's car") &&
            line.contains("watched from") &&
            line.contains("photographed"),
            "parade paper: the edition names the head " +
                "and the tail, your spot and your shutter")
        check(Parade.pageLines(s).any {
            it.contains("Your part: you watched from") } &&
            Parade.pageLines(s).any {
                it.startsWith("1. 🏫 South Park Elementary") },
            "parade page: the Journal carries the derived " +
                "order and your part in it")
    }

    // ---------- the day, MARCHED whole ----------
    run {
        val y = 2027
        val (_, s) = paradeState(14450)
        s.lifeText["crew:members"] = "Pip,Dougie"
        atStreet(s, y, 10 * 60)
        seatAtStreet(s, "Pip")
        seatAtStreet(s, "Dougie")
        val pipBefore = s.friendship["Pip"] ?: 0
        val dougieBefore = s.friendship["Dougie"] ?: 0
        check(Parade.playChoose(s, "march", "") != null &&
            Parade.currentRecord(s)!!.marchEntry == "crew",
            "parade march: you march with your crew")
        check(Parade.playLineup(s) != null,
            "parade march: the lineup lands")
        var guard = 0
        var sawCatch = false
        while (guard++ < 40) {
            when (Parade.nextBeatKind(s)) {
                "pass" -> if (Parade.playPass(s) == null) {
                    break }
                "catch" -> { sawCatch = true; break }
                else -> break
            }
        }
        check(!sawCatch,
            "parade march: marchers catch nothing — the " +
                "throwers throw to the curb, and the wrap " +
                "pays the walkers instead")
        // the crew's standing-with-you drip is ambient
        // (it lands across the day's ticks, parade or
        // no) — the parade's own pay is the delta across
        // the closing beat itself, measured here
        val pipMid = s.friendship["Pip"] ?: 0
        val dougieMid = s.friendship["Dougie"] ?: 0
        check(Parade.nextBeatKind(s) == "mayor" &&
            Parade.playMayor(s) != null,
            "parade march: the Mayor's car closes the " +
                "route for the marchers too")
        val rec = Parade.currentRecord(s)!!
        check(rec.wrapped == "played" &&
            rec.photoId.isNotEmpty() &&
            s.photos.any { p -> p.id == rec.photoId &&
                p.caption.contains("your crew") &&
                p.caption.contains("City Hall steps") },
            "parade march: the shutter catches your entry " +
                "at the City Hall steps — the route's end " +
                "is the marchers' frame")
        check((s.friendship["Pip"] ?: 0) ==
            pipMid + Parade.MARCH_PAY &&
            (s.friendship["Dougie"] ?: 0) ==
                dougieMid + Parade.MARCH_PAY,
            "parade march: the wrap pays the walkers " +
                "+${Parade.MARCH_PAY} each, as posted " +
                "(measured across the closing beat — the " +
                "day's ambient crew drip is not the " +
                "parade's money)")
        val line = Parade.paperLine(s,
            Jobs.weekIndex(ParadeCalendar.paradeDay(y)))
        check(line != null && line.contains("you marched"),
            "parade paper: a marched year names your " +
                "entry in the edition")
    }

    // ---------- marching with nobody: the school walk ----------
    run {
        val y = 2027
        val (_, s) = paradeState(14451)
        atStreet(s, y, 10 * 60)
        val vicBefore = s.friendship["Victoria"] ?: 0
        check(Parade.playChoose(s, "march", "") != null &&
            Parade.currentRecord(s)!!.marchEntry == "school",
            "parade march: crewless, the school's walking " +
                "entry takes you — stated, not improvised")
        Parade.playLineup(s)
        var guard = 0
        while (guard++ < 40) {
            if (Parade.nextBeatKind(s) == "pass") {
                if (Parade.playPass(s) == null) break
            } else break
        }
        check(Parade.playMayor(s) != null &&
            Parade.currentRecord(s)!!.wrapped == "played" &&
            (s.friendship["Victoria"] ?: 0) ==
                vicBefore + Parade.MARCH_PAY,
            "parade march: the free-agent walk wraps " +
                "played, and Principal Victoria notes the " +
                "showing up (+${Parade.MARCH_PAY})")
    }

    // ---------- the candy economy, computed ----------
    run {
        // the maximum possible haul, COMPUTED from the
        // dials and the stand's own price table — never
        // trusted from a comment
        val maxThrows = Parade.THROWERS.size *
            Parade.THROWS_PER
        val maxHaul = minOf(maxThrows, Parade.CANDY_CAP)
        val dearest = Parade.THROWERS.values.maxOf { item ->
            Stand.STOCK.first { it.itemId == item }.shopPrice }
        check(maxThrows == 9 && maxHaul == Parade.CANDY_CAP &&
            maxHaul * dearest == 12,
            "parade economy: nine throws exist in the day, " +
                "pockets cap the gain at six items, and at " +
                "the stand's own prices the richest possible " +
                "haul is worth 12 🪙 once a year — the " +
                "parade can never be a pantry farm (throws " +
                "$maxThrows, haul $maxHaul, dearest $dearest)")
        check(Parade.THROWERS.values.all { item ->
            Stand.STOCK.any { it.itemId == item } },
            "parade economy: every thrown good is a real " +
                "stand stock item with a real price — the " +
                "candy is pantry goods, not tokens")
    }

    // ---------- the Walk closure ----------
    run {
        val y = 2027
        // a real trip whose route passes THROUGH Main
        // Street, found in Walk's own geography
        var through: Triple<String, String, List<String>>? =
            null
        outer@ for (from in LOCATIONS.keys) {
            for (to in LOCATIONS.keys) {
                if (from == to) continue
                val path = Walk.route(from, to)
                val i = path.indexOf("MainStreet")
                if (i > 0 && i < path.size - 1) {
                    through = Triple(from, to, path)
                    break@outer
                }
            }
        }
        check(through != null,
            "walk closure (staging): the town's geography " +
                "has trips that pass through Main Street")
        val (from, to, path) = through!!
        val midIdx = path.indexOf("MainStreet")
        val before = path[midIdx - 1]
        // parade day, live
        val (_, sp) = paradeState(14460)
        setDayP(sp, ParadeCalendar.paradeDay(y))
        check(Parade.streetClosed(sp),
            "walk closure: the street reads closed on a " +
                "live parade day")
        // an ordinary day, same town
        val (_, so) = paradeState(14460)
        setDayP(so, ParadeCalendar.paradeDay(y) + 60)
        check(!Parade.streetClosed(so),
            "walk closure: the street reads open on an " +
                "ordinary day")
        check(Walk.route(from, to) ==
            Walk.route(from, to) &&
            Walk.route(from, to) == path,
            "walk closure: the route itself never moves — " +
                "traffic yields, geography doesn't")
        val baseThrough = Walk.routeMinutes(so, from, to)
        check(Walk.routeMinutes(sp, from, to) ==
            baseThrough + Parade.PASS_DELAY_MIN,
            "walk closure: the picker prices the through-" +
                "trip one tick dearer on parade day " +
                "($baseThrough → ${baseThrough + 15})")
        check(Walk.routeMinutes(sp, from, "MainStreet") ==
            Walk.routeMinutes(so, from, "MainStreet") &&
            Walk.routeMinutes(sp, "MainStreet", to) ==
                Walk.routeMinutes(so, "MainStreet", to),
            "walk closure: trips TO the parade and trips " +
                "OUT of it pay no delay")
        // the charged leg agrees with the picker
        fun legInto(dayState: GameState, dest: String):
            LegOutcome? {
            val me = dayState.agents.values.first {
                it.isPlayer }
            me.location = before
            dayState.walkDest = dest
            return Walk.walkLeg(dayState, Random(7))
        }
        val legParade = legInto(sp, to)
        val legOrdinary = legInto(so, to)
        check(legParade != null && legOrdinary != null &&
            legParade.to == "MainStreet" &&
            !legParade.arrived &&
            legParade.minutes ==
                legOrdinary.minutes + Parade.PASS_DELAY_MIN,
            "walk closure: the leg INTO Main Street mid-" +
                "trip charges the same tick the picker " +
                "quoted (${legOrdinary?.minutes} → " +
                "${legParade?.minutes})")
        val (_, sp2) = paradeState(14460)
        setDayP(sp2, ParadeCalendar.paradeDay(y))
        val (_, so2) = paradeState(14460)
        setDayP(so2, ParadeCalendar.paradeDay(y) + 60)
        val arrParade = legInto(sp2, "MainStreet")
        val arrOrdinary = legInto(so2, "MainStreet")
        check(arrParade != null && arrOrdinary != null &&
            arrParade.arrived && arrOrdinary.arrived &&
            arrParade.minutes == arrOrdinary.minutes,
            "walk closure: ARRIVING at Main Street is " +
                "never delayed — you are going TO the parade")
    }

    // ---------- the rollover: missed & partial ----------
    run {
        val y = 2027
        // a year nobody touched wraps as missed, on the
        // record, in the log, in the paper
        val (_, s) = paradeState(14470)
        setDayP(s, ParadeCalendar.paradeDay(y) + 1)
        Parade.dailyRollover(s)
        val rec = Parade.record(s, y)!!
        check(rec.wrapped == "missed" &&
            s.townLog.any { it.contains("🎺") &&
                it.contains("missed it") } &&
            Parade.paperLine(s, Jobs.weekIndex(
                ParadeCalendar.paradeDay(y)))
                ?.contains("you missed it") == true,
            "parade rollover: an untouched year opens its " +
                "record at the wrap and reads missed — " +
                "the town rolled without you, and every " +
                "surface says so")
        val beat = Parade.phoneBeat(s)
        check(beat == null || beat.first in
            CharacterSystem.CAST,
            "parade rollover: a missed year's text, when " +
                "one lands, comes from the cast (no friend " +
                "at 30+ on a fresh save, so usually none)")
        // a year started but not finished wraps partial
        val (_, s2) = paradeState(14471)
        atStreet(s2, y, 10 * 60)
        Parade.playChoose(s2, "watch", "bank")
        Parade.playLineup(s2)
        setDayP(s2, ParadeCalendar.paradeDay(y) + 1)
        Parade.dailyRollover(s2)
        check(Parade.record(s2, y)!!.wrapped == "partial",
            "parade rollover: a day begun and abandoned " +
                "wraps partial — the record doesn't pretend")
    }

    // ---------- saves: round-trip + legacy ----------
    run {
        val y = 2027
        val (_, s) = paradeState(14480)
        atStreet(s, y, 10 * 60)
        Parade.playChoose(s, "watch", "postoffice")
        Parade.playLineup(s)
        Parade.playPass(s)
        val back = decodeGameState(encodeGameState(s))
        val recB = Parade.record(back, y)
        val recA = Parade.record(s, y)
        check(recB != null && recA != null &&
            recB.mode == "watch" &&
            recB.spot == "postoffice" &&
            recB.step == recA.step && recB.stage == 1,
            "parade saves: a mid-day record round-trips " +
                "the real save path whole")
        // a pre-0.13.0d save has no parade keys at all —
        // it joins the next parade like anyone
        val (_, old) = paradeState(14481)
        check(old.lifeText.keys.none {
            it.startsWith("parade") } &&
            Parade.record(old, y) == null,
            "parade saves: a fresh (pre-parade) save " +
                "carries no parade state")
        atStreet(old, y, 10 * 60)
        check(Parade.playChoose(old, "march", "") != null &&
            Parade.record(old, y)?.mode == "march",
            "parade saves: the old save joins the next " +
                "parade — additive-only, nothing to migrate")
    }

    // ---------- wiring ----------
    run {
        check(gameSrc.contains("\"parade\" -> paradeDialog()") &&
            gameSrc.contains("presentParadeBeat()") &&
            gameSrc.contains("startParadeCatch(") &&
            gameSrc.contains(
                "Parade.lookText(state, me.location)") &&
            viewSrc.contains("drawParadeStand") &&
            viewSrc.contains("Hit(\"fixture\", \"parade\"") &&
            minigameSrc.contains("class ParadeCatchView") &&
            minigameSrc.contains("Parade.CatchSession"),
            "parade wiring: the stand routes to the day, " +
                "the catch launches its played view, the " +
                "street draws the reviewing stand, and Look " +
                "carries the poster")
        check(phoneSrc.contains("const val PARADE") &&
            phoneSrc.contains("Parade.phoneBeat(state)") &&
            Phone.MAX_TEXTS == 220 &&
            paperSrc.contains("Parade.paperLine(state, week)") &&
            journalSrc.contains("Parade.pageLines(state)") &&
            journalSrc.contains("🎺 THE PARADE") &&
            engineSrc.contains(
                "Parade.gatheringBlock(state, a.name, timeMin)") &&
            engineSrc.contains("Parade.dailyRollover(state)") &&
            walkSrc.contains("Parade.streetClosed(state)"),
            "parade wiring: one phone trigger (the budget " +
                "stands at 220), one paper hook, the " +
                "Journal page, the claim, the rollover, " +
                "and Walk's closure read")
        check(talkSrc.contains(
            "Parade.gossipLine(state, npcName)") &&
            !talkSrc.contains("Parade.talkStepFor") &&
            paradeSrc.contains("object ParadeCalendar"),
            "parade wiring: the talk seam is a seam — " +
                "TalkGate keeps its eleven rails, and the " +
                "calendar stands alone in the module")
    }
}


// ============================================================
// v0.13.0e: pen pals — a friend you've never met, in a town
// that doesn't exist anywhere else (Queue #13 item 5). Wren
// Halloway of Pinewood Flats is NOT cast (the parents'
// precedent): a VisitorPersona outside the 98, census-pinned
// from both sides, with her own authored voice and a warmth
// lane that never touches state.friendship. Letters in are
// composed from her banks plus FACT SLOTS — follow-ups on
// facts your own sent letters carried — and replies compose
// in front of you from your real records under three tones,
// the sent text kept verbatim. Silence stretches the
// cadence; three unanswered letters go dormant; the top
// band at May 31 earns the June visit. The paper never
// covers the letters; the phone gets nothing; no rail, no
// agenda claim, and no case machinery anywhere near it.
// ============================================================
private fun sectionV0130e(root: String) {
    println("== v0.13.0e: pen pals ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val penSrc = File(srcDir, "PenPals.kt").readText()
    val phoneSrc = File(srcDir, "Phone.kt").readText()
    val paperSrc = File(srcDir, "Newspaper.kt").readText()
    val talkSrc = File(srcDir, "TalkGate.kt").readText()
    val engineSrc = File(srcDir, "Engine.kt").readText()
    val gameSrc = File(srcDir, "GameActivity.kt").readText()
    val viewSrc = File(srcDir, "GameView.kt").readText()
    val journalSrc = File(srcDir, "JournalActivity.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "v0.13.0e: the manifest carries this build (99 / 0.13.0e)")
    check(readme.contains("### v0.13.0e") &&
        readme.contains("## Status — v0.13.0e"),
        "v0.13.0e: the README carries this build's changelog " +
            "entry and status section")
    val ktCount = srcDir.listFiles { f -> f.extension == "kt" }
        ?.size ?: 0
    check(ktCount == 137 && readme.contains("107 Kotlin files"),
        "v0.13.0e: one new module (PenPals.kt) — the tree " +
            "stands at 107 Kotlin files (found $ktCount)")

    fun palState(seed: Long): GameState {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return s
    }
    fun setDayE(s: GameState, key: String) {
        s.absDay = FairCalendar.absDayOfOrdinal(
            ordinalOfKey(key))
        s.todayKey = key
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
    }
    fun rollE(s: GameState) = PenPals.dailyRollover(s)
    fun arriveE(s: GameState) {
        val due = s.life["palNextDue"] ?: -1
        check(due >= 0, "pen pals fixture: a letter is scheduled")
        setDayE(s, keyFromOrdinal(
            FairCalendar.ordinalOfAbsDay(due)))
        PenPals.dailyRollover(s)
    }
    fun signedState(seed: Long): GameState {
        val s = palState(seed)
        setDayE(s, "20261005")
        check(PenPals.signupOpen(s),
            "pen pals fixture: the box is out on Oct 5")
        check(PenPals.signUp(s) != null,
            "pen pals fixture: the signup lands")
        return s
    }
    fun photoE(id: String, label: String, caption: String,
               vararg figs: String): PhotoRecord = PhotoRecord(
        id = id, dayKey = "20261020", dateLabel = label,
        timeMin = 600, locId = "KidsPark", inside = false,
        weatherId = "clear", appearance = DEFAULT_APPEARANCE,
        figures = listOf(PhotoFigure("New Kid", "player",
            "happy", reaction = "player")) + figs.map {
            PhotoFigure(it, "resident", "happy",
                reaction = "happy") },
        caption = caption)
    // meta records, parsed the archive's own way (fields are
    // \u0001-joined; [0] is i<n>/o<n>, [2] the summary, and
    // for incoming letters [3]/[4] the follow-up provenance)
    fun metaE(s: GameState): List<List<String>> =
        (s.lifeText["palMeta"] ?: "").split("\n")
            .filter { it.isNotBlank() }
            .map { it.split("\u0001") }
    fun fullCountE(s: GameState): Int =
        (1..PenPals.lettersIn(s)).count {
            s.lifeText["palLetter:$it"] != null } +
            (1..PenPals.lettersOut(s)).count {
                s.lifeText["palSent:$it"] != null }

    // ---------- the census wall, both sides ----------
    run {
        check(CharacterSystem.CAST_KIDS.size == 42 &&
            CharacterSystem.CAST_ADULTS.size == 56,
            "pen pals census: the cast still stands at 98 " +
                "(42 kids / 56 adults) — the pal joined nothing")
        check(PenPals.PAL !in CharacterSystem.CAST_KIDS &&
            PenPals.PAL !in CharacterSystem.CAST_ADULTS &&
            PenPals.PAL !in Family.PARENTS,
            "pen pals census: Wren Halloway is in no cast " +
                "set and is not a parent — a persona of her own")
        check(VisitorSystem.personaByName(PenPals.PAL) == null &&
            VisitorSystem.residents().none {
                it.loreName == PenPals.PAL },
            "pen pals census: the lorebook visitor system has " +
                "never heard of her — her persona comes only " +
                "from PenPals, like the parents' comes from Family")
        val p = PenPals.persona(palState(960_001))
        check(p.loreName == PenPals.PAL &&
            p.band == AgeBand.KID && !p.resident &&
            p.spec == PenPals.SPEC && !PenPals.SPEC.tall &&
            PenPals.SPEC.hairStyle == "ponytail" &&
            PenPals.SPEC.freckles,
            "pen pals census: her persona is a kid-band " +
                "visitor wearing her own authored spec — " +
                "rust ponytail, freckles, kid proportions")
        check(FACTIONS.none { f ->
                PenPals.PAL in f.members },
            "pen pals census: no faction claims her either")
    }

    // ---------- her voice: banks, card, denylist ----------
    run {
        val banks = mutableListOf<String>()
        PenPals.GREETINGS.values.forEach { banks += it }
        PenPals.SIGNOFFS.values.forEach { banks += it }
        PenPals.NEWS.forEach { banks += it.first; banks += it.second }
        PenPals.FOLLOWUPS.values.forEach { banks += it }
        banks += PenPals.ASKS
        PenPals.ASK_ANSWERS.values.forEach { banks += it }
        banks += PenPals.QUIET_NOTES
        banks += PenPals.DORMANT_NOTE
        banks += PenPals.PS_BANK
        banks += PenPals.FIRST_LETTER
        banks += PenPals.MAYBE_NEXT_LETTER
        banks += PenPals.THANKS_LETTER
        PenPals.REPLY_OPENERS.values.forEach { banks += it }
        PenPals.REPLY_FACT_LINE.values.forEach { banks += it }
        PenPals.REPLY_NO_FACT.values.forEach { banks += it }
        PenPals.REPLY_CLOSERS.values.forEach { banks += it }
        PenPals.REPLY_PS.values.forEach { banks += it }
        banks += PenPals.VISIT_GREETINGS
        banks += PenPals.VISIT_TALK
        banks += PenPals.VISIT_FACTS
        banks += PenPals.VISIT_DEEP
        banks += PenPals.VISIT_BYES
        banks += PenPals.VISIT_AMBIENT
        banks += PenPals.GOODBYE_LINE
        banks += PenPals.SPEECH_CARD.values
        val low = banks.joinToString("\n").lowercase()
        check(PenPals.DENYLIST.size >= 10 &&
            PenPals.DENYLIST.none { it in low },
            "pen pals voice: every authored surface — banks, " +
                "letters, visit lines, the speech card itself — " +
                "is clean of the franchise/real-place denylist")
        check(PenPals.SPEECH_CARD.keys == setOf("Tics", "Habits",
                "Never", "Deflects") &&
            PenPals.FOLLOWUPS.keys == setOf("photo", "case",
                "stand", "garden", "fair", "carnival", "dance",
                "talent", "parade", "family"),
            "pen pals voice: a mini speech card in the house " +
                "shape, and a follow-up bank for every fact " +
                "kind a reply can carry — no kind rides " +
                "unanswerable")
        check(PenPals.FIRST_LETTER.contains(PenPals.PAL_TOWN) &&
            PenPals.FIRST_LETTER.contains("Pinewood") &&
            !PenPals.FIRST_LETTER.contains("You wrote") &&
            !PenPals.FIRST_LETTER.contains("You said"),
            "pen pals voice: the first letter introduces a " +
                "town that doesn't exist anywhere else and " +
                "claims no fact about you — she knows none yet")
    }

    // ---------- the program: window, pairing, route ----------
    run {
        val s = palState(960_002)
        setDayE(s, "20260930")
        check(!PenPals.signupOpen(s) && PenPals.signUp(s) == null,
            "pen pals program: September is too early — the " +
                "box is a stated October thing")
        setDayE(s, "20261001")
        check(PenPals.signupOpen(s), "pen pals program: the " +
            "window opens October 1")
        rollE(s)
        check(s.events.count {
                it.contains("pen-pal program box") } == 1,
            "pen pals program: the box's opening rides the " +
                "morning ticker, once")
        rollE(s)
        check(s.events.count {
                it.contains("pen-pal program box") } == 1,
            "pen pals program: the note does not repeat itself")
        setDayE(s, "20261021")
        check(PenPals.signupOpen(s), "pen pals program: the " +
            "window's last day is October 21")
        setDayE(s, "20261022")
        check(!PenPals.signupOpen(s) && PenPals.signUp(s) == null,
            "pen pals program: October 22 is a late joiner — " +
                "next year's pairing, stated and enforced")
        setDayE(s, "20261005")
        val text = PenPals.signUp(s)!!
        check(text.contains(PenPals.PAL) &&
            text.contains(PenPals.PAL_TOWN) &&
            text.contains("Post Office") &&
            PenPals.signedYear(s) == 2027 &&
            PenPals.live(s),
            "pen pals program: the pairing names her and her " +
                "town, routes through Dad's Post Office, and " +
                "lands in the 2027 school year")
        check(!PenPals.signupOpen(s) && PenPals.signUp(s) == null,
            "pen pals program: one name per box per year")
        check((s.life["palNextDue"] ?: 0) - s.absDay in
            PenPals.GAP_MIN..(PenPals.GAP_MIN +
                PenPals.GAP_SPAN - 1),
            "pen pals program: the first letter is already " +
                "on the 3–5 day cadence")
        check((0..50).all { n ->
            PenPals.gapDays(s, n) in PenPals.GAP_MIN..
                (PenPals.GAP_MIN + PenPals.GAP_SPAN - 1) },
            "pen pals program: every seeded gap in the run " +
                "of 51 lands inside 3–5 days")
    }

    // ---------- cadence, dormancy, revival ----------
    run {
        val s = signedState(960_003)
        rollE(s)
        check(PenPals.lettersIn(s) == 0,
            "pen pals cadence: no letter before its day")
        arriveE(s)
        check(PenPals.lettersIn(s) == 1 &&
            PenPals.latestLetter(s) == PenPals.FIRST_LETTER &&
            PenPals.unread(s) && PenPals.unanswered(s) == 1 &&
            s.events.any { it.contains("📬") },
            "pen pals cadence: letter one is the introduction, " +
                "unread until the mailbox, announced on the ticker")
        PenPals.markRead(s)
        check(!PenPals.unread(s), "pen pals cadence: reading " +
            "is the mailbox's stamp, and it holds")
        arriveE(s)
        check(PenPals.lettersIn(s) == 2 &&
            PenPals.unanswered(s) == 2,
            "pen pals cadence: a second letter lands over " +
                "the silence — she writes on schedule, not " +
                "on your replies")
        val dueAfter2 = s.life["palNextDue"] ?: 0
        check(dueAfter2 - s.absDay in
            (PenPals.GAP_MIN + PenPals.QUIET_STRETCH)..
            (PenPals.GAP_MIN + PenPals.GAP_SPAN - 1 +
                PenPals.QUIET_STRETCH),
            "pen pals cadence: two unanswered letters stretch " +
                "the next gap by the stated +3 (next due in " +
                "${dueAfter2 - s.absDay})")
        check(PenPals.QUIET_NOTES.any {
                PenPals.latestLetter(s)!!.contains(it) },
            "pen pals cadence: the quiet is noted in her " +
                "letter, kindly and in her voice")
        arriveE(s)
        check(PenPals.lettersIn(s) == 3 &&
            PenPals.isDormant(s) &&
            PenPals.latestLetter(s)!!.contains(
                "stop filling your mailbox"),
            "pen pals dormancy: the third unanswered letter " +
                "carries the dormant note in its own text — " +
                "she says it before the rule bites")
        val inCount = PenPals.lettersIn(s)
        setDayE(s, keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(s.absDay) + 30))
        rollE(s)
        check(PenPals.lettersIn(s) == inCount,
            "pen pals dormancy: thirty days of silence bring " +
                "no fourth letter — the route is closed, not " +
                "the friendship")
        val ptsBefore = PenPals.points(s)
        val sent = PenPals.sendReply(s, PenPals.TONE_EVERYDAY)
        check(sent != null && !PenPals.isDormant(s) &&
            PenPals.unanswered(s) == 0 &&
            PenPals.points(s) - ptsBefore == PenPals.PTS_REVIVAL,
            "pen pals dormancy: one letter reopens the route, " +
                "worth the stated revival point and no more")
        arriveE(s)
        check(PenPals.latestLetter(s)!!.contains("route lives"),
            "pen pals dormancy: her next letter acknowledges " +
                "the revival — the route lives, in her words")
    }

    // ---------- warmth: its own lane, its own bands ----------
    run {
        val s = signedState(960_004)
        val friendshipBefore = s.friendship.toMap()
        var replies = 0
        while (replies < 15) {
            arriveE(s)
            val composed = PenPals.composeReply(s,
                PenPals.TONE_BIG)
            val sent = PenPals.sendReply(s, PenPals.TONE_BIG)
            check(sent == composed.first,
                "pen pals warmth: the letter sent is the " +
                    "letter composed in front of you, verbatim")
            check(s.lifeText["palSent:${replies + 1}"] == sent,
                "pen pals warmth: the freshest sent letter " +
                    "sits in the archive word for word")
            replies++
            if (replies == 5) check(
                PenPals.points(s) == 15 &&
                    PenPals.bandOf(s) == PenPals.BAND_REGULAR_I &&
                    PenPals.bandWord(s) == "a writing-regular",
                "pen pals warmth: five replies make a " +
                    "writing-regular at the stated 15")
        }
        check(PenPals.points(s) == 45 &&
            PenPals.bandOf(s) == PenPals.BAND_FRIEND_I &&
            PenPals.bandWord(s) == "a real friend",
            "pen pals warmth: fifteen replies reach the top " +
                "band at the stated 45 — a real friend")
        check(s.friendship == friendshipBefore &&
            PenPals.PAL !in s.friendship,
            "pen pals warmth: the whole correspondence moved " +
                "her lane and ONLY her lane — the town's " +
                "friendship book never gained her name")
        check(!penSrc.contains("state.friendship["),
            "pen pals warmth: the module's own source never " +
                "writes the friendship map — the lane wall is " +
                "in the code, not just the tests")
        val t = palState(960_005)
        t.life["palPts"] = 14
        check(PenPals.bandOf(t) == PenPals.BAND_STRANGER,
            "pen pals warmth: 14 is still a stranger")
        t.life["palPts"] = 44
        check(PenPals.bandOf(t) == PenPals.BAND_REGULAR_I,
            "pen pals warmth: 44 is a regular, not yet a friend")
    }

    // ---------- facts: provenance, tones, the public shape ----------
    run {
        val s = signedState(960_006)
        s.photos.add(photoE("pp1", "10/20", "the pond at dusk"))
        s.arcRetired = true
        s.life["famArrived"] = 1
        s.lifeText["standLoc"] = "KidsPark"
        s.life["standOpenDay"] = s.absDay
        s.lifeText["gardenBed:0"] =
            "tomato|0|5|5|0|0|0|0|1|0|"
        s.fairs.add(FairRecord(2026, false, "", attended = true))
        val facts = PenPals.factsAvailable(s)
        check(facts.map { it.kind } == listOf("case", "photo",
                "fair", "garden", "stand", "family"),
            "pen pals facts: a lived week offers its facts " +
                "in the stated order — case, photo, fair, " +
                "garden, stand, family (got " +
                "${facts.map { it.kind }})")
        val caseFact = facts.first { it.kind == "case" }
        check(caseFact.text.contains(Mystery.ARC_TITLE) &&
            caseFact.text.contains("closed") &&
            Attic.caseBoxes(s).any {
                caseFact.text.contains(it.title) },
            "pen pals facts: the case fact IS the attic's " +
                "public shape — the Journal title and the " +
                "word closed, sourced from the boxes and " +
                "nowhere else")
        val byTone = PenPals.TONES.map { tone ->
            PenPals.composeReply(s, tone) }
        check(byTone.all { it.second == facts.take(2) },
            "pen pals facts: the facts are IDENTICAL under " +
                "all three tones — the tone colors the frame, " +
                "never the facts")
        check(byTone.map { it.first }.distinct().size == 3 &&
            byTone.all { c -> facts.take(2).all {
                c.first.contains(it.text) } },
            "pen pals facts: three tones, three frames, and " +
                "every composed letter carries both fact " +
                "texts verbatim")
        arriveE(s)   // her first letter lands — now there
        // is something to answer (the module refuses a
        // reply into the void, as the refusal check below
        // pins from the other side)
        val sent = PenPals.sendReply(s, PenPals.TONE_FUNNY)!!
        check(PenPals.factsAvailable(s).none {
                it.kind == "case" || it.kind == "photo" },
            "pen pals facts: a fact that has ridden a letter " +
                "is spent — it is never offered twice")
        check(PenPals.sendReply(s, PenPals.TONE_BIG) == null &&
            !PenPals.canReply(s),
            "pen pals facts: one letter in flight each way — " +
                "with nothing waiting, there is nothing to " +
                "answer, and the module says so by refusal")
        arriveE(s)
        val inRecs = metaE(s).filter { it[0].startsWith("i") }
        val fu = inRecs.last()
        check(fu[3] in setOf("case", "photo") &&
            facts.take(2).any { it.text == fu[4] },
            "pen pals provenance: her follow-up quotes a " +
                "fact from YOUR sent letter — the meta record " +
                "carries it, traceable to the sent archive")
        // every follow-up across a long exchange traces home
        var cycles = 0
        while (cycles < 8) {
            if (PenPals.canReply(s)) PenPals.sendReply(s,
                PenPals.TONES[cycles % 3])
            arriveE(s)
            cycles++
        }
        val sentFactTexts = metaE(s)
            .filter { it[0].startsWith("o") && it.size >= 6 }
            .flatMap { it[5].split("\u0002") }.toSet()
        check(metaE(s).filter { it[0].startsWith("i") }
            .all { it.size < 5 || it[4].isBlank() ||
                it[4] in sentFactTexts },
            "pen pals provenance: across the whole archive, " +
                "every fact Wren ever followed up on appears " +
                "in a letter you actually sent — no exceptions")
    }

    // ---------- the spoiler wall over letters ----------
    run {
        val s = signedState(960_007)
        s.photos.add(photoE("pp9", "10/20", "the pond at dusk"))
        s.arcRetired = true; s.arcBranch = "truth"
        s.arc2Retired = true; s.arc2Branch = "solved"
        s.arc3Retired = true; s.arc3Branch = "bury"
        s.arc4Retired = true; s.arc4Branch = "name"
        s.arc5Retired = true; s.arc5Branch = "believe"
        s.arc6Retired = true; s.arc6Branch = "convicted"
        s.arc7Retired = true; s.arc7Branch = "mended"
        s.arc8Retired = true; s.arc9Retired = true
        s.arc10Retired = true; s.arc10Branch = "hung"
        val titles = listOf(Mystery.ARC_TITLE,
            Mystery2.CASE_TITLE, Mystery3.CASE_TITLE,
            Mystery4.CASE_TITLE, Mystery5.CASE_TITLE,
            Mystery6.CASE_TITLE, Mystery7.CASE_TITLE,
            Mystery8.CASE_TITLE, Mystery9.CASE_TITLE,
            Mystery10.CASE_TITLE)
        val surfaces = mutableListOf<String>()
        var cyc = 0
        while (cyc < 10) {
            arriveE(s)
            surfaces += PenPals.latestLetter(s)!!
            PenPals.sendReply(s, PenPals.TONES[cyc % 3])
                ?.let { surfaces += it }
            cyc++
        }
        check(Attic.caseBoxes(s).size == 10,
            "pen pals spoiler fixture: all ten cases stand " +
                "retired in this save — the wall is load-bearing")
        val stripped = surfaces.joinToString("\n") { line ->
            titles.fold(line) { acc, t -> acc.replace(t, "") }
        }.lowercase()
        val deny = listOf("sleepwalk", "professor chaos",
            "cameo", "strongbox", "commune", "the deed",
            "golden lure", "whittled", "night gardener",
            "confession", "culprit")
        check(deny.none { it in stripped },
            "pen pals spoiler wall: twenty composed letters " +
                "over a ten-case save breathe no word of any " +
                "case's answer — the titles are the public " +
                "shape, and titles are all the letters got")
        val branches = listOf("truth", "solved", "bury",
            "believe", "convicted", "mended", "hung")
        check(branches.none { it in stripped },
            "pen pals spoiler wall: no landing word from " +
                "any retired case survives into the mail")
    }

    // ---------- empty records: the fallback is honest ----------
    run {
        val s = signedState(960_008)
        check(PenPals.factsAvailable(s).isEmpty(),
            "pen pals fallback: a brand-new save offers no " +
                "facts — nothing photographed, planted, " +
                "opened, or closed")
        var cyc = 0
        while (cyc < 4) {
            arriveE(s)
            val letter = PenPals.latestLetter(s)!!
            val rec = metaE(s).last { it[0].startsWith("i") }
            check(rec[4].isBlank(),
                "pen pals fallback: over an empty save, her " +
                    "letter carries NO follow-up — the meta " +
                    "record itself testifies the slot stayed empty")
            if (cyc > 0) check(PenPals.NEWS.any {
                    letter.contains(it.second.take(24)) },
                "pen pals fallback: with nothing of yours to " +
                    "ask about, the letter runs on Pinewood " +
                    "Flats news — her town fills the page")
            val (text, facts) = PenPals.composeReply(s,
                PenPals.TONES[cyc % 3])
            check(facts.isEmpty() && PenPals.REPLY_NO_FACT
                .values.flatten().any { text.contains(it) },
                "pen pals fallback: your reply over an empty " +
                    "week says so in the tone's own no-news " +
                    "line — it does not invent a week for you")
            PenPals.sendReply(s, PenPals.TONES[cyc % 3])
            cyc++
        }
    }

    // ---------- settlement and the visit ----------
    run {
        // below the band: the honest letter
        val s = signedState(960_009)
        s.life["palPts"] = PenPals.BAND_FRIEND - 1
        val inBefore = PenPals.lettersIn(s)
        setDayE(s, "20270601")
        rollE(s)
        check(PenPals.lettersIn(s) == inBefore + 1 &&
            PenPals.latestLetter(s) ==
                PenPals.MAYBE_NEXT_LETTER &&
            (s.life["palVisitYear"] ?: 0) == 0,
            "pen pals visit: one point below the band, the " +
                "year ends with the maybe-next-summer letter " +
                "and no visit is stamped")
        rollE(s)
        check(PenPals.lettersIn(s) == inBefore + 1,
            "pen pals visit: the settlement fires once")

        // at the band: she comes
        val v = signedState(960_010)
        v.life["palPts"] = PenPals.BAND_FRIEND
        setDayE(v, "20270601")
        rollE(v)
        check((v.life["palVisitYear"] ?: 0) == 2027 &&
            PenPals.visitStart(v) == FairCalendar
                .absDayOfOrdinal(ordinalOfKey("20270610")),
            "pen pals visit: the top band at May 31 stamps " +
                "the visit — June 10, four days, derived from " +
                "the calendar and nothing else")
        setDayE(v, "20270609")
        check(!PenPals.visitLive(v) &&
            PenPals.presentAt(v, YOUR_HOUSE, true).isEmpty(),
            "pen pals visit: June 9 she is still a letter")
        setDayE(v, "20270610")
        check(PenPals.visitLive(v), "pen pals visit: June " +
            "10, she is here")
        v.timeMin = 9 * 60
        check(PenPals.blockAt(v, v.timeMin) ==
            (YOUR_HOUSE to true) &&
            PenPals.presentAt(v, YOUR_HOUSE, true)
                .singleOrNull()?.persona?.loreName ==
                PenPals.PAL &&
            PenPals.presentAt(v, YOUR_HOUSE, false).isEmpty() &&
            PenPals.presentAt(v, "KidsPark", false).isEmpty(),
            "pen pals visit: mornings she is your house " +
                "guest, indoors — present in the one room " +
                "the block names, absent everywhere else")
        v.timeMin = 13 * 60
        check(PenPals.blockAt(v, v.timeMin) ==
            ("KidsPark" to false) &&
            PenPals.presentAt(v, "KidsPark", false).size == 1 &&
            PenPals.presentAt(v, YOUR_HOUSE, true).isEmpty(),
            "pen pals visit: middays she is at the park, " +
                "seeing the town from your letters")
        v.timeMin = 18 * 60
        check(PenPals.blockAt(v, v.timeMin) ==
            (YOUR_HOUSE to true),
            "pen pals visit: evenings belong to the house again")
        v.timeMin = 23 * 60
        check(PenPals.blockAt(v, v.timeMin) == null &&
            PenPals.presentAt(v, YOUR_HOUSE, true).isEmpty(),
            "pen pals visit: at night she is offstage — " +
                "guests sleep")
        val pureBefore = encodeGameState(v)
        PenPals.presentAt(v, YOUR_HOUSE, true)
        PenPals.blockAt(v, 600); PenPals.pageLines(v)
        check(encodeGameState(v) == pureBefore,
            "pen pals visit: presence and the page are pure " +
                "reads — rendering her day writes nothing")
        setDayE(v, "20270611"); v.timeMin = 10 * 60
        val ptsV = PenPals.points(v)
        PenPals.noteTalk(v); PenPals.noteTalk(v)
        check(PenPals.points(v) - ptsV ==
            PenPals.TALK_PTS_PER_DAY,
            "pen pals visit: the day's first talk pays its " +
                "one point; the second pays nothing")
        setDayE(v, "20270613"); v.timeMin = 10 * 60
        check(PenPals.isLastVisitDay(v) &&
            PenPals.goodbyeDue(v) &&
            PenPals.greeting(v) == PenPals.GOODBYE_LINE,
            "pen pals visit: the last day's first hello IS " +
                "the goodbye beat")
        PenPals.noteTalk(v)
        check(!PenPals.goodbyeDue(v) &&
            PenPals.greeting(v) != PenPals.GOODBYE_LINE,
            "pen pals visit: a goodbye said is a goodbye " +
                "kept — it does not repeat")
        setDayE(v, "20270614")
        check(!PenPals.visitLive(v), "pen pals visit: " +
            "June 14, the guest room is a guest room again")
        val inV = PenPals.lettersIn(v)
        rollE(v)
        check(PenPals.lettersIn(v) == inV + 1 &&
            PenPals.latestLetter(v) == PenPals.THANKS_LETTER,
            "pen pals visit: the morning after, her " +
                "thank-you letter is in the box")
        rollE(v)
        check(PenPals.lettersIn(v) == inV + 1,
            "pen pals visit: the thank-you also fires once")
        // the page keeps the visit — and the photo question
        // is answered by the album itself
        check(PenPals.pageLines(v).any {
                it.contains("No photo caught her") },
            "pen pals visit: with no photo of her in the " +
                "album, the page says the camera missed her")
        v.photos.add(photoE("pv1", "6/12", "a guest",
            PenPals.PAL))
        check(PenPals.pageLines(v).any {
                it.contains("album keeps her") },
            "pen pals visit: one album photo with her in " +
                "frame and the page's record flips — derived " +
                "from the photo record, not a stamp")
    }

    // ---------- the page: caps, folds, honest states ----------
    run {
        val s = palState(960_011)
        val pre = PenPals.pageLines(s)
        check(pre.first().contains("Pen-Pal Program") &&
            pre.any { it.contains("October") } &&
            pre.any { it.contains("doesn't cover") } &&
            pre.any { it.contains("phone stays out") },
            "pen pals page: before any pairing, the page " +
                "explains the program, its window, and its " +
                "privacy — the paper doesn't cover the " +
                "letters and the phone stays out, stated")
        val w = signedState(960_012)
        var replies = 0
        var lastSent = ""
        while (replies < 15) {
            arriveE(w)
            lastSent = PenPals.sendReply(w,
                PenPals.TONES[replies % 3])!!
            replies++
        }
        check(metaE(w).size == 30 &&
            PenPals.lettersIn(w) == 15 &&
            PenPals.lettersOut(w) == 15,
            "pen pals page: the archive's meta keeps all " +
                "thirty letters of a full correspondence")
        check(fullCountE(w) in 1..PenPals.KEEP_FULL &&
            w.lifeText["palSent:15"] == lastSent,
            "pen pals page: at most ${PenPals.KEEP_FULL} " +
                "letters ride whole — and the newest is " +
                "among them, verbatim")
        check(PenPals.foldedLines(w).isNotEmpty() &&
            PenPals.foldedLines(w).size <= PenPals.FOLDED_CAP &&
            PenPals.foldedLines(w).all {
                it.first().isDigit() && it.contains(" — ") },
            "pen pals page: the elders folded to dated " +
                "one-liners from their own summaries, capped " +
                "at ${PenPals.FOLDED_CAP}")
        val page = PenPals.pageLines(w)
        check(page.first().contains(PenPals.PAL) &&
            page.any { it.contains("a real friend") } &&
            page.any { it.contains("✉ 10/") ||
                it.contains("✉ ") },
            "pen pals page: the standing rides the page in " +
                "her band's own words, over the folded lines")
        val back = decodeGameState(encodeGameState(w))
        check(PenPals.pageLines(back) == page &&
            PenPals.points(back) == PenPals.points(w),
            "pen pals page: the correspondence survives the " +
                "save round trip byte-for-byte — additive " +
                "keys only, nothing lost in the fold")
    }

    // ---------- wiring and the stated absences ----------
    run {
        check(engineSrc.contains("PenPals.dailyRollover(state)") &&
            journalSrc.contains("PenPals.pageLines(state)") &&
            journalSrc.contains("📬 PEN PALS") &&
            gameSrc.contains("\"mailbox\" -> mailboxDialog()") &&
            gameSrc.contains("PenPals.signUp(state)") &&
            gameSrc.contains("PenPals.presentAt(state, " +
                "me.location") &&
            gameSrc.contains("openPalSheet") &&
            viewSrc.contains("Hit(\"fixture\", \"mailbox\""),
            "pen pals wiring: the rollover hook, the " +
                "Journal page, the mailbox fixture and its " +
                "dialog, the board signup, the guest presence " +
                "and her own talk sheet are all wired")
        check(!phoneSrc.contains("PenPals") &&
            !paperSrc.contains("PenPals") &&
            !talkSrc.contains("PenPals") &&
            !penSrc.contains("gatheringBlock") &&
            !penSrc.contains("Mystery"),
            "pen pals absences, pinned: the phone never " +
                "hears of her, the paper never covers the " +
                "letters, TalkGate keeps its eleven rails " +
                "untouched, the visit claims no agenda seat, " +
                "and NO mystery machinery grew on the " +
                "correspondence")
    }
}


/** v0.13.0f section, extracted like the others (64 KB rule):
 *  mystery #11 — the voice case. */
private fun sectionV0130f(root: String) {
    println("== v0.13.0f: mystery #11 — signed in another's voice ==")
    val eng11 = Engine(1306)

    // ---------- the chapter defs ----------
    val ch11 = Mystery11.CHAPTERS11
    check(ch11.size == 4 && ch11.map { it.id }.toSet().size == 4,
        "voice: the case is four chapters, uniquely id'd")
    check(ch11[3].id == Mystery11.FINALE11_ID,
        "voice: the fourth chapter is the finale — the Open Letters, at City Hall")
    check(ch11.all { it.theme.icon.isNotBlank() &&
        it.theme.header.isNotBlank() && it.causers.isNotEmpty() },
        "voice: every chapter carries its theme and its credited causers")
    check(ch11.all { d -> d.stages.size == 4 && d.episodeTitles.size == 2 &&
        d.coldOpen.size == 2 && d.coldOpen.all { it.text.isNotBlank() } },
        "voice: every chapter carries the full episode kit")
    check(ch11.none { d -> SHENANIGANS.any { it.id == d.id } },
        "voice: no chapter sits in the random event pool")
    check(ch11.all { Mystery11.CHAPTER11_BY_ID[it.id] == it &&
        SHENANIGAN_BY_ID[it.id] == it },
        "voice: every chapter resolves by id, in the case and in the game")
    check(ch11[0].stages.any { it.clusterLoc == "Elementary" } &&
        ch11[1].stages.any { it.clusterLoc == "Bijou" } &&
        ch11[1].stages.any { it.clusterLoc == "KennysHouse" } &&
        ch11[2].stages.any { it.clusterLoc == "CityHall" } &&
        ch11[3].stages.take(3).all { it.clusterLoc == "CityHall" } &&
        ch11[3].stages[3].clusterLoc == null,
        "voice: the chapters surface the letters, tour the dictation households and the stage, open the study, and come to the hall — whose last stage walks everybody home")
    val finDef11 = Mystery11.CHAPTER11_BY_ID[Mystery11.FINALE11_ID]!!
    check(finDef11.causers.containsAll(listOf("McDaniels", "Mackey")),
        "voice: the Open Letters are chaired by the mayor and stood by the counselor whose name was borrowed")

    // ---------- the letters (the board's rows) ----------
    val letters11 = Mystery11.LETTERS11
    check(letters11.size == 6 && Mystery11.LETTER11_BY_ID.size == 6 &&
        letters11.map { it.index } == listOf(0, 1, 2, 3, 4, 5),
        "voice: six letters, declared in the order they surfaced")
    check(letters11.all { it.place in LOCATIONS && it.keeper.isNotBlank() &&
        it.claimLabel.isNotBlank() && it.text.isNotBlank() &&
        speechRulesFor(it.signer) != null },
        "voice: every letter surfaced in a real place, is kept by a named hand, and claims a signer with a voice card in the town's own record")
    check(letters11.map { it.truth } ==
        listOf("in", "off", "borrowed", "borrowed", "off", "off"),
        "voice: the six letters settle three ways — one the signer's own, three strangers', two studied")
    check(letters11.all { l ->
        val proof = Mystery11.CLUE11_BY_ID[l.proofBy]
        proof != null && proof.site == l.index && l.callPrice == 2 &&
            l.truth in Mystery11.CALL_KEYS },
        "voice: every letter is settled by exactly one piece tagged to itself, at the standing price")
    check(letters11.map { it.proofBy }.toSet().size == 6,
        "voice: no two letters share a settling piece")
    check(letters11[0].minChapter == 1 && letters11[1].minChapter == 1 &&
        letters11[4].minChapter == 1 && letters11[2].minChapter == 2 &&
        letters11[3].minChapter == 2 && letters11[5].minChapter == 2,
        "voice: the thank-you, the warning and the apology open in the fair-copies week; the note, the ranking and the long letter wait for the study")

    // ---------- the voice profiles ----------
    val profiles11 = Mystery11.PROFILES11
    check(profiles11.size == 6 &&
        profiles11.map { it.signer }.toSet() ==
            letters11.map { it.signer }.toSet() &&
        profiles11.all { p -> p.signer in AGENT_PROFILES &&
            speechRulesFor(p.signer) != null },
        "voice: every claimed signer carries exactly one structured profile, drawn against a real cast voice card")
    check(profiles11.all { p ->
        p.markers.size >= 2 && p.must.all { it in p.markers } &&
            p.nevers.isNotEmpty() && p.tells.isNotEmpty() &&
            (p.markers + p.nevers + p.tells).let {
                it.size == it.toSet().size } },
        "voice: every profile's lists are pairwise disjoint — a phrase is a marker, a never, or a tell, never two — and its load-bearing marks are among its markers")

    // ---------- THE SCAN (derived, never stored) ----------
    check(letters11.map { Mystery11.signature11(it) } ==
        letters11.map { it.truth },
        "voice: every letter scans as the shape its evidence settles — the ledger's columns and the case's truth agree, letter by letter")
    check(letters11.map { Mystery11.findings11(it).markersHit.size } ==
        listOf(4, 0, 2, 3, 1, 0) &&
        letters11.map { Mystery11.findings11(it).neversHit.size } ==
        listOf(0, 2, 1, 0, 4, 3) &&
        letters11.map { Mystery11.findings11(it).tellsHit.size } ==
        listOf(0, 0, 2, 3, 0, 0),
        "voice: the derived counts — the thank-you is all surface and no sin; the warning and the long letter have no surface at all; the apology's one marker drowns in its nevers; the studied pair carry their markers AND their tells")
    check(letters11.map { Mystery11.hasRouting11(it) } ==
        listOf(false, false, true, true, false, false),
        "voice: the routing phrase — office furniture, derived from the texts alone — surfaces in exactly two letters, the studied pair")

    // ---------- distinguishability, both directions, on fabricated letters ----------
    // The three-reading shape is the case's signature: these
    // fabrications prove OFF and BORROWED (and IN) are told
    // apart by the counts alone, in both directions, on
    // every profile — markers alone move a letter off<->in,
    // a tell alone moves it in<->borrowed, and a never with
    // no tell lands it in no clean shape at all.
    val neutralText11 = "the meeting is moved to thursday. " +
        "bring a chair. the hall will be open at six."
    var distinguishOk11 = true
    for (l in letters11) {
        val p = Mystery11.PROFILE11_BY_SIGNER[l.signer]!!
        val markersText = p.markers.joinToString(" ")
        if (Mystery11.signature11(l.copy(text = markersText)) != "in")
            distinguishOk11 = false
        if (Mystery11.signature11(l.copy(
                text = markersText + " " + p.tells[0])) != "borrowed")
            distinguishOk11 = false
        if (Mystery11.signature11(l.copy(text = neutralText11)) != "off")
            distinguishOk11 = false
        if (Mystery11.signature11(l.copy(
                text = markersText + " " + p.nevers[0])) != "mixed")
            distinguishOk11 = false
    }
    check(distinguishOk11,
        "voice: fabricated letters flip shapes on the counts alone, both directions, on all six profiles — markers-only reads IN, markers+tell reads BORROWED, no-surface reads OFF, markers+never-without-tell reads MIXED (no clean shape)")

    // ---------- the evidence registry ----------
    val clues11 = Mystery11.CLUES11
    check(clues11.size == 12 && Mystery11.CLUE11_IDS.size == 12,
        "voice: the evidence is twelve pieces")
    check(clues11.count { it.kind == Mystery11.Kind11.WITNESS } == 5 &&
        clues11.count { it.kind == Mystery11.Kind11.LOOK } == 5 &&
        clues11.count { it.kind == Mystery11.Kind11.PARTICIPATION } == 2,
        "voice: the verbs run 5 witness / 5 look / 2 participation")
    check((0..5).all { idx -> clues11.count { it.site == idx } == 2 },
        "voice: two pieces are tagged to every letter")
    check(clues11.all { c -> c.minChapter in 0..3 &&
        c.unlockChapter in c.minChapter..3 &&
        when (c.kind) {
            Mystery11.Kind11.WITNESS ->
                c.npc != null && c.npc in AGENT_PROFILES &&
                    !c.spoken.isNullOrBlank()
            Mystery11.Kind11.LOOK ->
                c.locId != null && c.locId in LOCATIONS &&
                    !c.foundText.isNullOrBlank()
            Mystery11.Kind11.PARTICIPATION ->
                c.chapterDefId != null &&
                    c.chapterDefId in Mystery11.CHAPTER11_BY_ID
        } },
        "voice: every piece names a real witness, place, or chapter")
    val locked11 = clues11.filter { it.unlockChapter > it.minChapter }
    check(locked11.map { it.id }.toSet() ==
        setOf("worksheet_form", "debate_draft") &&
        locked11.all { it.inertDetail != it.detail && it.inertDetail.isNotBlank() },
        "voice: exactly two pieces are context-locked, each with an honest inert face")
    check(Mystery11.CLUE11_BY_ID["worksheet_form"]!!.unlockChapter == 2 &&
        letters11[2].proofBy == "worksheet_form" &&
        Mystery11.CLUE11_BY_ID["debate_draft"]!!.unlockChapter == 3 &&
        letters11[3].proofBy == "debate_draft",
        "voice: THE STING — both load-bearing proofs are the locked pieces: the form reads only beside the study, the folder only beside the Open Letters: the two letters that matter most can only be proven late")

    // ---------- independent recomputation (the suite's own math) ----------
    fun recompFindings11(l: Mystery11.Letter11): Mystery11.Findings11 {
        val p = Mystery11.PROFILE11_BY_SIGNER[l.signer]!!
        val t = l.text.lowercase()
        return Mystery11.Findings11(
            p.markers.filter { it in t }, p.must.filter { it in t },
            p.must.filter { it !in t }, p.nevers.filter { it in t },
            p.tells.filter { it in t })
    }
    check(letters11.all { recompFindings11(it) == Mystery11.findings11(it) },
        "voice: the suite's own scan of every letter's text against its profile reproduces the module's findings exactly")
    fun recompVerdict11(held: Set<String>,
                        calls: Map<String, String>,
                        l: Mystery11.Letter11): String {
        val c = calls[l.id] ?: return "OPEN"
        // the sweep runs at chapter 4 (finale begun), where
        // every piece in hand is live by construction
        if (l.proofBy !in held) return "COMMITTED"
        return if (c == l.truth) "PROVEN" else "REFUTED"
    }
    var sweepOk11 = true
    for (mask in 0 until (1 shl clues11.size)) {
        val s = eng11.newState()
        s.arc11Chapter = 4
        clues11.forEachIndexed { i, c ->
            if (mask shr i and 1 == 1) s.mystery11Clues.add(c.id)
        }
        val held = s.mystery11Clues.toSet()
        for (scheme in 0..1) {
            val calls = mutableMapOf<String, String>()
            for (letter in letters11) {
                val code = if (scheme == 0)
                    (if (letter.index % 2 == 0) letter.truth else "in")
                else "borrowed"
                calls[letter.id] = code
            }
            if (scheme == 1) calls.clear()
