    // the phone: six fat solo threads, both parents,
    // the three group rooms — 196 texts, inside the cap
    var seq = 0
    fun addTexts12(thread: String, senderOf: (Int) -> String, count: Int) {
        repeat(count) { k ->
            seq++
            vet.phoneTexts.add(PhoneText(
                id = "vet12-t$seq", thread = thread,
                sender = senderOf(k),
                trigger = if (thread.startsWith("group:"))
                    Phone.GROUP else Phone.HELLO,
                absDay = 699, dayKey = "20280615",
                text = "A maximally long town text about absolutely everything " +
                    "that happened today, in complete detail, with opinions ($seq)".padEnd(280, '·'),
                read = k % 3 != 0))
        }
    }
