        addTexts12(tName, { k -> if (k % 7 == 3) "you" else tName },
            Phone.MAX_PER_THREAD)
    addTexts12("Mom", { "Mom" }, Phone.MAX_PER_THREAD)
    addTexts12("Dad", { "Dad" }, Phone.MAX_PER_THREAD)
    addTexts12(GroupChats.CREW_ID, { "Stan" }, 12)
    addTexts12(GroupChats.FAMILY_ID, { "Mom" }, 12)
    addTexts12(GroupChats.PLAY_ID, { "Victoria" }, 12)
    for (kind in listOf(Phone.FEAT, Phone.PHOTO, Phone.ERRAND, Phone.PULL))
        repeat(6) { vet.phoneNotes.add("699|$kind|Stan|") }
    vet.phoneMeta["seq"] = seq
    vet.phoneMeta["lastRoll"] = 699
    vet.phoneMeta["replies"] = 3
    for (def in Finales.DEFS) {
        vet.lifeText["finMark:${def.id}"] = def.choices[0].markText
