    vet.lifeText["danceRec:2028"] = danceRecRaw!!
    // pen pals: a real correspondence driven in a
    // scratch town — signed in October, answered
    // faithfully until the archive folds — then
    // transplanted by its own pal* keys
    val engPal = Engine(1311)
    val scP = engPal.newState()
    engPal.createPlayer(scP, "Veteran", DEFAULT_APPEARANCE)
    setDayG(scP, absOfKeyG("20261001"))
    PenPals.signUp(scP)
    var palGuard = 0
    while (palGuard++ < 300 &&
        !(PenPals.lettersIn(scP) >= 20 &&
            (scP.lifeText["palFolded"] ?: "").isNotBlank())) {
        engPal.onNewDay(scP)
        if (PenPals.canReply(scP))
            PenPals.sendReply(scP,
                listOf(PenPals.TONE_BIG, PenPals.TONE_EVERYDAY,
                    PenPals.TONE_FUNNY)[PenPals.lettersOut(scP) % 3])
    }
    check(PenPals.lettersIn(scP) >= 20 &&
        (scP.lifeText["palFolded"] ?: "").isNotBlank() &&
        PenPals.bandOf(scP) == PenPals.BAND_FRIEND_I,
        "veteran XII: (staging) the scratch " +
            "correspondence ran its course — " +
            "${PenPals.lettersIn(scP)} letters in, the " +
            "archive folding past sixteen whole, the " +
            "warmth at the top band")
    for (k in scP.life.keys.filter { it.startsWith("pal") })
        vet.life[k] = scP.life[k]!!
    for (k in scP.lifeText.keys.filter { it.startsWith("pal") })
        vet.lifeText[k] = scP.lifeText[k]!!
    // the paper's archive, at its caps
    vet.lifeText["paperSkyLog"] =
        (0 until Newspaper.SKY_LOG_CAP).joinToString(";") { i ->
            "${686 + i}:sunny:${SkyState.NONE}" }
    vet.lifeText["paperHeadlines"] =
        (0 until Newspaper.HEADLINE_CAP).joinToString(";") { i ->
            "${50 + i}|Archived headline number $i from the " +
                "veteran's long subscription" }
    val edV = Newspaper.composeEdition(vet,
        Jobs.weekIndex(vet.arc11RetiredDay))
    vet.lifeText["paperLatest"] = edV.lines.joinToString("\n")
    vet.life["paperWeek"] = edV.week
    vet.life["paperLastWeek"] = edV.week
    check(edV.headline == "THE CASE CLOSES",
        "veteran XII: (staging) the veteran's latest " +
            "edition headlines a case closing — the " +
            "eleventh case's stamp drives the ladder's " +
            "top tier like any case's")
    // the attic at this high-water
    check(!Attic.overflowEmpty(vet) &&
        Attic.overflowCollectibles(vet).isNotEmpty() &&
        Attic.overflowCups(vet) > 0,
        "veteran XII: (staging) the attic's overflow " +
            "shelf is loaded — collectibles past the " +
            "shelf's twelve slots and feat cups past its six")
    check(Attic.caseBoxes(vet).size == Attic.CASE_TOTAL,
        "veteran XII: (staging) twelve case boxes " +
            "stand in the attic — one per closed case, " +
            "public shape only")
    val vetOuttakes = Attic.outtakes(vet)
    check(vetOuttakes.any { !it.fromPrint &&
        it.record.id == "vet12fam" } &&
        vetOuttakes.any { it.fromPrint &&
            it.record.id == "vet12famgone" },
        "veteran XII: (staging) the outtakes hold the " +
            "framed photo's elder sibling from the album " +
            "and one family photo only a darkroom print " +
            "still holds")
    val lifeSizeV = vet.life.size
    val lifeTextSizeV = vet.lifeText.size

    // ---- measure, pin, round-trip ----
    val vetJson = Json.stringify(encodeGameState(vet))
    println("veteran XII game_state: ${vetJson.length} chars serialized")
    check(vetJson.length < 640 * 1024,
        "veteran XII: the saturated save (Queue #13 " +
            "included) stays under the 640K ceiling — " +
            "655,360 chars — (got ${vetJson.length})")
    check(vetJson.length > 577_752,
        "veteran XII: today's full state outgrows " +
            "veteran XI's 577,752 — the growth is Queue " +
            "#13's own records, each one capped (got " +
            "${vetJson.length})")
    @Suppress("UNCHECKED_CAST")
    val vetBack = decodeGameState(
        Json.parse(vetJson) as Map<String, Any?>)
    check(vetBack.errands.size == Errands.STATE_CAP &&
        vetBack.photos.size == 63 && StoryArcs.allDone(vetBack) &&
        vetBack.busPass && vetBack.walkTrips == 900 &&
        vetBack.arcRetired && vetBack.arc2Retired &&
        vetBack.arc3Retired && vetBack.arc4Retired &&
        vetBack.arc5Retired && vetBack.arc6Retired &&
        vetBack.arc7Retired && vetBack.arc8Retired,
        "veteran XII: the veteran body round-trips " +
            "whole — eight cases closed beneath the " +
            "ninth, tenth and eleventh")
    check(vetBack.arc11Retired &&
        vetBack.arc11Branch == "voiced" &&
        vetBack.mystery11Clues.size == Mystery11.CLUES11.size &&
        vetBack.arc11Calls.size == Mystery11.LETTERS11.size &&
        vetBack.arc11Posted,
        "veteran XII: the eleventh case round-trips " +
            "closed — full evidence file, every letter " +
            "read, the correction cards posted")
    check(Crew.members(vetBack) ==
        listOf("Stan", "Kyle", "Wendy", "Craig") &&
        Sleepovers.nights(vetBack).size ==
            Sleepovers.HISTORY_CAP &&
        Newspaper.headlineHistory(vetBack).size ==
            Newspaper.HEADLINE_CAP &&
        Newspaper.skyLog(vetBack).size ==
            Newspaper.SKY_LOG_CAP &&
        vetBack.yearbooks.size == 5 &&
        vetBack.fairs.size == 2 &&
        vetBack.prints.size == Darkroom.TOTAL_CAP,
        "veteran XII: the capped records round-trip " +
            "at their caps — eight sleepovers, the " +
            "paper's archives full, five yearbooks, " +
            "two fairs, the print box at its total " +
            "cap, the crew whole")
    check(Carnival.recordFor(vetBack, 2027)?.wrapped == true &&
        vetBack.phoneTexts.size == 196 &&
        PenPals.lettersIn(vetBack) == PenPals.lettersIn(scP) &&
        PenPals.lettersOut(vetBack) == PenPals.lettersOut(scP) &&
        PenPals.points(vetBack) >= PenPals.BAND_FRIEND,
        "veteran XII: the carnival, the 196-text " +
            "inbox and the whole pen-pal archive — " +
            "${PenPals.lettersIn(vetBack)} letters in, " +
            "${PenPals.lettersOut(vetBack)} out, warmth " +
            "at the top band — survive the round-trip")
    check(Dance.record(vetBack, 2028)?.night == "missed" &&
        Talent.record(vetBack, 2028)?.night == "played" &&
        Talent.record(vetBack, 2028)?.winner?.isNotEmpty() == true &&
        Parade.record(vetBack, 2028)?.wrapped == "played" &&
        Parade.record(vetBack, 2028)?.mode == "march",
        "veteran XII: Queue #13's gathering records " +
            "round-trip in their modules' own formats — " +
            "the missed dance, the played talent night " +
            "with its winner, the marched parade")
    check(vetBack.life.size == lifeSizeV &&
        vetBack.lifeText.size == lifeTextSizeV &&
        (vetBack.life["famChoreDoneBy:Mom"] ?: 0) == 27 &&
        (vetBack.life["famChoreDoneBy:Dad"] ?: 0) == 19 &&
        (vetBack.life["shopGoodsSpent"] ?: 0) == 5,
        "veteran XII: the life and lifeText maps come " +
            "through at exactly their staged sizes — " +
            "the family's chore counters and the " +
            "counters' books among them, nothing shed, " +
            "nothing invented")
    check(Attic.caseBoxes(vetBack).size ==
        Attic.CASE_TOTAL &&
        !Attic.overflowEmpty(vetBack) &&
        Attic.outtakes(vetBack).size ==
            vetOuttakes.size &&
        Attic.pageLines(vetBack) ==
            Attic.pageLines(vet),
        "veteran XII: the attic reads the round-tripped " +
            "save whole — eleven boxes, a loaded " +
            "overflow shelf, the outtakes intact, the " +
            "page byte-identical, because it stores nothing")
}
}

// ================= v0.14.0a: the reflections pass =================
/** Queue #14 item 1: the two longest-standing visual gaps
 *  close — rendering only, derivation untouched. (1) The
 *  Your House mirror shows the night look: while a
 *  sleepover night is live, Sleepwear.mirrorCode returns
 *  your pajama code — the shutter's own player branch —
 *  and GameView's mirror glass draws it through KidArt's
 *  sleep pass; outside a live night the code is empty
 *  and the glass shows the day look. (2) Your hero
 *  costume renders in street POV: while you stand a
 *  patrol spot in costume, Heroes.streetCostumeCode
 *  returns your costume code — figureCode's player
 *  branch read live — and GameView's figure pass draws
 *  you through KidArt's hero pass; off patrol the code
 *  is empty and the street stays first-person. Both
 *  readers are pure: deciding a render writes nothing. */
private fun sectionV0140a(root: String) {
println("== v0.14.0a: the reflections pass — Queue #14 item 1 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.14.0a"),
        "reflections: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 103 / 0.14.0b")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("108 Kotlin files"),
        "reflections: no new module — two pure readers in " +
            "Sleepwear/Heroes and two drawing calls in GameView; " +
            "the tree stays at 108 Kotlin files (counted $ktCount)")
}

    // ---------- helpers ----------
    fun setDayR(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun slpRState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        var d = 0
        while (!Sleepovers.isSleepoverDay(d)) d++
        setDayR(s, d)
        return e to s
    }
    /** Stage a live night directly (the save format is the
     *  contract): plan standing, everyone in the room at
     *  your house, the evening open. */
    fun stageNightR(s: GameState, guests: List<String>,
                    hour: Int = 19) {
        s.life["slpDay"] = s.absDay
        s.lifeText["slpGuests"] = guests.joinToString(",")
        for (g in guests) {
            val a = s.agents[g] ?: continue
            a.location = YOUR_HOUSE; a.asleep = false
        }
        val me = s.agents.values.first { it.isPlayer }
        me.location = YOUR_HOUSE; me.asleep = false
        s.timeMin = hour * 60
    }
    fun patrolDayR(from: Int): Int {
        var d = from
        while (!Heroes.isPatrolNight(d)) d++
        return d
    }
    fun heroRState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = patrolDayR(s.absDay)
        Heroes.createHero(s, "The Porchlight", "nightsight")
        e.player(s).location = "KidsPark"
        s.timeMin = 20 * 60
        return e to s
    }

    // ---------- the mirror: agreement with the shutter ----------
    run {
        val guests = listOf("Stan", "Kyle")
        val (_, s) = slpRState(940_001)
        stageNightR(s, guests)
        val mirror = Sleepwear.mirrorCode(s)
        check(mirror.isNotEmpty() &&
            mirror == Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "reflections: on a live sleepover night the mirror's " +
                "code is your own pajama derivation — your palette, " +
                "softened, the nightcap read off your day hat")
        val rec = Photos.compose(s, guests, emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        val meFig = rec.figures.firstOrNull { it.kind == "player" }
        check(meFig != null && meFig.sleep == mirror,
            "reflections: THE AGREEMENT — the mirror's code " +
                "equals the code the shutter froze onto your " +
                "figure in a frame composed at the house on the " +
                "same night, so the glass, the album, the street " +
                "re-render and the darkroom agree figure-for-figure")
        check(guests.all { g ->
                rec.figures.firstOrNull { it.name == g }?.sleep ==
                    Sleepwear.codeFor(g) },
            "reflections: the same frame freezes the planned " +
                "guests' own codes — the mirror's moment is the " +
                "frame's moment, guest set included")
        s.timeMin = 23 * 60
        check(Sleepwear.mirrorCode(s) == mirror,
            "reflections: late the same night the glass still " +
                "reads the shutter's moment, not a narrower one")
    }

    // ---------- the mirror: the day look on every other terms ----------
    run {
        val guests = listOf("Stan", "Kyle")
        val (_, s1) = slpRState(940_002)
        stageNightR(s1, guests, hour = 12)
        check(Sleepwear.mirrorCode(s1) == "",
            "reflections: at noon on a planned day the mirror " +
                "shows the day look — the evening has not opened")
        s1.timeMin = Sleepovers.ARRIVE_FROM - 15
        check(Sleepwear.mirrorCode(s1) == "",
            "reflections: a quarter hour before the evening " +
                "opens, the day look still stands")
        s1.timeMin = Sleepovers.ARRIVE_FROM
        check(Sleepwear.mirrorCode(s1) ==
            Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "reflections: the minute the evening opens, the " +
                "glass changes into the night look")
        val (_, s2) = slpRState(940_003)
        s2.agents.values.first { it.isPlayer }.location =
            YOUR_HOUSE
        s2.timeMin = 19 * 60
        check(!Sleepovers.plannedTonight(s2) &&
            Sleepwear.mirrorCode(s2) == "",
            "reflections: an evening at the house with no plan " +
                "standing shows the day look")
        val (_, s3) = slpRState(940_004)
        stageNightR(s3, guests)
        setDayR(s3, s3.absDay + 1)
        s3.timeMin = 9 * 60
        check(Sleepwear.mirrorCode(s3) == "",
            "reflections: the morning after, the mirror is a " +
                "day mirror again")
    }

    // ---------- the street: agreement with the camera ----------
    run {
        val (_, s) = heroRState(940_010)
        s.agents["Stan"]?.location = "KidsPark"
        s.agents["Stan"]?.asleep = false
        val code = Heroes.streetCostumeCode(s)
        check(code.isNotEmpty() &&
            code == Heroes.playerCostumeCode(s),
            "reflections: standing a patrol spot inside the " +
                "window, the street's code is your costume " +
                "derivation — your worn palette, caped")
        check(code == Heroes.figureCode(s,
                PhotoFigure("NewKid", "player", "happy")),
            "reflections: ...and identical to figureCode's " +
                "player branch — the street renders the identity " +
                "the photo records use, never a second derivation")
        val rec = Photos.compose(s, listOf("Stan"), emptyList(),
            "NewKid", DEFAULT_APPEARANCE)
        val meFig = rec.figures.firstOrNull { it.kind == "player" }
        check(meFig != null && meFig.hero == code,
            "reflections: a frame composed at the same moment " +
                "freezes the identical code onto your figure — " +
                "the street and the album tell the same story")
        val parsed = Heroes.parseCode(code)
        check(parsed != null && parsed.third ==
            (Heroes.POWER_EMBLEMS[s.lifeText["heroPower"]]
                ?: "star"),
            "reflections: the emblem the street draws is read " +
                "off the same power the caper records — one " +
                "persona on every surface")
    }

    // ---------- the street: street clothes on every other terms ----------
    run {
        val (_, s) = heroRState(940_011)
        s.timeMin = Heroes.PATROL_FROM - 15
        check(Heroes.streetCostumeCode(s) == "",
            "reflections: at 19:15 you are in street clothes — " +
                "the window has not opened")
        s.timeMin = Heroes.PATROL_FROM
        check(Heroes.streetCostumeCode(s) ==
            Heroes.playerCostumeCode(s),
            "reflections: at 19:30 sharp the costume is on")
        s.timeMin = Heroes.PATROL_TO - 15
        check(Heroes.streetCostumeCode(s).isNotEmpty(),
            "reflections: at 21:45 the patrol is still out")
        s.timeMin = Heroes.PATROL_TO
        check(Heroes.streetCostumeCode(s) == "",
            "reflections: at 22:00 the sleep hour takes the " +
                "costume off — the window's far edge is exact")
        var d = s.absDay + 1
        while (Heroes.isPatrolNight(d)) d++
        s.absDay = d
        s.timeMin = 20 * 60
        check(Heroes.streetCostumeCode(s) == "",
            "reflections: a non-patrol night at a spot at the " +
                "same hour is street clothes")
        val (_, s2) = heroRState(940_012)
        s2.agents.values.first { it.isPlayer }.location = "Bijou"
        check(Heroes.streetCostumeCode(s2) == "",
            "reflections: away from a patrol spot the costume " +
                "stays home, patrol hours or not")
        val (_, s3) = heroRState(940_013)
        s3.agents.values.first { it.isPlayer }.location =
            "Elementary"
        s3.playerInside = true
        check(Heroes.streetCostumeCode(s3) == "",
            "reflections: indoors — even inside a building " +
                "that is itself a spot — the street look is " +
                "street clothes")
        val e4 = Engine(940_014)
        val s4 = e4.newState()
        e4.createPlayer(s4, "NewKid", DEFAULT_APPEARANCE)
        s4.absDay = patrolDayR(s4.absDay)
        s4.timeMin = 20 * 60
        e4.player(s4).location = "KidsPark"
        check(!Heroes.heroCreated(s4) &&
            Heroes.streetCostumeCode(s4) == "",
            "reflections: with no hero identity made there is " +
                "no costume to render, spot and hour regardless")
    }

    // ---------- rendering writes nothing ----------
    run {
        val (_, s) = slpRState(940_020)
        stageNightR(s, listOf("Stan", "Kyle"))
        val (_, hs) = heroRState(940_021)
        val beforeS = encodeGameState(s)
        val beforeH = encodeGameState(hs)
        repeat(3) {
            Sleepwear.mirrorCode(s)
            Sleepwear.liveNow(s, YOUR_HOUSE)
            Heroes.streetCostumeCode(hs)
            Heroes.playerInCostume(hs)
        }
        check(encodeGameState(s) == beforeS &&
            encodeGameState(hs) == beforeH,
            "reflections: rendering decides, it never writes — " +
                "both saves byte-identical after every render " +
                "read this build adds")
    }

    // ---------- the wiring: one reader, one pass, per surface ----------
    run {
        val gv = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        val pv = File(root,
            "src/com/hunt3r/southparktown/PhotoView.kt").readText()
        val mirrorAt = gv.indexOf("the MIRROR (right wall strip)")
        val albumAt = gv.indexOf("the ALBUM BOOK (on the desk")
        // v0.15.0a re-pin: the glass now reads the ONE
        // preview derivation (LiveLook.playerLook), whose
        // sleep code IS mirrorCode's (pinned equal in the
        // v0.15.0a section); the reader count discipline
        // is unchanged — one call, in the fixture's block.
        val mCodeAt = gv.indexOf("LiveLook.playerLook(st)")
        val figAt0 = gv.indexOf("private fun drawFigures")
        check(mCodeAt > mirrorAt && mCodeAt < albumAt &&
            gv.indexOf("LiveLook.playerLook(st)", mCodeAt + 1) > figAt0 &&
            gv.indexOf("LiveLook.playerLook(st)", mCodeAt + 1) ==
                gv.lastIndexOf("LiveLook.playerLook(st)"),
            "reflections: LiveLook.playerLook has exactly TWO " +
                "readers in GameView — the mirror glass (in its " +
                "fixture block) and, since v0.15.0c, the " +
                "on-screen player figure inside drawFigures. " +
                "The derivation itself stays single; the " +
                "overhaul added the second reader, it did not " +
                "fork the look (v0.15.0c re-pin of the " +
                "exactly-once rule)")
        val figAt = gv.indexOf("private fun drawFigures")
        val doorAt = gv.indexOf("private fun drawEntryDoor")
        val sCodeAt = gv.indexOf("Heroes.streetCostumeCode(st)")
        val heroDrawAt = gv.indexOf("LiveLook.HERO -> KidArt.drawHeroFigure",
            figAt)
        check(sCodeAt == -1 && heroDrawAt > figAt && heroDrawAt < doorAt,
            "reflections: the street figure pass draws you " +
                "through KidArt's hero pass keyed on " +
                "LiveLook's HERO kind — inside drawFigures. " +
                "Heroes.streetCostumeCode is NO LONGER read " +
                "here (v0.15.0c re-pin: the spot-gated street " +
                "costume is retired with the first-person " +
                "view; the player stands in the scene and " +
                "wears LiveLook's window-based code, the " +
                "v0.15.0a ruling. streetCostumeCode's " +
                "derivation and its Photos-side pins stand)")
        check(pv.contains("PaperDoll.drawDollSleep") &&
            pv.contains("PaperDoll.drawDollHero"),
            "reflections: PhotoView still renders both freezes " +
                "through the same two KidArt passes — the album's " +
                "side of both agreements stands (v0.16.0d: routed " +
                "through PaperDoll, which wraps those two passes)")
    }
}


// ============================================================
// v0.14.0b: field trips — three Fridays a school year, the
// fourth grade meets on a bus (Queue #14 item 2). Anchors
// swept in one lived calendar space; the roster derived
// from the cast tables; the day bends (School goes quiet,
// an agenda claim holds the class at the site); boarding,
// a played choice beat per site, one photograph, and the
// dance-discipline records (Journal page, TOWN NEWS line,
// one FIELDTRIP phone text). TalkGate keeps eleven rails.
// ============================================================
private fun sectionV0140c(root: String) {
// ================= v0.14.0c: the Bijou film festival =================
// Queue #14 item 3. One December week a year the Bijou runs
// five wholly original town prints before a seated jury:
// the anchor swept disjoint 2026–2100 in ONE lived calendar
// space against every standing set piece; the slate's order
// a seeded (year) shuffle; the stars drawn the MovieNights
// way; the score derived (qualities 4/4/2 + the jury's
// leanings at face + twice the night's buzz) and recomputed
// here independently; the Golden Popcorn down a stated tie
// ladder proven level by level; the week riding MovieNights'
// machinery (its deference ladder learned DARK_FESTIVAL, its
// reaction table scores the session, its draw fills the
// house, its doors are the doors) with ONE new agenda claim
// seated twentieth; the records in the queue's discipline —
// TOWN NEWS lines only (the headline ladder stands at ten,
// deliberately), a yearbook line, a Journal page, one
// FESTIVAL phone text, +1 to the winner's stars only for a
// sat closing night, exactly one closing-night photograph.
println("== v0.14.0c: the Bijou film festival — Queue #14 item 3 ==")
val readme = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readme.contains("### v0.14.0c"),
    "v0.14.0c: the README carries this build's changelog entry")
check(readme.contains("## Status — v0.14.0c"),
    "v0.14.0c: the README carries this build's status section")
check(tuning.contains("The film festival (v0.14.0c"),
    "v0.14.0c: the tuning ledger carries the festival's entry")
val manifestSrc = File(root, "AndroidManifest.xml").readText()
check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 104 / 0.14.0c")
val ktCount = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCount == 137 && readme.contains("110 Kotlin files"),
    "v0.14.0c: the source tree and its description agree — " +
        "110 Kotlin files (Festival.kt joined) (counted $ktCount)")
val festSrc = File(root,
    "src/com/hunt3r/southparktown/Festival.kt").readText()
check(festSrc.contains("object FestivalCalendar") &&
    festSrc.contains("object Festival") &&
    festSrc.contains("data class FestFilm") &&
    festSrc.contains("data class FestRecord"),
    "festival: the module stands whole — calendar, engine, " +
        "the five prints and the year's record")
val engSrcC = File(root,
    "src/com/hunt3r/southparktown/Engine.kt").readText()
check(engSrcC.indexOf("Parade.gatheringBlock(state, a.name, timeMin)") <
    engSrcC.indexOf("FieldTrip.gatheringBlock(state, a.name, timeMin)") &&
    engSrcC.indexOf("FieldTrip.gatheringBlock(state, a.name, timeMin)") <
    engSrcC.indexOf("Festival.gatheringBlock(state, a.name, timeMin)") &&
    engSrcC.indexOf("Festival.gatheringBlock(state, a.name, timeMin)") <
    engSrcC.indexOf("Sleepovers.gatheringBlock(state, a.name, timeMin)"),
    "festival claim: the festival's claim seats TWENTIETH — " +
        "after the parade's and the field trips', before the " +
        "sleepovers' — in Engine's one living stack")
check(engSrcC.contains("Festival.dailyRollover(state)"),
    "festival rollover: Engine's morning runs the festival's " +
        "settle and wrap beside the field trips'")
val movieSrcC = File(root,
    "src/com/hunt3r/southparktown/MovieNights.kt").readText()
check(movieSrcC.contains("DARK_FESTIVAL") &&
    movieSrcC.contains("Festival.isFestivalNight(state)"),
    "festival deference: MovieNights' ladder learned the " +
        "festival as its last dark reason, and its house " +
        "stands down on festival nights")
val phoneSrcC = File(root,
    "src/com/hunt3r/southparktown/Phone.kt").readText()
check(Phone.FESTIVAL in Phone.TRIGGERS &&
    phoneSrcC.contains("Festival.phoneBeat(state)"),
    "festival phone: the FESTIVAL trigger stands in the " +
        "closed set and the harvest carries the one beat")
check(Festival.DOORS_FROM == MovieNights.DOORS_FROM &&
    Festival.LAST_SEATING == MovieNights.LAST_SEATING &&
    Festival.GATHER_TO == MovieNights.FEATURE_END,
    "festival doors: doors, last seating and the gather " +
        "window are MovieNights' own constants, read by " +
        "reference — one theater, one set of hours")

// ---------- helpers ----------
fun setDayC(s: GameState, absDay: Int) {
    s.absDay = absDay
    val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(absDay))
    s.gameYear = key.substring(0, 4).toInt()
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
    s.todayKey = key
}
fun festStateC(seed: Long): Pair<Engine, GameState> {
    val e = Engine(seed)
    val s = e.newState()
    e.createPlayer(s, "Veteran", DEFAULT_APPEARANCE)
    return e to s
}
fun playerToC(s: GameState, place: String, min: Int) {
    val me = s.agents.values.first { it.isPlayer }
    me.location = place; s.playerInside = true
    me.asleep = false; me.waypoints.clear()
    s.timeMin = min
}
fun stageCastC(s: GameState, names: List<String>, place: String) {
    for (a in s.agents.values) if (a.name in names) {
        a.location = place
        a.asleep = false; a.waypoints.clear()
    }
}
fun bestRidC(beat: String): String =
    MovieNights.REACTIONS.maxByOrNull {
        MovieNights.scoreFor(beat, it.first) }!!.first

// ---------- the anchor + the sweep ----------
// December's pocket, in ONE lived calendar space: every
// festival ordinal 2026–2100 against the REAL predicates of
// the dance, the talent show, the parade, the play's whole
// schedule, the fair and carnival weeks, all three trips,
// the finale windows and the holiday table.
run {
    fun finaleWindowsC(y: Int): List<IntRange> {
        val ends = listOf("0228", "0531", "0831", "1130")
        return ends.map { md ->
            var key = "$y$md"
            if (md == "0228" && (y % 4 == 0 &&
                (y % 100 != 0 || y % 400 == 0))) key = "${y}0229"
            val endOrd = ordinalOfKey(key)
            (endOrd - Finales.WINDOW_DAYS + 1)..endOrd
        }
    }
    var bad = ""
    var festDays = 0
    for (y in 2026..2100) {
        val monday = FestivalCalendar.nightDay(y, 0)
        val mOrd = FestivalCalendar.mondayOrdinal(y)
        if (FairCalendar.dowOfOrdinal(mOrd) != 1)
            bad = "$y: the festival Monday is not a Monday"
        val ann = FestivalCalendar.announceDay(y)
        if (ann != monday - 7)
            bad = "$y: the announce day is not a week ahead"
        // exactly five festival days in the lived December
        var count = 0
        for (d in 1..31) {
            val ord = ordinalOfKey("%04d12%02d".format(y, d))
            val abs = FairCalendar.absDayOfOrdinal(ord)
            val f = FestivalCalendar.festivalAt(abs)
            if (f != null) {
                count++
                if (f.first != y) bad = "$y: a December day " +
                    "claims another year's festival"
                if (FestivalCalendar.nightDay(y, f.second) != abs)
                    bad = "$y: night ${f.second} disagrees " +
                        "with the lived calendar"
            }
        }
        if (count != Festival.NIGHTS)
            bad = "$y: December holds $count festival days, " +
                "not ${Festival.NIGHTS}"
        festDays += count
        for (n in 0 until Festival.NIGHTS) {
            val abs = FestivalCalendar.nightDay(y, n)
            val ord = FairCalendar.ordinalOfAbsDay(abs)
            val dow = FairCalendar.dowOfOrdinal(ord)
            if (dow != 1 + n) bad = "$y night $n: weekday " +
                "$dow, not ${1 + n} (Mon–Fri)"
            val md = "%02d%02d".format(
                abs.let { keyFromOrdinal(ord).substring(4, 6).toInt() },
                keyFromOrdinal(ord).substring(6, 8).toInt())
            if (currentHoliday(md) != null)
                bad = "$y night $n: a holiday owns the day"
            if (ord == DanceCalendar.danceOrdinal(y) ||
                ord == DanceCalendar.danceOrdinal(y + 1) ||
                ord == TalentCalendar.showOrdinal(y) ||
                ord == TalentCalendar.showOrdinal(y + 1) ||
                ord == ParadeCalendar.paradeOrdinal(y) ||
                ord == ParadeCalendar.paradeOrdinal(y + 1))
                bad = "$y night $n: a set piece owns the day"
            val fairW = FairCalendar.windowFor(y)
            val fairW2 = FairCalendar.windowFor(y + 1)
            val carnW = CarnivalCalendar.windowFor(y)
            val carnW2 = CarnivalCalendar.windowFor(y + 1)
            if (ord in fairW.startOrd..fairW.startOrd + 6 ||
                ord in fairW2.startOrd..fairW2.startOrd + 6 ||
                ord in carnW.startOrd..carnW.endOrd ||
                ord in carnW2.startOrd..carnW2.endOrd)
                bad = "$y night $n: fair or carnival week"
            if (ord == TripCalendar.fallOrdinal(y) ||
                ord == TripCalendar.winterOrdinal(y) ||
                ord == TripCalendar.winterOrdinal(y + 1) ||
                ord == TripCalendar.springOrdinal(y) ||
                ord == TripCalendar.springOrdinal(y + 1))
                bad = "$y night $n: a field trip owns the day"
            for (sy in listOf(y, y + 1)) {
                val sch = PlayCalendar.scheduleFor(sy)
                if (abs in sch.announceDay..sch.openingDay)
                    bad = "$y night $n: inside the play's " +
                        "schedule (school year $sy)"
            }
            for (wy in listOf(y, y + 1)) {
                if (finaleWindowsC(wy).any { ord in it })
                    bad = "$y night $n: inside a finale window"
            }
            if (bad.isNotEmpty()) break
        }
        if (bad.isNotEmpty()) break
    }
    check(bad.isEmpty() && festDays == 75 * Festival.NIGHTS,
        "festival sweep: 2026–2100 in one lived calendar " +
            "space — every festival week is Mon–Fri in the " +
            "December pocket, announced a week ahead, and " +
            "disjoint from the dance, the talent Saturday, " +
            "the parade, the play's schedule, the fair and " +
            "carnival weeks, all three trips, the finale " +
            "windows and every holiday ($bad)")
    val nav = FestivalCalendar.festivalAt(
        FestivalCalendar.nightDay(2031, 4))
    check(nav == (2031 to 4) &&
        FestivalCalendar.nextYearAfter(
            FestivalCalendar.nightDay(2031, 4) + 1) == 2032 &&
        !Festival.isFestivalDay(
            FestivalCalendar.nightDay(2031, 4) + 3),
        "festival calendar: the closing Friday reads back " +
            "as (2031, 4), the next festival year after it " +
            "is 2032, and the Monday after is ordinary time")
}

// ---------- the slate, the stars, the jury ----------
run {
    check(Festival.FILMS.size == Festival.NIGHTS &&
        Festival.FILMS.map { it.id }.distinct().size ==
            Festival.NIGHTS,
        "festival slate: five prints, five distinct ids — " +
            "one for every night")
    val orders = mutableSetOf<List<String>>()
    var slateOk = true
    for (y in 2026..2035) {
        val slate = Festival.slate(y)
        if (slate.map { it.id }.sorted() !=
            Festival.FILMS.map { it.id }.sorted()) slateOk = false
        if (Festival.slate(y) != slate) slateOk = false
        orders.add(slate.map { it.id })
    }
    check(slateOk && orders.size >= 3,
        "festival slate: the seeded (year) shuffle deals " +
            "each of the five prints exactly once a year, " +
            "is stable within the year, and varies across " +
            "years (${orders.size} distinct orders, 2026–35)")
    var starsOk = true
    for (y in listOf(2026, 2027, 2031, 2050)) {
        for (f in Festival.FILMS) {
            val st = Festival.starsFor(y, f)
            if (st.size !in 2..4) starsOk = false
            if (st.any { it !in KID_ORDER }) starsOk = false
            if (st.any { it in MovieNights.NEVER_ATTENDS })
                starsOk = false
            if (Festival.starsFor(y, f) != st) starsOk = false
        }
    }
    check(starsOk,
        "festival stars: every print's cast is 2–4 names " +
            "from KID_ORDER, never a never-come name, and " +
            "the same on every read of the same (year, film)")
    var juryOk = true
    for (y in 2026..2100) {
        val j = Festival.juryFor(y)
        if (j.size != 3) juryOk = false
        if (j.map { it.lean }.toSet() !=
            setOf("craft", "heart", "weird")) juryOk = false
        if (j.any { jur -> jur.name !in CharacterSystem.CAST.keys })
            juryOk = false
        val next = Festival.juryFor(y + 1).map { it.name }
        if (j.any { it.name in next }) juryOk = false
    }
    check(juryOk,
        "festival jury: three seated jurors a year, one per " +
            "leaning, every name a real town name — and no " +
            "juror repeats across consecutive years, " +
            "2026–2100 (the yearbook rotation, grown up)")
    var denyHits = ""
    for (f in Festival.FILMS) {
        val hay = (f.title + " " + f.genre + " " + f.note +
            " " + f.opener + " " + f.flop + " " +
            f.finale)
            .lowercase()
        for (bad in Festival.DENYLIST) {
            if (hay.contains(bad)) denyHits += "${f.id}:$bad "
        }
    }
    for (j in Festival.JURY_POOL) {
        if (Festival.DENYLIST.any { j.taste.lowercase().contains(it) })
            denyHits += "juror:${j.name} "
    }
    check(denyHits.isEmpty(),
        "festival content: no real picture, franchise or " +
            "festival name anywhere in the prints or the " +
            "jury's tastes ($denyHits)")
}

// ---------- scoring, recomputed independently ----------
run {
    val (_, s) = festStateC(1401)
    var scoreOk = true
    for (y in listOf(2027, 2031, 2044)) {
        val cards = Festival.scoreCards(s, y)
        if (cards.size != Festival.NIGHTS) scoreOk = false
        val jury = Festival.juryFor(y)
        for (c in cards) {
            val q = c.film.craft * Festival.W_CRAFT +
                c.film.heart * Festival.W_HEART +
                c.film.weird * Festival.W_WEIRD
            val j = jury.sumOf { c.film.dim(it.lean) } *
                Festival.JURY_PER_LEAN
            val a = Festival.houseBuzz(y, c.film)
                .coerceIn(-3, 6) * Festival.AUD_PER_BUZZ
            if (c.quality != q || c.jury != j ||
                c.audience != a || c.total != q + j + a)
                scoreOk = false
        }
        val manual = cards.maxWithOrNull(
            compareBy<Festival.ScoreCard> { it.total }
                .thenBy { it.audience }
                .thenBy { it.film.heart }
                .thenByDescending { it.film.title })
        if (Festival.pickWinner(cards) != manual) scoreOk = false
        if (Festival.winnerCard(s, y) != manual) scoreOk = false
    }
    check(scoreOk,
        "festival scoring: qualities at 4/4/2, the jury's " +
            "leanings at face value, twice the night's buzz — " +
            "recomputed here from the authored numbers, and " +
            "the winner is the ladder's pick on every card")
    var buzzOk = true
    for (y in 2026..2060) for (f in Festival.FILMS) {
        val b = Festival.houseBuzz(y, f)
        if (b !in 0..6) buzzOk = false
        if (Festival.houseBuzz(y, f) != b) buzzOk = false
    }
    check(buzzOk,
        "festival house buzz: an unattended night's buzz is " +
            "a pure 0..6 function of (year, film) — the house " +
            "has its own opinion whether you sit or not")
    // the tie ladder, level by level, on fabricated cards
    fun filmC(id: String, title: String, heart: Int) =
        Festival.FestFilm(id, title, "Test", "note", "prop",
            5, heart, 5, MovieNights.BEAT_HEART,
            MovieNights.BEAT_HEART,
            "opener", "flop", "finale")
    val fa = filmC("fa", "Alpha Reel", 9)
    val fb = filmC("fb", "Beta Reel", 4)
    val byTotal = Festival.pickWinner(listOf(
        Festival.ScoreCard(fa, 10, 10, 10),
        Festival.ScoreCard(fb, 20, 20, 20)))
    val byAudience = Festival.pickWinner(listOf(
        Festival.ScoreCard(fa, 30, 10, 4),
        Festival.ScoreCard(fb, 20, 16, 8)))
    val byHeart = Festival.pickWinner(listOf(
        Festival.ScoreCard(fa, 30, 10, 8),
        Festival.ScoreCard(fb, 38, 2, 8)))
    val fc = filmC("fc", "Aardvark Reel", 9)
    val byTitle = Festival.pickWinner(listOf(
        Festival.ScoreCard(fa, 30, 10, 8),
        Festival.ScoreCard(fc, 30, 10, 8)))
    check(byTotal?.film == fb && byAudience?.film == fb &&
        byHeart?.film == fa && byTitle?.film == fc,
        "festival tie ladder: total decides first, then " +
            "the audience's points, then the film's heart, " +
            "then the title A–Z — each level proven on " +
            "cards tied through every level above it")
}

// ---------- deference + the claim ----------
run {
    val (_, s) = festStateC(1403)
    val y = 2027
    val monday = FestivalCalendar.nightDay(y, 0)
    setDayC(s, monday)
    playerToC(s, "Bijou", 19 * 60 + 30)
    check(MovieNights.darkReason(s) == MovieNights.DARK_FESTIVAL &&
        MovieNights.darkLine(s)?.contains("film festival") == true,
        "festival deference: on a festival night the " +
            "regular marquee reads dark FOR the festival — " +
            "MovieNights' ladder, extended not forked")
    check(!Festival.nightDark(s) &&
        Festival.nightDarkReason(s) == null,
        "festival deference: and the festival itself is " +
            "not dark on an ordinary festival night — no " +
            "bigger owner holds this December Monday")
    check(MovieNights.gatheringBlock(s, "Stan", 19 * 60 + 30) == null,
        "festival claim: the regular screening gathers " +
            "nobody on a festival night")
    val star = Festival.starsFor(y, Festival.filmFor(y, 0)).first()
    val block = Festival.gatheringBlock(s, star, 19 * 60 + 30)
    check(block != null && block.location == "Bijou",
        "festival claim: the festival's own claim (seat " +
            "twenty) holds tonight's star at the Bijou " +
            "through the feature")
    check(Festival.gatheringBlock(s, "Towelie", 19 * 60 + 30) == null,
        "festival claim: and nobody outside tonight's " +
            "derived house is claimed — the never-come " +
            "name stays home")
    check(Festival.screenOpen(s) &&
        Festival.sessionStatus(s).kind == Festival.ST_SEATING,
        "festival screen: on the day, the screen is the " +
            "festival's and the rope offers a seat at doors")
    setDayC(s, FestivalCalendar.announceDay(y))
    playerToC(s, "Bijou", 19 * 60 + 30)
    check(!Festival.screenOpen(s) &&
        Festival.lookText(s, "Bijou")
            ?.contains("second poster") == true,
        "festival screen: the poster week does NOT take " +
            "the screen — the program rides the marquee's " +
            "second poster while the regular feature " +
            "keeps its rope")
    val morning = Festival.morningNote(s)
    check(morning != null && morning.contains("Bijou Film Festival"),
        "festival mornings: announcement morning carries " +
            "the poster's line in the household report")
}

// ---------- one whole week, lived on one save ----------
run {
    val (_, s0) = festStateC(1404)
    val y = 2027
    val monday = FestivalCalendar.nightDay(y, 0)
    val friday = FestivalCalendar.nightDay(y, Festival.NIGHTS - 1)
    val saturday = friday + 1
    fun driveNight(s: GameState, n: Int): Pair<Int, String> {
        var expected = 0
        var credits = ""
        var guard = 0
        while (guard++ < 30) {
            val beat = Festival.sessionBeat(s) ?: break
            when (beat.kind) {
                "prompt" -> {
                    val cb = Festival.asFeature(y, n)
                        .cards[beat.cardIndex].beat
                    val rid = bestRidC(cb)
                    expected += MovieNights.scoreFor(cb, rid)
                    Festival.react(s, rid)
                }
                "credits" -> {
                    credits = beat.text
                    Festival.advance(s)
                    break
                }
                else -> Festival.advance(s)
            }
        }
        return expected to credits
    }
    // Monday: doors, a seat, the full eleven beats
    var s = s0
    setDayC(s, monday)
    playerToC(s, "Bijou", 10 * 60)
    check(Festival.sessionStatus(s).kind == Festival.ST_BEFORE,
        "festival week: Monday morning the rope says the " +
            "show is tonight, not yet")
    playerToC(s, "Bijou", 19 * 60)
    stageCastC(s, Festival.starsFor(y, Festival.filmFor(y, 0)),
        "Bijou")
    check(Festival.seat(s) &&
        Festival.sessionStatus(s).kind == Festival.ST_RESUME,
        "festival week: at doors you take your seat — " +
            "free, like every Bijou arts night")
    val (buzzMon, _) = driveNight(s, 0)
    val recMon = Festival.record(s, y)
    check(recMon != null && recMon.attended[0] == buzzMon &&
        recMon.settled.contains(0),
        "festival week: Monday's film lands in the record " +
            "at the buzz your reactions actually made " +
            "($buzzMon), settled the same night")
    val cardMon = Festival.scoreCards(s, y)
        .first { it.film == Festival.filmFor(y, 0) }
    check(cardMon.audience == buzzMon.coerceIn(-3, 6) *
        Festival.AUD_PER_BUZZ,
        "festival week: and Monday's card reads YOUR buzz " +
            "back at twice its weight — played nights are " +
            "not the house's opinion")
    // the save path, mid-festival: slate, record, session
    val doc = encodeGameState(s)
    s = decodeGameState(doc)
    check(Festival.record(s, y) == recMon &&
        Festival.slate(y) == Festival.slate(y),
        "festival save: a mid-festival save/reload through " +
            "the real encode/decode path keeps the year's " +
            "record whole")
    // Tue–Thu unplayed: the mornings settle the house's nights
    for (d in (monday + 1)..friday) {
        setDayC(s, d)
        Festival.dailyRollover(s)
    }
    val recFri = Festival.record(s, y)
    check(recFri != null &&
        recFri.settled.containsAll(listOf(0, 1, 2, 3)) &&
        recFri.attended.keys == setOf(0),
        "festival week: the skipped nights settle as the " +
            "house's own — attended only where you sat")
    // Friday: closing night, the award in the credits
    setDayC(s, friday)
    playerToC(s, "Bijou", 19 * 60)
    stageCastC(s, Festival.starsFor(y,
        Festival.filmFor(y, Festival.NIGHTS - 1)), "Bijou")
    check(Festival.seat(s), "festival week: closing " +
        "night seats like any other")
    val (_, creditsFri) = driveNight(s, Festival.NIGHTS - 1)
    val winner = Festival.winnerFilm(s, y)!!
    check(creditsFri.contains("Golden Popcorn") &&
        creditsFri.contains(winner.title),
        "festival week: Friday's credits name the Golden " +
            "Popcorn winner as the last card falls — the " +
            "same winner the arithmetic derives")
    check(Festival.sessionStatus(s).kind == Festival.ST_AWARD,
        "festival photo: after closing credits, the rope " +
            "offers the one photograph while the house " +
            "is still lit")
    val photosBefore = s.photos.size
    val photoText = Festival.takePhoto(s)
    val recPhoto = Festival.record(s, y)
    check(photoText != null && s.photos.size == photosBefore + 1 &&
        recPhoto != null && recPhoto.photoId.isNotEmpty() &&
        s.photos.any { it.id == recPhoto.photoId &&
            it.caption.contains("Golden Popcorn") },
        "festival photo: exactly one group photograph, " +
            "minted through the photo system's own " +
            "composition, its caption naming the award")
    check(Festival.takePhoto(s) == null &&
        Festival.sessionStatus(s).kind == Festival.ST_CLOSED,
        "festival photo: and never a second — the frame " +
            "is spent, the week is closed")
    // Saturday: the wrap pays the winner's stars — once
    val winStars = Festival.starsFor(y, winner)
    val bondsBefore = winStars.associateWith {
        s.friendship[it] ?: 0 }
    setDayC(s, saturday)
    Festival.dailyRollover(s)
    val recWrap = Festival.record(s, y)!!
    check(recWrap.wrapped && recWrap.wrapDay == saturday &&
        recWrap.paid,
        "festival wrap: the first morning after closing " +
            "wraps the year and pays the award")
    check(winStars.all {
        (s.friendship[it] ?: 0) == (bondsBefore[it] ?: 0) + 1 },
        "festival wrap: the winning film's stars each " +
            "gain +1 — because you SAT closing night")
    Festival.dailyRollover(s)
    check(winStars.all {
        (s.friendship[it] ?: 0) == (bondsBefore[it] ?: 0) + 1 },
        "festival wrap: a second rollover pays nothing " +
            "twice — the paid stamp is the discipline")
    val beat = Festival.phoneBeat(s)
    check(beat != null && beat.first == winStars.first() &&
        beat.third.contains(winner.title),
        "festival phone: on the wrap's morning, the " +
            "winning film's first star texts the fact — " +
            "and nobody else, on no other morning")
    setDayC(s, saturday + 1)
    check(Festival.phoneBeat(s) == null,
        "festival phone: Sunday hears nothing — the one " +
            "text was Saturday's")
    val line = Festival.paperLine(s, Jobs.weekIndex(friday))
    val annLine = Festival.paperLine(s,
        Jobs.weekIndex(FestivalCalendar.announceDay(y)))
    check(line != null && line.contains(winner.title) &&
        annLine != null && annLine.contains("coming"),
        "festival paper: the winner stands in the " +
            "closing week's TOWN NEWS, and the slate in " +
            "the announcement week's")
    val edition = Newspaper.composeEdition(s,
        Jobs.weekIndex(friday))
    check(edition.lines.any { it == line } &&
        !edition.headline.contains("Popcorn") &&
        !edition.headline.contains("FESTIVAL"),
        "festival paper: the winner's line is SECTION " +
            "copy inside the composed edition — the " +
            "headline stays the ladder's own (ten tiers, " +
            "no festival tier, by deliberate decision)")
    check(Festival.yearbookLine(s, y + 1)
        ?.contains(winner.title) == true,
        "festival yearbook: the volume the December " +
            "belongs to carries the winner's line")
    check(Festival.pageLines(s).any {
        it.contains(winner.title) &&
            it.contains("Golden Popcorn") },
        "festival journal: the 🎬 page reads the wrapped " +
            "year back with its winner")
    check(Festival.morningNote(s) == null,
        "festival mornings: after the wrap's morning, " +
            "the festival goes quiet until next December")
}

// ---------- missed closing: no pay, an honest text ----------
run {
    val (_, s) = festStateC(1405)
    val y = 2028
    val friday = FestivalCalendar.nightDay(y, Festival.NIGHTS - 1)
    val saturday = friday + 1
    // the year's record, staged through the module's own
    // serialized format: three nights sat, closing not
    s.lifeText["festRec:$y"] =
        "$y|att=0:3,1:2,2:4|yield=|settled=0,1,2|wrapped=0|" +
            "wrapDay=-1|paid=0|photo="
    s.lifeText["festYears"] = "$y"
    setDayC(s, saturday)
    Festival.dailyRollover(s)
    val rec = Festival.record(s, y)!!
    val winner = Festival.winnerFilm(s, y)!!
    val winStars = Festival.starsFor(y, winner)
    val bonds = winStars.associateWith { s.friendship[it] ?: 0 }
    check(rec.wrapped && !rec.paid &&
        rec.settled.containsAll(listOf(0, 1, 2, 3, 4)) &&
        winStars.all { (s.friendship[it] ?: 0) == bonds[it] },
        "festival missed: a closing night you never sat " +
            "still wraps and crowns — but pays nobody, " +
            "the played-through rule")
    val beat = Festival.phoneBeat(s)
    check(beat != null && beat.third.contains("missed"),
        "festival missed: the morning-after text says " +
            "you missed it, plainly, and moves on")
}

// ---------- left mid-feature: the settle keeps your buzz ----------
run {
    val (_, s) = festStateC(1406)
    val y = 2029
    val monday = FestivalCalendar.nightDay(y, 0)
    setDayC(s, monday)
    playerToC(s, "Bijou", 19 * 60)
    stageCastC(s, Festival.starsFor(y, Festival.filmFor(y, 0)),
        "Bijou")
    check(Festival.seat(s), "festival settle: Monday seats")
    var guard = 0
    while (guard++ < 12) {
        val beat = Festival.sessionBeat(s) ?: break
        if (beat.kind == "prompt") {
            val cb = Festival.asFeature(y, 0)
                .cards[beat.cardIndex].beat
            Festival.react(s, bestRidC(cb))
            break
        }
        Festival.advance(s)
    }
    val buzzAtLeave = Festival.buzzNow(s)
    setDayC(s, monday + 1)
    Festival.dailyRollover(s)
    val rec = Festival.record(s, y)
    check(buzzAtLeave > 0 && rec != null &&
        rec.attended[0] == buzzAtLeave && rec.settled.contains(0),
        "festival settle: walking out mid-feature still " +
            "lands the night in the record at the buzz " +
            "you'd reached — the morning keeps the " +
            "receipt, not a grudge")
    // the yield stamp branch: a night the town owned
    val y2 = 2030
    s.lifeText["festRec:$y2"] =
        "$y2|att=|yield=|settled=|wrapped=0|wrapDay=-1|" +
            "paid=0|photo="
    s.lifeText["festYears"] = "$y,$y2"
    s.lifeText["festYield:$y2:1"] = MovieNights.DARK_CASE
    setDayC(s, FestivalCalendar.nightDay(y2, 2))
    Festival.dailyRollover(s)
    val recY = Festival.record(s, y2)
    check(recY != null && recY.yielded.contains(1) &&
        recY.settled.containsAll(listOf(0, 1)) &&
        !recY.attended.containsKey(1),
        "festival settle: a night stamped yielded (a " +
            "case owned it, learned on the day) settles " +
            "as yielded — in neither column of shame")
}

// ---------- the hostile doc + the closed surfaces ----------
run {
    val (_, s) = festStateC(1407)
    s.lifeText["festRec:2031"] = "garbage"
    check(Festival.record(s, 2031) == null,
        "festival records: a garbage record reads as no " +
            "record — never a minted winner")
    s.lifeText["festRec:2031"] =
        "2031|att=x:y,0:99|yield=99,-2|settled=-4,0|" +
            "wrapped=3|wrapDay=abc|paid=2|photo=p1"
    val rec = Festival.record(s, 2031)
    check(rec != null && rec.attended == mapOf(0 to 99) &&
        rec.yielded.isEmpty() && rec.settled == setOf(0) &&
        !rec.wrapped && !rec.paid && rec.photoId == "p1",
        "festival records: a hostile record is clamped " +
            "field by field — nights to the week's five, " +
            "flags to their bits, junk dropped whole; " +
            "the buzz itself is clamped where it is " +
            "SPENT, in audiencePoints, not where it is kept")
    val src = festSrc
    check(src.contains("fun dailyRollover") &&
        src.contains("WRAP_TAIL"),
        "festival wrap: the wrap and its tail stand in " +
            "the module, where the suite can see them")
}
}

private fun sectionV0140b(root: String) {
println("== v0.14.0b: field trips — Queue #14 item 2 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.14.0b"),
        "trips: the README carries this build's changelog entry")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest itself carries 103 / 0.14.0b")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("109 Kotlin files"),
        "trips: one new module (FieldTrip.kt) — the tree " +
            "stands at 109 Kotlin files (counted $ktCount)")
}

    // ---------- helpers ----------
    fun setDayT(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun tripState(seed: Long, season: String, year: Int):
            Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        setDayT(s, TripCalendar.dayFor(season, year))
        return e to s
    }
    /** Put the player and some classmates physically
     *  somewhere (the save's own fields — presence is the
     *  contract every reader shares). */
    fun stageAt(s: GameState, loc: String,
                kids: List<String>, timeMin: Int) {
        val me = s.agents.values.first { it.isPlayer }
        me.location = loc; me.asleep = false
        me.waypoints.clear()
        for (k in kids) {
            val a = s.agents[k] ?: continue
            a.location = loc; a.asleep = false
            a.waypoints.clear()
        }
        val chap = s.agents[FieldTrip.chaperone(s.absDay)]
        if (chap != null) {
            chap.location = loc; chap.asleep = false
            chap.waypoints.clear()
        }
        s.playerInside = loc == "CityHall"
        s.timeMin = timeMin
    }

    // ---------- the anchors ----------
    run {
        var badDow = 0; var badRange = 0
        for (y in 2026..2100) {
            val f = TripCalendar.fallOrdinal(y)
            val w = TripCalendar.winterOrdinal(y)
            val sp = TripCalendar.springOrdinal(y)
            for (o in listOf(f, w, sp))
                if (FairCalendar.dowOfOrdinal(o) != 5) badDow++
            val fm = keyFromOrdinal(f).substring(4, 6)
            val fd = keyFromOrdinal(f).substring(6, 8).toInt()
            val wm = keyFromOrdinal(w).substring(4, 6)
            val wd = keyFromOrdinal(w).substring(6, 8).toInt()
            val sm = keyFromOrdinal(sp).substring(4, 6)
            val sd = keyFromOrdinal(sp).substring(6, 8).toInt()
            if (fm != "10" || fd !in 8..14) badRange++
            if (wm != "02" || wd !in 1..7) badRange++
            if (sm != "04" || sd !in 15..21) badRange++
        }
        check(badDow == 0 && badRange == 0,
            "trips: every anchor 2026–2100 is a Friday in " +
                "its pocket (fall Oct 8–14, winter Feb 1–7, " +
                "spring Apr 15–21) — three Fridays a year, " +
                "in the published rotation")
        check(TripCalendar.dayFor("fall", 2026) ==
            FairCalendar.absDayOfOrdinal(
                TripCalendar.fallOrdinal(2026)) &&
            FieldTrip.ANN_BACK == 7,
            "trips: the poster goes up exactly seven days " +
                "ahead, on the same calendar math")
    }

    // ---------- the sweep: one lived calendar space ----------
    run {
        var vDance = 0; var vTalent = 0; var vParade = 0
        var vFair = 0; var vCarn = 0; var vFinale = 0
        var vHoliday = 0; var vPlay = 0; var vSchool = 0
        // every finale window, as ordinals: the last seven
        // days of Feb / May / Aug / Nov
        fun finaleWindows(y: Int): List<IntRange> {
            val febEnd = ordinalOfKey("%04d0228".format(y)) +
                if ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0) 1 else 0
            val mayEnd = ordinalOfKey("%04d0531".format(y))
            val augEnd = ordinalOfKey("%04d0831".format(y))
            val novEnd = ordinalOfKey("%04d1130".format(y))
            return listOf(febEnd, mayEnd, augEnd, novEnd)
                .map { (it - 6)..it }
        }
        for (y in 2026..2100) {
            val trips = listOf(
                TripCalendar.fallOrdinal(y),
                TripCalendar.winterOrdinal(y),
                TripCalendar.springOrdinal(y))
            val dance = DanceCalendar.danceOrdinal(y)
            val talent = TripCalendar.nthWeekdayOrdinal(y, 4, 6, 2)
            val parade = TripCalendar.nthWeekdayOrdinal(y, 5, 6, 3)
            val fair = FairCalendar.windowFor(y)
            val carn = CarnivalCalendar.windowFor(y)
            val fins = finaleWindows(y) + finaleWindows(y - 1)
            // the play's whole schedule for the school year
            // whose fall is y (poster → opening), in absDays
            val play = PlayCalendar.scheduleFor(y + 1)
            val playOrds = (play.announceDay..play.openingDay).map {
                FairCalendar.ordinalOfAbsDay(it) }.toSet()
            for (t in trips) {
                if (t == dance) vDance++
                if (t == talent) vTalent++
                if (t == parade) vParade++
                if (t in fair.startOrd..fair.endOrd) vFair++
                if (t in carn.startOrd..carn.endOrd) vCarn++
                if (fins.any { t in it }) vFinale++
                val md = keyFromOrdinal(t).substring(4, 8)
                if (currentHoliday(md) != null) vHoliday++
                if (t in playOrds) vPlay++
                val d = FairCalendar.absDayOfOrdinal(t)
                if (!School.isSchoolDay(d) ||
                    Jobs.weekdayOf(d) != 5) vSchool++
            }
        }
        check(vDance == 0 && vTalent == 0 && vParade == 0,
            "trips sweep: no trip Friday 2026–2100 is the " +
                "dance's Friday, the talent show's Saturday " +
                "or the parade's Saturday — the February " +
                "pocket (trips 1–7, dance 8–14) is the " +
                "closest call and it holds every year")
        check(vFair == 0 && vCarn == 0,
            "trips sweep: no trip Friday lands inside the " +
                "fair's week or the carnival's week, in " +
                "either's own window math")
        check(vFinale == 0 && vHoliday == 0,
            "trips sweep: no trip Friday lands in a finale " +
                "window or on a holiday, judged by the " +
                "town's own holiday table (currentHoliday) " +
                "in the same calendar space")
        check(vPlay == 0 && vSchool == 0,
            "trips sweep: no fall trip touches the play's " +
                "schedule (poster through opening night), " +
                "and every trip day is a Friday school day " +
                "by School's own predicate")
    }

    // ---------- the roster, derived ----------
    run {
        val expect = CharacterSystem.CAST_KIDS
            .filter {
                CharacterSystem.CAST_BANDS[it] == AgeBand.KID
            }.sorted()
        check(FieldTrip.roster() == expect,
            "trips: the roster IS the derivation — every " +
                "cast kid in the KID age band, recomputed " +
                "here from the cast tables, no typed list")
        check(!FieldTrip.roster().contains("Shelley") &&
            !FieldTrip.roster().contains("Kevin McCormick") &&
            !FieldTrip.roster().contains("Michael") &&
            FieldTrip.roster().size == 39,
            "trips: the three young teens are not in the " +
                "class (the band table says so), and the " +
                "class stands at 39")
        check(FieldTrip.chaperone(
            TripCalendar.dayFor("fall", 2026)) == "Garrison" &&
            FieldTrip.chaperone(
                TripCalendar.dayFor("winter", 2027)) == "Garrison" &&
            FieldTrip.chaperone(
                TripCalendar.dayFor("spring", 2027)) == "Garrison",
            "trips: trips are Fridays, and Friday's teacher " +
                "is Garrison — the chaperone is the rotation's " +
                "own answer, not a casting choice")
    }

    // ---------- the claim and the quiet school ----------
    run {
        val (_, s) = tripState(941_001, "fall", 2026)
        s.timeMin = 10 * 60
        check(FieldTrip.gatheringBlock(s, "Stan", 10 * 60)
            ?.location == "StarksPond" &&
            FieldTrip.gatheringBlock(s, "Garrison", 10 * 60)
            ?.location == "StarksPond",
            "trips: at ten on trip morning the claim holds " +
                "a classmate and the chaperone at the pond")
        check(FieldTrip.gatheringBlock(s, "Randy", 10 * 60) == null &&
            FieldTrip.gatheringBlock(s, "Shelley", 10 * 60) == null &&
            FieldTrip.gatheringBlock(s, "Stan", 8 * 60) == null &&
            FieldTrip.gatheringBlock(s, "Stan", 13 * 60) == null,
            "trips: the claim takes nobody outside the " +
                "roster and the chaperone, and it stands " +
                "only 9:00–13:00 — the buses back are a " +
                "hard edge")
        check(School.quietReason(s) == School.QUIET_TRIP &&
            School.lessonStatus(s).kind == School.LS_QUIET &&
            School.beeStatus(s) == School.BS_QUIET,
            "trips: on trip day the school stands quiet " +
                "with the trip as its stated reason — the " +
                "lesson and Friday's bee stand down whole")
        val engSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        check(engSrc.indexOf("Parade.gatheringBlock") <
            engSrc.indexOf("FieldTrip.gatheringBlock") &&
            engSrc.indexOf("FieldTrip.gatheringBlock") <
            engSrc.indexOf("Sleepovers.gatheringBlock"),
            "trips: the claim seats nineteenth in Engine's " +
                "stack — after the parade's, before the " +
                "sleepovers' — pinned from the source order")
    }

    // ---------- a runtime owner yields the day ----------
    run {
        val (_, s) = tripState(941_002, "fall", 2026)
        // stage arc #1's climax due today (the case's own
        // fields — due-ness only, never case content)
        s.shenaniganId = Mystery.FINALE_ID
        for (c in Mystery.CLUES.take(Mystery.TRUTH_MIN_CLUES))
            s.mysteryClues.add(c.id)
        check(School.quietReason(s) == School.QUIET_CASE &&
            FieldTrip.yieldReason(s) == "case" &&
            !FieldTrip.tripLive(s) &&
            s.lifeText["tripYield:fall:2026"] == "case",
            "trips: a case climax due on trip day yields " +
                "the trip whole — the school quiets for the " +
                "CASE (the bigger reason prints), and the " +
                "first consult stamps the yield for the wrap")
        check(FieldTrip.gatheringBlock(s, "Stan", 10 * 60) == null &&
            !FieldTrip.boardOpen(s),
            "trips: a yielded day stands no claim and " +
                "opens no boarding — the bus stays in the lot")
        setDayT(s, TripCalendar.dayFor("fall", 2026) + 1)
        FieldTrip.dailyRollover(s)
        val rec = FieldTrip.record(s, "fall:2026")
        check(rec != null && rec.outcome == "yielded" &&
            rec.yieldWhy == "case" &&
            FieldTrip.phoneBeat(s) == null,
            "trips: the yielded day wraps yielded with " +
                "its reason on the record, and texts nobody")
    }

    // ---------- boarding, the beat, the photograph ----------
    run {
        val (_, s) = tripState(941_003, "fall", 2026)
        val day = s.absDay
        stageAt(s, "Elementary", emptyList(), 9 * 60)
        s.playerInside = true
        check(FieldTrip.boardOpen(s),
            "trips: boarding opens at first bell on a " +
                "live trip day")
        val rodeText = FieldTrip.boardBus(s)
        val me = s.agents.values.first { it.isPlayer }
        check(rodeText != null && FieldTrip.riding(s) &&
            me.location == "StarksPond" && s.timeMin == 9 * 60 + 30,
            "trips: boarding stamps the ride, lands you " +
                "at the site, and charges the ride's real " +
                "30 minutes")
        check(!FieldTrip.boardOpen(s),
            "trips: one boarding per kid — you are on the bus")
        // the class, physically at the pond
        val kids = listOf("Stan", "Kyle", "Butters", "Wendy")
        stageAt(s, "StarksPond", kids, 10 * 60)
        val before = kids.associateWith {
            s.friendship[it] ?: 0 }
        val chapBefore = s.friendship["Garrison"] ?: 0
        check(FieldTrip.menuOption(s, "Garrison") ==
            FieldTrip.OPT_BEAT_START + "Specimen Scan",
            "trips: the chaperone's menu offers the beat " +
                "first — the day's own order")
        check(FieldTrip.startBeat(s) &&
            FieldTrip.beatBeat(s)?.kind == "text",
            "trips: the beat opens on its teaching text")
        FieldTrip.advanceBeat(s)
        var allRight = true
        for (step in 1..FieldTrip.ROUNDS) {
            val beat = FieldTrip.beatBeat(s)
            val opts = FieldTrip.beatOptions(s)
            val right = FieldTrip.correctChoice(s,
                FieldTrip.siteFor("fall"), step)
            if (beat?.kind != "prompt" || opts.size != 3 ||
                opts.none { it.first == right }) allRight = false
            // mid-trip save/reload keeps the beat whole
            if (step == 2) {
                val back = decodeGameState(encodeGameState(s))
                check(FieldTrip.riding(back) &&
                    FieldTrip.beatBeat(back) != null &&
                    back.lifeText["tripPicks:$day"] ==
                        s.lifeText["tripPicks:$day"],
                    "trips: a mid-trip save/reload keeps " +
                        "the ride, the open beat and the " +
                        "picks whole — perishables ride " +
                        "the real save path")
            }
            FieldTrip.answerBeat(s, right)
        }
        check(allRight && FieldTrip.beatDone(s),
            "trips: three rounds, three options each, the " +
                "taught answer always among them — and the " +
                "third answer judges the beat")
        val rec = FieldTrip.record(s, "fall:2026")
        check(rec != null && rec.score == 3 &&
            rec.beatResult == "sharp",
            "trips: a perfect scan reads back sharp, " +
                "three for three, on the record")
        check(kids.all {
                (s.friendship[it] ?: 0) == (before[it] ?: 0) + 1 } &&
            (s.friendship["Garrison"] ?: 0) ==
                chapBefore + 1,
            "trips: the played-through beat pays the " +
                "classmates actually at the site +1 each " +
                "and the chaperone +1 for sharp work — " +
                "nobody else, nowhere else")
        val photosBefore = s.photos.size
        val photoText = FieldTrip.takePhoto(s)
        val rec2 = FieldTrip.record(s, "fall:2026")
        check(photoText != null && s.photos.size == photosBefore + 1 &&
            rec2?.photoId == s.photos.last().id,
            "trips: exactly one class photograph, minted " +
                "through the photo system's own composition, " +
                "its id on the record")
        check(FieldTrip.takePhoto(s) == null &&
            s.photos.size == photosBefore + 1,
            "trips: the camera fires once — a second ask " +
                "mints nothing")
        // the wrap, the paper, the phone
        setDayT(s, day + 1)
        FieldTrip.dailyRollover(s)
        val wrapped = FieldTrip.record(s, "fall:2026")
        check(wrapped?.outcome == "went" &&
            wrapped.beatResult == "sharp",
            "trips: the morning after wraps the day WENT, " +
                "the beat's result carried on the record")
        val beat = FieldTrip.phoneBeat(s)
        check(beat != null && beat.first in FieldTrip.roster() &&
            beat.second == "went",
            "trips: the morning-after text comes from a " +
                "classmate who rode, fact-only, under the " +
                "trip's own kind")
        val line = FieldTrip.paperLine(s, Jobs.weekIndex(day))
        check(line != null && line.contains("Stark's Pond") &&
            FieldTrip.pageLines(s).any {
                it.contains("photograph is in your album") },
            "trips: the week's edition carries the one " +
                "TOWN NEWS line, and the Journal page keeps " +
                "the trip with its photograph")
    }

    // ---------- the museum's counts are the game's own ----------
    run {
        val (_, s) = tripState(941_004, "winter", 2027)
        stageAt(s, "Elementary", emptyList(), 9 * 60)
        s.playerInside = true
        FieldTrip.boardBus(s)
        val site = FieldTrip.siteFor("winter")
        check(site.locId == "CityHall" &&
            FieldTrip.correctChoice(s, site, 1) == "right" &&
            FieldTrip.optionsFor(s, site, 1).any {
                it.first == "right" &&
                    it.second.contains("${LOCATIONS.size} buildings")
            } &&
            FieldTrip.optionsFor(s, site, 3).any {
                it.first == "right" &&
                    it.second.contains(
                        "${CharacterSystem.CAST_KIDS.size +
                            CharacterSystem.CAST_ADULTS.size} faces")
            },
            "trips: the quiz's count questions are counted " +
                "live off the game's own registries — the " +
                "museum's model has LOCATIONS.size buildings " +
                "and its wall the whole cast, by construction")
        val idx = (1..3).map { FieldTrip.roundIndex(s.absDay, it) }
        check(idx.toSet() == setOf(0, 1, 2),
            "trips: the three rounds rotate through the " +
                "three teachings — never the same sign twice " +
                "in a day, at any site")
    }

    // ---------- the farm beat, played wrong on purpose ----------
    run {
        val (_, s) = tripState(941_005, "spring", 2027)
        stageAt(s, "Elementary", emptyList(), 9 * 60)
        s.playerInside = true
        FieldTrip.boardBus(s)
        stageAt(s, "TegridyFarms", listOf("Stan"), 10 * 60)
        val stanBefore = s.friendship["Stan"] ?: 0
        FieldTrip.startBeat(s)
        FieldTrip.advanceBeat(s)
        val site = FieldTrip.siteFor("spring")
        for (step in 1..3) {
            val right = FieldTrip.correctChoice(s, site, step)
            val wrong = FieldTrip.beatOptions(s)
                .first { it.first != right }.first
            FieldTrip.answerBeat(s, wrong)
        }
        val rec = FieldTrip.record(s, "spring:2027")
        check(rec != null && rec.score == 0 &&
            rec.beatResult == "easy" &&
            (s.friendship["Stan"] ?: 0) == stanBefore + 1 &&
            (s.friendship["Garrison"] ?: 0) == 0,
            "trips: a whiffed beat still pays the room " +
                "its sprinkle (played through is played " +
                "through) — but the chaperone's bump is " +
                "earned by sharp work only")
    }

    // ---------- missed, honestly ----------
    run {
        val (_, s) = tripState(941_006, "fall", 2026)
        val day = s.absDay
        setDayT(s, day + 1)
        FieldTrip.dailyRollover(s)
        val rec = FieldTrip.record(s, "fall:2026")
        val beat = FieldTrip.phoneBeat(s)
        check(rec?.outcome == "missed" &&
            beat != null && beat.second == "missed" &&
            FieldTrip.paperLine(s, Jobs.weekIndex(day))
                ?.contains("wasn't on the bus") == true,
            "trips: never boarding wraps MISSED — the " +
                "record, the text and the paper all say " +
                "so plainly, and nothing pays out for it")
        // a fresh save carries no trip state at all and
        // joins the next trip like anyone
        val (_, fresh) = tripState(941_007, "fall", 2026)
        check(fresh.lifeText.keys.none {
            it.startsWith("trip") } &&
            FieldTrip.record(fresh, "fall:2026") == null &&
            FieldTrip.pageLines(fresh).isNotEmpty(),
            "trips: a pre-0.14.0b save loads with an empty " +
                "trip record — additive-only, nothing to migrate")
    }

    // ---------- the unattended year ----------
    run {
        val (e, s) = tripState(941_008, "fall", 2026)
        // start a week before the first trip so its whole
        // cycle (poster, day, wrap) lives inside the drive
        setDayT(s, s.absDay - 8)
        var days = 0
        while (days < 400) { e.onNewDay(s); days++ }
        val recs = FieldTrip.allRecords(s)
        check(recs.count { it.outcome == "missed" } >= 3 &&
            recs.all { it.outcome.isNotEmpty() },
            "trips soak: an unattended 400 days wraps at " +
                "least three trips (fall, winter, spring) " +
                "as missed — the bus runs on time whether " +
                "or not anyone rides, and every record " +
                "settles (got ${recs.size} records)")
    }

    // ---------- wiring ----------
    run {
        val gameSrc = File(root,
            "src/com/hunt3r/southparktown/GameActivity.kt").readText()
        val engineSrc = File(root,
            "src/com/hunt3r/southparktown/Engine.kt").readText()
        val phoneSrc = File(root,
            "src/com/hunt3r/southparktown/Phone.kt").readText()
        val paperSrc = File(root,
            "src/com/hunt3r/southparktown/Newspaper.kt").readText()
        val journalSrc = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
        val schoolSrc = File(root,
            "src/com/hunt3r/southparktown/School.kt").readText()
        check(gameSrc.contains("FieldTrip.boardOpen(state)") &&
            gameSrc.contains("FieldTrip.boardBus(state)") &&
            gameSrc.contains("FieldTrip.menuOption(state, npcName)") &&
            gameSrc.contains("presentTripBeat()") &&
            gameSrc.contains("FieldTrip.lookText(state, me.location)"),
            "trips wiring: boarding rides the classroom " +
                "board, the trip's business rides the " +
                "chaperone's person menu, the beat presents " +
                "in the lesson idiom, and Look carries the " +
                "poster and the dressed site")
        check(engineSrc.contains(
                "FieldTrip.gatheringBlock(state, a.name, timeMin)") &&
            engineSrc.contains("FieldTrip.dailyRollover(state)") &&
            schoolSrc.contains("QUIET_TRIP") &&
            schoolSrc.contains("FieldTrip.isTripDay(state)"),
            "trips wiring: the claim and the rollover are " +
                "in Engine, and the school's quiet day knows " +
                "the trip by its pure calendar")
        check(phoneSrc.contains("const val FIELDTRIP") &&
            phoneSrc.contains("FieldTrip.phoneBeat(state)") &&
            "fieldtrip" in Phone.TRIGGERS &&
            Phone.MAX_TEXTS == 220 &&
            paperSrc.contains("FieldTrip.paperLine(state, week)") &&
            journalSrc.contains("FieldTrip.pageLines(state)") &&
            journalSrc.contains("🚌 FIELD TRIPS"),
            "trips wiring: one phone trigger (the budget " +
                "stands at 220, the sender set untouched), " +
                "one paper hook, the Journal page")
        check(TalkGate.Rail.values().size == 11,
            "trips wiring: TalkGate keeps its eleven rails " +
                "— the trip adds none; its business rides " +
                "the board, the menu and the morning")
    }
}

private fun sectionV0140d(root: String) {
// ================= v0.14.0d: your birthday =================
// Queue #14 item 4. The new kid's birthday, derived whole
// from the save's arrival record (Family's famArrivalDay):
// the anniversary of arrival, every 365 game days, day-
// counted so leap years cannot move it, the first one a
// full year in and nothing retroactive. The morning is the
// household's — exactly one real snack cake (Birthdays'
// own CAKE_ITEM) stamped per year so a birthday-morning
// reload can never duplicate it, a card kept verbatim on
// the Journal page, and each parent's marking at +2 in
// the famPts lane only. Wishes ride the owed-lines seam
// (no twelfth rail), derived by the wisher's friendship
// band off Relationships.tierOf, and move nothing but
// their own once-per-person-per-birthday stamp — pinned
// byte-for-byte. The evening party, when the crew is
// non-empty and the town lets the night be yours, rides
// the DINNER rail with a payload beside the cast parties'
// and is claimed at the sleepover claim's own seat (no
// twenty-first seat), self-guarded on the crew's occupied
// oracle; a yielded birthday still fires its whole
// morning, with the reason derived on the birthday
// morning and stamped (Dance's guarded pattern). Records:
// one TOWN NEWS line in the birthday week's edition, one
// PLAYERBDAY phone text on the morning itself, and the
// Journal 🎂 YOUR BIRTHDAY page.
println("== v0.14.0d: your birthday — Queue #14 item 4 ==")
val readme = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readme.contains("### v0.14.0d"),
    "v0.14.0d: the README carries this build's changelog entry")
check(readme.contains("## Status — v0.14.0d"),
    "v0.14.0d: the README carries this build's status section")
check(tuning.contains("Your birthday (v0.14.0d"),
    "v0.14.0d: the tuning ledger carries the birthday's entry")
val manifestSrc = File(root, "AndroidManifest.xml").readText()
check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 105 / 0.14.0d")
val ktCount = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCount == 137 && readme.contains("111 Kotlin files"),
    "v0.14.0d: the source tree and its description agree — " +
        "111 Kotlin files (PlayerBirthday.kt joined) (counted $ktCount)")
val pbSrc = File(root,
    "src/com/hunt3r/southparktown/PlayerBirthday.kt").readText()
check(pbSrc.contains("object PlayerBirthday") &&
    pbSrc.contains("data class BdayHit") &&
    pbSrc.contains("Birthdays.CAKE_ITEM"),
    "birthday: the module stands whole — and its gift reads " +
        "the cast parties' cake constant, never re-typed")
val engSrcD = File(root,
    "src/com/hunt3r/southparktown/Engine.kt").readText()
check(engSrcD.indexOf("Sleepovers.gatheringBlock(state, a.name, timeMin)") <
    engSrcD.indexOf("PlayerBirthday.gatheringBlock(state, a.name, timeMin)") &&
    engSrcD.indexOf("PlayerBirthday.gatheringBlock(state, a.name, timeMin)") <
    engSrcD.indexOf("Stand.gatheringBlock(state, a.name, timeMin)"),
    "birthday claim: NO new agenda seat — the party's claim " +
        "is consulted at the sleepovers' own seat (after the " +
        "sleepovers', before the stand's) in Engine's one " +
        "living stack, the way Birthdays' rides Dinners'")
check(engSrcD.contains("PlayerBirthday.dailyRollover(state)"),
    "birthday rollover: Engine's morning runs the birthday's " +
        "wrap and landing beside the sleepovers'")
val crewSrcD = File(root,
    "src/com/hunt3r/southparktown/Crew.kt").readText()
check(crewSrcD.contains("PlayerBirthday.claims(state, name)"),
    "birthday claim: the crew's occupied oracle reads the " +
        "party's claim, beside the sleepovers'")
val gateSrcD = File(root,
    "src/com/hunt3r/southparktown/TalkGate.kt").readText()
check(gateSrcD.contains("bdayHit") &&
    gateSrcD.contains("PlayerBirthday.talkStepFor(state, npcName)") &&
    gateSrcD.contains("PlayerBirthday.wishLine(state, npcName)"),
    "birthday gate: the party beats ride the DINNER rail " +
        "with a payload, and the wishes ride the owed-lines " +
        "seam — both in TalkGate, neither a new rail")
check(TalkGate.Rail.values().size == 11,
    "birthday gate: TalkGate keeps its eleven rails")
val actSrcD = File(root,
    "src/com/hunt3r/southparktown/GameActivity.kt").readText()
check(actSrcD.contains("PlayerBirthday.judgeTalk(state, kidName)") &&
    actSrcD.contains("PlayerBirthday.familyLine(state, parent)") &&
    actSrcD.contains("PlayerBirthday.lookText(state, me.location)"),
    "birthday wiring: the activity judges the party beats, " +
        "opens the family sheet on the parents' line, and " +
        "hides the cake beat in the Look at home")
val phoneSrcD = File(root,
    "src/com/hunt3r/southparktown/Phone.kt").readText()
check(Phone.PLAYERBDAY in Phone.TRIGGERS &&
    phoneSrcD.contains("PlayerBirthday.phoneBeat(state)"),
    "birthday phone: the PLAYERBDAY trigger stands in the " +
        "closed set and the harvest carries the one beat")
check(Phone.MAX_TEXTS == 220,
    "birthday phone: the inbox cap stands at 220 — the " +
        "birthday spends the existing budget, never raises it")
check(File(root, "src/com/hunt3r/southparktown/Newspaper.kt")
        .readText().contains("PlayerBirthday.paperLine(state, week)") &&
    File(root, "src/com/hunt3r/southparktown/JournalActivity.kt")
        .readText().contains("PlayerBirthday.pageLines(state)") &&
    File(root, "src/com/hunt3r/southparktown/House.kt")
        .readText().contains("PlayerBirthday.morningNote(state)"),
    "birthday records: the paper calls the line in TOWN " +
        "NEWS, the Journal renders the page, and the house " +
        "report carries the morning note")

// ---------- helpers ----------
fun setDayD(s: GameState, absDay: Int) {
    s.absDay = absDay
    val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(absDay))
    s.gameYear = key.substring(0, 4).toInt()
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
    s.todayKey = key
}
fun bdayStateD(seed: Long): Pair<Engine, GameState> {
    val e = Engine(seed)
    val s = e.newState()
    e.createPlayer(s, "Veteran", DEFAULT_APPEARANCE)
    return e to s
}
fun arrivedD(s: GameState, anchor: Int = 3) {
    s.life["famArrived"] = 1
    s.life["famArrivalDay"] = anchor
}
fun stageAtD(s: GameState, names: List<String>, place: String) {
    for (a in s.agents.values) if (a.name in names) {
        a.location = place
        a.asleep = false; a.waypoints.clear()
    }
}
fun playerToD(s: GameState, place: String, min: Int) {
    val me = s.agents.values.first { it.isPlayer }
    me.location = place; s.playerInside = true
    me.asleep = false; me.waypoints.clear()
    s.timeMin = min
}

// ---------- the date, derived ----------
run {
    val (_, s) = bdayStateD(14041)
    // the preview is pure: asking never stamps the record
    check(PlayerBirthday.anchorDay(s) == Family.ARRIVAL_ABS_DAY &&
        !s.life.containsKey("famArrivalDay"),
        "derivation: an unstamped save previews the arrival " +
            "day Family will stamp — and the asking writes " +
            "nothing")
    // the date reads the arrival record and nothing else:
    // move the record, and the birthday moves with it
    arrivedD(s, 10)
    check(PlayerBirthday.anchorDay(s) == 10 &&
        PlayerBirthday.isBirthdayDay(375, 10) &&
        !PlayerBirthday.isBirthdayDay(374, 10) &&
        !PlayerBirthday.isBirthdayDay(376, 10) &&
        !PlayerBirthday.isBirthdayDay(10, 10) &&
        PlayerBirthday.isBirthdayDay(740, 10),
        "derivation: birthdays fire on arrival + 365k for " +
            "k ≥ 1 — the arrival day itself is not one, and " +
            "the day before and after are not either")
    setDayD(s, 375)
    check(PlayerBirthday.isBirthday(s) &&
        PlayerBirthday.birthdayNumber(s) == 1,
        "derivation: on arrival + 365 the save is having " +
            "its FIRST birthday — one full year in")
    s.life["famArrivalDay"] = 11
    check(!PlayerBirthday.isBirthday(s),
        "derivation: the same day under a different arrival " +
            "record is not a birthday — the record alone decides")
    // spacing: exactly ten birthdays in any ten years, each
    // exactly 365 days after the last — two never stack
    for (a in listOf(0, 3, 10, 100)) {
        val days = (a + 1..a + 3650)
            .filter { PlayerBirthday.isBirthdayDay(it, a) }
        check(days.size == 10 &&
            days.zipWithNext().all { (x, y) -> y - x == 365 },
            "derivation: from anchor $a, ten years hold " +
                "exactly ten birthdays, each 365 days after " +
                "the last — spacing by construction")
    }
    // leap-proof, by construction: the derivation is day-
    // counted arithmetic and never consults the calendar,
    // so the span absDay 3..2003 — which crosses February
    // 29, 2028 (and 2032) in lived calendar space — keeps
    // the 365-day period exactly
    check((4..2000).all {
            PlayerBirthday.isBirthdayDay(it + 365, 3) ==
                PlayerBirthday.isBirthdayDay(it, 3) },
        "derivation: the 365-day period holds across the " +
            "leap days the lived calendar grows — day-counted, " +
            "not calendar-dated, so February 29ths cannot " +
            "move, skip or double a birthday")
    val (_, s2) = bdayStateD(14042)
    arrivedD(s2, 3)
    setDayD(s2, 367)
    check(PlayerBirthday.birthdaysReached(s2) == 0 &&
        PlayerBirthday.daysUntilBirthday(s2) == 1,
        "derivation: the day before the first birthday, " +
            "none are on the record and one day remains")
    setDayD(s2, 368)
    check(PlayerBirthday.birthdaysReached(s2) == 1 &&
        PlayerBirthday.daysUntilBirthday(s2) == 0 &&
        PlayerBirthday.nextBirthdayDay(s2) == 368,
        "derivation: on the day itself it counts as reached, " +
            "and the next-birthday reader returns today")
    setDayD(s2, 369)
    check(PlayerBirthday.birthdaysReached(s2) == 1 &&
        PlayerBirthday.nextBirthdayDay(s2) == 733 &&
        PlayerBirthday.daysUntilBirthday(s2) == 364,
        "derivation: the morning after, the countdown " +
            "already points at the next one, 364 days out")
}

// ---------- the gift and the card ----------
run {
    val (_, s) = bdayStateD(14043)
    arrivedD(s, 3)
    setDayD(s, 367)
    PlayerBirthday.dailyRollover(s)
    check((s.inventory[PlayerBirthday.GIFT_ITEM] ?: 0) == 0 &&
        PlayerBirthday.keptCard(s) == null,
        "gift: the day before the birthday, nothing has landed")
    setDayD(s, 368)
    PlayerBirthday.dailyRollover(s)
    check(PlayerBirthday.GIFT_ITEM == Birthdays.CAKE_ITEM &&
        itemById(PlayerBirthday.GIFT_ITEM) != null &&
        (s.inventory[PlayerBirthday.GIFT_ITEM] ?: 0) == 1,
        "gift: on the birthday morning exactly ONE real " +
            "snack cake — Birthdays' own cake item, a live " +
            "ItemDef — is in your pack, Mom's bake")
    check(PlayerBirthday.keptCard(s) == PlayerBirthday.cardFor(1) &&
        (s.life["pbCardYear"] ?: 0) == 1,
        "card: the household's card arrived the same " +
            "morning and is kept, verbatim, for the page")
    // the reload pin: through the REAL save path, then a
    // worst-case rollover re-entry — still exactly one
    val back = decodeGameState(encodeGameState(s))
    back.life.remove("pbRollDay")
    PlayerBirthday.dailyRollover(back)
    check((back.inventory[PlayerBirthday.GIFT_ITEM] ?: 0) == 1 &&
        PlayerBirthday.keptCard(back) == PlayerBirthday.cardFor(1),
        "gift: a save/reload on the birthday morning yields " +
            "exactly one cake — the per-year stamp, not the " +
            "rollover guard, is what keeps it single")
    // and the second birthday gifts its own, a year later
    setDayD(back, 733)
    PlayerBirthday.dailyRollover(back)
    check((back.inventory[PlayerBirthday.GIFT_ITEM] ?: 0) == 2 &&
        PlayerBirthday.keptCard(back) == PlayerBirthday.cardFor(2),
        "gift: the second birthday lands its own cake and " +
            "its own card — one per year, every year")
}

// ---------- the parents' morning beat ----------
run {
    val (_, s) = bdayStateD(14044)
    arrivedD(s, 3)
    // absDay 368 is a family-dinner night (rhythm day) —
    // the party yields that night (below), and the
    // household beat fires anyway: the household is yours
    setDayD(s, 368)
    PlayerBirthday.dailyRollover(s)
    s.timeMin = 8 * 60
    val momPts = Family.points(s, Family.MOM)
    val dadPts = Family.points(s, Family.DAD)
    val momLine = PlayerBirthday.familyLine(s, Family.MOM)
    val dadLine = PlayerBirthday.familyLine(s, Family.DAD)
    check(momLine != null && dadLine != null &&
        momLine.speaker == Family.MOM && dadLine.speaker == Family.DAD,
        "parents: on the birthday morning, at home, each " +
            "parent marks the day before anything else — " +
            "even on a night the party yields")
    check(Family.points(s, Family.MOM) == momPts + 2 &&
        Family.points(s, Family.DAD) == dadPts + 2 &&
        !s.friendship.containsKey(Family.MOM) &&
        !s.friendship.containsKey(Family.DAD),
        "parents: the warmth lands at +2 each in the " +
            "family's own famPts lane — state.friendship " +
            "never learns their names (the family wall)")
    check(PlayerBirthday.familyLine(s, Family.MOM) == null &&
        PlayerBirthday.familyLine(s, Family.DAD) == null &&
        Family.points(s, Family.MOM) == momPts + 2,
        "parents: once per parent per birthday — a second " +
            "talk the same morning is the everyday greeting, " +
            "and pays nothing more")
    // away at work, the line waits — it is a home beat
    val (_, s2) = bdayStateD(14045)
    arrivedD(s2, 3)
    setDayD(s2, 733)
    s2.timeMin = 13 * 60
    check(PlayerBirthday.familyLine(s2, Family.MOM) == null,
        "parents: at one on a weekday Mom is at the bank — " +
            "the marking is a home beat and does not chase her")
    s2.timeMin = 8 * 60
    check(PlayerBirthday.familyLine(s2, Family.MOM) != null,
        "parents: home in the morning, the line is hers to give")
    setDayD(s2, 734)
    check(PlayerBirthday.familyLine(s2, Family.DAD) == null,
        "parents: the day after, no line — it is the " +
            "birthday's, not the week's")
}

// ---------- the wishes ----------
run {
    val (_, s) = bdayStateD(14046)
    arrivedD(s, 3)
    // absDay 733 is a Wednesday — a school day: the wishes
    // read normally, wherever people are met
    setDayD(s, 733)
    s.friendship["Stan"] = 70      // close friend
    s.friendship["Kyle"] = 40      // friend
    s.friendship["Wendy"] = 15     // acquaintance
    s.friendship["Kenny"] = 12     // acquaintance, own register
    s.friendship["Timmy"] = 35     // friend, own register
    s.friendship["Cartman"] = 0    // stranger: doesn't know
    // the band table, off the town's own tiers
    val bands = listOf(60 to Relationships.CLOSE_FRIEND,
        59 to Relationships.FRIEND, 30 to Relationships.FRIEND,
        29 to Relationships.ACQUAINTANCE,
        10 to Relationships.ACQUAINTANCE, 9 to -1)
    var bandsOk = true
    for ((pts, want) in bands) {
        s.friendship["Craig"] = pts
        if (PlayerBirthday.wishBand(s, "Craig") != want)
            bandsOk = false
    }
    s.friendship.remove("Craig")
    check(bandsOk,
        "wishes: the bands derive from Relationships.tierOf — " +
            "close at 60, friend at 30, acquaintance at 10, " +
            "and below that, silence")
    // a wish moves NOTHING but its own stamp — byte-pinned
    val friendBefore = HashMap(s.friendship)
    val invBefore = HashMap(s.inventory)
    val lifeBefore = HashMap(s.life)
    val textBefore = HashMap(s.lifeText)
    val wish = PlayerBirthday.wishLine(s, "Stan")
    check(wish != null && wish.speaker == "Stan" &&
        wish.text in PlayerBirthday.WISH_CLOSE,
        "wishes: a close friend wishes warm — the CLOSE " +
            "bank, in their own name")
    check(s.friendship == friendBefore && s.inventory == invBefore &&
        s.lifeText == textBefore &&
        s.life == lifeBefore + ("pbWishK:Stan" to 2),
        "wishes: byte-pinned — friendship, inventory and " +
            "every text record are untouched, and the life " +
            "map gains exactly the one wish stamp (no coins " +
            "move either: the purse rides these same maps)")
    check(PlayerBirthday.wishLine(s, "Stan") == null,
        "wishes: at most once per person per birthday")
    val kyleWish = PlayerBirthday.wishLine(s, "Kyle")
    val wendyWish = PlayerBirthday.wishLine(s, "Wendy")
    check(kyleWish != null && kyleWish.text in PlayerBirthday.WISH_FRIEND &&
        wendyWish != null &&
        wendyWish.text in PlayerBirthday.WISH_ACQUAINTANCE,
        "wishes: friend-band and acquaintance-band wishes " +
            "come from their own banks")
    check(PlayerBirthday.wishLine(s, "Cartman") == null &&
        PlayerBirthday.wishText(s, "Cartman") == null,
        "wishes: a stranger doesn't know it's your birthday — " +
            "no wish, and none derivable")
    val kennyWish = PlayerBirthday.wishLine(s, "Kenny")
    val timmyWish = PlayerBirthday.wishLine(s, "Timmy")
    check(kennyWish != null &&
        kennyWish.text in PlayerBirthday.WISH_KENNY &&
        timmyWish != null &&
        timmyWish.text == PlayerBirthday.WISH_TIMMY,
        "wishes: Kenny wishes muffled and Timmy by " +
            "proclamation — their registers override any band")
    val wished = PlayerBirthday.wishers(s, 2)
    check(wished.toSet() == setOf("Stan", "Kyle", "Wendy",
            "Kenny", "Timmy") &&
        wished == wished.sortedBy { KID_ORDER.indexOf(it) },
        "wishes: the year's wishers read back off the " +
            "stamps, in roster order, for the page")
    // the seam itself: the conversation's owed lines carry it
    val (_, s2) = bdayStateD(14047)
    arrivedD(s2, 3)
    setDayD(s2, 733)
    s2.friendship["Kyle"] = 40
    val expected = PlayerBirthday.wishText(s2, "Kyle")
    check(expected != null && TalkGate.owedLines(s2, "Kyle")
            .any { it.text == expected },
        "wishes: TalkGate.owedLines carries the wish into " +
            "the conversation — a seam, not a rail")
    setDayD(s2, 734)
    check(PlayerBirthday.wishLine(s2, "Kyle") == null,
        "wishes: the day after, the year's wishes are spent")
}

// ---------- the party ----------
// A full night, staged the way the evening stages itself:
// the rollover lands the gift, the crew is claimed to the
// house, the beats land Talk / Look / Talk.
run {
