private fun sectionV0140e(root: String) {
// ================= v0.14.0e: the clubhouse =================
// Queue #14 item 5. The crew claims a spot that rotates
// by season off the town's one season truth — treehouse
// at Kid's Park (spring/fall), the Marsh garage (summer),
// your basement (winter) — no new map location, every
// spot a fixture at a place the town already has. One
// new agenda claim seated after the stand's, before
// the crew's own hook (the twenty-first call in the
// stack when it was pinned; the twenty-second since
// v0.15.0f seated the gallery show above the
// sleepovers), self-guarded on
// Crew.busyReason read whole plus a veto pass over every
// claim seated above it, and priced like a rendezvous:
// Walk.routeMinutes from where a member actually is must
// land by the window's close or the member is not
// claimed — nobody teleports. Three beats (Settle In /
// The Project / Crew Business) ride the crew-talk channel
// and the Look — TalkGate keeps its eleven rails, proven
// below. Crew-only talk banks are fact-bound (the spot,
// who is here, Crew's own tallies) and non-members get
// silence from them. The wrap pays nothing (Crew's
// arrival rate is the day's pay, never paid twice),
// plants the topic, and writes the record; the records
// are the Journal page and ONE morning-after line — no
// phone text, no paper line, by stated design. An empty
// crew stands the whole thing down politely.
println("== v0.14.0e: the clubhouse — Queue #14 item 5 ==")
val readme = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readme.contains("### v0.14.0e"),
    "v0.14.0e: the README carries this build's changelog entry")
check(readme.contains("## Status — v0.14.0e"),
    "v0.14.0e: the README carries this build's status section")
check(tuning.contains("The clubhouse (v0.14.0e"),
    "v0.14.0e: the tuning ledger carries the clubhouse's entry")
val manifestSrc = File(root, "AndroidManifest.xml").readText()
check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 106 / 0.14.0e")
val ktCount = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCount == 137 && readme.contains("112 Kotlin files"),
    "v0.14.0e: the source tree and its description agree — " +
        "112 Kotlin files (Clubhouse.kt joined) (counted $ktCount)")
val clubSrc = File(root,
    "src/com/hunt3r/southparktown/Clubhouse.kt").readText()
check(clubSrc.contains("object Clubhouse") &&
    clubSrc.contains("data class Spot") &&
    clubSrc.contains("Walk.routeMinutes"),
    "clubhouse: the module stands whole — and its price " +
        "reads the Walk graph's own minutes, never re-typed")
val engSrcE = File(root,
    "src/com/hunt3r/southparktown/Engine.kt").readText()
check(engSrcE.indexOf("Stand.gatheringBlock(state, a.name, timeMin)") <
    engSrcE.indexOf("Clubhouse.gatheringBlock(state, a.name, timeMin)") &&
    engSrcE.indexOf("Clubhouse.gatheringBlock(state, a.name, timeMin)") <
    engSrcE.indexOf("\n            Crew.gatheringBlock(state, a.name, timeMin)"),
    "clubhouse claim: the claim seats after the stand's, " +
        "before the crew's own hook — in Engine's one " +
        "living stack (re-pinned v0.15.0f: the gallery " +
        "show's new claim above the sleepovers makes " +
        "this the twenty-second call in the stack; it " +
        "was the twenty-first before)")
check(engSrcE.contains("Clubhouse.dailyRollover(state)"),
    "clubhouse rollover: Engine's morning runs the wrap " +
        "beside the crew's own dispersal")
val gateSrcE = File(root,
    "src/com/hunt3r/southparktown/TalkGate.kt").readText()
check(TalkGate.Rail.values().size == 11 &&
    !gateSrcE.contains("Clubhouse"),
    "clubhouse gate: TalkGate keeps its eleven rails and " +
        "never learns the clubhouse's name — the beats ride " +
        "the crew-talk channel and the Look, not a rail")
val actSrcE = File(root,
    "src/com/hunt3r/southparktown/GameActivity.kt").readText()
check(actSrcE.contains("Clubhouse.talkLines(state, npcName)") &&
    actSrcE.contains("Clubhouse.lookText(state, me.location)"),
    "clubhouse wiring: the activity speaks the talk beats " +
        "through the crew-talk channel and hides the " +
        "project beat in the Look at the spot")
check(File(root, "src/com/hunt3r/southparktown/JournalActivity.kt")
        .readText().contains("Clubhouse.pageLines(state)") &&
    File(root, "src/com/hunt3r/southparktown/House.kt")
        .readText().contains("Clubhouse.morningNote(state)"),
    "clubhouse records: the Journal renders the page and " +
        "the house report carries the one morning line — " +
        "and there is no phone or paper surface by design")
check(!File(root, "src/com/hunt3r/southparktown/Phone.kt")
        .readText().contains("Clubhouse") &&
    !File(root, "src/com/hunt3r/southparktown/Newspaper.kt")
        .readText().contains("Clubhouse") &&
    Phone.MAX_TEXTS == 220,
    "clubhouse records: the phone and the paper never " +
        "learn the clubhouse's name — a daily afternoon " +
        "spends no MAX_TEXTS and headlines nothing")

// ---------- helpers ----------
fun setDayE(s: GameState, absDay: Int) {
    s.absDay = absDay
    val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(absDay))
    s.gameYear = key.substring(0, 4).toInt()
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
    s.todayKey = key
}
fun clubStateE(seed: Long): Pair<Engine, GameState> {
    val e = Engine(seed)
    val s = e.newState()
    e.createPlayer(s, "Veteran", DEFAULT_APPEARANCE)
    return e to s
}
fun stageAtE(s: GameState, names: List<String>, place: String) {
    for (a in s.agents.values) if (a.name in names) {
        a.location = place
        a.destination = place
        a.asleep = false; a.waypoints.clear()
    }
}
fun playerToE(s: GameState, place: String, min: Int) {
    val me = s.agents.values.first { it.isPlayer }
    me.location = place; s.playerInside = true
