// ---------- the pattern-proof: independent recomputation ----------
// The verdict rule, recomputed here from the items'
// raw fields under rules restated in the test — a
// second implementation of loss, hand and fit, shapes,
// grading and verdicts. Over all 4,096 subsets of the
// evidence, committed readings (truth on even subsets,
// the next reading around on odd ones) must grade
// IDENTICALLY under both implementations, every time.
fun shape12T(item: Mystery12.Return12): String {
    val card = Mystery12.HANDS12.first { it.kid == item.recipient }
    val feats = item.handFeatures
    val forms = card.forms.count { it in feats }
    val mustOk = card.must.all { it in feats }
    val nev = card.nevers.any { it in feats }
    val tel = card.tells.filter { it in feats }
    val drill = feats.count { it in Mystery12.DRILL_FORMS12 }
    val handT = when {
        tel.isNotEmpty() && forms >= 2 -> "copied"
        tel.isEmpty() && !nev && mustOk && forms >= 2 -> "true"
        tel.isEmpty() && !nev && drill >= 3 && forms >= 1 -> "drill"
        else -> "strange"
    }
    val lossT = item.filedKind != null && item.filedKind == item.kind
    val fitT = item.claimedMarks.toSet() == item.itemMarks.toSet()
    return when {
        tel.isNotEmpty() && forms >= 2 -> "planted"
        tel.isEmpty() && lossT && fitT &&
            (handT == "true" || handT == "drill") -> "true"
        tel.isEmpty() && !nev && lossT && !fitT -> "mistake"
        else -> "mixed"
    }
}
fun verdict12T(held: Set<String>, chapter: Int,
               item: Mystery12.Return12, call: String?): String {
    if (call == null) return "OPEN"
    val proof = Mystery12.CLUE12_BY_ID[item.proofBy]!!
    val live = proof.id in held && chapter > proof.unlockChapter
    if (!live) return "COMMITTED"
    return if (call == shape12T(item)) "PROVEN" else "REFUTED"
}
