    }
    val un = eng12.newState()
    un.arc12Started = true; un.arc12Chapter = 4
    for (id in held) un.mystery12Clues.add(id)
    for (item in items12)
        if (Mystery12.letterVerdict12(un, item) !=
            verdict12T(held, 4, item, null)) sweepBad12++
}
