// ================= v0.14.0g: polish & performance #14 =================
/** Queue #14 item 7, the QUEUE CLOSER — an audit-first
 *  pass in the polish #11–#13 tradition over the whole
 *  queue: the reflections readers, three field trips,
 *  the film festival, your birthday, the clubhouse and
 *  the returns case. The only production change is
 *  disposition one below, sanctioned by the brief.
 *  Disposition one — pen pals' post-settlement reply
 *  window: FIXED in-fiction. The special letters (the
 *  settlement's word, the thank-you after the visit)
 *  were stored uncounted by palUnanswered and gated by
 *  live(), so a thank-you landing after the June 1
 *  settlement could never be answered until October's
 *  box returned (polish #13's soak closed 61 of 62 for
 *  exactly this). They arrive at the HOME mailbox, so
 *  the reply now rides home mail: deliverSpecial stamps
 *  palHomeMail, canReply honors it in any season, the
 *  send clears it, and a fresh October signup folds a
 *  still-waiting home letter away. Dormancy rides
 *  whole — a home-mail reply to a dormant route IS the
 *  revival letter (+1, route reopened). Cadence,
 *  warmth and the archive are untouched.
 *  Disposition two — the pen-pal fabricated-record gap
 *  for the dance/talent/parade/carnival fact kinds:
 *  CLOSED below with fabricated records staged through
 *  the modules' own record paths and formats. */
private fun sectionV0140g(root: String) {
println("== v0.14.0g: polish & performance #14 — the town, audited in the mirror ==")

// ---------- shared fixtures ----------
val readme = File(root, "docs/CHANGELOG.md").readText()
fun setDayH(s: GameState, absDay: Int) {
    s.absDay = absDay
    val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(absDay))
    s.todayKey = key
    s.gameYear = key.substring(0, 4).toInt()
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
}
fun absOfKeyH(key: String): Int =
    FairCalendar.absDayOfOrdinal(ordinalOfKey(key))
fun auditStateH(seed: Long): Pair<Engine, GameState> {
    val e = Engine(seed)
    val s = e.newState()
    e.createPlayer(s, "Veteran", DEFAULT_APPEARANCE)
    return e to s
}
fun retiredCountH(st: GameState): Int = listOf(
    st.arcRetired, st.arc2Retired, st.arc3Retired,
    st.arc4Retired, st.arc5Retired, st.arc6Retired,
    st.arc7Retired, st.arc8Retired, st.arc9Retired,
    st.arc10Retired, st.arc11Retired, st.arc12Retired)
    .count { it }

// ---------- the release shape ----------
run {
    val manifest = File(root, "AndroidManifest.xml").readText()
    check(manifest.contains("versionCode=\"${Version.VERSION_CODE}\"") &&
        manifest.contains("versionName=\"${Version.VERSION_NAME}\""),
        "release: the manifest carries 108 / 0.14.0g — " +
            "one code past the returns case")
    check(readme.contains("### v0.14.0g") &&
        readme.contains("## Status — v0.14.0g"),
        "release: the README carries this polish in " +
            "its changelog and its status line")
    val ktCount = File(root,
        "src/com/hunt3r/southparktown")
        .listFiles()?.count {
            it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137,
        "release: polish adds no module — the tree " +
            "stands at 113 Kotlin files (counted $ktCount)")
}

// ---------- disposition one: the home-mail reply ----------
run {
    // the visit path, driven whole: sign up in October,
    // answer everything, earn the visit, and meet the
    // thank-you the morning after it ends
    val (_, v) = auditStateH(140_101)
    setDayH(v, absOfKeyH("20261005"))
    check(PenPals.signUp(v) != null,
        "home mail: (staging) the October signup lands")
    var thanksOutBefore = -1
    var thanksOutAfter = -1
    var dA = v.absDay
    val endA = absOfKeyH("20270620")
    while (dA < endA) {
        dA++
        setDayH(v, dA)
        PenPals.dailyRollover(v)
        if (PenPals.canReply(v)) {
            if (PenPals.homeMailPending(v) &&
                !PenPals.live(v) && thanksOutBefore < 0)
                thanksOutBefore = PenPals.lettersOut(v)
            val sent = PenPals.sendReply(v,
                PenPals.TONES[PenPals.lettersOut(v) % 3])
            if (sent != null && thanksOutBefore >= 0 &&
                thanksOutAfter < 0)
                thanksOutAfter = PenPals.lettersOut(v)
        }
    }
    check((v.life["palVisitYear"] ?: 0) > 0 &&
        PenPals.latestLetter(v) == PenPals.THANKS_LETTER,
        "home mail: the driven year earned the visit, " +
            "and the last letter in the box is her " +
            "thank-you for it")
    check(thanksOutBefore >= 0 &&
        thanksOutAfter - thanksOutBefore == 1 &&
        PenPals.points(v) == 100,
        "home mail: the thank-you WAS answered after " +
            "the settlement — exactly one more letter " +
            "out, through the home mailbox, with the " +
            "school year already settled behind it (the " +
            "warmth already stood at its 100 cap, so " +
            "the answer's measure is the letter, not " +
            "the points)")
    check(PenPals.lettersOut(v) == PenPals.lettersIn(v) &&
        !PenPals.homeMailPending(v) && !PenPals.canReply(v) &&
        PenPals.sendReply(v, PenPals.TONE_BIG) == null,
        "home mail: the correspondence closes WHOLE — " +
            "${PenPals.lettersIn(v)} in, every one " +
            "answered, the stamp cleared by the send, " +
            "and no phantom second answer behind it")
    // the dormant route: three letters unanswered, the
    // route asleep — then the settlement's maybe-next
    // letter lands in the home box, and answering it IS
    // the revival letter
    val (_, w) = auditStateH(140_102)
    setDayH(w, absOfKeyH("20261005"))
    PenPals.signUp(w)
    var dB = w.absDay
    val endB = absOfKeyH("20270602")
    while (dB < endB) {
        dB++
        setDayH(w, dB)
        PenPals.dailyRollover(w)
    }
    check(PenPals.isDormant(w) &&
        PenPals.latestLetter(w) == PenPals.MAYBE_NEXT_LETTER &&
        PenPals.homeMailPending(w) && !PenPals.live(w) &&
        PenPals.canReply(w),
        "home mail: a dormant route still gets the " +
            "settlement's word — in the HOME box, where " +
            "it can be answered the day it lands")
    val ptsW = PenPals.points(w)
    val revival = PenPals.sendReply(w, PenPals.TONE_EVERYDAY)
    check(revival != null &&
        PenPals.points(w) - ptsW == PenPals.PTS_REVIVAL &&
        !PenPals.isDormant(w) &&
        (w.life["palRevived"] ?: 0) == 1 &&
        !PenPals.homeMailPending(w),
        "home mail: the answer revives by the book — " +
            "+${PenPals.PTS_REVIVAL}, dormancy cleared, " +
            "the revival stamp set: the dormancy rules " +
            "rode home mail whole, never around it")
    // a fresh October folds a waiting home letter away:
    // the new program year starts clean
    val (_, x) = auditStateH(140_103)
    setDayH(x, absOfKeyH("20261005"))
    PenPals.signUp(x)
    var dC = x.absDay
    val endC = absOfKeyH("20270602")
    while (dC < endC) {
        dC++
        setDayH(x, dC)
        PenPals.dailyRollover(x)
    }
    check(PenPals.homeMailPending(x),
        "home mail: (staging) the maybe-next letter " +
            "waits unanswered in the home box")
    val inX = PenPals.lettersIn(x)
    setDayH(x, absOfKeyH("20271005"))
    check(PenPals.signupOpen(x) && PenPals.signUp(x) != null &&
        !PenPals.homeMailPending(x) && !PenPals.canReply(x) &&
        PenPals.lettersIn(x) == inX,
        "home mail: October's signup folds the stale " +
            "home letter into the archive — the letter " +
            "stays kept, the new year starts clean, and " +
            "no answer can be double-ridden across years")
    // the architecture pins, from the module's own source
    val palSrc = File(root,
        "src/com/hunt3r/southparktown/PenPals.kt").readText()
    check(palSrc.contains("K_HOME_MAIL") &&
        palSrc.contains("fun homeMailPending") &&
        !palSrc.contains("Phone.") &&
        !palSrc.contains("Newspaper"),
        "home mail: the stamp and its reader stand in " +
            "the module, and the correspondence still " +
            "appears nowhere in the phone or the paper")
}

// ---------- disposition two: her facts, fabricated whole ----------
run {
    val (_, sF) = auditStateH(140_104)
    setDayH(sF, absOfKeyH("20261005"))
    check(PenPals.signUp(sF) != null,
        "fabricated facts: (staging) the signup lands")
    setDayH(sF, sF.life["palNextDue"] ?: sF.absDay)
    PenPals.dailyRollover(sF)
    check(PenPals.unanswered(sF) == 1,
        "fabricated facts: (staging) her first letter " +
            "waits — there is something to answer")
    // the town lives a year the letters can draw on:
    // restage the calendar to March 2027 and fabricate
    // the four records through their own modules
    setDayH(sF, absOfKeyH("20270301"))
    val prF = Parade.recordOrNew(sF, 2027)
    prF.day = ParadeCalendar.paradeDay(2027)
    prF.wrapped = "played"; prF.mode = "march"
    Parade.saveRecord(sF, prF)
    val taF = Talent.recordOrNew(sF, 2027)
    taF.night = "played"
    taF.winner = Talent.field(2027).first()
    Talent.saveRecord(sF, taF)
    // the dance's and the carnival's save paths are
    // their modules' own pipe formats (the veteran
    // staging writes them the same way)
    sF.lifeText["danceRec:2027"] =
        "1|Kyle||||0|steady|0|0|played|||" +
            DanceCalendar.danceDay(2027)
    sF.lifeText["carnRec:2027"] =
        "2027~1~1~0~Wendy~the fabricated week~0~0~~"
    val factsF = PenPals.factsAvailable(sF)
    check(factsF.map { it.kind } == listOf("parade",
            "talent", "dance", "carnival") &&
        factsF.map { it.id } == listOf("parade:2027",
            "talent:2027", "dance:2027", "carnival:2027"),
        "fabricated facts: a lived spring offers all " +
            "four records the banks were waiting on — " +
            "parade, talent, dance, carnival, in the " +
            "stated order (got ${factsF.map { it.kind }})")
    check(factsF.first { it.kind == "dance" }.text
            .contains("Kyle") &&
        factsF.first { it.kind == "talent" }.text
            .contains("talent show") &&
        factsF.first { it.kind == "parade" }.text
            .contains("parade") &&
        factsF.first { it.kind == "carnival" }.text
            .contains("carnival"),
        "fabricated facts: each fact's text is its own " +
            "record read back — the date she danced " +
            "with, the played talent night, the march, " +
            "the winter carnival week")
    val byToneF = PenPals.TONES.map { tone ->
        PenPals.composeReply(sF, tone) }
    check(byToneF.all { it.second == factsF.take(2) },
        "fabricated facts: the four records' facts " +
            "are identical under all three tones — the " +
            "tone colors the frame, never the facts")
    val sentF1 = PenPals.sendReply(sF, PenPals.TONE_FUNNY)!!
    check(factsF.take(2).all { sentF1.contains(it.text) },
        "fabricated facts: the parade and the talent " +
            "night ride the first reply verbatim")
    check(PenPals.factsAvailable(sF).map { it.kind } ==
        listOf("dance", "carnival"),
        "fabricated facts: ridden facts are spent — " +
            "the dance and the carnival wait their turn")
    val fuF1 = PenPals.composeIncoming(sF)
    check(fuF1.fuKind in listOf("parade", "talent") &&
        fuF1.fuText == factsF.first {
            it.kind == fuF1.fuKind }.text,
        "fabricated facts: her follow-up reaches back " +
            "to a fact YOUR letter carried — the " +
            "${fuF1.fuKind} bank answers, provenance by " +
            "construction")
    setDayH(sF, sF.life["palNextDue"] ?: sF.absDay)
    PenPals.dailyRollover(sF)
    val sentF2 = PenPals.sendReply(sF, PenPals.TONE_BIG)!!
    check(factsF.drop(2).all { sentF2.contains(it.text) },
        "fabricated facts: the dance and the carnival " +
            "ride the second reply verbatim")
    val fuF2 = PenPals.composeIncoming(sF)
    check(fuF2.fuKind in listOf("dance", "carnival") &&
        fuF2.fuText == factsF.first {
            it.kind == fuF2.fuKind }.text,
        "fabricated facts: the second follow-up draws " +
            "from the second letter's facts — the dance " +
            "and carnival banks answer in their turn")
    check(PenPals.factsAvailable(sF).none {
        it.kind in listOf("parade", "talent", "dance",
            "carnival") },
        "fabricated facts: all four are spent now — " +
            "the gap polish #13 logged is closed, and " +
            "the record kinds join case/photo/fair/" +
            "garden/stand/family under full test")
}

// ---------- the 400-day soak over Queue #14 ----------
run {
    val eng = Engine(1407)
    val s = eng.newState()
    eng.createPlayer(s, "Veteran", DEFAULT_APPEARANCE)
    // a crew from the start (the phone week's idiom) and
    // a hero identity, so the clubhouse and the costume
    // reader have something to read all year
    s.lifeText["crew:members"] = "Stan,Kyle,Butters,Wendy"
    Heroes.createHero(s, "Captain Curfew", "speed")
    val closedSenders = CharacterSystem.CAST.keys +
        setOf("Mom", "Dad", "you")
    var twoCases = false
    var phoneViolation = false
    var inboxMax = 0
    var tripTexts = 0; var festTexts = 0; var bdayTexts = 0
    var q13Texts = 0; var totalTexts = 0
    var palSigned = false
    var lastInCount = 0; var lastInDay = -1
    val palGaps = mutableListOf<Int>()
    var palDormantSeen = false; var palMaxBand = 0
    var palLaneChecked = false; var palLaneBroken = false
    var homeMailAnswers = 0
    val palTones = listOf(PenPals.TONE_BIG,
        PenPals.TONE_EVERYDAY, PenPals.TONE_FUNNY)
    var arc12Seen = false
    var pageReads = 0; var pageUnstable = false
    var clubAttempts = 0; var clubAttended = 0
    val clubSpotsSeen = mutableSetOf<String>()
    var clubNotes = 0
    var mirrorProbes = 0; var mirrorMismatch = false
    var costumeProbes = 0; var costumeMismatch = false
    var readerImpure = false
    var noonDressed = false
    for (day in 0 until 400) {
        val beforeIds = s.phoneTexts.map { it.id }.toSet()
        eng.onNewDay(s)
        val openNow = listOf(
            s.arcStarted && !s.arcRetired,
            s.arc2Started && !s.arc2Retired,
            s.arc3Started && !s.arc3Retired,
            s.arc4Started && !s.arc4Retired,
            s.arc5Started && !s.arc5Retired,
            s.arc6Started && !s.arc6Retired,
            s.arc7Started && !s.arc7Retired,
            s.arc8Started && !s.arc8Retired,
            s.arc9Started && !s.arc9Retired,
            s.arc10Started && !s.arc10Retired,
            s.arc11Started && !s.arc11Retired,
            s.arc12Started && !s.arc12Retired).count { it }
        if (openNow > 1) twoCases = true
        if (s.arc12Started) arc12Seen = true
        // the phone, watched every morning
        val newTexts = s.phoneTexts
            .filter { it.id !in beforeIds }
        totalTexts += newTexts.size
        tripTexts += newTexts.count {
            it.trigger == Phone.FIELDTRIP }
        festTexts += newTexts.count {
            it.trigger == Phone.FESTIVAL }
        bdayTexts += newTexts.count {
            it.trigger == Phone.PLAYERBDAY }
        q13Texts += newTexts.count {
            it.trigger == Phone.DANCE ||
                it.trigger == Phone.TALENT ||
                it.trigger == Phone.PARADE }
        if (newTexts.any { it.sender !in closedSenders })
            phoneViolation = true
        if (s.phoneTexts.size > Phone.MAX_TEXTS)
            phoneViolation = true
        if (s.phoneTexts.size > inboxMax)
            inboxMax = s.phoneTexts.size
        // the family page, read weekly (polish #13's
        // continuity probe): pure and byte-stable
        if (day >= 5 && day % 7 == 0) {
            val lifeBefore = s.life.size
            val textBefore = s.lifeText.size
            val page1 = Family.pageLines(s)
            val page2 = Family.pageLines(s)
            pageReads++
            if (page1 != page2 ||
                page1.firstOrNull() != "👨‍👩‍👧 YOUR FAMILY" ||
                s.life.size != lifeBefore ||
                s.lifeText.size != textBefore)
                pageUnstable = true
        }
        // the reflections at noon: an ordinary day
        // dresses nobody — the mirror shows the day
        // look and the street stays first-person
        s.timeMin = 12 * 60
        if (Sleepwear.mirrorCode(s).isNotEmpty() ||
            Heroes.streetCostumeCode(s).isNotEmpty())
            noonDressed = true
        // the costume reader, probed on patrol nights:
        // the street code IS the code a photograph
        // would freeze, and reading writes nothing
        if (Heroes.isPatrolNight(s.absDay) && day % 27 == 6) {
            val me = s.agents.values.first { it.isPlayer }
            me.location = Heroes.PATROL_SPOTS[0]
            me.destination = Heroes.PATROL_SPOTS[0]
            me.asleep = false; me.waypoints.clear()
            s.playerInside = false
            s.timeMin = 20 * 60
            val encBefore = Json.stringify(encodeGameState(s))
            val street = Heroes.streetCostumeCode(s)
            val frozen = Heroes.figureCode(s,
                PhotoFigure("Veteran", "player", "happy"))
            val encAfter = Json.stringify(encodeGameState(s))
            costumeProbes++
            if (street.isEmpty() || street != frozen)
                costumeMismatch = true
            if (encBefore != encAfter) readerImpure = true
        }
        // the mirror reader, probed once on a staged
        // sleepover night: the glass wears the same
        // pajama code the shutter would freeze
        if (day == 150) {
            s.life["slpDay"] = s.absDay
            s.lifeText["slpGuests"] = "Stan"
            s.timeMin = 19 * 60
            val encBefore = Json.stringify(encodeGameState(s))
            val mirror = Sleepwear.mirrorCode(s)
            val frozen = Sleepwear.figureCode(s,
                PhotoFigure("Veteran", "player", "happy"),
                YOUR_HOUSE)
            val encAfter = Json.stringify(encodeGameState(s))
            mirrorProbes++
            if (mirror.isEmpty() || mirror != frozen)
                mirrorMismatch = true
            if (encBefore != encAfter) readerImpure = true
            s.life.remove("slpDay")
            s.lifeText.remove("slpGuests")
        }
        // the clubhouse, attended about every six
        // weeks: stage the room, play the three beats
        // through the module's own seams, let the
        // morning wrap it
        if (day % 45 == 20) {
            clubAttempts++
            val spot = Clubhouse.spotLoc(s)
            clubSpotsSeen.add(Clubhouse.spot(s).id)
            val members = Clubhouse.members(s)
            val me = s.agents.values.first { it.isPlayer }
            me.location = spot; me.destination = spot
            me.asleep = false; me.waypoints.clear()
            s.playerInside = spot == YOUR_HOUSE
            for (m in members) s.agents[m]?.let {
                it.location = spot; it.destination = spot
                it.asleep = false; it.waypoints.clear() }
            s.timeMin = 16 * 60
            if (members.size >= 2) {
                Clubhouse.talkLines(s, members[0])
                Clubhouse.lookText(s, spot)
                Clubhouse.talkLines(s, members[1])
            }
            if (Clubhouse.stepsDone(s) ==
                Clubhouse.STEP_COUNT) clubAttended++
        }
        if (Clubhouse.morningNote(s) != null) clubNotes++
        // pen pals: sign up in the window, answer every
        // letter the morning it can be answered — home
        // mail included, now
        if (!palSigned && PenPals.signupOpen(s)) {
            PenPals.signUp(s)
            palSigned = PenPals.isSignedUp(s)
        }
        if (palSigned) {
            val inNow = PenPals.lettersIn(s)
            if (inNow > lastInCount) {
                if (lastInDay >= 0)
                    palGaps.add(s.absDay - lastInDay)
                lastInDay = s.absDay
                lastInCount = inNow
            }
            if (PenPals.isDormant(s)) palDormantSeen = true
            if (PenPals.canReply(s)) {
                val viaHome = PenPals.homeMailPending(s) &&
                    !PenPals.live(s)
                val friendsBefore = s.friendship.toMap()
                val sent = PenPals.sendReply(s,
                    palTones[PenPals.lettersOut(s) % 3])
                if (sent != null) {
                    if (viaHome) homeMailAnswers++
                    if (!palLaneChecked) {
                        palLaneChecked = true
                        if (s.friendship.toMap() !=
                            friendsBefore) palLaneBroken = true
                    }
                }
            }
            val bandNow = PenPals.bandOf(s)
            if (bandNow > palMaxBand) palMaxBand = bandNow
        }
    }
    val tripRecs = FieldTrip.allRecords(s)
    val festRec = Festival.record(s, 2026)
    val clubHeld = Clubhouse.hangoutsHeld(s)
    val saveLen = Json.stringify(encodeGameState(s)).length
    println("audit soak Q14: trips=${tripRecs.map { "${it.key}=${it.outcome}" }} " +
        "fest2026 wrapped=${festRec?.wrapped} winner=${Festival.winnerFilm(s, 2026)?.title}, " +
        "bday giftYear=${s.life["pbGiftYear"]} cakes=${s.inventory[PlayerBirthday.GIFT_ITEM]}, " +
        "club=$clubAttended/$clubAttempts held=$clubHeld spots=$clubSpotsSeen notes=$clubNotes, " +
        "mirror=$mirrorProbes costume=$costumeProbes, pageReads=$pageReads, " +
        "palIn=${PenPals.lettersIn(s)} palOut=${PenPals.lettersOut(s)} " +
        "palPts=${PenPals.points(s)} homeMail=$homeMailAnswers gaps=$palGaps, " +
        "phone trip=$tripTexts fest=$festTexts bday=$bdayTexts q13=$q13Texts " +
        "total=$totalTexts inboxMax=$inboxMax, " +
        "retired=${retiredCountH(s)} arc12Seen=$arc12Seen, save=$saveLen")
    check(!twoCases,
        "soak: never two cases open together in 400 " +
            "days — the queue discipline holds with the " +
            "twelfth case in the line")
    check(!phoneViolation && inboxMax <= Phone.MAX_TEXTS,
        "soak: the phone's caps and closed sender set " +
            "hold every one of the 400 mornings with " +
            "the FIELDTRIP, FESTIVAL and PLAYERBDAY " +
            "triggers in the harvest — the inbox peaked " +
            "at $inboxMax of ${Phone.MAX_TEXTS}")
    check(tripRecs.count { it.outcome == "missed" } >= 3 &&
        tripRecs.filter { it.key in listOf("fall:2026",
            "winter:2027", "spring:2027") }
            .all { it.outcome.isNotEmpty() },
        "soak: the year's three trips all wrapped " +
            "unattended as missed — fall, winter and " +
            "spring, the bus on time whether or not " +
            "the audit rode (records: ${tripRecs.map {
                "${it.key}=${it.outcome}" }})")
    check(festRec?.wrapped == true &&
        Festival.winnerFilm(s, 2026) != null,
        "soak: the festival week wrapped unattended " +
            "in December and crowned its winner on the " +
            "record — the Bijou went on without the audit")
    check((s.life["pbGiftYear"] ?: 0) == 1 &&
        PlayerBirthday.keptCard(s) != null &&
        (s.inventory[PlayerBirthday.GIFT_ITEM] ?: 0) >= 1,
        "soak: the first birthday fired on its derived " +
            "morning inside the year — one real cake in " +
            "the bag, the household card kept on the page")
    check(clubAttended >= 5 && clubHeld >= 5 &&
        clubSpotsSeen.size >= 3 && clubNotes >= 3,
        "soak: the clubhouse stood and was attended " +
            "across the year — $clubAttended of " +
            "$clubAttempts staged afternoons played " +
            "their three beats, $clubHeld wrapped onto " +
            "the record across $clubSpotsSeen, and the " +
            "house report noted $clubNotes of them")
    check(mirrorProbes == 1 && costumeProbes >= 3 &&
        !mirrorMismatch && !costumeMismatch && !readerImpure,
        "soak: the reflections readers answered all " +
            "year — the mirror's pajama code and the " +
            "street's costume code each exactly the " +
            "code a photograph freezes at the same " +
            "moment, and every read left the serialized " +
            "save byte-identical")
    check(!noonDressed,
        "soak: at 400 ordinary noons the mirror never " +
            "showed the night look and the street never " +
            "dressed the player — the reflections keep " +
            "their hours")
    check(pageReads >= 40 && !pageUnstable,
        "soak: the family page read $pageReads times " +
            "across the year — byte-identical between " +
            "reads and a read wrote nothing, ever")
    check(palSigned && PenPals.lettersIn(s) >= 15 &&
        PenPals.lettersOut(s) == PenPals.lettersIn(s) &&
        homeMailAnswers >= 1,
        "soak: the correspondence closed WHOLE this " +
            "year — ${PenPals.lettersIn(s)} letters in " +
            "and every one answered, $homeMailAnswers " +
            "of them by home mail after the settlement " +
            "(polish #13's soak closed 61 of 62; the " +
            "seam is sewn)")
    check(palGaps.isNotEmpty() &&
        palGaps.count { it in 3..5 } >= palGaps.size - 1 &&
        palGaps.count { it in 6..18 } <= 1,
        "soak: every letter gap sat inside the seeded " +
            "3–5 day cadence but one — the settlement " +
            "seam, where the school year ended, she " +
            "came to visit, and her thank-you closed " +
            "the year (${palGaps.maxOrNull()} days, " +
            "letter to letter). The cadence is the " +
            "school year's; the seam is the summer")
    check(palMaxBand == PenPals.BAND_FRIEND_I &&
        !palDormantSeen && palLaneChecked && !palLaneBroken,
        "soak: faithful replies carried the warmth to " +
            "the top band without the route ever going " +
            "dormant — and a send, checked against a " +
            "snapshot, left the friendship table " +
            "byte-identical: palPts is its own lane")
    check(arc12Seen && retiredCountH(s) >= 11,
        "soak: the returns case opened inside the " +
            "year and the case queue ran deep — " +
            "${retiredCountH(s)} of twelve retired in " +
            "the soak's own life")
    check(Attic.caseBoxes(s).size == retiredCountH(s),
        "soak: the attic's case boxes always equal " +
            "the retired count — at the year's end, " +
            "${Attic.caseBoxes(s).size} boxes for " +
            "${retiredCountH(s)} closed cases")
}

// ---------- the twelve-case lifetime, re-driven ----------
run {
    val eng12L = Engine(1409)
    val life12L = eng12L.newState()
    eng12L.createPlayer(life12L, "Veteran", DEFAULT_APPEARANCE)
    var days12L = 0
    var openedOver11 = false
    var openedBehind11 = false
    while (days12L < 2600 &&
        !(life12L.arcRetired && life12L.arc2Retired &&
            life12L.arc3Retired && life12L.arc4Retired &&
            life12L.arc5Retired && life12L.arc6Retired &&
            life12L.arc7Retired && life12L.arc8Retired &&
            life12L.arc9Retired && life12L.arc10Retired &&
            life12L.arc11Retired && life12L.arc12Retired)) {
        eng12L.onNewDay(life12L)
        if (life12L.arc12Started) {
            if (!life12L.arc11Retired) openedOver11 = true
            if (life12L.arc11Retired) openedBehind11 = true
        }
        days12L++
    }
    println("audit lifetime: all twelve retired after " +
        "$days12L unattended days (arc12 branch " +
        "${life12L.arc12Branch})")
    check(life12L.arc12Retired && days12L < 2600 &&
        !openedOver11 && openedBehind11 &&
        life12L.arc12Branch in Mystery12.BRANCH_KEYS &&
        Mystery12.dueChapter12(life12L) == null,
        "audit: the twelve-case lifetime holds — all " +
            "twelve arcs retire in order in one " +
            "unattended life, the twelfth never over " +
            "the eleventh's open body, and the queue " +
            "is empty behind it")
    check(Attic.caseBoxes(life12L).size == 12 &&
        Attic.CASE_TOTAL == 13,
        "audit: a life with all twelve cases closed " +
            "reads twelve boxes in the attic — the " +
            "shelf is full and the total agrees")
}

// ---------- contention, re-pinned at the code's own seats ----------
run {
    check(TalkGate.Rail.values().toList() == listOf(
        TalkGate.Rail.DELIVER, TalkGate.Rail.HOLIDAY_BEAT,
        TalkGate.Rail.FINALE, TalkGate.Rail.CLIMAX,
        TalkGate.Rail.DINNER, TalkGate.Rail.WORK,
        TalkGate.Rail.FACTION_MISSION,
        TalkGate.Rail.EMERG_OFFER, TalkGate.Rail.RIVAL,
        TalkGate.Rail.ERRAND_ASK, TalkGate.Rail.DIALOGUE),
        "contention: the TalkGate ladder stands at " +
            "eleven rails in its order — Queue #14 " +
            "added none")
    val tgSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(tgSrc.contains("PlayerBirthday.talkStepFor") &&
        tgSrc.contains("bdayHit") &&
        tgSrc.contains("PlayerBirthday.wishLine") &&
        !tgSrc.contains("Clubhouse") &&
        !tgSrc.contains("FieldTrip") &&
        !tgSrc.contains("Festival.phoneBeat"),
        "contention: the birthday party rides the " +
            "DINNER rail on its bdayHit payload and the " +
            "wishes ride the owed-lines seam — no rail " +
            "of their own; the clubhouse and the trips " +
            "appear nowhere in the gate")
    // the agenda stack, in Engine's actual order: each
    // gathering claim's first call in effectiveAgendaBlock
    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    val stackNames = listOf("Dinners", "Birthdays", "Family",
        "Jobs", "Apprenticeships", "MovieNights", "Capstones",
        "Finales", "Fair",
        "Carnival", "RivalCrew", "Heroes", "Play",
        "Dance", "Talent", "Parade", "FieldTrip", "Festival",
        "Gallery", "Sleepovers", "PlayerBirthday", "Stand",
        "Clubhouse", "Crew")
    val idx = stackNames.map { nm ->
        Regex("(?<![A-Za-z])$nm\\.gatheringBlock")
            .find(engSrc)?.range?.first ?: -1 }
    check(idx.all { it >= 0 } && idx == idx.sorted() &&
        idx.distinct().size == idx.size,
        "contention: the agenda stack seats its " +
            "twenty-three claims in Engine's own order — " +
            "Dinners, cast Birthdays right after, Family, " +
            "Jobs, MovieNights, Capstones, Finales, Fair, " +
            "Carnival, RivalCrew, Heroes, Play, Dance, " +
            "Talent, Parade, FieldTrip, Festival, " +
            "Gallery, Sleepovers, Stand, Clubhouse, " +
            "Crew last — " +
            "with the player's birthday party consulted " +
            "at the sleepover seat, between the " +
            "sleepovers' claim and the stand's, riding " +
            "it rather than widening the stack. " +
            "v0.15.0f re-pin: the gallery show takes a " +
            "seat of its own (a new claim, not a rider) " +
            "between the festival and the sleepovers, " +
            "widening the stack to twenty-two claims — " +
            "both the festival and the hall own a framed " +
            "evening built from real entries, the " +
            "festival's came first in the town's life, " +
            "and the sleepovers' quieter claim yields to " +
            "the hall the way it yields to the theater. " +
            "v0.15.0h re-pin: the mentor's hours take a " +
            "seat of their own between Jobs and the " +
            "movie nights — work's own family, an " +
            "appointment rather than an event — widening " +
            "the stack to twenty-three claims; every set " +
            "piece seated below it still wins the mentor")
    val phoneSrc = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    val newsSrc = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(!phoneSrc.contains("Clubhouse") &&
        !newsSrc.contains("Clubhouse") &&
        !tgSrc.contains("Clubhouse"),
        "contention: the clubhouse has NO phone text, " +
            "NO paper line and NO rail — a daily " +
            "afternoon is not an event, pinned as an " +
            "absence in all three sources")
}

// ---------- the phone at its worst week ----------
// Polish #13's worst week, re-staged unchanged (the
// full-census inbox through the densest birthday week
// of the year) — the caps are the audit — and then
// each of Queue #14's three new beats proven on a
// morning with room, through the real harvest.
run {
    val (engW, sw) = auditStateH(1423)
    sw.life["famArrived"] = 1
    Heroes.createHero(sw, "Captain Curfew", "speed")
    sw.lifeText["crew:members"] = "Stan,Kyle,Butters,Wendy"
    val byWeek = mutableMapOf<Int, MutableSet<Int>>()
    for (d in 0..364) {
        val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(d))
        if (Birthdays.birthdaysOn(key).isNotEmpty())
            byWeek.getOrPut(Jobs.weekIndex(d)) { mutableSetOf() }
                .add(d)
    }
    val denseWeek = byWeek.entries
        .filter { (it.value.minOrNull() ?: 0) >= 7 }
        .maxByOrNull { it.value.size }
    check(denseWeek != null && denseWeek.value.size >= 3,
        "phone week: (staging) the year's densest " +
            "birthday week holds birthdays on " +
            "${denseWeek?.value?.size} of its seven days")
    val weekStart = denseWeek!!.value.minOrNull()!!
    val threadsW = CharacterSystem.CAST.keys.toList() +
        listOf("Mom", "Dad", GroupChats.CREW_ID,
            GroupChats.FAMILY_ID, GroupChats.PLAY_ID)
    var nW = 0
    for (t in threadsW) repeat(2) { k ->
        nW++
        sw.phoneTexts.add(PhoneText(
            id = "auditw-t$nW", thread = t,
            sender = if (t in CharacterSystem.CAST.keys) t
                else "Mom",
            trigger = Phone.HELLO, absDay = 1,
            dayKey = "20270101",
            text = "A full-census text, thread $t, " +
                "number $k.", read = true))
    }
    check(sw.phoneTexts.size == 206 && threadsW.size == 103,
        "phone week: (staging) the worst case stands " +
            "at 206 texts in 103 threads")
    sw.photos.add(PhotoRecord(
        id = "auditw-crew-photo",
        dayKey = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(weekStart - 1)),
        dateLabel = "the night before", timeMin = 15 * 60,
        locId = "KidsPark", inside = false,
        weatherId = "sunny", appearance = emptyMap(),
        figures = listOf(
            PhotoFigure("Veteran", "player", "happy"),
            PhotoFigure("Stan", "cast", "happy"),
            PhotoFigure("Kyle", "cast", "happy")),
        absDay = weekStart - 1))
    setDayH(sw, weekStart - 1)
    val closedSenders = CharacterSystem.CAST.keys +
        setOf("Mom", "Dad", "you")
    var paperTexts = 0
    var bdayTextsW = 0
    var heroTexts = 0
    var totalNew = 0
    var q14Texts = 0
    var weekBroken = false
    for (morning in 0 until 7) {
        if (morning == 1 || morning == 4)
            sw.life["heroLastPatrol"] = sw.absDay
        if (morning == 2) {
            sw.lifeText["paperLatest"] =
                "📰 THE SOUTH PARK GAZETTE\n" +
                "Printed from the town's own record\n" +
                "THE CASE CLOSES"
            sw.life["paperWeek"] = Jobs.weekIndex(weekStart)
            sw.life["paperSummaryDue"] = 1
        }
        val beforeIds = sw.phoneTexts.map { it.id }.toSet()
        engW.onNewDay(sw)
        val newTexts = sw.phoneTexts
            .filter { it.id !in beforeIds }
        totalNew += newTexts.size
        paperTexts += newTexts.count {
            it.trigger == Phone.PAPER }
        bdayTextsW += newTexts.count {
            it.trigger == Phone.BIRTHDAY }
        heroTexts += newTexts.count {
            it.trigger == Phone.HERO }
        q14Texts += newTexts.count {
            it.trigger == Phone.FIELDTRIP ||
                it.trigger == Phone.FESTIVAL ||
                it.trigger == Phone.PLAYERBDAY }
        if (newTexts.size > Phone.MAX_NEW_PER_DAY)
            weekBroken = true
        if (newTexts.count { it.trigger == Phone.BIRTHDAY } >
            maxOf(1, Birthdays.birthdaysToday(sw).size))
            weekBroken = true
        if (newTexts.any { it.sender !in closedSenders })
            weekBroken = true
        if (sw.phoneTexts.size > Phone.MAX_TEXTS)
            weekBroken = true
        if (sw.phoneTexts.groupBy { it.thread }.values
            .any { it.size > Phone.MAX_PER_THREAD })
            weekBroken = true
    }
    println("audit phone week: new=$totalNew paper=$paperTexts " +
        "birthdays=$bdayTextsW hero=$heroTexts q14=$q14Texts, " +
        "inbox at ${sw.phoneTexts.size} after seven mornings")
    check(!weekBroken && Phone.MAX_TEXTS == 220,
        "phone week: seven worst-case mornings with " +
            "the FIELDTRIP, FESTIVAL and PLAYERBDAY " +
            "triggers now in the harvest, and the caps " +
            "hold every single one — at most " +
            "${Phone.MAX_NEW_PER_DAY} new texts a " +
            "morning, no thread past " +
            "${Phone.MAX_PER_THREAD}, the inbox never " +
            "past MAX_TEXTS ${Phone.MAX_TEXTS}, never " +
            "more birthday texts in a day than the " +
            "day holds birthdays (v0.15.0i re-pin: " +
            "a shared day carries both beats now — " +
            "this staged week holds none, so the " +
            "bound reads as one here), and every " +
            "sender inside the closed set (cast, Mom, " +
            "Dad, you)")
    check(paperTexts == 1 && !Newspaper.summaryDue(sw),
        "phone week: the stamped summary landed " +
            "exactly once inside its week and the debt " +
            "cleared — deferral under pressure, never loss")
    check(bdayTextsW >= 1 && heroTexts <= 2,
        "phone week: the derived beats stay best-effort " +
            "by design, exactly as polish #12 measured " +
            "on this same staged week — birthday beats " +
            "landed $bdayTextsW of the week's mornings, " +
            "hero opinions $heroTexts; nothing invented, " +
            "nothing over a cap")
    check(totalNew >= 5,
        "phone week: the town actually talked — " +
            "$totalNew texts across the week, not a " +
            "frozen inbox")
    // the three new beats, each on a morning with
    // room, through the real onNewDay harvest
    val (engT, sT) = auditStateH(1431)
    setDayH(sT, TripCalendar.dayFor("fall", 2026))
    val beforeT = sT.phoneTexts.map { it.id }.toSet()
    engT.onNewDay(sT)
    val tripBeat = sT.phoneTexts
        .filter { it.id !in beforeT &&
            it.trigger == Phone.FIELDTRIP }
    check(tripBeat.size == 1 &&
        tripBeat[0].sender in FieldTrip.roster(),
        "phone beats: the morning after a missed " +
            "trip, the FIELDTRIP beat lands whole " +
            "through the harvest — one text, from a " +
            "classmate who rides the bus, on their " +
            "own thread")
    val (engF, sF2) = auditStateH(1432)
    sF2.lifeText["festRec:2026"] =
        "2026|att=0:3,1:2,2:4|yield=|settled=0,1,2|" +
            "wrapped=0|wrapDay=-1|paid=0|photo="
    sF2.lifeText["festYears"] = "2026"
    setDayH(sF2, FestivalCalendar.nightDay(2026,
        Festival.NIGHTS - 1))
    val beforeF = sF2.phoneTexts.map { it.id }.toSet()
    engF.onNewDay(sF2)
    val festBeat = sF2.phoneTexts
        .filter { it.id !in beforeF &&
            it.trigger == Phone.FESTIVAL }
    val festWinner = Festival.winnerFilm(sF2, 2026)
    check(festBeat.size == 1 && festWinner != null &&
        festBeat[0].sender ==
            Festival.starsFor(2026, festWinner!!).first(),
        "phone beats: on the festival wrap's morning, " +
            "the FESTIVAL beat lands whole — one text " +
            "from the winning film's first star, naming " +
            "the film that took the Golden Popcorn")
    val (engB, sB) = auditStateH(1433)
    sB.life["famArrived"] = 1
    sB.life["famArrivalDay"] = 3
    sB.friendship["Stan"] = 70
    setDayH(sB, 367)
