    for ((i, d) in clubDays13.withIndex())
        vet.lifeText["clubRec:$d"] =
            "${clubSpots13[i]}|Stan,Kyle,Wendy|3"
    vet.lifeText["clubDays"] =
        clubDays13.joinToString(",")
    vet.life["clubTotal"] = 8
    vet.life["clubWrapDay"] = clubDays13.last()
    check(Clubhouse.hangouts(vet).size ==
        Clubhouse.HISTORY_CAP,
        "veteran XIII: (staging) the clubhouse record " +
            "stands at its cap of eight afternoons")
    // the paper's archive, at its caps
    vet.lifeText["paperSkyLog"] =
        (0 until Newspaper.SKY_LOG_CAP).joinToString(";") { i ->
            "${686 + i}:sunny:${SkyState.NONE}" }
    vet.lifeText["paperHeadlines"] =
        (0 until Newspaper.HEADLINE_CAP).joinToString(";") { i ->
            "${50 + i}|Archived headline number $i from the " +
                "veteran's long subscription" }
    val edV = Newspaper.composeEdition(vet,
        Jobs.weekIndex(vet.arc11RetiredDay))
    vet.lifeText["paperLatest"] = edV.lines.joinToString("\n")
    vet.life["paperWeek"] = edV.week
    vet.life["paperLastWeek"] = edV.week
    check(edV.headline == "THE CASE CLOSES",
        "veteran XIII: (staging) the veteran's latest " +
            "edition headlines a case closing — the " +
            "eleventh case's stamp drives the ladder's " +
            "top tier like any case's")
    // the attic at this high-water
    check(!Attic.overflowEmpty(vet) &&
        Attic.overflowCollectibles(vet).isNotEmpty() &&
        Attic.overflowCups(vet) > 0,
        "veteran XIII: (staging) the attic's overflow " +
            "shelf is loaded — collectibles past the " +
            "shelf's twelve slots and feat cups past its six")
    check(Attic.caseBoxes(vet).size == Attic.CASE_TOTAL,
        "veteran XIII: (staging) twelve case boxes " +
            "stand in the attic — one per closed case, " +
            "public shape only")
    val vetOuttakes = Attic.outtakes(vet)
    check(vetOuttakes.any { !it.fromPrint &&
        it.record.id == "vet12fam" } &&
        vetOuttakes.any { it.fromPrint &&
            it.record.id == "vet12famgone" },
        "veteran XIII: (staging) the outtakes hold the " +
            "framed photo's elder sibling from the album " +
            "and one family photo only a darkroom print " +
            "still holds")
    val lifeSizeV = vet.life.size
    val lifeTextSizeV = vet.lifeText.size

    // ---- measure, pin, round-trip ----
    val vetJson = Json.stringify(encodeGameState(vet))
    println("veteran XIII game_state: ${vetJson.length} chars serialized")
    check(vetJson.length < 640 * 1024,
        "veteran XIII: the saturated save (Queue #13 " +
            "included) stays under the 640K ceiling — " +
            "655,360 chars — (got ${vetJson.length})")
    check(vetJson.length > 585_694,
        "veteran XIII: today's full state outgrows " +
            "veteran XII's 585,694 — the growth is Queue " +
            "#14's own records, each one capped (got " +
            "${vetJson.length})")
    @Suppress("UNCHECKED_CAST")
    val vetBack = decodeGameState(
        Json.parse(vetJson) as Map<String, Any?>)
    check(vetBack.errands.size == Errands.STATE_CAP &&
        vetBack.photos.size == 63 && StoryArcs.allDone(vetBack) &&
        vetBack.busPass && vetBack.walkTrips == 900 &&
        vetBack.arcRetired && vetBack.arc2Retired &&
        vetBack.arc3Retired && vetBack.arc4Retired &&
        vetBack.arc5Retired && vetBack.arc6Retired &&
        vetBack.arc7Retired && vetBack.arc8Retired,
        "veteran XIII: the veteran body round-trips " +
            "whole — eight cases closed beneath the " +
            "ninth, tenth, eleventh and twelfth")
    check(vetBack.arc11Retired &&
        vetBack.arc11Branch == "voiced" &&
        vetBack.mystery11Clues.size == Mystery11.CLUES11.size &&
        vetBack.arc11Calls.size == Mystery11.LETTERS11.size &&
        vetBack.arc11Posted,
        "veteran XIII: the eleventh case round-trips " +
            "closed — full evidence file, every letter " +
            "read, the correction cards posted")
    check(Crew.members(vetBack) ==
        listOf("Stan", "Kyle", "Wendy", "Craig") &&
        Sleepovers.nights(vetBack).size ==
            Sleepovers.HISTORY_CAP &&
        Newspaper.headlineHistory(vetBack).size ==
            Newspaper.HEADLINE_CAP &&
        Newspaper.skyLog(vetBack).size ==
            Newspaper.SKY_LOG_CAP &&
        vetBack.yearbooks.size == 5 &&
        vetBack.fairs.size == 2 &&
        vetBack.prints.size == Darkroom.TOTAL_CAP,
        "veteran XIII: the capped records round-trip " +
            "at their caps — eight sleepovers, the " +
            "paper's archives full, five yearbooks, " +
            "two fairs, the print box at its total " +
            "cap, the crew whole")
    check(Carnival.recordFor(vetBack, 2027)?.wrapped == true &&
        vetBack.phoneTexts.size == 196 &&
        PenPals.lettersIn(vetBack) == PenPals.lettersIn(scP) &&
        PenPals.lettersOut(vetBack) == PenPals.lettersOut(scP) &&
        PenPals.points(vetBack) >= PenPals.BAND_FRIEND,
        "veteran XIII: the carnival, the 196-text " +
            "inbox and the whole pen-pal archive — " +
            "${PenPals.lettersIn(vetBack)} letters in, " +
            "${PenPals.lettersOut(vetBack)} out, warmth " +
            "at the top band — survive the round-trip")
    check(Dance.record(vetBack, 2028)?.night == "missed" &&
        Talent.record(vetBack, 2028)?.night == "played" &&
        Talent.record(vetBack, 2028)?.winner?.isNotEmpty() == true &&
        Parade.record(vetBack, 2028)?.wrapped == "played" &&
        Parade.record(vetBack, 2028)?.mode == "march",
        "veteran XIII: Queue #13's gathering records " +
            "round-trip in their modules' own formats — " +
            "the missed dance, the played talent night " +
            "with its winner, the marched parade")
    check(vetBack.life.size == lifeSizeV &&
        vetBack.lifeText.size == lifeTextSizeV &&
        (vetBack.life["famChoreDoneBy:Mom"] ?: 0) == 27 &&
        (vetBack.life["famChoreDoneBy:Dad"] ?: 0) == 19 &&
        (vetBack.life["shopGoodsSpent"] ?: 0) == 5,
        "veteran XIII: the life and lifeText maps come " +
            "through at exactly their staged sizes — " +
            "the family's chore counters and the " +
            "counters' books among them, nothing shed, " +
            "nothing invented")
    check(Attic.caseBoxes(vetBack).size ==
        Attic.CASE_TOTAL &&
        !Attic.overflowEmpty(vetBack) &&
        Attic.outtakes(vetBack).size ==
            vetOuttakes.size &&
        Attic.pageLines(vetBack) ==
            Attic.pageLines(vet),
        "veteran XIII: the attic reads the round-tripped " +
            "save whole — twelve boxes, a loaded " +
            "overflow shelf, the outtakes intact, the " +
            "page byte-identical, because it stores nothing")
    check(vetBack.arc12Retired &&
        vetBack.arc12Branch in Mystery12.BRANCH_KEYS &&
        vetBack.mystery12Clues.size ==
            Mystery12.CLUES12.size &&
        vetBack.arc12Calls.size == Mystery12.ITEMS12.size &&
        vetBack.arc12Posted,
        "veteran XIII: the twelfth case round-trips " +
            "closed — full evidence file, every return " +
            "read, the reading held")
    check(FieldTrip.allRecords(vetBack).size == 3 &&
        Festival.record(vetBack, festY)?.wrapped == true &&
        (vetBack.life["pbGiftYear"] ?: 0) == 2 &&
        PlayerBirthday.keptCard(vetBack) != null &&
        Clubhouse.hangouts(vetBack).size ==
            Clubhouse.HISTORY_CAP &&
        Clubhouse.hangoutsHeld(vetBack) == 8,
        "veteran XIII: Queue #14's records round-trip " +
            "in their modules' own formats — three " +
            "trips, the wrapped festival, two birthdays " +
            "with the card kept, the clubhouse's eight " +
            "afternoons at the cap")
    check(PenPals.lettersOut(vetBack) ==
        PenPals.lettersIn(vetBack),
        "veteran XIII: the transplanted correspondence " +
            "round-trips CLOSED — every letter in has " +
            "its answer out, the thank-you included")
}
}


// ================= v0.15.0a: the preview pass =================
/** Queue #15 item 1: the previews show the look that is
 *  actually live. ONE derivation (LiveLook) serves the
 *  creator preview, the Journal YOU card and the mirror
 *  glass: sleepwear on a sleepover night (Sleepwear's
 *  own code — mirrorCode's, the shutter's), hero costume
 *  on a patrol night (Heroes' own code — figureCode's),
 *  day look otherwise. And sleepwear renders in street
 *  POV in the one legitimate window: a live sleepover
 *  evening, outdoors — the walk-home/escort window —
 *  with a street shutter freezing exactly what the
 *  street draws. Never daytime, never a wardrobe
 *  outfit: the pass stays derived and unpickable. */
private fun sectionV0150a(root: String) {
println("== v0.15.0a: the preview pass — Queue #15 item 1 ==")
run {
    val readme = File(root, "docs/CHANGELOG.md").readText()
    check(readme.contains("### v0.15.0a") &&
        readme.contains("## Status — v0.15.0a"),
        "preview: the README carries this build's changelog + status")
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "preview: the manifest itself carries 110 / 0.15.0b")
    val ktCount = File(root, "src/com/hunt3r/southparktown")
        .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
    check(ktCount == 137 && readme.contains("114 Kotlin files"),
        "preview: one new module (LiveLook.kt) — the tree " +
            "stands at 114 Kotlin files (counted $ktCount)")
    val llSrc = File(root,
        "src/com/hunt3r/southparktown/LiveLook.kt").readText()
    check(llSrc.contains("Sleepwear.playerCode") &&
        llSrc.contains("playerCostumeCodeFor") &&
        !llSrc.contains("softenHex") &&
        !llSrc.contains("POWER_EMBLEMS"),
        "preview: LiveLook derives NOTHING itself — its two " +
            "codes come straight from Sleepwear.playerCode " +
            "and Heroes.playerCostumeCodeFor; no second " +
            "softening, no second emblem table")
}

    // ---------- helpers ----------
    fun setDayP(s: GameState, absDay: Int) {
        s.absDay = absDay
        val key = keyFromOrdinal(FairCalendar
            .ordinalOfAbsDay(absDay))
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
        s.todayKey = key
    }
    fun slpPState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        var d = 0
        while (!Sleepovers.isSleepoverDay(d)) d++
        setDayP(s, d)
        return e to s
    }
    fun stageNightP(s: GameState, guests: List<String>,
                    hour: Int = 19) {
        s.life["slpDay"] = s.absDay
        s.lifeText["slpGuests"] = guests.joinToString(",")
        for (g in guests) {
            val a = s.agents[g] ?: continue
            a.location = YOUR_HOUSE; a.asleep = false
        }
        val me = s.agents.values.first { it.isPlayer }
        me.location = YOUR_HOUSE; me.asleep = false
        s.timeMin = hour * 60
    }
    fun patrolDayP(from: Int): Int {
        var d = from
        while (!Heroes.isPatrolNight(d)) d++
        return d
    }
    fun heroPState(seed: Long): Pair<Engine, GameState> {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "NewKid", DEFAULT_APPEARANCE)
        s.absDay = patrolDayP(s.absDay)
        Heroes.createHero(s, "The Porchlight", "nightsight")
        e.player(s).location = "KidsPark"
        s.timeMin = 20 * 60
        return e to s
    }

    // ---------- the preview on a sleepover night ----------
    run {
        val guests = listOf("Stan", "Kyle")
        val (_, s) = slpPState(950_001)
        stageNightP(s, guests)
        val look = LiveLook.playerLook(s)
        check(look.kind == LiveLook.SLEEP &&
            look.code == Sleepwear.mirrorCode(s) &&
            look.code == Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "preview: on a live sleepover night the preview's " +
                "look is SLEEP, and its code is the mirror's " +
                "own code — the shutter's player branch — so " +
                "creator, YOU card, glass and album agree")
        val altTop = CREATOR_OPTIONS["top"]!!.second
            .first { it.id != DEFAULT_APPEARANCE["top"] }.id
        val edited = DEFAULT_APPEARANCE + ("top" to altTop)
        val editedLook = LiveLook.lookFor(s, edited)
        check(editedLook.kind == LiveLook.SLEEP &&
            editedLook.code == Sleepwear.playerCode(edited),
            "preview: in the creator, the pajamas derive from " +
                "the look UNDER EDIT — change the top and the " +
                "preview's sleepwear re-derives from the edit, " +
                "not from the look still saved")
        s.timeMin = 12 * 60
        check(LiveLook.playerLook(s).kind == LiveLook.DAY,
            "preview: at noon on the planned day the preview " +
                "shows the day look — the evening has not opened")
        s.timeMin = Sleepovers.ARRIVE_FROM - 15
        check(LiveLook.playerLook(s).kind == LiveLook.DAY,
            "preview: a quarter hour before the evening opens, " +
                "still the day look")
        s.timeMin = Sleepovers.ARRIVE_FROM
        check(LiveLook.playerLook(s).kind == LiveLook.SLEEP,
            "preview: the minute the evening opens, the " +
                "preview is in pajamas")
        val (_, s2) = slpPState(950_002)
        s2.timeMin = 19 * 60
        check(LiveLook.playerLook(s2).kind == LiveLook.DAY,
            "preview: an evening with no plan standing is a " +
                "day-look evening in the preview too")
    }

    // ---------- the preview on a patrol night ----------
    run {
        val (_, s) = heroPState(950_010)
        val look = LiveLook.playerLook(s)
        check(look.kind == LiveLook.HERO &&
            look.code == Heroes.playerCostumeCode(s) &&
            look.code == Heroes.streetCostumeCode(s),
            "preview: on a patrol night inside the window the " +
                "preview's look is HERO, its code the costume " +
                "derivation itself — figureCode's, the street's")
        val atHome = s.agents.values.first { it.isPlayer }
        atHome.location = YOUR_HOUSE
        check(LiveLook.playerLook(s).kind == LiveLook.HERO &&
            Heroes.streetCostumeCode(s) == "",
            "preview: the preview's hero moment is the patrol " +
                "WINDOW, not the spot — at your house (no spot) " +
                "the mirror and previews still show the costume " +
                "you are dressed in, while the street keeps its " +
                "own spot gate, untouched")
        val altTop = CREATOR_OPTIONS["top"]!!.second
            .first { it.id != DEFAULT_APPEARANCE["top"] }.id
        val edited = DEFAULT_APPEARANCE + ("top" to altTop)
        check(LiveLook.lookFor(s, edited).code ==
            Heroes.playerCostumeCodeFor(s, edited),
            "preview: in the creator, the cape derives from " +
                "the look UNDER EDIT, through the same " +
                "playerCostumeCodeFor the worn look reads")
        s.timeMin = Heroes.PATROL_FROM - 15
        check(LiveLook.playerLook(s).kind == LiveLook.DAY,
            "preview: at 19:15 the preview is the day look — " +
                "the window has not opened")
        s.timeMin = Heroes.PATROL_FROM
        check(LiveLook.playerLook(s).kind == LiveLook.HERO,
            "preview: at 19:30 sharp the costume is on")
        s.timeMin = Heroes.PATROL_TO
        check(LiveLook.playerLook(s).kind == LiveLook.DAY,
            "preview: at 22:00 the preview is the day look " +
                "again — the window's far edge is exact")
        var d = s.absDay + 1
        while (Heroes.isPatrolNight(d) ||
            Sleepovers.isSleepoverDay(d)) d++
        setDayP(s, d); s.timeMin = 20 * 60
        check(LiveLook.playerLook(s).kind == LiveLook.DAY,
            "preview: an ordinary night at the same hour is " +
                "a day-look preview")
        val e2 = Engine(950_011); val s2 = e2.newState()
        e2.createPlayer(s2, "NewKid", DEFAULT_APPEARANCE)
        s2.absDay = patrolDayP(s2.absDay); s2.timeMin = 20 * 60
        check(!Heroes.heroCreated(s2) &&
            LiveLook.playerLook(s2).kind == LiveLook.DAY,
            "preview: with no hero identity made, a patrol " +
                "night previews the day look — no cape to show")
    }

    // ---------- precedence + the lived calendar ----------
    run {
        check((0..729).none {
                Sleepovers.isSleepoverDay(it) &&
                    Heroes.isPatrolNight(it) },
            "preview: across two lived years a sleepover " +
                "night is never a patrol night — the two live " +
                "looks cannot collide in the real calendar")
        val (_, s) = heroPState(950_020)
        stageNightP(s, listOf("Stan", "Kyle"), hour = 20)
        check(Sleepwear.eveningLive(s) && LiveLook.heroLive(s) &&
            LiveLook.playerLook(s).kind == LiveLook.SLEEP,
            "preview: on a STAGED state where both moments " +
                "stand (a tampered plan on a patrol night), " +
                "the stated precedence holds — SLEEP first, " +
                "the home night is the more specific fact")
    }

    // ---------- pajamas on the street: the walk-home window ----------
    run {
        val guests = listOf("Stan", "Kyle")
        val (_, s) = slpPState(950_030)
        stageNightP(s, guests, hour = 20)
        val me = s.agents.values.first { it.isPlayer }
        me.location = "MainStreet"
        s.playerInside = false
        val street = Sleepwear.streetCode(s)
        check(street.isNotEmpty() &&
            street == Sleepwear.playerCode(DEFAULT_APPEARANCE),
            "preview: out on the street on a live sleepover " +
                "night, your street code is your pajama " +
                "derivation — playerCode read live, the same " +
                "code the mirror shows back home")
        check(Sleepwear.figureCode(s,
                PhotoFigure("New Kid", "player", "happy"),
                "MainStreet") == street,
            "preview: the shutter abroad reads the same " +
                "window — figureCode's player branch freezes " +
                "exactly the code the street draws")
        val rec = Photos.compose(s, emptyList(), emptyList(),
            "New Kid", DEFAULT_APPEARANCE)
        val meFig = rec.figures.firstOrNull { it.kind == "player" }
        check(meFig != null && meFig.sleep == street,
            "preview: a frame composed on the street in the " +
                "window freezes the pajamas onto your figure — " +
                "the album will render the night you walked " +
                "home in them, through the same sleep pass")
        check(Sleepwear.figureCode(s,
                PhotoFigure("Stan", "cast", "happy"),
                "MainStreet") == "",
            "preview: the window dresses ONLY you — a guest " +
                "figure abroad freezes nothing; the guests' " +
                "pajamas live at the house, as ever")
        s.playerInside = true
        check(Sleepwear.streetCode(s) == "",
            "preview: indoors the street code is empty — the " +
                "street pass never draws you inside a room")
        s.playerInside = false
        s.timeMin = 12 * 60
        check(Sleepwear.streetCode(s) == "",
            "preview: at noon there is no street sleepwear — " +
                "never a daytime outfit, by the evening's own " +
                "arithmetic")
        s.timeMin = Sleepovers.ARRIVE_FROM - 15
        check(Sleepwear.streetCode(s) == "",
            "preview: before the evening opens, the street " +
                "is day clothes")
        val (_, s2) = slpPState(950_031)
        s2.agents.values.first { it.isPlayer }.location =
            "MainStreet"
        s2.timeMin = 20 * 60
        check(Sleepwear.streetCode(s2) == "",
            "preview: an ordinary evening abroad, no plan " +
                "standing, is street clothes")
        val (_, s3) = slpPState(950_032)
        stageNightP(s3, guests, hour = 20)
        setDayP(s3, s3.absDay + 1); s3.timeMin = 20 * 60
        s3.agents.values.first { it.isPlayer }.location =
            "MainStreet"
        check(Sleepwear.streetCode(s3) == "",
            "preview: the morning after (and its evening), " +
                "the window is gone with the plan")
    }

    // ---------- sleepwear stays unpickable ----------
    run {
        val optText = CREATOR_OPTIONS.values.flatMap { it.second }
            .joinToString(" ") { "${it.id} ${it.name}" }.lowercase()
        check(!optText.contains("pajama") &&
            !optText.contains("sleepwear") &&
            !optText.contains("nightcap"),
            "preview: no creator option sells sleep — no " +
                "pajama top, no sleepwear set, no nightcap hat; " +
                "the nightcap exists only inside the sleep " +
                "spec's derivation")
        check(Wardrobe.PIECES.none {
                it.id.lowercase().contains("pajama") ||
                    it.name.lowercase().contains("pajama") ||
                    it.id.lowercase().contains("sleep") },
            "preview: no wardrobe piece is sleepwear either — " +
                "the look can be lived on its night and never " +
                "chosen from a shelf")
    }

    // ---------- rendering writes nothing ----------
    run {
        val (_, s) = slpPState(950_040)
        stageNightP(s, listOf("Stan", "Kyle"), hour = 20)
        val (_, hs) = heroPState(950_041)
        val beforeS = encodeGameState(s)
        val beforeH = encodeGameState(hs)
        repeat(3) {
            LiveLook.playerLook(s); LiveLook.playerLook(hs)
            LiveLook.lookFor(s, DEFAULT_APPEARANCE)
            Sleepwear.streetCode(s); Sleepwear.eveningLive(s)
        }
        check(encodeGameState(s) == beforeS &&
            encodeGameState(hs) == beforeH,
            "preview: deciding a preview writes nothing — " +
                "both saves byte-identical after every read " +
                "this build adds")
    }

    // ---------- the wiring: one derivation, every surface ----------
    run {
        val ca = File(root,
            "src/com/hunt3r/southparktown/CreatorActivity.kt")
            .readText()
        val ja = File(root,
            "src/com/hunt3r/southparktown/JournalActivity.kt")
            .readText()
        val gv = File(root,
            "src/com/hunt3r/southparktown/GameView.kt").readText()
        check(ca.contains("LiveLook.lookFor(it, appearance.toMap())") &&
            ca.contains("preview.liveKind") &&
            ca.contains("LiveLook.SLEEP -> PaperDoll.drawDollSleep") &&
            ca.contains("LiveLook.HERO -> PaperDoll.drawDollHero"),
            "preview: the creator's preview is fed by " +
                "LiveLook.lookFor off the edited look, and " +
                "AvatarPreviewView draws the sleep and hero " +
                "kinds through KidArt's own two passes " +
                "(v0.16.0d: through the PaperDoll stills path)")
        check(ja.contains("LiveLook.playerLook(state)"),
            "preview: the Journal YOU card reads the same " +
                "derivation — one look for every preview")
        val figAt = gv.indexOf("private fun drawFigures")
        val doorAt = gv.indexOf("private fun drawEntryDoor")
        val stAt = gv.indexOf("Sleepwear.streetCode(st)")
        val slDrawAt = gv.indexOf("LiveLook.SLEEP -> KidArt.drawSleepFigure",
            figAt)
        val hrDrawAt = gv.indexOf("LiveLook.HERO -> KidArt.drawHeroFigure",
            figAt)
        check(stAt == -1 && slDrawAt > figAt && slDrawAt < doorAt &&
            hrDrawAt > figAt && hrDrawAt < doorAt,
            "preview: the figure pass draws you through " +
                "KidArt's sleep AND hero passes keyed on " +
                "LiveLook's kinds — inside drawFigures. " +
                "Sleepwear.streetCode is NO LONGER read here " +
                "(v0.15.0c re-pin: the outdoors-gated street " +
                "pajamas are retired with the first-person " +
                "view — the player stands in every scene and " +
                "wears LiveLook's code, whose sleep branch " +
                "IS Sleepwear.playerCode; streetCode's " +
                "derivation and its Photos-side pins stand)")
    }
}


// ============================================================
// v0.15.0b: pen pals — the visit, returned (Queue #15
// item 2). Season two of the correspondence: the program
// alternates. Her letters that year carry the plan (the
// JAR II fund); the top band's SECOND settlement — she
// has visited, no return trip on the books — stamps YOUR
// trip to Pinewood Flats instead of a second visit, and
// the invitation lands as a HOME letter, answerable in
// any season. The trip starts June 16, fifteen days
// after the settlement: the program's travel days ARE
// the seam between school years, stated in the letters,
// not shortened. Four days, four hosted beats (arrival,
// the tour, counter duty, the goodbye), one a day, each
// paying in her lane only; the morning after, her
// thank-you rides home mail, the mirror of season one's.
// Below the band in a return season, the maybe-next
// letter is reworded for year two. Still NOT cast, still
// no rail, no seat, no case machinery, no paper, no phone.
// ============================================================
private fun sectionV0150b(root: String) {
    println("== v0.15.0b: pen pals — the visit, returned ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val penSrc = File(srcDir, "PenPals.kt").readText()
    val gameSrc = File(srcDir, "GameActivity.kt").readText()
    val phoneSrc = File(srcDir, "Phone.kt").readText()
    val paperSrc = File(srcDir, "Newspaper.kt").readText()
    val talkSrc = File(srcDir, "TalkGate.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "return trip: the manifest carries this build " +
            "(110 / 0.15.0b)")
    check(readme.contains("### v0.15.0b") &&
        readme.contains("## Status — v0.15.0b"),
        "return trip: the README carries this build's " +
            "changelog entry and status section")
    val ktCount = srcDir.listFiles { f -> f.extension == "kt" }
        ?.size ?: 0
    check(ktCount == 137 && readme.contains("114 Kotlin files"),
        "return trip: no new module — PenPals.kt grows " +
            "the season; the tree stands at 114 Kotlin " +
            "files (found $ktCount)")
    check(PenPals.TRIP_MONTH == 6 && PenPals.TRIP_DAY == 16 &&
        PenPals.TRIP_DAYS == 4 && PenPals.TRIP_BEAT_PTS == 2 &&
        PenPals.TRIP_BEATS == listOf("arrive", "tour",
            "counter", "bye"),
        "return trip dials: June 16 — fifteen days after " +
            "the June 1 settlement, the travel days stated " +
            "as the seam — for four days, four beats in " +
            "order, two warmth apiece in her lane")

    fun palState(seed: Long): GameState {
        val e = Engine(seed)
        val s = e.newState()
        e.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
        return s
    }
    fun setDayE(s: GameState, key: String) {
        s.absDay = FairCalendar.absDayOfOrdinal(
            ordinalOfKey(key))
        s.todayKey = key
        s.gameYear = key.substring(0, 4).toInt()
        s.gameMonth = key.substring(4, 6).toInt()
        s.gameDay = key.substring(6, 8).toInt()
    }
    fun rollE(s: GameState) = PenPals.dailyRollover(s)
    fun arriveE(s: GameState) {
        val due = s.life["palNextDue"] ?: -1
        check(due >= 0, "return trip fixture: a letter is scheduled")
        setDayE(s, keyFromOrdinal(
            FairCalendar.ordinalOfAbsDay(due)))
        PenPals.dailyRollover(s)
    }
    fun signedState(seed: Long): GameState {
        val s = palState(seed)
        setDayE(s, "20261005")
        check(PenPals.signupOpen(s),
            "return trip fixture: the box is out on Oct 5")
        check(PenPals.signUp(s) != null,
            "return trip fixture: the signup lands")
        return s
    }
    /** Step a live season day by day, answering every
     *  letter the day it lands, stopping with [lastKey]
     *  processed and the settlement NOT yet fired. */
    fun driveSeason(s: GameState, lastKey: String) {
        var guard = 0
        while (s.todayKey < lastKey && guard++ < 400) {
            val ord = FairCalendar.ordinalOfAbsDay(s.absDay) + 1
            setDayE(s, keyFromOrdinal(ord))
            PenPals.dailyRollover(s)
            if (PenPals.canReply(s))
                PenPals.sendReply(s,
                    PenPals.TONES[PenPals.lettersOut(s) % 3])
        }
    }

    // ---------- her season-two voice: banks, denylist ----------
    run {
        val banks = mutableListOf<String>()
        banks += PenPals.PLAN_LINES
        banks += PenPals.INVITE_LETTER
        banks += PenPals.MAYBE_NEXT2_LETTER
        banks += PenPals.TRIP_THANKS_LETTER
        banks += PenPals.JOURNEY_LINE
        PenPals.TRIP_SCRIPTS.values.forEach { banks += it }
        banks += PenPals.HOST_TALK
        banks += PenPals.HOST_FACTS
        val low = banks.joinToString("\n").lowercase()
        check(PenPals.DENYLIST.none { it in low },
            "return trip voice: every new authored surface " +
                "— plan lines, the invitation, the year-two " +
                "maybe-next, the thank-you, the journey, " +
                "the beat scripts, the host pools — is " +
                "clean of the franchise/real-place denylist")
        check(PenPals.TRIP_SCRIPTS.keys ==
            PenPals.TRIP_BEATS.toSet() &&
            PenPals.TRIP_BEATS.all {
                PenPals.tripScript(it).size >= 2 &&
                    PenPals.tripScript(it).all { l ->
                        l.isNotBlank() } },
            "return trip voice: a script for every beat " +
                "and no beat scripted thin — arrival, tour, " +
                "counter duty, goodbye, all in her voice")
        check(PenPals.INVITE_LETTER.contains("June 16") &&
            low.contains("fifteen days") &&
            PenPals.INVITE_LETTER.contains("alternates") &&
            PenPals.JOURNEY_LINE.contains("Fifteen days"),
            "return trip voice: the invitation names the " +
                "day, the fifteen travel days, and the " +
                "alternation itself — the seam is stated " +
                "in the letters, never silently shortened")
        check(PenPals.MAYBE_NEXT2_LETTER.contains("JAR II") &&
            PenPals.TRIP_THANKS_LETTER.contains("rated") &&
            PenPals.PLAN_LINES.size == 3 &&
            PenPals.PLAN_LINES.all {
                it.contains("jar", true) ||
                    it.contains("alternates", true) ||
                    it.contains("fifteen", true) },
            "return trip voice: the year-two maybe-next " +
                "keeps the jar on the counter, the " +
                "thank-you rates the visit as she rates " +
                "everything, and the plan lines circle " +
                "the jar, the rule, and the road")
    }

    // ---------- the whole arc: two seasons, driven ----------
    run {
        val s = signedState(970_001)
        val friendship0 = s.friendship.toMap()
        // season one, answered faithfully to May 31
        driveSeason(s, "20270531")
        check(PenPals.bandOf(s) == PenPals.BAND_FRIEND_I,
            "return trip: (staging) season one closes at " +
                "the top band, answered letter for letter")
        setDayE(s, "20270601")
        rollE(s)
        check((s.life["palVisitYear"] ?: 0) == 2027 &&
            PenPals.tripYear(s) == 0,
            "return trip: the FIRST top-band settlement " +
                "keeps season one's shape — she visits, " +
                "and no trip stands on the books")
        setDayE(s, "20270614")
        rollE(s)
        check(PenPals.latestLetter(s) == PenPals.THANKS_LETTER &&
            PenPals.homeMailPending(s) &&
            PenPals.sendReply(s, PenPals.TONE_EVERYDAY) != null &&
            !PenPals.homeMailPending(s),
            "return trip: season one closes whole — her " +
                "thank-you rides home mail and is answered " +
                "there, the polish #14 shape")
        val ptsSeasonOne = PenPals.points(s)
        // season two: the box returns, same pal, warmth kept
        setDayE(s, "20271005")
        check(PenPals.signupOpen(s),
            "return trip: the box comes back out for " +
                "the 2028 pairing")
        val rejoin = PenPals.signUp(s)
        check(rejoin != null && rejoin.contains("Same pal") &&
            PenPals.signedYear(s) == 2028 &&
            PenPals.points(s) == ptsSeasonOne &&
            PenPals.tripPending(s),
            "return trip: re-pairing is frictionless for " +
                "an established correspondence — same pal, " +
                "warmth carried whole from season one, " +
                "never reset — and the season's shape is " +
                "the return trip from day one")
        check(PenPals.pageLines(s).any {
                it.contains("RETURN trip") },
            "return trip: the 📬 page names the season's " +
                "shape while it is still only a shape")
        // her letters carry the plan, over days
        arriveE(s)
        check(PenPals.PLAN_LINES.any {
                PenPals.latestLetter(s)!!.contains(it) },
            "return trip: a season-two letter carries a " +
                "plan line — the invitation is built over " +
                "days, in her ordinary mail, before it lands")
        // dormancy and revival, unchanged in season two
        arriveE(s)
        arriveE(s)
        check(PenPals.isDormant(s),
            "return trip dormancy: three unanswered " +
                "letters in season two put the route to " +
                "sleep by the same stated rule")
        val outBefore = PenPals.lettersOut(s)
        check(PenPals.sendReply(s, PenPals.TONE_BIG) != null &&
            !PenPals.isDormant(s) &&
            (s.life["palRevived"] ?: 0) == 1 &&
            PenPals.lettersOut(s) == outBefore + 1,
            "return trip dormancy: one letter reopens " +
                "the route in season two too — measured " +
                "by the revival stamp and the letter out, " +
                "the warmth already standing at its cap")
        // the rest of the season, answered
        driveSeason(s, "20280531")
        check(PenPals.bandOf(s) == PenPals.BAND_FRIEND_I &&
            PenPals.tripPending(s),
            "return trip: (staging) season two closes at " +
                "the top band with the trip still pending")
        // the settlement: the direction reverses
        val inBefore = PenPals.lettersIn(s)
        setDayE(s, "20280601")
        rollE(s)
        check(PenPals.lettersIn(s) == inBefore + 1 &&
            PenPals.latestLetter(s) == PenPals.INVITE_LETTER &&
            PenPals.tripYear(s) == 2028 &&
            PenPals.tripStart(s) == FairCalendar
                .absDayOfOrdinal(ordinalOfKey("20280616")) &&
            (s.life["palVisitYear"] ?: 0) == 2027 &&
            PenPals.homeMailPending(s),
            "return trip: the second top-band settlement " +
                "stamps YOUR trip — June 16, fifteen days " +
                "after the settlement, the seam kept — " +
                "the invitation lands as a home letter, " +
                "and her visit is NOT stamped a second time")
        rollE(s)
        check(PenPals.lettersIn(s) == inBefore + 1,
            "return trip: the invitation fires once")
        setDayE(s, "20280610")
        check(!PenPals.visitLive(s) &&
            PenPals.blockAt(s, 13 * 60) == null &&
            PenPals.presentAt(s, "KidsPark", false).isEmpty(),
            "return trip: June 10 of year two she is NOT " +
                "in town — the guest is the host now")
        // the seam: fifteen days, and home mail crosses it
        setDayE(s, "20280605")
        check(!PenPals.live(s) && !PenPals.tripLive(s) &&
            PenPals.pageLines(s).any {
                it.contains("RETURN TRIP IS STAMPED") },
            "return trip: inside the seam the year is " +
                "settled and the trip is still ahead — " +
                "the page says so plainly")
        check(PenPals.canReply(s) &&
            PenPals.sendReply(s, PenPals.TONE_FUNNY) != null &&
            !PenPals.homeMailPending(s),
            "return trip: the invitation is answerable " +
                "inside the seam, at home, in any season — " +
                "the home-mail rule rides the return whole")
        // the trip: four days, four beats, one a day
        setDayE(s, "20280615")
        check(!PenPals.tripLive(s) &&
            PenPals.tripBeatToday(s) == null,
            "return trip: June 15 is still the seam — " +
                "the road has not been crossed yet")
        setDayE(s, "20280616")
        check(PenPals.tripLive(s) &&
            PenPals.tripDayIndex(s) == 0 &&
            PenPals.tripBeatToday(s) == PenPals.BEAT_ARRIVE,
            "return trip: day one offers the arrival")
        rollE(s)
        check(s.events.any { it.contains("✈️") &&
                it.contains("day 1 of 4") },
            "return trip: the trip's mornings note " +
                "themselves on the ticker, beat and all")
        val pureBefore = encodeGameState(s)
        PenPals.tripBeatToday(s); PenPals.tripScript("tour")
        PenPals.tripDone(s); PenPals.pageLines(s)
        check(encodeGameState(s) == pureBefore,
            "return trip: the beat offers, the scripts " +
                "and the page are pure reads — hosting " +
                "writes nothing until a beat is kept")
        check(PenPals.noteTripBeat(s,
                PenPals.BEAT_ARRIVE) &&
            PenPals.BEAT_ARRIVE in PenPals.tripDone(s) &&
            !PenPals.noteTripBeat(s, PenPals.BEAT_ARRIVE) &&
            PenPals.tripBeatToday(s) == null,
            "return trip: a kept beat stamps once — " +
                "the stamp is the receipt, and the day " +
                "offers nothing twice (the driven " +
                "correspondence stands at the warmth " +
                "cap, so the payment itself is measured " +
                "on a staged state below)")
        val p = palState(970_004)
        p.life["palTripStart"] = p.absDay
        p.life["palPts"] = 10
        val p0 = PenPals.points(p)
        check(PenPals.tripBeatToday(p) ==
            PenPals.BEAT_ARRIVE &&
            PenPals.noteTripBeat(p, PenPals.BEAT_ARRIVE) &&
            PenPals.points(p) - p0 ==
                PenPals.TRIP_BEAT_PTS &&
            !PenPals.noteTripBeat(p, PenPals.BEAT_ARRIVE) &&
            PenPals.points(p) - p0 ==
                PenPals.TRIP_BEAT_PTS,
            "return trip: a kept beat pays exactly its " +
                "two warmth, once — the second stamp is " +
                "refused and pays nothing")
        setDayE(s, "20280617")
        check(PenPals.tripBeatToday(s) == PenPals.BEAT_TOUR &&
            PenPals.pageLines(s).any {
                it.contains("YOU ARE THERE") },
            "return trip: day two offers the tour, and " +
                "the page knows where you are")
        PenPals.noteTripBeat(s, PenPals.BEAT_TOUR)
        setDayE(s, "20280618")
        check(PenPals.tripBeatToday(s) ==
            PenPals.BEAT_COUNTER,
            "return trip: day three is counter duty")
        PenPals.noteTripBeat(s, PenPals.BEAT_COUNTER)
        setDayE(s, "20280619")
        check(PenPals.tripBeatToday(s) == PenPals.BEAT_BYE,
            "return trip: the last day offers the goodbye")
        PenPals.noteTripBeat(s, PenPals.BEAT_BYE)
        check(s.lifeText["palTripDone"] ==
            "arrive,tour,counter,bye" &&
            PenPals.tripDone(s) == PenPals.TRIP_BEATS.toSet(),
            "return trip: the kept beats stand in the " +
                "trip's own order in the record")
        check(s.friendship == friendship0 &&
            PenPals.PAL !in s.friendship,
            "return trip: four days in her town moved " +
                "her lane and ONLY her lane — the town's " +
                "friendship book never gained her name")
        // the morning after: the symmetry comes home
        setDayE(s, "20280620")
        check(!PenPals.tripLive(s), "return trip: June " +
            "20, you are a letter again")
        val inTrip = PenPals.lettersIn(s)
        rollE(s)
        check(PenPals.lettersIn(s) == inTrip + 1 &&
            PenPals.latestLetter(s) ==
                PenPals.TRIP_THANKS_LETTER &&
            PenPals.homeMailPending(s),
            "return trip: the morning after the trip, " +
                "her thank-you is in the HOME box — the " +
                "exact mirror of the letter she sent " +
                "after visiting you")
        rollE(s)
        check(PenPals.lettersIn(s) == inTrip + 1,
            "return trip: the trip thank-you fires once")
        check(PenPals.pageLines(s).any {
                it.contains("The return trip") &&
                    it.contains("Kept:") } &&
            PenPals.pageLines(s).any {
                it.contains("The Goodbye") },
            "return trip: the 📬 page keeps the trip — " +
                "the days, the direction, and the beats " +
                "that were kept, goodbye among them")
        val back = decodeGameState(encodeGameState(s))
        check(PenPals.tripDone(back) == PenPals.tripDone(s) &&
            PenPals.tripYear(back) == 2028 &&
            PenPals.points(back) == PenPals.points(s) &&
            PenPals.pageLines(back) == PenPals.pageLines(s),
            "return trip: the whole season survives the " +
                "save round trip — additive palTrip* keys " +
                "only, nothing lost in the fold")
    }

    // ---------- below the band in a return season ----------
    run {
        val s = signedState(970_002)
        // season one stands on the books by its stamps
        s.life["palVisitYear"] = 2027
        s.life["palSettledYear"] = 2027
        setDayE(s, "20271005")
        check(PenPals.signUp(s) != null &&
            PenPals.signedYear(s) == 2028 &&
            PenPals.tripPending(s),
            "return trip: (staging) a second season " +
                "opens over a visited first")
        s.life["palPts"] = PenPals.BAND_FRIEND - 1
        setDayE(s, "20280601")
        rollE(s)
        check(PenPals.latestLetter(s) ==
            PenPals.MAYBE_NEXT2_LETTER &&
            PenPals.tripYear(s) == 0 &&
            PenPals.homeMailPending(s),
            "return trip: one point below the band in a " +
                "return season, the year ends with the " +
                "year-two maybe-next — the jar stays on " +
                "the counter — and no trip is stamped")
        check(PenPals.MAYBE_NEXT2_LETTER !=
            PenPals.MAYBE_NEXT_LETTER,
            "return trip: the year-two letter is its own " +
                "letter, not season one's reworded in place")
    }

    // ---------- hostile paper: the stamps degrade sanely ----------
    run {
        val h = palState(970_003)
        h.life["palTripYear"] = 2028
        h.life["palTripStart"] = -99999
        h.lifeText["palTripDone"] = "bogus,arrive"
        check(!PenPals.tripLive(h) &&
            PenPals.tripBeatToday(h) == null &&
            !PenPals.noteTripBeat(h, "bogus"),
            "return trip hostile: a nonsense start date " +
                "opens no trip, offers no beat, and an " +
                "unnamed beat cannot be stamped")
        check(PenPals.noteTripBeat(h, PenPals.BEAT_TOUR) &&
            PenPals.BEAT_TOUR in PenPals.tripDone(h),
            "return trip hostile: the offering is the " +
                "gate — over a noisy record a real beat " +
                "still stamps, and the noise rides along " +
                "ignored by every reader that matters")
        val back = decodeGameState(encodeGameState(h))
        check(PenPals.tripYear(back) == 2028 &&
            PenPals.tripDone(back) ==
                PenPals.tripDone(h),
            "return trip hostile: the trip keys ride " +
                "the save round trip as they stand")
    }

    // ---------- wiring and the stated absences ----------
    run {
        check(gameSrc.contains("PenPals.tripBeatToday(state)") &&
            gameSrc.contains("openTripSheet") &&
            gameSrc.contains("PenPals.noteTripBeat(state, beat)") &&
            gameSrc.contains("PenPals.JOURNEY_LINE"),
            "return trip wiring: the mailbox offers the " +
                "day's beat, the sheet hosts it in her " +
                "voice, the journey narrates the arrival, " +
                "and the sheet's close stamps the beat")
        check(!phoneSrc.contains("PenPals") &&
            !paperSrc.contains("PenPals") &&
            !talkSrc.contains("PenPals") &&
            !penSrc.contains("state.friendship[") &&
            !penSrc.contains("gatheringBlock") &&
            !penSrc.contains("Mystery"),
            "return trip absences, pinned again for the " +
                "new surfaces: no phone, no paper, no " +
                "TalkGate rail, no friendship writes, no " +
                "agenda seat, and no case machinery on " +
                "the correspondence — the trip claims " +
                "nothing but her lane and the mailbox")
    }
}

// ============================================================
// v0.15.0c: THE VISUAL OVERHAUL — Lucky's direct playtest
// directive (Oct 17 ~19:08 CDT), preempting the roadmap
// queue (the gallery show is re-queued after it). The
// first-person POV is replaced by a PAPER CUT-OUT scene
// renderer: every scene is a stack of flat paper planes
// (PaperScene), every street is lined with buildings
// (PaperDressing), figures assemble from the measured
// sheet specs in the sheets' own piece order — torso,
// head base, eyes, mouth, hair, hat (FigurePieces) — the
// player STANDS in the scene and WALKS to whatever you
// tap (PaperWalk + PaperTap), the school bus runs for
// real, and a public bus network prices rides off the
// Walk graph at bus speed (BusNetwork). The rendering
// pins this build replaced were re-pinned at their own
// sites with their reasons stated; the behavioral pins
// (economy, gates, derivations) stand untouched.

private fun sectionV0150c(root: String) {
    println("== v0.15.0c: the visual overhaul — paper scenes, the kid on screen, the bus ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val gv = File(srcDir, "GameView.kt").readText()
    val sceneSrc = File(srcDir, "SceneArt.kt").readText()
    val gaSrc = File(srcDir, "GameActivity.kt").readText()
    val busSrc = File(srcDir, "BusNetwork.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "overhaul: the manifest carries this build (111 / 0.15.0c)")
    check(readme.contains("### v0.15.0c") &&
        readme.contains("## Status — v0.15.0c"),
        "overhaul: the README carries this build's status " +
            "and changelog")

    // ---------- the layer model ----------
    run {
        val order = PaperScene.EXTERIOR
        check(order == listOf(PaperPlane.SKY, PaperPlane.FAR,
            PaperPlane.BUILDINGS, PaperPlane.GROUND,
            PaperPlane.PROPS, PaperPlane.FIGURES,
            PaperPlane.TRAFFIC, PaperPlane.FOREGROUND),
            "paper: the exterior stack is sky → far → " +
                "buildings → ground → props → figures → " +
                "traffic → foreground")
        check(order.zipWithNext().all { (a, b) ->
            a.band.ordinal <= b.band.ordinal },
            "paper: plane bands never step backwards " +
                "(BACKGROUND → MIDGROUND → FOREGROUND)")
        check(PaperPlane.FIGURES.band ==
            Depth.bandOfLayer("figures", false) &&
            PaperPlane.TRAFFIC.band ==
            Depth.bandOfLayer("traffic", false) &&
            PaperPlane.FOREGROUND.band == Band.FOREGROUND,
            "paper: the planes' bands agree with Depth's " +
                "chain bands")
        val layers = Depth.EXTERIOR_LAYERS.map { it.id }
        check(layers.indexOf("neighbors") in
            0 until layers.indexOf("light") &&
            layers.indexOf("street") in
            0 until layers.indexOf("light") &&
            layers.indexOf("traffic") > layers.indexOf("foreground"),
            "paper: Depth's chain carries the neighbor row " +
                "and the street in the background half, and " +
                "traffic after the foreground frieze")
        check(PaperPlane.SKY.parallax == 0f &&
            PaperPlane.FAR.parallax in 0.3f..0.8f &&
            PaperPlane.BUILDINGS.parallax in 0.7f..0.95f &&
            PaperPlane.FAR.parallax < PaperPlane.BUILDINGS.parallax &&
            PaperPlane.BUILDINGS.parallax < PaperPlane.GROUND.parallax &&
            PaperPlane.GROUND.parallax == 1f &&
            PaperPlane.FOREGROUND.parallax == 1f,
            "paper: parallax deepens toward the camera — " +
                "sky still, far range slow, the buildings " +
                "slower than the world, ground and " +
                "foreground world-locked")
        check(PaperScene.INTERIOR == listOf(PaperRoomPlane.WALL,
            PaperRoomPlane.FLOOR, PaperRoomPlane.FURNITURE_BACK,
            PaperRoomPlane.FIGURES, PaperRoomPlane.FURNITURE_FRONT),
            "paper: interiors stack wall → floor → back " +
                "furniture → figures → front furniture")
        val staged = PaperScene.depthSorted(listOf(
            "a" to 0.9f, "b" to 0.2f, "c" to 0.5f)) { it.second }
            .map { it.first }
        check(staged == listOf("b", "c", "a"),
            "paper: y-sort paints the lowest baseline " +
                "(nearest the camera) last, on top")
    }

    // ---------- a town, not a house: the dressing census ----------
    run {
        var minCensus = Int.MAX_VALUE
        for (loc in LOCATIONS.values) {
            minCensus = minOf(minCensus, PaperDressing.census(loc))
            check(PaperDressing.census(loc) >= PaperDressing.MIN_CENSUS,
                "overhaul census: ${loc.id} is a dressed " +
                    "scene (${PaperDressing.census(loc)} " +
                    "pieces ≥ ${PaperDressing.MIN_CENSUS})")
        }
        check(minCensus >= PaperDressing.MIN_CENSUS,
            "overhaul census: no location in town falls " +
                "below the dressing floor")
        for (loc in LOCATIONS.values) {
            val d = PaperDressing.forLocation(loc)
            if (!d.hasStreet) continue
            check(1 + d.neighborCount + PaperDressing.FAR_ROW_MIN >= 5,
                "overhaul streets: ${loc.id}'s street reads " +
                    "as a street — facade + ${d.neighborCount} " +
                    "neighbors + the far row, never a lone house")
            if (loc.kind == "house" || loc.kind == "shop" ||
                loc.kind == "civic" || loc.id == "MainStreet") {
                check(d.neighborCount >= 3,
                    "overhaul streets: ${loc.id} is lined — " +
                        "${d.neighborCount} neighbors across " +
                        "the background plane")
            }
        }
        val dt = PaperDressing.forLocation(LOCATIONS["MainStreet"]!!)
        check(dt.downtown && dt.neighborTall &&
            PaperDressing.AWNING in dt.props &&
            PaperDressing.STOREFRONT in dt.props,
            "overhaul downtown: Main Street is a commercial " +
                "district — tall dense buildings, " +
                "storefronts, awnings")
        val stop = PaperDressing.forLocation(LOCATIONS["BusStop"]!!)
        check(stop.busStation && PaperDressing.SIGN in stop.props,
            "overhaul: the Bus Stop carries its sign — the " +
                "landmark reads instantly")
        for (loc in LOCATIONS.values) {
            check(PaperDressing.forLocation(loc).busStation ==
                (loc.id in BusNetwork.STATIONS),
                "overhaul: ${loc.id}'s station dressing " +
                    "agrees with the bus network")
        }
        check(!PaperDressing.forLocation(LOCATIONS["StarksPond"]!!).traffic &&
            !PaperDressing.forLocation(LOCATIONS["TegridyFarms"]!!).hasStreet &&
            PaperDressing.forLocation(LOCATIONS["MainStreet"]!!).traffic,
            "overhaul: traffic belongs to streets — the " +
                "pond and the farm stay quiet, Main Street rolls")
    }

    // ---------- figures: the sheets' piece order ----------
    run {
        val canon = listOf(FigurePiece.BACK, FigurePiece.BEHIND_HAIR,
            FigurePiece.LEGS, FigurePiece.TORSO, FigurePiece.ARMS,
            FigurePiece.HEAD, FigurePiece.EYES, FigurePiece.MOUTH,
            FigurePiece.FACE_EXTRA, FigurePiece.HAIR,
            FigurePiece.HAT)
        fun ordered(stack: List<FigurePiece>): Boolean {
            val idx = stack.map { canon.indexOf(it) }
            return idx == idx.sorted() &&
                idx.distinct().size == idx.size
        }
        for ((name, spec) in KidArt.SHEETS) {
            val stack = FigurePieces.stackFor(spec)
            check(ordered(stack),
                "pieces: $name assembles in the sheets' " +
                    "order (back → legs → torso → arms → " +
                    "head → eyes → mouth → extras → hair → hat)")
            check(FigurePiece.HEAD in stack &&
                FigurePiece.EYES in stack &&
                FigurePiece.TORSO in stack &&
                FigurePiece.LEGS in stack,
                "pieces: $name has a body, a head base and " +
                    "eyes on the face")
            check((FigurePiece.MOUTH in stack) ==
                (spec.special != "kenny_parka"),
                "pieces: $name's mouth sits on the face " +
                    "plane — present unless the parka " +
                    "covers it")
            check(FigurePieces.faceClear(spec),
                "pieces: $name's hair and hat frame the " +
                    "face — no shape ever covers an eye " +
                    "or the mouth")
        }
        check(FigurePiece.MOUTH !in
            FigurePieces.stackFor(KidArt.SHEETS["Kenny"]!!),
            "pieces: Kenny's parka hood covers the mouth — " +
                "the one covered mouth in town, by the sheet")
        val wendy = KidArt.SHEETS["Wendy"]!!
        check(FigurePiece.BEHIND_HAIR in FigurePieces.stackFor(wendy) &&
            FigurePiece.HAIR in FigurePieces.stackFor(wendy) &&
            FigurePiece.HAT in FigurePieces.stackFor(wendy),
            "pieces: Wendy's long hair runs behind the " +
                "torso AND frames the face, beret above it")
        check(FigurePiece.HAT in
            FigurePieces.stackFor(KidArt.SHEETS["Kyle"]!!),
            "pieces: Kyle's chullo sits on the hat plane, " +
                "above the hair")
        val garrison = KidArt.SHEETS["Garrison"]!!
        check(FigurePiece.FACE_EXTRA in FigurePieces.stackFor(garrison),
            "pieces: Garrison's face extras (brows, " +
                "wrinkles, glasses) ride the face plane")
        val stanD = FigureGeometry.derive(KidArt.SHEETS["Stan"]!!)
        check(stanD.headShare in 0.5f..0.75f,
            "pieces: a kid measures to the New Kid " +
                "calibration — head is ${stanD.headShare} " +
                "of the figure")
        val garD = FigureGeometry.derive(garrison)
        check(garD.headShare in 0.28f..0.38f &&
            garD.legShare >= garD.torsoShare &&
            garD.torsoShare < 0.36f,
            "pieces: an adult measures head ~1/3, torso " +
                "just under, legs just over (head " +
                "${garD.headShare}, torso ${garD.torsoShare}, " +
                "legs ${garD.legShare})")
        val avatarD = FigureGeometry.derive(avatarSpec(DEFAULT_APPEARANCE))
        check(avatarD.headShare in 0.5f..0.75f,
            "pieces: YOUR figure measures to the same kid " +
                "calibration as the cast")
        check(FigurePieces.faceClear(avatarSpec(DEFAULT_APPEARANCE)),
            "pieces: your own hair and hat never cover " +
                "your face either")
    }

    // ---------- the walk: tap-to-move state machine ----------
    run {
        var s = PaperWalk.State(x = 0.5f, band = 0.6f)
        s = PaperWalk.tapTarget(s, "kid", "Stan", 0.7f, 0.6f)
        check(s.walking && s.pending?.id == "Stan",
            "walk: a tap on a person starts the walk with " +
                "the talk pending")
        var fired: PaperWalk.Pending? = null
        var steps = 0
        while (s.walking && steps < 400) {
            val out = PaperWalk.step(s, 0.05f)
            s = out.first
            if (out.second != null) fired = out.second
            steps++
        }
        check(fired?.kind == "kid" && fired?.id == "Stan" &&
            !s.walking && kotlin.math.abs(s.x - 0.7f) < 0.01f,
            "walk: arrival fires the pending interaction " +
                "exactly once, at the target")
        val g = PaperWalk.tapGround(PaperWalk.State(), 0.2f, 0.5f)
        check(g.walking && g.pending == null && g.facing == -1,
            "walk: open ground walks with nothing pending, " +
                "facing the way you're headed")
        val t = PaperWalk.tapTarget(
            PaperWalk.State(x = 0.3f, band = 0.5f,
                tx = 0.3f, tband = 0.5f),
            "door", "", 0.3f, 0.5f)
        val first = PaperWalk.step(t, 0.05f)
        check(first.second?.kind == "door",
            "walk: tapping what you already stand at fires " +
                "on the first step — nothing waits")
        var ph = PaperWalk.State()
        ph = PaperWalk.tapGround(ph, 0.9f, 0.6f)
        val ph2 = PaperWalk.step(ph, 0.05f).first
        check(ph2.phase > 0f && ph2.x > ph.x,
            "walk: the step cycle advances as the kid " +
                "moves (the paper shuffle)")
    }

    // ---------- tap resolution ----------
    run {
        val a = PaperTap.Item("kid", "Stan", 100f, 100f, 40f, 60f, 160f)
        val b = PaperTap.Item("kid", "Kyle", 130f, 100f, 40f, 60f, 160f)
        check(PaperTap.resolve(listOf(a, b), 112f, 100f)?.id == "Stan",
            "tap: overlapping figures resolve to the " +
                "nearest center — the kid you aimed at")
        val prop = PaperTap.Item("bench", "", 100f, 100f, 80f, 40f, 140f)
        check(PaperTap.resolve(listOf(prop, a), 100f, 100f)?.kind == "kid",
            "tap: a figure beats the prop standing with it")
        val p2 = PaperTap.Item("lamp", "", 100f, 100f, 80f, 40f, 140f)
        check(PaperTap.resolve(listOf(prop, p2), 100f, 100f)?.kind == "lamp",
            "tap: between props, the topmost (last drawn) wins")
        check(PaperTap.resolve(listOf(a), 400f, 400f) == null,
            "tap: empty ground resolves to nothing — a " +
                "plain walk")
    }

    // ---------- the bus network ----------
    run {
        check(BusNetwork.STATIONS.size >= 8 &&
            BusNetwork.STATIONS.all { it in LOCATIONS },
            "bus: the network stands at real places all " +
                "over town (${BusNetwork.STATIONS.size} stations)")
        check(BusNetwork.rawRouteMinutes("KennysHouse", "StarksPond") == 87,
            "bus: the derivation walks the real graph — " +
                "Kennys→Starks is 87 raw minutes on foot")
        check(BusNetwork.rideMinutes("KennysHouse", "StarksPond") == 35,
            "bus: 87 raw minutes ride in 35 — " +
                "ceil(87 × 2/5); the bus beats the walk " +
                "without teleporting")
        for (x in BusNetwork.STATIONS) for (y in BusNetwork.STATIONS) {
            if (x == y) continue
            val raw = BusNetwork.rawRouteMinutes(x, y)
            val ride = BusNetwork.rideMinutes(x, y)
            check(ride >= BusNetwork.MIN_RIDE_MIN &&
                ride * 4 >= raw && (raw < 25 || ride < raw),
                "bus: $x→$y rides $ride on $raw raw — " +
                    "never free, never slower than walking " +
                    "a real route, never absurdly fast")
        }
        check(BusNetwork.destinationsFrom("BusStop")
            .map { it.first }.toSet() ==
            (BusNetwork.STATIONS - "BusStop"),
            "bus: every station serves every other station")
        check(Walk.rideCostMinutes("MainStreet", "TegridyFarms") ==
            BusNetwork.rideMinutes("MainStreet", "TegridyFarms"),
            "bus: Walk's ride price IS BusNetwork's " +
                "derivation — one price behind both doors " +
                "(the Go menu and the station signs)")
        check(!busSrc.contains("Parade"),
            "bus: the derivation never pays the parade " +
                "through-street delay — the standing bus " +
                "exemption, kept")
    }

    // ---------- the school bus ----------
    run {
        val e = Engine(150015)
        val s = e.newState()
        e.createPlayer(s, "Rider", DEFAULT_APPEARANCE)
        var day = 0
        while (!School.isSchoolDay(day)) day++
        s.absDay = day
        s.busPass = false
        e.player(s).location = "BusStop"
        s.timeMin = 7 * 60 + 30
        check(SchoolBus.morningWaiting(s) &&
            SchoolBus.busAt(s, "BusStop") &&
            !SchoolBus.busAt(s, "Elementary"),
            "school bus: on a school morning it stands " +
                "at the stop, not at the school")
        check(SchoolBus.destFrom(s, "BusStop") == "Elementary",
            "school bus: the morning run goes to school")
        val out = SchoolBus.ride(s, advance = false)
        check(out.ok && e.player(s).location == "Elementary" &&
            out.minutes ==
            BusNetwork.rideMinutes("BusStop", "Elementary") &&
            (s.life["schoolBusRides"] ?: 0) == 1,
            "school bus: the ride is real — you land at " +
                "school, priced by the derivation, no " +
                "pass needed")
        s.timeMin = 15 * 60 + 30
        check(SchoolBus.eveningWaiting(s) &&
            SchoolBus.busAt(s, "Elementary") &&
            SchoolBus.destFrom(s, "Elementary") == "BusStop",
            "school bus: in the afternoon it waits at " +
                "the school to take you back")
        val back = SchoolBus.ride(s, advance = false)
        check(back.ok && e.player(s).location == "BusStop" &&
            (s.life["schoolBusRides"] ?: 0) == 2,
            "school bus: the evening run brings you home")
        s.timeMin = 12 * 60
        check(!SchoolBus.busAt(s, "BusStop") &&
            !SchoolBus.busAt(s, "Elementary"),
            "school bus: midday it is nowhere — the run " +
                "is a morning and an evening thing")
        var wknd = 0
        while (School.isSchoolDay(wknd)) wknd++
        s.absDay = wknd
        s.timeMin = 7 * 60 + 30
        check(!SchoolBus.morningWaiting(s),
            "school bus: no school day, no bus")
    }

    // ---------- the wiring ----------
    run {
        check(gv.contains("PaperWalk.stepClamped(pwalk") &&
            gv.contains("LiveLook.playerLook(st)") &&
            gv.contains("KidArt.drawPlayerAvatar") &&
            gv.contains("drawTraffic(c, st, loc, worldW, h, seed)") &&
            gv.contains("SceneArt.drawBusStopSign(") &&
            gv.contains("SchoolBus.busAt(st, loc.id)"),
            "overhaul wiring: GameView steps the walk, " +
                "wears LiveLook on the player figure, and " +
                "draws the traffic and the buses")
        val trafAt = gv.indexOf("drawTraffic(")
        check(trafAt > gv.indexOf("SceneArt.drawForegroundLayer(") &&
            trafAt < gv.indexOf("drawSigns(c, loc"),
            "overhaul wiring: traffic paints after the " +
                "foreground frieze and before the " +
                "signposts — Depth's chain order, on screen")
        check(sceneSrc.contains("PaperPlane.FAR.parallax") &&
            sceneSrc.contains("PaperPlane.BUILDINGS.parallax"),
            "overhaul wiring: SceneArt rides the far " +
                "range and the neighbor row at their plane " +
                "factors — the parallax is real")
        check(gaSrc.contains("BusNetwork.destinationsFrom(") &&
            gaSrc.contains("SchoolBus.ride(state") &&
            gaSrc.contains("gameView.onBusStation = ") &&
            gaSrc.contains("gameView.onSchoolBus = "),
            "overhaul wiring: GameActivity serves the " +
                "station picker and the school run off " +
                "the same derivations")
        check(!gv.contains("walkX"),
            "overhaul: the old walk-marker state is gone " +
                "— the kid IS the marker now")
    }
}

// ================= v0.15.0d =================
private fun sectionV0150d(root: String) {
    println("== v0.15.0d: the overhaul correction — one scale, a walkable band, a bus that runs, the baseline town ==")
    val srcDir = File(root, "src/com/hunt3r/southparktown")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()
    val gv = File(srcDir, "GameView.kt").readText()
    val sceneSrc = File(srcDir, "SceneArt.kt").readText()
    val iaSrc = File(srcDir, "InteriorArt.kt").readText()
    val paperSrc = File(srcDir, "PaperScene.kt").readText()

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "correction: the manifest carries this build (112 / 0.15.0d)")
    check(readme.contains("### v0.15.0d") &&
        readme.contains("## Status — v0.15.0d"),
        "correction: the README carries this build's status and changelog")

    // ---------- 1 + 2: one world scale, the ladder ----------
    run {
        val h = 2400f
        check(WorldScale.KID_FRAC in 0.18f..0.22f,
            "scale: the kid figure composes at ${WorldScale.KID_FRAC} " +
                "of scene height — Lucky's 18–22% band")
        check(abs(WorldScale.kidPx(h) - h * WorldScale.KID_FRAC) < 0.01f,
            "scale: kidPx IS the fraction, one derivation")
        check(WorldScale.LADDER.zipWithNext().all { (a, b) -> a.second > b.second },
            "scale: the ladder descends house > tree > car length > " +
                "adult > kid > trash, strictly")
        check(WorldScale.ADULT_RATIO in 1.35f..1.50f,
            "scale: adults compose at ${WorldScale.ADULT_RATIO}× kid")
        val doorRatio = WorldScale.DOOR_U / WorldScale.ADULT_RATIO
        check(doorRatio in 1.15f..1.30f,
            "scale: a door is $doorRatio× an adult (1.15–1.30)")
        check(WorldScale.TRASH_U <= 0.45f,
            "scale: a trash can is ${WorldScale.TRASH_U}× kid (≤ 0.45)")
        check(WorldScale.SAPLING_U < 1.0f && WorldScale.SILO_U >
            WorldScale.HOUSE_PEAK_U,
            "scale: the exceptions are IN the data — the sapling " +
                "small on purpose, the silo a landmark on purpose")
        check(WorldScale.units(WorldScale.HOUSE_PEAK_U, h) >
            WorldScale.units(WorldScale.PINE_U, h) &&
            WorldScale.units(WorldScale.PINE_U, h) >
            WorldScale.units(WorldScale.CAR_LEN_U, h) &&
            WorldScale.units(WorldScale.CAR_LEN_U, h) >
            WorldScale.figurePx(h, WorldScale.ADULT_RATIO) &&
            WorldScale.figurePx(h, 1.0f) >
            WorldScale.units(WorldScale.TRASH_U, h),
            "scale: composed px at scene height keep the ladder's " +
                "order — house > tree > car > adult > kid > trash")
    }

    // ---------- 3: adults at adult scale ----------
    run {
        val h = 2400f
        val pairs = listOf(
            "Stan" to "Garrison", "Kyle" to "Randy",
            "Cartman" to "Chef", "Butters" to "Mackey",
            "Wendy" to "Victoria", "Kenny" to "Stuart",
            "Craig" to "Mr. Tucker", "Tweek" to "Lu Kim")
        for ((kid, adult) in pairs) {
            val r = WorldScale.figurePx(h, KidArt.heightFor(adult)) /
                WorldScale.figurePx(h, KidArt.heightFor(kid))
            // the floor is set by the measured extremes — the
            // shortest adult against the biggest kid — and still
            // clears "kid-sized" (≈1.0) by a wide margin
            check(r in 1.24f..1.65f,
                "scale pairs: $adult composes at ${r}× $kid — " +
                    "an adult next to a kid reads as an adult")
        }
        for (name in CharacterSystem.CAST.keys) {
            val rel = KidArt.heightFor(name)
            when (CharacterSystem.bandOf(name)) {
                AgeBand.ADULT -> check(rel >= 1.28f,
                    "scale census: cast adult $name composes at " +
                        "adult scale (heightRel $rel ≥ 1.28)")
                AgeBand.KID -> check(rel <= 1.15f,
                    "scale census: cast kid $name composes at " +
                        "kid scale (heightRel $rel ≤ 1.15)")
                else -> check(rel in 1.05f..1.32f,
                    "scale census: cast teen $name composes " +
                        "between (heightRel $rel)")
            }
        }
        check(CharacterSystem.heightScale(AgeBand.ADULT) >= 1.35f,
            "scale: generated adults ride the band ladder at " +
                "adult scale too — no kid-sized grown-ups anywhere")
        check(!gv.contains("backTop < h * 0.44f"),
            "scale: the crowd head-clearance clamp that shrank " +
                "adults toward kid height is removed, not bypassed")
    }

    // ---------- 4: the walkable ground band ----------
    run {
        val h = 2400f
        check(WalkBand.TOP_OUT > FacadeGeom.GROUND_LINE,
            "band: outdoors the band's top line sits in FRONT " +
                "of the building line — feet can never render " +
                "on a facade")
        check(WalkBand.BOTTOM_OUT < Depth.FG_TOP_OUT,
            "band: outdoors the band's bottom edge stops at " +
                "the sidewalk, short of the street")
        check(WalkBand.TOP_IN > 0.64f && WalkBand.BOTTOM_IN <= 0.905f,
            "band: indoors the band is the floor, below the " +
                "wall/floor seam")
        for (inside in listOf(false, true)) {
            for (b in listOf(0f, 0.25f, 0.5f, 0.75f, 1f)) {
                val fy = WalkBand.feetY(b, h, inside)
                check(fy >= WalkBand.top(inside) * h - 0.01f &&
                    fy <= WalkBand.bottom(inside) * h + 0.01f,
                    "band: feetY($b, inside=$inside) stays in the band")
                check(abs(WalkBand.bandForY(fy, h, inside) - b) < 0.001f,
                    "band: bandForY inverts feetY (inside=$inside, $b)")
            }
        }
        // prop footprints block: center taps slide out,
        // clear taps are untouched
        val prints = listOf(WalkBand.Footprint(0.5f, 0.5f, 0.03f, 0.13f))
        val (ax, ab) = WalkBand.avoid(0.5f, 0.5f, prints)
        check(!(ax == 0.5f && ab == 0.5f),
            "band: a tap dead-center on a prop footprint is " +
                "pushed out of it")
        val (ux, ub) = WalkBand.avoid(0.10f, 0.10f, prints)
        check(ux == 0.10f && ub == 0.10f,
            "band: a clear tap is left exactly where it landed")
        for (loc in LOCATIONS.values) {
            for (fp in PaperDressing.footprintsFor(loc)) {
                check(fp.x in 0f..1f && fp.band in 0f..1f &&
                    fp.rx > 0f && fp.rBand > 0f,
                    "band: ${loc.id}'s footprint is a real ellipse " +
                        "in the ground plane")
                val (px, pb) = WalkBand.avoid(fp.x, fp.band, listOf(fp))
                val dn = (px - fp.x) / fp.rx
                val db = (pb - fp.band) / fp.rBand
                check(dn * dn + db * db >= 0.99f,
                    "band: ${loc.id}'s footprint center is never " +
                        "a resting place")
            }
        }
        check(gv.contains("WalkBand.feetY(pwalk.band, h, inside)") &&
            gv.contains("WalkBand.bandForY(") &&
            gv.contains("WalkBand.avoid("),
            "band wiring: the view maps the player's feet, the " +
                "tap bands and the target clamp through WalkBand")
        check(!gv.contains("0.205f * 1.62f"),
            "band: the old band span math (feet up on the " +
                "buildings) is removed from the view")
    }

    // ---------- 5: doors on facades; vehicles are vehicles ----------
    run {
        val w = 1836f
        val h = 2400f
        for (loc in LOCATIONS.values) {
            if (loc.kind in CharacterSystem.BUILDING_KINDS) {
                val d = FacadeGeom.doorRect(loc.kind, w, h)
                val f = FacadeGeom.facadeRect(loc.kind, w, h)
                check(abs(d.bottom - FacadeGeom.GROUND_LINE * h) < 0.5f,
                    "doors: ${loc.id}'s door base sits ON the " +
                        "ground line")
                check(abs(d.cx - f.cx) < 0.5f && d.left >= f.left &&
                    d.right <= f.right,
                    "doors: ${loc.id}'s door is ON its facade")
                val ratio = d.height /
                    WorldScale.figurePx(h, WorldScale.ADULT_RATIO)
                check(ratio in 1.13f..1.32f,
                    "doors: ${loc.id}'s door is $ratio× an adult " +
                        "(1.15–1.30 by the ladder)")
            } else {
                val st = TownBaseline.of(loc.id)?.structure ?: "hut"
                val d = FacadeGeom.structureDoorRect(st, w, h)
                val s = FacadeGeom.structureRect(st, w, h)
                check(abs(d.bottom - FacadeGeom.GROUND_LINE * h) < 0.5f &&
                    d.left >= s.left && d.right <= s.right,
                    "doors: ${loc.id}'s entry is its structure's " +
                        "door ($st), anchored on the ground line")
            }
        }
        check(!gv.contains("standalone door prop"),
            "doors: the free-standing door slab is REMOVED " +
                "from the view, not left dormant")
        check(sceneSrc.contains("drawStructure(") &&
            gv.contains("FacadeGeom.doorRect(") &&
            gv.contains("FacadeGeom.structureDoorRect("),
            "doors wiring: SceneArt paints structures + " +
                "facade doors from FacadeGeom; the view " +
                "outlines + hit-tests the same rects")
        check(gv.contains("WorldScale.units(WorldScale.BUS_LEN_U, h)") &&
            gv.contains("WorldScale.units(WorldScale.CAR_LEN_U, h)"),
            "vehicles: the buses and cars size off the ladder")
        check(sceneSrc.contains("the side door: a panel with a window"),
            "vehicles: the bus wears a vehicle's side door — " +
                "body, window band, wheels, door — never a slab")
    }

    // ---------- 6: the bus takes you there, end to end ----------
    run {
        val e = Engine(150016)
        val s = e.newState()
        e.createPlayer(s, "Rider", DEFAULT_APPEARANCE)
        var day = 0
        while (!School.isSchoolDay(day)) day++
        s.absDay = day
        s.busPass = false
        e.player(s).location = "BusStop"
        s.timeMin = 7 * 60 + 30
        val out = SchoolBus.ride(s, advance = true)
        check(out.ok && e.player(s).location == "Elementary" &&
            s.timeMin > 7 * 60 + 30,
            "bus end-to-end: the morning school run LANDS at " +
                "the Elementary (player location after the " +
                "ride == the destination scene)")
        s.timeMin = 15 * 60 + 30
        val back = SchoolBus.ride(s, advance = true)
        check(back.ok && e.player(s).location == "BusStop",
            "bus end-to-end: the afternoon run returns the " +
                "player to the Bus Stop")
        // the tap itself: the bus is on the traffic plane,
        // in front of the crowd — a kid standing at the
        // curb no longer eats the tap
        val items = listOf(
            PaperTap.Item("kid", "Stan", 950f, 2280f, 300f, 480f, 2350f),
            PaperTap.Item("exit", "MainStreet", 950f, 2150f, 200f, 150f, 2230f),
            PaperTap.Item("schoolbus", "BusStop", 950f, 2250f, 1500f, 360f, 2390f))
        check(PaperTap.resolve(items, 950f, 2280f)?.kind == "schoolbus",
            "bus boarding: a tap on the bus resolves to the " +
                "BUS — not the kid in front of it, not the " +
                "signpost behind it")
        check(PaperTap.resolve(items.filter { it.kind != "schoolbus" },
            950f, 2280f)?.kind == "kid",
            "bus boarding: figures still win their own taps " +
                "when no vehicle is under the finger")
        // every public-bus station pair, on Walk.ride —
        // the very verb GameActivity's station flow calls
        s.busPass = true
        for (a in BusNetwork.STATIONS) for (b in BusNetwork.STATIONS) {
            if (a == b) continue
            e.player(s).location = a
            val r = Walk.ride(s, b, advance = false)
            check(r.ok && e.player(s).location == b,
                "bus end-to-end: the public bus lands $a → $b " +
                    "at $b")
        }
        s.busPass = false
        e.player(s).location = "BusStop"
        check(!Walk.ride(s, "Mall", advance = false).ok &&
            e.player(s).location == "BusStop",
            "bus end-to-end: no pass, no ride — and no " +
                "phantom trip either")
        check(gaContainsSchoolBusWiring(root),
            "bus wiring: GameActivity still routes the " +
                "schoolbus beat to SchoolBus.ride")
    }

    // ---------- 7: the bus interior ----------
    run {
        val kinds = BusInteriorSpec.PIECES.map { it.kind }.toSet()
        check(kinds == setOf(BusInteriorSpec.CEILING,
            BusInteriorSpec.WINDOW_BAND, BusInteriorSpec.ROUTE_BOARD,
            BusInteriorSpec.DRIVER, BusInteriorSpec.SEAT_BACKS,
            BusInteriorSpec.AISLE, BusInteriorSpec.SEAT_FRONTS,
            BusInteriorSpec.REAR_DOOR),
            "bus interior: the spec composes ceiling, window " +
                "band, route board, driver, seat backs, aisle, " +
                "seat fronts, rear door — no void, no floaters")
        fun planeOf(kind: String) =
            BusInteriorSpec.PIECES.first { it.kind == kind }.plane
        check(planeOf(BusInteriorSpec.WINDOW_BAND) == PaperRoomPlane.WALL &&
            planeOf(BusInteriorSpec.SEAT_BACKS) ==
                PaperRoomPlane.FURNITURE_BACK &&
            planeOf(BusInteriorSpec.AISLE) == PaperRoomPlane.FLOOR &&
            planeOf(BusInteriorSpec.SEAT_FRONTS) ==
                PaperRoomPlane.FURNITURE_FRONT &&
            planeOf(BusInteriorSpec.DRIVER) ==
                PaperRoomPlane.FURNITURE_BACK,
            "bus interior: the pieces ride the interior " +
                "planes in stack order — wall, back furniture, " +
                "floor, front furniture")
        check(BusInteriorSpec.SEAT_ROWS >= 3,
            "bus interior: real seat rows (${BusInteriorSpec.SEAT_ROWS})")
        check(INTERIORS["BusStop"]?.theme == "bus" &&
            INTERIORS["BusStop"]?.name == "Inside the School Bus",
            "bus interior: the Bus Stop's interior IS the " +
                "school bus")
        check(iaSrc.contains("drawBusRoom(") &&
            iaSrc.contains("BusInteriorSpec") &&
            iaSrc.contains("rooftops rolling past"),
            "bus interior wiring: InteriorArt paints the " +
                "spec's room — the window band shows the " +
                "street outside, not a yellow void")
    }

    // ---------- 8: ground dressing; the specks are gone ----------
    run {
        check(sceneSrc.contains("the sidewalk: pale slabs") &&
            sceneSrc.contains("snow as COVER") &&
            sceneSrc.contains("the packed path"),
            "ground: the ground plane is built from pieces — " +
                "yard, a packed path from the door, sidewalk " +
                "slabs, snow laid as cover with drift edges")
        check(!sceneSrc.contains("blue shadow dabs") &&
            !sceneSrc.contains("val dab = Paper.fillPaint"),
            "ground: the speck scatter is REMOVED from the " +
                "painter, not turned down")
        check(gv.contains("drawStandingProps(") &&
            gv.contains("PaperDressing.propSpots("),
            "ground: the dressing table's standing props are " +
                "painted at world scale on their own spots")
        check(!sceneSrc.contains("46f * s"),
            "ground: the 46px shrub pines are removed — " +
                "pines compose off the ladder now")
    }

    // ---------- 9: the merged-map baseline town ----------
    run {
        val ids = TownBaseline.BUILDINGS.map { it.locId }
            .filter { it.isNotEmpty() }
        check(ids.size == LOCATIONS.size &&
            ids.toSet() == LOCATIONS.keys,
            "baseline: every building on either map appears " +
                "ONCE — all 27 locations, no duplicates")
        check(TownBaseline.streetLine(TownBaseline.BOYS)
            .map { it.locId } == listOf("KennysHouse",
                "ButtersHouse", "CartmanHouse", "BusStop",
                "StanHouse", "KyleHouse", "YourHouse"),
            "baseline: the boys' houses and the bus stop " +
                "line their street in map order")
        check(TownBaseline.streetLine(TownBaseline.MAIN)
            .map { it.locId } == listOf("SkeetersBar",
                "FreemansTacos", "TweekBros", "TomsRhino",
                "PostOffice", "MainStreet", "Bank",
                "JimbosGuns", "CityWok", "Raisins", "Bijou",
                "Mall"),
            "baseline: Main Street's businesses stand in " +
                "their merged-map order, west to east")
        check(TownBaseline.neighborsOf("CartmanHouse")
            .map { it.locId } == listOf("ButtersHouse", "BusStop"),
            "baseline: Cartman's actual neighbors are " +
                "Butters' house and the bus stop")
        check(TownBaseline.neighborsOf("StanHouse")
            .map { it.locId } == listOf("BusStop", "KyleHouse"),
            "baseline: Stan's actual neighbors are the bus " +
                "stop and Kyle's house")
        check(TownBaseline.neighborsOf("TweekBros")
            .map { it.locId } == listOf("FreemansTacos", "TomsRhino"),
            "baseline: Tweek Bros. stands between Freeman's " +
                "Tacos and Tom's Rhinoplasty")
        for (loc in LOCATIONS.values) {
            val nbrs = TownBaseline.neighborsOf(loc.id)
            val seq = TownBaseline.rowSequence(loc.id, 4)
            if (nbrs.isNotEmpty())
                check(seq[0] == nbrs[0],
                    "baseline: ${loc.id}'s row opens with its " +
                        "real west/east neighbor")
            if (nbrs.size > 1)
                check(seq[1] == nbrs[1],
                    "baseline: ${loc.id}'s row continues with " +
                        "its other real neighbor")
        }
        for (street in TownBaseline.STREET_NAMES.keys) {
            val bodies = TownBaseline.streetLine(street)
                .map { it.bodyHex }
            check(bodies.distinct().size == bodies.size,
                "baseline: no two buildings on $street share " +
                    "a body color — each reads as itself")
        }
        check(TownBaseline.BUILDINGS.all { b ->
            listOf(b.bodyHex, b.roofHex, b.accentHex).all {
                it.matches(Regex("^#[0-9a-fA-F]{6}$")) } },
            "baseline: every look is a real color trio")
        check(TownBaseline.of("CartmanHouse")?.bodyHex == "#4f7d4a",
            "baseline look: Cartman's house is the green " +
                "one, from the reference")
        check(TownBaseline.streetSignOf("MainStreet") == "MAIN STREET" &&
            sceneSrc.contains("TownBaseline.streetSignOf(") &&
            sceneSrc.contains("TownBaseline.rowSequence("),
            "baseline wiring: corner street signs name the " +
                "street; neighbor rows read the baseline")
    }

    // ---------- 10: old assets don't stick ----------
    run {
        check(!gv.contains("min(h * 0.205f, slotW * 0.34f)"),
            "removed: the old figure base formula is gone " +
                "from the view (WorldScale.kidPx is the base)")
        // v0.15.0g re-pin: the one scale now lives in
        // FigureCompose (the pure composition module the
        // view calls) — the literal moved with the work;
        // the rule it pins (WorldScale.kidPx is THE base)
        // is unchanged
        val fcSrc = File(root,
            "src/com/hunt3r/southparktown/FigureCompose.kt")
            .readText()
        check(gv.contains("FigureCompose.compose(") &&
            fcSrc.contains("WorldScale.kidPx(h)"),
            "removed: ...and the one scale is in its place")
        check(paperSrc.contains("VEHICLES first"),
            "removed: the tap rule that let a figure eat a " +
                "bus tap is rewritten — vehicles resolve first")
        check(readme.contains("Removed in v0.15.0d"),
            "removed: the README lists what this build " +
                "took out")
        // the scale work never touched the sheets' stacks:
        // every face still clears its hair and hat
        for ((name, spec) in KidArt.SHEETS) {
            check(FigurePieces.faceClear(spec),
                "correction: $name's face stays clear — hair " +
                    "and hat frame it, never cover it")
        }
    }
}

private fun gaContainsSchoolBusWiring(root: String): Boolean {
    val ga = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    return ga.contains("SchoolBus.ride(state") &&
        ga.contains("gameView.onSchoolBus = ")
}

// ================= v0.15.0e =================
private fun sectionV0150e(root: String) {
    println("== v0.15.0e: the logo build — the approved sign, on the launcher and the title ==")
    val readme = File(root, "docs/CHANGELOG.md").readText()
    val manifestSrc = File(root, "AndroidManifest.xml").readText()

    fun sha256Of(f: File): String {
        val md = java.security.MessageDigest.getInstance("SHA-256")
        return md.digest(f.readBytes())
            .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
    }
    fun pngSizeOf(f: File): Pair<Int, Int> {
        val b = f.readBytes()
        fun be32(o: Int): Int = ((b[o].toInt() and 0xFF) shl 24) or
            ((b[o + 1].toInt() and 0xFF) shl 16) or
            ((b[o + 2].toInt() and 0xFF) shl 8) or
            (b[o + 3].toInt() and 0xFF)
        return be32(16) to be32(20)
    }

    // The approved artwork, hashed off the exact files Lucky
    // approved (Oct 17): the icon render, 512x512, and the
    // wide title render, 1200x760.
    val iconHash = "b9b9191a076e55f8f76d1faa1c716c066981c39db406090238a4497745fce0ab"
    val logoHash = "64be1865d0010f8e2bb0ee66c0f03f23bbff89ddbed473cb2c42b99e2ef6405e"
    val oldIconHash = "7ab73078e1262bbe5648202b60e868736b9e1e8b195be996a1b710568670cac3"

    check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
        manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
        "logo: the manifest carries this build (113 / 0.15.0e)")
    check(readme.contains("### v0.15.0e") &&
        readme.contains("## Status — v0.15.0e"),
        "logo: the README carries this build's status and changelog")
    check(manifestSrc.contains("android:icon=\"@drawable/ic_launcher\""),
        "logo: the manifest's launcher icon reference is the launcher drawable")

    // ---------- the launcher icon ----------
    run {
        val icon = File(root, "res/drawable/ic_launcher.png")
        check(sha256Of(icon) == iconHash,
            "logo: the launcher drawable IS the approved icon, byte for byte")
        check(sha256Of(icon) != oldIconHash,
            "logo: the old code-drawn icon's bytes are gone from the tree")
        check(pngSizeOf(icon) == (512 to 512),
            "logo: the launcher drawable is the full 512x512 artwork, " +
                "rounded corners baked in, no second mask")
        val master = File(root, "tools/logo/south-park-town-icon.png")
        check(master.exists() && sha256Of(master) == iconHash,
            "logo: the in-repo master the build installs is the same approved bytes")
    }

    // ---------- the retired generator ----------
    run {
        val gen = File(root, "tools/gen_icon.py").readText()
        check(gen.contains("south-park-town-icon.png") &&
            gen.contains("shutil.copyfile"),
            "logo: the build's icon step installs the approved master verbatim")
        check(!gen.contains("ImageDraw") && !gen.contains("DejaVuSans") &&
            !gen.contains("def draw_icon"),
            "logo: the old icon generator's drawing code is removed — " +
                "nothing in the build redraws the icon")
    }

    // ---------- the title art ----------
    run {
        val logo = File(root, "assets/title_logo.png")
        check(logo.exists() && sha256Of(logo) == logoHash,
            "logo: the bundled title art IS the approved wide logo, byte for byte")
        check(pngSizeOf(logo) == (1200 to 760),
            "logo: the title art is the full 1200x760 artwork")
        val assetNames = File(root, "assets").listFiles()!!
            .map { it.name }.sorted()
        check(assetNames == listOf("lorebook.json", "title_logo.png"),
            "logo: assets carry the lorebook and the title art — nothing else")
        val mainSrc = File(root,
            "src/com/hunt3r/southparktown/MainActivity.kt").readText()
        check(mainSrc.contains("assets.open(\"title_logo.png\")") &&
            mainSrc.contains("BitmapFactory.decodeStream"),
            "logo: the splash decodes the title art from the bundled asset")
        check(!mainSrc.contains("\"LIVING TOWN\"") && !mainSrc.contains("🌨"),
            "logo: the old lettered title (text + emoji) is removed from the splash")
        check(mainSrc.contains("postDelayed") &&
            mainSrc.contains("GameActivity::class.java") &&
            mainSrc.contains("CreatorActivity::class.java"),
            "logo: the splash routing is untouched — saved kid to the " +
                "game, new kid to the creator")
    }
}

// ================= v0.15.0f =================

private fun sectionV0150f(root: String) {
println("== v0.15.0f: the gallery show — Queue #15 item 4 ==")
val engF = Engine()
fun gState(): GameState {
    val s = engF.newState()
    engF.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
    return s
}
val readme = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readme.contains("### v0.15.0f"),
    "v0.15.0f: the README carries this build's changelog entry")
check(readme.contains("## Status — v0.15.0f"),
    "v0.15.0f: the README carries this build's status section")
check(tuning.contains("The gallery show (v0.15.0f"),
    "v0.15.0f: the tuning ledger carries the show's entry")
val manifestSrc = File(root, "AndroidManifest.xml").readText()
check(manifestSrc.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrc.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 114 / 0.15.0f")
val ktCount = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCount == 137,
    "v0.15.0f: the source tree holds 119 Kotlin files " +
        "(Gallery.kt joined) (counted $ktCount)")
val galSrc = File(root,
    "src/com/hunt3r/southparktown/Gallery.kt").readText()
check(galSrc.contains("object GalleryCalendar") &&
    galSrc.contains("object Gallery") &&
    galSrc.contains("data class GalleryShow") &&
    galSrc.contains("data class GalleryEntry"),
    "gallery: the module stands whole — calendar, records, " +
        "entries, jury, surfaces")
check(galSrc.contains("val DENYLIST"),
    "gallery: the module carries its own denylist")

// ---------- staging helpers ----------
fun galPhoto(id: String, dayKey: String, loc: String = "Mall",
             inside: Boolean = false, weather: String = "sunny",
             timeMin: Int = 720, followers: Int = 0,
             asker: String = "", starred: Boolean = false,
             group: Boolean = false,
             figs: List<Pair<String, String>> = emptyList()) =
    PhotoRecord(
        id = id, dayKey = dayKey, dateLabel = "?",
        timeMin = timeMin, locId = loc, inside = inside,
        weatherId = weather, appearance = DEFAULT_APPEARANCE,
        figures = figs.map { (n, r) ->
            PhotoFigure(n, "cast", "happy", reaction = r) },
        seed = 3L, absDay = 0, followersGained = followers,
        commissionAsker = asker, starred = starred,
        composition = if (group) "squad" else "")
fun keyIn(cal: GalleryCal, plus: Int = 5): String =
    keyFromOrdinal(cal.seasonStartOrd + plus)
val fallCal = GalleryCalendar.cal(2026, Season.FALL)
val fallKey = keyIn(fallCal)

// ---------- the calendar ----------
run {
    var ok = true
    for (y in 2026..2030) for (s in Season.values()) {
        val c = GalleryCalendar.cal(y, s)
        if (!(c.announceDay < c.hangDay &&
                c.hangDay < c.closeDay &&
                c.closeDay < c.wrapDay)) ok = false
        if (c.closeDay - c.hangDay != Gallery.RUN_DAYS) ok = false
        if (c.wrapDay != c.closeDay + 1) ok = false
        val hangOrd = FairCalendar.ordinalOfAbsDay(c.hangDay)
        if (FairCalendar.dowOfOrdinal(hangOrd) != 5) ok = false
        // the second Friday: seven days earlier is the
        // first Friday of the same month
        if (FairCalendar.dowOfOrdinal(hangOrd - 7) != 5) ok = false
        if (keyFromOrdinal(hangOrd).substring(4, 6) !=
            keyFromOrdinal(hangOrd - 7).substring(4, 6))
            ok = false
        if (keyFromOrdinal(hangOrd - 14).substring(4, 6) ==
            keyFromOrdinal(hangOrd).substring(4, 6))
            ok = false
        val (ss, sy) = GalleryCalendar
            .seasonOfKey(keyFromOrdinal(c.seasonStartOrd))
            ?: (Season.WINTER to -1)
        if (ss != s || sy != y) ok = false
        val (es, ey) = GalleryCalendar
            .seasonOfKey(keyFromOrdinal(c.seasonEndOrd))
            ?: (Season.WINTER to -1)
        if (es != s || ey != y) ok = false
    }
    check(ok, "gallery calendar: every season 2026–2030 " +
        "announces before it hangs on the SECOND Friday of " +
        "its middle month, hangs seven days, wraps the " +
        "morning after, and its span round-trips through " +
        "seasonOfKey (winter straddling the year turn)")
    val cyc = GalleryCalendar.cycleAt(fallCal.hangDay)
    check(!cyc.next && cyc.cal.id == fallCal.id,
        "gallery calendar: the cycle at hanging day IS " +
            "this season's show")
    val after = GalleryCalendar.cycleAt(fallCal.wrapDay + 3)
    check(after.next && after.cal.season == Season.WINTER,
        "gallery calendar: after the wrap the cycle points " +
            "at the next season's show, flagged next")
}

// ---------- the themes ----------
run {
    check(Gallery.THEMES.size == 12 &&
        Season.values().all { s ->
            Gallery.THEMES.count { it.season == s } == 3 },
        "gallery themes: twelve on the table, three a season")
    check(Gallery.THEMES.map { it.id }.distinct().size == 12,
        "gallery themes: every id distinct")
    check(Season.values().all { s ->
        Gallery.themeFor(GalleryCalendar.cal(2026, s)).id !=
            Gallery.themeFor(GalleryCalendar.cal(2027, s)).id &&
            Gallery.themeFor(GalleryCalendar.cal(2026, s))
                .season == s },
        "gallery themes: the derivation rotates within the " +
            "season's pool — never last year's theme twice")
    // every theme can be answered by a photograph the
    // town can actually take
    val probes: Map<String, PhotoRecord> = mapOf(
        "winter_snow" to galPhoto("p", "20270110",
            weather = "heavy_snow"),
        "winter_night" to galPhoto("p", "20270110",
            timeMin = 60),
        "winter_in" to galPhoto("p", "20270110",
            inside = true, loc = "TomsRhinoplasty",
            figs = listOf("Stan" to "happy", "Kyle" to "goofy")),
        "spring_thaw" to galPhoto("p", "20270410",
            loc = "StarksPond", weather = "rain"),
        "spring_light" to galPhoto("p", "20270410",
            weather = "sunny", timeMin = 720),
        "spring_faces" to galPhoto("p", "20270410",
            figs = listOf("Bebe" to "goofy")),
        "summer_gang" to galPhoto("p", "20270710", group = true,
            figs = listOf("Stan" to "happy", "Kyle" to "happy",
                "Kenny" to "happy", "Cartman" to "goofy")),
        "summer_air" to galPhoto("p", "20270710",
            timeMin = 720, weather = "sunny"),
        "summer_sky" to galPhoto("p", "20270710",
            weather = "blizzard"),
        "fall_harvest" to galPhoto("p", "20261010",
            timeMin = 18 * 60 + 30),
        "fall_in" to galPhoto("p", "20261010", inside = true,
            loc = "Bijou", timeMin = 21 * 60,
            figs = listOf("Wendy" to "happy")),
        "fall_work" to galPhoto("p", "20261010",
            asker = "Randy"))
    var fitsOk = true
    for (t in Gallery.THEMES) {
        val probe = probes[t.id]
        if (probe == null ||
            Gallery.themeFit(t, probe) <= 0) fitsOk = false
    }
    check(fitsOk, "gallery themes: every theme on the table " +
        "has a constructible photograph that fits it — no " +
        "theme demands content the album can't hold")
    check(Gallery.THEMES.none { t ->
        Gallery.DENYLIST.any { d ->
            (t.title + t.blurb).lowercase().contains(d) } },
        "gallery themes: no theme title or blurb touches " +
            "the denylist")
}

// ---------- eligibility & entry ----------
run {
    val s = gState()
    s.absDay = fallCal.announceDay + 2
    s.gameYear = 2026
    val show = Gallery.recordFor(s, fallCal)
    val inSeason = galPhoto("in1", fallKey,
        figs = listOf("Stan" to "happy"))
    val outSeason = galPhoto("out1", "20270115")
    val badKey = galPhoto("bad1", "garbage!")
    s.photos += listOf(inSeason, outSeason, badKey)
    check(Gallery.seasonEligible(fallCal, inSeason) &&
        !Gallery.seasonEligible(fallCal, outSeason) &&
        !Gallery.seasonEligible(fallCal, badKey),
        "gallery eligibility: a record competes in the " +
            "season of its own dayKey — never re-dated, and " +
            "an unreadable date competes nowhere")
    check(Gallery.eligibleAlbum(s, fallCal, show)
        .map { it.id } == listOf("in1"),
        "gallery eligibility: the album offer is exactly " +
            "the season's unentered frames")
    // prints: held and season-free; gifted is gone
    val recOld = galPhoto("old1", "20260303")
    val heldPrint = DarkroomPrint("prT1", "old1", recOld,
        Darkroom.SIZE_ENLARGEMENT, 3, "20260303")
    val giftedPrint = DarkroomPrint("prT2", "old1", recOld,
        Darkroom.SIZE_ENLARGEMENT, 3, "20260303",
        owner = "Wendy")
    s.prints += listOf(heldPrint, giftedPrint)
    check(Gallery.eligiblePrints(s, fallCal, show)
        .map { it.id } == listOf("prT1"),
        "gallery eligibility: a HELD darkroom print is " +
            "eligible in any season (the darkroom's second " +
            "life); a gifted print lives with its holder")
    check(Gallery.enterAlbum(s, "in1"),
        "gallery entry: an album frame enters")
    check(!Gallery.enterAlbum(s, "in1"),
        "gallery entry: the same photograph can't hang twice")
    // the print of the SAME photograph can't also hang
    val recIn2 = galPhoto("in2", fallKey)
    s.photos += recIn2
    val printOfIn1 = DarkroomPrint("prT3", "in1", inSeason,
        Darkroom.SIZE_PRINT, 3, fallKey)
    s.prints += printOfIn1
    check(!Gallery.enterPrint(s, "prT3"),
        "gallery entry: a print OF an entered photograph " +
            "is the same frame — it can't hang beside itself")
    check(Gallery.enterPrint(s, "prT1"),
        "gallery entry: a print lends (its season is free)")
    check(Gallery.playerEntriesOf(show).size == 2 &&
        !Gallery.enterAlbum(s, "in2"),
        "gallery entry: two frames of yours is the wall's " +
            "limit for one show")
    check(Gallery.withdraw(s, "in1") &&
        Gallery.enterAlbum(s, "in2"),
        "gallery entry: a withdrawal before the hanging " +
            "frees the slot")
    // the frozen copy: fade the album original and the
    // entry still renders its own facts
    val frozenFollowers = Gallery.playerEntriesOf(show)
        .first { it.photoId == "in2" }.record.followersGained
    s.photos.removeAll { it.id == "in2" }
    val kept = Gallery.playerEntriesOf(show)
        .firstOrNull { it.photoId == "in2" }
    check(kept != null &&
        kept.record.followersGained == frozenFollowers &&
        Photos.captionFor(kept.record).isNotEmpty(),
        "gallery entry: entries are stored as copies — " +
            "the wall survives the album's own fading")
    // submissions close at the hanging
    val s2 = gState(); s2.gameYear = 2026
    s2.absDay = fallCal.hangDay; s2.timeMin = Gallery.HANG_FROM
    val show2 = Gallery.recordFor(s2, fallCal)
    s2.photos += galPhoto("late1", fallKey)
    check(!Gallery.enterAlbum(s2, "late1"),
        "gallery entry: when the hanging starts, " +
            "submissions are closed")
}

// ---------- cast entries: derived, never fabricated ----------
run {
    val s = gState(); s.gameYear = 2026
    s.absDay = fallCal.announceDay + 3
    val jury = Gallery.juryFor(fallCal).map { it.name }
    val chair = jury[0]
    // the chair has the season's most-followed frame —
    // and sits the show out as an entrant anyway
    s.photos += galPhoto("jurors", fallKey, followers = 99,
        asker = chair)
    // a non-juror's commissioned frame
    s.photos += galPhoto("comm1", fallKey, followers = 10,
        asker = "Randy",
        figs = listOf("Stan" to "happy"))
    // a frame somebody merely stood in
    s.photos += galPhoto("stood1", fallKey, followers = 4,
        figs = listOf("Bebe" to "happy"))
    // a photobomb is not a sitting
    s.photos += galPhoto("bomb1", fallKey, followers = 50,
        figs = listOf("Clyde" to "bomb"))
    val cast = Gallery.castEntries(s, fallCal, emptySet())
    check(cast.none { it.entrant in jury },
        "gallery cast: jurors never enter their own show")
    check(cast.any { it.entrant == "Randy" &&
        it.photoId == "comm1" },
        "gallery cast: a commissioned photograph enters " +
            "for the neighbor who asked for it")
    check(cast.any { it.entrant == "Bebe" &&
        it.photoId == "stood1" },
        "gallery cast: a frame you stood in is yours to " +
            "be entered by")
    check(cast.none { it.entrant == "Clyde" },
        "gallery cast: a photobomb is not a sitting — it " +
            "earns no entry")
    check(cast.all { e ->
        s.photos.any { it.id == e.photoId } },
        "gallery cast: every cast entry names a photograph " +
            "that EXISTS in the real album — nothing is " +
            "fabricated for anyone")
    check(cast.map { it.photoId }.distinct().size ==
        cast.size,
        "gallery cast: no photograph hangs twice on the wall")
    check(Gallery.castEntries(s, fallCal, emptySet())
        .map { it.entrant to it.photoId } ==
        cast.map { it.entrant to it.photoId },
        "gallery cast: the derivation is deterministic — " +
            "the same album hangs the same wall")
    // the cap, with a crowded album
    val s3 = gState(); s3.gameYear = 2026
    val names = listOf("Stan", "Kyle", "Kenny", "Butters",
        "Bebe", "Clyde", "Craig", "Tweek", "Token", "Jimmy",
        "Timmy", "Wendy")
    for ((i, n) in names.withIndex()) {
        s3.photos += galPhoto("crowd$i", fallKey,
            followers = i, figs = listOf(n to "happy"))
    }
    val capped = Gallery.castEntries(s3, fallCal, emptySet())
    check(capped.size <= Gallery.CAST_ENTRY_CAP,
        "gallery cast: the cast wall caps at " +
            "${Gallery.CAST_ENTRY_CAP} frames")
}

// ---------- scoring & the jury ----------
run {
    val theme = Gallery.themeById("fall_work")!!
    val show = GalleryShow("gT", 2026, "FALL", "fall_work",
        0, 0)
    // A: on-theme (commissioned), modest craft.
    // B: off-theme, every craft bell rung.
    val recA = galPhoto("scA", fallKey, followers = 0,
        asker = "Randy",
        figs = listOf("Stan" to "neutral", "Kyle" to "neutral"))
    val recB = galPhoto("scB", fallKey, followers = 40,
        starred = true, group = true,
        figs = listOf("Stan" to "neutral", "Kyle" to "neutral"))
    val eA = GalleryEntry("Randy", Gallery.KIND_CAST,
        "scA", "", recA)
    val eB = GalleryEntry("Bebe", Gallery.KIND_CAST,
        "scB", "", recB)
    val placedShow = show.copy(entries = listOf(eB, eA))
    check(Gallery.scoreOf(placedShow, eA) >
        Gallery.scoreOf(placedShow, eB),
        "gallery jury: the theme is the show's argument — " +
            "twice the fit outranks a frame with every " +
            "craft bell rung and nothing to say to the theme")
    check(Gallery.scoreOf(placedShow, eA) ==
        Gallery.scoreOf(placedShow, eA),
        "gallery jury: a score is derived, never rolled — " +
            "the same wall scores the same forever")
    check(Gallery.placements(placedShow).map { it.photoId } ==
        listOf("scA", "scB"),
        "gallery jury: placements follow the score, " +
            "whatever order the frames went up in")
    // the tie ladder bottoms out at the hanging order
    val recT1 = galPhoto("tie1", fallKey, followers = 5)
    val recT2 = galPhoto("tie2", fallKey, followers = 5)
    val tieShow = show.copy(entries = listOf(
        GalleryEntry("Stan", Gallery.KIND_CAST, "tie1", "", recT1),
        GalleryEntry("Kyle", Gallery.KIND_CAST, "tie2", "", recT2)))
    check(Gallery.scoreOf(tieShow, tieShow.entries[0]) ==
        Gallery.scoreOf(tieShow, tieShow.entries[1]) &&
        Gallery.placements(tieShow).map { it.photoId } ==
            listOf("tie1", "tie2"),
        "gallery jury: a dead tie settles by the wall's " +
            "own order — the hanging decides, no coin flip")
    // the print bonus, exactly
    val asAlbum = GalleryEntry("You", Gallery.KIND_ALBUM,
        "scA", "", recA)
    val asPrint = GalleryEntry("You", Gallery.KIND_PRINT,
        "scA", "prX", recA)
    val bonusShow = show.copy(entries = listOf(asAlbum))
    check(Gallery.scoreOf(bonusShow, asPrint) -
        Gallery.scoreOf(bonusShow, asAlbum) ==
        Gallery.PRINT_BONUS,
        "gallery jury: a hand-developed print reads " +
            "+${Gallery.PRINT_BONUS} — the darkroom's " +
            "second life, stated on the tin")
    check(Gallery.juryFor(fallCal).size == 3 &&
        Gallery.juryFor(fallCal).map { it.lean }.toSet() ==
            setOf("craft", "heart", "light") &&
        Gallery.juryFor(GalleryCalendar.cal(2027,
            Season.FALL)).map { it.name } !=
            Gallery.juryFor(fallCal).map { it.name },
        "gallery jury: three jurors, three leanings, and " +
            "the trios rotate year over year")
}

// ---------- the judges' notes: facts only ----------
run {
    var ok = true
    val allLocs = LOCATIONS.values.map { it.name }
    for (idx in listOf(0, 1)) {
        val cal = GalleryCalendar.cal(2026 + idx, Season.FALL)
        val theme = Gallery.themeFor(cal)
        val show = GalleryShow(cal.id, cal.year, "FALL",
            theme.id, cal.hangDay, cal.closeDay)
        val recs = listOf(
            galPhoto("n1$idx", fallKey, loc = "StarksPond",
                weather = "rain",
                figs = listOf("Stan" to "goofy",
                    "Kyle" to "happy")),
            galPhoto("n2$idx", fallKey, loc = "Bijou",
                inside = true,
                figs = listOf("Bebe" to "happy")),
            galPhoto("n3$idx", fallKey, loc = "Mall",
                asker = "Randy",
                figs = listOf("Randy" to "neutral")))
        val entries = recs.mapIndexed { i, r ->
            GalleryEntry(listOf("Stan", "Bebe", "Randy")[i],
                Gallery.KIND_CAST, r.id, "", r) }
        val judged = show.copy(entries = entries)
        for ((i, e) in entries.withIndex()) {
            val note = Gallery.noteFor(judged, e, i + 1)
            val allowedNames = e.record.npcs.map { it.name } +
                Gallery.juryFor(cal).map { it.name }
            for (name in CharacterSystem.CAST.keys) {
                if (name !in allowedNames &&
                    note.contains(name)) ok = false
            }
            val recLoc = LOCATIONS[e.record.locId]?.name
            for (ln in allLocs) {
                if (ln != recLoc && note.contains(ln))
                    ok = false
            }
            if (note.isBlank()) ok = false
        }
    }
    check(ok, "gallery jury notes: across both trios and " +
        "every placing, a note names nobody who isn't in " +
            "the frame or on the jury, and no place but the " +
            "record's own — the yearbook judges' discipline")
}

// ---------- the empty show says so ----------
run {
    val s = gState(); s.gameYear = 2026
    val show = Gallery.recordFor(s, fallCal)
    Gallery.lockShow(s, show, quiet = true)
    check(show.entries.isEmpty() &&
        Gallery.wallText(s, fallCal, show).contains("bare") &&
        Gallery.winnerOf(show) == null,
        "gallery empty: a season with no photographs hangs " +
            "a bare wall and the book says so — no winner " +
            "is invented")
    s.absDay = fallCal.wrapDay
    Gallery.dailyRollover(s)
    check(show.wrapped && show.winnersLine.contains("bare") &&
        Gallery.phoneBeat(s) == null,
        "gallery empty: the wrap records the bare wall " +
            "and sends NO phone text — nothing happened " +
            "to anyone")
    val line = Gallery.paperLine(s,
        Jobs.weekIndex(fallCal.closeDay))
    check(line != null && line.contains("no entries"),
        "gallery empty: the paper's closing line reports " +
            "the bare wall honestly")
}

// ---------- the claim ----------
run {
    val s = gState(); s.gameYear = 2026
    s.photos += galPhoto("claim1", fallKey, followers = 8,
        asker = "Randy", figs = listOf("Stan" to "happy"))
    val show = Gallery.recordFor(s, fallCal)
    Gallery.lockShow(s, show, quiet = false)
    s.absDay = fallCal.hangDay
    val juror = Gallery.juryFor(fallCal)[0].name
    check(Gallery.gatheringBlock(s, juror,
        Gallery.HANG_FROM + 60) != null,
        "gallery claim: on hanging night the hall holds " +
            "its jury from six to nine")
    check(Gallery.gatheringBlock(s, juror, 15 * 60) == null,
        "gallery claim: no claim stands in the afternoon " +
            "of hanging day")
    check(Gallery.gatheringBlock(s, "Randy",
        Gallery.HANG_FROM + 60) != null &&
        Gallery.gatheringBlock(s, "Stan",
            Gallery.HANG_FROM + 60) != null,
        "gallery claim: entrants — and the people standing " +
            "in the hung frames — are held too")
    check(Gallery.gatheringBlock(s, "Chef",
        Gallery.HANG_FROM + 60) == null,
        "gallery claim: the uninvolved are nobody's claim")
    s.absDay = fallCal.hangDay + 2
    check(Gallery.gatheringBlock(s, juror, 13 * 60) != null &&
        Gallery.gatheringBlock(s, juror, 9 * 60) == null,
        "gallery claim: on the show's days the claim " +
            "holds the visiting afternoon only")
    val engSrcF = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(engSrcF.indexOf(
        "Festival.gatheringBlock(state, a.name, timeMin)") <
        engSrcF.indexOf(
            "Gallery.gatheringBlock(state, a.name, timeMin)") &&
        engSrcF.indexOf(
            "Gallery.gatheringBlock(state, a.name, timeMin)") <
        engSrcF.indexOf(
            "Sleepovers.gatheringBlock(state, a.name, timeMin)"),
        "gallery claim: seated after the film festival, " +
            "before the sleepovers, in Engine's one stack — " +
            "the stack's twenty-second claim is a seat of " +
            "its own, not a rider")
    check(engSrcF.indexOf("Festival.dailyRollover(state)") <
        engSrcF.indexOf("Gallery.dailyRollover(state)") &&
        engSrcF.indexOf("Gallery.dailyRollover(state)") <
        engSrcF.indexOf("Stand.dailyRollover(state)"),
        "gallery rollover: Engine's morning runs the " +
            "show's settle after the festival's, before " +
            "the paper and the phone read its facts")
    check(galSrc.contains("Finales.windowAt(state)") &&
        galSrc.contains("Emergencies.momentOwned(state)"),
        "gallery claim: the lite deference split stands " +
            "in the module — a finale evening or a moment " +
            "the town owns stands the hall down")
}

// ---------- the hanging set piece ----------
run {
    val s = gState(); s.gameYear = 2026
    s.photos += galPhoto("hang1", fallKey, followers = 3,
        figs = listOf("Bebe" to "happy"))
    s.absDay = fallCal.hangDay
    s.timeMin = Gallery.HANG_FROM + 30
    val beat0 = Gallery.hangBeat(s)
    check(beat0 != null && beat0.contains("HANGING"),
        "gallery hanging: the set piece opens on hanging " +
            "night, in its window")
    val show = Gallery.showFor(s, fallCal)
    check(show != null && show.locked,
        "gallery hanging: opening the hanging locks the wall")
    Gallery.advanceHang(s)
    val beat1 = Gallery.hangBeat(s)
    Gallery.advanceHang(s)
    val beat2 = Gallery.hangBeat(s)
    Gallery.advanceHang(s)
    check(beat1 != null && beat2 != null &&
        show!!.attendedHanging,
        "gallery hanging: three beats — the frames, the " +
            "ladder, the lights — and keeping them marks " +
            "the record")
    check(Gallery.hangBeat(s) == null,
        "gallery hanging: a kept evening doesn't replay")
    val s2 = gState(); s2.gameYear = 2026
    s2.absDay = fallCal.hangDay; s2.timeMin = 12 * 60
    check(Gallery.hangBeat(s2) == null,
        "gallery hanging: no beats stand outside the " +
            "evening window")
}

// ---------- the wrap pays, once ----------
run {
    // cast winner, attended -> +1 exactly once
    val s = gState(); s.gameYear = 2026
    s.photos += galPhoto("win1", fallKey, followers = 30,
        asker = "Randy",
        figs = listOf("Stan" to "happy", "Kyle" to "happy"))
    var show = Gallery.recordFor(s, fallCal)
    Gallery.lockShow(s, show, quiet = false)
    show.attendedHanging = true
    val before = s.friendship["Randy"] ?: 0
    s.absDay = fallCal.wrapDay
    Gallery.dailyRollover(s)
    val after1 = s.friendship["Randy"] ?: 0
    Gallery.dailyRollover(s)
    val after2 = s.friendship["Randy"] ?: 0
    check(show.wrapped && after1 == before + 1 &&
        after2 == after1,
        "gallery wrap: a cast winner takes +1 friendship " +
            "when you kept the hanging — once, at the wrap, " +
            "never twice")
    check(Gallery.winnerOf(show)?.entrant == "Randy" &&
        show.winnersLine.contains("Randy"),
        "gallery wrap: the winner and the index line are " +
            "the judged wall's own facts")
    check(Gallery.championShow(s)?.id == show.id,
        "gallery champion: the wrapped winner holds the " +
            "hall until the next show hangs")
    // cast winner, never attended -> no pay
    val s3 = gState(); s3.gameYear = 2026
    s3.photos += galPhoto("win2", fallKey, followers = 30,
        asker = "Randy")
    show = Gallery.recordFor(s3, fallCal)
    Gallery.lockShow(s3, show, quiet = true)
    val b3 = s3.friendship["Randy"] ?: 0
    s3.absDay = fallCal.wrapDay
    Gallery.dailyRollover(s3)
    check((s3.friendship["Randy"] ?: 0) == b3,
        "gallery wrap: a winner you never came to see " +
            "takes the mark, not the friendship — the " +
            "played-through rule")
    // player winner -> coins from the arts line
    val s4 = gState(); s4.gameYear = 2026
    s4.absDay = fallCal.announceDay + 1
    s4.photos += galPhoto("mine1", fallKey, followers = 60,
        starred = true, group = true,
        figs = listOf("Stan" to "goofy", "Kyle" to "goofy",
            "Kenny" to "happy", "Cartman" to "happy"))
    show = Gallery.recordFor(s4, fallCal)
    check(Gallery.enterAlbum(s4, "mine1"),
        "gallery wrap: staging — your frame enters")
    val coinsBefore = Minigames.capsuleCoins(s4)
    s4.absDay = fallCal.wrapDay
    Gallery.dailyRollover(s4)
    check(Gallery.winnerOf(show)?.entrant == Gallery.YOU &&
        Minigames.capsuleCoins(s4) ==
            coinsBefore + Gallery.WINNER_COINS,
        "gallery wrap: when the winner is you, the arts " +
            "line pays ${Gallery.WINNER_COINS} coins — " +
            "once, at the wrap")
    Gallery.dailyRollover(s4)
    check(Minigames.capsuleCoins(s4) ==
        coinsBefore + Gallery.WINNER_COINS,
        "gallery wrap: the prize does not pay twice")
    // the phone text on the wrap morning, then never
    val beat = Gallery.phoneBeat(s4)
    check(beat != null &&
        beat.first == Gallery.chairFor(fallCal).name &&
        beat.third.contains("champion"),
        "gallery phone: your win is texted by the jury's " +
            "chair, on the wrap's own morning")
    s4.absDay = fallCal.wrapDay + 1
    check(Gallery.phoneBeat(s4) == null,
        "gallery phone: exactly one text, on exactly " +
            "one morning")
}

// ---------- the lent print is elsewhere ----------
run {
    val s = gState(); s.gameYear = 2026
    s.absDay = fallCal.announceDay + 1
    val rec = galPhoto("lent1", fallKey)
    s.photos += rec
    val p = DarkroomPrint("prLent", "lent1", rec,
        Darkroom.SIZE_ENLARGEMENT, 1, fallKey)
    s.prints += p
    check(Gallery.enterPrint(s, "prLent"),
        "gallery lent: staging — the print lends")
    val show = Gallery.showFor(s, fallCal)!!
    Gallery.lockShow(s, show, quiet = false)
    check(Gallery.isLent(s, "prLent") &&
        Darkroom.giftablePrints(s, "Wendy")
            .none { it.id == "prLent" } &&
        !Darkroom.hang(s, "prLent"),
        "gallery lent: while the show hangs, the lent " +
            "print can't be gifted or hung at home — one " +
            "print, one wall")
    s.absDay = fallCal.wrapDay
    Gallery.dailyRollover(s)
    check(Darkroom.printById(s, "prLent") != null &&
        !Gallery.isLent(s, "prLent"),
        "gallery lent: the print is never consumed — it " +
            "comes home when the show comes down")
}

// ---------- paper, phone, journal, look ----------
run {
    val announceLine = Gallery.paperLine(gState(),
        Jobs.weekIndex(fallCal.announceDay))
    check(announceLine != null &&
        announceLine.contains("Gallery Show"),
        "gallery paper: the announcement stands in its " +
            "week's TOWN NEWS")
    check(Gallery.paperLine(gState(),
        Jobs.weekIndex(fallCal.announceDay) + 3) == null,
        "gallery paper: no line outside its weeks")
    val newsSrcF = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(newsSrcF.indexOf("PlayerBirthday.paperLine") <
        newsSrcF.indexOf("Gallery.paperLine"),
        "gallery paper: the line files after your " +
            "birthday's, in TOWN NEWS — the headline " +
            "ladder stands at ten, untouched")
    check(Phone.GALLERY in Phone.TRIGGERS &&
        Phone.GALLERY == "gallery" &&
        Phone.MAX_TEXTS == 220,
        "gallery phone: GALLERY stands in the closed " +
            "trigger set, and the inbox cap does not move " +
            "(MAX_TEXTS 220 — one text a season cannot " +
            "press the worst week)")
    val phoneSrcF = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    check(phoneSrcF.contains("Gallery.phoneBeat(state)"),
        "gallery phone: the harvest delivers the show's " +
            "beat under the GALLERY trigger")
    val s = gState(); s.gameYear = 2026
    s.absDay = fallCal.announceDay + 1
    val page = Gallery.pageLines(s)
    check(page.first().contains("GALLERY SHOW") &&
        page.any { it.contains("First Faces") ||
            it.contains(Gallery.themeFor(fallCal).title) },
        "gallery journal: the page leads with the live " +
            "show and its derived theme")
    check(Gallery.lookText(s, "CityHall") != null &&
        Gallery.lookText(s, "Mall") == null,
        "gallery look: the poster's line stands at City " +
            "Hall (the Community Hall) and nowhere else")
    check(Gallery.morningNote(s) == null &&
        Gallery.morningNote(s.apply {
            absDay = fallCal.announceDay }) != null,
        "gallery mornings: the poster's line lands on " +
            "the season's first morning")
    val actSrcF = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt")
        .readText()
    val viewSrcF = File(root,
        "src/com/hunt3r/southparktown/GameView.kt").readText()
    val houseSrcF = File(root,
        "src/com/hunt3r/southparktown/House.kt").readText()
    val journalSrcF = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt")
        .readText()
    check(actSrcF.contains("\"gallerywall\" -> galleryDialog()") &&
        actSrcF.contains("Gallery.hallStatus(state)") &&
        actSrcF.contains("Gallery.lookText(state, me.location)"),
        "gallery wiring: the activity routes the wall " +
            "fixture to the show's dialog and reads its " +
            "line in the Look")
    check(viewSrcF.contains("drawGalleryWall") &&
        viewSrcF.contains("\"gallerywall\"") &&
        viewSrcF.contains("photoRenderer.drawInto(c, e.record, rect)"),
        "gallery wiring: the hall wall paints in the " +
            "City Hall interior, framed prints rendered " +
            "by PhotoView's own renderer off the entries' " +
            "frozen records")
    check(houseSrcF.contains("Gallery.morningNote(state)") &&
        journalSrcF.contains("Gallery.pageLines(state)"),
        "gallery wiring: the morning report and the " +
            "Journal page both read the module")
    val gateSrcF = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(TalkGate.Rail.values().size == 11 &&
        !gateSrcF.contains("Gallery"),
        "gallery gate: TalkGate keeps its eleven rails " +
            "and never learns the show's name — the " +
            "hanging rides the agenda and the fixture, " +
            "not a rail")
}

// ---------- the save ----------
run {
    val s = gState(); s.gameYear = 2026
    s.absDay = fallCal.announceDay + 1
    s.photos += galPhoto("sv1", fallKey, followers = 9,
        asker = "Randy", figs = listOf("Stan" to "happy"))
    val show = Gallery.recordFor(s, fallCal)
    Gallery.enterAlbum(s, "sv1")
    Gallery.lockShow(s, show, quiet = false)
    val doc = encodeGameState(s)
    check((doc["gallery"] as? List<*>)?.size == 1,
        "gallery save: the shows ride the ONE additive " +
            "key \"gallery\"")
    val back = decodeGameState(doc)
    check(back.galleryShows.size == 1 &&
        back.galleryShows[0] == show,
        "gallery save: a show round-trips whole — " +
            "entries, frozen records, flags and all")
    // a hostile doc mints nothing
    val hostile = encodeGameState(s).toMutableMap()
    hostile["gallery"] = listOf(
        mapOf("id" to "gForged", "year" to 2026,
            "season" to "FALL", "themeId" to "not_a_theme",
            "hangDay" to 0, "closeDay" to 0),
        mapOf("id" to "gForged2", "year" to 2026,
            "season" to "NOSEASON", "themeId" to "fall_work",
            "hangDay" to 0, "closeDay" to 0),
        mapOf("id" to "gForged3", "year" to 2026,
            "season" to "FALL", "themeId" to "winter_snow",
            "hangDay" to 0, "closeDay" to 0))
    val cleaned = decodeGameState(hostile)
    check(cleaned.galleryShows.isEmpty(),
        "gallery save: a forged theme, a forged season, " +
            "and a theme in the wrong season all drop " +
            "whole — a hostile doc can't mint a show")
    val noKey = encodeGameState(s).toMutableMap()
    noKey.remove("gallery")
    check(decodeGameState(noKey).galleryShows.isEmpty(),
        "gallery save: an old save without the key " +
            "decodes to no shows — additive only")
    val prefsSrcF = File(root,
        "src/com/hunt3r/southparktown/Prefs.kt").readText()
    check(prefsSrcF.contains(
        "\"gallery\" to state.galleryShows.map { it.toMap() }"),
        "gallery save: Prefs writes the key beside " +
            "\"prints\" and \"yearbooks\"")
}
}

private fun sectionV0150g(root: String) {
println("== v0.15.0g: THE SCALE & SPACE BUILD — Lucky's playtest round 2 ==")
val engG = Engine()
val readmeG = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readmeG.contains("### v0.15.0g"),
    "v0.15.0g: the README carries this build's changelog entry")
check(readmeG.contains("## Status — v0.15.0g"),
    "v0.15.0g: the README carries this build's status section")
check(tuning.contains("The scale & space build (v0.15.0g"),
    "v0.15.0g: the tuning ledger carries the build's entry")
val manifestG = File(root, "AndroidManifest.xml").readText()
check(manifestG.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestG.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 115 / 0.15.0g")
val ktCountG = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCountG == 137,
    "v0.15.0g: the source tree holds 121 Kotlin files " +
        "(CastHomes.kt + FigureCompose.kt joined) (counted $ktCountG)")
val gvG = File(root,
    "src/com/hunt3r/southparktown/GameView.kt").readText()
val sceneG = File(root,
    "src/com/hunt3r/southparktown/SceneArt.kt").readText()
val actG = File(root,
    "src/com/hunt3r/southparktown/GameActivity.kt").readText()
val engSrcG = File(root,
    "src/com/hunt3r/southparktown/Engine.kt").readText()
fun closeG(a: Float, b: Float, tol: Float = 0.002f) =
    kotlin.math.abs(a - b) <= tol

// ---------- 1. AREAS 2–3× BIGGER (SceneScale) ----------
check(SceneScale.OLD_FACTOR == 1.7f,
    "scale: the composed width survives as OLD_FACTOR 1.7 — " +
        "the unit every fraction table still speaks")
run {
    var ok = true
    var inOk = true
    for ((_, loc) in LOCATIONS) {
        val g = SceneScale.growth(loc, false)
        if (g < 2.0f || g > 3.0f) ok = false
        // v0.16.0a supersedes this pin (was exactly 2.0f):
        // item 4 of Lucky's big update — interiors grow to
        // 2.4× for their multi-room layouts
        if (SceneScale.growth(loc, true) != 2.4f) inOk = false
    }
    check(ok, "scale: EVERY location's world grows 2–3× " +
        "(Lucky's band, no scene left narrow, none blown out)")
    check(inOk, "scale: every interior grows exactly 2.4× " +
        "(v0.16.0a, superseding the 2× pin for item 4)")
}
check(closeG(SceneScale.factor(LOCATIONS.getValue("StanHouse"), false), 4.25f, 0.01f) &&
    closeG(SceneScale.factor(LOCATIONS.getValue("StarksPond"), false), 5.1f, 0.01f) &&
    closeG(SceneScale.factor(LOCATIONS.getValue("MainStreet"), false), 4.25f, 0.01f),
    "scale: streets run 2.5× (4.25 screens), open land 3× (5.1) " +
        "— within float tolerance (1.7f × 2.5f is not exact)")
run {
    // the unit width round-trips: a widened world's
    // composition width is the world the town was drawn at
    val loc = LOCATIONS.getValue("StanHouse")
    val worldW = 1080f * SceneScale.factor(loc, false)
    check(closeG(SceneScale.unitW(worldW, loc, false), 1080f * 1.7f, 0.5f),
        "scale: unitW of a widened street world is the composed width")
    // the facade keeps its COMPOSED size at the widened
    // world's heart — the world grew around the building
    val fr = FacadeGeom.facadeRect("house", worldW, 2400f,
        SceneScale.unitW(worldW, loc, false))
    check(closeG(fr.width, 1836f * FacadeGeom.bodyWFrac("house"), 1f) &&
        closeG(fr.cx, worldW / 2f, 0.5f),
        "scale: the facade composes at unit width, centered on the wide world")
    val sr = FacadeGeom.structureRect("shelter", worldW, 2400f,
        SceneScale.unitW(worldW, loc, false))
    check(closeG(sr.cx, worldW / 2f, 0.5f),
        "scale: a structure stands at the scene's heart in the wide world " +
            "(the narrow world's 0.68 offset is retired)")
}
check(gvG.contains("SceneScale.factor(loc, inside)") &&
    !gvG.contains("const val WORLD_SCALE"),
    "scale: GameView's world width IS SceneScale's factor — " +
        "the old WORLD_SCALE constant is removed, not dormant")
run {
    // dressing density stretches honestly: the standing
    // spots tile per growth segment across the whole width
    val loc = LOCATIONS.getValue("StanHouse")
    val spots = PaperDressing.propSpots(loc)
    val base = PaperDressing.standingProps(loc).size
    check(spots.size == base * 3,
        "scale: a street scene's prop spots tile ×3 segments " +
            "(${spots.size} spots for $base kinds — density per screen holds)")
    check(spots.minOf { it.second } < 0.12f &&
        spots.maxOf { it.second } > 0.88f,
        "scale: tiled spots span the widened world edge to edge")
    check(spots.all { it.third in 0.05f..0.43f },
        "scale: every tiled spot still stands in the ground band")
}

// ---------- 2. DEPTH SCALING (the one curve) ----------
check(closeG(WalkBand.depthScale(0f), 0.75f, 0.001f) &&
    closeG(WalkBand.depthScale(0.5f), 0.95f, 0.001f) &&
    closeG(WalkBand.depthScale(1f), 1.15f, 0.001f) &&
    closeG(WalkBand.depthScale(1.5f), 1.15f, 0.001f),
    "depth: the curve is 0.75× at the houses → 1.15× at the street, " +
        "holding the front value mid-crossing (the old 0.80→1.00 " +
        "breath is superseded — Lucky: smaller at the house, " +
        "bigger at the street, by enough to SEE)")
run {
    var mono = true
    var prev = 0f
    for (i in 0..20) {
        val ds = WalkBand.depthScale(i / 20f)
        if (ds < prev) mono = false
        prev = ds
    }
    check(mono, "depth: the curve rises monotonically back to front")
    // the ladder holds at EVERY depth: depth multiplies
    // everything at the same band by the same factor
    var ladder = true
    for (band in listOf(0f, 0.25f, 0.5f, 0.75f, 1f)) {
        val ds = WalkBand.depthScale(band)
        val kid = WorldScale.figurePx(2400f, 1.0f) * ds
        val adult = WorldScale.figurePx(2400f, WorldScale.ADULT_RATIO) * ds
        val tree = WorldScale.units(WorldScale.PINE_U, 2400f) * ds
        val car = WorldScale.units(WorldScale.CAR_LEN_U, 2400f) * ds
        val trash = WorldScale.units(WorldScale.TRASH_U, 2400f) * ds
        if (!(tree > car && car > adult && adult > kid && kid > trash))
            ladder = false
    }
    check(ladder, "depth: house > tree > car > adult > kid > trash " +
        "at band 0, 0.25, 0.5, 0.75 and 1 — depth never reorders the ladder")
    // the same figure, back vs front of the band
    val back = WorldScale.figurePx(2400f, 1.0f) * WalkBand.depthScale(0f)
    val front = WorldScale.figurePx(2400f, 1.0f) * WalkBand.depthScale(1f)
    check(closeG(front / back, 1.15f / 0.75f, 0.01f),
        "depth: one figure composes 1.53× taller at the street " +
            "than up by the houses")
}
check(gvG.contains("val ds = WalkBand.depthScale(band)") &&
    !gvG.contains("0.82f + 0.18f * band"),
    "depth: standing props breathe on the ONE curve — " +
        "their private 0.82+0.18 breath is removed")
check(gvG.contains("fhBase * WalkBand.depthScale(pwalk.band)"),
    "depth: the player composes off the same curve at their own band")

// ---------- 3. THE CROWD, COMPOSED (FigureCompose) ----------
val hG = 2400f
val scrG = 1080f
fun widthG(name: String): Float = when (name) {
    "Timmy" -> 1.10f; "Jimmy" -> 0.95f
    else -> FigureCompose.WIDTH_RATIO
}
run {
    // a synthetic 28-figure crowd in two layout rows:
    // within a row, fh/heightRel is CONSTANT (the depth
    // factor is shared — the ladder cannot reorder);
    // the front row composes bigger than the back row
    val names = listOf("Stan", "Kyle", "Cartman", "Kenny", "Butters",
        "Wendy", "Craig", "Clyde", "Jimmy", "Timmy", "Tolkien", "Bebe",
        "Heidi", "Nichole", "Red", "Kevin", "Francis", "DogPoo",
        "Scott", "Annie", "Bradley", "Randy", "Sharon", "Gerald",
        "Sheila", "Liane", "Stuart", "Carol")
    val spots = names.mapIndexed { i, n ->
        FigureCompose.Spot(n, 0.04f + 0.92f * (i % 14) / 13f,
            if (i < 14) 1 else 0, false)
    }
    val worldW = scrG * SceneScale.factor(
        LOCATIONS.getValue("StanHouse"), false)
    val res = FigureCompose.compose(spots, { KidArt.heightFor(it) },
        ::widthG, worldW, scrG, hG, false, 0.5f, emptyList())
    check(res.placed.size == names.size &&
        res.placed.map { it.name }.toSet() == names.toSet(),
        "crowd: compose places every figure exactly once")
    check(res.rows in 2..FigureCompose.MAX_ROWS,
        "crowd: 28 figures spread over ${res.rows} depth rows, " +
            "not one overlapping line")
    var rowConst = true
    for ((_, row) in res.placed.groupBy { it.frontness }) {
        val unit = row.map { it.fh / KidArt.heightFor(it.name) }
        if (unit.max() - unit.min() > 0.02f * unit.max()) rowConst = false
    }
    check(rowConst, "crowd: within a row, height = base × heightRel × " +
        "ONE shared depth factor (adult > kid survives at every depth)")
    val backUnit = res.placed.filter { it.frontness == res.rows - 1 }
        .map { it.fh / KidArt.heightFor(it.name) }.average().toFloat()
    val frontUnit = res.placed.filter { it.frontness == 0 }
        .map { it.fh / KidArt.heightFor(it.name) }.average().toFloat()
    check(frontUnit > backUnit * 1.10f,
        "crowd: the front row composes ≥10% larger than the back row " +
            "(measured ${(frontUnit / backUnit * 100).toInt()}%)")
    // pairwise spacing, same row: bodies may brush
    // (PITCH_SLACK) but never merge
    var minGap = Float.MAX_VALUE
    var spacingOk = true
    for ((_, row) in res.placed.groupBy { it.frontness }) {
        val s = row.sortedBy { it.cx }
        for (i in 1 until s.size) {
            val need = (s[i - 1].fh * widthG(s[i - 1].name) +
                s[i].fh * widthG(s[i].name)) / 2f *
                FigureCompose.PITCH_SLACK
            val gap = s[i].cx - s[i - 1].cx
            if (gap < minGap) minGap = gap
            if (gap < need - 2f) spacingOk = false
        }
    }
    check(spacingOk, "crowd: no two bodies in a row overlap — " +
        "minimum composed pitch ${minGap.toInt()}px at body slack")
    check(res.placed.all { it.feetY >= WalkBand.top(false) * hG - 0.5f &&
        it.feetY <= WalkBand.bottom(false) * hG + 0.5f },
        "crowd: every composed foot stands inside the walk band")
    // a single figure at the front composes at the
    // curve's front value, exactly
    val solo = FigureCompose.compose(
        listOf(FigureCompose.Spot("Stan", 0.5f, 0, false)),
        { KidArt.heightFor(it) }, ::widthG,
        worldW, scrG, hG, false, 0.5f, emptyList())
    val stanSolo = solo.placed.single()
    check(closeG(stanSolo.fh, WorldScale.kidPx(hG) *
        KidArt.heightFor("Stan") * 1.15f, WorldScale.kidPx(hG) * 0.02f),
        "crowd: a lone figure at the curb composes at base × heightRel × 1.15")
}
// ---------- the 08:00 bus-stop crowd == the scheduled riders ----------
run {
    val s = engG.newState()
    var d = 0
    while (!School.isSchoolDay(d) && d < 14) d++
    check(School.isSchoolDay(d), "bus crowd: a school day exists to stage")
    s.absDay = d
    val key = keyFromOrdinal(FairCalendar.ordinalOfAbsDay(d))
    s.todayKey = key
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
    s.timeMin = 480
    // settle the town the way the device-sync placement
    // does: everyone AT their effective 08:00 block
    for ((_, a) in s.agents) {
        if (a.isPlayer) continue
        val b = engG.effectiveAgendaBlock(s, a, 480) ?: continue
        a.location = b.location
        a.destination = b.location
    }
    val present = s.agents.values.filter {
        !it.isPlayer && it.location == "BusStop" && it.waypoints.isEmpty()
    }.map { it.name }.toSet()
    val riders = SchoolBus.ridersAt(s)
    val crowd = SchoolBus.crowdAt(s)
    check(present == crowd,
        "bus crowd: who STANDS at the stop at 08:00 == who the " +
            "schedule sends there (riders + the driver on her route) — " +
            "the whole town no longer spawns on the stop")
    check(riders.size >= 20,
        "bus crowd: the morning run is a real crowd (${riders.size} riders)")
    check("Crabtree" in crowd && "Crabtree" !in riders,
        "bus crowd: the driver is crew at her own stop, never a rider")
    // compose THAT crowd at the stop, the bus standing:
    // nobody inside the bus, nobody merged with a neighbor
    val names = present.toList()
    val lay = Crowds.layout(names, Crowds.Chem())
    val spots = if (lay != null) {
        val byName = lay.placed.associateBy { it.name }
        names.map { n ->
            val p = byName.getValue(n)
            FigureCompose.Spot(n, p.xFrac, p.frontness, p.mirror)
        }
    } else names.mapIndexed { i, n ->
        FigureCompose.Spot(n, 0.05f + 0.9f * i / names.size, 0, false)
    }
    val loc = LOCATIONS.getValue("BusStop")
    val worldW = scrG * SceneScale.factor(loc, false)
    val (busL, busR) = FigureCompose.busSpanFrac(GameView.BUS_FX, worldW, hG)
    val res = FigureCompose.compose(spots, { KidArt.heightFor(it) },
        ::widthG, worldW, scrG, hG, false,
        FigureCompose.focalFrac("BusStop"),
        listOf(busL * worldW to busR * worldW))
    var busClear = true
    for (p in res.placed) {
        val wHalf = p.fh * widthG(p.name) / 2f
        if (p.cx + wHalf > busL * worldW + 1f &&
            p.cx - wHalf < busR * worldW - 1f) busClear = false
    }
    check(busClear, "bus crowd: NO waiting body intersects the standing " +
        "bus's span — the bus can never swallow a rider again")
    var spacingOk = true
    var minGap = Float.MAX_VALUE
    for ((_, row) in res.placed.groupBy { it.frontness }) {
        val sr = row.sortedBy { it.cx }
        for (i in 1 until sr.size) {
            val need = (sr[i - 1].fh * widthG(sr[i - 1].name) +
                sr[i].fh * widthG(sr[i].name)) / 2f *
                FigureCompose.PITCH_SLACK
            val gap = sr[i].cx - sr[i - 1].cx
            if (gap < minGap) minGap = gap
            if (gap < need - 2f) spacingOk = false
        }
    }
    check(spacingOk, "bus crowd: the busiest crowd in town holds body " +
        "pitch in every row (minimum ${minGap.toInt()}px)")
    check(res.rows >= 3,
        "bus crowd: ${names.size} riders spread over ${res.rows} depth " +
            "rows across the widened street — no blob")
    check(res.placed.all { it.cx - it.fh * widthG(it.name) / 2f >= -1f &&
        it.cx + it.fh * widthG(it.name) / 2f <= worldW + 1f },
        "bus crowd: every full body is inside the world, visible whole")
}
check(gvG.contains("FigureCompose.compose(") &&
    gvG.contains("FigureCompose.busSpanFrac(BUS_FX"),
    "crowd: GameView composes its figures through FigureCompose, " +
        "bus span forbidden — the pile's slot math is replaced, not patched")

// ---------- 4. DEFAULT LOCATIONS (CastHomes) ----------
check(CastHomes.HOME.keys == AGENT_PROFILES.keys &&
    CastHomes.HOME.size == 98,
    "homes: every one of the 98 cast is mapped exactly once")
check(CastHomes.HOME.values.all { it in LOCATIONS },
    "homes: every home is a real location")
check(CastHomes.HOME.values.none { it == "BusStop" } &&
    CastHomes.HOME.values.none { it == "YourHouse" },
    "homes: NOBODY defaults to the Bus Stop (and nobody " +
        "moves into the player's house)")
run {
    // the derivation, pinned against the town's own
    // family table: residence rows ARE KID_HOUSE's
    // house rows; every other row is its occupation
    // anchor, except the hand-placed rows
    var resOk = true
    var occOk = true
    var resCount = 0
    for ((name, _) in AGENT_PROFILES) {
        val anchor = KID_HOUSE[name]
        when {
            name in CastHomes.HAND_PLACED ->
                if (CastHomes.HOME[name] !=
                    CastHomes.HAND_PLACED[name]) occOk = false
            anchor in CastHomes.HOUSE_LOCS -> {
                resCount++
                if (CastHomes.HOME[name] != anchor) resOk = false
                if (!CastHomes.isResidence(name)) resOk = false
            }
            else -> if (CastHomes.HOME[name] != anchor) occOk = false
        }
    }
    check(resOk && resCount == 22,
        "homes: the 22 residence rows are the family houses " +
            "(Marsh, Broflovski, Cartman, McCormick, Stotch, Black)")
    check(occOk, "homes: every other row is the occupation anchor " +
        "(Mackey → Elementary, the Tweeks → their counter, and so on)")
    check(CastHomes.HAND_PLACED == mapOf("Crabtree" to "Elementary") &&
        KID_HOUSE["Crabtree"] == "BusStop",
        "homes: ONE hand-placed row — the driver's anchor moves " +
            "from the stop (her route) to the Elementary (her home)")
}
run {
    // day start: the cast spawns AT HOME; the player
    // still arrives at the stop (the intro beat)
    val s = engG.newState()
    var ok = true
    var atStop = 0
    for ((name, a) in s.agents) {
        if (a.isPlayer) continue
        if (a.location != CastHomes.HOME[name] ||
            a.destination != CastHomes.HOME[name]) ok = false
        if (a.location == "BusStop") atStop++
    }
    check(ok && atStop == 0,
        "homes: a fresh town wakes up at home — zero cast at the stop")
    check(s.agents.values.first { it.isPlayer }.location == "BusStop",
        "homes: the PLAYER still rolls into town at the bus stop")
    val sampled = mapOf("Stan" to "StanHouse", "Kyle" to "KyleHouse",
        "Cartman" to "CartmanHouse", "Kenny" to "KennysHouse",
        "Butters" to "ButtersHouse", "Mackey" to "Elementary",
        "Crabtree" to "Elementary", "Towelie" to "TegridyFarms",
        "Jesus" to "Church", "Jimbo" to "JimbosGuns",
        "Skeeter" to "SkeetersBar", "Lu Kim" to "CityWok")
    check(sampled.all { (n, h) -> s.agents[n]?.location == h },
        "homes: sampled day-start placement — the boys at their " +
            "houses, the staff at their workplaces")
    // the night march lands at the same home
    val night = engG.newState()
    night.timeMin = 23 * 60
    night.agents.getValue("Stan").location = "Mall"
    night.agents.getValue("Kyle").location = "MainStreet"
    night.agents.getValue("Mackey").location = "SkeetersBar"
    engG.inGameTick(night)
    check(listOf("Stan", "Kyle", "Mackey").all { n ->
        val a = night.agents.getValue(n)
        a.asleep && a.location == CastHomes.HOME[n]
    }, "homes: the 11 PM march sends everyone to their CastHomes home")
    // homes survive a save round-trip untouched (they
    // are placement, and placement persists as always)
    val rt = decodeGameState(encodeGameState(s))
    check(rt.agents.all { (n, a) ->
        a.isPlayer || a.location == CastHomes.HOME[n]
    }, "homes: a saved fresh town decodes with everyone still home")
}
check(engSrcG.contains("CastHomes.homeOf(name)") &&
    engSrcG.contains("location = home, coords = LOCATIONS[home]!!") &&
    !engSrcG.contains("val home = KID_HOUSE[name]"),
    "homes: Engine spawns and sleeps the cast by CastHomes — " +
        "the all-at-the-stop spawn and the KID_HOUSE night " +
        "march (with its Bus Stop row) are removed")

// ---------- 5+7. THE ROAD + CROSSWALKS ----------
check(Depth.FG_TOP_OUT == WalkBand.ROAD_TOP_OUT &&
    WalkBand.BOTTOM_OUT == 0.875f &&
    Depth.FRONT_FEET_OUT == WalkBand.BOTTOM_OUT,
    "road: the road band starts at 0.885 — the sidewalk's front " +
        "row stands at its edge (0.875), the foreground strip's " +
        "top IS the road's top (the v0.15.0d FG constants are " +
        "re-based with their reason: the road needed real height)")
check(1f - Depth.FG_TOP_OUT >= 0.10f,
    "road: the road claims ${(100 * (1f - Depth.FG_TOP_OUT)).toInt()}% " +
        "of scene height — a real band, never a sliver again")
run {
    var allOk = true
    var streetScenes = 0
    for ((_, loc) in LOCATIONS) {
        val d = PaperDressing.forLocation(loc)
        val spans = PaperDressing.crosswalks(loc)
        if (!d.hasStreet) {
            if (spans.isNotEmpty()) allOk = false
            continue
        }
        streetScenes++
        if (spans.size < 3) allOk = false
        if (spans.first().first > 0.02f ||
            spans.last().second < 0.98f) allOk = false
        if (spans.none { 0.5f in it.first..it.second }) allOk = false
        for (i in 1 until spans.size)
            if (spans[i].first <= spans[i - 1].second) allOk = false
        if (spans.any { it.first < 0f || it.second > 1f }) allOk = false
    }
    check(allOk && streetScenes >= 20,
        "road: every street scene ($streetScenes) marks crossings at " +
            "both ends and at its heart; path scenes have no road to cross")
    check(PaperDressing.crosswalks(
        LOCATIONS.getValue("MainStreet")).size == 5,
        "road: downtown earns two extra mid-block crossings")
    check(PaperDressing.SIGN_FX == 0.34f &&
        PaperDressing.footprintsFor(LOCATIONS.getValue("BusStop"))
            .any { kotlin.math.abs(it.x - PaperDressing.SIGN_FX) < 0.001f },
        "road: the station sign stands at SIGN_FX, west of the bus, " +
            "and its footprint reads the same number")
}
run {
    // the movement gate, exactly as GameView applies it:
    // a road target (band > 1) survives only in a span
    val loc = LOCATIONS.getValue("StanHouse")
    val spans = PaperDressing.crosswalks(loc)
    fun gate(x: Float, band: Float): Float =
        if (WalkBand.isRoad(band) && !WalkBand.inSpan(x, spans))
            1f else band
    var ok = true
    var x = 0.02f
    while (x < 0.99f) {
        val g = gate(x, WalkBand.BAND_MAX_OUT)
        if (WalkBand.inSpan(x, spans)) {
            if (g != WalkBand.BAND_MAX_OUT) ok = false
        } else if (g != 1f) ok = false
        x += 0.01f
    }
    check(ok, "road: at every x of a street scene, a tap on the road " +
        "lands on the road ONLY inside a marked crossing — " +
        "everywhere else it clamps to the sidewalk")
    // crossings traverse end to end: feet walk the
    // whole road strip inside a span
    val midX = 0.5f
    val feetBack = WalkBand.feetY(1f, hG, false)
    val feetFar = WalkBand.feetY(WalkBand.BAND_MAX_OUT, hG, false)
    check(WalkBand.inSpan(midX, spans) &&
        closeG(feetFar, WalkBand.ROAD_FEET_BOTTOM_OUT * hG, 0.5f) &&
        feetFar > feetBack,
        "road: inside the heart crossing, feet travel from the near " +
            "curb to the far curb (${feetBack.toInt()}px → ${feetFar.toInt()}px)")
    // round-trips across the extended band
    var rt = true
    for (b in listOf(0f, 0.25f, 0.5f, 0.75f, 1f, 1.25f, 1.5f)) {
        if (!closeG(WalkBand.bandForY(
                WalkBand.feetY(b, hG, false), hG, false), b, 0.004f))
            rt = false
    }
    check(rt, "road: feetY/bandForY round-trip across sidewalk AND road")
    check(closeG(WalkBand.feetY(1.5f, hG, true),
        WalkBand.feetY(1f, hG, true), 0.5f),
        "road: interiors never leave the floor — a road band clamps to it")
}
check(sceneG.contains("PaperDressing.crosswalks(loc)") &&
    gvG.contains("PaperDressing.crosswalks(locNow0)"),
    "road: the zebra painter and the tap gate read the SAME " +
        "crosswalk table — markings and movement cannot disagree")
check(gvG.contains("board from the curb"),
    "road: boarding resolves to the curb — a thing's standing " +
        "spot is never on the road")

// ---------- 6. LESS TRAFFIC ----------
check(Traffic.PERIOD_TICKS == 1140L && Traffic.PASS_TICKS == 210L,
    "traffic: the derivation's parameters — a pass slot every " +
        "1140 ticks per lane, a crossing still takes 210 (same speed)")
run {
    val oldRate = 2f * Traffic.TICKS_PER_MINUTE / 340f
    val newRate = Traffic.passesPerMinute()
    check(newRate in 2.0f..2.2f && newRate <= oldRate / 3f,
        "traffic: expected passes per scene-minute fall from " +
            "${(oldRate * 10).toInt() / 10f} to " +
            "${(newRate * 100).toInt() / 100f} — 0.30×, under the " +
            "third the correction allowed (less, not zero)")
    var visible = 0
    var t = 0L
    while (t < Traffic.PERIOD_TICKS * 10) {
        if (Traffic.progress(t, 0) != null) visible++
        t++
    }
    val duty = visible.toFloat() / (Traffic.PERIOD_TICKS * 10)
    check(closeG(duty, Traffic.PASS_TICKS.toFloat() /
        Traffic.PERIOD_TICKS, 0.01f),
        "traffic: a lane stands empty ${(100 - duty * 100).toInt()}% " +
            "of the time — a quiet street")
    check(Traffic.progress(0L, 0) == 0f &&
        Traffic.progress(0L, 1) == null &&
        !Traffic.dirRight(0) && Traffic.dirRight(1),
        "traffic: lanes are staggered half a period apart; the " +
            "near lane runs right, the far lane left")
}
check(gvG.contains("Traffic.progress(tick, k)") &&
    !gvG.contains("val period = 340L"),
    "traffic: GameView reads the pure derivation — the old " +
        "inline 340-tick loop is removed")

// ---------- 8. BUTTON LABELS ----------
val barLabels = listOf("👀 Look", "💬 Talk", "📸 Selfie",
    "🎒 Pack", "📓 Journal", "📱 Phone", "☰ Menu")
check(barLabels.all { actG.contains("\"$it\"") } &&
    BarFit.BUTTONS == 7,
    "bar: all seven buttons keep their names — none renamed, none dropped")
check(actG.contains("setSingleLine(true)") &&
    actG.contains("setAutoSizeTextTypeUniformWithConfiguration") &&
    actG.contains("BarFit.MIN_SP, BarFit.MAX_SP"),
    "bar: every bar button is single-line with auto-size text " +
        "over BarFit's range — a label cannot wrap mid-word")
run {
    var floorOk = true
    var midOk = true
    var wideOk = true
    for (label in barLabels) {
        if (!BarFit.fitsAtFloor(label, 320f)) floorOk = false
        if (BarFit.fittedSp(label, 360f) < 9.0f) midOk = false
        if (BarFit.fittedSp(label, 411f) < 10.0f) wideOk = false
    }
    check(floorOk, "bar: even on a 320dp screen every label fits " +
        "its share at the 8sp floor — the one-line guarantee holds")
    check(midOk && wideOk, "bar: at 360dp the labels settle at " +
        "≥9sp and at 411dp at ≥10sp (JOURNAL, the widest, included)")
}
}

private fun sectionV0150h(root: String) {
// ================= v0.15.0h: apprenticeships =================
// Queue #15 item 5. Town jobs grow a second tier: work a
// job site steady — shifts completed at that one counter,
// counted off Jobs' own clock-out — and the site's named
// keeper offers a five-stage apprenticeship chain, gated
// by days so it cannot be blitzed (floor: sixteen days),
// routed across town on the Walk graph (the errand leg is
// a real walk to a real person), deepening a named skill
// the Journal shows, and ending in a completion mark the
// town remarks on: the mentor's standing line, the
// neighbors' gossip for three weeks, one TOWN NEWS line,
// and the master's rate (+1 a shift at the mastered
// site) inside Jobs' own pay line. One at a time;
// declining costs nothing and the offer returns tomorrow;
// quitting costs nothing but the chain. ONE new agenda
// claim (the mentor's hours, after Jobs — the stack
// stands at twenty-three), NO new TalkGate rail (the
// beats ride below the gate whole), NO phone trigger
// (the closed sender set stays closed).
println("== v0.15.0h: apprenticeships — Queue #15 item 5 ==")
val engH = Engine()
fun hState(): GameState {
    val s = engH.newState()
    engH.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
    return s
}
val readmeH = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readmeH.contains("### v0.15.0h"),
    "v0.15.0h: the README carries this build's changelog entry")
check(readmeH.contains("## Status — v0.15.0h"),
    "v0.15.0h: the README carries this build's status section")
check(tuning.contains("The apprenticeships (v0.15.0h"),
    "v0.15.0h: the tuning ledger carries the apprenticeships' entry")
val manifestSrcH = File(root, "AndroidManifest.xml").readText()
check(manifestSrcH.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrcH.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 116 / 0.15.0h")
val ktCountH = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCountH == 137,
    "v0.15.0h: the source tree holds 122 Kotlin files " +
        "(Apprenticeships.kt joined) (counted $ktCountH)")
val apprSrc = File(root,
    "src/com/hunt3r/southparktown/Apprenticeships.kt").readText()
check(apprSrc.contains("object Apprenticeships") &&
    apprSrc.contains("data class ApprProgram") &&
    apprSrc.contains("fun onShiftCompleted") &&
    apprSrc.contains("fun gatheringBlock") &&
    apprSrc.contains("fun paperLine"),
    "apprenticeships: the module stands whole — registry, " +
        "the Jobs seams, the claim, the paper line")

// ---------- the registry ----------
run {
    val castNames = engH.newState().agents.keys
    check(Apprenticeships.PROGRAMS.size == 5,
        "apprenticeships: five programs, one per job site " +
            "the town runs (City Hall, Tegridy, and the " +
            "shop pool's three counters)")
    check(Apprenticeships.PROGRAMS.map { it.site }.distinct().size == 5 &&
        Apprenticeships.PROGRAMS.map { it.mentor }.distinct().size == 5,
        "apprenticeships: every site and every mentor distinct")
    check(Apprenticeships.PROGRAMS.all { it.site in LOCATIONS },
        "apprenticeships: every site is a real location")
    check(Apprenticeships.PROGRAMS.all {
        it.mentor in castNames && it.recipient in castNames &&
            it.judgeResolutions.all { r ->
                r.verb != "TALK" || r.target in castNames } },
        "apprenticeships: every mentor, every errand " +
            "recipient and every judgment witness is real " +
            "cast — no invented person fronts a counter")
    check(Apprenticeships.PROGRAMS.all { p ->
        val job = Jobs.defById(p.jobId)
        job != null && (if (p.jobId == "shop")
            Jobs.SHOPS.any { it.locId == p.site && it.keeper == p.mentor }
        else job.workplace == p.site && job.boss == p.mentor) },
        "apprenticeships: each program's mentor is the " +
            "keeper Jobs' own data seats at that site — " +
            "McDaniels, Randy, and the rota's three keepers")
    check(Apprenticeships.PROGRAMS.all {
        it.stageTitles.size == Apprenticeships.STAGE_COUNT &&
            it.judgeResolutions.size == 3 &&
            it.judgeResolutions.map { r -> r.quality }
                .sorted() == listOf(0, 1, 2) },
        "apprenticeships: five stages a chain, and every " +
            "judgment offers exactly three roads — the " +
            "fact-finding, the decent, and the hasty")
    check(Apprenticeships.GAPS.size == Apprenticeships.STAGE_COUNT &&
        Apprenticeships.GAPS.sum() == Apprenticeships.MIN_SPAN &&
        Apprenticeships.MIN_SPAN >= 14,
        "apprenticeships: the day-gates sum to the chain's " +
            "floor — sixteen days, the better part of two " +
            "weeks, and no stage can be blitzed")
    // every authored string in the module passes the
    // town's denylist (the gallery's own list, shared)
    val authored = Apprenticeships.PROGRAMS.flatMap { p ->
        listOf(p.offerText, p.acceptText, p.declineText,
            p.quitText, p.s0Text, p.pickupText, p.deliverText,
            p.s2Text, p.judgePoseText, p.markText,
            p.masterLine, p.paperText) +
            p.judgeResolutions.map { it.text } }
    check(authored.none { t ->
        Gallery.DENYLIST.any { d -> t.lowercase().contains(d) } },
        "apprenticeships: all copy is the town's own — " +
            "the denylist passes over every authored string")
}

// ---------- the count: Jobs' clock-out is the record ----------
run {
    val s = hState()
    val farmDef = Jobs.defById("farm")!!
    val farmProg = Apprenticeships.programAt("TegridyFarms")!!
    // a real shift, driven through Jobs' real judges on a
    // real shift morning (day 0 is a Thursday — a farm day)
    s.absDay = 0
    s.timeMin = 8 * 60 + 30
    Jobs.judgeTalk(s, "Randy", "TegridyFarms")          // hired
    Jobs.judgeTalk(s, "Randy", "TegridyFarms")          // clock in
    for (t in Jobs.tasksFor(s, farmDef)) when (t.kind) {
        "LOOK" -> Jobs.lookText(s, t.target)
        else -> Jobs.judgeTalk(s, t.target, "TegridyFarms")
    }
    Jobs.judgeTalk(s, "Randy", "TegridyFarms")          // clock out
    check(Apprenticeships.shiftsAt(s, farmProg) == 1,
        "apprenticeships: one honestly clocked-out farm " +
            "shift counts once on the farm's apprenticeship " +
            "count — the record is Jobs' own completion verb")
    check(Apprenticeships.shiftsAt(s,
        Apprenticeships.programAt("CityHall")!!) == 0,
        "apprenticeships: a farm shift counts at the farm " +
            "only — the counters keep separate books")
    // the threshold is exact: five counted routes do not
    // open the Gazette's offer; the sixth does
    val g = hState()
    val gazProg = Apprenticeships.programAt("CityHall")!!
    val paperDef = Jobs.defById("paper")!!
    repeat(5) { Apprenticeships.onShiftCompleted(g, paperDef) }
    check(Apprenticeships.talkStepFor(g, "McDaniels",
        "CityHall") == null,
        "apprenticeships: five of six routes walked — the " +
            "mayor's offer does not stand yet")
    Apprenticeships.onShiftCompleted(g, paperDef)
    val offer = Apprenticeships.talkStepFor(g, "McDaniels",
        "CityHall")
    check(offer != null && offer.kind == "OFFER",
        "apprenticeships: the sixth clean route earns the " +
            "offer, in person, at the mentor's own counter")
    check(Apprenticeships.talkStepFor(g, "McDaniels",
        "MainStreet") == null,
        "apprenticeships: the offer is made at the site — " +
            "the mayor does not pitch it from the street")
}

// ---------- the chain: gates, one at a time, declines, quits ----------
fun driveChainH(s: GameState, prog: ApprProgram,
                quality: Int = 2): Int {
    val coins0 = Minigames.capsuleCoins(s)
    Apprenticeships.judgeTalk(s, prog.mentor, prog.site)   // accept
    Apprenticeships.judgeTalk(s, prog.mentor, prog.site)   // stage 0
    s.absDay += Apprenticeships.GAPS[1]
    Apprenticeships.judgeTalk(s, prog.mentor, prog.site)   // pickup
    Apprenticeships.judgeTalk(s, prog.recipient, "MainStreet")
    s.absDay += Apprenticeships.GAPS[2]
    Apprenticeships.lookText(s, prog.site)                 // deep work
    s.absDay += Apprenticeships.GAPS[3]
    Apprenticeships.judgeTalk(s, prog.mentor, prog.site)   // the pose
    val res = prog.judgeResolutions.first { it.quality == quality }
    if (res.verb == "LOOK") Apprenticeships.lookText(s, res.target)
    else Apprenticeships.judgeTalk(s, res.target, "MainStreet")
    s.absDay += Apprenticeships.GAPS[4]
    Apprenticeships.judgeTalk(s, prog.mentor, prog.site)   // the mark
    return Minigames.capsuleCoins(s) - coins0
}
run {
    val s = hState()
    val prog = Apprenticeships.programAt("CityHall")!!
    val paperDef = Jobs.defById("paper")!!
    repeat(prog.threshold) {
        Apprenticeships.onShiftCompleted(s, paperDef) }
    // declining costs nothing, stamps the day, and the
    // offer returns tomorrow — never the same day twice
    Apprenticeships.judgeTalk(s, "McDaniels", "CityHall",
        "DECLINE")
    check(Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall") == null &&
        Apprenticeships.activeProgram(s) == null,
        "apprenticeships: a declined offer stands down " +
            "for the day and starts nothing")
    s.absDay += 1
    check(Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall")?.kind == "OFFER",
        "apprenticeships: the offer returns the next day, " +
            "unstained — declining is free")
    // accept; stage 0 lands at once, and re-talking the
    // mentor cannot pay it twice
    val accept = Apprenticeships.judgeTalk(s, "McDaniels",
        "CityHall")
    check(accept?.kind == "ACCEPT" &&
        Apprenticeships.activeProgram(s)?.site == "CityHall",
        "apprenticeships: accepting starts the one chain")
    val landed = Apprenticeships.judgeTalk(s, "McDaniels",
        "CityHall")
    check(landed?.kind == "STAGE" &&
        Apprenticeships.stagesDone(s, prog) == 1,
        "apprenticeships: the first morning lands as stage one")
    val coinsAfterS0 = Minigames.capsuleCoins(s)
    val again = Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall")
    check(again?.kind == "STATUS" &&
        Minigames.capsuleCoins(s) == coinsAfterS0,
        "apprenticeships: a landed stage cannot be landed " +
            "twice — the mentor's standing talk is a status, " +
            "not a second stipend")
    // the day-gate is real: stage two keeps until its day
    s.absDay += Apprenticeships.GAPS[1] - 1
    check(Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall")?.kind == "STATUS" &&
        Apprenticeships.objectiveText(s, prog).contains("opens"),
        "apprenticeships: a gated stage says when it opens " +
            "and judges nothing early")
    s.absDay += 1
    check(Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall")?.kind == "STAGE",
        "apprenticeships: on its morning the gate opens")
    // one at a time: with the Gazette chain running, a
    // full count at the farm earns no offer
    val farmProg = Apprenticeships.programAt("TegridyFarms")!!
    val farmDef = Jobs.defById("farm")!!
    repeat(farmProg.threshold) {
        Apprenticeships.onShiftCompleted(s, farmDef) }
    check(Apprenticeships.talkStepFor(s, "Randy",
        "TegridyFarms") == null &&
        Apprenticeships.pageLines(s).any {
            it.contains("One at a time") },
        "apprenticeships: one chain at a time — the farm's " +
            "offer waits while the Gazette's runs, and the " +
            "Journal says why")
    // quitting costs nothing but the chain: progress
    // resets, the count that earned the offer stands
    val quit = Apprenticeships.judgeTalk(s, "McDaniels",
        "CityHall", "QUIT")
    check(quit?.kind == "QUIT" &&
        Apprenticeships.activeProgram(s) == null &&
        Apprenticeships.stagesDone(s, prog) == 0 &&
        Apprenticeships.shiftsAt(s, prog) == prog.threshold,
        "apprenticeships: ending a chain early resets its " +
            "card and keeps its count — no punishment, " +
            "stated in the fiction and pinned in the state")
    check(Apprenticeships.talkStepFor(s, "Randy",
        "TegridyFarms")?.kind == "OFFER",
        "apprenticeships: with the chain ended, the waiting " +
            "offer stands the same day")
}

// ---------- a whole chain, and the judgment's three roads ----------
run {
    val prog = Apprenticeships.programAt("CityHall")!!
    val paperDef = Jobs.defById("paper")!!
    val totals = mutableListOf<Int>()
    for (q in listOf(2, 1, 0)) {
        val s = hState()
        repeat(prog.threshold) {
            Apprenticeships.onShiftCompleted(s, paperDef) }
        val stanBefore = s.friendship["Stan"] ?: 0
        val paid = driveChainH(s, prog, q)
        totals += paid
        check(Apprenticeships.isDone(s, prog) &&
            Apprenticeships.activeProgram(s) == null &&
            Apprenticeships.skillLevel(s, prog) ==
                Apprenticeships.STAGE_COUNT,
            "apprenticeships: the Gazette chain completes " +
                "on judgment road $q — every road is honest " +
                "and the mark still signs")
        if (q == 1)
            check((s.friendship["Stan"] ?: 0) == stanBefore + 1,
                "apprenticeships: asking the house kindly is " +
                    "remembered by the house (+1, Stan)")
        if (q == 2)
            check((s.friendship["Stan"] ?: 0) == stanBefore,
                "apprenticeships: the box's own evidence " +
                    "moves no friendship — facts are free")
    }
    check(totals == listOf(17, 16, 15),
        "apprenticeships: a chain pays 15–17 🪙 by the " +
            "judgment's quality (2/3/3/2+quality/5) — " +
            "the master's read prices the stipend, never " +
            "the completion (paid $totals)")
    // a completed site never offers again, and its Look
    // reads the framed card forever
    val s = hState()
    repeat(prog.threshold) {
        Apprenticeships.onShiftCompleted(s, paperDef) }
    driveChainH(s, prog)
    check(Apprenticeships.talkStepFor(s, "McDaniels",
        "CityHall") == null &&
        Apprenticeships.lookText(s, "CityHall")
            ?.contains("framed card") == true,
        "apprenticeships: once per site — a mastered " +
            "counter offers no second chain, only its card")
}

// ---------- the economy, proven against the ledger ----------
run {
    val s = hState()
    val chainMax = Apprenticeships.STIPENDS.sum() + 2
    var honest = true
    for (prog in Apprenticeships.PROGRAMS) {
        val def = Jobs.defById(prog.jobId)!!
        val tasks = Jobs.tasksFor(s, def).size
        val ordinaryWeek = def.days.size *
            (def.basePay + def.perTask * tasks)
        // over the chain's own minimum span (two-plus
        // weeks), the site's ordinary work pays at least
        // twice the chain's whole stipend purse
        if (chainMax > 2 * ordinaryWeek) honest = false
        // and the master's rate, at its weekly worst,
        // stays under half the ordinary week's pay
        if (Apprenticeships.MASTER_BONUS * def.days.size * 2 >
            ordinaryWeek) honest = false
    }
    check(honest,
        "apprenticeships economy: no loop — a whole chain " +
            "($chainMax 🪙 at most) pays less than half of " +
            "what the same counter's ordinary work pays " +
            "over the chain's own span, and the master's " +
            "rate is a mark, not a mint")
    // the master's rate inside Jobs' own pay line: the
    // same farm shift, with and without the mark
    fun farmShiftWeekPay(marked: Boolean): Int {
        val st = hState()
        val farmDef = Jobs.defById("farm")!!
        val farmProg = Apprenticeships.programAt("TegridyFarms")!!
        repeat(farmProg.threshold) {
            Apprenticeships.onShiftCompleted(st, farmDef) }
        if (marked) driveChainH(st, farmProg)
        while (!Jobs.isShiftDay(st.absDay, farmDef)) st.absDay++
        st.timeMin = 8 * 60 + 30
        Jobs.judgeTalk(st, "Randy", "TegridyFarms")
        Jobs.judgeTalk(st, "Randy", "TegridyFarms")
        for (t in Jobs.tasksFor(st, farmDef)) when (t.kind) {
            "LOOK" -> Jobs.lookText(st, t.target)
            else -> Jobs.judgeTalk(st, t.target, "TegridyFarms")
        }
        Jobs.judgeTalk(st, "Randy", "TegridyFarms")
        return Jobs.weekPay(st)
    }
    val plain = farmShiftWeekPay(false)
    val mastered = farmShiftWeekPay(true)
    check(mastered - plain == Apprenticeships.MASTER_BONUS,
        "apprenticeships economy: a mastered site's shift " +
            "pays exactly the master's rate more (+1 🪙 in " +
            "Jobs' own tab: $plain → $mastered) — the mark " +
            "is worth something real, in the system")
}

// ---------- the claim: the mentor's hours ----------
run {
    val s = hState()
    val prog = Apprenticeships.programAt("CityHall")!!
    val paperDef = Jobs.defById("paper")!!
    repeat(prog.threshold) {
        Apprenticeships.onShiftCompleted(s, paperDef) }
    check(Apprenticeships.gatheringBlock(s, "McDaniels",
        12 * 60)?.location == "CityHall",
        "apprenticeships claim: while the offer stands, " +
            "the mayor keeps her desk through the working day")
    check(Apprenticeships.gatheringBlock(s, "McDaniels",
        Apprenticeships.CLAIM_FROM - 1) == null &&
        Apprenticeships.gatheringBlock(s, "McDaniels",
            Apprenticeships.CLAIM_TO) == null,
        "apprenticeships claim: the hours are 9-to-5 — " +
            "outside them the mentor's day is their own")
    check(Apprenticeships.gatheringBlock(s, "Stan",
        12 * 60) == null &&
        Apprenticeships.gatheringBlock(s, "Randy",
            12 * 60) == null,
        "apprenticeships claim: nobody else's hours are " +
            "kept — Randy's counter has no business standing")
    val engSrcH = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(engSrcH.indexOf("Jobs.gatheringBlock(state, a.name, timeMin)") <
        engSrcH.indexOf(
            "Apprenticeships.gatheringBlock(state, a.name, timeMin)") &&
        engSrcH.indexOf(
            "Apprenticeships.gatheringBlock(state, a.name, timeMin)") <
        engSrcH.indexOf("MovieNights.gatheringBlock(state, a.name, timeMin)"),
        "apprenticeships claim: seated after Jobs, before " +
            "the movie nights, in Engine's one stack — the " +
            "stack's twenty-third claim, work's own family, " +
            "and every set piece below it still wins the mentor")
    // a completed program keeps no hours
    driveChainH(s, prog)
    check(Apprenticeships.gatheringBlock(s, "McDaniels",
        12 * 60) == null,
        "apprenticeships claim: a signed mark ends the " +
            "hours — the mayor's day is hers again")
}

// ---------- remarks, the paper, and the closed doors ----------
run {
    val s = hState()
    val prog = Apprenticeships.programAt("CityHall")!!
    val paperDef = Jobs.defById("paper")!!
    check(Apprenticeships.remarkLines(s, "Stan").isEmpty() &&
        Apprenticeships.remarkLines(s, "McDaniels").isEmpty(),
        "apprenticeships remarks: with no mark signed, the " +
            "town has nothing to remark on")
    repeat(prog.threshold) {
        Apprenticeships.onShiftCompleted(s, paperDef) }
    val doneDay = s.absDay + Apprenticeships.MIN_SPAN
    driveChainH(s, prog)
    check(Apprenticeships.completionDay(s, prog) == doneDay,
        "apprenticeships: the chain takes its sixteen " +
            "days — the completion day is the span's floor, " +
            "not a day less")
    val stanLine = Apprenticeships.remarkLines(s, "Stan")
    check(stanLine.size == 1 &&
        stanLine[0].text.contains("McDaniels"),
        "apprenticeships remarks: the town talks about a " +
            "fresh mark — once each, in fact's own words")
    check(Apprenticeships.remarkLines(s, "Stan").isEmpty(),
        "apprenticeships remarks: a remark is spent as it " +
            "is said (the removal is the playing)")
    val mentorLine = Apprenticeships.remarkLines(s, "McDaniels")
    check(mentorLine.size == 1 &&
        mentorLine[0].text.contains("Route master") &&
        Apprenticeships.remarkLines(s, "McDaniels").size == 1,
        "apprenticeships remarks: the mentor's own line " +
            "stands — every talk after, the favor-line " +
            "discipline, never consumed")
    check(Apprenticeships.paperLine(s,
        Jobs.weekIndex(doneDay)) == prog.paperText &&
        Apprenticeships.paperLine(s,
            Jobs.weekIndex(doneDay) + 1) == null,
        "apprenticeships paper: the graduation stands in " +
            "TOWN NEWS in its own week only — section copy, " +
            "derived whole off the site's record")
    val fresh = hState()
    check(Apprenticeships.paperLine(fresh, 0) == null &&
        Apprenticeships.lookText(fresh, "Mall") == null,
        "apprenticeships: no record, no line, no trace — " +
            "an untouched town reads clean")
}

// ---------- surfaces & the closed doors ----------
run {
    val s = hState()
    val page = Apprenticeships.pageLines(s)
    check(page[0].contains("APPRENTICESHIPS") &&
        Apprenticeships.PROGRAMS.all { p ->
            page.any { it.contains(p.chainTitle) } },
        "apprenticeships journal: the page names all five " +
            "chains and their counters from day one")
    check(page.any { it.contains("0 of 6") } &&
        page.any { it.contains("0 of 4") },
        "apprenticeships journal: the counts show " +
            "themselves honestly before a single shift")
    val jourSrc = File(root,
        "src/com/hunt3r/southparktown/JournalActivity.kt").readText()
    val actSrcH = File(root,
        "src/com/hunt3r/southparktown/GameActivity.kt").readText()
    check(jourSrc.contains("Apprenticeships.pageLines(state)") &&
        actSrcH.contains("Apprenticeships.talkStepFor") &&
        actSrcH.contains("Apprenticeships.lookText") &&
        actSrcH.contains("Apprenticeships.remarkLines"),
        "apprenticeships wiring: the Journal renders the " +
            "page, and the activity speaks the beats through " +
            "the dialogue branch, the Look chain and the " +
            "memory channel")
    val gateSrcH = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    val phoneSrcH = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    val phoneActSrcH = File(root,
        "src/com/hunt3r/southparktown/PhoneActivity.kt").readText()
    val newsSrcH = File(root,
        "src/com/hunt3r/southparktown/Newspaper.kt").readText()
    check(!gateSrcH.contains("Apprenticeships") &&
        TalkGate.Rail.values().size == 11,
        "apprenticeships gate: TalkGate keeps its eleven " +
            "rails and never learns the module's name — the " +
            "beats ride below the gate whole")
    check(!phoneSrcH.contains("Apprenticeship") &&
        !phoneActSrcH.contains("Apprenticeship") &&
        newsSrcH.contains("Apprenticeships.paperLine(state, week)"),
        "apprenticeships paper/phone: NO phone trigger — " +
            "the closed sender set stays closed and " +
            "MAX_TEXTS unmoved; the paper's TOWN NEWS seam " +
            "is the one sanctioned line")
    check(apprSrc.contains("Emergencies.momentOwned(state)"),
        "apprenticeships claim: the momentOwned deference " +
            "stands in the module — a moment the town owns " +
            "stands the mentor's hours down")
}

// ---------- the save round-trip ----------
run {
    val s = hState()
    val prog = Apprenticeships.programAt("TegridyFarms")!!
    val farmDef = Jobs.defById("farm")!!
    repeat(prog.threshold) {
        Apprenticeships.onShiftCompleted(s, farmDef) }
    Apprenticeships.judgeTalk(s, "Randy", "TegridyFarms")
    Apprenticeships.judgeTalk(s, "Randy", "TegridyFarms")
    s.absDay += Apprenticeships.GAPS[1]
    Apprenticeships.judgeTalk(s, "Randy", "TegridyFarms")
    val back = decodeGameState(encodeGameState(s))
    check(Apprenticeships.activeProgram(back)?.site == "TegridyFarms" &&
        Apprenticeships.stagesDone(back, prog) == 1 &&
        Apprenticeships.subStep(back, prog) == 1 &&
        Apprenticeships.shiftsAt(back, prog) == prog.threshold,
        "apprenticeships saves: a mid-chain state — one " +
            "stage landed, a crate on your back — round-trips " +
            "whole through the save (additive life keys, no " +
            "new save key of its own)")
}
}

private fun sectionV0150i(root: String) {
// ================= v0.15.0i: shared birthdays, whole =================
// Queue #15 item 6. The registry holds four shared days —
// July 1 (Cartman + Sheila), May 26 (Kyle + Gerald),
// September 11 (Butters + DogPoo), June 20 (Tolkien +
// Michael) — and until now every announcing/gathering
// system keyed on the roster-FIRST name alone: the
// second birthday's phone beat never sent, its party
// never considered, its name never bannered. This build
// retires the silent yield whole: both phone beats land
// inside the MAX_TEXTS discipline, the paper names the
// day AS shared, the party arbitration is explicit and
// STAMPED (a joint party at one table, a family-table
// observance at the other), and a player birthday
// landing on a cast birthday keeps both observances
// standing, the sharing on the record.
println("== v0.15.0i: shared birthdays, whole — Queue #15 item 6 ==")
val engI = Engine()
fun iState(): GameState {
    val s = engI.newState()
    engI.createPlayer(s, "New Kid", DEFAULT_APPEARANCE)
    return s
}
fun setDayI(s: GameState, absDay: Int) {
    s.absDay = absDay
    val key = keyFromOrdinal(FairCalendar
        .ordinalOfAbsDay(absDay))
    s.gameYear = key.substring(0, 4).toInt()
    s.gameMonth = key.substring(4, 6).toInt()
    s.gameDay = key.substring(6, 8).toInt()
    s.todayKey = key
}
fun absOfI(key: String): Int =
    FairCalendar.absDayOfOrdinal(ordinalOfKey(key))
// the first year (2027+) whose [md] date stands a party
// at [householdId] in a fresh town — deterministic: the
// rotation and the town's weeks are day-derived.
fun partyYear(md: String, householdId: String):
        Pair<GameState, Birthdays.Party>? {
    for (y in 2027..2032) {
        val s = iState()
        setDayI(s, absOfI("$y$md"))
        val p = Birthdays.partyTonight(s)
        if (p != null && p.household.id == householdId)
            return s to p
    }
    return null
}
val readmeI = File(root, "docs/CHANGELOG.md").readText()
val tuning = File(root, "docs/TUNING.md").readText()
check(readmeI.contains("### v0.15.0i"),
    "v0.15.0i: the README carries this build's changelog entry")
check(readmeI.contains("## Status — v0.15.0i"),
    "v0.15.0i: the README carries this build's status section")
check(tuning.contains("The shared birthdays, whole (v0.15.0i"),
    "v0.15.0i: the tuning ledger carries the shared birthdays' entry")
val manifestSrcI = File(root, "AndroidManifest.xml").readText()
check(manifestSrcI.contains("android:versionCode=\"${Version.VERSION_CODE}\"") &&
    manifestSrcI.contains("android:versionName=\"${Version.VERSION_NAME}\""),
    "release: the manifest itself carries 117 / 0.15.0i")
val ktCountI = File(root, "src/com/hunt3r/southparktown")
    .listFiles()?.count { it.isFile && it.name.endsWith(".kt") } ?: -1
check(ktCountI == 137,
    "v0.15.0i: no new module — the work rides inside " +
        "Birthdays, Phone, Engine, Newspaper and " +
        "PlayerBirthday (counted $ktCountI)")

// ---------- wiring pins: the yield is gone ----------
run {
    val phoneSrc = File(root,
        "src/com/hunt3r/southparktown/Phone.kt").readText()
    check(phoneSrc.contains(
        "for (who in Birthdays.birthdaysToday(state))") &&
        !phoneSrc.contains("birthdayOf(state)?.let"),
        "shared phone: the harvest iterates EVERY birthday " +
            "of the day — the first-name-only yield is out " +
