    val engSrc = File(root,
        "src/com/hunt3r/southparktown/Engine.kt").readText()
    check(!engSrc.contains("birthdayOf(state)?.let") &&
        engSrc.contains("for (b in Birthdays.birthdaysToday(state))") &&
