    val tgSrc = File(root,
        "src/com/hunt3r/southparktown/TalkGate.kt").readText()
    check(Regex("enum class Rail").containsMatchIn(tgSrc) &&
        !tgSrc.contains("Observance"),
        "shared rails: no observance rail exists — the " +
            "party still rides DINNER whole (TalkGate " +
            "stands at eleven rails, re-pinned in the " +
            "polish #14 contention block)")
    val claimCalls = Regex("\\.gatheringBlock\\(state")
        .findAll(engSrc).count()
    check(claimCalls == 24,
        "shared claims: Engine still consults its " +
