}

// ---------- the registry audit: the real shared days ----------
run {
    val byDay = Birthdays.DATES.entries
        .groupBy({ it.value }, { it.key })
    val shared = byDay.filter { it.value.size >= 2 }
    check(Birthdays.DATES.size == 98 && byDay.size == 94,
        "shared audit: 98 cast birthdays over 94 distinct " +
            "days — exactly four days are shared")
    check(shared.keys == setOf("0701", "0526", "0911", "0620"),
        "shared audit: the shared days are July 1, " +
            "May 26, September 11 and June 20 (got " +
            "${shared.keys})")
    check(shared["0701"]!!.toSet() == setOf("Cartman", "Sheila") &&
        shared["0526"]!!.toSet() == setOf("Kyle", "Gerald") &&
        shared["0911"]!!.toSet() == setOf("Butters", "DogPoo") &&
        shared["0620"]!!.toSet() == setOf("Tolkien", "Michael"),
        "shared audit: the pairs are Cartman + Sheila, " +
            "Kyle + Gerald, Butters + DogPoo, Tolkien + " +
            "Michael — pinned by name against the shipped " +
            "table, so a future cast wave re-opens this " +
            "audit instead of silently inheriting it")
    val s = iState()
    setDayI(s, absOfI("20270701"))
    check(Birthdays.birthdaysToday(s) ==
        listOf("Cartman", "Sheila"),
        "shared audit: birthdaysToday reads the whole " +
            "day in roster order — both names, always")
}

// ---------- May 26: one table, two birthdays — the finale week ----------
// The registry's only same-table pair. Their party is
// a JOINT party whenever the evening is free — but on
// the shipped calendar May 26 always falls inside the
// spring season-finale week (May 25–31 by Finales' own
// rule), the week every evening rail in town yields
// to, single birthdays included. So May 26's lived
// arbitration is the yield — for BOTH names, with the
// reason stamped — and the joint derivation stands
// underneath it, pinned, for any freer date.
run {
    val s = iState()
    setDayI(s, absOfI("20270526"))
    check(Birthdays.partyTonight(s) == null,
        "joint: (staging) May 26 stands no party — the " +
            "spring finale week owns the evening, this " +
            "year and every year")
    val y = Birthdays.partyYield(s)
    check(y != null && y.first == "Kyle" &&
        y.second.contains("season finale") &&
        Birthdays.birthdaysToday(s)
            .filter { Dinners.householdOf(it)?.id ==
                "broflovski" } ==
            listOf("Kyle", "Gerald"),
        "joint: the would-be party is JOINT by " +
            "derivation — the table's birthday members " +
            "are Kyle AND Gerald, exactly the set the " +
            "party's honoree rule seats — and it yields " +
            "to the finale week with its reason (yield " +
            "recorded for ${y?.first})")
    Birthdays.dailyRollover(s)
    val plan = Birthdays.planLine(s)
    check(plan != null && plan.contains("Kyle") &&
        plan.contains("Gerald") &&
        plan.contains("season finale"),
        "joint: the morning's stamp arbitrates the day " +
            "for BOTH names with the reason — Gerald's " +
            "yield is recorded beside his son's, not " +
            "absorbed into it ($plan)")
    val journal = Birthdays.journalLines(s)
    check(journal.any { it.startsWith("· Kyle:") &&
            it.contains("no party tonight") &&
            it.contains("season finale") } &&
        journal.any { it.startsWith("· Gerald:") &&
            it.contains("no party tonight") &&
            it.contains("season finale") },
        "joint: each Broflovski gets his OWN standing " +
            "line on the 🎂 page — the second name's day " +
            "is accounted in its own sentence, not a " +
            "footnote to the first")
    // the wrap of a played JOINT party pays both
    // honors: stage the record such a party writes
    // (the stamp technique this suite's censuses use)
    // and let the real rollover settle it.
    val s2 = iState()
    setDayI(s2, absOfI("20270526"))
    s2.life["bdayStepDay:broflovski"] = s2.absDay
    s2.life["bdaySteps:broflovski"] = 7
    s2.lifeText["bdayPerson:broflovski"] = "Kyle,Gerald"
    val before = listOf("Kyle", "Gerald", "Sheila", "Ike")
        .associateWith { s2.friendship[it] ?: 0 }
    setDayI(s2, s2.absDay + 1)
    Birthdays.dailyRollover(s2)
    fun delta2(name: String, gain: Int): Boolean {
        val b = before[name] ?: 0
        return (s2.friendship[name] ?: 0) ==
            minOf(100, b + gain) }
    val night2 = Birthdays.nightLine(s2, "broflovski")
    check(delta2("Kyle", Birthdays.WRAP_MEMBER_FULL +
            Birthdays.WRAP_HONOR_FULL) &&
        delta2("Gerald", Birthdays.WRAP_MEMBER_FULL +
            Birthdays.WRAP_HONOR_FULL) &&
        delta2("Sheila", Birthdays.WRAP_HOST_FULL) &&
        delta2("Ike", Birthdays.WRAP_MEMBER_FULL) &&
        night2 != null &&
        night2.contains("Kyle and Gerald") &&
        (s2.lifeText["bdayLast"] ?: "")
            .contains("Kyle and Gerald"),
        "joint: a played joint party's wrap pays EACH " +
            "honoree the honor rate on top of their " +
            "seat, and the night line names both — two " +
            "honors, one party, nobody's day halved")
}

// ---------- July 1: two tables — party + family observance ----------
run {
    val found = partyYear("0701", "cartman")
    check(found != null,
        "observance: a fresh town stands the Cartman " +
            "party on a July 1 within six years")
    val (s, party) = found!!
    check(party.honorees == listOf("Cartman"),
        "observance: the party is Cartman's — he is " +
            "first on the day's record")
    val obs = Birthdays.observancesTonight(s)
    check(obs.size == 1 && obs[0].household.id == "broflovski" &&
        obs[0].honorees == listOf("Sheila"),
        "observance: Sheila's table is CONSIDERED the " +
            "same evening — the Broflovskis hold an " +
            "observance, not a silence (got " +
            "${obs.map { it.household.id to it.honorees }})")
    // the gathering rail seats both households
    check(Birthdays.gatheringBlock(s, "Cartman", 18 * 60)
            ?.location == "CartmanHouse" &&
        Birthdays.gatheringBlock(s, "Liane", 18 * 60)
            ?.location == "CartmanHouse" &&
        Birthdays.gatheringBlock(s, "Sheila", 18 * 60)
            ?.location == "KyleHouse" &&
        Birthdays.gatheringBlock(s, "Kyle", 18 * 60)
            ?.location == "KyleHouse" &&
        Birthdays.gatheringBlock(s, "Stan", 18 * 60) == null,
        "observance: one claim, two tables — the party " +
            "household gathers for the party, the " +
            "observance household gathers at its own " +
            "table, and nobody else is claimed")
    s.timeMin = 18 * 60
    val venue = Birthdays.venueText(s, "KyleHouse")
    check(venue != null && venue.contains("Sheila") &&
        venue.contains("own"),
        "observance: a Look at the Broflovski house that " +
            "evening says what the house is doing — " +
            "marking Sheila's day at its own table")
    // the stamp, written at rollover in the day's own words
    Birthdays.dailyRollover(s)
    val plan = Birthdays.planLine(s)
    check(plan != null && plan.contains("Cartman") &&
        plan.contains("Sheila") && plan.contains("own table") &&
        (s.life["bdayPlanDay"] ?: -1) == s.absDay &&
        s.lifeText["bdayObs:broflovski"] == "Sheila" &&
        (s.life["bdayObsDay:broflovski"] ?: -1) == s.absDay,
        "observance: the arbitration is STAMPED on the " +
            "morning — who shared, where the party stands, " +
            "whose table marks its own ($plan)")
    val note = Birthdays.morningNote(s)
    check(note != null && note.contains("Cartman") &&
        note.contains("Sheila") && note.contains("own table"),
        "observance: the morning report names BOTH " +
            "birthdays and the arbitration — the second " +
            "name is announced, not absorbed")
    val journal = Birthdays.journalLines(s)
    check(journal.any { it.startsWith("· Sheila:") &&
            it.contains("own table") } &&
        journal.any { it.startsWith("📋 On the record:") &&
            it.contains("Cartman") && it.contains("Sheila") },
        "observance: the Journal's page gives Sheila her " +
            "own standing line and prints the stamped " +
            "arbitration verbatim")
    // the wrap: a night line, a count — and NO payment
    val friendsBefore = listOf("Gerald", "Sheila", "Kyle", "Ike")
        .associateWith { s.friendship[it] ?: 0 }
    setDayI(s, s.absDay + 1)
    Birthdays.dailyRollover(s)
    val obsNight = Birthdays.obsNightLine(s, "broflovski")
    check(obsNight != null && obsNight.contains("Sheila") &&
        (s.life["bdayObservances"] ?: 0) == 1 &&
        friendsBefore.all { (n, v) ->
            (s.friendship[n] ?: 0) == v } &&
        Birthdays.morningNote(s) == obsNight,
        "observance: the next morning carries the " +
            "family-table night line and the count — and " +
            "not one friendship point moved, because the " +
            "family marked it themselves (Dinners' " +
            "discipline: the town pays only at tables " +
            "the player sits at)")
}

// ---------- September 11 + June 20: the no-table birthdays ----------
run {
    val sep = partyYear("0911", "stotch")
    check(sep != null, "no-table: Butters' party stands " +
        "on a September 11 within six years")
    val (sSep, _) = sep!!
