// ---------- the phone: both beats, all four shared days ----------
run {
    fun phonePair(key: String, expect: Set<String>): Boolean {
        for (y in 2027..2031) {
            val k = "$y${key.substring(4)}"
            val s = iState()
            setDayI(s, absOfI(k) - 1)
            engI.onNewDay(s)
            if (s.todayKey != k) continue
            val beats = s.phoneTexts.filter {
                it.trigger == Phone.BIRTHDAY &&
                    it.absDay == s.absDay }
            if (beats.size == expect.size &&
                beats.map { it.sender }.toSet() == expect &&
                beats.all { it.thread == it.sender } &&
                beats.all { t -> Phone.BIRTHDAY_LINES
                    .any { it == t.text } })
                return true
        }
        return false
    }
    check(phonePair("20270701", setOf("Cartman", "Sheila")),
        "shared phone: on July 1 BOTH birthday beats " +
            "land through the real harvest — Cartman's " +
            "and Sheila's, each on their own thread")
    check(phonePair("20270526", setOf("Kyle", "Gerald")),
        "shared phone: on May 26 BOTH beats land — " +
            "Kyle's and Gerald's")
    check(phonePair("20270911", setOf("Butters", "DogPoo")),
        "shared phone: on September 11 BOTH beats " +
            "land — Butters' and DogPoo's (the day the " +
            "old rule starved hardest: no table, and " +
            "until now no text either)")
    check(phonePair("20270620", setOf("Tolkien", "Michael")),
        "shared phone: on June 20 BOTH beats land — " +
            "Tolkien's and Michael's")
}

// ---------- the phone under pressure: the shared week ----------
run {
    // the polish #14 full-census staging (206 read texts
    // in 103 threads), marched across the July 1 week:
    // the caps are the audit, and the pair is the proof.
    val s = iState()
    val threadsW = CharacterSystem.CAST.keys.toList() +
        listOf("Mom", "Dad", GroupChats.CREW_ID,
            GroupChats.FAMILY_ID, GroupChats.PLAY_ID)
    var nW = 0
    for (t in threadsW) repeat(2) {
        nW++
        s.phoneTexts.add(PhoneText(
            id = "sharew-t$nW", thread = t,
            sender = if (t in CharacterSystem.CAST.keys) t
                else "Mom",
            trigger = Phone.HELLO, absDay = 1,
            dayKey = "20270101",
            text = "A full-census text, thread $t.",
            read = true))
    }
    check(s.phoneTexts.size == 206 && threadsW.size == 103,
        "shared week: (staging) the worst case stands " +
            "at 206 texts in 103 threads")
    setDayI(s, absOfI("20270628"))
    var broken = false
    var pairLanded = false
    var bdayTexts = 0
    for (morning in 0 until 7) {
        val beforeIds = s.phoneTexts.map { it.id }.toSet()
        engI.onNewDay(s)
        val newTexts = s.phoneTexts
            .filter { it.id !in beforeIds }
        bdayTexts += newTexts.count {
            it.trigger == Phone.BIRTHDAY }
        if (s.todayKey == "20270701") {
            val senders = newTexts.filter {
                it.trigger == Phone.BIRTHDAY }
                .map { it.sender }.toSet()
            pairLanded = senders == setOf("Cartman", "Sheila")
        }
        if (newTexts.size > Phone.MAX_NEW_PER_DAY) broken = true
        if (newTexts.count { it.trigger == Phone.BIRTHDAY } >
            maxOf(1, Birthdays.birthdaysToday(s).size))
            broken = true
        if (s.phoneTexts.size > Phone.MAX_TEXTS) broken = true
        if (s.phoneTexts.groupBy { it.thread }.values
            .any { it.size > Phone.MAX_PER_THREAD })
            broken = true
        // a player who reads their phone: the harvest
        // stays alive all week, as it does in play
        for (t in s.phoneTexts) t.read = true
    }
    check(pairLanded,
        "shared week: on the July 1 morning, under a " +
            "full-census inbox, BOTH birthday beats land — " +
            "the second name is not what pressure sheds")
    check(!broken && Phone.MAX_TEXTS == 220,
        "shared week: seven mornings across a shared " +
            "day and the caps hold every one — at most " +
            "${Phone.MAX_NEW_PER_DAY} new a morning, no " +
            "thread past ${Phone.MAX_PER_THREAD}, the " +
            "inbox never past MAX_TEXTS ${Phone.MAX_TEXTS} " +
            "(the cap sheds oldest READ texts; a birthday " +
            "is never the thing dropped)")
    check(bdayTexts >= 4,
        "shared week: the week's birthday beats landed " +
            "across the march — Liane's, the July 1 pair, " +
            "and the weekend's (landed $bdayTexts)")
}

// ---------- the paper: the day named AS shared ----------
run {
    val s = iState()
    setDayI(s, absOfI("20270701"))
    val week = absOfI("20270701") / 7
    val shared = Birthdays.sharedDayLine(s, week)
    check(shared != null && shared.contains("Cartman") &&
        shared.contains("Sheila") &&
        shared.contains("July 1"),
        "shared paper: the shared-day line names both " +
            "and the date ($shared)")
    val list = Birthdays.birthdaysLine(s, week)
    check(list != null && list.contains("Cartman (7/1)") &&
        list.contains("Sheila (7/1)"),
        "shared paper: the week's list still carries " +
            "both names with their date, as it always did")
    val ed = Newspaper.composeEdition(s, week)
    val townIdx = ed.lines.indexOf("🗞 TOWN NEWS")
    val sportsIdx = ed.lines.indexOf("🏅 SPORTS")
    val sharedIdx = ed.lines.indexOf(shared)
    check(townIdx >= 0 && sharedIdx > townIdx &&
        sharedIdx < sportsIdx,
        "shared paper: the shared-day line stands " +
            "inside TOWN NEWS in the edition's fixed " +
            "order — section copy, the headline ladder " +
            "untouched at ten tiers")
    val sSingle = iState()
    setDayI(sSingle, absOfI("20271019"))
    check(Birthdays.sharedDayLine(sSingle,
        absOfI("20271019") / 7) == null,
        "shared paper: a week with no shared day " +
            "prints no shared-day line — the line exists " +
            "only where the calendar doubles")
}

// ---------- the player collision: your day meets Stephen's ----------
run {
    // on a fresh save (arrival day 3) the player's
    // day-counted birthday lands on October 3 — Stephen
    // Stotch's calendar birthday — in years two onward.
    val s = iState()
    s.life["famArrived"] = 1
    s.life["famArrivalDay"] = 3
    s.lifeText["crew:members"] = "Stan,Kyle,Butters,Wendy"
    s.friendship["Stan"] = 70
    setDayI(s, 732)
    engI.onNewDay(s)
    check(s.absDay == 733 && PlayerBirthday.isBirthday(s) &&
        Birthdays.birthdaysToday(s) == listOf("Stephen"),
        "collision: (staging) day 733 is BOTH your " +
            "second birthday and Stephen's — the shipped " +
            "calendars collide on the record, not in a " +
            "fixture invented for the test")
    val share = Birthdays.shareLine(s)
    check(share != null && share.contains("Stephen") &&
        (s.life["bdayShareDay"] ?: -1) == 733 &&
        (s.lifeText["bdayShare"] ?: "") == share,
        "collision: the sharing is STAMPED on the " +
            "morning — both observances stand in the " +
            "record's own words ($share)")
    val castParty = Birthdays.partyTonight(s) != null
    check(if (castParty)
            share!!.contains("Both tables stand") ||
                share.contains("Their table stands")
        else share!!.contains("yields tonight") ||
            share.contains("No dinner table"),
        "collision: the stamp arbitrates the evening " +
            "honestly — both tables, their table alone " +
            "with yours yielded, or theirs yielded with " +
            "its reason — and says which")
    val yourNote = PlayerBirthday.morningNote(s)
    check(yourNote != null && yourNote.contains("Stephen"),
        "collision: YOUR morning note names Stephen's " +
            "birthday too — the doubling is announced on " +
            "your own page of the morning")
    check(Birthdays.journalLines(s).any {
            it.contains("YOUR birthday today too") },
        "collision: the cast's Journal page names YOUR " +
            "birthday in return — both observances, both " +
            "records, neither absorbed")
    val bdayBeat = s.phoneTexts.filter {
        it.trigger == Phone.BIRTHDAY && it.absDay == 733 }
    val yourBeat = s.phoneTexts.filter {
        it.trigger == Phone.PLAYERBDAY && it.absDay == 733 }
    check(yourBeat.size == 1 && yourBeat[0].sender == "Stan" &&
        bdayBeat.any { it.sender == "Stephen" },
        "collision: the morning's phone carries BOTH " +
            "beats — your closest friend's PLAYERBDAY " +
            "text and Stephen's own BIRTHDAY text, " +
            "distinct senders, neither crowded out by " +
            "the other")
    val page = PlayerBirthday.pageLines(s)
    check(page.any { it.contains("Shared on the record:") &&
            it.contains("Stephen") },
        "collision: your Journal page prints the " +
            "stamped sharing verbatim")
}

// ---------- copy discipline ----------
run {
    val samples = ArrayList<String>()
    partyYear("0701", "cartman")?.let { (s, _) ->
        Birthdays.arbitrationLine(s)?.let { samples += it }
        samples += Birthdays.standingLine(s, "Sheila")
        Birthdays.venueText(s, "KyleHouse")?.let {
            samples += it }
        Birthdays.sharedDayLine(s, s.absDay / 7)?.let {
            samples += it }
    }
    partyYear("0526", "broflovski")?.let { (s, _) ->
        Birthdays.arbitrationLine(s)?.let { samples += it }
    }
    check(samples.isNotEmpty() && samples.none { t ->
        Gallery.DENYLIST.any { d ->
            t.lowercase().contains(d) } },
        "shared copy: every new authored sentence — " +
            "the arbitration, the standings, the venue " +
            "and paper lines — passes the town's denylist")
}
}

// ======================================================================
// v0.15.0j — MYSTERY #13: THE EXHIBITION CASE (Queue #15 item 7)
// The thirteenth case, "Not What the Frame Says": a print
// hanging in the wrapped gallery show is not the print its
// frame's record says it is, and the audit reads the game's
// REAL provenance chain — the album records, the darkroom
// copies, the frame log the show itself wrote. Six frames in
// hanging order, three derived checks apiece (THE PRINT /
// THE CHAIN / THE FRAME), twelve evidence, exactly two
// context-locked settlers, a finale at the Community Hall,
// CASE_TOTAL 13, and a THIRTEEN-case lifetime.
// 🔴 The spoiler wall below is load-bearing; the banned
// terms live only in this section's test data.
// ======================================================================
private fun sectionV0150j(root: String) {
    println("== v0.15.0j: mystery #13, the exhibition case ==")
    val eng13 = Engine()
    fun read13(rel: String) = File(root, rel).readText()
    val chapters13 = Mystery13.CHAPTERS13
    val items13 = Mystery13.CLUES13
    // this section's own staging helpers (the gallery
    // section's are its own locals): a fresh played state,
    // a photograph record, a season key
    fun gState13(): GameState {
        val s = eng13.newState()
        eng13.createPlayer(s, "Walker", DEFAULT_APPEARANCE)
        return s
    }
    fun photo13(id: String, dayKey: String, loc: String = "Mall",
                timeMin: Int = 720, followers: Int = 0,
                figs: List<Pair<String, String>> = emptyList()) =
        PhotoRecord(
            id = id, dayKey = dayKey, dateLabel = "?",
            timeMin = timeMin, locId = loc, inside = false,
            weatherId = "sunny", appearance = DEFAULT_APPEARANCE,
            figures = figs.map { (n, r) ->
                PhotoFigure(n, "cast", "happy", reaction = r) },
            seed = 3L, absDay = 0, followersGained = followers,
            commissionAsker = "", starred = false,
            composition = "")
    fun keyIn13(cal: GalleryCal): String =
        keyFromOrdinal(cal.seasonStartOrd + 5)

    // ---------- staging: a real wrapped show ----------
    // Two of the player's own frames (an album frame and a
    // darkroom print) and four cast frames ranked onto the
    // wall by their followings — hung by the game's own
    // hands (recordFor / enterAlbum / enterPrint / lockShow
    // / dailyRollover), wrapped by its own calendar. The
    // board's six frames are the wall's first six.
    fun stageWall13(s: GameState): GalleryShow {
        val cal = GalleryCalendar.cal(2026, Season.FALL)
        val key = keyIn13(cal)
        s.gameYear = 2026
        s.absDay = cal.announceDay + 1
        Gallery.recordFor(s, cal)
        val jurors = Gallery.juryFor(cal).map { it.name }.toSet()
        val castNames = listOf("Stan", "Kyle", "Bebe", "Wendy",
            "Craig", "Butters", "Kenny", "Cartman")
            .filter { it !in jurors }.take(4)
        val locs = listOf("Mall", "Bijou", "StarksPond", "CityHall")
        castNames.forEachIndexed { i, name ->
            s.photos += photo13("cast$i", key, loc = locs[i],
                timeMin = 700 + 20 * i,
                followers = 40 - 10 * i,
                figs = listOf(name to "happy"))
        }
        s.photos += photo13("mineA", key, loc = "MainStreet",
            timeMin = 800)
        val recP = photo13("mineP", key, loc = "FotoPharm",
            timeMin = 820)
        s.photos += recP
        s.prints += DarkroomPrint("prMine", "mineP", recP,
            Darkroom.SIZE_PRINT, 3, key)
        Gallery.enterAlbum(s, "mineA")
        Gallery.enterPrint(s, "prMine")
        val show = Gallery.showFor(s, cal)!!
        Gallery.lockShow(s, show, quiet = false)
        s.absDay = cal.wrapDay
        Gallery.dailyRollover(s)
        return show
    }
    // A case state with the wall staged and the audit open.
    fun caseState13(): GameState {
        val s = gState13()
        stageWall13(s)
        s.arc12Retired = true; s.arc12RetiredDay = 100
        s.arc13Started = true; s.arc13Chapter = 4
        s.arc13ShowId = s.galleryShows.last().id
        return s
    }
    val truthCalls13 = listOf("true", "mistake", "mistake",
        "true", "swapped", "true")
    fun settleWall13(s: GameState) {
        for (c in items13) Mystery13.grantClue13(s, c.id)
        Mystery13.boardFrames13(s).forEachIndexed { i, f ->
            Mystery13.chooseCall13(s, f.id, truthCalls13[i])
        }
    }

    // ---------- the case's shape ----------
    check(chapters13.size == 4 &&
        chapters13.all { it.stages.size == 4 } &&
        chapters13.all { it.episodeTitles.size == 2 } &&
        chapters13.all { it.coldOpen.size == 2 } &&
        chapters13[3].id == Mystery13.FINALE13_ID &&
        Mystery13.CASE_TITLE == "Not What the Frame Says",
        "exhibition: the case is four chapters of four " +
            "stages, two episode titles and a two-line cold " +
            "open apiece, the finale 'The Wall, Read Back'")
    check(chapters13.map { it.causers } == listOf(
        listOf("Victoria", "Mephesto"), listOf("Mephesto", "Craig"),
        listOf("Victoria", "Craig"), listOf("Victoria", "Mephesto")),
        "exhibition: the chapters' credited causers — the " +
            "hang's curator and the darkroom's keeper open " +
            "and close it; the hanger carries the middle")
    check(Mystery13.CHAPTER_GAP_DAYS == 7 &&
        Mystery13.OPEN_DELAY_DAYS == 10 &&
        Mystery13.POST_DELAY_DAYS == 7,
        "exhibition: the case's clock — a chapter a week, " +
            "ten days' queue behind the twelfth case, the " +
            "quiet rehang a week after the telling")

    // ---------- the board derives from the real wall ----------
    run {
        val s = caseState13()
        val frames = Mystery13.boardFrames13(s)
        check(frames.size == 6 &&
            frames.map { it.id } == (1..6).map { "frame_$it" } &&
            frames.map { it.index } == (0..5).toList(),
            "exhibition board: six frames in hanging order, " +
                "numbered off the wall itself — the audit's " +
                "board is the show's own record, re-read")
        check(frames.map { Mystery13.shape13(s, it) } ==
            truthCalls13,
            "exhibition board: on the staged wall the " +
                "derived shapes are two true hangings " +
                "standing clean, a crossed pair, one frame " +
                "whose records all agree and whose mount " +
                "disagrees, and the rest true — shape is " +
                "DERIVED from the records, never assigned")
        check(frames[0].entry.entrant == Gallery.YOU &&
            frames[1].entry.entrant == Gallery.YOU &&
            frames[1].entry.kind == Gallery.KIND_PRINT,
            "exhibition board: the player's own two frames " +
                "lead the wall — an album frame and a " +
                "darkroom print, both auditable like any other")
        // the three checks, named on the findings
        val f0 = Mystery13.findings13(s, frames[0])
        check(f0.printOk && f0.chainOk && f0.frameOk &&
            f0.printState == "match",
            "exhibition board: a clean frame passes THE " +
                "PRINT, THE CHAIN and THE FRAME together")
        val f1 = Mystery13.findings13(s, frames[1])
        val f2 = Mystery13.findings13(s, frames[2])
        check(f1.crossed && f2.crossed && !f1.printOk &&
            frames[1].partner == 2 && frames[2].partner == 1,
            "exhibition board: the crossed pair's prints " +
                "read as EACH OTHER'S records against the " +
                "album and the darkroom copies — the cross " +
                "is in the chain, not in either record")
        val f4 = Mystery13.findings13(s, frames[4])
        check(f4.printOk && f4.chainOk && f4.frameOk &&
            f4.mountTells.size == 2 &&
            Mystery13.shape13(s, frames[4]) == "swapped",
            "exhibition board: the one frame whose three " +
                "record checks all pass and whose mount tells " +
                "on it — the print is right in every record " +
                "and wrong on the wall")
        // derivation is live: break a chain and the shape moves
        val sBroke = caseState13()
        val brokeFrames = Mystery13.boardFrames13(sBroke)
        val victim = brokeFrames[3]
        sBroke.photos.removeAll { it.id == victim.entry.photoId }
        check(!Mystery13.findings13(sBroke, victim).chainOk &&
            Mystery13.shape13(sBroke, victim) == "mistake",
            "exhibition board: take a frame's album record " +
                "out of the world and its chain breaks on the " +
                "next read — nothing about the board is stored")
        // and a cross survives its partner's record fading:
        // the mount facts carry what the paper no longer can
        val sFaded = caseState13()
        val fadedFrames = Mystery13.boardFrames13(sFaded)
        sFaded.photos.removeAll {
            it.id == fadedFrames[2].entry.photoId }
        check(Mystery13.shape13(sFaded, fadedFrames[1]) ==
            "mistake",
            "exhibition board: a crossed frame stays crossed " +
                "when the partner photograph leaves the album " +
                "— the witnessed mount is part of the record")
    }

    // ---------- the evidence registry ----------
    check(items13.size == 12 &&
        items13.count { it.kind == Mystery13.Kind13.WITNESS } == 5 &&
        items13.count { it.kind == Mystery13.Kind13.LOOK } == 5 &&
        items13.count { it.kind == Mystery13.Kind13.PARTICIPATION } == 2 &&
        items13.map { it.id }.distinct().size == 12 &&
        items13.all { it.title.isNotBlank() && it.detail.isNotBlank() },
        "exhibition evidence: the registry is twelve " +
            "pieces — five witness, five look, two " +
            "participation — every one titled and told")
    check((0..5).all { site ->
            items13.count { it.site == site } == 2 &&
            Mystery13.SETTLER13[site] in
                items13.filter { it.site == site }.map { it.id } &&
            items13.single { it.id == Mystery13.SETTLER13[site] }
                .proof },
        "exhibition evidence: two pieces stand at every " +
            "frame's site, and exactly one of them — the " +
            "frame's settler — can grade a reading of it")
    check(items13.count { it.proof } == 6 &&
        items13.filter { it.unlockChapter > it.minChapter }
            .map { it.id }.toSet() ==
            setOf("hang_list_whole", "rehang_hands") &&
        items13.filter { it.unlockChapter > it.minChapter }
            .all { c -> items13.any {
                it.id == Mystery13.SETTLER13[c.site] &&
                    it.id == c.id } },
        "exhibition evidence: exactly two pieces are " +
            "context-locked, and they are the two " +
            "load-bearing frames' settlers — a frame's " +
            "settler IS its site's proof, six sites, six proofs")
    check(Mystery13.FRAME_MIN_CHAPTER13 == listOf(1, 2, 1, 1, 2, 1) &&
        Mystery13.SETTLER13[1] == "hang_list_whole" &&
        Mystery13.SETTLER13[4] == "rehang_hands",
        "exhibition evidence: the load-bearing frames are " +
            "the crossed pair's near half and the swapped " +
            "frame — the finale's full read stands on those " +
            "two readings or it does not stand")


    // ---------- verdicts: the 4,096-subset sweep ----------
    // The verdict rule, restated in the test from the
    // case's published terms alone (the registry's own
    // numbers and the staged wall's shapes): a frame can
    // be read once its chapter has come and its OWN site
    // holds two live pieces; a reading with its settler
    // not live is COMMITTED; with the settler live it is
    // PROVEN when it matches the derived shape and
    // REFUTED when it doesn't; an unreadable frame stays
    // OPEN whatever was attempted. Swept over every
    // evidence subset at two chapters — one where the
    // locked settlers have opened, one where they haven't.
    run {
        val frames = Mystery13.boardFrames13(caseState13())
        val ids = items13.map { it.id }
        fun expectedVerdict(mask: Int, chapter: Int,
                            fIdx: Int): String {
            fun held(i: Int) = mask and (1 shl i) != 0
            fun live(c: Mystery13.Clue13) =
                held(ids.indexOf(c.id)) &&
                    chapter > c.unlockChapter
            val siteClues = items13.filter { it.site == fIdx }
            val callable = chapter >
                Mystery13.FRAME_MIN_CHAPTER13[fIdx] &&
                siteClues.count { live(it) } >= 2
            if (!callable) return "OPEN"
            val settler = items13.single {
                it.id == Mystery13.SETTLER13[fIdx] }
            if (!live(settler)) return "COMMITTED"
            return if (truthCalls13[fIdx] == "true")
                "PROVEN" else "REFUTED"
        }
        var ok = true
        var subsets = 0
        for (chapter in listOf(4, 2)) {
            for (mask in 0 until 4096) {
                val s = caseState13()
                s.arc13Chapter = chapter
                for (i in ids.indices)
                    if (mask and (1 shl i) != 0)
                        Mystery13.grantClue13(s, ids[i])
                for (f in frames)
                    Mystery13.chooseCall13(s, f.id, "true")
                for (f in frames)
                    if (Mystery13.frameVerdict13(s, f) !=
                        expectedVerdict(mask, chapter, f.index))
                        ok = false
                subsets++
            }
        }
        check(ok && subsets == 8192,
            "exhibition verdicts: across all 4,096 evidence " +
                "subsets at two chapters the derived verdict " +
                "matches the independent restatement — a " +
                "reading is only ever graded by its own " +
                "frame's LIVE settler, priced off its own site")
        // uncalled frames read OPEN whatever the evidence
        val sOpen = caseState13()
        check(Mystery13.boardFrames13(sOpen).all {
            Mystery13.frameVerdict13(sOpen, it) == "OPEN" },
            "exhibition verdicts: an uncalled frame is OPEN " +
                "whatever the evidence — the board never " +
                "calls a reading for you")
        // a refuted reading can be struck and read again;
        // a standing proven reading is final
        val sRe = caseState13()
        for (c in items13) Mystery13.grantClue13(sRe, c.id)
        val fr = Mystery13.boardFrames13(sRe)[0]
        Mystery13.chooseCall13(sRe, fr.id, "mistake")
        val refuted = Mystery13.frameVerdict13(sRe, fr) == "REFUTED"
        Mystery13.chooseCall13(sRe, fr.id, "true")
        val proven = Mystery13.frameVerdict13(sRe, fr) == "PROVEN"
        val frozen = !Mystery13.chooseCall13(sRe, fr.id, "mistake")
        check(refuted && proven && frozen,
            "exhibition verdicts: a refuted reading strikes " +
                "and re-reads; a proven reading stands final")
    }

    // ---------- discovery: queue, anchor, the three seams ----------
    run {
        // the queue gate: nothing before the twelfth retires
        val sEarly = gState13()
        stageWall13(sEarly)
        sEarly.absDay = 500
        check(Mystery13.dueChapter13(sEarly) == null &&
            !sEarly.arc13Started && sEarly.arc13DueAbsDay == -1,
            "exhibition queue: with the returns case still " +
                "open the exhibition case does not exist — " +
                "no anchor, no chapter, however ready the wall")
        // the arming rule: retired twelfth, but no show —
        // the queue waits unanchored rather than fabricating
        val sNoShow = gState13()
        sNoShow.arc12Retired = true; sNoShow.arc12RetiredDay = 100
        sNoShow.absDay = 500
        check(Mystery13.dueChapter13(sNoShow) == null &&
            sNoShow.arc13DueAbsDay == -1 &&
            sNoShow.arc13ShowId.isEmpty(),
            "exhibition queue: a save that never exhibited " +
                "never arms the case — ten days past the " +
                "twelfth case it still waits, unanchored, " +
                "for a wall that exists")
        // an unqualified show doesn't arm it either: hang a
        // thin wall (two frames) and it still waits
        val sThin = gState13()
        val calT = GalleryCalendar.cal(2026, Season.FALL)
        sThin.gameYear = 2026
        sThin.absDay = calT.announceDay + 1
        Gallery.recordFor(sThin, calT)
        sThin.photos += photo13("only1", keyIn13(calT))
        Gallery.enterAlbum(sThin, "only1")
        val thinShow = Gallery.showFor(sThin, calT)!!
        Gallery.lockShow(sThin, thinShow, quiet = true)
        sThin.absDay = calT.wrapDay
        Gallery.dailyRollover(sThin)
        sThin.arc12Retired = true; sThin.arc12RetiredDay = 100
        sThin.absDay = 500
        check(Mystery13.dueChapter13(sThin) == null &&
            sThin.arc13ShowId.isEmpty(),
            "exhibition queue: a wrapped show under six " +
                "distinct photographs is a wall, not an " +
                "audit — the case keeps waiting")
        // the anchor: the first qualifying morning pins the
        // show and the day, ten past the twelfth's retirement
        val sArm = gState13()
        val show = stageWall13(sArm)
        sArm.arc12Retired = true; sArm.arc12RetiredDay =
            sArm.absDay - 3
        val dueDay = sArm.arc12RetiredDay + 10
        check(Mystery13.dueChapter13(sArm) == null &&
            sArm.arc13ShowId == show.id &&
            sArm.arc13DueAbsDay == dueDay,
            "exhibition queue: the morning the queue can " +
                "first see its wall, it books the audit — " +
                "the show pinned, the day set ten past the " +
                "twelfth case's retirement, nothing aired early")
        sArm.absDay = dueDay - 1
        check(Mystery13.dueChapter13(sArm) == null,
            "exhibition queue: the booked day is the day — " +
                "not the night before")
        sArm.absDay = dueDay
        sArm.holidayId = "halloween"
        check(Mystery13.dueChapter13(sArm) == null,
            "exhibition queue: a holiday defers the opening " +
                "without repricing it")
        sArm.holidayId = null
        val ch1 = Mystery13.dueChapter13(sArm)
        check(ch1 != null && ch1.id == chapters13[0].id,
            "exhibition queue: on its morning, chapter one " +
                "is due")
        Mystery13.noteChapterStarted13(sArm, ch1!!)
        check(sArm.arc13Started && sArm.arc13Chapter == 1 &&
            sArm.arc13DueAbsDay == dueDay + 7,
            "exhibition queue: an aired chapter starts the " +
                "case and paces the next a week out")
    }
    run {
        // witness tellings on the owed-lines seam
        val s = caseState13()
        s.arc13Chapter = 1
        val tw = Mystery13.witnessLine13(s, "Tweek")
        check(tw != null && tw.speaker == "Tweek" &&
            "ladder_foot" in s.mystery13Clues,
            "exhibition discovery: a witness's telling " +
                "grants its piece on the seam — the boy who " +
                "held the ladder, in his own voice")
        check(Mystery13.witnessLine13(s, "Tweek") == null,
            "exhibition discovery: a telling is told once")
        // the look seam: an unlocked piece reads whole; a
        // locked one is granted but the board shows its
        // sealed face and it is not live evidence
        val sLook = caseState13()
        sLook.arc13Chapter = 1
        val log = Mystery13.lookClueText13(sLook, "CityHall")
        check(log != null && "log_first_page" in
            sLook.mystery13Clues &&
            Mystery13.clueLive13(sLook, items13.single {
                it.id == "log_first_page" }),
            "exhibition discovery: the log book's first " +
                "page is a look away at the hall, live from " +
                "the chapter that surfaces it")
        val sLock = caseState13()
        sLock.arc13Chapter = 2
        Mystery13.grantClue13(sLock, "log_first_page")
        val whole = Mystery13.lookClueText13(sLock, "CityHall")
        val lockedClue = items13.single { it.id == "hang_list_whole" }
        val boardSealed = Mystery13.boardLines13(sLock)
            .joinToString("\n")
        check(whole != null && "hang_list_whole" in
            sLock.mystery13Clues &&
            boardSealed.contains("🔒") &&
            !boardSealed.contains(lockedClue.detail) &&
            !Mystery13.clueLive13(sLock, lockedClue),
            "exhibition discovery: the hang list is in hand " +
                "a chapter before its context — carried, " +
                "sealed on the board, and NOT live evidence " +
                "while it waits")
        sLock.arc13Chapter = 3
        val boardOpen = Mystery13.boardLines13(sLock)
            .joinToString("\n")
        check(boardOpen.contains(lockedClue.detail) &&
            Mystery13.clueLive13(sLock, lockedClue),
            "exhibition discovery: when its chapter airs " +
                "the context, the same page reads whole on " +
                "the board and the piece goes live")
        // participation rides the case's own chapters
        val sPart = caseState13()
        sPart.arc13Chapter = 2
        Mystery13.noteParticipation13(sPart,
            "arc13_ch2_the_chain_of_copies")
        check("pair_handled" in sPart.mystery13Clues,
            "exhibition discovery: the crossed pair handled " +
                "under the darkroom lamp is earned inside " +
                "the chapter that stages it, not before")
        val sPart2 = caseState13()
        sPart2.arc13Chapter = 3
        Mystery13.noteParticipation13(sPart2,
            "arc13_ch3_the_rehang")
        check("rehang_hands" in sPart2.mystery13Clues &&
            !Mystery13.clueLive13(sPart2, items13.single {
                it.id == "rehang_hands" }),
            "exhibition discovery: the rehang's hands-on " +
                "piece is granted in its chapter and sits " +
                "inert until the finale's chapter airs its context")
        // pricing: a frame is callable at two live pieces
        // bearing on ITS site — evidence elsewhere on the
        // wall doesn't price it
        val sPrice = caseState13()
        sPrice.arc13Chapter = 3
        val priced = Mystery13.boardFrames13(sPrice)[1]
        Mystery13.grantClue13(sPrice, "hang_list_whole")
        check(!Mystery13.frameCallable13(sPrice, priced),
            "exhibition pricing: one live piece at a frame's " +
                "site is not the price — the crossed frame " +
                "waits for its second")
        Mystery13.grantClue13(sPrice, "log_first_page")
        Mystery13.grantClue13(sPrice, "ladder_foot")
        check(!Mystery13.frameCallable13(sPrice, priced),
            "exhibition pricing: live evidence at ANOTHER " +
                "frame's site doesn't price this one either")
        Mystery13.grantClue13(sPrice, "hanger_on_the_cross")
        Mystery13.chooseCall13(sPrice,
            Mystery13.boardFrames13(sPrice)[0].id, "true")
        check(Mystery13.frameCallable13(sPrice, priced) &&
            Mystery13.pendingFrame13(sPrice)?.id == priced.id,
            "exhibition pricing: the second live piece at " +
                "its own site makes the frame readable, and " +
                "the board offers it")
    }

    // ---------- the finale: tiers, deference, the lock ----------
    run {
        val sDue = caseState13()
        sDue.absDay = 500
        settleWall13(sDue)
        check(!Mystery13.verdictDue(sDue),
            "exhibition finale: a settled audit alone " +
                "doesn't call the reading — the finale has " +
                "to be airing")
        sDue.shenaniganId = Mystery13.FINALE13_ID
        sDue.timeMin = 8 * 60
        check(!Mystery13.verdictDue(sDue),
            "exhibition finale: — and its climax stage has " +
                "to have come")
        sDue.timeMin = 13 * 60
        check(Mystery13.verdictDue(sDue) &&
            Finales.climaxPending(sDue) &&
            School.anyClimaxDueToday(sDue) &&
            Walk.caseCritical(sDue) &&
            MovieNights.anyClimaxDueTonight(sDue),
            "exhibition finale: with the audit complete " +
                "and the reading airing, every deference " +
                "list in town stands down for it — finales, " +
                "school, the road, the movies")
        check(Mystery13.finishEligible13(sDue) &&
            Mystery13.nameEligible13(sDue),
            "exhibition finale: a fully proven audit opens " +
                "both gated calls")
        check(!Mystery13.chooseFinale13(sDue, "dance"),
            "exhibition finale: the reading takes the four " +
                "calls and no others")
        // one load-bearing frame short: the read locks,
        // the name call stands
        val sShort = caseState13()
        sShort.absDay = 500
        for (c in items13) Mystery13.grantClue13(sShort, c.id)
        Mystery13.boardFrames13(sShort).forEachIndexed { i, f ->
            if (i != 4) Mystery13.chooseCall13(sShort, f.id,
                truthCalls13[i])
        }
        check(!Mystery13.finishEligible13(sShort) &&
            Mystery13.nameEligible13(sShort),
            "exhibition finale: with the swapped frame " +
                "unread the full read stays locked — its two " +
                "load-bearing readings are the gate — while " +
                "the name call stands on the proven rest")
        // the board completed with that frame read WRONG:
        // the reading is due, the full read still refuses
        Mystery13.chooseCall13(sShort,
            Mystery13.boardFrames13(sShort)[4].id, "true")
        sShort.shenaniganId = Mystery13.FINALE13_ID
        sShort.timeMin = 13 * 60
        check(Mystery13.verdictDue(sShort) &&
            !Mystery13.chooseFinale13(sShort, "read") &&
            Mystery13.chooseFinale13(sShort, "stand"),
            "exhibition finale: at the lock, the full read " +
                "refuses an audit short of its gate — and " +
                "the ungated calls still take")
        // nothing proven at all: even the name call locks
        val sNone = caseState13()
        check(!Mystery13.nameEligible13(sNone) &&
            !Mystery13.finishEligible13(sNone),
            "exhibition finale: with nothing proven, even " +
                "the name call is locked — the room must " +
                "have read SOMETHING")
    }


    // ---------- resolve, effects, the delayed tail ----------
    run {
        val s = caseState13()
        s.absDay = 500
        settleWall13(s)
        s.shenaniganId = Mystery13.FINALE13_ID
        s.timeMin = 13 * 60
        check(Mystery13.chooseFinale13(s, "read"),
            "exhibition resolve: the earned read locks")
        val out = Mystery13.resolveVerdict(s)
        check(s.arc13Retired && s.arc13Branch == "read" &&
            out.branch == "read" && s.arc13RetiredDay == 500,
            "exhibition resolve: the full read lands READ — " +
                "retired, stamped, branch and all")
        Mystery13.applyVerdictEffects(s, out.branch)
        check(s.arc13PostPending && s.arc13PostDay == 507 &&
            !s.arc13Posted &&
            s.lifeText["mark:CityHall"]!!.contains("read back aloud"),
            "exhibition resolve: the read landing leaves " +
                "its mark at the hall and books its quiet " +
                "rehang a week out — and only the read " +
                "landing books one")
        s.absDay = 506
        Mystery13.noteWallCorrected(s)
        check(!s.arc13Posted && s.arc13PostPending,
            "exhibition tail: the rehang does not come early")
        s.absDay = 507
        Mystery13.noteWallCorrected(s)
        check(s.arc13Posted && !s.arc13PostPending &&
            s.lifeText["mark:CityHall"]!!.contains("rehung true"),
            "exhibition tail: a week on, the wall is " +
                "quietly rehung true — the pair uncrossed, " +
                "the original home in its frame")
        val eventsAfter = s.events.size
        Mystery13.noteWallCorrected(s)
        check(s.events.size == eventsAfter,
            "exhibition tail: the rehang happens once")
        // degraded at the wrap: lock the read, then break
        // the board under it — the landing degrades, it is
        // never upgraded
        val sDeg = caseState13()
        sDeg.absDay = 500
        settleWall13(sDeg)
        sDeg.shenaniganId = Mystery13.FINALE13_ID
        sDeg.timeMin = 13 * 60
        Mystery13.chooseFinale13(sDeg, "read")
        val third = Mystery13.boardFrames13(sDeg)[3]
        sDeg.photos.removeAll { it.id == third.entry.photoId }
        val outDeg = Mystery13.resolveVerdict(sDeg)
        check(outDeg.branch == "unread" && sDeg.arc13Retired &&
            sDeg.arc13Branch == "unread",
            "exhibition resolve: a read locked on a board " +
                "that breaks before the wrap lands UNREAD — " +
                "the gate re-checks at the wrap, and a " +
                "finish is never forced or upgraded")
        // the other landings retire cleanly too
        for ((choice, branch) in listOf("name" to "named",
            "stand" to "standing", "walk" to "unread")) {
            val sx = caseState13()
            sx.absDay = 500
            settleWall13(sx)
            sx.shenaniganId = Mystery13.FINALE13_ID
            sx.timeMin = 13 * 60
            Mystery13.chooseFinale13(sx, choice)
            val ox = Mystery13.resolveVerdict(sx)
            check(ox.branch == branch && sx.arc13Retired &&
                !sx.arc13PostPending,
                "exhibition resolve: the '$choice' call lands " +
                    "$branch, and books no rehang")
        }
    }

    // ---------- aftermath & ambient: one voice per landing ----------
    run {
        val voices = mapOf("read" to "Victoria",
            "named" to "Craig", "standing" to "Mephesto",
            "unread" to "Butters")
        var ok = true
        for ((branch, voice) in voices) {
            val s = caseState13()
            s.arc13Retired = true; s.arc13Branch = branch
            for (other in voices.values)
                if ((Mystery13.aftermathLine13(s, other) != null) !=
                    (other == voice)) ok = false
            val amb = Mystery13.ambientCallback13(s,
                kotlin.random.Random(13))
            if (amb == null) ok = false
        }
        check(ok, "exhibition aftermath: each landing " +
            "leaves exactly one voice standing on the seam " +
            "— the curator for the read, the named man for " +
            "the name, the examiner for the standing, the " +
            "kind heart for the unread — and the ending " +
            "drifts into ordinary talk")
        val sOpen = caseState13()
        check(voices.values.all {
            Mystery13.aftermathLine13(sOpen, it) == null },
            "exhibition aftermath: nobody speaks for a case " +
                "that hasn't closed")
    }

    // ---------- the board, drawn ----------
    run {
        val s = caseState13()
        s.arc13Chapter = 2
        Mystery13.grantClue13(s, "hang_list_whole")
        val joined = Mystery13.boardLines13(s)
            .joinToString("\n")
        check(Mystery13.boardVisible13(s) &&
            joined.contains("TRUE SHAPED") &&
            joined.contains("CROSSED SHAPED") &&
            joined.contains("SWAPPED SHAPED") &&
            joined.contains("THE PRINT") &&
            joined.contains("THE CHAIN") &&
            joined.contains("THE FRAME") &&
            joined.contains("THE READING'S TERMS"),
            "exhibition board: the board draws the wall in " +
                "hanging order — frames, the three checks, " +
                "derived shapes — and publishes the " +
                "reading's terms while the case is open")
        check(joined.contains("🔒") &&
            joined.contains("hasn't arrived"),
            "exhibition board: an in-hand piece whose " +
                "context hasn't come shows its locked face — " +
                "the board can hold the audit; it cannot " +
                "read it")
        val sDone = caseState13()
        sDone.absDay = 500
        settleWall13(sDone)
        sDone.shenaniganId = Mystery13.FINALE13_ID
        sDone.timeMin = 13 * 60
        Mystery13.chooseFinale13(sDone, "read")
        Mystery13.resolveVerdict(sDone)
        Mystery13.applyVerdictEffects(sDone, "read")
        sDone.absDay = 507
        Mystery13.noteWallCorrected(sDone)
        val closed = Mystery13.boardLines13(sDone)
            .joinToString("\n")
        check(closed.contains("🏁") &&
            closed.contains("the rehang came"),
            "exhibition board: the closed board carries " +
                "its closing lines — and the rehang, come " +
                "home, a week on")
        check(!Mystery13.boardVisible13(eng13.newState()),
            "exhibition board: there is no thirteenth case " +
                "on a fresh Journal")
    }

    // ---------- 🔴 the spoiler wall ----------
    // Everything a player can read BEFORE the finale —
    // chapters 1–3 entire, every clue's face that can be
    // held by chapter 3 (live details for the unlocked,
    // inert faces for the locked), the board as it stands
    // mid-case, and this build's README entry — must not
    // name the hand the finale names, its hiding place,
    // or its errand. The terms below live only here.
    run {
        val corpus = StringBuilder()
        for (ch in chapters13.take(3)) {
            corpus.append(ch.title).append('\n')
            corpus.append(ch.blurb).append('\n')
            for (st in ch.stages) {
                corpus.append(st.title).append('\n')
                corpus.append(st.banner).append('\n')
                corpus.append(st.journalNote).append('\n')
                corpus.append(st.objective).append('\n')
            }
            for (line in ch.coldOpen)
                corpus.append(line.text).append('\n')
        }
        for (c in items13) {
            corpus.append(c.title).append('\n')
            if (c.unlockChapter <= 2)
                corpus.append(c.detail).append('\n')
            corpus.append(c.inertDetail).append('\n')
            if (c.minChapter <= 2) {
                c.spoken?.let { corpus.append(it).append('\n') }
                c.foundText?.let { corpus.append(it).append('\n') }
            }
        }
        val sMid = caseState13()
        sMid.arc13Chapter = 3
        for (c in items13) Mystery13.grantClue13(sMid, c.id)
        corpus.append(Mystery13.boardLines13(sMid)
            .joinToString("\n"))
        val readme13 = read13("docs/CHANGELOG.md")
        val entryStart = readme13.indexOf("### v0.15.0j")
        val entryEnd = readme13.indexOf("### v0.15.0i")
        corpus.append(readme13.substring(entryStart, entryEnd))
        val text = corpus.toString()
        val banned = listOf("Randy", "Marsh", "Tegridy",
            "gift box", "victimless", "certified")
        val hits = banned.filter {
            text.lowercase().contains(it.lowercase()) }
        check(hits.isEmpty(),
            "exhibition spoiler wall: nothing a player can " +
                "read before the finale names the hand, its " +
                "hiding place or its errand (hits: $hits)")
    }

    // ---------- saves: additive, hostile-safe ----------
    run {
        val sMid = caseState13()
        sMid.arc13Chapter = 3
        sMid.arc13DueAbsDay = 401; sMid.absDay = 396
        sMid.mystery13Clues.clear()
        for (id in listOf("log_first_page", "hang_list_whole",
            "negative_sleeve", "frame_backs"))
            sMid.mystery13Clues.add(id)
        val frames = Mystery13.boardFrames13(sMid)
        sMid.arc13Calls[frames[0].id] = "true"
        sMid.arc13Calls[frames[4].id] = "mistake"
        val round = decodeGameState(encodeGameState(sMid))
        check(round.arc13Started && round.arc13Chapter == 3 &&
            round.arc13DueAbsDay == 401 &&
            round.arc13ShowId == sMid.arc13ShowId &&
            round.mystery13Clues == sMid.mystery13Clues &&
            round.arc13Calls == sMid.arc13Calls,
            "exhibition saves: a mid-case save — chapter, " +
                "booked show, evidence, readings — survives " +
                "the round trip whole")
        val legacyDoc = encodeGameState(sMid).toMutableMap()
            .apply { remove("arc13"); remove("mystery13Clues")
                remove("arc13Calls") }
        val legacy = decodeGameState(legacyDoc)
        check(!legacy.arc13Started &&
            legacy.mystery13Clues.isEmpty() &&
            legacy.arc13Calls.isEmpty() &&
            legacy.arc13DueAbsDay == -1 &&
            legacy.arc13ShowId.isEmpty(),
            "exhibition saves: a pre-0.15.0j save loads " +
                "quietly — no chapter, no evidence, no " +
                "anchor: the case queues behind the " +
                "twelfth, unqueued and unharmed")
        val hostileDoc = encodeGameState(sMid).toMutableMap()
            .apply {
                put("arc13", mapOf("chapter" to 2,
                    "started" to true, "branch" to "solved",
                    "choice" to "yell",
                    "showId" to "forged_show"))
                put("mystery13Clues", listOf("log_first_page",
                    "the_answer"))
                put("arc13Calls", mapOf("frame_1" to "whatever",
                    "frame_9" to "swapped",
                    "frame_5" to "swapped"))
            }
        val hostile = decodeGameState(hostileDoc)
        check(hostile.arc13Branch.isEmpty() &&
            hostile.arc13Choice.isEmpty() &&
            hostile.mystery13Clues == setOf("log_first_page") &&
            hostile.arc13Calls == mapOf("frame_5" to "swapped"),
            "exhibition saves: a tampered save keeps only " +
                "registered pieces, frames and readings — " +
                "the audit cannot be forged")
    }


    // ---------- the thirteen-case lifetime ----------
    // Phase one: twelve cases retire in one unattended
    // life while no show has ever hung — the thirteenth
    // cannot so much as anchor. Phase two: a real show is
    // staged into the running life (entered by the game's
    // own hands, wrapped by its own calendar), and the
    // case the show casts as its shadow airs, retires,
    // and leaves the queue empty behind it.
    run {
        val life = eng13.newState()
        eng13.createPlayer(life, "Walker", DEFAULT_APPEARANCE)
        var days = 0
        var startedEarly = false
        while (days < 3000 && !life.arc12Retired) {
            eng13.onNewDay(life)
            if (life.arc13Started) startedEarly = true
            days++
        }
        check(life.arc12Retired && !startedEarly &&
            !life.arc13Started && life.arc13DueAbsDay == -1,
            "exhibition lifetime: twelve cases retire in " +
                "one unattended life ($days days) and the " +
                "thirteenth never anchors — no wall has " +
                "ever hung in it")
        var staged = false
        var startedBehind = false
        var days2 = 0
        while (days2 < 2400 && !life.arc13Retired) {
            eng13.onNewDay(life)
            if (!staged) {
                val cal = GalleryCalendar.cycleAt(life.absDay).cal
                if (life.absDay == cal.announceDay + 1) {
                    val key = keyIn13(cal)
                    val jurors = Gallery.juryFor(cal)
                        .map { it.name }.toSet()
                    val names = listOf("Stan", "Kyle", "Bebe",
                        "Wendy", "Craig", "Butters", "Kenny",
                        "Cartman").filter { it !in jurors }.take(4)
                    names.forEachIndexed { i, name ->
                        life.photos += photo13("life$i", key,
                            loc = listOf("Mall", "Bijou",
                                "StarksPond", "CityHall")[i],
                            timeMin = 700 + 20 * i,
                            followers = 40 - 10 * i,
                            figs = listOf(name to "happy"))
                    }
                    life.photos += photo13("lifeMine", key,
                        loc = "MainStreet", timeMin = 800)
                    val lifeRecP = photo13("lifeMineP", key,
                        loc = "FotoPharm", timeMin = 820)
                    life.photos += lifeRecP
                    life.prints += DarkroomPrint("lifePr",
                        "lifeMineP", lifeRecP,
                        Darkroom.SIZE_PRINT, 3, key)
                    Gallery.recordFor(life, cal)
                    Gallery.enterAlbum(life, "lifeMine")
                    Gallery.enterPrint(life, "lifePr")
                    staged = true
                }
            }
            if (life.arc13Started && life.arc12Retired)
                startedBehind = true
            days2++
        }
        check(staged && life.arc13Retired && startedBehind &&
            life.arc13Branch in Mystery13.BRANCH_KEYS &&
            Mystery13.dueChapter13(life) == null,
            "exhibition lifetime: the THIRTEEN-case life " +
                "holds — once a show has hung and wrapped " +
                "in the same life, the thirteenth case airs " +
                "behind the twelfth's retirement and retires " +
                "($days2 further days), and the queue is " +
                "empty behind all thirteen")
    }

    // ---------- the attic's thirteenth box ----------
    run {
        val sAttic = eng13.newState()
        check(Attic.caseBoxes(sAttic).none { it.number == 13 },
            "exhibition attic: no thirteenth box before " +
                "the case closes")
        sAttic.arc13Retired = true
        sAttic.arc13RetiredDay = 321
        for (c in items13) sAttic.mystery13Clues.add(c.id)
        val box = Attic.caseBoxes(sAttic)
            .single { it.number == 13 }
        check(box.title == Mystery13.CASE_TITLE &&
            box.piecesHeld == 12 && box.piecesTotal == 12 &&
            box.closedDay == 321 && Attic.CASE_TOTAL == 13,
            "exhibition attic: the thirteenth box stands — " +
                "the case's title, its closing day, and all " +
                "twelve pieces inside")
        val sAll = eng13.newState()
        sAll.arcRetired = true; sAll.arc2Retired = true
        sAll.arc3Retired = true; sAll.arc4Retired = true
        sAll.arc5Retired = true; sAll.arc6Retired = true
        sAll.arc7Retired = true; sAll.arc8Retired = true
        sAll.arc9Retired = true; sAll.arc10Retired = true
        sAll.arc11Retired = true; sAll.arc12Retired = true
        sAll.arc13Retired = true
        check(Attic.caseBoxes(sAll).map { it.number } ==
            (1..13).toList() &&
            Attic.caseBoxes(sAll).size == Attic.CASE_TOTAL,
            "exhibition attic: thirteen closed cases stand " +
                "in order, and the shelf's count is honest")
    }

    // ---------- wiring, version, README, denylist ----------
    run {
        val engSrc = read13("src/com/hunt3r/southparktown/Engine.kt")
        check(engSrc.contains("Mystery13.resolveVerdict") &&
            engSrc.contains("Mystery13.applyVerdictEffects") &&
            engSrc.contains("Mystery13.dueChapter13") &&
            engSrc.contains("Mystery13.noteChapterStarted13") &&
            engSrc.contains("Mystery13.noteParticipation13") &&
            engSrc.contains("Mystery13.noteWallCorrected") &&
            engSrc.contains("Mystery13.ambientCallback13"),
            "exhibition wiring: the engine resolves its " +
                "reading, ripples its effects, schedules its " +
                "chapters, grants its hands-on pieces, " +
                "corrects its wall and remembers its ending")
        check(read13("src/com/hunt3r/southparktown/TalkGate.kt")
            .contains("Mystery13.witnessLine13") &&
            read13("src/com/hunt3r/southparktown/TalkGate.kt")
                .contains("Mystery13.aftermathLine13"),
            "exhibition wiring: the gate carries its " +
                "witnesses and its aftermath on the " +
                "owed-lines seam — no twelfth rail")
        val gaSrc = read13("src/com/hunt3r/southparktown/GameActivity.kt")
        check(gaSrc.contains("maybeShowVerdict()") &&
            gaSrc.contains("maybeShowFrameItem()") &&
            gaSrc.contains("Mystery13.chooseFinale13") &&
            gaSrc.contains("Mystery13.chooseCall13") &&
            gaSrc.contains("Mystery13.lookClueText13"),
            "exhibition wiring: the reading and the frame " +
                "dialog ride the same safe moments as the " +
                "twelve before them, and the Look carries " +
                "its evidence")
        check(read13("src/com/hunt3r/southparktown/JournalActivity.kt")
            .contains("Mystery13.boardLines13"),
            "exhibition wiring: the Journal draws the audit")
        val prefsSrc = read13("src/com/hunt3r/southparktown/Prefs.kt")
        check(prefsSrc.contains("\"arc13\" to mapOf") &&
            prefsSrc.contains("\"mystery13Clues\" to") &&
            prefsSrc.contains("\"arc13Calls\" to") &&
            read13("src/com/hunt3r/southparktown/Shenanigans.kt")
                .contains("Mystery13.CHAPTERS13"),
            "exhibition wiring: the case's state saves " +
                "and its chapters register with the game")
        check(read13("src/com/hunt3r/southparktown/Finales.kt")
            .contains("Mystery13.verdictDue") &&
            read13("src/com/hunt3r/southparktown/MovieNights.kt")
                .contains("Mystery13.verdictDue") &&
            read13("src/com/hunt3r/southparktown/Walk.kt")
                .contains("Mystery13.verdictDue") &&
            read13("src/com/hunt3r/southparktown/School.kt")
                .contains("Mystery13.verdictDue") &&
            read13("src/com/hunt3r/southparktown/Newspaper.kt")
                .contains("arc13RetiredDay") &&
            read13("src/com/hunt3r/southparktown/Attic.kt")
                .contains("Mystery13.CASE_TITLE") &&
            read13("src/com/hunt3r/southparktown/Attic.kt")
                .contains("CASE_TOTAL = 13"),
            "exhibition wiring: the reading is on every " +
                "deference list, the paper can headline the " +
                "thirteenth case's closing day, and the " +
                "attic keeps a box for it")
        val m13Src = read13("src/com/hunt3r/southparktown/Mystery13.kt")
        check(!m13Src.contains("import android") &&
            !m13Src.contains("PenPals") &&
            !m13Src.contains("Wren"),
            "exhibition wiring: the case module stands on " +
                "the town's own records alone — no platform " +
                "imports, no borrowed systems")
        val manifest = read13("AndroidManifest.xml")
        check(manifest.contains("versionCode=\"${Version.VERSION_CODE}\"") &&
            manifest.contains("versionName=\"${Version.VERSION_NAME}\""),
            "release: the manifest itself carries 118 / 0.15.0j")
        val readme = read13("docs/CHANGELOG.md")
        val tuning = File(root, "docs/TUNING.md").readText()
        val arch = File(root, "docs/ARCHITECTURE.md").readText()
        val eStart = readme.indexOf("### v0.15.0j")
        val eEnd = readme.indexOf("### v0.15.0i")
        check(eStart >= 0 && eEnd > eStart,
            "exhibition README: the changelog carries " +
                "this build's entry")
        val entry = if (eStart >= 0 && eEnd > eStart)
            readme.substring(eStart, eEnd) else ""
        check(entry.contains("provenance chain") &&
            entry.contains("SWAPPED PRINT"),
            "exhibition README: the changelog entry " +
                "describes the provenance chain and its " +
                "three readings")
        check(tuning.contains("**Mystery #13 (v0.15.0j") &&
            arch.contains("`Mystery13.kt` (v0.15.0j: mystery #13") &&
            readme.contains("## Status — v0.15.0j"),
            "exhibition README: the tuning ledger, the " +
                "source layout and the status sections all " +
                "carry the thirteenth case, structure only")
        // the authored copy passes the town's denylist
        val authored = StringBuilder()
        for (ch in chapters13) {
            authored.append(ch.title).append('\n')
            authored.append(ch.blurb).append('\n')
            for (st in ch.stages) {
                authored.append(st.title).append('\n')
                authored.append(st.banner).append('\n')
                authored.append(st.journalNote).append('\n')
                authored.append(st.objective).append('\n')
            }
            for (line in ch.coldOpen)
                authored.append(line.text).append('\n')
        }
        for (c in items13) {
            authored.append(c.title).append('\n')
            authored.append(c.detail).append('\n')
            authored.append(c.inertDetail).append('\n')
            c.spoken?.let { authored.append(it).append('\n') }
            c.foundText?.let { authored.append(it).append('\n') }
        }
        val authoredText = authored.toString().lowercase()
        check(Gallery.DENYLIST.none { it in authoredText },
            "exhibition copy: every authored sentence of " +
                "the case — chapters, evidence, tellings — " +
                "passes the town's denylist")
    }
}

